SET check_function_bodies = off;
CREATE OR REPLACE FUNCTION public._assert_complaint_fresh(_id uuid, _expected timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_current timestamptz;
BEGIN
  IF _expected IS NULL THEN RETURN; END IF;
  SELECT updated_at INTO v_current FROM public.complaints WHERE id = _id;
  IF v_current IS NULL THEN RAISE EXCEPTION 'Complaint not found' USING ERRCODE = 'P0002'; END IF;
  -- 1s tolerance for pgbouncer clock drift
  IF v_current > _expected + interval '1 second' THEN
    RAISE EXCEPTION 'complaint_stale: Complaint was modified by another user. Please reload.' USING ERRCODE = '40001';
  END IF;
END; $function$
;
CREATE OR REPLACE FUNCTION public._assert_review_action(_user_id uuid, _entity_type text, _entity_id uuid, _step_id uuid, _role_id uuid, _action text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF _user_id IS NULL THEN RAISE EXCEPTION 'REVIEW_UNAUTHENTICATED'; END IF;
  IF NOT public.can_access_review_entity(_user_id, _entity_type, _entity_id) THEN
    RAISE EXCEPTION 'REVIEW_FORBIDDEN_ENTITY';
  END IF;
  IF _role_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.user_dynamic_roles WHERE user_id=_user_id AND role_id=_role_id) THEN
      RAISE EXCEPTION 'REVIEW_INVALID_ROLE';
    END IF;
    IF public.can_review_action(_step_id, _role_id, _action) THEN RETURN; END IF;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_dynamic_roles udr
     WHERE udr.user_id = _user_id
       AND public.can_review_action(_step_id, udr.role_id, _action)
  ) AND NOT public.is_collab_admin(_user_id) THEN
    RAISE EXCEPTION 'REVIEW_FORBIDDEN_ACTION';
  END IF;
END $function$
;
CREATE OR REPLACE FUNCTION public._fp_sdr_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$
;
CREATE OR REPLACE FUNCTION public._fp_ser_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$
;
CREATE OR REPLACE FUNCTION public._fp_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$
;
CREATE OR REPLACE FUNCTION public._guard_conduct_closure_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status = 'approved'
     AND current_setting('conduct.closure_rpc', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'An approved closure record is immutable' USING ERRCODE='42501';
  END IF;
  IF OLD.status = 'pending_approval'
     AND current_setting('conduct.closure_rpc', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'A closure awaiting approval can only be changed through the approval actions'
      USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public._guard_conduct_intel_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status IN ('published','superseded') THEN
    RAISE EXCEPTION 'A published intelligence report cannot be deleted — publish a superseding version instead'
      USING ERRCODE='22023';
  END IF;
  RETURN OLD;
END $function$
;
CREATE OR REPLACE FUNCTION public._guard_conduct_interview_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.finalised_at IS NOT NULL
     AND current_setting('app.conduct_interview_amend', true) IS DISTINCT FROM OLD.id::text
     AND to_jsonb(NEW) - 'updated_at' IS DISTINCT FROM to_jsonb(OLD) - 'updated_at' THEN
    RAISE EXCEPTION 'Interview record is finalised; amendments require a justification (use conduct_amend_interview)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public._prevent_form_version_delete_if_used()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int;
BEGIN
  -- form_responses
  SELECT count(*) INTO v_count FROM public.form_responses WHERE version_id = OLD.id;
  IF v_count > 0 THEN
    RAISE EXCEPTION 'FORM_VERSION_IN_USE: This version has % form response(s) and cannot be deleted. Retire or archive it instead.', v_count
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  -- normalized assignments
  SELECT count(*) INTO v_count FROM public.application_form_versions WHERE version_id = OLD.id;
  IF v_count > 0 THEN
    RAISE EXCEPTION 'FORM_VERSION_IN_USE: This version is assigned to % application(s) and cannot be deleted. Retire or archive it instead.', v_count
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  -- legacy JSON pins or direct column reference on non-draft apps
  SELECT count(*) INTO v_count
    FROM public.applications a
   WHERE (
     a.form_version_id = OLD.id
     OR EXISTS (
       SELECT 1 FROM jsonb_each_text(COALESCE(a.data->'form_version_ids','{}'::jsonb)) v(k, val)
        WHERE val = OLD.id::text
     )
   )
   AND a.status <> 'draft';
  IF v_count > 0 THEN
    RAISE EXCEPTION 'FORM_VERSION_IN_USE: This version is referenced by % non-draft application(s) and cannot be deleted. Retire or archive it instead.', v_count
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  RETURN OLD;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._prudential_canonical_detect_run(_return_filing_version_id uuid, _trigger_kind text DEFAULT 'manual'::text, _actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v record; v_run_id uuid; v_sector uuid; v_period_end date; v_actor uuid;
  m record; th record; rule record; v_level text;
  v_metrics int := 0; v_thresholds int := 0; v_breaches int := 0; v_warnings int := 0; v_ewi int := 0;
  v_distance numeric; v_prev numeric; v_change numeric; v_breach_periods int;
  v_evaluations jsonb := '[]'::jsonb; v_config jsonb; v_summary jsonb;
BEGIN
  v_actor := COALESCE(_actor, auth.uid());

  SELECT rfv.id AS version_id, rfv.version_number, rfv.status AS version_status,
         rf.id AS filing_id, rf.filing_reference, rf.status AS filing_status,
         rf.entity_id, rf.reporting_period_id, rp.period_end, rp.period_label
    INTO v
    FROM public.return_filing_versions rfv
    JOIN public.return_filings rf ON rf.id = rfv.return_filing_id
    LEFT JOIN public.reporting_periods rp ON rp.id = rf.reporting_period_id
   WHERE rfv.id = _return_filing_version_id;

  IF v.version_id IS NULL THEN
    RAISE EXCEPTION 'A2: canonical filing version % not found', _return_filing_version_id;
  END IF;
  IF COALESCE(v.version_status, '') NOT IN ('ACCEPTED', 'SUBMITTED', 'UNDER_REVIEW') THEN
    RAISE EXCEPTION 'A2: detection requires a submitted or accepted filing version (found %)', v.version_status;
  END IF;

  SELECT sector_id INTO v_sector FROM public.licensees WHERE id = v.entity_id;
  v_period_end := COALESCE(v.period_end, CURRENT_DATE);

  SELECT jsonb_build_object(
           'thresholds', COALESCE((
             SELECT jsonb_agg(jsonb_build_object('metric_key', t.metric_key, 'comparator', t.comparator,
                                                 'warn_value', t.warn_value, 'breach_value', t.breach_value,
                                                 'version', t.current_version))
               FROM public.prudential_thresholds t WHERE t.is_active), '[]'::jsonb),
           'ewi_rules', COALESCE((
             SELECT jsonb_agg(jsonb_build_object('code', r.code, 'rule_type', r.rule_type,
                                                 'params', r.params, 'version', r.version, 'severity', r.severity))
               FROM public.prudential_ewi_rules r
              WHERE r.is_active AND r.rule_type IN ('canonical_threshold_approach','canonical_repeated_breach','canonical_deterioration')), '[]'::jsonb)
         ) INTO v_config;

  INSERT INTO public.prudential_detection_runs
    (entity_id, return_filing_id, return_filing_version_id, reporting_period_id, period_end,
     trigger_kind, triggered_by, status, config_snapshot)
  VALUES (v.entity_id, v.filing_id, v.version_id, v.reporting_period_id, v_period_end,
          COALESCE(_trigger_kind, 'manual'), v_actor, 'RUNNING', v_config)
  RETURNING id INTO v_run_id;

  FOR m IN
    SELECT mv.id AS metric_value_id, mv.regulatory_metric_id, mv.value_numeric, mv.source_kind,
           rm.code AS metric_code, rm.name AS metric_name, rm.unit AS metric_unit
      FROM public.return_metric_values mv
      JOIN public.regulatory_metrics rm ON rm.id = mv.regulatory_metric_id
     WHERE mv.return_filing_version_id = v.version_id
       AND COALESCE(mv.availability, 'AVAILABLE') = 'AVAILABLE'
       AND mv.value_numeric IS NOT NULL
     ORDER BY rm.code
  LOOP
    v_metrics := v_metrics + 1;
    SELECT * INTO th FROM public.prudential_resolve_threshold(m.metric_code, v_sector, v_period_end);

    IF th.threshold_id IS NULL THEN
      v_evaluations := v_evaluations || jsonb_build_object('metric', m.metric_code, 'value', m.value_numeric,
                                                          'outcome', 'no_threshold_configured');
      CONTINUE;
    END IF;

    v_thresholds := v_thresholds + 1;
    v_level := NULL;

    IF th.comparator = '>=' THEN
      IF th.breach_value IS NOT NULL AND m.value_numeric < th.breach_value THEN v_level := 'breach';
      ELSIF th.warn_value IS NOT NULL AND m.value_numeric < th.warn_value THEN v_level := 'warn'; END IF;
    ELSIF th.comparator = '<=' THEN
      IF th.breach_value IS NOT NULL AND m.value_numeric > th.breach_value THEN v_level := 'breach';
      ELSIF th.warn_value IS NOT NULL AND m.value_numeric > th.warn_value THEN v_level := 'warn'; END IF;
    END IF;

    v_evaluations := v_evaluations || jsonb_build_object(
      'metric', m.metric_code, 'value', m.value_numeric, 'comparator', th.comparator,
      'warn_value', th.warn_value, 'breach_value', th.breach_value,
      'threshold_version', th.threshold_version, 'outcome', COALESCE(v_level, 'within_tolerance'));

    IF v_level IS NOT NULL THEN
      INSERT INTO public.return_threshold_breaches
        (return_id, metric_key, level, value, threshold_value, comparator, detected_at, notified,
         risk_level, threshold_version, entity_id, return_filing_id, return_filing_version_id,
         reporting_period_id, regulatory_metric_id, detection_source, detection_run_id, evidence)
      VALUES (NULL, m.metric_code, v_level, m.value_numeric, th.breach_value, th.comparator, now(), false,
              CASE WHEN v_level = 'breach' THEN 'red' ELSE 'amber' END,
              th.threshold_version, v.entity_id, v.filing_id, v.version_id,
              v.reporting_period_id, m.regulatory_metric_id, 'CANONICAL_ENGINE', v_run_id,
              jsonb_build_object('engine_version', 'a2.canonical.v1', 'metric_code', m.metric_code,
                                 'metric_name', m.metric_name, 'metric_value_id', m.metric_value_id,
                                 'value', m.value_numeric, 'unit', COALESCE(th.unit, m.metric_unit),
                                 'comparator', th.comparator, 'warn_value', th.warn_value,
                                 'breach_value', th.breach_value, 'threshold_id', th.threshold_id,
                                 'threshold_label', th.label, 'threshold_version', th.threshold_version,
                                 'filing_reference', v.filing_reference, 'period_label', v.period_label,
                                 'period_end', v_period_end, 'source_kind', m.source_kind))
      ON CONFLICT DO NOTHING;

      IF v_level = 'breach' THEN v_breaches := v_breaches + 1; ELSE v_warnings := v_warnings + 1; END IF;
    END IF;

    FOR rule IN
      SELECT * FROM public.prudential_ewi_rules
       WHERE is_active
         AND rule_type IN ('canonical_threshold_approach', 'canonical_repeated_breach', 'canonical_deterioration')
         AND (sector_id IS NULL OR sector_id = v_sector)
    LOOP
      IF rule.rule_type = 'canonical_threshold_approach' THEN
        CONTINUE WHEN v_level = 'breach' OR th.breach_value IS NULL OR th.breach_value = 0;
        v_distance := ABS(m.value_numeric - th.breach_value) / ABS(th.breach_value) * 100;
        IF v_distance <= COALESCE((rule.params->>'buffer_pct')::numeric, 20) THEN
          INSERT INTO public.prudential_ewi_alerts
            (entity_id, rule_id, rule_code, rule_version, period_end, metric_key, severity, evidence, executed_at,
             detection_source, detection_run_id, return_filing_id, return_filing_version_id,
             reporting_period_id, regulatory_metric_id)
          VALUES (v.entity_id, rule.id, rule.code, rule.version, v_period_end, m.metric_code, rule.severity,
                  jsonb_build_object('rule_type', rule.rule_type, 'params', rule.params,
                                     'value', m.value_numeric, 'breach_value', th.breach_value,
                                     'comparator', th.comparator,
                                     'distance_to_breach_pct', ROUND(v_distance * 100) / 100,
                                     'threshold_version', th.threshold_version,
                                     'filing_reference', v.filing_reference, 'period_label', v.period_label,
                                     'engine_version', 'a2.canonical.v1'), now(),
                  'CANONICAL_ENGINE', v_run_id, v.filing_id, v.version_id,
                  v.reporting_period_id, m.regulatory_metric_id)
          ON CONFLICT (entity_id, rule_id, period_end, metric_key)
          DO UPDATE SET evidence = EXCLUDED.evidence, executed_at = now(),
                        detection_run_id = EXCLUDED.detection_run_id,
                        return_filing_version_id = EXCLUDED.return_filing_version_id,
                        updated_at = now();
          v_ewi := v_ewi + 1;
        END IF;

      ELSIF rule.rule_type = 'canonical_deterioration' THEN
        SELECT mv.value_numeric INTO v_prev
          FROM public.return_metric_values mv
          JOIN public.reporting_periods rp2 ON rp2.id = mv.reporting_period_id
          JOIN public.return_filing_versions v2 ON v2.id = mv.return_filing_version_id
          JOIN public.return_filings f2 ON f2.id = v2.return_filing_id
         WHERE mv.entity_id = v.entity_id
           AND mv.regulatory_metric_id = m.regulatory_metric_id
           AND mv.value_numeric IS NOT NULL
           AND rp2.period_end < v_period_end
           AND f2.status = 'ACCEPTED'
         ORDER BY rp2.period_end DESC, mv.recorded_at DESC
         LIMIT 1;

        IF v_prev IS NOT NULL AND v_prev <> 0 THEN
          v_change := CASE WHEN th.comparator = '>=' THEN (v_prev - m.value_numeric) / ABS(v_prev) * 100
                                                     ELSE (m.value_numeric - v_prev) / ABS(v_prev) * 100 END;
          IF v_change >= COALESCE((rule.params->>'min_change_pct')::numeric, 15) THEN
            INSERT INTO public.prudential_ewi_alerts
              (entity_id, rule_id, rule_code, rule_version, period_end, metric_key, severity, evidence, executed_at,
               detection_source, detection_run_id, return_filing_id, return_filing_version_id,
               reporting_period_id, regulatory_metric_id)
            VALUES (v.entity_id, rule.id, rule.code, rule.version, v_period_end, m.metric_code, rule.severity,
                    jsonb_build_object('rule_type', rule.rule_type, 'params', rule.params,
                                       'current', m.value_numeric, 'previous', v_prev,
                                       'adverse_change_pct', ROUND(v_change * 100) / 100,
                                       'comparator', th.comparator,
                                       'filing_reference', v.filing_reference,
                                       'engine_version', 'a2.canonical.v1'), now(),
                    'CANONICAL_ENGINE', v_run_id, v.filing_id, v.version_id,
                    v.reporting_period_id, m.regulatory_metric_id)
            ON CONFLICT (entity_id, rule_id, period_end, metric_key)
            DO UPDATE SET evidence = EXCLUDED.evidence, executed_at = now(),
                          detection_run_id = EXCLUDED.detection_run_id,
                          return_filing_version_id = EXCLUDED.return_filing_version_id,
                          updated_at = now();
            v_ewi := v_ewi + 1;
          END IF;
        END IF;

      ELSIF rule.rule_type = 'canonical_repeated_breach' THEN
        SELECT COUNT(DISTINCT b.reporting_period_id) INTO v_breach_periods
          FROM public.return_threshold_breaches b
          JOIN public.reporting_periods rp3 ON rp3.id = b.reporting_period_id
          JOIN public.return_filings f3 ON f3.id = b.return_filing_id
         WHERE b.entity_id = v.entity_id
           AND b.regulatory_metric_id = m.regulatory_metric_id
           AND b.level = 'breach'
           AND b.detection_source = 'CANONICAL_ENGINE'
           AND COALESCE(f3.status, '') <> 'WITHDRAWN'
           AND rp3.period_end <= v_period_end
           AND b.detection_run_id = (
             SELECT r.id FROM public.prudential_detection_runs r
              WHERE r.return_filing_version_id = b.return_filing_version_id
              ORDER BY r.started_at DESC NULLS LAST LIMIT 1);

        IF v_breach_periods >= COALESCE((rule.params->>'min_breaches')::int, 2) THEN
          INSERT INTO public.prudential_ewi_alerts
            (entity_id, rule_id, rule_code, rule_version, period_end, metric_key, severity, evidence, executed_at,
             detection_source, detection_run_id, return_filing_id, return_filing_version_id,
             reporting_period_id, regulatory_metric_id)
          VALUES (v.entity_id, rule.id, rule.code, rule.version, v_period_end, m.metric_code, rule.severity,
                  jsonb_build_object('rule_type', rule.rule_type, 'params', rule.params,
                                     'breach_periods', v_breach_periods,
                                     'filing_reference', v.filing_reference,
                                     'engine_version', 'a2.canonical.v1'), now(),
                  'CANONICAL_ENGINE', v_run_id, v.filing_id, v.version_id,
                  v.reporting_period_id, m.regulatory_metric_id)
          ON CONFLICT (entity_id, rule_id, period_end, metric_key)
          DO UPDATE SET evidence = EXCLUDED.evidence, executed_at = now(),
                        detection_run_id = EXCLUDED.detection_run_id,
                        updated_at = now();
          v_ewi := v_ewi + 1;
        END IF;
      END IF;
    END LOOP;
  END LOOP;

  UPDATE public.prudential_detection_runs
     SET status = 'COMPLETED', metrics_evaluated = v_metrics, thresholds_resolved = v_thresholds,
         breaches_created = v_breaches, warnings_created = v_warnings, ewi_created = v_ewi,
         result = jsonb_build_object('evaluations', v_evaluations), completed_at = now()
   WHERE id = v_run_id;

  v_summary := jsonb_build_object('entity_id', v.entity_id, 'filing_reference', v.filing_reference,
                                  'period_end', v_period_end, 'metrics_evaluated', v_metrics,
                                  'breaches', v_breaches, 'warnings', v_warnings, 'ewi', v_ewi,
                                  'trigger_kind', COALESCE(_trigger_kind, 'manual'),
                                  'engine_version', 'a2.canonical.v1');

  IF v_actor IS NOT NULL THEN
    PERFORM public.log_compliance_audit_as_actor(
      v_actor, 'INTEGRATION_EVENT'::public.compliance_audit_action,
      'prudential_detection_run', v_run_id::text, NULL, v_summary,
      'A2 canonical prudential detection run', NULL, NULL, NULL,
      jsonb_build_object('trigger_kind', COALESCE(_trigger_kind, 'manual')));
  ELSE
    INSERT INTO public.compliance_audit_logs
      (user_id, user_role, action_type, object_type, object_id, after_value, justification, metadata)
    VALUES (NULL, 'SYSTEM', 'INTEGRATION_EVENT'::public.compliance_audit_action,
            'prudential_detection_run', v_run_id::text, v_summary,
            'A2 canonical prudential detection run (system trigger)',
            jsonb_build_object('trigger_kind', COALESCE(_trigger_kind, 'manual'),
                               'engine_version', 'a2.canonical.v1'));
  END IF;

  RETURN jsonb_build_object('success', true, 'run_id', v_run_id, 'entity_id', v.entity_id,
    'filing_reference', v.filing_reference, 'period_end', v_period_end,
    'metrics_evaluated', v_metrics, 'thresholds_resolved', v_thresholds,
    'breaches_created', v_breaches, 'warnings_created', v_warnings,
    'ewi_created', v_ewi, 'evaluations', v_evaluations);
END $function$
;
CREATE OR REPLACE FUNCTION public._resolve_application_workflow(_license_type text, _regulator_id uuid, _sector_id uuid, _category_id uuid)
 RETURNS TABLE(workflow_id uuid, first_step_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_wf_id uuid;
  v_step_id uuid;
  v_eff_reg uuid;
  v_lt text := lower(coalesce(_license_type, ''));
BEGIN
  v_eff_reg := public._resolve_effective_regulator(_regulator_id, _sector_id, _category_id);

  -- Helper expression for prefix-tolerant license_type match (current row alias `aw`)
  -- Used in subsequent SELECTs.

  -- 1. effective regulator + category (prefix-tolerant license_type)
  IF v_eff_reg IS NOT NULL AND _category_id IS NOT NULL THEN
    SELECT id INTO v_wf_id FROM public.approval_workflows aw
     WHERE aw.entity_type='application' AND aw.is_active=true
       AND aw.regulator_id=v_eff_reg AND aw.category_id=_category_id
       AND aw.license_type <> ''
       AND (v_lt = lower(aw.license_type)
            OR v_lt LIKE lower(aw.license_type) || ' %'
            OR v_lt LIKE lower(aw.license_type) || '\_%' ESCAPE '\'
            OR v_lt LIKE lower(aw.license_type) || '-%')
     ORDER BY length(aw.license_type) DESC
     LIMIT 1;
  END IF;

  -- 2. effective regulator + sector
  IF v_wf_id IS NULL AND v_eff_reg IS NOT NULL AND _sector_id IS NOT NULL THEN
    SELECT id INTO v_wf_id FROM public.approval_workflows aw
     WHERE aw.entity_type='application' AND aw.is_active=true
       AND aw.regulator_id=v_eff_reg AND aw.sector_id=_sector_id
       AND aw.license_type <> ''
       AND (v_lt = lower(aw.license_type)
            OR v_lt LIKE lower(aw.license_type) || ' %'
            OR v_lt LIKE lower(aw.license_type) || '\_%' ESCAPE '\'
            OR v_lt LIKE lower(aw.license_type) || '-%')
     ORDER BY length(aw.license_type) DESC
     LIMIT 1;
  END IF;

  -- 3. effective regulator only
  IF v_wf_id IS NULL AND v_eff_reg IS NOT NULL THEN
    SELECT id INTO v_wf_id FROM public.approval_workflows aw
     WHERE aw.entity_type='application' AND aw.is_active=true
       AND aw.regulator_id=v_eff_reg
       AND aw.license_type <> ''
       AND (v_lt = lower(aw.license_type)
            OR v_lt LIKE lower(aw.license_type) || ' %'
            OR v_lt LIKE lower(aw.license_type) || '\_%' ESCAPE '\'
            OR v_lt LIKE lower(aw.license_type) || '-%')
     ORDER BY (aw.category_id IS NULL), (aw.sector_id IS NULL), length(aw.license_type) DESC
     LIMIT 1;
  END IF;

  -- 4. fallback: original regulator
  IF v_wf_id IS NULL AND _regulator_id IS NOT NULL AND _regulator_id IS DISTINCT FROM v_eff_reg THEN
    SELECT id INTO v_wf_id FROM public.approval_workflows aw
     WHERE aw.entity_type='application' AND aw.is_active=true
       AND aw.regulator_id=_regulator_id
       AND aw.license_type <> ''
       AND (v_lt = lower(aw.license_type)
            OR v_lt LIKE lower(aw.license_type) || ' %'
            OR v_lt LIKE lower(aw.license_type) || '\_%' ESCAPE '\'
            OR v_lt LIKE lower(aw.license_type) || '-%')
     ORDER BY length(aw.license_type) DESC
     LIMIT 1;
  END IF;

  -- 5. license_type exact only (no regulator)
  IF v_wf_id IS NULL THEN
    SELECT id INTO v_wf_id FROM public.approval_workflows
     WHERE license_type=_license_type AND entity_type='application' AND is_active=true
     LIMIT 1;
  END IF;

  -- 6. prefix-tolerant license_type only
  IF v_wf_id IS NULL THEN
    SELECT id INTO v_wf_id FROM public.approval_workflows aw
     WHERE aw.entity_type='application' AND aw.is_active=true AND aw.license_type<>''
       AND (v_lt = lower(aw.license_type)
            OR v_lt LIKE lower(aw.license_type) || ' %'
            OR v_lt LIKE lower(aw.license_type) || '\_%' ESCAPE '\'
            OR v_lt LIKE lower(aw.license_type) || '-%')
     ORDER BY length(aw.license_type) DESC
     LIMIT 1;
  END IF;

  IF v_wf_id IS NULL THEN RETURN; END IF;

  SELECT s.id INTO v_step_id FROM public.approval_steps s
   WHERE s.workflow_id=v_wf_id ORDER BY s.step_order ASC LIMIT 1;

  workflow_id := v_wf_id;
  first_step_id := v_step_id;
  RETURN NEXT;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._resolve_application_workflow(_license_type text, _regulator_id uuid, _sector_id uuid, _category_id uuid, _is_post_license boolean DEFAULT false)
 RETURNS TABLE(workflow_id uuid, first_step_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_wf_id uuid;
  v_step_id uuid;
  v_eff_reg uuid;
  v_lt text := lower(coalesce(_license_type, ''));
  v_entity_types text[];
  v_is_post boolean := COALESCE(_is_post_license, false);
  v_sub_sector_id uuid;
BEGIN
  v_eff_reg := public._resolve_effective_regulator(_regulator_id, _sector_id, _category_id);

  -- Pre-license applications never resolve to a 'registration' workflow.
  v_entity_types := CASE WHEN v_is_post
                         THEN ARRAY['post_application','application']
                         ELSE ARRAY['pre_application','application'] END;

  -- Derive sub_sector from category when not passed in.
  IF _category_id IS NOT NULL THEN
    SELECT sub_sector_id INTO v_sub_sector_id FROM public.categories WHERE id=_category_id;
  END IF;

  -- TAXONOMY-FIRST MATCH (license_type ignored): most specific wins.
  -- service > category > sub_sector > sector > regulator-only.

  IF v_eff_reg IS NOT NULL AND _category_id IS NOT NULL THEN
    SELECT id INTO v_wf_id FROM public.approval_workflows aw
     WHERE aw.entity_type = ANY(v_entity_types) AND aw.is_active=true
       AND aw.regulator_id=v_eff_reg AND aw.category_id=_category_id
     ORDER BY array_position(v_entity_types, aw.entity_type), aw.updated_at DESC
     LIMIT 1;
  END IF;

  IF v_wf_id IS NULL AND v_eff_reg IS NOT NULL AND v_sub_sector_id IS NOT NULL THEN
    SELECT id INTO v_wf_id FROM public.approval_workflows aw
     WHERE aw.entity_type = ANY(v_entity_types) AND aw.is_active=true
       AND aw.regulator_id=v_eff_reg AND aw.sub_sector_id=v_sub_sector_id
       AND aw.category_id IS NULL
     ORDER BY array_position(v_entity_types, aw.entity_type), aw.updated_at DESC
     LIMIT 1;
  END IF;

  IF v_wf_id IS NULL AND v_eff_reg IS NOT NULL AND _sector_id IS NOT NULL THEN
    SELECT id INTO v_wf_id FROM public.approval_workflows aw
     WHERE aw.entity_type = ANY(v_entity_types) AND aw.is_active=true
       AND aw.regulator_id=v_eff_reg AND aw.sector_id=_sector_id
       AND aw.sub_sector_id IS NULL AND aw.category_id IS NULL
     ORDER BY array_position(v_entity_types, aw.entity_type), aw.updated_at DESC
     LIMIT 1;
  END IF;

  IF v_wf_id IS NULL AND v_eff_reg IS NOT NULL THEN
    SELECT id INTO v_wf_id FROM public.approval_workflows aw
     WHERE aw.entity_type = ANY(v_entity_types) AND aw.is_active=true
       AND aw.regulator_id=v_eff_reg
       AND aw.sector_id IS NULL AND aw.sub_sector_id IS NULL AND aw.category_id IS NULL
     ORDER BY array_position(v_entity_types, aw.entity_type), aw.updated_at DESC
     LIMIT 1;
  END IF;

  -- LEGACY license_type prefix match (back-compat for older configs).
  IF v_wf_id IS NULL AND v_eff_reg IS NOT NULL THEN
    SELECT id INTO v_wf_id FROM public.approval_workflows aw
     WHERE aw.entity_type = ANY(v_entity_types) AND aw.is_active=true
       AND aw.regulator_id=v_eff_reg
       AND aw.license_type <> '' AND lower(aw.license_type) <> 'general'
       AND (v_lt = lower(aw.license_type)
            OR v_lt LIKE lower(aw.license_type) || ' %'
            OR v_lt LIKE lower(aw.license_type) || '\_%' ESCAPE '\'
            OR v_lt LIKE lower(aw.license_type) || '-%')
     ORDER BY array_position(v_entity_types, aw.entity_type),
              (aw.category_id IS NULL), (aw.sub_sector_id IS NULL), (aw.sector_id IS NULL),
              length(aw.license_type) DESC
     LIMIT 1;
  END IF;

  IF v_wf_id IS NULL THEN RETURN; END IF;

  SELECT s.id INTO v_step_id FROM public.approval_steps s
   WHERE s.workflow_id=v_wf_id ORDER BY s.step_order ASC LIMIT 1;

  workflow_id := v_wf_id;
  first_step_id := v_step_id;
  RETURN NEXT;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._resolve_effective_regulator(_regulator_id uuid, _sector_id uuid, _category_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sector_reg uuid;
  v_cat_sector uuid;
BEGIN
  -- Prefer category -> sector -> regulator
  IF _category_id IS NOT NULL THEN
    SELECT c.sector_id INTO v_cat_sector FROM public.categories c WHERE c.id = _category_id;
    IF v_cat_sector IS NOT NULL THEN
      SELECT s.regulator_id INTO v_sector_reg FROM public.sectors s WHERE s.id = v_cat_sector;
      IF v_sector_reg IS NOT NULL THEN RETURN v_sector_reg; END IF;
    END IF;
  END IF;

  IF _sector_id IS NOT NULL THEN
    SELECT s.regulator_id INTO v_sector_reg FROM public.sectors s WHERE s.id = _sector_id;
    IF v_sector_reg IS NOT NULL THEN RETURN v_sector_reg; END IF;
  END IF;

  RETURN _regulator_id;
END;
$function$
;
