CREATE OR REPLACE FUNCTION public.a2_detection_reset_nonproduction()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_enabled boolean;
  v_b int; v_a int; v_r int;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only a super administrator may reset detection outcomes';
  END IF;

  SELECT reset_enabled INTO v_enabled FROM public.cert_nonproduction_guard LIMIT 1;
  IF NOT COALESCE(v_enabled, false) THEN
    RAISE EXCEPTION 'Non-production reset is disabled for this environment';
  END IF;

  DELETE FROM public.return_threshold_breaches WHERE detection_source = 'CANONICAL_ENGINE';
  GET DIAGNOSTICS v_b = ROW_COUNT;
  DELETE FROM public.prudential_ewi_alerts WHERE detection_source = 'CANONICAL_ENGINE';
  GET DIAGNOSTICS v_a = ROW_COUNT;
  DELETE FROM public.prudential_detection_runs;
  GET DIAGNOSTICS v_r = ROW_COUNT;

  RETURN jsonb_build_object('breaches_deleted', v_b, 'alerts_deleted', v_a, 'runs_deleted', v_r);
END $function$
;
CREATE OR REPLACE FUNCTION public.accept_review_suggestion(_suggestion_id uuid)
 RETURNS review_suggestions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s public.review_suggestions%ROWTYPE;
  reg record;
  _tbl text; _col text; _current text; _new text; _slice text;
BEGIN
  SELECT * INTO s FROM public.review_suggestions WHERE id = _suggestion_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REVIEW_NOT_FOUND'; END IF;
  IF s.status <> 'pending' THEN RAISE EXCEPTION 'REVIEW_ALREADY_DECIDED'; END IF;
  PERFORM public._assert_review_action(auth.uid(), s.entity_type, s.entity_id, s.workflow_step_id, NULL, 'accept');

  SELECT table_name, column_name INTO _tbl, _col
    FROM public.review_narrative_fields
   WHERE entity_type = s.entity_type AND field_key = s.field_key;
  IF _tbl IS NULL THEN RAISE EXCEPTION 'REVIEW_UNKNOWN_FIELD'; END IF;

  EXECUTE format('SELECT %I FROM public.%I WHERE id = $1 FOR UPDATE', _col, _tbl)
    USING s.entity_id INTO _current;
  _current := COALESCE(_current, '');

  IF s.type = 'insert' THEN
    IF s.selection_start IS NULL OR s.selection_start < 0 OR s.selection_start > length(_current) THEN
      RAISE EXCEPTION 'REVIEW_SUGGESTION_STALE';
    END IF;
    _new := substr(_current, 1, s.selection_start) || COALESCE(s.suggested_text, '') || substr(_current, s.selection_start + 1);
  ELSE
    IF s.selection_start IS NULL OR s.selection_end IS NULL
       OR s.selection_start < 0 OR s.selection_end > length(_current)
       OR s.selection_end < s.selection_start THEN
      RAISE EXCEPTION 'REVIEW_SUGGESTION_STALE';
    END IF;
    _slice := substr(_current, s.selection_start + 1, s.selection_end - s.selection_start);
    IF s.original_text IS NOT NULL AND _slice <> s.original_text THEN
      RAISE EXCEPTION 'REVIEW_SUGGESTION_STALE';
    END IF;
    IF s.type = 'delete' THEN
      _new := substr(_current, 1, s.selection_start) || substr(_current, s.selection_end + 1);
    ELSE -- replace
      _new := substr(_current, 1, s.selection_start) || COALESCE(s.suggested_text, '') || substr(_current, s.selection_end + 1);
    END IF;
  END IF;

  EXECUTE format('UPDATE public.%I SET %I = $1 WHERE id = $2', _tbl, _col) USING _new, s.entity_id;

  UPDATE public.review_suggestions
     SET status = 'accepted', decided_by = auth.uid(), decided_at = now()
   WHERE id = _suggestion_id RETURNING * INTO s;
  RETURN s;
END $function$
;
CREATE OR REPLACE FUNCTION public.activate_captcha_configuration(_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _prev uuid;
BEGIN
  IF NOT (has_role(auth.uid(),'super_admin'::app_role) OR has_role(auth.uid(),'admin'::app_role)) THEN
    RAISE EXCEPTION 'Not authorised to manage CAPTCHA configurations';
  END IF;

  SELECT id INTO _prev FROM public.captcha_configurations WHERE is_active AND id <> _id FOR UPDATE;

  UPDATE public.captcha_configurations
     SET is_active = false, updated_by = auth.uid(), updated_at = now()
   WHERE is_active AND id <> _id;

  UPDATE public.captcha_configurations
     SET is_active = true, updated_by = auth.uid(), updated_at = now()
   WHERE id = _id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CAPTCHA configuration not found';
  END IF;

  RETURN jsonb_build_object('activated_id', _id, 'deactivated_id', _prev);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.activate_form_version_as_current(_version_id uuid, _activation_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_v record;
  v_now timestamptz := now();
  v_activation timestamptz;
  v_month_end timestamptz;
  v_retired_count int;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF NOT (public.has_role(v_uid,'super_admin'::app_role) OR public.has_role(v_uid,'admin'::app_role)) THEN
    RETURN jsonb_build_object('error','Admin only','code','FORBIDDEN','http',403);
  END IF;

  SELECT id, template_id, version, semantic_version, status
    INTO v_v
    FROM public.form_versions
   WHERE id = _version_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Version not found','code','NOT_FOUND','http',404);
  END IF;
  IF v_v.status <> 'published' THEN
    RETURN jsonb_build_object('error','Only published versions can be activated','code','INVALID_STATUS','http',409);
  END IF;

  v_activation := COALESCE(_activation_date::timestamptz, date_trunc('day', v_now));
  -- Last day of current month at 23:59:59.999999
  v_month_end := date_trunc('month', v_now) + interval '1 month' - interval '1 microsecond';

  -- Promote chosen version
  UPDATE public.form_versions
     SET effective_from = v_activation,
         effective_until = NULL
   WHERE id = _version_id;

  -- Retire other open-ended or future-ending published versions of same template
  UPDATE public.form_versions
     SET effective_until = v_month_end
   WHERE template_id = v_v.template_id
     AND id <> _version_id
     AND status = 'published'
     AND (effective_until IS NULL OR effective_until > v_month_end);
  GET DIAGNOSTICS v_retired_count = ROW_COUNT;

  PERFORM public.create_audit_log(
    v_uid,
    'form_version_activated_as_current',
    'form_version',
    _version_id::text,
    NULL,
    jsonb_build_object(
      'template_id', v_v.template_id,
      'activation_date', v_activation,
      'retired_other_until', v_month_end,
      'retired_count', v_retired_count
    ),
    NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'http', 200,
    'version_id', _version_id,
    'template_id', v_v.template_id,
    'activation_date', v_activation,
    'retired_other_until', v_month_end,
    'retired_count', v_retired_count
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.add_correspondence_attachment(_thread_id uuid, _file_name text, _storage_path text, _size_kb integer, _content_type text DEFAULT NULL::text, _message_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_actor text; v_version integer; v_id uuid;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT public.correspondence_thread_visible(_thread_id, v_user) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  v_actor := public.correspondence_actor_label(v_user);
  SELECT COALESCE(MAX(version), 0) + 1 INTO v_version
  FROM public.correspondence_attachments WHERE thread_id = _thread_id AND file_name = _file_name;

  INSERT INTO public.correspondence_attachments (thread_id, message_id, file_name, storage_path, size_kb, content_type, version, uploaded_by, uploaded_by_name)
  VALUES (_thread_id, _message_id, _file_name, _storage_path, COALESCE(_size_kb,0), _content_type, v_version, v_user, v_actor)
  RETURNING id INTO v_id;

  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail)
  VALUES (_thread_id, v_user, v_actor, CASE WHEN public.is_internal_staff(v_user) THEN 'Staff' ELSE 'Licensee' END,
          'Attachment uploaded', _file_name || ' (v' || v_version || ')');
  RETURN v_id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.add_review_comment(_entity_type text, _entity_id uuid, _field_key text, _body text, _selection jsonb DEFAULT NULL::jsonb, _is_blocking boolean DEFAULT false, _role_id uuid DEFAULT NULL::uuid, _parent_comment_id uuid DEFAULT NULL::uuid)
 RETURNS review_comments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE ctx record; row public.review_comments%ROWTYPE; _act text;
BEGIN
  SELECT * INTO ctx FROM public.current_workflow_step_for(_entity_type, _entity_id);
  _act := CASE WHEN _parent_comment_id IS NOT NULL THEN 'reply'
               WHEN _is_blocking THEN 'mark_blocking' ELSE 'comment' END;
  PERFORM public._assert_review_action(auth.uid(), _entity_type, _entity_id, ctx.step_id, _role_id, _act);

  INSERT INTO public.review_comments (
    entity_type, entity_id, workflow_instance_id, workflow_step_id,
    field_key, body,
    selection_start, selection_end, selection_text,
    author_user_id, author_role_id, is_blocking, parent_comment_id
  ) VALUES (
    _entity_type, _entity_id, ctx.instance_id, ctx.step_id,
    _field_key, _body,
    NULLIF((_selection->>'start')::int, NULL),
    NULLIF((_selection->>'end')::int, NULL),
    _selection->>'text',
    auth.uid(), _role_id, COALESCE(_is_blocking,false), _parent_comment_id
  ) RETURNING * INTO row;
  RETURN row;
END $function$
;
CREATE OR REPLACE FUNCTION public.admin_override_form_version_assignment(_application_id uuid, _template_id uuid, _version_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_old record;
  v_new record;
  v_now timestamptz := now();
  v_existing_map jsonb;
  v_new_map jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF NOT (public.has_role(v_uid,'super_admin'::app_role) OR public.has_role(v_uid,'admin'::app_role)) THEN
    RETURN jsonb_build_object('error','Admin only','code','FORBIDDEN','http',403);
  END IF;
  IF _reason IS NULL OR length(trim(_reason)) = 0 THEN
    RETURN jsonb_build_object('error','Reason is required for an admin override','code','REASON_REQUIRED','http',422);
  END IF;
  IF _application_id IS NULL OR _template_id IS NULL OR _version_id IS NULL THEN
    RETURN jsonb_build_object('error','application_id, template_id and version_id are required','code','BAD_REQUEST','http',400);
  END IF;

  SELECT id, applicant_id, data INTO v_app
    FROM public.applications WHERE id = _application_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  SELECT id, version, semantic_version, status, template_id INTO v_new
    FROM public.form_versions
   WHERE id = _version_id AND template_id = _template_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Target version not found for this template','code','VERSION_NOT_FOUND','http',404);
  END IF;

  -- Mark current active assignment as superseded
  SELECT id, version_id INTO v_old
    FROM public.application_form_versions
   WHERE application_id = _application_id AND template_id = _template_id AND status = 'active'
   LIMIT 1;
  IF FOUND THEN
    UPDATE public.application_form_versions
       SET status = 'superseded', updated_at = v_now
     WHERE id = v_old.id;
  END IF;

  INSERT INTO public.application_form_versions
    (application_id, template_id, version_id, assigned_reason, assigned_by, locked_at, status)
  VALUES
    (_application_id, _template_id, _version_id, 'admin_override', v_uid, v_now, 'active');

  -- Mirror to legacy JSON
  v_existing_map := COALESCE(v_app.data->'form_version_ids', '{}'::jsonb);
  v_new_map := v_existing_map || jsonb_build_object(_template_id::text, _version_id::text);
  UPDATE public.applications
     SET data = COALESCE(data, '{}'::jsonb) || jsonb_build_object('form_version_ids', v_new_map),
         updated_at = v_now
   WHERE id = _application_id;

  PERFORM public.create_audit_log(
    v_uid, 'application_form_version_overridden', 'application',
    _application_id::text, NULL,
    jsonb_build_object(
      'template_id', _template_id,
      'old_version_id', v_old.version_id,
      'new_version_id', _version_id,
      'new_version_number', v_new.version,
      'reason', trim(_reason)
    ), NULL
  );

  PERFORM public.create_notification(
    v_app.applicant_id,
    'Form version updated by admin',
    'An administrator has updated the form version assigned to one of your applications.',
    'info', 'application', _application_id::text
  );

  RETURN jsonb_build_object(
    'success', true, 'http', 200,
    'application_id', _application_id,
    'template_id', _template_id,
    'old_version_id', v_old.version_id,
    'new_version_id', _version_id
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.ai_insight_review(_insight_id uuid, _action text, _justification text DEFAULT NULL::text, _follow_up_type text DEFAULT NULL::text, _follow_up_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.ai_insights;
BEGIN
  IF NOT (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(),'report_management','create')) THEN
    RAISE EXCEPTION 'not authorised to review AI insights' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_row FROM public.ai_insights WHERE id = _insight_id;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'insight not found' USING ERRCODE = 'P0002';
  END IF;
  IF _action NOT IN ('reviewed','accepted','dismissed','escalated','follow_up_created','overridden') THEN
    RAISE EXCEPTION 'invalid action %', _action USING ERRCODE = '22023';
  END IF;
  IF _action IN ('overridden','dismissed') AND COALESCE(length(btrim(_justification)),0) < 10 THEN
    RAISE EXCEPTION 'justification of at least 10 characters is required' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.ai_insight_actions(insight_id, action, justification, follow_up_type, follow_up_id)
  VALUES (_insight_id, _action, _justification, _follow_up_type, _follow_up_id);

  IF _action = 'overridden' THEN
    PERFORM public.log_rule_override('ai_insights','ai_insight', _insight_id::text, 'ai_insight_review',
      to_jsonb(v_row.review_status), to_jsonb('overridden'::text), _justification,
      jsonb_build_object('provider_state', v_row.provider_state, 'module', v_row.module));
  END IF;

  IF _action IN ('accepted','dismissed','escalated','overridden') THEN
    UPDATE public.ai_insights
       SET review_status = CASE _action WHEN 'accepted' THEN 'accepted'
                                        WHEN 'dismissed' THEN 'dismissed'
                                        WHEN 'escalated' THEN 'escalated'
                                        ELSE 'overridden' END,
           reviewer_id = auth.uid(), reviewed_at = now()
     WHERE id = _insight_id;
  END IF;

  SELECT * INTO v_row FROM public.ai_insights WHERE id = _insight_id;
  RETURN jsonb_build_object('id', v_row.id, 'review_status', v_row.review_status);
END $function$
;
CREATE OR REPLACE FUNCTION public.app_actor_display_name(_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(
    (SELECT nullif(btrim(coalesce(p.full_name, p.email, '')), '') FROM profiles p WHERE p.id = _user_id),
    (SELECT nullif(btrim(coalesce(u.full_name, u.email, '')), '') FROM pre_license_users u WHERE u.id = _user_id)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.app_applicant_org_name(_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT nullif(btrim(coalesce(u.entity_name, '')), '') FROM pre_license_users u WHERE u.id = _user_id;
$function$
;
CREATE OR REPLACE FUNCTION public.app_require_rationale(_text text, _min integer, _label text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  IF _text IS NULL OR length(trim(_text)) < _min THEN
    RAISE EXCEPTION '% must be at least % characters', _label, _min USING ERRCODE = '22023';
  END IF;
END; $function$
;
CREATE OR REPLACE FUNCTION public.appeal_case_file_status(_appeal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_appeal record;
  v_app record;
  v_docs int := 0;
  v_items jsonb;
  v_blocking int;
BEGIN
  IF NOT public.can_read_license_appeal(auth.uid(), _appeal_id) THEN
    RETURN jsonb_build_object('error','Not allowed','code','FORBIDDEN','http',403);
  END IF;

  SELECT * INTO v_appeal FROM public.license_appeals WHERE id = _appeal_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Appeal not found','code','NOT_FOUND','http',404);
  END IF;

  SELECT * INTO v_app FROM public.applications WHERE id = v_appeal.application_id;

  SELECT count(*) INTO v_docs
    FROM public.documents
   WHERE entity_type = 'application' AND entity_id = v_appeal.application_id;

  v_items := jsonb_build_array(
    jsonb_build_object('key','original_application','label','Original application',
      'required',true,'satisfied', v_app.id IS NOT NULL),
    jsonb_build_object('key','original_decision','label','Original decision on file',
      'required',true,'satisfied', v_app.rejected_at IS NOT NULL OR v_app.approved_at IS NOT NULL),
    jsonb_build_object('key','decision_rationale','label','Decision rationale',
      'required',true,'satisfied', coalesce(nullif(trim(coalesce(v_app.decision_rationale,'')),''), (
        SELECT nullif(trim(coalesce(aa.comments,'')),'')
          FROM public.approval_actions aa
         WHERE aa.application_id = v_app.id AND aa.action IN ('reject','rejected')
         ORDER BY aa.responded_at DESC NULLS LAST LIMIT 1
      )) IS NOT NULL),
    jsonb_build_object('key','appeal_grounds','label','Grounds of appeal',
      'required',true,'satisfied', nullif(trim(coalesce(v_appeal.grounds,'')),'') IS NOT NULL),
    jsonb_build_object('key','supporting_documents','label','Supporting documents',
      'required',false,'satisfied', v_docs > 0 OR (
        jsonb_typeof(coalesce(v_appeal.supporting_docs,'[]'::jsonb)) = 'array'
        AND jsonb_array_length(coalesce(v_appeal.supporting_docs,'[]'::jsonb)) > 0)),
    jsonb_build_object('key','acknowledgement','label','Appeal acknowledged',
      'required',true,'satisfied', v_appeal.acknowledged_at IS NOT NULL),
    jsonb_build_object('key','legal_review','label','Legal / compliance referral (where required)',
      'required',false,'satisfied', EXISTS (
        SELECT 1 FROM public.application_legal_referrals r
         WHERE r.application_id = v_app.id AND r.status IN ('returned','completed','closed')
      ))
  );

  SELECT count(*) INTO v_blocking
    FROM jsonb_array_elements(v_items) i
   WHERE (i->>'required')::boolean AND NOT (i->>'satisfied')::boolean;

  RETURN jsonb_build_object(
    'appeal_id', _appeal_id,
    'items', v_items,
    'blocking_count', v_blocking,
    'ready', v_blocking = 0
  );
END; $function$
;
CREATE OR REPLACE FUNCTION public.application_blockers(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_gates jsonb; v_out jsonb := '[]'::jsonb; g jsonb; v_fp jsonb;
BEGIN
  v_gates := public.decision_gate_status(_application_id);
  FOR g IN SELECT * FROM jsonb_array_elements(coalesce(v_gates->'gates', '[]'::jsonb)) LOOP
    IF (g->>'blocking')::boolean AND NOT (g->>'passed')::boolean THEN
      v_out := v_out || jsonb_build_array(jsonb_build_object(
        'code', g->>'key', 'label', g->>'label', 'detail', g->>'detail',
        'href', '/applications/' || _application_id));
    END IF;
  END LOOP;

  v_fp := public.application_fp_gate(_application_id);
  IF coalesce((v_fp->>'blocking')::boolean, false) THEN
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'code', 'fit_and_proper',
      'label', 'Fit & Proper assessment outstanding',
      'detail', (v_fp->>'pending') || ' pending, ' || (v_fp->>'adverse') || ' adverse',
      'href', '/applications/' || _application_id));
  END IF;
  RETURN v_out;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.application_case(_application_id uuid, _audience text DEFAULT 'internal'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb; s record; v_ext boolean := (_audience = 'external');
BEGIN
  SELECT * INTO s FROM public.v_application_case_state WHERE id = _application_id;
  IF s.id IS NULL THEN RETURN NULL; END IF;

  v := jsonb_build_object(
    'application_id', s.id,
    'reference', s.application_number,
    'applicant_id', s.applicant_id,
    'applicant_name', s.applicant_name,
    'applicant_org', s.applicant_org,
    'entity_id', s.entity_id,
    'entity_name', s.entity_name,
    'entity_href', CASE WHEN s.entity_id IS NOT NULL THEN '/entities/' || s.entity_id END,
    'application_category', s.application_category,
    'license_type', s.license_type,
    'regulator_id', s.regulator_id,
    'stage', s.stage,
    'stage_label', s.stage_label,
    'status', s.status,
    'status_label', s.status_label,
    'submitted_at', s.submitted_at,
    'created_at', s.created_at,
    'last_activity_at', s.last_activity_at,
    'is_terminal', s.is_terminal,
    'canonical_href', s.canonical_href,
    'next_action', public.application_next_action(s.stage, coalesce(_audience, 'internal')),
    'workflow', jsonb_build_object(
      'instance_id', s.workflow_instance_id,
      'workflow_id', s.workflow_id,
      'current_step_id', s.current_step_id,
      'current_step_name', s.current_step_name,
      'current_step_order', s.current_step_order,
      'is_final_step', s.current_step_is_terminal),
    'sufficiency', (
      SELECT jsonb_build_object(
        'status', s.sufficiency_status,
        'evaluation_id', e.id,
        'evaluated_at', e.evaluated_at,
        'triggered_by', e.triggered_by,
        'overall_status', e.overall_status,
        'blocker_count', e.blocker_count,
        'warning_count', e.warning_count,
        'pass_count', e.pass_count)
        FROM sufficiency_evaluations e
       WHERE e.application_id = s.id ORDER BY e.evaluated_at DESC LIMIT 1),
    'rfis', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', r.id, 'summary', r.summary, 'status', r.status,
               'raised_at', r.raised_at, 'due_at', r.due_at,
               'closed_at', r.closed_at, 'closure_notes', r.closure_notes,
               'pauses_sla', r.pauses_sla,
               'raised_by_name', CASE WHEN v_ext THEN NULL ELSE public.app_actor_display_name(r.raised_by) END)
             ORDER BY r.raised_at DESC)
        FROM application_rfis r WHERE r.application_id = s.id), '[]'::jsonb),
    'open_rfi_count', s.open_rfi_count,
    'forms', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'requirement_id', fr.id, 'template_id', fr.template_id,
               'form_version_id', fr.form_version_id, 'package_id', fr.package_id,
               'is_required', fr.is_required, 'sequence', fr.sequence,
               'status', fr.status, 'response_id', fr.response_id,
               'pinned_at', fr.pinned_at) ORDER BY fr.sequence NULLS LAST)
        FROM application_form_requirements fr WHERE fr.application_id = s.id), '[]'::jsonb),
    'payments', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', p.id, 'amount', p.amount, 'currency', p.currency,
               'status', p.status, 'verification_status', p.verification_status,
               'paid_at', p.paid_at, 'receipt_number', p.receipt_number,
               'fee_configuration_id', p.fee_configuration_id) ORDER BY p.created_at DESC)
        FROM payments p WHERE p.application_id = s.id), '[]'::jsonb),
    'license', (SELECT jsonb_build_object(
               'id', l.id, 'license_number', l.license_number, 'status', l.status,
               'issued_at', l.issued_at, 'valid_from', l.valid_from, 'valid_until', l.valid_until,
               'href', '/licenses/' || l.id)
        FROM licenses l WHERE l.application_id = s.id LIMIT 1)
  );

  IF v_ext THEN
    RETURN v;
  END IF;

  RETURN v || jsonb_build_object(
    'owner_user_id', s.owner_user_id,
    'owner_name', s.owner_name,
    'team', s.team,
    'priority', s.priority,
    'priority_reason', s.priority_reason,
    'priority_source', s.priority_source,
    'manual_priority', s.manual_priority,
    'sla_due_at', s.sla_due_at,
    'sla_state', s.sla_state,
    'sla_hours', s.sla_hours,
    'waiting_on', s.waiting_on,
    'blockers', public.application_blockers(s.id),
    'decision_gates', public.decision_gate_status(s.id),
    'fit_and_proper', public.application_fp_gate(s.id),
    'decision', jsonb_build_object(
      'rationale', (SELECT a.decision_rationale FROM applications a WHERE a.id = s.id),
      'approved_at', (SELECT a.approved_at FROM applications a WHERE a.id = s.id),
      'rejected_at', (SELECT a.rejected_at FROM applications a WHERE a.id = s.id),
      'cancelled_at', (SELECT a.cancelled_at FROM applications a WHERE a.id = s.id),
      'artifacts', coalesce((SELECT jsonb_agg(jsonb_build_object(
            'id', d.id, 'artifact_type', d.artifact_type, 'version', d.version,
            'created_at', d.created_at) ORDER BY d.created_at DESC)
          FROM decision_artifacts d WHERE d.application_id = s.id), '[]'::jsonb))
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.application_classification_update(_application_id uuid, _sector_id uuid DEFAULT NULL::uuid, _sub_sector_id uuid DEFAULT NULL::uuid, _category_id uuid DEFAULT NULL::uuid, _license_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_app record;
  v_editable boolean;
  v_sec record; v_sub record; v_cat record;
  v_set jsonb;
  v_item jsonb;
  v_tids uuid[] := '{}';
  v_versions jsonb := '{}'::jsonb;
  v_data jsonb;
  v_prev_forms jsonb;
  v_kept jsonb := '{}'::jsonb;
  v_retired jsonb := '{}'::jsonb;
  v_key text;
  v_pruned int := 0;
begin
  if v_uid is null then
    return jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED');
  end if;

  select * into v_app from public.applications where id = _application_id for update;
  if not found then
    return jsonb_build_object('error','Application not found','code','NOT_FOUND');
  end if;

  if not (v_app.applicant_id = v_uid
          or public.has_permission(v_uid,'application_management','edit')
          or public.wb_entity_member(v_app.entity_id)) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  v_editable := coalesce(lower(v_app.status),'draft')
                in ('draft','in_progress','resubmission_requested','query_raised');
  if not v_editable then
    return jsonb_build_object('error','Application is not in an editable state',
                              'code','APPLICATION_NOT_EDITABLE','status',v_app.status);
  end if;

  -- Taxonomy relationship validation (server authority).
  if _sector_id is not null then
    select * into v_sec from public.sectors where id = _sector_id and status = 'active';
    if not found then return jsonb_build_object('error','Unknown or inactive sector','code','INVALID_SECTOR'); end if;
  end if;
  if _sub_sector_id is not null then
    select * into v_sub from public.sub_sectors where id = _sub_sector_id and status = 'active';
    if not found then return jsonb_build_object('error','Unknown or inactive sub-sector','code','INVALID_SUB_SECTOR'); end if;
    if v_sub.sector_id is distinct from _sector_id then
      return jsonb_build_object('error','Sub-sector does not belong to the selected sector','code','TAXONOMY_MISMATCH');
    end if;
  end if;
  if _category_id is not null then
    select * into v_cat from public.categories where id = _category_id and status = 'active';
    if not found then return jsonb_build_object('error','Unknown or inactive category','code','INVALID_CATEGORY'); end if;
    if v_cat.sub_sector_id is distinct from _sub_sector_id then
      return jsonb_build_object('error','Category does not belong to the selected sub-sector','code','TAXONOMY_MISMATCH');
    end if;
  end if;
  if _category_id is not null and _sub_sector_id is null then
    return jsonb_build_object('error','Category requires a sub-sector','code','TAXONOMY_MISMATCH');
  end if;
  if _sub_sector_id is not null and _sector_id is null then
    return jsonb_build_object('error','Sub-sector requires a sector','code','TAXONOMY_MISMATCH');
  end if;

  v_set := public.application_resolve_form_set(
             v_app.regulator_id, _sector_id, _sub_sector_id, _category_id,
             coalesce(nullif(_license_type,''), v_app.license_type),
             coalesce(v_app.data->>'application_type','pre_license'));

  for v_item in select * from jsonb_array_elements(coalesce(v_set->'items','[]'::jsonb)) loop
    v_tids := v_tids || (v_item->>'template_id')::uuid;
    if nullif(v_item->>'form_version_id','') is not null then
      v_versions := v_versions || jsonb_build_object(v_item->>'template_id', v_item->>'form_version_id');
    end if;
  end loop;

  -- Draft answers: keep applicable, ARCHIVE (never destroy) the rest.
  v_data := coalesce(v_app.data, '{}'::jsonb);
  v_prev_forms := coalesce(v_data->'forms_data', '{}'::jsonb);
  v_retired := coalesce(v_data->'retired_forms_data', '{}'::jsonb);
  for v_key in select jsonb_object_keys(v_prev_forms) loop
    if v_key = any (select unnest(v_tids)::text) then
      v_kept := v_kept || jsonb_build_object(v_key, v_prev_forms->v_key);
    else
      v_retired := v_retired || jsonb_build_object(v_key, v_prev_forms->v_key);
      v_pruned := v_pruned + 1;
    end if;
  end loop;

  v_data := v_data
    || jsonb_build_object(
         'sector_id', coalesce(_sector_id::text, ''),
         'sub_sector_id', coalesce(_sub_sector_id::text, ''),
         'category_id', coalesce(_category_id::text, ''),
         'sector_name', coalesce(v_sec.name, ''),
         'sub_sector_name', coalesce(v_sub.name, ''),
         'category_name', coalesce(v_cat.name, ''),
         'form_template_ids', to_jsonb(coalesce(array(select unnest(v_tids)::text), '{}'::text[])),
         'form_version_ids', v_versions,
         'forms_data', v_kept,
         'retired_forms_data', v_retired,
         'form_applicability', jsonb_build_object(
            'source', v_set->>'source',
            'scope', v_set->>'scope',
            'package_id', v_set->>'package_id',
            'applicability_rule_id', v_set->>'applicability_rule_id',
            'resolved_at', now()));

  update public.applications
     set data = v_data,
         license_type = coalesce(nullif(_license_type,''), license_type),
         updated_at = now()
   where id = _application_id;

  -- Server-owned requirement pin for this application.
  delete from public.application_form_requirements
   where application_id = _application_id
     and (array_length(v_tids,1) is null or template_id <> all (v_tids));

  for v_item in select * from jsonb_array_elements(coalesce(v_set->'items','[]'::jsonb)) loop
    if nullif(v_item->>'form_version_id','') is null then continue; end if;
    insert into public.application_form_requirements
      (application_id, template_id, form_version_id, package_id, applicability_rule_id, is_required, sequence)
    values (_application_id, (v_item->>'template_id')::uuid, (v_item->>'form_version_id')::uuid,
            nullif(v_set->>'package_id','')::uuid, nullif(v_set->>'applicability_rule_id','')::uuid,
            coalesce((v_item->>'is_required')::boolean, true), coalesce((v_item->>'sequence')::int, 0))
    on conflict (application_id, template_id)
      do update set form_version_id = excluded.form_version_id,
                    is_required = excluded.is_required,
                    sequence = excluded.sequence,
                    updated_at = now();
  end loop;

  perform public.create_audit_log(
    v_uid, 'application.classification.updated', 'application', _application_id::text, null,
    jsonb_build_object('sector_id',_sector_id,'sub_sector_id',_sub_sector_id,'category_id',_category_id,
                       'license_type', coalesce(nullif(_license_type,''), v_app.license_type),
                       'source', v_set->>'source', 'scope', v_set->>'scope',
                       'templates', to_jsonb(coalesce(array(select unnest(v_tids)::text),'{}'::text[])),
                       'archived_form_answers', v_pruned), null);

  return jsonb_build_object(
    'success', true,
    'application_id', _application_id,
    'resolved', coalesce((v_set->>'resolved')::boolean, false),
    'source', v_set->>'source',
    'scope', v_set->>'scope',
    'package_id', v_set->>'package_id',
    'items', coalesce(v_set->'items','[]'::jsonb),
    'form_template_ids', to_jsonb(coalesce(array(select unnest(v_tids)::text),'{}'::text[])),
    'form_version_ids', v_versions,
    'archived_form_answers', v_pruned);
end $function$
;
CREATE OR REPLACE FUNCTION public.application_delete_draft(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  SELECT id, applicant_id, status, application_number
    INTO v_app FROM public.applications WHERE id = _application_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Application not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_app.applicant_id <> v_uid THEN
    RAISE EXCEPTION 'You cannot delete this application' USING ERRCODE = '42501';
  END IF;
  IF v_app.status <> 'draft' THEN
    RAISE EXCEPTION 'Only a draft application can be deleted' USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);
  DELETE FROM public.applications WHERE id = _application_id;

  PERFORM public.create_audit_log(
    v_uid, 'application_draft_deleted', 'application', _application_id::text,
    jsonb_build_object('application_number', v_app.application_number), NULL, NULL);

  RETURN jsonb_build_object('success', true);
END; $function$
;
CREATE OR REPLACE FUNCTION public.application_draft_save(_application_id uuid, _data jsonb, _license_type text DEFAULT NULL::text, _regulator_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app public.applications;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: You must be signed in to save an application.'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_app FROM public.applications WHERE id = _application_id;
  IF v_app.id IS NULL THEN
    RAISE EXCEPTION 'APPLICATION_NOT_FOUND: Application % does not exist.', _application_id
      USING ERRCODE = 'P0002';
  END IF;

  IF NOT (
    public.is_super_admin(v_uid)
    OR v_app.applicant_id = v_uid
    OR public.has_permission(v_uid, 'application_management', 'edit')
    OR EXISTS (
      SELECT 1 FROM public.entity_user_memberships m
       WHERE m.user_id = v_uid AND m.status = 'APPROVED'
         AND m.entity_id = v_app.entity_id
    )
  ) THEN
    RAISE EXCEPTION 'APPLICATION_EDIT_FORBIDDEN: You do not have permission to edit this application.'
      USING ERRCODE = '42501';
  END IF;

  IF COALESCE(v_app.status, 'draft') NOT IN (
    'draft', 'in_progress', 'returned', 'info_requested', 'query_raised',
    'resubmission_required', 'pending_payment'
  ) AND NOT public.is_super_admin(v_uid)
    AND NOT public.has_permission(v_uid, 'application_management', 'edit') THEN
    RAISE EXCEPTION 'APPLICATION_NOT_EDITABLE: This application is not currently open for editing.'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.applications
     SET data = COALESCE(_data, data),
         license_type = COALESCE(NULLIF(trim(COALESCE(_license_type, '')), ''), license_type),
         regulator_id = COALESCE(_regulator_id, regulator_id),
         updated_at = now()
   WHERE id = _application_id;

  RETURN jsonb_build_object('success', true, 'application_id', _application_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.application_fp_gate(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entity uuid;
  v_rows jsonb;
  v_pending int := 0;
  v_adverse int := 0;
  v_conditional int := 0;
  v_linkage text;
  v_explicit int := 0;
BEGIN
  SELECT entity_id INTO v_entity FROM applications WHERE id = _application_id;

  SELECT count(*) INTO v_explicit
    FROM application_fp_links WHERE application_id = _application_id;

  IF v_explicit = 0 AND v_entity IS NULL THEN
    RETURN jsonb_build_object('required', false, 'linked', '[]'::jsonb, 'linkage', 'none',
      'pending', 0, 'adverse', 0, 'conditional', 0, 'blocking', false);
  END IF;

  v_linkage := CASE WHEN v_explicit > 0 THEN 'explicit' ELSE 'entity_inferred' END;

  SELECT coalesce(jsonb_agg(x.row ORDER BY x.person), '[]'::jsonb),
         count(*) FILTER (WHERE x.outcome IS NULL AND x.is_required),
         count(*) FILTER (WHERE lower(coalesce(x.outcome, '')) IN ('not_fit','adverse','rejected','fail','refused')),
         count(*) FILTER (WHERE lower(coalesce(x.outcome, '')) IN ('conditional','fit_with_conditions'))
    INTO v_rows, v_pending, v_adverse, v_conditional
  FROM (
    SELECT coalesce(i.full_name, 'Unknown') AS person,
           d.outcome AS outcome,
           coalesce(l.is_required, true) AS is_required,
           jsonb_build_object(
             'assessment_id', a.id,
             'person', coalesce(i.full_name, 'Unknown'),
             'role', coalesce(l.role_note, r.role_title, r.role_type, a.assessment_type),
             'stage', a.status,
             'status', a.status,
             'determination', d.outcome,
             'determined_at', d.determined_at,
             'is_required', coalesce(l.is_required, true),
             'linkage', CASE WHEN l.id IS NOT NULL THEN 'explicit' ELSE 'entity_inferred' END,
             'licensing_blocker',
               (coalesce(l.is_required, true) AND d.outcome IS NULL)
               OR lower(coalesce(d.outcome, '')) IN ('not_fit','adverse','rejected','fail','refused'),
             'href', '/fpa/assessments/' || a.id
           ) AS row
      FROM fp_assessments a
      LEFT JOIN application_fp_links l
             ON l.assessment_id = a.id AND l.application_id = _application_id
      LEFT JOIN fp_individuals i ON i.id = a.individual_id
      LEFT JOIN fp_individual_roles r ON r.id = a.role_id
      LEFT JOIN fp_determinations d ON d.assessment_id = a.id AND coalesce(d.is_current, true)
     WHERE coalesce(a.status, '') NOT IN ('withdrawn', 'cancelled')
       AND (
         (v_explicit > 0 AND l.id IS NOT NULL)                      -- explicit linkage wins
         OR (v_explicit = 0 AND v_entity IS NOT NULL AND a.licensee_id = v_entity)
       )
  ) x;

  RETURN jsonb_build_object(
    'required', jsonb_array_length(coalesce(v_rows, '[]'::jsonb)) > 0,
    'linkage', v_linkage,
    'linked', coalesce(v_rows, '[]'::jsonb),
    'pending', coalesce(v_pending, 0),
    'adverse', coalesce(v_adverse, 0),
    'conditional', coalesce(v_conditional, 0),
    'blocking', coalesce(v_pending, 0) > 0 OR coalesce(v_adverse, 0) > 0
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.application_ids_for_licensee(_licensee_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT lic.application_id
  FROM public.licenses lic
  JOIN public.licensees l ON l.license_id = lic.id
  WHERE l.id = _licensee_id AND lic.application_id IS NOT NULL
$function$
;
CREATE OR REPLACE FUNCTION public.application_next_action(_stage text, _audience text DEFAULT 'internal'::text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _audience = 'external' THEN CASE _stage
      WHEN 'PREPARATION' THEN jsonb_build_object('code', 'COMPLETE_APPLICATION', 'label', 'Complete and submit your application', 'permission', NULL)
      WHEN 'AWAITING_APPLICANT' THEN jsonb_build_object('code', 'RESPOND_RFI', 'label', 'Respond to the information request', 'permission', NULL)
      WHEN 'AUTHORISATION' THEN jsonb_build_object('code', 'AWAIT_LICENCE', 'label', 'Approved — licence being issued', 'permission', NULL)
      WHEN 'CLOSED' THEN jsonb_build_object('code', 'NONE', 'label', 'No action required', 'permission', NULL)
      ELSE jsonb_build_object('code', 'AWAIT_REVIEW', 'label', 'Await regulator review', 'permission', NULL)
    END
    ELSE CASE _stage
      WHEN 'PREPARATION' THEN jsonb_build_object('code', 'AWAIT_SUBMISSION', 'label', 'Awaiting applicant submission', 'permission', NULL)
      WHEN 'SUBMITTED_INTAKE' THEN jsonb_build_object('code', 'TRIAGE', 'label', 'Triage and assign the application', 'permission', 'application_management.update')
      WHEN 'SUFFICIENCY_REVIEW' THEN jsonb_build_object('code', 'EVALUATE_SUFFICIENCY', 'label', 'Run the sufficiency evaluation', 'permission', 'application_management.review')
      WHEN 'AWAITING_APPLICANT' THEN jsonb_build_object('code', 'AWAIT_APPLICANT', 'label', 'Awaiting applicant response to information request', 'permission', NULL)
      WHEN 'REGULATORY_REVIEW' THEN jsonb_build_object('code', 'COMPLETE_REVIEW', 'label', 'Complete the current review step', 'permission', 'application_management.review')
      WHEN 'DECISION' THEN jsonb_build_object('code', 'RECORD_DECISION', 'label', 'Record the authorisation decision', 'permission', 'application_management.approve')
      WHEN 'AUTHORISATION' THEN jsonb_build_object('code', 'ISSUE_LICENCE', 'label', 'Complete licence issuance handoff', 'permission', 'license_management.create')
      ELSE jsonb_build_object('code', 'NONE', 'label', 'No action required', 'permission', NULL)
    END
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.application_open_rfi_count(_application_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT count(*)::int FROM application_rfis
   WHERE application_id = _application_id AND status = 'open';
$function$
;
CREATE OR REPLACE FUNCTION public.application_payment_verify(_payment_id uuid, _application_id uuid, _note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _before jsonb; _after jsonb; _target uuid;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;
  IF NOT (public.has_permission(_uid,'fee_management','edit')
          OR public.has_permission(_uid,'application_management','approve')
          OR public.is_super_admin(_uid)) THEN
    RAISE EXCEPTION 'Payment verification permission required' USING ERRCODE='42501';
  END IF;

  IF _payment_id IS NOT NULL THEN
    SELECT id INTO _target FROM public.payments WHERE id=_payment_id;
  ELSIF _application_id IS NOT NULL THEN
    SELECT id INTO _target FROM public.payments WHERE application_id=_application_id ORDER BY created_at DESC LIMIT 1;
  END IF;
  IF _target IS NULL THEN RAISE EXCEPTION 'Payment not found' USING ERRCODE='P0002'; END IF;

  SELECT to_jsonb(p) INTO _before FROM public.payments p WHERE p.id=_target;
  UPDATE public.payments SET status='success', paid_at=now() WHERE id=_target
    RETURNING to_jsonb(payments) INTO _after;
  PERFORM public.log_compliance_audit('APPROVE'::compliance_audit_action,
    'payment', _target::text, _before, _after, nullif(btrim(coalesce(_note,'')),''));
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.application_pin_form_requirements(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_app record; v_res jsonb; v_item jsonb; v_count int := 0; v_missing int := 0;
BEGIN
  SELECT * INTO v_app FROM public.applications WHERE id = _application_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Application not found'; END IF;
  IF NOT (public.has_permission(auth.uid(),'application_management','view')
          OR v_app.applicant_id = auth.uid()
          OR public.wb_entity_member(v_app.entity_id)) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (SELECT 1 FROM public.application_form_requirements WHERE application_id = _application_id) THEN
    RETURN jsonb_build_object('success',true,'idempotent',true,'application_id',_application_id);
  END IF;

  v_res := public.resolve_applicable_form_package(jsonb_build_object(
    'regulator_id', v_app.regulator_id,
    'sector_id', v_app.data->>'sector_id',
    'sub_sector_id', v_app.data->>'sub_sector_id',
    'category_id', v_app.data->>'category_id',
    'license_type', v_app.license_type,
    'lifecycle_key', 'applicant',
    'application_type', COALESCE(v_app.data->>'application_type','pre_license')));

  IF NOT (v_res->>'resolved')::boolean THEN
    RETURN jsonb_build_object('success',false,'code','NO_APPLICABLE_PACKAGE','application_id',_application_id);
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_res->'items') LOOP
    IF NULLIF(v_item->>'form_version_id','') IS NULL THEN
      v_missing := v_missing + 1;  -- never pin an unpublished form
      CONTINUE;
    END IF;
    INSERT INTO public.application_form_requirements
      (application_id, template_id, form_version_id, package_id, applicability_rule_id, is_required, sequence)
    VALUES (_application_id, (v_item->>'template_id')::uuid, (v_item->>'form_version_id')::uuid,
            (v_res->>'package_id')::uuid, (v_res->>'applicability_rule_id')::uuid,
            COALESCE((v_item->>'is_required')::boolean,true), COALESCE((v_item->>'sequence')::int,0))
    ON CONFLICT (application_id, template_id) DO NOTHING;
    v_count := v_count + 1;
  END LOOP;

  PERFORM public.create_audit_log(auth.uid(),'form.applicability.changed','application',_application_id::text,NULL,
    jsonb_build_object('package_id', v_res->>'package_id','pinned', v_count,'skipped_unpublished', v_missing), NULL);
  RETURN jsonb_build_object('success',true,'application_id',_application_id,'pinned',v_count,
    'skipped_unpublished',v_missing,'package_id',v_res->>'package_id');
END $function$
;
CREATE OR REPLACE FUNCTION public.application_record_action(_application_id uuid, _action text, _comments text DEFAULT NULL::text, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_applicant_action boolean;
  v_now timestamptz := now();
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF _action IS NULL OR trim(_action) = '' THEN
    RAISE EXCEPTION 'action is required' USING ERRCODE = '22023';
  END IF;
  IF lower(_action) IN ('approved','rejected','cancelled','approve','reject') THEN
    RAISE EXCEPTION 'Final decisions must use the governed decision workflow'
      USING ERRCODE = '22023';
  END IF;

  SELECT id, applicant_id, status, application_number
    INTO v_app FROM public.applications WHERE id = _application_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Application not found' USING ERRCODE = 'P0002';
  END IF;

  v_applicant_action := lower(_action) IN ('edit_requested','resubmitted','withdraw_requested');

  IF v_applicant_action THEN
    IF NOT public.can_mutate_application(v_uid, _application_id) THEN
      RAISE EXCEPTION 'You are not entitled to act on this application'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT public.has_permission(v_uid, 'application_management', 'workflow_action') THEN
      RAISE EXCEPTION 'Application workflow authority required' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Reason is mandatory on every action that changes what the applicant or
  -- the regulator may next do with the application.
  IF lower(_action) IN ('edit_requested','edit_denied','edit_approved') THEN
    PERFORM public.app_require_rationale(_comments, 10, 'Reason');
  END IF;

  INSERT INTO public.approval_actions (
    application_id, actor_id, action, action_type, comments, responded_at,
    entity_type, entity_id
  ) VALUES (
    _application_id, v_uid, _action, lower(_action), NULLIF(trim(_comments), ''), v_now,
    'application', _application_id
  ) RETURNING id INTO v_id;

  PERFORM public.create_audit_log(
    v_uid, 'application_action_recorded', 'application', _application_id::text, NULL,
    jsonb_build_object('action', _action, 'comments', _comments),
    COALESCE(_metadata, '{}'::jsonb)
  );

  RETURN jsonb_build_object('success', true, 'action_id', v_id);
END; $function$
;
CREATE OR REPLACE FUNCTION public.application_resolve_form_set(_regulator_id uuid, _sector_id uuid, _sub_sector_id uuid, _category_id uuid, _license_type text DEFAULT NULL::text, _application_type text DEFAULT 'pre_license'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pkg jsonb;
  v_items jsonb;
  v_scope text;
  v_types text[];
begin
  if _sector_id is null and _sub_sector_id is null and _category_id is null then
    return jsonb_build_object('resolved', false, 'reason', 'INCOMPLETE_TAXONOMY',
                              'source', 'none', 'items', '[]'::jsonb);
  end if;

  v_types := case when coalesce(_application_type, 'pre_license') = 'post_license'
                  then array['post_license','application']
                  else array['pre_license','application'] end;

  if _sector_id is not null and _sub_sector_id is not null and _category_id is not null then
    v_pkg := public.resolve_applicable_form_package(jsonb_build_object(
      'regulator_id', _regulator_id,
      'sector_id', _sector_id,
      'sub_sector_id', _sub_sector_id,
      'category_id', _category_id,
      'license_type', _license_type,
      'lifecycle_key', case when coalesce(_application_type,'pre_license')='post_license' then 'licensee' else 'applicant' end,
      'application_type', coalesce(_application_type, 'pre_license')));

    if coalesce((v_pkg->>'resolved')::boolean, false) then
      return v_pkg || jsonb_build_object('source', 'package', 'scope', 'package');
    end if;
  end if;

  for v_scope in select unnest(array['category','sub_sector','sector']) loop
    if (v_scope = 'category' and _category_id is null)
       or (v_scope = 'sub_sector' and _sub_sector_id is null)
       or (v_scope = 'sector' and _sector_id is null) then
      continue;
    end if;

    select jsonb_agg(x order by x->>'template_name')
      into v_items
      from (
        select jsonb_build_object(
                 'template_id', t.id,
                 'template_name', t.name,
                 'is_required', true,
                 'sequence', coalesce(t.form_order, 0),
                 'form_version_id', pv.id,
                 'form_version', pv.version) as x
          from public.form_templates t
          left join lateral (
            select v.id, v.version
              from public.form_versions v
             where v.template_id = t.id
               and v.status = 'published'
               and (v.effective_from is null or v.effective_from <= now())
               and (v.effective_until is null or v.effective_until >= now())
             order by v.version desc
             limit 1) pv on true
         where t.status = 'published'
           and t.form_type = any(v_types)
           and (t.regulator_id is null or _regulator_id is null or t.regulator_id = _regulator_id)
           and case v_scope
                 when 'category'   then t.category_id = _category_id
                 when 'sub_sector' then t.sub_sector_id = _sub_sector_id and t.category_id is null
                 else t.sector_id = _sector_id and t.sub_sector_id is null and t.category_id is null
               end
      ) s;

    if v_items is not null and jsonb_array_length(v_items) > 0 then
      return jsonb_build_object('resolved', true, 'source', 'template_taxonomy', 'scope', v_scope,
                                'package_id', null, 'applicability_rule_id', null, 'items', v_items);
    end if;
  end loop;

  return jsonb_build_object('resolved', false, 'reason', 'NO_APPLICABLE_FORMS',
                            'source', 'none', 'items', '[]'::jsonb);
end $function$
;
CREATE OR REPLACE FUNCTION public.application_rfi_close(_rfi_id uuid, _closure_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_rfi public.application_rfis;
  v_status text;
  v_reverted text := NULL;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: You must be signed in to close an information request.'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_rfi FROM public.application_rfis WHERE id = _rfi_id;
  IF v_rfi.id IS NULL THEN
    RAISE EXCEPTION 'RFI_NOT_FOUND: Information request % does not exist.', _rfi_id
      USING ERRCODE = 'P0002';
  END IF;

  IF NOT (
    public.is_super_admin(v_uid)
    OR public.has_permission(v_uid, 'application_management', 'edit')
    OR public.has_permission(v_uid, 'application_management', 'review')
  ) THEN
    RAISE EXCEPTION 'RFI_CLOSE_FORBIDDEN: You do not have permission to close information requests.'
      USING ERRCODE = '42501';
  END IF;

  IF v_rfi.status = 'closed' THEN
    RETURN jsonb_build_object('success', true, 'already_closed', true);
  END IF;

  UPDATE public.application_rfis
     SET status = 'closed',
         closed_by = v_uid,
         closed_at = now(),
         closure_notes = NULLIF(trim(COALESCE(_closure_notes, '')), '')
   WHERE id = _rfi_id;

  SELECT status INTO v_status FROM public.applications WHERE id = v_rfi.application_id;
  IF v_status IN ('info_requested', 'query_raised') THEN
    UPDATE public.applications
       SET status = 'under_review', updated_at = now()
     WHERE id = v_rfi.application_id;
    v_reverted := v_status;
  END IF;

  INSERT INTO public.compliance_audit_logs (
    user_id, action_type, object_type, object_id, after_value, justification
  ) VALUES (
    v_uid, 'UPDATE'::public.compliance_audit_action, 'application_rfis', _rfi_id::text,
    jsonb_build_object('status', 'closed', 'status_reverted_from', v_reverted),
    NULLIF(trim(COALESCE(_closure_notes, '')), '')
  );

  RETURN jsonb_build_object('success', true, 'status_reverted_from', v_reverted);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.application_rfi_pauses_sla(_application_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT exists(SELECT 1 FROM application_rfis
                 WHERE application_id = _application_id AND status = 'open'
                   AND coalesce(pauses_sla, false));
$function$
;
CREATE OR REPLACE FUNCTION public.application_rfi_raise(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _rfi_id uuid; _app_id uuid; _item jsonb; _ord int := 0;
        _step_action_id uuid; _pause boolean; _summary text; _after jsonb;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;
  IF NOT (public.has_permission(_uid,'application_management','workflow_action')
          OR public.has_permission(_uid,'application_management','edit')
          OR public.is_super_admin(_uid)) THEN
    RAISE EXCEPTION 'Application workflow permission required' USING ERRCODE='42501';
  END IF;

  _app_id := nullif(_payload->>'application_id','')::uuid;
  IF _app_id IS NULL THEN
    RAISE EXCEPTION 'application_id is required' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.applications WHERE id=_app_id) THEN
    RAISE EXCEPTION 'Application not found' USING ERRCODE='P0002';
  END IF;
  IF coalesce(jsonb_array_length(_payload->'items'),0) = 0 THEN
    RAISE EXCEPTION 'At least one information request item is required' USING ERRCODE='22023';
  END IF;

  _summary := nullif(btrim(coalesce(_payload->>'summary','')),'');
  _step_action_id := nullif(_payload->>'approval_step_action_id','')::uuid;
  _pause := coalesce((_payload->>'pause_sla')::boolean, false);

  INSERT INTO public.application_rfis (
    application_id, raised_by, due_at, summary, approval_step_action_id, status,
    sufficiency_evaluation_id, pauses_sla
  ) VALUES (
    _app_id, _uid,
    nullif(_payload->>'due_at','')::timestamptz,
    _summary,
    _step_action_id,
    'open',
    nullif(_payload->>'sufficiency_evaluation_id','')::uuid,
    coalesce((_payload->>'pauses_sla')::boolean, nullif(_payload->>'sufficiency_evaluation_id','') IS NOT NULL)
  ) RETURNING id INTO _rfi_id;

  FOR _item IN SELECT * FROM jsonb_array_elements(_payload->'items') LOOP
    IF coalesce(length(btrim(_item->>'prompt')),0) = 0 THEN
      RAISE EXCEPTION 'Every information request item needs a prompt' USING ERRCODE='22023';
    END IF;
    INSERT INTO public.application_rfi_items (
      rfi_id, ordinal, prompt, question_type, required, item_due_at, response_status
    ) VALUES (
      _rfi_id, _ord, btrim(_item->>'prompt'),
      coalesce(nullif(_item->>'question_type',''),'text'),
      coalesce((_item->>'required')::boolean, true),
      nullif(_item->>'item_due_at','')::timestamptz,
      'pending'
    );
    _ord := _ord + 1;
  END LOOP;

  IF _pause AND _step_action_id IS NOT NULL THEN
    UPDATE public.approval_step_actions SET
      paused_at = now(),
      paused_reason = 'RFI raised: ' || coalesce(_summary,'awaiting applicant response'),
      resumed_at = NULL
    WHERE id = _step_action_id;
  END IF;

  SELECT to_jsonb(r) INTO _after FROM public.application_rfis r WHERE r.id=_rfi_id;
  PERFORM public.log_compliance_audit('CREATE'::compliance_audit_action,
    'application_rfi', _rfi_id::text, NULL, _after, _summary);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.application_rfi_submit_response(p_rfi_item_id uuid, p_response_text text DEFAULT NULL::text, p_file_upload_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_item public.application_rfi_items;
  v_rfi public.application_rfis;
  v_all_done boolean;
  v_response_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_item FROM public.application_rfi_items WHERE id = p_rfi_item_id;
  IF v_item.id IS NULL THEN
    RAISE EXCEPTION 'Information request question not found';
  END IF;

  SELECT * INTO v_rfi FROM public.application_rfis WHERE id = v_item.rfi_id;
  IF v_rfi.id IS NULL THEN
    RAISE EXCEPTION 'Information request not found';
  END IF;

  IF NOT (
    public.is_super_admin(v_uid)
    OR public.has_permission(v_uid, 'application_management', 'edit')
    OR public.has_permission(v_uid, 'application_management', 'workflow_action')
    OR public.can_mutate_application(v_uid, v_rfi.application_id)
  ) THEN
    RAISE EXCEPTION 'Not authorised to respond to this information request';
  END IF;

  IF v_rfi.status NOT IN ('open', 'responded') THEN
    RAISE EXCEPTION 'This information request is closed to further responses';
  END IF;

  IF v_item.response_status = 'responded'
     OR EXISTS (SELECT 1 FROM public.application_rfi_responses WHERE rfi_item_id = p_rfi_item_id) THEN
    RAISE EXCEPTION 'This question has already been answered';
  END IF;

  INSERT INTO public.application_rfi_responses (rfi_item_id, response_text, file_upload_ids, submitted_by)
  VALUES (p_rfi_item_id, NULLIF(btrim(coalesce(p_response_text, '')), ''), coalesce(p_file_upload_ids, '{}'::uuid[]), v_uid)
  RETURNING id INTO v_response_id;

  UPDATE public.application_rfi_items
  SET response_status = 'responded'
  WHERE id = p_rfi_item_id;

  SELECT NOT EXISTS (
    SELECT 1 FROM public.application_rfi_items
    WHERE rfi_id = v_rfi.id AND response_status <> 'responded'
  ) INTO v_all_done;

  IF v_all_done THEN
    UPDATE public.application_rfis SET status = 'responded' WHERE id = v_rfi.id;
    IF v_rfi.approval_step_action_id IS NOT NULL THEN
      UPDATE public.approval_step_actions
      SET resumed_at = now()
      WHERE id = v_rfi.approval_step_action_id AND resumed_at IS NULL;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'response_id', v_response_id,
    'rfi_id', v_rfi.id,
    'application_id', v_rfi.application_id,
    'all_items_done', v_all_done
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.application_triage_update(_application_ids uuid[], _priority integer DEFAULT NULL::integer, _priority_reason text DEFAULT NULL::text, _assigned_to uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_now timestamptz := now();
  v_id uuid;
  v_count integer := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission(v_uid, 'application_management', 'edit') THEN
    RAISE EXCEPTION 'Application management authority required' USING ERRCODE = '42501';
  END IF;
  IF _application_ids IS NULL OR array_length(_application_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'At least one application is required' USING ERRCODE = '22023';
  END IF;
  IF _priority IS NULL AND _assigned_to IS NULL THEN
    RAISE EXCEPTION 'Provide a priority or an assignee' USING ERRCODE = '22023';
  END IF;
  IF _priority IS NOT NULL AND (_priority < 1 OR _priority > 5) THEN
    RAISE EXCEPTION 'Priority must be between 1 and 5' USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  FOREACH v_id IN ARRAY _application_ids LOOP
    UPDATE public.applications
       SET priority        = COALESCE(_priority, priority),
           priority_reason = CASE WHEN _priority IS NOT NULL
                                  THEN NULLIF(trim(_priority_reason), '') ELSE priority_reason END,
           priority_set_by = CASE WHEN _priority IS NOT NULL THEN v_uid ELSE priority_set_by END,
           priority_set_at = CASE WHEN _priority IS NOT NULL THEN v_now ELSE priority_set_at END,
           assigned_to     = COALESCE(_assigned_to, assigned_to),
           assigned_by     = CASE WHEN _assigned_to IS NOT NULL THEN v_uid ELSE assigned_by END,
           assigned_at     = CASE WHEN _assigned_to IS NOT NULL THEN v_now ELSE assigned_at END,
           updated_at      = v_now
     WHERE id = v_id;
    IF FOUND THEN
      v_count := v_count + 1;
      PERFORM public.create_audit_log(
        v_uid, 'application_triage_updated', 'application', v_id::text, NULL,
        jsonb_build_object('priority', _priority, 'assigned_to', _assigned_to,
                           'priority_reason', _priority_reason), NULL);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'updated', v_count);
END; $function$
;
CREATE OR REPLACE FUNCTION public.application_work_queue(_stages text[] DEFAULT NULL::text[], _statuses text[] DEFAULT NULL::text[], _sla_states text[] DEFAULT NULL::text[], _waiting_on text DEFAULT NULL::text, _categories text[] DEFAULT NULL::text[], _license_type text DEFAULT NULL::text, _entity_id uuid DEFAULT NULL::uuid, _regulator_id uuid DEFAULT NULL::uuid, _sector_id uuid DEFAULT NULL::uuid, _assigned_to uuid DEFAULT NULL::uuid, _unassigned boolean DEFAULT false, _priorities text[] DEFAULT NULL::text[], _submitted_from timestamp with time zone DEFAULT NULL::timestamp with time zone, _submitted_to timestamp with time zone DEFAULT NULL::timestamp with time zone, _search text DEFAULT NULL::text, _include_closed boolean DEFAULT false, _include_drafts boolean DEFAULT false, _sort text DEFAULT 'priority'::text, _limit integer DEFAULT 25, _offset integer DEFAULT 0)
 RETURNS TABLE(application_id uuid, application_number text, applicant_id uuid, applicant_name text, entity_id uuid, entity_name text, application_category text, license_type text, stage text, stage_label text, status text, status_label text, owner_user_id uuid, owner_name text, team text, priority text, priority_reason text, priority_source text, sla_due_at timestamp with time zone, sla_state text, waiting_on text, blocker_count integer, blockers jsonb, next_action_code text, next_action_label text, next_action_permission text, next_action_href text, submitted_at timestamp with time zone, last_activity_at timestamp with time zone, current_workflow_step text, canonical_href text, total_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH scoped AS (
    SELECT v.* FROM public.v_application_case_state v
     WHERE (_include_closed OR NOT v.is_terminal)
       AND (_include_drafts OR v.status <> 'draft')
       AND (_stages IS NULL OR v.stage = ANY(_stages))
       AND (_statuses IS NULL OR v.status = ANY(_statuses))
       AND (_sla_states IS NULL OR v.sla_state = ANY(_sla_states))
       AND (_waiting_on IS NULL OR v.waiting_on = _waiting_on)
       AND (_categories IS NULL OR v.application_category = ANY(_categories))
       AND (_license_type IS NULL OR v.license_type ILIKE '%' || _license_type || '%')
       AND (_entity_id IS NULL OR v.entity_id = _entity_id)
       AND (_regulator_id IS NULL OR v.regulator_id = _regulator_id)
       AND (_sector_id IS NULL OR EXISTS (
             SELECT 1 FROM public.applications a WHERE a.id = v.id
              AND (a.data->>'sector_id' = _sector_id::text
                OR a.data->>'resolved_sector_id' = _sector_id::text)))
       AND (_assigned_to IS NULL OR v.owner_user_id = _assigned_to)
       AND (NOT _unassigned OR v.owner_user_id IS NULL)
       AND (_priorities IS NULL OR v.priority = ANY(_priorities))
       AND (_submitted_from IS NULL OR v.submitted_at >= _submitted_from)
       AND (_submitted_to IS NULL OR v.submitted_at <= _submitted_to)
       AND (_search IS NULL OR btrim(_search) = '' OR
            v.application_number ILIKE '%' || btrim(_search) || '%' OR
            coalesce(v.applicant_name, '') ILIKE '%' || btrim(_search) || '%' OR
            coalesce(v.entity_name, '') ILIKE '%' || btrim(_search) || '%' OR
            coalesce(v.license_type, '') ILIKE '%' || btrim(_search) || '%')
  ), counted AS (SELECT count(*) AS n FROM scoped)
  SELECT s.id, s.application_number, s.applicant_id,
         CASE WHEN s.applicant_org IS NOT NULL AND s.applicant_org <> s.applicant_name
              THEN s.applicant_name || ' (' || s.applicant_org || ')' ELSE s.applicant_name END,
         s.entity_id, s.entity_name, s.application_category, s.license_type,
         s.stage, s.stage_label, s.status, s.status_label,
         s.owner_user_id, s.owner_name, s.team,
         s.priority, s.priority_reason, s.priority_source,
         s.sla_due_at, s.sla_state, s.waiting_on,
         jsonb_array_length(b.blockers)::int, b.blockers,
         na->>'code', na->>'label', na->>'permission', s.canonical_href,
         s.submitted_at, s.last_activity_at, s.current_step_name, s.canonical_href, counted.n
    FROM scoped s
    CROSS JOIN counted
    CROSS JOIN LATERAL (SELECT public.application_blockers(s.id) AS blockers) b
    CROSS JOIN LATERAL (SELECT public.application_next_action(s.stage, 'internal') AS na) n(na)
   ORDER BY
     CASE WHEN _sort = 'priority' THEN
       CASE s.priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 WHEN 'low' THEN 3 ELSE 4 END
       ELSE NULL END NULLS LAST,
     CASE WHEN _sort = 'sla' THEN
       CASE s.sla_state WHEN 'breached' THEN 0 WHEN 'due_soon' THEN 1 WHEN 'on_track' THEN 2 ELSE 3 END
       ELSE NULL END NULLS LAST,
     CASE WHEN _sort = 'submitted_asc' THEN coalesce(s.submitted_at, s.created_at) ELSE NULL END ASC NULLS LAST,
     CASE WHEN _sort = 'submitted_desc' THEN coalesce(s.submitted_at, s.created_at) ELSE NULL END DESC NULLS LAST,
     CASE WHEN _sort = 'applicant' THEN s.applicant_name ELSE NULL END ASC NULLS LAST,
     CASE WHEN _sort = 'app_number' THEN s.application_number ELSE NULL END ASC NULLS LAST,
     s.sla_due_at NULLS LAST, coalesce(s.submitted_at, s.created_at) DESC
   LIMIT greatest(1, least(coalesce(_limit, 25), 200)) OFFSET greatest(0, coalesce(_offset, 0));
$function$
;
CREATE OR REPLACE FUNCTION public.application_work_queue_counts(_regulator_id uuid DEFAULT NULL::uuid, _sector_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH scoped AS (
    SELECT v.* FROM public.v_application_case_state v
     WHERE v.status <> 'draft'
       AND (_regulator_id IS NULL OR v.regulator_id = _regulator_id)
       AND (_sector_id IS NULL OR EXISTS (
             SELECT 1 FROM public.applications a WHERE a.id = v.id
              AND (a.data->>'sector_id' = _sector_id::text
                OR a.data->>'resolved_sector_id' = _sector_id::text)))
  )
  SELECT jsonb_build_object(
    'total_open', count(*) FILTER (WHERE NOT is_terminal),
    'awaiting_triage', count(*) FILTER (WHERE stage = 'SUBMITTED_INTAKE'),
    'sufficiency_review', count(*) FILTER (WHERE stage = 'SUFFICIENCY_REVIEW'),
    'under_review', count(*) FILTER (WHERE stage = 'REGULATORY_REVIEW'),
    'awaiting_applicant', count(*) FILTER (WHERE stage = 'AWAITING_APPLICANT'),
    'decision_ready', count(*) FILTER (WHERE stage = 'DECISION'),
    'authorisation', count(*) FILTER (WHERE stage = 'AUTHORISATION'),
    'breached', count(*) FILTER (WHERE sla_state = 'breached' AND NOT is_terminal),
    'due_soon', count(*) FILTER (WHERE sla_state = 'due_soon' AND NOT is_terminal),
    'unassigned', count(*) FILTER (WHERE owner_user_id IS NULL AND NOT is_terminal),
    'closed', count(*) FILTER (WHERE is_terminal),
    'by_stage', coalesce((SELECT jsonb_object_agg(stage, n) FROM
        (SELECT stage, count(*) n FROM scoped WHERE NOT is_terminal GROUP BY stage) q), '{}'::jsonb),
    'by_priority', coalesce((SELECT jsonb_object_agg(priority, n) FROM
        (SELECT priority, count(*) n FROM scoped WHERE NOT is_terminal GROUP BY priority) q), '{}'::jsonb)
  ) FROM scoped;
$function$
;
CREATE OR REPLACE FUNCTION public.apply_application_guard(_sector_id uuid, _sub_sector_id uuid, _category_id uuid, _service_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_settings jsonb;
  v_allow_reapply boolean;
  v_app_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('action','block','code','UNAUTHORIZED',
      'message','You must be signed in.');
  END IF;

  IF _sector_id IS NULL THEN
    RETURN jsonb_build_object('action','block','code','BAD_REQUEST',
      'message','Sector is required.');
  END IF;

  SELECT value INTO v_settings
  FROM public.site_settings
  WHERE key = 'application_settings'
  LIMIT 1;

  v_allow_reapply := COALESCE((v_settings->>'allow_reapplication')::boolean, true);

  -- 1) When Allow Re-Application is OFF, BLOCK on any existing editable
  --    application (draft / in_progress / resubmission_requested / query_raised)
  --    for the same triple. The user must explicitly resume from "My
  --    Applications" — no silent auto-continue from the New Application flow.
  IF NOT v_allow_reapply THEN
    SELECT a.id INTO v_app_id
    FROM public.applications a
    WHERE a.applicant_id = v_uid
      AND lower(COALESCE(a.status,'')) IN ('draft','in_progress','resubmission_requested','query_raised')
      AND COALESCE(a.data->>'sector_id','') = COALESCE(_sector_id::text,'')
      AND COALESCE(a.data->>'sub_sector_id','') = COALESCE(_sub_sector_id::text,'')
      AND COALESCE(a.data->>'category_id','') = COALESCE(_category_id::text,'')
      AND COALESCE(a.data->>'service_id','') = COALESCE(_service_id::text,'')
    ORDER BY a.updated_at DESC
    LIMIT 1;

    IF v_app_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'action','block',
        'code','DUPLICATE_EDITABLE',
        'application_id', v_app_id,
        'message','You already have an application for this sector, sub-sector, and category/service. Re-application is currently not allowed.'
      );
    END IF;
  END IF;

  -- 2) Block on truly active / submitted applications, or payment-pending
  --    applications that already have a successful payment recorded.
  WITH matching AS (
    SELECT
      a.id,
      lower(COALESCE(a.status, '')) AS app_status,
      a.updated_at,
      COALESCE(pay.has_successful_payment, false) AS has_successful_payment,
      pay.latest_payment_status
    FROM public.applications a
    LEFT JOIN LATERAL (
      SELECT
        bool_or(lower(COALESCE(p.status, '')) IN ('completed','success','paid')) AS has_successful_payment,
        (array_agg(lower(COALESCE(p.status, '')) ORDER BY p.created_at DESC NULLS LAST))[1] AS latest_payment_status
      FROM public.payments p
      WHERE p.application_id = a.id
    ) pay ON true
    WHERE a.applicant_id = v_uid
      AND COALESCE(a.data->>'sector_id','') = COALESCE(_sector_id::text,'')
      AND COALESCE(a.data->>'sub_sector_id','') = COALESCE(_sub_sector_id::text,'')
      AND COALESCE(a.data->>'category_id','') = COALESCE(_category_id::text,'')
      AND COALESCE(a.data->>'service_id','') = COALESCE(_service_id::text,'')
      AND lower(COALESCE(a.status, '')) NOT IN ('draft','in_progress','resubmission_requested','query_raised')
  )
  SELECT m.id INTO v_app_id
  FROM matching m
  WHERE m.app_status IN (
      'submitted','in_review','pending_review','under_review',
      'forwarded','awaiting_approval'
    )
    OR (
      m.app_status IN ('payment_pending','awaiting_payment','pending_payment')
      AND m.has_successful_payment
    )
  ORDER BY m.updated_at DESC
  LIMIT 1;

  IF v_app_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'action','block',
      'code','DUPLICATE_ACTIVE',
      'application_id', v_app_id,
      'message','You already have an active application for this sector, sub-sector, and category. You cannot start a new application until the existing application is finalized.'
    );
  END IF;

  -- 3) Pending-payment redirect when no successful payment has settled yet.
  WITH matching AS (
    SELECT
      a.id,
      lower(COALESCE(a.status, '')) AS app_status,
      a.updated_at,
      COALESCE(pay.has_successful_payment, false) AS has_successful_payment,
      pay.latest_payment_status
    FROM public.applications a
    LEFT JOIN LATERAL (
      SELECT
        bool_or(lower(COALESCE(p.status, '')) IN ('completed','success','paid')) AS has_successful_payment,
        (array_agg(lower(COALESCE(p.status, '')) ORDER BY p.created_at DESC NULLS LAST))[1] AS latest_payment_status
      FROM public.payments p
      WHERE p.application_id = a.id
    ) pay ON true
    WHERE a.applicant_id = v_uid
      AND COALESCE(a.data->>'sector_id','') = COALESCE(_sector_id::text,'')
      AND COALESCE(a.data->>'sub_sector_id','') = COALESCE(_sub_sector_id::text,'')
      AND COALESCE(a.data->>'category_id','') = COALESCE(_category_id::text,'')
      AND COALESCE(a.data->>'service_id','') = COALESCE(_service_id::text,'')
      AND lower(COALESCE(a.status, '')) NOT IN ('draft','in_progress','resubmission_requested','query_raised')
  )
  SELECT m.id INTO v_app_id
  FROM matching m
  WHERE NOT m.has_successful_payment
    AND (
      m.app_status IN ('payment_pending','awaiting_payment','pending_payment')
      OR m.latest_payment_status IN ('pending','processing','initiated')
    )
  ORDER BY m.updated_at DESC
  LIMIT 1;

  IF v_app_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'action','redirect_payment',
      'application_id', v_app_id,
      'message','You have an application with pending payment. Please complete payment to continue.'
    );
  END IF;

  -- 4) Re-application policy: only block approved/rejected duplicates when
  --    the admin "Allow Re-Application" setting is OFF.
  IF NOT v_allow_reapply THEN
    SELECT a.id INTO v_app_id
    FROM public.applications a
    WHERE a.applicant_id = v_uid
      AND COALESCE(a.data->>'sector_id','') = COALESCE(_sector_id::text,'')
      AND COALESCE(a.data->>'sub_sector_id','') = COALESCE(_sub_sector_id::text,'')
      AND COALESCE(a.data->>'category_id','') = COALESCE(_category_id::text,'')
      AND COALESCE(a.data->>'service_id','') = COALESCE(_service_id::text,'')
      AND lower(COALESCE(a.status, '')) = 'approved'
    ORDER BY a.updated_at DESC
    LIMIT 1;

    IF v_app_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'action','block',
        'code','DUPLICATE_APPROVED',
        'application_id', v_app_id,
        'message','You already have an application for this sector, sub-sector, and category/service. Re-application is currently not allowed.'
      );
    END IF;

    SELECT a.id INTO v_app_id
    FROM public.applications a
    WHERE a.applicant_id = v_uid
      AND COALESCE(a.data->>'sector_id','') = COALESCE(_sector_id::text,'')
      AND COALESCE(a.data->>'sub_sector_id','') = COALESCE(_sub_sector_id::text,'')
      AND COALESCE(a.data->>'category_id','') = COALESCE(_category_id::text,'')
      AND COALESCE(a.data->>'service_id','') = COALESCE(_service_id::text,'')
      AND lower(COALESCE(a.status, '')) = 'rejected'
    ORDER BY a.updated_at DESC
    LIMIT 1;

    IF v_app_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'action','block',
        'code','DUPLICATE_REJECTED',
        'application_id', v_app_id,
        'message','You already have an application for this sector, sub-sector, and category/service. Re-application is currently not allowed.'
      );
    END IF;
  END IF;

  RETURN jsonb_build_object('action','allow');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.apply_complaint_type_sla()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sla_days integer;
BEGIN
  IF NEW.complaint_type_id IS NOT NULL THEN
    SELECT sla_days INTO v_sla_days
    FROM public.complaint_types
    WHERE id = NEW.complaint_type_id;
  END IF;

  IF v_sla_days IS NULL THEN
    v_sla_days := 20;
  END IF;

  IF NEW.sla_days IS NULL THEN
    NEW.sla_days := v_sla_days;
  END IF;

  IF NEW.sla_due_at IS NULL THEN
    NEW.sla_due_at := COALESCE(NEW.created_at, now()) + (NEW.sla_days || ' days')::interval;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.apply_entity_change_set(_change_set_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cs record; v_ent record; v_it record; v_applied int := 0; v_skipped int := 0;
  v_eff timestamptz; v_pv jsonb; v_new_id uuid; v_rt uuid; v_party uuid;
BEGIN
  PERFORM public.wb_require('entity_structure','apply');

  SELECT * INTO v_cs FROM public.entity_change_sets WHERE id = _change_set_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Change set not found'; END IF;
  IF v_cs.status = 'APPLIED' THEN
    RETURN jsonb_build_object('success',true,'idempotent',true,'change_set_id',_change_set_id);
  END IF;
  IF v_cs.status <> 'APPROVED' THEN
    RAISE EXCEPTION 'Only approved change sets can be applied (status %)', v_cs.status;
  END IF;

  -- lock canonical entity + concurrency check
  SELECT * INTO v_ent FROM public.licensees WHERE id = v_cs.entity_id FOR UPDATE;
  IF v_ent.structure_version <> v_cs.baseline_version THEN
    RAISE EXCEPTION 'Stale change set: entity structure changed since proposal (baseline %, current %)',
      v_cs.baseline_version, v_ent.structure_version;
  END IF;

  v_eff := COALESCE(v_cs.effective_date::timestamptz, now());

  FOR v_it IN SELECT * FROM public.entity_change_items WHERE change_set_id = _change_set_id ORDER BY sequence LOOP
    v_pv := COALESCE(v_it.proposed_value,'{}'::jsonb);
    v_new_id := NULL;
    BEGIN
      IF v_it.change_type = 'ENTITY_FACT' OR v_it.change_type = 'CLASSIFICATION' THEN
        UPDATE public.entity_facts
           SET valid_to = COALESCE(v_it.effective_from, v_eff), superseded_at = now(),
               approval_status = 'SUPERSEDED'
         WHERE entity_id = v_cs.entity_id AND data_concept_id = v_it.data_concept_id
           AND valid_to IS NULL;
        INSERT INTO public.entity_facts (entity_id, data_concept_id, value_text, value_number, value_date,
          value_boolean, value_uuid, value_json, valid_from, source_submission_id, source_form_version_id,
          source_change_set_id, verified_by, verified_at, approval_status)
        VALUES (v_cs.entity_id, v_it.data_concept_id, v_pv->>'value_text',
          NULLIF(v_pv->>'value_number','')::numeric, NULLIF(v_pv->>'value_date','')::date,
          NULLIF(v_pv->>'value_boolean','')::boolean, NULLIF(v_pv->>'value_uuid','')::uuid, v_pv->'value_json',
          COALESCE(v_it.effective_from, v_eff), v_cs.source_submission_id, v_cs.source_form_version_id,
          _change_set_id, auth.uid(), now(), 'APPROVED')
        RETURNING id INTO v_new_id;

      ELSIF v_it.change_type = 'ORGANIZATION_NAME' THEN
        UPDATE public.organization_names
           SET effective_to = COALESCE(v_it.effective_from, v_eff), is_current = false,
               name_type = CASE WHEN name_type = 'LEGAL' THEN 'FORMER_LEGAL' ELSE name_type END
         WHERE party_id = v_ent.party_id AND is_current
           AND name_type = COALESCE(v_pv->>'name_type','LEGAL');
        INSERT INTO public.organization_names (party_id, name_type, name, effective_from, is_current,
          source_submission_id, source_change_set_id)
        VALUES (v_ent.party_id, COALESCE(v_pv->>'name_type','LEGAL'), v_pv->>'name',
          COALESCE(v_it.effective_from, v_eff), true, v_cs.source_submission_id, _change_set_id)
        RETURNING id INTO v_new_id;
        IF COALESCE(v_pv->>'name_type','LEGAL') = 'LEGAL' THEN
          UPDATE public.organizations SET legal_name = v_pv->>'name', updated_at = now()
           WHERE party_id = v_ent.party_id;
          UPDATE public.licensees SET name = v_pv->>'name', updated_at = now() WHERE id = v_cs.entity_id;
          PERFORM public.create_audit_log(auth.uid(),'entity.name.changed','licensee',v_cs.entity_id::text,
            jsonb_build_object('name', v_ent.name), jsonb_build_object('name', v_pv->>'name'), NULL);
        END IF;

      ELSIF v_it.change_type = 'OWNERSHIP' THEN
        IF v_it.operation = 'CLOSE' THEN
          UPDATE public.ownership_interests
             SET effective_to = COALESCE(v_it.effective_from, v_eff), superseded_at = now(),
                 approval_status = 'SUPERSEDED', source_change_set_id = _change_set_id
           WHERE id = v_it.target_record_id AND effective_to IS NULL
          RETURNING id INTO v_new_id;
        ELSE
          v_party := NULLIF(v_pv->>'owner_party_id','')::uuid;
          IF v_party IS NULL THEN RAISE EXCEPTION 'owner_party_id required for ownership change'; END IF;
          UPDATE public.ownership_interests
             SET effective_to = COALESCE(v_it.effective_from, v_eff), superseded_at = now(),
                 approval_status = 'SUPERSEDED'
           WHERE owned_entity_id = v_cs.entity_id AND owner_party_id = v_party
             AND effective_to IS NULL
             AND COALESCE(ownership_type_id::text,'') = COALESCE(NULLIF(v_pv->>'ownership_type_id','')::text,COALESCE(ownership_type_id::text,''))
             AND COALESCE(share_class_id::text,'') = COALESCE(NULLIF(v_pv->>'share_class_id','')::text,COALESCE(share_class_id::text,''));
          INSERT INTO public.ownership_interests (owner_party_id, owned_entity_id, ownership_type_id,
            share_class_id, shares_held, total_shares, economic_interest_percentage, voting_rights_percentage,
            beneficial_interest_percentage, is_direct, is_controller, is_ubo, control_determination,
            effective_from, approval_status, approved_by, approved_at, source_submission_id,
            source_form_version_id, source_change_set_id)
          VALUES (v_party, v_cs.entity_id, NULLIF(v_pv->>'ownership_type_id','')::uuid,
            NULLIF(v_pv->>'share_class_id','')::uuid, NULLIF(v_pv->>'shares_held','')::numeric,
            NULLIF(v_pv->>'total_shares','')::numeric, NULLIF(v_pv->>'economic_interest_percentage','')::numeric,
            NULLIF(v_pv->>'voting_rights_percentage','')::numeric,
            NULLIF(v_pv->>'beneficial_interest_percentage','')::numeric,
            COALESCE((v_pv->>'is_direct')::boolean,true), COALESCE((v_pv->>'is_controller')::boolean,false),
            COALESCE((v_pv->>'is_ubo')::boolean,false),
            CASE WHEN COALESCE((v_pv->>'is_controller')::boolean,false) OR COALESCE((v_pv->>'is_ubo')::boolean,false)
                 THEN 'VERIFIED' ELSE 'NOT_ASSESSED' END,
            COALESCE(v_it.effective_from, v_eff), 'APPROVED', auth.uid(), now(), v_cs.source_submission_id,
            v_cs.source_form_version_id, _change_set_id)
          RETURNING id INTO v_new_id;
        END IF;
        PERFORM public.create_audit_log(auth.uid(),'entity.ownership.changed','licensee',v_cs.entity_id::text,
          v_it.current_value, v_pv, jsonb_build_object('change_set_id',_change_set_id));

      ELSIF v_it.change_type = 'APPOINTMENT' THEN
        IF v_it.operation = 'CLOSE' THEN
          UPDATE public.entity_appointments
             SET effective_to = COALESCE(v_it.effective_from, v_eff), status='ENDED',
                 superseded_at = now(), source_change_set_id = _change_set_id
           WHERE id = v_it.target_record_id AND effective_to IS NULL
          RETURNING id INTO v_new_id;
        ELSE
          v_party := NULLIF(v_pv->>'person_party_id','')::uuid;
          SELECT id INTO v_rt FROM public.role_types
           WHERE id = NULLIF(v_pv->>'role_type_id','')::uuid
              OR key = NULLIF(v_pv->>'role_type_key','') LIMIT 1;
          IF v_party IS NULL OR v_rt IS NULL THEN
            RAISE EXCEPTION 'person_party_id and a configured role type are required for an appointment';
          END IF;
          INSERT INTO public.entity_appointments (entity_id, person_party_id, role_type_id, appointment_date,
            effective_from, is_executive, status, regulatory_approval_status, fp_individual_id,
            source_submission_id, source_form_version_id, source_change_set_id)
          VALUES (v_cs.entity_id, v_party, v_rt, NULLIF(v_pv->>'appointment_date','')::date,
            COALESCE(v_it.effective_from, v_eff), NULLIF(v_pv->>'is_executive','')::boolean, 'ACTIVE',
            CASE WHEN (SELECT requires_fit_and_proper FROM public.role_types WHERE id = v_rt)
                 THEN 'PENDING' ELSE 'NOT_REQUIRED' END,
            NULLIF(v_pv->>'fp_individual_id','')::uuid, v_cs.source_submission_id,
            v_cs.source_form_version_id, _change_set_id)
          RETURNING id INTO v_new_id;
        END IF;
        PERFORM public.create_audit_log(auth.uid(),'entity.appointment.changed','licensee',v_cs.entity_id::text,
          v_it.current_value, v_pv, jsonb_build_object('change_set_id',_change_set_id));

      ELSIF v_it.change_type = 'RELATIONSHIP' THEN
        IF v_it.operation = 'CLOSE' THEN
          UPDATE public.party_relationships
             SET effective_to = COALESCE(v_it.effective_from, v_eff), status='ENDED',
                 superseded_at = now(), source_change_set_id = _change_set_id
           WHERE id = v_it.target_record_id AND effective_to IS NULL
          RETURNING id INTO v_new_id;
        ELSE
          SELECT id INTO v_rt FROM public.relationship_types
           WHERE id = NULLIF(v_pv->>'relationship_type_id','')::uuid
              OR key = NULLIF(v_pv->>'relationship_type_key','') LIMIT 1;
          IF v_rt IS NULL THEN RAISE EXCEPTION 'A configured relationship type is required'; END IF;
          INSERT INTO public.party_relationships (source_party_id, target_party_id, relationship_type_id,
            entity_id, effective_from, status, notes, source_submission_id, source_form_version_id,
            source_change_set_id)
          VALUES (COALESCE(NULLIF(v_pv->>'source_party_id','')::uuid, v_ent.party_id),
            NULLIF(v_pv->>'target_party_id','')::uuid, v_rt, v_cs.entity_id,
            COALESCE(v_it.effective_from, v_eff), 'ACTIVE', v_pv->>'notes',
            v_cs.source_submission_id, v_cs.source_form_version_id, _change_set_id)
          RETURNING id INTO v_new_id;
        END IF;
        PERFORM public.create_audit_log(auth.uid(),'entity.relationship.changed','licensee',v_cs.entity_id::text,
          v_it.current_value, v_pv, jsonb_build_object('change_set_id',_change_set_id));
      ELSE
        RAISE EXCEPTION 'Unsupported change type %', v_it.change_type;
      END IF;

      UPDATE public.entity_change_items SET apply_status='APPLIED', applied_record_id=v_new_id
       WHERE id = v_it.id;
      v_applied := v_applied + 1;
    EXCEPTION WHEN others THEN
      UPDATE public.entity_change_items SET apply_status='FAILED', apply_error=SQLERRM WHERE id = v_it.id;
      RAISE;
    END;
  END LOOP;

  UPDATE public.licensees SET structure_version = structure_version + 1, updated_at = now()
   WHERE id = v_cs.entity_id;
  UPDATE public.entity_change_sets SET status='APPLIED', applied_by=auth.uid(), applied_at=now(),
    updated_at=now() WHERE id = _change_set_id;

  PERFORM public.create_audit_log(auth.uid(),'entity.change_set.applied','entity_change_set',
    _change_set_id::text, NULL,
    jsonb_build_object('entity_id',v_cs.entity_id,'applied',v_applied,'skipped',v_skipped), NULL);

  RETURN jsonb_build_object('success',true,'change_set_id',_change_set_id,'applied',v_applied);
END $function$
;
CREATE OR REPLACE FUNCTION public.approval_action_notification_delete(_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := public.assert_workflow_config_writer();
  _row public.approval_action_notifications;
BEGIN
  SELECT * INTO _row FROM public.approval_action_notifications WHERE id = _id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('deleted', 0);
  END IF;
  DELETE FROM public.approval_action_notifications WHERE id = _id;

  PERFORM public.log_compliance_audit('DELETE'::compliance_audit_action,
    'approval_action_notifications', _id::text, to_jsonb(_row), NULL,
    'Workflow action notification removed');

  RETURN jsonb_build_object('deleted', 1, 'step_id', _row.step_id);
END $function$
;
CREATE OR REPLACE FUNCTION public.approval_action_notification_save(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := public.assert_workflow_config_writer();
  _id uuid := nullif(_payload->>'id','')::uuid;
  _step_id uuid := nullif(_payload->>'step_id','')::uuid;
  _action_type text := nullif(btrim(coalesce(_payload->>'action_type','')),'');
  _event_key text := nullif(btrim(coalesce(_payload->>'event_key','')),'');
  _recipient_type text := nullif(btrim(coalesce(_payload->>'recipient_type','')),'');
  _cfg jsonb;
  _template_id uuid := nullif(_payload->>'template_id','')::uuid;
  _row public.approval_action_notifications;
BEGIN
  IF _id IS NOT NULL AND _step_id IS NULL THEN
    SELECT step_id INTO _step_id FROM public.approval_action_notifications WHERE id = _id;
  END IF;
  IF _step_id IS NULL OR _action_type IS NULL OR _event_key IS NULL OR _recipient_type IS NULL THEN
    RAISE EXCEPTION 'step_id, action_type, event_key and recipient_type are required'
      USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.approval_steps WHERE id = _step_id) THEN
    RAISE EXCEPTION 'Step not found' USING ERRCODE='P0002';
  END IF;
  IF _action_type NOT IN ('approve','reject','send_back','escalate',
                          'request_resubmission','return_for_correction',
                          'request_more_info','save_comment') THEN
    RAISE EXCEPTION 'Unsupported action_type: %', _action_type USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.approval_step_actions
     WHERE step_id = _step_id AND action_type = _action_type
  ) THEN
    RAISE EXCEPTION 'Configure the "%" action on this step before binding a notification to it', _action_type
      USING ERRCODE='22023';
  END IF;

  _cfg := public.validate_notification_recipient_config(_recipient_type, _payload->'recipient_config');

  IF _template_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.notification_templates WHERE id = _template_id) THEN
      RAISE EXCEPTION 'Selected notification template does not exist' USING ERRCODE='P0002';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.notification_templates WHERE id = _template_id AND is_active) THEN
      RAISE EXCEPTION 'Selected notification template is inactive' USING ERRCODE='22023';
    END IF;
  END IF;

  IF _id IS NOT NULL THEN
    UPDATE public.approval_action_notifications SET
      step_id = _step_id,
      action_type = _action_type,
      event_key = _event_key,
      recipient_type = _recipient_type::workflow_notification_recipient,
      recipient_config = _cfg,
      template_id = _template_id,
      is_enabled = coalesce((_payload->>'is_enabled')::boolean, true),
      updated_at = now()
    WHERE id = _id
    RETURNING * INTO _row;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Notification binding not found' USING ERRCODE='P0002';
    END IF;
  ELSE
    INSERT INTO public.approval_action_notifications
      (step_id, action_type, event_key, recipient_type, recipient_config, template_id, is_enabled)
    VALUES (_step_id, _action_type, _event_key,
            _recipient_type::workflow_notification_recipient, _cfg, _template_id,
            coalesce((_payload->>'is_enabled')::boolean, true))
    RETURNING * INTO _row;
  END IF;

  PERFORM public.log_compliance_audit('UPDATE'::compliance_audit_action,
    'approval_action_notifications', _row.id::text, NULL,
    to_jsonb(_row), 'Workflow action notification saved');

  RETURN to_jsonb(_row);
END $function$
;
CREATE OR REPLACE FUNCTION public.approval_step_action_delete(_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _row public.approval_step_actions;
  _allowed text[];
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;
  IF NOT (public.has_permission(_uid,'workflow_management','edit')
          OR public.has_permission(_uid,'workflow_management','manage_config')
          OR public.has_permission(_uid,'workflow_management','publish')
          OR public.is_super_admin(_uid)) THEN
    RAISE EXCEPTION 'Workflow configuration permission required' USING ERRCODE='42501';
  END IF;

  SELECT * INTO _row FROM public.approval_step_actions WHERE id = _id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('deleted', 0);
  END IF;

  DELETE FROM public.approval_action_notifications
   WHERE step_id = _row.step_id AND action_type = _row.action_type;
  DELETE FROM public.approval_step_actions WHERE id = _id;

  SELECT array_agg(DISTINCT x.action_type)
    INTO _allowed
    FROM public.approval_step_actions x
   WHERE x.step_id = _row.step_id AND x.is_enabled;
  UPDATE public.approval_steps
     SET allowed_actions = to_jsonb(coalesce(_allowed, ARRAY[]::text[]))
   WHERE id = _row.step_id;

  PERFORM public.log_compliance_audit('DELETE'::compliance_audit_action,
    'approval_step_actions', _id::text, to_jsonb(_row), NULL,
    'Workflow step action removed');

  RETURN jsonb_build_object('deleted', 1, 'step_id', _row.step_id);
END $function$
;
CREATE OR REPLACE FUNCTION public.approval_step_action_save(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _step_id uuid := nullif(_payload->>'step_id','')::uuid;
  _action_type text := nullif(_payload->>'action_type','');
  _mode text := coalesce(nullif(_payload->>'next_step_mode',''),'next');
  _next_step_id uuid := nullif(_payload->>'next_step_id','')::uuid;
  _end_state text := nullif(_payload->>'end_state','');
  _row public.approval_step_actions;
  _allowed text[];
  _entity_type text;
  _event_key text;
  _template_id uuid;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;
  IF NOT (public.has_permission(_uid,'workflow_management','edit')
          OR public.has_permission(_uid,'workflow_management','manage_config')
          OR public.has_permission(_uid,'workflow_management','publish')
          OR public.is_super_admin(_uid)) THEN
    RAISE EXCEPTION 'Workflow configuration permission required' USING ERRCODE='42501';
  END IF;

  IF _step_id IS NULL OR _action_type IS NULL THEN
    RAISE EXCEPTION 'step_id and action_type are required' USING ERRCODE='22023';
  END IF;
  IF _action_type NOT IN ('approve','reject','send_back','escalate',
                          'request_resubmission','return_for_correction',
                          'request_more_info','save_comment') THEN
    RAISE EXCEPTION 'Unsupported action_type: %', _action_type USING ERRCODE='22023';
  END IF;
  IF _mode NOT IN ('next','specific_step','previous','return_to_applicant','end_workflow','keep') THEN
    RAISE EXCEPTION 'Unsupported next_step_mode: %', _mode USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.approval_steps WHERE id = _step_id) THEN
    RAISE EXCEPTION 'Step not found' USING ERRCODE='P0002';
  END IF;

  IF _mode = 'specific_step' THEN
    IF _next_step_id IS NULL THEN
      RAISE EXCEPTION 'Choose the target step for "Move to Specific Step".' USING ERRCODE='22023';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.approval_steps t
      JOIN public.approval_steps s ON s.workflow_id = t.workflow_id
      WHERE t.id = _next_step_id AND s.id = _step_id
    ) THEN
      RAISE EXCEPTION 'Target step must belong to the same workflow' USING ERRCODE='22023';
    END IF;
  ELSE
    _next_step_id := NULL;
  END IF;

  IF _mode = 'end_workflow' THEN
    IF _end_state IS NULL OR _end_state NOT IN ('approved','rejected','cancelled') THEN
      RAISE EXCEPTION 'Choose an end state (Approved / Rejected / Cancelled) for "End Workflow".' USING ERRCODE='22023';
    END IF;
  ELSE
    _end_state := NULL;
  END IF;

  INSERT INTO public.approval_step_actions AS a (
    step_id, action_type, label, require_comments, result_status_override,
    next_step_mode, next_step_id, end_state, sort_order, is_enabled,
    require_digital_signature, signature_data_url
  ) VALUES (
    _step_id,
    _action_type,
    nullif(btrim(coalesce(_payload->>'label','')),''),
    coalesce((_payload->>'require_comments')::boolean, false),
    nullif(btrim(coalesce(_payload->>'result_status_override','')),''),
    _mode,
    _next_step_id,
    _end_state,
    coalesce((_payload->>'sort_order')::int, 0),
    coalesce((_payload->>'is_enabled')::boolean, true),
    coalesce((_payload->>'require_digital_signature')::boolean, false),
    CASE WHEN coalesce((_payload->>'require_digital_signature')::boolean,false)
         THEN nullif(_payload->>'signature_data_url','') ELSE NULL END
  )
  ON CONFLICT (step_id, action_type) DO UPDATE SET
    label = EXCLUDED.label,
    require_comments = EXCLUDED.require_comments,
    result_status_override = EXCLUDED.result_status_override,
    next_step_mode = EXCLUDED.next_step_mode,
    next_step_id = EXCLUDED.next_step_id,
    end_state = EXCLUDED.end_state,
    sort_order = EXCLUDED.sort_order,
    is_enabled = EXCLUDED.is_enabled,
    require_digital_signature = EXCLUDED.require_digital_signature,
    signature_data_url = EXCLUDED.signature_data_url,
    updated_at = now()
  RETURNING a.* INTO _row;

  -- Keep the runtime gate (approval_steps.allowed_actions) in lock-step.
  SELECT array_agg(DISTINCT x.action_type)
    INTO _allowed
    FROM public.approval_step_actions x
   WHERE x.step_id = _step_id AND x.is_enabled;
  UPDATE public.approval_steps
     SET allowed_actions = to_jsonb(coalesce(_allowed, ARRAY[]::text[]))
   WHERE id = _step_id;

  -- Seed a default action notification when one is not configured yet.
  IF _row.is_enabled THEN
    SELECT w.entity_type INTO _entity_type
      FROM public.approval_steps s
      JOIN public.approval_workflows w ON w.id = s.workflow_id
     WHERE s.id = _step_id;

    _event_key := CASE
      WHEN _entity_type = 'registration' THEN 'registration_' || _action_type
      WHEN _entity_type = 'return' THEN 'return_' || _action_type
      WHEN _entity_type = 'complaint' THEN 'complaint_' || _action_type
      ELSE 'application_' || _action_type
    END;

    IF NOT EXISTS (
      SELECT 1 FROM public.approval_action_notifications n
       WHERE n.step_id = _step_id AND n.action_type = _action_type AND n.event_key = _event_key
    ) THEN
      SELECT t.id INTO _template_id
        FROM public.notification_templates t
       WHERE t.event_type = _event_key AND t.channel = 'email' AND t.is_active
       ORDER BY t.created_at ASC LIMIT 1;
      IF _template_id IS NOT NULL THEN
        INSERT INTO public.approval_action_notifications
          (step_id, action_type, event_key, recipient_type, recipient_config, template_id, is_enabled)
        VALUES (_step_id, _action_type, _event_key, 'applicant', '{}'::jsonb, _template_id, true)
        ON CONFLICT DO NOTHING;
      END IF;
    END IF;
  END IF;

  PERFORM public.log_compliance_audit('UPDATE'::compliance_audit_action,
    'approval_step_actions', _row.id::text, NULL,
    to_jsonb(_row), 'Workflow step action saved');

  RETURN to_jsonb(_row);
END $function$
;
CREATE OR REPLACE FUNCTION public.approval_step_config_write(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _row jsonb; _n_actions int := 0; _n_entry int := 0; _n_notif int := 0;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;
  IF NOT (public.has_permission(_uid,'workflow_management','edit')
          OR public.has_permission(_uid,'workflow_management','manage_config')
          OR public.has_permission(_uid,'workflow_management','publish')
          OR public.is_super_admin(_uid)) THEN
    RAISE EXCEPTION 'Workflow configuration permission required' USING ERRCODE='42501';
  END IF;

  FOR _row IN SELECT * FROM jsonb_array_elements(coalesce(_payload->'step_actions','[]'::jsonb)) LOOP
    INSERT INTO public.approval_step_actions SELECT * FROM jsonb_populate_record(NULL::public.approval_step_actions, _row);
    _n_actions := _n_actions + 1;
  END LOOP;
  FOR _row IN SELECT * FROM jsonb_array_elements(coalesce(_payload->'entry_notifications','[]'::jsonb)) LOOP
    INSERT INTO public.approval_step_entry_notifications SELECT * FROM jsonb_populate_record(NULL::public.approval_step_entry_notifications, _row);
    _n_entry := _n_entry + 1;
  END LOOP;
  FOR _row IN SELECT * FROM jsonb_array_elements(coalesce(_payload->'action_notifications','[]'::jsonb)) LOOP
    INSERT INTO public.approval_action_notifications SELECT * FROM jsonb_populate_record(NULL::public.approval_action_notifications, _row);
    _n_notif := _n_notif + 1;
  END LOOP;

  PERFORM public.log_compliance_audit('UPDATE'::compliance_audit_action,
    'approval_step_config', nullif(_payload->>'workflow_id','')::text, NULL,
    jsonb_build_object('step_actions',_n_actions,'entry_notifications',_n_entry,'action_notifications',_n_notif),
    'Workflow step configuration written');
  RETURN jsonb_build_object('step_actions',_n_actions,'entry_notifications',_n_entry,'action_notifications',_n_notif);
END; $function$
;
CREATE OR REPLACE FUNCTION public.approval_step_delete(_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := public.assert_workflow_config_writer();
  _row public.approval_steps;
  _wf uuid;
  _i int := 0;
  _s record;
BEGIN
  SELECT * INTO _row FROM public.approval_steps WHERE id = _id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('deleted', 0);
  END IF;
  _wf := _row.workflow_id;

  IF EXISTS (SELECT 1 FROM public.workflow_instances
              WHERE current_step_id = _id AND status = 'active') THEN
    RAISE EXCEPTION 'This step is the current step of an in-flight workflow and cannot be deleted'
      USING ERRCODE='22023';
  END IF;

  DELETE FROM public.approval_action_notifications WHERE step_id = _id;
  DELETE FROM public.approval_step_entry_notifications WHERE step_id = _id;
  DELETE FROM public.approval_step_actions WHERE step_id = _id;
  UPDATE public.approval_step_actions SET next_step_mode = 'next', next_step_id = NULL
   WHERE next_step_id = _id;
  DELETE FROM public.approval_steps WHERE id = _id;

  FOR _s IN SELECT id FROM public.approval_steps WHERE workflow_id = _wf ORDER BY step_order LOOP
    _i := _i + 1;
    UPDATE public.approval_steps SET step_order = _i WHERE id = _s.id;
  END LOOP;

  PERFORM public.log_compliance_audit('DELETE'::compliance_audit_action,
    'approval_steps', _id::text, to_jsonb(_row), NULL, 'Workflow step removed');

  RETURN jsonb_build_object('deleted', 1, 'workflow_id', _wf);
END $function$
;
