CREATE OR REPLACE FUNCTION public.approval_step_entry_notification_save(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := public.assert_workflow_config_writer();
  _id uuid := nullif(_payload->>'id','')::uuid;
  _step_id uuid := nullif(_payload->>'step_id','')::uuid;
  _event_key text := nullif(btrim(coalesce(_payload->>'event_key','')),'');
  _recipient_type text := nullif(btrim(coalesce(_payload->>'recipient_type','')),'');
  _cfg jsonb;
  _template_id uuid := nullif(_payload->>'template_id','')::uuid;
  _row public.approval_step_entry_notifications;
BEGIN
  IF _id IS NOT NULL AND _step_id IS NULL THEN
    SELECT step_id INTO _step_id FROM public.approval_step_entry_notifications WHERE id = _id;
  END IF;
  IF _step_id IS NULL OR _event_key IS NULL OR _recipient_type IS NULL THEN
    RAISE EXCEPTION 'step_id, event_key and recipient_type are required' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.approval_steps WHERE id = _step_id) THEN
    RAISE EXCEPTION 'Step not found' USING ERRCODE='P0002';
  END IF;

  _cfg := public.validate_notification_recipient_config(_recipient_type, _payload->'recipient_config');

  IF _template_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.notification_templates WHERE id = _template_id) THEN
      RAISE EXCEPTION 'Selected notification template does not exist' USING ERRCODE='P0002';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.notification_templates WHERE id = _template_id AND is_active) THEN
      RAISE EXCEPTION 'Selected notification template is inactive' USING ERRCODE='22023';
    END IF;
  END IF;

  IF _id IS NOT NULL THEN
    UPDATE public.approval_step_entry_notifications SET
      step_id = _step_id,
      event_key = _event_key,
      recipient_type = _recipient_type,
      recipient_config = _cfg,
      template_id = _template_id,
      is_enabled = coalesce((_payload->>'is_enabled')::boolean, true),
      updated_at = now()
    WHERE id = _id
    RETURNING * INTO _row;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Notification binding not found' USING ERRCODE='P0002';
    END IF;
  ELSE
    INSERT INTO public.approval_step_entry_notifications
      (step_id, event_key, recipient_type, recipient_config, template_id, is_enabled)
    VALUES (_step_id, _event_key, _recipient_type, _cfg, _template_id,
            coalesce((_payload->>'is_enabled')::boolean, true))
    RETURNING * INTO _row;
  END IF;

  PERFORM public.log_compliance_audit('UPDATE'::compliance_audit_action,
    'approval_step_entry_notifications', _row.id::text, NULL,
    to_jsonb(_row), 'Workflow step entry notification saved');

  RETURN to_jsonb(_row);
END $function$
;
CREATE OR REPLACE FUNCTION public.approval_step_save(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := public.assert_workflow_config_writer();
  _id uuid := nullif(_payload->>'id','')::uuid;
  _workflow_id uuid := nullif(_payload->>'workflow_id','')::uuid;
  _row public.approval_steps;
  _existing public.approval_steps;
BEGIN
  IF _id IS NOT NULL THEN
    SELECT * INTO _existing FROM public.approval_steps WHERE id = _id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Step not found' USING ERRCODE='P0002';
    END IF;

    UPDATE public.approval_steps s SET
      step_order = coalesce((_payload->>'step_order')::int, s.step_order),
      name = coalesce(nullif(btrim(coalesce(_payload->>'name','')),''), s.name),
      description = CASE WHEN _payload ? 'description'
                         THEN nullif(_payload->>'description','') ELSE s.description END,
      approver_role = coalesce(nullif(_payload->>'approver_role','')::app_role, s.approver_role),
      approver_role_id = CASE WHEN _payload ? 'approver_role_id'
                              THEN nullif(_payload->>'approver_role_id','')::uuid
                              ELSE s.approver_role_id END,
      approver_type = coalesce(nullif(_payload->>'approver_type',''), s.approver_type),
      approver_config = coalesce(_payload->'approver_config', s.approver_config),
      step_type = coalesce(nullif(_payload->>'step_type',''), s.step_type),
      condition = CASE WHEN _payload ? 'condition' THEN _payload->'condition' ELSE s.condition END,
      is_required = coalesce((_payload->>'is_required')::boolean, s.is_required),
      sla_hours = CASE WHEN _payload ? 'sla_hours'
                       THEN nullif(_payload->>'sla_hours','')::int ELSE s.sla_hours END,
      sla_warning_threshold_percent = CASE WHEN _payload ? 'sla_warning_threshold_percent'
                       THEN nullif(_payload->>'sla_warning_threshold_percent','')::int
                       ELSE s.sla_warning_threshold_percent END,
      sla_pause_on_rfi = coalesce((_payload->>'sla_pause_on_rfi')::boolean, s.sla_pause_on_rfi),
      sla_warning_template_id = CASE WHEN _payload ? 'sla_warning_template_id'
                       THEN nullif(_payload->>'sla_warning_template_id','')::uuid
                       ELSE s.sla_warning_template_id END,
      sla_breach_template_id = CASE WHEN _payload ? 'sla_breach_template_id'
                       THEN nullif(_payload->>'sla_breach_template_id','')::uuid
                       ELSE s.sla_breach_template_id END,
      escalation_role = CASE WHEN _payload ? 'escalation_role'
                       THEN nullif(_payload->>'escalation_role','') ELSE s.escalation_role END,
      escalation_after_hours = CASE WHEN _payload ? 'escalation_after_hours'
                       THEN nullif(_payload->>'escalation_after_hours','')::int
                       ELSE s.escalation_after_hours END,
      auto_approve_on_timeout = coalesce((_payload->>'auto_approve_on_timeout')::boolean, s.auto_approve_on_timeout),
      step_entry_notifications_enabled = coalesce((_payload->>'step_entry_notifications_enabled')::boolean,
                                                 s.step_entry_notifications_enabled),
      require_digital_signature = coalesce((_payload->>'require_digital_signature')::boolean, s.require_digital_signature),
      is_legal_compliance_stage = coalesce((_payload->>'is_legal_compliance_stage')::boolean, s.is_legal_compliance_stage),
      step_key = CASE WHEN _payload ? 'step_key' THEN nullif(_payload->>'step_key','') ELSE s.step_key END,
      is_start = coalesce((_payload->>'is_start')::boolean, s.is_start),
      is_terminal = coalesce((_payload->>'is_terminal')::boolean, s.is_terminal),
      complainant_visible = coalesce((_payload->>'complainant_visible')::boolean, s.complainant_visible),
      licensee_visible = coalesce((_payload->>'licensee_visible')::boolean, s.licensee_visible),
      assignment_rule = coalesce(_payload->'assignment_rule', s.assignment_rule),
      public_label = CASE WHEN _payload ? 'public_label' THEN nullif(_payload->>'public_label','') ELSE s.public_label END
    WHERE s.id = _id
    RETURNING s.* INTO _row;

    PERFORM public.log_compliance_audit('UPDATE'::compliance_audit_action,
      'approval_steps', _row.id::text, to_jsonb(_existing), to_jsonb(_row),
      'Workflow step updated');
  ELSE
    IF _workflow_id IS NULL THEN
      RAISE EXCEPTION 'workflow_id is required' USING ERRCODE='22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.approval_workflows WHERE id = _workflow_id) THEN
      RAISE EXCEPTION 'Workflow not found' USING ERRCODE='P0002';
    END IF;

    INSERT INTO public.approval_steps (
      workflow_id, step_order, name, description, approver_role, approver_role_id,
      approver_type, approver_config, step_type, condition, is_required,
      sla_hours, sla_warning_threshold_percent, sla_pause_on_rfi,
      escalation_role, escalation_after_hours, auto_approve_on_timeout,
      step_entry_notifications_enabled, require_digital_signature,
      is_legal_compliance_stage, step_key, is_start, is_terminal,
      complainant_visible, licensee_visible, allowed_actions
    ) VALUES (
      _workflow_id,
      coalesce((_payload->>'step_order')::int,
               (SELECT coalesce(max(step_order),0)+1 FROM public.approval_steps WHERE workflow_id=_workflow_id)),
      coalesce(nullif(btrim(coalesce(_payload->>'name','')),''), 'Step'),
      nullif(_payload->>'description',''),
      coalesce(nullif(_payload->>'approver_role','')::app_role, 'admin'::app_role),
      nullif(_payload->>'approver_role_id','')::uuid,
      coalesce(nullif(_payload->>'approver_type',''),'role_based_user'),
      coalesce(_payload->'approver_config','{}'::jsonb),
      coalesce(nullif(_payload->>'step_type',''),'sequential'),
      _payload->'condition',
      coalesce((_payload->>'is_required')::boolean, true),
      coalesce(nullif(_payload->>'sla_hours','')::int, 48),
      coalesce(nullif(_payload->>'sla_warning_threshold_percent','')::int, 80),
      coalesce((_payload->>'sla_pause_on_rfi')::boolean, false),
      nullif(_payload->>'escalation_role',''),
      nullif(_payload->>'escalation_after_hours','')::int,
      coalesce((_payload->>'auto_approve_on_timeout')::boolean, false),
      coalesce((_payload->>'step_entry_notifications_enabled')::boolean, true),
      coalesce((_payload->>'require_digital_signature')::boolean, false),
      coalesce((_payload->>'is_legal_compliance_stage')::boolean, false),
      nullif(_payload->>'step_key',''),
      coalesce((_payload->>'is_start')::boolean, false),
      coalesce((_payload->>'is_terminal')::boolean, false),
      coalesce((_payload->>'complainant_visible')::boolean, true),
      coalesce((_payload->>'licensee_visible')::boolean, true),
      '[]'::jsonb
    )
    RETURNING * INTO _row;

    PERFORM public.log_compliance_audit('CREATE'::compliance_audit_action,
      'approval_steps', _row.id::text, NULL, to_jsonb(_row), 'Workflow step created');
  END IF;

  RETURN to_jsonb(_row);
END $function$
;
CREATE OR REPLACE FUNCTION public.approval_steps_snapshot_insert(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := public.assert_workflow_config_writer();
  _step jsonb;
  _ids jsonb := '[]'::jsonb;
  _new jsonb;
BEGIN
  FOR _step IN SELECT * FROM jsonb_array_elements(coalesce(_payload->'steps','[]'::jsonb)) LOOP
    _new := public.approval_step_save(_step);
    _ids := _ids || jsonb_build_array(jsonb_build_object(
      'id', _new->>'id', 'step_order', (_new->>'step_order')::int));
  END LOOP;
  RETURN jsonb_build_object('steps', _ids);
END $function$
;
CREATE OR REPLACE FUNCTION public.archive_prudential_ratio(_ratio_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row public.prudential_ratios;
BEGIN
  IF NOT public.can_manage_prudential_config(auth.uid()) THEN
    RAISE EXCEPTION 'You do not have permission to manage prudential configuration';
  END IF;
  SELECT * INTO _row FROM public.prudential_ratios WHERE id=_ratio_id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Ratio not found'; END IF;
  UPDATE public.prudential_ratios SET is_active=false, updated_at=now() WHERE id=_ratio_id;
  PERFORM public.log_compliance_audit('UPDATE','prudential_ratios',_ratio_id::text,to_jsonb(_row),NULL,'Ratio archived',NULL,NULL,jsonb_build_object('event','RATIO_ARCHIVED'));
END $function$
;
CREATE OR REPLACE FUNCTION public.archive_prudential_threshold(_threshold_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row public.prudential_thresholds;
BEGIN
  IF NOT public.can_manage_prudential_config(auth.uid()) THEN RAISE EXCEPTION 'Not authorised to manage prudential configuration'; END IF;
  SELECT * INTO _row FROM public.prudential_thresholds WHERE id=_threshold_id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Threshold not found'; END IF;
  PERFORM set_config('app.version_maintenance','on',true);
  UPDATE public.prudential_thresholds SET is_active=false, effective_to=current_date, updated_at=now() WHERE id=_threshold_id;
  UPDATE public.prudential_threshold_versions SET effective_to=current_date WHERE threshold_id=_threshold_id AND effective_to IS NULL;
  PERFORM set_config('app.version_maintenance','off',true);
  PERFORM public.log_compliance_audit('UPDATE','prudential_thresholds',_threshold_id::text,to_jsonb(_row),NULL,'Threshold archived',NULL,NULL,jsonb_build_object('event','THRESHOLD_ARCHIVED'));
END $function$
;
CREATE OR REPLACE FUNCTION public.archive_validation_rule(_rule_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _next integer; _def jsonb;
BEGIN
  IF NOT public.can_manage_returns_config(auth.uid()) THEN
    RAISE EXCEPTION 'You do not have permission to manage returns configuration';
  END IF;
  PERFORM set_config('app.version_maintenance','on',true);
  UPDATE public.return_validation_rules SET is_active = false, updated_at = now() WHERE id = _rule_id;
  UPDATE public.return_validation_rule_versions SET is_current = false WHERE rule_id = _rule_id AND is_current;
  SELECT COALESCE(MAX(version),0)+1 INTO _next FROM public.return_validation_rule_versions WHERE rule_id = _rule_id;
  SELECT to_jsonb(r.*) INTO _def FROM public.return_validation_rules r WHERE r.id = _rule_id;
  INSERT INTO public.return_validation_rule_versions(rule_id, version, definition, published_by, is_current)
    VALUES (_rule_id, _next, _def || jsonb_build_object('archived', true), auth.uid(), true);
  UPDATE public.return_validation_rules SET current_version = _next WHERE id = _rule_id;
  PERFORM public.log_compliance_audit('UPDATE','return_validation_rules', _rule_id::text, NULL, _def,
    'Rule archived', NULL, NULL, jsonb_build_object('event','RULE_ARCHIVED','version',_next));
END $function$
;
CREATE OR REPLACE FUNCTION public.assert_role_management_action(_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  -- service_role and other privileged Postgres roles bypass the check.
  IF current_setting('request.jwt.claims', true) IS NULL
     OR current_setting('request.jwt.claims', true) = '' THEN
    RETURN;
  END IF;
  IF (current_setting('request.jwt.claims', true)::json ->> 'role') = 'service_role' THEN
    RETURN;
  END IF;

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'role_management_action_denied: no authenticated user'
      USING ERRCODE = '42501';
  END IF;

  IF public.is_super_admin(v_uid) THEN
    RETURN;
  END IF;

  IF NOT public.has_permission(v_uid, 'role_management', _action) THEN
    RAISE EXCEPTION 'role_management_action_denied: missing role_management.%', _action
      USING ERRCODE = '42501';
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.assert_role_permission_dependencies()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module text;
  v_action text;
  v_enforced boolean;
  v_deprecated boolean;
  v_view_exists boolean;
BEGIN
  SELECT p.module, lower(p.name), p.enforced, COALESCE(p.deprecated, false)
    INTO v_module, v_action, v_enforced, v_deprecated
  FROM public.permissions p
  WHERE p.id = NEW.permission_id;

  IF v_module IS NULL THEN
    RAISE EXCEPTION 'permission_missing: %', NEW.permission_id USING ERRCODE = '22023';
  END IF;

  IF v_deprecated THEN
    RAISE EXCEPTION 'permission_deprecated: %.% has been deprecated and cannot be assigned',
      v_module, v_action USING ERRCODE = '22023';
  END IF;

  IF NOT v_enforced THEN
    RAISE EXCEPTION 'permission_orphaned: %.% is not enforced anywhere and cannot be assigned',
      v_module, v_action USING ERRCODE = '22023';
  END IF;

  IF public.permission_has_dependency(v_action) THEN
    SELECT EXISTS (
      SELECT 1 FROM public.role_permissions rp
      JOIN public.permissions p ON p.id = rp.permission_id
      WHERE rp.role_id = NEW.role_id
        AND p.module = v_module
        AND lower(p.name) = 'view'
    ) INTO v_view_exists;

    IF NOT v_view_exists THEN
      RAISE EXCEPTION 'dependency_missing: %.% requires %.view on the same role',
        v_module, v_action, v_module USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.assert_role_permission_view_retained()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module text;
  v_action text;
  v_dependents_remaining boolean;
BEGIN
  SELECT p.module, lower(p.name) INTO v_module, v_action
  FROM public.permissions p
  WHERE p.id = OLD.permission_id;

  IF v_action IS DISTINCT FROM 'view' OR v_module IS NULL THEN
    RETURN OLD;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.role_permissions rp
    JOIN public.permissions p ON p.id = rp.permission_id
    WHERE rp.role_id = OLD.role_id
      AND p.module = v_module
      AND lower(p.name) <> 'view'
      AND public.permission_has_dependency(lower(p.name))
      AND rp.permission_id <> OLD.permission_id
  ) INTO v_dependents_remaining;

  IF v_dependents_remaining THEN
    RAISE EXCEPTION 'dependency_still_referenced: cannot remove %.view while dependent actions remain on the role',
      v_module
      USING ERRCODE = '22023';
  END IF;

  RETURN OLD;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.assert_workflow_config_writer()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;
  IF NOT (public.has_permission(_uid,'workflow_management','edit')
          OR public.has_permission(_uid,'workflow_management','manage_config')
          OR public.has_permission(_uid,'workflow_management','publish')
          OR public.is_super_admin(_uid)) THEN
    RAISE EXCEPTION 'Workflow configuration permission required' USING ERRCODE='42501';
  END IF;
  RETURN _uid;
END $function$
;
CREATE OR REPLACE FUNCTION public.assign_appeal_panel(_appeal_id uuid, _panel_id uuid, _hearing_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _hearing_format text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_appeal record;
  v_panel record;
  v_roster jsonb;
  v_voting int;
  v_chair jsonb;
  v_format text;
  v_case jsonb;
  v_snapshot_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF NOT (public.has_permission(v_uid,'license_appeals','assign_panel')
          OR public.has_permission(v_uid,'license_appeals','decide')) THEN
    RETURN jsonb_build_object('error','You are not allowed to refer appeals to a panel','code','FORBIDDEN','http',403);
  END IF;

  SELECT * INTO v_appeal FROM public.license_appeals WHERE id = _appeal_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Appeal not found','code','NOT_FOUND','http',404);
  END IF;
  IF v_appeal.status NOT IN ('submitted','under_review','panel_review') THEN
    RETURN jsonb_build_object('error','This appeal is closed and cannot be referred to a panel','code','INVALID_STATE','http',409);
  END IF;

  SELECT * INTO v_panel FROM public.license_appeal_panels WHERE id = _panel_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Panel not found','code','NOT_FOUND','http',404);
  END IF;
  IF NOT v_panel.is_active
     OR (v_panel.effective_from IS NOT NULL AND v_panel.effective_from > current_date)
     OR (v_panel.effective_to IS NOT NULL AND v_panel.effective_to < current_date) THEN
    RETURN jsonb_build_object('error','That panel is not active today','code','PANEL_INACTIVE','http',409);
  END IF;
  IF v_panel.appeal_scope <> 'licensing' THEN
    RETURN jsonb_build_object('error','That panel does not hear licensing appeals','code','PANEL_SCOPE','http',409);
  END IF;
  IF v_panel.regulator_id IS NOT NULL AND v_appeal.regulator_id IS NOT NULL
     AND v_panel.regulator_id <> v_appeal.regulator_id THEN
    RETURN jsonb_build_object('error','That panel belongs to a different regulator','code','PANEL_REGULATOR','http',409);
  END IF;

  v_case := public.appeal_case_file_status(_appeal_id);
  IF coalesce((v_case->>'ready')::boolean, false) IS NOT TRUE THEN
    RETURN jsonb_build_object('error','The case file is not complete yet','code','CASE_FILE_INCOMPLETE','http',422,'case_file',v_case);
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
            'member_id', m.id,
            'user_id', m.user_id,
            'full_name', coalesce(p.full_name, p.email, 'Member'),
            'email', p.email,
            'member_role', m.member_role,
            'is_chair', m.is_chair,
            'is_voting', m.is_voting,
            'vote_weight', m.vote_weight,
            'regulator_id', m.regulator_id
          ) ORDER BY m.is_chair DESC, m.member_role, coalesce(p.full_name, p.email)), '[]'::jsonb)
    INTO v_roster
    FROM public.license_appeal_panel_members m
    LEFT JOIN public.profiles p ON p.id = m.user_id
   WHERE m.panel_id = _panel_id
     AND m.is_active
     AND (m.effective_from IS NULL OR m.effective_from <= current_date)
     AND (m.effective_to IS NULL OR m.effective_to >= current_date);

  SELECT count(*) INTO v_voting
    FROM jsonb_array_elements(v_roster) r WHERE (r->>'is_voting')::boolean;

  SELECT r INTO v_chair FROM jsonb_array_elements(v_roster) r WHERE (r->>'is_chair')::boolean LIMIT 1;

  IF v_chair IS NULL THEN
    RETURN jsonb_build_object('error','That panel has no active chair','code','PANEL_NO_CHAIR','http',409);
  END IF;
  IF v_voting < v_panel.quorum THEN
    RETURN jsonb_build_object('error',
      format('That panel cannot meet its quorum of %s (only %s active voting members)', v_panel.quorum, v_voting),
      'code','PANEL_QUORUM','http',409);
  END IF;

  v_format := coalesce(nullif(trim(coalesce(_hearing_format,'')),''), v_panel.default_hearing_format);

  INSERT INTO public.license_appeal_panel_snapshots (
    appeal_id, panel_id, panel_name, appeal_scope, quorum, decision_rule,
    hearing_format, member_roster, snapshot_by
  ) VALUES (
    _appeal_id, _panel_id, v_panel.name, v_panel.appeal_scope, v_panel.quorum, v_panel.decision_rule,
    v_format, v_roster, v_uid
  ) RETURNING id INTO v_snapshot_id;

  UPDATE public.license_appeals
     SET panel_id = _panel_id,
         status = 'panel_review',
         hearing_date = coalesce(_hearing_date, hearing_date),
         hearing_format = v_format,
         case_file_ready_at = coalesce(case_file_ready_at, now()),
         updated_at = now()
   WHERE id = _appeal_id;

  INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id, metadata)
  VALUES (
    _appeal_id, 'panel_constituted',
    format('Appeal referred to %s — panel constituted with %s member(s), quorum %s',
           v_panel.name, jsonb_array_length(v_roster), v_panel.quorum),
    v_uid,
    jsonb_build_object('panel_id', _panel_id, 'snapshot_id', v_snapshot_id,
                       'quorum', v_panel.quorum, 'members', jsonb_array_length(v_roster))
  );

  IF _hearing_date IS NOT NULL THEN
    INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id, metadata)
    VALUES (_appeal_id, 'hearing_scheduled',
            format('Hearing scheduled for %s (%s)', to_char(_hearing_date, 'DD Mon YYYY HH24:MI'), v_format),
            v_uid, jsonb_build_object('hearing_date', _hearing_date, 'hearing_format', v_format));
  END IF;

  PERFORM public.notification_enqueue_event(
    'license_appeal.panel_member_assigned', 'license_appeal', _appeal_id,
    jsonb_build_object('appeal_reference', v_appeal.appeal_reference,
                       'panel_name', v_panel.name,
                       'member_user_ids', (SELECT jsonb_agg(r->>'user_id') FROM jsonb_array_elements(v_roster) r)),
    v_snapshot_id::text
  );

  RETURN jsonb_build_object('success', true, 'http', 200,
                            'snapshot_id', v_snapshot_id, 'members', jsonb_array_length(v_roster));
END; $function$
;
CREATE OR REPLACE FUNCTION public.assign_complaint(_id uuid, _investigator uuid DEFAULT NULL::uuid, _team text DEFAULT NULL::text, _reason text DEFAULT NULL::text)
 RETURNS complaints
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  before_row public.complaints%ROWTYPE;
  after_row public.complaints%ROWTYPE;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='28000'; END IF;
  IF NOT public.has_complaint_perm(actor, 'assign') THEN
    RAISE EXCEPTION 'permission denied: complaint_management.assign' USING ERRCODE='42501';
  END IF;
  SELECT * INTO before_row FROM public.complaints WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'complaint not found' USING ERRCODE='P0002'; END IF;

  UPDATE public.complaints
     SET investigator_id = COALESCE(_investigator, investigator_id),
         assigned_team   = COALESCE(_team, assigned_team),
         updated_at      = now()
   WHERE id = _id
  RETURNING * INTO after_row;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value)
  VALUES (actor, 'complaint.assigned', 'complaint', _id,
          jsonb_build_object('investigator_id', before_row.investigator_id, 'assigned_team', before_row.assigned_team),
          jsonb_build_object('investigator_id', after_row.investigator_id, 'assigned_team', after_row.assigned_team, 'reason', _reason));
  RETURN after_row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.assign_complaint(_id uuid, _assignee uuid, _expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_prev uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_complaint_perm(v_uid,'triage') THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;
  PERFORM public._assert_complaint_fresh(_id, _expected_updated_at);
  SELECT investigator_id INTO v_prev FROM public.complaints WHERE id = _id;
  UPDATE public.complaints SET investigator_id = _assignee, updated_at = now() WHERE id = _id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid,'complaint.assigned','complaint',_id, jsonb_build_object('from',v_prev,'to',_assignee));
END; $function$
;
CREATE OR REPLACE FUNCTION public.assign_correspondence(_thread_id uuid, _unit text, _officer text DEFAULT NULL::text, _officer_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_actor text;
BEGIN
  IF NOT public.is_internal_staff(v_user) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  v_actor := public.correspondence_actor_label(v_user);
  UPDATE public.correspondence_threads
  SET assigned_unit = _unit, assigned_officer = _officer, assigned_officer_id = _officer_id,
      status = CASE WHEN status IN ('received','classified') THEN 'assigned' ELSE status END
  WHERE id = _thread_id;
  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail)
  VALUES (_thread_id, v_user, v_actor, 'Staff', 'Assigned', _unit || COALESCE(' -> ' || _officer, ''));
END; $function$
;
CREATE OR REPLACE FUNCTION public.assign_primary_user(_entity_id uuid, _user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_now timestamptz := now();
  v_existing record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF NOT (public.has_role(v_uid,'super_admin'::app_role) OR public.has_role(v_uid,'admin'::app_role)) THEN
    RETURN jsonb_build_object('error','Admin only','code','FORBIDDEN','http',403);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.licensees WHERE id = _entity_id) THEN
    RETURN jsonb_build_object('error','Entity not found','code','ENTITY_NOT_FOUND','http',404);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _user_id) THEN
    RETURN jsonb_build_object('error','User not found','code','USER_NOT_FOUND','http',404);
  END IF;

  SELECT * INTO v_existing FROM public.entity_user_access
   WHERE entity_id = _entity_id AND access_type='primary_user' AND is_active=true
   FOR UPDATE;

  IF FOUND AND v_existing.user_id = _user_id THEN
    RETURN jsonb_build_object('error','This user is already the active Primary User for this entity.',
      'code','ALREADY_PRIMARY','http',409);
  END IF;

  IF FOUND THEN
    UPDATE public.entity_user_access
       SET is_active = false, end_date = v_now
     WHERE id = v_existing.id;

    UPDATE public.profiles
       SET role = 'applicant',
           user_type = 'applicant',
           updated_at = v_now
     WHERE id = v_existing.user_id
       AND licensee_id = _entity_id
       AND role = 'licensee_primary';
  END IF;

  INSERT INTO public.entity_user_access (user_id, entity_id, access_type, is_active, start_date, created_by)
  VALUES (_user_id, _entity_id, 'primary_user', true, v_now, v_uid);

  UPDATE public.profiles
     SET role = 'licensee_primary',
         user_type = 'primary',
         licensee_id = _entity_id,
         updated_at = v_now
   WHERE id = _user_id;

  PERFORM public.create_audit_log(
    v_uid, 'entity_primary_user_assigned', 'licensee', _entity_id::text, NULL,
    jsonb_build_object('new_primary_user_id', _user_id,
                       'previous_primary_user_id', v_existing.user_id),
    NULL
  );

  RETURN jsonb_build_object('success', true, 'http', 200,
    'entity_id', _entity_id, 'user_id', _user_id,
    'previous_user_id', v_existing.user_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.audit_captcha_configuration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'captcha_configuration_created';
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'captcha_configuration_deleted';
  ELSIF COALESCE(OLD.is_active,false) IS DISTINCT FROM COALESCE(NEW.is_active,false) THEN
    v_action := CASE WHEN NEW.is_active THEN 'captcha_configuration_activated'
                     ELSE 'captcha_configuration_deactivated' END;
  ELSE
    v_action := 'captcha_configuration_updated';
  END IF;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value)
  VALUES (
    auth.uid(),
    v_action,
    'captcha_configuration',
    COALESCE(NEW.id, OLD.id),
    CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE jsonb_build_object(
      'name', OLD.name, 'provider', OLD.provider, 'environment', OLD.environment,
      'is_active', OLD.is_active, 'score_threshold', OLD.score_threshold) END,
    CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE jsonb_build_object(
      'name', NEW.name, 'provider', NEW.provider, 'environment', NEW.environment,
      'is_active', NEW.is_active, 'score_threshold', NEW.score_threshold) END
  );

  RETURN COALESCE(NEW, OLD);
END;
$function$
;
