$function$
;
CREATE OR REPLACE FUNCTION public.auto_seed_supervisory_plan()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_license   RECORD;
  v_licensee  RECORD;
  v_template  RECORD;
  v_plan_id   UUID;
  v_exists    BOOLEAN;
BEGIN
  -- Only fire on transition into approved
  IF NEW.status <> 'approved' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'approved' THEN RETURN NEW; END IF;

  -- Find the license issued for this application
  SELECT id, holder_id, sector_id
    INTO v_license
    FROM public.licenses
   WHERE application_id = NEW.id
   ORDER BY issued_at DESC
   LIMIT 1;

  IF v_license IS NULL THEN
    -- License not yet materialised — bail; trigger will fire again from license insert if needed
    RETURN NEW;
  END IF;

  -- Find the licensee entity for this license
  SELECT id, sector_id
    INTO v_licensee
    FROM public.licensees
   WHERE license_id = v_license.id
   LIMIT 1;

  IF v_licensee IS NULL THEN RETURN NEW; END IF;

  -- Idempotent: skip if a plan already exists for this entity from this license
  SELECT EXISTS (
    SELECT 1 FROM public.supervisory_plans
     WHERE entity_id = v_licensee.id
       AND license_id = v_license.id
  ) INTO v_exists;
  IF v_exists THEN RETURN NEW; END IF;

  -- Resolve template: sector match > global (sector_id NULL) > any active
  SELECT id INTO v_template
    FROM public.supervisory_plan_templates
   WHERE is_active
     AND (sector_id = v_licensee.sector_id OR sector_id = v_license.sector_id)
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_template IS NULL THEN
    SELECT id INTO v_template
      FROM public.supervisory_plan_templates
     WHERE is_active AND sector_id IS NULL
     ORDER BY created_at DESC
     LIMIT 1;
  END IF;

  -- Create the plan (even without a template we still create an empty plan)
  INSERT INTO public.supervisory_plans (entity_id, license_id, created_from, status, notes)
  VALUES (
    v_licensee.id,
    v_license.id,
    'auto_on_approval',
    'active',
    'Auto-created on application approval'
  )
  RETURNING id INTO v_plan_id;

  -- Seed actions from template (if any)
  IF v_template.id IS NOT NULL THEN
    INSERT INTO public.supervisory_plan_actions (plan_id, title, description, owner_role, due_date, status, source)
    SELECT
      v_plan_id,
      a.title,
      a.description,
      a.owner_role,
      (CURRENT_DATE + (a.offset_days || ' days')::interval)::date,
      'pending',
      'template'
    FROM public.supervisory_plan_template_actions a
    WHERE a.template_id = v_template.id
    ORDER BY a.sort_order;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.auto_seed_supervisory_plan_from_license()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_licensee RECORD;
  v_template RECORD;
  v_plan_id  UUID;
  v_exists   BOOLEAN;
  v_app_status TEXT;
BEGIN
  IF NEW.application_id IS NULL THEN RETURN NEW; END IF;

  SELECT status INTO v_app_status FROM public.applications WHERE id = NEW.application_id;
  IF v_app_status IS DISTINCT FROM 'approved' THEN RETURN NEW; END IF;

  SELECT id, sector_id INTO v_licensee
    FROM public.licensees WHERE license_id = NEW.id LIMIT 1;
  IF v_licensee IS NULL THEN RETURN NEW; END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.supervisory_plans
     WHERE entity_id = v_licensee.id AND license_id = NEW.id
  ) INTO v_exists;
  IF v_exists THEN RETURN NEW; END IF;

  SELECT id INTO v_template
    FROM public.supervisory_plan_templates
   WHERE is_active
     AND (sector_id = v_licensee.sector_id OR sector_id = NEW.sector_id)
   ORDER BY created_at DESC LIMIT 1;

  IF v_template IS NULL THEN
    SELECT id INTO v_template FROM public.supervisory_plan_templates
     WHERE is_active AND sector_id IS NULL ORDER BY created_at DESC LIMIT 1;
  END IF;

  INSERT INTO public.supervisory_plans (entity_id, license_id, created_from, status, notes)
  VALUES (v_licensee.id, NEW.id, 'auto_on_approval', 'active', 'Auto-created on license issuance')
  RETURNING id INTO v_plan_id;

  IF v_template.id IS NOT NULL THEN
    INSERT INTO public.supervisory_plan_actions (plan_id, title, description, owner_role, due_date, status, source)
    SELECT v_plan_id, a.title, a.description, a.owner_role,
           (CURRENT_DATE + (a.offset_days || ' days')::interval)::date,
           'pending', 'template'
      FROM public.supervisory_plan_template_actions a
     WHERE a.template_id = v_template.id
     ORDER BY a.sort_order;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.bootstrap_supervisory_profile(_license_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entity_id uuid;
  v_rating_id uuid;
  v_plan_id uuid;
  v_app_no text;
BEGIN
  SELECT lic.id, COALESCE(a.application_number, '')
    INTO v_entity_id, v_app_no
  FROM public.licensees lic
  LEFT JOIN public.licenses l ON l.id = lic.license_id
  LEFT JOIN public.applications a ON a.id = l.application_id
  WHERE lic.license_id = _license_id
  LIMIT 1;

  IF v_entity_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Skip if a plan already exists
  IF EXISTS (SELECT 1 FROM public.supervisory_plans WHERE entity_id = v_entity_id) THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.risk_ratings (entity_id, overall_rating, risk_score, risk_factors, notes)
  VALUES (
    v_entity_id, 'medium', 50,
    '[{"factor":"new_licensee","weight":1.0}]'::jsonb,
    'Auto-generated from licensing findings' || CASE WHEN v_app_no <> '' THEN ' (application ' || v_app_no || ')' ELSE '' END
  )
  RETURNING id INTO v_rating_id;

  INSERT INTO public.supervisory_plans (entity_id, license_id, risk_rating_id, created_from, status, notes)
  VALUES (v_entity_id, _license_id, v_rating_id, 'licensing', 'active',
    'Initial supervisory plan auto-generated upon licensing.')
  RETURNING id INTO v_plan_id;

  INSERT INTO public.supervisory_plan_actions (plan_id, title, description, owner_role, due_date, source)
  VALUES
    (v_plan_id, 'Initial onboarding meeting', 'Conduct kickoff meeting with newly licensed entity to review obligations.', 'supervisor', (CURRENT_DATE + INTERVAL '30 days')::date, 'auto'),
    (v_plan_id, 'Submit baseline compliance return', 'Entity must file its first baseline compliance return.', 'licensee', (CURRENT_DATE + INTERVAL '60 days')::date, 'auto'),
    (v_plan_id, 'First desk / on-site review', 'Officer reviews initial filings and onboarding documentation.', 'supervisor', (CURRENT_DATE + INTERVAL '90 days')::date, 'auto'),
    (v_plan_id, 'Risk reassessment', 'Re-evaluate baseline risk rating after first quarter of operation.', 'supervisor', (CURRENT_DATE + INTERVAL '180 days')::date, 'auto');

  RETURN v_plan_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.branch_form_version(_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_src record; v_new record; v_next int;
BEGIN
  PERFORM public.wb_require('form_management','edit');
  SELECT * INTO v_src FROM public.form_versions WHERE id = _version_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Form version not found'; END IF;
  SELECT COALESCE(MAX(version),0) + 1 INTO v_next FROM public.form_versions WHERE template_id = v_src.template_id;
  INSERT INTO public.form_versions (template_id, version, status, schema_snapshot, created_by, branched_from_version_id)
  VALUES (v_src.template_id, v_next, 'draft', v_src.schema_snapshot, auth.uid(), _version_id)
  RETURNING * INTO v_new;

  INSERT INTO public.form_fields (version_id, form_field_definition_id, section_id, section_title, section_order,
    section_description, section_is_repeatable, field_type, label, field_name, required, placeholder, help_text,
    default_value, options, validation, sort_order, content, table_columns, calculated_expression, line_code)
  SELECT v_new.id, form_field_definition_id, section_id, section_title, section_order,
    section_description, section_is_repeatable, field_type, label, field_name, required, placeholder, help_text,
    default_value, options, validation, sort_order, content, table_columns, calculated_expression, line_code
    FROM public.form_fields WHERE version_id = _version_id;

  RETURN jsonb_build_object('success',true,'version_id',v_new.id,'version',v_new.version);
END $function$
;
CREATE OR REPLACE FUNCTION public.build_workflow_snapshot(_workflow_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'version', 2,
    'steps', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'local_id', s.id::text,
            'step_order', s.step_order,
            'name', s.name,
            'description', s.description,
            'approver_role', s.approver_role::text,
            'approver_role_id', s.approver_role_id,
            'approver_type', s.approver_type,
            'approver_config', s.approver_config,
            'sla_hours', s.sla_hours,
            'auto_approve_on_timeout', s.auto_approve_on_timeout,
            'allowed_actions', s.allowed_actions,
            'actions', COALESCE((
              SELECT jsonb_agg(jsonb_build_object(
                'action_type', a.action_type,
                'label', a.label,
                'require_comments', a.require_comments,
                'result_status_override', a.result_status_override,
                'next_step_mode', a.next_step_mode,
                'next_step_local_id', a.next_step_id::text,
                'end_state', a.end_state,
                'sort_order', a.sort_order,
                'is_enabled', a.is_enabled,
                'require_digital_signature', a.require_digital_signature,
                'signature_data_url', a.signature_data_url
              ) ORDER BY a.sort_order)
              FROM public.approval_step_actions a WHERE a.step_id = s.id
            ), '[]'::jsonb),
            'entry_notifications', COALESCE((
              SELECT jsonb_agg(jsonb_build_object(
                'event_key', n.event_key,
                'recipient_type', n.recipient_type,
                'recipient_config', n.recipient_config,
                'template_id', n.template_id,
                'is_enabled', n.is_enabled
              ))
              FROM public.approval_step_entry_notifications n WHERE n.step_id = s.id
            ), '[]'::jsonb),
            'action_notifications', COALESCE((
              SELECT jsonb_agg(jsonb_build_object(
                'action_type', n.action_type,
                'event_key', n.event_key,
                'recipient_type', n.recipient_type::text,
                'recipient_config', n.recipient_config,
                'template_id', n.template_id,
                'is_enabled', n.is_enabled
              ))
              FROM public.approval_action_notifications n WHERE n.step_id = s.id
            ), '[]'::jsonb)
          ) ORDER BY s.step_order
        )
        FROM public.approval_steps s WHERE s.workflow_id = _workflow_id
      ),
      '[]'::jsonb
    )
  )
$function$
;
CREATE OR REPLACE FUNCTION public.can_access_review_entity(_user_id uuid, _entity_type text, _entity_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _step uuid;
  _ok boolean;
BEGIN
  IF _user_id IS NULL OR _entity_id IS NULL THEN
    RETURN false;
  END IF;

  IF public.is_collab_admin(_user_id) THEN
    RETURN true;
  END IF;

  IF _entity_type = 'application' THEN
    SELECT true INTO _ok FROM public.applications WHERE id = _entity_id AND applicant_id = _user_id;
    IF _ok THEN RETURN true; END IF;
  ELSIF _entity_type = 'registration' THEN
    SELECT true INTO _ok FROM public.registrations WHERE id = _entity_id AND user_id = _user_id;
    IF _ok THEN RETURN true; END IF;
  ELSIF _entity_type = 'complaint' THEN
    SELECT true INTO _ok FROM public.complaints WHERE id = _entity_id AND complainant_id = _user_id;
    IF _ok THEN RETURN true; END IF;
  ELSIF _entity_type = 'return' THEN
    SELECT true INTO _ok FROM public.returns_filed r
      WHERE r.id = _entity_id
        AND (r.created_by = _user_id
             OR EXISTS (SELECT 1 FROM public.entity_user_access eua
                         WHERE eua.entity_id = r.entity_id AND eua.user_id = _user_id));
    IF _ok THEN RETURN true; END IF;
  END IF;

  SELECT ctx.step_id INTO _step
    FROM public.current_workflow_step_for(_entity_type, _entity_id) ctx
   LIMIT 1;

  IF _step IS NULL THEN
    RETURN false;
  END IF;

  SELECT true INTO _ok
    FROM public.review_step_permissions rsp
    JOIN public.user_dynamic_roles udr ON udr.role_id = rsp.role_id
   WHERE rsp.step_id = _step
     AND udr.user_id = _user_id
     AND rsp.enabled = true
     AND rsp.can_view = true
   LIMIT 1;

  RETURN COALESCE(_ok, false);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.can_act_on_approval(_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.is_super_admin(_user)
      OR public.has_permission(_user,'workflow_management','workflow_action')
      OR public.has_permission(_user,'workflow_management','manage_config');
$function$
;
