CREATE OR REPLACE FUNCTION public.can_act_on_examination(_user_id uuid, _action text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.is_super_admin(_user_id)
