CREATE OR REPLACE FUNCTION public.can_mutate_compliance_return(_user uuid, _return_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _user IS NULL OR _return_id IS NULL THEN false
    WHEN public.is_super_admin(_user) THEN true
    WHEN public.has_permission(_user, 'compliance_management', 'edit') THEN true
    WHEN public.has_permission(_user, 'compliance_management', 'workflow_action') THEN true
    WHEN EXISTS (
      SELECT 1 FROM public.compliance_returns r
      WHERE r.id = _return_id
        AND r.submitter_id = _user
        AND r.status = ANY (ARRAY['draft','pending','resubmission_requested','rejected'])
    ) THEN true
    WHEN public.has_external_role(_user)
         AND public.external_can_access_compliance_return(_user, _return_id, 'can_submit_returns')
      THEN true
    ELSE false
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.can_mutate_license(_user uuid, _license_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE h_id uuid; s_id uuid;
BEGIN
  IF _user IS NULL OR _license_id IS NULL THEN RETURN false; END IF;
  IF public.is_super_admin(_user) THEN RETURN true; END IF;
  SELECT holder_id, sector_id INTO h_id, s_id FROM public.licenses WHERE id = _license_id;
  RETURN public.has_scoped_permission(_user, 'license_management', 'edit', h_id, s_id, NULL)
      OR public.has_scoped_permission(_user, 'license_management', 'workflow_action', h_id, s_id, NULL);
END;
$function$
;
