 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s_id uuid;
BEGIN
  IF _user IS NULL OR _licensee_id IS NULL THEN RETURN false; END IF;
  IF public.is_super_admin(_user) THEN RETURN true; END IF;
  SELECT sector_id INTO s_id FROM public.licensees WHERE id = _licensee_id;
  RETURN public.has_scoped_permission(_user, 'licensee_management', 'edit', _licensee_id, s_id, NULL);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.can_mutate_return_filed(_user_id uuid, _return_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.returns_filed%ROWTYPE; editable_statuses text[] := ARRAY['TEMP','WIP','TBR'];
BEGIN
  IF _user_id IS NULL OR _return_id IS NULL THEN RETURN false; END IF;
  IF public.is_super_admin(_user_id) THEN RETURN true; END IF;
  IF public.has_permission(_user_id, 'returns_management', 'edit') THEN RETURN true; END IF;
  SELECT * INTO r FROM public.returns_filed WHERE id = _return_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF (r.workflow_status::text = ANY (editable_statuses)) THEN
    IF r.created_by = _user_id THEN RETURN true; END IF;
    IF EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = _user_id AND p.licensee_id IS NOT NULL
               AND (p.licensee_id = r.entity_id OR p.licensee_id = r.on_behalf_of_licensee_id))
      THEN RETURN true; END IF;
    IF EXISTS (SELECT 1 FROM public.ppoc_mapped_licensee_ids(_user_id) AS m(licensee_id)
               WHERE m.licensee_id = r.entity_id OR m.licensee_id = r.on_behalf_of_licensee_id)
      THEN RETURN true; END IF;
    IF public.external_can_access_return_filed(_user_id, r.id, 'can_submit_returns')
      THEN RETURN true; END IF;
  END IF;
  RETURN false;
END $function$
;
CREATE OR REPLACE FUNCTION public.can_read_application(_user uuid, _application_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _user IS NULL OR _application_id IS NULL THEN false
    WHEN public.is_super_admin(_user) THEN true
    WHEN public.has_permission(_user, 'application_management','view_all_entities') THEN true
    ELSE EXISTS (
      SELECT 1 FROM public.applications a
       WHERE a.id = _application_id
         AND (
           a.applicant_id = _user
           OR (public.has_permission(_user, 'application_management','view')
               AND NOT public.has_external_role(_user))
           OR (public.user_licensee_id(_user) IS NOT NULL
               AND a.id IN (SELECT public.application_ids_for_licensee(public.user_licensee_id(_user))))
           OR a.applicant_id IN (
             SELECT p.id FROM public.profiles p
              WHERE p.licensee_id IN (SELECT public.ppoc_mapped_licensee_ids(_user))
           )
           OR public.external_can_access_application(_user, a.id, 'can_view'::text)
         )
    )
  END
$function$
;
