CREATE OR REPLACE FUNCTION public.can_read_license(_user uuid, _license_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  h_id uuid;
  s_id uuid;
  app_id uuid;
  lic_entity uuid;
BEGIN
  IF _user IS NULL OR _license_id IS NULL THEN RETURN false; END IF;
  IF public.is_super_admin(_user) THEN RETURN true; END IF;

  SELECT holder_id, sector_id, application_id
    INTO h_id, s_id, app_id
  FROM public.licenses WHERE id = _license_id;

  -- Supervisory / internal scoped access (unchanged)
  IF public.has_scoped_permission(_user, 'license_management', 'view', h_id, s_id, NULL) THEN RETURN true; END IF;

  -- Holder side: the licence holder account itself
  IF h_id IS NOT NULL AND h_id = _user THEN RETURN true; END IF;

  -- Holder side: applicant on the originating application
  IF app_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.applications a
    WHERE a.id = app_id AND a.applicant_id = _user
  ) THEN RETURN true; END IF;

  -- Entity linked to this licence
  SELECT id INTO lic_entity FROM public.licensees WHERE license_id = _license_id LIMIT 1;

  IF lic_entity IS NOT NULL THEN
    IF public.can_read_licensee(_user, lic_entity) THEN RETURN true; END IF;
    IF EXISTS (
      SELECT 1 FROM public.entity_user_access ea
      WHERE ea.user_id = _user
        AND ea.entity_id = lic_entity
        AND ea.is_active = true
        AND (ea.end_date IS NULL OR ea.end_date >= CURRENT_DATE)
    ) THEN RETURN true; END IF;
  END IF;

  -- Legacy path: holder_id treated as a licensee id (older data)
  IF h_id IS NOT NULL AND public.can_read_licensee(_user, h_id) THEN RETURN true; END IF;

  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.can_read_license_appeal(_user_id uuid, _appeal_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.license_appeals la
    JOIN public.applications a ON a.id = la.application_id
    WHERE la.id = _appeal_id
      AND (
        la.filed_by = _user_id
        OR a.applicant_id = _user_id
        OR public.has_permission(_user_id, 'license_appeals', 'view')
        OR public.is_appeal_panel_member(_user_id, la.id)
      )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.can_read_licensee(_user uuid, _licensee_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s_id uuid;
BEGIN
  IF _user IS NULL OR _licensee_id IS NULL THEN RETURN false; END IF;
  IF public.is_super_admin(_user) THEN RETURN true; END IF;

  SELECT sector_id INTO s_id FROM public.licensees WHERE id = _licensee_id;

  IF public.has_permission(_user, 'licensee_management', 'view_all_entities')
     OR public.has_permission(_user, 'license_management', 'view_all_entities')
  THEN
    RETURN true;
  END IF;

  IF NOT public.has_external_role(_user)
     AND (
       public.has_scoped_permission(_user, 'licensee_management', 'view', _licensee_id, s_id, NULL)
       OR public.has_scoped_permission(_user, 'license_management', 'view', _licensee_id, s_id, NULL)
     )
  THEN
    RETURN true;
  END IF;

  IF EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = _user AND p.licensee_id = _licensee_id) THEN RETURN true; END IF;
  IF EXISTS (SELECT 1 FROM public.ppoc_entity_mappings m
             WHERE m.ppoc_user_id = _user AND m.licensee_id = _licensee_id AND m.is_active = true) THEN RETURN true; END IF;
  IF EXISTS (SELECT 1 FROM public.licensees lc WHERE lc.id = _licensee_id
             AND (lc.lead_regulator_id = _user OR lc.regulator_officer_id = _user
                  OR lc.alternate_regulator_id = _user OR lc.assigned_supervisor_id = _user)) THEN RETURN true; END IF;
  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.can_read_payment_oversight(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.is_super_admin(_user_id)
      OR public.has_permission(_user_id, 'prudential_supervision', 'view')
      OR public.has_permission(_user_id, 'prudential_supervision', 'view_all_entities')
      OR public.has_permission(_user_id, 'prudential_supervision', 'manage_payment_oversight');
$function$
;
CREATE OR REPLACE FUNCTION public.can_read_prudential_entity(_user uuid, _entity_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.is_super_admin(_user)
      OR public.has_permission(_user,'prudential_supervision','view_all_entities')
      OR (
        public.has_permission(_user,'prudential_supervision','view')
        AND (
          _entity_id IS NULL
          OR public.user_has_entity_assignment(_user, _entity_id)
          OR EXISTS (SELECT 1 FROM public.entity_user_access eua WHERE eua.entity_id=_entity_id AND eua.user_id=_user)
        )
      );
$function$
;
CREATE OR REPLACE FUNCTION public.can_read_return_filed(_user_id uuid, _return_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.returns_filed%ROWTYPE;
BEGIN
  IF _user_id IS NULL OR _return_id IS NULL THEN RETURN false; END IF;
  IF public.is_super_admin(_user_id) THEN RETURN true; END IF;
  IF public.has_permission(_user_id, 'returns_management', 'view_all_entities') THEN RETURN true; END IF;
  SELECT * INTO r FROM public.returns_filed WHERE id = _return_id;
  IF NOT FOUND THEN RETURN false; END IF;
  RETURN public.can_read_return_filed_row(_user_id, r.entity_id, r.on_behalf_of_licensee_id, r.created_by, r.id);
END $function$
;
CREATE OR REPLACE FUNCTION public.can_read_return_filed_row(_user_id uuid, _entity_id uuid, _on_behalf_of_licensee_id uuid, _created_by uuid, _return_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s_id uuid; lic uuid := COALESCE(_entity_id, _on_behalf_of_licensee_id);
BEGIN
  IF _user_id IS NULL THEN RETURN false; END IF;
  IF public.is_super_admin(_user_id) THEN RETURN true; END IF;
  IF public.has_permission(_user_id, 'returns_management', 'view_all_entities') THEN RETURN true; END IF;
  IF _created_by = _user_id THEN RETURN true; END IF;
  IF lic IS NOT NULL THEN
    SELECT sector_id INTO s_id FROM public.licensees WHERE id = lic;
    IF public.has_scoped_permission(_user_id, 'returns_management', 'view', lic, s_id, _created_by) THEN RETURN true; END IF;
  END IF;
  IF public.user_has_entity_assignment(_user_id, _entity_id)
     OR public.user_has_entity_assignment(_user_id, _on_behalf_of_licensee_id) THEN RETURN true; END IF;
  IF EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = _user_id AND p.licensee_id IS NOT NULL
             AND (p.licensee_id = _entity_id OR p.licensee_id = _on_behalf_of_licensee_id)) THEN RETURN true; END IF;
  IF EXISTS (SELECT 1 FROM public.entity_user_access eua
             WHERE eua.user_id = _user_id AND eua.is_active = true
               AND (eua.end_date IS NULL OR eua.end_date > now())
               AND eua.entity_id = ANY (ARRAY[_entity_id, _on_behalf_of_licensee_id])) THEN RETURN true; END IF;
  IF EXISTS (SELECT 1 FROM public.ppoc_mapped_licensee_ids(_user_id) AS m(licensee_id)
             WHERE m.licensee_id = _entity_id OR m.licensee_id = _on_behalf_of_licensee_id) THEN RETURN true; END IF;
  IF _return_id IS NOT NULL AND (
       public.external_can_access_return_filed(_user_id, _return_id, 'can_view_status')
    OR public.external_can_access_return_filed(_user_id, _return_id, 'can_submit_returns')
  ) THEN RETURN true; END IF;
  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.can_read_workflow_instance(_user uuid, _entity_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.is_super_admin(_user)
      OR public.has_permission(_user,'workflow_management','view')
      OR public.has_permission(_user,'workflow_management','view_all')
      OR EXISTS (SELECT 1 FROM public.applications a WHERE a.id=_entity_id AND a.applicant_id=_user);
$function$
;
CREATE OR REPLACE FUNCTION public.can_review_action(_step_id uuid, _role_id uuid, _action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.review_step_permissions%ROWTYPE;
BEGIN
  IF _step_id IS NULL OR _role_id IS NULL THEN RETURN false; END IF;
  SELECT * INTO r FROM public.review_step_permissions WHERE step_id = _step_id AND role_id = _role_id;
  IF NOT FOUND OR NOT r.enabled THEN RETURN false; END IF;
  RETURN CASE _action
    WHEN 'view' THEN r.can_view
    WHEN 'comment' THEN r.can_comment
    WHEN 'reply' THEN r.can_reply
    WHEN 'suggest' THEN r.can_suggest
    WHEN 'accept' THEN r.can_accept
    WHEN 'reject' THEN r.can_reject
    WHEN 'resolve' THEN r.can_resolve
    WHEN 'mark_blocking' THEN r.can_mark_blocking
    ELSE false
  END;
END $function$
;
CREATE OR REPLACE FUNCTION public.can_user_access_licensee(_user_id uuid, _target_licensee_id uuid, _target_sector_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    _user_id IS NOT NULL
    AND _target_licensee_id IS NOT NULL
    AND (
      -- Primary User: profile directly linked to the licensee
      EXISTS (
        SELECT 1 FROM public.profiles p
        WHERE p.id = _user_id
          AND p.licensee_id = _target_licensee_id
      )
      OR
      -- Original license holder: the licensee row links to a license whose
      -- holder_id is the current user (covers pre_license_users-created
      -- accounts whose profile.licensee_id was never backfilled).
      EXISTS (
        SELECT 1
        FROM public.licensees l
        JOIN public.licenses lic ON lic.id = l.license_id
        WHERE l.id = _target_licensee_id
          AND lic.holder_id = _user_id
          AND (
            _target_sector_id IS NULL
            OR lic.sector_id IS NULL
            OR lic.sector_id = _target_sector_id
          )
      )
      OR
      -- PPOC: active mapping, sector match when target sector is provided
      EXISTS (
        SELECT 1
        FROM public.ppoc_entity_mappings m
        JOIN public.licensees l ON l.id = m.licensee_id
        WHERE m.ppoc_user_id = _user_id
          AND m.is_active = true
          AND m.licensee_id = _target_licensee_id
          AND (
            _target_sector_id IS NULL
            OR EXISTS (
              SELECT 1 FROM public.ppoc_mapping_sectors s
              WHERE s.mapping_id = m.id
                AND s.sector_id = _target_sector_id
            )
          )
          AND (
            l.sector_id IS NULL
            OR EXISTS (
              SELECT 1 FROM public.ppoc_mapping_sectors s
              WHERE s.mapping_id = m.id
                AND s.sector_id = l.sector_id
            )
          )
      )
    )
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_advisory_ai(_module text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case _module
    when 'examination' then
      public.has_permission(auth.uid(), 'prudential_supervision', 'view')
      or public.has_permission(auth.uid(), 'inspection_management', 'view')
    when 'enforcement' then
      public.has_permission(auth.uid(), 'enforcement_management', 'view')
    when 'complaints' then
      public.has_permission(auth.uid(), 'complaint_management', 'view')
    when 'conduct' then
      public.has_permission(auth.uid(), 'market_conduct', 'view')
    when 'cross_module' then
      public.has_permission(auth.uid(), 'prudential_supervision', 'view')
    when 'executive' then
      public.has_permission(auth.uid(), 'executive_oversight', 'view_all_dashboards')
      or public.has_permission(auth.uid(), 'admin_dashboard', 'view')
    else false
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_advisory_ai(_module text, _source_modules text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    public.can_view_advisory_ai(_module)
    and (
      -- legacy cross-module analyses carry no source metadata: require regeneration
      case when _module = 'cross_module'
        then coalesce(array_length(_source_modules, 1), 0) > 0
        else true
      end
    )
    and not exists (
      select 1
      from unnest(coalesce(_source_modules, '{}'::text[])) s
      where not public.can_view_advisory_ai_source(s)
    );
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_advisory_ai_source(_source text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case _source
    when 'prudential' then
      public.has_permission(auth.uid(), 'prudential_supervision', 'view')
    when 'examinations' then
      public.has_permission(auth.uid(), 'prudential_supervision', 'view')
      or public.has_permission(auth.uid(), 'inspection_management', 'view')
    when 'complaints' then
      public.has_permission(auth.uid(), 'complaint_management', 'view')
    when 'conduct' then
      public.has_permission(auth.uid(), 'market_conduct', 'view')
    when 'enforcement' then
      public.has_permission(auth.uid(), 'enforcement_management', 'view')
    when 'supervisory_actions' then
      public.has_permission(auth.uid(), 'prudential_supervision', 'view')
    when 'licensing' then
      public.has_permission(auth.uid(), 'license_management', 'view')
      or public.has_permission(auth.uid(), 'application_management', 'view')
    when 'fit_and_proper' then
      public.has_permission(auth.uid(), 'fit_proper_assessment', 'view')
    else false
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_application_legal_notes(_user_id uuid, _application_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_workflow_id uuid;
  v_step_id uuid;
BEGIN
  IF _user_id IS NULL OR _application_id IS NULL THEN
    RETURN false;
  END IF;

  -- super_admin / admin / legal reviewers
  IF public.has_role(_user_id, 'super_admin'::app_role)
     OR public.has_role(_user_id, 'admin'::app_role)
     OR public.is_legal_compliance_user(_user_id) THEN
    RETURN true;
  END IF;

  -- Internal user who can act on any step of the application's workflow
  SELECT wi.workflow_id INTO v_workflow_id
  FROM public.workflow_instances wi
  WHERE wi.entity_type = 'application'
    AND wi.entity_id = _application_id
  ORDER BY wi.created_at DESC
  LIMIT 1;

  IF v_workflow_id IS NULL THEN
    RETURN false;
  END IF;

  FOR v_step_id IN
    SELECT id FROM public.approval_steps WHERE workflow_id = v_workflow_id
  LOOP
    BEGIN
      IF ((public.user_can_act_on_workflow_step(_user_id, v_step_id))->>'can_act')::boolean THEN
        RETURN true;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      -- ignore evaluation errors, keep checking
      NULL;
    END;
  END LOOP;

  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_communications(_object_type text, _object_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_licensee uuid;
  v_ok boolean := false;
BEGIN
  IF _object_id IS NULL OR v_uid IS NULL THEN
    RETURN false;
  END IF;

  IF public.is_super_admin(v_uid) THEN
    RETURN true;
  END IF;

  v_licensee := public.user_licensee_id(v_uid);

  CASE lower(COALESCE(_object_type, ''))
    WHEN 'application' THEN
      SELECT EXISTS (
        SELECT 1 FROM public.applications a
         WHERE a.id = _object_id
           AND (
             a.applicant_id = v_uid
             OR (v_licensee IS NOT NULL
                 AND a.id IN (SELECT public.application_ids_for_licensee(v_licensee)))
             OR public.has_permission(v_uid, 'licensing', 'view')
           )
      ) INTO v_ok;

    WHEN 'complaint' THEN
      SELECT EXISTS (
        SELECT 1 FROM public.complaints c
         WHERE c.id = _object_id
           AND (
             c.internal_created_by = v_uid
             OR (v_licensee IS NOT NULL AND c.licensee_id = v_licensee)
             OR public.has_complaint_perm(v_uid, 'view_all')
             OR public.has_complaint_perm(v_uid, 'triage')
           )
      ) INTO v_ok;

    WHEN 'fp_assessment' THEN
      SELECT EXISTS (
        SELECT 1 FROM public.fp_assessments f
         WHERE f.id = _object_id
           AND (public.has_permission(v_uid, 'fit_and_proper', 'view')
                OR public.has_permission(v_uid, 'licensing', 'view')
                OR (v_licensee IS NOT NULL AND f.licensee_id = v_licensee))
      ) INTO v_ok;

    WHEN 'prudential_action' THEN
      SELECT EXISTS (
        SELECT 1 FROM public.prudential_actions p
         WHERE p.id = _object_id
           AND public.has_permission(v_uid, 'prudential_supervision', 'view')
      ) INTO v_ok;

    WHEN 'conduct_investigation' THEN
      SELECT EXISTS (
        SELECT 1 FROM public.conduct_investigations i
         WHERE i.id = _object_id
           AND public.has_permission(v_uid, 'market_conduct', 'view')
      ) INTO v_ok;

    WHEN 'enforcement_action' THEN
      SELECT EXISTS (
        SELECT 1 FROM public.enforcement_actions e
         WHERE e.id = _object_id
           AND public.has_permission(v_uid, 'market_conduct', 'view')
      ) INTO v_ok;

    ELSE
      v_ok := false;
  END CASE;

  RETURN COALESCE(v_ok, false);
END $function$
;
CREATE OR REPLACE FUNCTION public.can_view_complaint_rfi(_rfi_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.complaint_rfis r
    WHERE r.id = _rfi_id
      AND (
        public.is_super_admin(auth.uid())
        OR public.has_complaint_perm(auth.uid(), 'view')
        OR public.can_current_user_access_licensee(r.licensee_id, NULL)
      )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_conduct_intelligence()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT (auth.uid() IS NULL AND current_user IN ('service_role','postgres','supabase_admin'))
      OR has_role(auth.uid(),'super_admin'::app_role)
      OR has_role(auth.uid(),'admin'::app_role)
      OR has_role(auth.uid(),'supervisor'::app_role)
      OR has_role(auth.uid(),'analyst'::app_role)
      OR has_role(auth.uid(),'legal_compliance'::app_role)
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_conduct_investigation(_investigation_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.conduct_investigations ci
    WHERE ci.id = _investigation_id
      AND (
        public.is_super_admin(auth.uid())
        OR public.has_scoped_permission(auth.uid(),'conduct_investigations','view', ci.id, ci.licensee_id,
             (SELECT l.sector_id FROM public.licensees l WHERE l.id = ci.licensee_id), NULL::uuid)
        OR public.has_scoped_permission(auth.uid(),'market_conduct_investigation','view', ci.id, ci.licensee_id,
             (SELECT l.sector_id FROM public.licensees l WHERE l.id = ci.licensee_id), NULL::uuid)
        OR public.has_scoped_permission(auth.uid(),'market_conduct_investigation','access_investigation_workspace', ci.id, ci.licensee_id,
             (SELECT l.sector_id FROM public.licensees l WHERE l.id = ci.licensee_id), NULL::uuid)
      )
  )
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_entity_returns(_user_id uuid, _licensee_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    public.is_super_admin(_user_id)
    OR public.has_permission(_user_id, 'returns_management', 'view_all_entities')
    OR public.user_has_entity_assignment(_user_id, _licensee_id);
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_entity_returns(_user_id uuid, _licensee_id uuid, _workflow_status text, _status text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _user_id IS NULL OR _licensee_id IS NULL THEN false
    WHEN public.is_super_admin(_user_id) THEN true
    WHEN public.has_permission(_user_id, 'returns_management', 'view_all_entities') THEN true
    -- Users holding the standard view permission: assignment gates entity
    -- scope, but no lifecycle gate is applied (they legitimately review
    -- drafts they own or WIP records inside their queue).
    WHEN public.has_permission(_user_id, 'returns_management', 'view')
      AND public.user_has_entity_assignment(_user_id, _licensee_id) THEN true
    -- Assignment-only regulators: entity must match AND record must be in
    -- the submitted lifecycle. Prefer workflow_status when present, fall
    -- back to status.
    WHEN public.user_has_entity_assignment(_user_id, _licensee_id)
      AND public.is_assignment_only_regulator(_user_id)
      AND public.return_status_is_submitted_lifecycle(
        COALESCE(NULLIF(_workflow_status, ''), _status)
      ) THEN true
    ELSE false
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_lineage(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT _user_id IS NOT NULL
     AND (
       public.has_role(_user_id, 'super_admin'::app_role)
       OR public.has_role(_user_id, 'admin'::app_role)
       OR (public.is_internal_staff(_user_id)
           AND (public.has_permission(_user_id, 'audit_management', 'view')
                OR public.has_permission(_user_id, 'audit_management', 'export')))
     );
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_return_filed(_user_id uuid, _return_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.returns_filed r
    LEFT JOIN public.profiles p ON p.id = _user_id
    WHERE r.id = _return_id
      AND (
        r.created_by = _user_id
        OR public.can_view_entity_returns(_user_id, r.entity_id, r.workflow_status::text, r.status)
        OR public.can_view_entity_returns(_user_id, r.on_behalf_of_licensee_id, r.workflow_status::text, r.status)
        OR (
          p.licensee_id IS NOT NULL
          AND (p.licensee_id = r.entity_id OR p.licensee_id = r.on_behalf_of_licensee_id)
        )
        OR r.entity_id IN (SELECT public.ppoc_mapped_licensee_ids(_user_id))
        OR r.on_behalf_of_licensee_id IN (SELECT public.ppoc_mapped_licensee_ids(_user_id))
        OR public.external_can_access_return_filed(_user_id, r.id, 'can_submit_returns'::text)
        OR public.external_can_access_return_filed(_user_id, r.id, 'can_view_status'::text)
        OR EXISTS (
          SELECT 1
          FROM public.workflow_instances wi
          JOIN public.approval_steps s ON s.id = wi.current_step_id
          WHERE wi.entity_type IN ('return', 'returns_filed', 'return_filed')
            AND wi.entity_id = r.id
            AND wi.status = 'active'
            AND (
              (
                s.approver_type = 'specific_users'
                AND EXISTS (
                  SELECT 1
                  FROM jsonb_array_elements_text(COALESCE(s.approver_config->'user_ids', '[]'::jsonb)) AS assigned(user_id)
                  WHERE assigned.user_id = _user_id::text
                )
              )
              OR (
                s.approver_type = 'role_based_user'
                AND s.approver_role_id IN (
                  SELECT udr.role_id
                  FROM public.user_dynamic_roles udr
                  WHERE udr.user_id = _user_id
                )
              )
              OR (
                s.approver_role IS NOT NULL
                AND p.role::text = s.approver_role::text
              )
            )
        )
      )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.can_view_rule_engine(_user_id uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT _user_id IS NOT NULL AND (
    public.is_super_admin(_user_id)
    OR public.has_permission(_user_id, 'rule_engine', 'view')
    OR public.has_permission(_user_id, 'rule_engine', 'edit')
  );
$function$
;
CREATE OR REPLACE FUNCTION public.cancel_application(_application_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_now timestamptz := now();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;

  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  SELECT id, applicant_id, status, application_number
    INTO v_app
    FROM public.applications
   WHERE id = _application_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  IF v_app.applicant_id <> v_uid THEN
    RETURN jsonb_build_object('error','You cannot cancel this application','code','FORBIDDEN','http',403);
  END IF;

  IF v_app.status NOT IN ('draft','in_progress','resubmission_requested','query_raised','submitted') THEN
    RETURN jsonb_build_object('error',format('Cannot cancel application in ''%s'' status', v_app.status),
                              'code','INVALID_STATUS','http',409);
  END IF;

  UPDATE public.applications
     SET status = 'cancelled', cancelled_at = v_now, updated_at = v_now
   WHERE id = _application_id;

  UPDATE public.workflow_instances
     SET status = 'cancelled', completed_at = v_now, updated_at = v_now
   WHERE entity_id = _application_id
     AND entity_type = 'application'
     AND status = 'active';

  INSERT INTO public.approval_actions (
    application_id, actor_id, action, action_type, comments, responded_at
  ) VALUES (
    _application_id, v_uid, 'cancelled', 'cancel',
    COALESCE(NULLIF(trim(_reason),''),'Application cancelled by applicant'), v_now
  );

  PERFORM public.create_audit_log(
    v_uid, 'application_cancelled', 'application', _application_id::text, NULL,
    jsonb_build_object('reason', _reason), NULL
  );

  RETURN jsonb_build_object('success', true, 'http', 200, 'application_id', _application_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.check_applicant_name_exists(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.registrations
    WHERE lower(btrim(applicant_name)) = lower(btrim(p_name))
  );
$function$
;
CREATE OR REPLACE FUNCTION public.check_approval_blocked(_entity_type text, _entity_id uuid, _step_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _enforce boolean; _cnt int;
BEGIN
  IF _step_id IS NULL THEN RETURN jsonb_build_object('blocked', false, 'count', 0); END IF;
  SELECT bool_or(block_approval_on_unresolved_blocking AND enabled) INTO _enforce
    FROM public.review_step_permissions WHERE step_id = _step_id;
  IF NOT COALESCE(_enforce, false) THEN
    RETURN jsonb_build_object('blocked', false, 'count', 0);
  END IF;
  SELECT count(*) INTO _cnt FROM public.review_comments
    WHERE entity_type = _entity_type AND entity_id = _entity_id
      AND is_blocking = true AND status = 'open';
  RETURN jsonb_build_object('blocked', _cnt > 0, 'count', _cnt);
END $function$
;
CREATE OR REPLACE FUNCTION public.check_coordination_gates(_subject_type text, _subject_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE blockers jsonb := '[]'::jsonb; r record;
BEGIN
  IF _subject_id IS NULL THEN RETURN blockers; END IF;
  FOR r IN SELECT cc.id, cc.status, cc.title FROM coordination_cases cc
           WHERE cc.subject_type=_subject_type AND cc.subject_id=_subject_id AND cc.status<>'closed'
  LOOP
    IF EXISTS (SELECT 1 FROM coordination_escalations WHERE case_id=r.id AND status IN ('open','in_review')) THEN
      blockers := blockers || jsonb_build_object('kind','coordination_escalation','case_id',r.id,'title',r.title);
    END IF;
    IF EXISTS (SELECT 1 FROM coordination_flags WHERE case_id=r.id AND status='open' AND flag_type IN ('blocker','interdependency','concurrent_review')) THEN
      blockers := blockers || jsonb_build_object('kind','coordination_flag','case_id',r.id,'title',r.title);
    END IF;
    IF EXISTS (SELECT 1 FROM coordination_participants WHERE case_id=r.id AND coalesce(clearance_status,'pending') NOT IN ('cleared','not_required','waived')) THEN
      blockers := blockers || jsonb_build_object('kind','pending_clearance','case_id',r.id,'title',r.title);
    END IF;
  END LOOP;
  RETURN blockers;
END; $function$
;
CREATE OR REPLACE FUNCTION public.check_decision_gates(_application_id uuid, _license_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  blockers jsonb := '[]'::jsonb;
  r record;
  app_row applications%ROWTYPE;
  lic_row licenses%ROWTYPE;
  target_licensee uuid;
  target_license uuid;
BEGIN
  IF _application_id IS NOT NULL THEN
    SELECT * INTO app_row FROM applications WHERE id = _application_id;
    target_licensee := app_row.applicant_id;
  END IF;

  IF _license_id IS NOT NULL THEN
    SELECT * INTO lic_row FROM licenses WHERE id = _license_id;
    target_license := lic_row.id;
    IF target_licensee IS NULL THEN
      target_licensee := lic_row.holder_id;
    END IF;
  END IF;

  -- Coordination flags: blocker / concurrent_review still open
  FOR r IN
    SELECT cf.id, cf.flag_type, cf.title, cf.case_id
    FROM coordination_flags cf
    WHERE cf.status = 'open'
      AND cf.flag_type IN ('blocker','concurrent_review')
      AND (
        (_application_id IS NOT NULL AND cf.linked_application_id = _application_id)
        OR (_license_id IS NOT NULL AND cf.linked_license_id = _license_id)
      )
  LOOP
    blockers := blockers || jsonb_build_object(
      'kind','coordination_flag',
      'flag_id',r.id,
      'flag_type',r.flag_type,
      'case_id',r.case_id,
      'title',r.title
    );
  END LOOP;

  -- Coordination escalations still open on cases that reference this app/license
  FOR r IN
    SELECT ce.id, ce.tier, ce.status, ce.case_id
    FROM coordination_escalations ce
    JOIN coordination_flags cf ON cf.case_id = ce.case_id
    WHERE ce.status IN ('open','in_review')
      AND (
        (_application_id IS NOT NULL AND cf.linked_application_id = _application_id)
        OR (_license_id IS NOT NULL AND cf.linked_license_id = _license_id)
      )
  LOOP
    blockers := blockers || jsonb_build_object(
      'kind','coordination_escalation',
      'escalation_id',r.id,
      'tier',r.tier,
      'status',r.status,
      'case_id',r.case_id
    );
  END LOOP;

  -- Fit & Proper: for each current critical role at the licensee, ensure a current positive determination
  IF target_licensee IS NOT NULL THEN
    FOR r IN
      SELECT ir.individual_id, ir.role_type, ir.role_title,
             d.outcome AS latest_outcome
      FROM fp_individual_roles ir
      LEFT JOIN LATERAL (
        SELECT outcome FROM fp_determinations
        WHERE individual_id = ir.individual_id
          AND is_current = true
        ORDER BY determined_at DESC NULLS LAST
        LIMIT 1
      ) d ON true
      WHERE ir.licensee_id = target_licensee
        AND ir.is_current = true
        AND (ir.role_type IS NULL OR ir.role_type IN (
          'director','ceo','cfo','coo','chairperson','shareholder',
          'controller','key_person','md','executive_director','compliance_officer'
        ))
        AND (d.outcome IS NULL OR d.outcome IN ('rejected','deferred','withdrawn'))
    LOOP
      blockers := blockers || jsonb_build_object(
        'kind','fit_and_proper',
        'individual_id',r.individual_id,
        'role_type',r.role_type,
        'role_title',r.role_title,
        'latest_outcome',COALESCE(r.latest_outcome,'none')
      );
    END LOOP;
  END IF;

  RETURN blockers;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.check_primary_user_email_exists(p_email text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.registrations where lower(email) = lower(trim(p_email))
    union all
    select 1 from public.profiles where lower(email) = lower(trim(p_email))
    union all
    select 1 from auth.users where lower(email) = lower(trim(p_email))
  );
$function$
;
CREATE OR REPLACE FUNCTION public.claim_email_retry_batch(_limit integer DEFAULT 25, _worker text DEFAULT NULL::text)
 RETURNS SETOF notification_dispatch_log
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH claimed AS (
    SELECT id
      FROM public.notification_dispatch_log
     WHERE channel = 'email'
       AND status = 'failed'
       AND poisoned = false
       AND attempts < 5
       AND recipient_email IS NOT NULL
       AND COALESCE(error, '') NOT IN ('no_email', 'recipient_preference_opted_out', 'deferred_to_digest')
       AND COALESCE(error, '') !~* 'no such user|mailbox unavailable|recipient rejected|smtp authentication failed'
       AND (next_attempt_at IS NULL OR next_attempt_at <= now())
       AND (claimed_at IS NULL OR claimed_at < now() - interval '10 minutes')
     ORDER BY created_at
     LIMIT GREATEST(1, COALESCE(_limit, 25))
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.notification_dispatch_log l
     SET status = 'processing',
         claimed_at = now(),
         claimed_by = _worker
    FROM claimed c
   WHERE l.id = c.id
  RETURNING l.*;
END; $function$
;
CREATE OR REPLACE FUNCTION public.claim_notification_event_queue(_limit integer DEFAULT 50, _worker text DEFAULT NULL::text)
 RETURNS SETOF notification_event_queue
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH claimed AS (
    SELECT id FROM public.notification_event_queue
    WHERE status = 'pending' AND next_attempt_at <= now()
    ORDER BY created_at
    LIMIT greatest(1, coalesce(_limit, 50))
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.notification_event_queue q
     SET status = 'processing', claimed_at = now(), claimed_by = _worker
   WHERE q.id IN (SELECT id FROM claimed)
  RETURNING q.*;
END; $function$
;
CREATE OR REPLACE FUNCTION public.claim_notification_outbox(_limit integer DEFAULT 50, _worker text DEFAULT NULL::text)
 RETURNS SETOF notification_outbox
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH picked AS (
    SELECT id
    FROM public.notification_outbox
    WHERE status = 'pending'
      AND next_attempt_at <= now()
    ORDER BY created_at
    LIMIT GREATEST(_limit, 1)
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.notification_outbox o
     SET status     = 'processing',
         claimed_at = now(),
         claimed_by = COALESCE(_worker, 'worker')
    FROM picked
   WHERE o.id = picked.id
  RETURNING o.*;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.classify_complaint(_id uuid, _payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_sev text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_complaint_perm(v_uid, 'triage') THEN
    RAISE EXCEPTION 'Not permitted to triage complaints' USING ERRCODE = '42501';
  END IF;
  v_sev := NULLIF(_payload->>'severity','');
  IF v_sev IS NOT NULL AND v_sev NOT IN ('low','medium','high','critical') THEN
    RAISE EXCEPTION 'Invalid severity' USING ERRCODE = '22023';
  END IF;
  UPDATE public.complaints
     SET conduct_risk_category_id = NULLIF(_payload->>'conduct_risk_category_id','')::uuid,
         product_id               = NULLIF(_payload->>'product_id','')::uuid,
         channel_id               = NULLIF(_payload->>'channel_id','')::uuid,
         customer_type            = NULLIF(_payload->>'customer_type',''),
         vulnerability_indicator  = COALESCE((_payload->>'vulnerability_indicator')::boolean, false),
         vulnerability_notes      = NULLIF(_payload->>'vulnerability_notes',''),
         priority                 = NULLIF(_payload->>'priority',''),
         severity                 = COALESCE(v_sev, severity),
         sla_days                 = NULLIF(_payload->>'sla_days','')::int,
         assigned_team            = NULLIF(_payload->>'assigned_team',''),
         triage_source            = COALESCE(NULLIF(_payload->>'triage_source',''), triage_source),
         triage_override_status   = COALESCE(NULLIF(_payload->>'triage_override_status',''), triage_override_status),
         updated_at = now()
   WHERE id = _id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'complaint.classification_updated', 'complaint', _id, _payload);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.classify_correspondence(_thread_id uuid, _category text, _priority text, _tags text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_actor text;
BEGIN
  IF NOT public.is_internal_staff(v_user) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  v_actor := public.correspondence_actor_label(v_user);
  UPDATE public.correspondence_threads
  SET category = _category, priority = _priority,
      tags = COALESCE(_tags, tags),
      status = CASE WHEN status = 'received' THEN 'classified' ELSE status END
  WHERE id = _thread_id;
  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail)
  VALUES (_thread_id, v_user, v_actor, 'Staff', 'Classified', _category || ' / priority ' || _priority);
END; $function$
;
CREATE OR REPLACE FUNCTION public.classify_ratio_risk(_value numeric, _warn numeric, _breach numeric, _comparator text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _value IS NULL THEN 'green'
    WHEN _comparator IN ('>=','>') THEN
      CASE WHEN _breach IS NOT NULL AND _value >= _breach THEN 'red'
           WHEN _warn IS NOT NULL AND _value >= _warn THEN 'amber' ELSE 'green' END
    WHEN _comparator IN ('<=','<') THEN
      CASE WHEN _breach IS NOT NULL AND _value <= _breach THEN 'red'
           WHEN _warn IS NOT NULL AND _value <= _warn THEN 'amber' ELSE 'green' END
    ELSE 'green' END;
$function$
;
CREATE OR REPLACE FUNCTION public.cleanup_orphaned_complaint_evidence(_older_than interval DEFAULT '24:00:00'::interval)
 RETURNS TABLE(deleted_evidence_id uuid, file_upload_id uuid, bucket_name text, file_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin')
     AND NOT public.has_role(auth.uid(), 'super_admin')
     AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH del AS (
    DELETE FROM public.complaint_evidence e
     WHERE e.finalized_at IS NULL
       AND e.staged_at < now() - _older_than
     RETURNING e.id, e.file_upload_id
  )
  SELECT del.id, del.file_upload_id, fu.bucket_name, fu.file_path
    FROM del
    LEFT JOIN public.file_uploads fu ON fu.id = del.file_upload_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.clone_validation_rule(_rule_id uuid, _new_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _src public.return_validation_rules; _new_id uuid; _def jsonb;
BEGIN
  IF NOT public.can_manage_returns_config(auth.uid()) THEN
    RAISE EXCEPTION 'You do not have permission to manage returns configuration';
  END IF;
  SELECT * INTO _src FROM public.return_validation_rules WHERE id = _rule_id;
  IF _src.id IS NULL THEN RAISE EXCEPTION 'Rule not found'; END IF;
  INSERT INTO public.return_validation_rules(
    return_config_id, form_id, scope, name, rule_type, expression, error_message, severity,
    field_refs, is_active, current_version, created_by
  ) VALUES (
    _src.return_config_id, _src.form_id, _src.scope, COALESCE(NULLIF(_new_name,''), _src.name || ' (copy)'),
    _src.rule_type, _src.expression, _src.error_message, _src.severity,
    _src.field_refs, _src.is_active, 1, auth.uid()
  ) RETURNING id INTO _new_id;
  SELECT to_jsonb(r.*) INTO _def FROM public.return_validation_rules r WHERE r.id = _new_id;
  PERFORM public.log_compliance_audit('CREATE','return_validation_rules', _new_id::text, NULL, _def,
    'Rule cloned', NULL, NULL, jsonb_build_object('event','RULE_CLONED','from_rule',_rule_id));
  RETURN _new_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.close_application(_application_id uuid, _reason text DEFAULT NULL::text)
 RETURNS applications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.applications;
BEGIN
  PERFORM public.enforce_permission('application_management', 'close');

  UPDATE public.applications
     SET status = 'closed',
         updated_at = now()
   WHERE id = _application_id
   RETURNING * INTO _row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Application % not found', _application_id
      USING ERRCODE = 'no_data_found';
  END IF;

  INSERT INTO public.audit_logs (
    user_id, action, entity_type, entity_id, metadata, created_at
  ) VALUES (
    auth.uid(),
    'application.close',
    'application',
    _application_id,
    jsonb_build_object('reason', _reason),
    now()
  );

  RETURN _row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.close_complaint(_id uuid, _reason text, _category text DEFAULT NULL::text, _expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_status text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_complaint_perm(v_uid, 'close') THEN
    RAISE EXCEPTION 'Not permitted to close complaints' USING ERRCODE = '42501';
  END IF;
  IF _reason IS NULL OR length(trim(_reason)) < 5 THEN
    RAISE EXCEPTION 'Closure reason (min 5 chars) is required' USING ERRCODE = '22023';
  END IF;
  IF _category IS NULL OR length(trim(_category)) = 0 THEN
    RAISE EXCEPTION 'Closure category is required' USING ERRCODE = '22023';
  END IF;
  PERFORM public._assert_complaint_fresh(_id, _expected_updated_at);
  SELECT status INTO v_status FROM public.complaints WHERE id = _id;
  IF v_status IS NULL THEN RAISE EXCEPTION 'Complaint not found' USING ERRCODE = 'P0002'; END IF;
  IF v_status = 'closed' THEN RETURN; END IF;
  UPDATE public.complaints
     SET status='closed', closed_at=now(), closed_by=v_uid,
         closure_reason=_reason, closure_category=_category, updated_at=now()
   WHERE id = _id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'complaint.closed', 'complaint', _id,
          jsonb_build_object('reason',_reason,'category',_category,'from_status',v_status));
END; $function$
;
CREATE OR REPLACE FUNCTION public.close_correspondence(_thread_id uuid, _notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_actor text;
BEGIN
  IF NOT public.is_internal_staff(v_user) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  v_actor := public.correspondence_actor_label(v_user);
  UPDATE public.correspondence_threads
     SET status = 'closed',
         thread_state = 'closed',
         closed_at = now(),
         closed_by = v_user,
         pending_since = NULL,
         response_due_at = NULL
   WHERE id = _thread_id;
  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail)
  VALUES (_thread_id, v_user, v_actor, 'Staff', 'Correspondence closed', _notes);
END; $function$
;
CREATE OR REPLACE FUNCTION public.close_prudential_action(_action_id uuid, _kind text, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid();
        _a public.prudential_actions;
        _accepted boolean;
BEGIN
  IF _uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHENTICATED');
  END IF;
  IF _kind NOT IN ('completed','waived','cancelled') THEN
    RETURN jsonb_build_object('error','Invalid closure type','code','VALIDATION');
  END IF;
  IF _reason IS NULL OR length(trim(_reason)) < 5 THEN
    RETURN jsonb_build_object('error','A reason of at least 5 characters is required','code','VALIDATION');
  END IF;
  SELECT * INTO _a FROM public.prudential_actions WHERE id = _action_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Action not found','code','NOT_FOUND');
  END IF;
  IF NOT (public.is_super_admin(_uid) OR public.can_act_on_prudential(_uid)) THEN
    RETURN jsonb_build_object('error','You are not permitted to close supervisory actions','code','FORBIDDEN');
  END IF;

  IF _kind = 'completed' AND _a.evidence_required THEN
    SELECT EXISTS (SELECT 1 FROM public.prudential_action_responses r
                    WHERE r.action_id = _action_id AND r.kind = 'supervisor_review' AND r.decision = 'accepted')
      INTO _accepted;
    IF NOT _accepted THEN
      RETURN jsonb_build_object(
        'error','This action requires evidence that has been reviewed and accepted before it can be completed',
        'code','EVIDENCE_NOT_ACCEPTED');
    END IF;
  END IF;

  UPDATE public.prudential_actions
     SET status = _kind,
         completion_notes = CASE WHEN _kind = 'completed' THEN trim(_reason) ELSE completion_notes END,
         waiver_reason   = CASE WHEN _kind = 'waived' THEN trim(_reason) ELSE waiver_reason END,
         cancellation_reason = CASE WHEN _kind = 'cancelled' THEN trim(_reason) ELSE cancellation_reason END,
         progress_percent = CASE WHEN _kind = 'completed' THEN 100 ELSE progress_percent END,
         closed_at = now(), closed_by = _uid, updated_at = now()
   WHERE id = _action_id;

  INSERT INTO public.prudential_action_events(action_id, event_type, from_status, to_status, actor_id, reason)
  VALUES (_action_id, 'closed', _a.status, _kind, _uid, trim(_reason));

  RETURN jsonb_build_object('ok', true, 'status', _kind);
END $function$
;
CREATE OR REPLACE FUNCTION public.communication_timeline(_object_type text, _object_id uuid)
 RETURNS TABLE(id uuid, occurred_at timestamp with time zone, direction text, channel text, event_key text, subject text, recipient text, recipient_user_id uuid, communication_state communication_state, provider text, provider_message_id text, failure_category text, error text, retry_count integer, template_id uuid, template_version integer, rendered_content_ref text, delivered_at timestamp with time zone, failed_at timestamp with time zone, sent_to_provider_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.can_view_communications(_object_type, _object_id) THEN
    RAISE EXCEPTION 'not authorized for communications of % %', _object_type, _object_id
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT d.id, COALESCE(d.requested_at, d.created_at), 'outbound'::text, d.channel, d.event_key,
         d.subject, COALESCE(d.recipient_email, d.recipient_phone), d.recipient_user_id,
         d.communication_state, d.provider, d.provider_message_id,
         d.failure_category, d.error, COALESCE(d.retry_count,0),
         d.template_id, d.template_version, d.rendered_content_ref,
         d.delivered_at, d.failed_at, d.sent_to_provider_at
  FROM public.notification_dispatch_log d
  WHERE d.entity_id = _object_id::text
    AND (d.entity_type IS NULL OR lower(d.entity_type) = lower(_object_type))
  ORDER BY COALESCE(d.requested_at, d.created_at) DESC
  LIMIT 500;
END $function$
;
CREATE OR REPLACE FUNCTION public.complaint_autolink_licensee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.licensee_id IS NULL AND NEW.complainant_id IS NOT NULL THEN
    SELECT p.licensee_id INTO NEW.licensee_id
    FROM public.profiles p
    WHERE p.id = NEW.complainant_id
      AND p.licensee_id IS NOT NULL;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_blockers(_complaint_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _c record; _out jsonb := '[]'::jsonb; _open_rfis int;
BEGIN
  SELECT * INTO _c FROM public.complaints WHERE id = _complaint_id;
  IF _c IS NULL THEN RETURN _out; END IF;
  IF _c.status IN ('closed', 'resolved') THEN RETURN _out; END IF;

  IF _c.investigator_id IS NULL THEN
    _out := _out || jsonb_build_array(jsonb_build_object('code','NO_OWNER','label','No investigating officer is assigned'));
  END IF;
  IF _c.acknowledged_at IS NULL THEN
    _out := _out || jsonb_build_array(jsonb_build_object('code','NOT_ACKNOWLEDGED','label','The complainant has not been acknowledged'));
  END IF;

  SELECT count(*) INTO _open_rfis FROM public.complaint_rfis r
   WHERE r.complaint_id = _complaint_id AND coalesce(r.status, '') NOT IN ('closed', 'completed', 'cancelled', 'responded');
  IF _open_rfis > 0 THEN
    _out := _out || jsonb_build_array(jsonb_build_object('code','OPEN_RFI',
      'label', _open_rfis || ' outstanding information request(s) awaiting response'));
  END IF;

  IF _c.status IN ('under_investigation', 'investigation') AND coalesce(btrim(_c.findings), '') = '' THEN
    _out := _out || jsonb_build_array(jsonb_build_object('code','NO_FINDINGS','label','No investigation findings have been recorded'));
  END IF;
  IF coalesce(btrim(_c.resolution), '') = '' AND coalesce(btrim(_c.resolution_notes), '') = ''
     AND _c.status IN ('pending_closure', 'awaiting_closure') THEN
    _out := _out || jsonb_build_array(jsonb_build_object('code','NO_RESOLUTION','label','No resolution has been recorded'));
  END IF;
  RETURN _out;
END; $function$
;
CREATE OR REPLACE FUNCTION public.complaint_bulk_import(_source text, _file_name text, _rows jsonb, _regulator_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch uuid;
  v_row jsonb;
  v_idx integer := 0;
  v_errors jsonb;
  v_subject text;
  v_desc text;
  v_email text;
  v_dup uuid;
  v_new jsonb;
  v_total integer := 0; v_valid integer := 0; v_invalid integer := 0;
  v_dupes integer := 0; v_imported integer := 0;
BEGIN
  IF NOT public.has_complaint_perm(auth.uid(),'edit') THEN
    RAISE EXCEPTION 'not authorised to import complaints' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(_rows) <> 'array' THEN
    RAISE EXCEPTION 'rows must be a JSON array' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.complaint_import_batches(regulator_id, source, file_name, status, created_by)
  VALUES (_regulator_id, COALESCE(_source,'csv'), _file_name, 'processing', auth.uid())
  RETURNING id INTO v_batch;

  FOR v_row IN SELECT * FROM jsonb_array_elements(_rows) LOOP
    v_idx := v_idx + 1;
    v_total := v_total + 1;
    v_errors := '[]'::jsonb;
    v_subject := NULLIF(btrim(COALESCE(v_row->>'subject','')),'');
    v_desc := NULLIF(btrim(COALESCE(v_row->>'description','')),'');
    v_email := NULLIF(btrim(COALESCE(v_row->>'email','')),'');
    v_dup := NULL;

    IF v_subject IS NULL THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object('field','subject','message','Subject is required'));
    END IF;
    IF v_desc IS NULL OR length(v_desc) < 10 THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object('field','description','message','Description must be at least 10 characters'));
    END IF;
    IF v_email IS NOT NULL AND v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object('field','email','message','Email is not valid'));
    END IF;
    IF (v_row ? 'licensee_id') AND NULLIF(v_row->>'licensee_id','') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.licensees l WHERE l.id = (v_row->>'licensee_id')::uuid) THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object('field','licensee_id','message','Unknown regulated entity'));
    END IF;

    IF jsonb_array_length(v_errors) > 0 THEN
      v_invalid := v_invalid + 1;
      INSERT INTO public.complaint_import_rows(batch_id,row_number,raw_data,outcome,validation_errors,rejection_reason)
      VALUES (v_batch, v_idx, v_row, 'invalid', v_errors, 'Validation failed');
      CONTINUE;
    END IF;

    SELECT c.id INTO v_dup
    FROM public.complaints c
    WHERE lower(btrim(c.subject)) = lower(v_subject)
      AND (
        (v_email IS NOT NULL AND lower(COALESCE(c.email,'')) = lower(v_email))
        OR (NULLIF(v_row->>'licensee_id','') IS NOT NULL AND c.licensee_id = (v_row->>'licensee_id')::uuid)
      )
      AND c.created_at > now() - interval '90 days'
    ORDER BY c.created_at DESC
    LIMIT 1;

    IF v_dup IS NOT NULL THEN
      v_dupes := v_dupes + 1;
      INSERT INTO public.complaint_import_rows(batch_id,row_number,raw_data,outcome,duplicate_of_complaint_id,rejection_reason)
      VALUES (v_batch, v_idx, v_row, 'duplicate', v_dup, 'Matches an existing complaint within 90 days');
      CONTINUE;
    END IF;

    v_valid := v_valid + 1;
    BEGIN
      v_new := public.create_complaint('internal', v_row || jsonb_build_object('intake_source','bulk_import'));
      v_imported := v_imported + 1;
      INSERT INTO public.complaint_import_rows(batch_id,row_number,raw_data,outcome,complaint_id,complaint_number)
      VALUES (v_batch, v_idx, v_row, 'imported', (v_new->>'id')::uuid, v_new->>'complaint_number');
    EXCEPTION WHEN OTHERS THEN
      v_valid := v_valid - 1;
      v_invalid := v_invalid + 1;
      INSERT INTO public.complaint_import_rows(batch_id,row_number,raw_data,outcome,validation_errors,rejection_reason)
      VALUES (v_batch, v_idx, v_row, 'failed',
              jsonb_build_array(jsonb_build_object('field','_row','message',SQLERRM)), SQLERRM);
    END;
  END LOOP;

  UPDATE public.complaint_import_batches
     SET status = CASE WHEN v_imported = 0 THEN 'failed'
                       WHEN v_invalid + v_dupes > 0 THEN 'partial'
                       ELSE 'completed' END,
         total_rows = v_total, valid_rows = v_valid, invalid_rows = v_invalid,
         duplicate_rows = v_dupes, imported_rows = v_imported, updated_at = now()
   WHERE id = v_batch;

  RETURN jsonb_build_object('batch_id', v_batch, 'total', v_total, 'valid', v_valid,
    'invalid', v_invalid, 'duplicates', v_dupes, 'imported', v_imported);
END $function$
;
CREATE OR REPLACE FUNCTION public.complaint_case(_complaint_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _c record; _entity text; _owner text; _res jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
  SELECT * INTO _c FROM public.complaints WHERE id = _complaint_id;
  IF _c IS NULL THEN RAISE EXCEPTION 'Complaint not found' USING ERRCODE = 'P0002'; END IF;

  SELECT l.name INTO _entity FROM public.licensees l WHERE l.id = coalesce(_c.licensee_id, _c.license_holder_id);
  SELECT p.full_name INTO _owner FROM public.profiles p WHERE p.id = _c.investigator_id;

  _res := jsonb_build_object(
    'id', _c.id,
    'reference', _c.complaint_number,
    'subject', _c.subject,
    'case_type', 'Complaint',
    'entity_id', coalesce(_c.licensee_id, _c.license_holder_id),
    'entity_name', _entity,
    'entity_href', CASE WHEN coalesce(_c.licensee_id, _c.license_holder_id) IS NOT NULL
                        THEN '/entities/' || coalesce(_c.licensee_id, _c.license_holder_id) ELSE NULL END,
    'stage', upper(_c.status),
    'stage_label', initcap(replace(_c.status, '_', ' ')),
    'status', _c.status,
    'status_label', initcap(replace(_c.status, '_', ' ')),
    'owner_id', _c.investigator_id,
    'owner_name', _owner,
    'team', _c.assigned_team,
    'priority', coalesce(_c.priority, 'medium'),
    'severity', coalesce(_c.severity, 'medium'),
    'sla_due_at', _c.sla_due_at,
    'sla_state', CASE
      WHEN _c.status IN ('closed', 'resolved') THEN 'paused'
      WHEN _c.sla_due_at IS NULL THEN 'paused'
      WHEN _c.sla_due_at < now() THEN 'breached'
      WHEN _c.sla_due_at < now() + interval '3 days' THEN 'due_soon'
      ELSE 'on_track' END,
    'is_terminal', (_c.status IN ('closed', 'resolved')),
    'waiting_on', CASE
      WHEN _c.status IN ('closed', 'resolved') THEN NULL
      WHEN _c.investigator_id IS NULL THEN 'Case allocation'
      WHEN EXISTS (SELECT 1 FROM public.complaint_rfis r WHERE r.complaint_id = _c.id
                     AND coalesce(r.status,'') NOT IN ('closed','completed','cancelled','responded'))
        THEN 'Regulated entity / complainant'
      ELSE 'Assigned officer' END,
    'next_action_label', CASE
      WHEN _c.status IN ('closed', 'resolved') THEN NULL
      WHEN _c.investigator_id IS NULL THEN 'Allocate an investigating officer'
      WHEN _c.acknowledged_at IS NULL THEN 'Acknowledge the complainant'
      WHEN _c.status IN ('under_investigation', 'investigation') THEN 'Record investigation findings'
      ELSE 'Progress the complaint' END,
    'blockers', public.complaint_blockers(_complaint_id),
    'vulnerability_indicator', _c.vulnerability_indicator,
    'repeat_complaint_count', _c.repeat_complaint_count,
    'opened_at', _c.created_at,
    'acknowledged_at', _c.acknowledged_at,
    'resolved_at', _c.resolved_at,
    'closed_at', _c.closed_at,
    'last_activity_at', greatest(_c.updated_at, _c.created_at),
    'counts', jsonb_build_object(
      'evidence', (SELECT count(*) FROM public.complaint_evidence e WHERE e.complaint_id = _c.id),
      'rfis', (SELECT count(*) FROM public.complaint_rfis r WHERE r.complaint_id = _c.id),
      'open_rfis', (SELECT count(*) FROM public.complaint_rfis r WHERE r.complaint_id = _c.id
                      AND coalesce(r.status,'') NOT IN ('closed','completed','cancelled','responded')),
      'tasks', (SELECT count(*) FROM public.complaint_investigation_tasks t WHERE t.complaint_id = _c.id),
      'open_tasks', (SELECT count(*) FROM public.complaint_investigation_tasks t WHERE t.complaint_id = _c.id
                       AND coalesce(t.status,'') NOT IN ('completed','cancelled')),
      'findings', (SELECT count(*) FROM public.conduct_findings f
                     WHERE f.source_type = 'complaint' AND f.source_id = _c.id),
      'remediation_open', (SELECT count(*) FROM public.conduct_actions a
                             WHERE a.source_module = 'complaint' AND a.source_id = _c.id
                               AND a.status NOT IN ('completed','waived','cancelled')),
      'linked_alerts', (SELECT count(*) FROM public.conduct_alerts al WHERE al.complaint_id = _c.id)));

  RETURN _res;
END; $function$
;
CREATE OR REPLACE FUNCTION public.complaint_intake_decide(_variant text, _regulator_id uuid, _payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_variant text := lower(coalesce(_variant,'internal'));
  v_rules public.complaint_intake_rules%ROWTYPE;
  v_default_rules public.complaint_intake_rules%ROWTYPE;
  v_subject text := btrim(coalesce(_payload->>'subject',''));
  v_desc    text := btrim(coalesce(_payload->>'description',''));
  v_email   text := NULLIF(_payload->>'email','');
  v_anon boolean := coalesce((_payload->>'anonymous')::boolean, false);
  v_vuln boolean := coalesce((_payload->>'vulnerability_indicator')::boolean, false);
  v_vuln_notes text := NULLIF(_payload->>'vulnerability_notes','');
  v_vuln_cat text := NULLIF(_payload->>'vulnerability_category','');
  v_sev text;
  v_prio text;
  v_intake text := NULLIF(_payload->>'intake_source','');
  v_errors jsonb := '[]'::jsonb;
  v_field text;
BEGIN
  SELECT * INTO v_rules FROM public.complaint_intake_rules
   WHERE variant = v_variant
     AND (regulator_id = _regulator_id OR (regulator_id IS NULL))
   ORDER BY regulator_id NULLS LAST
   LIMIT 1;

  IF v_rules.id IS NULL THEN
    v_rules.required_fields := ARRAY['subject','description'];
    v_rules.allow_anonymous := (v_variant = 'public');
  END IF;

  -- Severity is system-assigned for EVERY variant. No caller can set it.
  -- Fallback order: variant rule default -> global default row -> 'medium'.
  v_sev := v_rules.default_severity;
  IF v_sev IS NULL THEN
    SELECT * INTO v_default_rules FROM public.complaint_intake_rules
      WHERE regulator_id IS NULL AND default_severity IS NOT NULL
      ORDER BY variant LIMIT 1;
    v_sev := v_default_rules.default_severity;
  END IF;
  v_sev := coalesce(v_sev, 'medium');

  IF v_variant IN ('public','licensee') THEN
    v_prio := 'p3';
  ELSE
    v_prio := coalesce(NULLIF(_payload->>'priority',''),'p3');
  END IF;

  IF v_subject = '' OR length(v_subject) < 3 THEN
    v_errors := v_errors || jsonb_build_object('code','required','field','subject','message','Subject is required (min 3 chars)');
  END IF;
  IF v_desc = '' OR length(v_desc) < 10 THEN
    v_errors := v_errors || jsonb_build_object('code','required','field','description','message','Description is required (min 10 chars)');
  END IF;

  FOREACH v_field IN ARRAY coalesce(v_rules.required_fields, ARRAY[]::text[]) LOOP
    IF v_field IN ('subject','description','severity') THEN CONTINUE; END IF;
    IF NULLIF(_payload->>v_field,'') IS NULL THEN
      v_errors := v_errors || jsonb_build_object('code','required','field',v_field,'message',v_field||' is required');
    END IF;
  END LOOP;

  IF v_vuln AND v_vuln_notes IS NULL AND v_vuln_cat IS NULL THEN
    v_errors := v_errors || jsonb_build_object('code','required','field','vulnerability_notes','message','Provide vulnerability notes or category when marked vulnerable');
  END IF;

  IF v_variant = 'public' AND v_anon = false AND v_email IS NULL THEN
    v_errors := v_errors || jsonb_build_object('code','required','field','email','message','Email required unless anonymous is checked');
  END IF;
  IF v_variant = 'public' AND v_anon = true AND NOT coalesce(v_rules.allow_anonymous, true) THEN
    v_errors := v_errors || jsonb_build_object('code','forbidden','field','anonymous','message','Anonymous submission is not permitted');
  END IF;

  IF v_intake IS NULL THEN
    v_intake := CASE v_variant
      WHEN 'public'   THEN 'consumer_portal'
      WHEN 'licensee' THEN 'licensee_portal'
      WHEN 'internal' THEN 'internal'
      WHEN 'staff'    THEN 'staff_intake'
    END;
  END IF;

  RETURN jsonb_build_object(
    'variant', v_variant,
    'rule_id', v_rules.id,
    'required_fields', to_jsonb(coalesce(v_rules.required_fields, ARRAY[]::text[])),
    'allow_anonymous', coalesce(v_rules.allow_anonymous, true),
    'max_attachments', v_rules.max_attachments,
    'severity', v_sev,
    'severity_source', 'intake_default',
    'priority', v_prio,
    'intake_source', v_intake,
    'errors', v_errors
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_record_closure_review(_complaint_id uuid, _decision text, _resolution_summary text DEFAULT NULL::text, _rationale text DEFAULT NULL::text, _outcome_category text DEFAULT NULL::text, _final_communication_ref text DEFAULT NULL::text, _evidence_complete boolean DEFAULT false, _qa_required boolean DEFAULT false, _reviewer_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF NOT public.has_complaint_perm(auth.uid(),'edit') THEN
    RAISE EXCEPTION 'not authorised' USING ERRCODE = '42501';
  END IF;
  IF _decision NOT IN ('closure_proposed','qa_approved','qa_returned','closed') THEN
    RAISE EXCEPTION 'invalid decision %', _decision USING ERRCODE = '22023';
  END IF;
  IF _decision IN ('closure_proposed','closed') THEN
    IF COALESCE(btrim(_resolution_summary),'') = '' THEN
      RAISE EXCEPTION 'resolution summary is required' USING ERRCODE = '22023';
    END IF;
    IF COALESCE(length(btrim(_rationale)),0) < 10 THEN
      RAISE EXCEPTION 'rationale of at least 10 characters is required' USING ERRCODE = '22023';
    END IF;
    IF COALESCE(btrim(_outcome_category),'') = '' THEN
      RAISE EXCEPTION 'outcome category is required' USING ERRCODE = '22023';
    END IF;
    IF NOT COALESCE(_evidence_complete,false) THEN
      RAISE EXCEPTION 'evidence completeness must be confirmed' USING ERRCODE = '22023';
    END IF;
  END IF;
  IF _decision = 'qa_returned' AND COALESCE(length(btrim(_rationale)),0) < 10 THEN
    RAISE EXCEPTION 'return reason of at least 10 characters is required' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.complaint_closure_reviews(
    complaint_id, stage, decision, resolution_summary, rationale, outcome_category,
    final_communication_ref, evidence_complete, qa_required, reviewer_id)
  VALUES (_complaint_id,
          CASE WHEN _decision LIKE 'qa_%' THEN 'qa' ELSE 'closure' END,
          _decision, _resolution_summary, _rationale, _outcome_category,
          _final_communication_ref, COALESCE(_evidence_complete,false),
          COALESCE(_qa_required,false), _reviewer_id)
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.complaint_rfi_approve(p_rfi_id uuid, p_notes text DEFAULT NULL::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rec record;
  v_questions integer;
  v_due timestamptz;
BEGIN
  SELECT * INTO v_rec FROM public.complaint_rfis WHERE id = p_rfi_id;
  IF v_rec.id IS NULL THEN RAISE EXCEPTION 'rfi_not_found'; END IF;
  IF NOT public.can_approve_complaint_rfi(auth.uid()) THEN
    RAISE EXCEPTION 'not_authorised_to_approve_complaint_rfi';
  END IF;
  IF v_rec.approval_state <> 'pending_approval' THEN
    RAISE EXCEPTION 'rfi_not_pending_approval';
  END IF;

  SELECT count(*) INTO v_questions FROM public.complaint_rfi_items WHERE rfi_id = p_rfi_id;
  IF v_questions = 0 THEN RAISE EXCEPTION 'at_least_one_question_required'; END IF;

  v_due := COALESCE(p_due_at, v_rec.due_at);

  UPDATE public.complaint_rfis
  SET approval_state = 'dispatched',
      status = 'open',
      due_at = v_due,
      approved_at = now(),
      approved_by = auth.uid(),
      approval_notes = NULLIF(btrim(coalesce(p_notes,'')), ''),
      rejection_reason = NULL,
      dispatched_at = now(),
      raised_at = now()
  WHERE id = p_rfi_id;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value, metadata)
  VALUES (auth.uid(), 'complaint.rfi_approved', 'complaint', v_rec.complaint_id,
          jsonb_build_object('rfi_id', p_rfi_id, 'notes', p_notes, 'due_at', v_due,
                             'nominated_approver_id', v_rec.approver_id,
                             'acted_as_nominee', v_rec.approver_id IS NOT DISTINCT FROM auth.uid()),
          jsonb_build_object('licensee_id', v_rec.licensee_id));

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value, metadata)
  VALUES (auth.uid(), 'complaint.rfi_dispatched', 'complaint', v_rec.complaint_id,
          jsonb_build_object('rfi_id', p_rfi_id, 'questions', v_questions, 'due_at', v_due,
                             'recipient_licensee_id', v_rec.licensee_id, 'dispatched_at', now()),
          jsonb_build_object('licensee_id', v_rec.licensee_id));

  RETURN jsonb_build_object('ok', true, 'questions', v_questions,
                            'licensee_id', v_rec.licensee_id,
                            'complaint_id', v_rec.complaint_id, 'due_at', v_due);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_rfi_cancel(p_rfi_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_complaint uuid;
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR public.has_complaint_perm(auth.uid(), 'edit')) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;
  SELECT complaint_id INTO v_complaint FROM public.complaint_rfis WHERE id = p_rfi_id;
  IF v_complaint IS NULL THEN RAISE EXCEPTION 'rfi_not_found'; END IF;

  UPDATE public.complaint_rfis
  SET status = 'cancelled', closure_notes = NULLIF(btrim(coalesce(p_reason,'')), ''),
      closed_by = auth.uid(), closed_at = now()
  WHERE id = p_rfi_id AND status IN ('open','submitted');

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
  VALUES (auth.uid(), 'complaint.rfi_cancelled', 'complaint', v_complaint,
          jsonb_build_object('rfi_id', p_rfi_id, 'reason', p_reason));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_rfi_close(p_rfi_id uuid, p_notes text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_complaint uuid;
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR public.has_complaint_perm(auth.uid(), 'edit')) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  SELECT complaint_id INTO v_complaint FROM public.complaint_rfis WHERE id = p_rfi_id;
  IF v_complaint IS NULL THEN RAISE EXCEPTION 'rfi_not_found'; END IF;

  UPDATE public.complaint_rfis
  SET status = 'closed', closure_notes = NULLIF(btrim(coalesce(p_notes,'')), ''),
      closed_by = auth.uid(), closed_at = now()
  WHERE id = p_rfi_id;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
  VALUES (auth.uid(), 'complaint.rfi_closed', 'complaint', v_complaint,
          jsonb_build_object('rfi_id', p_rfi_id, 'notes', p_notes));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_rfi_raise(p_complaint_id uuid, p_summary text, p_due_at timestamp with time zone, p_items jsonb, p_as_draft boolean DEFAULT NULL::boolean, p_approver_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_licensee uuid;
  v_rfi uuid;
  v_item jsonb;
  v_ord integer := 0;
  v_required boolean;
  v_state text;
  v_status text;
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR public.has_complaint_perm(auth.uid(), 'edit')) THEN
    RAISE EXCEPTION 'not_authorised_to_raise_complaint_rfi';
  END IF;

  SELECT licensee_id INTO v_licensee FROM public.complaints WHERE id = p_complaint_id;
  IF v_licensee IS NULL THEN
    RAISE EXCEPTION 'complaint_has_no_linked_entity';
  END IF;

  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'at_least_one_question_required';
  END IF;

  SELECT approval_required INTO v_required FROM public.complaint_rfi_settings LIMIT 1;
  v_required := COALESCE(v_required, true);

  IF COALESCE(p_as_draft, v_required) THEN
    v_state := 'draft';
    v_status := 'draft';
  ELSE
    IF v_required THEN
      RAISE EXCEPTION 'approval_required_for_complaint_rfi';
    END IF;
    v_state := 'dispatched';
    v_status := 'open';
  END IF;

  INSERT INTO public.complaint_rfis (
    complaint_id, licensee_id, raised_by, due_at, summary, status,
    approval_state, approver_id, dispatched_at
  )
  VALUES (
    p_complaint_id, v_licensee, auth.uid(), p_due_at,
    NULLIF(btrim(coalesce(p_summary,'')), ''), v_status,
    v_state, p_approver_id,
    CASE WHEN v_state = 'dispatched' THEN now() ELSE NULL END
  )
  RETURNING id INTO v_rfi;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_ord := v_ord + 1;
    IF btrim(coalesce(v_item->>'prompt','')) = '' THEN
      RAISE EXCEPTION 'question_prompt_required';
    END IF;
    INSERT INTO public.complaint_rfi_items (rfi_id, ordinal, prompt, question_type, required)
    VALUES (
      v_rfi,
      v_ord,
      btrim(v_item->>'prompt'),
      coalesce(NULLIF(v_item->>'question_type',''), 'text'),
      coalesce((v_item->>'required')::boolean, true)
    );
  END LOOP;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value, metadata)
  VALUES (auth.uid(),
          CASE WHEN v_state = 'draft' THEN 'complaint.rfi_drafted' ELSE 'complaint.rfi_raised' END,
          'complaint', p_complaint_id,
          jsonb_build_object('rfi_id', v_rfi, 'questions', v_ord, 'due_at', p_due_at,
                             'approval_state', v_state, 'approver_id', p_approver_id),
          jsonb_build_object('licensee_id', v_licensee));

  IF v_state = 'dispatched' THEN
    INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value, metadata)
    VALUES (auth.uid(), 'complaint.rfi_dispatched', 'complaint', p_complaint_id,
            jsonb_build_object('rfi_id', v_rfi, 'questions', v_ord, 'due_at', p_due_at,
                               'approval_gate', 'disabled'),
            jsonb_build_object('licensee_id', v_licensee));
  END IF;

  RETURN v_rfi;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_rfi_reject(p_rfi_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rec record;
BEGIN
  SELECT * INTO v_rec FROM public.complaint_rfis WHERE id = p_rfi_id;
  IF v_rec.id IS NULL THEN RAISE EXCEPTION 'rfi_not_found'; END IF;
  IF NOT public.can_approve_complaint_rfi(auth.uid()) THEN
    RAISE EXCEPTION 'not_authorised_to_approve_complaint_rfi';
  END IF;
  IF v_rec.approval_state <> 'pending_approval' THEN
    RAISE EXCEPTION 'rfi_not_pending_approval';
  END IF;
  IF btrim(coalesce(p_reason,'')) = '' THEN
    RAISE EXCEPTION 'rejection_reason_required';
  END IF;

  UPDATE public.complaint_rfis
  SET approval_state = 'rejected',
      rejection_reason = btrim(p_reason),
      approved_at = NULL,
      approved_by = NULL
  WHERE id = p_rfi_id;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value, metadata)
  VALUES (auth.uid(), 'complaint.rfi_rejected', 'complaint', v_rec.complaint_id,
          jsonb_build_object('rfi_id', p_rfi_id, 'reason', btrim(p_reason)),
          jsonb_build_object('licensee_id', v_rec.licensee_id));

  RETURN jsonb_build_object('ok', true, 'drafter_id', v_rec.raised_by,
                            'complaint_id', v_rec.complaint_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_rfi_return_item(p_item_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rfi uuid;
  v_complaint uuid;
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR public.has_complaint_perm(auth.uid(), 'edit')) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;
  IF btrim(coalesce(p_reason,'')) = '' THEN
    RAISE EXCEPTION 'clarification_reason_required';
  END IF;

  SELECT i.rfi_id, r.complaint_id INTO v_rfi, v_complaint
  FROM public.complaint_rfi_items i
  JOIN public.complaint_rfis r ON r.id = i.rfi_id
  WHERE i.id = p_item_id;
  IF v_rfi IS NULL THEN RAISE EXCEPTION 'rfi_item_not_found'; END IF;

  UPDATE public.complaint_rfi_items
  SET response_status = 'returned', returned_reason = btrim(p_reason)
  WHERE id = p_item_id;

  UPDATE public.complaint_rfis
  SET status = 'open', submitted_at = NULL, submitted_by = NULL
  WHERE id = v_rfi AND status = 'submitted';

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
  VALUES (auth.uid(), 'complaint.rfi_item_returned', 'complaint', v_complaint,
          jsonb_build_object('rfi_id', v_rfi, 'item_id', p_item_id, 'reason', btrim(p_reason)));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_rfi_save_draft(p_item_id uuid, p_response_text text, p_file_upload_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rfi uuid;
  v_status text;
  v_resp uuid;
BEGIN
  SELECT i.rfi_id, r.status INTO v_rfi, v_status
  FROM public.complaint_rfi_items i
  JOIN public.complaint_rfis r ON r.id = i.rfi_id
  WHERE i.id = p_item_id;

  IF v_rfi IS NULL THEN RAISE EXCEPTION 'rfi_item_not_found'; END IF;
  IF NOT public.is_complaint_rfi_entity_user(v_rfi) THEN
    RAISE EXCEPTION 'not_authorised_for_this_entity';
  END IF;
  IF v_status <> 'open' THEN RAISE EXCEPTION 'rfi_not_open'; END IF;
  IF EXISTS (SELECT 1 FROM public.complaint_rfi_items WHERE id = p_item_id AND response_status = 'responded') THEN
    RAISE EXCEPTION 'question_already_submitted';
  END IF;

  SELECT id INTO v_resp FROM public.complaint_rfi_responses
  WHERE rfi_item_id = p_item_id AND is_draft LIMIT 1;

  IF v_resp IS NULL THEN
    INSERT INTO public.complaint_rfi_responses (rfi_item_id, response_text, file_upload_ids, is_draft, submitted_by)
    VALUES (p_item_id, NULLIF(btrim(coalesce(p_response_text,'')), ''), coalesce(p_file_upload_ids, '{}'), true, auth.uid())
    RETURNING id INTO v_resp;
  ELSE
    UPDATE public.complaint_rfi_responses
    SET response_text = NULLIF(btrim(coalesce(p_response_text,'')), ''),
        file_upload_ids = coalesce(p_file_upload_ids, '{}'),
        submitted_by = auth.uid()
    WHERE id = v_resp;
  END IF;

  UPDATE public.complaint_rfi_items
  SET response_status = 'draft'
  WHERE id = p_item_id AND response_status IN ('pending','returned','draft');

  RETURN v_resp;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_rfi_set_approval_required(p_required boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_old boolean;
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR public.has_role(auth.uid(), 'admin')) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  SELECT approval_required INTO v_old FROM public.complaint_rfi_settings LIMIT 1;

  IF v_old IS NULL THEN
    INSERT INTO public.complaint_rfi_settings (approval_required, updated_by)
    VALUES (COALESCE(p_required, true), auth.uid());
  ELSE
    UPDATE public.complaint_rfi_settings
    SET approval_required = COALESCE(p_required, true), updated_by = auth.uid();
  END IF;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value)
  VALUES (auth.uid(), 'complaint.rfi_approval_gate_changed', 'complaint_rfi_settings', NULL,
          jsonb_build_object('approval_required', v_old),
          jsonb_build_object('approval_required', COALESCE(p_required, true)));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_rfi_submit(p_rfi_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rec record;
  v_missing text[] := '{}';
  v_item record;
  v_draft record;
  v_submitted integer := 0;
  v_file uuid;
BEGIN
  SELECT * INTO v_rec FROM public.complaint_rfis WHERE id = p_rfi_id;
  IF v_rec.id IS NULL THEN RAISE EXCEPTION 'rfi_not_found'; END IF;
  IF NOT public.is_complaint_rfi_entity_user(p_rfi_id) THEN
    RAISE EXCEPTION 'not_authorised_for_this_entity';
  END IF;
  IF v_rec.status <> 'open' THEN RAISE EXCEPTION 'rfi_not_open'; END IF;

  -- Gate: every mandatory question must have a usable draft answer.
  FOR v_item IN
    SELECT i.*, d.response_text, d.file_upload_ids
    FROM public.complaint_rfi_items i
    LEFT JOIN public.complaint_rfi_responses d ON d.rfi_item_id = i.id AND d.is_draft
    WHERE i.rfi_id = p_rfi_id AND i.response_status <> 'responded'
    ORDER BY i.ordinal
  LOOP
    IF v_item.required THEN
      IF v_item.question_type IN ('text','both')
         AND btrim(coalesce(v_item.response_text,'')) = '' THEN
        v_missing := v_missing || ('Q' || v_item.ordinal || ': written response required');
      END IF;
      IF v_item.question_type IN ('document','both')
         AND coalesce(array_length(v_item.file_upload_ids, 1), 0) = 0 THEN
        v_missing := v_missing || ('Q' || v_item.ordinal || ': supporting document required');
      END IF;
    END IF;
  END LOOP;

  IF array_length(v_missing, 1) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'missing', to_jsonb(v_missing));
  END IF;

  -- Lock drafts as submitted responses; link documents to complaint evidence.
  FOR v_draft IN
    SELECT d.id, d.rfi_item_id, d.file_upload_ids
    FROM public.complaint_rfi_responses d
    JOIN public.complaint_rfi_items i ON i.id = d.rfi_item_id
    WHERE i.rfi_id = p_rfi_id AND d.is_draft
  LOOP
    UPDATE public.complaint_rfi_responses
    SET is_draft = false, submitted_at = now(), submitted_by = auth.uid()
    WHERE id = v_draft.id;

    UPDATE public.complaint_rfi_items SET response_status = 'responded' WHERE id = v_draft.rfi_item_id;
    v_submitted := v_submitted + 1;

    INSERT INTO public.complaint_evidence (complaint_id, file_upload_id, label, description, uploaded_by, finalized_at)
    SELECT v_rec.complaint_id, f, 'RFI response document',
           'Submitted via complaint information request', auth.uid(), now()
    FROM unnest(coalesce(v_draft.file_upload_ids, '{}'::uuid[])) AS f
    WHERE NOT EXISTS (
      SELECT 1 FROM public.complaint_evidence ce
      WHERE ce.complaint_id = v_rec.complaint_id AND ce.file_upload_id = f
    );
  END LOOP;

  UPDATE public.complaint_rfis
  SET status = 'submitted', submitted_at = now(), submitted_by = auth.uid()
  WHERE id = p_rfi_id;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value, metadata)
  VALUES (auth.uid(), 'complaint.rfi_response_submitted', 'complaint', v_rec.complaint_id,
          jsonb_build_object('rfi_id', p_rfi_id, 'answers', v_submitted),
          jsonb_build_object('licensee_id', v_rec.licensee_id));

  RETURN jsonb_build_object('ok', true, 'answers', v_submitted);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_rfi_submit_for_approval(p_rfi_id uuid, p_approver_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rec record;
BEGIN
  SELECT * INTO v_rec FROM public.complaint_rfis WHERE id = p_rfi_id;
  IF v_rec.id IS NULL THEN RAISE EXCEPTION 'rfi_not_found'; END IF;
  IF v_rec.approval_state NOT IN ('draft','rejected') THEN
    RAISE EXCEPTION 'rfi_not_in_draft_state';
  END IF;
  IF NOT (
    public.is_super_admin(auth.uid())
    OR (public.has_complaint_perm(auth.uid(), 'edit')
        AND (v_rec.raised_by = auth.uid() OR public.can_approve_complaint_rfi(auth.uid())))
  ) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.complaint_rfi_items WHERE rfi_id = p_rfi_id) THEN
    RAISE EXCEPTION 'at_least_one_question_required';
  END IF;

  UPDATE public.complaint_rfis
  SET approval_state = 'pending_approval',
      approver_id = COALESCE(p_approver_id, approver_id),
      submitted_for_approval_at = now(),
      submitted_for_approval_by = auth.uid(),
      rejection_reason = NULL
  WHERE id = p_rfi_id;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value, metadata)
  VALUES (auth.uid(), 'complaint.rfi_approval_requested', 'complaint', v_rec.complaint_id,
          jsonb_build_object('rfi_id', p_rfi_id,
                             'approver_id', COALESCE(p_approver_id, v_rec.approver_id),
                             'nominated', p_approver_id IS NOT NULL),
          jsonb_build_object('licensee_id', v_rec.licensee_id));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_rfi_update_draft(p_rfi_id uuid, p_summary text, p_due_at timestamp with time zone, p_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rec record;
  v_before jsonb;
  v_after jsonb;
  v_item jsonb;
  v_ord integer := 0;
BEGIN
  SELECT * INTO v_rec FROM public.complaint_rfis WHERE id = p_rfi_id;
  IF v_rec.id IS NULL THEN RAISE EXCEPTION 'rfi_not_found'; END IF;
  IF v_rec.approval_state NOT IN ('draft','pending_approval','rejected') THEN
    RAISE EXCEPTION 'rfi_already_dispatched';
  END IF;
  IF NOT (
    public.is_super_admin(auth.uid())
    OR public.can_approve_complaint_rfi(auth.uid())
    OR (v_rec.raised_by = auth.uid() AND public.has_complaint_perm(auth.uid(), 'edit'))
  ) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'at_least_one_question_required';
  END IF;

  SELECT jsonb_build_object(
           'summary', v_rec.summary,
           'due_at', v_rec.due_at,
           'items', COALESCE(jsonb_agg(jsonb_build_object(
             'ordinal', i.ordinal, 'prompt', i.prompt,
             'question_type', i.question_type, 'required', i.required)
             ORDER BY i.ordinal), '[]'::jsonb))
    INTO v_before
  FROM public.complaint_rfi_items i WHERE i.rfi_id = p_rfi_id;

  DELETE FROM public.complaint_rfi_items WHERE rfi_id = p_rfi_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_ord := v_ord + 1;
    IF btrim(coalesce(v_item->>'prompt','')) = '' THEN
      RAISE EXCEPTION 'question_prompt_required';
    END IF;
    INSERT INTO public.complaint_rfi_items (rfi_id, ordinal, prompt, question_type, required)
    VALUES (p_rfi_id, v_ord, btrim(v_item->>'prompt'),
            coalesce(NULLIF(v_item->>'question_type',''), 'text'),
            coalesce((v_item->>'required')::boolean, true));
  END LOOP;

  UPDATE public.complaint_rfis
  SET summary = NULLIF(btrim(coalesce(p_summary,'')), ''),
      due_at = p_due_at
  WHERE id = p_rfi_id;

  SELECT jsonb_build_object(
           'summary', NULLIF(btrim(coalesce(p_summary,'')), ''),
           'due_at', p_due_at,
           'items', COALESCE(jsonb_agg(jsonb_build_object(
             'ordinal', i.ordinal, 'prompt', i.prompt,
             'question_type', i.question_type, 'required', i.required)
             ORDER BY i.ordinal), '[]'::jsonb))
    INTO v_after
  FROM public.complaint_rfi_items i WHERE i.rfi_id = p_rfi_id;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value, metadata)
  VALUES (auth.uid(), 'complaint.rfi_modified', 'complaint', v_rec.complaint_id,
          v_before, v_after,
          jsonb_build_object('rfi_id', p_rfi_id, 'licensee_id', v_rec.licensee_id,
                             'modified_by_approver', public.can_approve_complaint_rfi(auth.uid())));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_sla_status(_created_at timestamp with time zone, _sla_due_at timestamp with time zone, _sla_days integer, _resolved_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  due timestamptz;
  ms_left double precision;
  days_left double precision;
BEGIN
  IF _sla_due_at IS NOT NULL THEN
    due := _sla_due_at;
  ELSIF _created_at IS NOT NULL AND _sla_days IS NOT NULL THEN
    due := _created_at + make_interval(days => _sla_days);
  ELSE
    due := NULL;
  END IF;

  IF _resolved_at IS NOT NULL THEN
    IF due IS NOT NULL AND _resolved_at > due THEN
      RETURN 'resolved_late';
    END IF;
    RETURN 'resolved_on_time';
  END IF;

  IF due IS NULL THEN
    RETURN 'unknown';
  END IF;

  ms_left := EXTRACT(EPOCH FROM (due - now()));
  IF ms_left < 0 THEN RETURN 'breached'; END IF;
  days_left := ms_left / 86400.0;
  IF days_left <= 2 THEN RETURN 'at_risk'; END IF;
  IF _sla_days IS NOT NULL AND _sla_days > 0 AND (days_left / _sla_days) <= 0.25 THEN
    RETURN 'at_risk';
  END IF;
  RETURN 'on_track';
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaint_task_create(_complaint_id uuid, _title text, _description text DEFAULT NULL::text, _due_date date DEFAULT NULL::date, _owner_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _id uuid; _after jsonb;
BEGIN
  _uid := public.conduct_require('complaint_management','edit');
  IF coalesce(length(btrim(_title)),0) = 0 THEN
    RAISE EXCEPTION 'Please describe the work item' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.complaints WHERE id=_complaint_id) THEN
    RAISE EXCEPTION 'Complaint not found' USING ERRCODE='P0002';
  END IF;
  INSERT INTO public.complaint_investigation_tasks
    (complaint_id, title, description, due_date, owner_id, created_by)
  VALUES (_complaint_id, btrim(_title), nullif(btrim(coalesce(_description,'')),''),
          _due_date, coalesce(_owner_id,_uid), _uid)
  RETURNING id INTO _id;
  SELECT to_jsonb(t) INTO _after FROM public.complaint_investigation_tasks t WHERE t.id=_id;
  PERFORM public.log_compliance_audit('CREATE','complaint_investigation_task',_id,NULL,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.complaint_task_set_status(_task_id uuid, _status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb;
BEGIN
  _uid := public.conduct_require('complaint_management','edit');
  IF _status NOT IN ('pending','in_progress','completed','cancelled') THEN
    RAISE EXCEPTION 'Unsupported work item status: %', _status USING ERRCODE='22023';
  END IF;
  SELECT to_jsonb(t) INTO _before FROM public.complaint_investigation_tasks t WHERE t.id=_task_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Work item not found' USING ERRCODE='P0002'; END IF;
  UPDATE public.complaint_investigation_tasks SET
    status = _status,
    completed_at = CASE WHEN _status='completed' THEN now() ELSE NULL END,
    completed_by = CASE WHEN _status='completed' THEN _uid ELSE NULL END,
    updated_at = now()
  WHERE id=_task_id RETURNING to_jsonb(complaint_investigation_tasks) INTO _after;
  PERFORM public.log_compliance_audit('UPDATE','complaint_investigation_task',_task_id,_before,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.complaints_analytics(_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_is_internal boolean; v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  v_is_internal := public.has_complaint_perm(v_uid,'view_all') OR public.has_complaint_perm(v_uid,'triage');
  IF NOT v_is_internal THEN RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501'; END IF;

  WITH scope AS (
    SELECT c.*, public.complaint_sla_status(c.created_at,c.sla_due_at,c.sla_days,c.resolved_at) AS sla_status
      FROM public.complaints c
     WHERE (NULLIF(_filters->>'date_from','') IS NULL OR c.created_at >= (_filters->>'date_from')::timestamptz)
       AND (NULLIF(_filters->>'date_to','')   IS NULL OR c.created_at <= (_filters->>'date_to')::timestamptz)
       AND (NULLIF(_filters->>'regulator_id','') IS NULL OR c.regulator_id = (_filters->>'regulator_id')::uuid)
       AND (NULLIF(_filters->>'severity','') IS NULL OR c.severity = _filters->>'severity')
       AND (NULLIF(_filters->>'complaint_type_id','') IS NULL OR c.complaint_type_id = (_filters->>'complaint_type_id')::uuid)
  )
  SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM scope),
    'open', (SELECT count(*) FROM scope WHERE status IN ('submitted','under_investigation')),
    'resolved_or_closed', (SELECT count(*) FROM scope WHERE status IN ('resolved','closed')),
    'avg_resolve_hours', (SELECT COALESCE(ROUND(EXTRACT(EPOCH FROM AVG(resolved_at-created_at))/3600.0,1),0) FROM scope WHERE resolved_at IS NOT NULL),
    'breached', (SELECT count(*) FROM scope WHERE sla_status='breached'),
    'at_risk',  (SELECT count(*) FROM scope WHERE sla_status='at_risk'),
    'on_track', (SELECT count(*) FROM scope WHERE sla_status='on_track'),
    'by_status',   (SELECT COALESCE(jsonb_object_agg(status,cnt),'{}'::jsonb) FROM (SELECT status,count(*) cnt FROM scope GROUP BY status) s),
    'by_severity', (SELECT COALESCE(jsonb_object_agg(severity,cnt),'{}'::jsonb) FROM (SELECT severity,count(*) cnt FROM scope GROUP BY severity) s),
    'by_type', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('type_id',complaint_type_id,'name',name,'count',cnt) ORDER BY cnt DESC),'[]'::jsonb)
        FROM (SELECT s.complaint_type_id,t.name,count(*) cnt FROM scope s LEFT JOIN public.complaint_types t ON t.id=s.complaint_type_id GROUP BY s.complaint_type_id,t.name) x
    ),
    'trend', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('day',day,'count',cnt) ORDER BY day),'[]'::jsonb)
        FROM (SELECT date_trunc('day',created_at)::date AS day,count(*) cnt FROM scope GROUP BY 1) d
    )
  ) INTO v_result;
  RETURN v_result;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaints_dashboard_counts(_scope jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_internal boolean;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  v_is_internal := public.has_complaint_perm(v_uid,'view_all') OR public.has_complaint_perm(v_uid,'triage');
  IF NOT v_is_internal THEN RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501'; END IF;

  WITH scope AS (
    SELECT c.*, public.complaint_sla_status(c.created_at,c.sla_due_at,c.sla_days,c.resolved_at) AS sla_status
      FROM public.complaints c
     WHERE (NULLIF(_scope->>'regulator_id','') IS NULL OR c.regulator_id = (_scope->>'regulator_id')::uuid)
       AND (NULLIF(_scope->>'licensee_id','') IS NULL OR c.licensee_id = (_scope->>'licensee_id')::uuid)
       AND (NULLIF(_scope->>'date_from','') IS NULL OR c.created_at >= (_scope->>'date_from')::timestamptz)
       AND (NULLIF(_scope->>'date_to','')   IS NULL OR c.created_at <= (_scope->>'date_to')::timestamptz)
  )
  SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM scope),
    'open',  (SELECT count(*) FROM scope WHERE status NOT IN ('closed','resolved')),
    'critical', (SELECT count(*) FROM scope WHERE severity = 'critical'),
    'under_investigation', (SELECT count(*) FROM scope WHERE status = 'under_investigation'),
    'closed', (SELECT count(*) FROM scope WHERE status IN ('closed','resolved')),
    'breached', (SELECT count(*) FROM scope WHERE sla_status = 'breached'),
    'by_licensee', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('licensee_id',licensee_id,'count',cnt) ORDER BY cnt DESC), '[]'::jsonb)
        FROM (SELECT licensee_id, count(*) cnt FROM scope WHERE licensee_id IS NOT NULL GROUP BY licensee_id LIMIT 20) s
    ),
    'trend', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('day', d::text, 'count', cnt) ORDER BY d), '[]'::jsonb)
        FROM (
          SELECT date_trunc('day', created_at)::date d, count(*) cnt
            FROM scope
           WHERE created_at >= now() - interval '90 days'
           GROUP BY 1
        ) s
    )
  ) INTO v_result;

  RETURN v_result;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complete_appeal_hearing(_appeal_id uuid, _minutes text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_appeal record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF NOT (public.has_permission(v_uid,'license_appeals','decide')
          OR public.has_permission(v_uid,'license_appeals','edit')) THEN
    RETURN jsonb_build_object('error','You are not allowed to record hearing minutes','code','FORBIDDEN','http',403);
  END IF;

  SELECT * INTO v_appeal FROM public.license_appeals WHERE id = _appeal_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Appeal not found','code','NOT_FOUND','http',404);
  END IF;
  IF v_appeal.hearing_date IS NULL THEN
    RETURN jsonb_build_object('error','No hearing has been scheduled','code','NO_HEARING','http',409);
  END IF;

  UPDATE public.license_appeals
     SET hearing_notes = _minutes,
         hearing_completed_at = now(),
         updated_at = now()
   WHERE id = _appeal_id;

  INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id, metadata)
  VALUES (_appeal_id, 'hearing_completed', 'Hearing completed and minutes recorded', v_uid, '{}'::jsonb);

  RETURN jsonb_build_object('success', true, 'http', 200);
END; $function$
;
CREATE OR REPLACE FUNCTION public.complete_appeal_hearing(_appeal_id uuid, _minutes text, _amend boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_appeal record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF NOT (public.has_permission(v_uid,'license_appeals','decide')
          OR public.has_permission(v_uid,'license_appeals','edit')) THEN
    RETURN jsonb_build_object('error','You are not allowed to record hearing minutes','code','FORBIDDEN','http',403);
  END IF;

  SELECT * INTO v_appeal FROM public.license_appeals WHERE id = _appeal_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Appeal not found','code','NOT_FOUND','http',404);
  END IF;
  IF v_appeal.hearing_date IS NULL THEN
    RETURN jsonb_build_object('error','No hearing has been scheduled','code','NO_HEARING','http',409);
  END IF;

  IF _minutes IS NULL OR length(btrim(_minutes)) < 10 THEN
    RETURN jsonb_build_object('error','Record the hearing minutes first (at least 10 characters)','code','MINUTES_REQUIRED','http',422);
  END IF;

  -- Already completed: only an explicit amendment may write again.
  IF v_appeal.hearing_completed_at IS NOT NULL AND NOT COALESCE(_amend, false) THEN
    RETURN jsonb_build_object(
      'error','This hearing has already been marked complete',
      'code','ALREADY_COMPLETED','http',409,
      'completed_at', v_appeal.hearing_completed_at
    );
  END IF;

  IF v_appeal.hearing_completed_at IS NOT NULL THEN
    IF btrim(COALESCE(v_appeal.hearing_notes,'')) = btrim(_minutes) THEN
      RETURN jsonb_build_object('error','The minutes are unchanged — nothing to amend','code','NO_CHANGE','http',409);
    END IF;

    UPDATE public.license_appeals
       SET hearing_notes = _minutes,
           updated_at = now()
     WHERE id = _appeal_id;

    INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id, metadata)
    VALUES (_appeal_id, 'hearing_minutes_amended', 'Hearing minutes amended', v_uid, '{}'::jsonb);

    RETURN jsonb_build_object('success', true, 'amended', true, 'http', 200,
                              'completed_at', v_appeal.hearing_completed_at);
  END IF;

  UPDATE public.license_appeals
     SET hearing_notes = _minutes,
         hearing_completed_at = now(),
         updated_at = now()
   WHERE id = _appeal_id;

  INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id, metadata)
  VALUES (_appeal_id, 'hearing_completed', 'Hearing completed and minutes recorded', v_uid, '{}'::jsonb);

  RETURN jsonb_build_object('success', true, 'amended', false, 'http', 200);
END; $function$
;
CREATE OR REPLACE FUNCTION public.complete_or_get_application_payment(_application_id uuid, _amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_payment record;
  v_amount numeric := COALESCE(_amount, 0);
  v_txn_ref text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object(
      'action', 'block',
      'code', 'UNAUTHORIZED',
      'message', 'You must be signed in.'
    );
  END IF;

  SELECT id, applicant_id
    INTO v_app
    FROM public.applications
   WHERE id = _application_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'block',
      'code', 'NOT_FOUND',
      'message', 'Application not found.'
    );
  END IF;

  IF v_app.applicant_id <> v_uid
     AND NOT public.has_role(v_uid, 'super_admin'::app_role)
     AND NOT public.has_role(v_uid, 'admin'::app_role) THEN
    RETURN jsonb_build_object(
      'action', 'block',
      'code', 'FORBIDDEN',
      'message', 'You do not have access to this application.'
    );
  END IF;

  SELECT p.id, p.status, p.amount, p.transaction_ref, p.receipt_number, p.currency, p.paid_at, p.created_at
    INTO v_payment
    FROM public.payments p
   WHERE p.application_id = _application_id
     AND lower(p.status) IN ('completed', 'success', 'paid')
   ORDER BY p.paid_at DESC NULLS LAST, p.created_at DESC
   LIMIT 1
   FOR UPDATE;

  IF v_payment.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'action', 'paid',
      'payment_id', v_payment.id,
      'status', v_payment.status,
      'amount', v_payment.amount,
      'transaction_ref', v_payment.transaction_ref,
      'receipt_number', v_payment.receipt_number,
      'currency', v_payment.currency,
      'paid_at', v_payment.paid_at
    );
  END IF;

  SELECT p.id, p.status, p.amount, p.transaction_ref, p.receipt_number, p.currency, p.paid_at, p.created_at
    INTO v_payment
    FROM public.payments p
   WHERE p.application_id = _application_id
     AND lower(p.status) IN ('pending', 'processing', 'initiated')
   ORDER BY p.created_at DESC
   LIMIT 1
   FOR UPDATE;

  IF v_payment.id IS NULL THEN
    v_txn_ref := 'TXN-' || EXTRACT(EPOCH FROM clock_timestamp())::bigint || '-' || upper(substr(md5(random()::text), 1, 6));

    INSERT INTO public.payments (
      user_id,
      application_id,
      amount,
      status,
      payment_method,
      transaction_ref
    ) VALUES (
      v_uid,
      _application_id,
      v_amount,
      'initiated',
      'online',
      v_txn_ref
    )
    RETURNING id, status, amount, transaction_ref, receipt_number, currency, paid_at, created_at
      INTO v_payment;
  END IF;

  BEGIN
    UPDATE public.payments p
       SET status = 'completed',
           paid_at = COALESCE(p.paid_at, now()),
           amount = COALESCE(NULLIF(p.amount, 0), v_amount, p.amount)
     WHERE p.id = v_payment.id
     RETURNING p.id, p.status, p.amount, p.transaction_ref, p.receipt_number, p.currency, p.paid_at, p.created_at
      INTO v_payment;
  EXCEPTION WHEN unique_violation THEN
    SELECT p.id, p.status, p.amount, p.transaction_ref, p.receipt_number, p.currency, p.paid_at, p.created_at
      INTO v_payment
      FROM public.payments p
     WHERE p.application_id = _application_id
       AND lower(p.status) IN ('completed', 'success', 'paid')
     ORDER BY p.paid_at DESC NULLS LAST, p.created_at DESC
     LIMIT 1;

    IF v_payment.id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'action', 'paid',
        'payment_id', v_payment.id,
        'status', v_payment.status,
        'amount', v_payment.amount,
        'transaction_ref', v_payment.transaction_ref,
        'receipt_number', v_payment.receipt_number,
        'currency', v_payment.currency,
        'paid_at', v_payment.paid_at
      );
    END IF;

    RAISE;
  END;

  RETURN jsonb_build_object(
    'action', 'completed',
    'payment_id', v_payment.id,
    'status', v_payment.status,
    'amount', v_payment.amount,
    'transaction_ref', v_payment.transaction_ref,
    'receipt_number', v_payment.receipt_number,
    'currency', v_payment.currency,
    'paid_at', v_payment.paid_at
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complete_vulnerability_review(_complaint_id uuid, _decision text, _category text DEFAULT NULL::text, _notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '28000';
  END IF;
  IF _decision NOT IN ('confirmed', 'not_applicable') THEN
    RAISE EXCEPTION 'invalid_decision' USING HINT = 'decision must be confirmed or not_applicable';
  END IF;
  IF NOT (public.has_role(v_uid, 'super_admin'::app_role)
          OR public.has_role(v_uid, 'admin'::app_role)
          OR EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.regulator_id IS NOT NULL)) THEN
    RAISE EXCEPTION 'insufficient_privilege' USING ERRCODE = '42501';
  END IF;

  IF _decision = 'not_applicable' THEN
    UPDATE public.complaints
      SET vulnerability_indicator = FALSE,
          vulnerability_review_state = 'not_applicable',
          vulnerability_notes = NULL,
          vulnerability_category = NULL,
          updated_at = now()
    WHERE id = _complaint_id;
  ELSE
    IF COALESCE(btrim(_category), '') = '' AND COALESCE(btrim(_notes), '') = '' THEN
      RAISE EXCEPTION 'category_or_notes_required';
    END IF;
    UPDATE public.complaints
      SET vulnerability_indicator = TRUE,
          vulnerability_review_state = 'confirmed',
          vulnerability_category = NULLIF(btrim(_category), ''),
          vulnerability_notes = NULLIF(btrim(_notes), ''),
          updated_at = now()
    WHERE id = _complaint_id;
  END IF;

  INSERT INTO public.audit_logs (action, entity_type, entity_id, user_id, details, created_at)
  VALUES (
    'complaint.vulnerability_review_completed',
    'complaint',
    _complaint_id,
    v_uid,
    jsonb_build_object('decision', _decision, 'category', _category, 'notes_provided', _notes IS NOT NULL),
    now()
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.compliance_return_acknowledge(_return_id uuid, _ack_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _before jsonb; _after jsonb;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;
  SELECT to_jsonb(r) INTO _before FROM public.compliance_returns r WHERE r.id=_return_id;
  IF _before IS NULL THEN
    RAISE EXCEPTION 'Return not found' USING ERRCODE='P0002';
  END IF;
  IF NOT public.compliance_return_can_file(_uid, nullif(_before->>'license_id','')::uuid,
                                           nullif(_before->>'on_behalf_of_licensee_id','')::uuid) THEN
    RAISE EXCEPTION 'You are not entitled to file this return' USING ERRCODE='42501';
  END IF;
  IF coalesce(length(btrim(coalesce(_ack_text,''))),0) = 0 THEN
    RAISE EXCEPTION 'Acknowledgement text is required' USING ERRCODE='22023';
  END IF;

  UPDATE public.compliance_returns SET
    ack_by = _uid, ack_at = now(), ack_text = left(btrim(_ack_text), 4000), updated_at = now()
  WHERE id=_return_id RETURNING to_jsonb(compliance_returns) INTO _after;

  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.compliance_return_can_file(_user_id uuid, _license_id uuid, _on_behalf_of uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    _user_id IS NOT NULL
    AND (
      public.has_permission(_user_id, 'returns_management', 'edit')
      OR public.is_super_admin(_user_id)
      OR (
        _on_behalf_of IS NULL
        AND (
          EXISTS (SELECT 1 FROM public.entity_user_access a WHERE a.user_id = _user_id)
          OR EXISTS (SELECT 1 FROM public.entity_user_memberships m WHERE m.user_id = _user_id)
        )
      )
      OR (
        _on_behalf_of IS NOT NULL
        AND (
          EXISTS (
            SELECT 1 FROM public.entity_user_access a
            WHERE a.user_id = _user_id AND a.entity_id = _on_behalf_of
          )
          OR EXISTS (
            SELECT 1 FROM public.entity_user_memberships m
            WHERE m.user_id = _user_id AND m.entity_id = _on_behalf_of
          )
        )
      )
    );
$function$
;
CREATE OR REPLACE FUNCTION public.compliance_return_review_decision(_return_id uuid, _decision text, _comments text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _before jsonb; _after jsonb;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;
  IF NOT (public.has_permission(_uid,'returns_management','review')
          OR public.has_permission(_uid,'returns_management','edit')
          OR public.is_super_admin(_uid)) THEN
    RAISE EXCEPTION 'Returns review permission required' USING ERRCODE='42501';
  END IF;
  IF _decision NOT IN ('accepted','revision_requested','rejected','under_review') THEN
    RAISE EXCEPTION 'Unsupported review decision: %', _decision USING ERRCODE='22023';
  END IF;
  IF _decision <> 'under_review' AND coalesce(length(btrim(_comments)),0) < 10 THEN
    RAISE EXCEPTION 'Review comments required (min 10 characters)' USING ERRCODE='22023';
  END IF;
  SELECT to_jsonb(r) INTO _before FROM public.compliance_returns r WHERE r.id=_return_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Return not found' USING ERRCODE='P0002'; END IF;
  IF _before->>'status' = 'draft' THEN
    RAISE EXCEPTION 'A draft return cannot be reviewed' USING ERRCODE='22023';
  END IF;
  UPDATE public.compliance_returns SET
    status = _decision, reviewer_id = _uid, reviewed_at = now(),
    reviewer_comments = nullif(btrim(coalesce(_comments,'')),''), updated_at = now()
  WHERE id=_return_id RETURNING to_jsonb(compliance_returns) INTO _after;
  PERFORM public.log_compliance_audit(
    (CASE WHEN _decision='accepted' THEN 'APPROVE' WHEN _decision='rejected' THEN 'REJECT'
         ELSE 'WORKFLOW_TRANSITION' END)::compliance_audit_action,
    'compliance_return', _return_id::text, _before, _after, _comments::text);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.compliance_return_save_draft(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _id uuid; _before jsonb; _after jsonb; _on_behalf uuid;
        _suppress boolean := coalesce((_payload->>'_suppress_audit')::boolean, false);
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;
  _id := nullif(_payload->>'return_id','')::uuid;
  _on_behalf := nullif(_payload->>'on_behalf_of_licensee_id','')::uuid;

  IF _id IS NOT NULL THEN
    SELECT to_jsonb(r) INTO _before FROM public.compliance_returns r WHERE r.id=_id;
    IF _before IS NULL THEN RAISE EXCEPTION 'Return not found' USING ERRCODE='P0002'; END IF;
    IF _before->>'status' IN ('accepted','under_review') THEN
      RAISE EXCEPTION 'This return can no longer be edited (status %)', _before->>'status' USING ERRCODE='22023';
    END IF;
    IF NOT public.compliance_return_can_file(_uid, nullif(_before->>'license_id','')::uuid,
                                             nullif(_before->>'on_behalf_of_licensee_id','')::uuid) THEN
      RAISE EXCEPTION 'You are not entitled to file this return' USING ERRCODE='42501';
    END IF;
    UPDATE public.compliance_returns SET
      form_data = coalesce(_payload->'form_data', form_data),
      status = 'draft',
      updated_at = now()
    WHERE id=_id RETURNING to_jsonb(compliance_returns) INTO _after;
  ELSE
    IF NOT public.compliance_return_can_file(_uid, nullif(_payload->>'license_id','')::uuid, _on_behalf) THEN
      RAISE EXCEPTION 'You are not entitled to file returns for this entity' USING ERRCODE='42501';
    END IF;
    INSERT INTO public.compliance_returns (
      return_config_id, license_id, submitter_id, on_behalf_of_licensee_id,
      period_start, period_end, due_date, form_data, status
    ) VALUES (
      nullif(_payload->>'return_config_id','')::uuid,
      nullif(_payload->>'license_id','')::uuid,
      _uid, _on_behalf,
      (_payload->>'period_start')::date,
      (_payload->>'period_end')::date,
      (_payload->>'due_date')::date,
      coalesce(_payload->'form_data','{}'::jsonb),
      'draft'
    ) RETURNING id INTO _id;
    SELECT to_jsonb(r) INTO _after FROM public.compliance_returns r WHERE r.id=_id;
  END IF;

  IF NOT _suppress THEN
    PERFORM public.log_compliance_audit(
      (CASE WHEN _before IS NULL THEN 'CREATE' ELSE 'UPDATE' END)::compliance_audit_action,
      'compliance_return', _id::text, _before, _after, NULL::text);
  END IF;
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.compliance_return_submit(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _id uuid; _before jsonb; _after jsonb; _draft jsonb;
        _existing jsonb; _p jsonb := _payload;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;

  SELECT to_jsonb(r) INTO _before FROM public.compliance_returns r
   WHERE r.id = nullif(_payload->>'return_id','')::uuid;

  -- Submitting an already-saved draft may omit form_data: reuse what is stored.
  IF coalesce(_p->'form_data','{}'::jsonb) = '{}'::jsonb AND _before IS NOT NULL THEN
    _existing := coalesce(_before->'form_data','{}'::jsonb);
    _p := _p || jsonb_build_object('form_data', _existing);
  END IF;

  IF coalesce(_p->'form_data','{}'::jsonb) = '{}'::jsonb THEN
    RAISE EXCEPTION 'A return cannot be submitted with no data' USING ERRCODE='22023';
  END IF;

  _draft := public.compliance_return_save_draft(_p || jsonb_build_object('_suppress_audit', true));
  _id := (_draft->>'id')::uuid;

  UPDATE public.compliance_returns SET
    status = 'submitted', submitted_at = now(), updated_at = now()
  WHERE id=_id RETURNING to_jsonb(compliance_returns) INTO _after;

  PERFORM public.log_compliance_audit(
    'WORKFLOW_TRANSITION'::compliance_audit_action,
    'compliance_return', _id::text, _before, _after, 'Return submitted by filer'::text);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_action_available_actions(_action_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _s record; _uid uuid := auth.uid(); _out jsonb := '[]'::jsonb; _reviewer boolean;
BEGIN
  IF _uid IS NULL THEN RETURN _out; END IF;
  SELECT * INTO _s FROM public.v_conduct_action_state WHERE id = _action_id;
  IF _s IS NULL OR _s.is_terminal THEN RETURN _out; END IF;
  IF NOT public.has_permission(_uid, 'market_conduct', 'edit') THEN RETURN _out; END IF;
  _reviewer := public.has_permission(_uid, 'market_conduct', 'approve')
            OR public.has_permission(_uid, 'market_conduct', 'edit');

  IF _s.assigned_to IS NULL THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','ASSIGN','label','Assign owner','variant','default','enabled',true,'blocked_reason',NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','assigned_to','label','Responsible officer','type','user','required',true),
        jsonb_build_object('name','assigned_team','label','Team','type','text','required',false))));
  END IF;

  IF _s.status = 'open' AND _s.assigned_to IS NOT NULL THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','START','label','Start remediation','variant','default','enabled',true,'blocked_reason',NULL,
      'inputs','[]'::jsonb));
  END IF;

  IF _s.status IN ('open','in_progress','returned') THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','SUBMIT_EVIDENCE','label','Submit remediation evidence','variant','default','enabled',true,'blocked_reason',NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','evidence_summary','label','What has been done','type','textarea','required',true,'min_length',20))));
  END IF;

  IF _s.status = 'under_review' AND _reviewer THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','COMPLETE','label','Accept as satisfied / complete','variant','default','enabled',
      (_s.evidence_status <> 'outstanding'),
      'blocked_reason', CASE WHEN _s.evidence_status = 'outstanding' THEN 'Remediation evidence must be submitted first' ELSE NULL END,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','outcome','label','Outcome','type','text','required',true),
        jsonb_build_object('name','completion_notes','label','Review notes','type','textarea','required',true,'min_length',10))));

    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','RETURN','label','Return for more information','variant','outline','enabled',true,'blocked_reason',NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','reason','label','What is still required','type','textarea','required',true,'min_length',10))));

    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','ESCALATE','label','Unsatisfactory — escalate','variant','outline','enabled',true,'blocked_reason',NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','reason','label','Escalation rationale','type','textarea','required',true,'min_length',20))));
  END IF;

  IF _s.status IN ('open','in_progress','returned','escalated') AND _s.is_overdue THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','ESCALATE','label','Escalate overdue remediation','variant','outline','enabled',true,'blocked_reason',NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','reason','label','Escalation rationale','type','textarea','required',true,'min_length',20))));
  END IF;

  IF public.has_permission(_uid, 'market_conduct', 'approve') THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','WAIVE','label','Waive requirement','variant','outline','enabled',true,'blocked_reason',NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','reason','label','Waiver rationale','type','textarea','required',true,'min_length',20))));
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','CANCEL','label','Cancel requirement','variant','outline','enabled',true,'blocked_reason',NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','reason','label','Cancellation rationale','type','textarea','required',true,'min_length',20))));
  END IF;

  RETURN _out;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_action_case(_action_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _s record;
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  SELECT * INTO _s FROM public.v_conduct_action_state WHERE id = _action_id;
  IF _s IS NULL THEN RAISE EXCEPTION 'Remediation requirement not found' USING ERRCODE = 'P0002'; END IF;
  RETURN to_jsonb(_s) || jsonb_build_object(
    'entity_href', CASE WHEN _s.entity_id IS NOT NULL THEN '/entities/' || _s.entity_id ELSE NULL END,
    'source_href', CASE
      WHEN _s.source_type = 'complaint' THEN '/complaints/' || _s.source_id
      WHEN _s.source_type = 'conduct_investigation' THEN '/conduct/investigations/' || _s.source_id
      WHEN _s.source_type = 'conduct_finding' THEN '/conduct/findings/' || _s.source_id
      WHEN _s.source_type = 'thematic_review' THEN '/supervision/thematic-reviews/' || _s.source_id
      WHEN _s.source_type = 'enforcement' THEN '/enforcement/' || _s.source_id
      ELSE NULL END,
    'available_actions', public.conduct_action_available_actions(_action_id),
    'evidence', (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', e.id, 'title', e.title, 'evidence_type', e.evidence_type,
        'restricted', e.restricted, 'uploaded_at', e.uploaded_at) ORDER BY e.uploaded_at DESC), '[]'::jsonb)
      FROM public.conduct_evidence e WHERE e.action_id = _action_id));
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_action_close(_action_id uuid, _disposition text, _reason text, _outcome text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb; _min int;
BEGIN
  _uid := public.conduct_require('market_conduct','issue_enforcement_action');
  IF _disposition NOT IN ('completed','waived','cancelled') THEN
    RAISE EXCEPTION 'Unsupported disposition: %', _disposition USING ERRCODE='22023';
  END IF;
  _min := CASE WHEN _disposition='completed' THEN 1 ELSE 10 END;
  IF coalesce(length(btrim(_reason)),0) < _min THEN
    RAISE EXCEPTION 'Reason required (min % characters)', _min USING ERRCODE='22023';
  END IF;
  IF _disposition='completed' AND coalesce(length(btrim(_outcome)),0) = 0 THEN
    RAISE EXCEPTION 'Outcome is required to complete an action' USING ERRCODE='22023';
  END IF;
  SELECT to_jsonb(a) INTO _before FROM public.conduct_actions a WHERE a.id=_action_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Action not found' USING ERRCODE='P0002'; END IF;
  IF _before->>'status' IN ('completed','waived','cancelled') THEN
    RAISE EXCEPTION 'Action is already closed' USING ERRCODE='22023';
  END IF;
  UPDATE public.conduct_actions SET
    status = _disposition,
    outcome = CASE WHEN _disposition='completed' THEN btrim(_outcome) ELSE outcome END,
    completion_notes = CASE WHEN _disposition='completed' THEN btrim(_reason) ELSE completion_notes END,
    waiver_reason = CASE WHEN _disposition='waived' THEN btrim(_reason) ELSE waiver_reason END,
    cancellation_reason = CASE WHEN _disposition='cancelled' THEN btrim(_reason) ELSE cancellation_reason END,
    closed_by = _uid, closed_at = now(), updated_at = now()
  WHERE id=_action_id
  RETURNING to_jsonb(conduct_actions) INTO _after;
  PERFORM public.log_compliance_audit(
    CASE WHEN _disposition='completed' THEN 'UPDATE' ELSE 'OVERRIDE' END,
    'conduct_action',_action_id,_before,_after,btrim(_reason));
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_action_issue(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _id uuid; _after jsonb; _rationale text;
BEGIN
  _uid := public.conduct_require('market_conduct','issue_enforcement_action');
  _rationale := btrim(coalesce(_payload->>'rationale',''));
  IF coalesce(length(btrim(_payload->>'title')),0) = 0 THEN
    RAISE EXCEPTION 'Title is required' USING ERRCODE='22023';
  END IF;
  IF length(_rationale) < 10 THEN
    RAISE EXCEPTION 'Rationale required (min 10 characters)' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.conduct_actions (
    source_module, source_id, entity_id, product_id, action_type, title, description,
    due_date, assigned_to, assigned_team, status, created_by, metadata
  ) VALUES (
    coalesce(nullif(_payload->>'source_module',''),'manual'),
    nullif(_payload->>'source_id','')::uuid,
    nullif(_payload->>'entity_id','')::uuid,
    nullif(_payload->>'product_id','')::uuid,
    coalesce(nullif(_payload->>'action_type',''),'remediation_request'),
    btrim(_payload->>'title'),
    nullif(btrim(coalesce(_payload->>'description','')),''),
    nullif(_payload->>'due_date','')::date,
    nullif(_payload->>'assigned_to','')::uuid,
    nullif(btrim(coalesce(_payload->>'assigned_team','')),''),
    'open', _uid,
    coalesce(_payload->'metadata','{}'::jsonb) || jsonb_build_object('rationale',_rationale)
  ) RETURNING id INTO _id;
  SELECT to_jsonb(a) INTO _after FROM public.conduct_actions a WHERE a.id=_id;
  PERFORM public.log_compliance_audit('CREATE','conduct_action',_id,NULL,_after,_rationale);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_action_overdue_alert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  is_overdue boolean;
  dkey text;
BEGIN
  is_overdue := NEW.due_date IS NOT NULL AND NEW.due_date < CURRENT_DATE
                AND NEW.status NOT IN ('completed','waived','closed','cancelled');
  IF is_overdue THEN
    IF NEW.status <> 'overdue' THEN NEW.status := 'overdue'; END IF;
    dkey := encode(extensions.digest(('action_overdue:'||NEW.id::text)::bytea, 'sha1'),'hex');
    -- attempt insert; ignore conflicts with existing open alert (partial index)
    BEGIN
      INSERT INTO public.conduct_alerts(
        licensee_id, kind, severity, title, detail, dedupe_key, status, source, generated_by
      ) VALUES (
        NEW.entity_id, 'action_overdue', 'high',
        'Conduct action overdue: '||NEW.title,
        jsonb_build_object('conduct_action_id', NEW.id, 'source_module', NEW.source_module, 'due_date', NEW.due_date),
        dkey, 'open', 'system', 'overdue_trigger'
      );
    EXCEPTION WHEN unique_violation THEN NULL;
    END;
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_action_register(_statuses text[] DEFAULT NULL::text[], _source_types text[] DEFAULT NULL::text[], _entity_id uuid DEFAULT NULL::uuid, _assigned_to uuid DEFAULT NULL::uuid, _unassigned boolean DEFAULT false, _overdue_only boolean DEFAULT false, _search text DEFAULT NULL::text, _include_closed boolean DEFAULT false, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, action_reference text, title text, description text, action_type text, source_type text, source_id uuid, source_reference text, source_href text, finding_id uuid, finding_reference text, entity_id uuid, entity_name text, status text, stage_label text, is_terminal boolean, assigned_to uuid, assigned_to_name text, assigned_team text, due_date date, sla_due_at timestamp with time zone, sla_state text, is_overdue boolean, evidence_status text, evidence_count bigint, waiting_on text, next_action_label text, last_activity_at timestamp with time zone, canonical_href text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  RETURN QUERY
  WITH scoped AS (
    SELECT s.* FROM public.v_conduct_action_state s
     WHERE (_include_closed OR NOT s.is_terminal)
       AND (_statuses IS NULL OR s.status = ANY(_statuses))
       AND (_source_types IS NULL OR s.source_type = ANY(_source_types))
       AND (_entity_id IS NULL OR s.entity_id = _entity_id)
       AND (_assigned_to IS NULL OR s.assigned_to = _assigned_to)
       AND (NOT coalesce(_unassigned, false) OR s.assigned_to IS NULL)
       AND (NOT coalesce(_overdue_only, false) OR s.is_overdue)
       AND (_search IS NULL OR btrim(_search) = '' OR
            s.action_reference ILIKE '%' || btrim(_search) || '%' OR
            coalesce(s.title, '') ILIKE '%' || btrim(_search) || '%' OR
            coalesce(s.description, '') ILIKE '%' || btrim(_search) || '%' OR
            coalesce(s.entity_name, '') ILIKE '%' || btrim(_search) || '%')
  ), counted AS (SELECT count(*) AS n FROM scoped)
  SELECT s.id, s.action_reference, s.title, s.description, s.action_type,
         s.source_type, s.source_id,
         coalesce(s.finding_reference, s.investigation_code, s.complaint_number, NULL),
         CASE
           WHEN s.source_type = 'complaint' THEN '/complaints/' || s.source_id
           WHEN s.source_type = 'conduct_investigation' THEN '/conduct/investigations/' || s.source_id
           WHEN s.source_type = 'conduct_finding' THEN '/conduct/findings/' || s.source_id
           WHEN s.source_type = 'thematic_review' THEN '/supervision/thematic-reviews/' || s.source_id
           WHEN s.source_type = 'enforcement' THEN '/enforcement/' || s.source_id
           ELSE NULL END,
         s.finding_id, s.finding_reference,
         s.entity_id, s.entity_name, s.status, s.stage_label, s.is_terminal,
         s.assigned_to, s.assigned_to_name, s.assigned_team,
         s.due_date, s.sla_due_at, s.sla_state, s.is_overdue,
         s.evidence_status, s.evidence_count, s.waiting_on, s.next_action_label,
         s.last_activity_at, '/conduct/actions/' || s.id, counted.n
    FROM scoped s CROSS JOIN counted
   ORDER BY CASE s.sla_state WHEN 'breached' THEN 0 WHEN 'due_soon' THEN 1 WHEN 'on_track' THEN 2 ELSE 3 END,
            s.due_date NULLS LAST, s.created_at DESC
   LIMIT greatest(1, least(coalesce(_limit, 50), 200)) OFFSET greatest(0, coalesce(_offset, 0));
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_action_register_counts(_entity_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _res jsonb;
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  SELECT jsonb_build_object(
    'total_open', count(*) FILTER (WHERE NOT s.is_terminal),
    'overdue', count(*) FILTER (WHERE s.is_overdue),
    'under_review', count(*) FILTER (WHERE s.status = 'under_review'),
    'unassigned', count(*) FILTER (WHERE NOT s.is_terminal AND s.assigned_to IS NULL),
    'evidence_outstanding', count(*) FILTER (WHERE NOT s.is_terminal AND s.evidence_status = 'outstanding'),
    'escalated', count(*) FILTER (WHERE s.status = 'escalated'),
    'completed', count(*) FILTER (WHERE s.status = 'completed'),
    'waived', count(*) FILTER (WHERE s.status = 'waived'),
    'cancelled', count(*) FILTER (WHERE s.status = 'cancelled'),
    'by_status', coalesce(jsonb_object_agg(s.status, s.n) FILTER (WHERE false), '{}'::jsonb))
    INTO _res
  FROM (SELECT v.*, 1 AS n FROM public.v_conduct_action_state v
         WHERE (_entity_id IS NULL OR v.entity_id = _entity_id)) s;

  SELECT coalesce(_res, '{}'::jsonb) || jsonb_build_object(
    'by_status', coalesce((SELECT jsonb_object_agg(x.status, x.n) FROM (
      SELECT v.status, count(*) AS n FROM public.v_conduct_action_state v
       WHERE (_entity_id IS NULL OR v.entity_id = _entity_id)
       GROUP BY v.status) x), '{}'::jsonb)) INTO _res;
  RETURN coalesce(_res, '{}'::jsonb);
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_action_step(_action_id uuid, _action_code text, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _actions jsonb; _action jsonb; _before jsonb; _after jsonb;
BEGIN
  _uid := public.conduct_require('market_conduct', 'edit');
  _actions := public.conduct_action_available_actions(_action_id);
  SELECT a INTO _action FROM jsonb_array_elements(_actions) a WHERE a->>'action_code' = _action_code;
  IF _action IS NULL THEN
    RAISE EXCEPTION 'Action % is not available for this remediation requirement', _action_code USING ERRCODE = '42501';
  END IF;
  IF NOT coalesce((_action->>'enabled')::boolean, false) THEN
    RAISE EXCEPTION '%', coalesce(_action->>'blocked_reason', 'Action is blocked') USING ERRCODE = '22023';
  END IF;

  SELECT to_jsonb(a) INTO _before FROM public.conduct_actions a WHERE a.id = _action_id;

  IF _action_code = 'ASSIGN' THEN
    IF coalesce(nullif(_payload->>'assigned_to', ''), '') = '' THEN
      RAISE EXCEPTION 'A responsible officer is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_actions
       SET assigned_to = (_payload->>'assigned_to')::uuid,
           assigned_team = coalesce(nullif(btrim(_payload->>'assigned_team'), ''), assigned_team),
           assigned_at = now(), updated_at = now()
     WHERE id = _action_id;

  ELSIF _action_code = 'START' THEN
    UPDATE public.conduct_actions
       SET status = 'in_progress', started_at = coalesce(started_at, now()), updated_at = now()
     WHERE id = _action_id;

  ELSIF _action_code = 'SUBMIT_EVIDENCE' THEN
    IF coalesce(length(btrim(_payload->>'evidence_summary')), 0) < 20 THEN
      RAISE EXCEPTION 'Describe the remediation performed (min 20 characters)' USING ERRCODE = '22023';
    END IF;
    -- Evidence submission never completes a requirement: it moves it to review.
    UPDATE public.conduct_actions
       SET status = 'under_review',
           evidence_summary = btrim(_payload->>'evidence_summary'),
           evidence_submitted_at = now(), evidence_submitted_by = _uid,
           return_reason = NULL, updated_at = now()
     WHERE id = _action_id;

  ELSIF _action_code = 'COMPLETE' THEN
    IF coalesce(nullif(btrim(_payload->>'outcome'), ''), '') = ''
       OR coalesce(length(btrim(_payload->>'completion_notes')), 0) < 10 THEN
      RAISE EXCEPTION 'An outcome and review notes (min 10 characters) are required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_actions
       SET status = 'completed', review_outcome = 'satisfied',
           outcome = btrim(_payload->>'outcome'),
           completion_notes = btrim(_payload->>'completion_notes'),
           reviewed_by = _uid, reviewed_at = now(),
           closed_by = _uid, closed_at = now(), updated_at = now()
     WHERE id = _action_id;

  ELSIF _action_code = 'RETURN' THEN
    IF coalesce(length(btrim(_payload->>'reason')), 0) < 10 THEN
      RAISE EXCEPTION 'State what is still required (min 10 characters)' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_actions
       SET status = 'returned', review_outcome = 'more_information_required',
           return_reason = btrim(_payload->>'reason'),
           reviewed_by = _uid, reviewed_at = now(), updated_at = now()
     WHERE id = _action_id;

  ELSIF _action_code = 'ESCALATE' THEN
    IF coalesce(length(btrim(_payload->>'reason')), 0) < 20 THEN
      RAISE EXCEPTION 'An escalation rationale of at least 20 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_actions
       SET status = 'escalated', review_outcome = 'unsatisfactory',
           escalation_reason = btrim(_payload->>'reason'), escalated_at = now(),
           reviewed_by = _uid, reviewed_at = now(), updated_at = now()
     WHERE id = _action_id;

  ELSIF _action_code IN ('WAIVE', 'CANCEL') THEN
    IF coalesce(length(btrim(_payload->>'reason')), 0) < 20 THEN
      RAISE EXCEPTION 'A rationale of at least 20 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_actions
       SET status = CASE WHEN _action_code = 'WAIVE' THEN 'waived' ELSE 'cancelled' END,
           waiver_reason = CASE WHEN _action_code = 'WAIVE' THEN btrim(_payload->>'reason') ELSE waiver_reason END,
           cancellation_reason = CASE WHEN _action_code = 'CANCEL' THEN btrim(_payload->>'reason') ELSE cancellation_reason END,
           closed_by = _uid, closed_at = now(), updated_at = now()
     WHERE id = _action_id;
  ELSE
    RAISE EXCEPTION 'Unsupported action %', _action_code USING ERRCODE = '22023';
  END IF;

  SELECT to_jsonb(a) INTO _after FROM public.conduct_actions a WHERE a.id = _action_id;
  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION', 'conduct_action', _action_id, _before, _after,
    _action_code || coalesce(' — ' || nullif(btrim(coalesce(_payload->>'reason', _payload->>'completion_notes', _payload->>'evidence_summary')), ''), ''));

  RETURN jsonb_build_object('id', _action_id);
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_alert_acknowledge(_alert_id uuid, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb;
BEGIN
  _uid := public.conduct_require('market_conduct','manage_complaints');
  SELECT to_jsonb(a) INTO _before FROM public.conduct_alerts a WHERE a.id = _alert_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Alert not found' USING ERRCODE = 'P0002'; END IF;
  IF _before->>'status' NOT IN ('open','escalated') THEN
    RAISE EXCEPTION 'Only open alerts can be acknowledged' USING ERRCODE = '22023';
  END IF;
  UPDATE public.conduct_alerts SET status='acknowledged', acknowledged_by=_uid,
    acknowledged_at=now(), updated_at=now() WHERE id=_alert_id
  RETURNING to_jsonb(conduct_alerts) INTO _after;
  PERFORM public.log_compliance_audit('UPDATE','conduct_alert',_alert_id,_before,_after,_note);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_alert_close(_alert_id uuid, _reason text, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb;
BEGIN
  _uid := public.conduct_require('market_conduct','manage_complaints');
  IF coalesce(length(btrim(_reason)),0) < 5 THEN
    RAISE EXCEPTION 'Closure reason required (min 5 characters)' USING ERRCODE = '22023';
  END IF;
  SELECT to_jsonb(a) INTO _before FROM public.conduct_alerts a WHERE a.id=_alert_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Alert not found' USING ERRCODE = 'P0002'; END IF;
  IF _before->>'status' = 'closed' THEN
    RAISE EXCEPTION 'Alert is already closed' USING ERRCODE = '22023';
  END IF;
  UPDATE public.conduct_alerts SET status='closed', closed_by=_uid, closed_at=now(),
    closure_reason=btrim(_reason),
    disposition = coalesce(_metadata->>'disposition', disposition),
    disposition_reason = coalesce(_metadata->>'disposition_reason', disposition_reason),
    updated_at=now() WHERE id=_alert_id
  RETURNING to_jsonb(conduct_alerts) INTO _after;
  PERFORM public.log_compliance_audit(
    CASE WHEN _before->>'status'='open' THEN 'OVERRIDE' ELSE 'UPDATE' END,
    'conduct_alert',_alert_id,_before,_after,btrim(_reason));
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_alert_dispose(_alert_id uuid, _disposition text, _reason text, _target_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _a record; _before jsonb; _after jsonb;
BEGIN
  _uid := public.conduct_require('market_conduct', 'edit');
  SELECT * INTO _a FROM public.conduct_alerts WHERE id = _alert_id;
  IF _a IS NULL THEN RAISE EXCEPTION 'Alert not found' USING ERRCODE = 'P0002'; END IF;
  IF _a.status IN ('closed', 'dismissed') THEN
    RAISE EXCEPTION 'This alert is already disposed' USING ERRCODE = '22023';
  END IF;
  IF coalesce(length(btrim(_reason)), 0) < 10 THEN
    RAISE EXCEPTION 'A rationale of at least 10 characters is required' USING ERRCODE = '22023';
  END IF;
  IF _disposition NOT IN ('DISMISS', 'LINK_TO_EXISTING_COMPLAINT', 'LINK_TO_EXISTING_INVESTIGATION') THEN
    RAISE EXCEPTION 'Unsupported disposition %', _disposition USING ERRCODE = '22023';
  END IF;

  SELECT to_jsonb(a) INTO _before FROM public.conduct_alerts a WHERE a.id = _alert_id;

  IF _disposition = 'DISMISS' THEN
    UPDATE public.conduct_alerts
       SET status = 'dismissed', disposition = 'dismissed', disposition_reason = btrim(_reason),
           reviewed_by = _uid, reviewed_at = now(), closed_by = _uid, closed_at = now(), updated_at = now()
     WHERE id = _alert_id;

  ELSIF _disposition = 'LINK_TO_EXISTING_COMPLAINT' THEN
    IF _target_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.complaints c WHERE c.id = _target_id) THEN
      RAISE EXCEPTION 'A valid complaint must be selected' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_alerts
       SET complaint_id = _target_id, disposition = 'linked_to_complaint',
           disposition_reason = btrim(_reason),
           status = CASE WHEN status = 'open' THEN 'acknowledged' ELSE status END,
           acknowledged_by = coalesce(acknowledged_by, _uid),
           acknowledged_at = coalesce(acknowledged_at, now()),
           reviewed_by = _uid, reviewed_at = now(), updated_at = now()
     WHERE id = _alert_id;

  ELSE
    IF _target_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.conduct_investigations i WHERE i.id = _target_id) THEN
      RAISE EXCEPTION 'A valid investigation must be selected' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_alerts
       SET investigation_id = _target_id, disposition = 'linked_to_investigation',
           disposition_reason = btrim(_reason),
           status = CASE WHEN status = 'open' THEN 'acknowledged' ELSE status END,
           acknowledged_by = coalesce(acknowledged_by, _uid),
           acknowledged_at = coalesce(acknowledged_at, now()),
           reviewed_by = _uid, reviewed_at = now(), updated_at = now()
     WHERE id = _alert_id;
  END IF;

  SELECT to_jsonb(a) INTO _after FROM public.conduct_alerts a WHERE a.id = _alert_id;
  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION', 'conduct_alert', _alert_id, _before, _after,
    _disposition || ' — ' || btrim(_reason));
  RETURN jsonb_build_object('id', _alert_id, 'disposition', _disposition);
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_alert_promote_to_investigation(_alert_id uuid, _rationale text, _allegation text DEFAULT NULL::text, _due_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _a record; _inv uuid; _code text; _before jsonb; _after jsonb; _lineage jsonb;
BEGIN
  _uid := public.conduct_require('market_conduct', 'initiate_investigation');
  SELECT * INTO _a FROM public.conduct_alerts WHERE id = _alert_id;
  IF _a IS NULL THEN RAISE EXCEPTION 'Alert not found' USING ERRCODE = 'P0002'; END IF;
  IF _a.investigation_id IS NOT NULL THEN
    RAISE EXCEPTION 'This alert is already linked to an investigation' USING ERRCODE = '22023';
  END IF;
  IF coalesce(length(btrim(_rationale)), 0) < 20 THEN
    RAISE EXCEPTION 'A promotion rationale of at least 20 characters is required' USING ERRCODE = '22023';
  END IF;

  _code := 'CI-' || to_char(now(), 'YYYY') || '-' ||
           lpad((1 + coalesce((SELECT max(substring(i.code from '[0-9]+$')::int)
                                 FROM public.conduct_investigations i
                                WHERE i.code LIKE 'CI-' || to_char(now(), 'YYYY') || '-%'), 0))::text, 5, '0');

  _lineage := jsonb_build_object(
    'alert_id', _a.id,
    'signal_source', coalesce(_a.source, _a.generated_by),
    'alert_kind', _a.kind,
    'rule_id', _a.triage_rule_id,
    'rule_version', _a.rule_version,
    'rule_snapshot', _a.rule_snapshot,
    'monitoring_result_id', _a.monitoring_result_id,
    'observation_start', coalesce(_a.observation_start, _a.window_start),
    'observation_end', coalesce(_a.observation_end, _a.window_end),
    'threshold_value', _a.threshold_value,
    'explanation', _a.explanation,
    'source_record_ids', to_jsonb(_a.source_record_ids),
    'product_id', _a.product_id,
    'channel_id', _a.channel_id,
    'promotion_rationale', btrim(_rationale),
    'promoted_by', _uid,
    'promoted_at', now());

  INSERT INTO public.conduct_investigations(
    code, source_type, source_id, licensee_id, product_id, allegation,
    priority, severity, status, due_date, opened_by, metadata, legal_basis)
  VALUES (
    _code, 'conduct_alert', _a.id, _a.licensee_id, _a.product_id,
    coalesce(nullif(btrim(_allegation), ''), _a.title),
    CASE _a.severity WHEN 'critical' THEN 'critical' WHEN 'high' THEN 'high' ELSE 'medium' END,
    coalesce(_a.severity, 'medium'), 'opened', _due_date, _uid,
    jsonb_build_object('promoted_from_alert', _lineage), NULL)
  RETURNING id INTO _inv;

  SELECT to_jsonb(a) INTO _before FROM public.conduct_alerts a WHERE a.id = _alert_id;
  UPDATE public.conduct_alerts
     SET investigation_id = _inv, disposition = 'promoted_to_investigation',
         disposition_reason = btrim(_rationale),
         status = CASE WHEN status = 'open' THEN 'acknowledged' ELSE status END,
         acknowledged_by = coalesce(acknowledged_by, _uid),
         acknowledged_at = coalesce(acknowledged_at, now()),
         reviewed_by = _uid, reviewed_at = now(), updated_at = now()
   WHERE id = _alert_id;
  SELECT to_jsonb(a) INTO _after FROM public.conduct_alerts a WHERE a.id = _alert_id;

  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION', 'conduct_alert', _alert_id, _before, _after,
    'PROMOTE_TO_INVESTIGATION — ' || btrim(_rationale));
  PERFORM public.log_compliance_audit('CREATE', 'conduct_investigation', _inv, NULL,
    (SELECT to_jsonb(i) FROM public.conduct_investigations i WHERE i.id = _inv),
    'Promoted from conduct alert ' || _alert_id::text);

  RETURN jsonb_build_object('investigation_id', _inv, 'alert_id', _alert_id, 'code', _code);
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_alert_register(_statuses text[] DEFAULT NULL::text[], _severities text[] DEFAULT NULL::text[], _entity_id uuid DEFAULT NULL::uuid, _search text DEFAULT NULL::text, _include_closed boolean DEFAULT false, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, reference text, kind text, source text, entity_id uuid, entity_name text, product_name text, channel_name text, risk_category_name text, rule_id uuid, rule_version integer, threshold_value numeric, severity text, status text, disposition text, disposition_reason text, explanation text, observation_start timestamp with time zone, observation_end timestamp with time zone, generated_at timestamp with time zone, acknowledged_by uuid, acknowledged_by_name text, acknowledged_at timestamp with time zone, complaint_id uuid, complaint_href text, investigation_id uuid, investigation_href text, title text, last_activity_at timestamp with time zone, canonical_href text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  RETURN QUERY
  WITH scoped AS (
    SELECT a.*, l.name AS entity_name, pr.name AS product_name, ch.name AS channel_name,
           rc.name AS risk_category_name, p.full_name AS acknowledged_by_name
      FROM public.conduct_alerts a
      LEFT JOIN public.licensees l ON l.id = a.licensee_id
      LEFT JOIN public.conduct_products pr ON pr.id = a.product_id
      LEFT JOIN public.conduct_channels ch ON ch.id = a.channel_id
      LEFT JOIN public.conduct_risk_categories rc ON rc.id = a.conduct_risk_category_id
      LEFT JOIN public.profiles p ON p.id = a.acknowledged_by
     WHERE (_include_closed OR a.status NOT IN ('closed', 'dismissed'))
       AND (_statuses IS NULL OR a.status = ANY(_statuses))
       AND (_severities IS NULL OR a.severity = ANY(_severities))
       AND (_entity_id IS NULL OR a.licensee_id = _entity_id)
       AND (_search IS NULL OR btrim(_search) = '' OR
            coalesce(a.title, '') ILIKE '%' || btrim(_search) || '%' OR
            coalesce(l.name, '') ILIKE '%' || btrim(_search) || '%')
  ), counted AS (SELECT count(*) AS n FROM scoped)
  SELECT s.id, 'AL-' || upper(left(s.id::text, 8)), s.kind, coalesce(s.source, s.generated_by),
         s.licensee_id, s.entity_name, s.product_name, s.channel_name, s.risk_category_name,
         s.triage_rule_id, s.rule_version, s.threshold_value,
         s.severity, s.status, s.disposition, s.disposition_reason,
         s.explanation,
         coalesce(s.observation_start, s.window_start), coalesce(s.observation_end, s.window_end),
         s.created_at, s.acknowledged_by, s.acknowledged_by_name, s.acknowledged_at,
         s.complaint_id, CASE WHEN s.complaint_id IS NOT NULL THEN '/complaints/' || s.complaint_id ELSE NULL END,
         s.investigation_id, CASE WHEN s.investigation_id IS NOT NULL THEN '/conduct/investigations/' || s.investigation_id ELSE NULL END,
         s.title, greatest(s.updated_at, s.created_at),
         '/conduct/alerts?alert=' || s.id, counted.n
    FROM scoped s CROSS JOIN counted
   ORDER BY CASE s.severity WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END,
            s.created_at DESC
   LIMIT greatest(1, least(coalesce(_limit, 50), 200)) OFFSET greatest(0, coalesce(_offset, 0));
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_alert_register_counts(_entity_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _res jsonb;
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  SELECT jsonb_build_object(
    'open', count(*) FILTER (WHERE a.status = 'open'),
    'acknowledged', count(*) FILTER (WHERE a.status = 'acknowledged'),
    'high_severity_open', count(*) FILTER (WHERE a.status NOT IN ('closed','dismissed') AND a.severity IN ('high','critical')),
    'promoted', count(*) FILTER (WHERE a.investigation_id IS NOT NULL),
    'closed', count(*) FILTER (WHERE a.status IN ('closed','dismissed'))) INTO _res
  FROM public.conduct_alerts a
  WHERE (_entity_id IS NULL OR a.licensee_id = _entity_id);
  RETURN coalesce(_res, '{}'::jsonb);
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_amend_interview(_interview_id uuid, _patch jsonb, _justification text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  rec public.conduct_interviews;
BEGIN
  SELECT * INTO rec FROM public.conduct_interviews WHERE id = _interview_id;
  IF rec.id IS NULL THEN
    RAISE EXCEPTION 'Interview not found' USING ERRCODE = 'no_data_found';
  END IF;

  IF NOT public.can_manage_conduct_investigation(rec.investigation_id) THEN
    RAISE EXCEPTION 'Not authorised to amend this interview record' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF length(coalesce(btrim(_justification), '')) < 10 THEN
    RAISE EXCEPTION 'Amendment justification of at least 10 characters is required' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.conduct_interview_amend', _interview_id::text, true);

  UPDATE public.conduct_interviews SET
    key_information   = coalesce(_patch->>'key_information', key_information),
    topics_covered    = coalesce(_patch->>'topics_covered', topics_covered),
    admissions        = coalesce(_patch->>'admissions', admissions),
    follow_up_actions = coalesce(_patch->>'follow_up_actions', follow_up_actions),
    amendments = amendments || jsonb_build_array(jsonb_build_object(
      'amended_at', now(),
      'amended_by', auth.uid(),
      'justification', btrim(_justification),
      'patch', _patch
    ))
  WHERE id = _interview_id
  RETURNING * INTO rec;

  PERFORM set_config('app.conduct_interview_amend', '', true);

  RETURN to_jsonb(rec);
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_appendonly_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION '% rows are append-only', TG_TABLE_NAME;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_closure_approve(_closure_id uuid, _decision_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_c record; v_inv record; v_new_status text; v_mon record;
BEGIN
  SELECT * INTO v_c FROM public.conduct_investigation_closures WHERE id=_closure_id;
  IF v_c IS NULL THEN RAISE EXCEPTION 'Closure record not found' USING ERRCODE='P0002'; END IF;
  IF v_c.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'This closure record is not awaiting approval' USING ERRCODE='22023'; END IF;
  IF NOT public.can_approve_conduct_closure(_closure_id) THEN
    RAISE EXCEPTION 'Not authorised to approve this closure' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_inv FROM public.conduct_investigations WHERE id=v_c.investigation_id;
  v_new_status := CASE WHEN v_c.determination_type='discontinuation' THEN 'discontinued' ELSE 'closed' END;

  PERFORM set_config('conduct.closure_rpc','on', true);
  UPDATE public.conduct_investigation_closures SET
    status='approved', approved_by=auth.uid(), approved_at=now(),
    metadata = metadata || jsonb_build_object('decision_note', _decision_note)
  WHERE id=_closure_id;
  PERFORM set_config('conduct.closure_rpc','off', true);

  UPDATE public.conduct_investigations SET
    status=v_new_status,
    outcome=coalesce(v_c.findings_summary, outcome),
    closure_reason=coalesce(v_c.rationale, closure_reason),
    closed_by=auth.uid(), closed_at=now(),
    discontinuation_ground=CASE WHEN v_new_status='discontinued' THEN v_c.discontinuation_ground ELSE discontinuation_ground END,
    discontinued_at=CASE WHEN v_new_status='discontinued' THEN now() ELSE discontinued_at END,
    discontinued_by=CASE WHEN v_new_status='discontinued' THEN auth.uid() ELSE discontinued_by END,
    active_closure_id=_closure_id
  WHERE id=v_c.investigation_id;

  -- Activate any monitoring directive attached to this closure / investigation
  FOR v_mon IN
    SELECT * FROM public.conduct_post_closure_monitoring
    WHERE investigation_id=v_c.investigation_id AND status='pending'
  LOOP
    UPDATE public.conduct_post_closure_monitoring SET
      status='active', closure_id=coalesce(closure_id,_closure_id), activated_at=now(),
      next_review_date = coalesce(v_mon.start_date, CURRENT_DATE) + (
        CASE v_mon.frequency WHEN 'monthly' THEN interval '1 month'
                             WHEN 'quarterly' THEN interval '3 months'
                             WHEN 'semi_annual' THEN interval '6 months'
                             ELSE interval '12 months' END)
    WHERE id=v_mon.id;

    INSERT INTO public.conduct_monitoring_reviews(monitoring_id, due_date)
    VALUES (v_mon.id, (coalesce(v_mon.start_date, CURRENT_DATE) + (
      CASE v_mon.frequency WHEN 'monthly' THEN interval '1 month'
                           WHEN 'quarterly' THEN interval '3 months'
                           WHEN 'semi_annual' THEN interval '6 months'
                           ELSE interval '12 months' END))::date);

    PERFORM public.notification_enqueue_event('conduct_investigation.monitoring_activated','conduct_investigation',
      v_c.investigation_id,
      jsonb_build_object('investigation_code', coalesce(v_inv.code,''), 'focus_areas', v_mon.focus_areas,
        'frequency', v_mon.frequency, 'owner_id', v_mon.owner_id),
      v_mon.id::text, NULL, NULL);
  END LOOP;

  PERFORM public.log_compliance_audit('APPROVE','conduct_investigation_closure', _closure_id::text,
    jsonb_build_object('status','pending_approval'),
    jsonb_build_object('status','approved','investigation_status',v_new_status),
    coalesce(_decision_note,'Closure approved'), NULL, NULL,
    jsonb_build_object('module','market_conduct','investigation_id',v_c.investigation_id));

  PERFORM public.notification_enqueue_event('conduct_investigation.closure_approved','conduct_investigation',
    v_c.investigation_id,
    jsonb_build_object('investigation_code', coalesce(v_inv.code,''), 'allegation', v_inv.allegation,
      'determination_type', v_c.determination_type, 'decision_note', coalesce(_decision_note,'')),
    _closure_id::text, NULL, NULL);

  IF v_new_status='discontinued' THEN
    PERFORM public.notification_enqueue_event('conduct_investigation.discontinued','conduct_investigation',
      v_c.investigation_id,
      jsonb_build_object('investigation_code', coalesce(v_inv.code,''),
        'ground', coalesce(v_c.discontinuation_ground,''), 'detail', coalesce(v_c.discontinuation_detail,'')),
      _closure_id::text, NULL, NULL);
  END IF;
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_closure_link_enforcement(_closure_id uuid, _enforcement_action_id uuid DEFAULT NULL::uuid, _create_new boolean DEFAULT false, _enforcement_type text DEFAULT 'warning'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_c record; v_inv record; v_id uuid; v_case text;
BEGIN
  SELECT * INTO v_c FROM public.conduct_investigation_closures WHERE id=_closure_id;
  IF v_c IS NULL THEN RAISE EXCEPTION 'Closure record not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_manage_conduct_investigation(v_c.investigation_id) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;
  IF v_c.status = 'approved' THEN
    RAISE EXCEPTION 'An approved closure record is immutable' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_inv FROM public.conduct_investigations WHERE id=v_c.investigation_id;

  IF _create_new THEN
    IF v_inv.licensee_id IS NULL THEN
      RAISE EXCEPTION 'An entity is required to open an enforcement case' USING ERRCODE='22023'; END IF;
    v_case := 'ENF-' || to_char(now(),'YYYY') || '-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,6));
    INSERT INTO public.enforcement_actions(
      entity_id, case_number, enforcement_type, status, description, findings,
      opened_by, source_type, source_reference_id)
    VALUES (v_inv.licensee_id, v_case, coalesce(_enforcement_type,'warning'), 'open',
      left(coalesce(v_inv.allegation,''), 2000), v_c.findings_summary,
      auth.uid(), 'conduct_investigation', v_inv.id)
    RETURNING id INTO v_id;

    INSERT INTO public.enforcement_case_events(case_id, event_type, note, actor_id, detail)
    VALUES (v_id, 'opened', 'Referred from market conduct investigation closure', auth.uid(),
      jsonb_build_object('investigation_id', v_inv.id, 'closure_id', _closure_id));
  ELSE
    IF _enforcement_action_id IS NULL THEN
      RAISE EXCEPTION 'An enforcement case must be selected' USING ERRCODE='22023'; END IF;
    v_id := _enforcement_action_id;
    INSERT INTO public.enforcement_case_events(case_id, event_type, note, actor_id, detail)
    VALUES (v_id, 'linked', 'Linked to market conduct investigation closure', auth.uid(),
      jsonb_build_object('investigation_id', v_inv.id, 'closure_id', _closure_id));
  END IF;

  PERFORM set_config('conduct.closure_rpc','on', true);
  UPDATE public.conduct_investigation_closures SET enforcement_action_id=v_id WHERE id=_closure_id;
  PERFORM set_config('conduct.closure_rpc','off', true);

  PERFORM public.log_compliance_audit('UPDATE','conduct_investigation_closure', _closure_id::text,
    jsonb_build_object('enforcement_action_id', v_c.enforcement_action_id),
    jsonb_build_object('enforcement_action_id', v_id),
    'Enforcement referral recorded', NULL, NULL,
    jsonb_build_object('module','market_conduct','investigation_id',v_c.investigation_id));

  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_closure_readiness(_investigation_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'unfinalised_interviews', (
      SELECT count(*) FROM public.conduct_interviews i
      WHERE i.investigation_id = _investigation_id
        AND coalesce(i.status,'') NOT IN ('recorded','cancelled')),
    'evidence_count', (
      SELECT count(*) FROM public.conduct_evidence e
      WHERE e.investigation_id = _investigation_id),
    'open_actions', (
      SELECT count(*) FROM public.conduct_actions a
      WHERE a.source_module = 'investigation' AND a.source_id = _investigation_id
        AND a.status IN ('open','in_progress')),
    'has_enforcement_link', (
      SELECT EXISTS (SELECT 1 FROM public.conduct_investigation_closures c
                     WHERE c.investigation_id = _investigation_id
                       AND c.status IN ('draft','pending_approval')
                       AND c.enforcement_action_id IS NOT NULL))
  )
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_closure_reject(_closure_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_c record; v_inv record;
BEGIN
  SELECT * INTO v_c FROM public.conduct_investigation_closures WHERE id=_closure_id;
  IF v_c IS NULL THEN RAISE EXCEPTION 'Closure record not found' USING ERRCODE='P0002'; END IF;
  IF v_c.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'This closure record is not awaiting approval' USING ERRCODE='22023'; END IF;
  IF NOT public.can_approve_conduct_closure(_closure_id) THEN
    RAISE EXCEPTION 'Not authorised to review this closure' USING ERRCODE='42501'; END IF;
  IF _reason IS NULL OR length(btrim(_reason)) < 10 THEN
    RAISE EXCEPTION 'A rejection reason of at least 10 characters is required' USING ERRCODE='23514'; END IF;

  SELECT * INTO v_inv FROM public.conduct_investigations WHERE id=v_c.investigation_id;

  PERFORM set_config('conduct.closure_rpc','on', true);
  UPDATE public.conduct_investigation_closures SET
    status='rejected', rejected_by=auth.uid(), rejected_at=now(), rejection_reason=btrim(_reason)
  WHERE id=_closure_id;
  PERFORM set_config('conduct.closure_rpc','off', true);

  PERFORM public.log_compliance_audit('REJECT','conduct_investigation_closure', _closure_id::text,
    jsonb_build_object('status','pending_approval'), jsonb_build_object('status','rejected'),
    btrim(_reason), NULL, NULL,
    jsonb_build_object('module','market_conduct','investigation_id',v_c.investigation_id));

  PERFORM public.notification_enqueue_event('conduct_investigation.closure_rejected','conduct_investigation',
    v_c.investigation_id,
    jsonb_build_object('investigation_code', coalesce(v_inv.code,''), 'reason', btrim(_reason),
      'submitted_by', v_c.submitted_by),
    _closure_id::text, NULL, NULL);
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_closure_submit(_closure_id uuid, _approver_id uuid DEFAULT NULL::uuid, _override_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_c record; v_inv record; v_ready jsonb;
BEGIN
  SELECT * INTO v_c FROM public.conduct_investigation_closures WHERE id=_closure_id;
  IF v_c IS NULL THEN RAISE EXCEPTION 'Closure record not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_manage_conduct_investigation(v_c.investigation_id) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;
  IF v_c.status NOT IN ('draft','rejected') THEN
    RAISE EXCEPTION 'This closure record is not in draft' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_inv FROM public.conduct_investigations WHERE id=v_c.investigation_id;
  IF v_inv.status IN ('closed','discontinued') THEN
    RAISE EXCEPTION 'The investigation is already concluded' USING ERRCODE='22023'; END IF;

  IF v_c.findings_summary IS NULL OR length(btrim(v_c.findings_summary)) < 20 THEN
    RAISE EXCEPTION 'A findings summary of at least 20 characters is required' USING ERRCODE='23514'; END IF;
  IF v_c.rationale IS NULL OR length(btrim(v_c.rationale)) < 20 THEN
    RAISE EXCEPTION 'A determination rationale of at least 20 characters is required' USING ERRCODE='23514'; END IF;

  IF v_c.determination_type = 'discontinuation' THEN
    IF v_c.discontinuation_ground IS NULL OR btrim(v_c.discontinuation_ground) = '' THEN
      RAISE EXCEPTION 'A discontinuation ground is required' USING ERRCODE='23514'; END IF;
    IF v_c.discontinuation_ground = 'other'
       AND (v_c.discontinuation_detail IS NULL OR length(btrim(v_c.discontinuation_detail)) < 10) THEN
      RAISE EXCEPTION 'Describe the discontinuation ground (min 10 characters)' USING ERRCODE='23514'; END IF;
  END IF;

  IF v_c.determination_type = 'closure_with_enforcement' AND v_c.enforcement_action_id IS NULL THEN
    RAISE EXCEPTION 'An enforcement referral is required for an enforcement-track closure' USING ERRCODE='23514';
  END IF;

  v_ready := public.conduct_closure_readiness(v_c.investigation_id);

  IF (v_ready->>'unfinalised_interviews')::int > 0 OR (v_ready->>'open_actions')::int > 0 THEN
    IF _override_reason IS NULL OR length(btrim(_override_reason)) < 10 THEN
      RAISE EXCEPTION 'Closure blocked: % unfinalised interview(s) and % open action(s). A documented override reason (min 10 characters) is required.',
        (v_ready->>'unfinalised_interviews'), (v_ready->>'open_actions') USING ERRCODE='23514';
    END IF;
  END IF;

  PERFORM set_config('conduct.closure_rpc','on', true);
  UPDATE public.conduct_investigation_closures SET
    status='pending_approval', submitted_by=auth.uid(), submitted_at=now(),
    approver_id=coalesce(_approver_id, approver_id),
    override_reason=_override_reason, readiness_snapshot=v_ready,
    rejection_reason=NULL, rejected_by=NULL, rejected_at=NULL
  WHERE id=_closure_id;
  PERFORM set_config('conduct.closure_rpc','off', true);

  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION','conduct_investigation_closure', _closure_id::text,
    jsonb_build_object('status', v_c.status), jsonb_build_object('status','pending_approval'),
    coalesce(_override_reason, btrim(v_c.rationale)), NULL, NULL,
    jsonb_build_object('module','market_conduct','investigation_id',v_c.investigation_id,'readiness',v_ready));

  PERFORM public.notification_enqueue_event('conduct_investigation.closure_requested','conduct_investigation',
    v_c.investigation_id,
    jsonb_build_object('investigation_code', coalesce(v_inv.code,''), 'allegation', v_inv.allegation,
      'determination_type', v_c.determination_type, 'approver_id', coalesce(_approver_id, v_c.approver_id)),
    _closure_id::text, NULL, NULL);
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_closure_upsert_draft(_investigation_id uuid, _closure_id uuid DEFAULT NULL::uuid, _determination_type text DEFAULT 'closure_no_further_action'::text, _findings_summary text DEFAULT NULL::text, _evidence_relied_upon text DEFAULT NULL::text, _rationale text DEFAULT NULL::text, _next_steps text DEFAULT NULL::text, _regulatory_learning text DEFAULT NULL::text, _discontinuation_ground text DEFAULT NULL::text, _discontinuation_detail text DEFAULT NULL::text, _entity_letter_required boolean DEFAULT false, _approver_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_status text; v_ver int;
BEGIN
  IF NOT public.can_manage_conduct_investigation(_investigation_id) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;
  IF _determination_type NOT IN ('closure_with_enforcement','closure_no_further_action','discontinuation') THEN
    RAISE EXCEPTION 'Invalid determination type' USING ERRCODE='22023'; END IF;

  PERFORM set_config('conduct.closure_rpc','on', true);

  IF _closure_id IS NOT NULL THEN
    SELECT status INTO v_status FROM public.conduct_investigation_closures WHERE id=_closure_id;
    IF v_status IS NULL THEN RAISE EXCEPTION 'Closure record not found' USING ERRCODE='P0002'; END IF;
    IF v_status NOT IN ('draft','rejected') THEN
      RAISE EXCEPTION 'Only a draft or rejected closure record can be edited' USING ERRCODE='22023'; END IF;
    UPDATE public.conduct_investigation_closures SET
      determination_type=_determination_type,
      findings_summary=_findings_summary,
      evidence_relied_upon=_evidence_relied_upon,
      rationale=_rationale,
      next_steps=_next_steps,
      regulatory_learning=_regulatory_learning,
      discontinuation_ground=_discontinuation_ground,
      discontinuation_detail=_discontinuation_detail,
      entity_letter_required=coalesce(_entity_letter_required,false),
      approver_id=_approver_id,
      status='draft'
    WHERE id=_closure_id
    RETURNING id INTO v_id;
  ELSE
    SELECT coalesce(max(version),0)+1 INTO v_ver
      FROM public.conduct_investigation_closures WHERE investigation_id=_investigation_id;
    INSERT INTO public.conduct_investigation_closures(
      investigation_id, version, determination_type, findings_summary, evidence_relied_upon,
      rationale, next_steps, regulatory_learning, discontinuation_ground, discontinuation_detail,
      entity_letter_required, approver_id, prepared_by)
    VALUES (_investigation_id, v_ver, _determination_type, _findings_summary, _evidence_relied_upon,
      _rationale, _next_steps, _regulatory_learning, _discontinuation_ground, _discontinuation_detail,
      coalesce(_entity_letter_required,false), _approver_id, auth.uid())
    RETURNING id INTO v_id;
  END IF;

  PERFORM public.log_compliance_audit('UPDATE','conduct_investigation_closure', v_id::text,
    NULL, jsonb_build_object('determination_type',_determination_type,'status','draft'),
    _rationale, NULL, NULL,
    jsonb_build_object('module','market_conduct','investigation_id',_investigation_id));

  PERFORM set_config('conduct.closure_rpc','off', true);
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_entity_audit_history(_entity_id uuid)
 RETURNS TABLE(logged_at timestamp with time zone, actor_id uuid, action_type text, object_type text, object_id text, justification text, before_value jsonb, after_value jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT cal.timestamp AS logged_at, cal.user_id AS actor_id, cal.action_type::text,
         cal.object_type, cal.object_id::text, cal.justification, cal.before_value, cal.after_value
  FROM public.compliance_audit_logs cal
  WHERE cal.object_type IN ('complaint','conduct_alert','conduct_action','conduct_investigation','conduct_evidence','thematic_review','conduct_monitoring_rule','licensee')
    AND (
      cal.object_id = _entity_id::text
      OR cal.object_id IN (SELECT id::text FROM public.complaints WHERE licensee_id = _entity_id)
      OR cal.object_id IN (SELECT id::text FROM public.conduct_alerts WHERE licensee_id = _entity_id)
      OR cal.object_id IN (SELECT id::text FROM public.conduct_actions WHERE entity_id = _entity_id)
      OR cal.object_id IN (SELECT id::text FROM public.conduct_investigations WHERE licensee_id = _entity_id)
    )
  ORDER BY cal.timestamp DESC
  LIMIT 500;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_entity_profile_summary(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'complaints_total',   (SELECT count(*) FROM complaints WHERE licensee_id = _entity_id),
    'complaints_open',    (SELECT count(*) FROM complaints WHERE licensee_id = _entity_id AND status NOT IN ('resolved','closed','rejected')),
    'complaints_high',    (SELECT count(*) FROM complaints WHERE licensee_id = _entity_id AND severity IN ('high','critical')),
    'complaints_repeat',  (SELECT count(*) FROM complaints WHERE licensee_id = _entity_id AND coalesce(repeat_complaint_count,0) > 1),
    'alerts_open',        (SELECT count(*) FROM conduct_alerts WHERE licensee_id = _entity_id AND status = 'open'),
    'actions_open',       (SELECT count(*) FROM conduct_actions WHERE entity_id = _entity_id AND status NOT IN ('completed','waived','cancelled')),
    'investigations_open',(SELECT count(*) FROM conduct_investigations WHERE licensee_id = _entity_id AND status <> 'closed'),
    'thematic_reviews',   (SELECT count(*) FROM thematic_review_entities WHERE licensee_id = _entity_id)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_evidence_set_restriction(_evidence_id uuid, _restricted boolean, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb;
BEGIN
  _uid := public.conduct_require('market_conduct_investigation','manage_evidence_repository');
  IF coalesce(length(btrim(_reason)),0) < 10 THEN
    RAISE EXCEPTION 'Reason required (min 10 characters)' USING ERRCODE='22023';
  END IF;
  SELECT to_jsonb(e) INTO _before FROM public.conduct_evidence e WHERE e.id=_evidence_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Evidence not found' USING ERRCODE='P0002'; END IF;
  UPDATE public.conduct_evidence SET restricted=_restricted, updated_at=now()
  WHERE id=_evidence_id RETURNING to_jsonb(conduct_evidence) INTO _after;
  PERFORM public.log_conduct_evidence_access(_evidence_id,
    CASE WHEN _restricted THEN 'restrict' ELSE 'unrestrict' END, btrim(_reason));
  PERFORM public.log_compliance_audit('UPDATE','conduct_evidence',_evidence_id,_before,_after,btrim(_reason));
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_evidence_upload(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _id uuid; _after jsonb;
BEGIN
  _uid := public.conduct_require('market_conduct_investigation','manage_evidence_repository');
  IF coalesce(length(btrim(_payload->>'title')),0) = 0 THEN
    RAISE EXCEPTION 'Evidence title is required' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.conduct_evidence (
    title, evidence_type, file_url, file_id, description, source, restricted,
    confidentiality_level, complaint_id, investigation_id, thematic_review_id,
    alert_id, action_id, entity_id, metadata, uploaded_by
  ) VALUES (
    btrim(_payload->>'title'),
    nullif(_payload->>'evidence_type',''),
    nullif(_payload->>'file_url',''),
    nullif(_payload->>'file_id','')::uuid,
    nullif(_payload->>'description',''),
    nullif(_payload->>'source',''),
    coalesce((_payload->>'restricted')::boolean,false),
    nullif(_payload->>'confidentiality_level',''),
    nullif(_payload->>'complaint_id','')::uuid,
    nullif(_payload->>'investigation_id','')::uuid,
    nullif(_payload->>'thematic_review_id','')::uuid,
    nullif(_payload->>'alert_id','')::uuid,
    nullif(_payload->>'action_id','')::uuid,
    nullif(_payload->>'entity_id','')::uuid,
    coalesce(_payload->'metadata','{}'::jsonb),
    _uid
  ) RETURNING id INTO _id;
  SELECT to_jsonb(e) INTO _after FROM public.conduct_evidence e WHERE e.id=_id;
  PERFORM public.log_compliance_audit('CREATE','conduct_evidence',_id,NULL,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_finalise_interview(_interview_id uuid, _attestation_outcome text, _attestation_name text DEFAULT NULL::text, _signed_document_url text DEFAULT NULL::text, _refusal_reason text DEFAULT NULL::text, _refusal_witnessed_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  rec public.conduct_interviews;
  has_doc boolean;
BEGIN
  SELECT * INTO rec FROM public.conduct_interviews WHERE id = _interview_id;
  IF rec.id IS NULL THEN
    RAISE EXCEPTION 'Interview not found' USING ERRCODE = 'no_data_found';
  END IF;

  IF NOT public.can_manage_conduct_investigation(rec.investigation_id) THEN
    RAISE EXCEPTION 'Not authorised to finalise this interview record' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF rec.finalised_at IS NOT NULL THEN
    RAISE EXCEPTION 'Interview record already finalised' USING ERRCODE = 'check_violation';
  END IF;

  IF _attestation_outcome NOT IN ('signed','refused','not_required') THEN
    RAISE EXCEPTION 'Attestation outcome must be signed, refused or not_required' USING ERRCODE = 'check_violation';
  END IF;

  IF coalesce(btrim(rec.key_information), '') = '' THEN
    RAISE EXCEPTION 'Key information obtained is required before finalising' USING ERRCODE = 'check_violation';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.conduct_interview_attachments a
    WHERE a.interview_id = _interview_id AND coalesce(btrim(a.file_url),'') <> ''
  ) INTO has_doc;

  IF _attestation_outcome = 'signed'
     AND coalesce(btrim(_attestation_name), '') = ''
     AND coalesce(btrim(_signed_document_url), '') = ''
     AND NOT has_doc THEN
    RAISE EXCEPTION 'Signed records require an attestation name or an uploaded signed copy' USING ERRCODE = 'check_violation';
  END IF;

  IF _attestation_outcome = 'refused' AND length(coalesce(btrim(_refusal_reason), '')) < 10 THEN
    RAISE EXCEPTION 'Refusal reason of at least 10 characters is required' USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.conduct_interviews SET
    status = 'recorded',
    attestation_outcome = _attestation_outcome,
    attestation_name = nullif(btrim(coalesce(_attestation_name,'')), ''),
    attestation_at = CASE WHEN _attestation_outcome = 'signed' THEN now() ELSE attestation_at END,
    attestation_captured_by = auth.uid(),
    signed_document_url = nullif(btrim(coalesce(_signed_document_url,'')), ''),
    refusal_reason = nullif(btrim(coalesce(_refusal_reason,'')), ''),
    refusal_witnessed_by = nullif(btrim(coalesce(_refusal_witnessed_by,'')), ''),
    finalised_by = auth.uid(),
    finalised_at = now()
  WHERE id = _interview_id
  RETURNING * INTO rec;

  RETURN to_jsonb(rec);
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_finding_available_actions(_finding_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _f record; _uid uuid := auth.uid(); _out jsonb := '[]'::jsonb;
BEGIN
  IF _uid IS NULL THEN RETURN _out; END IF;
  SELECT * INTO _f FROM public.conduct_findings WHERE id = _finding_id;
  IF _f IS NULL THEN RETURN _out; END IF;
  IF NOT public.has_permission(_uid, 'market_conduct', 'edit') THEN RETURN _out; END IF;
  IF _f.status = 'closed' THEN RETURN _out; END IF;

  IF _f.status IN ('draft','under_analysis','response_received') THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','UPDATE_ANALYSIS','label','Update analysis','variant','outline','enabled',true,'blocked_reason',NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','description','label','Finding analysis','type','textarea','required',true,'min_length',20),
        jsonb_build_object('name','legal_basis','label','Legal / regulatory basis','type','textarea','required',false),
        jsonb_build_object('name','severity','label','Severity','type','select','required',false,'options',jsonb_build_array('low','medium','high','critical')))));
  END IF;

  IF _f.status IN ('draft','under_analysis') THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','REQUEST_ENTITY_RESPONSE','label','Request entity response','variant','default','enabled',
      (coalesce(btrim(_f.description),'') <> ''),
      'blocked_reason', CASE WHEN coalesce(btrim(_f.description),'') = '' THEN 'Record the finding analysis first' ELSE NULL END,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','note','label','What the entity must address','type','textarea','required',true,'min_length',10))));
  END IF;

  IF _f.status = 'awaiting_entity_response' THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','RECORD_RESPONSE','label','Record entity response','variant','default','enabled',true,'blocked_reason',NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','entity_response','label','Entity response','type','textarea','required',true,'min_length',10))));
  END IF;

  IF _f.status IN ('under_analysis','response_received','draft') THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','CONFIRM_FINDING','label','Confirm finding','variant','default','enabled',
      (coalesce(btrim(_f.description),'') <> ''),
      'blocked_reason', CASE WHEN coalesce(btrim(_f.description),'') = '' THEN 'Record the finding analysis first' ELSE NULL END,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','note','label','Confirmation rationale','type','textarea','required',true,'min_length',10),
        jsonb_build_object('name','risk_rating','label','Risk rating','type','select','required',false,
          'options', jsonb_build_array('low','moderate','elevated','high','severe')))));

    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','DISMISS_FINDING','label','Dismiss / false positive','variant','outline','enabled',true,'blocked_reason',NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','reason','label','Why this finding is not sustained','type','textarea','required',true,'min_length',10))));
  END IF;

  IF _f.status = 'confirmed' THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','REQUIRE_REMEDIATION','label','Require remediation','variant','default','enabled',true,'blocked_reason',NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','requirement','label','Required remediation','type','textarea','required',true,'min_length',20),
        jsonb_build_object('name','due_date','label','Remediation due date','type','date','required',true))));

    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','REFER_TO_ENFORCEMENT','label','Refer to enforcement','variant','outline','enabled',
      (_f.investigation_id IS NOT NULL OR _f.complaint_id IS NOT NULL),
      'blocked_reason', CASE WHEN _f.investigation_id IS NULL AND _f.complaint_id IS NULL
        THEN 'Enforcement referral requires a canonical complaint or investigation source' ELSE NULL END,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','note','label','Referral rationale','type','textarea','required',true,'min_length',20))));
  END IF;

  IF _f.status IN ('confirmed','remediation_required','dismissed') THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code','CLOSE_FINDING','label','Close finding','variant','outline','enabled',
      NOT EXISTS (SELECT 1 FROM public.conduct_actions a
                   WHERE a.finding_id = _f.id AND a.status NOT IN ('completed','waived','cancelled')),
      'blocked_reason', CASE WHEN EXISTS (SELECT 1 FROM public.conduct_actions a
                   WHERE a.finding_id = _f.id AND a.status NOT IN ('completed','waived','cancelled'))
        THEN 'Outstanding remediation must be completed, waived or cancelled first' ELSE NULL END,
      'inputs', jsonb_build_array(
        jsonb_build_object('name','note','label','Closure rationale','type','textarea','required',true,'min_length',10))));
  END IF;

  RETURN _out;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_finding_case(_finding_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _f record; _res jsonb;
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  SELECT f.*, l.name AS entity_name, p.full_name AS owner_name,
         i.code AS investigation_code, c.complaint_number
    INTO _f
    FROM public.conduct_findings f
    LEFT JOIN public.licensees l ON l.id = f.entity_id
    LEFT JOIN public.profiles p ON p.id = f.owner_id
    LEFT JOIN public.conduct_investigations i ON i.id = f.investigation_id
    LEFT JOIN public.complaints c ON c.id = f.complaint_id
   WHERE f.id = _finding_id;
  IF _f IS NULL THEN RAISE EXCEPTION 'Finding not found' USING ERRCODE = 'P0002'; END IF;

  _res := to_jsonb(_f) || jsonb_build_object(
    'source_href', CASE
      WHEN _f.source_type = 'conduct_investigation' THEN '/conduct/investigations/' || _f.source_id
      WHEN _f.source_type = 'complaint' THEN '/complaints/' || _f.source_id
      WHEN _f.source_type = 'conduct_alert' THEN '/conduct/alerts?alert=' || _f.source_id
      ELSE NULL END,
    'entity_href', CASE WHEN _f.entity_id IS NOT NULL THEN '/entities/' || _f.entity_id ELSE NULL END,
    'available_actions', public.conduct_finding_available_actions(_finding_id),
    'evidence', (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', e.id, 'title', e.title, 'evidence_type', e.evidence_type,
        'restricted', e.restricted, 'uploaded_at', e.uploaded_at) ORDER BY e.uploaded_at DESC), '[]'::jsonb)
      FROM public.conduct_evidence e WHERE e.finding_id = _finding_id),
    'remediation', (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', a.id, 'title', a.title, 'status', a.status, 'due_date', a.due_date,
        'href', '/conduct/actions?action=' || a.id) ORDER BY a.created_at DESC), '[]'::jsonb)
      FROM public.conduct_actions a WHERE a.finding_id = _finding_id)
  );
  RETURN _res;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_finding_next_reference()
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT 'CF-' || to_char(now(), 'YYYY') || '-' ||
         lpad((1 + coalesce((
           SELECT max(substring(f.finding_reference from '[0-9]+$')::int)
             FROM public.conduct_findings f
            WHERE f.finding_reference LIKE 'CF-' || to_char(now(), 'YYYY') || '-%'), 0))::text, 5, '0');
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_finding_raise(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid;
  _src_type text := nullif(btrim(_payload->>'source_type'), '');
  _src_id uuid := nullif(_payload->>'source_id', '')::uuid;
  _inv uuid; _cmp uuid; _entity uuid; _id uuid;
BEGIN
  _uid := public.conduct_require('market_conduct', 'edit');
  IF _src_type IS NULL OR _src_id IS NULL THEN
    RAISE EXCEPTION 'A finding must record its exact source (source_type and source_id)' USING ERRCODE = '22023';
  END IF;
  IF coalesce(length(btrim(_payload->>'title')), 0) < 5 THEN
    RAISE EXCEPTION 'A finding title of at least 5 characters is required' USING ERRCODE = '22023';
  END IF;

  IF _src_type = 'conduct_investigation' THEN
    SELECT i.id, i.licensee_id,
           CASE WHEN i.source_type = 'complaint' THEN i.source_id ELSE NULL END
      INTO _inv, _entity, _cmp
      FROM public.conduct_investigations i WHERE i.id = _src_id;
    IF _inv IS NULL THEN RAISE EXCEPTION 'Source investigation not found' USING ERRCODE = 'P0002'; END IF;
  ELSIF _src_type = 'complaint' THEN
    SELECT c.id, coalesce(c.licensee_id, c.license_holder_id) INTO _cmp, _entity
      FROM public.complaints c WHERE c.id = _src_id;
    IF _cmp IS NULL THEN RAISE EXCEPTION 'Source complaint not found' USING ERRCODE = 'P0002'; END IF;
  ELSIF _src_type = 'conduct_alert' THEN
    SELECT a.licensee_id, a.complaint_id, a.investigation_id INTO _entity, _cmp, _inv
      FROM public.conduct_alerts a WHERE a.id = _src_id;
  END IF;

  _entity := coalesce(nullif(_payload->>'entity_id','')::uuid, _entity);

  INSERT INTO public.conduct_findings(
    finding_reference, source_type, source_id, investigation_id, complaint_id, entity_id,
    category, conduct_risk_category_id, title, description, severity, legal_basis,
    status, owner_id, owner_team, created_by)
  VALUES (
    public.conduct_finding_next_reference(), _src_type, _src_id, _inv, _cmp, _entity,
    nullif(btrim(_payload->>'category'), ''),
    nullif(_payload->>'conduct_risk_category_id','')::uuid,
    btrim(_payload->>'title'),
    nullif(btrim(_payload->>'description'), ''),
    coalesce(nullif(_payload->>'severity',''), 'medium'),
    nullif(btrim(_payload->>'legal_basis'), ''),
    CASE WHEN coalesce(btrim(_payload->>'description'),'') = '' THEN 'draft' ELSE 'under_analysis' END,
    coalesce(nullif(_payload->>'owner_id','')::uuid, _uid),
    nullif(btrim(_payload->>'owner_team'), ''),
    _uid)
  RETURNING id INTO _id;

  PERFORM public.log_compliance_audit('CREATE', 'conduct_finding', _id, NULL,
    (SELECT to_jsonb(f) FROM public.conduct_findings f WHERE f.id = _id),
    'Finding raised from ' || _src_type);

  RETURN jsonb_build_object('id', _id);
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_finding_register(_statuses text[] DEFAULT NULL::text[], _entity_id uuid DEFAULT NULL::uuid, _source_type text DEFAULT NULL::text, _investigation_id uuid DEFAULT NULL::uuid, _complaint_id uuid DEFAULT NULL::uuid, _search text DEFAULT NULL::text, _include_closed boolean DEFAULT false, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, finding_reference text, title text, source_type text, source_id uuid, source_href text, investigation_id uuid, complaint_id uuid, entity_id uuid, entity_name text, category text, severity text, risk_rating text, status text, owner_id uuid, owner_name text, owner_team text, remediation_required boolean, open_remediation bigint, evidence_count bigint, enforcement_referred_at timestamp with time zone, opened_at timestamp with time zone, closed_at timestamp with time zone, last_activity_at timestamp with time zone, canonical_href text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  RETURN QUERY
  WITH scoped AS (
    SELECT f.*, l.name AS entity_name, p.full_name AS owner_name
      FROM public.conduct_findings f
      LEFT JOIN public.licensees l ON l.id = f.entity_id
      LEFT JOIN public.profiles p ON p.id = f.owner_id
     WHERE (_include_closed OR f.status <> 'closed')
       AND (_statuses IS NULL OR f.status = ANY(_statuses))
       AND (_entity_id IS NULL OR f.entity_id = _entity_id)
       AND (_source_type IS NULL OR f.source_type = _source_type)
       AND (_investigation_id IS NULL OR f.investigation_id = _investigation_id)
       AND (_complaint_id IS NULL OR f.complaint_id = _complaint_id)
       AND (_search IS NULL OR btrim(_search) = '' OR
            f.finding_reference ILIKE '%' || btrim(_search) || '%' OR
            f.title ILIKE '%' || btrim(_search) || '%' OR
            coalesce(l.name, '') ILIKE '%' || btrim(_search) || '%')
  ), counted AS (SELECT count(*) AS n FROM scoped)
  SELECT s.id, s.finding_reference, s.title, s.source_type, s.source_id,
         CASE
           WHEN s.source_type = 'conduct_investigation' THEN '/conduct/investigations/' || s.source_id
           WHEN s.source_type = 'complaint' THEN '/complaints/' || s.source_id
           WHEN s.source_type = 'conduct_alert' THEN '/conduct/alerts?alert=' || s.source_id
           ELSE NULL END,
         s.investigation_id, s.complaint_id, s.entity_id, s.entity_name, s.category,
         s.severity, s.risk_rating, s.status, s.owner_id, s.owner_name, s.owner_team,
         s.remediation_required,
         (SELECT count(*) FROM public.conduct_actions a
           WHERE a.finding_id = s.id AND a.status NOT IN ('completed','waived','cancelled')),
         (SELECT count(*) FROM public.conduct_evidence e WHERE e.finding_id = s.id),
         s.enforcement_referred_at, s.opened_at, s.closed_at,
         greatest(s.updated_at, s.created_at),
         '/conduct/findings/' || s.id,
         counted.n
    FROM scoped s CROSS JOIN counted
   ORDER BY CASE s.severity WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END,
            s.opened_at DESC
   LIMIT greatest(1, least(coalesce(_limit, 50), 200)) OFFSET greatest(0, coalesce(_offset, 0));
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_finding_register_counts(_entity_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _res jsonb;
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  SELECT jsonb_build_object(
    'total_open', count(*) FILTER (WHERE f.status <> 'closed'),
    'awaiting_response', count(*) FILTER (WHERE f.status = 'awaiting_entity_response'),
    'confirmed', count(*) FILTER (WHERE f.status = 'confirmed'),
    'remediation_required', count(*) FILTER (WHERE f.status = 'remediation_required'),
    'high_severity', count(*) FILTER (WHERE f.status <> 'closed' AND f.severity IN ('high','critical')),
    'enforcement_referred', count(*) FILTER (WHERE f.enforcement_referred_at IS NOT NULL),
    'closed', count(*) FILTER (WHERE f.status = 'closed'),
    'by_status', coalesce((SELECT jsonb_object_agg(x.status, x.n) FROM (
        SELECT g.status, count(*) AS n FROM public.conduct_findings g
         WHERE (_entity_id IS NULL OR g.entity_id = _entity_id) GROUP BY g.status) x), '{}'::jsonb))
    INTO _res
  FROM public.conduct_findings f
  WHERE (_entity_id IS NULL OR f.entity_id = _entity_id);
  RETURN coalesce(_res, '{}'::jsonb);
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_finding_step(_finding_id uuid, _action_code text, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid; _actions jsonb; _action jsonb; _before jsonb; _after jsonb; _f record; _act_id uuid;
BEGIN
  _uid := public.conduct_require('market_conduct', 'edit');
  _actions := public.conduct_finding_available_actions(_finding_id);
  SELECT a INTO _action FROM jsonb_array_elements(_actions) a WHERE a->>'action_code' = _action_code;
  IF _action IS NULL THEN
    RAISE EXCEPTION 'Action % is not available for this finding', _action_code USING ERRCODE = '42501';
  END IF;
  IF NOT coalesce((_action->>'enabled')::boolean, false) THEN
    RAISE EXCEPTION '%', coalesce(_action->>'blocked_reason', 'Action is blocked') USING ERRCODE = '22023';
  END IF;

  SELECT to_jsonb(f) INTO _before FROM public.conduct_findings f WHERE f.id = _finding_id;
  SELECT * INTO _f FROM public.conduct_findings WHERE id = _finding_id;

  IF _action_code = 'UPDATE_ANALYSIS' THEN
    IF coalesce(length(btrim(_payload->>'description')), 0) < 20 THEN
      RAISE EXCEPTION 'Finding analysis of at least 20 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_findings
       SET description = btrim(_payload->>'description'),
           legal_basis = coalesce(nullif(btrim(_payload->>'legal_basis'), ''), legal_basis),
           severity = coalesce(nullif(_payload->>'severity', ''), severity),
           status = CASE WHEN status = 'draft' THEN 'under_analysis' ELSE status END
     WHERE id = _finding_id;

  ELSIF _action_code = 'REQUEST_ENTITY_RESPONSE' THEN
    IF coalesce(length(btrim(_payload->>'note')), 0) < 10 THEN
      RAISE EXCEPTION 'Describe what the entity must address (min 10 characters)' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_findings SET status = 'awaiting_entity_response' WHERE id = _finding_id;

  ELSIF _action_code = 'RECORD_RESPONSE' THEN
    IF coalesce(length(btrim(_payload->>'entity_response')), 0) < 10 THEN
      RAISE EXCEPTION 'An entity response of at least 10 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_findings
       SET entity_response = btrim(_payload->>'entity_response'),
           entity_response_at = now(), status = 'response_received'
     WHERE id = _finding_id;

  ELSIF _action_code = 'CONFIRM_FINDING' THEN
    IF coalesce(length(btrim(_payload->>'note')), 0) < 10 THEN
      RAISE EXCEPTION 'A confirmation rationale of at least 10 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_findings
       SET status = 'confirmed',
           risk_rating = coalesce(nullif(_payload->>'risk_rating', ''), risk_rating)
     WHERE id = _finding_id;

  ELSIF _action_code = 'DISMISS_FINDING' THEN
    IF coalesce(length(btrim(_payload->>'reason')), 0) < 10 THEN
      RAISE EXCEPTION 'A dismissal reason of at least 10 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_findings
       SET status = 'dismissed', dismissal_reason = btrim(_payload->>'reason')
     WHERE id = _finding_id;

  ELSIF _action_code = 'REQUIRE_REMEDIATION' THEN
    IF coalesce(length(btrim(_payload->>'requirement')), 0) < 20
       OR coalesce(nullif(_payload->>'due_date', ''), '') = '' THEN
      RAISE EXCEPTION 'A remediation requirement (min 20 characters) and due date are required' USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.conduct_actions(
      source_module, source_id, finding_id, entity_id, action_type, title, description,
      due_date, status, created_by, metadata)
    VALUES (
      'conduct_finding', _finding_id, _finding_id, _f.entity_id, 'remediation',
      'Remediation: ' || _f.finding_reference, btrim(_payload->>'requirement'),
      (_payload->>'due_date')::date, 'open', _uid,
      jsonb_build_object('finding_reference', _f.finding_reference,
                         'source_type', _f.source_type, 'source_id', _f.source_id))
    RETURNING id INTO _act_id;
    UPDATE public.conduct_findings
       SET status = 'remediation_required', remediation_required = true
     WHERE id = _finding_id;

  ELSIF _action_code = 'REFER_TO_ENFORCEMENT' THEN
    IF coalesce(length(btrim(_payload->>'note')), 0) < 20 THEN
      RAISE EXCEPTION 'A referral rationale of at least 20 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_findings SET enforcement_referred_at = now() WHERE id = _finding_id;

  ELSIF _action_code = 'CLOSE_FINDING' THEN
    IF coalesce(length(btrim(_payload->>'note')), 0) < 10 THEN
      RAISE EXCEPTION 'A closure rationale of at least 10 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_findings
       SET status = 'closed', closed_at = now(), closure_rationale = btrim(_payload->>'note')
     WHERE id = _finding_id;
  ELSE
    RAISE EXCEPTION 'Unsupported action %', _action_code USING ERRCODE = '22023';
  END IF;

  SELECT to_jsonb(f) INTO _after FROM public.conduct_findings f WHERE f.id = _finding_id;
  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION', 'conduct_finding', _finding_id, _before, _after,
    _action_code || coalesce(' — ' || nullif(btrim(_payload->>'note'), ''), ''));

  RETURN jsonb_build_object('id', _finding_id, 'remediation_action_id', _act_id);
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_intel_aggregate(_period_start date, _period_end date, _regulator_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_from timestamptz := _period_start::timestamptz;
  v_to   timestamptz := (_period_end + 1)::timestamptz;
  v_result jsonb;
BEGIN
  IF NOT public.can_view_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501';
  END IF;

  WITH cmp AS (
    SELECT * FROM public.complaints
    WHERE created_at >= v_from AND created_at < v_to
      AND (_regulator_id IS NULL OR regulator_id = _regulator_id)
  ), alerts AS (
    SELECT * FROM public.conduct_alerts
    WHERE created_at >= v_from AND created_at < v_to
      AND (_regulator_id IS NULL OR regulator_id = _regulator_id)
  ), thm AS (
    SELECT * FROM public.thematic_reviews
    WHERE (closed_at >= v_from AND closed_at < v_to)
      AND (_regulator_id IS NULL OR regulator_id = _regulator_id)
  ), enf AS (
    SELECT * FROM public.enforcement_actions
    WHERE date_opened >= _period_start AND date_opened <= _period_end
  )
  SELECT jsonb_build_object(
    'period', jsonb_build_object('start', _period_start, 'end', _period_end),
    'generated_at', now(),
    'complaint_volume', jsonb_build_object(
      'total', (SELECT count(*) FROM cmp),
      'resolved', (SELECT count(*) FROM cmp WHERE resolved_at IS NOT NULL),
      'open', (SELECT count(*) FROM cmp WHERE resolved_at IS NULL),
      'sla_breached', (SELECT count(*) FROM cmp WHERE sla_due_at IS NOT NULL
                        AND COALESCE(resolved_at, now()) > sla_due_at),
      'vulnerable', (SELECT count(*) FROM cmp WHERE vulnerability_indicator),
      'repeat', (SELECT count(*) FROM cmp WHERE COALESCE(repeat_complaint_count,0) > 0),
      'by_severity', COALESCE((SELECT jsonb_object_agg(k, n) FROM (
          SELECT COALESCE(severity,'unspecified') AS k, count(*) AS n FROM cmp GROUP BY 1) s), '{}'::jsonb),
      'by_month', COALESCE((SELECT jsonb_agg(jsonb_build_object('bucket', b, 'count', n) ORDER BY b) FROM (
          SELECT to_char(date_trunc('month', created_at),'YYYY-MM') AS b, count(*) AS n
          FROM cmp GROUP BY 1) m), '[]'::jsonb)
    ),
    'top_issues', jsonb_build_object(
      'by_category', COALESCE((SELECT jsonb_agg(x ORDER BY (x->>'count')::int DESC) FROM (
          SELECT jsonb_build_object('label', COALESCE(rc.name,'Uncategorised'), 'count', count(*)) AS x
          FROM cmp LEFT JOIN public.conduct_risk_categories rc ON rc.id = cmp.conduct_risk_category_id
          GROUP BY rc.name ORDER BY count(*) DESC LIMIT 10) a), '[]'::jsonb),
      'by_product', COALESCE((SELECT jsonb_agg(x ORDER BY (x->>'count')::int DESC) FROM (
          SELECT jsonb_build_object('label', COALESCE(p.name,'Unspecified'), 'count', count(*)) AS x
          FROM cmp LEFT JOIN public.conduct_products p ON p.id = cmp.product_id
          GROUP BY p.name ORDER BY count(*) DESC LIMIT 10) a), '[]'::jsonb),
      'by_channel', COALESCE((SELECT jsonb_agg(x ORDER BY (x->>'count')::int DESC) FROM (
          SELECT jsonb_build_object('label', COALESCE(ch.name,'Unspecified'), 'count', count(*)) AS x
          FROM cmp LEFT JOIN public.conduct_channels ch ON ch.id = cmp.channel_id
          GROUP BY ch.name ORDER BY count(*) DESC LIMIT 10) a), '[]'::jsonb),
      'by_entity', COALESCE((SELECT jsonb_agg(x ORDER BY (x->>'count')::int DESC) FROM (
          SELECT jsonb_build_object('label', COALESCE(l.name,'Unattributed'), 'count', count(*)) AS x
          FROM cmp LEFT JOIN public.licensees l ON l.id = cmp.licensee_id
          GROUP BY l.name ORDER BY count(*) DESC LIMIT 10) a), '[]'::jsonb)
    ),
    'pattern_alerts', jsonb_build_object(
      'total', (SELECT count(*) FROM alerts),
      'open', (SELECT count(*) FROM alerts WHERE status NOT IN ('closed','dismissed')),
      'closed', (SELECT count(*) FROM alerts WHERE status IN ('closed','dismissed')),
      'by_severity', COALESCE((SELECT jsonb_object_agg(k, n) FROM (
          SELECT COALESCE(severity,'unspecified') AS k, count(*) AS n FROM alerts GROUP BY 1) s), '{}'::jsonb),
      'by_kind', COALESCE((SELECT jsonb_agg(x ORDER BY (x->>'count')::int DESC) FROM (
          SELECT jsonb_build_object('label', COALESCE(kind,'unspecified'), 'count', count(*)) AS x
          FROM alerts GROUP BY kind ORDER BY count(*) DESC LIMIT 10) a), '[]'::jsonb)
    ),
    'thematic_reviews', jsonb_build_object(
      'closed', (SELECT count(*) FROM thm),
      'items', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'code', t.code, 'title', t.title, 'closed_at', t.closed_at,
            'findings', (SELECT count(*) FROM public.thematic_review_findings f WHERE f.review_id = t.id),
            'summary', left(COALESCE(t.closure_summary,''), 500))
          ORDER BY t.closed_at DESC) FROM thm t), '[]'::jsonb)
    ),
    'enforcement', jsonb_build_object(
      'total', (SELECT count(*) FROM enf),
      'penalty_total', COALESCE((SELECT sum(COALESCE(penalty_amount,0)) FROM enf), 0),
      'by_type', COALESCE((SELECT jsonb_agg(x ORDER BY (x->>'count')::int DESC) FROM (
          SELECT jsonb_build_object('label', COALESCE(enforcement_type,'unspecified'), 'count', count(*)) AS x
          FROM enf GROUP BY enforcement_type ORDER BY count(*) DESC LIMIT 10) a), '[]'::jsonb),
      'by_status', COALESCE((SELECT jsonb_object_agg(k, n) FROM (
          SELECT COALESCE(status,'unspecified') AS k, count(*) AS n FROM enf GROUP BY 1) s), '{}'::jsonb)
    )
  ) INTO v_result;

  RETURN v_result;
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_intel_approve_report(_report_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rep record;
BEGIN
  SELECT * INTO v_rep FROM public.conduct_intelligence_reports WHERE id=_report_id;
  IF v_rep IS NULL THEN RAISE EXCEPTION 'Report not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_approve_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised to approve intelligence reports' USING ERRCODE='42501'; END IF;
  IF v_rep.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'Report is not awaiting approval' USING ERRCODE='22023'; END IF;
  IF v_rep.submitted_by IS NOT NULL AND v_rep.submitted_by = auth.uid()
     AND NOT has_role(auth.uid(),'super_admin'::app_role) THEN
    RAISE EXCEPTION 'A report cannot be approved by the officer who submitted it' USING ERRCODE='42501'; END IF;

  UPDATE public.conduct_intelligence_reports
     SET status='approved', approved_by=auth.uid(), approved_at=now()
   WHERE id=_report_id;

  PERFORM public.log_compliance_audit('APPROVE','conduct_intelligence_report', _report_id::text,
    jsonb_build_object('status','pending_approval'), jsonb_build_object('status','approved'),
    NULL, NULL, NULL, jsonb_build_object('module','market_conduct'));
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_intel_create_report(_template_code text, _title text, _period_start date, _period_end date, _regulator_id uuid DEFAULT NULL::uuid, _sector_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_tpl record; v_metrics jsonb; v_sections jsonb := '{}'::jsonb; s jsonb;
BEGIN
  IF NOT public.can_manage_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised to create intelligence reports' USING ERRCODE='42501'; END IF;
  IF _period_start IS NULL OR _period_end IS NULL OR _period_end < _period_start THEN
    RAISE EXCEPTION 'A valid reporting period is required' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_tpl FROM public.conduct_intelligence_templates WHERE code = _template_code;

  INSERT INTO public.conduct_intelligence_reports(
    template_id, template_code, title, period_start, period_end,
    regulator_id, sector_id, status, created_by)
  VALUES (v_tpl.id, COALESCE(_template_code,'custom'),
    COALESCE(NULLIF(btrim(_title),''), COALESCE(v_tpl.name,'Conduct Intelligence Report')),
    _period_start, _period_end, _regulator_id, _sector_id, 'draft', auth.uid())
  RETURNING id INTO v_id;

  v_metrics := public.conduct_intel_aggregate(_period_start, _period_end, _regulator_id);

  FOR s IN SELECT jsonb_array_elements(COALESCE(v_tpl.sections, '[]'::jsonb))
  LOOP
    v_sections := v_sections || jsonb_build_object(s->>'key', jsonb_build_object('narrative',''));
  END LOOP;

  INSERT INTO public.conduct_intelligence_report_versions(report_id, version, sections, metrics, generated_by, change_note)
  VALUES (v_id, 1, v_sections, v_metrics, auth.uid(), 'Initial generation');

  UPDATE public.conduct_intelligence_reports SET current_version = 1 WHERE id = v_id;

  PERFORM public.log_compliance_audit('CREATE','conduct_intelligence_report', v_id::text, NULL,
    jsonb_build_object('template', _template_code, 'period_start', _period_start, 'period_end', _period_end),
    NULL, NULL, NULL, jsonb_build_object('module','market_conduct','event','INTELLIGENCE_REPORT_GENERATED'));

  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_intel_log_export(_report_id uuid, _format text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.can_view_conduct_intelligence()
          OR EXISTS (SELECT 1 FROM public.conduct_intelligence_report_recipients r
                     JOIN public.conduct_intelligence_reports rep ON rep.id = r.report_id
                     WHERE r.report_id = _report_id AND rep.status = 'published'
                       AND public.can_current_user_access_licensee(r.licensee_id))) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501';
  END IF;
  PERFORM public.log_compliance_audit('EXPORT','conduct_intelligence_report', _report_id::text,
    NULL, jsonb_build_object('format', COALESCE(_format,'pdf')), NULL, NULL, NULL,
    jsonb_build_object('module','market_conduct','event','INTELLIGENCE_REPORT_EXPORTED'));
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_intel_publish_report(_report_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rep record; v_count integer := 0; v_prev uuid;
BEGIN
  SELECT * INTO v_rep FROM public.conduct_intelligence_reports WHERE id=_report_id;
  IF v_rep IS NULL THEN RAISE EXCEPTION 'Report not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_approve_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised to publish intelligence reports' USING ERRCODE='42501'; END IF;
  IF v_rep.status <> 'approved' THEN
    RAISE EXCEPTION 'Only an approved report can be published' USING ERRCODE='22023'; END IF;

  SELECT id INTO v_prev FROM public.conduct_intelligence_reports
   WHERE status='published' AND template_code = v_rep.template_code
     AND COALESCE(regulator_id,'00000000-0000-0000-0000-000000000000'::uuid)
         = COALESCE(v_rep.regulator_id,'00000000-0000-0000-0000-000000000000'::uuid)
   ORDER BY published_at DESC LIMIT 1;

  IF v_prev IS NOT NULL THEN
    UPDATE public.conduct_intelligence_reports
       SET status='superseded', superseded_at=now() WHERE id=v_prev;
  END IF;

  UPDATE public.conduct_intelligence_reports
     SET status='published', published_by=auth.uid(), published_at=now(),
         supersedes_report_id=v_prev
   WHERE id=_report_id;

  IF v_rep.publish_to_sector THEN
    INSERT INTO public.conduct_intelligence_report_recipients(report_id, licensee_id)
    SELECT _report_id, l.id FROM public.licensees l
     WHERE (v_rep.sector_id IS NULL OR l.sector_id = v_rep.sector_id)
    ON CONFLICT (report_id, licensee_id) DO NOTHING;
    GET DIAGNOSTICS v_count = ROW_COUNT;
  END IF;

  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION','conduct_intelligence_report', _report_id::text,
    jsonb_build_object('status','approved'), jsonb_build_object('status','published'),
    NULL, NULL, NULL, jsonb_build_object('module','market_conduct',
      'event','INTELLIGENCE_REPORT_PUBLISHED','recipients',v_count,'supersedes',v_prev));

  PERFORM public.notification_enqueue_event('conduct_intelligence_report_published','conduct_intelligence_report',
    _report_id, jsonb_build_object('report_title', v_rep.title,
      'period', v_rep.period_start::text||' to '||v_rep.period_end::text,
      'recipients', v_count), _report_id::text, NULL, NULL);

  RETURN v_count;
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_intel_reject_report(_report_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rep record;
BEGIN
  IF _reason IS NULL OR length(btrim(_reason)) < 10 THEN
    RAISE EXCEPTION 'A rejection reason of at least 10 characters is required' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_rep FROM public.conduct_intelligence_reports WHERE id=_report_id;
  IF v_rep IS NULL THEN RAISE EXCEPTION 'Report not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_approve_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;
  IF v_rep.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'Report is not awaiting approval' USING ERRCODE='22023'; END IF;

  UPDATE public.conduct_intelligence_reports
     SET status='rejected', rejection_reason=btrim(_reason)
   WHERE id=_report_id;

  PERFORM public.log_compliance_audit('REJECT','conduct_intelligence_report', _report_id::text,
    jsonb_build_object('status','pending_approval'), jsonb_build_object('status','rejected'),
    btrim(_reason), NULL, NULL, jsonb_build_object('module','market_conduct'));
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_intel_save_version(_report_id uuid, _sections jsonb, _ai_draft jsonb DEFAULT NULL::jsonb, _regenerate boolean DEFAULT false, _change_note text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rep record; v_ver integer; v_metrics jsonb; v_prev record;
BEGIN
  SELECT * INTO v_rep FROM public.conduct_intelligence_reports WHERE id = _report_id;
  IF v_rep IS NULL THEN RAISE EXCEPTION 'Report not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_manage_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;
  IF v_rep.status NOT IN ('draft','rejected') THEN
    RAISE EXCEPTION 'Only draft or rejected reports can be edited' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_prev FROM public.conduct_intelligence_report_versions
   WHERE report_id = _report_id ORDER BY version DESC LIMIT 1;

  IF _regenerate OR v_prev IS NULL THEN
    v_metrics := public.conduct_intel_aggregate(v_rep.period_start, v_rep.period_end, v_rep.regulator_id);
  ELSE
    v_metrics := v_prev.metrics;
  END IF;

  v_ver := COALESCE(v_prev.version, 0) + 1;

  INSERT INTO public.conduct_intelligence_report_versions(
    report_id, version, sections, metrics, ai_draft, generated_by, change_note)
  VALUES (_report_id, v_ver, COALESCE(_sections,'{}'::jsonb), v_metrics,
    COALESCE(_ai_draft, COALESCE(v_prev.ai_draft,'{}'::jsonb)), auth.uid(),
    COALESCE(NULLIF(btrim(COALESCE(_change_note,'')),''),
             CASE WHEN _regenerate THEN 'Data regenerated' ELSE 'Narrative saved' END));

  UPDATE public.conduct_intelligence_reports
     SET current_version = v_ver, status = 'draft', rejection_reason = NULL
   WHERE id = _report_id;

  IF _regenerate THEN
    PERFORM public.log_compliance_audit('UPDATE','conduct_intelligence_report', _report_id::text, NULL,
      jsonb_build_object('version', v_ver), NULL, NULL, NULL,
      jsonb_build_object('module','market_conduct','event','INTELLIGENCE_REPORT_GENERATED'));
  END IF;

  RETURN v_ver;
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_intel_submit_for_approval(_report_id uuid, _publish_to_sector boolean DEFAULT false, _approver_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rep record; v_sections jsonb; v_exec text;
BEGIN
  SELECT * INTO v_rep FROM public.conduct_intelligence_reports WHERE id = _report_id;
  IF v_rep IS NULL THEN RAISE EXCEPTION 'Report not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_manage_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;
  IF v_rep.status NOT IN ('draft','rejected') THEN
    RAISE EXCEPTION 'Only a draft report can be submitted for approval' USING ERRCODE='22023'; END IF;

  SELECT sections INTO v_sections FROM public.conduct_intelligence_report_versions
   WHERE report_id = _report_id ORDER BY version DESC LIMIT 1;
  v_exec := btrim(COALESCE(v_sections #>> '{executive_summary,narrative}',''));
  IF v_exec = '' THEN
    RAISE EXCEPTION 'The Executive Summary must be completed before the report can be submitted'
      USING ERRCODE='22023';
  END IF;

  UPDATE public.conduct_intelligence_reports
     SET status='pending_approval', submitted_at=now(), submitted_by=auth.uid(),
         approver_id=_approver_id, publish_to_sector=COALESCE(_publish_to_sector,false),
         rejection_reason=NULL
   WHERE id=_report_id;

  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION','conduct_intelligence_report', _report_id::text,
    jsonb_build_object('status', v_rep.status), jsonb_build_object('status','pending_approval'),
    NULL, NULL, NULL, jsonb_build_object('module','market_conduct'));

  PERFORM public.notification_enqueue_event('conduct_intelligence_report_submitted','conduct_intelligence_report',
    _report_id, jsonb_build_object('report_title', v_rep.title, 'period', v_rep.period_start::text||' to '||v_rep.period_end::text),
    _report_id::text, NULL, NULL);
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_investigation_available_actions(_investigation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _s record;
  _can boolean;
  _blockers jsonb;
  _out jsonb := '[]'::jsonb;
BEGIN
  IF _uid IS NULL THEN RETURN _out; END IF;
  SELECT * INTO _s FROM public.v_conduct_investigation_state WHERE id = _investigation_id;
  IF _s IS NULL THEN RETURN _out; END IF;
  _can := public.has_permission(_uid, 'market_conduct', 'initiate_investigation');
  IF NOT _can OR _s.is_terminal THEN RETURN _out; END IF;
  _blockers := public.conduct_investigation_blockers(_investigation_id);

  IF _s.assigned_to IS NULL THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code', 'ASSIGN_OWNER', 'label', 'Assign investigating officer',
      'variant', 'default', 'enabled', true, 'blocked_reason', NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name', 'assigned_investigator', 'label', 'Investigating officer', 'type', 'user', 'required', true))));
  END IF;

  IF _s.stage = 'INTAKE' THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code', 'RECORD_PLAN', 'label', 'Record scope, legal basis and plan',
      'variant', 'outline', 'enabled', true, 'blocked_reason', NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name', 'scope', 'label', 'Investigation scope', 'type', 'textarea', 'required', true, 'min_length', 20),
        jsonb_build_object('name', 'legal_basis', 'label', 'Legal basis', 'type', 'textarea', 'required', true, 'min_length', 10),
        jsonb_build_object('name', 'investigation_plan', 'label', 'Investigation plan', 'type', 'textarea', 'required', false),
        jsonb_build_object('name', 'due_date', 'label', 'Target completion date', 'type', 'date', 'required', true))));

    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code', 'BEGIN_EVIDENCE', 'label', 'Begin evidence gathering',
      'variant', 'default',
      'enabled', (_blockers = '[]'::jsonb),
      'blocked_reason', CASE WHEN _blockers = '[]'::jsonb THEN NULL
        ELSE 'Owner, scope, legal basis and target date must be recorded first' END,
      'inputs', '[]'::jsonb));
  END IF;

  IF _s.stage = 'EVIDENCE' THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code', 'BEGIN_ANALYSIS', 'label', 'Move to analysis',
      'variant', 'default',
      'enabled', (_s.evidence_count > 0),
      'blocked_reason', CASE WHEN _s.evidence_count > 0 THEN NULL
        ELSE 'Record at least one item of evidence before analysis' END,
      'inputs', jsonb_build_array(
        jsonb_build_object('name', 'note', 'label', 'Analysis entry note', 'type', 'textarea', 'required', false))));
  END IF;

  IF _s.stage = 'ANALYSIS' THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code', 'PROPOSE_OUTCOME', 'label', 'Record proposed outcome',
      'variant', 'default', 'enabled', true, 'blocked_reason', NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name', 'outcome', 'label', 'Proposed outcome', 'type', 'textarea', 'required', true, 'min_length', 20))));
  END IF;

  IF _s.stage = 'PROPOSED_OUTCOME' THEN
    _out := _out || jsonb_build_array(jsonb_build_object(
      'action_code', 'RETURN_TO_ANALYSIS', 'label', 'Return to analysis',
      'variant', 'outline', 'enabled', true, 'blocked_reason', NULL,
      'inputs', jsonb_build_array(
        jsonb_build_object('name', 'note', 'label', 'Reason for further analysis', 'type', 'textarea', 'required', true, 'min_length', 10))));
  END IF;

  RETURN _out;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_investigation_blockers(_investigation_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(jsonb_agg(b ORDER BY b->>'code'), '[]'::jsonb)
  FROM public.v_conduct_investigation_state s
  CROSS JOIN LATERAL (
    SELECT jsonb_build_object('code', code, 'label', label) AS b
    FROM (VALUES
      ('NO_OWNER', 'Assign an investigating officer',
        s.assigned_to IS NULL AND NOT s.is_terminal),
      ('NO_SCOPE', 'Record the investigation scope and legal basis',
        (coalesce(btrim(s.scope), '') = '' OR coalesce(btrim(s.legal_basis), '') = '') AND NOT s.is_terminal),
      ('NO_DUE_DATE', 'Set a target completion date',
        s.due_date IS NULL AND NOT s.is_terminal),
      ('NO_EVIDENCE', 'Record at least one item of evidence before analysis',
        s.evidence_count = 0 AND s.stage IN ('EVIDENCE', 'ANALYSIS')),
      ('NO_OUTCOME', 'Record the proposed outcome',
        coalesce(btrim(s.outcome), '') = '' AND s.stage = 'PROPOSED_OUTCOME')
    ) AS v(code, label, active)
    WHERE v.active
  ) x
  WHERE s.id = _investigation_id;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_investigation_case(_investigation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _s record; _res jsonb;
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  IF NOT public.can_view_conduct_investigation(_investigation_id) THEN
    RAISE EXCEPTION 'Permission denied for this investigation' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _s FROM public.v_conduct_investigation_state WHERE id = _investigation_id;
  IF _s IS NULL THEN RAISE EXCEPTION 'Investigation not found' USING ERRCODE = 'P0002'; END IF;

  _res := jsonb_build_object(
    'id', _s.id,
    'reference', coalesce(_s.code, left(_s.id::text, 8)),
    'subject', left(_s.allegation, 160),
    'entity_id', _s.entity_id,
    'entity_name', _s.entity_name,
    'entity_href', CASE WHEN _s.entity_id IS NOT NULL THEN '/entities/' || _s.entity_id ELSE NULL END,
    'stage', _s.stage,
    'stage_label', _s.stage_label,
    'stage_seq', _s.stage_seq,
    'status', _s.status,
    'is_terminal', _s.is_terminal,
    'priority', _s.priority,
    'severity', _s.severity,
    'source_type', _s.source_type,
    'source_id', _s.source_id,
    'assigned_to', _s.assigned_to,
    'assigned_to_name', _s.assigned_to_name,
    'due_date', _s.due_date,
    'sla_due_at', _s.sla_due_at,
    'sla_state', _s.sla_state,
    'waiting_on', CASE
      WHEN _s.is_terminal THEN NULL
      WHEN _s.stage = 'PROPOSED_OUTCOME' THEN 'Supervisory approval'
      WHEN _s.assigned_to IS NULL THEN 'Case allocation'
      ELSE 'Investigating officer' END,
    'scope', _s.scope,
    'legal_basis', _s.legal_basis,
    'investigation_plan', _s.investigation_plan,
    'outcome', _s.outcome,
    'closure_status', _s.closure_status,
    'evidence_count', _s.evidence_count,
    'interview_count', _s.interview_count,
    'open_action_count', _s.open_action_count,
    'last_activity_at', _s.last_activity_at,
    'blockers', public.conduct_investigation_blockers(_investigation_id),
    'available_actions', public.conduct_investigation_available_actions(_investigation_id),
    'timeline', (
      SELECT coalesce(jsonb_agg(t ORDER BY t->>'at'), '[]'::jsonb) FROM (
        SELECT jsonb_build_object('at', _s.created_at, 'code', 'OPENED', 'label', 'Investigation opened') AS t
        UNION ALL
        SELECT jsonb_build_object('at', e.uploaded_at, 'code', 'EVIDENCE', 'label', 'Evidence: ' || e.title)
          FROM public.conduct_evidence e WHERE e.investigation_id = _s.id
        UNION ALL
        SELECT jsonb_build_object('at', v.created_at, 'code', 'INTERVIEW', 'label', 'Interview recorded')
          FROM public.conduct_interviews v WHERE v.investigation_id = _s.id
        UNION ALL
        SELECT jsonb_build_object('at', c.created_at, 'code', 'CLOSURE_' || upper(c.status),
                                  'label', 'Closure determination ' || c.status)
          FROM public.conduct_investigation_closures c WHERE c.investigation_id = _s.id
      ) z
    )
  );
  RETURN _res;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_investigation_open(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _id uuid; _after jsonb;
BEGIN
  _uid := public.conduct_require('market_conduct','initiate_investigation');
  IF coalesce(length(btrim(_payload->>'allegation')),0) < 10 THEN
    RAISE EXCEPTION 'Allegation summary required (min 10 characters)' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.conduct_investigations (
    source_type, source_id, licensee_id, product_id, allegation, priority, severity,
    assigned_investigator, status, due_date, scope, legal_basis, investigation_plan,
    metadata, opened_by
  ) VALUES (
    coalesce(_payload->>'source_type','manual'),
    nullif(_payload->>'source_id','')::uuid,
    nullif(_payload->>'licensee_id','')::uuid,
    nullif(_payload->>'product_id','')::uuid,
    btrim(_payload->>'allegation'),
    nullif(_payload->>'priority',''),
    nullif(_payload->>'severity',''),
    nullif(_payload->>'assigned_investigator','')::uuid,
    coalesce(nullif(_payload->>'status',''),'open'),
    nullif(_payload->>'due_date','')::date,
    nullif(_payload->>'scope',''),
    nullif(_payload->>'legal_basis',''),
    nullif(_payload->>'investigation_plan',''),
    coalesce(_payload->'metadata','{}'::jsonb),
    _uid
  ) RETURNING id INTO _id;
  SELECT to_jsonb(i) INTO _after FROM public.conduct_investigations i WHERE i.id=_id;
  PERFORM public.log_compliance_audit('CREATE','conduct_investigation',_id,NULL,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_investigation_step(_investigation_id uuid, _action_code text, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid;
  _actions jsonb;
  _action jsonb;
  _before jsonb;
  _after jsonb;
  _new_status text;
BEGIN
  _uid := public.conduct_require('market_conduct', 'initiate_investigation');
  _actions := public.conduct_investigation_available_actions(_investigation_id);
  SELECT a INTO _action FROM jsonb_array_elements(_actions) a
   WHERE a->>'action_code' = _action_code;
  IF _action IS NULL THEN
    RAISE EXCEPTION 'Action % is not available for this investigation', _action_code USING ERRCODE = '42501';
  END IF;
  IF NOT coalesce((_action->>'enabled')::boolean, false) THEN
    RAISE EXCEPTION '%', coalesce(_action->>'blocked_reason', 'Action is blocked') USING ERRCODE = '22023';
  END IF;

  SELECT to_jsonb(i) INTO _before FROM public.conduct_investigations i WHERE i.id = _investigation_id;

  IF _action_code = 'ASSIGN_OWNER' THEN
    IF coalesce(nullif(_payload->>'assigned_investigator', ''), '') = '' THEN
      RAISE EXCEPTION 'An investigating officer is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_investigations
       SET assigned_investigator = (_payload->>'assigned_investigator')::uuid, updated_at = now()
     WHERE id = _investigation_id;

  ELSIF _action_code = 'RECORD_PLAN' THEN
    IF coalesce(length(btrim(_payload->>'scope')), 0) < 20
       OR coalesce(length(btrim(_payload->>'legal_basis')), 0) < 10
       OR coalesce(nullif(_payload->>'due_date', ''), '') = '' THEN
      RAISE EXCEPTION 'Scope (min 20 chars), legal basis (min 10 chars) and target date are required'
        USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_investigations
       SET scope = btrim(_payload->>'scope'),
           legal_basis = btrim(_payload->>'legal_basis'),
           investigation_plan = coalesce(nullif(btrim(_payload->>'investigation_plan'), ''), investigation_plan),
           due_date = (_payload->>'due_date')::date,
           updated_at = now()
     WHERE id = _investigation_id;

  ELSIF _action_code IN ('BEGIN_EVIDENCE', 'BEGIN_ANALYSIS', 'RETURN_TO_ANALYSIS') THEN
    _new_status := CASE _action_code
      WHEN 'BEGIN_EVIDENCE' THEN 'evidence_gathering'
      ELSE 'analysis' END;
    IF _action_code = 'RETURN_TO_ANALYSIS' AND coalesce(length(btrim(_payload->>'note')), 0) < 10 THEN
      RAISE EXCEPTION 'A reason of at least 10 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_investigations
       SET status = _new_status, updated_at = now()
     WHERE id = _investigation_id;

  ELSIF _action_code = 'PROPOSE_OUTCOME' THEN
    IF coalesce(length(btrim(_payload->>'outcome')), 0) < 20 THEN
      RAISE EXCEPTION 'A proposed outcome of at least 20 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.conduct_investigations
       SET outcome = btrim(_payload->>'outcome'), status = 'proposed_outcome', updated_at = now()
     WHERE id = _investigation_id;

  ELSE
    RAISE EXCEPTION 'Unsupported action %', _action_code USING ERRCODE = '22023';
  END IF;

  SELECT to_jsonb(i) INTO _after FROM public.conduct_investigations i WHERE i.id = _investigation_id;
  PERFORM public.log_compliance_audit(
    'WORKFLOW_TRANSITION', 'conduct_investigation', _investigation_id, _before, _after,
    _action_code || coalesce(' — ' || nullif(btrim(_payload->>'note'), ''), ''));

  RETURN public.conduct_investigation_case(_investigation_id);
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_investigation_update(_investigation_id uuid, _patch jsonb, _justification text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb; _closing boolean;
BEGIN
  _uid := public.conduct_require('market_conduct','initiate_investigation');
  SELECT to_jsonb(i) INTO _before FROM public.conduct_investigations i WHERE i.id=_investigation_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Investigation not found' USING ERRCODE='P0002'; END IF;
  _closing := (_patch->>'status') = 'closed' AND coalesce(_before->>'status','') <> 'closed';
  IF _closing AND coalesce(length(btrim(_justification)),0) < 10 THEN
    RAISE EXCEPTION 'Closure justification required (min 10 characters)' USING ERRCODE='22023';
  END IF;
  UPDATE public.conduct_investigations SET
    status = coalesce(nullif(_patch->>'status',''), status),
    priority = coalesce(nullif(_patch->>'priority',''), priority),
    severity = coalesce(nullif(_patch->>'severity',''), severity),
    allegation = coalesce(nullif(_patch->>'allegation',''), allegation),
    assigned_investigator = CASE WHEN _patch ? 'assigned_investigator'
      THEN nullif(_patch->>'assigned_investigator','')::uuid ELSE assigned_investigator END,
    due_date = CASE WHEN _patch ? 'due_date' THEN nullif(_patch->>'due_date','')::date ELSE due_date END,
    scope = coalesce(nullif(_patch->>'scope',''), scope),
    legal_basis = coalesce(nullif(_patch->>'legal_basis',''), legal_basis),
    investigation_plan = coalesce(nullif(_patch->>'investigation_plan',''), investigation_plan),
    milestones = coalesce(_patch->'milestones', milestones),
    outcome = coalesce(nullif(_patch->>'outcome',''), outcome),
    closure_reason = coalesce(nullif(_patch->>'closure_reason',''), closure_reason),
    metadata = coalesce(_patch->'metadata', metadata),
    closed_by = CASE WHEN _closing THEN _uid ELSE closed_by END,
    closed_at = CASE WHEN _closing THEN now() ELSE closed_at END,
    updated_at = now()
  WHERE id=_investigation_id
  RETURNING to_jsonb(conduct_investigations) INTO _after;
  PERFORM public.log_compliance_audit(
    CASE WHEN _closing THEN 'APPROVE' ELSE 'UPDATE' END,
    'conduct_investigation',_investigation_id,_before,_after,_justification);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_monitoring_directive_upsert(_investigation_id uuid, _monitoring_id uuid DEFAULT NULL::uuid, _closure_id uuid DEFAULT NULL::uuid, _focus_areas text DEFAULT NULL::text, _indicators text DEFAULT NULL::text, _entity_reporting_requirement text DEFAULT NULL::text, _frequency text DEFAULT 'quarterly'::text, _start_date date DEFAULT NULL::date, _end_date date DEFAULT NULL::date, _owner_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_lic uuid;
BEGIN
  IF NOT public.can_manage_conduct_investigation(_investigation_id) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;
  IF _focus_areas IS NULL OR length(btrim(_focus_areas)) < 10 THEN
    RAISE EXCEPTION 'Monitoring focus areas of at least 10 characters are required' USING ERRCODE='22023'; END IF;
  IF coalesce(_frequency,'quarterly') NOT IN ('monthly','quarterly','semi_annual','annual') THEN
    RAISE EXCEPTION 'Invalid monitoring frequency' USING ERRCODE='22023'; END IF;

  SELECT licensee_id INTO v_lic FROM public.conduct_investigations WHERE id=_investigation_id;

  IF _monitoring_id IS NOT NULL THEN
    UPDATE public.conduct_post_closure_monitoring SET
      closure_id=coalesce(_closure_id, closure_id),
      focus_areas=btrim(_focus_areas), indicators=_indicators,
      entity_reporting_requirement=_entity_reporting_requirement,
      frequency=coalesce(_frequency,'quarterly'),
      start_date=coalesce(_start_date, start_date),
      end_date=_end_date, owner_id=_owner_id
    WHERE id=_monitoring_id RETURNING id INTO v_id;
    IF v_id IS NULL THEN RAISE EXCEPTION 'Monitoring directive not found' USING ERRCODE='P0002'; END IF;
  ELSE
    INSERT INTO public.conduct_post_closure_monitoring(
      investigation_id, closure_id, licensee_id, focus_areas, indicators,
      entity_reporting_requirement, frequency, start_date, end_date, owner_id, created_by)
    VALUES (_investigation_id, _closure_id, v_lic, btrim(_focus_areas), _indicators,
      _entity_reporting_requirement, coalesce(_frequency,'quarterly'),
      coalesce(_start_date, CURRENT_DATE), _end_date, _owner_id, auth.uid())
    RETURNING id INTO v_id;
  END IF;

  PERFORM public.log_compliance_audit('UPDATE','conduct_post_closure_monitoring', v_id::text,
    NULL, jsonb_build_object('focus_areas', btrim(_focus_areas), 'frequency', _frequency),
    'Post-closure monitoring directive saved', NULL, NULL,
    jsonb_build_object('module','market_conduct','investigation_id',_investigation_id));
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_monitoring_review_record(_review_id uuid, _observations text, _outcome text DEFAULT 'satisfactory'::text, _escalate boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_r record; v_m record; v_next date;
BEGIN
  SELECT * INTO v_r FROM public.conduct_monitoring_reviews WHERE id=_review_id;
  IF v_r IS NULL THEN RAISE EXCEPTION 'Monitoring review not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_m FROM public.conduct_post_closure_monitoring WHERE id=v_r.monitoring_id;
  IF NOT public.can_manage_conduct_investigation(v_m.investigation_id) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;
  IF _observations IS NULL OR length(btrim(_observations)) < 10 THEN
    RAISE EXCEPTION 'Review observations of at least 10 characters are required' USING ERRCODE='23514'; END IF;

  UPDATE public.conduct_monitoring_reviews SET
    status='completed', observations=btrim(_observations), outcome=_outcome,
    reviewed_by=auth.uid(), reviewed_at=now(), escalated=coalesce(_escalate,false)
  WHERE id=_review_id;

  v_next := (v_r.due_date + (CASE v_m.frequency WHEN 'monthly' THEN interval '1 month'
                                                WHEN 'quarterly' THEN interval '3 months'
                                                WHEN 'semi_annual' THEN interval '6 months'
                                                ELSE interval '12 months' END))::date;

  IF v_m.end_date IS NULL OR v_next <= v_m.end_date THEN
    INSERT INTO public.conduct_monitoring_reviews(monitoring_id, due_date) VALUES (v_m.id, v_next);
    UPDATE public.conduct_post_closure_monitoring SET next_review_date=v_next WHERE id=v_m.id;
  ELSE
    UPDATE public.conduct_post_closure_monitoring
       SET status='completed', closed_at=now(), next_review_date=NULL WHERE id=v_m.id;
  END IF;

  PERFORM public.log_compliance_audit('UPDATE','conduct_monitoring_review', _review_id::text,
    jsonb_build_object('status', v_r.status),
    jsonb_build_object('status','completed','outcome',_outcome),
    btrim(_observations), NULL, NULL,
    jsonb_build_object('module','market_conduct','investigation_id',v_m.investigation_id));
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _res jsonb;
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  SELECT jsonb_build_object(
    'work', jsonb_build_object(
      'open_total', count(*) FILTER (WHERE NOT i.is_terminal),
      'breached', count(*) FILTER (WHERE NOT i.is_terminal AND i.sla_state = 'breached'),
      'due_soon', count(*) FILTER (WHERE NOT i.is_terminal AND i.sla_state = 'due_soon'),
      'unassigned', count(*) FILTER (WHERE NOT i.is_terminal AND i.assigned_to IS NULL),
      'complaints_open', count(*) FILTER (WHERE NOT i.is_terminal AND i.kind = 'COMPLAINT'),
      'alerts_open', count(*) FILTER (WHERE NOT i.is_terminal AND i.kind = 'ALERT'),
      'investigations_open', count(*) FILTER (WHERE NOT i.is_terminal AND i.kind = 'INVESTIGATION'),
      'findings_open', count(*) FILTER (WHERE NOT i.is_terminal AND i.kind = 'FINDING'),
      'remediation_open', count(*) FILTER (WHERE NOT i.is_terminal AND i.kind = 'ACTION')))
    INTO _res
  FROM public.v_conduct_work_items i;

  _res := _res || jsonb_build_object(
    'remediation', (SELECT jsonb_build_object(
        'overdue', count(*) FILTER (WHERE r.is_overdue),
        'under_review', count(*) FILTER (WHERE r.status = 'under_review'),
        'escalated', count(*) FILTER (WHERE r.status = 'escalated'),
        'evidence_outstanding', count(*) FILTER (WHERE NOT r.is_terminal AND r.evidence_status = 'outstanding'))
      FROM public.v_conduct_action_state r),
    'findings', (SELECT jsonb_build_object(
        'confirmed', count(*) FILTER (WHERE f.status = 'confirmed'),
        'under_analysis', count(*) FILTER (WHERE f.status = 'under_analysis'),
        'dismissed', count(*) FILTER (WHERE f.status = 'dismissed'),
        'remediation_required', count(*) FILTER (WHERE f.status = 'remediation_required'))
      FROM public.conduct_findings f),
    'top_entities', (SELECT coalesce(jsonb_agg(t), '[]'::jsonb) FROM (
        SELECT i.entity_id, i.entity_name,
               count(*) AS open_items,
               count(*) FILTER (WHERE i.sla_state = 'breached') AS breached_items,
               '/entities/' || i.entity_id AS entity_href
          FROM public.v_conduct_work_items i
         WHERE NOT i.is_terminal AND i.entity_id IS NOT NULL
         GROUP BY i.entity_id, i.entity_name
         ORDER BY count(*) FILTER (WHERE i.sla_state = 'breached') DESC, count(*) DESC
         LIMIT 10) t));
  RETURN coalesce(_res, '{}'::jsonb);
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_related_cases(_case_type text, _case_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_entity uuid;
BEGIN
  IF v_user IS NULL OR NOT public.is_internal_staff(v_user) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _case_type NOT IN ('complaint', 'conduct_investigation') THEN
    RAISE EXCEPTION 'unsupported_case_type' USING ERRCODE = '22023';
  END IF;

  IF _case_type = 'complaint' THEN
    SELECT licensee_id INTO v_entity FROM public.complaints WHERE id = _case_id;
  ELSE
    SELECT licensee_id INTO v_entity FROM public.conduct_investigations WHERE id = _case_id;
  END IF;

  RETURN jsonb_build_object(
    'case_type', _case_type,
    'case_id', _case_id,
    'entity', CASE WHEN v_entity IS NOT NULL THEN jsonb_build_object(
        'id', v_entity,
        'name', (SELECT l.entity_name FROM public.licensees l WHERE l.id = v_entity),
        'href', '/entities/' || v_entity) END,
    'enforcement', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', e.id, 'case_number', e.case_number,
               'status', e.status, 'source_kind', COALESCE(e.source_kind, e.source_type),
               'href', '/enforcement/' || e.id) ORDER BY e.created_at DESC), '[]'::jsonb)
        FROM public.enforcement_actions e
       WHERE (_case_type = 'complaint'
              AND ((e.source_type = 'complaint' AND e.source_id = _case_id)
                   OR (e.source_kind = 'COMPLAINT' AND e.source_reference_id = _case_id)
                   OR e.id IN (SELECT c.enforcement_action_id FROM public.complaints c WHERE c.id = _case_id)))
          OR (_case_type = 'conduct_investigation'
              AND ((e.source_type = 'conduct_investigation' AND e.source_id = _case_id)
                   OR (e.source_kind = 'CONDUCT_INVESTIGATION' AND e.source_reference_id = _case_id)
                   OR e.source_investigation_id = _case_id))),
    'investigations', CASE WHEN _case_type = 'complaint' THEN (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', i.id, 'code', i.code, 'status', i.status,
               'href', '/conduct/investigations/' || i.id) ORDER BY i.created_at DESC), '[]'::jsonb)
        FROM public.conduct_investigations i
       WHERE i.source_type = 'complaint' AND i.source_id = _case_id) ELSE '[]'::jsonb END,
    'complaints', CASE WHEN _case_type = 'conduct_investigation' THEN (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', c.id, 'reference', c.complaint_number,
               'status', c.status, 'href', '/complaints/' || c.id) ORDER BY c.created_at DESC), '[]'::jsonb)
        FROM public.complaints c
       WHERE c.id IN (SELECT i.source_id FROM public.conduct_investigations i
                       WHERE i.id = _case_id AND i.source_type = 'complaint')) ELSE '[]'::jsonb END,
    'alerts', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', a.id, 'title', a.title, 'status', a.status,
               'severity', a.severity, 'href', '/conduct/alerts') ORDER BY a.created_at DESC), '[]'::jsonb)
        FROM public.conduct_alerts a
       WHERE (_case_type = 'complaint' AND a.complaint_id = _case_id)
          OR (_case_type = 'conduct_investigation' AND a.investigation_id = _case_id)),
    'findings', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', f.id, 'reference', f.finding_reference,
               'title', f.title, 'status', f.status, 'risk_rating', f.risk_rating,
               'href', '/conduct/findings/' || f.id) ORDER BY f.created_at DESC), '[]'::jsonb)
        FROM public.conduct_findings f
       WHERE (_case_type = 'complaint' AND f.complaint_id = _case_id)
          OR (_case_type = 'conduct_investigation' AND f.investigation_id = _case_id)),
    'remediation_actions', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', ac.id, 'title', ac.title, 'status', ac.status,
               'due_date', ac.due_date, 'href', '/conduct/actions/' || ac.id) ORDER BY ac.created_at DESC), '[]'::jsonb)
        FROM public.conduct_actions ac
       WHERE (ac.source_module = _case_type AND ac.source_id = _case_id)
          OR ac.finding_id IN (
               SELECT f.id FROM public.conduct_findings f
                WHERE (_case_type = 'complaint' AND f.complaint_id = _case_id)
                   OR (_case_type = 'conduct_investigation' AND f.investigation_id = _case_id))),
    'correspondence', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', t.id, 'reference', t.reference,
               'subject', t.subject, 'thread_state', t.thread_state,
               'last_activity_at', COALESCE(t.last_message_at, t.received_at),
               'href', '/correspondence/' || t.id) ORDER BY COALESCE(t.last_message_at, t.received_at) DESC), '[]'::jsonb)
        FROM public.correspondence_threads t
       WHERE t.source_type = _case_type AND t.source_id = _case_id)
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.conduct_require(_module text, _action text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission(_uid, _module, _action) THEN
    RAISE EXCEPTION 'Permission denied: %.%', _module, _action USING ERRCODE = '42501';
  END IF;
  RETURN _uid;
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_rule_version_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v integer;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v := COALESCE(NEW.current_version, 1);
  ELSE
    IF NEW.definition IS NOT DISTINCT FROM OLD.definition
       AND NEW.threshold_value IS NOT DISTINCT FROM OLD.threshold_value
       AND NEW.comparison_operator IS NOT DISTINCT FROM OLD.comparison_operator
       AND NEW.lookback_days IS NOT DISTINCT FROM OLD.lookback_days
       AND NEW.metric IS NOT DISTINCT FROM OLD.metric
       AND NEW.active IS NOT DISTINCT FROM OLD.active THEN
      RETURN NEW;
    END IF;
    v := COALESCE(OLD.current_version, 1) + 1;
    NEW.current_version := v;
  END IF;

  INSERT INTO public.conduct_monitoring_rule_versions (rule_id, version, snapshot, created_by)
  VALUES (
    NEW.id, v,
    jsonb_build_object(
      'code', NEW.code, 'name', NEW.name, 'description', NEW.description,
      'scope', NEW.scope, 'rule_type', NEW.rule_type, 'definition', NEW.definition,
      'metric', NEW.metric, 'source_dataset', NEW.source_dataset,
      'threshold_value', NEW.threshold_value, 'comparison_operator', NEW.comparison_operator,
      'lookback_days', NEW.lookback_days, 'frequency', NEW.frequency,
      'risk_delta', NEW.risk_delta, 'active', NEW.active
    ),
    auth.uid()
  )
  ON CONFLICT (rule_id, version) DO NOTHING;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_signal_disposition_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.disposition IS DISTINCT FROM OLD.disposition
     AND COALESCE(current_setting('app.signal_disposition_ok', true), '') <> 'on'
     AND NOT (auth.uid() IS NULL AND current_user IN ('service_role','postgres','supabase_admin')) THEN
    RAISE EXCEPTION 'Signal disposition can only be changed via set_conduct_signal_disposition()';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_supervision_learning(_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE res jsonb;
BEGIN
  IF NOT public.can_view_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised to view conduct supervision data';
  END IF;

  SELECT COALESCE(jsonb_agg(x ORDER BY occurred_at DESC), '[]'::jsonb) INTO res
  FROM (
    SELECT jsonb_build_object('source','thematic_review','id',t.id,'ref',t.code,'title',t.title,
             'learning',t.regulatory_learning,'occurred_at',COALESCE(t.closed_at, t.updated_at),
             'href','/supervision/thematic-reviews/'||t.id) AS x,
           COALESCE(t.closed_at, t.updated_at) AS occurred_at
    FROM public.thematic_reviews t
    WHERE t.regulatory_learning IS NOT NULL AND length(trim(t.regulatory_learning)) > 0

    UNION ALL

    SELECT jsonb_build_object('source','investigation','id',cc.investigation_id,'ref',i.code,
             'title',COALESCE(i.allegation,'Investigation closure'),'learning',cc.regulatory_learning,
             'occurred_at',COALESCE(cc.approved_at, cc.updated_at),
             'href','/conduct/investigations/'||cc.investigation_id) AS x,
           COALESCE(cc.approved_at, cc.updated_at) AS occurred_at
    FROM public.conduct_investigation_closures cc
    JOIN public.conduct_investigations i ON i.id = cc.investigation_id
    WHERE cc.regulatory_learning IS NOT NULL AND length(trim(cc.regulatory_learning)) > 0
      AND cc.status = 'approved'
  ) s
  LIMIT _limit;

  RETURN res;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_supervision_log_export(_scope jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.can_view_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;
  PERFORM public.log_compliance_audit('EXPORT'::compliance_audit_action,'conduct_supervision_loop',
    COALESCE(_scope->>'entity_id','all'), NULL::jsonb, NULL::jsonb,
    'Supervision loop conduct report exported', NULL, NULL, _scope);
  PERFORM public.log_self_audit('SUPERVISION_LOOP_REPORT_EXPORTED','conduct_supervision_loop',
    COALESCE(_scope->>'entity_id','all'), NULL::jsonb, NULL::jsonb, _scope);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_supervision_log_view(_scope jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.can_view_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;
  PERFORM public.log_self_audit('SUPERVISION_LOOP_DASHBOARD_VIEWED','conduct_supervision_loop',
    COALESCE(_scope->>'entity_id','all'), NULL::jsonb, NULL::jsonb, _scope);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_supervision_loop_cases(_stage text, _entity_id uuid DEFAULT NULL::uuid, _from date DEFAULT ((CURRENT_DATE - '1 year'::interval))::date, _to date DEFAULT CURRENT_DATE, _sector_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ents uuid[];
  out_rows jsonb;
BEGIN
  IF NOT public.can_view_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised to view conduct supervision data';
  END IF;

  SELECT COALESCE(array_agg(l.id), ARRAY[]::uuid[]) INTO ents
  FROM public.licensees l
  WHERE (_entity_id IS NULL OR l.id = _entity_id)
    AND (_sector_id IS NULL OR l.sector_id = _sector_id);

  IF _stage IN ('complaints_received','classified','closed') THEN
    SELECT COALESCE(jsonb_agg(x ORDER BY x->>'occurred_at' DESC), '[]'::jsonb) INTO out_rows
    FROM (
      SELECT jsonb_build_object(
        'id', c.id, 'ref', c.complaint_number, 'title', c.subject,
        'status', c.status, 'severity', c.severity,
        'entity', l.name, 'occurred_at', c.created_at, 'kind', 'complaint',
        'href', '/complaints/' || c.id
      ) x
      FROM public.complaints c
      LEFT JOIN public.licensees l ON l.id = c.licensee_id
      WHERE c.licensee_id = ANY(ents)
        AND c.created_at::date BETWEEN _from AND _to
        AND (
          _stage = 'complaints_received'
          OR (_stage = 'classified' AND (c.conduct_risk_category_id IS NOT NULL OR c.complaint_type_id IS NOT NULL))
          OR (_stage = 'closed' AND (c.closed_at IS NOT NULL OR c.resolved_at IS NOT NULL OR c.status IN ('closed','resolved')))
        )
      LIMIT 300
    ) s;
  ELSIF _stage = 'investigated' THEN
    SELECT COALESCE(jsonb_agg(x ORDER BY x->>'occurred_at' DESC), '[]'::jsonb) INTO out_rows
    FROM (
      SELECT jsonb_build_object(
        'id', i.id, 'ref', i.code, 'title', i.allegation,
        'status', i.status, 'severity', i.severity,
        'entity', l.name, 'occurred_at', i.created_at, 'kind', 'investigation',
        'href', '/conduct/investigations/' || i.id
      ) x
      FROM public.conduct_investigations i
      LEFT JOIN public.licensees l ON l.id = i.licensee_id
      WHERE i.licensee_id = ANY(ents) AND i.created_at::date BETWEEN _from AND _to
      LIMIT 300
    ) s;
  ELSIF _stage IN ('enforcement','compliance') THEN
    SELECT COALESCE(jsonb_agg(x ORDER BY x->>'occurred_at' DESC), '[]'::jsonb) INTO out_rows
    FROM (
      SELECT jsonb_build_object(
        'id', e.id, 'ref', e.case_number, 'title', COALESCE(e.enforcement_type, 'Enforcement action'),
        'status', e.status, 'severity', NULL,
        'entity', l.name, 'occurred_at', e.date_opened, 'kind', 'enforcement',
        'href', '/enforcement/' || e.id
      ) x
      FROM public.enforcement_actions e
      LEFT JOIN public.licensees l ON l.id = e.entity_id
      WHERE e.entity_id = ANY(ents) AND e.date_opened::date BETWEEN _from AND _to
        AND (_stage = 'enforcement' OR e.resolution_date IS NOT NULL OR e.closed_at IS NOT NULL
             OR e.status IN ('closed','resolved','complied','completed'))
      LIMIT 300
    ) s;
  ELSIF _stage IN ('monitoring','recurrences') THEN
    SELECT COALESCE(jsonb_agg(x ORDER BY x->>'occurred_at' DESC), '[]'::jsonb) INTO out_rows
    FROM (
      SELECT jsonb_build_object(
        'id', m.id, 'ref', 'MON-' || LEFT(m.id::text, 8), 'title', COALESCE(m.entity_reporting_requirement, 'Post-closure monitoring'),
        'status', m.status, 'severity', NULL,
        'entity', l.name, 'occurred_at', COALESCE(m.start_date::timestamptz, m.created_at), 'kind', 'monitoring',
        'href', '/conduct/investigations/' || m.investigation_id
      ) x
      FROM public.conduct_post_closure_monitoring m
      LEFT JOIN public.licensees l ON l.id = m.licensee_id
      WHERE m.licensee_id = ANY(ents)
        AND (_stage = 'monitoring' OR EXISTS (
          SELECT 1 FROM public.conduct_monitoring_results r
          WHERE r.entity_id = m.licensee_id AND r.matched
            AND r.evaluated_at >= COALESCE(m.start_date, m.created_at::date)
        ))
      LIMIT 300
    ) s;
  ELSE
    out_rows := '[]'::jsonb;
  END IF;

  RETURN out_rows;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_supervision_loop_summary(_entity_id uuid DEFAULT NULL::uuid, _from date DEFAULT ((CURRENT_DATE - '1 year'::interval))::date, _to date DEFAULT CURRENT_DATE, _sector_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v jsonb;
  ents uuid[];
BEGIN
  IF NOT public.can_view_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised to view conduct supervision data';
  END IF;

  SELECT array_agg(l.id) INTO ents
  FROM public.licensees l
  WHERE (_entity_id IS NULL OR l.id = _entity_id)
    AND (_sector_id IS NULL OR l.sector_id = _sector_id);

  ents := COALESCE(ents, ARRAY[]::uuid[]);

  WITH c AS (
    SELECT * FROM public.complaints
    WHERE licensee_id = ANY(ents)
      AND created_at::date BETWEEN _from AND _to
  ), inv AS (
    SELECT * FROM public.conduct_investigations
    WHERE licensee_id = ANY(ents)
      AND created_at::date BETWEEN _from AND _to
  ), enf AS (
    SELECT * FROM public.enforcement_actions
    WHERE entity_id = ANY(ents)
      AND date_opened::date BETWEEN _from AND _to
  ), mon AS (
    SELECT * FROM public.conduct_post_closure_monitoring
    WHERE licensee_id = ANY(ents)
  ), rec AS (
    SELECT DISTINCT m.id
    FROM public.conduct_post_closure_monitoring m
    JOIN public.conduct_monitoring_results r
      ON r.entity_id = m.licensee_id AND r.matched
     AND r.evaluated_at >= COALESCE(m.start_date, m.created_at::date)
    WHERE m.licensee_id = ANY(ents)
  ), t2e AS (
    SELECT e.id,
           (SELECT MIN(x.created_at) FROM public.complaints x
             WHERE x.licensee_id = e.entity_id AND x.created_at <= e.date_opened) AS first_complaint,
           e.date_opened, e.resolution_date, e.closed_at, e.status, e.entity_id
    FROM enf e
  ), prepost AS (
    SELECT e.entity_id, e.date_opened,
      (SELECT COUNT(*) FROM public.complaints x
        WHERE x.licensee_id = e.entity_id
          AND x.created_at >= e.date_opened - INTERVAL '180 days'
          AND x.created_at < e.date_opened) AS pre_ct,
      (SELECT COUNT(*) FROM public.complaints x
        WHERE x.licensee_id = e.entity_id
          AND x.created_at > e.date_opened
          AND x.created_at <= e.date_opened + INTERVAL '180 days') AS post_ct
    FROM enf e
  )
  SELECT jsonb_build_object(
    'entity_count', cardinality(ents),
    'funnel', jsonb_build_object(
      'complaints_received', (SELECT COUNT(*) FROM c),
      'classified', (SELECT COUNT(*) FROM c WHERE conduct_risk_category_id IS NOT NULL OR complaint_type_id IS NOT NULL),
      'investigated', (SELECT COUNT(*) FROM inv),
      'enforcement', (SELECT COUNT(*) FROM enf),
      'compliance', (SELECT COUNT(*) FROM enf WHERE resolution_date IS NOT NULL OR closed_at IS NOT NULL OR status IN ('closed','resolved','complied','completed')),
      'closed', (SELECT COUNT(*) FROM c WHERE closed_at IS NOT NULL OR resolved_at IS NOT NULL OR status IN ('closed','resolved')),
      'monitoring', (SELECT COUNT(*) FROM mon),
      'recurrences', (SELECT COUNT(*) FROM rec)
    ),
    'severity_mix', COALESCE((
      SELECT jsonb_object_agg(COALESCE(severity,'unspecified'), n)
      FROM (SELECT severity, COUNT(*) n FROM c GROUP BY severity) s
    ), '{}'::jsonb),
    'effectiveness', jsonb_build_object(
      'time_to_enforcement_avg_days', (SELECT ROUND(AVG(EXTRACT(EPOCH FROM (date_opened - first_complaint))/86400)::numeric,1) FROM t2e WHERE first_complaint IS NOT NULL),
      'time_to_enforcement_min_days', (SELECT ROUND(MIN(EXTRACT(EPOCH FROM (date_opened - first_complaint))/86400)::numeric,1) FROM t2e WHERE first_complaint IS NOT NULL),
      'time_to_enforcement_max_days', (SELECT ROUND(MAX(EXTRACT(EPOCH FROM (date_opened - first_complaint))/86400)::numeric,1) FROM t2e WHERE first_complaint IS NOT NULL),
      'time_to_compliance_avg_days', (SELECT ROUND(AVG(EXTRACT(EPOCH FROM (COALESCE(resolution_date::timestamptz, closed_at) - date_opened))/86400)::numeric,1) FROM t2e WHERE COALESCE(resolution_date::timestamptz, closed_at) IS NOT NULL),
      'interventions', (SELECT COUNT(*) FROM prepost),
      'pre_intervention_avg', (SELECT ROUND(AVG(pre_ct)::numeric,2) FROM prepost),
      'post_intervention_avg', (SELECT ROUND(AVG(post_ct)::numeric,2) FROM prepost),
      'improved_interventions', (SELECT COUNT(*) FROM prepost WHERE post_ct < pre_ct),
      'recurrence_rate', CASE WHEN (SELECT COUNT(*) FROM mon) > 0
        THEN ROUND(((SELECT COUNT(*) FROM rec)::numeric / (SELECT COUNT(*) FROM mon)) * 100, 1) ELSE 0 END
    ),
    'period', jsonb_build_object('from', _from, 'to', _to)
  ) INTO v;

  RETURN v;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_supervision_timeline(_entity_id uuid, _from date DEFAULT ((CURRENT_DATE - '2 years'::interval))::date, _to date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE res jsonb;
BEGIN
  IF NOT public.can_view_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised to view conduct supervision data';
  END IF;

  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'occurred_at'), '[]'::jsonb) INTO res
  FROM (
    SELECT jsonb_build_object('kind','complaint','id',c.id,'ref',c.complaint_number,'label',c.subject,
      'severity',c.severity,'status',c.status,'occurred_at',c.created_at,'ended_at',COALESCE(c.closed_at,c.resolved_at),
      'href','/complaints/'||c.id) x
    FROM public.complaints c
    WHERE c.licensee_id = _entity_id AND c.created_at::date BETWEEN _from AND _to
    UNION ALL
    SELECT jsonb_build_object('kind','investigation','id',i.id,'ref',i.code,'label',i.allegation,
      'severity',i.severity,'status',i.status,'occurred_at',i.created_at,'ended_at',i.closed_at,
      'href','/conduct/investigations/'||i.id)
    FROM public.conduct_investigations i
    WHERE i.licensee_id = _entity_id AND i.created_at::date BETWEEN _from AND _to
    UNION ALL
    SELECT jsonb_build_object('kind','enforcement','id',e.id,'ref',e.case_number,'label',COALESCE(e.enforcement_type,'Enforcement action'),
      'severity',NULL,'status',e.status,'occurred_at',e.date_opened,'ended_at',COALESCE(e.resolution_date::timestamptz,e.closed_at),
      'href','/enforcement/'||e.id)
    FROM public.enforcement_actions e
    WHERE e.entity_id = _entity_id AND e.date_opened::date BETWEEN _from AND _to
    UNION ALL
    SELECT jsonb_build_object('kind','monitoring','id',r.id,'ref',COALESCE(mr.name,'Monitoring rule'),'label',
      COALESCE(mr.name,'Monitoring rule') || ' triggered','severity',NULL,'status',
      CASE WHEN r.matched THEN 'triggered' ELSE 'clear' END,'occurred_at',r.evaluated_at,'ended_at',NULL,
      'href','/conduct/entities/'||_entity_id)
    FROM public.conduct_monitoring_results r
    LEFT JOIN public.conduct_monitoring_rules mr ON mr.id = r.rule_id
    WHERE r.entity_id = _entity_id AND r.matched AND r.evaluated_at::date BETWEEN _from AND _to
    UNION ALL
    SELECT jsonb_build_object('kind','annotation','id',a.id,'ref','Note','label',a.label,'severity',NULL,
      'status',NULL,'occurred_at',a.event_date::timestamptz,'ended_at',NULL,'note',a.note,'href',NULL)
    FROM public.conduct_supervision_annotations a
    WHERE a.licensee_id = _entity_id AND a.event_date BETWEEN _from AND _to
  ) s;

  RETURN res;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_supervision_unresolved_risks(_entity_id uuid DEFAULT NULL::uuid, _sector_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE ents uuid[]; res jsonb;
BEGIN
  IF NOT public.can_view_conduct_intelligence() THEN
    RAISE EXCEPTION 'Not authorised to view conduct supervision data';
  END IF;

  SELECT COALESCE(array_agg(l.id), ARRAY[]::uuid[]) INTO ents
  FROM public.licensees l
  WHERE (_entity_id IS NULL OR l.id = _entity_id)
    AND (_sector_id IS NULL OR l.sector_id = _sector_id);

  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'severity', x->>'entity'), '[]'::jsonb) INTO res
  FROM (
    -- repeated monitoring triggers without an escalation / open action
    SELECT jsonb_build_object(
      'reason_code','repeat_monitoring_no_escalation',
      'reason','Monitoring rules triggered ' || COUNT(*) || ' times in 180 days with no open supervisory action',
      'severity','high','entity', l.name, 'entity_id', l.id,
      'target_href','/conduct/entities/'||l.id, 'occurred_at', MAX(r.evaluated_at)
    ) x
    FROM public.conduct_monitoring_results r
    JOIN public.licensees l ON l.id = r.entity_id
    WHERE r.entity_id = ANY(ents) AND r.matched
      AND r.evaluated_at >= now() - INTERVAL '180 days'
      AND NOT EXISTS (
        SELECT 1 FROM public.conduct_actions a
        WHERE a.entity_id = l.id AND a.closed_at IS NULL
          AND a.created_at >= now() - INTERVAL '180 days'
      )
    GROUP BY l.id, l.name
    HAVING COUNT(*) >= 2

    UNION ALL
    -- enforcement compliance overdue
    SELECT jsonb_build_object(
      'reason_code','enforcement_compliance_overdue',
      'reason','Enforcement action ' || COALESCE(e.case_number,'') || ' opened ' ||
               (CURRENT_DATE - e.date_opened::date) || ' days ago without recorded compliance',
      'severity','critical','entity', l.name, 'entity_id', l.id,
      'target_href','/enforcement/'||e.id, 'occurred_at', e.date_opened
    )
    FROM public.enforcement_actions e
    JOIN public.licensees l ON l.id = e.entity_id
    WHERE e.entity_id = ANY(ents)
      AND e.resolution_date IS NULL AND e.closed_at IS NULL
      AND COALESCE(e.status,'') NOT IN ('closed','resolved','complied','completed','withdrawn')
      AND e.date_opened::date < CURRENT_DATE - 90

    UNION ALL
    -- open investigation past due date
    SELECT jsonb_build_object(
      'reason_code','investigation_overdue',
      'reason','Investigation ' || COALESCE(i.code,'') || ' is open and past its due date',
      'severity','high','entity', l.name, 'entity_id', l.id,
      'target_href','/conduct/investigations/'||i.id, 'occurred_at', i.created_at
    )
    FROM public.conduct_investigations i
    JOIN public.licensees l ON l.id = i.licensee_id
    WHERE i.licensee_id = ANY(ents)
      AND i.closed_at IS NULL AND i.due_date IS NOT NULL AND i.due_date < CURRENT_DATE

    UNION ALL
    -- risk band deteriorated with no supervisory action since
    SELECT jsonb_build_object(
      'reason_code','risk_band_rise_no_action',
      'reason','Conduct risk band is ' || COALESCE(s.band,'unknown') || ' with no supervisory action recorded since scoring',
      'severity','medium','entity', l.name, 'entity_id', l.id,
      'target_href','/conduct/entities/'||l.id, 'occurred_at', s.computed_at
    )
    FROM public.entity_risk_scores s
    JOIN public.licensees l ON l.id = s.entity_id
    WHERE s.entity_id = ANY(ents) AND s.is_current
      AND LOWER(COALESCE(s.band,'')) IN ('high','critical','severe')
      AND NOT EXISTS (
        SELECT 1 FROM public.conduct_actions a
        WHERE a.entity_id = l.id AND a.created_at >= s.computed_at
      )
  ) q;

  RETURN res;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.conduct_work_queue(_kinds text[] DEFAULT NULL::text[], _sla_states text[] DEFAULT NULL::text[], _entity_id uuid DEFAULT NULL::uuid, _assigned_to uuid DEFAULT NULL::uuid, _unassigned boolean DEFAULT false, _search text DEFAULT NULL::text, _include_closed boolean DEFAULT false, _sort text DEFAULT 'sla'::text, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS TABLE(item_id uuid, kind text, kind_label text, reference text, subject text, entity_id uuid, entity_name text, stage text, stage_label text, status text, priority text, severity text, assigned_to uuid, assigned_to_name text, sla_due_at timestamp with time zone, sla_state text, waiting_on text, next_action_label text, blockers jsonb, last_activity_at timestamp with time zone, canonical_href text, total_count bigint)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  RETURN QUERY
  WITH scoped AS (
    SELECT i.* FROM public.v_conduct_work_items i
     WHERE (_include_closed OR NOT i.is_terminal)
       AND (_kinds IS NULL OR i.kind = ANY(_kinds))
       AND (_sla_states IS NULL OR i.sla_state = ANY(_sla_states))
       AND (_entity_id IS NULL OR i.entity_id = _entity_id)
       AND (_assigned_to IS NULL OR i.assigned_to = _assigned_to)
       AND (NOT coalesce(_unassigned, false) OR i.assigned_to IS NULL)
       AND (_search IS NULL OR btrim(_search) = '' OR
            coalesce(i.reference, '') ILIKE '%' || btrim(_search) || '%' OR
            coalesce(i.subject, '') ILIKE '%' || btrim(_search) || '%' OR
            coalesce(i.entity_name, '') ILIKE '%' || btrim(_search) || '%')
  ), counted AS (SELECT count(*) AS n FROM scoped)
  SELECT s.item_id, s.kind, s.kind_label, s.reference, s.subject, s.entity_id, s.entity_name,
         s.stage, s.stage_label, s.status, s.priority, s.severity, s.assigned_to, s.assigned_to_name,
         s.sla_due_at, s.sla_state, s.waiting_on, s.next_action_label, s.blockers,
         s.last_activity_at, s.canonical_href, counted.n
    FROM scoped s CROSS JOIN counted
   ORDER BY
     CASE WHEN _sort = 'sla' THEN
       CASE s.sla_state WHEN 'breached' THEN 0 WHEN 'due_soon' THEN 1 WHEN 'on_track' THEN 2 ELSE 3 END
       ELSE NULL END NULLS LAST,
     CASE WHEN _sort = 'priority' THEN
       CASE s.priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END
       ELSE NULL END NULLS LAST,
     s.sla_due_at NULLS LAST, s.created_at DESC
   LIMIT greatest(1, least(coalesce(_limit, 50), 200)) OFFSET greatest(0, coalesce(_offset, 0));
END; $function$
;
CREATE OR REPLACE FUNCTION public.conduct_work_queue_counts()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE _res jsonb;
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  SELECT jsonb_build_object(
    'total_open', count(*),
    'breached', count(*) FILTER (WHERE i.sla_state = 'breached'),
    'due_soon', count(*) FILTER (WHERE i.sla_state = 'due_soon'),
    'unassigned', count(*) FILTER (WHERE i.assigned_to IS NULL),
    'by_kind', coalesce((SELECT jsonb_object_agg(z.kind, z.n) FROM (
        SELECT w.kind, count(*) AS n FROM public.v_conduct_work_items w
         WHERE NOT w.is_terminal GROUP BY w.kind) z), '{}'::jsonb))
    INTO _res
  FROM public.v_conduct_work_items i
  WHERE NOT i.is_terminal;
  RETURN coalesce(_res, '{}'::jsonb);
END; $function$
;
CREATE OR REPLACE FUNCTION public.configure_application_form(_form_config_id uuid, _config jsonb)
 RETURNS registration_form_configs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.registration_form_configs;
BEGIN
  PERFORM public.enforce_permission('application_management', 'configure');

  UPDATE public.registration_form_configs
     SET updated_at = now()
   WHERE id = _form_config_id
   RETURNING * INTO _row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Application form config % not found', _form_config_id
      USING ERRCODE = 'no_data_found';
  END IF;

  INSERT INTO public.audit_logs (
    user_id, action, entity_type, entity_id, metadata, created_at
  ) VALUES (
    auth.uid(),
    'application.configure',
    'registration_form_config',
    _form_config_id,
    jsonb_build_object('config', _config),
    now()
  );

  RETURN _row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.confirm_complaint_duplicate(_pair_id uuid, _parent_id uuid, _notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pair record;
  v_child_regulator uuid;
  v_parent_regulator uuid;
BEGIN
  IF NOT public.has_complaint_perm(auth.uid(), 'triage')
     AND NOT public.has_complaint_perm(auth.uid(), 'view_all') THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_pair FROM public.complaint_duplicate_pairs WHERE id = _pair_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'pair_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF _parent_id NOT IN (v_pair.primary_complaint_id, v_pair.candidate_complaint_id) THEN
    RAISE EXCEPTION 'parent_must_be_in_pair' USING ERRCODE = '22023';
  END IF;

  SELECT regulator_id INTO v_child_regulator FROM public.complaints
    WHERE id = CASE WHEN _parent_id = v_pair.primary_complaint_id THEN v_pair.candidate_complaint_id ELSE v_pair.primary_complaint_id END;
  SELECT regulator_id INTO v_parent_regulator FROM public.complaints WHERE id = _parent_id;

  IF v_child_regulator IS DISTINCT FROM v_parent_regulator THEN
    RAISE EXCEPTION 'regulator_mismatch' USING ERRCODE = '42501';
  END IF;

  UPDATE public.complaints
     SET parent_complaint_id = _parent_id,
         status = 'duplicate',
         updated_at = now()
   WHERE id = CASE WHEN _parent_id = v_pair.primary_complaint_id THEN v_pair.candidate_complaint_id ELSE v_pair.primary_complaint_id END;

  UPDATE public.complaint_duplicate_pairs
     SET status = 'confirmed',
         decided_at = now(),
         decided_by = auth.uid(),
         updated_at = now()
   WHERE id = _pair_id;

  INSERT INTO public.audit_logs (user_id, action, table_name, record_id, new_values)
  VALUES (auth.uid(), 'confirm_duplicate', 'complaint_duplicate_pairs', _pair_id,
          jsonb_build_object('parent_complaint_id', _parent_id, 'notes', _notes));

  RETURN jsonb_build_object('pair_id', _pair_id, 'parent_complaint_id', _parent_id, 'status', 'confirmed');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.consume_worker_token(_token text, _purpose text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ok boolean;
BEGIN
  UPDATE public.worker_invocation_tokens
     SET consumed_at = now()
   WHERE token = _token
     AND purpose = _purpose
     AND consumed_at IS NULL
     AND expires_at > now()
  RETURNING true INTO v_ok;
  RETURN COALESCE(v_ok, false);
END; $function$
;
CREATE OR REPLACE FUNCTION public.coord_case_seed_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.coordination_participants (case_id, regulator_id, user_id, participant_role, clearance_status, invited_by)
  VALUES (NEW.id, NEW.owner_regulator_id, NEW.owner_user_id, 'owner', 'cleared', NEW.owner_user_id)
  ON CONFLICT (case_id, user_id) DO NOTHING;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.coord_check_clearance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_case_id UUID := NEW.case_id; v_pending INT; v_blocked INT;
BEGIN
  SELECT COUNT(*) FILTER (WHERE clearance_status = 'pending'),
         COUNT(*) FILTER (WHERE clearance_status = 'blocked')
  INTO v_pending, v_blocked
  FROM public.coordination_participants WHERE case_id = v_case_id;

  IF v_blocked > 0 THEN
    UPDATE public.coordination_cases SET status = 'pending_clearance', updated_at = now() WHERE id = v_case_id AND status != 'closed';
  ELSIF v_pending = 0 THEN
    UPDATE public.coordination_cases SET status = 'cleared', updated_at = now() WHERE id = v_case_id AND status != 'closed';
  ELSE
    UPDATE public.coordination_cases SET status = 'pending_clearance', updated_at = now() WHERE id = v_case_id AND status != 'closed';
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.coord_escalation_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at := now();

  IF NEW.status IN ('resolved','withdrawn') AND
     (OLD IS NULL OR OLD.status <> NEW.status) THEN
    IF NEW.resolution_rationale IS NULL OR length(trim(NEW.resolution_rationale)) < 10 THEN
      RAISE EXCEPTION 'Resolution rationale (min 10 chars) required when marking an escalation as % ', NEW.status;
    END IF;
    IF NEW.resolved_at IS NULL THEN NEW.resolved_at := now(); END IF;
    IF NEW.resolved_by IS NULL THEN NEW.resolved_by := auth.uid(); END IF;
    IF NEW.status = 'resolved' AND NEW.resolution_outcome IS NULL THEN
      RAISE EXCEPTION 'Resolution outcome required when marking an escalation as resolved';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.copy_review_step_permissions(_from_step uuid, _to_step uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  n integer := 0;
  _wf uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'REVIEW_UNAUTHENTICATED'; END IF;
  IF NOT public.is_collab_admin(auth.uid()) THEN
    RAISE EXCEPTION 'REVIEW_FORBIDDEN_ACTION';
  END IF;
  SELECT workflow_id INTO _wf FROM public.approval_steps WHERE id = _to_step;
  IF _wf IS NULL THEN RAISE EXCEPTION 'REVIEW_UNKNOWN_STEP'; END IF;

  INSERT INTO public.review_step_permissions (
    workflow_id, step_id, role_id, enabled, can_view, can_comment, can_reply,
    can_suggest, can_accept, can_reject, can_resolve, can_mark_blocking,
    block_approval_on_unresolved_blocking
  )
  SELECT _wf, _to_step, role_id, enabled, can_view, can_comment, can_reply,
         can_suggest, can_accept, can_reject, can_resolve, can_mark_blocking,
         block_approval_on_unresolved_blocking
  FROM public.review_step_permissions
  WHERE step_id = _from_step
  ON CONFLICT (step_id, role_id) DO UPDATE SET
    enabled = EXCLUDED.enabled,
    can_view = EXCLUDED.can_view,
    can_comment = EXCLUDED.can_comment,
    can_reply = EXCLUDED.can_reply,
    can_suggest = EXCLUDED.can_suggest,
    can_accept = EXCLUDED.can_accept,
    can_reject = EXCLUDED.can_reject,
    can_resolve = EXCLUDED.can_resolve,
    can_mark_blocking = EXCLUDED.can_mark_blocking,
    block_approval_on_unresolved_blocking = EXCLUDED.block_approval_on_unresolved_blocking;

  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $function$
;
CREATE OR REPLACE FUNCTION public.correspondence_actor_label(_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(NULLIF(TRIM(p.full_name), ''), p.email, 'System')
  FROM public.profiles p WHERE p.id = _user_id;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_add_participant(_thread_id uuid, _user_id uuid, _party_role text DEFAULT 'Officer'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_name text; v_id uuid; v_actor text; v_t public.correspondence_threads%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  IF NOT public.is_internal_staff(v_user)
     OR NOT public.has_permission(v_user, 'correspondence_management', 'edit') THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.correspondence_thread_visible(_thread_id, v_user) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_internal_staff(_user_id) THEN RAISE EXCEPTION 'recipient_not_internal'; END IF;

  SELECT full_name INTO v_name FROM public.profiles WHERE id = _user_id;
  IF v_name IS NULL THEN RAISE EXCEPTION 'recipient_not_found'; END IF;
  SELECT * INTO v_t FROM public.correspondence_threads WHERE id = _thread_id;
  v_actor := public.correspondence_actor_label(v_user);

  INSERT INTO public.correspondence_thread_participants (thread_id, user_id, party_type, display_name, party_role, is_internal)
  VALUES (_thread_id, _user_id, 'officer', v_name, COALESCE(_party_role, 'Officer'), true)
  ON CONFLICT (thread_id, user_id) DO UPDATE SET party_role = COALESCE(EXCLUDED.party_role, correspondence_thread_participants.party_role)
  RETURNING id INTO v_id;

  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
  VALUES (_thread_id, v_user, v_actor, 'Staff', 'THREAD_STATUS_CHANGED', 'Internal participant added: ' || v_name, false);

  INSERT INTO public.notifications (
    user_id, title, message, type, channel, severity, category, module,
    action_required, entity_type, entity_id, source_reference, event_key, metadata
  ) VALUES (
    _user_id,
    'You were added to a communication thread',
    COALESCE(v_actor, 'A colleague') || ' added you to ' || v_t.reference || ' — ' || v_t.subject,
    'info', 'in_app', 'medium', 'info', 'communications',
    false, 'correspondence_thread', _thread_id::text, v_t.reference,
    'correspondence.internal_participant_added',
    jsonb_build_object('thread_id', _thread_id, 'added_by', v_user)
  );

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_case_href(_source_type text, _source_id uuid)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _source_id IS NULL OR _source_type IS NULL THEN NULL
    WHEN _source_type = 'application' THEN '/applications/' || _source_id
    WHEN _source_type IN ('license', 'licence') THEN '/licenses/' || _source_id
    WHEN _source_type = 'complaint' THEN '/complaints/' || _source_id
    WHEN _source_type IN ('return', 'return_filing') THEN '/returns/filings/' || _source_id
    WHEN _source_type IN ('conduct_investigation', 'investigation') THEN '/conduct/investigations/' || _source_id
    WHEN _source_type = 'conduct_finding' THEN '/conduct/findings/' || _source_id
    WHEN _source_type = 'conduct_action' THEN '/conduct/actions/' || _source_id
    WHEN _source_type IN ('enforcement', 'enforcement_action') THEN '/enforcement/' || _source_id
    WHEN _source_type = 'examination' THEN '/examinations/' || _source_id
    WHEN _source_type IN ('fp_assessment', 'fit_and_proper') THEN '/fpa/assessments/' || _source_id
    WHEN _source_type = 'fp_person' THEN '/fpa/individuals/' || _source_id
    WHEN _source_type IN ('prudential_assessment', 'prudential') THEN '/prudential/assessments/' || _source_id
    WHEN _source_type IN ('licensee', 'entity') THEN '/entities/' || _source_id
    ELSE NULL
  END
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_case_readable(_source_type text, _source_id uuid, _user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_type text := lower(COALESCE(_source_type, ''));
BEGIN
  IF _source_id IS NULL THEN
    RETURN true; -- nothing linked; thread-level visibility governs
  END IF;
  IF _user_id IS NULL THEN RETURN false; END IF;

  IF v_type IN ('application', 'applications', 'registration', 'rfi', 'application_rfi') THEN
    RETURN public.can_read_application(_user_id, _source_id);
  ELSIF v_type IN ('complaint', 'complaints') THEN
    RETURN public.has_complaint_perm(_user_id, 'view')
        OR EXISTS (SELECT 1 FROM public.complaints c WHERE c.id = _source_id);
  ELSIF v_type IN ('return', 'returns', 'compliance_return') THEN
    RETURN public.can_read_return_filed(_user_id, _source_id);
  ELSIF v_type IN ('enforcement', 'enforcement_action', 'enforcement_case') THEN
    RETURN public.can_read_enforcement(_user_id, _source_id);
  ELSIF v_type IN ('inspection', 'inspections') THEN
    RETURN public.can_read_inspection(_user_id, _source_id);
  ELSIF v_type IN ('licensee', 'entity') THEN
    RETURN public.can_read_licensee(_user_id, _source_id);
  ELSIF v_type IN ('license', 'licence') THEN
    RETURN public.can_read_license(_user_id, _source_id);
  END IF;

  -- Unknown source types fall back to staff-only access
  RETURN public.is_internal_staff(_user_id);
EXCEPTION WHEN others THEN
  RETURN public.is_internal_staff(_user_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_delivery_state(_msg_status text, _delivered_at timestamp with time zone, _opened_at timestamp with time zone, _bounce_reason text, _dispatch_status text, _sent_at timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _bounce_reason IS NOT NULL OR lower(COALESCE(_msg_status, '')) IN ('bounced', 'rejected')
         OR upper(COALESCE(_dispatch_status, '')) IN ('BOUNCED', 'REJECTED') THEN 'bounced'
    WHEN lower(COALESCE(_msg_status, '')) IN ('failed', 'dead_letter', 'error')
         OR upper(COALESCE(_dispatch_status, '')) IN ('FAILED', 'DEAD_LETTER', 'ERROR') THEN 'failed'
    WHEN upper(COALESCE(_dispatch_status, '')) IN ('RETRYING') THEN 'retrying'
    WHEN _opened_at IS NOT NULL OR lower(COALESCE(_msg_status, '')) = 'opened' THEN 'opened'
    WHEN _delivered_at IS NOT NULL OR lower(COALESCE(_msg_status, '')) = 'delivered'
         OR upper(COALESCE(_dispatch_status, '')) = 'DELIVERED' THEN 'delivered'
    WHEN lower(COALESCE(_msg_status, '')) IN ('sent', 'sent_to_provider')
         OR upper(COALESCE(_dispatch_status, '')) IN ('SENT', 'SENT_TO_PROVIDER') THEN 'sent'
    WHEN lower(COALESCE(_msg_status, '')) IN ('queued', 'pending')
         OR upper(COALESCE(_dispatch_status, '')) IN ('QUEUED', 'PENDING') THEN 'queued'
    WHEN upper(COALESCE(_dispatch_status, '')) IN ('SUPPRESSED', 'PROVIDER_NOT_CONFIGURED') THEN 'not_delivered'
    WHEN _sent_at IS NOT NULL THEN 'recorded'
    ELSE 'unknown'
  END
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_discard_draft(_message_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_deleted uuid;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  DELETE FROM public.correspondence_messages
   WHERE id = _message_id AND author_id = v_user AND COALESCE(is_draft, false) = true
  RETURNING id INTO v_deleted;
  IF v_deleted IS NULL THEN RAISE EXCEPTION 'draft_not_found'; END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_export_manifest(_thread_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_staff boolean;
  v_t public.correspondence_threads%ROWTYPE;
  v_out jsonb;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  IF NOT public.correspondence_thread_visible(_thread_id, v_user) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  v_staff := public.is_internal_staff(v_user);
  SELECT * INTO v_t FROM public.correspondence_threads WHERE id = _thread_id;
  IF NOT v_staff AND v_t.is_entity_facing = false THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF v_staff AND NOT public.correspondence_case_readable(v_t.source_type, v_t.source_id, v_user) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  v_out := jsonb_build_object(
    'thread', jsonb_build_object(
      'id', v_t.id, 'reference', v_t.reference, 'subject', v_t.subject,
      'module', v_t.module, 'thread_type', v_t.thread_type, 'thread_state', v_t.thread_state,
      'source_reference', v_t.source_reference, 'source_type', v_t.source_type,
      'entity_name', (SELECT l.entity_name FROM public.licensees l WHERE l.id = v_t.licensee_id),
      'received_at', v_t.received_at, 'closed_at', v_t.closed_at,
      'response_due_at', v_t.response_due_at, 'exported_at', now(),
      'exported_by', public.correspondence_actor_label(v_user),
      'includes_internal', v_staff
    ),
    'participants', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'name', p.display_name, 'role', COALESCE(p.party_role, p.party_type),
               'is_internal', p.is_internal) ORDER BY p.created_at), '[]'::jsonb)
        FROM public.correspondence_thread_participants p
       WHERE p.thread_id = _thread_id AND (v_staff OR p.is_internal = false)
    ),
    'messages', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'id', m.id, 'author_name', m.author_name, 'author_role', m.author_role,
               'sent_at', m.sent_at, 'direction', m.direction, 'message_kind', m.message_kind,
               'body', m.body, 'body_format', m.body_format,
               'delivery_status', m.delivery_status, 'is_internal', m.is_internal_note,
               'system_generated', m.sent_by_system,
               'attachments', (
                 SELECT COALESCE(jsonb_agg(a.file_name ORDER BY a.created_at), '[]'::jsonb)
                   FROM public.correspondence_attachments a WHERE a.message_id = m.id
               )) ORDER BY m.sent_at), '[]'::jsonb)
        FROM public.correspondence_messages m
       WHERE m.thread_id = _thread_id
         AND COALESCE(m.is_draft, false) = false
         AND (v_staff OR m.is_internal_note = false)
    ),
    'audit', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'action', e.action, 'actor', e.actor_name, 'role', e.actor_role,
               'detail', e.detail, 'at', e.created_at) ORDER BY e.created_at), '[]'::jsonb)
        FROM public.correspondence_events e
       WHERE e.thread_id = _thread_id AND (v_staff OR e.visible_to_licensee = true)
    )
  );

  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
  VALUES (_thread_id, v_user, public.correspondence_actor_label(v_user),
          CASE WHEN v_staff THEN 'Staff' ELSE 'Licensee' END,
          'THREAD_EXPORTED',
          'PDF export' || CASE WHEN v_staff THEN ' (including internal messages)' ELSE ' (external content only)' END,
          false);

  RETURN v_out;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_guard_event_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'audit_trail_immutable' USING ERRCODE = '42501';
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_guard_message_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_state text;
  v_privileged boolean;
BEGIN
  v_privileged := v_user IS NOT NULL
                  AND public.is_internal_staff(v_user)
                  AND public.has_permission(v_user, 'correspondence_management', 'approve');

  IF TG_OP = 'DELETE' THEN
    IF COALESCE(OLD.is_draft, false) = true AND OLD.author_id = v_user THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'communication_history_immutable' USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Delivery bookkeeping columns may always change; content may not once sent.
    IF COALESCE(OLD.is_draft, false) = false THEN
      IF NEW.body IS DISTINCT FROM OLD.body
         OR NEW.subject IS DISTINCT FROM OLD.subject
         OR NEW.is_internal_note IS DISTINCT FROM OLD.is_internal_note
         OR NEW.message_kind IS DISTINCT FROM OLD.message_kind
         OR NEW.author_id IS DISTINCT FROM OLD.author_id
         OR NEW.thread_id IS DISTINCT FROM OLD.thread_id THEN
        RAISE EXCEPTION 'communication_history_immutable' USING ERRCODE = '42501';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  -- INSERT
  SELECT thread_state INTO v_state FROM public.correspondence_threads WHERE id = NEW.thread_id;
  IF v_state = 'closed' AND NOT v_privileged THEN
    RAISE EXCEPTION 'thread_closed' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_link_documents(_message_id uuid, _document_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_msg public.correspondence_messages%ROWTYPE;
  v_t public.correspondence_threads%ROWTYPE;
  v_doc record;
  v_ok uuid[] := '{}';
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  SELECT * INTO v_msg FROM public.correspondence_messages WHERE id = _message_id;
  IF v_msg.id IS NULL THEN RAISE EXCEPTION 'message_not_found'; END IF;
  IF NOT public.correspondence_thread_visible(v_msg.thread_id, v_user) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_t FROM public.correspondence_threads WHERE id = v_msg.thread_id;

  FOR v_doc IN SELECT d.* FROM public.documents d WHERE d.id = ANY(COALESCE(_document_ids, '{}')) LOOP
    IF public.correspondence_case_readable(v_doc.entity_type, v_doc.entity_id, v_user)
       AND (v_t.source_id IS NULL OR v_doc.entity_id = v_t.source_id OR public.is_internal_staff(v_user)) THEN
      v_ok := v_ok || v_doc.id;
    END IF;
  END LOOP;

  IF array_length(v_ok, 1) IS NULL THEN
    RETURN 0;
  END IF;

  UPDATE public.correspondence_messages SET linked_document_ids = v_ok WHERE id = _message_id;
  RETURN array_length(v_ok, 1);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_module_for(_source_type text, _category text, _thread_type text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _thread_type = 'internal_discussion' THEN 'internal'
    WHEN lower(COALESCE(_source_type,'')) IN ('application','applications','registration','licence','license','appeal') THEN 'licensing'
    WHEN lower(COALESCE(_source_type,'')) IN ('complaint','complaints') THEN 'complaints'
    WHEN lower(COALESCE(_source_type,'')) IN ('return','returns','compliance_return') THEN 'returns'
    WHEN lower(COALESCE(_source_type,'')) IN ('enforcement','enforcement_action','enforcement_case') THEN 'enforcement'
    WHEN lower(COALESCE(_source_type,'')) IN ('inspection','inspections') THEN 'inspections'
    WHEN lower(COALESCE(_source_type,'')) IN ('conduct','conduct_alert','market_conduct') THEN 'conduct'
    WHEN lower(COALESCE(_source_type,'')) IN ('rfi','application_rfi') THEN 'licensing'
    WHEN lower(COALESCE(_category,'')) = 'internal' THEN 'internal'
    WHEN lower(COALESCE(_category,'')) LIKE '%complaint%' THEN 'complaints'
    WHEN lower(COALESCE(_category,'')) LIKE '%return%' THEN 'returns'
    WHEN lower(COALESCE(_category,'')) LIKE '%licen%' THEN 'licensing'
    WHEN lower(COALESCE(_category,'')) LIKE '%enforce%' THEN 'enforcement'
    ELSE 'general'
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_reopen_thread(_thread_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_actor text; v_t public.correspondence_threads%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  IF NOT public.is_internal_staff(v_user)
     OR NOT public.has_permission(v_user, 'correspondence_management', 'approve') THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(length(TRIM(_reason)), 0) < 10 THEN RAISE EXCEPTION 'reopen_reason_required'; END IF;
  SELECT * INTO v_t FROM public.correspondence_threads WHERE id = _thread_id;
  IF v_t.id IS NULL THEN RAISE EXCEPTION 'thread_not_found'; END IF;
  IF v_t.thread_state <> 'closed' THEN RAISE EXCEPTION 'thread_not_closed'; END IF;
  v_actor := public.correspondence_actor_label(v_user);

  UPDATE public.correspondence_threads
     SET thread_state = 'open', status = 'in_review', closed_at = NULL, closed_by = NULL,
         pending_since = NULL, response_due_at = NULL,
         sla_warned_at = NULL, sla_breached_at = NULL,
         reopened_count = COALESCE(reopened_count, 0) + 1
   WHERE id = _thread_id;

  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
  VALUES (_thread_id, v_user, v_actor, 'Staff', 'THREAD_STATUS_CHANGED', 'Reopened: ' || _reason, true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_route_decide(_category text, _channel text, _subject text, _priority text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule public.correspondence_routing_rules%ROWTYPE;
  v_priority text := COALESCE(_priority, 'normal');
  v_sla integer := 5;
BEGIN
  SELECT * INTO v_rule FROM public.correspondence_routing_rules r
  WHERE r.is_active
    AND (
      (r.match_type = 'category' AND lower(r.match_value) = lower(COALESCE(_category,'')))
      OR (r.match_type = 'channel' AND lower(r.match_value) = lower(COALESCE(_channel,'')))
      OR (r.match_type = 'subject' AND COALESCE(_subject,'') ILIKE '%' || r.match_value || '%')
      OR (r.match_type = 'priority' AND lower(r.match_value) = lower(v_priority))
    )
  ORDER BY r.sort_order ASC LIMIT 1;

  IF v_rule.id IS NOT NULL THEN
    v_sla := v_rule.sla_days;
    IF _priority IS NULL THEN v_priority := v_rule.priority; END IF;
  END IF;

  RETURN jsonb_build_object(
    'matched', (v_rule.id IS NOT NULL),
    'rule_id', v_rule.id,
    'rule_name', v_rule.name,
    'match_type', v_rule.match_type,
    'match_value', v_rule.match_value,
    'sort_order', v_rule.sort_order,
    'priority', v_priority,
    'sla_days', v_sla,
    'assign_unit', v_rule.assign_unit,
    'assign_officer', v_rule.assign_officer,
    'allow_manual_override', v_rule.allow_manual_override,
    'status', CASE WHEN v_rule.id IS NOT NULL THEN 'assigned' ELSE 'received' END
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_set_pending_response(_thread_id uuid, _due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_actor text; v_due timestamptz; v_t public.correspondence_threads%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  IF NOT public.is_internal_staff(v_user)
     OR NOT public.has_permission(v_user, 'correspondence_management', 'edit') THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_t FROM public.correspondence_threads WHERE id = _thread_id;
  IF v_t.id IS NULL THEN RAISE EXCEPTION 'thread_not_found'; END IF;
  IF v_t.thread_state = 'closed' THEN RAISE EXCEPTION 'thread_closed' USING ERRCODE = '42501'; END IF;

  v_due := COALESCE(_due_at, now() + (COALESCE(v_t.sla_hours, COALESCE(v_t.sla_days, 5) * 24) || ' hours')::interval);
  v_actor := public.correspondence_actor_label(v_user);

  UPDATE public.correspondence_threads
     SET thread_state = 'pending_response',
         pending_since = now(),
         response_due_at = v_due,
         sla_warned_at = NULL,
         sla_breached_at = NULL
   WHERE id = _thread_id;

  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
  VALUES (_thread_id, v_user, v_actor, 'Staff', 'THREAD_STATUS_CHANGED',
          COALESCE(_note, 'Pending response · response due ' || to_char(v_due, 'DD Mon YYYY HH24:MI')), true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_sla_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_warned integer := 0;
  v_breached integer := 0;
  r record;
BEGIN
  FOR r IN
    SELECT t.* FROM public.correspondence_threads t
     WHERE t.thread_state = 'pending_response'
       AND t.response_due_at IS NOT NULL
       AND t.sla_warned_at IS NULL
       AND t.sla_breached_at IS NULL
       AND now() >= t.response_due_at - GREATEST(
             (COALESCE(t.sla_hours, COALESCE(t.sla_days, 5) * 24) * 0.25 || ' hours')::interval,
             interval '4 hours')
       AND now() < t.response_due_at
  LOOP
    UPDATE public.correspondence_threads SET sla_warned_at = now() WHERE id = r.id;
    INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
    VALUES (r.id, NULL, 'SLA Monitor', 'System', 'THREAD_STATUS_CHANGED',
            'Response deadline approaching (' || to_char(r.response_due_at, 'DD Mon YYYY HH24:MI') || ')', false);
    PERFORM public.notification_enqueue_event(
      'correspondence.sla_near_breach', 'correspondence_thread', r.id,
      jsonb_build_object(
        'thread_id', r.id,
        'reference', r.reference,
        'subject', r.subject,
        'assigned_officer_id', r.assigned_officer_id,
        'licensee_id', r.licensee_id,
        'response_due_at', r.response_due_at,
        'cta_url', '/correspondence/' || r.id::text
      ),
      'warn');
    v_warned := v_warned + 1;
  END LOOP;

  FOR r IN
    SELECT t.* FROM public.correspondence_threads t
     WHERE t.thread_state = 'pending_response'
       AND t.response_due_at IS NOT NULL
       AND t.sla_breached_at IS NULL
       AND now() >= t.response_due_at
  LOOP
    UPDATE public.correspondence_threads SET sla_breached_at = now() WHERE id = r.id;
    INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
    VALUES (r.id, NULL, 'SLA Monitor', 'System', 'THREAD_STATUS_CHANGED',
            'Response deadline breached (' || to_char(r.response_due_at, 'DD Mon YYYY HH24:MI') || ')', true);
    PERFORM public.notification_enqueue_event(
      'correspondence.sla_breached', 'correspondence_thread', r.id,
      jsonb_build_object(
        'thread_id', r.id,
        'reference', r.reference,
        'subject', r.subject,
        'assigned_officer_id', r.assigned_officer_id,
        'licensee_id', r.licensee_id,
        'response_due_at', r.response_due_at,
        'cta_url', '/correspondence/' || r.id::text
      ),
      'breach');
    v_breached := v_breached + 1;
  END LOOP;

  RETURN jsonb_build_object('warned', v_warned, 'breached', v_breached, 'ran_at', now());
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_thread_case(_thread_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_staff boolean;
  t record;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  IF NOT public.correspondence_thread_visible(_thread_id, v_user) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  v_staff := public.is_internal_staff(v_user);
  SELECT * INTO t FROM public.correspondence_threads WHERE id = _thread_id;
  IF t IS NULL THEN RAISE EXCEPTION 'thread_not_found' USING ERRCODE = '22023'; END IF;

  RETURN jsonb_build_object(
    'id', t.id,
    'reference', t.reference,
    'subject', t.subject,
    'summary', t.summary,
    'module', t.module,
    'category', t.category,
    'channel', t.channel,
    'thread_type', t.thread_type,
    'thread_state', t.thread_state,
    'stage_label', CASE t.thread_state WHEN 'open' THEN 'Open conversation'
                                       WHEN 'pending_response' THEN 'Awaiting response'
                                       ELSE 'Closed' END,
    'status_label', initcap(replace(COALESCE(t.status, t.thread_state), '_', ' ')),
    'priority', t.priority,
    'is_entity_facing', t.is_entity_facing,
    'entity_id', t.licensee_id,
    'entity_name', (SELECT l.name FROM public.licensees l WHERE l.id = t.licensee_id),
    'entity_href', CASE WHEN t.licensee_id IS NOT NULL AND v_staff
                        THEN '/entities/' || t.licensee_id END,
    'owner_name', t.assigned_officer,
    'owner_id', t.assigned_officer_id,
    'team', COALESCE(t.assigned_team, t.assigned_unit),
    'sla_due_at', COALESCE(t.response_due_at, t.due_at),
    'sla_state', CASE
        WHEN t.thread_state = 'closed' THEN 'none'
        WHEN t.sla_breached_at IS NOT NULL THEN 'breached'
        WHEN t.sla_warned_at IS NOT NULL THEN 'at_risk'
        WHEN COALESCE(t.response_due_at, t.due_at) IS NULL THEN 'none'
        WHEN COALESCE(t.response_due_at, t.due_at) < now() THEN 'breached'
        WHEN COALESCE(t.response_due_at, t.due_at) < now() + interval '48 hours' THEN 'at_risk'
        ELSE 'on_track' END,
    'waiting_on', CASE WHEN t.thread_state = 'closed' THEN NULL
                       WHEN t.thread_state = 'pending_response' THEN 'entity'
                       ELSE 'regulator' END,
    'next_action', CASE
        WHEN t.thread_state = 'closed' THEN 'No action — thread closed'
        WHEN t.thread_state = 'pending_response' THEN 'Await entity response'
        WHEN COALESCE(t.last_message_kind, '') = 'external_inbound' THEN 'Review inbound message and respond'
        WHEN t.assigned_officer_id IS NULL THEN 'Assign an owner'
        ELSE 'Progress the conversation' END,
    'last_activity_at', COALESCE(t.last_message_at, t.received_at),
    'related_case', CASE WHEN t.source_id IS NOT NULL THEN jsonb_build_object(
        'source_type', t.source_type,
        'source_id', t.source_id,
        'reference', t.source_reference,
        'href', public.correspondence_case_href(t.source_type, t.source_id)) END,
    'rfi_links', CASE WHEN NOT v_staff THEN '[]'::jsonb ELSE (
        SELECT COALESCE(jsonb_agg(x ORDER BY x->>'raised_at' DESC), '[]'::jsonb) FROM (
          SELECT jsonb_build_object('kind', 'complaint_rfi', 'id', r.id, 'status', r.status,
                                    'summary', LEFT(COALESCE(r.summary, ''), 160),
                                    'due_at', r.due_at, 'raised_at', r.raised_at,
                                    'href', '/complaints/' || r.complaint_id) AS x
            FROM public.complaint_rfis r
           WHERE t.source_type = 'complaint' AND r.complaint_id = t.source_id
          UNION ALL
          SELECT jsonb_build_object('kind', 'application_rfi', 'id', r.id, 'status', r.status,
                                    'summary', LEFT(COALESCE(r.summary, ''), 160),
                                    'due_at', r.due_at, 'raised_at', r.raised_at,
                                    'href', '/applications/' || r.application_id) AS x
            FROM public.application_rfis r
           WHERE t.source_type = 'application' AND r.application_id = t.source_id
        ) s) END,
    'delivery_evidence', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
                 'message_id', m.id, 'channel', m.channel, 'status', m.delivery_status,
                 'sent_at', m.sent_at, 'delivered_at', m.delivered_at, 'opened_at', m.opened_at,
                 'bounce_reason', m.bounce_reason,
                 'dispatch_status', d.status,
                 'error_message', COALESCE(m.bounce_reason, d.error_message),
                 'provider_message_id', d.provider_message_id,
                 'evidence_state', public.correspondence_delivery_state(
                    m.delivery_status, m.delivered_at, m.opened_at, m.bounce_reason, d.status, m.sent_at),
                 'delivery_confirmed', (m.delivered_at IS NOT NULL
                    OR lower(COALESCE(m.delivery_status, '')) IN ('delivered', 'opened')
                    OR upper(COALESCE(d.status, '')) = 'DELIVERED'),
                 'recipient', COALESCE(d.recipient_email, d.recipient_phone))
               ORDER BY m.sent_at DESC NULLS LAST, m.id), '[]'::jsonb)
          FROM public.correspondence_messages m
          LEFT JOIN public.correspondence_dispatches d ON d.id = m.dispatch_id
         WHERE m.thread_id = t.id
           AND m.is_draft = false
           AND m.message_kind IN ('external_outbound', 'external_inbound')
           AND (v_staff OR m.is_internal_note = false)),
    'reopened_count', COALESCE(t.reopened_count, 0),
    'can_act', v_staff
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.correspondence_thread_feed(_filters jsonb DEFAULT '{}'::jsonb, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_staff boolean;
  v_licensee uuid;
  v_q text := NULLIF(TRIM(COALESCE(_filters->>'query', '')), '');
  v_status text := NULLIF(_filters->>'status', 'all');
  v_module text := NULLIF(_filters->>'module', 'all');
  v_direction text := NULLIF(_filters->>'direction', 'all');
  v_type text := NULLIF(_filters->>'thread_type', 'all');
  v_assignee uuid := NULLIF(_filters->>'assigned_officer_id', '')::uuid;
  v_team text := NULLIF(_filters->>'assigned_team', 'all');
  v_unread boolean := COALESCE((_filters->>'unread_only')::boolean, false);
  v_source_type text := NULLIF(_filters->>'source_type', '');
  v_source_id uuid := NULLIF(_filters->>'source_id', '')::uuid;
  v_lim integer := LEAST(GREATEST(COALESCE(_limit, 50), 1), 200);
  v_off integer := GREATEST(COALESCE(_offset, 0), 0);
  v_total integer;
  v_rows jsonb;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  v_staff := public.is_internal_staff(v_user);
  v_licensee := public.user_licensee_id(v_user);

  IF NOT v_staff AND v_licensee IS NULL THEN
    RETURN jsonb_build_object('rows', '[]'::jsonb, 'total', 0);
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS _corr_feed_tmp (id uuid) ON COMMIT DROP;

  WITH base AS (
    SELECT t.*
      FROM public.correspondence_threads t
     WHERE (
             v_staff
             OR (t.is_entity_facing = true
                 AND ((t.licensee_id IS NOT NULL AND t.licensee_id = v_licensee)
                      OR t.created_by = v_user))
           )
       AND (v_staff = false OR public.correspondence_case_readable(t.source_type, t.source_id, v_user))
       AND (v_status IS NULL OR t.thread_state = v_status)
       AND (v_module IS NULL OR t.module = v_module)
       AND (v_type IS NULL OR t.thread_type = v_type)
       AND (v_team IS NULL OR t.assigned_team = v_team OR t.assigned_unit = v_team)
       AND (v_assignee IS NULL OR t.assigned_officer_id = v_assignee)
       AND (v_source_type IS NULL OR t.source_type = v_source_type)
       AND (v_source_id IS NULL OR t.source_id = v_source_id)
       AND (
             v_direction IS NULL
             OR (v_direction = 'internal' AND t.is_entity_facing = false)
             OR (v_direction <> 'internal' AND t.is_entity_facing = true
                 AND COALESCE(t.last_message_kind,
                              CASE WHEN t.direction = 'inbound' THEN 'external_inbound' ELSE 'external_outbound' END)
                     = CASE WHEN v_direction = 'inbound' THEN 'external_inbound' ELSE 'external_outbound' END)
           )
       AND (
             v_q IS NULL
             OR t.subject ILIKE '%' || v_q || '%'
             OR t.reference ILIKE '%' || v_q || '%'
             OR COALESCE(t.source_reference, '') ILIKE '%' || v_q || '%'
             OR COALESCE(t.sender_name, '') ILIKE '%' || v_q || '%'
             OR COALESCE(t.sender_org, '') ILIKE '%' || v_q || '%'
             OR EXISTS (SELECT 1 FROM public.licensees l
                         WHERE l.id = t.licensee_id AND l.entity_name ILIKE '%' || v_q || '%')
             OR EXISTS (SELECT 1 FROM public.correspondence_thread_participants p
                         WHERE p.thread_id = t.id AND p.display_name ILIKE '%' || v_q || '%')
           )
  ), scored AS (
    SELECT b.*, public.correspondence_thread_unread_count(b.id, v_user) AS unread_count
      FROM base b
  ), filtered AS (
    SELECT * FROM scored WHERE v_unread = false OR unread_count > 0
  )
  SELECT COUNT(*)::int,
         COALESCE(jsonb_agg(row_to_json(page)::jsonb ORDER BY page.sort_at DESC), '[]'::jsonb)
    INTO v_total, v_rows
    FROM (
      SELECT f.id, f.reference, f.subject, f.summary, f.module, f.category, f.channel,
             f.thread_type, f.thread_state, f.priority, f.is_entity_facing,
             f.source_type, f.source_id, f.source_reference,
             f.licensee_id, f.assigned_unit, f.assigned_team, f.assigned_officer,
             f.assigned_officer_id, f.sender_name, f.sender_org,
             f.last_message_at, f.last_message_preview, f.last_message_kind,
             f.received_at, f.pending_since, f.response_due_at,
             f.sla_warned_at, f.sla_breached_at, f.closed_at, f.unread_count,
             COALESCE(f.last_message_at, f.received_at) AS sort_at,
             CASE WHEN f.is_entity_facing = false THEN 'internal'
                  WHEN COALESCE(f.last_message_kind, '') = 'external_inbound' THEN 'inbound'
                  WHEN COALESCE(f.last_message_kind, '') = 'external_outbound' THEN 'outbound'
                  ELSE f.direction END AS effective_direction,
             (SELECT l.entity_name FROM public.licensees l WHERE l.id = f.licensee_id) AS entity_name,
             (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'id', p.id, 'name', p.display_name, 'role', COALESCE(p.party_role, p.party_type),
                        'is_internal', p.is_internal, 'last_read_at', p.last_read_at)
                      ORDER BY p.created_at), '[]'::jsonb)
                FROM public.correspondence_thread_participants p
               WHERE p.thread_id = f.id
                 AND (v_staff OR p.is_internal = false)) AS parties
        FROM filtered f
       ORDER BY COALESCE(f.last_message_at, f.received_at) DESC
       LIMIT v_lim OFFSET v_off
    ) page;

  RETURN jsonb_build_object(
    'rows', v_rows,
    'total', (SELECT COUNT(*)::int FROM public.correspondence_threads t
               WHERE (v_staff OR (t.is_entity_facing = true
                     AND ((t.licensee_id IS NOT NULL AND t.licensee_id = v_licensee) OR t.created_by = v_user)))),
    'page_count', v_total,
    'can_filter_assignee', v_staff
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_thread_link_case(_thread_id uuid, _source_type text, _source_id uuid, _source_reference text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_actor text;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  IF NOT public.is_internal_staff(v_user) THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;
  IF NOT public.correspondence_thread_visible(_thread_id, v_user) THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;
  IF NOT public.correspondence_case_readable(_source_type, _source_id, v_user) THEN
    RAISE EXCEPTION 'case_not_accessible' USING ERRCODE = '42501';
  END IF;
  v_actor := public.correspondence_actor_label(v_user);

  UPDATE public.correspondence_threads
     SET source_type = _source_type,
         source_id = _source_id,
         source_reference = COALESCE(_source_reference, source_reference),
         module = public.correspondence_module_for(_source_type, category, thread_type)
   WHERE id = _thread_id;

  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
  VALUES (_thread_id, v_user, v_actor, 'Staff', 'THREAD_STATUS_CHANGED',
          'Linked to ' || _source_type || COALESCE(' ' || _source_reference, ''), true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_thread_unread_count(_thread_id uuid, _user_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COUNT(*)::int
    FROM public.correspondence_messages m
   WHERE m.thread_id = _thread_id
     AND COALESCE(m.is_draft, false) = false
     AND m.author_id IS DISTINCT FROM _user_id
     AND (m.is_internal_note = false OR public.is_internal_staff(_user_id))
     AND m.sent_at > COALESCE(
       (SELECT p.last_read_at FROM public.correspondence_thread_participants p
         WHERE p.thread_id = _thread_id AND p.user_id = _user_id),
       'epoch'::timestamptz);
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_thread_visible(_thread_id uuid, _user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.correspondence_threads t
    WHERE t.id = _thread_id
      AND (
        public.is_internal_staff(_user_id)
        OR (t.licensee_id IS NOT NULL AND t.licensee_id = public.user_licensee_id(_user_id))
        OR t.created_by = _user_id
      )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_touch_thread_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(NEW.is_draft, false) = false THEN
    UPDATE public.correspondence_threads
       SET last_message_at = COALESCE(NEW.sent_at, now()),
           last_message_preview = left(regexp_replace(COALESCE(NEW.body,''), '\s+', ' ', 'g'), 180),
           last_message_kind = NEW.message_kind
     WHERE id = NEW.thread_id;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.correspondence_work_queue(_filters jsonb DEFAULT '{}'::jsonb, _limit integer DEFAULT 25, _offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_staff boolean;
  v_licensee uuid;
  v_q text := NULLIF(TRIM(COALESCE(_filters->>'query', '')), '');
  v_state text := NULLIF(_filters->>'status', 'all');
  v_module text := NULLIF(_filters->>'module', 'all');
  v_type text := NULLIF(_filters->>'thread_type', 'all');
  v_channel text := NULLIF(_filters->>'channel', 'all');
  v_priority text := NULLIF(_filters->>'priority', 'all');
  v_bucket text := NULLIF(_filters->>'bucket', 'all');
  v_assignee uuid := NULLIF(_filters->>'assigned_officer_id', '')::uuid;
  v_source_type text := NULLIF(_filters->>'source_type', '');
  v_source_id uuid := NULLIF(_filters->>'source_id', '')::uuid;
  v_lim integer := LEAST(GREATEST(COALESCE(_limit, 25), 1), 200);
  v_off integer := GREATEST(COALESCE(_offset, 0), 0);
  v_total integer := 0;
  v_rows jsonb := '[]'::jsonb;
  v_counts jsonb := '{}'::jsonb;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  v_staff := public.is_internal_staff(v_user);
  v_licensee := public.user_licensee_id(v_user);

  IF NOT v_staff AND v_licensee IS NULL THEN
    RETURN jsonb_build_object('rows', '[]'::jsonb, 'total', 0, 'page_count', 0,
                              'counts', jsonb_build_object(), 'can_filter_assignee', false);
  END IF;

  WITH base AS (
    SELECT t.id, t.reference, t.subject, t.summary, t.module, t.category,
           t.channel, t.thread_type, t.thread_state, t.priority, t.is_entity_facing,
           t.source_type, t.source_id, t.source_reference,
           public.correspondence_case_href(t.source_type, t.source_id) AS related_href,
           t.licensee_id,
           (SELECT l.name FROM public.licensees l WHERE l.id = t.licensee_id) AS entity_name,
           t.sender_name AS person_name, t.sender_org AS person_org,
           t.assigned_officer AS owner_name, t.assigned_officer_id AS owner_id,
           COALESCE(t.assigned_team, t.assigned_unit) AS team,
           COALESCE(t.response_due_at, t.due_at) AS sla_due_at,
           CASE
             WHEN t.thread_state = 'closed' THEN 'none'
             WHEN t.sla_breached_at IS NOT NULL THEN 'breached'
             WHEN t.sla_warned_at IS NOT NULL THEN 'at_risk'
             WHEN COALESCE(t.response_due_at, t.due_at) IS NULL THEN 'none'
             WHEN COALESCE(t.response_due_at, t.due_at) < now() THEN 'breached'
             WHEN COALESCE(t.response_due_at, t.due_at) < now() + interval '48 hours' THEN 'at_risk'
             ELSE 'on_track'
           END AS sla_state,
           CASE
             WHEN t.thread_state = 'closed' THEN NULL
             WHEN t.thread_state = 'pending_response' THEN 'entity'
             ELSE 'regulator'
           END AS waiting_on,
           public.correspondence_thread_unread_count(t.id, v_user) AS unread_count,
           CASE
             WHEN t.thread_state = 'closed' THEN 'No action — thread closed'
             WHEN t.thread_state = 'pending_response' THEN 'Await entity response'
             WHEN COALESCE(t.last_message_kind, '') = 'external_inbound' THEN 'Review inbound message and respond'
             WHEN t.assigned_officer_id IS NULL THEN 'Assign an owner'
             ELSE 'Progress the conversation'
           END AS next_action,
           COALESCE(t.last_message_at, t.received_at) AS last_activity_at,
           '/correspondence/' || t.id AS canonical_href,
           CASE WHEN t.is_entity_facing = false THEN 'internal'
                WHEN COALESCE(t.last_message_kind, '') = 'external_inbound' THEN 'inbound'
                WHEN COALESCE(t.last_message_kind, '') = 'external_outbound' THEN 'outbound'
                ELSE t.direction END AS effective_direction
      FROM public.correspondence_threads t
     WHERE (
             v_staff
             OR (t.is_entity_facing = true
                 AND ((t.licensee_id IS NOT NULL AND t.licensee_id = v_licensee) OR t.created_by = v_user))
           )
       AND (v_staff = false OR public.correspondence_case_readable(t.source_type, t.source_id, v_user))
  ), scoped AS (
    SELECT b.*,
           (b.thread_state <> 'closed'
            AND (
              (v_staff AND (b.unread_count > 0 OR b.waiting_on = 'regulator' OR b.owner_id IS NULL))
              OR (NOT v_staff AND (b.unread_count > 0 OR b.waiting_on = 'entity'))
            )) AS action_required
      FROM base b
  ), agg AS (
    SELECT jsonb_build_object(
      'total_open', COUNT(*) FILTER (WHERE thread_state <> 'closed'),
      'awaiting_response', COUNT(*) FILTER (WHERE waiting_on = 'entity'),
      'breached', COUNT(*) FILTER (WHERE sla_state = 'breached'),
      'at_risk', COUNT(*) FILTER (WHERE sla_state = 'at_risk'),
      'unread', COUNT(*) FILTER (WHERE unread_count > 0),
      'action_required', COUNT(*) FILTER (WHERE action_required),
      'unassigned', COUNT(*) FILTER (WHERE owner_id IS NULL AND thread_state <> 'closed'),
      'mine', COUNT(*) FILTER (WHERE owner_id = v_user AND thread_state <> 'closed'),
      'total', COUNT(*)
    ) AS counts FROM scoped
  ), f AS (
    SELECT w.* FROM scoped w
     WHERE (v_state IS NULL OR w.thread_state = v_state)
       AND (v_module IS NULL OR w.module = v_module)
       AND (v_type IS NULL OR w.thread_type = v_type)
       AND (v_channel IS NULL OR w.channel = v_channel)
       AND (v_priority IS NULL OR w.priority = v_priority)
       AND (v_assignee IS NULL OR w.owner_id = v_assignee)
       AND (v_source_type IS NULL OR w.source_type = v_source_type)
       AND (v_source_id IS NULL OR w.source_id = v_source_id)
       AND (
             v_bucket IS NULL
             OR (v_bucket = 'open' AND w.thread_state <> 'closed')
             OR (v_bucket = 'mine' AND w.owner_id = v_user AND w.thread_state <> 'closed')
             OR (v_bucket = 'unassigned' AND w.owner_id IS NULL AND w.thread_state <> 'closed')
             OR (v_bucket = 'awaiting_response' AND w.waiting_on = 'entity')
             OR (v_bucket = 'breached' AND w.sla_state = 'breached')
             OR (v_bucket = 'unread' AND w.unread_count > 0)
             OR (v_bucket = 'action_required' AND w.action_required)
           )
       AND (
             v_q IS NULL
             OR w.subject ILIKE '%' || v_q || '%'
             OR w.reference ILIKE '%' || v_q || '%'
             OR COALESCE(w.source_reference, '') ILIKE '%' || v_q || '%'
             OR COALESCE(w.person_name, '') ILIKE '%' || v_q || '%'
             OR COALESCE(w.person_org, '') ILIKE '%' || v_q || '%'
             OR COALESCE(w.entity_name, '') ILIKE '%' || v_q || '%'
           )
  ), page AS (
    SELECT * FROM f ORDER BY last_activity_at DESC NULLS LAST, id LIMIT v_lim OFFSET v_off
  )
  SELECT (SELECT COUNT(*)::int FROM f),
         COALESCE((SELECT jsonb_agg(row_to_json(p)::jsonb ORDER BY p.last_activity_at DESC NULLS LAST, p.id) FROM page p), '[]'::jsonb),
         (SELECT counts FROM agg)
    INTO v_total, v_rows, v_counts;

  RETURN jsonb_build_object(
    'rows', v_rows,
    'total', v_total,
    'page_count', jsonb_array_length(v_rows),
    'counts', v_counts,
    'can_filter_assignee', v_staff
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.create_application_draft(_license_type text, _data jsonb DEFAULT '{}'::jsonb, _regulator_id uuid DEFAULT NULL::uuid)
 RETURNS applications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_application public.applications;
  v_entity_id uuid;
  v_is_post boolean;
  v_is_staff boolean;
  v_license_id uuid := NULLIF(_data->>'license_id','')::uuid;
  v_claimed_entity uuid := NULLIF(_data->>'licensee_id','')::uuid;
  v_license_holder uuid;
  v_service_id text := NULLIF(_data->>'service_id','');
  v_existing uuid;
  v_reg_id uuid := NULLIF(_data->>'registration_id','')::uuid;
  v_handoff record;
  v_ctx record;
  v_data jsonb := COALESCE(_data, '{}'::jsonb);
  v_regulator uuid := _regulator_id;
  v_trusted boolean := COALESCE(current_setting('app.workflow_mutation_context', true), '') = 'trusted';
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: You must be signed in to create an application draft.'
      USING ERRCODE = '42501';
  END IF;

  v_is_staff := public.is_super_admin(v_uid)
                OR public.has_permission(v_uid, 'application_management', 'create');

  IF NOT (
    v_is_staff
    OR public.has_role(v_uid, 'applicant'::public.app_role)
    OR public.has_role(v_uid, 'pre_licensee'::public.app_role)
    OR public.has_role(v_uid, 'licensee_primary'::public.app_role)
    OR public.has_role(v_uid, 'licensee_secondary'::public.app_role)
  ) THEN
    RAISE EXCEPTION 'APPLICATION_CREATE_FORBIDDEN: You do not have permission to create an application draft.'
      USING ERRCODE = '42501';
  END IF;

  SELECT m.entity_id INTO v_entity_id
    FROM public.entity_user_memberships m
    JOIN public.licensees l ON l.id = m.entity_id
   WHERE m.user_id = v_uid AND m.status = 'APPROVED' AND l.merged_into_entity_id IS NULL
   ORDER BY m.approved_at DESC NULLS LAST
   LIMIT 1;

  IF v_entity_id IS NULL THEN
    SELECT p.licensee_id INTO v_entity_id
      FROM public.profiles p JOIN public.licensees l ON l.id = p.licensee_id
     WHERE p.id = v_uid AND l.merged_into_entity_id IS NULL;
  END IF;

  IF v_entity_id IS NULL THEN
    SELECT l.id INTO v_entity_id
      FROM public.licensees l
     WHERE l.applicant_id = v_uid AND l.merged_into_entity_id IS NULL
     ORDER BY l.created_at
     LIMIT 1;
  END IF;

  v_is_post := (v_service_id IS NOT NULL)
               OR lower(COALESCE(_data->>'type','')) = 'post_license'
               OR v_license_id IS NOT NULL;

  IF v_is_post THEN
    IF v_license_id IS NULL THEN
      IF NOT v_is_staff THEN
        RAISE EXCEPTION 'LICENSE_REQUIRED: Select the licence this post-licence service relates to.'
          USING ERRCODE = '22023';
      END IF;
    ELSE
      SELECT * INTO v_ctx
        FROM public.resolve_post_license_intake_context(v_license_id, NULLIF(v_service_id,'')::uuid);
      IF v_ctx.entity_id IS NULL THEN
        RAISE EXCEPTION 'LICENSE_NOT_FOUND: The selected licence could not be found.'
          USING ERRCODE = '22023';
      END IF;
      v_license_holder := v_ctx.entity_id;

      IF v_claimed_entity IS NOT NULL AND v_claimed_entity IS DISTINCT FROM v_license_holder THEN
        RAISE EXCEPTION 'LICENSE_ENTITY_MISMATCH: The selected licence does not belong to the selected entity.'
          USING ERRCODE = '42501';
      END IF;
      v_entity_id := v_license_holder;

      IF v_service_id IS NOT NULL
         AND NOT public.service_license_compatible(v_service_id::uuid, v_license_id) THEN
        RAISE EXCEPTION 'SERVICE_LICENSE_INCOMPATIBLE: The selected service is not available for the scope of this licence.'
          USING ERRCODE = '42501';
      END IF;

      v_data := v_data || jsonb_build_object(
        'type', 'post_license',
        'license_id', v_license_id,
        'licensee_id', v_entity_id,
        'sector_id', v_ctx.sector_id,
        'sub_sector_id', v_ctx.sub_sector_id,
        'category_id', v_ctx.category_id
      );
      v_regulator := COALESCE(v_regulator, v_ctx.regulator_id);

      IF NOT v_is_staff THEN
        IF NOT public.can_act_on_specific_license(v_license_id, v_license_holder, NULL, NULL, NULL) THEN
          RAISE EXCEPTION 'LICENSE_ENTITLEMENT_REQUIRED: Post-licence services are only available for a licence that is approved, issued and in good standing for this sector.'
            USING ERRCODE = '42501';
        END IF;
      END IF;
    END IF;

    IF v_license_id IS NULL AND NOT v_is_staff THEN
      IF NOT public.can_act_on_license(
           COALESCE(v_claimed_entity, v_entity_id),
           NULLIF(_data->>'sector_id','')::uuid,
           NULLIF(_data->>'sub_sector_id','')::uuid,
           NULLIF(_data->>'category_id','')::uuid
         ) THEN
        RAISE EXCEPTION 'LICENSE_ENTITLEMENT_REQUIRED: Post-licence services are only available for a licence that is approved, issued and in good standing for this sector.'
          USING ERRCODE = '42501';
      END IF;
    END IF;

    IF v_license_id IS NOT NULL AND v_service_id IS NOT NULL THEN
      PERFORM pg_advisory_xact_lock(
        hashtextextended('post_license_request:' || v_license_id::text || ':' || v_service_id, 0)
      );

      SELECT a.id INTO v_existing
        FROM public.applications a
       WHERE COALESCE(a.data->>'license_id','') = v_license_id::text
         AND COALESCE(a.data->>'service_id','') = v_service_id
         AND a.status = ANY (public.post_license_open_statuses())
       ORDER BY a.created_at
       LIMIT 1;

      IF v_existing IS NOT NULL THEN
        RAISE EXCEPTION 'DUPLICATE_POST_LICENSE_REQUEST: %', v_existing
          USING ERRCODE = 'unique_violation',
                HINT = v_existing::text;
      END IF;
    END IF;
  ELSE
    IF NOT v_trusted THEN
      IF v_reg_id IS NULL THEN
        SELECT h.registration_id INTO v_reg_id
          FROM public.registration_licensing_handoffs h
          JOIN public.registrations r ON r.id = h.registration_id
         WHERE r.user_id = v_uid AND lower(r.status) = 'approved'
         ORDER BY h.created_at DESC
         LIMIT 1;
      END IF;

      IF v_reg_id IS NULL THEN
        RAISE EXCEPTION 'REGISTRATION_HANDOFF_REQUIRED: A new licence application requires an approved registration handoff.'
          USING ERRCODE = '42501';
      END IF;

      SELECT h.*, r.status AS reg_status, r.user_id AS reg_user
        INTO v_handoff
        FROM public.registration_licensing_handoffs h
        JOIN public.registrations r ON r.id = h.registration_id
       WHERE h.registration_id = v_reg_id;

      IF NOT FOUND OR lower(COALESCE(v_handoff.reg_status,'')) <> 'approved' THEN
        RAISE EXCEPTION 'REGISTRATION_HANDOFF_REQUIRED: A new licence application requires an approved registration handoff.'
          USING ERRCODE = '42501';
      END IF;

      IF NOT v_is_staff AND v_handoff.reg_user IS DISTINCT FROM v_uid THEN
        RAISE EXCEPTION 'REGISTRATION_HANDOFF_FORBIDDEN: This registration handoff does not belong to you.'
          USING ERRCODE = '42501';
      END IF;

      IF v_handoff.application_id IS NOT NULL THEN
        SELECT * INTO v_application FROM public.applications WHERE id = v_handoff.application_id;
        IF FOUND THEN
          RETURN v_application;
        END IF;
      END IF;
    END IF;
  END IF;

  INSERT INTO public.applications (
    applicant_id, license_type, status, data, regulator_id, entity_id
  )
  VALUES (
    v_uid,
    COALESCE(NULLIF(trim(_license_type), ''), 'Application'),
    'draft',
    v_data || CASE WHEN v_reg_id IS NOT NULL
      THEN jsonb_build_object('registration_id', v_reg_id) ELSE '{}'::jsonb END,
    v_regulator,
    v_entity_id
  )
  RETURNING * INTO v_application;

  IF NOT v_is_post AND v_reg_id IS NOT NULL THEN
    UPDATE public.registration_licensing_handoffs
       SET application_id = v_application.id, updated_at = now()
     WHERE registration_id = v_reg_id AND application_id IS NULL;
  END IF;

  RETURN v_application;
END $function$
;
CREATE OR REPLACE FUNCTION public.create_audit_log(_user_id uuid, _action text, _entity_type text, _entity_id text DEFAULT NULL::text, _old_value jsonb DEFAULT NULL::jsonb, _new_value jsonb DEFAULT NULL::jsonb, _metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value, metadata)
  VALUES (_user_id, _action, _entity_type, _entity_id, _old_value, _new_value, _metadata)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_audit_log(_entity_type text, _entity_id uuid, _action text, _metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.create_audit_log(
    auth.uid(), _action, _entity_type, _entity_id::text, NULL::jsonb, NULL::jsonb, _metadata
  );
$function$
;
CREATE OR REPLACE FUNCTION public.create_complaint(_payload jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT public.create_complaint(
    COALESCE(
      NULLIF(_payload->>'variant',''),
      CASE WHEN COALESCE(_payload->>'intake_source','') IN ('internal','staff_intake')
           THEN 'internal' ELSE 'licensee' END
    ),
    _payload
  );
$function$
;
CREATE OR REPLACE FUNCTION public.create_complaint(_variant text, _payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_variant text := lower(coalesce(_variant,'internal'));
  v_is_internal boolean;
  v_regulator uuid := NULLIF(_payload->>'regulator_id','')::uuid;
  v_licensee uuid := NULLIF(_payload->>'licensee_id','')::uuid;
  v_subject text := btrim(coalesce(_payload->>'subject',''));
  v_desc    text := btrim(coalesce(_payload->>'description',''));
  v_email   text := NULLIF(_payload->>'email','');
  v_type_id uuid := NULLIF(_payload->>'complaint_type_id','')::uuid;
  v_crc_id uuid := NULLIF(_payload->>'conduct_risk_category_id','')::uuid;
  v_product_id uuid := NULLIF(_payload->>'product_id','')::uuid;
  v_channel_id uuid := NULLIF(_payload->>'channel_id','')::uuid;
  v_customer_type text := NULLIF(_payload->>'customer_type','');
  v_sev text;
  v_prio text;
  v_intake text := NULLIF(_payload->>'intake_source','');
  v_anon boolean := coalesce((_payload->>'anonymous')::boolean, false);
  v_vuln boolean := coalesce((_payload->>'vulnerability_indicator')::boolean, false);
  v_vuln_notes text := NULLIF(_payload->>'vulnerability_notes','');
  v_vuln_cat text := NULLIF(_payload->>'vulnerability_category','');
  v_workflow_id uuid;
  v_workflow_version uuid;
  v_first_step uuid;
  v_first_step_key text;
  v_id uuid;
  v_wi_id uuid;
  v_errors jsonb := '[]'::jsonb;
  v_row jsonb;
  v_decision jsonb;
BEGIN
  -- Variant validation
  IF v_variant NOT IN ('public','licensee','internal','staff') THEN
    RAISE EXCEPTION 'Invalid variant: %', v_variant USING ERRCODE='22023';
  END IF;

  -- Auth policy per variant
  IF v_variant IN ('licensee','internal','staff') AND v_uid IS NULL THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE='42501';
  END IF;

  -- Rule resolution + validation (single source of truth: public.complaint_intake_decide)
  v_decision := public.complaint_intake_decide(v_variant, v_regulator, _payload);
  v_sev    := v_decision->>'severity';
  v_prio   := v_decision->>'priority';
  v_errors := COALESCE(v_decision->'errors', '[]'::jsonb);
  IF NOT v_vuln THEN
    v_vuln_notes := NULL; v_vuln_cat := NULL;
  END IF;

  -- Ignore unknown customer types rather than failing intake
  IF v_customer_type IS NOT NULL
     AND lower(v_customer_type) NOT IN ('retail','sme','corporate','vulnerable','other') THEN
    v_customer_type := NULL;
  ELSIF v_customer_type IS NOT NULL THEN
    v_customer_type := lower(v_customer_type);
  END IF;

  -- Only keep reference ids that exist (defensive: stale client caches)
  IF v_crc_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.conduct_risk_categories WHERE id = v_crc_id) THEN
    v_crc_id := NULL;
  END IF;
  IF v_product_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.conduct_products WHERE id = v_product_id) THEN
    v_product_id := NULL;
  END IF;
  IF v_channel_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.conduct_channels WHERE id = v_channel_id) THEN
    v_channel_id := NULL;
  END IF;

  IF jsonb_array_length(v_errors) > 0 THEN
    RAISE EXCEPTION 'validation_failed'
      USING ERRCODE = '22023', DETAIL = v_errors::text, HINT = 'complaint_validation';
  END IF;

  -- Determine intake_source default
  v_is_internal := (v_variant IN ('internal','staff'));
  IF v_intake IS NULL THEN
    v_intake := v_decision->>'intake_source';
  END IF;

  -- Insert the complaint
  INSERT INTO public.complaints (
    complainant_id, subject, description, email, severity, priority, status,
    intake_source, internal_created_by, complaint_type_id, licensee_id, regulator_id,
    conduct_risk_category_id, product_id, channel_id, customer_type,
    vulnerability_indicator, vulnerability_notes, vulnerability_category
  ) VALUES (
    CASE WHEN v_variant IN ('public') AND v_anon THEN NULL
         WHEN v_is_internal THEN NULL
         ELSE v_uid END,
    v_subject, v_desc,
    COALESCE(v_email, CASE WHEN v_uid IS NOT NULL THEN (SELECT email FROM auth.users WHERE id=v_uid) END),
    v_sev, v_prio, 'submitted',
    v_intake,
    CASE WHEN v_is_internal THEN v_uid END,
    v_type_id, v_licensee, v_regulator,
    v_crc_id, v_product_id, v_channel_id, v_customer_type,
    v_vuln, v_vuln_notes, v_vuln_cat
  ) RETURNING id INTO v_id;

  -- Start the workflow (best-effort — if no active version, complaint still created)
  SELECT id INTO v_workflow_id FROM public.approval_workflows
    WHERE lower(name) LIKE '%complaint%' ORDER BY created_at LIMIT 1;

  IF v_workflow_id IS NOT NULL THEN
    SELECT id INTO v_workflow_version FROM public.approval_workflow_versions
      WHERE workflow_id = v_workflow_id AND status='published'
      ORDER BY version_number DESC LIMIT 1;

    SELECT id, step_key INTO v_first_step, v_first_step_key FROM public.approval_steps
      WHERE workflow_id = v_workflow_id
      ORDER BY step_order ASC NULLS LAST LIMIT 1;

    IF v_workflow_version IS NOT NULL THEN
      INSERT INTO public.workflow_instances (
        workflow_id, workflow_version_id, entity_type, entity_id,
        current_step_id, current_step_key, status
      ) VALUES (
        v_workflow_id, v_workflow_version, 'complaint', v_id,
        v_first_step, v_first_step_key, 'active'
      )
      ON CONFLICT (entity_id, entity_type) WHERE status = ANY (ARRAY['active','paused']) DO NOTHING
      RETURNING id INTO v_wi_id;
    END IF;
  END IF;

  -- Audit
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'complaint.created', 'complaint', v_id,
    jsonb_build_object('variant', v_variant, 'intake_source', v_intake, 'workflow_instance_id', v_wi_id));

  -- Notification outbox (best-effort dedupe via existing unique index)
  BEGIN
    INSERT INTO public.notification_outbox (event_key, entity_type, entity_id, channel, payload)
    VALUES ('complaint.created','complaint',v_id,'in_app',
      jsonb_build_object('variant',v_variant,'complaint_id',v_id));
  EXCEPTION WHEN unique_violation THEN NULL;
  END;

  SELECT to_jsonb(c.*) INTO v_row FROM public.complaints c WHERE c.id = v_id;
  RETURN jsonb_build_object(
    'id', v_id,
    'complaint_number', v_row->>'complaint_number',
    'workflow_instance_id', v_wi_id,
    'complaint', v_row
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_complaint_with_attachments(_variant text, _payload jsonb, _staged_upload_ids uuid[] DEFAULT ARRAY[]::uuid[], _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_existing_id uuid;
  v_existing jsonb;
  v_result jsonb;
  v_complaint_id uuid;
  v_reg uuid;
  v_upload record;
  v_payload jsonb := coalesce(_payload,'{}'::jsonb);
BEGIN
  -- Idempotency short-circuit (authenticated callers only)
  IF _idempotency_key IS NOT NULL AND v_uid IS NOT NULL THEN
    SELECT id INTO v_existing_id
      FROM public.complaints
     WHERE internal_created_by = v_uid AND idempotency_key = _idempotency_key
     LIMIT 1;
    IF v_existing_id IS NOT NULL THEN
      SELECT jsonb_build_object(
        'id', c.id,
        'complaint_number', c.complaint_number,
        'workflow_instance_id', (
          SELECT wi.id FROM public.workflow_instances wi
           WHERE wi.entity_type='complaint' AND wi.entity_id=c.id
           ORDER BY wi.created_at DESC LIMIT 1
        ),
        'complaint', to_jsonb(c),
        'idempotent', true
      ) INTO v_existing FROM public.complaints c WHERE c.id = v_existing_id;
      RETURN v_existing;
    END IF;
  END IF;

  -- Delegate to canonical create_complaint (same tx; any raise rolls back)
  v_result := public.create_complaint(_variant, v_payload);
  v_complaint_id := (v_result->>'id')::uuid;

  IF v_complaint_id IS NULL THEN
    RAISE EXCEPTION 'create_complaint returned no id';
  END IF;

  -- Store idempotency key
  IF _idempotency_key IS NOT NULL THEN
    UPDATE public.complaints
       SET idempotency_key = _idempotency_key
     WHERE id = v_complaint_id;
  END IF;

  SELECT regulator_id INTO v_reg FROM public.complaints WHERE id = v_complaint_id;

  -- Validate + link staged uploads (any failure aborts entire tx)
  IF _staged_upload_ids IS NOT NULL AND array_length(_staged_upload_ids,1) > 0 THEN
    FOR v_upload IN
      SELECT id, uploaded_by, entity_type, entity_id
        FROM public.file_uploads
       WHERE id = ANY(_staged_upload_ids)
    LOOP
      -- Ownership
      IF v_uid IS NOT NULL AND v_upload.uploaded_by IS DISTINCT FROM v_uid THEN
        RAISE EXCEPTION 'Staged upload % not owned by caller', v_upload.id
          USING ERRCODE='42501';
      END IF;
      -- Not already linked to a different complaint
      IF EXISTS (
        SELECT 1 FROM public.complaint_evidence ce
         WHERE ce.file_upload_id = v_upload.id AND ce.complaint_id <> v_complaint_id
      ) THEN
        RAISE EXCEPTION 'Staged upload % already linked to another complaint', v_upload.id
          USING ERRCODE='23505';
      END IF;
    END LOOP;

    -- All checks passed, link via existing finalize function (which enforces
    -- regulator scope + idempotent inserts internally).
    PERFORM public.finalize_complaint_with_attachments(v_complaint_id, _staged_upload_ids);
  END IF;

  RETURN v_result || jsonb_build_object('idempotent', false);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_correspondence_thread(_subject text, _summary text, _sender_name text, _sender_org text DEFAULT NULL::text, _sender_email text DEFAULT NULL::text, _channel text DEFAULT 'email'::text, _category text DEFAULT 'General'::text, _priority text DEFAULT NULL::text, _licensee_id uuid DEFAULT NULL::uuid, _tags text[] DEFAULT '{}'::text[], _body text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_staff boolean;
  v_licensee uuid := _licensee_id;
  v_rule public.correspondence_routing_rules%ROWTYPE;
  v_priority text := COALESCE(_priority, 'normal');
  v_sla integer := 5;
  v_id uuid;
  v_actor text;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  v_staff := public.is_internal_staff(v_user);
  IF NOT v_staff THEN
    v_licensee := public.user_licensee_id(v_user);
    IF v_licensee IS NULL THEN RAISE EXCEPTION 'not_authorized'; END IF;
  END IF;
  v_actor := public.correspondence_actor_label(v_user);

  SELECT * INTO v_rule FROM public.correspondence_routing_rules r
  WHERE r.is_active
    AND (
      (r.match_type = 'category' AND lower(r.match_value) = lower(_category))
      OR (r.match_type = 'channel' AND lower(r.match_value) = lower(_channel))
      OR (r.match_type = 'subject' AND _subject ILIKE '%' || r.match_value || '%')
      OR (r.match_type = 'priority' AND lower(r.match_value) = lower(v_priority))
    )
  ORDER BY r.sort_order ASC LIMIT 1;

  IF v_rule.id IS NOT NULL THEN
    v_sla := v_rule.sla_days;
    IF _priority IS NULL THEN v_priority := v_rule.priority; END IF;
  END IF;

  INSERT INTO public.correspondence_threads (
    subject, summary, sender_name, sender_org, sender_email, channel, category,
    priority, licensee_id, tags, sla_days, due_at, retention_expires_at,
    assigned_unit, assigned_officer, status, created_by
  ) VALUES (
    _subject, _summary, _sender_name, _sender_org, _sender_email, _channel, _category,
    v_priority, v_licensee, COALESCE(_tags, '{}'), v_sla, now() + (v_sla || ' days')::interval,
    now() + interval '7 years',
    v_rule.assign_unit, v_rule.assign_officer,
    CASE WHEN v_rule.id IS NOT NULL THEN 'assigned' ELSE 'received' END,
    v_user
  ) RETURNING id INTO v_id;

  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail)
  VALUES (v_id, v_user, v_actor, CASE WHEN v_staff THEN 'Staff' ELSE 'Licensee' END,
          'Correspondence received', 'Channel: ' || _channel);

  IF v_rule.id IS NOT NULL THEN
    INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail)
    VALUES (v_id, v_user, 'Routing Engine', 'System', 'Routed automatically',
            v_rule.assign_unit || COALESCE(' -> ' || v_rule.assign_officer, '') || ' (rule: ' || v_rule.name || ')');
  END IF;

  IF _body IS NOT NULL AND length(TRIM(_body)) > 0 THEN
    INSERT INTO public.correspondence_messages (thread_id, direction, channel, subject, body, author_id, author_name, author_role)
    VALUES (v_id, 'inbound', _channel, _subject, _body, v_user, COALESCE(_sender_name, v_actor),
            CASE WHEN v_staff THEN 'Staff' ELSE 'Licensee' END);
  END IF;

  RETURN v_id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.create_correspondence_thread(_subject text, _summary text, _sender_name text, _sender_org text DEFAULT NULL::text, _sender_email text DEFAULT NULL::text, _channel text DEFAULT 'email'::text, _category text DEFAULT 'General'::text, _priority text DEFAULT NULL::text, _licensee_id uuid DEFAULT NULL::uuid, _tags text[] DEFAULT '{}'::text[], _body text DEFAULT NULL::text, _thread_type text DEFAULT 'general_correspondence'::text, _source_type text DEFAULT NULL::text, _source_id uuid DEFAULT NULL::uuid, _source_reference text DEFAULT NULL::text, _is_entity_facing boolean DEFAULT true, _participants jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_staff boolean;
  v_licensee uuid := _licensee_id;
  v_rule public.correspondence_routing_rules%ROWTYPE;
  v_priority text := COALESCE(_priority, 'normal');
  v_sla integer := 5;
  v_id uuid;
  v_actor text;
  v_entity_facing boolean := COALESCE(_is_entity_facing, true);
  v_module text;
  v_p jsonb;
  v_route jsonb;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  v_staff := public.is_internal_staff(v_user);
  IF NOT v_staff THEN
    v_licensee := public.user_licensee_id(v_user);
    IF v_licensee IS NULL THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;
  END IF;
  IF _thread_type = 'internal_discussion' THEN v_entity_facing := false; END IF;
  IF _thread_type NOT IN ('general_correspondence', 'internal_discussion')
     AND _source_id IS NULL AND _source_reference IS NULL THEN
    RAISE EXCEPTION 'linked_case_required';
  END IF;
  IF _source_id IS NOT NULL AND NOT public.correspondence_case_readable(_source_type, _source_id, v_user) THEN
    RAISE EXCEPTION 'case_not_accessible' USING ERRCODE = '42501';
  END IF;
  v_actor := public.correspondence_actor_label(v_user);
  v_module := public.correspondence_module_for(_source_type, _category, _thread_type);

  -- Routing decision (single source of truth: public.correspondence_route_decide)
  v_route := public.correspondence_route_decide(_category, _channel, _subject, v_priority);
  IF COALESCE((v_route->>'matched')::boolean, false) THEN
    SELECT * INTO v_rule FROM public.correspondence_routing_rules
     WHERE id = (v_route->>'rule_id')::uuid;
    v_sla := COALESCE((v_route->>'sla_days')::int, v_sla);
    IF _priority IS NULL THEN v_priority := COALESCE(v_route->>'priority', v_priority); END IF;
  END IF;

  INSERT INTO public.correspondence_threads (
    subject, summary, sender_name, sender_org, sender_email, channel, category,
    priority, licensee_id, tags, sla_days, sla_hours, due_at, retention_expires_at,
    assigned_unit, assigned_officer, status, created_by,
    thread_type, thread_state, source_type, source_id, source_reference,
    is_entity_facing, last_message_at, module
  ) VALUES (
    _subject, _summary, _sender_name, _sender_org, _sender_email, _channel, _category,
    v_priority, v_licensee, COALESCE(_tags, '{}'), v_sla, v_sla * 24,
    now() + (v_sla || ' days')::interval, now() + interval '7 years',
    v_rule.assign_unit, v_rule.assign_officer,
    CASE WHEN v_rule.id IS NOT NULL THEN 'assigned' ELSE 'received' END,
    v_user,
    COALESCE(_thread_type, 'general_correspondence'), 'open',
    _source_type, _source_id, _source_reference, v_entity_facing, now(), v_module
  ) RETURNING id INTO v_id;

  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
  VALUES (v_id, v_user, v_actor, CASE WHEN v_staff THEN 'Staff' ELSE 'Licensee' END,
          'THREAD_CREATED',
          'Type: ' || COALESCE(_thread_type, 'general_correspondence') || ' · Module: ' || v_module || ' · Channel: ' || _channel,
          v_entity_facing);

  IF v_rule.id IS NOT NULL THEN
    INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
    VALUES (v_id, v_user, 'Routing Engine', 'System', 'THREAD_STATUS_CHANGED',
            'Routed to ' || v_rule.assign_unit || COALESCE(' -> ' || v_rule.assign_officer, '') || ' (rule: ' || v_rule.name || ')', false);
  END IF;

  INSERT INTO public.correspondence_thread_participants (thread_id, user_id, party_type, display_name, party_role, last_read_at, is_internal)
  VALUES (v_id, v_user, CASE WHEN v_staff THEN 'officer' ELSE 'entity' END, v_actor,
          CASE WHEN v_staff THEN 'Officer' ELSE 'Entity' END, now(), v_staff)
  ON CONFLICT (thread_id, user_id) DO NOTHING;

  IF _participants IS NOT NULL THEN
    FOR v_p IN SELECT * FROM jsonb_array_elements(_participants) LOOP
      INSERT INTO public.correspondence_thread_participants (thread_id, user_id, party_type, display_name, party_role, is_internal)
      VALUES (v_id,
              NULLIF(v_p->>'user_id', '')::uuid,
              COALESCE(v_p->>'party_type', 'officer'),
              COALESCE(v_p->>'display_name', 'Participant'),
              v_p->>'party_role',
              COALESCE((v_p->>'is_internal')::boolean,
                       CASE WHEN NULLIF(v_p->>'user_id','') IS NOT NULL
                            THEN public.is_internal_staff((v_p->>'user_id')::uuid) ELSE false END))
      ON CONFLICT (thread_id, user_id) DO NOTHING;
    END LOOP;
  END IF;

  IF _body IS NOT NULL AND length(TRIM(_body)) > 0 THEN
    INSERT INTO public.correspondence_messages (
      thread_id, direction, channel, subject, body, author_id, author_name, author_role,
      message_kind, delivery_status, is_internal_note
    ) VALUES (
      v_id, CASE WHEN v_staff THEN 'outbound' ELSE 'inbound' END, _channel, _subject, _body, v_user,
      COALESCE(_sender_name, v_actor),
      CASE WHEN v_staff THEN 'Staff' ELSE 'Licensee' END,
      CASE WHEN NOT v_entity_facing THEN 'internal'
           WHEN v_staff THEN 'external_outbound' ELSE 'external_inbound' END,
      'sent',
      NOT v_entity_facing
    );
  END IF;

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_document_version(_group_id uuid, _file_upload_id uuid, _change_note text DEFAULT NULL::text, _action text DEFAULT 'new_version'::text)
 RETURNS TABLE(version_id uuid, version integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _owner uuid;
  _next int;
  _new_id uuid;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  SELECT owner_id INTO _owner FROM public.document_groups WHERE id = _group_id FOR UPDATE;
  IF _owner IS NULL THEN RAISE EXCEPTION 'group_not_found'; END IF;
  IF _owner <> _caller AND NOT public.is_doc_staff(_caller) THEN RAISE EXCEPTION 'forbidden'; END IF;

  SELECT COALESCE(MAX(v.version), 0) + 1 INTO _next
    FROM public.document_versions v WHERE v.group_id = _group_id;

  INSERT INTO public.document_versions (group_id, version, file_upload_id, uploaded_by, change_note)
  VALUES (_group_id, _next, _file_upload_id, _caller, _change_note)
  RETURNING id INTO _new_id;

  UPDATE public.document_groups
     SET current_version_id = _new_id, updated_at = now()
   WHERE id = _group_id;

  INSERT INTO public.document_action_logs (group_id, version_id, actor_id, action, details)
  VALUES (_group_id, _new_id, _caller, _action,
          jsonb_build_object('version', _next, 'file_upload_id', _file_upload_id));

  RETURN QUERY SELECT _new_id, _next;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_document_version_metadata(_entity_type text, _entity_id text, _document_type text, _document_label text, _form_id text, _field_id text, _submission_id text, _bucket text, _storage_path text, _file_upload_id uuid, _original_file_name text, _safe_file_name text, _file_size bigint, _mime_type text, _extension text, _checksum text, _metadata jsonb DEFAULT '{}'::jsonb, _change_note text DEFAULT NULL::text, _group_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(document_upload_id uuid, document_version_id uuid, version_number integer, current_version_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _group uuid;
  _next int;
  _new_version uuid;
  _resolved_file_upload_id uuid := COALESCE(_file_upload_id, gen_random_uuid());
  _path_parts text[] := storage.foldername(_storage_path);
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF _bucket <> 'secure-documents' THEN
    RAISE EXCEPTION 'invalid_bucket';
  END IF;

  IF _storage_path IS NULL
     OR COALESCE(_path_parts[1], '') <> _caller::text
     OR COALESCE(_path_parts[2], '') <> 'form-management' THEN
    RAISE EXCEPTION 'invalid_storage_path';
  END IF;

  IF _file_size IS NULL OR _file_size <= 0 OR _file_size > 20971520 THEN
    RAISE EXCEPTION 'invalid_file_size';
  END IF;

  IF _mime_type IS NULL OR _mime_type NOT IN (
    'application/pdf',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'image/jpeg',
    'image/png',
    'image/webp',
    'text/plain',
    'text/csv'
  ) THEN
    RAISE EXCEPTION 'invalid_mime_type';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM storage.objects o
    WHERE o.bucket_id = _bucket
      AND o.name = _storage_path
  ) THEN
    RAISE EXCEPTION 'storage_object_missing';
  END IF;

  IF _group_id IS NOT NULL THEN
    -- Explicit version target: caller is re-versioning a specific logical document.
    SELECT id INTO _group
    FROM public.document_groups
    WHERE id = _group_id
      AND is_deleted = false
    FOR UPDATE;

    IF _group IS NULL THEN
      RAISE EXCEPTION 'group_not_found';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.document_groups g
      WHERE g.id = _group
        AND (g.owner_id = _caller OR public.is_doc_staff(_caller))
    ) THEN
      RAISE EXCEPTION 'forbidden';
    END IF;
  ELSE
    -- Find-or-create: a logical document is uniquely identified by
    -- (entity, document_type, form_id, field_id, owner, ORIGINAL FILE NAME).
    -- Including the original file name prevents distinct files uploaded into the
    -- same multi-file form field from collapsing into a single shared group
    -- (which previously caused every file in the field to receive a new version
    -- whenever any one of them was re-uploaded).
    SELECT id INTO _group
    FROM public.document_groups
    WHERE entity_type = _entity_type
      AND COALESCE(entity_id,'') = COALESCE(_entity_id,'')
      AND document_type = _document_type
      AND COALESCE(field_id,'') = COALESCE(_field_id,'')
      AND COALESCE(form_id,'') = COALESCE(_form_id,'')
      AND owner_id = _caller
      AND COALESCE(display_name,'') = COALESCE(_original_file_name,'')
      AND is_deleted = false
    ORDER BY created_at ASC
    LIMIT 1
    FOR UPDATE;

    IF _group IS NULL THEN
      INSERT INTO public.document_groups (
        entity_type, entity_id, document_type, display_name, document_label,
        form_id, field_id, submission_id, owner_id
      ) VALUES (
        _entity_type, _entity_id, _document_type,
        _original_file_name,
        _document_label,
        _form_id, _field_id, _submission_id, _caller
      ) RETURNING id INTO _group;
    END IF;
  END IF;

  INSERT INTO public.file_uploads (
    id,
    file_name,
    file_path,
    file_size,
    mime_type,
    file_extension,
    uploaded_by,
    entity_type,
    entity_id,
    bucket_name,
    scan_status,
    metadata
  ) VALUES (
    _resolved_file_upload_id,
    _original_file_name,
    _storage_path,
    _file_size,
    _mime_type,
    COALESCE(_extension, ''),
    _caller,
    'document_version',
    _group::text,
    _bucket,
    'clean',
    COALESCE(_metadata, '{}'::jsonb) || jsonb_build_object(
      'original_name', _original_file_name,
      'safe_name', _safe_file_name,
      'document_type', _document_type,
      'document_group_id', _group,
      'checksum_sha256', _checksum,
      'created_via', 'create_document_version_metadata'
    )
  );

  SELECT COALESCE(MAX(version),0) + 1 INTO _next
  FROM public.document_versions
  WHERE group_id = _group;

  INSERT INTO public.document_versions (
    group_id, version, file_upload_id, uploaded_by, change_note,
    bucket, storage_path, original_file_name, safe_file_name,
    file_size, mime_type, extension, checksum, metadata
  ) VALUES (
    _group, _next, _resolved_file_upload_id, _caller, _change_note,
    _bucket, _storage_path, _original_file_name, _safe_file_name,
    _file_size, _mime_type, _extension, _checksum,
    COALESCE(_metadata,'{}'::jsonb) || jsonb_build_object('file_upload_id', _resolved_file_upload_id)
  ) RETURNING id INTO _new_version;

  UPDATE public.document_groups
     SET current_version_id = _new_version, updated_at = now()
   WHERE id = _group;

  INSERT INTO public.document_action_logs (group_id, version_id, actor_id, action, details)
  VALUES (
    _group, _new_version, _caller,
    CASE WHEN _next = 1 THEN 'upload' ELSE 'version_created' END,
    jsonb_build_object(
      'version', _next,
      'file_upload_id', _resolved_file_upload_id,
      'storage_path', _storage_path,
      'mime_type', _mime_type,
      'file_size', _file_size,
      'original_file_name', _original_file_name
    )
  );

  RETURN QUERY
    SELECT _group, _new_version, _next,
           (SELECT dg.current_version_id FROM public.document_groups dg WHERE dg.id = _group);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_notification(_user_id uuid, _title text, _message text, _type text DEFAULT 'info'::text, _entity_type text DEFAULT NULL::text, _entity_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.notifications (user_id, title, message, type, entity_type, entity_id)
  VALUES (_user_id, _title, _message, _type, _entity_type, _entity_id)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_or_get_application_payment(_application_id uuid, _amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_payment record;
  v_amount numeric := COALESCE(_amount, 0);
  v_txn_ref text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object(
      'action', 'block',
      'code', 'UNAUTHORIZED',
      'message', 'You must be signed in.'
    );
  END IF;

  SELECT id, applicant_id
    INTO v_app
    FROM public.applications
   WHERE id = _application_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'block',
      'code', 'NOT_FOUND',
      'message', 'Application not found.'
    );
  END IF;

  IF v_app.applicant_id <> v_uid
     AND NOT public.has_role(v_uid, 'super_admin'::app_role)
     AND NOT public.has_role(v_uid, 'admin'::app_role) THEN
    RETURN jsonb_build_object(
      'action', 'block',
      'code', 'FORBIDDEN',
      'message', 'You do not have access to this application.'
    );
  END IF;

  SELECT p.id, p.status, p.amount, p.transaction_ref, p.receipt_number, p.currency, p.paid_at, p.created_at
    INTO v_payment
    FROM public.payments p
   WHERE p.application_id = _application_id
     AND lower(p.status) IN ('completed', 'success', 'paid')
   ORDER BY p.paid_at DESC NULLS LAST, p.created_at DESC
   LIMIT 1
   FOR UPDATE;

  IF v_payment.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'action', 'paid',
      'payment_id', v_payment.id,
      'status', v_payment.status,
      'amount', v_payment.amount,
      'transaction_ref', v_payment.transaction_ref,
      'receipt_number', v_payment.receipt_number,
      'currency', v_payment.currency,
      'paid_at', v_payment.paid_at
    );
  END IF;

  SELECT p.id, p.status, p.amount, p.transaction_ref, p.receipt_number, p.currency, p.paid_at, p.created_at
    INTO v_payment
    FROM public.payments p
   WHERE p.application_id = _application_id
     AND lower(p.status) IN ('pending', 'processing', 'initiated')
   ORDER BY p.created_at DESC
   LIMIT 1
   FOR UPDATE;

  IF v_payment.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'action', 'pending',
      'payment_id', v_payment.id,
      'status', v_payment.status,
      'amount', v_payment.amount,
      'transaction_ref', v_payment.transaction_ref,
      'receipt_number', v_payment.receipt_number,
      'currency', v_payment.currency,
      'paid_at', v_payment.paid_at
    );
  END IF;

  v_txn_ref := 'TXN-' || EXTRACT(EPOCH FROM clock_timestamp())::bigint || '-' || upper(substr(md5(random()::text), 1, 6));

  INSERT INTO public.payments (
    user_id,
    application_id,
    amount,
    status,
    payment_method,
    transaction_ref
  ) VALUES (
    v_uid,
    _application_id,
    v_amount,
    'initiated',
    'online',
    v_txn_ref
  )
  RETURNING id, status, amount, transaction_ref, receipt_number, currency, paid_at, created_at
    INTO v_payment;

  RETURN jsonb_build_object(
    'action', 'created',
    'payment_id', v_payment.id,
    'status', v_payment.status,
    'amount', v_payment.amount,
    'transaction_ref', v_payment.transaction_ref,
    'receipt_number', v_payment.receipt_number,
    'currency', v_payment.currency,
    'paid_at', v_payment.paid_at
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_review_suggestion(_entity_type text, _entity_id uuid, _field_key text, _type text, _original_text text, _suggested_text text, _selection jsonb, _role_id uuid DEFAULT NULL::uuid)
 RETURNS review_suggestions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE ctx record; row public.review_suggestions%ROWTYPE;
BEGIN
  IF _type NOT IN ('insert','delete','replace') THEN RAISE EXCEPTION 'REVIEW_BAD_SUGGESTION_TYPE'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.review_narrative_fields WHERE entity_type=_entity_type AND field_key=_field_key) THEN
    RAISE EXCEPTION 'REVIEW_UNKNOWN_FIELD';
  END IF;
  SELECT * INTO ctx FROM public.current_workflow_step_for(_entity_type, _entity_id);
  PERFORM public._assert_review_action(auth.uid(), _entity_type, _entity_id, ctx.step_id, _role_id, 'suggest');

  INSERT INTO public.review_suggestions (
    entity_type, entity_id, workflow_instance_id, workflow_step_id,
    field_key, author_user_id, author_role_id, type,
    original_text, suggested_text, selection_start, selection_end
  ) VALUES (
    _entity_type, _entity_id, ctx.instance_id, ctx.step_id,
    _field_key, auth.uid(), _role_id, _type,
    _original_text, _suggested_text,
    NULLIF((_selection->>'start')::int, NULL),
    NULLIF((_selection->>'end')::int, NULL)
  ) RETURNING * INTO row;
  RETURN row;
END $function$
;
CREATE OR REPLACE FUNCTION public.current_workflow_step_for(_entity_type text, _entity_id uuid)
 RETURNS TABLE(instance_id uuid, workflow_id uuid, step_id uuid, regulator_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT wi.id, wi.workflow_id, wi.current_step_id,
         COALESCE(
           (SELECT a.regulator_id FROM public.applications a WHERE a.id = _entity_id),
           (SELECT c.regulator_id FROM public.complaints c WHERE c.id = _entity_id),
           NULL
         )
    FROM public.workflow_instances wi
   WHERE wi.entity_id = _entity_id
     AND (
       (_entity_type = 'application' AND wi.entity_type = ANY(ARRAY['pre_application','post_application','application']))
       OR (_entity_type <> 'application' AND wi.entity_type = _entity_type)
     )
   ORDER BY
     CASE wi.status
       WHEN 'active' THEN 1
       WHEN 'paused' THEN 2
       WHEN 'completed' THEN 3
       WHEN 'cancelled' THEN 4
       ELSE 5
     END,
     wi.created_at DESC
   LIMIT 1;
$function$
;
CREATE OR REPLACE FUNCTION public.decide_duplicate_pair(_id uuid, _action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_complaint_perm(v_uid,'triage') THEN RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501'; END IF;
  IF _action NOT IN ('linked','merged','dismissed','confirmed') THEN
    RAISE EXCEPTION 'Invalid action %', _action USING ERRCODE = '22023';
  END IF;
  UPDATE public.complaint_duplicate_pairs
     SET status=_action, decided_at=now(), decided_by=v_uid, updated_at=now()
   WHERE id = _id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid,'complaint.duplicate_decision','complaint_duplicate_pair',_id, jsonb_build_object('action',_action));
END; $function$
;
CREATE OR REPLACE FUNCTION public.decide_escalation_case(_id uuid, _decision text, _notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_complaint_perm(v_uid,'escalate') THEN RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501'; END IF;
  IF _decision NOT IN ('acknowledged','escalated','dismissed','snoozed','resolved') THEN
    RAISE EXCEPTION 'Invalid decision %', _decision USING ERRCODE = '22023';
  END IF;
  UPDATE public.complaint_escalation_cases
     SET status=_decision, decided_at=now(), decided_by=v_uid,
         notes=COALESCE(_notes,notes), updated_at=now()
   WHERE id = _id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid,'complaint.escalation_decision','complaint_escalation_case',_id,
          jsonb_build_object('decision',_decision,'notes',_notes));
END; $function$
;
CREATE OR REPLACE FUNCTION public.decide_return_edit_request(_request_id uuid, _decision text, _comment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_req public.return_edit_requests%ROWTYPE;
  v_return public.returns_filed%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF NOT (has_role(v_uid,'super_admin') OR has_role(v_uid,'admin') OR has_role(v_uid,'supervisor')) THEN
    RETURN jsonb_build_object('error','Only regulators can decide edit requests','code','FORBIDDEN','http',403);
  END IF;
  IF _decision NOT IN ('allowed','denied') THEN
    RETURN jsonb_build_object('error','Decision must be allowed or denied','code','BAD_REQUEST','http',400);
  END IF;

  SELECT * INTO v_req FROM public.return_edit_requests WHERE id = _request_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Request not found','code','NOT_FOUND','http',404);
  END IF;
  IF v_req.status <> 'pending' THEN
    RETURN jsonb_build_object('error','Request has already been decided','code','ALREADY_DECIDED','http',409);
  END IF;

  SELECT * INTO v_return FROM public.returns_filed WHERE id = v_req.return_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Return not found','code','NOT_FOUND','http',404);
  END IF;

  UPDATE public.return_edit_requests
  SET status = _decision,
      decided_by = v_uid,
      decision_comment = nullif(btrim(coalesce(_comment,'')), ''),
      decided_at = now()
  WHERE id = _request_id;

  IF _decision = 'allowed' THEN
    -- Move return to TBR and open a return_requests row so the existing
    -- TBR/resubmit-return path works unchanged.
    UPDATE public.returns_filed
    SET workflow_status = 'TBR', updated_by = v_uid
    WHERE id = v_req.return_id;

    BEGIN
      INSERT INTO public.return_requests(return_id, reasons, status, requested_by)
      VALUES (v_req.return_id, v_req.reason, 'active', v_req.requested_by);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    BEGIN
      INSERT INTO public.return_audit_log(return_id, action, previous_status, new_status, comments, performed_by, created_at)
      VALUES (v_req.return_id, 'edit_request_allowed', v_return.workflow_status, 'TBR', nullif(btrim(coalesce(_comment,'')), ''), v_uid, now());
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  ELSE
    BEGIN
      INSERT INTO public.return_audit_log(return_id, action, previous_status, new_status, comments, performed_by, created_at)
      VALUES (v_req.return_id, 'edit_request_denied', v_return.workflow_status, v_return.workflow_status, nullif(btrim(coalesce(_comment,'')), ''), v_uid, now());
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  RETURN jsonb_build_object('ok', true, 'decision', _decision, 'return_id', v_req.return_id);
END $function$
;
CREATE OR REPLACE FUNCTION public.decision_gate_status(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_eval RECORD;
  v_blockers int := 0;
  v_open_rfi int := 0;
  v_paid numeric := 0;
  v_gates jsonb := '[]'::jsonb;
  v_blocking int := 0;
  v_fp jsonb;
BEGIN
  SELECT * INTO v_eval
  FROM public.sufficiency_evaluations
  WHERE application_id = _application_id
  ORDER BY evaluated_at DESC
  LIMIT 1;

  IF v_eval.id IS NOT NULL THEN
    SELECT count(*) INTO v_blockers
    FROM public.sufficiency_evaluation_results r
    WHERE r.evaluation_id = v_eval.id
      AND r.status = 'fail'
      AND r.severity = 'blocker'
      AND NOT EXISTS (SELECT 1 FROM public.sufficiency_overrides o WHERE o.evaluation_result_id = r.id);
  END IF;

  SELECT count(*) INTO v_open_rfi
  FROM public.application_rfis
  WHERE application_id = _application_id AND status = 'open';

  SELECT coalesce(sum(amount), 0) INTO v_paid
  FROM public.payments
  WHERE application_id = _application_id AND status IN ('paid','completed','verified','success');

  v_fp := public.application_fp_gate(_application_id);

  v_gates := v_gates || jsonb_build_object(
    'key', 'sufficiency_blockers',
    'label', 'Sufficiency blockers resolved or overridden',
    'blocking', true,
    'passed', (v_eval.id IS NOT NULL AND v_blockers = 0),
    'detail', CASE
      WHEN v_eval.id IS NULL THEN 'No sufficiency evaluation has been run'
      WHEN v_blockers > 0 THEN v_blockers || ' unresolved blocker(s)'
      ELSE 'All blockers cleared' END);

  v_gates := v_gates || jsonb_build_object(
    'key', 'open_rfis',
    'label', 'No open requests for information',
    'blocking', true,
    'passed', (v_open_rfi = 0),
    'detail', CASE WHEN v_open_rfi > 0 THEN v_open_rfi || ' open RFI(s)' ELSE 'None open' END);

  v_gates := v_gates || jsonb_build_object(
    'key', 'fit_and_proper',
    'label', 'Required fit & proper assessments determined',
    'blocking', true,
    'passed', NOT coalesce((v_fp->>'blocking')::boolean, false),
    'detail', CASE
      WHEN NOT coalesce((v_fp->>'required')::boolean, false) THEN 'No fit & proper assessment required'
      ELSE coalesce(v_fp->>'pending','0') || ' pending, ' || coalesce(v_fp->>'adverse','0') || ' adverse'
           || ' (' || coalesce(v_fp->>'linkage','none') || ' linkage)' END,
    'evidence', v_fp);

  v_gates := v_gates || jsonb_build_object(
    'key', 'payment',
    'label', 'Application fees settled',
    'blocking', false,
    'passed', (v_paid > 0),
    'detail', CASE WHEN v_paid > 0 THEN 'Settled amount ' || v_paid::text ELSE 'No settled payment recorded' END);

  SELECT count(*) INTO v_blocking
  FROM jsonb_array_elements(v_gates) g
  WHERE (g->>'blocking')::boolean AND NOT (g->>'passed')::boolean;

  RETURN jsonb_build_object(
    'application_id', _application_id,
    'ready', v_blocking = 0,
    'blocking_unmet', v_blocking,
    'evaluated_at', now(),
    'gates', v_gates);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.delete_ppoc_mapping(_mapping_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_old record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF NOT (public.has_role(v_uid,'super_admin'::app_role) OR public.has_role(v_uid,'admin'::app_role)) THEN
    RETURN jsonb_build_object('error','Admin only','code','FORBIDDEN','http',403);
  END IF;
  IF _mapping_id IS NULL THEN
    RETURN jsonb_build_object('error','Mapping id required','code','INVALID','http',422);
  END IF;

  SELECT * INTO v_old FROM public.ppoc_entity_mappings WHERE id = _mapping_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Mapping not found','code','NOT_FOUND','http',404);
  END IF;

  DELETE FROM public.ppoc_mapping_sectors WHERE mapping_id = _mapping_id;
  DELETE FROM public.ppoc_entity_mappings WHERE id = _mapping_id;

  INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, old_value, new_value, metadata)
  VALUES (
    v_uid,
    'ppoc_mapping_deleted',
    'ppoc_entity_mapping',
    _mapping_id::text,
    jsonb_build_object(
      'ppoc_user_id', v_old.ppoc_user_id,
      'licensee_id', v_old.licensee_id,
      'is_active', v_old.is_active
    ),
    NULL,
    '{}'::jsonb
  );

  RETURN jsonb_build_object('ok', true, 'mapping_id', _mapping_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.derive_communication_state(_status text, _delivered_at timestamp with time zone, _failed_at timestamp with time zone, _error text, _poisoned boolean, _retry_count integer, _next_attempt_at timestamp with time zone)
 RETURNS communication_state
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _delivered_at IS NOT NULL THEN 'DELIVERED'::public.communication_state
    WHEN lower(COALESCE(_status,'')) IN ('delivered','opened') AND _delivered_at IS NOT NULL THEN 'DELIVERED'
    WHEN lower(COALESCE(_status,'')) = 'skipped' THEN 'SUPPRESSED'
    WHEN COALESCE(_error,'') ILIKE '%not_configured%'
      OR COALESCE(_error,'') ILIKE '%not configured%' THEN 'PROVIDER_NOT_CONFIGURED'
    WHEN COALESCE(_poisoned,false) OR COALESCE(_retry_count,0) >= 6
      THEN CASE WHEN lower(COALESCE(_status,'')) IN ('failed','bounced','dead') THEN 'DEAD_LETTER'::public.communication_state ELSE 'FAILED'::public.communication_state END
    WHEN lower(COALESCE(_status,'')) IN ('failed','bounced')
      THEN CASE WHEN _next_attempt_at IS NOT NULL THEN 'RETRYING'::public.communication_state ELSE 'FAILED'::public.communication_state END
    WHEN lower(COALESCE(_status,'')) IN ('sent','sent_to_provider','opened','delivered') THEN 'SENT_TO_PROVIDER'
    ELSE 'QUEUED'
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.derive_ratio_result_state(_value numeric, _null_reason text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _value IS NOT NULL THEN 'CALCULATED'
    WHEN _null_reason IN ('missing_input','missing_ratio_dependency') THEN 'INSUFFICIENT_DATA'
    WHEN _null_reason IN ('not_configured','no_ratio_config') THEN 'NOT_CONFIGURED'
    WHEN _null_reason IS NOT NULL THEN 'CALCULATION_ERROR'
    ELSE 'INSUFFICIENT_DATA'
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.detect_complaint_duplicates(_complaint_id uuid DEFAULT NULL::uuid, _window_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_inserted int := 0; v_score int; v_matched jsonb;
  c1 public.complaints%ROWTYPE; c2 public.complaints%ROWTYPE;
BEGIN
  IF v_uid IS NOT NULL AND NOT (public.has_complaint_perm(v_uid,'triage') OR public.has_complaint_perm(v_uid,'view_all')) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;
  FOR c1 IN SELECT * FROM public.complaints
     WHERE created_at >= now() - make_interval(days => _window_days)
       AND (_complaint_id IS NULL OR id = _complaint_id) LOOP
    FOR c2 IN SELECT * FROM public.complaints
       WHERE id <> c1.id
         AND created_at >= c1.created_at - make_interval(days => _window_days)
         AND created_at <= c1.created_at + make_interval(days => _window_days) LOOP
      v_score := 0; v_matched := '[]'::jsonb;
      IF c1.email IS NOT NULL AND LOWER(c1.email) = LOWER(COALESCE(c2.email,'')) THEN
        v_score := v_score + 40;
        v_matched := v_matched || jsonb_build_object('field','Email','detail','Exact match','strength','exact');
      END IF;
      IF c1.complainant_id IS NOT NULL AND c1.complainant_id = c2.complainant_id THEN
        v_score := v_score + 30;
        v_matched := v_matched || jsonb_build_object('field','Complainant','detail','Same account','strength','exact');
      END IF;
      IF c1.licensee_id IS NOT NULL AND c1.licensee_id = c2.licensee_id THEN
        v_score := v_score + 15;
        v_matched := v_matched || jsonb_build_object('field','Institution','detail','Exact match','strength','exact');
      END IF;
      IF c1.product_id IS NOT NULL AND c1.product_id = c2.product_id THEN
        v_score := v_score + 10;
        v_matched := v_matched || jsonb_build_object('field','Product','detail','Exact match','strength','exact');
      END IF;
      IF c1.complaint_type_id IS NOT NULL AND c1.complaint_type_id = c2.complaint_type_id THEN
        v_score := v_score + 5;
        v_matched := v_matched || jsonb_build_object('field','Issue','detail','Same complaint type','strength','partial');
      END IF;
      IF v_score >= 50 THEN
        INSERT INTO public.complaint_duplicate_pairs (primary_complaint_id, candidate_complaint_id, similarity_score, matched, recommendation, status)
        VALUES (c1.id, c2.id, LEAST(v_score,100), v_matched,
                CASE WHEN v_score >= 80 THEN 'merge' ELSE 'link' END, 'pending')
        ON CONFLICT (primary_complaint_id, candidate_complaint_id) DO NOTHING;
        IF FOUND THEN v_inserted := v_inserted + 1; END IF;
      END IF;
    END LOOP;
  END LOOP;
  RETURN jsonb_build_object('detected', v_inserted, 'ran_at', now());
END; $function$
;
CREATE OR REPLACE FUNCTION public.dismiss_complaint_duplicate(_pair_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_complaint_perm(auth.uid(), 'triage')
     AND NOT public.has_complaint_perm(auth.uid(), 'view_all') THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  UPDATE public.complaint_duplicate_pairs
     SET status = 'dismissed',
         decided_at = now(),
         decided_by = auth.uid(),
         updated_at = now()
   WHERE id = _pair_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pair_not_found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.audit_logs (user_id, action, table_name, record_id, new_values)
  VALUES (auth.uid(), 'dismiss_duplicate', 'complaint_duplicate_pairs', _pair_id,
          jsonb_build_object('reason', _reason));

  RETURN jsonb_build_object('pair_id', _pair_id, 'status', 'dismissed');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.dismiss_complaint_escalation(_case_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_complaint_perm(auth.uid(), 'triage')
     AND NOT public.has_complaint_perm(auth.uid(), 'escalate')
     AND NOT public.has_complaint_perm(auth.uid(), 'view_all') THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  UPDATE public.complaint_escalation_cases
     SET status = 'dismissed',
         decided_at = now(),
         decided_by = auth.uid(),
         notes = COALESCE(_reason, notes),
         updated_at = now()
   WHERE id = _case_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'escalation_not_found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.audit_logs (user_id, action, table_name, record_id, new_values)
  VALUES (auth.uid(), 'dismiss_escalation', 'complaint_escalation_cases', _case_id,
          jsonb_build_object('reason', _reason));

  RETURN jsonb_build_object('case_id', _case_id, 'status', 'dismissed');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.duplicate_hub_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF NOT (public.has_complaint_perm(v_uid,'triage') OR public.has_complaint_perm(v_uid,'view_all')) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;
  RETURN jsonb_build_object(
    'pending', (SELECT count(*) FROM public.complaint_duplicate_pairs WHERE status='pending'),
    'linked', (SELECT count(*) FROM public.complaint_duplicate_pairs WHERE status='linked'),
    'merged', (SELECT count(*) FROM public.complaint_duplicate_pairs WHERE status='merged'),
    'dismissed', (SELECT count(*) FROM public.complaint_duplicate_pairs WHERE status='dismissed'),
    'active_rules', (SELECT count(*) FROM public.complaint_duplicate_rules WHERE enabled=true),
    'total_rules', (SELECT count(*) FROM public.complaint_duplicate_rules)
  );
END; $function$
;
CREATE OR REPLACE FUNCTION public.e360_section_allowed(_user uuid, _section text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN public.is_super_admin(_user) THEN true
    WHEN NOT public.is_internal_staff(_user) THEN false
    WHEN _section IN ('overview','identity','business_profile') THEN
      public.has_permission(_user,'licensee_management','view')
      OR public.has_permission(_user,'entity_structure','view')
    WHEN _section = 'licences' THEN public.has_permission(_user,'license_management','view')
      OR public.has_permission(_user,'licensee_management','view')
    WHEN _section IN ('ownership','relationships','governance') THEN
      public.has_permission(_user,'entity_structure','view')
      OR public.has_permission(_user,'licensee_management','view')
    WHEN _section = 'fit_and_proper' THEN public.has_permission(_user,'fit_and_proper','view')
    WHEN _section = 'fit_and_proper_evidence' THEN
      public.has_permission(_user,'fit_and_proper','view_confidential')
      OR public.has_permission(_user,'fit_and_proper_determinations','view')
    WHEN _section IN ('prudential','risk','supervision') THEN
      public.has_permission(_user,'prudential_supervision','view')
    WHEN _section = 'returns' THEN public.has_permission(_user,'returns_management','view')
    WHEN _section = 'market_conduct' THEN public.has_permission(_user,'market_conduct','view')
      OR public.has_permission(_user,'complaint_management','view')
    WHEN _section = 'aml' THEN public.has_permission(_user,'aml_supervision','view')
    WHEN _section = 'aml_confidential' THEN public.has_permission(_user,'aml_supervision','view_confidential')
    WHEN _section = 'resilience' THEN public.has_permission(_user,'operational_resilience','view')
      OR public.has_permission(_user,'prudential_supervision','view')
    WHEN _section = 'examinations' THEN public.has_permission(_user,'inspection_management','view')
      OR public.has_permission(_user,'prudential_supervision','view')
    WHEN _section = 'enforcement' THEN public.has_permission(_user,'enforcement_management','view')
    WHEN _section = 'regulatory_requests' THEN public.has_permission(_user,'regulatory_requests','view')
      OR public.has_permission(_user,'entity_structure','view')
    WHEN _section = 'documents' THEN public.has_permission(_user,'licensee_management','view')
      OR public.has_permission(_user,'entity_structure','view')
    WHEN _section = 'correspondence' THEN public.has_permission(_user,'coordination','view')
      OR public.has_permission(_user,'licensee_management','view')
    WHEN _section IN ('timeline','provenance') THEN
      public.has_permission(_user,'licensee_management','view')
      OR public.has_permission(_user,'entity_structure','view')
    ELSE false
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforce_action(_module text, _action text, _meta jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF _module IS NULL OR btrim(_module) = '' OR _action IS NULL OR btrim(_action) = '' THEN
    RAISE EXCEPTION 'module and action are required' USING ERRCODE = '22023';
  END IF;
  PERFORM public.enforce_permission(_module, _action);
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid, 'rbac_action.' || _module || '.' || _action, _module, NULL, COALESCE(_meta, '{}'::jsonb));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforce_application_decision_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  blockers jsonb;
  override_exists boolean;
BEGIN
  IF NEW.status = 'approved' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'approved') THEN
    SELECT EXISTS(
      SELECT 1 FROM public.rule_overrides
      WHERE rule_key = 'decision.gate.override'
        AND entity_type = 'application'
        AND entity_id = NEW.id::text
    ) INTO override_exists;

    IF NOT override_exists THEN
      blockers := public.check_decision_gates(NEW.id, NULL);
      IF jsonb_array_length(blockers) > 0 THEN
        RAISE EXCEPTION 'Decision blocked by unresolved gates: %', blockers::text
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforce_complaint_closure_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE blockers jsonb;
BEGIN
  IF NEW.status IN ('closed','resolved') AND OLD.status IS DISTINCT FROM NEW.status THEN
    IF public.has_decision_gate_override('complaint', NEW.id) THEN RETURN NEW; END IF;
    blockers := public.check_coordination_gates('complaint', NEW.id);
    IF jsonb_array_length(blockers) > 0 THEN
      RAISE EXCEPTION 'Complaint closure blocked by unresolved coordination: %', blockers::text USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.enforce_coordination_case_closure()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE open_esc int; open_flags int;
BEGIN
  IF NEW.status = 'closed' AND (OLD.status IS DISTINCT FROM 'closed') THEN
    IF NEW.closure_rationale IS NULL OR length(trim(NEW.closure_rationale)) < 10 THEN
      RAISE EXCEPTION 'Closure rationale (min 10 chars) is required to close a coordination case' USING ERRCODE='check_violation';
    END IF;
    SELECT count(*) INTO open_esc FROM coordination_escalations WHERE case_id=NEW.id AND status IN ('open','in_review');
    IF open_esc > 0 THEN RAISE EXCEPTION 'Cannot close case: % open/in-review escalation(s) remain', open_esc USING ERRCODE='check_violation'; END IF;
    SELECT count(*) INTO open_flags FROM coordination_flags WHERE case_id=NEW.id AND status='open' AND flag_type IN ('blocker','interdependency','concurrent_review');
    IF open_flags > 0 THEN RAISE EXCEPTION 'Cannot close case: % open blocker flag(s) remain', open_flags USING ERRCODE='check_violation'; END IF;
    IF NEW.closed_by IS NULL THEN NEW.closed_by := auth.uid(); END IF;
    IF NEW.closed_at IS NULL THEN NEW.closed_at := now(); END IF;
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.enforce_enforcement_closure_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE blockers jsonb;
BEGIN
  IF NEW.status IN ('closed','resolved') AND OLD.status IS DISTINCT FROM NEW.status THEN
    IF public.has_decision_gate_override('enforcement_action', NEW.id) THEN RETURN NEW; END IF;
    blockers := public.check_coordination_gates('enforcement_action', NEW.id);
    IF jsonb_array_length(blockers) > 0 THEN
      RAISE EXCEPTION 'Enforcement closure blocked by unresolved coordination: %', blockers::text USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.enforce_fp_determination_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE blockers jsonb;
BEGIN
  IF NEW.is_current=true AND NEW.outcome IN ('approved','conditional','rejected','deferred')
     AND (TG_OP='INSERT' OR OLD.is_current IS DISTINCT FROM true OR OLD.outcome IS DISTINCT FROM NEW.outcome) THEN
    IF public.has_decision_gate_override('fp_determination', NEW.id) THEN RETURN NEW; END IF;
    blockers := public.check_coordination_gates('fp_assessment', NEW.assessment_id);
    IF jsonb_array_length(blockers) > 0 THEN
      RAISE EXCEPTION 'Determination blocked by unresolved coordination: %', blockers::text USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.enforce_license_decision_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  blockers jsonb;
  override_exists boolean;
  new_status text;
  old_status text;
BEGIN
  new_status := NEW.status;
  old_status := CASE WHEN TG_OP = 'UPDATE' THEN OLD.status ELSE NULL END;

  IF new_status IN ('active','issued') AND (old_status IS NULL OR old_status IS DISTINCT FROM new_status) THEN
    SELECT EXISTS(
      SELECT 1 FROM public.rule_overrides
      WHERE rule_key = 'decision.gate.override'
        AND (
          (entity_type = 'license'     AND entity_id = NEW.id::text)
          OR (entity_type = 'application' AND entity_id = NEW.application_id::text)
        )
    ) INTO override_exists;

    IF NOT override_exists THEN
      blockers := public.check_decision_gates(NEW.application_id, NEW.id);
      IF jsonb_array_length(blockers) > 0 THEN
        RAISE EXCEPTION 'License activation blocked by unresolved gates: %', blockers::text
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforce_permission(_module text, _action text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication required for %.%', _module, _action
      USING ERRCODE = '42501';
  END IF;
  IF public.is_super_admin(v_uid) THEN
    RETURN;
  END IF;
  IF NOT public.has_permission(v_uid, _module, _action) THEN
    RAISE EXCEPTION 'permission denied: %.%', _module, _action
      USING ERRCODE = '42501';
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforce_review_approval_block()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _et text; _res jsonb;
BEGIN
  IF NEW.action_type IS NULL OR NEW.action_type NOT IN ('approve','escalate') THEN
    RETURN NEW;
  END IF;
  IF NEW.entity_type IS NULL OR NEW.entity_id IS NULL OR NEW.step_id IS NULL THEN
    RETURN NEW;
  END IF;
  _et := CASE WHEN NEW.entity_type = 'pre_application' THEN 'application' ELSE NEW.entity_type END;
  _res := public.check_approval_blocked(_et, NEW.entity_id, NEW.step_id);
  IF (_res->>'blocked')::boolean THEN
    RAISE EXCEPTION 'REVIEW_BLOCKED:%', (_res->>'count')::int USING ERRCODE='P0001';
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.enforce_scoped_permission(_module text, _action text, _holder uuid DEFAULT NULL::uuid, _sector uuid DEFAULT NULL::uuid, _region uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication required for %.%', _module, _action
      USING ERRCODE = '42501';
  END IF;
  IF public.is_super_admin(v_uid) THEN
    RETURN;
  END IF;
  IF NOT public.has_scoped_permission(v_uid, _module, _action, _holder, _sector, _region) THEN
    RAISE EXCEPTION 'permission denied: %.% (scope check failed)', _module, _action
      USING ERRCODE = '42501';
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforce_workflow_transition(_module text, _action text, _record_id uuid, _submitter_id uuid DEFAULT NULL::uuid, _from_state text DEFAULT NULL::text, _to_state text DEFAULT NULL::text, _meta jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _override boolean := false;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF _module IS NULL OR btrim(_module) = '' OR _action IS NULL OR btrim(_action) = '' THEN
    RAISE EXCEPTION 'module and action are required' USING ERRCODE = '22023';
  END IF;

  PERFORM public.enforce_permission(_module, _action);

  IF _submitter_id IS NOT NULL
     AND _submitter_id = _uid
     AND _action IN ('approve', 'reject', 'close', 'issue', 'revoke', 'suspend') THEN
    SELECT public.has_permission(_uid, _module, 'override_workflow')
      INTO _override;
    IF COALESCE(_override, false) IS NOT TRUE THEN
      RAISE EXCEPTION
        'segregation of duties: actor cannot % their own submission on %', _action, _module
        USING ERRCODE = '42501';
    END IF;
  END IF;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (
    _uid,
    'workflow.' || _module || '.' || _action,
    _module,
    _record_id::text,
    COALESCE(_meta, '{}'::jsonb)
      || jsonb_build_object(
        'from_state', _from_state,
        'to_state',   _to_state,
        'submitter',  _submitter_id
      )
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforcement_action_create(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _id uuid; _after jsonb;
BEGIN
  _uid := public.conduct_require('enforcement_management','create');
  IF coalesce(length(btrim(_payload->>'case_number')),0) = 0 THEN
    RAISE EXCEPTION 'Case number is required' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.enforcement_actions (
    entity_id, case_number, enforcement_type, date_opened, status,
    penalty_amount, description, source_type, opened_by
  ) VALUES (
    nullif(_payload->>'entity_id','')::uuid,
    btrim(_payload->>'case_number'),
    coalesce(nullif(_payload->>'enforcement_type',''),'Warning'),
    coalesce(nullif(_payload->>'date_opened','')::date, current_date),
    coalesce(nullif(_payload->>'status',''),'open'),
    coalesce((_payload->>'penalty_amount')::numeric,0),
    nullif(btrim(coalesce(_payload->>'description','')),''),
    coalesce(nullif(_payload->>'source_type',''),'manual'),
    _uid
  ) RETURNING id INTO _id;
  SELECT to_jsonb(e) INTO _after FROM public.enforcement_actions e WHERE e.id=_id;
  PERFORM public.log_compliance_audit('CREATE','enforcement_action',_id,NULL,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.enforcement_action_delete(_action_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb;
BEGIN
  _uid := public.conduct_require('enforcement_management','delete');
  IF coalesce(length(btrim(_reason)),0) < 10 THEN
    RAISE EXCEPTION 'Deletion reason required (min 10 characters)' USING ERRCODE='22023';
  END IF;
  SELECT to_jsonb(e) INTO _before FROM public.enforcement_actions e WHERE e.id=_action_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Enforcement action not found' USING ERRCODE='P0002'; END IF;
  DELETE FROM public.enforcement_actions WHERE id=_action_id;
  PERFORM public.log_compliance_audit('DELETE','enforcement_action',_action_id,_before,NULL,btrim(_reason));
END; $function$
;
CREATE OR REPLACE FUNCTION public.enforcement_action_update(_action_id uuid, _patch jsonb, _rationale text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb; _closing boolean;
BEGIN
  _uid := public.conduct_require('enforcement_management','edit');
  SELECT to_jsonb(e) INTO _before FROM public.enforcement_actions e WHERE e.id=_action_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Enforcement action not found' USING ERRCODE='P0002'; END IF;
  _closing := (_patch->>'status') = 'closed' AND coalesce(_before->>'status','') <> 'closed';
  IF _closing AND coalesce(length(btrim(_rationale)),0) < 10 THEN
    RAISE EXCEPTION 'Closure rationale required (min 10 characters)' USING ERRCODE='22023';
  END IF;
  UPDATE public.enforcement_actions SET
    case_number = coalesce(nullif(_patch->>'case_number',''), case_number),
    enforcement_type = coalesce(nullif(_patch->>'enforcement_type',''), enforcement_type),
    date_opened = coalesce(nullif(_patch->>'date_opened','')::date, date_opened),
    status = coalesce(nullif(_patch->>'status',''), status),
    penalty_amount = coalesce((_patch->>'penalty_amount')::numeric, penalty_amount),
    description = CASE WHEN _patch ? 'description'
      THEN nullif(btrim(coalesce(_patch->>'description','')),'') ELSE description END,
    closed_by = CASE WHEN _closing THEN _uid ELSE closed_by END,
    closed_at = CASE WHEN _closing THEN now() ELSE closed_at END,
    updated_at = now()
  WHERE id=_action_id RETURNING to_jsonb(enforcement_actions) INTO _after;
  PERFORM public.log_compliance_audit(
    CASE WHEN _closing THEN 'APPROVE' ELSE 'UPDATE' END,
    'enforcement_action',_action_id,_before,_after,_rationale);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.enforcement_case(_case_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'case', to_jsonb(c) - 'id' || jsonb_build_object('id', c.id,
              'canonical_href', '/enforcement/' || c.id,
              'entity_href', CASE WHEN c.entity_id IS NOT NULL THEN '/entities/' || c.entity_id END,
              'source_href', public.enforcement_source_href(c.source_kind, c.source_id)),
    'blockers', public.enforcement_case_blockers(c.id),
    'stage_model', (SELECT coalesce(jsonb_agg(jsonb_build_object(
                       'stage', s.stage, 'label', s.label, 'seq', s.seq,
                       'is_terminal', s.is_terminal, 'description', s.description,
                       'waiting_on', s.waiting_on, 'sla_days', s.sla_days)
                     ORDER BY s.seq), '[]'::jsonb)
                    FROM enforcement_workflow_stages s WHERE s.version = 1 AND s.is_active),
    'available_actions', (SELECT coalesce(jsonb_agg(jsonb_build_object(
                             'action_code', t.action_code, 'label', t.label,
                             'to_stage', t.to_stage, 'description', t.description,
                             'permission_action', t.permission_action,
                             'requires_rationale', t.requires_rationale,
                             'min_rationale_length', t.min_rationale_length,
                             'requires_evidence', t.requires_evidence,
                             'requires_maker_checker', t.requires_maker_checker,
                             'advances_stage', t.to_stage <> t.from_stage,
                             'permitted', public.has_permission(auth.uid(), 'enforcement_management', t.permission_action))
                           ORDER BY t.seq), '[]'::jsonb)
                          FROM enforcement_workflow_transitions t
                         WHERE t.version = 1 AND t.is_active AND t.from_stage = c.stage),
    'obligations', (SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.created_at), '[]'::jsonb)
                     FROM enforcement_obligations o WHERE o.case_id = c.id),
    'representations', (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.received_at DESC), '[]'::jsonb)
                     FROM enforcement_representations r WHERE r.case_id = c.id),
    'appeals', (SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.lodged_at DESC), '[]'::jsonb)
                     FROM enforcement_appeals a WHERE a.case_id = c.id),
    'payments', (SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.paid_on DESC), '[]'::jsonb)
                     FROM enforcement_penalty_payments p WHERE p.case_id = c.id),
    'timeline', (SELECT coalesce(jsonb_agg(jsonb_build_object(
                     'id', e.id, 'event_type', e.event_type, 'actor_id', e.actor_id,
                     'actor_name', coalesce(pf.full_name, pf.email), 'note', e.note,
                     'detail', e.detail, 'created_at', e.created_at)
                   ORDER BY e.created_at DESC), '[]'::jsonb)
                  FROM enforcement_case_events e LEFT JOIN profiles pf ON pf.id = e.actor_id
                 WHERE e.case_id = c.id)
  )
  FROM v_enforcement_case_state c WHERE c.id = _case_id;
$function$
;
CREATE OR REPLACE FUNCTION public.enforcement_case_action(_case_id uuid, _action text, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_case enforcement_actions;
  v_t enforcement_workflow_transitions;
  v_rationale text := nullif(btrim(_payload->>'rationale'), '');
  v_before jsonb;
  v_child uuid;
  v_amount numeric;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_case FROM enforcement_actions WHERE id = _case_id FOR UPDATE;
  IF v_case.id IS NULL THEN
    RAISE EXCEPTION 'Enforcement case not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.can_read_enforcement(v_uid, v_case.entity_id) THEN
    RAISE EXCEPTION 'You are not authorised for this enforcement case' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_t FROM enforcement_workflow_transitions
   WHERE version = 1 AND is_active AND action_code = upper(_action) AND from_stage = v_case.stage;
  IF v_t.id IS NULL THEN
    RAISE EXCEPTION 'Action % is not available at stage %', _action, v_case.stage USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission(v_uid, 'enforcement_management', v_t.permission_action) THEN
    RAISE EXCEPTION 'You do not hold the % authority required for this action', v_t.permission_action
      USING ERRCODE = '42501';
  END IF;

  IF v_t.requires_rationale AND (v_rationale IS NULL OR length(v_rationale) < v_t.min_rationale_length) THEN
    RAISE EXCEPTION 'A rationale of at least % characters is required', v_t.min_rationale_length
      USING ERRCODE = '22023';
  END IF;

  -- maker/checker: the decision maker may not be the officer who proposed the case stage
  IF v_t.requires_maker_checker AND v_uid IN (
       coalesce(v_case.referred_by, '00000000-0000-0000-0000-000000000000'::uuid),
       coalesce(v_case.opened_by,   '00000000-0000-0000-0000-000000000000'::uuid)
     ) THEN
    RAISE EXCEPTION 'Maker/checker separation: the referring officer cannot take this decision'
      USING ERRCODE = '42501';
  END IF;

  v_before := to_jsonb(v_case);

  -- action specific prerequisites and record keeping
  IF upper(_action) = 'ISSUE_NOTICE' THEN
    IF nullif(btrim(_payload->>'notice_reference'), '') IS NULL THEN
      RAISE EXCEPTION 'A notice reference is required to issue an enforcement notice' USING ERRCODE = '22023';
    END IF;
    IF v_case.legal_basis IS NULL AND nullif(btrim(_payload->>'legal_basis'), '') IS NULL THEN
      RAISE EXCEPTION 'The legal basis must be recorded before a notice can be issued' USING ERRCODE = '22023';
    END IF;
    IF v_t.requires_evidence AND v_case.findings IS NULL
       AND nullif(btrim(_payload->>'findings'), '') IS NULL THEN
      RAISE EXCEPTION 'Assessment findings must be recorded before a notice can be issued' USING ERRCODE = '22023';
    END IF;
    UPDATE enforcement_actions SET
      notice_issued_at = now(),
      notice_reference = _payload->>'notice_reference',
      notice_recipient = nullif(btrim(_payload->>'notice_recipient'), ''),
      notice_dispatch_method = nullif(btrim(_payload->>'notice_dispatch_method'), ''),
      representation_deadline = coalesce(nullif(_payload->>'representation_deadline','')::date,
                                        (CURRENT_DATE + 21)),
      legal_basis = coalesce(nullif(btrim(_payload->>'legal_basis'), ''), legal_basis),
      findings = coalesce(nullif(btrim(_payload->>'findings'), ''), findings)
     WHERE id = _case_id;

  ELSIF upper(_action) = 'BEGIN_ASSESSMENT' THEN
    UPDATE enforcement_actions SET
      findings = coalesce(nullif(btrim(_payload->>'findings'), ''), findings),
      legal_basis = coalesce(nullif(btrim(_payload->>'legal_basis'), ''), legal_basis),
      severity = coalesce(nullif(btrim(_payload->>'severity'), ''), severity)
     WHERE id = _case_id;

  ELSIF upper(_action) = 'RECORD_REPRESENTATION' THEN
    INSERT INTO enforcement_representations (case_id, received_from, channel, summary,
                                             attachment_reference, recorded_by)
    VALUES (_case_id, nullif(btrim(_payload->>'received_from'), ''),
            nullif(btrim(_payload->>'channel'), ''), v_rationale,
            nullif(btrim(_payload->>'attachment_reference'), ''), v_uid)
    RETURNING id INTO v_child;
    UPDATE enforcement_actions SET
      response_received_at = coalesce(response_received_at, now()),
      response_summary = v_rationale
     WHERE id = _case_id;

  ELSIF upper(_action) = 'COMPLETE_EVIDENCE_REVIEW' THEN
    UPDATE enforcement_actions SET
      representations_closed_at = now(), evidence_review_at = now(), evidence_review_note = v_rationale
     WHERE id = _case_id;

  ELSIF upper(_action) IN ('MAKE_DECISION','CLOSE_NO_ACTION') THEN
    IF nullif(btrim(_payload->>'decision_outcome'), '') IS NULL THEN
      RAISE EXCEPTION 'A decision outcome is required' USING ERRCODE = '22023';
    END IF;
    UPDATE enforcement_actions SET
      decision_at = now(),
      decision_outcome = _payload->>'decision_outcome',
      decision_rationale = v_rationale,
      decision_authority = v_uid,
      legal_basis = coalesce(nullif(btrim(_payload->>'legal_basis'), ''), legal_basis),
      closed_at = CASE WHEN upper(_action) = 'CLOSE_NO_ACTION' THEN now() ELSE closed_at END,
      closed_by = CASE WHEN upper(_action) = 'CLOSE_NO_ACTION' THEN v_uid ELSE closed_by END,
      closure_rationale = CASE WHEN upper(_action) = 'CLOSE_NO_ACTION' THEN v_rationale ELSE closure_rationale END
     WHERE id = _case_id;

  ELSIF upper(_action) IN ('IMPOSE_SANCTION','ISSUE_DIRECTIVE') THEN
    IF v_case.decision_at IS NULL THEN
      RAISE EXCEPTION 'A sanction can only follow a recorded enforcement decision' USING ERRCODE = '22023';
    END IF;
    v_amount := coalesce(nullif(_payload->>'penalty_amount','')::numeric, 0);
    IF v_amount < 0 THEN
      RAISE EXCEPTION 'A monetary penalty cannot be negative' USING ERRCODE = '22023';
    END IF;
    UPDATE enforcement_actions SET
      sanction_imposed_at = now(),
      sanction_type = coalesce(nullif(btrim(_payload->>'sanction_type'), ''),
                               CASE WHEN upper(_action) = 'ISSUE_DIRECTIVE' THEN 'directive' ELSE sanction_type END),
      sanction_detail = coalesce(nullif(btrim(_payload->>'sanction_detail'), ''), v_rationale),
      directive_detail = CASE WHEN upper(_action) = 'ISSUE_DIRECTIVE'
                              THEN coalesce(nullif(btrim(_payload->>'directive_detail'), ''), v_rationale)
                              ELSE directive_detail END,
      penalty_amount = CASE WHEN v_amount > 0 THEN v_amount ELSE penalty_amount END,
      penalty_currency = coalesce(nullif(btrim(_payload->>'penalty_currency'), ''), penalty_currency),
      effective_date = coalesce(nullif(_payload->>'effective_date','')::date, CURRENT_DATE),
      appeal_deadline = coalesce(nullif(_payload->>'appeal_deadline','')::date, CURRENT_DATE + 30),
      monitoring_state = 'monitoring'
     WHERE id = _case_id;

  ELSIF upper(_action) = 'RECORD_OBLIGATION' THEN
    INSERT INTO enforcement_obligations (case_id, obligation, detail, deadline, status, created_by)
    VALUES (_case_id, coalesce(nullif(btrim(_payload->>'obligation'), ''), v_rationale),
            nullif(btrim(_payload->>'detail'), ''),
            nullif(_payload->>'deadline','')::date, 'outstanding', v_uid)
    RETURNING id INTO v_child;

  ELSIF upper(_action) = 'REVIEW_REMEDIATION' THEN
    UPDATE enforcement_actions SET
      non_compliance_flag = coalesce((_payload->>'non_compliant')::boolean, false),
      non_compliance_note = CASE WHEN coalesce((_payload->>'non_compliant')::boolean, false)
                                 THEN v_rationale ELSE non_compliance_note END,
      monitoring_state = CASE WHEN coalesce((_payload->>'non_compliant')::boolean, false)
                              THEN 'non_compliant' ELSE 'monitoring' END
     WHERE id = _case_id;

  ELSIF upper(_action) = 'RECORD_PAYMENT' THEN
    v_amount := coalesce(nullif(_payload->>'amount','')::numeric, 0);
    IF v_amount <= 0 THEN
      RAISE EXCEPTION 'A payment amount greater than zero is required' USING ERRCODE = '22023';
    END IF;
    IF lower(coalesce(_payload->>'kind','payment')) = 'waiver'
       AND NOT public.has_permission(v_uid, 'enforcement_management', 'decide') THEN
      RAISE EXCEPTION 'Only an enforcement decision maker can waive a penalty' USING ERRCODE = '42501';
    END IF;
    IF coalesce(v_case.penalty_amount, 0) = 0 THEN
      RAISE EXCEPTION 'This case has no monetary penalty to settle' USING ERRCODE = '22023';
    END IF;
    IF coalesce(v_case.penalty_paid_amount,0) + coalesce(v_case.penalty_waived_amount,0) + v_amount
       > coalesce(v_case.penalty_amount,0) THEN
      RAISE EXCEPTION 'Recorded settlement cannot exceed the imposed penalty' USING ERRCODE = '22023';
    END IF;
    INSERT INTO enforcement_penalty_payments (case_id, amount, currency, payment_reference, paid_on, kind, note, recorded_by)
    VALUES (_case_id, v_amount, coalesce(nullif(btrim(_payload->>'currency'),''), coalesce(v_case.penalty_currency,'USD')),
            nullif(btrim(_payload->>'payment_reference'), ''),
            coalesce(nullif(_payload->>'paid_on','')::date, CURRENT_DATE),
            lower(coalesce(_payload->>'kind','payment')), v_rationale, v_uid)
    RETURNING id INTO v_child;
    UPDATE enforcement_actions SET
      penalty_paid_amount = coalesce(penalty_paid_amount,0)
        + CASE WHEN lower(coalesce(_payload->>'kind','payment')) = 'payment' THEN v_amount ELSE 0 END,
      penalty_waived_amount = coalesce(penalty_waived_amount,0)
        + CASE WHEN lower(coalesce(_payload->>'kind','payment')) = 'waiver' THEN v_amount ELSE 0 END
     WHERE id = _case_id;

  ELSIF upper(_action) = 'LODGE_APPEAL' THEN
    INSERT INTO enforcement_appeals (case_id, appellant, grounds, review_body, lodged_by,
                                     lodged_at, status)
    VALUES (_case_id, nullif(btrim(_payload->>'appellant'), ''), v_rationale,
            nullif(btrim(_payload->>'review_body'), ''), v_uid,
            coalesce(nullif(_payload->>'lodged_at','')::timestamptz, now()), 'lodged')
    RETURNING id INTO v_child;

  ELSIF upper(_action) = 'DECIDE_APPEAL' THEN
    IF nullif(btrim(_payload->>'appeal_decision'), '') IS NULL THEN
      RAISE EXCEPTION 'An appeal decision is required' USING ERRCODE = '22023';
    END IF;
    UPDATE enforcement_appeals SET
      status = 'decided', decision = _payload->>'appeal_decision',
      decision_rationale = v_rationale, decision_at = now(), decided_by = v_uid,
      effect_on_action = nullif(btrim(_payload->>'effect_on_action'), '')
     WHERE case_id = _case_id AND status = 'lodged';

  ELSIF upper(_action) = 'CLOSE' THEN
    IF EXISTS (SELECT 1 FROM enforcement_obligations o
                WHERE o.case_id = _case_id AND o.status NOT IN ('complied','waived')) THEN
      RAISE EXCEPTION 'All compliance obligations must be discharged or waived before closure' USING ERRCODE = '22023';
    END IF;
    IF coalesce(v_case.penalty_amount,0) >
       coalesce(v_case.penalty_paid_amount,0) + coalesce(v_case.penalty_waived_amount,0) THEN
      RAISE EXCEPTION 'The monetary penalty is not fully settled or waived' USING ERRCODE = '22023';
    END IF;
    UPDATE enforcement_actions SET
      closed_at = now(), closed_by = v_uid, closure_rationale = v_rationale,
      resolution_date = CURRENT_DATE, monitoring_state = 'closed'
     WHERE id = _case_id;

  ELSIF upper(_action) = 'WITHDRAW' THEN
    UPDATE enforcement_actions SET
      withdrawn_at = now(), withdrawal_reason = v_rationale, closed_at = now(), closed_by = v_uid
     WHERE id = _case_id;
  END IF;

  -- governed stage/status advance
  UPDATE enforcement_actions SET
    stage = v_t.to_stage,
    status = coalesce(v_t.to_status, status),
    updated_at = now()
   WHERE id = _case_id;

  INSERT INTO enforcement_case_events (case_id, event_type, actor_id, note, detail)
  VALUES (_case_id, upper(_action), v_uid, v_rationale,
          jsonb_build_object('from_stage', v_case.stage, 'to_stage', v_t.to_stage,
                             'child_id', v_child, 'payload', _payload - 'rationale'));

  PERFORM public.log_compliance_audit_as_actor(
    v_uid, 'WORKFLOW_TRANSITION'::compliance_audit_action, 'enforcement_actions', _case_id::text,
    v_before, (SELECT to_jsonb(e) FROM enforcement_actions e WHERE e.id = _case_id),
    v_rationale, NULL, NULL, NULL,
    jsonb_build_object('process', 'P11', 'action', upper(_action),
                       'from_stage', v_case.stage, 'to_stage', v_t.to_stage));

  RETURN jsonb_build_object('case_id', _case_id, 'action', upper(_action),
                            'from_stage', v_case.stage, 'to_stage', v_t.to_stage);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforcement_case_blockers(_case_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(jsonb_agg(b), '[]'::jsonb) FROM (
    SELECT jsonb_build_object('code','ASSESSMENT_FINDINGS','label','Record the assessment findings') AS b
      FROM v_enforcement_case_state c WHERE c.id = _case_id AND c.stage = 'ASSESSMENT' AND c.findings IS NULL
    UNION ALL
    SELECT jsonb_build_object('code','LEGAL_BASIS','label','Record the legal basis for enforcement')
      FROM v_enforcement_case_state c WHERE c.id = _case_id AND c.stage IN ('ASSESSMENT','NOTICE') AND c.legal_basis IS NULL
    UNION ALL
    SELECT jsonb_build_object('code','NO_DECISION','label','An enforcement decision must be recorded before a sanction')
      FROM v_enforcement_case_state c WHERE c.id = _case_id AND c.stage = 'SANCTION' AND c.decision_at IS NULL
    UNION ALL
    SELECT jsonb_build_object('code','OPEN_OBLIGATIONS',
             'label', c.open_obligations || ' compliance obligation(s) remain open')
      FROM v_enforcement_case_state c WHERE c.id = _case_id AND c.stage = 'REMEDIATION_MONITORING' AND c.open_obligations > 0
    UNION ALL
    SELECT jsonb_build_object('code','PENALTY_UNSETTLED','label','The monetary penalty is not fully settled or waived')
      FROM v_enforcement_case_state c WHERE c.id = _case_id AND c.stage = 'REMEDIATION_MONITORING'
       AND coalesce(c.penalty_amount,0) > coalesce(c.penalty_paid_amount,0) + coalesce(c.penalty_waived_amount,0)
    UNION ALL
    SELECT jsonb_build_object('code','OPEN_APPEAL','label','An appeal is pending decision')
      FROM v_enforcement_case_state c WHERE c.id = _case_id AND c.stage = 'APPEAL' AND c.open_appeals > 0
  ) x;
$function$
;
CREATE OR REPLACE FUNCTION public.enforcement_entity_summary(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'open_cases', count(*) FILTER (WHERE NOT coalesce(is_terminal,false)),
    'closed_cases', count(*) FILTER (WHERE coalesce(is_terminal,false)),
    'breached_sla', count(*) FILTER (WHERE sla_state = 'breached' AND NOT coalesce(is_terminal,false)),
    'penalty_imposed', coalesce(sum(coalesce(penalty_amount,0)), 0),
    'penalty_outstanding', coalesce(sum(greatest(coalesce(penalty_amount,0)
        - coalesce(penalty_paid_amount,0) - coalesce(penalty_waived_amount,0), 0)), 0),
    'open_obligations', coalesce(sum(open_obligations) FILTER (WHERE NOT coalesce(is_terminal,false)), 0),
    'cases', coalesce(jsonb_agg(jsonb_build_object(
        'case_id', id, 'case_number', case_number, 'stage', stage, 'stage_label', stage_label,
        'status', status, 'source_kind', source_kind, 'source_reference', source_reference,
        'severity', severity, 'sla_state', sla_state, 'sla_due_at', sla_due_at,
        'penalty_amount', penalty_amount, 'penalty_currency', penalty_currency,
        'decision_outcome', decision_outcome, 'closed_at', closed_at,
        'canonical_href', '/enforcement/' || id)
      ORDER BY coalesce(is_terminal,false), stage_seq, created_at DESC), '[]'::jsonb)
  ) FROM v_enforcement_case_state WHERE entity_id = _entity_id;
$function$
;
CREATE OR REPLACE FUNCTION public.enforcement_lifecycle_action(_case_id uuid, _action text, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_case public.enforcement_actions;
  v_note text := NULLIF(btrim(COALESCE(_payload->>'note','')),'');
BEGIN
  SELECT * INTO v_case FROM public.enforcement_actions WHERE id = _case_id;
  IF v_case.id IS NULL THEN
    RAISE EXCEPTION 'enforcement case not found' USING ERRCODE = 'P0002';
  END IF;

  IF _action IN ('approve','reject') THEN
    IF NOT public.can_act_on_enforcement(auth.uid(),'approve') THEN
      RAISE EXCEPTION 'enforcement approval permission required' USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT public.can_act_on_enforcement(auth.uid(),'edit') THEN
      RAISE EXCEPTION 'enforcement edit permission required' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF _action = 'propose' THEN
    IF COALESCE(btrim(_payload->>'proposed_action'),'') = ''
       OR COALESCE(length(btrim(_payload->>'proposal_rationale')),0) < 10 THEN
      RAISE EXCEPTION 'proposed action and a rationale of at least 10 characters are required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.enforcement_actions
       SET proposed_action = _payload->>'proposed_action',
           proposal_rationale = _payload->>'proposal_rationale',
           proposed_by = auth.uid(), proposed_at = now(),
           review_state = 'pending_review', updated_at = now()
     WHERE id = _case_id;
  ELSIF _action = 'review' THEN
    UPDATE public.enforcement_actions
       SET review_state = 'reviewed', reviewed_by = auth.uid(), reviewed_at = now(),
           review_notes = v_note, updated_at = now()
     WHERE id = _case_id AND review_state = 'pending_review';
  ELSIF _action = 'approve' THEN
    IF v_case.review_state NOT IN ('reviewed','pending_review') THEN
      RAISE EXCEPTION 'case must be proposed and reviewed before approval' USING ERRCODE = '22023';
    END IF;
    UPDATE public.enforcement_actions
       SET review_state = 'approved', approved_by = auth.uid(), approved_at = now(),
           approval_notes = v_note, updated_at = now()
     WHERE id = _case_id;
  ELSIF _action = 'reject' THEN
    IF COALESCE(length(v_note),0) < 10 THEN
      RAISE EXCEPTION 'rejection reason of at least 10 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.enforcement_actions
       SET review_state = 'rejected', reviewed_by = auth.uid(), reviewed_at = now(),
           review_notes = v_note, updated_at = now()
     WHERE id = _case_id;
  ELSIF _action = 'issue' THEN
    IF v_case.review_state <> 'approved' THEN
      RAISE EXCEPTION 'case must be approved before issuance' USING ERRCODE = '22023';
    END IF;
    UPDATE public.enforcement_actions
       SET review_state = 'issued', status = 'active',
           effective_date = COALESCE((_payload->>'effective_date')::date, CURRENT_DATE),
           notice_issued_at = now(), monitoring_state = 'monitoring', updated_at = now()
     WHERE id = _case_id;
  ELSIF _action = 'monitor' THEN
    UPDATE public.enforcement_actions
       SET monitoring_state = COALESCE(NULLIF(_payload->>'monitoring_state',''),'monitoring'),
           updated_at = now()
     WHERE id = _case_id;
  ELSIF _action = 'flag_non_compliance' THEN
    IF COALESCE(length(v_note),0) < 10 THEN
      RAISE EXCEPTION 'non-compliance note of at least 10 characters is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.enforcement_actions
       SET non_compliance_flag = true, non_compliance_note = v_note,
           monitoring_state = 'non_compliant', updated_at = now()
     WHERE id = _case_id;
  ELSIF _action = 'close' THEN
    IF COALESCE(btrim(_payload->>'outcome'),'') = ''
       OR COALESCE(length(btrim(_payload->>'rationale')),0) < 10 THEN
      RAISE EXCEPTION 'outcome and a rationale of at least 10 characters are required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.enforcement_actions
       SET status = 'closed', review_state = 'closed',
           decision_outcome = _payload->>'outcome',
           decision_rationale = _payload->>'rationale',
           decision_at = now(), closed_at = now(), closed_by = auth.uid(),
           monitoring_state = 'closed', updated_at = now()
     WHERE id = _case_id;
  ELSE
    RAISE EXCEPTION 'unknown enforcement action %', _action USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.enforcement_case_events(case_id, event_type, actor_id, note, detail)
  VALUES (_case_id, 'lifecycle_' || _action, auth.uid(), v_note, _payload);

  SELECT * INTO v_case FROM public.enforcement_actions WHERE id = _case_id;
  RETURN jsonb_build_object('id', v_case.id, 'review_state', v_case.review_state,
    'status', v_case.status, 'monitoring_state', v_case.monitoring_state);
END $function$
;
CREATE OR REPLACE FUNCTION public.enforcement_next_case_number()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year integer := extract(year FROM now())::int;
  v_next integer;
BEGIN
  -- One atomic upsert: the row lock serialises concurrent allocation, so no two
  -- referrals get the same reference and no valid referral fails on a race.
  INSERT INTO public.enforcement_case_number_counters AS c (year, last_value)
  VALUES (v_year, 1)
  ON CONFLICT (year) DO UPDATE SET last_value = c.last_value + 1, updated_at = now()
  RETURNING c.last_value INTO v_next;

  RETURN 'ENF-' || v_year::text || '-' || lpad(v_next::text, 5, '0');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforcement_obligation_add(_case_id uuid, _obligation text, _detail text DEFAULT NULL::text, _deadline date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _id uuid; _after jsonb;
BEGIN
  _uid := public.conduct_require('enforcement_management','edit');
  IF coalesce(length(btrim(_obligation)),0) < 3 THEN
    RAISE EXCEPTION 'Obligation description is required' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.enforcement_actions WHERE id=_case_id) THEN
    RAISE EXCEPTION 'Enforcement case not found' USING ERRCODE='P0002';
  END IF;
  INSERT INTO public.enforcement_obligations (case_id, obligation, detail, deadline, created_by)
  VALUES (_case_id, btrim(_obligation), nullif(btrim(coalesce(_detail,'')),''), _deadline, _uid)
  RETURNING id INTO _id;
  SELECT to_jsonb(o) INTO _after FROM public.enforcement_obligations o WHERE o.id=_id;
  PERFORM public.log_compliance_audit('CREATE','enforcement_obligation',_id,NULL,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.enforcement_obligation_set_status(_obligation_id uuid, _status text, _breach_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _case public.enforcement_actions;
  _before jsonb;
  _after jsonb;
BEGIN
  IF _status NOT IN ('outstanding','in_progress','complied','breached','waived') THEN
    RAISE EXCEPTION 'Unsupported obligation status: %', _status USING ERRCODE='22023';
  END IF;
  IF _status = 'breached' AND coalesce(length(btrim(_breach_note)),0) < 5 THEN
    RAISE EXCEPTION 'Breach note required (min 5 characters)' USING ERRCODE='22023';
  END IF;

  SELECT ea.* INTO _case
  FROM public.enforcement_actions ea
  JOIN public.enforcement_obligations o ON o.case_id = ea.id
  WHERE o.id = _obligation_id;
  IF _case.id IS NULL THEN
    RAISE EXCEPTION 'Obligation not found' USING ERRCODE='22023';
  END IF;
  IF NOT public.can_read_enforcement(_uid, _case.entity_id)
     OR NOT public.has_permission(_uid, 'enforcement_management', 'workflow_action') THEN
    RAISE EXCEPTION 'You are not authorised for this enforcement case' USING ERRCODE='42501';
  END IF;
  IF _status = 'waived' AND NOT public.has_permission(_uid, 'enforcement_management', 'decide') THEN
    RAISE EXCEPTION 'Only an enforcement decision maker can waive an obligation' USING ERRCODE='42501';
  END IF;

  SELECT to_jsonb(o) INTO _before FROM public.enforcement_obligations o WHERE o.id=_obligation_id;
  UPDATE public.enforcement_obligations SET
    status = _status,
    breach_note = CASE WHEN _status='breached' THEN btrim(_breach_note) ELSE breach_note END,
    completed_at = CASE WHEN _status='complied' THEN now() ELSE NULL END,
    completed_by = CASE WHEN _status='complied' THEN _uid ELSE NULL END,
    updated_at = now()
  WHERE id=_obligation_id RETURNING to_jsonb(enforcement_obligations) INTO _after;

  PERFORM public.log_compliance_audit('UPDATE','enforcement_obligation',_obligation_id,_before,_after,_breach_note);
  RETURN _after;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforcement_referral_create(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_kind text := upper(nullif(btrim(_payload->>'source_kind'), ''));
  v_src uuid := nullif(_payload->>'source_id','')::uuid;
  v_reason text := nullif(btrim(_payload->>'referral_reason'), '');
  v_resolved jsonb;
  v_entity uuid;
  v_case uuid;
  v_number text;
  v_domain text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF v_reason IS NULL OR length(v_reason) < 20 THEN
    RAISE EXCEPTION 'A referral reason of at least 20 characters is required' USING ERRCODE = '22023';
  END IF;

  v_resolved := public.enforcement_resolve_source(v_kind, v_src);
  v_entity := (v_resolved->>'entity_id')::uuid;
  v_domain := v_resolved->>'domain';

  IF NOT (
    public.has_permission(v_uid, 'enforcement_management', 'refer')
    OR public.has_permission(v_uid, 'enforcement_management', 'create')
    OR public.has_permission(v_uid, v_domain, 'workflow_action')
    OR public.has_permission(v_uid, v_domain, 'approve')
  ) THEN
    RAISE EXCEPTION 'You are not authorised to refer this matter to Enforcement' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (SELECT 1 FROM enforcement_actions ea
              WHERE ea.source_kind = v_kind AND ea.source_id = v_src
                AND ea.stage NOT IN ('CLOSED','WITHDRAWN')) THEN
    RAISE EXCEPTION 'An open enforcement case already exists for this source record' USING ERRCODE = '23505';
  END IF;

  v_number := public.enforcement_next_case_number();

  INSERT INTO enforcement_actions (
    entity_id, case_number, enforcement_type, date_opened, status, stage,
    source_kind, source_id, source_reference, referred_by, referred_at, referral_reason,
    legal_basis, description, severity, assigned_to, assigned_team, opened_by, review_state
  ) VALUES (
    v_entity, v_number,
    coalesce(nullif(btrim(_payload->>'enforcement_type'), ''), 'regulatory_action'),
    CURRENT_DATE, 'referred', 'REFERRAL',
    v_kind, v_src, v_resolved->>'reference', v_uid, now(), v_reason,
    nullif(btrim(_payload->>'legal_basis'), ''),
    coalesce(nullif(btrim(_payload->>'description'), ''), v_resolved->>'title'),
    coalesce(nullif(btrim(_payload->>'severity'), ''), 'medium'),
    nullif(_payload->>'assigned_to','')::uuid,
    nullif(btrim(_payload->>'assigned_team'), ''),
    v_uid, 'proposed'
  ) RETURNING id INTO v_case;

  INSERT INTO enforcement_case_events (case_id, event_type, actor_id, note, detail)
  VALUES (v_case, 'REFERRAL_RECEIVED', v_uid, v_reason,
          jsonb_build_object('source_kind', v_kind, 'source_id', v_src,
                             'source_reference', v_resolved->>'reference',
                             'source_href', v_resolved->>'href', 'to_stage', 'REFERRAL'));

  PERFORM public.log_compliance_audit_as_actor(
    v_uid, 'CREATE'::compliance_audit_action, 'enforcement_actions', v_case::text,
    NULL, jsonb_build_object('case_number', v_number, 'stage', 'REFERRAL',
                             'source_kind', v_kind, 'source_id', v_src, 'entity_id', v_entity),
    v_reason, NULL, NULL, NULL, jsonb_build_object('process', 'P11', 'action', 'REFER'));

  RETURN v_case;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforcement_resolve_source(_kind text, _id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r jsonb;
BEGIN
  IF _kind IS NULL OR _id IS NULL THEN
    RAISE EXCEPTION 'Source kind and source record are both required' USING ERRCODE = '22023';
  END IF;

  CASE _kind
    WHEN 'COMPLAINT' THEN
      SELECT jsonb_build_object('entity_id', c.licensee_id, 'reference', c.complaint_number,
             'title', c.subject, 'href', '/complaints/' || c.id, 'domain', 'complaint_management')
        INTO r FROM complaints c WHERE c.id = _id;
    WHEN 'CONDUCT_INVESTIGATION' THEN
      SELECT jsonb_build_object('entity_id', i.licensee_id, 'reference', i.code,
             'title', i.allegation, 'href', '/conduct/investigations/' || i.id, 'domain', 'market_conduct')
        INTO r FROM conduct_investigations i WHERE i.id = _id;
    WHEN 'THEMATIC_FINDING' THEN
      SELECT jsonb_build_object('entity_id', f.licensee_id, 'reference', left(f.id::text, 8),
             'title', f.title, 'href', '/supervision/thematic-reviews/' || f.review_id, 'domain', 'market_conduct')
        INTO r FROM thematic_review_findings f WHERE f.id = _id;
    WHEN 'PRUDENTIAL_BREACH' THEN
      SELECT jsonb_build_object('entity_id', b.entity_id, 'reference', b.metric_key,
             'title', 'Threshold breach: ' || b.metric_key,
             'href', CASE WHEN b.return_filing_id IS NOT NULL
                          THEN '/returns/filings/' || b.return_filing_id ELSE '/supervision/breaches' END,
             'domain', 'prudential_supervision')
        INTO r FROM return_threshold_breaches b WHERE b.id = _id;
    WHEN 'PRUDENTIAL_ACTION' THEN
      SELECT jsonb_build_object('entity_id', a.entity_id, 'reference', a.action_reference,
             'title', a.title, 'href', '/prudential/actions', 'domain', 'prudential_supervision')
        INTO r FROM prudential_actions a WHERE a.id = _id;
    WHEN 'EXAMINATION_FINDING' THEN
      SELECT jsonb_build_object('entity_id', e.entity_id, 'reference', f.reference,
             'title', f.title, 'href', '/prudential/examinations/' || e.id, 'domain', 'prudential_supervision')
        INTO r FROM examination_findings f JOIN examinations e ON e.id = f.examination_id WHERE f.id = _id;
    WHEN 'LICENSING_VIOLATION' THEN
      SELECT jsonb_build_object('entity_id', ap.entity_id, 'reference', ap.application_number,
             'title', 'Licensing matter ' || ap.application_number,
             'href', '/applications/' || ap.id, 'domain', 'license_management')
        INTO r FROM applications ap WHERE ap.id = _id;
    WHEN 'FP_MATTER' THEN
      SELECT jsonb_build_object('entity_id', fa.licensee_id, 'reference', left(fa.id::text, 8),
             'title', 'Fit and proper matter', 'href', '/fpa/assessments/' || fa.id, 'domain', 'fit_and_proper')
        INTO r FROM fp_assessments fa WHERE fa.id = _id;
    WHEN 'MANUAL_REFERRAL' THEN
      SELECT jsonb_build_object('entity_id', l.id, 'reference', NULL::text,
             'title', 'Manual enforcement referral', 'href', '/entities/' || l.id,
             'domain', 'enforcement_management')
        INTO r FROM licensees l WHERE l.id = _id;
    ELSE
      RAISE EXCEPTION 'Unsupported enforcement source kind %', _kind USING ERRCODE = '22023';
  END CASE;

  IF r IS NULL THEN
    RAISE EXCEPTION 'Referred % record was not found', _kind USING ERRCODE = 'P0002';
  END IF;
  IF (r->>'entity_id') IS NULL THEN
    RAISE EXCEPTION 'Referred % record is not linked to a regulated entity', _kind USING ERRCODE = '22023';
  END IF;
  RETURN r;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforcement_source_href(_kind text, _id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE _kind
    WHEN 'COMPLAINT' THEN '/complaints/' || _id
    WHEN 'CONDUCT_INVESTIGATION' THEN '/conduct/investigations/' || _id
    WHEN 'THEMATIC_FINDING' THEN '/supervision/thematic-reviews'
    WHEN 'PRUDENTIAL_BREACH' THEN '/supervision/breaches'
    WHEN 'PRUDENTIAL_ACTION' THEN '/prudential/actions'
    WHEN 'EXAMINATION_FINDING' THEN '/prudential/examinations'
    WHEN 'LICENSING_VIOLATION' THEN '/applications/' || _id
    WHEN 'FP_MATTER' THEN '/fpa/assessments/' || _id
    ELSE NULL END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforcement_work_queue(_stages text[] DEFAULT NULL::text[], _source_kinds text[] DEFAULT NULL::text[], _sla_states text[] DEFAULT NULL::text[], _entity_id uuid DEFAULT NULL::uuid, _assigned_to uuid DEFAULT NULL::uuid, _search text DEFAULT NULL::text, _include_closed boolean DEFAULT false, _sort text DEFAULT 'sla'::text, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS TABLE(case_id uuid, case_number text, entity_id uuid, entity_name text, enforcement_type text, stage text, stage_label text, status text, source_kind text, source_reference text, source_href text, priority text, severity text, assigned_to uuid, assigned_to_name text, assigned_team text, sla_due_at timestamp with time zone, sla_state text, waiting_on text, next_action_code text, next_action_label text, blockers jsonb, penalty_amount numeric, penalty_currency text, open_obligations bigint, last_activity_at timestamp with time zone, canonical_href text, total_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH scoped AS (
    SELECT c.* FROM v_enforcement_case_state c
     WHERE (_include_closed OR NOT coalesce(c.is_terminal, false))
       AND (_stages IS NULL OR c.stage = ANY(_stages))
       AND (_source_kinds IS NULL OR c.source_kind = ANY(_source_kinds))
       AND (_sla_states IS NULL OR c.sla_state = ANY(_sla_states))
       AND (_entity_id IS NULL OR c.entity_id = _entity_id)
       AND (_assigned_to IS NULL OR c.assigned_to = _assigned_to)
       AND (_search IS NULL OR btrim(_search) = '' OR
            c.case_number ILIKE '%' || btrim(_search) || '%' OR
            coalesce(c.entity_name,'') ILIKE '%' || btrim(_search) || '%' OR
            coalesce(c.source_reference,'') ILIKE '%' || btrim(_search) || '%')
  ), counted AS (SELECT count(*) AS n FROM scoped)
  SELECT s.id, s.case_number, s.entity_id, s.entity_name, s.enforcement_type,
         s.stage, s.stage_label, s.status, s.source_kind, s.source_reference,
         public.enforcement_source_href(s.source_kind, s.source_id),
         s.priority, s.severity, s.assigned_to, s.assigned_to_name, s.assigned_team,
         s.sla_due_at, s.sla_state, s.waiting_on,
         t.action_code, t.label,
         public.enforcement_case_blockers(s.id),
         s.penalty_amount, s.penalty_currency, s.open_obligations,
         s.last_activity_at, '/enforcement/' || s.id, counted.n
    FROM scoped s
    CROSS JOIN counted
    LEFT JOIN LATERAL (
      SELECT wt.action_code, wt.label FROM enforcement_workflow_transitions wt
       WHERE wt.version = 1 AND wt.is_active AND wt.from_stage = s.stage AND wt.to_stage <> wt.from_stage
         AND wt.to_stage <> 'WITHDRAWN'
       ORDER BY wt.seq LIMIT 1
    ) t ON true
   ORDER BY
     CASE WHEN _sort = 'sla' THEN
       CASE s.sla_state WHEN 'breached' THEN 0 WHEN 'due_soon' THEN 1 WHEN 'on_track' THEN 2 ELSE 3 END
       ELSE NULL END NULLS LAST,
     CASE WHEN _sort = 'priority' THEN
       CASE s.priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END
       ELSE NULL END NULLS LAST,
     CASE WHEN _sort = 'stage' THEN s.stage_seq ELSE NULL END NULLS LAST,
     s.sla_due_at NULLS LAST, s.created_at DESC
   LIMIT greatest(1, least(coalesce(_limit,50), 200)) OFFSET greatest(0, coalesce(_offset,0));
$function$
;
CREATE OR REPLACE FUNCTION public.enforcement_work_queue_counts()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'total_open', count(*) FILTER (WHERE NOT coalesce(is_terminal,false)),
    'breached', count(*) FILTER (WHERE sla_state = 'breached' AND NOT coalesce(is_terminal,false)),
    'due_soon', count(*) FILTER (WHERE sla_state = 'due_soon' AND NOT coalesce(is_terminal,false)),
    'unassigned', count(*) FILTER (WHERE assigned_to IS NULL AND NOT coalesce(is_terminal,false)),
    'awaiting_entity', count(*) FILTER (WHERE waiting_on = 'entity' AND NOT coalesce(is_terminal,false)),
    'closed', count(*) FILTER (WHERE coalesce(is_terminal,false)),
    'by_stage', coalesce((SELECT jsonb_object_agg(stage, n) FROM (
        SELECT stage, count(*) n FROM v_enforcement_case_state
         WHERE NOT coalesce(is_terminal,false) GROUP BY stage) q), '{}'::jsonb),
    'by_source', coalesce((SELECT jsonb_object_agg(coalesce(source_kind,'UNKNOWN'), n) FROM (
        SELECT source_kind, count(*) n FROM v_enforcement_case_state
         WHERE NOT coalesce(is_terminal,false) GROUP BY source_kind) q), '{}'::jsonb),
    'penalty_outstanding', coalesce(sum(greatest(coalesce(penalty_amount,0)
        - coalesce(penalty_paid_amount,0) - coalesce(penalty_waived_amount,0), 0))
        FILTER (WHERE NOT coalesce(is_terminal,false)), 0)
  ) FROM v_enforcement_case_state;
$function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_activate(_rule_id uuid, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.engine_rules; v_before jsonb; v_errs text[]; v_test boolean;
BEGIN
  IF NOT public.can_activate_rule_engine(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT to_jsonb(r) INTO v_before FROM public.engine_rules r WHERE r.id = _rule_id;
  IF v_before IS NULL THEN RAISE EXCEPTION 'rule_not_found'; END IF;
  SELECT * INTO v_row FROM public.engine_rules WHERE id = _rule_id;

  v_errs := public.engine_rule_validate_payload(v_before, _rule_id);
  IF array_length(v_errs,1) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'errors', to_jsonb(v_errs));
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.engine_rule_tests t
    WHERE t.rule_id = _rule_id AND t.version = v_row.version AND t.passed
  ) INTO v_test;
  IF NOT v_test THEN
    RETURN jsonb_build_object('ok', false, 'errors',
      to_jsonb(ARRAY['This rule version must pass a sandbox test before it can be activated.']));
  END IF;

  UPDATE public.engine_rules
     SET status = 'active', active_version = version, activated_at = now(), activated_by = auth.uid(),
         activation_note = nullif(btrim(_note),''), deactivation_reason = NULL, updated_by = auth.uid()
   WHERE id = _rule_id RETURNING * INTO v_row;

  INSERT INTO public.engine_rule_versions (rule_id, version, snapshot, note, created_by)
  VALUES (v_row.id, v_row.version, to_jsonb(v_row), coalesce(nullif(btrim(_note),''),'activated'), auth.uid())
  ON CONFLICT (rule_id, version) DO NOTHING;

  PERFORM public.create_audit_log(auth.uid(), 'ADMIN_RULE_ACTIVATED', 'engine_rule', v_row.id::text, v_before,
    jsonb_build_object('rule', to_jsonb(v_row), 'rule_code', v_row.rule_code, 'rule_family','shared_engine',
                       'version', v_row.version, 'justification', nullif(btrim(_note),'')));
  PERFORM public.notification_enqueue_event('admin_rule_activated', 'engine_rule', v_row.id,
    jsonb_build_object('rule_code', v_row.rule_code, 'rule_name', v_row.name, 'module', v_row.module));

  RETURN jsonb_build_object('ok', true, 'rule', to_jsonb(v_row));
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_alert_transition(_alert_id uuid, _to_status text, _note text DEFAULT NULL::text, _assign_to uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.engine_rule_alerts;
  v_before jsonb;
  v_from text;
  v_uid uuid := auth.uid();
  v_manage boolean;
  v_allowed text[];
BEGIN
  SELECT * INTO v_row FROM public.engine_rule_alerts WHERE id = _alert_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'alert_not_found'; END IF;

  v_manage := public.can_manage_rule_engine(v_uid);
  IF NOT v_manage AND coalesce(v_row.assigned_to, '00000000-0000-0000-0000-000000000000'::uuid) <> coalesce(v_uid, '11111111-1111-1111-1111-111111111111'::uuid) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_from := coalesce(v_row.status, 'open');
  v_allowed := CASE v_from
    WHEN 'open'         THEN ARRAY['acknowledged','assigned','closed']
    WHEN 'acknowledged' THEN ARRAY['assigned','resolved','closed']
    WHEN 'assigned'     THEN ARRAY['resolved','closed']
    WHEN 'resolved'     THEN ARRAY['closed']
    ELSE ARRAY[]::text[]
  END;

  IF NOT (_to_status = ANY (v_allowed)) THEN
    RAISE EXCEPTION 'invalid_transition:% ->%', v_from, _to_status;
  END IF;
  IF _to_status = 'assigned' AND _assign_to IS NULL THEN
    RAISE EXCEPTION 'assignee_required';
  END IF;

  v_before := to_jsonb(v_row);

  UPDATE public.engine_rule_alerts SET
    status = _to_status,
    acknowledged_by = CASE WHEN _to_status = 'acknowledged' THEN v_uid ELSE acknowledged_by END,
    acknowledged_at = CASE WHEN _to_status = 'acknowledged' THEN now() ELSE acknowledged_at END,
    assigned_to     = CASE WHEN _to_status = 'assigned' THEN _assign_to ELSE assigned_to END,
    assigned_by     = CASE WHEN _to_status = 'assigned' THEN v_uid ELSE assigned_by END,
    assigned_at     = CASE WHEN _to_status = 'assigned' THEN now() ELSE assigned_at END,
    resolved_by     = CASE WHEN _to_status = 'resolved' THEN v_uid ELSE resolved_by END,
    resolved_at     = CASE WHEN _to_status = 'resolved' THEN now() ELSE resolved_at END,
    closed_by       = CASE WHEN _to_status = 'closed' THEN v_uid ELSE closed_by END,
    closed_at       = CASE WHEN _to_status = 'closed' THEN now() ELSE closed_at END,
    updated_at = now()
  WHERE id = _alert_id RETURNING * INTO v_row;

  INSERT INTO public.engine_rule_lifecycle_events (
    target_type, target_id, rule_id, version, from_status, to_status, note,
    actor_id, actor_role, correlation_id
  ) VALUES (
    'alert', _alert_id, v_row.rule_id, v_row.version, v_from, _to_status, nullif(btrim(coalesce(_note,'')),''),
    v_uid, public.resolve_actor_role(v_uid), v_row.correlation_id
  );

  PERFORM public.create_audit_log(
    v_uid, 'RULE_ALERT_' || upper(_to_status), 'engine_rule_alert', _alert_id::text, v_before,
    jsonb_build_object('from_status', v_from, 'to_status', _to_status, 'note', _note,
      'rule_id', v_row.rule_id, 'version', v_row.version, 'rule_family', 'shared_engine',
      'correlation_id', v_row.correlation_id, 'source_event_id', v_row.source_event_id,
      'action_index', v_row.action_index)
  );

  RETURN jsonb_build_object('ok', true, 'alert', to_jsonb(v_row));
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_deactivate(_rule_id uuid, _justification text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.engine_rules; v_open int; v_before jsonb;
BEGIN
  IF NOT public.can_deactivate_rule_engine(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF coalesce(btrim(_justification),'') = '' THEN RAISE EXCEPTION 'justification_required'; END IF;

  SELECT to_jsonb(r) INTO v_before FROM public.engine_rules r WHERE r.id = _rule_id;
  IF v_before IS NULL THEN RAISE EXCEPTION 'rule_not_found'; END IF;

  UPDATE public.engine_rules
     SET status = 'inactive', active_version = NULL,
         deactivation_reason = btrim(_justification), updated_by = auth.uid()
   WHERE id = _rule_id RETURNING * INTO v_row;

  SELECT count(*) INTO v_open FROM public.engine_rule_alerts WHERE rule_id = _rule_id AND status = 'open';

  PERFORM public.create_audit_log(auth.uid(), 'ADMIN_RULE_DEACTIVATED', 'engine_rule', v_row.id::text,
    v_before, jsonb_build_object('status','inactive','rule_code', v_row.rule_code,
      'rule_family','shared_engine','version', v_row.version,
      'justification', btrim(_justification), 'open_alerts_retained', v_open));

  RETURN jsonb_build_object('ok', true, 'rule', to_jsonb(v_row), 'open_alerts_retained', v_open);
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_is_executable(_rule_id uuid, _as_of date DEFAULT CURRENT_DATE)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.engine_rules r
    WHERE r.id = _rule_id
      AND r.status = 'active'
      AND (r.effective_from IS NULL OR r.effective_from <= _as_of)
      AND (r.effective_to   IS NULL OR r.effective_to   >= _as_of)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_lifecycle_state(_status text, _from date, _to date, _as_of date DEFAULT CURRENT_DATE)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _status <> 'active' THEN _status
    WHEN _to IS NOT NULL AND _to < _as_of THEN 'expired'
    WHEN _from IS NOT NULL AND _from > _as_of THEN 'scheduled'
    ELSE 'active'
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_owner_candidates()
 RETURNS TABLE(user_id uuid, full_name text, email text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p.id,
         coalesce(nullif(btrim(p.full_name),''), p.email) AS full_name,
         p.email
    FROM public.profiles p
   WHERE public.can_view_rule_engine()
     AND NOT public.has_external_role(p.id)
     AND coalesce(p.status,'active') = 'active'
   ORDER BY 2
$function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_owner_is_valid(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT _user_id IS NULL OR EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = _user_id AND NOT public.has_external_role(p.id)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_record_test(_rule_id uuid, _params jsonb, _results jsonb, _evaluated integer, _matched integer, _passed boolean, _error text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ver int; v_id uuid;
BEGIN
  IF NOT public.can_manage_rule_engine(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF;
  SELECT version INTO v_ver FROM public.engine_rules WHERE id = _rule_id;
  IF v_ver IS NULL THEN RAISE EXCEPTION 'rule_not_found'; END IF;
  INSERT INTO public.engine_rule_tests (rule_id, version, passed, params, results, evaluated_count, matched_count, error, run_by)
  VALUES (_rule_id, v_ver, coalesce(_passed,false), coalesce(_params,'{}'::jsonb), coalesce(_results,'[]'::jsonb),
          coalesce(_evaluated,0), coalesce(_matched,0), _error, auth.uid())
  RETURNING id INTO v_id;
  RETURN v_id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_record_test_run(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule_id uuid := (_payload->>'rule_id')::uuid;
  v_run_by uuid := nullif(_payload->>'run_by','')::uuid;
  v_actor uuid := coalesce(auth.uid(), v_run_by);
  v_ver int;
  v_id uuid;
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role'
     AND NOT public.can_manage_rule_engine(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT version INTO v_ver FROM public.engine_rules WHERE id = v_rule_id;
  IF v_ver IS NULL THEN RAISE EXCEPTION 'rule_not_found'; END IF;

  INSERT INTO public.engine_rule_tests (
    rule_id, version, target_version, run_mode, passed, params, results,
    evaluated_count, matched_count, error, run_by, duration_ms, correlation_id, label
  ) VALUES (
    v_rule_id,
    v_ver,
    coalesce((_payload->>'target_version')::int, v_ver),
    coalesce(nullif(_payload->>'run_mode',''), 'current_snapshot'),
    coalesce((_payload->>'passed')::boolean, false),
    coalesce(_payload->'params', '{}'::jsonb),
    coalesce(_payload->'results', '[]'::jsonb),
    coalesce((_payload->>'evaluated')::int, 0),
    coalesce((_payload->>'matched')::int, 0),
    nullif(_payload->>'error',''),
    v_actor,
    (_payload->>'duration_ms')::int,
    nullif(_payload->>'correlation_id','')::uuid,
    nullif(_payload->>'label','')
  ) RETURNING id INTO v_id;

  PERFORM public.create_audit_log(
    v_actor, 'RULE_TEST_RUN', 'engine_rule', v_rule_id::text, NULL,
    jsonb_build_object(
      'test_id', v_id,
      'run_mode', coalesce(nullif(_payload->>'run_mode',''), 'current_snapshot'),
      'target_version', coalesce((_payload->>'target_version')::int, v_ver),
      'evaluated', coalesce((_payload->>'evaluated')::int, 0),
      'matched', coalesce((_payload->>'matched')::int, 0),
      'passed', coalesce((_payload->>'passed')::boolean, false),
      'correlation_id', nullif(_payload->>'correlation_id',''),
      'rule_family', 'shared_engine'
    )
  );

  RETURN v_id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_restore_version(_rule_id uuid, _version integer, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_snap jsonb; v_row public.engine_rules; v_before jsonb;
BEGIN
  IF NOT public.can_manage_rule_engine(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT snapshot INTO v_snap FROM public.engine_rule_versions
   WHERE rule_id = _rule_id AND version = _version;
  IF v_snap IS NULL THEN RAISE EXCEPTION 'version_not_found'; END IF;

  SELECT to_jsonb(r) INTO v_before FROM public.engine_rules r WHERE r.id = _rule_id;
  IF v_before IS NULL THEN RAISE EXCEPTION 'rule_not_found'; END IF;

  INSERT INTO public.engine_rule_versions (rule_id, version, snapshot, note, created_by)
  SELECT _rule_id, (v_before->>'version')::int, v_before, 'superseded', auth.uid()
  ON CONFLICT (rule_id, version) DO NOTHING;

  UPDATE public.engine_rules SET
    name = v_snap->>'name',
    description = nullif(v_snap->>'description',''),
    rule_type = v_snap->>'rule_type',
    module = coalesce(nullif(v_snap->>'module',''), module),
    sub_module = nullif(v_snap->>'sub_module',''),
    severity = coalesce(nullif(v_snap->>'severity',''),'medium'),
    conditions = coalesce(v_snap->'conditions','{}'::jsonb),
    actions = coalesce(v_snap->'actions','[]'::jsonb),
    suppression_days = coalesce((v_snap->>'suppression_days')::int, 0),
    effective_from = nullif(v_snap->>'effective_from','')::date,
    effective_to = nullif(v_snap->>'effective_to','')::date,
    on_action_failure = coalesce(nullif(v_snap->>'on_action_failure',''),'continue'),
    version = version + 1,
    status = 'draft',
    updated_by = auth.uid(),
    updated_at = now()
  WHERE id = _rule_id
  RETURNING * INTO v_row;

  INSERT INTO public.engine_rule_versions (rule_id, version, snapshot, note, created_by)
  VALUES (v_row.id, v_row.version, to_jsonb(v_row),
          coalesce(nullif(btrim(_note),''), 'restored from v' || _version), auth.uid());

  PERFORM public.create_audit_log(auth.uid(), 'ADMIN_RULE_VERSION_RESTORED', 'engine_rule',
    v_row.id::text, v_before,
    jsonb_build_object('rule', to_jsonb(v_row), 'rule_code', v_row.rule_code,
      'rule_family','shared_engine','version', v_row.version,
      'restored_from_version', _version, 'justification', nullif(btrim(_note),'')));

  RETURN jsonb_build_object('ok', true, 'rule', to_jsonb(v_row));
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_save(_payload jsonb, _rule_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_errs text[];
  v_id uuid := _rule_id;
  v_row public.engine_rules;
  v_before jsonb;
  v_type text := _payload->>'rule_type';
  v_new_version boolean := false;
  v_material boolean := false;
  v_note text := nullif(btrim(_payload->>'version_note'),'');
  v_intent text := coalesce(_payload->>'intent','draft');
BEGIN
  IF NOT public.can_manage_rule_engine(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_errs := public.engine_rule_validate_payload(_payload, v_id);

  IF coalesce(btrim(_payload->>'name'),'') = '' THEN
    RETURN jsonb_build_object('ok', false, 'errors', to_jsonb(ARRAY['Rule name is required.']));
  END IF;
  IF v_intent <> 'draft' AND array_length(v_errs,1) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'errors', to_jsonb(v_errs));
  END IF;
  IF NOT public.engine_rule_owner_is_valid(nullif(_payload->>'owner_user_id','')::uuid) THEN
    RETURN jsonb_build_object('ok', false, 'errors',
      to_jsonb(ARRAY['Rule owner must be an authorised internal user.']));
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.engine_rules (
      name, description, rule_type, module, sub_module, tags, severity,
      conditions, actions, suppression_days, owner_user_id, effective_from, effective_to,
      on_action_failure, created_by, updated_by
    ) VALUES (
      btrim(_payload->>'name'), nullif(_payload->>'description',''), v_type,
      coalesce(nullif(_payload->>'module',''),'general'), nullif(_payload->>'sub_module',''),
      coalesce((SELECT array_agg(t::text) FROM jsonb_array_elements_text(coalesce(_payload->'tags','[]'::jsonb)) t), '{}'),
      coalesce(nullif(_payload->>'severity',''),'medium'),
      coalesce(_payload->'conditions','{}'::jsonb), coalesce(_payload->'actions','[]'::jsonb),
      coalesce((_payload->>'suppression_days')::int, 0),
      nullif(_payload->>'owner_user_id','')::uuid,
      nullif(_payload->>'effective_from','')::date,
      nullif(_payload->>'effective_to','')::date,
      coalesce(nullif(_payload->>'on_action_failure',''),'continue'),
      auth.uid(), auth.uid()
    ) RETURNING * INTO v_row;

    INSERT INTO public.engine_rule_versions (rule_id, version, snapshot, note, created_by)
    VALUES (v_row.id, v_row.version, to_jsonb(v_row), coalesce(v_note,'initial draft'), auth.uid())
    ON CONFLICT (rule_id, version) DO NOTHING;

    PERFORM public.create_audit_log(auth.uid(), 'ADMIN_RULE_CREATED', 'engine_rule', v_row.id::text, NULL,
      jsonb_build_object('rule', to_jsonb(v_row), 'rule_code', v_row.rule_code,
                         'rule_family','shared_engine','version', v_row.version));
  ELSE
    SELECT to_jsonb(r) INTO v_before FROM public.engine_rules r WHERE r.id = v_id;
    IF v_before IS NULL THEN RAISE EXCEPTION 'rule_not_found'; END IF;
    SELECT * INTO v_row FROM public.engine_rules WHERE id = v_id;

    v_material := (
      coalesce(_payload->'conditions','{}'::jsonb) IS DISTINCT FROM v_row.conditions
      OR coalesce(_payload->'actions','[]'::jsonb) IS DISTINCT FROM v_row.actions
      OR coalesce(nullif(_payload->>'severity',''),'medium') IS DISTINCT FROM v_row.severity
      OR nullif(_payload->>'owner_user_id','')::uuid IS DISTINCT FROM v_row.owner_user_id
      OR nullif(_payload->>'effective_from','')::date IS DISTINCT FROM v_row.effective_from
      OR nullif(_payload->>'effective_to','')::date IS DISTINCT FROM v_row.effective_to
      OR coalesce((_payload->>'suppression_days')::int,0) IS DISTINCT FROM v_row.suppression_days
    );

    IF v_material AND v_note IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'errors',
        to_jsonb(ARRAY['A version note is required when conditions, actions, severity, owner, effective dates or suppression change.']));
    END IF;

    v_new_version := (v_row.status = 'active') OR v_material;

    INSERT INTO public.engine_rule_versions (rule_id, version, snapshot, note, created_by)
    VALUES (v_row.id, v_row.version, to_jsonb(v_row), 'superseded', auth.uid())
    ON CONFLICT (rule_id, version) DO NOTHING;

    UPDATE public.engine_rules SET
      name = btrim(_payload->>'name'),
      description = nullif(_payload->>'description',''),
      rule_type = v_type,
      module = coalesce(nullif(_payload->>'module',''), module),
      sub_module = nullif(_payload->>'sub_module',''),
      tags = coalesce((SELECT array_agg(t::text) FROM jsonb_array_elements_text(coalesce(_payload->'tags','[]'::jsonb)) t), '{}'),
      severity = coalesce(nullif(_payload->>'severity',''),'medium'),
      conditions = coalesce(_payload->'conditions','{}'::jsonb),
      actions = coalesce(_payload->'actions','[]'::jsonb),
      suppression_days = coalesce((_payload->>'suppression_days')::int, 0),
      owner_user_id = nullif(_payload->>'owner_user_id','')::uuid,
      effective_from = nullif(_payload->>'effective_from','')::date,
      effective_to = nullif(_payload->>'effective_to','')::date,
      on_action_failure = coalesce(nullif(_payload->>'on_action_failure',''),'continue'),
      version = CASE WHEN v_new_version THEN version + 1 ELSE version END,
      status = CASE WHEN v_new_version THEN 'draft' ELSE status END,
      updated_by = auth.uid(),
      updated_at = now()
    WHERE id = v_row.id
    RETURNING * INTO v_row;

    IF v_new_version THEN
      INSERT INTO public.engine_rule_versions (rule_id, version, snapshot, note, created_by)
      VALUES (v_row.id, v_row.version, to_jsonb(v_row), coalesce(v_note,'draft revision'), auth.uid())
      ON CONFLICT (rule_id, version) DO NOTHING;
    END IF;

    PERFORM public.create_audit_log(auth.uid(), 'ADMIN_RULE_UPDATED', 'engine_rule', v_row.id::text,
      v_before,
      jsonb_build_object('rule', to_jsonb(v_row), 'rule_code', v_row.rule_code,
                         'rule_family','shared_engine', 'version', v_row.version,
                         'justification', v_note, 'new_version', v_new_version));

    IF (v_before->>'owner_user_id') IS DISTINCT FROM v_row.owner_user_id::text THEN
      PERFORM public.create_audit_log(auth.uid(), 'ADMIN_RULE_OWNER_CHANGED', 'engine_rule', v_row.id::text,
        jsonb_build_object('owner_user_id', v_before->>'owner_user_id'),
        jsonb_build_object('owner_user_id', v_row.owner_user_id, 'rule_code', v_row.rule_code,
                           'version', v_row.version, 'justification', v_note));
    END IF;

    IF (v_before->>'effective_from') IS DISTINCT FROM v_row.effective_from::text
       OR (v_before->>'effective_to') IS DISTINCT FROM v_row.effective_to::text THEN
      PERFORM public.create_audit_log(auth.uid(), 'ADMIN_RULE_EFFECTIVE_DATES_CHANGED', 'engine_rule', v_row.id::text,
        jsonb_build_object('effective_from', v_before->>'effective_from', 'effective_to', v_before->>'effective_to'),
        jsonb_build_object('effective_from', v_row.effective_from, 'effective_to', v_row.effective_to,
                           'rule_code', v_row.rule_code, 'version', v_row.version, 'justification', v_note));
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'rule', to_jsonb(v_row),
                            'new_version', v_new_version, 'warnings', to_jsonb(v_errs));
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_suppression_state(_rule_id uuid, _entity_key text, _at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rule public.engine_rules; v_sup public.engine_rule_suppressions;
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role'
     AND NOT public.can_view_rule_engine(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_rule FROM public.engine_rules WHERE id = _rule_id;
  IF v_rule.id IS NULL THEN RAISE EXCEPTION 'rule_not_found'; END IF;

  SELECT * INTO v_sup FROM public.engine_rule_suppressions
   WHERE rule_id = _rule_id AND entity_key = _entity_key;

  RETURN jsonb_build_object(
    'rule_id', _rule_id,
    'entity_key', _entity_key,
    'as_of', _at,
    'suppression_days', v_rule.suppression_days,
    'critical_bypass', v_rule.severity = 'critical',
    'record_exists', v_sup.id IS NOT NULL,
    'suppressed_until', v_sup.suppressed_until,
    'suppressed_count', coalesce(v_sup.suppressed_count, 0),
    'last_suppressed_at', v_sup.last_suppressed_at,
    'expired', v_sup.id IS NOT NULL AND v_sup.suppressed_until <= _at,
    'suppressed',
      v_rule.severity <> 'critical'
      AND coalesce(v_rule.suppression_days, 0) > 0
      AND v_sup.id IS NOT NULL
      AND v_sup.suppressed_until > _at
  );
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_task_transition(_task_id uuid, _to_status text, _note text DEFAULT NULL::text, _assign_to uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.engine_rule_tasks;
  v_before jsonb;
  v_from text;
  v_uid uuid := auth.uid();
  v_manage boolean;
  v_allowed text[];
BEGIN
  SELECT * INTO v_row FROM public.engine_rule_tasks WHERE id = _task_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'task_not_found'; END IF;

  v_manage := public.can_manage_rule_engine(v_uid);
  IF NOT v_manage AND coalesce(v_row.assigned_to, '00000000-0000-0000-0000-000000000000'::uuid) <> coalesce(v_uid, '11111111-1111-1111-1111-111111111111'::uuid) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_from := coalesce(v_row.status, 'open');
  v_allowed := CASE v_from
    WHEN 'open'        THEN ARRAY['in_progress','completed','cancelled']
    WHEN 'in_progress' THEN ARRAY['completed','cancelled']
    ELSE ARRAY[]::text[]
  END;

  IF NOT (_to_status = ANY (v_allowed)) THEN
    RAISE EXCEPTION 'invalid_transition:% ->%', v_from, _to_status;
  END IF;

  v_before := to_jsonb(v_row);

  UPDATE public.engine_rule_tasks SET
    status = _to_status,
    assigned_to  = coalesce(_assign_to, assigned_to),
    started_at   = CASE WHEN _to_status = 'in_progress' THEN now() ELSE started_at END,
    started_by   = CASE WHEN _to_status = 'in_progress' THEN v_uid ELSE started_by END,
    completed_by = CASE WHEN _to_status = 'completed' THEN v_uid ELSE completed_by END,
    completed_at = CASE WHEN _to_status = 'completed' THEN now() ELSE completed_at END,
    cancelled_by = CASE WHEN _to_status = 'cancelled' THEN v_uid ELSE cancelled_by END,
    cancelled_at = CASE WHEN _to_status = 'cancelled' THEN now() ELSE cancelled_at END,
    updated_at = now()
  WHERE id = _task_id RETURNING * INTO v_row;

  INSERT INTO public.engine_rule_lifecycle_events (
    target_type, target_id, rule_id, version, from_status, to_status, note,
    actor_id, actor_role, correlation_id
  ) VALUES (
    'task', _task_id, v_row.rule_id, v_row.version, v_from, _to_status, nullif(btrim(coalesce(_note,'')),''),
    v_uid, public.resolve_actor_role(v_uid), v_row.correlation_id
  );

  PERFORM public.create_audit_log(
    v_uid, 'RULE_TASK_' || upper(_to_status), 'engine_rule_task', _task_id::text, v_before,
    jsonb_build_object('from_status', v_from, 'to_status', _to_status, 'note', _note,
      'rule_id', v_row.rule_id, 'version', v_row.version, 'rule_family', 'shared_engine',
      'correlation_id', v_row.correlation_id, 'source_event_id', v_row.source_event_id,
      'action_index', v_row.action_index)
  );

  RETURN jsonb_build_object('ok', true, 'task', to_jsonb(v_row));
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_validate(_rule_type text, _conditions jsonb, _actions jsonb, _name text)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  errs text[] := '{}';
  act jsonb;
  wf uuid;
  sectors jsonb := coalesce(_conditions->'sector_ids', '[]'::jsonb);
  window_days int;
BEGIN
  IF coalesce(btrim(_name), '') = '' THEN errs := errs || 'Rule name is required.'; END IF;

  IF coalesce(jsonb_array_length(coalesce(_conditions->'predicates','[]'::jsonb)), 0) = 0 THEN
    errs := errs || 'At least one condition is required.';
  END IF;

  IF coalesce(jsonb_array_length(coalesce(_actions,'[]'::jsonb)), 0) = 0 THEN
    errs := errs || 'At least one action on trigger is required.';
  END IF;

  -- R-ADM-020: sector scope mandatory for threshold / early-warning style rules
  IF _rule_type IN ('threshold','trend','peer_comparison','macro_overlay','group_contagion')
     AND jsonb_typeof(sectors) = 'array' AND jsonb_array_length(sectors) = 0 THEN
    errs := errs || 'Sector scope is required for threshold and early-warning rules.';
  END IF;

  -- R-ADM-021: pattern detection window must be at least 7 days
  IF _rule_type = 'pattern_detection' THEN
    window_days := coalesce((_conditions->>'window_days')::int, 0);
    IF window_days < 7 THEN
      errs := errs || 'Pattern detection time window must be at least 7 days.';
    END IF;
  END IF;

  -- R-ADM-019: workflow actions may only reference published workflows
  FOR act IN SELECT * FROM jsonb_array_elements(coalesce(_actions,'[]'::jsonb)) LOOP
    IF act->>'type' = 'initiate_workflow' THEN
      wf := nullif(act->>'workflow_id','')::uuid;
      IF wf IS NULL THEN
        errs := errs || 'Initiate Workflow action requires a workflow.';
      ELSIF NOT EXISTS (
        SELECT 1 FROM public.approval_workflows w
        WHERE w.id = wf AND w.current_published_version_id IS NOT NULL
      ) THEN
        errs := errs || 'Only published workflows can be selected for Initiate Workflow.';
      END IF;
    END IF;
    IF act->>'type' = 'generate_alert' AND coalesce(btrim(act->>'template'),'') = '' THEN
      errs := errs || 'Generate Alert action requires alert text.';
    END IF;
    IF act->>'type' = 'send_notification' AND coalesce(btrim(act->>'event_key'),'') = '' THEN
      errs := errs || 'Send Notification action requires a notification event.';
    END IF;
    IF act->>'type' = 'create_task' AND coalesce(btrim(act->>'assigned_role'),'') = '' THEN
      errs := errs || 'Create Task action requires an assigned role.';
    END IF;
  END LOOP;

  RETURN errs;
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_validate_payload(_payload jsonb, _rule_id uuid DEFAULT NULL::uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  errs text[] := '{}';
  v_type text := _payload->>'rule_type';
  v_conditions jsonb := coalesce(_payload->'conditions','{}'::jsonb);
  v_actions jsonb := coalesce(_payload->'actions','[]'::jsonb);
  preds jsonb; p jsonb; act jsonb; wf uuid; sid uuid; idx int := 0;
  valid_ops text[] := ARRAY['gt','gte','lt','lte','eq','neq','between','in','not_in','contains','changed_by_pct','trend_up','trend_down'];
  valid_periods text[] := ARRAY['daily','weekly','monthly','quarterly','half_yearly','annual','rolling'];
BEGIN
  IF coalesce(btrim(_payload->>'name'),'') = '' THEN
    errs := array_append(errs, 'Rule name is required.');
  END IF;

  IF coalesce(btrim(_payload->>'rule_code'),'') <> '' AND EXISTS (
       SELECT 1 FROM public.engine_rules r
        WHERE lower(r.rule_code) = lower(btrim(_payload->>'rule_code'))
          AND (_rule_id IS NULL OR r.id <> _rule_id)) THEN
    errs := array_append(errs, 'Rule code is already used by another rule.');
  END IF;

  IF coalesce(btrim(_payload->>'module'),'') = '' THEN
    errs := array_append(errs, 'Module is required.');
  END IF;

  IF v_type IS NULL OR v_type NOT IN ('threshold','trend','peer_comparison','pattern_detection',
        'cross_field_validation','routing','sla','condition_monitoring','recurrence','scheduling',
        'macro_overlay','group_contagion') THEN
    errs := array_append(errs, 'Unsupported rule type.');
  END IF;

  IF coalesce(nullif(_payload->>'severity',''),'medium') NOT IN ('low','medium','high','critical') THEN
    errs := array_append(errs, 'Invalid severity.');
  END IF;

  IF jsonb_typeof(v_conditions) <> 'object' THEN
    errs := array_append(errs, 'Condition data is malformed.');
  ELSE
    preds := coalesce(v_conditions->'predicates','[]'::jsonb);
    IF jsonb_typeof(preds) <> 'array' THEN
      errs := array_append(errs, 'Condition data is malformed.');
    ELSIF jsonb_array_length(preds) = 0 THEN
      errs := array_append(errs, 'At least one condition is required.');
    ELSE
      FOR p IN SELECT * FROM jsonb_array_elements(preds) LOOP
        IF jsonb_typeof(p) <> 'object' THEN
          errs := array_append(errs, 'Condition data is malformed.');
          CONTINUE;
        END IF;
        IF coalesce(btrim(p->>'metric'),'') = '' THEN
          errs := array_append(errs, 'Every condition requires a metric.');
        END IF;
        IF coalesce(btrim(p->>'operator'),'') = '' OR NOT (p->>'operator' = ANY(valid_ops)) THEN
          errs := array_append(errs, format('Invalid operator "%s".', coalesce(p->>'operator','(empty)')));
        END IF;
        IF coalesce(btrim(p->>'value'),'') = '' THEN
          errs := array_append(errs, 'Every condition requires a threshold value.');
        ELSIF (p->>'operator') = ANY(ARRAY['gt','gte','lt','lte','eq','neq','changed_by_pct'])
              AND (p->>'value') !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
          errs := array_append(errs, 'Threshold value must be numeric for this operator.');
        END IF;
      END LOOP;
    END IF;

    IF nullif(v_conditions->>'period','') IS NOT NULL
       AND NOT ((v_conditions->>'period') = ANY(valid_periods)) THEN
      errs := array_append(errs, 'Invalid reporting period.');
    END IF;
    IF nullif(v_conditions->>'window_days','') IS NOT NULL THEN
      IF (v_conditions->>'window_days') !~ '^[0-9]+$' THEN
        errs := array_append(errs, 'Time window must be a positive number of days.');
      ELSIF v_type = 'pattern_detection' AND (v_conditions->>'window_days')::int < 7 THEN
        errs := array_append(errs, 'Pattern detection time window must be at least 7 days.');
      END IF;
    ELSIF v_type = 'pattern_detection' THEN
      errs := array_append(errs, 'Pattern detection time window must be at least 7 days.');
    END IF;

    IF jsonb_typeof(coalesce(v_conditions->'sector_ids','[]'::jsonb)) <> 'array' THEN
      errs := array_append(errs, 'Sector scope is malformed.');
    ELSE
      IF v_type IN ('threshold','trend','peer_comparison','macro_overlay','group_contagion')
         AND jsonb_array_length(coalesce(v_conditions->'sector_ids','[]'::jsonb)) = 0 THEN
        errs := array_append(errs, 'Sector scope is required for threshold and early-warning rules.');
      END IF;
      FOR p IN SELECT to_jsonb(t) FROM jsonb_array_elements_text(coalesce(v_conditions->'sector_ids','[]'::jsonb)) t LOOP
        BEGIN
          sid := (p #>> '{}')::uuid;
        EXCEPTION WHEN others THEN
          sid := NULL;
        END;
        IF sid IS NULL OR NOT EXISTS (SELECT 1 FROM public.sectors s WHERE s.id = sid) THEN
          errs := array_append(errs, 'Selected sector no longer exists.');
        END IF;
      END LOOP;
    END IF;
  END IF;

  IF jsonb_typeof(v_actions) <> 'array' THEN
    errs := array_append(errs, 'Action data is malformed.');
  ELSIF jsonb_array_length(v_actions) = 0 THEN
    errs := array_append(errs, 'At least one action on trigger is required.');
  ELSE
    FOR act IN SELECT * FROM jsonb_array_elements(v_actions) LOOP
      idx := idx + 1;
      IF jsonb_typeof(act) <> 'object' OR coalesce(btrim(act->>'type'),'') = '' THEN
        errs := array_append(errs, format('Action %s is malformed.', idx));
        CONTINUE;
      END IF;
      IF act->>'type' = 'initiate_workflow' THEN
        wf := nullif(act->>'workflow_id','')::uuid;
        IF wf IS NULL THEN
          errs := array_append(errs, format('Action %s (Initiate Workflow) requires a workflow.', idx));
        ELSIF NOT EXISTS (SELECT 1 FROM public.approval_workflows w
                           WHERE w.id = wf AND w.current_published_version_id IS NOT NULL) THEN
          errs := array_append(errs, format('Action %s references a workflow that is not published.', idx));
        END IF;
      END IF;
      IF act->>'type' = 'generate_alert' AND coalesce(btrim(act->>'template'),'') = '' THEN
        errs := array_append(errs, format('Action %s (Generate Alert) requires alert text.', idx));
      END IF;
      IF act->>'type' = 'send_notification' THEN
        IF coalesce(btrim(act->>'event_key'),'') = '' THEN
          errs := array_append(errs, format('Action %s (Send Notification) requires a notification event.', idx));
        ELSIF NOT EXISTS (SELECT 1 FROM public.notification_event_configs c
                           WHERE c.event_key = act->>'event_key') THEN
          errs := array_append(errs, format('Action %s references an unknown notification event.', idx));
        END IF;
      END IF;
      IF act->>'type' = 'create_task' THEN
        IF coalesce(btrim(act->>'assigned_role'),'') = '' THEN
          errs := array_append(errs, format('Action %s (Create Task) requires an assigned role.', idx));
        ELSIF NOT EXISTS (
          SELECT 1 FROM public.roles r
           WHERE r.name = act->>'assigned_role'
              OR coalesce(r.system_role::text,'') = act->>'assigned_role') THEN
          errs := array_append(errs, format('Action %s references an unknown role.', idx));
        END IF;
        IF nullif(act->>'due_days','') IS NOT NULL AND (act->>'due_days') !~ '^[0-9]+$' THEN
          errs := array_append(errs, format('Action %s has an invalid due-day value.', idx));
        END IF;
      END IF;
      IF act->>'type' = 'raise_escalation' THEN
        IF coalesce(btrim(act->>'escalation_type'),'') = '' THEN
          errs := array_append(errs, format('Action %s (Raise Escalation) requires an escalation type.', idx));
        END IF;
        IF nullif(act->>'severity','') IS NOT NULL
           AND NOT ((act->>'severity') = ANY(ARRAY['low','medium','high','critical'])) THEN
          errs := array_append(errs, format('Action %s has an invalid escalation severity.', idx));
        END IF;
      END IF;
    END LOOP;
  END IF;

  IF nullif(_payload->>'suppression_days','') IS NOT NULL
     AND ((_payload->>'suppression_days') !~ '^-?[0-9]+$' OR (_payload->>'suppression_days')::int < 0) THEN
    errs := array_append(errs, 'Suppression window cannot be negative.');
  END IF;

  IF nullif(_payload->>'effective_from','') IS NOT NULL AND nullif(_payload->>'effective_to','') IS NOT NULL
     AND (_payload->>'effective_to')::date < (_payload->>'effective_from')::date THEN
    errs := array_append(errs, 'Expiry date cannot be earlier than the effective date.');
  END IF;

  IF NOT public.engine_rule_owner_is_valid(nullif(_payload->>'owner_user_id','')::uuid) THEN
    errs := array_append(errs, 'Rule owner must be an authorised internal user.');
  END IF;

  IF coalesce(nullif(_payload->>'on_action_failure',''),'continue') NOT IN ('continue','stop') THEN
    errs := array_append(errs, 'Invalid action failure policy.');
  END IF;

  RETURN errs;
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rule_versions_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'engine_rule_versions rows are immutable (attempted %)', TG_OP
    USING ERRCODE = '42501';
END; $function$
;
CREATE OR REPLACE FUNCTION public.engine_rules_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.rule_code IS DISTINCT FROM OLD.rule_code THEN
    RAISE EXCEPTION 'rule_code_immutable';
  END IF;

  IF OLD.status = 'active' AND NEW.status = 'active' AND NEW.version = OLD.version THEN
    IF NEW.conditions IS DISTINCT FROM OLD.conditions
       OR NEW.actions IS DISTINCT FROM OLD.actions
       OR NEW.rule_type IS DISTINCT FROM OLD.rule_type
       OR NEW.severity IS DISTINCT FROM OLD.severity
       OR NEW.suppression_days IS DISTINCT FROM OLD.suppression_days
       OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
       OR NEW.effective_to IS DISTINCT FROM OLD.effective_to
       OR NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id
       OR NEW.on_action_failure IS DISTINCT FROM OLD.on_action_failure THEN
      RAISE EXCEPTION 'active_rule_requires_new_version'
        USING ERRCODE = '42501',
              HINT = 'Editing an active rule must create a new draft version.';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.ensure_module_scope_all()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  mkey text := lower(regexp_replace(NEW.module,'\s+','_','g'));
BEGIN
  INSERT INTO public.rbac_module_scopes (module, scope, label)
  VALUES (mkey, 'all', 'All records')
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.ensure_submission_acknowledgement(_application_id uuid, _ack_text text DEFAULT NULL::text, _applicant_name text DEFAULT NULL::text, _applicant_email text DEFAULT NULL::text, _entity_name text DEFAULT NULL::text, _is_resubmission boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app RECORD;
  v_row public.application_acknowledgements;
  v_version integer;
BEGIN
  SELECT id, application_number, applicant_id, license_type, submitted_at, status
    INTO v_app
  FROM public.applications
  WHERE id = _application_id;

  IF v_app.id IS NULL THEN
    RETURN jsonb_build_object('error', 'Application not found', 'code', 'NOT_FOUND');
  END IF;
  IF v_app.submitted_at IS NULL THEN
    RETURN jsonb_build_object('error', 'Application has not been submitted', 'code', 'NOT_SUBMITTED');
  END IF;

  -- Existing acknowledgement for this exact submission => idempotent return.
  SELECT * INTO v_row
  FROM public.application_acknowledgements
  WHERE application_id = _application_id AND submitted_at = v_app.submitted_at;

  IF v_row.id IS NOT NULL THEN
    RETURN jsonb_build_object('created', false, 'acknowledgement', to_jsonb(v_row));
  END IF;

  SELECT coalesce(max(submission_version), 0) + 1 INTO v_version
  FROM public.application_acknowledgements
  WHERE application_id = _application_id;

  INSERT INTO public.application_acknowledgements (
    application_id, submission_version, reference, applicant_id, applicant_name,
    applicant_email, entity_name, license_type, submitted_at, is_resubmission,
    ack_text, status
  ) VALUES (
    _application_id, v_version, v_app.application_number, v_app.applicant_id, _applicant_name,
    _applicant_email, _entity_name, v_app.license_type, v_app.submitted_at, coalesce(_is_resubmission, false),
    left(coalesce(_ack_text, ''), 4000), 'GENERATED'
  )
  ON CONFLICT (application_id, submitted_at) DO NOTHING
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    SELECT * INTO v_row
    FROM public.application_acknowledgements
    WHERE application_id = _application_id AND submitted_at = v_app.submitted_at;
    RETURN jsonb_build_object('created', false, 'acknowledgement', to_jsonb(v_row));
  END IF;

  RETURN jsonb_build_object('created', true, 'acknowledgement', to_jsonb(v_row));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.entity360_as_of(_entity_id uuid, _as_of timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE u uuid := auth.uid();
BEGIN
  IF u IS NULL OR NOT public.is_internal_staff(u) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT public.e360_section_allowed(u,'overview') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'as_of', _as_of,
    'identity', public.entity360_section(_entity_id,'identity',_as_of,500,0) -> 'rows',
    'business_profile', public.entity360_section(_entity_id,'business_profile',_as_of,500,0) -> 'rows',
    'licences', public.entity360_section(_entity_id,'licences',_as_of,500,0) -> 'rows',
    'ownership', public.entity360_section(_entity_id,'ownership',_as_of,500,0) -> 'rows',
    'relationships', public.entity360_section(_entity_id,'relationships',_as_of,500,0) -> 'rows',
    'governance', public.entity360_section(_entity_id,'governance',_as_of,500,0) -> 'rows'
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.entity360_overview(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  u uuid := auth.uid();
  res jsonb;
  ent record;
BEGIN
  IF u IS NULL OR NOT public.is_internal_staff(u) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT public.e360_section_allowed(u, 'overview') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT l.id, l.name, l.status, l.public_slug, l.systemic_importance,
         s.name AS sector_name, ss.name AS sub_sector_name, c.name AS category_name,
         st.label AS identity_status, ls.label AS lifecycle_stage, l.party_id,
         l.merged_into_entity_id, l.structure_version
    INTO ent
  FROM public.licensees l
  LEFT JOIN public.sectors s ON s.id = l.sector_id
  LEFT JOIN public.sub_sectors ss ON ss.id = l.sub_sector_id
  LEFT JOIN public.categories c ON c.id = l.category_id
  LEFT JOIN public.entity_identity_statuses st ON st.id = l.identity_status_id
  LEFT JOIN public.lifecycle_stages ls ON ls.id = l.lifecycle_stage_id
  WHERE l.id = _entity_id;

  IF ent.id IS NULL THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  res := jsonb_build_object(
    'found', true,
    'entity', jsonb_build_object(
      'id', ent.id, 'name', ent.name, 'status', ent.status,
      'public_slug', ent.public_slug, 'systemic_importance', ent.systemic_importance,
      'sector', ent.sector_name, 'sub_sector', ent.sub_sector_name, 'category', ent.category_name,
      'identity_status', ent.identity_status, 'lifecycle_stage', ent.lifecycle_stage,
      'party_id', ent.party_id, 'merged_into_entity_id', ent.merged_into_entity_id,
      'structure_version', ent.structure_version),
    'sections', (
      SELECT jsonb_object_agg(sec, public.e360_section_allowed(u, sec))
      FROM unnest(ARRAY['identity','licences','ownership','relationships','governance','fit_and_proper',
        'fit_and_proper_evidence','business_profile','prudential','returns','risk','supervision',
        'market_conduct','aml','aml_confidential','resilience','examinations','enforcement',
        'regulatory_requests','documents','correspondence','timeline','provenance']) sec
    )
  );

  IF public.e360_section_allowed(u,'licences') THEN
    res := res || jsonb_build_object('licences', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', li.id, 'license_number', li.license_number,
        'license_type', li.license_type, 'status', li.status, 'issued_at', li.issued_at,
        'valid_until', li.valid_until, 'is_primary', el.is_primary,
        'effective_from', el.effective_from, 'effective_to', el.effective_to)
        ORDER BY el.is_primary DESC NULLS LAST, li.issued_at DESC NULLS LAST)
      FROM public.entity_licenses el JOIN public.licenses li ON li.id = el.license_id
      WHERE el.entity_id = _entity_id), '[]'::jsonb));
  END IF;

  IF public.e360_section_allowed(u,'ownership') THEN
    res := res || jsonb_build_object('ownership_summary', (
      SELECT jsonb_build_object('current_holders', count(*),
        'controllers', count(*) FILTER (WHERE oi.is_controller),
        'ubos', count(*) FILTER (WHERE oi.is_ubo))
      FROM public.ownership_interests oi
      WHERE oi.owned_entity_id = _entity_id AND oi.effective_to IS NULL AND oi.superseded_at IS NULL));
    res := res || jsonb_build_object('governance_summary', (
      SELECT jsonb_build_object('current_appointments', count(*),
        'awaiting_approval', count(*) FILTER (WHERE a.regulatory_approval_status IS DISTINCT FROM 'approved'))
      FROM public.entity_appointments a
      WHERE a.entity_id = _entity_id AND a.effective_to IS NULL AND a.superseded_at IS NULL));
  END IF;

  IF public.e360_section_allowed(u,'fit_and_proper') THEN
    res := res || jsonb_build_object('fp_summary', (
      SELECT jsonb_build_object('total', count(*),
        'open', count(*) FILTER (WHERE f.closed_at IS NULL),
        'determined', count(*) FILTER (WHERE f.determined_at IS NOT NULL))
      FROM public.fp_assessments f WHERE f.licensee_id = _entity_id));
  END IF;

  IF public.e360_section_allowed(u,'returns') THEN
    res := res || jsonb_build_object('returns_summary', (
      SELECT jsonb_build_object(
        'obligations', (SELECT count(*) FROM public.entity_reporting_obligations o
                         WHERE o.entity_id = _entity_id AND lower(o.status) = 'active'),
        'filings', count(*),
        'accepted', count(*) FILTER (WHERE lower(rf.status) = 'accepted'),
        'awaiting_review', count(*) FILTER (WHERE lower(rf.status) IN ('submitted','under_review')),
        'overdue', count(*) FILTER (WHERE lower(rf.status) <> 'accepted' AND p.due_date < current_date))
      FROM public.return_filings rf
      LEFT JOIN public.reporting_periods p ON p.id = rf.reporting_period_id
      WHERE rf.entity_id = _entity_id));
  END IF;

  IF public.e360_section_allowed(u,'risk') THEN
    res := res
      || jsonb_build_object('risk', (
        SELECT jsonb_build_object('overall_rating', r.overall_rating, 'risk_score', r.risk_score,
          'assessment_date', r.assessment_date, 'risk_factors', r.risk_factors)
        FROM public.risk_ratings r WHERE r.entity_id = _entity_id
        ORDER BY r.assessment_date DESC NULLS LAST, r.created_at DESC LIMIT 1))
      || jsonb_build_object('risk_score_current', (
        SELECT jsonb_build_object('score', rs.score, 'band', rs.band, 'period_key', rs.period_key,
          'computed_at', rs.computed_at)
        FROM public.entity_risk_scores rs
        WHERE rs.entity_id = _entity_id AND rs.is_current LIMIT 1));
  END IF;

  IF public.e360_section_allowed(u,'supervision') THEN
    res := res || jsonb_build_object('supervision', jsonb_build_object(
      'assignment', (SELECT jsonb_build_object('supervisor_name', a.supervisor_name, 'team', a.team,
          'supervisory_cycle', a.supervisory_cycle, 'cycle_start', a.cycle_start, 'cycle_end', a.cycle_end)
        FROM public.entity_supervision_assignments a
        WHERE a.entity_id = _entity_id AND a.status = 'active' AND a.effective_to IS NULL
        ORDER BY a.effective_from DESC LIMIT 1),
      'plans', (SELECT count(*) FROM public.supervisory_plans sp WHERE sp.entity_id = _entity_id),
      'open_actions', (SELECT count(*) FROM public.supervisory_plan_actions sa
        JOIN public.supervisory_plans sp ON sp.id = sa.plan_id
        WHERE sp.entity_id = _entity_id AND sa.status <> 'completed')));
  END IF;

  IF public.e360_section_allowed(u,'prudential') THEN
    res := res || jsonb_build_object('prudential', jsonb_build_object(
      'assessments', (SELECT count(*) FROM public.prudential_assessments pa WHERE pa.entity_id = _entity_id),
      'latest_rating', (SELECT pa.overall_rating FROM public.prudential_assessments pa
        WHERE pa.entity_id = _entity_id ORDER BY pa.period_end DESC NULLS LAST LIMIT 1),
      'metrics_reported', (SELECT count(DISTINCT mv.regulatory_metric_id)
        FROM public.return_metric_values mv WHERE mv.entity_id = _entity_id)));
  END IF;

  IF public.e360_section_allowed(u,'market_conduct') THEN
    res := res || jsonb_build_object('market_conduct', jsonb_build_object(
      'complaints', (SELECT count(*) FROM public.complaints c WHERE c.licensee_id = _entity_id),
      'open_complaints', (SELECT count(*) FROM public.complaints c
        WHERE c.licensee_id = _entity_id AND c.closed_at IS NULL),
      'alerts_open', (SELECT count(*) FROM public.conduct_alerts ca
        WHERE ca.licensee_id = _entity_id AND ca.closed_at IS NULL)));
  END IF;

  IF public.e360_section_allowed(u,'aml') THEN
    res := res || jsonb_build_object('aml', jsonb_build_object(
      'latest', (SELECT jsonb_build_object('reference', a.reference, 'assessment_date', a.assessment_date,
          'residual_rating', a.residual_rating, 'status', a.status, 'inspection_status', a.inspection_status,
          'next_review_date', a.next_review_date)
        FROM public.aml_assessments a WHERE a.entity_id = _entity_id
        ORDER BY a.assessment_date DESC LIMIT 1),
      'open_findings', (SELECT count(*) FROM public.aml_findings f
        WHERE f.entity_id = _entity_id AND f.status <> 'closed')));
  END IF;

  IF public.e360_section_allowed(u,'resilience') THEN
    res := res || jsonb_build_object('resilience', jsonb_build_object(
      'arrangements', (SELECT count(*) FROM public.resilience_arrangements ra
        WHERE ra.entity_id = _entity_id AND ra.status = 'active'),
      'critical_providers', (SELECT count(*) FROM public.resilience_arrangements ra
        WHERE ra.entity_id = _entity_id AND ra.criticality = 'critical' AND ra.status = 'active'),
      'open_incidents', (SELECT count(*) FROM public.resilience_incidents ri
        WHERE ri.entity_id = _entity_id AND ri.status <> 'closed')));
  END IF;

  IF public.e360_section_allowed(u,'examinations') THEN
    res := res || jsonb_build_object('examinations', jsonb_build_object(
      'total', (SELECT count(*) FROM public.examinations e WHERE e.entity_id = _entity_id),
      'in_progress', (SELECT count(*) FROM public.examinations e
        WHERE e.entity_id = _entity_id AND e.closed_at IS NULL),
      'open_findings', (SELECT count(*) FROM public.examination_findings ef
        JOIN public.examinations e ON e.id = ef.examination_id
        WHERE e.entity_id = _entity_id AND ef.status <> 'closed')));
  END IF;

  IF public.e360_section_allowed(u,'enforcement') THEN
    res := res || jsonb_build_object('enforcement', jsonb_build_object(
      'total', (SELECT count(*) FROM public.enforcement_actions ea WHERE ea.entity_id = _entity_id),
      'open', (SELECT count(*) FROM public.enforcement_actions ea
        WHERE ea.entity_id = _entity_id AND ea.closed_at IS NULL)));
  END IF;

  IF public.e360_section_allowed(u,'regulatory_requests') THEN
    res := res || jsonb_build_object('regulatory_requests', jsonb_build_object(
      'total', (SELECT count(*) FROM public.regulatory_requests rr WHERE rr.entity_id = _entity_id),
      'open', (SELECT count(*) FROM public.regulatory_requests rr
        WHERE rr.entity_id = _entity_id AND rr.closed_at IS NULL),
      'change_sets_pending', (SELECT count(*) FROM public.entity_change_sets cs
        WHERE cs.entity_id = _entity_id AND cs.status NOT IN ('applied','rejected'))));
  END IF;

  RETURN res;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.entity360_section(_entity_id uuid, _section text, _as_of timestamp with time zone DEFAULT NULL::timestamp with time zone, _limit integer DEFAULT 100, _offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  u uuid := auth.uid();
  lim int := LEAST(GREATEST(COALESCE(_limit,100),1), 500);
  off int := GREATEST(COALESCE(_offset,0),0);
  asof timestamptz := COALESCE(_as_of, now());
  rows jsonb := '[]'::jsonb;
BEGIN
  IF u IS NULL OR NOT public.is_internal_staff(u) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT public.e360_section_allowed(u, _section) THEN
    RETURN jsonb_build_object('section', _section, 'allowed', false, 'rows', '[]'::jsonb);
  END IF;

  IF _section = 'identity' THEN
    rows := COALESCE((SELECT jsonb_agg(x ORDER BY x->>'is_primary' DESC) FROM (
      SELECT jsonb_build_object('id', i.id, 'type', it.label, 'value', i.identifier_value,
        'normalized_value', i.normalized_value, 'scope', i.uniqueness_scope,
        'verification_status', i.verification_status, 'is_primary', i.is_primary,
        'effective_from', i.effective_from, 'effective_to', i.effective_to) AS x
      FROM public.entity_identifiers i
      LEFT JOIN public.entity_identifier_types it ON it.id = i.identifier_type_id
      WHERE i.entity_id = _entity_id
        AND (_as_of IS NULL OR (i.effective_from <= asof AND (i.effective_to IS NULL OR i.effective_to > asof)))
      LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'business_profile' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', f.id, 'concept', dc.label, 'concept_key', dc.key,
        'value', COALESCE(f.value_text, f.value_number::text, f.value_date::text,
                          f.value_datetime::text, f.value_boolean::text, f.value_json::text),
        'valid_from', f.valid_from, 'valid_to', f.valid_to,
        'approval_status', f.approval_status, 'verified_at', f.verified_at) AS x
      FROM public.entity_facts f
      LEFT JOIN public.data_concepts dc ON dc.id = f.data_concept_id
      WHERE f.entity_id = _entity_id AND f.superseded_at IS NULL
        AND (_as_of IS NULL OR (f.valid_from <= asof AND (f.valid_to IS NULL OR f.valid_to > asof)))
      ORDER BY dc.label LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'licences' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', li.id, 'license_number', li.license_number,
        'license_type', li.license_type, 'status', li.status, 'issued_at', li.issued_at,
        'valid_from', li.valid_from, 'valid_until', li.valid_until,
        'is_primary', el.is_primary, 'effective_from', el.effective_from,
        'effective_to', el.effective_to, 'source', el.source) AS x
      FROM public.entity_licenses el JOIN public.licenses li ON li.id = el.license_id
      WHERE el.entity_id = _entity_id
        AND (_as_of IS NULL OR (el.effective_from <= asof AND (el.effective_to IS NULL OR el.effective_to > asof)))
      ORDER BY el.is_primary DESC NULLS LAST, li.issued_at DESC NULLS LAST
      LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'ownership' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', oi.id, 'owner_party_id', oi.owner_party_id,
        'owner_name', p.display_name, 'owner_kind', p.party_kind,
        'economic_interest_percentage', oi.economic_interest_percentage,
        'voting_rights_percentage', oi.voting_rights_percentage,
        'beneficial_interest_percentage', oi.beneficial_interest_percentage,
        'is_direct', oi.is_direct, 'is_controller', oi.is_controller, 'is_ubo', oi.is_ubo,
        'approval_status', oi.approval_status, 'effective_from', oi.effective_from,
        'effective_to', oi.effective_to) AS x
      FROM public.ownership_interests oi
      LEFT JOIN public.parties p ON p.id = oi.owner_party_id
      WHERE oi.owned_entity_id = _entity_id
        AND (_as_of IS NULL
             OR (oi.effective_from <= asof
                 AND (oi.effective_to IS NULL OR oi.effective_to > asof)
                 AND (oi.superseded_at IS NULL OR oi.superseded_at > asof)))
      ORDER BY oi.economic_interest_percentage DESC NULLS LAST
      LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'relationships' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', r.id, 'related_entity_id', r.related_entity_id,
        'related_entity_name', COALESCE(r.related_entity_name, l2.name),
        'relationship_type', r.relationship_type, 'ownership_percentage', r.ownership_percentage,
        'status', r.status, 'effective_date', r.effective_date) AS x
      FROM public.entity_relationships r
      LEFT JOIN public.licensees l2 ON l2.id = r.related_entity_id
      WHERE r.entity_id = _entity_id
        AND (_as_of IS NULL OR r.effective_date IS NULL OR r.effective_date <= asof::date)
      ORDER BY r.created_at DESC LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'governance' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', a.id, 'person_party_id', a.person_party_id,
        'person_name', p.display_name, 'role', rt.label, 'role_key', rt.key,
        'is_executive', a.is_executive, 'status', a.status,
        'regulatory_approval_status', a.regulatory_approval_status,
        'appointment_date', a.appointment_date, 'effective_from', a.effective_from,
        'effective_to', a.effective_to, 'fp_individual_id', a.fp_individual_id) AS x
      FROM public.entity_appointments a
      LEFT JOIN public.parties p ON p.id = a.person_party_id
      LEFT JOIN public.role_types rt ON rt.id = a.role_type_id
      WHERE a.entity_id = _entity_id
        AND (_as_of IS NULL
             OR (a.effective_from <= asof
                 AND (a.effective_to IS NULL OR a.effective_to > asof)
                 AND (a.superseded_at IS NULL OR a.superseded_at > asof)))
      ORDER BY a.effective_from DESC LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'fit_and_proper' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', f.id, 'individual_name', ind.full_name,
        'assessment_type', f.assessment_type, 'status', f.status, 'pq_state', f.pq_state,
        'submitted_at', f.submitted_at, 'determined_at', f.determined_at,
        'closed_at', f.closed_at) AS x
      FROM public.fp_assessments f
      LEFT JOIN public.fp_individuals ind ON ind.id = f.individual_id
      WHERE f.licensee_id = _entity_id
      ORDER BY f.submitted_at DESC NULLS LAST LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'returns' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', rf.id, 'filing_reference', rf.filing_reference,
        'status', rf.status, 'period_label', p.period_label, 'due_date', p.due_date,
        'submitted_at', rf.submitted_at, 'accepted_at', rf.accepted_at,
        'version', rf.current_version_number, 'return_definition_id', rf.return_definition_id) AS x
      FROM public.return_filings rf
      LEFT JOIN public.reporting_periods p ON p.id = rf.reporting_period_id
      WHERE rf.entity_id = _entity_id
      ORDER BY p.due_date DESC NULLS LAST LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'risk' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', r.id, 'overall_rating', r.overall_rating,
        'risk_score', r.risk_score, 'assessment_date', r.assessment_date,
        'risk_factors', r.risk_factors, 'mitigation_measures', r.mitigation_measures) AS x
      FROM public.risk_ratings r WHERE r.entity_id = _entity_id
      ORDER BY r.assessment_date DESC NULLS LAST LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'supervision' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', sp.id, 'status', sp.status,
        'approval_status', sp.approval_status, 'created_from', sp.created_from,
        'created_at', sp.created_at,
        'open_actions', (SELECT count(*) FROM public.supervisory_plan_actions sa
          WHERE sa.plan_id = sp.id AND sa.status <> 'completed')) AS x
      FROM public.supervisory_plans sp WHERE sp.entity_id = _entity_id
      ORDER BY sp.created_at DESC LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'prudential' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', pa.id, 'period_start', pa.period_start,
        'period_end', pa.period_end, 'overall_rating', pa.overall_rating,
        'status', pa.status, 'conclusion', pa.conclusion, 'approved_at', pa.approved_at) AS x
      FROM public.prudential_assessments pa WHERE pa.entity_id = _entity_id
      ORDER BY pa.period_end DESC NULLS LAST LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'market_conduct' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', c.id, 'complaint_number', c.complaint_number,
        'subject', c.subject, 'status', c.status, 'severity', c.severity,
        'created_at', c.created_at, 'closed_at', c.closed_at, 'sla_due_at', c.sla_due_at) AS x
      FROM public.complaints c WHERE c.licensee_id = _entity_id
      ORDER BY c.created_at DESC LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'aml' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', a.id, 'reference', a.reference,
        'assessment_date', a.assessment_date, 'inherent_rating', a.inherent_rating,
        'control_rating', a.control_rating, 'residual_rating', a.residual_rating,
        'status', a.status, 'summary', a.summary,
        'confidential_notes', CASE WHEN public.e360_section_allowed(u,'aml_confidential')
                                   THEN a.confidential_notes ELSE NULL END,
        'next_review_date', a.next_review_date,
        'open_findings', (SELECT count(*) FROM public.aml_findings f
          WHERE f.aml_assessment_id = a.id AND f.status <> 'closed')) AS x
      FROM public.aml_assessments a WHERE a.entity_id = _entity_id
      ORDER BY a.assessment_date DESC LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'resilience' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('kind', 'arrangement', 'id', ra.id,
        'arrangement_type', ra.arrangement_type, 'provider_name', ra.provider_name,
        'criticality', ra.criticality, 'status', ra.status,
        'effective_from', ra.effective_from, 'last_assessed_at', ra.last_assessed_at) AS x,
        ra.created_at AS ord
      FROM public.resilience_arrangements ra WHERE ra.entity_id = _entity_id
      UNION ALL
      SELECT jsonb_build_object('kind', 'incident', 'id', ri.id, 'reference', ri.reference,
        'incident_type', ri.incident_type, 'severity', ri.severity,
        'occurred_at', ri.occurred_at, 'resolved_at', ri.resolved_at,
        'status', ri.status, 'summary', ri.summary), ri.created_at
      FROM public.resilience_incidents ri WHERE ri.entity_id = _entity_id
      ORDER BY ord DESC LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'examinations' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', e.id, 'reference', e.reference, 'title', e.title,
        'examination_type', e.examination_type, 'stage', e.stage, 'risk_rating', e.risk_rating,
        'fieldwork_start', e.fieldwork_start, 'fieldwork_end', e.fieldwork_end,
        'closed_at', e.closed_at,
        'open_findings', (SELECT count(*) FROM public.examination_findings ef
          WHERE ef.examination_id = e.id AND ef.status <> 'closed')) AS x
      FROM public.examinations e WHERE e.entity_id = _entity_id
      ORDER BY e.created_at DESC LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'enforcement' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', ea.id, 'case_number', ea.case_number,
        'enforcement_type', ea.enforcement_type, 'status', ea.status,
        'date_opened', ea.date_opened, 'penalty_amount', ea.penalty_amount,
        'decision_outcome', ea.decision_outcome, 'closed_at', ea.closed_at) AS x
      FROM public.enforcement_actions ea WHERE ea.entity_id = _entity_id
      ORDER BY ea.date_opened DESC NULLS LAST LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'regulatory_requests' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', rr.id, 'request_number', rr.request_number,
        'status', rr.status, 'priority', rr.priority, 'summary', rr.summary,
        'submitted_at', rr.submitted_at, 'decided_at', rr.decided_at,
        'closed_at', rr.closed_at, 'change_set_id', rr.change_set_id) AS x
      FROM public.regulatory_requests rr WHERE rr.entity_id = _entity_id
      ORDER BY rr.created_at DESC LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'correspondence' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', t.id, 'reference', t.reference, 'subject', t.subject,
        'channel', t.channel, 'direction', t.direction, 'status', t.status,
        'received_at', t.received_at, 'due_at', t.due_at, 'closed_at', t.closed_at) AS x
      FROM public.correspondence_threads t WHERE t.licensee_id = _entity_id
      ORDER BY COALESCE(t.last_message_at, t.created_at) DESC LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'documents' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', d.id, 'file_name', d.file_name,
        'file_path', d.file_path, 'file_size', d.file_size, 'mime_type', d.mime_type,
        'uploaded_at', d.created_at) AS x
      FROM public.documents d
      WHERE d.entity_id = _entity_id
        AND (_as_of IS NULL OR d.created_at <= asof)
      ORDER BY d.created_at DESC LIMIT lim OFFSET off) s), '[]'::jsonb);

  ELSIF _section = 'provenance' THEN
    rows := COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('id', cs.id, 'change_set_number', cs.change_set_number,
        'origin_type', cs.origin_type, 'status', cs.status, 'summary', cs.summary,
        'effective_date', cs.effective_date, 'submitted_at', cs.submitted_at,
        'approved_at', cs.approved_at, 'applied_at', cs.applied_at) AS x
      FROM public.entity_change_sets cs WHERE cs.entity_id = _entity_id
      ORDER BY cs.created_at DESC LIMIT lim OFFSET off) s), '[]'::jsonb);
  END IF;

  RETURN jsonb_build_object('section', _section, 'allowed', true,
    'as_of', _as_of, 'limit', lim, 'offset', off, 'rows', rows);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.entity360_timeline(_entity_id uuid, _domains text[] DEFAULT NULL::text[], _from timestamp with time zone DEFAULT NULL::timestamp with time zone, _to timestamp with time zone DEFAULT NULL::timestamp with time zone, _limit integer DEFAULT 100, _offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  u uuid := auth.uid();
  lim int := LEAST(GREATEST(COALESCE(_limit,100),1), 500);
  off int := GREATEST(COALESCE(_offset,0),0);
  total int;
  events jsonb;
BEGIN
  IF u IS NULL OR NOT public.is_internal_staff(u) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT public.e360_section_allowed(u, 'timeline') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS _e360_tl (
    occurred_at timestamptz, domain text, event_type text,
    title text, detail text, source_table text, source_id uuid
  ) ON COMMIT DROP;
  DELETE FROM _e360_tl;

  IF public.e360_section_allowed(u,'licences') THEN
    INSERT INTO _e360_tl
    SELECT el.effective_from, 'licensing', 'licence_linked',
      COALESCE(li.license_number, 'Licence'), li.license_type, 'entity_licenses', el.id
    FROM public.entity_licenses el LEFT JOIN public.licenses li ON li.id = el.license_id
    WHERE el.entity_id = _entity_id;
  END IF;

  IF public.e360_section_allowed(u,'ownership') THEN
    INSERT INTO _e360_tl
    SELECT oi.effective_from, 'ownership', 'ownership_recorded',
      COALESCE(p.display_name,'Owner'),
      concat_ws(' ', oi.economic_interest_percentage::text, '% economic interest'),
      'ownership_interests', oi.id
    FROM public.ownership_interests oi LEFT JOIN public.parties p ON p.id = oi.owner_party_id
    WHERE oi.owned_entity_id = _entity_id;

    INSERT INTO _e360_tl
    SELECT a.effective_from, 'governance', 'appointment_recorded',
      COALESCE(p.display_name,'Officer'), rt.label, 'entity_appointments', a.id
    FROM public.entity_appointments a
    LEFT JOIN public.parties p ON p.id = a.person_party_id
    LEFT JOIN public.role_types rt ON rt.id = a.role_type_id
    WHERE a.entity_id = _entity_id;
  END IF;

  IF public.e360_section_allowed(u,'returns') THEN
    INSERT INTO _e360_tl
    SELECT COALESCE(rf.submitted_at, rf.created_at), 'returns', 'filing_' || rf.status,
      rf.filing_reference, pr.period_label, 'return_filings', rf.id
    FROM public.return_filings rf
    LEFT JOIN public.reporting_periods pr ON pr.id = rf.reporting_period_id
    WHERE rf.entity_id = _entity_id;
  END IF;

  IF public.e360_section_allowed(u,'risk') THEN
    INSERT INTO _e360_tl
    SELECT COALESCE(r.assessment_date::timestamptz, r.created_at), 'risk', 'risk_rating_set',
      r.overall_rating, r.notes, 'risk_ratings', r.id
    FROM public.risk_ratings r WHERE r.entity_id = _entity_id;
  END IF;

  IF public.e360_section_allowed(u,'examinations') THEN
    INSERT INTO _e360_tl
    SELECT e.created_at, 'examination', 'examination_' || COALESCE(e.stage,'opened'),
      e.reference, e.title, 'examinations', e.id
    FROM public.examinations e WHERE e.entity_id = _entity_id;
  END IF;

  IF public.e360_section_allowed(u,'enforcement') THEN
    INSERT INTO _e360_tl
    SELECT COALESCE(ea.date_opened::timestamptz, ea.created_at), 'enforcement', 'enforcement_' || ea.status,
      ea.case_number, ea.enforcement_type, 'enforcement_actions', ea.id
    FROM public.enforcement_actions ea WHERE ea.entity_id = _entity_id;
  END IF;

  IF public.e360_section_allowed(u,'market_conduct') THEN
    INSERT INTO _e360_tl
    SELECT c.created_at, 'conduct', 'complaint_' || c.status, c.complaint_number, c.subject,
      'complaints', c.id
    FROM public.complaints c WHERE c.licensee_id = _entity_id;
  END IF;

  IF public.e360_section_allowed(u,'aml') THEN
    INSERT INTO _e360_tl
    SELECT a.assessment_date::timestamptz, 'aml', 'aml_assessment_' || a.status,
      a.reference, a.residual_rating, 'aml_assessments', a.id
    FROM public.aml_assessments a WHERE a.entity_id = _entity_id;
  END IF;

  IF public.e360_section_allowed(u,'resilience') THEN
    INSERT INTO _e360_tl
    SELECT ri.occurred_at, 'resilience', 'incident_' || ri.status, ri.reference, ri.summary,
      'resilience_incidents', ri.id
    FROM public.resilience_incidents ri WHERE ri.entity_id = _entity_id;
  END IF;

  IF public.e360_section_allowed(u,'regulatory_requests') THEN
    INSERT INTO _e360_tl
    SELECT rr.created_at, 'requests', 'request_' || rr.status, rr.request_number, rr.summary,
      'regulatory_requests', rr.id
    FROM public.regulatory_requests rr WHERE rr.entity_id = _entity_id;

    INSERT INTO _e360_tl
    SELECT cs.created_at, 'change', 'change_set_' || cs.status, cs.change_set_number, cs.summary,
      'entity_change_sets', cs.id
    FROM public.entity_change_sets cs WHERE cs.entity_id = _entity_id;
  END IF;

  IF public.e360_section_allowed(u,'correspondence') THEN
    INSERT INTO _e360_tl
    SELECT COALESCE(t.received_at, t.created_at), 'correspondence', 'thread_' || t.status,
      t.reference, t.subject, 'correspondence_threads', t.id
    FROM public.correspondence_threads t WHERE t.licensee_id = _entity_id;
  END IF;

  SELECT count(*) INTO total FROM _e360_tl
  WHERE occurred_at IS NOT NULL
    AND (_domains IS NULL OR domain = ANY(_domains))
    AND (_from IS NULL OR occurred_at >= _from)
    AND (_to IS NULL OR occurred_at <= _to);

  SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.occurred_at DESC), '[]'::jsonb) INTO events
  FROM (
    SELECT * FROM _e360_tl
    WHERE occurred_at IS NOT NULL
      AND (_domains IS NULL OR domain = ANY(_domains))
      AND (_from IS NULL OR occurred_at >= _from)
      AND (_to IS NULL OR occurred_at <= _to)
    ORDER BY occurred_at DESC
    LIMIT lim OFFSET off
  ) t;

  RETURN jsonb_build_object('total', total, 'limit', lim, 'offset', off, 'events', events);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.entity_attach_license(_entity_id uuid, _license_id uuid, _is_primary boolean DEFAULT false, _source text DEFAULT 'LICENCE_ISSUANCE'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); v_id uuid;
BEGIN
  INSERT INTO public.entity_licenses (entity_id, license_id, effective_from, is_primary, source)
  VALUES (_entity_id, _license_id, now(), _is_primary, _source)
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM public.entity_licenses WHERE entity_id=_entity_id AND license_id=_license_id LIMIT 1;
  ELSE
    PERFORM public.create_audit_log(uid, 'license.attached_to_entity', 'entity_license', v_id::text,
      NULL, jsonb_build_object('entity_id', _entity_id, 'license_id', _license_id), '{}'::jsonb);
  END IF;
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_change_set_create(_entity_id uuid, _items jsonb, _origin_type text DEFAULT 'FORM_SUBMISSION'::text, _summary text DEFAULT NULL::text, _effective_date date DEFAULT NULL::date, _source_submission_id uuid DEFAULT NULL::uuid, _source_form_version_id uuid DEFAULT NULL::uuid, _application_id uuid DEFAULT NULL::uuid, _regulatory_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_cs record; v_item jsonb; v_seq int := 0; v_baseline int;
BEGIN
  PERFORM public.wb_require('entity_structure','propose', _entity_id, 'submit_structural_form');
  SELECT structure_version INTO v_baseline FROM public.licensees WHERE id = _entity_id;
  IF v_baseline IS NULL THEN RAISE EXCEPTION 'Entity not found'; END IF;

  INSERT INTO public.entity_change_sets (entity_id, origin_type, application_id, regulatory_request_id,
    source_submission_id, source_form_version_id, summary, effective_date, baseline_version, created_by,
    status)
  VALUES (_entity_id, _origin_type, _application_id, _regulatory_request_id, _source_submission_id,
    _source_form_version_id, _summary, _effective_date, v_baseline, auth.uid(), 'DRAFT')
  RETURNING * INTO v_cs;

  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(_items,'[]'::jsonb)) LOOP
    v_seq := v_seq + 1;
    INSERT INTO public.entity_change_items (change_set_id, change_type, operation, data_concept_id,
      target_table, target_record_id, current_value, proposed_value, effective_from, effective_to,
      source_submission_id, form_field_definition_id, sequence)
    VALUES (v_cs.id, v_item->>'change_type', COALESCE(v_item->>'operation','UPSERT'),
      NULLIF(v_item->>'data_concept_id','')::uuid, v_item->>'target_table',
      NULLIF(v_item->>'target_record_id','')::uuid, v_item->'current_value',
      COALESCE(v_item->'proposed_value','{}'::jsonb),
      NULLIF(v_item->>'effective_from','')::timestamptz, NULLIF(v_item->>'effective_to','')::timestamptz,
      _source_submission_id, NULLIF(v_item->>'form_field_definition_id','')::uuid, v_seq);
  END LOOP;

  PERFORM public.create_audit_log(auth.uid(),'entity.change_set.created','entity_change_set',v_cs.id::text,NULL,
    jsonb_build_object('entity_id',_entity_id,'items',v_seq,'origin',_origin_type),NULL);
  RETURN jsonb_build_object('success',true,'change_set_id',v_cs.id,'items',v_seq);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_change_set_transition(_change_set_id uuid, _action text, _notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_cs record;
BEGIN
  SELECT * INTO v_cs FROM public.entity_change_sets WHERE id = _change_set_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Change set not found'; END IF;

  IF _action = 'submit' THEN
    PERFORM public.wb_require('entity_structure','propose', v_cs.entity_id, 'submit_structural_form');
    IF v_cs.status <> 'DRAFT' THEN RAISE EXCEPTION 'Only draft change sets can be submitted'; END IF;
    UPDATE public.entity_change_sets SET status='SUBMITTED', submitted_by=auth.uid(), submitted_at=now(),
      updated_at=now() WHERE id=_change_set_id;

  ELSIF _action = 'review' THEN
    PERFORM public.wb_require('entity_structure','review');
    UPDATE public.entity_change_sets SET status='RECOMMENDED', reviewed_by=auth.uid(), reviewed_at=now(),
      review_notes=_notes, updated_at=now() WHERE id=_change_set_id AND status IN ('SUBMITTED','UNDER_REVIEW');

  ELSIF _action = 'approve' THEN
    PERFORM public.wb_require('entity_structure','approve');
    IF v_cs.status NOT IN ('SUBMITTED','UNDER_REVIEW','RECOMMENDED') THEN
      RAISE EXCEPTION 'Change set cannot be approved from status %', v_cs.status;
    END IF;
    UPDATE public.entity_change_sets SET status='APPROVED', approved_by=auth.uid(), approved_at=now(),
      updated_at=now() WHERE id=_change_set_id;
    PERFORM public.create_audit_log(auth.uid(),'entity.change_set.approved','entity_change_set',
      _change_set_id::text,NULL,jsonb_build_object('entity_id',v_cs.entity_id),NULL);

  ELSIF _action = 'reject' THEN
    PERFORM public.wb_require('entity_structure','approve');
    UPDATE public.entity_change_sets SET status='REJECTED', rejected_by=auth.uid(), rejected_at=now(),
      rejection_reason=_notes, updated_at=now() WHERE id=_change_set_id;
    PERFORM public.create_audit_log(auth.uid(),'entity.change_set.rejected','entity_change_set',
      _change_set_id::text,NULL,jsonb_build_object('reason',_notes),NULL);
  ELSE
    RAISE EXCEPTION 'Unknown action %', _action;
  END IF;

  RETURN jsonb_build_object('success',true,'change_set_id',_change_set_id,'action',_action);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_conduct_summary(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _res jsonb;
BEGIN
  PERFORM public.conduct_require('market_conduct', 'view');
  SELECT jsonb_build_object(
    'open_items', count(*) FILTER (WHERE NOT i.is_terminal),
    'breached_items', count(*) FILTER (WHERE NOT i.is_terminal AND i.sla_state = 'breached'),
    'complaints_open', count(*) FILTER (WHERE NOT i.is_terminal AND i.kind = 'COMPLAINT'),
    'complaints_total', count(*) FILTER (WHERE i.kind = 'COMPLAINT'),
    'alerts_open', count(*) FILTER (WHERE NOT i.is_terminal AND i.kind = 'ALERT'),
    'investigations_open', count(*) FILTER (WHERE NOT i.is_terminal AND i.kind = 'INVESTIGATION'),
    'findings_open', count(*) FILTER (WHERE NOT i.is_terminal AND i.kind = 'FINDING'),
    'remediation_open', count(*) FILTER (WHERE NOT i.is_terminal AND i.kind = 'ACTION'),
    'items', coalesce(jsonb_agg(jsonb_build_object(
        'kind', i.kind, 'kind_label', i.kind_label, 'reference', i.reference,
        'subject', i.subject, 'stage_label', i.stage_label, 'sla_state', i.sla_state,
        'assigned_to_name', i.assigned_to_name, 'last_activity_at', i.last_activity_at,
        'canonical_href', i.canonical_href)
      ORDER BY i.last_activity_at DESC) FILTER (WHERE NOT i.is_terminal), '[]'::jsonb))
    INTO _res
  FROM public.v_conduct_work_items i
  WHERE i.entity_id = _entity_id;
  RETURN coalesce(_res, '{}'::jsonb);
END; $function$
;
CREATE OR REPLACE FUNCTION public.entity_create_local(_legal_name text, _identifiers jsonb DEFAULT '[]'::jsonb, _sector_id uuid DEFAULT NULL::uuid, _lifecycle_key text DEFAULT 'applicant'::text, _identity_status_key text DEFAULT 'provisional'::text, _case_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  v_party uuid; v_entity uuid; v_life uuid; v_ident uuid; v_type uuid; rec jsonb; v_norm text;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  IF btrim(COALESCE(_legal_name,'')) = '' THEN RAISE EXCEPTION 'legal_name is required' USING ERRCODE='22023'; END IF;

  SELECT id INTO v_life FROM public.lifecycle_stages WHERE key = _lifecycle_key;
  SELECT id INTO v_ident FROM public.entity_identity_statuses WHERE key = _identity_status_key;

  INSERT INTO public.parties (party_kind, display_name) VALUES ('ORGANIZATION', _legal_name)
  RETURNING id INTO v_party;
  -- Applicant-declared names are LOCAL_PROVISIONAL until a registry projection
  -- or verification promotes them (organizations_legal_name_authority_check).
  INSERT INTO public.organizations (party_id, legal_name, display_name, legal_name_authority)
  VALUES (v_party, _legal_name, _legal_name, 'LOCAL_PROVISIONAL');

  INSERT INTO public.licensees (name, sector_id, status, party_id, lifecycle_stage_id, identity_status_id, applicant_id)
  VALUES (_legal_name, _sector_id, 'active', v_party, v_life, v_ident, uid)
  RETURNING id INTO v_entity;

  FOR rec IN SELECT jsonb_array_elements(COALESCE(_identifiers,'[]'::jsonb)) LOOP
    SELECT id INTO v_type FROM public.entity_identifier_types WHERE key = rec->>'type' AND is_active;
    CONTINUE WHEN v_type IS NULL;
    v_norm := public.normalize_entity_identifier(v_type, rec->>'value');
    CONTINUE WHEN COALESCE(v_norm,'') = '';
    INSERT INTO public.entity_identifiers
      (entity_id, identifier_type_id, identifier_value, normalized_value, uniqueness_scope,
       is_primary, verification_status, source_type, effective_from)
    SELECT v_entity, v_type, rec->>'value', v_norm, t.uniqueness_scope, false, 'unverified', 'APPLICANT_DECLARED', now()
    FROM public.entity_identifier_types t WHERE t.id = v_type
    ON CONFLICT DO NOTHING;
  END LOOP;

  IF _case_id IS NOT NULL THEN
    INSERT INTO public.entity_resolution_events (case_id, event_type, actor_id, detail)
    VALUES (_case_id, 'entity.created', uid, jsonb_build_object('entity_id', v_entity));
  END IF;

  PERFORM public.create_audit_log(uid, 'entity.created', 'entity', v_entity::text,
    NULL, jsonb_build_object('legal_name', _legal_name, 'lifecycle', _lifecycle_key,
                             'identity_status', _identity_status_key), '{}'::jsonb);
  RETURN v_entity;
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_external_read_access(_user_id uuid, _entity_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT _user_id IS NOT NULL AND _entity_id IS NOT NULL AND (
    EXISTS (
      SELECT 1 FROM public.entity_user_access ea
      WHERE ea.user_id = _user_id
        AND ea.entity_id = _entity_id
        AND ea.is_active = true
        AND (ea.end_date IS NULL OR ea.end_date >= CURRENT_DATE)
    )
    OR public.entity_membership_capability(_user_id, _entity_id, 'returns.view')
  );
$function$
;
CREATE OR REPLACE FUNCTION public.entity_follow_merge(_entity_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid := _entity_id; v_next uuid; v_guard int := 0;
BEGIN
  WHILE v_id IS NOT NULL AND v_guard < 20 LOOP
    SELECT merged_into_entity_id INTO v_next FROM public.licensees WHERE id = v_id;
    IF v_next IS NULL THEN RETURN v_id; END IF;
    v_id := v_next; v_guard := v_guard + 1;
  END LOOP;
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_for_license(_license_id uuid, _application_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_entity_id uuid;
BEGIN
  -- 1. Canonical: the application is already bound to an entity.
  IF _application_id IS NOT NULL THEN
    SELECT entity_id INTO v_entity_id FROM public.applications WHERE id = _application_id;
  END IF;

  -- 2. Canonical multi-licence link table.
  IF v_entity_id IS NULL AND _license_id IS NOT NULL THEN
    SELECT el.entity_id INTO v_entity_id
      FROM public.entity_licenses el
      JOIN public.licensees l ON l.id = el.entity_id
     WHERE el.license_id = _license_id
     ORDER BY (l.merged_into_entity_id IS NULL) DESC,
              COALESCE(el.is_primary, false) DESC, el.effective_from
     LIMIT 1;
  END IF;

  -- 3. Documented legacy compatibility fallback only (licensees.license_id is
  --    compatibility-only; an entity may own many licences).
  IF v_entity_id IS NULL AND _license_id IS NOT NULL THEN
    SELECT id INTO v_entity_id FROM public.licensees
     WHERE license_id = _license_id ORDER BY created_at LIMIT 1;
  END IF;

  RETURN public.entity_follow_merge(v_entity_id);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_identifier_normalize()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_scope text; v_active boolean; v_key text;
BEGIN
  SELECT uniqueness_scope, is_active, key INTO v_scope, v_active, v_key
    FROM public.entity_identifier_types WHERE id = NEW.identifier_type_id;
  IF v_scope IS NULL THEN
    RAISE EXCEPTION 'Unknown identifier type %', NEW.identifier_type_id USING ERRCODE = '23503';
  END IF;
  IF NOT v_active THEN
    RAISE EXCEPTION 'Identifier type "%" is retired and cannot be used for entity identity', v_key USING ERRCODE = '23514';
  END IF;

  NEW.uniqueness_scope := v_scope;
  NEW.normalized_value := public.normalize_entity_identifier(NEW.identifier_type_id, NEW.identifier_value);
  IF NULLIF(btrim(COALESCE(NEW.normalized_value, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Identifier value normalises to an empty string under the configured strategy' USING ERRCODE = '22023';
  END IF;

  IF v_scope = 'JURISDICTION' AND NEW.jurisdiction_id IS NULL THEN
    RAISE EXCEPTION 'Identifier type requires a jurisdiction (uniqueness_scope = JURISDICTION)' USING ERRCODE = '23514';
  END IF;
  IF v_scope = 'ISSUER' AND NULLIF(btrim(COALESCE(NEW.issuer_key, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Identifier type requires an issuer (uniqueness_scope = ISSUER)' USING ERRCODE = '23514';
  END IF;
  IF v_scope = 'REGULATOR' AND NEW.regulator_id IS NULL THEN
    RAISE EXCEPTION 'Identifier type requires a regulator (uniqueness_scope = REGULATOR)' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_identity_snapshot_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_user IN ('postgres', 'supabase_admin') THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  RAISE EXCEPTION 'entity_identity_snapshots is append-only: % is not permitted', TG_OP USING ERRCODE = '42501';
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_license_summary(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH lic AS (
    SELECT l.* FROM public.licenses l
     WHERE l.application_id IN (SELECT a.id FROM public.applications a WHERE a.entity_id = _entity_id)
  )
  SELECT jsonb_build_object(
    'licences', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'license_id', l.id, 'license_number', l.license_number, 'license_type', l.license_type,
        'status', l.status, 'issued_at', l.issued_at, 'valid_from', l.valid_from, 'valid_until', l.valid_until,
        'open_matters', (SELECT count(*) FROM public.license_lifecycle_matters m
                          WHERE m.license_id = l.id AND m.status='open'),
        'open_conditions', (SELECT count(*) FROM public.license_conditions c
                             WHERE c.license_id = l.id AND c.status IN ('open','in_progress','evidence_due')),
        'outstanding_fees', (SELECT COALESCE(sum(f.amount),0) FROM public.license_fee_assessments f
                              WHERE f.license_id = l.id AND f.status IN ('due','paid')),
        'live_appeals', (SELECT count(*) FROM public.license_decision_appeals ap
                          WHERE ap.license_id = l.id AND ap.status NOT IN ('withdrawn','determined'))
      ) ORDER BY l.issued_at DESC) FROM lic l), '[]'::jsonb),
    'summary', COALESCE((SELECT jsonb_build_object(
        'total', count(*),
        'active', count(*) FILTER (WHERE status='active'),
        'suspended', count(*) FILTER (WHERE status='suspended'),
        'revoked', count(*) FILTER (WHERE status='revoked'),
        'expiring_90d', count(*) FILTER (WHERE valid_until IS NOT NULL
                          AND valid_until BETWEEN current_date AND current_date + 90))
      FROM lic), jsonb_build_object('total',0,'active',0,'suspended',0,'revoked',0,'expiring_90d',0))
  ) WHERE public.is_internal_staff_user(auth.uid());
$function$
;
CREATE OR REPLACE FUNCTION public.entity_link_license(_entity_id uuid, _license_id uuid, _application_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_from timestamptz;
BEGIN
  IF _entity_id IS NULL OR _license_id IS NULL THEN RETURN NULL; END IF;

  SELECT id INTO v_id FROM public.entity_licenses
   WHERE entity_id = _entity_id AND license_id = _license_id LIMIT 1;

  IF v_id IS NULL THEN
    SELECT COALESCE(valid_from, now()) INTO v_from FROM public.licenses WHERE id = _license_id;
    INSERT INTO public.entity_licenses (entity_id, license_id, effective_from, is_primary, source)
    VALUES (_entity_id, _license_id, COALESCE(v_from, now()),
            NOT EXISTS (SELECT 1 FROM public.entity_licenses WHERE entity_id = _entity_id),
            'LICENCE_ISSUANCE')
    RETURNING id INTO v_id;
  END IF;

  IF _application_id IS NOT NULL THEN
    UPDATE public.applications
       SET entity_id = _entity_id, updated_at = now()
     WHERE id = _application_id AND entity_id IS DISTINCT FROM _entity_id;
  END IF;

  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_membership_approve(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); v_row public.entity_user_memberships;
BEGIN
  IF NOT public.sec_has_permission(uid, 'entity_membership', 'approve') THEN
    RAISE EXCEPTION 'entity_membership.approve required' USING ERRCODE='42501';
  END IF;
  UPDATE public.entity_user_memberships
     SET status = 'APPROVED', approved_at = now(), approved_by = uid,
         effective_from = COALESCE(effective_from, now())
   WHERE id = _id AND status IN ('REQUESTED','PENDING_VERIFICATION')
  RETURNING * INTO v_row;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Membership not pending approval' USING ERRCODE='22023'; END IF;
  PERFORM public.create_audit_log(uid, 'entity.membership.approved', 'entity_user_membership', _id::text,
    NULL, jsonb_build_object('entity_id', v_row.entity_id, 'user_id', v_row.user_id), '{}'::jsonb);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_membership_capability(_user_id uuid, _entity_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH normalized AS (
    SELECT CASE _capability
             WHEN 'returns.view' THEN 'view_status'
             WHEN 'returns.submit' THEN 'submit'
             WHEN 'returns.respond' THEN 'respond_rfi'
             ELSE _capability
           END AS cap
  )
  SELECT EXISTS (
    SELECT 1 FROM public.entity_user_memberships m
      JOIN public.entity_membership_roles r ON r.id = m.membership_role_id
      LEFT JOIN public.entity_membership_role_permissions p ON p.membership_role_id = r.id
      CROSS JOIN normalized n
     WHERE m.user_id = _user_id
       AND m.entity_id = _entity_id
       AND m.status = 'APPROVED'
       AND (m.effective_to IS NULL OR m.effective_to > now())
       AND (p.capability = n.cap OR r.is_primary_representative)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.entity_membership_directory(_query text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE q text := btrim(COALESCE(_query,'')); qn text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  IF length(q) < 3 THEN RETURN '[]'::jsonb; END IF;
  qn := upper(regexp_replace(q, '[^A-Za-z0-9]', '', 'g'));

  RETURN COALESCE((
    SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object(
               'entity_id', l.id,
               'legal_name', COALESCE(o.legal_name, l.name),
               'lifecycle', ls.key
             ) AS x
      FROM public.licensees l
      LEFT JOIN public.organizations o ON o.party_id = l.party_id
      LEFT JOIN public.lifecycle_stages ls ON ls.id = l.lifecycle_stage_id
      WHERE l.merged_into_entity_id IS NULL
        AND (l.name ILIKE '%'||q||'%'
             OR o.legal_name ILIKE '%'||q||'%'
             OR EXISTS (SELECT 1 FROM public.entity_identifiers ei
                         WHERE ei.entity_id = l.id AND ei.normalized_value = qn))
      ORDER BY COALESCE(o.legal_name, l.name)
      LIMIT 20
    ) s
  ), '[]'::jsonb);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_membership_reject(_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid();
BEGIN
  IF NOT public.sec_has_permission(uid, 'entity_membership', 'approve') THEN
    RAISE EXCEPTION 'entity_membership.approve required' USING ERRCODE='42501';
  END IF;
  UPDATE public.entity_user_memberships
     SET status='REJECTED', rejected_at = now(), rejected_by = uid, revocation_reason = _reason
   WHERE id = _id AND status IN ('REQUESTED','PENDING_VERIFICATION');
  IF NOT FOUND THEN RAISE EXCEPTION 'Membership not pending' USING ERRCODE='22023'; END IF;
  PERFORM public.create_audit_log(uid, 'entity.membership.rejected', 'entity_user_membership', _id::text,
    NULL, jsonb_build_object('reason', _reason), '{}'::jsonb);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_membership_request(_entity_id uuid, _membership_role_key text, _authority_evidence_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); v_role uuid; v_id uuid;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  SELECT id INTO v_role FROM public.entity_membership_roles WHERE key = _membership_role_key AND is_active;
  IF v_role IS NULL THEN RAISE EXCEPTION 'Unknown membership role %', _membership_role_key USING ERRCODE='22023'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.licensees WHERE id = _entity_id) THEN
    RAISE EXCEPTION 'Unknown entity %', _entity_id USING ERRCODE='23503';
  END IF;

  INSERT INTO public.entity_user_memberships (user_id, entity_id, membership_role_id, status, requested_by, requested_at)
  VALUES (uid, _entity_id, v_role, 'PENDING_VERIFICATION', uid, now())
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM public.entity_user_memberships
    WHERE user_id = uid AND entity_id = _entity_id AND membership_role_id = v_role
      AND status IN ('REQUESTED','PENDING_VERIFICATION','APPROVED');
  ELSE
    UPDATE public.entity_user_memberships
      SET authority_evidence_reference = _authority_evidence_reference WHERE id = v_id;
    PERFORM public.create_audit_log(uid, 'entity.membership.requested', 'entity_user_membership', v_id::text,
      NULL, jsonb_build_object('entity_id', _entity_id, 'membership_role', _membership_role_key), '{}'::jsonb);
  END IF;
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_membership_revoke(_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid();
BEGIN
  IF NOT public.sec_has_permission(uid, 'entity_membership', 'revoke') THEN
    RAISE EXCEPTION 'entity_membership.revoke required' USING ERRCODE='42501';
  END IF;
  UPDATE public.entity_user_memberships
     SET status='REVOKED', revoked_at = now(), revoked_by = uid,
         revocation_reason = _reason, effective_to = now()
   WHERE id = _id AND status = 'APPROVED';
  IF NOT FOUND THEN RAISE EXCEPTION 'Membership is not approved' USING ERRCODE='22023'; END IF;
  PERFORM public.create_audit_log(uid, 'entity.membership.revoked', 'entity_user_membership', _id::text,
    NULL, jsonb_build_object('reason', _reason), '{}'::jsonb);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_membership_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END $function$
;
CREATE OR REPLACE FUNCTION public.entity_membership_verify(_id uuid, _notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid();
BEGIN
  IF NOT public.sec_has_permission(uid, 'entity_membership', 'verify') THEN
    RAISE EXCEPTION 'entity_membership.verify required' USING ERRCODE='42501';
  END IF;
  UPDATE public.entity_user_memberships
     SET verified_at = now(), verified_by = uid, status = 'PENDING_VERIFICATION'
   WHERE id = _id AND status IN ('REQUESTED','PENDING_VERIFICATION');
  IF NOT FOUND THEN RAISE EXCEPTION 'Membership not open for verification' USING ERRCODE='22023'; END IF;
  PERFORM public.create_audit_log(uid, 'entity.identity.verified', 'entity_user_membership', _id::text,
    NULL, jsonb_build_object('notes', _notes), '{}'::jsonb);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_merge_execute(_survivor_entity_id uuid, _absorbed_entity_id uuid, _reason text, _case_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  v_merge uuid;
  v_before jsonb;
  v_preview jsonb;
  v_merged_status uuid;
BEGIN
  IF NOT public.sec_has_permission(uid,'entity_resolution','merge') THEN
    RAISE EXCEPTION 'entity_resolution.merge required' USING ERRCODE='42501'; END IF;
  IF btrim(COALESCE(_reason,'')) = '' THEN
    RAISE EXCEPTION 'A merge reason is required' USING ERRCODE='22023'; END IF;
  IF _survivor_entity_id = _absorbed_entity_id THEN
    RAISE EXCEPTION 'Survivor and absorbed entity must differ' USING ERRCODE='22023'; END IF;
  IF (SELECT merged_into_entity_id FROM public.licensees WHERE id = _absorbed_entity_id) IS NOT NULL THEN
    RAISE EXCEPTION 'Absorbed entity is already merged' USING ERRCODE='22023'; END IF;

  v_preview := public.entity_merge_preview(_survivor_entity_id, _absorbed_entity_id);
  v_before := jsonb_build_object(
    'survivor', public.entity_registry_entity_dto(_survivor_entity_id),
    'absorbed', public.entity_registry_entity_dto(_absorbed_entity_id));

  INSERT INTO public.entity_merges
    (survivor_entity_id, absorbed_entity_id, case_id, status, reason, impact_preview,
     before_snapshot, requested_by, approved_by, approved_at)
  VALUES (_survivor_entity_id, _absorbed_entity_id, _case_id, 'APPROVED', _reason, v_preview,
          v_before, uid, uid, now())
  RETURNING id INTO v_merge;

  PERFORM public.create_audit_log(uid, 'entity.merge.approved', 'entity_merge', v_merge::text,
    NULL, jsonb_build_object('survivor', _survivor_entity_id, 'absorbed', _absorbed_entity_id,
                             'reason', _reason), '{}'::jsonb);

  -- Repoint approved child lineage. Nothing is deleted.
  UPDATE public.entity_licenses SET entity_id = _survivor_entity_id, updated_at = now()
   WHERE entity_id = _absorbed_entity_id;
  UPDATE public.entity_identifiers SET entity_id = _survivor_entity_id, updated_at = now()
   WHERE entity_id = _absorbed_entity_id
     AND NOT EXISTS (
       SELECT 1 FROM public.entity_identifiers s
       WHERE s.entity_id = _survivor_entity_id
         AND s.identifier_type_id = public.entity_identifiers.identifier_type_id
         AND s.normalized_value = public.entity_identifiers.normalized_value);
  UPDATE public.entity_external_references SET entity_id = _survivor_entity_id, updated_at = now()
   WHERE entity_id = _absorbed_entity_id;
  UPDATE public.applications SET entity_id = _survivor_entity_id, updated_at = now()
   WHERE entity_id = _absorbed_entity_id;
  UPDATE public.entity_user_memberships SET entity_id = _survivor_entity_id
   WHERE entity_id = _absorbed_entity_id
     AND NOT EXISTS (
       SELECT 1 FROM public.entity_user_memberships s
       WHERE s.entity_id = _survivor_entity_id
         AND s.user_id = public.entity_user_memberships.user_id
         AND s.membership_role_id = public.entity_user_memberships.membership_role_id
         AND s.status IN ('REQUESTED','PENDING_VERIFICATION','APPROVED'));

  SELECT id INTO v_merged_status FROM public.entity_identity_statuses WHERE key = 'merged';
  UPDATE public.licensees
     SET merged_into_entity_id = _survivor_entity_id,
         identity_status_id = COALESCE(v_merged_status, identity_status_id),
         updated_at = now()
   WHERE id = _absorbed_entity_id;

  UPDATE public.entity_merges
     SET status='COMPLETED', completed_at = now(),
         after_snapshot = jsonb_build_object(
           'survivor', public.entity_registry_entity_dto(_survivor_entity_id),
           'absorbed', public.entity_registry_entity_dto(_absorbed_entity_id))
   WHERE id = v_merge;

  IF _case_id IS NOT NULL THEN
    UPDATE public.entity_resolution_cases
       SET status='RESOLVED', outcome='MERGED', resolved_entity_id=_survivor_entity_id,
           resolved_by=uid, resolved_at=now()
     WHERE id=_case_id;
    INSERT INTO public.entity_resolution_events (case_id, event_type, actor_id, detail)
    VALUES (_case_id, 'entity.merge.completed', uid,
            jsonb_build_object('merge_id', v_merge, 'survivor', _survivor_entity_id));
  END IF;

  PERFORM public.create_audit_log(uid, 'entity.merge.completed', 'entity_merge', v_merge::text,
    v_before, jsonb_build_object('survivor', _survivor_entity_id, 'absorbed', _absorbed_entity_id), '{}'::jsonb);

  RETURN v_merge;
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_merge_preview(_survivor_entity_id uuid, _absorbed_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid();
BEGIN
  IF NOT public.sec_has_permission(uid,'entity_resolution','view') THEN
    RAISE EXCEPTION 'entity_resolution.view required' USING ERRCODE='42501'; END IF;
  IF _survivor_entity_id = _absorbed_entity_id THEN
    RAISE EXCEPTION 'Survivor and absorbed entity must differ' USING ERRCODE='22023'; END IF;

  RETURN jsonb_build_object(
    'survivor', public.entity_registry_entity_dto(_survivor_entity_id),
    'absorbed', public.entity_registry_entity_dto(_absorbed_entity_id),
    'impact', jsonb_build_object(
      'licences', (SELECT count(*) FROM public.entity_licenses WHERE entity_id = _absorbed_entity_id),
      'identifiers', (SELECT count(*) FROM public.entity_identifiers WHERE entity_id = _absorbed_entity_id),
      'external_references', (SELECT count(*) FROM public.entity_external_references WHERE entity_id = _absorbed_entity_id),
      'applications', (SELECT count(*) FROM public.applications WHERE entity_id = _absorbed_entity_id),
      'memberships', (SELECT count(*) FROM public.entity_user_memberships WHERE entity_id = _absorbed_entity_id)
    ));
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_onboarding_activity(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT public.onboarding_can_view_audit(auth.uid()) THEN
    RAISE EXCEPTION 'Not permitted to read onboarding activity' USING ERRCODE='42501';
  END IF;
  SELECT jsonb_build_object(
    'identity_matches', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'event_reference', e.event_reference, 'occurred_at', e.occurred_at,
        'searched_legal_name', e.searched_legal_name, 'outcome', e.resolution_outcome,
        'match_basis', e.match_basis, 'journey_type', e.journey_type,
        'user_email', COALESCE(p.email, plu.email), 'follow_up_action', e.follow_up_action)
        ORDER BY e.occurred_at DESC)
      FROM public.entity_identity_resolution_events e
      LEFT JOIN public.profiles p ON p.id = e.user_id
      LEFT JOIN public.pre_license_users plu ON plu.id = e.user_id
      WHERE e.matched_entity_id = _entity_id OR _entity_id = ANY(e.candidate_entity_ids)), '[]'::jsonb),
    'membership_requests', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', m.id, 'status', m.status, 'requested_at', m.requested_at, 'approved_at', m.approved_at,
        'user_email', COALESCE(p.email, plu.email), 'role', r.label) ORDER BY m.requested_at DESC)
      FROM public.entity_user_memberships m
      LEFT JOIN public.entity_membership_roles r ON r.id = m.membership_role_id
      LEFT JOIN public.profiles p ON p.id = m.user_id
      LEFT JOIN public.pre_license_users plu ON plu.id = m.user_id
      WHERE m.entity_id = _entity_id), '[]'::jsonb),
    'resolution_cases', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', c.id, 'case_number', c.case_number, 'status', c.status,
        'outcome', c.outcome, 'subject_name', c.subject_name, 'created_at', c.created_at) ORDER BY c.created_at DESC)
      FROM public.entity_resolution_cases c WHERE c.resolved_entity_id = _entity_id), '[]'::jsonb))
  INTO v;
  RETURN v;
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_public_slug_assign()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE base text; candidate text; n int := 0;
BEGIN
  IF NEW.publication_policy_id IS NULL THEN
    SELECT id INTO NEW.publication_policy_id FROM public.registry_publication_policies WHERE is_default AND is_active LIMIT 1;
  END IF;
  IF NEW.public_slug IS NULL THEN
    base := trim(both '-' from COALESCE(NULLIF(regexp_replace(lower(COALESCE(NEW.name,'entity')), '[^a-z0-9]+', '-', 'g'),''),'entity'));
    candidate := left(base, 60);
    WHILE EXISTS (SELECT 1 FROM public.licensees WHERE public_slug = candidate) LOOP
      n := n + 1;
      candidate := left(base, 55) || '-' || n::text;
    END LOOP;
    NEW.public_slug := candidate;
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_registry_entity_dto(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'source', 'LOCAL',
    'entity_id', l.id,
    'legal_name', COALESCE(o.legal_name, l.name),
    'display_name', COALESCE(o.display_name, l.name),
    'lifecycle', ls.key,
    'lifecycle_label', ls.label,
    'identity_status', ist.key,
    'identity_status_label', ist.label,
    'merged_into_entity_id', l.merged_into_entity_id,
    'sector_id', l.sector_id,
    'assigned_supervisor_id', l.assigned_supervisor_id,
    'identifiers', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'type', t.key, 'label', t.label, 'value', ei.identifier_value,
        'normalized_value', ei.normalized_value,
        'verification_status', ei.verification_status,
        'is_primary', ei.is_primary) ORDER BY t.sort_order)
      FROM public.entity_identifiers ei
      JOIN public.entity_identifier_types t ON t.id = ei.identifier_type_id
      WHERE ei.entity_id = l.id AND (ei.effective_to IS NULL OR ei.effective_to > now())
    ), '[]'::jsonb),
    'licences', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'license_id', lic.id, 'license_number', lic.license_number,
        'license_type', lic.license_type, 'status', lic.status,
        'valid_until', lic.valid_until, 'is_primary', el.is_primary,
        'effective_from', el.effective_from) ORDER BY el.effective_from DESC)
      FROM public.entity_licenses el
      JOIN public.licenses lic ON lic.id = el.license_id
      WHERE el.entity_id = l.id
    ), '[]'::jsonb),
    'external_references', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'external_entity_id', x.external_entity_id,
        'verification_status', x.verification_status,
        'is_authoritative', x.is_authoritative,
        'last_verified_at', x.last_verified_at))
      FROM public.entity_external_references x
      WHERE x.entity_id = l.id AND (x.effective_to IS NULL OR x.effective_to > now())
    ), '[]'::jsonb)
  )
  FROM public.licensees l
  LEFT JOIN public.organizations o ON o.party_id = l.party_id
  LEFT JOIN public.lifecycle_stages ls ON ls.id = l.lifecycle_stage_id
  LEFT JOIN public.entity_identity_statuses ist ON ist.id = l.identity_status_id
  WHERE l.id = _entity_id;
$function$
;
CREATE OR REPLACE FUNCTION public.entity_registry_search(_criteria jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  q text := btrim(COALESCE(_criteria->>'query',''));
  qn text := upper(regexp_replace(q, '[^A-Za-z0-9]', '', 'g'));
  lim int := LEAST(COALESCE((_criteria->>'limit')::int, 50), 200);
  ids uuid[];
BEGIN
  IF NOT public.sec_has_permission(auth.uid(), 'licensee_management', 'view')
     AND NOT public.sec_has_permission(auth.uid(), 'entity_resolution', 'view') THEN
    RAISE EXCEPTION 'licensee_management.view or entity_resolution.view required' USING ERRCODE='42501';
  END IF;

  SELECT array_agg(id) INTO ids FROM (
    SELECT l.id
    FROM public.licensees l
    LEFT JOIN public.organizations o ON o.party_id = l.party_id
    WHERE q = ''
       OR l.name ILIKE '%'||q||'%'
       OR o.legal_name ILIKE '%'||q||'%'
       OR EXISTS (
         SELECT 1 FROM public.entity_identifiers ei
         WHERE ei.entity_id = l.id AND (qn <> '' AND ei.normalized_value = qn)
       )
       OR EXISTS (
         SELECT 1 FROM public.entity_licenses el
         JOIN public.licenses lic ON lic.id = el.license_id
         WHERE el.entity_id = l.id AND qn <> ''
           AND upper(regexp_replace(lic.license_number, '[^A-Za-z0-9]', '', 'g')) = qn
       )
    ORDER BY l.name
    LIMIT lim
  ) s;

  RETURN COALESCE((
    SELECT jsonb_agg(public.entity_registry_entity_dto(x)) FROM unnest(COALESCE(ids,'{}'::uuid[])) x
  ), '[]'::jsonb);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_relationship_delete(_relationship_id uuid, _reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record;
BEGIN
  PERFORM public.enforce_permission('license_management','edit');
  SELECT * INTO _prev FROM public.entity_relationships WHERE id = _relationship_id;
  IF _prev IS NULL THEN RETURN; END IF;
  DELETE FROM public.entity_relationships WHERE id = _relationship_id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'entity.relationship.deleted','entity_relationship',_relationship_id,
          jsonb_build_object('before',to_jsonb(_prev),'reason',_reason));
END; $function$
;
CREATE OR REPLACE FUNCTION public.entity_relationship_save(_entity_id uuid, _related_entity_name text, _relationship_type text, _relationship_id uuid DEFAULT NULL::uuid, _related_entity_id uuid DEFAULT NULL::uuid, _ownership_percentage numeric DEFAULT NULL::numeric, _effective_date date DEFAULT NULL::date, _status text DEFAULT 'active'::text, _notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('license_management','edit');
  IF _related_entity_name IS NULL OR btrim(_related_entity_name) = '' THEN
    RAISE EXCEPTION 'related entity name is required' USING ERRCODE='22023';
  END IF;
  IF _ownership_percentage IS NOT NULL AND (_ownership_percentage < 0 OR _ownership_percentage > 100) THEN
    RAISE EXCEPTION 'ownership percentage must be between 0 and 100' USING ERRCODE='22023';
  END IF;
  IF _relationship_id IS NULL THEN
    INSERT INTO public.entity_relationships (entity_id, related_entity_id, related_entity_name,
      relationship_type, ownership_percentage, effective_date, status, notes)
    VALUES (_entity_id, _related_entity_id, btrim(_related_entity_name),
            COALESCE(NULLIF(_relationship_type,''),'associate'), _ownership_percentage,
            _effective_date, COALESCE(_status,'active'), _notes)
    RETURNING * INTO _row;
  ELSE
    SELECT * INTO _prev FROM public.entity_relationships WHERE id = _relationship_id FOR UPDATE;
    IF _prev IS NULL THEN RAISE EXCEPTION 'relationship not found' USING ERRCODE='22023'; END IF;
    UPDATE public.entity_relationships
       SET related_entity_id = _related_entity_id,
           related_entity_name = btrim(_related_entity_name),
           relationship_type = COALESCE(NULLIF(_relationship_type,''),'associate'),
           ownership_percentage = _ownership_percentage,
           effective_date = _effective_date,
           status = COALESCE(_status,'active'),
           notes = _notes
     WHERE id = _relationship_id RETURNING * INTO _row;
  END IF;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid, CASE WHEN _relationship_id IS NULL THEN 'entity.relationship.created' ELSE 'entity.relationship.updated' END,
          'entity_relationship', _row.id,
          jsonb_build_object('entity_id',_entity_id,'before',to_jsonb(_prev),'after',to_jsonb(_row)));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.entity_resolution_case_view(_case_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); c public.entity_resolution_cases; b public.registration_entity_bindings;
BEGIN
  IF uid IS NULL OR NOT public.sec_has_permission(uid,'entity_resolution','view') THEN
    RAISE EXCEPTION 'entity_resolution.view required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO c FROM public.entity_resolution_cases WHERE id = _case_id;
  IF c.id IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO b FROM public.registration_entity_bindings WHERE resolution_case_id = _case_id;

  RETURN jsonb_build_object(
    'detail', jsonb_build_object(
      'id', c.id, 'case_number', c.case_number, 'status', c.status, 'outcome', c.outcome,
      'subject_name', c.subject_name, 'subject_identifiers', c.subject_identifiers,
      'provider_status', c.provider_status, 'authority_mode', c.authority_mode,
      'requires_maker_checker', public.entity_resolution_requires_maker_checker(_case_id),
      'application_id', c.application_id,
      'resolved_entity_id', c.resolved_entity_id,
      'resolved_entity_name', (SELECT COALESCE(o.legal_name, l.name) FROM public.licensees l
                                 LEFT JOIN public.organizations o ON o.party_id = l.party_id
                                WHERE l.id = c.resolved_entity_id),
      'decision_notes', c.decision_notes,
      'requested_at', c.requested_at, 'resolved_at', c.resolved_at,
      'resolved_by', c.resolved_by,
      'resolved_by_name', (SELECT COALESCE(full_name, email) FROM public.profiles WHERE id = c.resolved_by),
      'recommended_action', c.recommended_action,
      'recommended_entity_id', c.recommended_entity_id,
      'recommended_entity_name', (SELECT COALESCE(o.legal_name, l.name) FROM public.licensees l
                                    LEFT JOIN public.organizations o ON o.party_id = l.party_id
                                   WHERE l.id = c.recommended_entity_id),
      'recommended_by', c.recommended_by,
      'recommended_by_name', (SELECT COALESCE(full_name, email) FROM public.profiles WHERE id = c.recommended_by),
      'recommended_at', c.recommended_at, 'recommendation_notes', c.recommendation_notes,
      'escalated_by', c.escalated_by,
      'escalated_by_name', (SELECT COALESCE(full_name, email) FROM public.profiles WHERE id = c.escalated_by),
      'escalated_at', c.escalated_at, 'escalation_reason', c.escalation_reason,
      'supervisor_decision', c.supervisor_decision, 'supervisor_notes', c.supervisor_notes,
      'supervisor_decided_by', c.supervisor_decided_by,
      'supervisor_decided_by_name', (SELECT COALESCE(full_name, email) FROM public.profiles WHERE id = c.supervisor_decided_by),
      'supervisor_decided_at', c.supervisor_decided_at,
      'approved_by', c.approved_by, 'approved_at', c.approved_at
    ),
    'journey', jsonb_build_object(
      'journey_type', COALESCE(c.subject_payload->>'journey_type',
                               CASE WHEN b.registration_id IS NOT NULL THEN 'FORM_FIRST' ELSE 'ENTITY_FIRST' END),
      'registration_id', b.registration_id,
      'registration_reference', (SELECT registration_reference FROM public.registrations WHERE id = b.registration_id),
      'binding_status', b.binding_status,
      'applicant_name', (SELECT applicant_name FROM public.registrations WHERE id = b.registration_id),
      'applicant_email', (SELECT email FROM public.registrations WHERE id = b.registration_id),
      'sector_name', (SELECT s.name FROM public.registrations r JOIN public.sectors s ON s.id = r.sector_id WHERE r.id = b.registration_id),
      'initiated_at', COALESCE((SELECT created_at FROM public.registrations WHERE id = b.registration_id), c.requested_at)
    ),
    'candidates', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', mc.id, 'entity_id', mc.entity_id,
        'entity_name', COALESCE(o.legal_name, l.name),
        'lifecycle', COALESCE((SELECT ls.label FROM public.lifecycle_stages ls WHERE ls.id = l.lifecycle_stage_id), l.status),
        'licence_numbers', COALESCE((SELECT jsonb_agg(lic.license_number)
                                       FROM public.entity_licenses el
                                       JOIN public.licenses lic ON lic.id = el.license_id
                                      WHERE el.entity_id = mc.entity_id), '[]'::jsonb),
        'match_score', mc.match_score, 'match_basis', mc.match_basis,
        'signals', mc.signals, 'is_selected', mc.is_selected)
        ORDER BY mc.match_score DESC)
      FROM public.entity_match_candidates mc
      LEFT JOIN public.licensees l ON l.id = mc.entity_id
      LEFT JOIN public.organizations o ON o.party_id = l.party_id
      WHERE mc.case_id = _case_id), '[]'::jsonb),
    'events', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', e.id, 'event_type', e.event_type, 'created_at', e.created_at,
        'actor_id', e.actor_id,
        'actor_name', (SELECT COALESCE(full_name, email) FROM public.profiles WHERE id = e.actor_id),
        'detail', e.detail) ORDER BY e.created_at DESC)
      FROM public.entity_resolution_events e WHERE e.case_id = _case_id), '[]'::jsonb)
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_resolution_decide(_case_id uuid, _action text, _entity_id uuid DEFAULT NULL::uuid, _notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  c public.entity_resolution_cases;
  v_entity uuid;
  v_event text;
  v_mc boolean;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  SELECT * INTO c FROM public.entity_resolution_cases WHERE id = _case_id FOR UPDATE;
  IF c.id IS NULL THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='22023'; END IF;
  IF c.status IN ('RESOLVED','REJECTED','CLOSED') THEN
    RAISE EXCEPTION 'Case is already closed' USING ERRCODE='22023'; END IF;

  v_mc := public.entity_resolution_requires_maker_checker(_case_id);

  IF _action IN ('RECOMMEND_EXISTING','RECOMMEND_NEW') THEN
    IF NOT public.sec_has_permission(uid,'entity_resolution','resolve') THEN
      RAISE EXCEPTION 'entity_resolution.resolve required' USING ERRCODE='42501'; END IF;
    IF COALESCE(length(btrim(_notes)),0) < 10 THEN
      RAISE EXCEPTION 'A recommendation rationale is required' USING ERRCODE='22023'; END IF;
    IF _action = 'RECOMMEND_EXISTING' AND _entity_id IS NULL THEN
      RAISE EXCEPTION 'entity_id required' USING ERRCODE='22023'; END IF;

    UPDATE public.entity_resolution_cases
       SET recommended_action = CASE WHEN _action='RECOMMEND_EXISTING' THEN 'RESOLVE_EXISTING' ELSE 'CONFIRM_NEW' END,
           recommended_entity_id = CASE WHEN _action='RECOMMEND_EXISTING' THEN _entity_id ELSE NULL END,
           recommended_by = uid, recommended_at = now(), recommendation_notes = btrim(_notes),
           status = 'PENDING_REVIEW',
           supervisor_decision = NULL, supervisor_notes = NULL,
           supervisor_decided_by = NULL, supervisor_decided_at = NULL
     WHERE id = _case_id;
    v_entity := _entity_id;
    v_event := CASE WHEN _action='RECOMMEND_EXISTING' THEN 'entity.resolution.recommended_existing'
                    ELSE 'entity.resolution.recommended_new' END;

  ELSIF _action IN ('RESOLVE_EXISTING','CONFIRM_NEW') THEN
    IF NOT public.sec_has_permission(uid,'entity_resolution','resolve') THEN
      RAISE EXCEPTION 'entity_resolution.resolve required' USING ERRCODE='42501'; END IF;
    IF c.status = 'ESCALATED' AND NOT public.sec_has_permission(uid,'entity_resolution','approve') THEN
      RAISE EXCEPTION 'Escalated cases require entity_resolution.approve' USING ERRCODE='42501'; END IF;
    IF v_mc AND c.status <> 'ESCALATED' AND NOT public.sec_has_permission(uid,'entity_resolution','approve') THEN
      RAISE EXCEPTION 'Supervisory approval is required: record a recommendation and escalate' USING ERRCODE='42501';
    END IF;
    v_entity := public.entity_resolution_finalise(_case_id, _action, _entity_id, uid,
                  CASE WHEN c.status='ESCALATED' THEN uid ELSE NULL END, _notes);
    RETURN jsonb_build_object('case_id', _case_id, 'entity_id', v_entity, 'action', _action);

  ELSIF _action = 'REQUEST_EVIDENCE' THEN
    IF NOT (public.sec_has_permission(uid,'entity_resolution','verify')
            OR public.sec_has_permission(uid,'entity_resolution','approve')) THEN
      RAISE EXCEPTION 'entity_resolution.verify required' USING ERRCODE='42501'; END IF;
    IF COALESCE(length(btrim(_notes)),0) < 10 THEN
      RAISE EXCEPTION 'An explanation of the evidence required is mandatory' USING ERRCODE='22023'; END IF;
    UPDATE public.entity_resolution_cases
       SET status='EVIDENCE_REQUESTED', decision_notes = btrim(_notes),
           supervisor_decision = CASE WHEN c.status='ESCALATED' THEN 'EVIDENCE_REQUESTED' ELSE supervisor_decision END,
           supervisor_notes = CASE WHEN c.status='ESCALATED' THEN btrim(_notes) ELSE supervisor_notes END,
           supervisor_decided_by = CASE WHEN c.status='ESCALATED' THEN uid ELSE supervisor_decided_by END,
           supervisor_decided_at = CASE WHEN c.status='ESCALATED' THEN now() ELSE supervisor_decided_at END
     WHERE id = _case_id;
    v_event := 'entity.resolution.evidence_requested';

  ELSIF _action = 'ESCALATE' THEN
    IF NOT public.sec_has_permission(uid,'entity_resolution','escalate') THEN
      RAISE EXCEPTION 'entity_resolution.escalate required' USING ERRCODE='42501'; END IF;
    IF COALESCE(length(btrim(_notes)),0) < 10 THEN
      RAISE EXCEPTION 'An escalation reason is required' USING ERRCODE='22023'; END IF;
    UPDATE public.entity_resolution_cases
       SET status='ESCALATED', escalated_by=uid, escalated_at=now(),
           escalation_reason = btrim(_notes),
           supervisor_decision = NULL, supervisor_notes = NULL,
           supervisor_decided_by = NULL, supervisor_decided_at = NULL
     WHERE id = _case_id;
    PERFORM public.entity_resolution_notify_approvers(_case_id,
      'Entity resolution awaiting supervisor decision',
      'Case ' || c.case_number || ' (' || c.subject_name || ') needs a supervisory decision.');
    v_event := 'entity.resolution.escalated';

  ELSIF _action = 'APPROVE' THEN
    IF NOT public.sec_has_permission(uid,'entity_resolution','approve') THEN
      RAISE EXCEPTION 'entity_resolution.approve required' USING ERRCODE='42501'; END IF;
    IF c.status <> 'ESCALATED' THEN
      RAISE EXCEPTION 'Only escalated cases awaiting a supervisory decision can be approved' USING ERRCODE='22023'; END IF;
    IF c.recommended_action IS NULL THEN
      RAISE EXCEPTION 'There is no officer recommendation to approve' USING ERRCODE='22023'; END IF;
    IF c.recommended_by IS NOT NULL AND c.recommended_by = uid THEN
      RAISE EXCEPTION 'Maker-checker: you cannot approve your own recommendation' USING ERRCODE='42501'; END IF;

    UPDATE public.entity_resolution_cases
       SET supervisor_decision='APPROVED', supervisor_notes = COALESCE(btrim(_notes), supervisor_notes),
           supervisor_decided_by = uid, supervisor_decided_at = now()
     WHERE id = _case_id;

    INSERT INTO public.entity_resolution_events (case_id, event_type, actor_id, detail)
    VALUES (_case_id, 'entity.resolution.approved', uid,
            jsonb_build_object('recommended_action', c.recommended_action,
                               'recommended_entity_id', c.recommended_entity_id,
                               'recommended_by', c.recommended_by, 'notes', _notes));
    PERFORM public.create_audit_log(uid, 'entity.resolution.approved', 'entity_resolution_case',
      _case_id::text, NULL, jsonb_build_object('recommended_action', c.recommended_action,
      'recommended_by', c.recommended_by), '{}'::jsonb);

    v_entity := public.entity_resolution_finalise(_case_id, c.recommended_action,
                  c.recommended_entity_id, c.recommended_by, uid,
                  COALESCE(btrim(_notes), c.recommendation_notes));
    RETURN jsonb_build_object('case_id', _case_id, 'entity_id', v_entity, 'action', 'APPROVE');

  ELSIF _action = 'RETURN_FOR_REVIEW' THEN
    IF NOT public.sec_has_permission(uid,'entity_resolution','approve') THEN
      RAISE EXCEPTION 'entity_resolution.approve required' USING ERRCODE='42501'; END IF;
    IF c.status <> 'ESCALATED' THEN
      RAISE EXCEPTION 'Only escalated cases can be returned for review' USING ERRCODE='22023'; END IF;
    IF COALESCE(length(btrim(_notes)),0) < 10 THEN
      RAISE EXCEPTION 'A return reason is required' USING ERRCODE='22023'; END IF;
    UPDATE public.entity_resolution_cases
       SET status='PENDING_REVIEW', supervisor_decision='RETURNED',
           supervisor_notes = btrim(_notes), supervisor_decided_by = uid, supervisor_decided_at = now()
     WHERE id = _case_id;
    v_event := 'entity.resolution.returned';

  ELSE
    RAISE EXCEPTION 'Unsupported action %', _action USING ERRCODE='22023';
  END IF;

  INSERT INTO public.entity_resolution_events (case_id, event_type, actor_id, detail)
  VALUES (_case_id, v_event, uid,
          jsonb_build_object('action', _action, 'entity_id', v_entity, 'notes', _notes));

  PERFORM public.create_audit_log(uid, v_event, 'entity_resolution_case', _case_id::text, NULL,
    jsonb_build_object('action', _action, 'entity_id', v_entity), '{}'::jsonb);

  RETURN jsonb_build_object('case_id', _case_id, 'entity_id', v_entity, 'action', _action);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_resolution_finalise(_case_id uuid, _action text, _entity_id uuid, _resolver uuid, _approver uuid, _notes text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.entity_resolution_cases;
  v_entity uuid := _entity_id;
  v_outcome text;
  b public.registration_entity_bindings;
  v_user uuid;
BEGIN
  SELECT * INTO c FROM public.entity_resolution_cases WHERE id = _case_id FOR UPDATE;
  IF c.id IS NULL THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='22023'; END IF;
  IF c.status = 'RESOLVED' THEN RAISE EXCEPTION 'Case already resolved' USING ERRCODE='22023'; END IF;

  IF _action = 'RESOLVE_EXISTING' THEN
    IF v_entity IS NULL THEN RAISE EXCEPTION 'entity_id required' USING ERRCODE='22023'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.licensees l
                    WHERE l.id = v_entity AND l.merged_into_entity_id IS NULL) THEN
      RAISE EXCEPTION 'Recommended entity is no longer valid (merged or removed)' USING ERRCODE='22023';
    END IF;
    UPDATE public.entity_match_candidates SET is_selected = (entity_id = v_entity) WHERE case_id = _case_id;
    v_outcome := 'RESOLVED_EXISTING';
  ELSIF _action = 'CONFIRM_NEW' THEN
    v_entity := public.entity_create_local(
      c.subject_name, c.subject_identifiers,
      NULLIF(c.subject_payload->>'sector_id','')::uuid,
      'applicant', 'provisional', _case_id);
    v_outcome := 'CONFIRMED_NEW';
  ELSE
    RAISE EXCEPTION 'Unsupported final action %', _action USING ERRCODE='22023';
  END IF;

  UPDATE public.entity_resolution_cases
     SET status = 'RESOLVED', outcome = v_outcome, resolved_entity_id = v_entity,
         resolved_by = COALESCE(_resolver, auth.uid()), resolved_at = now(),
         approved_by = COALESCE(_approver, approved_by),
         approved_at = CASE WHEN _approver IS NOT NULL THEN now() ELSE approved_at END,
         decision_notes = COALESCE(_notes, decision_notes)
   WHERE id = _case_id;

  SELECT * INTO b FROM public.registration_entity_bindings WHERE resolution_case_id = _case_id;
  IF b.id IS NOT NULL THEN
    UPDATE public.registration_entity_bindings
       SET entity_id = v_entity,
           binding_status = CASE WHEN v_outcome = 'RESOLVED_EXISTING' THEN 'BOUND_EXISTING' ELSE 'BOUND_PROVISIONAL' END,
           bound_at = now(), updated_at = now()
     WHERE id = b.id;
    SELECT user_id INTO v_user FROM public.registrations WHERE id = b.registration_id;
    IF v_user IS NOT NULL THEN
      PERFORM public.onboarding_record_journey_event(
        v_user, 'ENTITY_IDENTIFICATION', 'FORM_FIRST', v_entity, b.registration_id, b.identification_event_id,
        jsonb_build_object('resolution_case_id', _case_id, 'outcome', v_outcome, 'source', 'regulator_decision'));
      BEGIN
        PERFORM public.create_notification(v_user, 'Organisation verification complete',
          'The regulator has completed verification of your organisation details. Your registration continues.',
          'info', 'registration', b.registration_id::text);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END IF;
  END IF;

  INSERT INTO public.entity_resolution_events (case_id, event_type, actor_id, detail)
  VALUES (_case_id,
          CASE WHEN v_outcome = 'RESOLVED_EXISTING' THEN 'entity.resolution.resolved_existing'
               ELSE 'entity.resolution.confirmed_new' END,
          COALESCE(_approver, _resolver, auth.uid()),
          jsonb_build_object('entity_id', v_entity, 'resolver', _resolver, 'approver', _approver, 'notes', _notes));

  PERFORM public.create_audit_log(COALESCE(_approver, _resolver, auth.uid()),
    CASE WHEN v_outcome = 'RESOLVED_EXISTING' THEN 'entity.resolution.resolved_existing'
         ELSE 'entity.resolution.confirmed_new' END,
    'entity_resolution_case', _case_id::text, NULL,
    jsonb_build_object('entity_id', v_entity, 'resolver', _resolver, 'approver', _approver), '{}'::jsonb);

  RETURN v_entity;
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_resolution_notify_approvers(_case_id uuid, _title text, _body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r RECORD;
BEGIN
  FOR r IN
    SELECT DISTINCT ur.user_id
      FROM public.sec_user_roles ur
     WHERE public.sec_has_permission(ur.user_id, 'entity_resolution', 'approve')
     LIMIT 50
  LOOP
    BEGIN
      PERFORM public.create_notification(r.user_id, _title, _body, 'action_required',
                                         'entity_resolution_case', _case_id::text);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END LOOP;
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_resolution_queue(_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); v_rows jsonb;
BEGIN
  IF uid IS NULL OR NOT public.sec_has_permission(uid,'entity_resolution','view') THEN
    RAISE EXCEPTION 'entity_resolution.view required' USING ERRCODE='42501';
  END IF;

  SELECT COALESCE(jsonb_agg(r ORDER BY r->>'created_at' DESC), '[]'::jsonb) INTO v_rows
  FROM (
    SELECT jsonb_build_object(
      'id', c.id,
      'case_number', c.case_number,
      'status', c.status,
      'outcome', c.outcome,
      'subject_name', c.subject_name,
      'provider_status', c.provider_status,
      'authority_mode', c.authority_mode,
      'journey_type', COALESCE(c.subject_payload->>'journey_type',
                               CASE WHEN b.registration_id IS NOT NULL THEN 'FORM_FIRST' ELSE NULL END),
      'registration_id', b.registration_id,
      'registration_reference', reg.registration_reference,
      'binding_status', b.binding_status,
      'recommended_action', c.recommended_action,
      'recommended_entity_id', c.recommended_entity_id,
      'recommended_entity_name', COALESCE(ro.legal_name, rl.name),
      'recommended_by', c.recommended_by,
      'recommended_by_name', COALESCE(rp.full_name, rp.email),
      'recommended_at', c.recommended_at,
      'escalated_by', c.escalated_by,
      'escalated_by_name', COALESCE(ep.full_name, ep.email),
      'escalated_at', c.escalated_at,
      'escalation_reason', c.escalation_reason,
      'supervisor_decision', c.supervisor_decision,
      'top_match_score', (SELECT max(mc.match_score) FROM public.entity_match_candidates mc WHERE mc.case_id = c.id),
      'candidate_count', (SELECT count(*) FROM public.entity_match_candidates mc WHERE mc.case_id = c.id),
      'escalation_age_hours', CASE WHEN c.escalated_at IS NULL THEN NULL
                                   ELSE round(extract(epoch from (now() - c.escalated_at))/3600.0, 1) END,
      'awaiting_supervisor', (c.status = 'ESCALATED'),
      'resolved_entity_id', c.resolved_entity_id,
      'requested_at', c.requested_at,
      'resolved_at', c.resolved_at,
      'created_at', c.created_at
    ) AS r
    FROM public.entity_resolution_cases c
    LEFT JOIN public.registration_entity_bindings b ON b.resolution_case_id = c.id
    LEFT JOIN public.registrations reg ON reg.id = b.registration_id
    LEFT JOIN public.licensees rl ON rl.id = c.recommended_entity_id
    LEFT JOIN public.organizations ro ON ro.party_id = rl.party_id
    LEFT JOIN public.profiles rp ON rp.id = c.recommended_by
    LEFT JOIN public.profiles ep ON ep.id = c.escalated_by
    WHERE _status IS NULL OR _status = 'all' OR c.status = _status
    ORDER BY c.created_at DESC
    LIMIT 300
  ) s;

  RETURN jsonb_build_object(
    'rows', v_rows,
    'awaiting_supervisor_count',
      (SELECT count(*) FROM public.entity_resolution_cases WHERE status = 'ESCALATED'));
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_resolution_requires_maker_checker(_case_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT p.requires_maker_checker
       FROM public.entity_resolution_cases c
       LEFT JOIN public.entity_resolution_policies p ON p.id = c.resolution_policy_id
      WHERE c.id = _case_id),
    (SELECT requires_maker_checker FROM public.entity_resolution_policies WHERE is_default AND is_active LIMIT 1),
    true);
$function$
;
CREATE OR REPLACE FUNCTION public.entity_resolution_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END $function$
;
CREATE OR REPLACE FUNCTION public.entity_resolve_identity(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  v_name text := btrim(COALESCE(_payload->>'legal_name',''));
  v_name_norm text := upper(regexp_replace(COALESCE(_payload->>'legal_name',''), '[^A-Za-z0-9]', '', 'g'));
  v_ids jsonb := COALESCE(_payload->'identifiers', '[]'::jsonb);
  v_licence text := upper(regexp_replace(COALESCE(_payload->>'license_number',''), '[^A-Za-z0-9]', '', 'g'));
  v_app uuid := NULLIF(_payload->>'application_id','')::uuid;
  rec jsonb;
  v_type uuid;
  v_norm text;
  v_entity uuid;
  v_case uuid;
  v_case_no text;
  v_policy uuid;
  v_outcome text := 'NO_MATCH';
  cand RECORD;
  v_candidates jsonb := '[]'::jsonb;
  v_exact_basis text;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  IF v_name = '' THEN RAISE EXCEPTION 'legal_name is required' USING ERRCODE='22023'; END IF;

  SELECT id INTO v_policy FROM public.entity_resolution_policies WHERE is_default AND is_active LIMIT 1;

  -- 1. Authoritative identifier match (canonical normalization service)
  FOR rec IN SELECT jsonb_array_elements(v_ids) LOOP
    SELECT id INTO v_type FROM public.entity_identifier_types
      WHERE key = rec->>'type' AND is_active;
    CONTINUE WHEN v_type IS NULL;
    v_norm := public.normalize_entity_identifier(v_type, rec->>'value');
    CONTINUE WHEN COALESCE(v_norm,'') = '';
    SELECT ei.entity_id INTO v_entity
      FROM public.entity_identifiers ei
     WHERE ei.identifier_type_id = v_type AND ei.normalized_value = v_norm
       AND (ei.effective_to IS NULL OR ei.effective_to > now())
     LIMIT 1;
    IF v_entity IS NOT NULL THEN
      v_outcome := 'EXACT_MATCH';
      v_exact_basis := 'identifier:' || (rec->>'type');
      EXIT;
    END IF;
  END LOOP;

  -- 2. Licence number is only a LOOKUP SIGNAL, resolved through entity_licenses
  IF v_entity IS NULL AND v_licence <> '' THEN
    SELECT el.entity_id INTO v_entity
      FROM public.entity_licenses el
      JOIN public.licenses lic ON lic.id = el.license_id
     WHERE upper(regexp_replace(lic.license_number, '[^A-Za-z0-9]', '', 'g')) = v_licence
     LIMIT 1;
    IF v_entity IS NOT NULL THEN
      v_outcome := 'EXACT_MATCH';
      v_exact_basis := 'licence_lookup';
    END IF;
  END IF;

  IF v_entity IS NOT NULL THEN
    -- Follow merge lineage to the survivor entity
    WHILE (SELECT merged_into_entity_id FROM public.licensees WHERE id = v_entity) IS NOT NULL LOOP
      SELECT merged_into_entity_id INTO v_entity FROM public.licensees WHERE id = v_entity;
    END LOOP;
    RETURN jsonb_build_object(
      'outcome', 'EXACT_MATCH', 'entity_id', v_entity, 'match_basis', v_exact_basis,
      'entity', public.entity_registry_entity_dto(v_entity), 'case_id', NULL,
      'candidates', '[]'::jsonb);
  END IF;

  -- 3. Candidate signals (names are never deterministic identity)
  v_case_no := 'ERC-' || to_char(now(), 'YYYYMMDD') || '-' ||
               lpad(((extract(epoch from clock_timestamp())::bigint) % 100000)::text, 5, '0');

  FOR cand IN
    SELECT l.id,
           CASE
             WHEN upper(regexp_replace(COALESCE(o.legal_name, l.name), '[^A-Za-z0-9]', '', 'g')) = v_name_norm THEN 80
             WHEN upper(regexp_replace(COALESCE(o.legal_name, l.name), '[^A-Za-z0-9]', '', 'g')) LIKE '%'||v_name_norm||'%'
               OR v_name_norm LIKE '%'||upper(regexp_replace(COALESCE(o.legal_name, l.name), '[^A-Za-z0-9]', '', 'g'))||'%' THEN 55
             ELSE 0
           END AS score,
           COALESCE(o.legal_name, l.name) AS legal_name
    FROM public.licensees l
    LEFT JOIN public.organizations o ON o.party_id = l.party_id
    WHERE l.merged_into_entity_id IS NULL AND v_name_norm <> ''
    ORDER BY 2 DESC
    LIMIT 10
  LOOP
    CONTINUE WHEN cand.score = 0;
    IF v_case IS NULL THEN
      INSERT INTO public.entity_resolution_cases
        (case_number, status, outcome, subject_name, subject_identifiers, subject_payload,
         resolution_policy_id, application_id, requested_by)
      VALUES (v_case_no, 'OPEN', 'POSSIBLE_MATCH', v_name, v_ids, _payload, v_policy, v_app, uid)
      RETURNING id INTO v_case;
      v_outcome := 'POSSIBLE_MATCH';
    END IF;
    INSERT INTO public.entity_match_candidates (case_id, entity_id, match_score, match_basis, signals)
    VALUES (v_case, cand.id, cand.score, 'name_similarity',
            jsonb_build_object('candidate_legal_name', cand.legal_name, 'subject_legal_name', v_name));
    v_candidates := v_candidates || jsonb_build_array(jsonb_build_object(
      'entity_id', cand.id, 'legal_name', cand.legal_name,
      'match_score', cand.score, 'match_basis', 'name_similarity'));
  END LOOP;

  IF v_case IS NOT NULL THEN
    INSERT INTO public.entity_resolution_events (case_id, event_type, actor_id, detail)
    VALUES (v_case, 'entity.resolution.requested', uid, jsonb_build_object('outcome','POSSIBLE_MATCH'));
    PERFORM public.create_audit_log(uid, 'entity.resolution.requested', 'entity_resolution_case', v_case::text,
      NULL, jsonb_build_object('subject_name', v_name, 'outcome','POSSIBLE_MATCH'), '{}'::jsonb);
  END IF;

  RETURN jsonb_build_object(
    'outcome', v_outcome, 'entity_id', NULL, 'case_id', v_case,
    'case_number', CASE WHEN v_case IS NULL THEN NULL ELSE v_case_no END,
    'candidates', v_candidates);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_set_publication_policy(_entity_id uuid, _policy_key text, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_policy uuid; v_old uuid;
BEGIN
  IF NOT public.sec_has_permission(auth.uid(), 'licensee_management', 'edit') THEN
    RAISE EXCEPTION 'licensee_management.edit required' USING ERRCODE='42501';
  END IF;
  SELECT id INTO v_policy FROM public.registry_publication_policies WHERE key = _policy_key AND is_active;
  IF v_policy IS NULL THEN RAISE EXCEPTION 'Unknown publication policy %', _policy_key USING ERRCODE='22023'; END IF;
  SELECT publication_policy_id INTO v_old FROM public.licensees WHERE id = _entity_id;
  UPDATE public.licensees SET publication_policy_id = v_policy, updated_at = now() WHERE id = _entity_id;
  PERFORM public.create_audit_log(auth.uid(), 'entity.publication_policy.changed', 'licensee', _entity_id::text,
    jsonb_build_object('policy_id', v_old), jsonb_build_object('policy_key', _policy_key, 'reason', _reason), '{}'::jsonb);
  RETURN jsonb_build_object('entity_id', _entity_id, 'publication_policy', _policy_key);
END $function$
;
CREATE OR REPLACE FUNCTION public.entity_structure_overview(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_out jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT (
    public.has_permission(v_uid, 'entity_membership', 'view')
    OR public.has_permission(v_uid, 'license_management', 'view')
    OR EXISTS (SELECT 1 FROM public.entity_user_memberships m
                WHERE m.user_id = v_uid AND m.entity_id = _entity_id AND m.status = 'APPROVED')
  ) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'entity_id', l.id,
    'name', l.name,
    'party_id', l.party_id,
    'sector_id', l.sector_id,
    'sub_sector_id', l.sub_sector_id,
    'category_id', l.category_id,
    'status', l.status,
    'lifecycle_stage_id', l.lifecycle_stage_id,
    'identity_status_id', l.identity_status_id,
    'merged_into_entity_id', l.merged_into_entity_id,
    'structure_version', l.structure_version,
    'licences', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('license_id', el.license_id, 'is_primary', el.is_primary,
                                          'effective_from', el.effective_from, 'effective_to', el.effective_to)
             ORDER BY el.effective_from DESC)
      FROM public.entity_licenses el WHERE el.entity_id = l.id), '[]'::jsonb),
    'ownership_count', (SELECT count(*) FROM public.ownership_interests o WHERE o.owned_entity_id = l.id AND o.effective_to IS NULL),
    'controller_count', (SELECT count(*) FROM public.ownership_interests o WHERE o.owned_entity_id = l.id AND o.effective_to IS NULL AND o.is_controller),
    'ubo_count', (SELECT count(*) FROM public.ownership_interests o WHERE o.owned_entity_id = l.id AND o.effective_to IS NULL AND o.is_ubo),
    'relationship_count', (SELECT count(*) FROM public.party_relationships r WHERE r.entity_id = l.id AND r.effective_to IS NULL),
    'board_count', (SELECT count(*) FROM public.entity_appointments a JOIN public.role_types rt ON rt.id = a.role_type_id
                     WHERE a.entity_id = l.id AND a.effective_to IS NULL AND rt.is_governance),
    'key_function_count', (SELECT count(*) FROM public.entity_appointments a JOIN public.role_types rt ON rt.id = a.role_type_id
                     WHERE a.entity_id = l.id AND a.effective_to IS NULL AND NOT rt.is_governance),
    'open_requests', (SELECT count(*) FROM public.regulatory_requests r WHERE r.entity_id = l.id AND r.status NOT IN ('CLOSED','REJECTED','WITHDRAWN')),
    'pending_change_sets', (SELECT count(*) FROM public.entity_change_sets cs WHERE cs.entity_id = l.id AND cs.status NOT IN ('APPLIED','REJECTED','WITHDRAWN')),
    'names', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('name', n.name, 'name_type', n.name_type, 'is_current', n.is_current,
                                          'effective_from', n.effective_from, 'effective_to', n.effective_to)
             ORDER BY n.effective_from DESC)
      FROM public.organization_names n WHERE n.party_id = l.party_id), '[]'::jsonb)
  ) INTO v_out
  FROM public.licensees l
  WHERE l.id = _entity_id;

  IF v_out IS NULL THEN RAISE EXCEPTION 'Entity not found'; END IF;
  RETURN v_out;
END $function$
;
CREATE OR REPLACE FUNCTION public.escalate_application(_application_id uuid, _reason text DEFAULT NULL::text)
 RETURNS applications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.applications;
BEGIN
  PERFORM public.enforce_permission('application_management', 'escalate');

  UPDATE public.applications
     SET status = 'escalated',
         updated_at = now()
   WHERE id = _application_id
   RETURNING * INTO _row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Application % not found', _application_id
      USING ERRCODE = 'no_data_found';
  END IF;

  INSERT INTO public.audit_logs (
    user_id, action, entity_type, entity_id, metadata, created_at
  ) VALUES (
    auth.uid(),
    'application.escalate',
    'application',
    _application_id,
    jsonb_build_object('reason', _reason),
    now()
  );

  RETURN _row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalate_complaint_to_enforcement(_id uuid, _findings text)
 RETURNS TABLE(complaint_id uuid, enforcement_id uuid, case_number text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  c public.complaints%ROWTYPE;
  new_ea_id uuid;
  new_case_number text;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='28000'; END IF;
  IF NOT public.has_complaint_perm(actor, 'escalate') THEN
    RAISE EXCEPTION 'permission denied: complaint_management.escalate' USING ERRCODE='42501';
  END IF;
  IF _findings IS NULL OR length(btrim(_findings)) < 10 THEN
    RAISE EXCEPTION 'findings required (min 10 chars)' USING ERRCODE='22023';
  END IF;

  SELECT * INTO c FROM public.complaints WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'complaint not found' USING ERRCODE='P0002'; END IF;
  IF c.licensee_id IS NULL THEN
    RAISE EXCEPTION 'complaint must be linked to a licensee before escalation' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.enforcement_actions AS ea
    (entity_id, enforcement_type, status, description, findings, opened_by, source_type, source_reference_id)
  VALUES
    (c.licensee_id, 'complaint_escalation', 'open',
     format('Escalated from complaint %s: %s'||E'\n\nFindings: %s', c.complaint_number, c.subject, btrim(_findings)),
     btrim(_findings), actor, 'complaint', c.id)
  RETURNING ea.id, ea.case_number INTO new_ea_id, new_case_number;

  UPDATE public.complaints
     SET enforcement_action_id = new_ea_id, updated_at = now()
   WHERE id = _id;

  INSERT INTO public.enforcement_case_events (case_id, event_type, note, detail, actor_id)
  VALUES (new_ea_id, 'opened',
          format('Auto-opened from complaint %s', c.complaint_number),
          jsonb_build_object('complaint_id', c.id), actor);

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value)
  VALUES (actor, 'complaint.escalated_to_enforcement', 'complaint', _id,
          jsonb_build_object('enforcement_action_id', c.enforcement_action_id),
          jsonb_build_object('enforcement_action_id', new_ea_id, 'case_number', new_case_number, 'findings', btrim(_findings)));

  complaint_id := _id;
  enforcement_id := new_ea_id;
  case_number := new_case_number;
  RETURN NEXT;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_acknowledge(_id uuid, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e public.escalations; v_pause boolean;
BEGIN
  PERFORM public.enforce_permission('escalation_management', 'acknowledge');
  SELECT * INTO e FROM public.escalations WHERE id = _id FOR UPDATE;
  IF e.id IS NULL THEN RAISE EXCEPTION 'escalation_not_found'; END IF;
  IF e.status IN ('resolved','closed') THEN RAISE EXCEPTION 'escalation_is_terminal'; END IF;

  SELECT coalesce(pause_on_acknowledgement, true) INTO v_pause
  FROM public.escalation_rules WHERE id = e.rule_id;

  UPDATE public.escalations
  SET status = 'acknowledged',
      acknowledged_at = coalesce(acknowledged_at, now()),
      acknowledged_by = coalesce(acknowledged_by, auth.uid()),
      auto_escalate_paused_at = CASE WHEN coalesce(v_pause, true) THEN now() ELSE auto_escalate_paused_at END,
      next_auto_escalation_at = CASE WHEN coalesce(v_pause, true) THEN NULL ELSE next_auto_escalation_at END
  WHERE id = _id;

  INSERT INTO public.escalation_ownership_events
    (escalation_id, from_user_id, to_user_id, event_type, note, actor_id)
  VALUES (_id, e.assigned_user_id, auth.uid(), 'acknowledged', _note, auth.uid());

  RETURN jsonb_build_object('ok', true, 'paused', coalesce(v_pause, true));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_advance_tier(_id uuid, _trigger text DEFAULT 'manual'::text, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  e public.escalations; v_next integer; v_cfg jsonb; v_ack timestamptz; v_event_id uuid;
BEGIN
  SELECT * INTO e FROM public.escalations WHERE id = _id FOR UPDATE;
  IF e.id IS NULL THEN RAISE EXCEPTION 'escalation_not_found'; END IF;
  IF e.status IN ('resolved','closed') THEN RAISE EXCEPTION 'escalation_is_terminal'; END IF;

  v_next := e.current_tier + 1;
  IF v_next > 3 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'max_tier_reached', 'tier', e.current_tier);
  END IF;

  v_cfg := public.escalation_tier_config(e.rule_id, v_next);
  IF v_cfg IS NULL OR coalesce(v_cfg->>'role','') = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_tier_configured', 'tier', e.current_tier);
  END IF;

  v_ack := public.escalation_deadline(e.rule_id, now(), (v_cfg->>'threshold')::int);

  UPDATE public.escalations
  SET current_tier = v_next,
      status = 'escalated',
      assigned_role = v_cfg->>'role',
      acknowledgement_deadline = v_ack,
      acknowledged_at = NULL,
      acknowledged_by = NULL,
      auto_escalate_paused_at = NULL,
      next_auto_escalation_at = v_ack
  WHERE id = _id;

  INSERT INTO public.escalation_tier_events
    (escalation_id, from_tier, to_tier, trigger_source, recipient_role, reason, acknowledgement_deadline, actor_id)
  VALUES (_id, e.current_tier, v_next, _trigger, v_cfg->>'role',
          coalesce(_reason, CASE WHEN _trigger = 'automatic'
                 THEN 'Acknowledgement deadline passed without response'
                 ELSE 'Manually escalated to the next tier' END), v_ack, auth.uid())
  RETURNING id INTO v_event_id;

  PERFORM public.escalation_notify(
    _id, 'escalation.tier_advanced', v_cfg->>'role', v_next,
    format('[%s] Escalation %s moved to tier %s', upper(e.severity::text), e.escalation_ref, v_next),
    format('Escalation %s (%s from %s) has moved to tier %s. Source: %s. %s',
           e.escalation_ref, replace(e.escalation_type::text,'_',' '), e.source_module, v_next,
           coalesce(e.source_reference, 'n/a'),
           coalesce(to_char(v_ack,'"Acknowledge before "DD Mon YYYY HH24:MI'), '')),
    e.severity = 'critical', v_event_id);

  RETURN jsonb_build_object('ok', true, 'tier', v_next, 'role', v_cfg->>'role');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_business_deadline(_profile_id uuid, _from timestamp with time zone, _minutes integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prof public.business_calendar_profiles;
  v_cursor timestamptz := _from;
  v_remaining integer := greatest(coalesce(_minutes, 0), 0);
  v_day_start timestamptz;
  v_day_end timestamptz;
  v_available integer;
  v_guard integer := 0;
BEGIN
  IF _minutes IS NULL OR _minutes <= 0 THEN RETURN _from; END IF;

  SELECT * INTO v_prof FROM public.business_calendar_profiles WHERE id = _profile_id;
  IF v_prof.id IS NULL THEN
    RETURN _from + make_interval(mins => _minutes);
  END IF;

  WHILE v_remaining > 0 AND v_guard < 400 LOOP
    v_guard := v_guard + 1;
    v_day_start := date_trunc('day', v_cursor) + v_prof.working_start_time;
    v_day_end   := date_trunc('day', v_cursor) + v_prof.working_end_time;

    IF NOT (to_char(v_cursor, 'FMDay') = ANY (v_prof.working_days))
       AND NOT (lower(to_char(v_cursor, 'FMDay')) = ANY (SELECT lower(unnest(v_prof.working_days))))
       OR EXISTS (
         SELECT 1 FROM public.business_calendar_holidays h
         WHERE h.profile_id = v_prof.id AND h.holiday_date = v_cursor::date
       ) THEN
      v_cursor := date_trunc('day', v_cursor) + interval '1 day';
      CONTINUE;
    END IF;

    IF v_cursor < v_day_start THEN v_cursor := v_day_start; END IF;
    IF v_cursor >= v_day_end THEN
      v_cursor := date_trunc('day', v_cursor) + interval '1 day';
      CONTINUE;
    END IF;

    v_available := floor(extract(epoch FROM (v_day_end - v_cursor)) / 60)::int;
    IF v_available >= v_remaining THEN
      RETURN v_cursor + make_interval(mins => v_remaining);
    END IF;
    v_remaining := v_remaining - v_available;
    v_cursor := date_trunc('day', v_cursor) + interval '1 day';
  END LOOP;

  RETURN v_cursor;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_deadline(_rule_id uuid, _from timestamp with time zone, _minutes integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.escalation_rules;
BEGIN
  IF _minutes IS NULL OR _minutes <= 0 THEN RETURN NULL; END IF;
  SELECT * INTO r FROM public.escalation_rules WHERE id = _rule_id;
  IF r.id IS NULL OR NOT r.business_hours_only THEN
    RETURN _from + make_interval(mins => _minutes);
  END IF;
  RETURN public.escalation_business_deadline(r.business_calendar_profile_id, _from, _minutes);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_detail(_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e public.escalations; v_uid uuid := auth.uid();
BEGIN
  PERFORM public.enforce_permission('escalation_management', 'view');
  SELECT * INTO e FROM public.escalations WHERE id = _id;
  IF e.id IS NULL THEN RAISE EXCEPTION 'escalation_not_found'; END IF;

  IF NOT (public.is_super_admin(v_uid)
          OR public.has_permission(v_uid, 'escalation_management', 'configure')
          OR e.assigned_user_id = v_uid
          OR public.has_module_access_for_escalation(v_uid, e.source_module)) THEN
    RAISE EXCEPTION 'permission denied: escalation not in scope' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'escalation', to_jsonb(e) || jsonb_build_object(
        'owner_name', (SELECT p.full_name FROM public.profiles p WHERE p.id = e.assigned_user_id),
        'acknowledged_by_name', (SELECT p.full_name FROM public.profiles p WHERE p.id = e.acknowledged_by),
        'resolved_by_name', (SELECT p.full_name FROM public.profiles p WHERE p.id = e.resolved_by)),
    'rule', (SELECT to_jsonb(r) FROM public.escalation_rules r WHERE r.id = e.rule_id),
    'tier_history', (SELECT coalesce(jsonb_agg(to_jsonb(t) || jsonb_build_object(
                        'actor_name', (SELECT p.full_name FROM public.profiles p WHERE p.id = t.actor_id))
                        ORDER BY t.created_at), '[]'::jsonb)
                     FROM public.escalation_tier_events t WHERE t.escalation_id = _id),
    'ownership_history', (SELECT coalesce(jsonb_agg(to_jsonb(o) || jsonb_build_object(
                        'actor_name', (SELECT p.full_name FROM public.profiles p WHERE p.id = o.actor_id),
                        'to_name', (SELECT p.full_name FROM public.profiles p WHERE p.id = o.to_user_id))
                        ORDER BY o.created_at), '[]'::jsonb)
                     FROM public.escalation_ownership_events o WHERE o.escalation_id = _id),
    'notification_history', (SELECT coalesce(jsonb_agg(to_jsonb(n) || jsonb_build_object(
                        'recipient_name', (SELECT p.full_name FROM public.profiles p WHERE p.id = n.recipient_user_id))
                        ORDER BY n.created_at DESC), '[]'::jsonb)
                     FROM public.escalation_notification_events n WHERE n.escalation_id = _id),
    'delivery_records', (SELECT coalesce(jsonb_agg(jsonb_build_object(
                        'id', d.id, 'channel', d.channel, 'status', d.status, 'error', d.error,
                        'recipient_email', d.recipient_email, 'event_key', d.event_key,
                        'created_at', d.created_at, 'sent_at', d.sent_at) ORDER BY d.created_at DESC), '[]'::jsonb)
                     FROM public.notification_dispatch_log d
                     WHERE d.entity_type = 'escalation' AND d.entity_id = _id::text),
    'source_event', jsonb_build_object(
        'module', e.source_module, 'event', e.source_event,
        'entity_type', e.source_entity_type, 'entity_id', e.source_entity_id,
        'reference', e.source_reference, 'rule_id', e.source_rule_id,
        'metadata', e.metadata, 'correlation_id', e.correlation_id)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_escalate_tier(_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.enforce_permission('escalation_management', 'escalate');
  RETURN public.escalation_advance_tier(_id, 'manual', _reason);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_feed(_modules text[] DEFAULT NULL::text[], _types text[] DEFAULT NULL::text[], _severities text[] DEFAULT NULL::text[], _tiers integer[] DEFAULT NULL::integer[], _statuses text[] DEFAULT NULL::text[], _owner uuid DEFAULT NULL::uuid, _from timestamp with time zone DEFAULT NULL::timestamp with time zone, _to timestamp with time zone DEFAULT NULL::timestamp with time zone, _search text DEFAULT NULL::text, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_all boolean; v_rows jsonb; v_total integer;
BEGIN
  PERFORM public.enforce_permission('escalation_management', 'view');
  v_all := public.is_super_admin(v_uid) OR public.has_permission(v_uid, 'escalation_management', 'configure');

  WITH scoped AS (
    SELECT e.*
    FROM public.escalations e
    WHERE (v_all
           OR e.assigned_user_id = v_uid
           OR public.has_module_access_for_escalation(v_uid, e.source_module))
      AND (_modules IS NULL OR e.source_module = ANY(_modules))
      AND (_types IS NULL OR e.escalation_type::text = ANY(_types))
      AND (_severities IS NULL OR e.severity::text = ANY(_severities))
      AND (_tiers IS NULL OR e.current_tier = ANY(_tiers))
      AND (_statuses IS NULL OR e.status::text = ANY(_statuses))
      AND (_owner IS NULL OR e.assigned_user_id = _owner)
      AND (_from IS NULL OR e.created_at >= _from)
      AND (_to IS NULL OR e.created_at <= _to)
      AND (_search IS NULL OR btrim(_search) = ''
           OR e.escalation_ref ILIKE '%'||_search||'%'
           OR coalesce(e.source_reference,'') ILIKE '%'||_search||'%'
           OR e.source_event ILIKE '%'||_search||'%')
  )
  SELECT count(*)::int,
         coalesce(jsonb_agg(x ORDER BY x->>'created_at' DESC), '[]'::jsonb)
    INTO v_total, v_rows
  FROM (
    SELECT to_jsonb(s) - 'metadata' ||
           jsonb_build_object(
             'owner_name', (SELECT p.full_name FROM public.profiles p WHERE p.id = s.assigned_user_id),
             'rule_name', (SELECT r.name FROM public.escalation_rules r WHERE r.id = s.rule_id),
             'hours_open', round(extract(epoch FROM (coalesce(s.resolved_at, now()) - s.created_at)) / 3600.0, 1),
             'ack_overdue', (s.acknowledged_at IS NULL AND s.acknowledgement_deadline IS NOT NULL AND s.acknowledgement_deadline < now()),
             'resolution_overdue', (s.resolved_at IS NULL AND s.resolution_deadline IS NOT NULL AND s.resolution_deadline < now())
           ) AS x
    FROM scoped s
    ORDER BY s.created_at DESC
    LIMIT greatest(coalesce(_limit, 50), 1) OFFSET greatest(coalesce(_offset, 0), 0)
  ) q;

  RETURN jsonb_build_object('rows', v_rows, 'total', v_total);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_health_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.enforce_permission('escalation_management', 'view_system_health');
  RETURN jsonb_build_object(
    'signals', (SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.last_seen DESC), '[]'::jsonb)
                FROM public.escalation_health_signals s),
    'open_health_escalations', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', e.id, 'escalation_ref', e.escalation_ref, 'escalation_type', e.escalation_type,
        'severity', e.severity, 'status', e.status, 'current_tier', e.current_tier,
        'source_event', e.source_event, 'source_reference', e.source_reference,
        'created_at', e.created_at, 'acknowledgement_deadline', e.acknowledgement_deadline,
        'acknowledged_at', e.acknowledged_at) ORDER BY e.created_at DESC), '[]'::jsonb)
      FROM public.escalations e
      WHERE e.source_module = 'system_health' AND e.status NOT IN ('resolved','closed'))
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_health_sweep(_min_failures integer DEFAULT 3)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s record; v_raised integer := 0;
BEGIN
  FOR s IN SELECT * FROM public.escalation_health_signals LOOP
    IF s.failure_count < greatest(coalesce(_min_failures, 3), 1) THEN CONTINUE; END IF;
    PERFORM public.escalation_raise(
      'system_health',
      s.signal_key || '.' || coalesce(s.subject, 'unknown'),
      s.escalation_type::public.escalation_type,
      'system', NULL,
      coalesce(s.subject, s.signal_key),
      'critical'::public.escalation_severity,
      NULL,
      jsonb_build_object('signal', s.signal_key, 'subject', s.subject,
                         'failure_count', s.failure_count, 'last_seen', s.last_seen),
      NULL);
    v_raised := v_raised + 1;
  END LOOP;
  RETURN jsonb_build_object('raised', v_raised);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_hub_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF NOT (public.has_complaint_perm(v_uid,'triage') OR public.has_complaint_perm(v_uid,'view_all') OR public.has_complaint_perm(v_uid,'escalate')) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;
  RETURN jsonb_build_object(
    'pending', (SELECT count(*) FROM public.complaint_escalation_cases WHERE status='pending'),
    'critical', (SELECT count(*) FROM public.complaint_escalation_cases WHERE severity='critical'),
    'escalated', (SELECT count(*) FROM public.complaint_escalation_cases WHERE status='escalated'),
    'active_rules', (SELECT count(*) FROM public.complaint_escalation_rules WHERE enabled=true),
    'total_rules', (SELECT count(*) FROM public.complaint_escalation_rules)
  );
END; $function$
;
CREATE OR REPLACE FUNCTION public.escalation_notify(_escalation_id uuid, _event_key text, _role text, _tier integer, _title text, _body text, _immediate boolean DEFAULT false, _dedupe_ref uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  e public.escalations;
  v_uid uuid;
  v_email text;
  v_sent integer := 0;
  v_channels text[];
  v_raw jsonb;
  v_ref uuid := coalesce(_dedupe_ref, gen_random_uuid());
BEGIN
  SELECT * INTO e FROM public.escalations WHERE id = _escalation_id;
  IF e.id IS NULL THEN RETURN 0; END IF;

  v_raw := public.escalation_tier_config(e.rule_id, _tier)->'channels';
  IF v_raw IS NULL OR jsonb_typeof(v_raw) <> 'array' OR jsonb_array_length(v_raw) = 0 THEN
    v_channels := ARRAY['in_app','email']::text[];
  ELSE
    v_channels := ARRAY(SELECT jsonb_array_elements_text(v_raw));
  END IF;

  FOR v_uid, v_email IN
    SELECT DISTINCT p.id, p.email
    FROM public.user_roles ur
    JOIN public.profiles p ON p.id = ur.user_id
    WHERE ur.role::text = _role
    UNION
    SELECT p.id, p.email FROM public.profiles p
    WHERE e.assigned_user_id IS NOT NULL AND p.id = e.assigned_user_id
  LOOP
    IF 'in_app' = ANY(v_channels) THEN
      INSERT INTO public.notifications
        (user_id, title, message, type, entity_type, entity_id, channel, severity, category,
         module, action_required, event_key, correlation_id, metadata, recipient_role,
         source_reference, source_route, system_required)
      VALUES
        (v_uid, _title, _body, 'alert', 'escalation', e.id::text, 'in_app',
         CASE e.severity WHEN 'critical' THEN 'critical' WHEN 'high' THEN 'high'
                         WHEN 'low' THEN 'low' ELSE 'medium' END::public.notification_severity,
         'action_required'::public.notification_category,
         'escalation_management', true, _event_key, e.correlation_id,
         jsonb_build_object('escalation_ref', e.escalation_ref, 'tier', _tier,
                            'source_module', e.source_module, 'escalation_type', e.escalation_type),
         _role, e.escalation_ref, '/admin/escalations',
         e.severity = 'critical');

      INSERT INTO public.escalation_notification_events
        (escalation_id, tier, event_key, recipient_role, recipient_user_id, channel, outcome)
      VALUES (e.id, _tier, _event_key, _role, v_uid, 'in_app', 'delivered');
    END IF;

    IF 'email' = ANY(v_channels) AND v_email IS NOT NULL AND v_email <> '' THEN
      INSERT INTO public.notification_outbox
        (event_key, entity_type, entity_id, recipient_user_id, recipient_email, channel,
         subject, body, payload, status, correlation_id, action_history_id)
      VALUES
        (_event_key, 'escalation', e.id, v_uid, v_email, 'email',
         _title, _body,
         jsonb_build_object('escalation_ref', e.escalation_ref, 'tier', _tier,
                            'severity', e.severity, 'immediate', _immediate),
         'pending', e.correlation_id, v_ref)
      ON CONFLICT (event_key, entity_id, COALESCE((recipient_user_id)::text, recipient_email),
                   channel, COALESCE((action_history_id)::text, ''::text))
      DO NOTHING;

      INSERT INTO public.escalation_notification_events
        (escalation_id, tier, event_key, recipient_role, recipient_user_id, channel, outcome)
      VALUES (e.id, _tier, _event_key, _role, v_uid, 'email', 'queued');
    END IF;

    v_sent := v_sent + 1;
  END LOOP;

  IF v_sent = 0 THEN
    INSERT INTO public.escalation_notification_events
      (escalation_id, tier, event_key, recipient_role, channel, outcome, detail)
    VALUES (e.id, _tier, _event_key, _role, 'in_app', 'no_recipient',
            jsonb_build_object('reason', 'no user holds role ' || coalesce(_role, '(null)')));
  END IF;

  RETURN v_sent;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_raise(_source_module text, _source_event text, _escalation_type escalation_type, _source_entity_type text DEFAULT NULL::text, _source_entity_id uuid DEFAULT NULL::uuid, _source_reference text DEFAULT NULL::text, _severity escalation_severity DEFAULT NULL::escalation_severity, _source_rule_id uuid DEFAULT NULL::uuid, _metadata jsonb DEFAULT '{}'::jsonb, _correlation_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule public.escalation_rules;
  v_id uuid;
  v_existing uuid;
  v_sev public.escalation_severity;
  v_ack timestamptz;
  v_res timestamptz;
  v_cfg jsonb;
  v_event_id uuid;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_internal_staff(auth.uid()) THEN
    RAISE EXCEPTION 'permission denied: escalation_management.raise' USING ERRCODE = '42501';
  END IF;

  SELECT id INTO v_existing
  FROM public.escalations
  WHERE source_module = _source_module
    AND source_event = _source_event
    AND coalesce(source_entity_id, '00000000-0000-0000-0000-000000000000') = coalesce(_source_entity_id, '00000000-0000-0000-0000-000000000000')
    AND coalesce(source_rule_id, '00000000-0000-0000-0000-000000000000') = coalesce(_source_rule_id, '00000000-0000-0000-0000-000000000000')
    AND status IN ('open','acknowledged','in_progress','escalated');
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;

  SELECT * INTO v_rule
  FROM public.escalation_rules
  WHERE source_module = _source_module
    AND escalation_type = _escalation_type
    AND is_active
  ORDER BY created_at
  LIMIT 1;

  v_sev := coalesce(_severity, v_rule.default_severity, 'medium');
  v_cfg := public.escalation_tier_config(v_rule.id, 0);
  v_ack := public.escalation_deadline(v_rule.id, now(), (v_cfg->>'threshold')::int);
  v_res := public.escalation_deadline(v_rule.id, now(), v_rule.resolution_threshold_minutes);

  INSERT INTO public.escalations
    (source_module, source_event, source_rule_id, source_entity_type, source_entity_id,
     source_reference, escalation_type, severity, current_tier, status, rule_id,
     assigned_role, acknowledgement_deadline, resolution_deadline, next_auto_escalation_at,
     correlation_id, metadata, created_by)
  VALUES
    (_source_module, _source_event, _source_rule_id, _source_entity_type, _source_entity_id,
     _source_reference, _escalation_type, v_sev, 0, 'open', v_rule.id,
     v_cfg->>'role', v_ack, v_res, v_ack,
     coalesce(_correlation_id, gen_random_uuid()), coalesce(_metadata, '{}'::jsonb), auth.uid())
  RETURNING id INTO v_id;

  INSERT INTO public.escalation_tier_events
    (escalation_id, from_tier, to_tier, trigger_source, recipient_role, reason, acknowledgement_deadline, actor_id)
  VALUES (v_id, NULL, 0, 'automatic', v_cfg->>'role',
          'Escalation raised from ' || _source_module || ' (' || _source_event || ')', v_ack, auth.uid())
  RETURNING id INTO v_event_id;

  PERFORM public.escalation_notify(
    v_id, 'escalation.raised', v_cfg->>'role', 0,
    format('[%s] %s escalation raised', upper(v_sev::text), replace(_escalation_type::text, '_', ' ')),
    format('Escalation %s was raised from %s. Source: %s. Please acknowledge before %s.',
           (SELECT escalation_ref FROM public.escalations WHERE id = v_id),
           _source_module, coalesce(_source_reference, coalesce(_source_entity_id::text, 'n/a')),
           coalesce(to_char(v_ack, 'DD Mon YYYY HH24:MI'), 'the configured deadline')),
    v_sev = 'critical', v_event_id);

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_resolve(_id uuid, _resolution_narrative text, _root_cause text DEFAULT NULL::text, _close boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e public.escalations; v_role text; v_count integer := 0; v_ref uuid := gen_random_uuid();
BEGIN
  PERFORM public.enforce_permission('escalation_management', 'resolve');

  IF coalesce(length(btrim(_resolution_narrative)), 0) < 50 THEN
    RAISE EXCEPTION 'resolution_narrative_too_short: at least 50 characters are required';
  END IF;

  SELECT * INTO e FROM public.escalations WHERE id = _id FOR UPDATE;
  IF e.id IS NULL THEN RAISE EXCEPTION 'escalation_not_found'; END IF;
  IF e.status IN ('resolved','closed') THEN RAISE EXCEPTION 'escalation_is_terminal'; END IF;

  UPDATE public.escalations
  SET status = CASE WHEN _close THEN 'closed' ELSE 'resolved' END,
      resolution_narrative = btrim(_resolution_narrative),
      root_cause = coalesce(nullif(btrim(_root_cause), ''), root_cause),
      resolved_at = now(),
      resolved_by = auth.uid(),
      next_auto_escalation_at = NULL
  WHERE id = _id;

  INSERT INTO public.escalation_ownership_events
    (escalation_id, from_user_id, to_user_id, event_type, note, actor_id)
  VALUES (_id, e.assigned_user_id, auth.uid(),
          CASE WHEN _close THEN 'closed' ELSE 'resolved' END,
          left(btrim(_resolution_narrative), 500), auth.uid());

  FOR v_role IN
    SELECT DISTINCT recipient_role FROM public.escalation_tier_events
    WHERE escalation_id = _id AND recipient_role IS NOT NULL
  LOOP
    v_count := v_count + public.escalation_notify(
      _id, 'escalation.resolved', v_role, e.current_tier,
      format('Escalation %s resolved', e.escalation_ref),
      format('Escalation %s (%s from %s) was resolved.%s%sResolution: %s',
             e.escalation_ref, replace(e.escalation_type::text,'_',' '), e.source_module,
             E'\n', E'\n', btrim(_resolution_narrative)),
      false, v_ref);
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'notified', v_count,
                            'status', CASE WHEN _close THEN 'closed' ELSE 'resolved' END);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_rule_preview(_rule_id uuid, _from timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.escalation_rules; v_out jsonb := '[]'::jsonb; t integer; cfg jsonb; v_at timestamptz;
BEGIN
  PERFORM public.enforce_permission('escalation_management', 'view');
  SELECT * INTO r FROM public.escalation_rules WHERE id = _rule_id;
  IF r.id IS NULL THEN RAISE EXCEPTION 'rule_not_found'; END IF;

  v_at := _from;
  FOR t IN 0..3 LOOP
    cfg := public.escalation_tier_config(_rule_id, t);
    IF cfg IS NULL OR coalesce(cfg->>'role','') = '' THEN CONTINUE; END IF;
    v_out := v_out || jsonb_build_object(
      'tier', t,
      'recipient_role', cfg->>'role',
      'channels', cfg->'channels',
      'notified_at', v_at,
      'acknowledge_by', public.escalation_deadline(_rule_id, v_at, (cfg->>'threshold')::int));
    v_at := coalesce(public.escalation_deadline(_rule_id, v_at, (cfg->>'threshold')::int), v_at);
  END LOOP;

  RETURN jsonb_build_object(
    'rule', to_jsonb(r),
    'tiers', v_out,
    'resolve_by', public.escalation_deadline(_rule_id, _from, r.resolution_threshold_minutes));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_rule_save(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid := nullif(_payload->>'id','')::uuid;
BEGIN
  PERFORM public.enforce_permission('escalation_management', 'configure');

  IF coalesce(btrim(_payload->>'name'), '') = '' THEN
    RAISE EXCEPTION 'rule_name_required';
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.escalation_rules (
      name, description, source_module, escalation_type, default_severity,
      initial_recipient_role,
      tier1_recipient_role, tier1_ack_threshold_minutes, tier1_template_id, tier1_channels,
      tier2_recipient_role, tier2_ack_threshold_minutes, tier2_template_id, tier2_channels,
      tier3_recipient_role, tier3_ack_threshold_minutes, tier3_template_id, tier3_channels,
      resolution_threshold_minutes, pause_on_acknowledgement, business_hours_only,
      business_calendar_profile_id, create_task, create_case, is_active, created_by, updated_by)
    VALUES (
      btrim(_payload->>'name'), nullif(_payload->>'description',''),
      _payload->>'source_module', (_payload->>'escalation_type')::public.escalation_type,
      coalesce(nullif(_payload->>'default_severity','')::public.escalation_severity, 'medium'),
      _payload->>'initial_recipient_role',
      nullif(_payload->>'tier1_recipient_role',''), nullif(_payload->>'tier1_ack_threshold_minutes','')::int,
      nullif(_payload->>'tier1_template_id','')::uuid,
      coalesce((SELECT array_agg(v::text) FROM jsonb_array_elements_text(coalesce(_payload->'tier1_channels','[]'::jsonb)) v), ARRAY['in_app','email']),
      nullif(_payload->>'tier2_recipient_role',''), nullif(_payload->>'tier2_ack_threshold_minutes','')::int,
      nullif(_payload->>'tier2_template_id','')::uuid,
      coalesce((SELECT array_agg(v::text) FROM jsonb_array_elements_text(coalesce(_payload->'tier2_channels','[]'::jsonb)) v), ARRAY['in_app','email']),
      nullif(_payload->>'tier3_recipient_role',''), nullif(_payload->>'tier3_ack_threshold_minutes','')::int,
      nullif(_payload->>'tier3_template_id','')::uuid,
      coalesce((SELECT array_agg(v::text) FROM jsonb_array_elements_text(coalesce(_payload->'tier3_channels','[]'::jsonb)) v), ARRAY['in_app','email']),
      nullif(_payload->>'resolution_threshold_minutes','')::int,
      coalesce((_payload->>'pause_on_acknowledgement')::boolean, true),
      coalesce((_payload->>'business_hours_only')::boolean, false),
      nullif(_payload->>'business_calendar_profile_id','')::uuid,
      coalesce((_payload->>'create_task')::boolean, false),
      coalesce((_payload->>'create_case')::boolean, false),
      coalesce((_payload->>'is_active')::boolean, true),
      auth.uid(), auth.uid())
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.escalation_rules SET
      name = coalesce(btrim(_payload->>'name'), name),
      description = coalesce(nullif(_payload->>'description',''), description),
      default_severity = coalesce(nullif(_payload->>'default_severity','')::public.escalation_severity, default_severity),
      initial_recipient_role = coalesce(nullif(_payload->>'initial_recipient_role',''), initial_recipient_role),
      tier1_recipient_role = nullif(_payload->>'tier1_recipient_role',''),
      tier1_ack_threshold_minutes = nullif(_payload->>'tier1_ack_threshold_minutes','')::int,
      tier1_template_id = nullif(_payload->>'tier1_template_id','')::uuid,
      tier1_channels = coalesce((SELECT array_agg(v::text) FROM jsonb_array_elements_text(_payload->'tier1_channels') v), tier1_channels),
      tier2_recipient_role = nullif(_payload->>'tier2_recipient_role',''),
      tier2_ack_threshold_minutes = nullif(_payload->>'tier2_ack_threshold_minutes','')::int,
      tier2_template_id = nullif(_payload->>'tier2_template_id','')::uuid,
      tier2_channels = coalesce((SELECT array_agg(v::text) FROM jsonb_array_elements_text(_payload->'tier2_channels') v), tier2_channels),
      tier3_recipient_role = nullif(_payload->>'tier3_recipient_role',''),
      tier3_ack_threshold_minutes = nullif(_payload->>'tier3_ack_threshold_minutes','')::int,
      tier3_template_id = nullif(_payload->>'tier3_template_id','')::uuid,
      tier3_channels = coalesce((SELECT array_agg(v::text) FROM jsonb_array_elements_text(_payload->'tier3_channels') v), tier3_channels),
      resolution_threshold_minutes = nullif(_payload->>'resolution_threshold_minutes','')::int,
      pause_on_acknowledgement = coalesce((_payload->>'pause_on_acknowledgement')::boolean, pause_on_acknowledgement),
      business_hours_only = coalesce((_payload->>'business_hours_only')::boolean, business_hours_only),
      business_calendar_profile_id = nullif(_payload->>'business_calendar_profile_id','')::uuid,
      create_task = coalesce((_payload->>'create_task')::boolean, create_task),
      create_case = coalesce((_payload->>'create_case')::boolean, create_case),
      is_active = coalesce((_payload->>'is_active')::boolean, is_active),
      updated_by = auth.uid(),
      updated_at = now()
    WHERE id = v_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'rule_not_found'; END IF;
  END IF;

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_rules_list()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.enforce_permission('escalation_management', 'view');
  RETURN (
    SELECT coalesce(jsonb_agg(to_jsonb(r) || jsonb_build_object(
             'active_escalations',
             (SELECT count(*) FROM public.escalations e
               WHERE e.rule_id = r.id AND e.status NOT IN ('resolved','closed'))
           ) ORDER BY r.source_module, r.name), '[]'::jsonb)
    FROM public.escalation_rules r
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.enforce_permission('escalation_management', 'view');
  RETURN (
    SELECT jsonb_build_object(
      'open', count(*) FILTER (WHERE status IN ('open','acknowledged','in_progress','escalated')),
      'unacknowledged_overdue', count(*) FILTER (WHERE acknowledged_at IS NULL AND acknowledgement_deadline < now() AND status NOT IN ('resolved','closed')),
      'tier3', count(*) FILTER (WHERE current_tier = 3 AND status NOT IN ('resolved','closed')),
      'resolution_breached', count(*) FILTER (WHERE resolved_at IS NULL AND resolution_deadline < now() AND status NOT IN ('resolved','closed')),
      'critical', count(*) FILTER (WHERE severity = 'critical' AND status NOT IN ('resolved','closed')),
      'resolved_30d', count(*) FILTER (WHERE resolved_at > now() - interval '30 days')
    ) FROM public.escalations
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  e record; v_advanced integer := 0; v_scanned integer := 0; v_maxed integer := 0; v_res jsonb;
BEGIN
  FOR e IN
    SELECT id FROM public.escalations
    WHERE status IN ('open','acknowledged','in_progress','escalated')
      AND auto_escalate_paused_at IS NULL
      AND next_auto_escalation_at IS NOT NULL
      AND next_auto_escalation_at < now()
    ORDER BY severity, next_auto_escalation_at
    LIMIT 500
  LOOP
    v_scanned := v_scanned + 1;
    v_res := public.escalation_advance_tier(e.id, 'automatic', NULL);
    IF (v_res->>'ok')::boolean THEN
      v_advanced := v_advanced + 1;
    ELSE
      v_maxed := v_maxed + 1;
      UPDATE public.escalations SET next_auto_escalation_at = NULL WHERE id = e.id;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('scanned', v_scanned, 'advanced', v_advanced, 'terminal_tier', v_maxed)
      || public.escalation_health_sweep(3);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_take_ownership(_id uuid, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e public.escalations;
BEGIN
  PERFORM public.enforce_permission('escalation_management', 'own');
  SELECT * INTO e FROM public.escalations WHERE id = _id FOR UPDATE;
  IF e.id IS NULL THEN RAISE EXCEPTION 'escalation_not_found'; END IF;
  IF e.status IN ('resolved','closed') THEN RAISE EXCEPTION 'escalation_is_terminal'; END IF;

  UPDATE public.escalations
  SET assigned_user_id = auth.uid(),
      status = CASE WHEN status = 'open' THEN 'in_progress' ELSE status END
  WHERE id = _id;

  INSERT INTO public.escalation_ownership_events
    (escalation_id, from_user_id, to_user_id, from_role, to_role, event_type, note, actor_id)
  VALUES (_id, e.assigned_user_id, auth.uid(), e.assigned_role, e.assigned_role, 'ownership_taken', _note, auth.uid());

  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalation_tier_config(_rule_id uuid, _tier integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.escalation_rules;
BEGIN
  SELECT * INTO r FROM public.escalation_rules WHERE id = _rule_id;
  IF r.id IS NULL THEN RETURN NULL; END IF;
  RETURN CASE _tier
    WHEN 0 THEN jsonb_build_object('tier',0,'role',r.initial_recipient_role,
                  'threshold', r.tier1_ack_threshold_minutes,'channels', to_jsonb(r.tier1_channels),'template_id', r.tier1_template_id)
    WHEN 1 THEN jsonb_build_object('tier',1,'role',r.tier1_recipient_role,
                  'threshold', r.tier2_ack_threshold_minutes,'channels', to_jsonb(r.tier1_channels),'template_id', r.tier1_template_id)
    WHEN 2 THEN jsonb_build_object('tier',2,'role',r.tier2_recipient_role,
                  'threshold', r.tier3_ack_threshold_minutes,'channels', to_jsonb(r.tier2_channels),'template_id', r.tier2_template_id)
    WHEN 3 THEN jsonb_build_object('tier',3,'role',r.tier3_recipient_role,
                  'threshold', NULL,'channels', to_jsonb(r.tier3_channels),'template_id', r.tier3_template_id)
    ELSE NULL END;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.evaluate_all_complaint_escalations()
 RETURNS TABLE(scanned integer, escalated integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_c record;
  v_scanned integer := 0;
  v_escalated integer := 0;
  v_opened integer;
BEGIN
  FOR v_c IN
    SELECT id FROM public.complaints
     WHERE status NOT IN ('closed','withdrawn','rejected')
  LOOP
    v_scanned := v_scanned + 1;
    BEGIN
      v_opened := public.evaluate_complaint_escalations_v2(v_c.id);
      v_escalated := v_escalated + coalesce(v_opened,0);
    EXCEPTION WHEN OTHERS THEN
      -- Never abort the sweep on a single-record failure
      NULL;
    END;
  END LOOP;
  RETURN QUERY SELECT v_scanned, v_escalated;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.evaluate_complaint_escalations(_complaint_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c RECORD;
  r RECORD;
  age_days integer;
  volume_count integer;
  should_fire boolean;
  reason text;
  fired integer := 0;
  v_case_id uuid;
BEGIN
  SELECT id, subject, licensee_id, severity, created_at, resolved_at, closed_at, status
    INTO c FROM public.complaints WHERE id = _complaint_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  -- Skip terminal complaints
  IF c.resolved_at IS NOT NULL OR c.closed_at IS NOT NULL
     OR c.status IN ('resolved','closed','withdrawn','dismissed') THEN
    RETURN 0;
  END IF;

  age_days := GREATEST(0, EXTRACT(day FROM (now() - c.created_at))::int);

  FOR r IN SELECT * FROM public.complaint_escalation_rules WHERE enabled = true
  LOOP
    should_fire := false;
    reason := NULL;

    IF r.criterion = 'age' THEN
      IF age_days >= COALESCE((r.thresholds->>'maxAgeDays')::int, 999999) THEN
        should_fire := true;
        reason := format('Open for %s days (threshold %s)', age_days, r.thresholds->>'maxAgeDays');
      END IF;

    ELSIF r.criterion = 'harm' OR r.criterion = 'risk_rating' THEN
      -- Both use complaint severity as proxy
      IF c.severity IS NOT NULL AND
         (SELECT CASE c.severity WHEN 'critical' THEN 4 WHEN 'high' THEN 3 WHEN 'medium' THEN 2 ELSE 1 END)
         >=
         (SELECT CASE COALESCE(r.thresholds->>'minSeverity', r.thresholds->>'minRisk','high')
                 WHEN 'critical' THEN 4 WHEN 'high' THEN 3 WHEN 'medium' THEN 2 ELSE 1 END)
      THEN
        should_fire := true;
        reason := format('Severity %s meets threshold %s', c.severity,
                         COALESCE(r.thresholds->>'minSeverity', r.thresholds->>'minRisk'));
      END IF;

    ELSIF r.criterion = 'volume' THEN
      IF c.licensee_id IS NOT NULL THEN
        SELECT count(*) INTO volume_count FROM public.complaints
         WHERE licensee_id = c.licensee_id
           AND created_at >= now() - (COALESCE((r.thresholds->>'windowDays')::int, 30) || ' days')::interval;
        IF volume_count >= COALESCE((r.thresholds->>'minCount')::int, 999999) THEN
          should_fire := true;
          reason := format('%s complaints on same licensee in %s days', volume_count, r.thresholds->>'windowDays');
        END IF;
      END IF;
    END IF;

    IF NOT should_fire THEN CONTINUE; END IF;

    -- Skip if active case already exists for this kind
    IF EXISTS (
      SELECT 1 FROM public.complaint_escalation_cases
       WHERE complaint_id = _complaint_id
         AND rule_key = r.key
         AND status IN ('pending','acknowledged','escalated','snoozed')
    ) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.complaint_escalation_cases
      (complaint_id, rule_id, rule_key, rule_label, target_tier, severity, trigger_reason, status)
    VALUES
      (_complaint_id, r.id, r.key, r.label, r.target_tier,
       COALESCE(c.severity,'medium'), reason, 'pending')
    RETURNING id INTO v_case_id;

    INSERT INTO public.audit_logs (user_id, action, table_name, record_id, new_values)
    VALUES (NULL, 'auto_escalate', 'complaint_escalation_cases', v_case_id,
            jsonb_build_object('complaint_id', _complaint_id, 'rule_key', r.key,
                               'target_tier', r.target_tier, 'reason', reason));

    fired := fired + 1;
  END LOOP;

  RETURN fired;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.evaluate_complaint_escalations_v2(_complaint_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_a integer := 0;
  v_b integer := 0;
BEGIN
  v_a := public.evaluate_complaint_escalations(_complaint_id);
  v_b := public.evaluate_complaint_vulnerability_escalations(_complaint_id);
  RETURN v_a + v_b;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.evaluate_complaint_vulnerability_escalations(_complaint_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_c public.complaints%ROWTYPE;
  v_rule public.complaint_escalation_rules%ROWTYPE;
  v_opened integer := 0;
  v_thresholds jsonb;
  v_required_state text;
  v_required_cats text[];
BEGIN
  SELECT * INTO v_c FROM public.complaints WHERE id = _complaint_id;
  IF NOT FOUND OR v_c.status IN ('closed','withdrawn','rejected') THEN
    RETURN 0;
  END IF;

  FOR v_rule IN
    SELECT * FROM public.complaint_escalation_rules
     WHERE criterion = 'vulnerability'
       AND coalesce(enabled, true)
       AND (regulator_id IS NULL OR regulator_id = v_c.regulator_id)
  LOOP
    v_thresholds := coalesce(v_rule.thresholds, '{}'::jsonb);
    v_required_state := NULLIF(v_thresholds->>'review_state','');
    v_required_cats := CASE
      WHEN jsonb_typeof(v_thresholds->'categories') = 'array'
      THEN ARRAY(SELECT jsonb_array_elements_text(v_thresholds->'categories'))
      ELSE NULL
    END;

    -- Rule fires when:
    --   * indicator is true, AND
    --   * (no state filter) OR review_state matches, AND
    --   * (no category filter) OR category in required set
    IF v_c.vulnerability_indicator
       AND (v_required_state IS NULL OR v_c.vulnerability_review_state::text = v_required_state)
       AND (v_required_cats IS NULL OR v_c.vulnerability_category = ANY(v_required_cats))
    THEN
      -- Dedupe: no active case of same rule for this complaint
      IF NOT EXISTS (
        SELECT 1 FROM public.complaint_escalation_cases ec
         WHERE ec.complaint_id = _complaint_id
           AND ec.rule_key = v_rule.key
           AND ec.status = 'open'
      ) THEN
        INSERT INTO public.complaint_escalation_cases (
          complaint_id, rule_key, criterion, target_tier, status,
          triggered_at, regulator_id
        ) VALUES (
          _complaint_id, v_rule.key, 'vulnerability',
          coalesce(v_rule.target_tier, 'head_of_unit'), 'open',
          now(), v_c.regulator_id
        );
        v_opened := v_opened + 1;

        INSERT INTO public.audit_logs (entity_type, entity_id, action, changes, user_id)
        VALUES ('complaint', _complaint_id, 'escalation.vulnerability.opened',
                jsonb_build_object('rule_key', v_rule.key), NULL);
      END IF;
    END IF;
  END LOOP;

  RETURN v_opened;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.evaluate_return_validations(_return_id uuid, _form_data jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_cfg uuid; v_rules jsonb;
BEGIN
  SELECT rf.return_configuration_id INTO v_cfg FROM public.returns_filed rf WHERE rf.id = _return_id;
  IF v_cfg IS NULL THEN
    RETURN jsonb_build_object('return_id', _return_id, 'rules', '[]'::jsonb, 'form_data', COALESCE(_form_data,'{}'::jsonb));
  END IF;
  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.severity DESC, r.name), '[]'::jsonb)
  INTO v_rules FROM public.return_validation_rules r
  WHERE r.return_config_id = v_cfg AND r.is_active = true;
  RETURN jsonb_build_object('return_id', _return_id, 'return_config_id', v_cfg, 'rules', v_rules, 'form_data', COALESCE(_form_data,'{}'::jsonb));
END; $function$
;
CREATE OR REPLACE FUNCTION public.evaluate_stress_indicators_for_filing(_return_filing_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ent_id uuid;
  ent_sector uuid;
  ent_sub uuid;
  v_version_id uuid;
  new_events jsonb := '[]'::jsonb;
  updated_events jsonb := '[]'::jsonb;
  ind RECORD;
  fact RECORD;
  match boolean;
  ins_id uuid;
  was_new boolean;
BEGIN
  IF NOT (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(), 'prudential_supervision', 'edit')) THEN
    RAISE EXCEPTION 'not authorised to evaluate stress indicators';
  END IF;

  SELECT w.entity_id, COALESCE(w.accepted_version_id, w.current_version_id)
    INTO ent_id, v_version_id
    FROM public.v_return_filing_workflow_state w
   WHERE w.filing_id = _return_filing_id
     AND w.status <> 'WITHDRAWN';

  IF ent_id IS NULL OR v_version_id IS NULL THEN
    RETURN jsonb_build_object('new_events','[]'::jsonb,'updated_events','[]'::jsonb);
  END IF;

  SELECT l.sector_id, l.sub_sector_id INTO ent_sector, ent_sub
    FROM public.licensees l WHERE l.id = ent_id;

  FOR ind IN
    SELECT * FROM public.prudential_stress_indicators
    WHERE is_active = true
      AND (sector_id IS NULL OR sector_id = ent_sector)
      AND (sub_sector_id IS NULL OR sub_sector_id = ent_sub)
  LOOP
    FOR fact IN
      SELECT mv.value_numeric AS value
        FROM public.return_metric_values mv
        JOIN public.regulatory_metrics m ON m.id = mv.regulatory_metric_id
       WHERE mv.return_filing_version_id = v_version_id
         AND mv.value_numeric IS NOT NULL
         AND upper(m.code) = upper(ind.metric_key)
    LOOP
      match := CASE ind.direction
        WHEN 'gt'  THEN fact.value >  ind.threshold_value
        WHEN 'gte' THEN fact.value >= ind.threshold_value
        WHEN 'lt'  THEN fact.value <  ind.threshold_value
        WHEN 'lte' THEN fact.value <= ind.threshold_value
        WHEN 'eq'  THEN fact.value =  ind.threshold_value
        ELSE false END;
      IF match THEN
        WITH up AS (
          INSERT INTO public.prudential_stress_events
            (indicator_id, entity_id, return_filing_id, return_filing_version_id, observed_value)
          VALUES (ind.id, ent_id, _return_filing_id, v_version_id, fact.value)
          ON CONFLICT (indicator_id, return_filing_id) WHERE return_filing_id IS NOT NULL
          DO UPDATE SET observed_value = EXCLUDED.observed_value,
                        return_filing_version_id = EXCLUDED.return_filing_version_id
          RETURNING id, (xmax = 0) AS inserted
        )
        SELECT id, inserted INTO ins_id, was_new FROM up;
        IF was_new THEN
          new_events := new_events || jsonb_build_object(
            'event_id', ins_id, 'indicator_id', ind.id, 'metric_key', ind.metric_key,
            'label', ind.label, 'severity', ind.severity, 'observed_value', fact.value,
            'threshold_value', ind.threshold_value, 'direction', ind.direction,
            'escalate', ind.escalate, 'entity_id', ent_id,
            'return_filing_id', _return_filing_id, 'return_filing_version_id', v_version_id
          );
        ELSE
          updated_events := updated_events || jsonb_build_object(
            'event_id', ins_id, 'indicator_id', ind.id, 'metric_key', ind.metric_key,
            'label', ind.label, 'severity', ind.severity, 'observed_value', fact.value,
            'threshold_value', ind.threshold_value, 'direction', ind.direction,
            'escalate', ind.escalate, 'entity_id', ent_id,
            'return_filing_id', _return_filing_id, 'return_filing_version_id', v_version_id
          );
        END IF;
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('new_events', new_events, 'updated_events', updated_events);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.evaluate_stress_indicators_for_return(_return_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ent_id uuid;
  ent_sector uuid;
  ent_sub uuid;
  new_events jsonb := '[]'::jsonb;
  updated_events jsonb := '[]'::jsonb;
  ind RECORD;
  ratio RECORD;
  match boolean;
  ins_id uuid;
  was_new boolean;
BEGIN
  SELECT rf.entity_id INTO ent_id FROM public.returns_filed rf WHERE rf.id = _return_id;
  IF ent_id IS NULL THEN
    RETURN jsonb_build_object('new_events','[]'::jsonb,'updated_events','[]'::jsonb);
  END IF;
  SELECT l.sector_id, l.sub_sector_id INTO ent_sector, ent_sub FROM public.licensees l WHERE l.id = ent_id;

  FOR ind IN
    SELECT * FROM public.prudential_stress_indicators
    WHERE is_active = true
      AND (sector_id IS NULL OR sector_id = ent_sector)
      AND (sub_sector_id IS NULL OR sub_sector_id = ent_sub)
  LOOP
    FOR ratio IN
      SELECT * FROM public.return_calculated_ratios
      WHERE return_id = _return_id AND ratio_key = ind.metric_key
    LOOP
      match := CASE ind.direction
        WHEN 'gt'  THEN ratio.value >  ind.threshold_value
        WHEN 'gte' THEN ratio.value >= ind.threshold_value
        WHEN 'lt'  THEN ratio.value <  ind.threshold_value
        WHEN 'lte' THEN ratio.value <= ind.threshold_value
        WHEN 'eq'  THEN ratio.value =  ind.threshold_value
        ELSE false END;
      IF match THEN
        -- Detect newness via xmax=0 trick on the RETURNING row
        WITH up AS (
          INSERT INTO public.prudential_stress_events (indicator_id, entity_id, return_id, observed_value)
          VALUES (ind.id, ent_id, _return_id, ratio.value)
          ON CONFLICT (indicator_id, return_id)
          DO UPDATE SET observed_value = EXCLUDED.observed_value
          RETURNING id, (xmax = 0) AS inserted
        )
        SELECT id, inserted INTO ins_id, was_new FROM up;
        IF was_new THEN
          new_events := new_events || jsonb_build_object(
            'event_id', ins_id, 'indicator_id', ind.id, 'metric_key', ind.metric_key,
            'label', ind.label, 'severity', ind.severity, 'observed_value', ratio.value,
            'threshold_value', ind.threshold_value, 'direction', ind.direction,
            'escalate', ind.escalate, 'entity_id', ent_id, 'return_id', _return_id
          );
        ELSE
          updated_events := updated_events || jsonb_build_object(
            'event_id', ins_id, 'indicator_id', ind.id, 'observed_value', ratio.value
          );
        END IF;
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('new_events', new_events, 'updated_events', updated_events);
END $function$
;
CREATE OR REPLACE FUNCTION public.examination_create(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _id uuid; _after jsonb;
BEGIN
  _uid := public.conduct_require('prudential_supervision','manage_examination');
  IF nullif(_payload->>'entity_id','') IS NULL THEN
    RAISE EXCEPTION 'entity_id is required' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.examinations (entity_id, regulator_id, sector_id, title, examination_type, stage, risk_rating,
        period_under_review_start, period_under_review_end, fieldwork_start, fieldwork_end, lead_examiner_id, created_by)
  VALUES ((_payload->>'entity_id')::uuid, nullif(_payload->>'regulator_id','')::uuid, nullif(_payload->>'sector_id','')::uuid,
          nullif(_payload->>'title',''), nullif(_payload->>'examination_type',''),
          coalesce(nullif(_payload->>'stage',''),'planned'), nullif(_payload->>'risk_rating',''),
          nullif(_payload->>'period_under_review_start','')::date, nullif(_payload->>'period_under_review_end','')::date,
          nullif(_payload->>'fieldwork_start','')::date, nullif(_payload->>'fieldwork_end','')::date,
          coalesce(nullif(_payload->>'lead_examiner_id','')::uuid, _uid), _uid)
  RETURNING id INTO _id;
  SELECT to_jsonb(e) INTO _after FROM public.examinations e WHERE e.id=_id;
  PERFORM public.log_compliance_audit('CREATE'::compliance_audit_action,'examination',_id::text,NULL,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.examination_create_remediation_action(_finding_id uuid, _due_date date, _assigned_to uuid DEFAULT NULL::uuid, _entity_contact text DEFAULT NULL::text, _description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_f public.examination_findings;
  v_entity uuid;
  v_action_id uuid;
BEGIN
  IF NOT (public.can_act_on_examination(auth.uid(), 'manage_remediation')
          OR public.can_act_on_examination(auth.uid(), 'workflow_action')
          OR public.can_act_on_examination(auth.uid(), 'edit')) THEN
    RAISE EXCEPTION 'not_authorised_for_remediation';
  END IF;

  SELECT * INTO v_f FROM public.examination_findings WHERE id = _finding_id;
  IF v_f.id IS NULL THEN RAISE EXCEPTION 'finding_not_found'; END IF;
  IF v_f.remediation_action_id IS NOT NULL THEN RAISE EXCEPTION 'remediation_already_linked'; END IF;

  SELECT entity_id INTO v_entity FROM public.examinations WHERE id = v_f.examination_id;

  INSERT INTO public.prudential_actions (
    entity_id, source_type, source_id, action_type, title, description,
    severity, due_date, assigned_to, entity_contact, status, evidence_required, created_by)
  VALUES (
    v_entity, 'examination_finding', _finding_id, 'remediation_plan',
    v_f.title, COALESCE(_description, v_f.recommendation, v_f.observation),
    v_f.severity, _due_date, _assigned_to, _entity_contact, 'open', true, auth.uid())
  RETURNING id INTO v_action_id;

  UPDATE public.examination_findings
     SET remediation_action_id = v_action_id, status = 'remediation_pending',
         target_date = COALESCE(_due_date, target_date), updated_at = now()
   WHERE id = _finding_id;

  INSERT INTO public.examination_events (examination_id, event_type, actor_id, metadata)
  VALUES (v_f.examination_id, 'remediation_action_created', auth.uid(),
          jsonb_build_object('finding_id', _finding_id, 'action_id', v_action_id));

  RETURN jsonb_build_object('ok', true, 'action_id', v_action_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.examination_has_issued_report(_examination_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.examination_reports r
    WHERE r.examination_id = _examination_id
      AND r.issued_at IS NOT NULL
  );
$function$
;
CREATE OR REPLACE FUNCTION public.examination_report_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.approved_by IS NOT NULL AND NEW.prepared_by IS NOT NULL
     AND NEW.approved_by = NEW.prepared_by THEN
    RAISE EXCEPTION 'report_approver_must_differ_from_preparer';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.examination_set_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE seq int;
BEGIN
  IF NEW.reference IS NULL OR NEW.reference = '' THEN
    SELECT COALESCE(MAX((regexp_replace(reference, '^EXM-\d{4}-', ''))::int), 0) + 1
      INTO seq
      FROM public.examinations
     WHERE reference LIKE 'EXM-' || to_char(now(), 'YYYY') || '-%';
    NEW.reference := 'EXM-' || to_char(now(), 'YYYY') || '-' || lpad(seq::text, 5, '0');
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.examination_signoff_workpaper(_workpaper_id uuid, _role text, _notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_wp public.examination_workpapers;
BEGIN
  IF NOT (public.can_act_on_examination(auth.uid(), 'workflow_action')
          OR public.can_act_on_examination(auth.uid(), 'edit')) THEN
    RAISE EXCEPTION 'not_authorised_for_examination_workflow';
  END IF;
  SELECT * INTO v_wp FROM public.examination_workpapers WHERE id = _workpaper_id;
  IF v_wp.id IS NULL THEN RAISE EXCEPTION 'workpaper_not_found'; END IF;

  IF _role = 'preparer' THEN
    UPDATE public.examination_workpapers
       SET prepared_by = auth.uid(), prepared_at = now(), status = 'prepared', updated_at = now()
     WHERE id = _workpaper_id;
  ELSIF _role = 'reviewer' THEN
    IF v_wp.prepared_at IS NULL THEN RAISE EXCEPTION 'workpaper_not_prepared'; END IF;
    IF v_wp.prepared_by = auth.uid() THEN
      RAISE EXCEPTION 'workpaper_reviewer_must_differ_from_preparer';
    END IF;
    UPDATE public.examination_workpapers
       SET reviewed_by = auth.uid(), reviewed_at = now(), review_notes = _notes,
           status = 'reviewed', updated_at = now()
     WHERE id = _workpaper_id;
  ELSE
    RAISE EXCEPTION 'invalid_signoff_role';
  END IF;

  INSERT INTO public.examination_events (examination_id, event_type, actor_id, notes, metadata)
  VALUES (v_wp.examination_id, 'workpaper_' || _role || '_signoff', auth.uid(), _notes,
          jsonb_build_object('workpaper_id', _workpaper_id, 'area', v_wp.area));

  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.examination_transition_stage(_examination_id uuid, _to_stage text, _notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exam public.examinations;
  v_allowed text[];
  v_unreviewed int;
  v_open_findings int;
  v_open_actions int;
  v_scope_approved boolean;
  v_lead int;
BEGIN
  IF NOT (public.can_act_on_examination(auth.uid(), 'workflow_action')
          OR public.can_act_on_examination(auth.uid(), 'edit')) THEN
    RAISE EXCEPTION 'not_authorised_for_examination_workflow';
  END IF;

  SELECT * INTO v_exam FROM public.examinations WHERE id = _examination_id;
  IF v_exam.id IS NULL THEN RAISE EXCEPTION 'examination_not_found'; END IF;

  v_allowed := CASE v_exam.stage
    WHEN 'planned'             THEN ARRAY['scoping','cancelled']
    WHEN 'scoping'             THEN ARRAY['pre_exam_request','cancelled']
    WHEN 'pre_exam_request'    THEN ARRAY['fieldwork','cancelled']
    WHEN 'fieldwork'           THEN ARRAY['exit_meeting','cancelled']
    WHEN 'exit_meeting'        THEN ARRAY['draft_report','cancelled']
    WHEN 'draft_report'        THEN ARRAY['management_response','cancelled']
    WHEN 'management_response'  THEN ARRAY['final_report','draft_report','cancelled']
    WHEN 'final_report'        THEN ARRAY['remediation','closed']
    WHEN 'remediation'         THEN ARRAY['closed']
    ELSE ARRAY[]::text[]
  END;

  IF NOT (_to_stage = ANY (v_allowed)) THEN
    RAISE EXCEPTION 'invalid_stage_transition: % -> %', v_exam.stage, _to_stage;
  END IF;

  IF _to_stage = 'fieldwork' THEN
    SELECT approved_at IS NOT NULL INTO v_scope_approved
      FROM public.examination_scoping WHERE examination_id = _examination_id;
    IF COALESCE(v_scope_approved, false) = false THEN
      RAISE EXCEPTION 'scoping_memo_not_approved';
    END IF;
    SELECT count(*) INTO v_lead FROM public.examination_team_members
     WHERE examination_id = _examination_id AND team_role = 'lead_examiner';
    IF v_lead = 0 THEN RAISE EXCEPTION 'lead_examiner_not_assigned'; END IF;
  END IF;

  IF _to_stage = 'final_report' THEN
    SELECT count(*) INTO v_unreviewed FROM public.examination_workpapers
     WHERE examination_id = _examination_id AND reviewed_at IS NULL;
    IF v_unreviewed > 0 THEN RAISE EXCEPTION 'workpapers_pending_review'; END IF;
    SELECT count(*) INTO v_open_findings FROM public.examination_findings
     WHERE examination_id = _examination_id
       AND status = 'open' AND remediation_action_id IS NULL;
    IF v_open_findings > 0 THEN RAISE EXCEPTION 'findings_without_remediation'; END IF;
  END IF;

  IF _to_stage = 'closed' THEN
    SELECT count(*) INTO v_open_actions
      FROM public.examination_findings f
      JOIN public.prudential_actions a ON a.id = f.remediation_action_id
     WHERE f.examination_id = _examination_id
       AND a.status NOT IN ('completed','closed','waived','cancelled');
    IF v_open_actions > 0 THEN RAISE EXCEPTION 'open_remediation_actions'; END IF;
  END IF;

  UPDATE public.examinations
     SET stage = _to_stage,
         closed_at = CASE WHEN _to_stage = 'closed' THEN now() ELSE closed_at END,
         closed_by = CASE WHEN _to_stage = 'closed' THEN auth.uid() ELSE closed_by END,
         cancellation_reason = CASE WHEN _to_stage = 'cancelled' THEN _notes ELSE cancellation_reason END,
         updated_at = now()
   WHERE id = _examination_id;

  INSERT INTO public.examination_events (examination_id, event_type, from_stage, to_stage, actor_id, notes)
  VALUES (_examination_id, 'stage_change', v_exam.stage, _to_stage, auth.uid(), _notes);

  RETURN jsonb_build_object('ok', true, 'from_stage', v_exam.stage, 'to_stage', _to_stage);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.examination_update(_examination_id uuid, _patch jsonb, _rationale text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb;
BEGIN
  _uid := public.conduct_require('prudential_supervision','manage_examination');
  SELECT to_jsonb(e) INTO _before FROM public.examinations e WHERE e.id=_examination_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Examination not found' USING ERRCODE='P0002'; END IF;
  UPDATE public.examinations SET
    title = CASE WHEN _patch ? 'title' THEN nullif(_patch->>'title','') ELSE title END,
    examination_type = CASE WHEN _patch ? 'examination_type' THEN nullif(_patch->>'examination_type','') ELSE examination_type END,
    risk_rating = CASE WHEN _patch ? 'risk_rating' THEN nullif(_patch->>'risk_rating','') ELSE risk_rating END,
    period_under_review_start = CASE WHEN _patch ? 'period_under_review_start' THEN nullif(_patch->>'period_under_review_start','')::date ELSE period_under_review_start END,
    period_under_review_end = CASE WHEN _patch ? 'period_under_review_end' THEN nullif(_patch->>'period_under_review_end','')::date ELSE period_under_review_end END,
    fieldwork_start = CASE WHEN _patch ? 'fieldwork_start' THEN nullif(_patch->>'fieldwork_start','')::date ELSE fieldwork_start END,
    fieldwork_end = CASE WHEN _patch ? 'fieldwork_end' THEN nullif(_patch->>'fieldwork_end','')::date ELSE fieldwork_end END,
    lead_examiner_id = CASE WHEN _patch ? 'lead_examiner_id' THEN nullif(_patch->>'lead_examiner_id','')::uuid ELSE lead_examiner_id END,
    overall_conclusion = CASE WHEN _patch ? 'overall_conclusion' THEN nullif(_patch->>'overall_conclusion','') ELSE overall_conclusion END,
    updated_at = now()
  WHERE id=_examination_id RETURNING to_jsonb(examinations) INTO _after;
  PERFORM public.log_compliance_audit('UPDATE'::compliance_audit_action,'examination',_examination_id::text,_before,_after,_rationale);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.examination_workpaper_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.reviewed_by IS NOT NULL AND NEW.prepared_by IS NOT NULL
     AND NEW.reviewed_by = NEW.prepared_by THEN
    RAISE EXCEPTION 'workpaper_reviewer_must_differ_from_preparer';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.execute_complaint_workflow_action(_complaint_id uuid, _action_key text, _payload jsonb DEFAULT '{}'::jsonb, _expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_complaint public.complaints%ROWTYPE;
  v_instance public.workflow_instances%ROWTYPE;
  v_step public.approval_steps%ROWTYPE;
  v_action public.approval_step_actions%ROWTYPE;
  v_next_step public.approval_steps%ROWTYPE;
  v_user_role text; v_kind text;
  v_history_id uuid := gen_random_uuid();
  v_correlation uuid := gen_random_uuid();
  v_enf_id uuid; v_next_assignee uuid; v_next_role text;
  v_before jsonb; v_after jsonb; v_req jsonb;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT * INTO v_complaint FROM public.complaints WHERE id=_complaint_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'COMPLAINT_NOT_FOUND'; END IF;
  IF NOT (public.is_super_admin(v_user) OR public.has_complaint_perm(v_user, 'edit')) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  SELECT * INTO v_instance FROM public.workflow_instances
    WHERE entity_type='complaint' AND entity_id=_complaint_id AND status IN ('active','paused')
    ORDER BY started_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NO_ACTIVE_WORKFLOW'; END IF;

  IF _expected_updated_at IS NOT NULL AND v_instance.updated_at IS DISTINCT FROM _expected_updated_at THEN
    RAISE EXCEPTION 'STALE_STATE';
  END IF;

  SELECT * INTO v_step FROM public.approval_steps WHERE id=v_instance.current_step_id;
  SELECT * INTO v_action FROM public.approval_step_actions
    WHERE step_id=v_step.id AND action_key=_action_key AND is_enabled=true;
  IF NOT FOUND THEN RAISE EXCEPTION 'ACTION_NOT_ALLOWED_AT_STEP'; END IF;

  SELECT role::text INTO v_user_role FROM public.user_roles WHERE user_id=v_user LIMIT 1;
  IF array_length(v_action.allowed_role_slugs,1)>0
     AND NOT (v_action.allowed_role_slugs && public.user_workflow_role_slugs(v_user))
     AND NOT public.has_role(v_user,'super_admin'::app_role) THEN
    RAISE EXCEPTION 'ROLE_NOT_PERMITTED';
  END IF;

  FOR v_req IN SELECT * FROM jsonb_array_elements(v_action.required_fields) LOOP
    IF (v_req->>'required')::boolean IS TRUE AND (_payload -> (v_req->>'key')) IS NULL THEN
      RAISE EXCEPTION 'MISSING_REQUIRED_FIELD:%', v_req->>'key';
    END IF;
  END LOOP;

  v_kind := v_action.mutation_spec->>'kind';
  v_before := to_jsonb(v_complaint);

  IF v_kind='complaint_status' THEN
    UPDATE public.complaints SET status=v_action.mutation_spec->>'status', updated_at=now() WHERE id=_complaint_id;
  ELSIF v_kind='assign_investigator' THEN
    UPDATE public.complaints SET investigator_id=(_payload->>'investigator_id')::uuid, status='under_investigation', updated_at=now() WHERE id=_complaint_id;
  ELSIF v_kind='resolve_complaint' THEN
    UPDATE public.complaints SET status='resolved', resolution=COALESCE(_payload->>'resolution',resolution), resolution_notes=COALESCE(_payload->>'resolution',resolution_notes), resolved_at=now(), updated_at=now() WHERE id=_complaint_id;
  ELSIF v_kind='close_complaint' THEN
    UPDATE public.complaints SET status='closed', closure_reason=_payload->>'closure_reason', closed_at=now(), closed_by=v_user, updated_at=now() WHERE id=_complaint_id;
  ELSIF v_kind='escalate_to_enforcement' THEN
    IF (_payload->>'licensee_id') IS NOT NULL THEN
      UPDATE public.complaints SET licensee_id=(_payload->>'licensee_id')::uuid WHERE id=_complaint_id;
    END IF;
    INSERT INTO public.enforcement_actions (entity_id, case_number, enforcement_type, date_opened, status, description, findings, source_type, source_reference_id, opened_by)
    VALUES (
      (SELECT licensee_id FROM public.complaints WHERE id=_complaint_id),
      'ENF-'||to_char(now(),'YYYY')||'-'||lpad(nextval('public.enforcement_actions_seq')::text,5,'0'),
      'complaint_escalation', current_date,'open',
      'Escalated from complaint '||v_complaint.complaint_number,
      _payload->>'findings','complaint',_complaint_id,v_user
    ) RETURNING id INTO v_enf_id;
    UPDATE public.complaints SET enforcement_action_id=v_enf_id, updated_at=now() WHERE id=_complaint_id;
    INSERT INTO public.enforcement_case_events(case_id,event_type,actor_id,note) VALUES(v_enf_id,'case_opened',v_user,_payload->>'findings');
  ELSIF v_kind IN ('enforcement_notice','enforcement_response','enforcement_decision','enforcement_payment','enforcement_appeal','enforcement_close','enforcement_withdraw') THEN
    v_enf_id := v_complaint.enforcement_action_id;
    IF v_enf_id IS NULL THEN RAISE EXCEPTION 'NO_ENFORCEMENT_CASE'; END IF;
    IF v_kind='enforcement_notice' THEN
      UPDATE public.enforcement_actions SET status='notice_issued', notice_issued_at=now(), updated_at=now() WHERE id=v_enf_id;
      INSERT INTO public.enforcement_case_events(case_id,event_type,actor_id,note) VALUES(v_enf_id,'notice_issued',v_user,_payload->>'note');
    ELSIF v_kind='enforcement_response' THEN
      UPDATE public.enforcement_actions SET status='response_received', response_received_at=now(), response_summary=_payload->>'response_summary', updated_at=now() WHERE id=v_enf_id;
      INSERT INTO public.enforcement_case_events(case_id,event_type,actor_id,note) VALUES(v_enf_id,'response_received',v_user,_payload->>'response_summary');
    ELSIF v_kind='enforcement_decision' THEN
      UPDATE public.enforcement_actions SET status='decided', decision_at=now(), decision_outcome=_payload->>'decision_outcome', decision_rationale=_payload->>'decision_rationale', penalty_amount=NULLIF(_payload->>'penalty_amount','')::numeric, updated_at=now() WHERE id=v_enf_id;
      INSERT INTO public.enforcement_case_events(case_id,event_type,actor_id,note) VALUES(v_enf_id,'decision_recorded',v_user,_payload->>'decision_rationale');
    ELSIF v_kind='enforcement_payment' THEN
      UPDATE public.enforcement_actions SET penalty_paid_amount=COALESCE(penalty_paid_amount,0)+COALESCE(NULLIF(_payload->>'penalty_paid_amount','')::numeric,0), updated_at=now() WHERE id=v_enf_id;
      INSERT INTO public.enforcement_case_events(case_id,event_type,actor_id,note) VALUES(v_enf_id,'payment_received',v_user,_payload->>'penalty_paid_amount');
    ELSIF v_kind='enforcement_appeal' THEN
      UPDATE public.enforcement_actions SET status='appealed', updated_at=now() WHERE id=v_enf_id;
      INSERT INTO public.enforcement_case_events(case_id,event_type,actor_id,note) VALUES(v_enf_id,'appeal_filed',v_user,_payload->>'note');
    ELSIF v_kind='enforcement_close' THEN
      UPDATE public.enforcement_actions SET status='closed', closed_at=now(), closed_by=v_user, resolution_date=current_date, updated_at=now() WHERE id=v_enf_id;
      INSERT INTO public.enforcement_case_events(case_id,event_type,actor_id,note) VALUES(v_enf_id,'case_closed',v_user,_payload->>'note');
      UPDATE public.complaints SET status='closed', closed_at=now(), closed_by=v_user, closure_reason=_payload->>'note', updated_at=now() WHERE id=_complaint_id;
    ELSIF v_kind='enforcement_withdraw' THEN
      UPDATE public.enforcement_actions SET status='withdrawn', closed_at=now(), closed_by=v_user, updated_at=now() WHERE id=v_enf_id;
      INSERT INTO public.enforcement_case_events(case_id,event_type,actor_id,note) VALUES(v_enf_id,'case_withdrawn',v_user,_payload->>'note');
      UPDATE public.complaints SET status='closed', closed_at=now(), closed_by=v_user, closure_reason=_payload->>'note', updated_at=now() WHERE id=_complaint_id;
    END IF;
  END IF;

  SELECT * INTO v_complaint FROM public.complaints WHERE id=_complaint_id;
  v_after := to_jsonb(v_complaint);

  IF v_action.next_step_id IS NOT NULL THEN
    SELECT * INTO v_next_step FROM public.approval_steps WHERE id=v_action.next_step_id;

    IF v_action.next_assignee_rule->>'kind'='payload_user' THEN
      v_next_assignee := (_payload->>(v_action.next_assignee_rule->>'field'))::uuid;
    ELSIF v_action.next_assignee_rule->>'kind'='role' THEN
      v_next_role := v_action.next_assignee_rule->>'role';
    ELSIF v_action.next_assignee_rule->>'kind'='inherit_step' THEN
      IF v_next_step.assignment_rule->>'kind'='investigator' THEN
        v_next_assignee := v_complaint.investigator_id;
      ELSIF v_next_step.assignment_rule->>'kind'='role' THEN
        v_next_role := v_next_step.assignment_rule->>'role';
      END IF;
    END IF;

    UPDATE public.workflow_instances
      SET current_step_id=v_next_step.id, current_step_key=v_next_step.step_key,
          assigned_user_id=v_next_assignee, assigned_role=COALESCE(v_next_role,assigned_role),
          due_at=CASE WHEN v_next_step.sla_hours>0 THEN now()+(v_next_step.sla_hours||' hours')::interval ELSE NULL END,
          status=CASE WHEN v_next_step.is_terminal THEN 'completed' ELSE 'active' END,
          completed_at=CASE WHEN v_next_step.is_terminal THEN now() ELSE NULL END,
          updated_at=now()
      WHERE id=v_instance.id;
  END IF;

  INSERT INTO public.approval_actions (id, workflow_instance_id, step_id, action, action_type, actor_id, comments, entity_type, entity_id, responded_at)
  VALUES (v_history_id, v_instance.id, v_step.id, v_action.action_key, v_action.action_type, v_user, _payload->>'comments','complaint',_complaint_id, now());

  INSERT INTO public.audit_logs (entity_type, entity_id, action, user_id, metadata)
  VALUES ('complaint',_complaint_id,'complaint.'||_action_key,v_user,
    jsonb_build_object('before',v_before,'after',v_after,'action_key',_action_key,'workflow_instance',v_instance.id,'correlation_id',v_correlation,'payload',_payload));

  IF v_action.notification_event_key IS NOT NULL THEN
    IF v_action.complainant_visible AND v_complaint.complainant_id IS NOT NULL THEN
      INSERT INTO public.notification_outbox(event_key,entity_type,entity_id,recipient_user_id,channel,subject,body,payload,action_history_id,correlation_id)
      VALUES(v_action.notification_event_key,'complaint',_complaint_id,v_complaint.complainant_id,'in_app',
             'Complaint update: '||v_action.label,
             'Your complaint '||v_complaint.complaint_number||' — '||v_action.label,
             _payload,v_history_id,v_correlation)
      ON CONFLICT DO NOTHING;
      IF v_complaint.email IS NOT NULL THEN
        INSERT INTO public.notification_outbox(event_key,entity_type,entity_id,recipient_email,channel,subject,body,payload,action_history_id,correlation_id)
        VALUES(v_action.notification_event_key,'complaint',_complaint_id,v_complaint.email,'email',
               'Update on your complaint '||v_complaint.complaint_number,
               'Status: '||v_action.label,
               _payload,v_history_id,v_correlation)
        ON CONFLICT DO NOTHING;
      END IF;
    END IF;

    IF v_next_assignee IS NOT NULL THEN
      INSERT INTO public.notification_outbox(event_key,entity_type,entity_id,recipient_user_id,channel,subject,body,payload,action_history_id,correlation_id)
      VALUES(v_action.notification_event_key,'complaint',_complaint_id,v_next_assignee,'in_app',
             'Complaint assigned to you: '||v_complaint.complaint_number,v_action.label,
             _payload,v_history_id,v_correlation)
      ON CONFLICT DO NOTHING;
    END IF;

    IF v_action.licensee_visible AND v_complaint.licensee_id IS NOT NULL THEN
      INSERT INTO public.notification_outbox(event_key,entity_type,entity_id,recipient_user_id,channel,subject,body,payload,action_history_id,correlation_id)
      SELECT v_action.notification_event_key,'complaint',_complaint_id,p.id,'in_app',
             'Complaint update: '||v_complaint.complaint_number,v_action.label,
             _payload,v_history_id,v_correlation
      FROM public.profiles p WHERE p.licensee_id=v_complaint.licensee_id
      ON CONFLICT DO NOTHING;
    END IF;
  END IF;

  RETURN jsonb_build_object('ok',true,'complaint_id',_complaint_id,'action_key',_action_key,
    'new_status',v_complaint.status,'enforcement_action_id',v_complaint.enforcement_action_id,
    'workflow_instance_id',v_instance.id,'action_history_id',v_history_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.executive_conduct_summary(_from date DEFAULT NULL::date, _to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'complaints_total', (SELECT count(*) FROM public.complaints c
       WHERE (_from IS NULL OR c.created_at >= _from) AND (_to IS NULL OR c.created_at < (_to + 1))),
    'complaints_severe', (SELECT count(*) FROM public.complaints c
       WHERE c.severity IN ('critical','high')
         AND (_from IS NULL OR c.created_at >= _from) AND (_to IS NULL OR c.created_at < (_to + 1))),
    'complaints_open', (SELECT count(*) FROM public.complaints c WHERE c.closed_at IS NULL),
    'sla_breaches', (SELECT count(*) FROM public.complaints c
       WHERE c.sla_due_at IS NOT NULL AND c.resolved_at IS NULL AND c.sla_due_at < now()),
    'investigations_open', (SELECT count(*) FROM public.conduct_investigations i
       WHERE i.status NOT IN ('closed','discontinued')),
    'pattern_alerts_open', (SELECT count(*) FROM public.conduct_alerts a WHERE a.closed_at IS NULL),
    'enforcement_open', (SELECT count(*) FROM public.enforcement_actions e WHERE e.status <> 'closed')
  );
$function$
;
CREATE OR REPLACE FUNCTION public.expire_delegation_rules()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  UPDATE public.delegation_rules
  SET is_active = false
  WHERE is_active = true
    AND effective_until IS NOT NULL
    AND effective_until < now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_application(_user_id uuid, _application_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
  -- Static external roles inherently can act on their own application.
  EXISTS (
    SELECT 1
    FROM public.applications a
    WHERE a.id = _application_id
      AND a.applicant_id = _user_id
      AND (
        public.has_role(_user_id, 'applicant'::app_role)
        OR public.has_role(_user_id, 'pre_licensee'::app_role)
        OR public.has_role(_user_id, 'licensee_primary'::app_role)
        OR public.has_role(_user_id, 'licensee_secondary'::app_role)
      )
  )
  OR EXISTS (
    SELECT 1
    FROM public.applications a
    WHERE a.id = _application_id
      AND a.applicant_id = _user_id
      AND public.has_portal_capability(_user_id, NULL, 'licensing'::public.portal_area, _capability)
  )
  OR EXISTS (
    SELECT 1
    FROM public.portal_application_entity_ids(_application_id) e(entity_id)
    WHERE public.has_portal_capability(_user_id, e.entity_id, 'licensing'::public.portal_area, _capability)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_application_values(_user_id uuid, _applicant_id uuid, _data jsonb, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
  -- Built-in static roles inherently imply the ability to act on their own app
  (
    _applicant_id = _user_id
    AND (
      public.has_role(_user_id, 'applicant'::app_role)
      OR public.has_role(_user_id, 'pre_licensee'::app_role)
      OR public.has_role(_user_id, 'licensee_primary'::app_role)
      OR public.has_role(_user_id, 'licensee_secondary'::app_role)
    )
  )
  OR (
    _applicant_id = _user_id
    AND public.has_portal_capability(_user_id, NULL, 'licensing'::public.portal_area, _capability)
  )
  OR (
    public.safe_uuid(_data->>'licensee_id') IS NOT NULL
    AND public.has_portal_capability(
      _user_id,
      public.safe_uuid(_data->>'licensee_id'),
      'licensing'::public.portal_area,
      _capability
    )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_complaint(_user_id uuid, _complaint_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.complaints c
    WHERE c.id = _complaint_id
      AND public.external_can_access_complaint_values(_user_id, c.complainant_id, c.license_holder_id, _capability)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_complaint_values(_user_id uuid, _complainant_id uuid, _license_holder_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT _complainant_id = _user_id
     AND (
       (_license_holder_id IS NULL AND public.has_portal_capability(_user_id, NULL, 'complaints'::public.portal_area, _capability))
       OR (_license_holder_id IS NOT NULL AND public.has_portal_capability(_user_id, _license_holder_id, 'complaints'::public.portal_area, _capability))
     );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_compliance_return(_user_id uuid, _return_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.compliance_returns r
    WHERE r.id = _return_id
      AND public.external_can_access_compliance_return_values(
        _user_id,
        r.license_id,
        r.on_behalf_of_licensee_id,
        r.submitter_id,
        _capability
      )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_compliance_return_values(_user_id uuid, _license_id uuid, _on_behalf_of_licensee_id uuid, _submitter_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT _submitter_id = _user_id
     AND (
       (
         _on_behalf_of_licensee_id IS NOT NULL
         AND public.has_portal_capability(_user_id, _on_behalf_of_licensee_id, 'returns'::public.portal_area, _capability)
       )
       OR EXISTS (
         SELECT 1
         FROM public.portal_license_entity_ids(_license_id) e(entity_id)
         WHERE public.has_portal_capability(_user_id, e.entity_id, 'returns'::public.portal_area, _capability)
       )
     );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_document_ref(_user_id uuid, _entity_type text, _entity_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_type text := lower(coalesce(_entity_type, ''));
BEGIN
  IF _entity_id IS NULL THEN
    RETURN false;
  END IF;

  IF v_type IN ('application', 'applications') THEN
    RETURN public.external_can_access_application(_user_id, _entity_id, _capability);
  ELSIF v_type IN ('license', 'licenses') THEN
    RETURN public.external_can_access_license(_user_id, _entity_id, _capability);
  ELSIF v_type IN ('compliance_return', 'compliance_returns') THEN
    RETURN public.external_can_access_compliance_return(_user_id, _entity_id, _capability);
  ELSIF v_type IN ('return', 'returns_filed', 'return_filed') THEN
    RETURN public.external_can_access_return_filed(_user_id, _entity_id, _capability);
  ELSIF v_type IN ('complaint', 'complaints') THEN
    RETURN public.external_can_access_complaint(_user_id, _entity_id, _capability);
  ELSIF v_type IN ('payment', 'payments') THEN
    RETURN public.external_can_access_payment(_user_id, _entity_id, _capability);
  ELSIF v_type IN ('prudential_action', 'prudential_actions', 'supervisory_action') THEN
    RETURN public.external_can_access_prudential_action(_user_id, _entity_id, _capability);
  ELSIF v_type IN ('licensee', 'licensees', 'entity') THEN
    RETURN public.has_portal_capability(_user_id, _entity_id, 'licensing'::public.portal_area, _capability);
  END IF;

  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_license(_user_id uuid, _license_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.portal_license_entity_ids(_license_id) e(entity_id)
    WHERE public.has_portal_capability(_user_id, e.entity_id, 'licensing'::public.portal_area, _capability)
  )
  OR EXISTS (
    SELECT 1
    FROM public.licenses lic
    WHERE lic.id = _license_id
      AND lic.holder_id = _user_id
      AND public.has_portal_capability(_user_id, NULL, 'licensing'::public.portal_area, _capability)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_payment(_user_id uuid, _payment_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.payments p
    WHERE p.id = _payment_id
      AND public.external_can_access_payment_values(_user_id, p.user_id, p.application_id, _capability)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_payment_values(_user_id uuid, _payment_user_id uuid, _application_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT _payment_user_id = _user_id
     AND (
       _application_id IS NULL
       OR public.external_can_access_application(_user_id, _application_id, _capability)
     );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_prudential_action(_user_id uuid, _action_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.prudential_actions a
    WHERE a.id = _action_id
      AND a.entity_id IS NOT NULL
      AND public.has_portal_capability(_user_id, a.entity_id, 'licensing'::public.portal_area, _capability)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_return_filed(_user_id uuid, _return_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.returns_filed r
    WHERE r.id = _return_id
      AND public.external_can_access_return_filed_values(
        _user_id,
        r.entity_id,
        r.on_behalf_of_licensee_id,
        r.created_by,
        _capability
      )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_access_return_filed_values(_user_id uuid, _entity_id uuid, _on_behalf_of_licensee_id uuid, _created_by uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    (_created_by = _user_id)
    OR (
      _entity_id IS NOT NULL
      AND public.has_portal_capability(_user_id, _entity_id, 'returns'::public.portal_area, _capability)
    )
    OR (
      _on_behalf_of_licensee_id IS NOT NULL
      AND public.has_portal_capability(_user_id, _on_behalf_of_licensee_id, 'returns'::public.portal_area, _capability)
    );
$function$
;
CREATE OR REPLACE FUNCTION public.external_can_upload_document_ref(_user_id uuid, _entity_type text, _entity_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_type text := lower(coalesce(_entity_type, ''));
  v_entity uuid := _entity_id;
  v_app_id uuid;
BEGIN
  IF v_entity IS NULL THEN
    RETURN false;
  END IF;

  IF v_type IN ('application', 'applications', 'license', 'licenses', 'licensee', 'licensees', 'entity', 'payment', 'payments') THEN
    RETURN public.external_can_access_document_ref(_user_id, v_type, v_entity, 'can_upload_documents');
  ELSIF v_type IN ('prudential_action', 'prudential_actions', 'supervisory_action') THEN
    RETURN public.external_can_access_prudential_action(_user_id, v_entity, 'can_upload_documents');
  ELSIF v_type IN ('compliance_return', 'compliance_returns') THEN
    RETURN EXISTS (
      SELECT 1
      FROM public.compliance_returns r
      WHERE r.id = v_entity
        AND public.external_can_access_compliance_return_values(_user_id, r.license_id, r.on_behalf_of_licensee_id, r.submitter_id, 'can_upload_documents')
    );
  ELSIF v_type IN ('return', 'returns_filed', 'return_filed') THEN
    RETURN EXISTS (
      SELECT 1
      FROM public.returns_filed r
      WHERE r.id = v_entity
        AND (
          (r.entity_id IS NOT NULL AND public.has_portal_capability(_user_id, r.entity_id, 'returns'::public.portal_area, 'can_upload_documents'))
          OR (r.on_behalf_of_licensee_id IS NOT NULL AND public.has_portal_capability(_user_id, r.on_behalf_of_licensee_id, 'returns'::public.portal_area, 'can_upload_documents'))
        )
    );
  ELSIF v_type IN ('complaint', 'complaints') THEN
    RETURN EXISTS (
      SELECT 1
      FROM public.complaints c
      WHERE c.id = v_entity
        AND public.external_can_access_complaint_values(_user_id, c.complainant_id, c.license_holder_id, 'can_submit_complaints')
    );
  ELSIF v_type IN ('rfi_response', 'application_rfi_response') THEN
    SELECT r.application_id INTO v_app_id
    FROM public.application_rfi_items it
    JOIN public.application_rfis r ON r.id = it.rfi_id
    WHERE it.id = v_entity
    LIMIT 1;
    IF v_app_id IS NULL THEN RETURN false; END IF;
    RETURN public.external_can_access_document_ref(_user_id, 'application', v_app_id, 'can_upload_documents')
        OR public.external_can_access_document_ref(_user_id, 'application', v_app_id, 'can_respond_rfi');
  ELSIF v_type IN ('rfi', 'application_rfi') THEN
    SELECT application_id INTO v_app_id
    FROM public.application_rfis
    WHERE id = v_entity
    LIMIT 1;
    IF v_app_id IS NULL THEN RETURN false; END IF;
    RETURN public.external_can_access_document_ref(_user_id, 'application', v_app_id, 'can_upload_documents')
        OR public.external_can_access_document_ref(_user_id, 'application', v_app_id, 'can_respond_rfi');
  END IF;

  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.external_user_entity_ids(_user_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT entity_id FROM public.entity_user_access
    WHERE user_id = _user_id AND is_active = true AND entity_id IS NOT NULL
  UNION
  SELECT licensee_id FROM public.profiles
    WHERE id = _user_id AND licensee_id IS NOT NULL;
$function$
;
CREATE OR REPLACE FUNCTION public.finalize_complaint_with_attachments(p_complaint_id uuid, p_file_upload_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_complaint record;
  v_file record;
  v_results jsonb := '[]'::jsonb;
  v_linked int := 0;
  v_failed int := 0;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'AUTH_REQUIRED';
  END IF;

  SELECT id, regulator_id, complainant_id, licensee_id
    INTO v_complaint
    FROM public.complaints
   WHERE id = p_complaint_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'COMPLAINT_NOT_FOUND';
  END IF;

  -- Caller must be: complainant, an internal staff member (any role), or
  -- a member of the licensee organisation. RLS on complaint_evidence enforces
  -- the eventual insert, but we short-circuit here for a cleaner error.
  IF NOT (
    v_complaint.complainant_id = v_uid
    OR public.has_role(v_uid, 'admin'::app_role)
    OR public.has_role(v_uid, 'staff'::app_role)
    OR EXISTS (
      SELECT 1 FROM public.entity_user_access eua
       WHERE eua.user_id = v_uid AND eua.licensee_id = v_complaint.licensee_id
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'NOT_AUTHORIZED_FOR_COMPLAINT';
  END IF;

  IF p_file_upload_ids IS NULL OR array_length(p_file_upload_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('linked', 0, 'failed', 0, 'results', '[]'::jsonb);
  END IF;

  FOREACH v_id IN ARRAY p_file_upload_ids LOOP
    BEGIN
      SELECT id, uploaded_by, file_name, entity_type, entity_id, is_quarantined
        INTO v_file
        FROM public.file_uploads
       WHERE id = v_id
       FOR UPDATE;

      IF NOT FOUND THEN
        v_failed := v_failed + 1;
        v_results := v_results || jsonb_build_object('file_upload_id', v_id, 'ok', false, 'error', 'FILE_NOT_FOUND');
        CONTINUE;
      END IF;

      IF v_file.uploaded_by <> v_uid THEN
        v_failed := v_failed + 1;
        v_results := v_results || jsonb_build_object('file_upload_id', v_id, 'ok', false, 'error', 'NOT_FILE_OWNER');
        CONTINUE;
      END IF;

      IF v_file.is_quarantined THEN
        v_failed := v_failed + 1;
        v_results := v_results || jsonb_build_object('file_upload_id', v_id, 'ok', false, 'error', 'FILE_QUARANTINED');
        CONTINUE;
      END IF;

      -- Reject files already linked to a different complaint / entity.
      IF v_file.entity_type IS NOT NULL AND v_file.entity_type NOT IN ('complaint','general','staging')
         OR (v_file.entity_type = 'complaint' AND v_file.entity_id IS NOT NULL AND v_file.entity_id <> p_complaint_id::text)
      THEN
        v_failed := v_failed + 1;
        v_results := v_results || jsonb_build_object('file_upload_id', v_id, 'ok', false, 'error', 'FILE_ALREADY_LINKED');
        CONTINUE;
      END IF;

      -- Idempotency: skip if already linked to this complaint.
      IF EXISTS (
        SELECT 1 FROM public.complaint_evidence
         WHERE complaint_id = p_complaint_id AND file_upload_id = v_id
      ) THEN
        v_linked := v_linked + 1;
        v_results := v_results || jsonb_build_object('file_upload_id', v_id, 'ok', true, 'idempotent', true);
        CONTINUE;
      END IF;

      INSERT INTO public.complaint_evidence (complaint_id, file_upload_id, label, uploaded_by)
      VALUES (p_complaint_id, v_id, v_file.file_name, v_uid);

      UPDATE public.file_uploads
         SET entity_type = 'complaint',
             entity_id = p_complaint_id::text,
             updated_at = now()
       WHERE id = v_id;

      v_linked := v_linked + 1;
      v_results := v_results || jsonb_build_object('file_upload_id', v_id, 'ok', true);
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      v_results := v_results || jsonb_build_object('file_upload_id', v_id, 'ok', false, 'error', SQLERRM);
    END;
  END LOOP;

  RETURN jsonb_build_object('linked', v_linked, 'failed', v_failed, 'results', v_results);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.form_applicability_rule_delete(_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.rdm_require('form_management', 'manage_applicability');
  DELETE FROM public.form_applicability_rules WHERE id = _id;
  RETURN true;
END $function$
;
CREATE OR REPLACE FUNCTION public.form_applicability_rule_save(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid := NULLIF(_payload->>'id','')::uuid;
BEGIN
  PERFORM public.rdm_require('form_management', 'manage_applicability');

  IF v_id IS NULL THEN
    INSERT INTO public.form_applicability_rules
      (package_id, regulator_id, jurisdiction, sector_id, sub_sector_id, category_id, service_id,
       license_type, entity_classification_value_id, lifecycle_key, request_type_key, application_type,
       effective_from, effective_to, priority, is_active)
    VALUES (
      (_payload->>'package_id')::uuid, NULLIF(_payload->>'regulator_id','')::uuid, NULLIF(_payload->>'jurisdiction',''),
      NULLIF(_payload->>'sector_id','')::uuid, NULLIF(_payload->>'sub_sector_id','')::uuid,
      NULLIF(_payload->>'category_id','')::uuid, NULLIF(_payload->>'service_id','')::uuid,
      NULLIF(_payload->>'license_type',''), NULLIF(_payload->>'entity_classification_value_id','')::uuid,
      NULLIF(_payload->>'lifecycle_key',''), NULLIF(_payload->>'request_type_key',''), NULLIF(_payload->>'application_type',''),
      COALESCE(NULLIF(_payload->>'effective_from','')::timestamptz, now()),
      NULLIF(_payload->>'effective_to','')::timestamptz,
      COALESCE((_payload->>'priority')::int, 100),
      COALESCE((_payload->>'is_active')::boolean, true))
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.form_applicability_rules SET
      package_id = COALESCE(NULLIF(_payload->>'package_id','')::uuid, package_id),
      regulator_id = NULLIF(_payload->>'regulator_id','')::uuid,
      jurisdiction = NULLIF(_payload->>'jurisdiction',''),
      sector_id = NULLIF(_payload->>'sector_id','')::uuid,
      sub_sector_id = NULLIF(_payload->>'sub_sector_id','')::uuid,
      category_id = NULLIF(_payload->>'category_id','')::uuid,
      service_id = NULLIF(_payload->>'service_id','')::uuid,
      license_type = NULLIF(_payload->>'license_type',''),
      entity_classification_value_id = NULLIF(_payload->>'entity_classification_value_id','')::uuid,
      lifecycle_key = NULLIF(_payload->>'lifecycle_key',''),
      request_type_key = NULLIF(_payload->>'request_type_key',''),
      application_type = NULLIF(_payload->>'application_type',''),
      effective_from = COALESCE(NULLIF(_payload->>'effective_from','')::timestamptz, effective_from),
      effective_to = NULLIF(_payload->>'effective_to','')::timestamptz,
      priority = COALESCE((_payload->>'priority')::int, priority),
      is_active = COALESCE((_payload->>'is_active')::boolean, is_active),
      updated_at = now()
    WHERE id = v_id;
  END IF;
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.form_field_definition_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.is_published THEN
    IF NEW.field_key IS DISTINCT FROM OLD.field_key THEN
      RAISE EXCEPTION 'field_key is immutable after publication (%).', OLD.field_key;
    END IF;
    IF NEW.data_concept_id IS DISTINCT FROM OLD.data_concept_id THEN
      RAISE EXCEPTION 'data_concept_id is immutable for a published logical field; create a new field definition instead';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.form_fields_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_version uuid; v_status text;
BEGIN
  IF COALESCE(current_setting('app.form_publish_context', true),'') = 'trusted' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  v_version := COALESCE(NEW.version_id, OLD.version_id);
  SELECT status INTO v_status FROM public.form_versions WHERE id = v_version;
  IF v_status = 'published' THEN
    RAISE EXCEPTION 'Fields of a published form version cannot be changed (version %)', v_version;
  END IF;
  RETURN COALESCE(NEW, OLD);
END $function$
;
CREATE OR REPLACE FUNCTION public.form_package_item_delete(_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.rdm_require('form_management', 'manage_packages');
  DELETE FROM public.form_package_items WHERE id = _id;
  RETURN true;
END $function$
;
CREATE OR REPLACE FUNCTION public.form_package_item_save(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  PERFORM public.rdm_require('form_management', 'manage_packages');
  INSERT INTO public.form_package_items (package_id, template_id, is_required, sequence, notes)
  VALUES ((_payload->>'package_id')::uuid, (_payload->>'template_id')::uuid,
          COALESCE((_payload->>'is_required')::boolean, true),
          COALESCE((_payload->>'sequence')::int, 0), _payload->>'notes')
  ON CONFLICT (package_id, template_id) DO UPDATE
    SET is_required = EXCLUDED.is_required, sequence = EXCLUDED.sequence, notes = EXCLUDED.notes
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.form_package_save(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid; v_id uuid := NULLIF(_payload->>'id','')::uuid; v_status text := COALESCE(_payload->>'status','draft');
BEGIN
  v_uid := public.rdm_require('form_management', 'manage_packages');
  IF v_status <> 'draft' THEN
    PERFORM public.rdm_require('form_management', 'publish');
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.form_packages (code, name, description, regulator_id, status, is_active, created_by)
    VALUES (upper(trim(_payload->>'code')), _payload->>'name', _payload->>'description',
            NULLIF(_payload->>'regulator_id','')::uuid, v_status,
            COALESCE((_payload->>'is_active')::boolean, true), v_uid)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.form_packages SET
      name = COALESCE(_payload->>'name', name),
      description = COALESCE(_payload->>'description', description),
      regulator_id = NULLIF(_payload->>'regulator_id','')::uuid,
      status = v_status,
      published_at = CASE WHEN v_status = 'active' AND published_at IS NULL THEN now() ELSE published_at END,
      published_by = CASE WHEN v_status = 'active' AND published_by IS NULL THEN v_uid ELSE published_by END,
      is_active = COALESCE((_payload->>'is_active')::boolean, is_active),
      updated_at = now()
    WHERE id = v_id;
  END IF;
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.form_save_draft(_template_id uuid, _fields jsonb, _change_notes text DEFAULT NULL::text, _version_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_version record; v_f jsonb; v_def_id uuid; v_next int; v_key text;
BEGIN
  PERFORM public.wb_require('form_management','edit');
  IF NOT EXISTS (SELECT 1 FROM public.form_templates WHERE id = _template_id) THEN
    RAISE EXCEPTION 'Form definition not found';
  END IF;

  IF _version_id IS NOT NULL THEN
    SELECT * INTO v_version FROM public.form_versions WHERE id = _version_id FOR UPDATE;
    IF v_version.status = 'published' THEN
      RAISE EXCEPTION 'Published form versions are immutable; branch a new version instead';
    END IF;
  ELSE
    SELECT * INTO v_version FROM public.form_versions
      WHERE template_id = _template_id AND status = 'draft'
      ORDER BY version DESC LIMIT 1 FOR UPDATE;
  END IF;

  IF v_version.id IS NULL THEN
    SELECT COALESCE(MAX(version),0) + 1 INTO v_next FROM public.form_versions WHERE template_id = _template_id;
    INSERT INTO public.form_versions (template_id, version, status, change_notes, created_by, schema_snapshot)
    VALUES (_template_id, v_next, 'draft', _change_notes, auth.uid(), COALESCE(_fields,'[]'::jsonb))
    RETURNING * INTO v_version;
  ELSE
    UPDATE public.form_versions
       SET schema_snapshot = COALESCE(_fields, schema_snapshot),
           change_notes = COALESCE(_change_notes, change_notes)
     WHERE id = v_version.id RETURNING * INTO v_version;
    DELETE FROM public.form_fields WHERE version_id = v_version.id;
  END IF;

  FOR v_f IN SELECT * FROM jsonb_array_elements(COALESCE(_fields,'[]'::jsonb)) LOOP
    v_key := COALESCE(NULLIF(v_f->>'field_key',''), NULLIF(v_f->>'field_name',''));
    v_def_id := NULL;
    IF v_key IS NOT NULL THEN
      SELECT id INTO v_def_id FROM public.form_field_definitions
       WHERE template_id = _template_id AND field_key = v_key;
      IF v_def_id IS NULL THEN
        INSERT INTO public.form_field_definitions (template_id, field_key, data_concept_id, label_hint)
        VALUES (_template_id, v_key, NULLIF(v_f->>'data_concept_id','')::uuid, v_f->>'label')
        RETURNING id INTO v_def_id;
      ELSE
        UPDATE public.form_field_definitions
           SET data_concept_id = COALESCE(NULLIF(v_f->>'data_concept_id','')::uuid, data_concept_id),
               label_hint = COALESCE(v_f->>'label', label_hint)
         WHERE id = v_def_id;
      END IF;
    END IF;

    INSERT INTO public.form_fields (version_id, form_field_definition_id, section_id, section_title,
      section_order, field_type, label, field_name, required, placeholder, help_text, default_value,
      options, validation, sort_order, calculated_expression)
    VALUES (v_version.id, v_def_id, v_f->>'section_id', v_f->>'section_title',
      COALESCE((v_f->>'section_order')::int,0), COALESCE(v_f->>'field_type','text'), v_f->>'label', v_key,
      COALESCE((v_f->>'required')::boolean,false), v_f->>'placeholder', v_f->>'help_text', v_f->>'default_value',
      v_f->'options', v_f->'validation', COALESCE((v_f->>'sort_order')::int,0), v_f->>'calculated_expression');
  END LOOP;

  PERFORM public.create_audit_log(auth.uid(),'form.definition.updated','form_version', v_version.id::text, NULL,
    jsonb_build_object('template_id',_template_id,'version',v_version.version), NULL);
  RETURN jsonb_build_object('success',true,'version_id',v_version.id,'version',v_version.version);
END $function$
;
CREATE OR REPLACE FUNCTION public.form_version_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(current_setting('app.form_publish_context', true),'') = 'trusted' THEN RETURN NEW; END IF;
  IF OLD.status = 'published' THEN
    IF NEW.schema_snapshot IS DISTINCT FROM OLD.schema_snapshot
       OR NEW.version IS DISTINCT FROM OLD.version
       OR NEW.template_id IS DISTINCT FROM OLD.template_id THEN
      RAISE EXCEPTION 'Published form version % is immutable', OLD.id;
    END IF;
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.fp_appeal_assign_committee(_appeal_id uuid, _committee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev text; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','edit');
  SELECT status INTO _prev FROM public.fp_appeals WHERE id = _appeal_id;
  IF _prev IS NULL THEN RAISE EXCEPTION 'appeal not found' USING ERRCODE='22023'; END IF;
  IF _prev IN ('decided','withdrawn') THEN
    RAISE EXCEPTION 'appeal is closed' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fp_committees WHERE id = _committee_id) THEN
    RAISE EXCEPTION 'committee not found' USING ERRCODE='22023';
  END IF;
  UPDATE public.fp_appeals
     SET appeal_committee_id = _committee_id, status = 'under_review'
   WHERE id = _appeal_id RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid, 'fp.appeal.committee_assigned', 'fp_appeal', _appeal_id,
          jsonb_build_object('before',jsonb_build_object('status',_prev),
                             'after',jsonb_build_object('status','under_review','appeal_committee_id',_committee_id)));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_appeal_decide(_appeal_id uuid, _decision text, _rationale text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _appeal record; _det record; _new_det_id uuid; _outcome text; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','approve');
  IF _decision IS NULL OR _decision NOT IN ('upheld','dismissed','overturned_to_approved','overturned_to_conditional') THEN
    RAISE EXCEPTION 'invalid appeal decision' USING ERRCODE='22023';
  END IF;
  IF _rationale IS NULL OR length(btrim(_rationale)) < 10 THEN
    RAISE EXCEPTION 'decision rationale must be at least 10 characters' USING ERRCODE='22023';
  END IF;
  SELECT * INTO _appeal FROM public.fp_appeals WHERE id = _appeal_id FOR UPDATE;
  IF _appeal IS NULL THEN RAISE EXCEPTION 'appeal not found' USING ERRCODE='22023'; END IF;
  IF _appeal.status IN ('decided','withdrawn') THEN
    RAISE EXCEPTION 'appeal already closed' USING ERRCODE='22023';
  END IF;

  IF _decision IN ('overturned_to_approved','overturned_to_conditional') THEN
    _outcome := CASE WHEN _decision = 'overturned_to_approved' THEN 'approved' ELSE 'conditional' END;
    SELECT * INTO _det FROM public.fp_determinations WHERE id = _appeal.determination_id;
    IF _det IS NULL THEN RAISE EXCEPTION 'appealed determination missing' USING ERRCODE='22023'; END IF;
    UPDATE public.fp_determinations SET is_current = false WHERE id = _appeal.determination_id;
    INSERT INTO public.fp_determinations (
      assessment_id, individual_id, outcome, rationale, determined_by,
      supersedes_id, is_current, effective_from
    ) VALUES (
      _det.assessment_id, _appeal.individual_id, _outcome,
      'Appeal outcome: ' || btrim(_rationale), _uid,
      _appeal.determination_id, true, CURRENT_DATE
    ) RETURNING id INTO _new_det_id;

    IF _appeal.license_id IS NOT NULL THEN
      INSERT INTO public.license_actions (license_id, action_type, actor_id, reason, metadata)
      VALUES (_appeal.license_id, 'fp_appeal_overturn', _uid,
              'FP appeal ' || _decision || ': ' || btrim(_rationale),
              jsonb_build_object('appeal_id',_appeal_id,'individual_id',_appeal.individual_id,
                                 'new_determination_id',_new_det_id,'new_outcome',_outcome));
    END IF;
  END IF;

  UPDATE public.fp_appeals
     SET status = 'decided', decision = _decision, decision_rationale = btrim(_rationale),
         decided_by = _uid, decided_at = now(), new_determination_id = _new_det_id
   WHERE id = _appeal_id RETURNING * INTO _row;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid, 'fp.appeal.decided', 'fp_appeal', _appeal_id,
          jsonb_build_object('before',jsonb_build_object('status',_appeal.status),
                             'after',jsonb_build_object('status','decided','decision',_decision,
                                                        'new_determination_id',_new_det_id),
                             'justification',btrim(_rationale),
                             'individual_id',_appeal.individual_id));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_appeal_file(_individual_id uuid, _determination_id uuid, _grounds text, _license_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _det record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','submit');
  IF _grounds IS NULL OR length(btrim(_grounds)) < 20 THEN
    RAISE EXCEPTION 'grounds must be at least 20 characters' USING ERRCODE='22023';
  END IF;
  SELECT * INTO _det FROM public.fp_determinations WHERE id = _determination_id;
  IF _det IS NULL THEN RAISE EXCEPTION 'determination not found' USING ERRCODE='22023'; END IF;
  IF _det.individual_id <> _individual_id THEN
    RAISE EXCEPTION 'determination does not belong to individual' USING ERRCODE='22023';
  END IF;
  IF NOT _det.is_current THEN
    RAISE EXCEPTION 'only the current determination may be appealed' USING ERRCODE='22023';
  END IF;
  IF _det.outcome NOT IN ('rejected','conditional') THEN
    RAISE EXCEPTION 'only rejected or conditional determinations may be appealed' USING ERRCODE='22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.fp_appeals a
             WHERE a.determination_id = _determination_id
               AND a.status NOT IN ('decided','withdrawn')) THEN
    RAISE EXCEPTION 'an open appeal already exists for this determination' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.fp_appeals (individual_id, determination_id, filed_by, grounds, status, supporting_docs, license_id)
  VALUES (_individual_id, _determination_id, _uid, btrim(_grounds), 'submitted', '[]'::jsonb, _license_id)
  RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid, 'fp.appeal.filed', 'fp_appeal', _row.id,
          jsonb_build_object('individual_id',_individual_id,'determination_id',_determination_id,
                             'license_id',_license_id,'after',jsonb_build_object('status','submitted')));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_appeal_start_review(_appeal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev text; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','edit');
  SELECT status INTO _prev FROM public.fp_appeals WHERE id = _appeal_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'appeal not found' USING ERRCODE='22023'; END IF;
  IF _prev <> 'submitted' THEN
    RAISE EXCEPTION 'only submitted appeals can move to review' USING ERRCODE='22023';
  END IF;
  UPDATE public.fp_appeals SET status = 'under_review' WHERE id = _appeal_id RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'fp.appeal.review_started','fp_appeal',_appeal_id,
          jsonb_build_object('before',jsonb_build_object('status',_prev),
                             'after',jsonb_build_object('status','under_review')));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_appeal_withdraw(_appeal_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _appeal record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','edit');
  SELECT * INTO _appeal FROM public.fp_appeals WHERE id = _appeal_id FOR UPDATE;
  IF _appeal IS NULL THEN RAISE EXCEPTION 'appeal not found' USING ERRCODE='22023'; END IF;
  IF _appeal.status IN ('decided','withdrawn') THEN
    RAISE EXCEPTION 'appeal already closed' USING ERRCODE='22023';
  END IF;
  UPDATE public.fp_appeals SET status = 'withdrawn' WHERE id = _appeal_id RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid, 'fp.appeal.withdrawn', 'fp_appeal', _appeal_id,
          jsonb_build_object('before',jsonb_build_object('status',_appeal.status),
                             'after',jsonb_build_object('status','withdrawn'),'reason',_reason));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_assessment_assign_committee(_assessment_id uuid, _committee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_committee','edit');
  SELECT * INTO _prev FROM public.fp_assessments WHERE id = _assessment_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'assessment not found' USING ERRCODE='22023'; END IF;
  IF _prev.status IN ('determined','closed','withdrawn') THEN
    RAISE EXCEPTION 'assessment is % and can no longer be routed to a committee', _prev.status
      USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fp_committees WHERE id = _committee_id AND is_active) THEN
    RAISE EXCEPTION 'committee not found or inactive' USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_assessments
     SET committee_id = _committee_id, status = 'awaiting_committee'
   WHERE id = _assessment_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.assessment.committee_assigned','fp_assessment',_assessment_id,
    jsonb_build_object('committee_id',_prev.committee_id,'status',_prev.status),
    jsonb_build_object('committee_id',_committee_id,'status','awaiting_committee'),
    jsonb_build_object('individual_id',_prev.individual_id,'assessment_id',_assessment_id,
                       'committee_id',_committee_id));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_assessment_case(_assessment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  a record;
  v_person text;
  v_role_id uuid;
  v_role_label text;
  v_role_type text;
  v_role_licensee uuid;
  v_licensee uuid;
  v_det_id uuid;
  v_det jsonb := 'null'::jsonb;
  v_can_act boolean;
  v_stage text;
  v_stage_label text;
  v_sla_days int;
  v_sla_anchor timestamptz;
  v_sla_due timestamptz;
  v_sla_state text;
  v_waiting text;
  v_priority text;
  v_blockers jsonb := '[]'::jsonb;
  v_actions jsonb := '[]'::jsonb;
  v_next jsonb := 'null'::jsonb;
  v_committee jsonb := 'null'::jsonb;
  v_findings jsonb := '[]'::jsonb;
  v_screening jsonb := '[]'::jsonb;
  v_votes jsonb := '[]'::jsonb;
  v_conditions jsonb := '[]'::jsonb;
  v_monitoring jsonb := '[]'::jsonb;
  v_appeals jsonb := '[]'::jsonb;
  v_related jsonb := '[]'::jsonb;
  v_history jsonb := '[]'::jsonb;
  v_declaration jsonb := 'null'::jsonb;
  v_open_findings int := 0;
  v_high_findings int := 0;
  v_open_conditions int := 0;
  v_last timestamptz;
BEGIN
  IF _assessment_id IS NULL THEN
    RETURN jsonb_build_object('found', false, 'allowed', false);
  END IF;

  SELECT * INTO a FROM public.fp_assessments WHERE id = _assessment_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false, 'allowed', false);
  END IF;

  IF NOT public.can_read_fp_assessment(v_user, _assessment_id) THEN
    RETURN jsonb_build_object('found', true, 'allowed', false);
  END IF;

  v_can_act := public.can_act_on_fp(v_user);

  SELECT full_name INTO v_person FROM public.fp_individuals WHERE id = a.individual_id;

  SELECT r.id, COALESCE(r.role_title, r.role_type), r.role_type, r.licensee_id
    INTO v_role_id, v_role_label, v_role_type, v_role_licensee
    FROM public.fp_individual_roles r
   WHERE r.id = a.role_id;

  v_licensee := COALESCE(a.licensee_id, v_role_licensee);

  -- Determination for THIS assessment only (never the person's current one).
  SELECT d.id, jsonb_build_object(
           'id', d.id, 'outcome', d.outcome, 'rationale', d.rationale,
           'determined_at', d.determined_at, 'determined_by', d.determined_by,
           'effective_from', d.effective_from, 'effective_to', d.effective_to,
           'is_current', d.is_current, 'is_committee_override', d.is_committee_override,
           'override_reason', d.override_reason)
    INTO v_det_id, v_det
    FROM public.fp_determinations d
   WHERE d.assessment_id = _assessment_id
   ORDER BY d.determined_at DESC NULLS LAST
   LIMIT 1;
  v_det := COALESCE(v_det, 'null'::jsonb);

  /* ---------------------------------------------------------------- stage */
  v_stage := a.status;
  v_stage_label := CASE a.status
    WHEN 'draft'              THEN 'Declaration requested'
    WHEN 'submitted'          THEN 'Declaration received'
    WHEN 'screening'          THEN 'Screening & findings'
    WHEN 'awaiting_committee' THEN 'Committee decision'
    WHEN 'determined'         THEN 'Determination issued'
    WHEN 'closed'             THEN 'Closed'
    WHEN 'withdrawn'          THEN 'Withdrawn'
    ELSE COALESCE(a.status, 'Unknown') END;

  /* ------------------------------------------------------------ evidence */
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', f.id, 'run_id', f.run_id, 'check_type', f.check_type,
           'severity', f.severity, 'title', f.title, 'summary', f.summary,
           'is_false_positive', f.is_false_positive,
           'resolution_status', f.resolution_status,
           'assigned_to', f.assigned_to,
           'created_at', f.created_at,
           'href', '/fpa/findings/' || f.id
         ) ORDER BY f.created_at DESC), '[]'::jsonb)
    INTO v_findings
    FROM public.fp_findings f
   WHERE f.assessment_id = _assessment_id;

  SELECT count(*) FILTER (WHERE COALESCE(f.is_false_positive,false) = false
                            AND COALESCE(f.resolution_status,'open') NOT IN ('resolved','dismissed','cleared')),
         count(*) FILTER (WHERE COALESCE(f.is_false_positive,false) = false
                            AND f.severity IN ('high','critical'))
    INTO v_open_findings, v_high_findings
    FROM public.fp_findings f
   WHERE f.assessment_id = _assessment_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', r.id, 'run_type', r.run_type, 'status', r.status,
           'started_at', r.started_at, 'completed_at', r.completed_at,
           'total_checks', r.total_checks, 'total_hits', r.total_hits,
           'error', r.error
         ) ORDER BY r.started_at DESC), '[]'::jsonb)
    INTO v_screening
    FROM public.fp_screening_runs r
   WHERE r.assessment_id = _assessment_id;

  /* ----------------------------------------------------------- committee */
  SELECT jsonb_build_object(
           'id', c.id, 'name', c.name, 'quorum', c.quorum,
           'approval_threshold_pct', c.approval_threshold_pct,
           'is_active', c.is_active,
           'member_count', (SELECT count(*) FROM public.fp_committee_members m
                             WHERE m.committee_id = c.id AND m.is_active),
           'my_membership_id', (SELECT m.id FROM public.fp_committee_members m
                                 WHERE m.committee_id = c.id AND m.user_id = v_user AND m.is_active LIMIT 1)
         )
    INTO v_committee
    FROM public.fp_committees c
   WHERE c.id = a.committee_id;
  v_committee := COALESCE(v_committee, 'null'::jsonb);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', v.id, 'member_id', v.member_id, 'vote', v.vote,
           'justification', v.justification, 'voted_at', v.voted_at, 'weight', v.weight
         ) ORDER BY v.voted_at), '[]'::jsonb)
    INTO v_votes
    FROM public.fp_committee_votes v
   WHERE v.assessment_id = _assessment_id;

  /* ------------------------------- conditions / monitoring / appeal (lineage) */
  IF v_det_id IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'id', k.id, 'category', k.category, 'description', k.description,
             'due_date', k.due_date, 'status', k.status,
             'monitoring_owner', k.monitoring_owner, 'evidence_type', k.evidence_type,
             'satisfied_at', k.satisfied_at
           ) ORDER BY k.created_at DESC), '[]'::jsonb),
           count(*) FILTER (WHERE k.status IN ('open','overdue'))
      INTO v_conditions, v_open_conditions
      FROM public.fp_conditions k
     WHERE k.determination_id = v_det_id;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'id', m.id, 'event_type', m.event_type, 'severity', m.severity,
             'summary', m.summary, 'raised_at', m.raised_at,
             'acknowledged_at', m.acknowledged_at
           ) ORDER BY m.raised_at DESC), '[]'::jsonb)
      INTO v_monitoring
      FROM public.fp_monitoring_events m
     WHERE m.determination_id = v_det_id;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'id', p.id, 'status', p.status, 'grounds', p.grounds,
             'filed_at', p.filed_at, 'decision', p.decision,
             'decision_rationale', p.decision_rationale, 'decided_at', p.decided_at
           ) ORDER BY p.filed_at DESC), '[]'::jsonb)
      INTO v_appeals
      FROM public.fp_appeals p
     WHERE p.determination_id = v_det_id;
  END IF;

  /* -------------------------------------------------------- declaration */
  v_declaration := jsonb_build_object(
    'pq_state', a.pq_state,
    'pq_amendment_reason', a.pq_amendment_reason,
    'submitted_at', a.submitted_at,
    'submitted_by', a.submitted_by,
    'form_template_id', a.form_template_id,
    'form_version_id', a.form_version_id,
    'form_response_id', a.form_response_id,
    'has_data', (a.declaration_data IS NOT NULL AND a.declaration_data <> '{}'::jsonb),
    'invitation', (
      SELECT jsonb_build_object('id', i.id, 'status', i.status, 'channel', i.channel,
                                'recipient_email', i.recipient_email,
                                'sent_at', i.sent_at, 'opened_at', i.opened_at,
                                'submitted_at', i.submitted_at, 'expires_at', i.expires_at)
        FROM public.declaration_invitations i
       WHERE i.assessment_id = _assessment_id
       ORDER BY i.created_at DESC LIMIT 1));

  /* ------------------------------------------------------ related cases */
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'kind', 'FP_ASSESSMENT',
           'label', COALESCE(o.assessment_type,'assessment') || ' — ' || o.status,
           'detail', to_char(o.created_at, 'DD Mon YYYY'),
           'href', '/fpa/assessments/' || o.id
         ) ORDER BY o.created_at DESC), '[]'::jsonb)
    INTO v_related
    FROM public.fp_assessments o
   WHERE o.individual_id = a.individual_id AND o.id <> _assessment_id;

  /* ------------------------------------------------------------ history */
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'at', l."timestamp", 'action', l.action_type::text,
           'object_type', l.object_type, 'user_id', l.user_id,
           'justification', l.justification
         ) ORDER BY l."timestamp" DESC), '[]'::jsonb)
    INTO v_history
    FROM (SELECT * FROM public.compliance_audit_logs
           WHERE object_id = _assessment_id::text
           ORDER BY "timestamp" DESC LIMIT 200) l;

  /* ---------------------------------------------------------- blockers */
  IF a.status = 'draft' AND COALESCE(a.declaration_data,'{}'::jsonb) = '{}'::jsonb THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','DECLARATION_OUTSTANDING','label','Declaration has not been received',
      'href','/fpa/assessments/' || a.id || '?section=declaration&from=current');
  END IF;
  IF a.status IN ('submitted','screening') AND jsonb_array_length(v_screening) = 0 THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','NO_SCREENING_RUN','label','No screening run recorded for this assessment',
      'href','/fpa/assessments/' || a.id || '?section=screening&from=current');
  END IF;
  IF a.status = 'awaiting_committee' AND a.committee_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','NO_COMMITTEE','label','No committee assigned to this assessment',
      'href','/fpa/assessments/' || a.id || '?section=committee&from=current');
  END IF;
  IF a.status = 'awaiting_committee' AND a.committee_id IS NOT NULL AND jsonb_array_length(v_votes) = 0 THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','NO_VOTES','label','Committee has not voted yet',
      'href','/fpa/assessments/' || a.id || '?section=committee&from=current');
  END IF;
  IF a.status = 'determined' AND v_det_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','NO_DETERMINATION','label','No determination is recorded for this assessment',
      'href','/fpa/assessments/' || a.id || '?section=determination&from=current');
  END IF;
  IF a.status = 'determined' AND v_open_conditions > 0 THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','OPEN_CONDITIONS','label','Determination conditions are still open',
      'href','/fpa/assessments/' || a.id || '?section=conditions&from=current');
  END IF;

  /* ------------------------------------------- available governed actions */
  IF v_can_act THEN
    IF a.status = 'draft' THEN
      v_actions := v_actions || jsonb_build_object('code','submit','label','Record declaration as received',
        'to_status','submitted','requires_reason',false,'permission','fit_and_proper.workflow_action',
        'enabled', COALESCE(a.declaration_data,'{}'::jsonb) <> '{}'::jsonb);
    ELSIF a.status = 'submitted' THEN
      v_actions := v_actions
        || jsonb_build_object('code','screening','label','Start screening','to_status','screening',
             'requires_reason',false,'permission','fit_and_proper.workflow_action','enabled',true)
        || jsonb_build_object('code','awaiting_committee','label','Refer to committee','to_status','awaiting_committee',
             'requires_reason',true,'permission','fit_and_proper.workflow_action','enabled', a.committee_id IS NOT NULL);
    ELSIF a.status = 'screening' THEN
      v_actions := v_actions
        || jsonb_build_object('code','awaiting_committee','label','Refer to committee','to_status','awaiting_committee',
             'requires_reason',true,'permission','fit_and_proper.workflow_action','enabled', a.committee_id IS NOT NULL)
        || jsonb_build_object('code','determined','label','Record determination','to_status','determined',
             'requires_reason',true,'permission','fit_and_proper.workflow_action','enabled', v_det_id IS NOT NULL);
    ELSIF a.status = 'awaiting_committee' THEN
      v_actions := v_actions
        || jsonb_build_object('code','determined','label','Record determination','to_status','determined',
             'requires_reason',true,'permission','fit_and_proper.workflow_action','enabled', v_det_id IS NOT NULL);
    ELSIF a.status = 'determined' THEN
      v_actions := v_actions
        || jsonb_build_object('code','closed','label','Close assessment case','to_status','closed',
             'requires_reason',true,'permission','fit_and_proper.workflow_action',
             'enabled', v_open_conditions = 0);
    END IF;
  END IF;

  v_next := CASE a.status
    WHEN 'draft'              THEN jsonb_build_object('code','declaration','label','Obtain and record the declaration')
    WHEN 'submitted'          THEN jsonb_build_object('code','screening','label','Run screening for this assessment')
    WHEN 'screening'          THEN jsonb_build_object('code','findings','label','Dispose of screening findings')
    WHEN 'awaiting_committee' THEN jsonb_build_object('code','committee','label','Complete committee voting')
    WHEN 'determined'         THEN jsonb_build_object('code','conditions','label','Monitor conditions, then close')
    ELSE 'null'::jsonb END;

  v_waiting := CASE a.status
    WHEN 'draft'              THEN 'Individual — declaration'
    WHEN 'submitted'          THEN 'Regulator — screening'
    WHEN 'screening'          THEN 'Regulator — findings disposition'
    WHEN 'awaiting_committee' THEN 'Committee — vote'
    WHEN 'determined'         THEN 'Regulator — conditions monitoring'
    ELSE NULL END;

  /* ---------------------------------------------------------------- SLA */
  v_sla_days := CASE a.status
    WHEN 'draft' THEN 14 WHEN 'submitted' THEN 10 WHEN 'screening' THEN 15
    WHEN 'awaiting_committee' THEN 20 WHEN 'determined' THEN 30 ELSE NULL END;
  v_sla_anchor := CASE a.status
    WHEN 'draft' THEN a.created_at
    WHEN 'submitted' THEN COALESCE(a.submitted_at, a.updated_at, a.created_at)
    WHEN 'determined' THEN COALESCE(a.determined_at, a.updated_at)
    ELSE COALESCE(a.pq_state_changed_at, a.updated_at, a.created_at) END;
  IF v_sla_days IS NOT NULL AND v_sla_anchor IS NOT NULL THEN
    v_sla_due := v_sla_anchor + (v_sla_days || ' days')::interval;
    v_sla_state := CASE
      WHEN now() > v_sla_due THEN 'breached'
      WHEN now() > v_sla_due - interval '3 days' THEN 'due_soon'
      ELSE 'on_track' END;
  ELSE
    v_sla_state := 'paused';
  END IF;

  v_priority := CASE
    WHEN a.status IN ('closed','withdrawn') THEN 'low'
    WHEN v_sla_state = 'breached' OR v_high_findings > 0 THEN 'critical'
    WHEN v_sla_state = 'due_soon' OR v_open_findings > 0 THEN 'high'
    ELSE 'medium' END;

  v_last := GREATEST(
    COALESCE(a.updated_at, a.created_at),
    COALESCE(a.submitted_at, a.created_at),
    COALESCE(a.determined_at, a.created_at),
    COALESCE(a.closed_at, a.created_at));

  RETURN jsonb_build_object(
    'found', true,
    'allowed', true,
    'generated_at', now(),
    'can_act', v_can_act,
    'assessment_id', a.id,
    'header', jsonb_build_object(
      'reference', 'FP-' || upper(substr(a.id::text, 1, 8)),
      'subject', COALESCE(v_person, 'Unknown individual'),
      'subject_href', '/fpa/individuals/' || a.individual_id,
      'individual_id', a.individual_id,
      'role_id', v_role_id,
      'role_label', v_role_label,
      'role_type', v_role_type,
      'licensee_id', v_licensee,
      'licensee_name', (SELECT l.name FROM public.licensees l WHERE l.id = v_licensee),
      'entity_href', CASE WHEN v_licensee IS NOT NULL THEN '/entities/' || v_licensee ELSE NULL END,
      'regulator_id', a.regulator_id,
      'regulator_name', (SELECT r.name FROM public.regulators r WHERE r.id = a.regulator_id),
      'assessment_type', a.assessment_type,
      'stage', v_stage,
      'stage_label', v_stage_label,
      'status', a.status,
      'status_label', v_stage_label,
      'owner_user_id', COALESCE(a.submitted_by, a.created_by),
      'team', 'Fit & Proper',
      'priority', v_priority,
      'sla_due_at', v_sla_due,
      'sla_state', v_sla_state,
      'waiting_on', v_waiting,
      'created_at', a.created_at,
      'last_activity_at', v_last
    ),
    'blockers', v_blockers,
    'available_actions', v_actions,
    'next_action', v_next,
    'declaration', v_declaration,
    'screening', jsonb_build_object(
      'runs', v_screening,
      'open_findings', v_open_findings,
      'high_findings', v_high_findings),
    'findings', v_findings,
    'committee', jsonb_build_object('committee', v_committee, 'votes', v_votes),
    'determination', v_det,
    'conditions', v_conditions,
    'monitoring', v_monitoring,
    'appeals', v_appeals,
    'related_cases', v_related,
    'history', v_history
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_assessment_comparison(_assessment_id uuid)
 RETURNS TABLE(check_type text, title text, change_class text, current_severity text, prior_severity text, current_finding_id uuid, prior_finding_id uuid, prior_assessment_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_individual uuid;
  v_created timestamptz;
  v_prior uuid;
BEGIN
  SELECT a.individual_id, a.created_at INTO v_individual, v_created
  FROM public.fp_assessments a
  WHERE a.id = _assessment_id
    AND public.fp_regulator_visible(a.regulator_id);
  IF v_individual IS NULL THEN
    RETURN;
  END IF;

  SELECT a.id INTO v_prior
  FROM public.fp_assessments a
  WHERE a.individual_id = v_individual
    AND a.id <> _assessment_id
    AND a.created_at < v_created
  ORDER BY a.created_at DESC
  LIMIT 1;

  RETURN QUERY
  WITH sev AS (
    SELECT * FROM (VALUES ('high',3),('medium',2),('low',1),('none',0)) s(name, rank)
  ),
  cur AS (
    SELECT f.id, coalesce(f.check_type,'other') AS check_type, coalesce(f.title,'(untitled)') AS title,
           coalesce(f.severity,'none') AS severity
    FROM public.fp_findings f WHERE f.assessment_id = _assessment_id
  ),
  pri AS (
    SELECT f.id, coalesce(f.check_type,'other') AS check_type, coalesce(f.title,'(untitled)') AS title,
           coalesce(f.severity,'none') AS severity
    FROM public.fp_findings f WHERE v_prior IS NOT NULL AND f.assessment_id = v_prior
  )
  SELECT coalesce(c.check_type, p.check_type),
         coalesce(c.title, p.title),
         CASE
           WHEN p.id IS NULL THEN 'new'
           WHEN c.id IS NULL THEN 'resolved'
           WHEN (SELECT rank FROM sev WHERE name = c.severity) >
                (SELECT rank FROM sev WHERE name = p.severity) THEN 'worsened'
           WHEN c.severity IS DISTINCT FROM p.severity THEN 'changed'
           ELSE 'unchanged'
         END,
         c.severity, p.severity, c.id, p.id, v_prior
  FROM cur c
  FULL OUTER JOIN pri p ON p.check_type = c.check_type AND p.title = c.title
  ORDER BY 1, 2;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_assessment_initiate(_individual_id uuid, _assessment_type text, _declaration_data jsonb DEFAULT '{}'::jsonb, _role_id uuid DEFAULT NULL::uuid, _licensee_id uuid DEFAULT NULL::uuid, _regulator_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_initiation','initiate_assessment');
  IF _assessment_type IS NULL OR btrim(_assessment_type) = '' THEN
    RAISE EXCEPTION 'assessment type is required' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fp_individuals WHERE id = _individual_id) THEN
    RAISE EXCEPTION 'individual not found' USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.fp_assessments
     WHERE individual_id = _individual_id
       AND assessment_type = _assessment_type
       AND status NOT IN ('determined','closed','withdrawn')
  ) THEN
    RAISE EXCEPTION 'an open % assessment already exists for this individual', _assessment_type
      USING ERRCODE='22023';
  END IF;

  INSERT INTO public.fp_assessments (
    individual_id, assessment_type, status, declaration_data,
    created_by, role_id, licensee_id, regulator_id)
  VALUES (
    _individual_id, _assessment_type, 'draft', COALESCE(_declaration_data,'{}'::jsonb),
    _uid, _role_id, _licensee_id, _regulator_id)
  RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.assessment.initiated','fp_assessment',_row.id, NULL,
    jsonb_build_object('assessment_type',_assessment_type,'status','draft',
                       'role_id',_role_id,'licensee_id',_licensee_id),
    jsonb_build_object('individual_id',_individual_id,'assessment_id',_row.id),
    NULL, 'CREATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_assessment_save_pq(_assessment_id uuid, _declaration_data jsonb, _submit boolean DEFAULT false, _form_response_id uuid DEFAULT NULL::uuid, _amendment_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','submit');
  SELECT * INTO _prev FROM public.fp_assessments WHERE id = _assessment_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'assessment not found' USING ERRCODE='22023'; END IF;
  IF _prev.status IN ('determined','closed','withdrawn') THEN
    RAISE EXCEPTION 'assessment is % — the questionnaire is closed', _prev.status USING ERRCODE='22023';
  END IF;
  IF _submit AND (_declaration_data IS NULL OR _declaration_data = '{}'::jsonb)
     AND COALESCE(_form_response_id, _prev.form_response_id) IS NULL THEN
    RAISE EXCEPTION 'cannot submit an empty questionnaire' USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_assessments
     SET declaration_data  = COALESCE(_declaration_data, declaration_data),
         form_response_id  = COALESCE(_form_response_id, form_response_id),
         pq_amendment_reason = COALESCE(NULLIF(btrim(COALESCE(_amendment_reason,'')),''), pq_amendment_reason),
         status       = CASE WHEN _submit THEN 'submitted' ELSE status END,
         submitted_at = CASE WHEN _submit THEN now() ELSE submitted_at END,
         submitted_by = CASE WHEN _submit THEN _uid ELSE submitted_by END
   WHERE id = _assessment_id RETURNING * INTO _row;

  IF _submit THEN
    PERFORM public.fp_audit_event(
      'fp.assessment.status_changed','fp_assessment',_assessment_id,
      jsonb_build_object('status',_prev.status),
      jsonb_build_object('status','submitted','form_response_id',_row.form_response_id),
      jsonb_build_object('individual_id',_prev.individual_id,'assessment_id',_assessment_id,
                         'source','pq_submission'));
  ELSE
    PERFORM public.fp_audit_event(
      'fp.assessment.pq_saved','fp_assessment',_assessment_id, NULL,
      jsonb_build_object('form_response_id',_row.form_response_id),
      jsonb_build_object('individual_id',_prev.individual_id,'assessment_id',_assessment_id),
      NULL, 'UPDATE');
  END IF;
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_assessment_set_status(_assessment_id uuid, _status text, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','workflow_action');
  IF _status NOT IN ('draft','submitted','screening','awaiting_committee','determined','closed','withdrawn') THEN
    RAISE EXCEPTION 'invalid assessment status %', _status USING ERRCODE='22023';
  END IF;
  SELECT * INTO _prev FROM public.fp_assessments WHERE id = _assessment_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'assessment not found' USING ERRCODE='22023'; END IF;
  IF _prev.status = _status THEN
    RAISE EXCEPTION 'assessment is already %', _status USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_assessments
     SET status = _status,
         closed_at = CASE WHEN _status IN ('closed','withdrawn') THEN now() ELSE closed_at END
   WHERE id = _assessment_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.assessment.status_changed','fp_assessment',_assessment_id,
    jsonb_build_object('status',_prev.status),
    jsonb_build_object('status',_status),
    jsonb_build_object('individual_id',_prev.individual_id,'assessment_id',_assessment_id),
    NULLIF(btrim(COALESCE(_note,'')),''));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_audit_event(_action text, _entity_type text, _entity_id uuid, _before jsonb DEFAULT NULL::jsonb, _after jsonb DEFAULT NULL::jsonb, _context jsonb DEFAULT '{}'::jsonb, _justification text DEFAULT NULL::text, _compliance_action compliance_audit_action DEFAULT 'WORKFLOW_TRANSITION'::compliance_audit_action)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid();
BEGIN
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid, _action, _entity_type, _entity_id,
          jsonb_strip_nulls(
            COALESCE(_context,'{}'::jsonb)
            || jsonb_build_object('before',_before,'after',_after,'justification',_justification)));

  INSERT INTO public.compliance_audit_logs (
    user_id, action_type, object_type, object_id, before_value, after_value, justification, metadata)
  VALUES (_uid, _compliance_action, _entity_type, _entity_id::text, _before, _after, _justification,
          jsonb_strip_nulls(COALESCE(_context,'{}'::jsonb) || jsonb_build_object('action',_action)));
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_can_read_evidence_object(_user uuid, _name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_individual uuid;
  v_registered boolean;
BEGIN
  SELECT individual_id, true INTO v_individual, v_registered
  FROM public.fp_condition_evidence
  WHERE file_path = _name
  LIMIT 1;

  IF coalesce(v_registered,false) THEN
    -- condition evidence: individual-scoped, never "any F&P viewer"
    RETURN v_individual IS NULL
             AND public.has_permission(_user,'fit_and_proper','view')
           OR public.can_read_fp_individual(_user, v_individual);
  END IF;

  -- every other object in the bucket keeps the previous module-level rule
  RETURN public.is_super_admin(_user)
      OR public.has_permission(_user,'fit_and_proper','view');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_check_assessment_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_has_screening BOOLEAN;
  v_has_determination BOOLEAN;
  v_override BOOLEAN;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
    IF OLD.status IN ('determined','closed') THEN
      SELECT EXISTS (
        SELECT 1 FROM public.rule_overrides
        WHERE rule_key = 'fit_and_proper.assessment.edit_finalized'
          AND (entity_id = OLD.id::text OR entity_id IS NULL)
          AND created_at > (now() - interval '1 hour')
      ) INTO v_override;
      IF NOT v_override AND NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
        RAISE EXCEPTION 'F&P assessment % is % and cannot be edited without an admin override', OLD.id, OLD.status
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status = 'submitted' AND OLD.status = 'draft' THEN
    IF NEW.form_response_id IS NULL AND (NEW.declaration_data IS NULL OR NEW.declaration_data = '{}'::jsonb) THEN
      RAISE EXCEPTION 'Cannot submit assessment: PQ/declaration is empty' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.status = 'awaiting_committee' AND OLD.status IN ('submitted','screening') THEN
    SELECT EXISTS (SELECT 1 FROM public.fp_screening_runs WHERE assessment_id = NEW.id AND status = 'completed')
      INTO v_has_screening;
    IF NOT v_has_screening THEN
      SELECT EXISTS (
        SELECT 1 FROM public.rule_overrides
        WHERE rule_key = 'fit_and_proper.skip_screening'
          AND entity_id = NEW.id::text
          AND created_at > (now() - interval '1 hour')
      ) INTO v_override;
      IF NOT v_override THEN
        RAISE EXCEPTION 'Cannot route to committee: no successful screening run and no override'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  ELSIF NEW.status = 'determined' AND OLD.status IN ('awaiting_committee','submitted','screening') THEN
    SELECT EXISTS (SELECT 1 FROM public.fp_determinations WHERE assessment_id = NEW.id AND is_current = true)
      INTO v_has_determination;
    IF NOT v_has_determination THEN
      RAISE EXCEPTION 'Cannot mark determined: no finalized determination exists' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.status = 'closed' AND OLD.status = 'determined' THEN
    NULL;
  ELSIF NEW.status = 'screening' AND OLD.status = 'submitted' THEN
    NULL;
  ELSE
    IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
      RAISE EXCEPTION 'Invalid F&P assessment transition: % -> %', OLD.status, NEW.status
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_check_committee_vote()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_active BOOLEAN;
  v_exists BOOLEAN;
BEGIN
  SELECT is_active INTO v_active FROM public.fp_committee_members WHERE id = NEW.member_id;
  IF v_active IS NULL OR v_active = false THEN
    RAISE EXCEPTION 'Committee member % is not active', NEW.member_id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.vote IN ('reject','conditional') AND (NEW.justification IS NULL OR length(trim(NEW.justification)) < 10) THEN
    RAISE EXCEPTION 'Justification (min 10 chars) required for % votes', NEW.vote USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.fp_committee_votes
      WHERE assessment_id = NEW.assessment_id AND member_id = NEW.member_id
    ) INTO v_exists;
    IF v_exists THEN
      RAISE EXCEPTION 'Member % has already voted on assessment %', NEW.member_id, NEW.assessment_id
        USING ERRCODE = 'unique_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_check_determination_finalize()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_committee_id UUID;
  v_quorum INT;
  v_threshold NUMERIC;
  v_total INT;
  v_approve INT;
  v_conditional INT;
  v_pct NUMERIC;
  v_has_screening BOOLEAN;
  v_open_high_findings INT;
BEGIN
  IF NEW.is_current IS DISTINCT FROM true THEN RETURN NEW; END IF;
  IF NEW.rationale IS NULL OR length(trim(NEW.rationale)) < 10 THEN
    RAISE EXCEPTION 'Determination rationale required (min 10 chars)' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.supersedes_id IS NOT NULL THEN RETURN NEW; END IF;

  SELECT committee_id INTO v_committee_id FROM public.fp_assessments WHERE id = NEW.assessment_id;

  IF v_committee_id IS NOT NULL THEN
    -- Committee attached: quorum/threshold are mandatory. The override flag
    -- does not apply here — attaching a committee is itself the commitment
    -- to go through it.
    SELECT quorum, approval_threshold_pct INTO v_quorum, v_threshold
      FROM public.fp_committees WHERE id = v_committee_id;

    SELECT count(*), count(*) FILTER (WHERE vote = 'approve'), count(*) FILTER (WHERE vote = 'conditional')
      INTO v_total, v_approve, v_conditional
      FROM public.fp_committee_votes WHERE assessment_id = NEW.assessment_id;

    IF v_total < COALESCE(v_quorum, 1) THEN
      RAISE EXCEPTION 'Quorum not met: % votes cast, % required', v_total, v_quorum USING ERRCODE = 'check_violation';
    END IF;

    v_pct := CASE WHEN v_total > 0 THEN ((v_approve + v_conditional)::numeric / v_total) * 100 ELSE 0 END;

    IF NEW.outcome IN ('approved','conditional') AND v_pct < COALESCE(v_threshold, 50) THEN
      RAISE EXCEPTION 'Approval threshold not met: % percent vs required % percent', round(v_pct,1), v_threshold
        USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
  END IF;

  -- No committee attached (fast-track path). Require completed screening —
  -- or an explicit, permissioned, documented override in its place.
  SELECT EXISTS (
    SELECT 1 FROM public.fp_screening_runs
    WHERE assessment_id = NEW.assessment_id AND status = 'completed'
  ) INTO v_has_screening;

  IF v_has_screening THEN
    IF NOT public.is_fp_staff(auth.uid()) THEN
      RAISE EXCEPTION 'Cannot finalize determination without an assigned committee' USING ERRCODE = 'check_violation';
    END IF;

    -- Even with completed screening, don't let a determination finalize
    -- over still-open high/critical findings unless explicitly overridden.
    SELECT count(*) INTO v_open_high_findings
      FROM public.fp_findings
      WHERE assessment_id = NEW.assessment_id
        AND severity IN ('high','critical')
        AND coalesce(is_false_positive, false) IS NOT TRUE
        AND coalesce(resolution_status, 'pending') = 'pending';

    IF v_open_high_findings > 0 AND NOT COALESCE(NEW.is_committee_override, false) THEN
      RAISE EXCEPTION '% unresolved high/critical finding(s) remain — resolve them or use the override action with a documented reason', v_open_high_findings
        USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
  END IF;

  IF COALESCE(NEW.is_committee_override, false) THEN
    IF NEW.override_reason IS NULL OR length(trim(NEW.override_reason)) < 20 THEN
      RAISE EXCEPTION 'Committee/screening override reason must be at least 20 characters' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT (public.is_super_admin(auth.uid()) OR public.has_permission(auth.uid(), 'fit_and_proper', 'override_committee')) THEN
      RAISE EXCEPTION 'Finalizing without completed screening/committee requires the F&P committee-override permission' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Cannot finalize determination: no completed screening run and no committee assigned — use the override action with a documented reason'
    USING ERRCODE = 'check_violation';
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_check_determination_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_override BOOLEAN;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.is_current = true AND NEW.is_current = false
     AND OLD.outcome IS NOT DISTINCT FROM NEW.outcome
     AND OLD.rationale IS NOT DISTINCT FROM NEW.rationale
     AND OLD.assessment_id IS NOT DISTINCT FROM NEW.assessment_id THEN
    RETURN NEW;
  END IF;
  IF (TG_OP = 'UPDATE' AND OLD.is_current = true) OR (TG_OP = 'DELETE' AND OLD.is_current = true) THEN
    SELECT EXISTS (
      SELECT 1 FROM public.rule_overrides
      WHERE rule_key = 'fit_and_proper.determination.edit_finalized'
        AND entity_id = OLD.id::text
        AND created_at > (now() - interval '1 hour')
    ) INTO v_override;
    IF NOT v_override AND NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
      RAISE EXCEPTION 'Finalized determination % is immutable; use appeal or admin override', OLD.id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_committee_cast_vote(_assessment_id uuid, _vote text, _justification text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _assess record; _member record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_committee','cast_weighted_vote');
  IF _vote NOT IN ('approve','conditional','reject','abstain') THEN
    RAISE EXCEPTION 'invalid vote %', _vote USING ERRCODE='22023';
  END IF;
  SELECT * INTO _assess FROM public.fp_assessments WHERE id = _assessment_id;
  IF _assess IS NULL THEN RAISE EXCEPTION 'assessment not found' USING ERRCODE='22023'; END IF;
  IF _assess.committee_id IS NULL THEN
    RAISE EXCEPTION 'assessment is not routed to a committee' USING ERRCODE='22023';
  END IF;
  IF _assess.status <> 'awaiting_committee' THEN
    RAISE EXCEPTION 'assessment is "%" — voting is only open while Awaiting Committee', _assess.status
      USING ERRCODE='22023';
  END IF;

  SELECT * INTO _member FROM public.fp_committee_members
   WHERE committee_id = _assess.committee_id AND user_id = _uid AND is_active;
  IF _member IS NULL THEN
    RAISE EXCEPTION 'you are not an active member of this committee' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.fp_committee_votes
              WHERE assessment_id = _assessment_id AND member_id = _member.id) THEN
    RAISE EXCEPTION 'you have already voted on this assessment' USING ERRCODE='22023';
  END IF;
  IF _vote IN ('reject','conditional') AND (_justification IS NULL OR length(btrim(_justification)) < 10) THEN
    RAISE EXCEPTION 'a justification of at least 10 characters is required for reject/conditional votes'
      USING ERRCODE='22023';
  END IF;

  INSERT INTO public.fp_committee_votes (
    assessment_id, committee_id, member_id, vote, justification, weight)
  VALUES (
    _assessment_id, _assess.committee_id, _member.id, _vote,
    NULLIF(btrim(COALESCE(_justification,'')),''), _member.vote_weight)
  RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.committee.vote_cast','fp_committee_vote',_row.id, NULL,
    jsonb_build_object('vote',_vote,'weight',_member.vote_weight),
    jsonb_build_object('individual_id',_assess.individual_id,'assessment_id',_assessment_id,
                       'committee_id',_assess.committee_id),
    NULLIF(btrim(COALESCE(_justification,'')),''),'APPROVE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_committee_create(_name text, _quorum integer, _approval_threshold_pct numeric, _description text DEFAULT NULL::text, _regulator_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_committee','create');
  IF COALESCE(btrim(_name),'') = '' THEN
    RAISE EXCEPTION 'committee name is required' USING ERRCODE='22023';
  END IF;
  IF _quorum IS NULL OR _quorum < 1 THEN
    RAISE EXCEPTION 'quorum must be at least 1' USING ERRCODE='22023';
  END IF;
  IF _approval_threshold_pct IS NULL OR _approval_threshold_pct <= 0 OR _approval_threshold_pct > 100 THEN
    RAISE EXCEPTION 'approval threshold must be between 1 and 100 percent' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.fp_committees (name, description, regulator_id, quorum, approval_threshold_pct, is_active)
  VALUES (btrim(_name), NULLIF(btrim(COALESCE(_description,'')),''), _regulator_id,
          _quorum, _approval_threshold_pct, true)
  RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.committee.created','fp_committee',_row.id, NULL,
    jsonb_build_object('name',_row.name,'quorum',_quorum,'approval_threshold_pct',_approval_threshold_pct,
                       'regulator_id',_regulator_id),
    jsonb_build_object('committee_id',_row.id),NULL,'CREATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_committee_member_add(_committee_id uuid, _user_id uuid, _member_role text DEFAULT 'member'::text, _vote_weight numeric DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_committee','edit');
  IF _vote_weight IS NULL OR _vote_weight <= 0 THEN
    RAISE EXCEPTION 'vote weight must be greater than zero' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fp_committees WHERE id = _committee_id) THEN
    RAISE EXCEPTION 'committee not found' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _user_id) THEN
    RAISE EXCEPTION 'user not found' USING ERRCODE='22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.fp_committee_members
              WHERE committee_id = _committee_id AND user_id = _user_id AND is_active) THEN
    RAISE EXCEPTION 'user is already an active member of this committee' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.fp_committee_members (committee_id, user_id, member_role, vote_weight, is_active)
  VALUES (_committee_id, _user_id, COALESCE(NULLIF(btrim(_member_role),''),'member'), _vote_weight, true)
  RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.committee.member_added','fp_committee',_committee_id, NULL,
    jsonb_build_object('member_id',_row.id,'user_id',_user_id,'member_role',_row.member_role,
                       'vote_weight',_vote_weight),
    jsonb_build_object('committee_id',_committee_id),NULL,'CREATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_committee_member_remove(_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _prev record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_committee','edit');
  SELECT * INTO _prev FROM public.fp_committee_members WHERE id = _member_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'committee member not found' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM public.fp_committee_votes WHERE member_id = _member_id) THEN
    RAISE EXCEPTION 'this member has cast votes and cannot be removed — deactivate them instead'
      USING ERRCODE='22023';
  END IF;

  DELETE FROM public.fp_committee_members WHERE id = _member_id;

  PERFORM public.fp_audit_event(
    'fp.committee.member_removed','fp_committee',_prev.committee_id,
    jsonb_build_object('member_id',_member_id,'user_id',_prev.user_id), NULL,
    jsonb_build_object('committee_id',_prev.committee_id),NULL,'DELETE');
  RETURN jsonb_build_object('ok',true,'member_id',_member_id);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_committee_member_set_active(_member_id uuid, _is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_committee','edit');
  SELECT * INTO _prev FROM public.fp_committee_members WHERE id = _member_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'committee member not found' USING ERRCODE='22023'; END IF;

  UPDATE public.fp_committee_members SET is_active = _is_active
   WHERE id = _member_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.committee.member_active_changed','fp_committee',_prev.committee_id,
    jsonb_build_object('member_id',_member_id,'is_active',_prev.is_active),
    jsonb_build_object('member_id',_member_id,'is_active',_is_active),
    jsonb_build_object('committee_id',_prev.committee_id),NULL,'UPDATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_committee_member_set_weight(_member_id uuid, _vote_weight numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_committee','edit');
  IF _vote_weight IS NULL OR _vote_weight <= 0 THEN
    RAISE EXCEPTION 'vote weight must be greater than zero' USING ERRCODE='22023';
  END IF;
  SELECT * INTO _prev FROM public.fp_committee_members WHERE id = _member_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'committee member not found' USING ERRCODE='22023'; END IF;

  UPDATE public.fp_committee_members SET vote_weight = _vote_weight
   WHERE id = _member_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.committee.member_weight_changed','fp_committee',_prev.committee_id,
    jsonb_build_object('member_id',_member_id,'vote_weight',_prev.vote_weight),
    jsonb_build_object('member_id',_member_id,'vote_weight',_vote_weight),
    jsonb_build_object('committee_id',_prev.committee_id),NULL,'UPDATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_committee_set_casting_vote(_committee_id uuid, _member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_committee','edit');
  SELECT * INTO _prev FROM public.fp_committees WHERE id = _committee_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'committee not found' USING ERRCODE='22023'; END IF;
  IF _member_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.fp_committee_members
        WHERE id = _member_id AND committee_id = _committee_id AND is_active) THEN
    RAISE EXCEPTION 'casting-vote holder must be an active member of this committee' USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_committees SET casting_vote_member_id = _member_id
   WHERE id = _committee_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.committee.casting_vote_set','fp_committee',_committee_id,
    jsonb_build_object('casting_vote_member_id',_prev.casting_vote_member_id),
    jsonb_build_object('casting_vote_member_id',_member_id),
    jsonb_build_object('committee_id',_committee_id),NULL,'UPDATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_committee_update(_committee_id uuid, _name text DEFAULT NULL::text, _quorum integer DEFAULT NULL::integer, _approval_threshold_pct numeric DEFAULT NULL::numeric, _description text DEFAULT NULL::text, _is_active boolean DEFAULT NULL::boolean, _regulator_id uuid DEFAULT NULL::uuid, _clear_regulator boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_committee','edit');
  SELECT * INTO _prev FROM public.fp_committees WHERE id = _committee_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'committee not found' USING ERRCODE='22023'; END IF;
  IF _quorum IS NOT NULL AND _quorum < 1 THEN
    RAISE EXCEPTION 'quorum must be at least 1' USING ERRCODE='22023';
  END IF;
  IF _approval_threshold_pct IS NOT NULL
     AND (_approval_threshold_pct <= 0 OR _approval_threshold_pct > 100) THEN
    RAISE EXCEPTION 'approval threshold must be between 1 and 100 percent' USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_committees
     SET name = COALESCE(NULLIF(btrim(COALESCE(_name,'')),''), name),
         description = COALESCE(NULLIF(btrim(COALESCE(_description,'')),''), description),
         quorum = COALESCE(_quorum, quorum),
         approval_threshold_pct = COALESCE(_approval_threshold_pct, approval_threshold_pct),
         is_active = COALESCE(_is_active, is_active),
         regulator_id = CASE WHEN _clear_regulator THEN NULL
                             ELSE COALESCE(_regulator_id, regulator_id) END
   WHERE id = _committee_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.committee.updated','fp_committee',_committee_id,
    jsonb_build_object('name',_prev.name,'quorum',_prev.quorum,
                       'approval_threshold_pct',_prev.approval_threshold_pct,
                       'is_active',_prev.is_active,'regulator_id',_prev.regulator_id),
    jsonb_build_object('name',_row.name,'quorum',_row.quorum,
                       'approval_threshold_pct',_row.approval_threshold_pct,
                       'is_active',_row.is_active,'regulator_id',_row.regulator_id),
    jsonb_build_object('committee_id',_committee_id),NULL,'UPDATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_condition_create(_determination_id uuid, _individual_id uuid, _category text, _description text, _due_date date DEFAULT NULL::date, _monitoring_owner uuid DEFAULT NULL::uuid, _evidence_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _det record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_conditions','create');
  IF _description IS NULL OR btrim(_description) = '' THEN
    RAISE EXCEPTION 'condition description is required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO _det FROM public.fp_determinations WHERE id = _determination_id;
  IF _det IS NULL THEN RAISE EXCEPTION 'determination not found' USING ERRCODE='22023'; END IF;
  IF _det.individual_id <> _individual_id THEN
    RAISE EXCEPTION 'determination does not belong to this individual' USING ERRCODE='22023';
  END IF;
  IF NOT _det.is_current THEN
    RAISE EXCEPTION 'conditions may only be attached to the current determination' USING ERRCODE='22023';
  END IF;
  IF _due_date IS NOT NULL AND _due_date < CURRENT_DATE THEN
    RAISE EXCEPTION 'condition due date cannot be in the past' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.fp_conditions (
    determination_id, individual_id, category, description, due_date,
    monitoring_owner, evidence_type, status, created_by)
  VALUES (
    _determination_id, _individual_id, COALESCE(NULLIF(btrim(COALESCE(_category,'')),''),'other'),
    btrim(_description), _due_date, _monitoring_owner,
    NULLIF(btrim(COALESCE(_evidence_type,'')),''), 'open', _uid)
  RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.condition.created','fp_condition',_row.id, NULL,
    jsonb_build_object('category',_row.category,'due_date',_due_date,'status','open',
                       'evidence_type',_row.evidence_type),
    jsonb_build_object('individual_id',_individual_id,'determination_id',_determination_id,
                       'condition_id',_row.id),
    NULL,'CREATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_condition_events_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'Condition history is append-only' USING ERRCODE = 'insufficient_privilege';
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_condition_evidence_review(_evidence_id uuid, _review_state text, _review_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_conditions','approve');
  IF _review_state NOT IN ('accepted','rejected') THEN
    RAISE EXCEPTION 'invalid evidence review state %', _review_state USING ERRCODE='22023';
  END IF;
  SELECT * INTO _prev FROM public.fp_condition_evidence WHERE id = _evidence_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'evidence not found' USING ERRCODE='22023'; END IF;
  IF COALESCE(_prev.review_state,'pending') <> 'pending' THEN
    RAISE EXCEPTION 'evidence has already been reviewed as %', _prev.review_state USING ERRCODE='22023';
  END IF;
  IF _prev.submitted_by = _uid THEN
    RAISE EXCEPTION 'evidence cannot be reviewed by the person who submitted it' USING ERRCODE='42501';
  END IF;
  IF _review_state = 'rejected' AND (_review_note IS NULL OR length(btrim(_review_note)) < 5) THEN
    RAISE EXCEPTION 'rejection note must be at least 5 characters' USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_condition_evidence
     SET review_state = _review_state, reviewed_by = _uid, reviewed_at = now(),
         review_note = NULLIF(btrim(COALESCE(_review_note,'')),'')
   WHERE id = _evidence_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.condition.evidence_reviewed','fp_condition',_prev.condition_id,
    jsonb_build_object('review_state','pending'),
    jsonb_build_object('evidence_id',_evidence_id,'review_state',_review_state),
    jsonb_build_object('individual_id',_prev.individual_id,'condition_id',_prev.condition_id),
    NULLIF(btrim(COALESCE(_review_note,'')),''),
    CASE WHEN _review_state = 'accepted' THEN 'APPROVE' ELSE 'REJECT' END::compliance_audit_action);
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_condition_evidence_submit(_condition_id uuid, _file_path text, _file_name text, _file_size integer DEFAULT NULL::integer, _description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _cond record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','upload_documents');
  IF COALESCE(btrim(_file_path),'') = '' OR COALESCE(btrim(_file_name),'') = '' THEN
    RAISE EXCEPTION 'evidence file path and name are required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO _cond FROM public.fp_conditions WHERE id = _condition_id;
  IF _cond IS NULL THEN RAISE EXCEPTION 'condition not found' USING ERRCODE='22023'; END IF;
  IF _cond.status IN ('satisfied','waived') THEN
    RAISE EXCEPTION 'condition is % — evidence can no longer be submitted', _cond.status USING ERRCODE='22023';
  END IF;

  INSERT INTO public.fp_condition_evidence (
    condition_id, individual_id, regulator_id, file_path, file_name, file_size,
    description, submitted_by, review_state)
  VALUES (
    _condition_id, _cond.individual_id,
    (SELECT regulator_id FROM public.fp_individuals WHERE id = _cond.individual_id),
    btrim(_file_path), btrim(_file_name), _file_size,
    NULLIF(btrim(COALESCE(_description,'')),''), _uid, 'pending')
  RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.condition.evidence_submitted','fp_condition',_condition_id, NULL,
    jsonb_build_object('evidence_id',_row.id,'file_name',_row.file_name,'review_state','pending'),
    jsonb_build_object('individual_id',_cond.individual_id,'condition_id',_condition_id),
    NULL,'CREATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_condition_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'waived' THEN
    IF NEW.waiver_reason IS NULL OR length(trim(NEW.waiver_reason)) < 5 THEN
      IF NEW.satisfaction_note IS NOT NULL AND length(trim(NEW.satisfaction_note)) >= 5 THEN
        NEW.waiver_reason := NEW.satisfaction_note;
      ELSE
        RAISE EXCEPTION 'Waiver reason (min 5 chars) required to mark condition as waived';
      END IF;
    END IF;
  END IF;

  IF NEW.status = 'breached'
     AND (NEW.satisfaction_note IS NULL OR length(trim(NEW.satisfaction_note)) < 5) THEN
    RAISE EXCEPTION 'Breach rationale (min 5 chars) required to mark condition as breached'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status IN ('open','breached') AND NEW.due_date IS NOT NULL AND NEW.due_date < CURRENT_DATE THEN
    IF NEW.overdue_at IS NULL THEN
      NEW.overdue_at := now();
    END IF;
  ELSIF NEW.status IN ('satisfied','waived') THEN
    NULL;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_condition_log_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reg uuid;
BEGIN
  SELECT i.regulator_id INTO v_reg FROM public.fp_individuals i WHERE i.id = NEW.individual_id;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.fp_condition_events (condition_id, individual_id, regulator_id, event_type, to_status, reason, actor_id)
    VALUES (NEW.id, NEW.individual_id, v_reg, 'created', NEW.status, NEW.description, auth.uid());
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.fp_condition_events (condition_id, individual_id, regulator_id, event_type, from_status, to_status, reason, actor_id)
    VALUES (NEW.id, NEW.individual_id, v_reg, 'status_change', OLD.status, NEW.status,
            coalesce(NEW.waiver_reason, NEW.satisfaction_note), auth.uid());
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_condition_record_reminder(_condition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_conditions','edit');
  SELECT * INTO _prev FROM public.fp_conditions WHERE id = _condition_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'condition not found' USING ERRCODE='22023'; END IF;
  IF _prev.status IN ('satisfied','waived') THEN
    RAISE EXCEPTION 'condition is % — no reminder is due', _prev.status USING ERRCODE='22023';
  END IF;

  INSERT INTO public.fp_monitoring_events (
    individual_id, determination_id, event_type, severity, summary, detail)
  VALUES (
    _prev.individual_id, _prev.determination_id, 'condition_due', 'low',
    'Condition due on ' || COALESCE(_prev.due_date::text,'(no date)') || ': ' || left(COALESCE(_prev.description,''),200),
    jsonb_build_object('condition_id',_condition_id,'due_date',_prev.due_date,'reminder',true,'manual',true));

  UPDATE public.fp_conditions SET reminder_sent_at = now()
   WHERE id = _condition_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.condition.reminder_sent','fp_condition',_condition_id, NULL,
    jsonb_build_object('reminder_sent_at',_row.reminder_sent_at),
    jsonb_build_object('individual_id',_prev.individual_id,'condition_id',_condition_id),
    NULL,'NOTIFICATION_SENT');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_condition_set_status(_condition_id uuid, _status text, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  IF _status NOT IN ('open','satisfied','waived','overdue','breached') THEN
    RAISE EXCEPTION 'invalid condition status %', _status USING ERRCODE='22023';
  END IF;

  IF _status IN ('satisfied','waived') THEN
    PERFORM public.enforce_permission('fit_and_proper_conditions','approve');
  ELSE
    PERFORM public.enforce_permission('fit_and_proper_conditions','edit');
  END IF;

  SELECT * INTO _prev FROM public.fp_conditions WHERE id = _condition_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'condition not found' USING ERRCODE='22023'; END IF;
  IF _prev.status = _status THEN
    RAISE EXCEPTION 'condition is already %', _status USING ERRCODE='22023';
  END IF;
  IF _prev.status IN ('satisfied','waived') AND _status <> 'open' THEN
    RAISE EXCEPTION 'a closed condition must be reopened before it can move to %', _status
      USING ERRCODE='22023';
  END IF;

  IF _status = 'satisfied' THEN
    IF _prev.evidence_type IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.fp_condition_evidence
       WHERE condition_id = _condition_id AND review_state = 'accepted') THEN
      RAISE EXCEPTION 'condition requires accepted evidence before it can be satisfied'
        USING ERRCODE='22023';
    END IF;
  ELSIF _status = 'waived' THEN
    IF _note IS NULL OR length(btrim(_note)) < 5 THEN
      RAISE EXCEPTION 'waiver reason must be at least 5 characters' USING ERRCODE='22023';
    END IF;
  ELSIF _status = 'breached' THEN
    IF _note IS NULL OR length(btrim(_note)) < 5 THEN
      RAISE EXCEPTION 'breach rationale must be at least 5 characters' USING ERRCODE='22023';
    END IF;
  ELSIF _status = 'open' AND _prev.status IN ('satisfied','waived') THEN
    IF _note IS NULL OR length(btrim(_note)) < 5 THEN
      RAISE EXCEPTION 'reopen reason must be at least 5 characters' USING ERRCODE='22023';
    END IF;
  END IF;

  UPDATE public.fp_conditions
     SET status = _status,
         satisfied_at = CASE WHEN _status IN ('satisfied','waived') THEN now()
                             WHEN _status = 'open' THEN NULL ELSE satisfied_at END,
         satisfied_by = CASE WHEN _status IN ('satisfied','waived') THEN _uid
                             WHEN _status = 'open' THEN NULL ELSE satisfied_by END,
         satisfaction_note = CASE WHEN _status = 'open' THEN NULL
                                  ELSE NULLIF(btrim(COALESCE(_note,'')),'') END,
         waiver_reason = CASE WHEN _status = 'waived' THEN btrim(_note)
                              WHEN _status = 'open' THEN NULL ELSE waiver_reason END
   WHERE id = _condition_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.condition.status_changed','fp_condition',_condition_id,
    jsonb_build_object('status',_prev.status),
    jsonb_build_object('status',_status),
    jsonb_build_object('individual_id',_prev.individual_id,
                       'determination_id',_prev.determination_id,'condition_id',_condition_id),
    NULLIF(btrim(COALESCE(_note,'')),''),
    CASE WHEN _status IN ('satisfied','waived') THEN 'APPROVE' ELSE 'WORKFLOW_TRANSITION' END::compliance_audit_action);
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_declaration_invitation_create(_assessment_id uuid, _individual_id uuid, _token_hash text, _verification_hash text, _channel text, _expires_at timestamp with time zone, _verification_hash_alt text DEFAULT NULL::text, _recipient_email text DEFAULT NULL::text, _recipient_phone text DEFAULT NULL::text, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _assessment record; _row record; _merged jsonb;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','edit');

  IF _channel NOT IN ('EMAIL','SMS','PORTAL') THEN
    RAISE EXCEPTION 'invalid declaration channel %', _channel USING ERRCODE='22023';
  END IF;
  IF _token_hash IS NULL OR length(btrim(_token_hash)) = 0
     OR _verification_hash IS NULL OR length(btrim(_verification_hash)) = 0 THEN
    RAISE EXCEPTION 'token and verification hashes are required' USING ERRCODE='22023';
  END IF;
  IF _expires_at IS NULL OR _expires_at <= now() THEN
    RAISE EXCEPTION 'invitation expiry must be in the future' USING ERRCODE='22023';
  END IF;

  SELECT * INTO _assessment FROM public.fp_assessments WHERE id = _assessment_id FOR UPDATE;
  IF _assessment IS NULL THEN
    RAISE EXCEPTION 'assessment not found' USING ERRCODE='22023';
  END IF;
  IF _assessment.individual_id <> _individual_id THEN
    RAISE EXCEPTION 'individual does not belong to this assessment' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.declaration_invitations (
    individual_id, assessment_id, token_hash, verification_hash, verification_hash_alt,
    channel, recipient_email, recipient_phone, status, expires_at, created_by
  ) VALUES (
    _individual_id, _assessment_id, btrim(_token_hash), btrim(_verification_hash),
    NULLIF(btrim(COALESCE(_verification_hash_alt,'')),''),
    _channel, NULLIF(btrim(COALESCE(_recipient_email,'')),''),
    NULLIF(btrim(COALESCE(_recipient_phone,'')),''),
    'PENDING', _expires_at, _uid
  ) RETURNING * INTO _row;

  _merged := COALESCE(_assessment.declaration_data,'{}'::jsonb) || jsonb_build_object(
    'channel', _channel,
    'requested_at', now(),
    'note', NULLIF(btrim(COALESCE(_note,'')),'')
  );

  UPDATE public.fp_assessments SET declaration_data = _merged WHERE id = _assessment_id;

  PERFORM public.fp_audit_event(
    'fp.declaration.invitation_created','fp_assessment',_assessment_id,
    jsonb_build_object('declaration_data',_assessment.declaration_data),
    jsonb_build_object('declaration_data',_merged,'invitation_id',_row.id),
    jsonb_build_object('individual_id',_individual_id,'assessment_id',_assessment_id,
                       'channel',_channel),
    NULLIF(btrim(COALESCE(_note,'')),''),
    'NOTIFICATION_SENT'::compliance_audit_action);

  RETURN jsonb_build_object('invitation_id',_row.id,'declaration_data',_merged);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_declaration_invitation_resend(_invitation_id uuid, _token_hash text, _expires_at timestamp with time zone, _recipient_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prior record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','edit');

  IF _token_hash IS NULL OR length(btrim(_token_hash)) = 0 THEN
    RAISE EXCEPTION 'token hash is required' USING ERRCODE='22023';
  END IF;
  IF _expires_at IS NULL OR _expires_at <= now() THEN
    RAISE EXCEPTION 'invitation expiry must be in the future' USING ERRCODE='22023';
  END IF;

  SELECT * INTO _prior FROM public.declaration_invitations WHERE id = _invitation_id FOR UPDATE;
  IF _prior IS NULL THEN
    RAISE EXCEPTION 'invitation not found' USING ERRCODE='22023';
  END IF;
  IF _prior.submitted_at IS NOT NULL THEN
    RAISE EXCEPTION 'a submitted declaration cannot be re-issued' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.declaration_invitations (
    individual_id, assessment_id, token_hash, verification_hash, verification_hash_alt,
    channel, recipient_email, recipient_phone, status, expires_at, created_by
  ) VALUES (
    _prior.individual_id, _prior.assessment_id, btrim(_token_hash),
    _prior.verification_hash, _prior.verification_hash_alt,
    _prior.channel,
    COALESCE(NULLIF(btrim(COALESCE(_recipient_email,'')),''), _prior.recipient_email),
    _prior.recipient_phone, 'SENT', _expires_at, _uid
  ) RETURNING * INTO _row;

  UPDATE public.declaration_invitations SET status = 'EXPIRED' WHERE id = _invitation_id;

  PERFORM public.fp_audit_event(
    'fp.declaration.invitation_reissued','fp_assessment',_prior.assessment_id,
    jsonb_build_object('invitation_id',_invitation_id,'status',_prior.status),
    jsonb_build_object('invitation_id',_row.id,'status','SENT'),
    jsonb_build_object('individual_id',_prior.individual_id,'assessment_id',_prior.assessment_id,
                       'channel',_prior.channel),
    NULL,'NOTIFICATION_SENT'::compliance_audit_action);

  RETURN jsonb_build_object('invitation_id',_row.id);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_determination_record(_assessment_id uuid, _individual_id uuid, _outcome text, _rationale text, _regulator_id uuid DEFAULT NULL::uuid, _effective_from date DEFAULT NULL::date, _effective_to date DEFAULT NULL::date, _is_committee_override boolean DEFAULT false, _override_reason text DEFAULT NULL::text, _conditions jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _assess record; _prior record; _row record;
  _lens uuid; _cond jsonb; _created_conditions int := 0;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_determinations','approve');
  IF _is_committee_override THEN
    PERFORM public.enforce_permission('fit_and_proper','override_committee');
  END IF;

  IF _outcome NOT IN ('approved','conditional','rejected','deferred','withdrawn','fit','not_fit') THEN
    RAISE EXCEPTION 'invalid determination outcome %', _outcome USING ERRCODE='22023';
  END IF;
  IF _rationale IS NULL OR length(btrim(_rationale)) < 10 THEN
    RAISE EXCEPTION 'determination rationale must be at least 10 characters' USING ERRCODE='22023';
  END IF;
  IF _is_committee_override AND (_override_reason IS NULL OR length(btrim(_override_reason)) < 20) THEN
    RAISE EXCEPTION 'committee override reason must be at least 20 characters' USING ERRCODE='22023';
  END IF;

  SELECT * INTO _assess FROM public.fp_assessments WHERE id = _assessment_id FOR UPDATE;
  IF _assess IS NULL THEN RAISE EXCEPTION 'assessment not found' USING ERRCODE='22023'; END IF;
  IF _assess.individual_id <> _individual_id THEN
    RAISE EXCEPTION 'assessment does not belong to this individual' USING ERRCODE='22023';
  END IF;
  IF _assess.status NOT IN ('submitted','screening','awaiting_committee') THEN
    RAISE EXCEPTION 'This assessment is currently "%" — a determination can only be recorded once it reaches Submitted, Screening or Awaiting Committee.',
      _assess.status USING ERRCODE='22023';
  END IF;

  -- Maker-checker: the officer who prepared or submitted the assessment may
  -- never record its determination. Segregation of duties is not waivable by
  -- an ordinary F&P role; only a super admin may act on both sides.
  IF _uid IS NOT NULL
     AND (_uid = _assess.created_by OR _uid = _assess.submitted_by)
     AND NOT public.is_super_admin(_uid) THEN
    RAISE EXCEPTION 'Maker-checker violation: the officer who prepared or submitted this assessment cannot record its determination. A separate decision-maker must decide.'
      USING ERRCODE='42501';
  END IF;

  _lens := COALESCE(_assess.regulator_id, _regulator_id);

  SELECT * INTO _prior FROM public.fp_determinations
   WHERE individual_id = _individual_id AND is_current
     AND _lens IS NOT DISTINCT FROM regulator_id
   FOR UPDATE;

  IF _prior.id IS NOT NULL THEN
    UPDATE public.fp_determinations SET is_current = false WHERE id = _prior.id;
  END IF;

  INSERT INTO public.fp_determinations (
    assessment_id, individual_id, outcome, rationale, determined_by,
    supersedes_id, is_current, effective_from, effective_to, regulator_id,
    is_committee_override, override_reason)
  VALUES (
    _assessment_id, _individual_id, _outcome, btrim(_rationale), _uid,
    _prior.id, true, COALESCE(_effective_from, CURRENT_DATE), _effective_to, _lens,
    COALESCE(_is_committee_override,false),
    CASE WHEN _is_committee_override THEN btrim(_override_reason) ELSE NULL END)
  RETURNING * INTO _row;

  UPDATE public.fp_assessments
     SET status = 'determined', determined_at = now()
   WHERE id = _assessment_id;

  IF _conditions IS NOT NULL AND jsonb_typeof(_conditions) = 'array' THEN
    FOR _cond IN SELECT * FROM jsonb_array_elements(_conditions) LOOP
      IF COALESCE(btrim(_cond->>'description'),'') = '' THEN
        RAISE EXCEPTION 'each condition requires a description' USING ERRCODE='22023';
      END IF;
      INSERT INTO public.fp_conditions (
        determination_id, individual_id, category, description, due_date,
        monitoring_owner, evidence_type, status, created_by)
      VALUES (
        _row.id, _individual_id, COALESCE(NULLIF(btrim(COALESCE(_cond->>'category','')),''),'other'),
        btrim(_cond->>'description'), NULLIF(_cond->>'due_date','')::date,
        NULLIF(_cond->>'monitoring_owner','')::uuid, NULLIF(_cond->>'evidence_type',''),
        'open', _uid);
      _created_conditions := _created_conditions + 1;
    END LOOP;
  END IF;

  IF _prior.id IS NOT NULL THEN
    PERFORM public.fp_audit_event(
      'fp.determination.superseded','fp_determination',_prior.id,
      jsonb_build_object('is_current',true,'outcome',_prior.outcome),
      jsonb_build_object('is_current',false,'superseded_by',_row.id),
      jsonb_build_object('individual_id',_individual_id,'assessment_id',_assessment_id,
                         'regulator_id',_lens));
  END IF;

  PERFORM public.fp_audit_event(
    'fp.determination.' || _outcome,'fp_determination',_row.id, NULL,
    jsonb_build_object('outcome',_outcome,'regulator_id',_lens,'supersedes_id',_prior.id,
                       'is_committee_override',COALESCE(_is_committee_override,false),
                       'conditions_created',_created_conditions),
    jsonb_build_object('individual_id',_individual_id,'assessment_id',_assessment_id,
                       'determination_id',_row.id,'regulator_id',_lens),
    CASE WHEN _is_committee_override THEN btrim(_override_reason) ELSE btrim(_rationale) END,
    CASE WHEN _is_committee_override THEN 'OVERRIDE' ELSE 'APPROVE' END::compliance_audit_action);

  RETURN to_jsonb(_row) || jsonb_build_object('conditions_created',_created_conditions);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_entity_fp_summary(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _out jsonb;
BEGIN
  IF NOT public.can_read_fp_licensee(_uid, _entity_id) THEN
    RAISE EXCEPTION 'not permitted to read fit & proper information for this entity'
      USING ERRCODE='42501';
  END IF;

  SELECT jsonb_build_object(
    'entity_id', _entity_id,
    'counts', jsonb_build_object(
      'current_appointments', (
        SELECT count(*) FROM public.fp_individual_roles r
         WHERE r.licensee_id = _entity_id AND r.is_current),
      'open_assessments', (
        SELECT count(*) FROM public.fp_assessments a
         WHERE a.licensee_id = _entity_id
           AND a.status NOT IN ('determined','closed','withdrawn')),
      'reassessments_due', (
        SELECT count(*) FROM public.fp_individual_roles r
         WHERE r.licensee_id = _entity_id AND r.is_current
           AND r.next_reassessment_due IS NOT NULL
           AND r.next_reassessment_due <= CURRENT_DATE),
      'open_conditions', (
        SELECT count(*) FROM public.fp_conditions c
          JOIN public.fp_determinations d ON d.id = c.determination_id
          JOIN public.fp_assessments a ON a.id = d.assessment_id
         WHERE a.licensee_id = _entity_id AND c.status IN ('open','overdue','breached'))
    ),
    'appointments', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'person_name')
        FROM (
          SELECT jsonb_build_object(
                   'role_id', r.id,
                   'individual_id', r.individual_id,
                   'person_name', i.full_name,
                   'role_type', r.role_type,
                   'is_current', r.is_current,
                   'effective_from', r.effective_from,
                   'reassessment_cycle_months', r.reassessment_cycle_months,
                   'next_reassessment_due', r.next_reassessment_due) AS x
            FROM public.fp_individual_roles r
            JOIN public.fp_individuals i ON i.id = r.individual_id
           WHERE r.licensee_id = _entity_id AND r.is_current
           LIMIT 200
        ) s), '[]'::jsonb),
    'assessments', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'created_at' DESC)
        FROM (
          SELECT jsonb_build_object(
                   'assessment_id', a.id,
                   'reference', 'FP-' || upper(substr(a.id::text,1,8)),
                   'individual_id', a.individual_id,
                   'person_name', i.full_name,
                   'assessment_type', a.assessment_type,
                   'status', a.status,
                   'created_at', a.created_at,
                   'outcome', (SELECT d.outcome FROM public.fp_determinations d
                                WHERE d.assessment_id = a.id
                                ORDER BY d.created_at DESC LIMIT 1)) AS x
            FROM public.fp_assessments a
            JOIN public.fp_individuals i ON i.id = a.individual_id
           WHERE a.licensee_id = _entity_id
           ORDER BY a.created_at DESC
           LIMIT 50
        ) s), '[]'::jsonb)
  ) INTO _out;

  RETURN _out;
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_find_duplicate_candidates(_full_name text, _date_of_birth date DEFAULT NULL::date, _national_id text DEFAULT NULL::text, _limit integer DEFAULT 10)
 RETURNS TABLE(id uuid, full_name text, date_of_birth date, national_id text, status text, name_similarity numeric, dob_match boolean, id_match boolean, match_score numeric, match_reason text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT i.id, i.full_name, i.date_of_birth, i.national_id, i.status,
         round(similarity(lower(coalesce(i.full_name,'')), lower(coalesce(_full_name,'')))::numeric, 3) AS name_similarity,
         (_date_of_birth IS NOT NULL AND i.date_of_birth = _date_of_birth) AS dob_match,
         (_national_id IS NOT NULL AND nullif(trim(_national_id),'') IS NOT NULL
            AND lower(trim(i.national_id)) = lower(trim(_national_id))) AS id_match,
         round((
           0.6 * similarity(lower(coalesce(i.full_name,'')), lower(coalesce(_full_name,'')))::numeric
           + CASE WHEN _date_of_birth IS NOT NULL AND i.date_of_birth = _date_of_birth THEN 0.25 ELSE 0 END
           + CASE WHEN _national_id IS NOT NULL AND nullif(trim(_national_id),'') IS NOT NULL
                    AND lower(trim(i.national_id)) = lower(trim(_national_id)) THEN 0.15 ELSE 0 END
         )::numeric, 3) AS match_score,
         concat_ws(' + ',
           CASE WHEN similarity(lower(coalesce(i.full_name,'')), lower(coalesce(_full_name,''))) >= 0.35
                THEN 'similar name' END,
           CASE WHEN _date_of_birth IS NOT NULL AND i.date_of_birth = _date_of_birth THEN 'same date of birth' END,
           CASE WHEN _national_id IS NOT NULL AND nullif(trim(_national_id),'') IS NOT NULL
                     AND lower(trim(i.national_id)) = lower(trim(_national_id)) THEN 'same identifier' END
         ) AS match_reason
  FROM public.fp_individuals i
  WHERE public.fp_regulator_visible(i.regulator_id)
    AND (
      similarity(lower(coalesce(i.full_name,'')), lower(coalesce(_full_name,''))) >= 0.35
      OR (_date_of_birth IS NOT NULL AND i.date_of_birth = _date_of_birth)
      OR (_national_id IS NOT NULL AND nullif(trim(_national_id),'') IS NOT NULL
          AND lower(trim(i.national_id)) = lower(trim(_national_id)))
    )
  ORDER BY match_score DESC, i.full_name
  LIMIT greatest(coalesce(_limit,10), 1);
$function$
;
CREATE OR REPLACE FUNCTION public.fp_finding_apply_confidence_bands()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.resolution_status = 'pending' AND NEW.confidence_score IS NOT NULL THEN
    IF NEW.confidence_score < 30 THEN
      NEW.resolution_status := 'false_positive_draft';
    ELSIF NEW.confidence_score >= 80 THEN
      NEW.resolution_status := 'true_positive_draft';
    ELSE
      NEW.resolution_status := 'needs_review';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_finding_assign(_finding_id uuid, _assignee uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_screening','edit');
  SELECT * INTO _prev FROM public.fp_findings WHERE id = _finding_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'finding not found' USING ERRCODE='22023'; END IF;
  IF _prev.resolved_at IS NOT NULL THEN
    RAISE EXCEPTION 'a resolved finding cannot be reassigned' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _assignee) THEN
    RAISE EXCEPTION 'assignee not found' USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_findings
     SET assigned_to = _assignee, resolution_status = 'under_review',
         reviewed_by = _uid, reviewed_at = now()
   WHERE id = _finding_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.finding.assigned','fp_finding',_finding_id,
    jsonb_build_object('assigned_to',_prev.assigned_to,'resolution_status',_prev.resolution_status),
    jsonb_build_object('assigned_to',_assignee,'resolution_status','under_review'),
    jsonb_build_object('individual_id',_prev.individual_id,'assessment_id',_prev.assessment_id,
                       'finding_id',_finding_id),
    NULL,'UPDATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_finding_disposition(_finding_id uuid, _resolution_status text, _reason text, _raw_payload jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record; _false boolean; _resolves boolean;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_screening','record_adverse_findings');
  IF _resolution_status NOT IN ('true_positive','false_positive','confirmed','cleared','dismissed','needs_review') THEN
    RAISE EXCEPTION 'invalid finding disposition %', _resolution_status USING ERRCODE='22023';
  END IF;
  IF _reason IS NULL OR length(btrim(_reason)) < 10 THEN
    RAISE EXCEPTION 'Reason must be at least 10 characters.' USING ERRCODE='22023';
  END IF;
  SELECT * INTO _prev FROM public.fp_findings WHERE id = _finding_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'finding not found' USING ERRCODE='22023'; END IF;
  IF _prev.resolved_at IS NOT NULL AND _prev.resolution_status = _resolution_status THEN
    RAISE EXCEPTION 'finding is already dispositioned as %', _prev.resolution_status USING ERRCODE='22023';
  END IF;

  _resolves := _resolution_status <> 'needs_review';
  _false := _resolution_status IN ('false_positive','cleared');

  UPDATE public.fp_findings
     SET resolution_status = _resolution_status,
         resolution_reason = btrim(_reason),
         is_false_positive = CASE WHEN _resolves THEN _false ELSE is_false_positive END,
         review_note = btrim(_reason),
         reviewed_by = _uid, reviewed_at = now(),
         resolved_by = CASE WHEN _resolves THEN _uid ELSE NULL END,
         resolved_at = CASE WHEN _resolves THEN now() ELSE NULL END,
         raw_payload = COALESCE(_raw_payload, raw_payload)
   WHERE id = _finding_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    CASE WHEN _resolves THEN 'fp.finding.resolved' ELSE 'fp.finding.sent_for_review' END,
    'fp_finding',_finding_id,
    jsonb_build_object('resolution_status',_prev.resolution_status,
                       'is_false_positive',_prev.is_false_positive),
    jsonb_build_object('resolution_status',_resolution_status,'is_false_positive',_row.is_false_positive),
    jsonb_build_object('individual_id',_prev.individual_id,'assessment_id',_prev.assessment_id,
                       'finding_id',_finding_id,'severity',_prev.severity),
    btrim(_reason),
    CASE WHEN _false THEN 'OVERRIDE' WHEN _resolves THEN 'APPROVE' ELSE 'WORKFLOW_TRANSITION' END::compliance_audit_action);
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_finding_escalate(_finding_id uuid, _note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_screening','record_adverse_findings');
  IF _note IS NULL OR length(btrim(_note)) < 10 THEN
    RAISE EXCEPTION 'escalation note must be at least 10 characters' USING ERRCODE='22023';
  END IF;
  SELECT * INTO _prev FROM public.fp_findings WHERE id = _finding_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'finding not found' USING ERRCODE='22023'; END IF;
  IF _prev.resolved_at IS NOT NULL THEN
    RAISE EXCEPTION 'a resolved finding cannot be escalated' USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_findings
     SET review_note = 'ESCALATED: ' || btrim(_note),
         reviewed_by = _uid, reviewed_at = now(),
         resolution_status = 'needs_review',
         severity_basis = COALESCE(severity_basis,'{}'::jsonb) || jsonb_build_object(
           'escalated', true, 'escalated_at', now(), 'escalated_by', _uid, 'note', btrim(_note))
   WHERE id = _finding_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.finding.escalated','fp_finding',_finding_id,
    jsonb_build_object('resolution_status',_prev.resolution_status),
    jsonb_build_object('resolution_status','needs_review','escalated',true),
    jsonb_build_object('individual_id',_prev.individual_id,'assessment_id',_prev.assessment_id,
                       'finding_id',_finding_id,'severity',_prev.severity),
    btrim(_note));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_finding_save_note(_finding_id uuid, _note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_screening','edit');
  SELECT * INTO _prev FROM public.fp_findings WHERE id = _finding_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'finding not found' USING ERRCODE='22023'; END IF;
  IF _prev.resolved_at IS NOT NULL THEN
    RAISE EXCEPTION 'a resolved finding can no longer be annotated' USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_findings
     SET review_note = NULLIF(btrim(COALESCE(_note,'')),''),
         reviewed_by = _uid, reviewed_at = now()
   WHERE id = _finding_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.finding.note_saved','fp_finding',_finding_id, NULL, NULL,
    jsonb_build_object('individual_id',_prev.individual_id,'assessment_id',_prev.assessment_id,
                       'finding_id',_finding_id),
    NULL,'UPDATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_finding_set_evidence(_finding_id uuid, _evidence_urls jsonb DEFAULT NULL::jsonb, _clear_legacy boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','upload_documents');
  SELECT * INTO _prev FROM public.fp_findings WHERE id = _finding_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'finding not found' USING ERRCODE='22023'; END IF;
  IF _prev.resolved_at IS NOT NULL THEN
    RAISE EXCEPTION 'evidence on a resolved finding is immutable' USING ERRCODE='22023';
  END IF;
  IF _evidence_urls IS NOT NULL AND jsonb_typeof(_evidence_urls) <> 'array' THEN
    RAISE EXCEPTION 'evidence_urls must be a JSON array' USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_findings
     SET evidence_urls = COALESCE(_evidence_urls, evidence_urls),
         evidence_url  = CASE WHEN _clear_legacy THEN NULL ELSE evidence_url END
   WHERE id = _finding_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.finding.evidence_updated','fp_finding',_finding_id,
    jsonb_build_object('evidence_count',jsonb_array_length(COALESCE(_prev.evidence_urls,'[]'::jsonb))),
    jsonb_build_object('evidence_count',jsonb_array_length(COALESCE(_row.evidence_urls,'[]'::jsonb))),
    jsonb_build_object('individual_id',_prev.individual_id,'assessment_id',_prev.assessment_id,
                       'finding_id',_finding_id),
    NULL,'UPDATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_finding_set_false_positive(_finding_id uuid, _is_false_positive boolean, _justification text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_screening','record_adverse_findings');
  SELECT * INTO _prev FROM public.fp_findings WHERE id = _finding_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'finding not found' USING ERRCODE='22023'; END IF;
  IF _prev.resolved_at IS NOT NULL THEN
    RAISE EXCEPTION 'this finding is already resolved — reopen it before changing the false-positive flag'
      USING ERRCODE='22023';
  END IF;
  IF _is_false_positive AND (_justification IS NULL OR length(btrim(_justification)) < 10) THEN
    RAISE EXCEPTION 'a false-positive override requires a written justification (min 10 characters)'
      USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_findings
     SET is_false_positive = _is_false_positive,
         reviewed_by = _uid, reviewed_at = now()
   WHERE id = _finding_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    CASE WHEN _is_false_positive THEN 'fp.finding.false_positive' ELSE 'fp.finding.restored' END,
    'fp_finding',_finding_id,
    jsonb_build_object('is_false_positive',_prev.is_false_positive),
    jsonb_build_object('is_false_positive',_is_false_positive),
    jsonb_build_object('individual_id',_prev.individual_id,'assessment_id',_prev.assessment_id,
                       'finding_id',_finding_id,'severity',_prev.severity),
    NULLIF(btrim(COALESCE(_justification,'')),''),
    CASE WHEN _is_false_positive THEN 'OVERRIDE' ELSE 'UPDATE' END::compliance_audit_action);
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_individual_create(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _row record;
  _name text := btrim(COALESCE(_payload->>'full_name',''));
  _nid  text := NULLIF(btrim(COALESCE(_payload->>'national_id','')),'');
  _mail text := NULLIF(btrim(COALESCE(_payload->>'email','')),'');
  _dup  record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','create');

  IF _name = '' THEN
    RAISE EXCEPTION 'full name is required' USING ERRCODE='22023';
  END IF;

  SELECT id, full_name, national_id, email INTO _dup
    FROM public.fp_individuals
   WHERE (_nid IS NOT NULL AND national_id = _nid)
      OR (_mail IS NOT NULL AND email = _mail)
   LIMIT 1;
  IF _dup.id IS NOT NULL THEN
    RAISE EXCEPTION 'duplicate subject: "%" is already registered (%)',
      _dup.full_name, COALESCE(_dup.national_id, _dup.email)
      USING ERRCODE='23505';
  END IF;

  INSERT INTO public.fp_individuals (
    full_name, national_id, passport_number, nationality, date_of_birth,
    email, phone, address, notes, status, created_by)
  VALUES (
    _name, _nid,
    NULLIF(btrim(COALESCE(_payload->>'passport_number','')),''),
    NULLIF(btrim(COALESCE(_payload->>'nationality','')),''),
    NULLIF(_payload->>'date_of_birth','')::date,
    _mail,
    NULLIF(btrim(COALESCE(_payload->>'phone','')),''),
    NULLIF(btrim(COALESCE(_payload->>'address','')),''),
    NULLIF(btrim(COALESCE(_payload->>'notes','')),''),
    'active', _uid)
  RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.individual.created','fp_individual',_row.id, NULL,
    jsonb_build_object('full_name',_name,'national_id',_nid,'email',_mail),
    jsonb_build_object('individual_id',_row.id), NULL, 'CREATE');

  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_individual_set_directory_status(_individual_id uuid, _status text, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _before text; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','edit');

  IF _status NOT IN ('active','inactive') THEN
    RAISE EXCEPTION 'subject register status may only be active or inactive — suspension and prohibition are determination outcomes'
      USING ERRCODE='22023';
  END IF;
  IF COALESCE(btrim(_reason),'') = '' THEN
    RAISE EXCEPTION 'a reason is required' USING ERRCODE='22023';
  END IF;

  SELECT status INTO _before FROM public.fp_individuals WHERE id = _individual_id;
  IF _before IS NULL THEN
    RAISE EXCEPTION 'individual not found' USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_individuals SET status = _status, updated_at = now()
   WHERE id = _individual_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.individual.status.changed','fp_individual',_individual_id,
    jsonb_build_object('status',_before), jsonb_build_object('status',_status),
    jsonb_build_object('individual_id',_individual_id), _reason, 'UPDATE');

  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_individual_update(_individual_id uuid, _patch jsonb, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _before record; _row record; _k text;
  _allowed text[] := ARRAY['full_name','national_id','passport_number','nationality',
                           'date_of_birth','email','phone','address','notes'];
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','edit');

  SELECT * INTO _before FROM public.fp_individuals WHERE id = _individual_id;
  IF _before.id IS NULL THEN
    RAISE EXCEPTION 'individual not found' USING ERRCODE='22023';
  END IF;

  FOR _k IN SELECT jsonb_object_keys(COALESCE(_patch,'{}'::jsonb)) LOOP
    IF NOT (_k = ANY(_allowed)) THEN
      RAISE EXCEPTION 'field "%" is not editable master data', _k USING ERRCODE='22023';
    END IF;
  END LOOP;

  IF _patch ? 'full_name' AND btrim(COALESCE(_patch->>'full_name','')) = '' THEN
    RAISE EXCEPTION 'full name is required' USING ERRCODE='22023';
  END IF;

  IF _patch ? 'national_id' AND NULLIF(btrim(_patch->>'national_id'),'') IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.fp_individuals
                  WHERE national_id = btrim(_patch->>'national_id') AND id <> _individual_id) THEN
    RAISE EXCEPTION 'another subject already holds that national id' USING ERRCODE='23505';
  END IF;

  UPDATE public.fp_individuals SET
    full_name       = CASE WHEN _patch ? 'full_name' THEN btrim(_patch->>'full_name') ELSE full_name END,
    national_id     = CASE WHEN _patch ? 'national_id' THEN NULLIF(btrim(_patch->>'national_id'),'') ELSE national_id END,
    passport_number = CASE WHEN _patch ? 'passport_number' THEN NULLIF(btrim(_patch->>'passport_number'),'') ELSE passport_number END,
    nationality     = CASE WHEN _patch ? 'nationality' THEN NULLIF(btrim(_patch->>'nationality'),'') ELSE nationality END,
    date_of_birth   = CASE WHEN _patch ? 'date_of_birth' THEN NULLIF(_patch->>'date_of_birth','')::date ELSE date_of_birth END,
    email           = CASE WHEN _patch ? 'email' THEN NULLIF(btrim(_patch->>'email'),'') ELSE email END,
    phone           = CASE WHEN _patch ? 'phone' THEN NULLIF(btrim(_patch->>'phone'),'') ELSE phone END,
    address         = CASE WHEN _patch ? 'address' THEN NULLIF(btrim(_patch->>'address'),'') ELSE address END,
    notes           = CASE WHEN _patch ? 'notes' THEN NULLIF(btrim(_patch->>'notes'),'') ELSE notes END,
    updated_at      = now()
  WHERE id = _individual_id
  RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.individual.master_data.updated','fp_individual',_individual_id,
    to_jsonb(_before) - 'notes', _patch,
    jsonb_build_object('individual_id',_individual_id), _reason, 'UPDATE');

  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_link_persons_deterministic()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_i record; v_party uuid; v_linked int := 0; v_ambiguous int := 0; v_method text;
BEGIN
  PERFORM public.wb_require('fit_and_proper','edit');
  FOR v_i IN SELECT * FROM public.fp_individuals f
              WHERE NOT EXISTS (SELECT 1 FROM public.fp_individual_party_links l WHERE l.fp_individual_id = f.id)
  LOOP
    v_party := NULL; v_method := NULL;
    -- only exact identity-document / user-account matches are deterministic
    IF COALESCE(v_i.national_id,'') <> '' THEN
      SELECT p.id INTO v_party FROM public.parties p JOIN public.persons pe ON pe.party_id = p.id
        JOIN public.entity_identifiers ei ON ei.party_id = p.id
       WHERE ei.normalized_value = upper(regexp_replace(v_i.national_id,'[^A-Za-z0-9]','','g')) LIMIT 1;
      IF v_party IS NOT NULL THEN v_method := 'NATIONAL_ID'; END IF;
    END IF;
    IF v_party IS NULL THEN
      -- unresolved people are reported, never guessed
      v_ambiguous := v_ambiguous + 1;
      CONTINUE;
    END IF;
    INSERT INTO public.fp_individual_party_links (fp_individual_id, person_party_id, match_method, linked_by)
    VALUES (v_i.id, v_party, v_method, auth.uid())
    ON CONFLICT (fp_individual_id) DO NOTHING;
    v_linked := v_linked + 1;
  END LOOP;
  RETURN jsonb_build_object('linked',v_linked,'unresolved',v_ambiguous);
END $function$
;
CREATE OR REPLACE FUNCTION public.fp_monitoring_event_acknowledge(_event_id uuid, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_monitoring','edit');
  SELECT * INTO _prev FROM public.fp_monitoring_events WHERE id = _event_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'monitoring event not found' USING ERRCODE='22023'; END IF;
  IF _prev.acknowledged_at IS NOT NULL THEN
    RAISE EXCEPTION 'event has already been acknowledged' USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_monitoring_events
     SET acknowledged_at = now(), acknowledged_by = _uid,
         acknowledgement_note = NULLIF(btrim(COALESCE(_note,'')),'')
   WHERE id = _event_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.monitoring.event_acknowledged','fp_monitoring_event',_event_id,
    jsonb_build_object('acknowledged',false), jsonb_build_object('acknowledged',true),
    jsonb_build_object('individual_id',_prev.individual_id),
    NULLIF(btrim(COALESCE(_note,'')),''),'UPDATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_monitoring_event_raise(_individual_id uuid, _event_type text, _summary text, _severity text DEFAULT 'low'::text, _determination_id uuid DEFAULT NULL::uuid, _detail jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row record;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper_monitoring','create');
  IF COALESCE(btrim(_event_type),'') = '' OR COALESCE(btrim(_summary),'') = '' THEN
    RAISE EXCEPTION 'event type and summary are required' USING ERRCODE='22023';
  END IF;
  IF _severity NOT IN ('low','medium','high','critical') THEN
    RAISE EXCEPTION 'invalid severity %', _severity USING ERRCODE='22023';
  END IF;

  INSERT INTO public.fp_monitoring_events (
    individual_id, determination_id, event_type, severity, summary, detail)
  VALUES (_individual_id, _determination_id, btrim(_event_type), _severity, btrim(_summary), _detail)
  RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.monitoring.event_raised','fp_monitoring_event',_row.id, NULL,
    jsonb_build_object('event_type',_row.event_type,'severity',_severity),
    jsonb_build_object('individual_id',_individual_id,'determination_id',_determination_id),
    NULL,'CREATE');
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_normalise_provider_state(_outcome text, _environment text DEFAULT NULL::text, _execution_mode text DEFAULT NULL::text, _error_category text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    -- already canonical
    WHEN upper(coalesce(_outcome,'')) IN (
      'SUCCESS_HIT','SUCCESS_NO_MATCH','NOT_CONFIGURED','SANDBOX',
      'PROVIDER_FAILURE','TRANSPORT_FAILURE','RATE_LIMITED','MANUAL')
      THEN upper(_outcome)
    -- explicit non-completion beats everything else
    WHEN lower(coalesce(_outcome,'')) IN ('not_configured','unconfigured')
      OR lower(coalesce(_error_category,'')) = 'not_configured'
      THEN 'NOT_CONFIGURED'
    WHEN lower(coalesce(_error_category,'')) IN ('rate_limited','throttled')
      THEN 'RATE_LIMITED'
    WHEN lower(coalesce(_error_category,'')) IN ('timeout','network','network_error','transport','transport_error','connection')
      THEN 'TRANSPORT_FAILURE'
    WHEN lower(coalesce(_outcome,'')) IN ('failed','failure','error','provider_error')
      THEN 'PROVIDER_FAILURE'
    WHEN lower(coalesce(_outcome,'')) = 'manual'
      THEN 'MANUAL'
    -- a simulated execution is NEVER a conclusive result
    WHEN lower(coalesce(_execution_mode,'')) IN ('mock','simulated','sandbox')
      OR lower(coalesce(_environment,'')) IN ('sandbox','test','staging')
      THEN 'SANDBOX'
    WHEN lower(coalesce(_outcome,'')) IN ('screened_hits','hit','hits','match','success_match')
      THEN 'SUCCESS_HIT'
    WHEN lower(coalesce(_outcome,'')) IN ('screened_clean','clean','no_match','no_hit')
      THEN 'SUCCESS_NO_MATCH'
    ELSE 'PROVIDER_FAILURE'
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_pin_pq_form_on_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tpl uuid;
  v_ver uuid;
BEGIN
  IF NEW.form_version_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT ft.id, fv.id
    INTO v_tpl, v_ver
    FROM public.form_templates ft
    JOIN public.form_versions  fv ON fv.template_id = ft.id
   WHERE ft.form_type = 'fit_and_proper'
     AND ft.service   = 'pq'
     AND ft.status = 'published'
     AND fv.status = 'published'
   ORDER BY fv.version DESC, fv.published_at DESC NULLS LAST
   LIMIT 1;

  IF v_tpl IS NOT NULL THEN
    NEW.form_template_id := v_tpl;
    NEW.form_version_id  := v_ver;
  END IF;

  RETURN NEW;
END
$function$
;
CREATE OR REPLACE FUNCTION public.fp_pq_state_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.pq_state NOT IN ('draft','incomplete','ready_to_submit','submitted','amendment_required') THEN
    RAISE EXCEPTION 'Invalid pq_state %', NEW.pq_state USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.pq_state = 'amendment_required'
     AND (NEW.pq_amendment_reason IS NULL OR length(trim(NEW.pq_amendment_reason)) < 5) THEN
    RAISE EXCEPTION 'Amendment reason (min 5 chars) required' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.pq_state IS DISTINCT FROM OLD.pq_state THEN
    NEW.pq_state_changed_at := now();
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_pq_state_on_declaration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.declaration_data IS NOT NULL
     AND NEW.declaration_data ? 'submitted_at'
     AND (
       TG_OP = 'INSERT'
       OR coalesce(OLD.declaration_data->>'submitted_at','') IS DISTINCT FROM (NEW.declaration_data->>'submitted_at')
     )
     AND coalesce(NEW.pq_state,'draft') <> 'submitted' THEN
    NEW.pq_state := 'submitted';
    NEW.pq_amendment_reason := NULL;
    NEW.pq_state_changed_at := now();
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_provider_state_conclusive(_state text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT upper(coalesce(_state,'')) IN ('SUCCESS_HIT','SUCCESS_NO_MATCH','MANUAL');
$function$
;
CREATE OR REPLACE FUNCTION public.fp_record_committee_decision(_assessment_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_committee public.fp_committees;
  v_assessment public.fp_assessments;
  v_roster jsonb;
  v_tally jsonb;
  v_approve numeric := 0;
  v_reject numeric := 0;
  v_abstain numeric := 0;
  v_conditional numeric := 0;
  v_votes integer := 0;
  v_entitled integer := 0;
  v_total numeric := 0;
  v_pct numeric := 0;
  v_quorum_met boolean;
  v_outcome text;
  v_id uuid;
BEGIN
  IF NOT (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(), 'fit_and_proper', 'edit')) THEN
    RAISE EXCEPTION 'Not authorized to record a committee decision' USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_assessment FROM public.fp_assessments WHERE id = _assessment_id;
  IF v_assessment.id IS NULL THEN
    RAISE EXCEPTION 'Assessment % not found', _assessment_id USING ERRCODE = 'no_data_found';
  END IF;
  IF v_assessment.committee_id IS NULL THEN
    RAISE EXCEPTION 'Assessment % has no committee assigned', _assessment_id USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM public.fp_committee_decision_snapshots WHERE assessment_id = _assessment_id) THEN
    RAISE EXCEPTION 'Committee decision already snapshotted for assessment %', _assessment_id
      USING ERRCODE = 'unique_violation';
  END IF;

  SELECT * INTO v_committee FROM public.fp_committees WHERE id = v_assessment.committee_id;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'member_id', m.id, 'user_id', m.user_id, 'member_role', m.member_role,
           'vote_weight', m.vote_weight, 'is_active', m.is_active,
           'vote', v.vote, 'justification', v.justification, 'voted_at', v.voted_at
         ) ORDER BY m.added_at), '[]'::jsonb)
    INTO v_roster
  FROM public.fp_committee_members m
  LEFT JOIN public.fp_committee_votes v
    ON v.member_id = m.id AND v.assessment_id = _assessment_id
  WHERE m.committee_id = v_committee.id AND m.is_active;

  SELECT count(*)::int INTO v_entitled
  FROM public.fp_committee_members m
  WHERE m.committee_id = v_committee.id AND m.is_active;

  -- Only votes cast by entitled (active) members of this committee count.
  SELECT count(*)::int,
         coalesce(sum(CASE WHEN v.vote = 'approve' THEN coalesce(v.weight,1) ELSE 0 END),0),
         coalesce(sum(CASE WHEN v.vote = 'reject' THEN coalesce(v.weight,1) ELSE 0 END),0),
         coalesce(sum(CASE WHEN v.vote = 'abstain' THEN coalesce(v.weight,1) ELSE 0 END),0),
         coalesce(sum(CASE WHEN v.vote = 'conditional' THEN coalesce(v.weight,1) ELSE 0 END),0)
    INTO v_votes, v_approve, v_reject, v_abstain, v_conditional
  FROM public.fp_committee_votes v
  JOIN public.fp_committee_members m
    ON m.id = v.member_id AND m.committee_id = v_committee.id AND m.is_active
  WHERE v.assessment_id = _assessment_id;

  -- Abstentions are recorded but excluded from the approval denominator.
  v_total := v_approve + v_reject + v_conditional;
  v_pct := CASE WHEN v_total > 0 THEN round((v_approve / v_total) * 100, 2) ELSE 0 END;
  v_quorum_met := v_votes >= coalesce(v_committee.quorum, 1);

  IF NOT v_quorum_met THEN
    v_outcome := 'insufficient_quorum';
  ELSIF v_total = 0 THEN
    -- quorum reached but every vote was an abstention: no decision can be taken
    v_outcome := 'insufficient_quorum';
    v_quorum_met := false;
  ELSIF v_pct >= coalesce(v_committee.approval_threshold_pct, 50) THEN
    v_outcome := CASE WHEN v_conditional > 0 THEN 'approved_with_conditions' ELSE 'approved' END;
  ELSE
    v_outcome := 'rejected';
  END IF;

  v_tally := jsonb_build_object(
    'votes', v_votes,
    'entitled_members', v_entitled,
    'total_weight', v_total,
    'approve_weight', v_approve,
    'reject_weight', v_reject,
    'abstain_weight', v_abstain,
    'conditional_weight', v_conditional,
    'approval_pct', v_pct
  );

  INSERT INTO public.fp_committee_decision_snapshots (
    assessment_id, committee_id, regulator_id, quorum, approval_threshold_pct,
    member_roster, tally, outcome, quorum_met, taken_by
  ) VALUES (
    _assessment_id, v_committee.id, coalesce(v_assessment.regulator_id, v_committee.regulator_id),
    coalesce(v_committee.quorum, 1), coalesce(v_committee.approval_threshold_pct, 50),
    v_roster, v_tally, v_outcome, v_quorum_met, auth.uid()
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_regulator_positions(_individual_id uuid)
 RETURNS TABLE(regulator_id uuid, regulator_name text, determination_id uuid, outcome text, rationale text, determined_by uuid, determined_at timestamp with time zone, effective_from date, condition_count integer, coordination_state text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_distinct integer;
  v_regulators integer;
  v_pending boolean;
  v_state text;
BEGIN
  CREATE TEMP TABLE _fp_pos ON COMMIT DROP AS
  SELECT d.regulator_id, d.id AS determination_id, d.outcome, d.rationale,
         d.determined_by, d.determined_at, d.effective_from
  FROM public.fp_determinations d
  WHERE d.individual_id = _individual_id AND d.is_current;

  SELECT count(DISTINCT p.outcome), count(DISTINCT p.regulator_id) INTO v_distinct, v_regulators FROM _fp_pos p;

  SELECT EXISTS (
    SELECT 1 FROM public.coordination_cases c
    WHERE c.subject_type = 'fp_individual' AND c.subject_id = _individual_id
      AND c.status <> 'closed'
  ) INTO v_pending;

  IF v_regulators <= 1 THEN
    v_state := 'SINGLE_REGULATOR';
  ELSIF v_distinct > 1 THEN
    v_state := CASE WHEN v_pending THEN 'COORDINATION_PENDING' ELSE 'DISAGREEMENT' END;
  ELSE
    v_state := 'ALIGNED';
  END IF;

  RETURN QUERY
  SELECT p.regulator_id,
         r.name::text,
         p.determination_id, p.outcome, p.rationale, p.determined_by,
         p.determined_at, p.effective_from,
         (SELECT count(*)::int FROM public.fp_conditions fc WHERE fc.determination_id = p.determination_id),
         v_state
  FROM _fp_pos p
  LEFT JOIN public.regulators r ON r.id = p.regulator_id
  WHERE public.fp_regulator_visible(p.regulator_id)
     OR public.has_permission(auth.uid(), 'fit_and_proper', 'view')
  ORDER BY p.determined_at DESC NULLS LAST;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_regulator_visible(_row_regulator_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.has_role(auth.uid(), 'super_admin'::app_role)
    OR public.fp_user_regulator_id(auth.uid()) IS NULL
    OR _row_regulator_id IS NULL
    OR _row_regulator_id = public.fp_user_regulator_id(auth.uid());
$function$
;
CREATE OR REPLACE FUNCTION public.fp_request_pq_amendment(_assessment_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev text;
BEGIN
  IF NOT (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(), 'fit_and_proper', 'edit')) THEN
    RAISE EXCEPTION 'Not authorized to request a PQ amendment'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF _reason IS NULL OR length(trim(_reason)) < 10 THEN
    RAISE EXCEPTION 'Amendment reason (min 10 chars) is required'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT pq_state INTO v_prev FROM public.fp_assessments WHERE id = _assessment_id;
  IF v_prev IS NULL THEN
    RAISE EXCEPTION 'Assessment % not found', _assessment_id USING ERRCODE = 'no_data_found';
  END IF;

  -- Prior submitted response and its pinned form version are deliberately
  -- left untouched: an amendment request never destroys the original answers.
  UPDATE public.fp_assessments
  SET pq_state = 'amendment_required',
      pq_amendment_reason = trim(_reason),
      pq_state_changed_at = now(),
      updated_at = now()
  WHERE id = _assessment_id;

  INSERT INTO public.compliance_audit_logs (
    user_id, action, entity_type, entity_id, details
  ) VALUES (
    auth.uid(), 'UPDATE', 'fp_assessment', _assessment_id,
    jsonb_build_object('event','fp.pq.amendment_requested',
                       'from_state', v_prev,
                       'to_state','amendment_required',
                       'reason', trim(_reason))
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_role_create(_individual_id uuid, _role_type text, _licensee_id uuid DEFAULT NULL::uuid, _is_current boolean DEFAULT true, _reassessment_cycle_months integer DEFAULT NULL::integer, _effective_from date DEFAULT NULL::date, _role_title text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _row record; _next date;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','create');

  IF COALESCE(btrim(_role_type),'') = '' THEN
    RAISE EXCEPTION 'role type is required' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fp_individuals WHERE id = _individual_id) THEN
    RAISE EXCEPTION 'individual not found' USING ERRCODE='22023';
  END IF;
  IF _licensee_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.licensees WHERE id = _licensee_id) THEN
    RAISE EXCEPTION 'entity not found' USING ERRCODE='22023';
  END IF;
  IF _reassessment_cycle_months IS NOT NULL
     AND (_reassessment_cycle_months <= 0 OR _reassessment_cycle_months > 120) THEN
    RAISE EXCEPTION 'reassessment cycle must be 1-120 months' USING ERRCODE='22023';
  END IF;
  IF COALESCE(_is_current,true)
     AND EXISTS (SELECT 1 FROM public.fp_individual_roles
                  WHERE individual_id = _individual_id
                    AND role_type = btrim(_role_type)
                    AND COALESCE(licensee_id::text,'-') = COALESCE(_licensee_id::text,'-')
                    AND is_current) THEN
    RAISE EXCEPTION 'this subject already holds a current % appointment at that entity', btrim(_role_type)
      USING ERRCODE='23505';
  END IF;

  _next := CASE WHEN _reassessment_cycle_months IS NULL THEN NULL
                ELSE (CURRENT_DATE + (_reassessment_cycle_months || ' months')::interval)::date END;

  INSERT INTO public.fp_individual_roles (
    individual_id, role_type, role_title, licensee_id, is_current,
    effective_from, reassessment_cycle_months, next_reassessment_due, created_by)
  VALUES (
    _individual_id, btrim(_role_type), NULLIF(btrim(COALESCE(_role_title,'')),''),
    _licensee_id, COALESCE(_is_current,true),
    COALESCE(_effective_from, CURRENT_DATE), _reassessment_cycle_months, _next, _uid)
  RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.role.created','fp_individual_role',_row.id, NULL, to_jsonb(_row),
    jsonb_build_object('individual_id',_individual_id,'role_id',_row.id), NULL, 'CREATE');

  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_role_end(_role_id uuid, _reason text, _effective_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _before record; _row record; _open int;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','edit');

  IF COALESCE(btrim(_reason),'') = '' THEN
    RAISE EXCEPTION 'a reason is required to cease an appointment' USING ERRCODE='22023';
  END IF;

  SELECT * INTO _before FROM public.fp_individual_roles WHERE id = _role_id;
  IF _before.id IS NULL THEN
    RAISE EXCEPTION 'role not found' USING ERRCODE='22023';
  END IF;
  IF NOT _before.is_current THEN
    RAISE EXCEPTION 'appointment is already ceased' USING ERRCODE='22023';
  END IF;

  SELECT count(*) INTO _open FROM public.fp_assessments
   WHERE role_id = _role_id AND status NOT IN ('determined','closed','withdrawn');
  IF _open > 0 THEN
    RAISE EXCEPTION 'cannot cease this appointment while % assessment(s) against it are still open', _open
      USING ERRCODE='22023';
  END IF;

  UPDATE public.fp_individual_roles
     SET is_current = false,
         effective_to = COALESCE(_effective_to, CURRENT_DATE),
         reassessment_cycle_months = NULL,
         next_reassessment_due = NULL,
         updated_at = now()
   WHERE id = _role_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.role.ceased','fp_individual_role',_role_id, to_jsonb(_before), to_jsonb(_row),
    jsonb_build_object('individual_id',_before.individual_id,'role_id',_role_id), _reason, 'UPDATE');

  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_role_set_reassessment_cycle(_role_id uuid, _months integer, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _before record; _row record; _next date;
BEGIN
  PERFORM public.enforce_permission('fit_and_proper','edit');

  SELECT * INTO _before FROM public.fp_individual_roles WHERE id = _role_id;
  IF _before.id IS NULL THEN
    RAISE EXCEPTION 'role not found' USING ERRCODE='22023';
  END IF;
  IF NOT _before.is_current THEN
    RAISE EXCEPTION 'a ceased appointment cannot carry a reassessment cycle' USING ERRCODE='22023';
  END IF;
  IF _months IS NOT NULL AND (_months <= 0 OR _months > 120) THEN
    RAISE EXCEPTION 'reassessment cycle must be 1-120 months' USING ERRCODE='22023';
  END IF;

  _next := CASE WHEN _months IS NULL THEN NULL
                ELSE (COALESCE(_before.last_reassessment_at::date, CURRENT_DATE)
                      + (_months || ' months')::interval)::date END;

  UPDATE public.fp_individual_roles
     SET reassessment_cycle_months = _months,
         next_reassessment_due = _next,
         updated_at = now()
   WHERE id = _role_id RETURNING * INTO _row;

  PERFORM public.fp_audit_event(
    'fp.role.reassessment_cycle.set','fp_individual_role',_role_id,
    jsonb_build_object('reassessment_cycle_months',_before.reassessment_cycle_months,
                       'next_reassessment_due',_before.next_reassessment_due),
    jsonb_build_object('reassessment_cycle_months',_months,'next_reassessment_due',_next),
    jsonb_build_object('individual_id',_before.individual_id,'role_id',_role_id), _reason, 'UPDATE');

  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.fp_run_is_conclusive(_run_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN NOT EXISTS (
      SELECT 1 FROM public.fp_screening_runs r
      WHERE r.id = _run_id AND jsonb_array_length(coalesce(r.provider_outcomes,'[]'::jsonb)) > 0
    ) THEN false
    ELSE NOT EXISTS (
      SELECT 1
      FROM public.fp_screening_runs r,
           jsonb_array_elements(r.provider_outcomes) e
      WHERE r.id = _run_id
        AND NOT public.fp_provider_state_conclusive(e->>'state')
    )
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.fp_screening_provider_status()
 RETURNS TABLE(integration_key text, name text, environment text, enabled boolean, status text, provider_verified boolean, circuit_state text, last_success_at timestamp with time zone, last_error_at timestamp with time zone, last_error text, has_credential boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT c.integration_key, c.name, c.environment, c.enabled, c.status,
         c.provider_verified, c.circuit_state, c.last_success_at,
         c.last_error_at, c.last_error,
         EXISTS (
           SELECT 1 FROM public.integration_credentials cr
           WHERE cr.connection_id = c.id AND cr.is_current
         ) AS has_credential
  FROM public.integration_connections c
  WHERE c.integration_key IN ('sanctions_screening', 'aml_screening')
    AND (
      public.is_super_admin(auth.uid())
      OR public.has_permission(auth.uid(), 'fit_and_proper', 'view')
      OR public.has_permission(auth.uid(), 'settings', 'view')
    );
$function$
;
