CREATE OR REPLACE FUNCTION public.get_application_actions(_application_id uuid)
 RETURNS TABLE(id uuid, application_id uuid, action text, comments text, actor_id uuid, actor_email text, actor_name text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_internal boolean;
  v_owner uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_is_internal := public.has_role(v_uid, 'super_admin'::app_role)
                OR public.has_role(v_uid, 'admin'::app_role)
                OR public.has_role(v_uid, 'supervisor'::app_role)
                OR public.has_role(v_uid, 'licensing_officer'::app_role)
                OR public.has_role(v_uid, 'analyst'::app_role);

  SELECT a.applicant_id INTO v_owner
  FROM public.applications a
  WHERE a.id = _application_id;

  IF v_owner IS NULL THEN
    RETURN;
  END IF;
  IF NOT v_is_internal AND v_owner <> v_uid THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT
    aa.id,
    aa.application_id,
    aa.action,
    aa.comments,
    aa.actor_id,
    COALESCE(p.email, pl.email)         AS actor_email,
    COALESCE(p.full_name, pl.full_name) AS actor_name,
    aa.created_at
  FROM public.approval_actions aa
  LEFT JOIN public.profiles          p  ON p.id  = aa.actor_id
  LEFT JOIN public.pre_license_users pl ON pl.id = aa.actor_id
  WHERE aa.application_id = _application_id
  ORDER BY aa.created_at ASC;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_application_list_page(_page integer, _page_size integer, _search text, _search_mode text, _status text, _version_id uuid, _sort_by text, _sort_dir text, _licensee_id uuid DEFAULT NULL::uuid, _sector_id uuid DEFAULT NULL::uuid, _sla text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, application_number text, applicant_id uuid, applicant_name text, applicant_email text, license_type text, status text, data jsonb, submitted_at timestamp with time zone, created_at timestamp with time zone, form_version_id uuid, sector_id uuid, resolved_sector_id uuid, sub_sector_id uuid, category_id uuid, service_id uuid, sector_name text, sub_sector_name text, category_name text, service_name text, payment_id uuid, payment_amount numeric, payment_status text, payment_currency text, payment_method text, payment_paid_at timestamp with time zone, action_count integer, total_count bigint)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_internal boolean;
  v_page_size int := GREATEST(1, LEAST(_page_size, 200));
  v_offset int := GREATEST(0, _page) * v_page_size;
  v_search text := NULLIF(trim(coalesce(_search, '')), '');
  v_mode text := lower(coalesce(_search_mode, 'contains'));
  v_status text := NULLIF(_status, 'all');
  v_sla text := NULLIF(lower(coalesce(_sla, '')), '');
  v_sort text := lower(coalesce(_sort_by, 'created_at'));
  v_dir text := lower(coalesce(_sort_dir, 'desc'));
  v_self_licensee_id uuid;
  v_submitted_set text[] := ARRAY['submitted','in_progress'];
  v_sla_cutoff timestamptz := now() - interval '30 days';
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_is_internal := public.has_role(v_uid, 'super_admin'::app_role)
                OR public.has_role(v_uid, 'admin'::app_role)
                OR public.has_role(v_uid, 'supervisor'::app_role)
                OR public.has_role(v_uid, 'licensing_officer'::app_role)
                OR public.has_role(v_uid, 'analyst'::app_role);

  SELECT p.licensee_id
  INTO v_self_licensee_id
  FROM public.profiles p
  WHERE p.id = v_uid;

  IF v_sort NOT IN ('created_at', 'submitted_at', 'application_number') THEN v_sort := 'created_at'; END IF;
  IF v_dir NOT IN ('asc', 'desc') THEN v_dir := 'desc'; END IF;
  IF v_mode NOT IN ('contains', 'starts_with', 'exact') THEN v_mode := 'contains'; END IF;

  RETURN QUERY
  WITH access_scope AS (
    SELECT DISTINCT target_licensee_id
    FROM (
      SELECT CASE
        WHEN v_is_internal THEN NULL::uuid
        WHEN _licensee_id IS NOT NULL AND EXISTS (
          SELECT 1
          FROM public.ppoc_entity_mappings pem
          WHERE pem.ppoc_user_id = v_uid
            AND pem.licensee_id = _licensee_id
            AND pem.is_active = true
        ) THEN _licensee_id
        WHEN _licensee_id IS NOT NULL AND v_self_licensee_id = _licensee_id THEN _licensee_id
        WHEN _licensee_id IS NULL AND v_self_licensee_id IS NOT NULL THEN v_self_licensee_id
        WHEN _licensee_id IS NULL THEN NULL::uuid
        ELSE NULL::uuid
      END AS target_licensee_id
    ) s
    WHERE target_licensee_id IS NOT NULL
  ),
  linked_applications AS (
    SELECT DISTINCT a.id AS application_id
    FROM public.applications a
    WHERE a.applicant_id = v_uid

    UNION

    SELECT DISTINCT lic.application_id AS application_id
    FROM access_scope sc
    JOIN public.licensees l ON l.id = sc.target_licensee_id
    JOIN public.licenses lic ON lic.id = l.license_id
    WHERE lic.application_id IS NOT NULL

    UNION

    SELECT DISTINCT a.id AS application_id
    FROM access_scope sc
    JOIN public.licensees l ON l.id = sc.target_licensee_id
    JOIN public.licenses lic ON lic.id = l.license_id
    JOIN public.applications seed ON seed.id = lic.application_id
    JOIN public.applications a ON a.applicant_id = seed.applicant_id

    UNION

    SELECT DISTINCT a.id AS application_id
    FROM access_scope sc
    JOIN public.licensees l ON l.id = sc.target_licensee_id
    JOIN public.profiles p ON p.licensee_id = l.id
    JOIN public.applications a ON a.applicant_id = p.id
  ),
  enriched AS (
    SELECT
      a.*, 
      lic.id AS linked_license_id,
      lic.sector_id AS linked_license_sector_id,
      lic.sub_sector_id AS linked_license_sub_sector_id,
      lic.category_id AS linked_license_category_id,
      l.id AS linked_licensee_id,
      l.sector_id AS linked_licensee_sector_id,
      l.sub_sector_id AS linked_licensee_sub_sector_id,
      l.category_id AS linked_licensee_category_id,
      COALESCE(
        NULLIF(a.data->>'sector_id', '')::uuid,
        lic.sector_id,
        l.sector_id
      ) AS resolved_sector_id_value,
      COALESCE(NULLIF(a.data->>'sub_sector_id', '')::uuid, lic.sub_sector_id, l.sub_sector_id) AS resolved_sub_sector_id_value,
      COALESCE(NULLIF(a.data->>'category_id', '')::uuid, lic.category_id, l.category_id) AS resolved_category_id_value,
      NULLIF(a.data->>'service_id', '')::uuid AS resolved_service_id_value
    FROM public.applications a
    LEFT JOIN public.licenses lic ON lic.application_id = a.id
    LEFT JOIN public.licensees l ON l.license_id = lic.id
    WHERE
      (
        v_is_internal
        OR a.id IN (SELECT la.application_id FROM linked_applications la)
      )
      AND (
        NOT v_is_internal
        OR (
          a.status <> 'draft'
          AND NOT (
            a.status = 'in_progress'
            AND a.submitted_at IS NULL
            AND a.workflow_id IS NULL
            AND a.current_step_id IS NULL
          )
        )
      )
      AND (
        v_status IS NULL
        OR (v_status = 'resubmission_requested' AND a.status IN ('resubmission_requested', 'query_raised'))
        OR a.status = v_status
      )
      AND (
        v_sla IS NULL
        OR (v_sla = 'pending' AND a.status = ANY(v_submitted_set))
        OR (v_sla = 'breached' AND a.status = ANY(v_submitted_set) AND a.submitted_at IS NOT NULL AND a.submitted_at < v_sla_cutoff)
        OR (v_sla = 'due_soon' AND a.status = ANY(v_submitted_set) AND a.submitted_at IS NOT NULL AND a.submitted_at < (now() - interval '20 days') AND a.submitted_at >= v_sla_cutoff)
      )
      AND (
        _version_id IS NULL
        OR a.form_version_id = _version_id
        OR (
          a.data ? 'form_version_ids'
          AND EXISTS (
            SELECT 1
            FROM jsonb_each_text(a.data->'form_version_ids') v(k, val)
            WHERE val::uuid = _version_id
          )
        )
      )
      AND (
        _sector_id IS NULL
        OR COALESCE(NULLIF(a.data->>'sector_id', '')::uuid, lic.sector_id, l.sector_id) = _sector_id
      )
      AND (
        v_search IS NULL
        OR (
          CASE v_mode
            WHEN 'exact' THEN lower(a.application_number) = lower(v_search)
            WHEN 'starts_with' THEN lower(a.application_number) LIKE lower(v_search) || '%'
            ELSE lower(a.application_number) LIKE '%' || lower(v_search) || '%'
          END
        )
        OR EXISTS (
          SELECT 1
          FROM public.profiles p
          WHERE p.id = a.applicant_id
            AND (
              CASE v_mode
                WHEN 'exact' THEN lower(coalesce(p.full_name, '')) = lower(v_search) OR lower(coalesce(p.email, '')) = lower(v_search)
                WHEN 'starts_with' THEN lower(coalesce(p.full_name, '')) LIKE lower(v_search) || '%' OR lower(coalesce(p.email, '')) LIKE lower(v_search) || '%'
                ELSE lower(coalesce(p.full_name, '')) LIKE '%' || lower(v_search) || '%' OR lower(coalesce(p.email, '')) LIKE '%' || lower(v_search) || '%'
              END
            )
        )
        OR EXISTS (
          SELECT 1
          FROM public.pre_license_users pl
          WHERE pl.id = a.applicant_id
            AND (
              CASE v_mode
                WHEN 'exact' THEN lower(coalesce(pl.full_name, '')) = lower(v_search) OR lower(coalesce(pl.email, '')) = lower(v_search)
                WHEN 'starts_with' THEN lower(coalesce(pl.full_name, '')) LIKE lower(v_search) || '%' OR lower(coalesce(pl.email, '')) LIKE lower(v_search) || '%'
                ELSE lower(coalesce(pl.full_name, '')) LIKE '%' || lower(v_search) || '%' OR lower(coalesce(pl.email, '')) LIKE '%' || lower(v_search) || '%'
              END
            )
        )
      )
  ),
  counted AS (
    SELECT count(*) AS total FROM enriched
  ),
  ordered AS (
    SELECT e.*
    FROM enriched e
    ORDER BY
      CASE WHEN v_sort = 'application_number' AND v_dir = 'asc' THEN e.application_number END ASC,
      CASE WHEN v_sort = 'application_number' AND v_dir = 'desc' THEN e.application_number END DESC,
      CASE WHEN v_sort = 'submitted_at' AND v_dir = 'asc' THEN e.submitted_at END ASC NULLS LAST,
      CASE WHEN v_sort = 'submitted_at' AND v_dir = 'desc' THEN e.submitted_at END DESC NULLS LAST,
      CASE WHEN v_sort = 'created_at' AND v_dir = 'asc' THEN e.created_at END ASC,
      CASE WHEN v_sort = 'created_at' AND v_dir = 'desc' THEN e.created_at END DESC,
      e.created_at DESC
    LIMIT v_page_size OFFSET v_offset
  )
  SELECT
    o.id,
    o.application_number,
    o.applicant_id,
    coalesce(p.full_name, pl.full_name, '')::text AS applicant_name,
    coalesce(p.email, pl.email, '')::text AS applicant_email,
    o.license_type,
    o.status::text,
    o.data,
    o.submitted_at,
    o.created_at,
    o.form_version_id,
    NULLIF(o.data->>'sector_id', '')::uuid AS sector_id,
    o.resolved_sector_id_value AS resolved_sector_id,
    NULLIF(o.data->>'sub_sector_id', '')::uuid AS sub_sector_id,
    NULLIF(o.data->>'category_id', '')::uuid AS category_id,
    NULLIF(o.data->>'service_id', '')::uuid AS service_id,
    sec.name::text AS sector_name,
    sub.name::text AS sub_sector_name,
    cat.name::text AS category_name,
    svc.name::text AS service_name,
    pay.id AS payment_id,
    pay.amount AS payment_amount,
    pay.status::text AS payment_status,
    pay.currency AS payment_currency,
    pay.payment_method::text AS payment_method,
    pay.paid_at AS payment_paid_at,
    coalesce(act.cnt, 0)::int AS action_count,
    (SELECT total FROM counted) AS total_count
  FROM ordered o
  LEFT JOIN public.profiles p ON p.id = o.applicant_id
  LEFT JOIN public.pre_license_users pl ON pl.id = o.applicant_id
  LEFT JOIN public.sectors sec ON sec.id = o.resolved_sector_id_value
  LEFT JOIN public.sub_sectors sub ON sub.id = o.resolved_sub_sector_id_value
  LEFT JOIN public.categories cat ON cat.id = o.resolved_category_id_value
  LEFT JOIN public.services svc ON svc.id = o.resolved_service_id_value
  LEFT JOIN LATERAL (
    SELECT pp.id, pp.amount, pp.status, pp.currency, pp.payment_method, pp.paid_at
    FROM public.payments pp
    WHERE pp.application_id = o.id
    ORDER BY
      CASE
        WHEN lower(pp.status::text) IN ('completed', 'success', 'paid') THEN 1
        WHEN lower(pp.status::text) IN ('pending', 'processing', 'initiated') THEN 2
        ELSE 3
      END,
      pp.created_at DESC
    LIMIT 1
  ) pay ON TRUE
  LEFT JOIN LATERAL (
    SELECT count(*)::int AS cnt
    FROM public.approval_actions aa
    WHERE aa.application_id = o.id
  ) act ON TRUE;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_application_list_page(_page integer, _page_size integer, _search text, _search_mode text, _status text, _version_id uuid, _sort_by text, _sort_dir text, _licensee_id uuid DEFAULT NULL::uuid, _sector_id uuid DEFAULT NULL::uuid, _sla text DEFAULT NULL::text, _status_group text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, application_number text, applicant_id uuid, applicant_name text, applicant_email text, license_type text, status text, data jsonb, submitted_at timestamp with time zone, created_at timestamp with time zone, form_version_id uuid, sector_id uuid, resolved_sector_id uuid, sub_sector_id uuid, category_id uuid, service_id uuid, sector_name text, sub_sector_name text, category_name text, service_name text, payment_id uuid, payment_amount numeric, payment_status text, payment_currency text, payment_method text, payment_paid_at timestamp with time zone, action_count integer, total_count bigint)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_internal boolean;
  v_page_size int := GREATEST(1, LEAST(_page_size, 200));
  v_offset int := GREATEST(0, _page) * v_page_size;
  v_search text := NULLIF(trim(coalesce(_search, '')), '');
  v_mode text := lower(coalesce(_search_mode, 'contains'));
  v_status text := NULLIF(_status, 'all');
  v_sla text := NULLIF(lower(coalesce(_sla, '')), '');
  v_status_group text := NULLIF(lower(coalesce(_status_group, '')), '');
  v_sort text := lower(coalesce(_sort_by, 'created_at'));
  v_dir text := lower(coalesce(_sort_dir, 'desc'));
  v_self_licensee_id uuid;
  v_submitted_set text[] := ARRAY['submitted','in_progress'];
  v_returned_set text[] := ARRAY['resubmission_requested','query_raised'];
  v_sla_cutoff timestamptz := now() - interval '30 days';
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_is_internal := public.has_role(v_uid, 'super_admin'::app_role)
                OR public.has_role(v_uid, 'admin'::app_role)
                OR public.has_role(v_uid, 'supervisor'::app_role)
                OR public.has_role(v_uid, 'licensing_officer'::app_role)
                OR public.has_role(v_uid, 'analyst'::app_role);

  SELECT p.licensee_id
  INTO v_self_licensee_id
  FROM public.profiles p
  WHERE p.id = v_uid;

  IF v_sort NOT IN ('created_at', 'submitted_at', 'application_number') THEN v_sort := 'created_at'; END IF;
  IF v_dir NOT IN ('asc', 'desc') THEN v_dir := 'desc'; END IF;
  IF v_mode NOT IN ('contains', 'starts_with', 'exact') THEN v_mode := 'contains'; END IF;

  RETURN QUERY
  WITH access_scope AS (
    SELECT DISTINCT target_licensee_id
    FROM (
      SELECT CASE
        WHEN v_is_internal THEN NULL::uuid
        WHEN _licensee_id IS NOT NULL AND EXISTS (
          SELECT 1
          FROM public.ppoc_entity_mappings pem
          WHERE pem.ppoc_user_id = v_uid
            AND pem.licensee_id = _licensee_id
            AND pem.is_active = true
        ) THEN _licensee_id
        WHEN _licensee_id IS NOT NULL AND v_self_licensee_id = _licensee_id THEN _licensee_id
        WHEN _licensee_id IS NULL AND v_self_licensee_id IS NOT NULL THEN v_self_licensee_id
        WHEN _licensee_id IS NULL THEN NULL::uuid
        ELSE NULL::uuid
      END AS target_licensee_id
    ) s
    WHERE target_licensee_id IS NOT NULL
  ),
  linked_applications AS (
    SELECT DISTINCT a.id AS application_id
    FROM public.applications a
    WHERE a.applicant_id = v_uid
      AND (
        _licensee_id IS NULL
        OR v_self_licensee_id = _licensee_id
      )

    UNION

    SELECT DISTINCT lic.application_id AS application_id
    FROM access_scope sc
    JOIN public.licensees l ON l.id = sc.target_licensee_id
    JOIN public.licenses lic ON lic.id = l.license_id
    WHERE lic.application_id IS NOT NULL

    UNION

    SELECT DISTINCT a.id AS application_id
    FROM access_scope sc
    JOIN public.applications a
      ON NULLIF(a.data->>'licensee_id', '')::uuid = sc.target_licensee_id

    UNION

    SELECT DISTINCT a.id AS application_id
    FROM access_scope sc
    JOIN public.licensees l ON l.id = sc.target_licensee_id
    JOIN public.profiles p ON p.licensee_id = l.id
    JOIN public.applications a ON a.applicant_id = p.id
  ),
  enriched AS (
    SELECT
      a.*,
      lic.id AS linked_license_id,
      lic.sector_id AS linked_license_sector_id,
      lic.sub_sector_id AS linked_license_sub_sector_id,
      lic.category_id AS linked_license_category_id,
      l.id AS linked_licensee_id,
      l.sector_id AS linked_licensee_sector_id,
      l.sub_sector_id AS linked_licensee_sub_sector_id,
      l.category_id AS linked_licensee_category_id,
      COALESCE(
        NULLIF(a.data->>'sector_id', '')::uuid,
        lic.sector_id,
        l.sector_id
      ) AS resolved_sector_id_value,
      COALESCE(NULLIF(a.data->>'sub_sector_id', '')::uuid, lic.sub_sector_id, l.sub_sector_id) AS resolved_sub_sector_id_value,
      COALESCE(NULLIF(a.data->>'category_id', '')::uuid, lic.category_id, l.category_id) AS resolved_category_id_value,
      NULLIF(a.data->>'service_id', '')::uuid AS resolved_service_id_value
    FROM public.applications a
    LEFT JOIN public.licenses lic ON lic.application_id = a.id
    LEFT JOIN public.licensees l ON l.license_id = lic.id
    WHERE
      (
        v_is_internal
        OR a.id IN (SELECT la.application_id FROM linked_applications la)
      )
      AND (
        NOT v_is_internal
        OR (
          a.status <> 'draft'
          AND NOT (
            a.status = 'in_progress'
            AND a.submitted_at IS NULL
            AND a.workflow_id IS NULL
            AND a.current_step_id IS NULL
          )
        )
      )
      AND (
        v_status IS NULL
        OR (v_status = 'resubmission_requested' AND a.status IN ('resubmission_requested', 'query_raised'))
        OR a.status = v_status
      )
      AND (
        v_status_group IS NULL
        OR (v_status_group = 'pending' AND a.status = ANY(v_submitted_set))
        OR (v_status_group = 'returned' AND a.status = ANY(v_returned_set))
        OR (v_status_group = 'approved' AND a.status = 'approved')
        OR (v_status_group = 'rejected' AND a.status = 'rejected')
      )
      AND (
        v_sla IS NULL
        OR (v_sla = 'pending' AND a.status = ANY(v_submitted_set))
        OR (v_sla = 'breached' AND a.status = ANY(v_submitted_set) AND a.submitted_at IS NOT NULL AND a.submitted_at < v_sla_cutoff)
        OR (v_sla = 'due_soon' AND a.status = ANY(v_submitted_set) AND a.submitted_at IS NOT NULL AND a.submitted_at < (now() - interval '20 days') AND a.submitted_at >= v_sla_cutoff)
      )
      AND (
        _version_id IS NULL
        OR a.form_version_id = _version_id
        OR (
          a.data ? 'form_version_ids'
          AND EXISTS (
            SELECT 1
            FROM jsonb_each_text(a.data->'form_version_ids') v(k, val)
            WHERE val::uuid = _version_id
          )
        )
      )
      AND (
        _sector_id IS NULL
        OR COALESCE(NULLIF(a.data->>'sector_id', '')::uuid, lic.sector_id, l.sector_id) = _sector_id
      )
      AND (
        v_search IS NULL
        OR (
          CASE v_mode
            WHEN 'exact' THEN lower(a.application_number) = lower(v_search)
            WHEN 'starts_with' THEN lower(a.application_number) LIKE lower(v_search) || '%'
            ELSE lower(a.application_number) LIKE '%' || lower(v_search) || '%'
          END
        )
        OR EXISTS (
          SELECT 1
          FROM public.profiles p
          WHERE p.id = a.applicant_id
            AND (
              CASE v_mode
                WHEN 'exact' THEN lower(coalesce(p.full_name, '')) = lower(v_search) OR lower(coalesce(p.email, '')) = lower(v_search)
                WHEN 'starts_with' THEN lower(coalesce(p.full_name, '')) LIKE lower(v_search) || '%' OR lower(coalesce(p.email, '')) LIKE lower(v_search) || '%'
                ELSE lower(coalesce(p.full_name, '')) LIKE '%' || lower(v_search) || '%' OR lower(coalesce(p.email, '')) LIKE '%' || lower(v_search) || '%'
              END
            )
        )
        OR EXISTS (
          SELECT 1
          FROM public.pre_license_users pl
          WHERE pl.id = a.applicant_id
            AND (
              CASE v_mode
                WHEN 'exact' THEN lower(coalesce(pl.full_name, '')) = lower(v_search) OR lower(coalesce(pl.email, '')) = lower(v_search)
                WHEN 'starts_with' THEN lower(coalesce(pl.full_name, '')) LIKE lower(v_search) || '%' OR lower(coalesce(pl.email, '')) LIKE lower(v_search) || '%'
                ELSE lower(coalesce(pl.full_name, '')) LIKE '%' || lower(v_search) || '%' OR lower(coalesce(pl.email, '')) LIKE '%' || lower(v_search) || '%'
              END
            )
        )
      )
  ),
  counted AS (
    SELECT count(*) AS total FROM enriched
  ),
  ordered AS (
    SELECT e.*
    FROM enriched e
    ORDER BY
      CASE WHEN v_sort = 'application_number' AND v_dir = 'asc' THEN e.application_number END ASC,
      CASE WHEN v_sort = 'application_number' AND v_dir = 'desc' THEN e.application_number END DESC,
      CASE WHEN v_sort = 'submitted_at' AND v_dir = 'asc' THEN e.submitted_at END ASC NULLS LAST,
      CASE WHEN v_sort = 'submitted_at' AND v_dir = 'desc' THEN e.submitted_at END DESC NULLS LAST,
      CASE WHEN v_sort = 'created_at' AND v_dir = 'asc' THEN e.created_at END ASC,
      CASE WHEN v_sort = 'created_at' AND v_dir = 'desc' THEN e.created_at END DESC,
      e.created_at DESC
    LIMIT v_page_size OFFSET v_offset
  )
  SELECT
    o.id,
    o.application_number,
    o.applicant_id,
    coalesce(p.full_name, pl.full_name, '')::text AS applicant_name,
    coalesce(p.email, pl.email, '')::text AS applicant_email,
    o.license_type,
    o.status::text,
    o.data,
    o.submitted_at,
    o.created_at,
    o.form_version_id,
    NULLIF(o.data->>'sector_id', '')::uuid AS sector_id,
    o.resolved_sector_id_value AS resolved_sector_id,
    NULLIF(o.data->>'sub_sector_id', '')::uuid AS sub_sector_id,
    NULLIF(o.data->>'category_id', '')::uuid AS category_id,
    NULLIF(o.data->>'service_id', '')::uuid AS service_id,
    sec.name::text AS sector_name,
    sub.name::text AS sub_sector_name,
    cat.name::text AS category_name,
    svc.name::text AS service_name,
    pay.id AS payment_id,
    pay.amount AS payment_amount,
    pay.status::text AS payment_status,
    pay.currency AS payment_currency,
    pay.payment_method::text AS payment_method,
    pay.paid_at AS payment_paid_at,
    coalesce(act.cnt, 0)::int AS action_count,
    (SELECT total FROM counted) AS total_count
  FROM ordered o
  LEFT JOIN public.profiles p ON p.id = o.applicant_id
  LEFT JOIN public.pre_license_users pl ON pl.id = o.applicant_id
  LEFT JOIN public.sectors sec ON sec.id = o.resolved_sector_id_value
  LEFT JOIN public.sub_sectors sub ON sub.id = o.resolved_sub_sector_id_value
  LEFT JOIN public.categories cat ON cat.id = o.resolved_category_id_value
  LEFT JOIN public.services svc ON svc.id = o.resolved_service_id_value
  LEFT JOIN LATERAL (
    SELECT pp.id, pp.amount, pp.status, pp.currency, pp.payment_method, pp.paid_at
    FROM public.payments pp
    WHERE pp.application_id = o.id
    ORDER BY
      CASE
        WHEN lower(pp.status::text) IN ('completed', 'success', 'paid') THEN 1
        WHEN lower(pp.status::text) IN ('pending', 'processing', 'initiated') THEN 2
        ELSE 3
      END,
      pp.created_at DESC
    LIMIT 1
  ) pay ON TRUE
  LEFT JOIN LATERAL (
    SELECT count(*)::int AS cnt
    FROM public.approval_actions aa
    WHERE aa.application_id = o.id
  ) act ON TRUE;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_application_list_stats(_licensee_id uuid DEFAULT NULL::uuid, _sector_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_total int;
  v_approved int;
  v_rejected int;
  v_pending int;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'insufficient_privilege';
  END IF;

  WITH base AS (
    SELECT x.status
    FROM public.get_application_list_page(
      0,
      5000,
      NULL,
      'contains',
      NULL,
      NULL,
      'created_at',
      'desc',
      _licensee_id,
      _sector_id,
      NULL,
      NULL
    ) x
  )
  SELECT
    count(*),
    count(*) FILTER (WHERE status = 'approved'),
    count(*) FILTER (WHERE status = 'rejected'),
    count(*) FILTER (WHERE status NOT IN ('approved', 'rejected', 'cancelled'))
  INTO v_total, v_approved, v_rejected, v_pending
  FROM base;

  RETURN jsonb_build_object(
    'total', v_total,
    'approved', v_approved,
    'rejected', v_rejected,
    'pending', v_pending
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_complaint(_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_row jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  SELECT to_jsonb(c.*) || jsonb_build_object(
           'sla_status', public.complaint_sla_status(c.created_at,c.sla_due_at,c.sla_days,c.resolved_at))
    INTO v_row
    FROM public.complaints c
   WHERE c.id = _id
     AND (public.has_complaint_perm(v_uid,'view_all') OR public.has_complaint_perm(v_uid,'triage')
          OR c.complainant_id = v_uid);
  IF v_row IS NULL THEN RAISE EXCEPTION 'Complaint not found or access denied' USING ERRCODE = 'P0002'; END IF;
  RETURN v_row;
END; $function$
;
CREATE OR REPLACE FUNCTION public.get_complaint_available_actions(_complaint_id uuid)
 RETURNS TABLE(action_key text, label text, action_type text, require_comments boolean, required_fields jsonb, target_step_key text, sort_order integer, mutation_kind text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_complaint public.complaints%ROWTYPE; v_user_role text; v_step_id uuid;
BEGIN
  IF v_user IS NULL THEN RETURN; END IF;
  SELECT * INTO v_complaint FROM public.complaints WHERE id=_complaint_id;
  IF NOT FOUND OR NOT public.has_complaint_perm(v_user,'view') THEN RETURN; END IF;

  SELECT current_step_id INTO v_step_id FROM public.workflow_instances
    WHERE entity_type='complaint' AND entity_id=_complaint_id AND status IN ('active','paused')
    ORDER BY started_at DESC LIMIT 1;
  IF v_step_id IS NULL THEN RETURN; END IF;

  SELECT role::text INTO v_user_role FROM public.user_roles WHERE user_id=v_user LIMIT 1;

  RETURN QUERY
  SELECT a.action_key, a.label, a.action_type, a.require_comments, a.required_fields,
         ns.step_key, a.sort_order, a.mutation_spec->>'kind'
  FROM public.approval_step_actions a
  LEFT JOIN public.approval_steps ns ON ns.id=a.next_step_id
  WHERE a.step_id=v_step_id AND a.is_enabled=true AND a.action_key IS NOT NULL
    AND (array_length(a.allowed_role_slugs,1) IS NULL OR array_length(a.allowed_role_slugs,1)=0
         OR a.allowed_role_slugs && public.user_workflow_role_slugs(v_user) OR public.has_role(v_user,'super_admin'::app_role))
  ORDER BY a.sort_order;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_complaint_current_assignees(_complaint_ids uuid[])
 RETURNS TABLE(complaint_id uuid, step_role text, user_id uuid, full_name text, email text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_any_internal_role(auth.uid()) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH inst AS (
    SELECT wi.entity_id AS complaint_id, wi.current_step_id
    FROM public.workflow_instances wi
    WHERE wi.entity_type = 'complaint'
      AND wi.entity_id = ANY(_complaint_ids)
      AND wi.status IN ('active', 'paused')
  ),
  step AS (
    SELECT i.complaint_id,
           s.id AS step_id,
           s.approver_role::text AS approver_role,
           s.approver_type,
           s.approver_config
    FROM inst i
    JOIN public.approval_steps s ON s.id = i.current_step_id
  ),
  specific_users AS (
    SELECT st.complaint_id, st.approver_role, (u::uuid) AS user_id
    FROM step st, jsonb_array_elements_text(COALESCE(st.approver_config->'user_ids', '[]'::jsonb)) AS u
    WHERE st.approver_type = 'specific_users'
  ),
  role_users AS (
    SELECT st.complaint_id, st.approver_role, ur.user_id
    FROM step st
    JOIN public.user_roles ur ON ur.role::text = st.approver_role
    WHERE st.approver_type = 'role_based_user' AND st.approver_role IS NOT NULL
  ),
  all_users AS (
    SELECT * FROM specific_users
    UNION
    SELECT * FROM role_users
  )
  SELECT au.complaint_id, au.approver_role, au.user_id, p.full_name, p.email
  FROM all_users au
  LEFT JOIN public.profiles p ON p.id = au.user_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_complaint_tracking(_complaint_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid(); v_complaint public.complaints%ROWTYPE; v_is_internal boolean;
  v_instance public.workflow_instances%ROWTYPE; v_current_step public.approval_steps%ROWTYPE;
  v_steps jsonb; v_events jsonb; v_assignee_name text; v_staff boolean;
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('error','AUTH_REQUIRED'); END IF;
  SELECT * INTO v_complaint FROM public.complaints WHERE id=_complaint_id;
  v_staff := public.has_complaint_perm(v_user,'view');
  IF NOT FOUND OR NOT (v_staff OR public.external_can_access_complaint(v_user, _complaint_id, 'view')) THEN
    RETURN jsonb_build_object('error','FORBIDDEN');
  END IF;

  v_is_internal := v_staff AND public.is_internal_staff(v_user);

  SELECT * INTO v_instance FROM public.workflow_instances
    WHERE entity_type='complaint' AND entity_id=_complaint_id ORDER BY started_at DESC LIMIT 1;

  IF v_instance.id IS NOT NULL THEN
    SELECT * INTO v_current_step FROM public.approval_steps WHERE id=v_instance.current_step_id;
    SELECT full_name INTO v_assignee_name FROM public.profiles WHERE id=v_instance.assigned_user_id;
  END IF;

  SELECT jsonb_agg(jsonb_build_object('step_key',s.step_key,'label',COALESCE(s.public_label,s.name),
    'order',s.step_order,'is_current',s.id=v_instance.current_step_id,
    'is_terminal',s.is_terminal,'is_start',s.is_start) ORDER BY s.step_order) INTO v_steps
  FROM public.approval_steps s WHERE s.workflow_id=v_instance.workflow_id
    AND (v_is_internal OR s.complainant_visible OR s.licensee_visible);

  SELECT jsonb_agg(evt ORDER BY (evt->>'when') DESC) INTO v_events FROM (
    SELECT jsonb_build_object('source','workflow','when',aa.responded_at,
      'title',COALESCE(a.label,aa.action),
      'note',CASE WHEN v_is_internal THEN aa.comments ELSE NULL END,
      'actor',CASE WHEN v_is_internal THEN p.full_name ELSE NULL END) AS evt
    FROM public.approval_actions aa
    LEFT JOIN public.approval_step_actions a ON a.step_id=aa.step_id AND a.action_key=aa.action
    LEFT JOIN public.profiles p ON p.id=aa.actor_id
    WHERE aa.entity_type='complaint' AND aa.entity_id=_complaint_id
      AND (v_is_internal OR a.complainant_visible=true OR a.licensee_visible=true)
    UNION ALL
    SELECT jsonb_build_object('source','enforcement','when',e.created_at,
      'title',initcap(replace(e.event_type,'_',' ')),
      'note',CASE WHEN v_is_internal THEN e.note ELSE NULL END,
      'actor',CASE WHEN v_is_internal THEN p.full_name ELSE NULL END)
    FROM public.enforcement_case_events e LEFT JOIN public.profiles p ON p.id=e.actor_id
    WHERE e.case_id=v_complaint.enforcement_action_id
  ) x;

  RETURN jsonb_build_object(
    'complaint_number',v_complaint.complaint_number,'status',v_complaint.status,
    'current_step_key',v_current_step.step_key,
    'current_step_label',COALESCE(v_current_step.public_label,v_current_step.name),
    'assigned_user_name',CASE WHEN v_is_internal THEN v_assignee_name ELSE NULL END,
    'assigned_role',CASE WHEN v_is_internal THEN v_instance.assigned_role ELSE NULL END,
    'due_at',v_instance.due_at,'sla_status',v_instance.sla_status,
    'instance_updated_at',v_instance.updated_at,
    'steps',COALESCE(v_steps,'[]'::jsonb),
    'events',COALESCE(v_events,'[]'::jsonb),
    'is_internal',v_is_internal);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_declaration_invitation_public(p_token text)
 RETURNS TABLE(id uuid, assessment_id uuid, status text, expires_at timestamp with time zone, failed_identity_attempts integer, individual_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hash text := encode(sha256(p_token::bytea), 'hex');
BEGIN
  RETURN QUERY
  SELECT di.id,
         di.assessment_id,
         di.status,
         di.expires_at,
         di.failed_identity_attempts,
         fp.full_name
  FROM   public.declaration_invitations di
  JOIN   public.fp_individuals           fp ON fp.id = di.individual_id
  WHERE  di.token_hash = v_hash;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_form_version_usage_counts(_template_id uuid)
 RETURNS TABLE(version_id uuid, in_progress_count bigint, submitted_response_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT (public.has_role(v_uid,'super_admin'::app_role)
       OR public.has_role(v_uid,'admin'::app_role)
       OR public.has_role(v_uid,'supervisor'::app_role)
       OR public.has_role(v_uid,'licensing_officer'::app_role)
       OR public.has_role(v_uid,'analyst'::app_role)) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  WITH vs AS (
    SELECT id FROM public.form_versions WHERE template_id = _template_id
  ),
  app_counts AS (
    SELECT
      COALESCE(NULLIF(v.k,'')::uuid, a.form_version_id) AS vid,
      count(*)::bigint AS cnt
    FROM public.applications a
    LEFT JOIN LATERAL jsonb_each_text(COALESCE(a.data->'form_version_ids','{}'::jsonb)) v(k, val)
      ON val::uuid IN (SELECT id FROM vs)
    WHERE a.status IN ('draft','in_progress','resubmission_requested','query_raised','submitted')
      AND (
        a.form_version_id IN (SELECT id FROM vs)
        OR val::uuid IN (SELECT id FROM vs)
      )
    GROUP BY 1
  ),
  resp_counts AS (
    SELECT version_id AS vid, count(*)::bigint AS cnt
    FROM public.form_responses
    WHERE version_id IN (SELECT id FROM vs)
      AND status = 'submitted'
    GROUP BY 1
  )
  SELECT
    vs.id,
    COALESCE((SELECT cnt FROM app_counts WHERE vid = vs.id), 0),
    COALESCE((SELECT cnt FROM resp_counts WHERE vid = vs.id), 0)
  FROM vs;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_fp_declaration_form_public()
 RETURNS TABLE(template_id uuid, version_id uuid, schema_snapshot jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT ft.id, fv.id, fv.schema_snapshot
  FROM public.form_templates ft
  JOIN public.form_versions fv ON fv.template_id = ft.id
  WHERE ft.form_type = 'fit_and_proper' AND ft.service = 'declaration'
  ORDER BY fv.version DESC
  LIMIT 1;
$function$
;
CREATE OR REPLACE FUNCTION public.get_fp_determination_audit_log(_determination_id uuid)
 RETURNS TABLE(id uuid, action text, user_id uuid, actor_name text, created_at timestamp with time zone, metadata jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT al.id, al.action, al.user_id, p.full_name, al.created_at, al.metadata
  FROM public.audit_logs al
  LEFT JOIN public.profiles p ON p.id = al.user_id
  WHERE al.entity_type = 'fp_determination'
    AND al.entity_id = _determination_id::text
    AND public.is_fp_staff(auth.uid())
  ORDER BY al.created_at DESC
  LIMIT 100;
$function$
;
CREATE OR REPLACE FUNCTION public.get_in_flight_renewals(license_ids uuid[])
 RETURNS TABLE(application_id uuid, license_id uuid, status text, is_pending boolean, is_in_progress boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH caller AS (
    SELECT
      auth.uid() AS uid,
      public.user_licensee_id(auth.uid()) AS lic_id
  ),
  scoped_app_ids AS (
    SELECT a.id
    FROM public.applications a, caller c
    WHERE a.applicant_id = c.uid
    UNION
    SELECT app_id
    FROM caller c,
         LATERAL public.application_ids_for_licensee(c.lic_id) AS app_id
    WHERE c.lic_id IS NOT NULL
    UNION
    SELECT a.id
    FROM public.applications a, caller c
    WHERE a.applicant_id IN (
      SELECT p.id FROM public.profiles p
      WHERE p.licensee_id IN (
        SELECT public.ppoc_mapped_licensee_ids(c.uid)
      )
    )
  )
  SELECT
    a.id AS application_id,
    ((a.data->>'renewal_of_license_id')::uuid) AS license_id,
    a.status::text AS status,
    (a.status::text = ANY (ARRAY['submitted','under_review','query_raised','resubmission_requested'])) AS is_pending,
    (a.status::text = ANY (ARRAY['draft','in_progress'])) AS is_in_progress
  FROM public.applications a
  WHERE a.id IN (SELECT id FROM scoped_app_ids)
    AND (a.data->>'is_renewal') = 'true'
    AND (a.data->>'renewal_of_license_id') IS NOT NULL
    AND ((a.data->>'renewal_of_license_id')::uuid) = ANY (license_ids)
    AND a.status::text = ANY (ARRAY['draft','in_progress','submitted','under_review','query_raised','resubmission_requested']);
$function$
;
CREATE OR REPLACE FUNCTION public.get_my_licenses_page(_page integer, _page_size integer, _search text DEFAULT NULL::text, _status text DEFAULT NULL::text, _sort_by text DEFAULT 'created_at'::text, _sort_dir text DEFAULT 'desc'::text, _licensee_id uuid DEFAULT NULL::uuid, _sector_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, license_number text, license_type text, holder_id uuid, status text, issued_at timestamp with time zone, valid_from timestamp with time zone, valid_until timestamp with time zone, conditions text, created_at timestamp with time zone, application_id uuid, sector_id uuid, resolved_sector_id uuid, total_count bigint)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_internal boolean;
  v_page_size int := GREATEST(1, LEAST(COALESCE(_page_size, 50), 200));
  v_offset int := GREATEST(0, COALESCE(_page, 0)) * v_page_size;
  v_search text := NULLIF(trim(coalesce(_search, '')), '');
  v_status text := NULLIF(_status, 'all');
  v_sort text := lower(coalesce(_sort_by, 'created_at'));
  v_dir text := lower(coalesce(_sort_dir, 'desc'));
  v_self_licensee_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_is_internal := public.has_role(v_uid, 'super_admin'::app_role)
                OR public.has_role(v_uid, 'admin'::app_role)
                OR public.has_role(v_uid, 'supervisor'::app_role)
                OR public.has_role(v_uid, 'licensing_officer'::app_role)
                OR public.has_role(v_uid, 'analyst'::app_role);

  SELECT p.licensee_id INTO v_self_licensee_id FROM public.profiles p WHERE p.id = v_uid;

  RETURN QUERY
  WITH access_scope AS (
    SELECT DISTINCT target_licensee_id
    FROM (
      SELECT CASE
        WHEN v_is_internal AND _licensee_id IS NOT NULL THEN _licensee_id
        WHEN _licensee_id IS NOT NULL AND EXISTS (
          SELECT 1
          FROM public.ppoc_entity_mappings pem
          WHERE pem.ppoc_user_id = v_uid
            AND pem.licensee_id = _licensee_id
            AND pem.is_active = true
        ) THEN _licensee_id
        WHEN _licensee_id IS NOT NULL AND v_self_licensee_id = _licensee_id THEN _licensee_id
        WHEN _licensee_id IS NULL AND v_self_licensee_id IS NOT NULL THEN v_self_licensee_id
        ELSE NULL::uuid
      END AS target_licensee_id
    ) s
    WHERE target_licensee_id IS NOT NULL
  ),
  scoped_users AS (
    SELECT DISTINCT p.id AS user_id, p.licensee_id
    FROM access_scope sc
    JOIN public.profiles p ON p.licensee_id = sc.target_licensee_id

    UNION

    SELECT v_uid AS user_id, v_self_licensee_id
    WHERE NOT v_is_internal AND v_self_licensee_id IS NULL
  ),
  scoped_applications AS (
    SELECT DISTINCT a.id, a.applicant_id, a.data
    FROM public.applications a
    WHERE NOT v_is_internal
      AND _licensee_id IS NULL
      AND a.applicant_id = v_uid

    UNION

    SELECT DISTINCT a.id, a.applicant_id, a.data
    FROM access_scope sc
    JOIN public.applications a ON a.applicant_id IN (
      SELECT su.user_id FROM scoped_users su WHERE su.licensee_id = sc.target_licensee_id
    )

    UNION

    SELECT DISTINCT a.id, a.applicant_id, a.data
    FROM access_scope sc
    JOIN public.licensees l ON l.id = sc.target_licensee_id
    JOIN public.licenses lic ON lic.id = l.license_id
    JOIN public.applications a ON a.id = lic.application_id
  ),
  base AS (
    SELECT DISTINCT
      lic.id AS lic_id,
      lic.license_number AS lic_number,
      lic.license_type AS lic_type,
      lic.holder_id AS lic_holder_id,
      lic.status AS lic_status,
      lic.issued_at AS lic_issued_at,
      lic.valid_from AS lic_valid_from,
      lic.valid_until AS lic_valid_until,
      lic.conditions AS lic_conditions,
      lic.created_at AS lic_created_at,
      lic.application_id AS lic_application_id,
      lic.sector_id AS lic_sector_id,
      COALESCE(
        lic.sector_id,
        linked_licensee.sector_id,
        NULLIF(app.data->>'sector_id', '')::uuid
      ) AS lic_resolved_sector_id
    FROM public.licenses lic
    LEFT JOIN public.licensees linked_licensee
      ON linked_licensee.license_id = lic.id
    LEFT JOIN public.applications app
      ON app.id = lic.application_id
    WHERE
      (v_is_internal AND _licensee_id IS NULL)
      OR lic.id IN (
        SELECT l.license_id
        FROM public.licensees l
        JOIN access_scope sc ON sc.target_licensee_id = l.id
        WHERE l.license_id IS NOT NULL
      )
      OR lic.id IN (
        SELECT linked_licensee.license_id
        FROM scoped_users su
        JOIN public.licensees linked_licensee ON linked_licensee.id = su.licensee_id
        WHERE linked_licensee.license_id IS NOT NULL
      )
      OR lic.application_id IN (SELECT sa.id FROM scoped_applications sa)
      OR lic.holder_id IN (
        SELECT su.user_id FROM scoped_users su
      )
      OR lic.holder_id IN (
        SELECT sc.target_licensee_id FROM access_scope sc
      )
  ),
  filtered AS (
    SELECT *
    FROM base b
    WHERE (v_status IS NULL OR b.lic_status = v_status)
      AND (_sector_id IS NULL OR b.lic_resolved_sector_id = _sector_id)
      AND (
        v_search IS NULL
        OR lower(coalesce(b.lic_number, '')) LIKE '%' || lower(v_search) || '%'
        OR lower(coalesce(b.lic_type, '')) LIKE '%' || lower(v_search) || '%'
      )
  ),
  counted AS (
    SELECT count(*) AS total FROM filtered
  ),
  ordered AS (
    SELECT *
    FROM filtered f
    ORDER BY
      CASE WHEN v_sort = 'license_number' AND v_dir = 'asc' THEN f.lic_number END ASC,
      CASE WHEN v_sort = 'license_number' AND v_dir = 'desc' THEN f.lic_number END DESC,
      CASE WHEN v_sort = 'issued_at' AND v_dir = 'asc' THEN f.lic_issued_at END ASC NULLS LAST,
      CASE WHEN v_sort = 'issued_at' AND v_dir = 'desc' THEN f.lic_issued_at END DESC NULLS LAST,
      CASE WHEN v_sort = 'created_at' AND v_dir = 'asc' THEN f.lic_created_at END ASC,
      CASE WHEN v_sort = 'created_at' AND v_dir = 'desc' THEN f.lic_created_at END DESC,
      f.lic_created_at DESC
    LIMIT v_page_size OFFSET v_offset
  )
  SELECT
    o.lic_id,
    o.lic_number,
    o.lic_type,
    o.lic_holder_id,
    o.lic_status::text,
    o.lic_issued_at,
    o.lic_valid_from,
    o.lic_valid_until,
    o.lic_conditions,
    o.lic_created_at,
    o.lic_application_id,
    o.lic_sector_id,
    o.lic_resolved_sector_id,
    c.total
  FROM ordered o
  CROSS JOIN counted c;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_my_ppoc_mapped_entities()
 RETURNS TABLE(mapping_id uuid, licensee_id uuid, entity_name text, sector_id uuid, resolved_sector_id uuid, created_at timestamp with time zone, application_id uuid, license_number text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH my_mappings AS (
    SELECT m.id, m.licensee_id, m.created_at
    FROM public.ppoc_entity_mappings m
    WHERE m.ppoc_user_id = auth.uid()
      AND m.is_active = true
  ),
  sectors_by_mapping AS (
    SELECT s.mapping_id, array_agg(s.sector_id) AS sector_ids
    FROM public.ppoc_mapping_sectors s
    WHERE s.mapping_id IN (SELECT id FROM my_mappings)
    GROUP BY s.mapping_id
  )
  SELECT
    m.id AS mapping_id,
    l.id AS licensee_id,
    COALESCE(
      NULLIF(r.applicant_name, ''),
      NULLIF(a.data->>'applicant_name', ''),
      NULLIF(a.data->>'entity_name', ''),
      NULLIF(pl.entity_name, ''),
      NULLIF(p.entity_name, ''),
      NULLIF(l.name, ''),
      '—'
    ) AS entity_name,
    COALESCE(r.sector_id, NULLIF(a.data->>'sector_id', '')::uuid, l.sector_id) AS sector_id,
    COALESCE(l.sector_id, r.sector_id, NULLIF(a.data->>'sector_id', '')::uuid) AS resolved_sector_id,
    COALESCE(l.created_at, m.created_at) AS created_at,
    a.id AS application_id,
    lic.license_number
  FROM my_mappings m
  JOIN public.licensees l ON l.id = m.licensee_id
  LEFT JOIN public.licenses lic ON lic.id = l.license_id
  LEFT JOIN public.applications a ON a.id = lic.application_id
  LEFT JOIN public.registrations r ON r.user_id = a.applicant_id
  LEFT JOIN public.pre_license_users pl ON pl.id = a.applicant_id
  LEFT JOIN public.profiles p ON p.id = a.applicant_id
  LEFT JOIN sectors_by_mapping sms ON sms.mapping_id = m.id
  WHERE (
    sms.sector_ids IS NULL
    OR array_length(sms.sector_ids, 1) IS NULL
    OR COALESCE(l.sector_id, r.sector_id, NULLIF(a.data->>'sector_id', '')::uuid) = ANY(sms.sector_ids)
  )
  ORDER BY COALESCE(l.created_at, m.created_at),
           COALESCE(
             NULLIF(r.applicant_name, ''),
             NULLIF(a.data->>'applicant_name', ''),
             NULLIF(a.data->>'entity_name', ''),
             NULLIF(pl.entity_name, ''),
             NULLIF(p.entity_name, ''),
             NULLIF(l.name, ''),
             '—'
           );
$function$
;
CREATE OR REPLACE FUNCTION public.get_permission_dependencies()
 RETURNS TABLE(action text, requires text)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT unnest(ARRAY[
    'edit','create','delete','approve','reject','export',
    'download','upload','import','publish','archive','restore','assign'
  ])::text AS action,
  'view'::text AS requires;
$function$
;
CREATE OR REPLACE FUNCTION public.get_public_complaint_tracking(p_reference text, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_c record;
  v_caller uuid;
  v_caller_email text;
  v_has_staff_tracking_override boolean := false;
  v_allowed boolean := false;
BEGIN
  IF p_reference IS NULL OR length(trim(p_reference)) < 4 THEN
    RETURN jsonb_build_object('found', false, 'error', 'REFERENCE_REQUIRED');
  END IF;

  SELECT id, complainant_id, email INTO v_c
    FROM public.complaints
   WHERE complaint_number = trim(p_reference)
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('found', false, 'error', 'AUTH_REQUIRED');
  END IF;

  SELECT lower(btrim(u.email)) INTO v_caller_email
    FROM auth.users u
   WHERE u.id = v_caller;

  SELECT
    EXISTS (
      SELECT 1
      FROM public.user_roles ur
      WHERE ur.user_id = v_caller
        AND ur.role IN (
          'super_admin'::public.app_role,
          'admin'::public.app_role,
          'supervisor'::public.app_role,
          'licensing_officer'::public.app_role,
          'analyst'::public.app_role,
          'legal_compliance'::public.app_role,
          'developer'::public.app_role
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.user_dynamic_roles udr
      JOIN public.roles r ON r.id = udr.role_id
      WHERE udr.user_id = v_caller
        AND r.role_type = 'internal'
        AND COALESCE(r.system_role, '') NOT IN (
          'applicant',
          'pre_licensee',
          'licensee_primary',
          'licensee_secondary'
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = v_caller
        AND (
          p.role IN ('super_admin', 'admin', 'supervisor', 'licensing_officer', 'analyst', 'legal_compliance', 'developer')
          OR p.user_type = 'employee'
        )
    )
  INTO v_has_staff_tracking_override;

  v_allowed :=
       (v_c.complainant_id IS NOT NULL AND v_c.complainant_id = v_caller)
    OR (v_caller_email IS NOT NULL AND v_c.email IS NOT NULL AND btrim(v_c.email) <> ''
        AND lower(btrim(v_c.email)) = v_caller_email)
    OR (v_has_staff_tracking_override AND public.has_complaint_perm(v_caller, 'view'));

  IF NOT v_allowed THEN
    RETURN jsonb_build_object('found', false, 'error', 'CONTACT_MISMATCH');
  END IF;

  RETURN public.get_public_complaint_tracking_raw(p_reference, v_c.email);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_public_complaint_tracking_raw(p_reference text, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_c record;
  v_status record;
  v_timeline jsonb := '[]'::jsonb;
  v_steps jsonb := '[]'::jsonb;
  v_actions jsonb := '[]'::jsonb;
  v_corr jsonb := '[]'::jsonb;
  v_details jsonb;
  v_investigation jsonb;
  v_is_owner boolean := false;
  v_wi record;
  v_current_order int;
  v_status_key text;
  v_status_order int;
  v_effective_order int;
  v_terminal boolean := false;
  v_tasks_total int := 0;
  v_tasks_done int := 0;
  v_inv_status text;
  v_synth jsonb := '[]'::jsonb;
  v_branch_keys text[] := ARRAY['enforcement','notice_issued','response_received','payment','appeal','withdrawn'];
BEGIN
  IF p_reference IS NULL OR length(trim(p_reference)) < 4 THEN
    RETURN jsonb_build_object('found', false, 'error', 'REFERENCE_REQUIRED');
  END IF;

  SELECT * INTO v_c
    FROM public.complaints
   WHERE complaint_number = trim(p_reference)
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  v_is_owner := auth.uid() IS NOT NULL AND v_c.complainant_id = auth.uid();

  IF NOT v_is_owner AND v_c.email IS NOT NULL AND btrim(v_c.email) <> '' THEN
    IF p_email IS NULL OR lower(btrim(p_email)) <> lower(btrim(v_c.email)) THEN
      RETURN jsonb_build_object('found', false, 'error', 'CONTACT_MISMATCH');
    END IF;
  END IF;

  SELECT public_label, public_description, is_terminal
    INTO v_status
    FROM public.complaint_status_catalogue
   WHERE code = v_c.status;

  v_terminal := v_c.status IN ('resolved','closed','rejected','duplicate')
                OR v_c.closed_at IS NOT NULL;

  -- Public, plain-English history built from audit events (whitelisted) plus
  -- any workflow actions. Nothing internal (notes, assignments, actors) leaks.
  WITH audit_events AS (
    SELECT
      a.created_at AS event_at,
      CASE lower(a.action)
        WHEN 'complaint_created' THEN 'Complaint received'
        WHEN 'complaint.created' THEN 'Complaint received'
        WHEN 'licensee_linked' THEN 'Matched to the firm concerned'
        WHEN 'complaint.investigation_started' THEN 'Review started'
        WHEN 'complaint_under_investigation' THEN 'Review started'
        WHEN 'complaint.task_created' THEN 'Review activity progressed'
        WHEN 'complaint.task_in_progress' THEN 'Review activity progressed'
        WHEN 'complaint.task_completed' THEN 'Review activity progressed'
        WHEN 'complaint.severity_set' THEN 'Complaint assessed'
        WHEN 'complaint_triage_retry' THEN 'Complaint assessed'
        WHEN 'rule_override' THEN 'Complaint assessed'
        WHEN 'complaint.escalated_to_enforcement' THEN 'Referred for enforcement'
        WHEN 'complaint.resolved' THEN 'Resolution reached'
        WHEN 'complaint_resolved' THEN 'Resolution reached'
        WHEN 'complaint_closed' THEN 'Complaint closed'
        WHEN 'complaint.closed' THEN 'Complaint closed'
        WHEN 'complaint_rejected' THEN 'Complaint not accepted'
        ELSE NULL
      END AS label,
      CASE lower(a.action)
        WHEN 'complaint_created' THEN 'We received your complaint and issued your reference number.'
        WHEN 'complaint.created' THEN 'We received your complaint and issued your reference number.'
        WHEN 'licensee_linked' THEN 'Your complaint was matched to the firm it concerns.'
        WHEN 'complaint.investigation_started' THEN 'A review of your complaint has begun.'
        WHEN 'complaint_under_investigation' THEN 'A review of your complaint has begun.'
        WHEN 'complaint.task_created' THEN 'Our team is working through the review activities.'
        WHEN 'complaint.task_in_progress' THEN 'Our team is working through the review activities.'
        WHEN 'complaint.task_completed' THEN 'A review activity was completed.'
        WHEN 'complaint.severity_set' THEN 'Your complaint was assessed and prioritised.'
        WHEN 'complaint_triage_retry' THEN 'Your complaint was assessed and prioritised.'
        WHEN 'rule_override' THEN 'Your complaint was assessed and prioritised.'
        WHEN 'complaint.escalated_to_enforcement' THEN 'Your complaint was referred for enforcement action.'
        WHEN 'complaint.resolved' THEN 'A resolution has been reached for your complaint.'
        WHEN 'complaint_resolved' THEN 'A resolution has been reached for your complaint.'
        WHEN 'complaint_closed' THEN 'Your complaint file has been closed.'
        WHEN 'complaint.closed' THEN 'Your complaint file has been closed.'
        WHEN 'complaint_rejected' THEN 'Your complaint was not accepted for investigation.'
        ELSE NULL
      END AS description,
      CASE WHEN lower(a.action) IN (
        'complaint_created','complaint.created',
        'complaint.investigation_started','complaint_under_investigation',
        'complaint.escalated_to_enforcement',
        'complaint.resolved','complaint_resolved',
        'complaint_closed','complaint.closed','complaint_rejected'
      ) THEN true ELSE false END AS is_decision
    FROM public.audit_logs a
   WHERE a.entity_type IN ('complaint','complaints')
     AND a.entity_id::text = v_c.id::text
  ),
  wf_events AS (
    SELECT
      aa.created_at AS event_at,
      COALESCE(cs.public_label,
        initcap(replace(COALESCE(aa.action_type, aa.action, 'update'), '_', ' '))) AS label,
      COALESCE(cs.public_description, 'Your complaint has been updated.') AS description,
      false AS is_decision
    FROM public.workflow_instances wi
    JOIN public.approval_actions aa ON aa.workflow_instance_id = wi.id
    LEFT JOIN public.complaint_status_catalogue cs
      ON cs.code = COALESCE(aa.action_type, aa.action)
    WHERE wi.entity_type = 'complaint' AND wi.entity_id::text = v_c.id::text
  ),
  -- Lifecycle milestones from the complaint record itself, so a resolved or
  -- closed complaint always shows those dates even when no audit row exists.
  synth AS (
    SELECT * FROM (
      VALUES
        (v_c.created_at, 'Complaint received',
         'We received your complaint and issued your reference number.', true),
        (v_c.resolved_at, 'Resolution reached',
         'A resolution has been reached for your complaint.', true),
        (v_c.closed_at,
         CASE WHEN v_c.status = 'rejected' THEN 'Complaint not accepted' ELSE 'Complaint closed' END,
         CASE WHEN v_c.status = 'rejected'
              THEN 'Your complaint was not accepted for investigation.'
              ELSE 'Your complaint file has been closed.' END, true)
    ) AS t(event_at, label, description, is_decision)
    WHERE t.event_at IS NOT NULL
  ),
  combined AS (
    SELECT * FROM audit_events WHERE label IS NOT NULL
    UNION ALL
    SELECT * FROM wf_events
    UNION ALL
    SELECT s.* FROM synth s
    WHERE NOT EXISTS (
      SELECT 1 FROM audit_events ae WHERE ae.label = s.label
    )
  ),
  merged AS (
    SELECT DISTINCT ON (label, date_trunc('second', event_at))
           event_at, label, description, is_decision
      FROM combined
     ORDER BY label, date_trunc('second', event_at), event_at
  )
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'event_at', m.event_at, 'label', m.label, 'description', m.description
    ) ORDER BY m.event_at), '[]'::jsonb),
    COALESCE(jsonb_agg(jsonb_build_object(
      'at', m.event_at, 'action', m.label, 'step', m.description
    ) ORDER BY m.event_at) FILTER (WHERE m.is_decision), '[]'::jsonb)
  INTO v_timeline, v_actions
  FROM merged m;

  -- Latest workflow instance for the complaint (progress steps)
  SELECT wi.id, wi.workflow_id, wi.current_step_key, wi.current_step_id, wi.status
    INTO v_wi
    FROM public.workflow_instances wi
   WHERE wi.entity_type = 'complaint' AND wi.entity_id::text = v_c.id::text
   ORDER BY wi.created_at DESC
   LIMIT 1;

  IF v_wi.id IS NOT NULL THEN
    SELECT s.step_order INTO v_current_order
      FROM public.approval_steps s
     WHERE s.workflow_id = v_wi.workflow_id
       AND (s.id = v_wi.current_step_id OR s.step_key = v_wi.current_step_key)
     LIMIT 1;
  END IF;

  -- Milestone derived from the complaint's own status: the workflow instance
  -- can be stale (no current step), but the complaint status is authoritative.
  v_status_key := CASE v_c.status
    WHEN 'submitted' THEN 'triage'
    WHEN 'under_investigation' THEN 'investigation'
    WHEN 'resolved' THEN 'resolved'
    WHEN 'closed' THEN 'closed'
    WHEN 'rejected' THEN 'closed'
    WHEN 'duplicate' THEN 'closed'
    ELSE 'filed'
  END;

  IF v_wi.id IS NOT NULL THEN
    SELECT s.step_order INTO v_status_order
      FROM public.approval_steps s
     WHERE s.workflow_id = v_wi.workflow_id AND s.step_key = v_status_key
     LIMIT 1;

    v_effective_order := GREATEST(COALESCE(v_status_order, 0), COALESCE(v_current_order, 0));

    SELECT COALESCE(jsonb_agg(x ORDER BY (x->>'order')::int), '[]'::jsonb)
      INTO v_steps
      FROM (
        SELECT jsonb_build_object(
                 'key', COALESCE(s.step_key, s.id::text),
                 'label', COALESCE(NULLIF(btrim(s.public_label), ''),
                                   NULLIF(btrim(s.name), ''),
                                   initcap(replace(COALESCE(s.step_key, 'step'), '_', ' '))),
                 'order', s.step_order,
                 'is_current', (NOT v_terminal
                                AND v_effective_order > 0
                                AND s.step_order = v_effective_order
                                AND COALESCE(v_wi.status, '') <> 'completed'),
                 'is_complete', (v_effective_order > 0 AND s.step_order < v_effective_order)
                                OR (v_terminal AND s.step_order <= v_effective_order)
                                OR (v_wi.status = 'completed'),
                 'is_terminal', COALESCE(s.is_terminal, false)
               ) AS x
          FROM public.approval_steps s
         WHERE s.workflow_id = v_wi.workflow_id
           AND COALESCE(s.complainant_visible, true)
           -- Branch-only stages are hidden unless the workflow actually reached them.
           AND (NOT (s.step_key = ANY (v_branch_keys))
                OR COALESCE(v_current_order, 0) >= s.step_order)
           -- Never advertise terminal outcomes the complaint did not take.
           AND (NOT COALESCE(s.is_terminal, false)
                OR NOT v_terminal
                OR s.step_key = v_status_key)
      ) q;
  ELSE
    -- No workflow instance: synthesise a simple milestone list from the status.
    v_status_order := CASE v_status_key
      WHEN 'filed' THEN 10 WHEN 'triage' THEN 20
      WHEN 'investigation' THEN 30 WHEN 'resolved' THEN 90 ELSE 95 END;
    v_effective_order := v_status_order;

    SELECT COALESCE(jsonb_agg(x ORDER BY (x->>'order')::int), '[]'::jsonb)
      INTO v_steps
      FROM (
        SELECT jsonb_build_object(
                 'key', t.key,
                 'label', t.label,
                 'order', t.ord,
                 'is_current', (NOT v_terminal AND t.ord = v_effective_order),
                 'is_complete', t.ord < v_effective_order OR (v_terminal AND t.ord <= v_effective_order),
                 'is_terminal', t.ord >= 90
               ) AS x
          FROM (VALUES
                  ('filed','Complaint received',10),
                  ('triage','Assessment',20),
                  ('investigation','Review',30),
                  ('resolved','Resolved',90),
                  ('closed','Closed',95)
               ) AS t(key,label,ord)
         WHERE t.ord < 90
            OR (v_status_key = 'resolved' AND t.ord = 90)
            OR (v_status_key = 'closed' AND t.ord = 95)
      ) q;
  END IF;

  SELECT count(*), count(*) FILTER (WHERE status = 'completed')
    INTO v_tasks_total, v_tasks_done
    FROM public.complaint_investigation_tasks
   WHERE complaint_id = v_c.id;

  v_inv_status := CASE
    WHEN v_c.resolved_at IS NOT NULL OR v_c.closed_at IS NOT NULL THEN 'Completed'
    WHEN v_c.status = 'under_investigation'
      OR v_c.investigator_id IS NOT NULL
      OR v_tasks_total > 0 THEN 'In progress'
    ELSE 'Not yet started'
  END;

  v_investigation := jsonb_build_object(
    'started', v_inv_status <> 'Not yet started',
    'status_label', v_inv_status,
    'tasks_total', v_tasks_total,
    'tasks_completed', v_tasks_done,
    'findings', CASE WHEN v_c.resolved_at IS NOT NULL OR v_c.closed_at IS NOT NULL
                     THEN NULLIF(btrim(COALESCE(v_c.findings, '')), '') END,
    'outcome', CASE WHEN v_c.resolved_at IS NOT NULL OR v_c.closed_at IS NOT NULL
                    THEN NULLIF(btrim(COALESCE(v_c.resolution, '')), '') END,
    'closure_reason', CASE WHEN v_c.closed_at IS NOT NULL
                           THEN NULLIF(btrim(COALESCE(v_c.closure_reason, '')), '') END
  );

  SELECT jsonb_build_object(
           'description', v_c.description,
           'type', (SELECT name FROM public.complaint_types WHERE id = v_c.complaint_type_id),
           'channel', (SELECT name FROM public.conduct_channels WHERE id = v_c.channel_id),
           'product', (SELECT name FROM public.conduct_products WHERE id = v_c.product_id),
           'entity', (SELECT name FROM public.licensees WHERE id = v_c.licensee_id),
           'acknowledged_at', v_c.acknowledged_at,
           'intake_source', v_c.intake_source
         )
    INTO v_details;

  IF v_is_owner THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'at', cc.created_at, 'subject', cc.subject, 'body', cc.body
           ) ORDER BY cc.created_at DESC), '[]'::jsonb)
      INTO v_corr
      FROM public.complaint_correspondence cc
     WHERE cc.complaint_id = v_c.id
       AND lower(COALESCE(cc.direction, 'outbound')) = 'outbound';
  END IF;

  RETURN jsonb_build_object(
    'found', true,
    'is_owner', v_is_owner,
    'reference', v_c.complaint_number,
    'subject', v_c.subject,
    'submitted_at', v_c.created_at,
    'updated_at', v_c.updated_at,
    'resolved_at', v_c.resolved_at,
    'closed_at', v_c.closed_at,
    'status', jsonb_build_object(
      'label', COALESCE(v_status.public_label, 'In progress'),
      'description', COALESCE(v_status.public_description, ''),
      'terminal', COALESCE(v_status.is_terminal, v_terminal)
    ),
    'details', v_details,
    'steps', v_steps,
    'actions', v_actions,
    'investigation', v_investigation,
    'correspondence', v_corr,
    'timeline', COALESCE(v_timeline, '[]'::jsonb)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_registration_reviewer_remarks(_registration_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner uuid;
  v_caller uuid := auth.uid();
  v_remark text;
BEGIN
  IF v_caller IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT user_id INTO v_owner FROM public.registrations WHERE id = _registration_id;
  IF v_owner IS NULL THEN
    RETURN NULL;
  END IF;

  -- Authorize: owner or internal staff
  IF v_owner <> v_caller
     AND NOT public.has_role(v_caller, 'super_admin')
     AND NOT public.has_role(v_caller, 'admin')
     AND NOT public.has_role(v_caller, 'supervisor')
     AND NOT public.has_role(v_caller, 'licensing_officer')
     AND NOT public.has_role(v_caller, 'analyst') THEN
    RETURN NULL;
  END IF;

  SELECT aa.comments INTO v_remark
    FROM public.approval_actions aa
   WHERE aa.entity_type = 'registration'
     AND aa.entity_id = _registration_id
     AND aa.actor_id IS DISTINCT FROM v_owner
     AND aa.action_type IN ('request_resubmission','return_for_correction','request_more_info','reject','send_back','approve','escalate','remark')
     AND nullif(trim(aa.comments), '') IS NOT NULL
   ORDER BY aa.created_at DESC
   LIMIT 1;

  RETURN v_remark;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_return_revisions(_return_id uuid)
 RETURNS SETOF return_data_revisions
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT rdr.*
  FROM public.return_data_revisions rdr
  WHERE rdr.return_id = _return_id
    AND public.can_view_return_filed(auth.uid(), rdr.return_id)
  ORDER BY rdr.revision_number ASC;
$function$
;
CREATE OR REPLACE FUNCTION public.get_review_role_display(_regulator_id uuid)
 RETURNS TABLE(role_id uuid, color text, show_reviewer_name boolean, show_role_name boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT ON (d.role_id)
         d.role_id, d.color, d.show_reviewer_name, d.show_role_name
    FROM public.review_role_display_settings d
   WHERE d.regulator_id = _regulator_id OR d.regulator_id IS NULL
   ORDER BY d.role_id, (d.regulator_id IS NULL); -- non-null (regulator-specific) first
$function$
;
CREATE OR REPLACE FUNCTION public.get_user_role(_user_id uuid)
 RETURNS app_role
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT role FROM public.user_roles WHERE user_id = _user_id
  ORDER BY CASE role
    WHEN 'super_admin' THEN 1 WHEN 'admin' THEN 2 WHEN 'supervisor' THEN 3
    WHEN 'licensing_officer' THEN 4 WHEN 'analyst' THEN 5 WHEN 'developer' THEN 6
    WHEN 'licensee_primary' THEN 7 WHEN 'licensee_secondary' THEN 8
    WHEN 'pre_licensee' THEN 9 WHEN 'applicant' THEN 10
  END LIMIT 1
$function$
;
CREATE OR REPLACE FUNCTION public.group_consolidated_recompute(_group_id uuid, _period_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_method public.group_consolidation_methods;
  v_matrix jsonb;
  v_ratios jsonb := '[]'::jsonb;
  v_elim jsonb;
  v_elim_total numeric := 0;
  v_members int := 0;
  v_base numeric;
  v_uplift numeric := 0;
  v_score numeric;
  v_band text;
  v_components jsonb;
  v_large int := 0;
  v_circ int := 0;
  v_high int := 0;
BEGIN
  IF NOT public.can_manage_financial_group(auth.uid()) THEN
    RAISE EXCEPTION 'not authorised to recompute group consolidation';
  END IF;

  SELECT * INTO v_method FROM public.group_consolidation_methods
   WHERE group_id = _group_id AND is_active ORDER BY version DESC LIMIT 1;

  SELECT COUNT(*) INTO v_members FROM public.financial_group_members
   WHERE group_id = _group_id AND consolidation_treatment <> 'excluded';

  v_matrix := public.intragroup_exposure_matrix(_group_id, _period_key);
  v_large := jsonb_array_length(v_matrix->'large_exposures');
  v_circ := jsonb_array_length(v_matrix->'circular_chains');

  -- eliminations restricted to configured exposure types
  SELECT COALESCE(SUM(amount),0) INTO v_elim_total
  FROM public.intragroup_exposures
  WHERE group_id = _group_id AND period_key = _period_key
    AND exposure_type = ANY (COALESCE(v_method.eliminate_exposure_types, ARRAY['loan','deposit','capital']::text[]));

  SELECT jsonb_build_object(
           'total', v_elim_total,
           'types', COALESCE(v_method.eliminate_exposure_types, ARRAY['loan','deposit','capital']::text[]),
           'by_type', COALESCE(v_matrix->'by_type', '{}'::jsonb))
    INTO v_elim;

  -- consolidated ratios
  WITH mr AS (
    SELECT r.*, m.consolidation_treatment, COALESCE(m.ownership_percentage, 100) AS own_pct
    FROM public.group_member_ratios(_group_id, _period_key) r
    JOIN public.financial_group_members m
      ON m.licensee_id = r.licensee_id AND m.group_id = _group_id
  ), rules AS (
    SELECT (x->>'ratio_key') AS ratio_key, COALESCE(x->>'method','') AS method,
           COALESCE((x->>'eliminate')::boolean, false) AS eliminate
    FROM jsonb_array_elements(COALESCE(v_method.ratio_rules, '[]'::jsonb)) x
  ), agg AS (
    SELECT mr.ratio_key,
           MAX(mr.label) AS label,
           MAX(mr.display_format) AS display_format,
           COUNT(mr.value) AS contributors,
           SUM(mr.value * CASE WHEN mr.consolidation_treatment = 'proportional' THEN mr.own_pct/100.0 ELSE 1 END) AS sum_value,
           CASE WHEN SUM(CASE WHEN mr.value IS NULL THEN 0 ELSE mr.own_pct END) > 0
                THEN SUM(COALESCE(mr.value,0) * mr.own_pct) / SUM(CASE WHEN mr.value IS NULL THEN 0 ELSE mr.own_pct END)
                ELSE NULL END AS wavg_value,
           COALESCE(MAX(ru.method), '') AS rule_method,
           COALESCE(BOOL_OR(ru.eliminate), false) AS rule_eliminate
    FROM mr LEFT JOIN rules ru ON ru.ratio_key = mr.ratio_key
    GROUP BY mr.ratio_key
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'ratio_key', ratio_key,
    'label', COALESCE(label, ratio_key),
    'display_format', display_format,
    'method', eff_method,
    'contributors', contributors,
    'gross_value', gross,
    'eliminated', CASE WHEN rule_eliminate THEN v_elim_total ELSE 0 END,
    'value', CASE WHEN rule_eliminate AND gross IS NOT NULL THEN gross - v_elim_total ELSE gross END
  ) ORDER BY ratio_key), '[]'::jsonb) INTO v_ratios
  FROM (
    SELECT a.*,
      CASE WHEN a.rule_method <> '' THEN a.rule_method
           WHEN a.display_format IN ('percent','ratio') THEN 'weighted_avg'
           ELSE 'sum' END AS eff_method,
      CASE WHEN (CASE WHEN a.rule_method <> '' THEN a.rule_method
                      WHEN a.display_format IN ('percent','ratio') THEN 'weighted_avg'
                      ELSE 'sum' END) = 'sum'
           THEN a.sum_value ELSE a.wavg_value END AS gross
    FROM agg a
  ) z;

  INSERT INTO public.group_consolidated_snapshots (group_id, period_key, ratios, eliminations, member_count, methodology_version, computed_at, computed_by)
  VALUES (_group_id, _period_key, v_ratios, v_elim, v_members, v_method.version, now(), auth.uid())
  ON CONFLICT (group_id, period_key) DO UPDATE
    SET ratios = EXCLUDED.ratios, eliminations = EXCLUDED.eliminations,
        member_count = EXCLUDED.member_count, methodology_version = EXCLUDED.methodology_version,
        computed_at = now(), computed_by = auth.uid();

  -- group score from member risk scores
  SELECT AVG(s.score) INTO v_base
  FROM public.financial_group_members m
  JOIN public.entity_risk_scores s ON s.entity_id = m.licensee_id AND s.is_current
  WHERE m.group_id = _group_id AND m.consolidation_treatment <> 'excluded';

  SELECT COUNT(*) INTO v_high
  FROM public.financial_group_members m
  JOIN public.entity_risk_scores s ON s.entity_id = m.licensee_id AND s.is_current
  WHERE m.group_id = _group_id AND s.band IN ('high','critical');

  v_uplift := LEAST(15, 5 * v_large + CASE WHEN v_circ > 0 THEN 10 ELSE 0 END);
  v_score := LEAST(100, ROUND(COALESCE(v_base, 0) + v_uplift, 2));
  v_band := CASE WHEN v_score >= 75 THEN 'critical' WHEN v_score >= 50 THEN 'high'
                 WHEN v_score >= 25 THEN 'medium' ELSE 'low' END;

  v_components := jsonb_build_object(
    'member_score_average', v_base,
    'members_scored', (SELECT COUNT(*) FROM public.financial_group_members m
                        JOIN public.entity_risk_scores s ON s.entity_id = m.licensee_id AND s.is_current
                       WHERE m.group_id = _group_id),
    'members_total', v_members,
    'members_high_or_critical', v_high,
    'large_exposures', v_large,
    'circular_chains', v_circ,
    'contagion_uplift', v_uplift,
    'base_available', v_base IS NOT NULL
  );

  INSERT INTO public.group_risk_scores (group_id, period_key, score, band, components, is_current, computed_at, computed_by)
  VALUES (_group_id, _period_key, v_score, v_band, v_components, true, now(), auth.uid())
  ON CONFLICT (group_id, period_key) DO UPDATE
    SET score = EXCLUDED.score, band = EXCLUDED.band, components = EXCLUDED.components,
        is_current = true, computed_at = now(), computed_by = auth.uid();

  UPDATE public.group_risk_scores SET is_current = false
   WHERE group_id = _group_id AND period_key <> _period_key AND is_current;

  PERFORM public.group_ewi_evaluate(_group_id, _period_key);

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
  VALUES (auth.uid(), 'GROUP_CONSOLIDATED_RECOMPUTED', 'financial_group', _group_id::text,
          jsonb_build_object('period_key', _period_key, 'score', v_score, 'band', v_band));

  RETURN jsonb_build_object('ok', true, 'period_key', _period_key, 'ratios', v_ratios,
                            'eliminations', v_elim, 'score', v_score, 'band', v_band,
                            'components', v_components, 'matrix', v_matrix);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.group_data_coverage(_group_id uuid, _period_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total int := 0;
  v_missing jsonb := '[]'::jsonb;
  v_missing_count int := 0;
BEGIN
  SELECT COUNT(*) INTO v_total
    FROM public.financial_group_members m
   WHERE m.group_id = _group_id AND m.consolidation_treatment <> 'excluded'
     AND (m.end_date IS NULL OR m.end_date >= CURRENT_DATE);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'licensee_id', m.licensee_id,
           'name', l.name,
           'reason', 'no_return_data_for_period')), '[]'::jsonb),
         COUNT(*)
    INTO v_missing, v_missing_count
    FROM public.financial_group_members m
    JOIN public.licensees l ON l.id = m.licensee_id
   WHERE m.group_id = _group_id AND m.consolidation_treatment <> 'excluded'
     AND (m.end_date IS NULL OR m.end_date >= CURRENT_DATE)
     AND NOT EXISTS (
       SELECT 1 FROM public.returns_filed rf
        JOIN public.return_calculated_ratios rcr ON rcr.return_id = rf.id
       WHERE rf.entity_id = m.licensee_id
         AND rf.return_year = NULLIF(split_part(_period_key,'-',1),'')::int
         AND rf.return_period = split_part(_period_key,'-',2));

  RETURN jsonb_build_object(
    'members_total', v_total,
    'members_missing', v_missing_count,
    'members_with_data', GREATEST(v_total - v_missing_count, 0),
    'excluded_members', v_missing,
    'data_state', CASE
      WHEN v_total = 0 OR v_missing_count >= v_total THEN 'NO_GROUP_DATA'
      WHEN v_missing_count > 0 THEN 'PARTIAL_GROUP_DATA'
      ELSE 'COMPLETE_GROUP_DATA' END);
END $function$
;
CREATE OR REPLACE FUNCTION public.group_ewi_evaluate(_group_id uuid, _period_key text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r public.group_ewi_rules;
  v_fired int := 0;
  v_high int := 0;
  v_matrix jsonb;
  v_period text := COALESCE(_period_key, (SELECT period_key FROM public.group_risk_scores WHERE group_id = _group_id ORDER BY computed_at DESC LIMIT 1));
  v_hit boolean;
  v_details jsonb;
BEGIN
  FOR r IN SELECT * FROM public.group_ewi_rules WHERE is_active LOOP
    v_hit := false; v_details := '{}'::jsonb;

    IF r.condition->>'type' = 'member_band_count' THEN
      SELECT COUNT(*) INTO v_high
      FROM public.financial_group_members m
      JOIN public.entity_risk_scores s ON s.entity_id = m.licensee_id AND s.is_current
      WHERE m.group_id = _group_id
        AND s.band = ANY (ARRAY(SELECT jsonb_array_elements_text(r.condition->'band_in')));
      IF v_high >= COALESCE((r.condition->>'min_count')::int, 2) THEN
        v_hit := true;
        v_details := jsonb_build_object('members_matching', v_high);
      END IF;

    ELSIF r.condition->>'type' IN ('large_exposure','circular_exposure') THEN
      IF v_period IS NOT NULL THEN
        v_matrix := public.intragroup_exposure_matrix(_group_id, v_period);
        IF r.condition->>'type' = 'large_exposure' AND jsonb_array_length(v_matrix->'large_exposures') > 0 THEN
          v_hit := true;
          v_details := jsonb_build_object('count', jsonb_array_length(v_matrix->'large_exposures'),
                                          'threshold', v_matrix->'large_exposure_threshold',
                                          'basis', v_matrix->'large_exposure_basis');
        ELSIF r.condition->>'type' = 'circular_exposure' AND jsonb_array_length(v_matrix->'circular_chains') > 0 THEN
          v_hit := true;
          v_details := jsonb_build_object('chains', v_matrix->'circular_chains');
        END IF;
      END IF;
    END IF;

    IF v_hit THEN
      IF NOT EXISTS (SELECT 1 FROM public.group_ewi_alerts a
                      WHERE a.group_id = _group_id AND a.rule_code = r.code AND a.status = 'open') THEN
        INSERT INTO public.group_ewi_alerts (group_id, rule_code, rule_name, severity, details)
        VALUES (_group_id, r.code, r.name, r.severity, v_details || jsonb_build_object('period_key', v_period));
        v_fired := v_fired + 1;
        INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
        VALUES (auth.uid(), 'GROUP_EWI_FIRED', 'financial_group', _group_id::text,
                jsonb_build_object('rule_code', r.code, 'details', v_details));
      ELSE
        UPDATE public.group_ewi_alerts
           SET details = v_details || jsonb_build_object('period_key', v_period)
         WHERE group_id = _group_id AND rule_code = r.code AND status = 'open';
      END IF;
    ELSE
      UPDATE public.group_ewi_alerts SET status = 'closed'
       WHERE group_id = _group_id AND rule_code = r.code AND status = 'open';
    END IF;
  END LOOP;

  RETURN v_fired;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.group_member_ratios(_group_id uuid, _period_key text)
 RETURNS TABLE(licensee_id uuid, ratio_key text, label text, display_format text, value numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT ON (m.licensee_id, r.ratio_key)
         m.licensee_id, r.ratio_key, r.label, r.display_format, r.value
  FROM public.financial_group_members m
  JOIN public.returns_filed rf ON rf.entity_id = m.licensee_id
   AND rf.return_year = NULLIF(split_part(_period_key,'-',1),'')::int
   AND rf.return_period = split_part(_period_key,'-',2)
  JOIN public.return_calculated_ratios r ON r.return_id = rf.id
  WHERE m.group_id = _group_id
    AND m.consolidation_treatment <> 'excluded'
    AND (m.end_date IS NULL OR m.end_date >= CURRENT_DATE)
  ORDER BY m.licensee_id, r.ratio_key, r.computed_at DESC;
$function$
;
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  requested_role text;
  requested_user_type text;
  bootstrap_email text;
  resolved_role app_role;
  is_internal_role boolean := false;
  is_internal_admin_created boolean := false;
BEGIN
  requested_role := COALESCE(NEW.raw_user_meta_data->>'role', 'applicant');
  requested_user_type := NEW.raw_user_meta_data->>'user_type';

  BEGIN
    is_internal_role := (requested_role::app_role) NOT IN (
      'applicant'::app_role,
      'pre_licensee'::app_role,
      'licensee_primary'::app_role,
      'licensee_secondary'::app_role
    );
  EXCEPTION WHEN OTHERS THEN
    is_internal_role := false;
  END;

  is_internal_admin_created :=
    requested_user_type = 'employee'
    OR is_internal_role;

  IF requested_role = 'pre_licensee' THEN
    INSERT INTO public.pre_license_users (id, full_name, email, entity_name)
    VALUES (NEW.id,
            COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),
            COALESCE(NEW.email, ''),
            COALESCE(NEW.raw_user_meta_data->>'entity_name', ''));
  ELSE
    INSERT INTO public.profiles (id, full_name, email, user_type, entity_name, role)
    VALUES (NEW.id,
            COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),
            COALESCE(NEW.email, ''),
            COALESCE((NEW.raw_user_meta_data->>'user_type')::public.user_type, 'primary'),
            COALESCE(NEW.raw_user_meta_data->>'entity_name', ''),
            CASE
              WHEN is_internal_admin_created AND is_internal_role
                THEN requested_role::app_role
              WHEN requested_role IN ('applicant','pre_licensee')
                THEN requested_role::app_role
              ELSE 'applicant'::app_role
            END);
  END IF;

  SELECT trim(both '"' from value::text)
    INTO bootstrap_email
    FROM public.site_settings
   WHERE key = 'super_admin_bootstrap_email'
   LIMIT 1;

  IF bootstrap_email IS NOT NULL
     AND length(bootstrap_email) > 0
     AND lower(bootstrap_email) = lower(COALESCE(NEW.email, '')) THEN
    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'super_admin'::app_role);
    INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
    VALUES (NEW.id, 'bootstrap_super_admin_assigned', 'user', NEW.id::text,
            jsonb_build_object('email', NEW.email));
  ELSIF is_internal_admin_created THEN
    NULL;
  ELSE
    IF requested_role IN ('applicant', 'pre_licensee') THEN
      BEGIN
        resolved_role := requested_role::app_role;
      EXCEPTION WHEN OTHERS THEN
        resolved_role := 'applicant'::app_role;
      END;
    ELSE
      resolved_role := 'applicant'::app_role;
    END IF;
    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, resolved_role);
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.has_any_internal_role(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id
      AND role NOT IN (
        'applicant'::app_role,
        'pre_licensee'::app_role,
        'licensee_primary'::app_role,
        'licensee_secondary'::app_role
      )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.has_any_permission(_user_id uuid, _keys text[])
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  k text;
  parts text[];
BEGIN
  IF _user_id IS NULL OR _keys IS NULL OR array_length(_keys, 1) IS NULL THEN
    RETURN false;
  END IF;
  IF public.is_super_admin(_user_id) THEN
    RETURN true;
  END IF;
  FOREACH k IN ARRAY _keys LOOP
    parts := string_to_array(k, '.');
    IF array_length(parts, 1) = 2
       AND public.has_permission(_user_id, parts[1], parts[2]) THEN
      RETURN true;
    END IF;
  END LOOP;
  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.has_complaint_perm(_user_id uuid, _action text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH aliased AS (
    SELECT CASE
             WHEN _action = 'view_all' THEN ARRAY['view']
             WHEN _action = 'triage'   THEN ARRAY['assign','edit','investigate']
             ELSE ARRAY[_action]
           END AS actions
  )
  SELECT _user_id IS NOT NULL AND (
    public.is_super_admin(_user_id)
    OR EXISTS (
      SELECT 1 FROM aliased a, unnest(a.actions) AS act(action_key)
      WHERE public.sec_has_permission(_user_id, 'complaint_management', act.action_key)
    )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.has_decision_gate_override(_entity_type text, _entity_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM rule_overrides
    WHERE rule_key='decision.gate.override' AND entity_type=_entity_type AND entity_id::text=_entity_id::text);
$function$
;
