AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id
      AND role IN ('applicant'::app_role, 'pre_licensee'::app_role, 'licensee_primary'::app_role, 'licensee_secondary'::app_role)
