CREATE OR REPLACE FUNCTION public.has_module_access_for_escalation(_user_id uuid, _module text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.permission_modules m
    JOIN public.permission_actions a ON a.module_id = m.id
    WHERE m.key = _module
      AND public.has_permission(_user_id, m.key, a.key)
    LIMIT 1
  );
$function$
;
CREATE OR REPLACE FUNCTION public.has_permission(_user_id uuid, _module text, _action text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT _user_id IS NOT NULL
     AND (public.is_super_admin(_user_id) OR public.sec_has_permission(_user_id, _module, _action));
$function$
;
CREATE OR REPLACE FUNCTION public.has_portal_capability(_user_id uuid, _entity_id uuid, _area portal_area, _capability text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module text;
  v_action text;
BEGIN
  IF _user_id IS NULL THEN RETURN false; END IF;
  IF auth.uid() IS NOT NULL AND auth.uid() <> _user_id AND NOT public.is_internal_staff_user(auth.uid()) THEN
    RETURN false;
  END IF;
  IF public.is_internal_staff_user(_user_id) OR public.has_role(_user_id, 'super_admin'::app_role) THEN
    RETURN true;
  END IF;

  v_module := CASE _area
    WHEN 'licensing'        THEN 'licensing'
    WHEN 'returns'          THEN 'returns_management'
    WHEN 'complaints'       THEN 'complaint_management'
    WHEN 'fp_declarations'  THEN 'fit_and_proper'
  END;

  v_action := CASE _capability
    WHEN 'can_submit'                  THEN 'submit'
    WHEN 'can_submit_returns'          THEN 'submit'
    WHEN 'can_submit_complaints'       THEN 'submit'
    WHEN 'can_submit_fp_declarations'  THEN 'submit'
    WHEN 'can_upload_documents'        THEN 'upload_documents'
    WHEN 'can_view_status'             THEN 'view_status'
    WHEN 'can_respond_rfi'             THEN 'respond_rfi'
    ELSE _capability
  END;

  RETURN public.sec_has_permission(_user_id, v_module, v_action);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id AND role = _role
  )
$function$
;
CREATE OR REPLACE FUNCTION public.has_scoped_permission(_user_id uuid, _module text, _action text, _licensee_id uuid DEFAULT NULL::uuid, _sector_id uuid DEFAULT NULL::uuid, _owner_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE scope jsonb; kind text;
BEGIN
  IF _user_id IS NULL THEN RETURN false; END IF;
  IF public.is_super_admin(_user_id) THEN RETURN true; END IF;
  IF NOT public.has_permission(_user_id, _module, _action) THEN RETURN false; END IF;

  scope := public.user_scope_for(_user_id, _module, _action);
  kind := scope ->> 'scope';

  IF kind = 'all' THEN
    RETURN true;
  ELSIF kind = 'sector' THEN
    RETURN _sector_id IS NOT NULL AND scope -> 'sectors' ? _sector_id::text;
  ELSIF kind = 'institution' THEN
    RETURN _licensee_id IS NOT NULL AND scope -> 'licensees' ? _licensee_id::text;
  ELSIF kind = 'assigned' THEN
    -- CRITICAL FIX: assigned scope must prove assignment via authoritative
    -- module resolver. When no record id is passed, deny.
    IF _licensee_id IS NULL THEN RETURN false; END IF;
    RETURN public.is_record_assigned_to_user(_user_id, _module, _licensee_id);
  ELSIF kind = 'own' THEN
    RETURN _owner_id IS NOT NULL AND _owner_id = _user_id;
  END IF;
  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.has_scoped_permission(_user_id uuid, _module text, _action text, _record_id uuid, _licensee_id uuid, _sector_id uuid, _owner_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE scope jsonb; kind text;
BEGIN
  IF _user_id IS NULL THEN RETURN false; END IF;
  IF public.is_super_admin(_user_id) THEN RETURN true; END IF;
  IF NOT public.has_permission(_user_id, _module, _action) THEN RETURN false; END IF;

  scope := public.user_scope_for(_user_id, _module, _action);
  kind := scope ->> 'scope';

  IF kind = 'all' THEN
    RETURN true;
  ELSIF kind = 'sector' THEN
    RETURN _sector_id IS NOT NULL AND scope -> 'sectors' ? _sector_id::text;
  ELSIF kind = 'institution' THEN
    RETURN _licensee_id IS NOT NULL AND scope -> 'licensees' ? _licensee_id::text;
  ELSIF kind = 'assigned' THEN
    IF _record_id IS NULL THEN RETURN false; END IF;
    RETURN public.is_record_assigned_to_user(_user_id, _module, _record_id);
  ELSIF kind = 'own' THEN
    RETURN _owner_id IS NOT NULL AND _owner_id = _user_id;
  END IF;
  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.import_applications_bulk(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _count int;
BEGIN
  PERFORM public.enforce_permission('application_management', 'import');

  _count := COALESCE(jsonb_array_length(_payload -> 'items'), 0);

  INSERT INTO public.audit_logs (
    user_id, action, entity_type, entity_id, metadata, created_at
  ) VALUES (
    auth.uid(),
    'application.import',
    'application',
    NULL,
    jsonb_build_object('items_count', _count),
    now()
  );

  RETURN jsonb_build_object('accepted', _count);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.import_return_form_data(_return_id uuid, _strategy text, _rows jsonb)
 RETURNS TABLE(values_written integer, forms_touched uuid[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row JSONB;
  v_form_id UUID;
  v_version_id UUID;
  v_field_id TEXT;
  v_field_name TEXT;
  v_field_value TEXT;
  v_existing TEXT;
  v_written INT := 0;
  v_forms UUID[] := '{}';
  v_authorized BOOLEAN;
BEGIN
  IF _strategy NOT IN ('replace','fill_blanks') THEN
    RAISE EXCEPTION 'invalid strategy %', _strategy USING ERRCODE = '22023';
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM public.returns_filed r
    LEFT JOIN public.profiles p ON p.id = auth.uid()
    WHERE r.id = _return_id
      AND (
        (p.licensee_id IS NOT NULL
          AND (p.licensee_id = r.entity_id OR p.licensee_id = r.on_behalf_of_licensee_id))
        OR r.entity_id IN (SELECT ppoc_mapped_licensee_ids(auth.uid()))
        OR r.on_behalf_of_licensee_id IN (SELECT ppoc_mapped_licensee_ids(auth.uid()))
        OR public.external_can_access_return_filed(auth.uid(), r.id, 'can_submit_returns')
        OR has_role(auth.uid(), 'admin'::app_role)
        OR has_role(auth.uid(), 'super_admin'::app_role)
      )
  ) INTO v_authorized;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'not authorized to import into this return' USING ERRCODE = '42501';
  END IF;

  FOR v_row IN SELECT * FROM jsonb_array_elements(_rows)
  LOOP
    v_form_id := (v_row->>'form_id')::UUID;
    v_version_id := NULLIF(v_row->>'form_version_id','')::UUID;
    v_field_id := v_row->>'field_id';
    v_field_name := v_row->>'field_name';
    v_field_value := v_row->>'field_value';

    IF v_form_id IS NULL OR v_field_id IS NULL OR v_field_name IS NULL THEN
      CONTINUE;
    END IF;

    IF _strategy = 'fill_blanks' THEN
      SELECT field_value INTO v_existing
      FROM public.return_form_data
      WHERE return_id = _return_id AND form_id = v_form_id AND field_id = v_field_id;
      IF v_existing IS NOT NULL AND v_existing <> '' THEN
        CONTINUE;
      END IF;
    END IF;

    INSERT INTO public.return_form_data
      (return_id, form_id, field_id, field_name, field_value, form_version_id)
    VALUES
      (_return_id, v_form_id, v_field_id, v_field_name, COALESCE(v_field_value,''), v_version_id)
    ON CONFLICT (return_id, form_id, field_id)
    DO UPDATE SET
      field_value = EXCLUDED.field_value,
      field_name = EXCLUDED.field_name,
      form_version_id = COALESCE(EXCLUDED.form_version_id, public.return_form_data.form_version_id),
      updated_at = now();

    v_written := v_written + 1;
    IF NOT (v_form_id = ANY(v_forms)) THEN
      v_forms := array_append(v_forms, v_form_id);
    END IF;
  END LOOP;

  values_written := v_written;
  forms_touched := v_forms;
  RETURN NEXT;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.inspection_create(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _id uuid; _after jsonb;
BEGIN
  _uid := public.conduct_require('inspection_management','create');
  IF nullif(_payload->>'entity_id','') IS NULL THEN
    RAISE EXCEPTION 'entity_id is required' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.inspections (entity_id, inspection_type, scheduled_date, date_conducted, location, scope,
                                  inspector_id, inspector_name, lead_inspector_id, status)
  VALUES ((_payload->>'entity_id')::uuid, nullif(_payload->>'inspection_type',''),
          nullif(_payload->>'scheduled_date','')::date, nullif(_payload->>'date_conducted','')::date,
          nullif(_payload->>'location',''), nullif(_payload->>'scope',''),
          coalesce(nullif(_payload->>'inspector_id','')::uuid, _uid), nullif(_payload->>'inspector_name',''),
          nullif(_payload->>'lead_inspector_id','')::uuid,
          coalesce(nullif(_payload->>'status',''),'scheduled'))
  RETURNING id INTO _id;
  SELECT to_jsonb(i) INTO _after FROM public.inspections i WHERE i.id=_id;
  PERFORM public.log_compliance_audit('CREATE'::compliance_audit_action,'inspection',_id::text,NULL,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.inspection_finding_escalate(_finding_id uuid, _entity_id uuid, _enforcement_type text, _rationale text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _finding record; _case_id uuid;
BEGIN
  PERFORM public.enforce_permission('inspection_management','workflow_action');
  PERFORM public.enforce_permission('enforcement_management','create');
  IF _rationale IS NULL OR length(btrim(_rationale)) < 10 THEN
    RAISE EXCEPTION 'escalation rationale must be at least 10 characters' USING ERRCODE='22023';
  END IF;
  SELECT * INTO _finding FROM public.inspection_findings WHERE id = _finding_id FOR UPDATE;
  IF _finding IS NULL THEN RAISE EXCEPTION 'finding not found' USING ERRCODE='22023'; END IF;
  IF _finding.escalated_enforcement_id IS NOT NULL THEN
    RAISE EXCEPTION 'finding already escalated' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.enforcement_actions (entity_id, enforcement_type, description, findings,
    opened_by, source_type, source_reference_id, status)
  VALUES (_entity_id, COALESCE(NULLIF(_enforcement_type,''),'warning'),
          btrim(_rationale), _finding.description, _uid, 'inspection_finding', _finding_id, 'open')
  RETURNING id INTO _case_id;
  INSERT INTO public.enforcement_case_events (case_id, event_type, actor_id, note, detail)
  VALUES (_case_id,'opened_from_inspection_finding',_uid,btrim(_rationale),
          jsonb_build_object('finding_id',_finding_id,'inspection_id',_finding.inspection_id));
  UPDATE public.inspection_findings
     SET escalated_enforcement_id = _case_id, escalated_at = now(), escalated_by = _uid, status = 'escalated'
   WHERE id = _finding_id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'inspection.finding.escalated','inspection_finding',_finding_id,
          jsonb_build_object('enforcement_case_id',_case_id,'entity_id',_entity_id,
                             'justification',btrim(_rationale)));
  RETURN jsonb_build_object('enforcement_case_id',_case_id,'finding_id',_finding_id);
END; $function$
;
CREATE OR REPLACE FUNCTION public.inspection_finding_save(_inspection_id uuid, _category text, _severity text, _description text, _finding_id uuid DEFAULT NULL::uuid, _recommended_action text DEFAULT NULL::text, _follow_up_owner text DEFAULT NULL::text, _follow_up_due date DEFAULT NULL::date, _status text DEFAULT 'open'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('inspection_management','edit');
  IF _description IS NULL OR length(btrim(_description)) < 5 THEN
    RAISE EXCEPTION 'finding description is required' USING ERRCODE='22023';
  END IF;
  IF _severity NOT IN ('low','medium','high','critical') THEN
    RAISE EXCEPTION 'invalid severity' USING ERRCODE='22023';
  END IF;
  IF _finding_id IS NULL THEN
    INSERT INTO public.inspection_findings (inspection_id, category, severity, description,
      recommended_action, follow_up_owner, follow_up_due, status, created_by)
    VALUES (_inspection_id, _category, _severity, btrim(_description), _recommended_action,
            _follow_up_owner, _follow_up_due, COALESCE(_status,'open'), _uid)
    RETURNING * INTO _row;
  ELSE
    SELECT * INTO _prev FROM public.inspection_findings WHERE id = _finding_id FOR UPDATE;
    IF _prev IS NULL THEN RAISE EXCEPTION 'finding not found' USING ERRCODE='22023'; END IF;
    UPDATE public.inspection_findings
       SET category = _category, severity = _severity, description = btrim(_description),
           recommended_action = _recommended_action, follow_up_owner = _follow_up_owner,
           follow_up_due = _follow_up_due, status = COALESCE(_status, status)
     WHERE id = _finding_id RETURNING * INTO _row;
  END IF;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid, CASE WHEN _finding_id IS NULL THEN 'inspection.finding.created' ELSE 'inspection.finding.updated' END,
          'inspection_finding', _row.id,
          jsonb_build_object('inspection_id',_inspection_id,'before',to_jsonb(_prev),'after',to_jsonb(_row)));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.inspection_lifecycle_save(_inspection_id uuid, _patch jsonb, _rationale text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb; _new_status text; _closing boolean;
BEGIN
  _uid := public.conduct_require('inspection_management','edit');
  SELECT to_jsonb(i) INTO _before FROM public.inspections i WHERE i.id=_inspection_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Inspection not found' USING ERRCODE='P0002'; END IF;
  _new_status := nullif(_patch->>'status','');
  IF _new_status IS NOT NULL AND _new_status NOT IN ('planned','scheduled','in_progress','completed','cancelled','closed') THEN
    RAISE EXCEPTION 'Invalid inspection status %', _new_status USING ERRCODE='22023';
  END IF;
  _closing := _new_status IN ('completed','closed','cancelled') AND coalesce(_before->>'status','') <> _new_status;
  UPDATE public.inspections SET
    status = coalesce(_new_status, status),
    scheduled_date = CASE WHEN _patch ? 'scheduled_date' THEN nullif(_patch->>'scheduled_date','')::date ELSE scheduled_date END,
    date_conducted = CASE WHEN _patch ? 'date_conducted' THEN nullif(_patch->>'date_conducted','')::date ELSE date_conducted END,
    location = CASE WHEN _patch ? 'location' THEN nullif(_patch->>'location','') ELSE location END,
    scope = CASE WHEN _patch ? 'scope' THEN nullif(_patch->>'scope','') ELSE scope END,
    inspector_name = CASE WHEN _patch ? 'inspector_name' THEN nullif(_patch->>'inspector_name','') ELSE inspector_name END,
    findings_summary = CASE WHEN _patch ? 'findings_summary' THEN nullif(_patch->>'findings_summary','') ELSE findings_summary END,
    compliance_rating = CASE WHEN _patch ? 'compliance_rating' THEN nullif(_patch->>'compliance_rating','') ELSE compliance_rating END,
    follow_up_actions = CASE WHEN _patch ? 'follow_up_actions' THEN nullif(_patch->>'follow_up_actions','') ELSE follow_up_actions END,
    updated_at = now()
  WHERE id=_inspection_id RETURNING to_jsonb(inspections) INTO _after;
  PERFORM public.log_compliance_audit(
    (CASE WHEN _closing THEN 'WORKFLOW_TRANSITION' ELSE 'UPDATE' END)::compliance_audit_action,
    'inspection',_inspection_id::text,_before,_after,_rationale);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.integration_alert_rule_save(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid := NULLIF(_payload->>'id','')::uuid;
  v_conn uuid := NULLIF(_payload->>'connection_id','')::uuid;
BEGIN
  PERFORM public.enforce_permission('settings','edit');

  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM public.integration_alert_rules
     WHERE COALESCE(connection_id,'00000000-0000-0000-0000-000000000000'::uuid)
         = COALESCE(v_conn,'00000000-0000-0000-0000-000000000000'::uuid);
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.integration_alert_rules (
      connection_id, error_count_threshold, window_minutes,
      recipient_user_ids, recipient_emails, enabled, created_by
    ) VALUES (
      v_conn,
      COALESCE((_payload->>'error_count_threshold')::integer, 5),
      COALESCE((_payload->>'window_minutes')::integer, 15),
      COALESCE((SELECT array_agg(x::uuid) FROM jsonb_array_elements_text(COALESCE(_payload->'recipient_user_ids','[]'::jsonb)) t(x)), '{}'),
      COALESCE((SELECT array_agg(x) FROM jsonb_array_elements_text(COALESCE(_payload->'recipient_emails','[]'::jsonb)) t(x)), '{}'),
      COALESCE((_payload->>'enabled')::boolean, true),
      auth.uid()
    ) RETURNING id INTO v_id;
  ELSE
    UPDATE public.integration_alert_rules SET
      error_count_threshold = COALESCE((_payload->>'error_count_threshold')::integer, error_count_threshold),
      window_minutes = COALESCE((_payload->>'window_minutes')::integer, window_minutes),
      recipient_user_ids = COALESCE((SELECT array_agg(x::uuid) FROM jsonb_array_elements_text(COALESCE(_payload->'recipient_user_ids','[]'::jsonb)) t(x)), recipient_user_ids),
      recipient_emails = COALESCE((SELECT array_agg(x) FROM jsonb_array_elements_text(COALESCE(_payload->'recipient_emails','[]'::jsonb)) t(x)), recipient_emails),
      enabled = COALESCE((_payload->>'enabled')::boolean, enabled)
    WHERE id = v_id;
  END IF;

  PERFORM public.log_compliance_audit(
    'UPDATE'::compliance_audit_action,
    'integration_alert_rule', v_id::text, NULL, _payload, NULL, NULL, NULL,
    jsonb_build_object('event','ADMIN_INTEGRATION_ALERT_UPDATED')
  );

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.integration_alert_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
  v_errors bigint;
  v_fired int := 0;
BEGIN
  FOR r IN
    SELECT ar.*, c.integration_key, c.name AS connection_name
    FROM public.integration_alert_rules ar
    LEFT JOIN public.integration_connections c ON c.id = ar.connection_id
    WHERE ar.enabled
  LOOP
    SELECT COUNT(*) INTO v_errors
    FROM public.integration_logs l
    WHERE l.status = 'failure'
      AND l.created_at > now() - make_interval(mins => r.window_minutes)
      AND (r.connection_id IS NULL OR l.integration_key = r.integration_key);

    IF v_errors >= r.error_count_threshold
       AND (r.last_fired_at IS NULL
            OR r.last_fired_at < now() - make_interval(mins => r.window_minutes)) THEN

      PERFORM public.escalation_raise(
        'integration_manager',
        'integration_error_threshold_breached',
        'integration_failure'::escalation_type,
        'integration_connection',
        r.connection_id,
        COALESCE(r.integration_key, 'global'),
        'high'::escalation_severity,
        NULL,
        jsonb_build_object(
          'alert_rule_id', r.id,
          'connection_name', COALESCE(r.connection_name, 'All integrations'),
          'error_count', v_errors,
          'window_minutes', r.window_minutes,
          'threshold', r.error_count_threshold,
          'recipient_user_ids', r.recipient_user_ids,
          'recipient_emails', r.recipient_emails
        ),
        NULL
      );

      UPDATE public.integration_alert_rules SET last_fired_at = now() WHERE id = r.id;
      v_fired := v_fired + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('rules_fired', v_fired, 'swept_at', now());
END;
$function$
;
CREATE OR REPLACE FUNCTION public.integration_connection_dependencies(_connection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_key text;
  v_recent bigint;
  v_pending bigint;
BEGIN
  PERFORM public.enforce_permission('settings','view');
  SELECT integration_key INTO v_key FROM public.integration_connections WHERE id = _connection_id;
  IF v_key IS NULL THEN
    RAISE EXCEPTION 'connection_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT COUNT(DISTINCT COALESCE(entity_id::text, id::text))
    INTO v_recent
  FROM public.integration_logs
  WHERE integration_key = v_key AND created_at > now() - interval '30 days';

  SELECT COUNT(*) INTO v_pending
  FROM public.integration_logs
  WHERE integration_key = v_key AND status = 'pending';

  RETURN jsonb_build_object(
    'integration_key', v_key,
    'recent_dependent_records', v_recent,
    'in_flight_events', v_pending
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.integration_connection_save(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid := NULLIF(_payload->>'id','')::uuid;
  v_before jsonb;
  v_url text := NULLIF(trim(_payload->>'base_url'), '');
  v_requires boolean := COALESCE((_payload->>'requires_credentials')::boolean, true);
  v_key text := lower(trim(COALESCE(_payload->>'integration_key','')));
  v_env text := COALESCE(NULLIF(_payload->>'environment',''), 'sandbox');
BEGIN
  PERFORM public.enforce_permission('settings','edit');

  IF v_key = '' THEN
    RAISE EXCEPTION 'integration_key_required' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(trim(_payload->>'name'),'') = '' THEN
    RAISE EXCEPTION 'name_required' USING ERRCODE = '22023';
  END IF;
  IF v_env NOT IN ('sandbox','production') THEN
    RAISE EXCEPTION 'invalid_environment' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(_payload->>'protocol','REST') IN ('REST','SOAP','WEBHOOK','GRAPHQL') THEN
    IF v_url IS NULL OR v_url !~* '^https://[^\s]+$' THEN
      RAISE EXCEPTION 'base_url_must_be_https' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_id IS NOT NULL THEN
    SELECT to_jsonb(c) INTO v_before FROM public.integration_connections c WHERE c.id = v_id;
    IF v_before IS NULL THEN
      RAISE EXCEPTION 'connection_not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.integration_connections (
      integration_key, name, description, category, type, protocol, base_url,
      auth_type, requires_credentials, timeout_ms, retry_count, retry_backoff_ms,
      data_mapping, enabled, environment, owner_team, owner_user_id, adapter_key,
      circuit_failure_threshold, circuit_cooloff_seconds, rate_limit_per_minute,
      created_by, updated_by
    ) VALUES (
      v_key,
      trim(_payload->>'name'),
      NULLIF(_payload->>'description',''),
      NULLIF(_payload->>'category',''),
      COALESCE(_payload->>'type','outbound'),
      COALESCE(_payload->>'protocol','REST'),
      v_url,
      COALESCE(_payload->>'auth_type','api_key'),
      v_requires,
      COALESCE((_payload->>'timeout_ms')::integer, 15000),
      COALESCE((_payload->>'retry_count')::integer, 3),
      COALESCE((_payload->>'retry_backoff_ms')::integer, 2000),
      COALESCE(_payload->'data_mapping', '{}'::jsonb),
      COALESCE((_payload->>'enabled')::boolean, true),
      v_env,
      NULLIF(_payload->>'owner_team',''),
      NULLIF(_payload->>'owner_user_id','')::uuid,
      COALESCE(NULLIF(_payload->>'adapter_key',''), v_key),
      COALESCE((_payload->>'circuit_failure_threshold')::integer, 5),
      COALESCE((_payload->>'circuit_cooloff_seconds')::integer, 300),
      NULLIF(_payload->>'rate_limit_per_minute','')::integer,
      auth.uid(), auth.uid()
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.integration_connections SET
      name = trim(_payload->>'name'),
      description = NULLIF(_payload->>'description',''),
      category = NULLIF(_payload->>'category',''),
      type = COALESCE(_payload->>'type', type),
      protocol = COALESCE(_payload->>'protocol', protocol),
      base_url = v_url,
      auth_type = COALESCE(_payload->>'auth_type', auth_type),
      requires_credentials = v_requires,
      timeout_ms = COALESCE((_payload->>'timeout_ms')::integer, timeout_ms),
      retry_count = COALESCE((_payload->>'retry_count')::integer, retry_count),
      retry_backoff_ms = COALESCE((_payload->>'retry_backoff_ms')::integer, retry_backoff_ms),
      data_mapping = COALESCE(_payload->'data_mapping', data_mapping),
      environment = v_env,
      owner_team = COALESCE(NULLIF(_payload->>'owner_team',''), owner_team),
      owner_user_id = COALESCE(NULLIF(_payload->>'owner_user_id','')::uuid, owner_user_id),
      adapter_key = COALESCE(NULLIF(_payload->>'adapter_key',''), adapter_key, v_key),
      circuit_failure_threshold = COALESCE((_payload->>'circuit_failure_threshold')::integer, circuit_failure_threshold),
      circuit_cooloff_seconds = COALESCE((_payload->>'circuit_cooloff_seconds')::integer, circuit_cooloff_seconds),
      rate_limit_per_minute = COALESCE(NULLIF(_payload->>'rate_limit_per_minute','')::integer, rate_limit_per_minute),
      updated_by = auth.uid()
    WHERE id = v_id;
  END IF;

  PERFORM public.log_compliance_audit(
    CASE WHEN v_before IS NULL THEN 'CREATE' ELSE 'UPDATE' END::compliance_audit_action,
    'integration_connection', v_id::text, v_before,
    (SELECT to_jsonb(c) FROM public.integration_connections c WHERE c.id = v_id),
    NULL, NULL, NULL,
    jsonb_build_object('event','ADMIN_INTEGRATION_UPDATED','integration_key', v_key)
  );

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.integration_connection_set_enabled(_connection_id uuid, _enabled boolean, _justification text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_before jsonb;
BEGIN
  PERFORM public.enforce_permission('settings','edit');

  SELECT to_jsonb(c) INTO v_before FROM public.integration_connections c WHERE c.id = _connection_id;
  IF v_before IS NULL THEN
    RAISE EXCEPTION 'connection_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT _enabled AND COALESCE(length(trim(_justification)), 0) < 10 THEN
    RAISE EXCEPTION 'justification_required' USING ERRCODE = '22023';
  END IF;

  UPDATE public.integration_connections SET
    enabled = _enabled,
    status = CASE WHEN _enabled THEN status ELSE 'inactive' END,
    disabled_reason = CASE WHEN _enabled THEN NULL ELSE trim(_justification) END,
    disabled_at = CASE WHEN _enabled THEN NULL ELSE now() END,
    disabled_by = CASE WHEN _enabled THEN NULL ELSE auth.uid() END,
    updated_by = auth.uid()
  WHERE id = _connection_id;

  PERFORM public.log_compliance_audit(
    'UPDATE'::compliance_audit_action,
    'integration_connection', _connection_id::text, v_before,
    (SELECT to_jsonb(c) FROM public.integration_connections c WHERE c.id = _connection_id),
    CASE WHEN _enabled THEN NULL ELSE trim(_justification) END, NULL, NULL,
    jsonb_build_object('event', CASE WHEN _enabled THEN 'INTEGRATION_ENABLED' ELSE 'INTEGRATION_DISABLED' END)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.integration_credentials_rotate(_connection_id uuid, _secret_ref text, _key_prefix text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_version integer;
  v_hint text;
BEGIN
  PERFORM public.enforce_permission('settings','edit');

  IF NOT EXISTS (SELECT 1 FROM public.integration_connections WHERE id = _connection_id) THEN
    RAISE EXCEPTION 'connection_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF COALESCE(trim(_secret_ref),'') = '' THEN
    RAISE EXCEPTION 'secret_ref_required' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(MAX(version), 0) + 1 INTO v_version
  FROM public.integration_credentials WHERE connection_id = _connection_id;

  UPDATE public.integration_credentials
     SET is_current = false, superseded_at = now()
   WHERE connection_id = _connection_id AND is_current;

  v_hint := '••••••••' || COALESCE(right(NULLIF(trim(_key_prefix),''), 4), '');

  INSERT INTO public.integration_credentials (
    connection_id, secret_ref, key_prefix, masked_hint, version, is_current, rotated_by
  ) VALUES (
    _connection_id, trim(_secret_ref), NULLIF(trim(_key_prefix),''), v_hint, v_version, true, auth.uid()
  );

  PERFORM public.log_compliance_audit(
    'UPDATE'::compliance_audit_action,
    'integration_credentials', _connection_id::text, NULL,
    jsonb_build_object('version', v_version, 'secret_ref', trim(_secret_ref)),
    NULL, NULL, NULL,
    jsonb_build_object('event','INTEGRATION_CREDENTIALS_ROTATED')
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.integration_dlq_resolve(_id uuid, _note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v public.integration_dead_letter;
BEGIN
  PERFORM public.integration_retry_assert_operator();
  IF coalesce(btrim(_note),'') = '' THEN
    RAISE EXCEPTION 'justification_required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v FROM public.integration_dead_letter WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'dead_letter_not_found'; END IF;

  UPDATE public.integration_dead_letter
     SET resolution_status = 'resolved', resolution_note = _note,
         resolved_by = auth.uid(), resolved_at = now()
   WHERE id = _id;

  PERFORM public.log_compliance_audit(
    'OVERRIDE'::compliance_audit_action, 'integration_dead_letter', _id::text,
    jsonb_build_object('resolution_status', v.resolution_status),
    jsonb_build_object('resolution_status','resolved'), _note, NULL, NULL,
    jsonb_build_object('integration_key', v.integration_key, 'operation', v.operation,
                       'event','integration.dead_letter.resolved'));
  RETURN _id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.integration_dlq_retry(_id uuid, _justification text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v public.integration_dead_letter; v_queue uuid;
BEGIN
  PERFORM public.integration_retry_assert_operator();
  IF coalesce(btrim(_justification),'') = '' THEN
    RAISE EXCEPTION 'justification_required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v FROM public.integration_dead_letter WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'dead_letter_not_found'; END IF;

  IF v.retry_queue_id IS NOT NULL THEN
    PERFORM public.integration_retry_now(v.retry_queue_id, _justification);
    RETURN v.retry_queue_id;
  END IF;

  INSERT INTO public.integration_retry_queue (
    integration_key, connection_id, operation, source_module, business_event,
    source_entity_type, source_entity_id, actor_id, correlation_id,
    idempotency_key, idempotency_fingerprint, payload, redacted_fields, metadata,
    status, next_attempt_at, max_attempts, enqueued_reason
  ) VALUES (
    v.integration_key, v.connection_id, v.operation, v.source_module, v.business_event,
    v.source_entity_type, v.source_entity_id, v.actor_id, v.correlation_id,
    v.idempotency_key, v.idempotency_fingerprint, v.payload, v.redacted_fields, v.metadata,
    'retry_scheduled', now(), 1, 'manual_dlq_retry'
  ) RETURNING id INTO v_queue;

  UPDATE public.integration_dead_letter
     SET resolution_status = 'retrying', retry_queue_id = v_queue,
         last_retried_at = now(), last_retried_by = auth.uid()
   WHERE id = _id;

  PERFORM public.log_compliance_audit(
    'OVERRIDE'::compliance_audit_action, 'integration_dead_letter', _id::text,
    NULL, jsonb_build_object('resolution_status','retrying','retry_queue_id',v_queue),
    _justification, NULL, NULL,
    jsonb_build_object('integration_key', v.integration_key, 'operation', v.operation,
                       'event','integration.dead_letter.retried'));
  RETURN v_queue;
END; $function$
;
CREATE OR REPLACE FUNCTION public.integration_fallback_metrics(_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH win AS (
    SELECT * FROM public.integration_logs
     WHERE created_at > now() - make_interval(days => GREATEST(_days, 1))
  ), modes AS (
    SELECT COALESCE(execution_mode,'real') AS mode, count(*) AS n FROM win GROUP BY 1
  )
  SELECT jsonb_build_object(
    'window_days', GREATEST(_days, 1),
    'executions', (SELECT COALESCE(sum(n),0) FROM modes),
    'real', (SELECT COALESCE(sum(n),0) FROM modes WHERE mode = 'real'),
    'mock', (SELECT COALESCE(sum(n),0) FROM modes WHERE mode = 'mock'),
    'fallback', (SELECT COALESCE(sum(n),0) FROM modes WHERE mode = 'fallback'),
    'blocked', (SELECT COALESCE(sum(n),0) FROM modes WHERE mode = 'blocked'),
    'fallback_rate', CASE WHEN (SELECT COALESCE(sum(n),0) FROM modes) = 0 THEN 0
      ELSE round((SELECT COALESCE(sum(n),0) FROM modes WHERE mode='fallback')::numeric
                 / (SELECT sum(n) FROM modes), 4) END,
    'reasons', COALESCE((SELECT jsonb_object_agg(fallback_reason, c) FROM (
        SELECT fallback_reason, count(*) c FROM public.integration_fallback_events
         WHERE created_at > now() - make_interval(days => GREATEST(_days,1))
         GROUP BY 1) r), '{}'::jsonb),
    'modules', COALESCE((SELECT jsonb_object_agg(source_module, c) FROM (
        SELECT source_module, count(*) c FROM public.integration_fallback_events
         WHERE created_at > now() - make_interval(days => GREATEST(_days,1))
         GROUP BY 1) m), '{}'::jsonb),
    'integrations_in_fallback', COALESCE((SELECT jsonb_agg(jsonb_build_object(
         'integration_key', integration_key,
         'since', fallback_since,
         'count', fallback_count,
         'business_critical', business_critical,
         'max_duration_hours', fallback_max_duration_hours,
         'over_max_duration', fallback_since IS NOT NULL
            AND fallback_since < now() - make_interval(hours => fallback_max_duration_hours)))
       FROM public.integration_connections
      WHERE fallback_since IS NOT NULL), '[]'::jsonb),
    'oldest_unresolved_fallback', (SELECT min(created_at)
       FROM public.integration_fallback_events WHERE recovery_state = 'unresolved')
  );
$function$
;
CREATE OR REPLACE FUNCTION public.integration_health_summary()
 RETURNS TABLE(connection_id uuid, integration_key text, name text, type text, protocol text, enabled boolean, status text, base_url text, auth_type text, environment text, owner_team text, adapter_key text, provider_verified boolean, circuit_state text, circuit_failure_count integer, circuit_opened_at timestamp with time zone, last_success_at timestamp with time zone, last_error_at timestamp with time zone, last_error text, last_test_at timestamp with time zone, last_test_latency_ms integer, last_recovery_at timestamp with time zone, error_count_24h bigint, event_count_24h bigint, avg_latency_ms integer, success_rate numeric, error_rate numeric, credential_masked_hint text, credential_rotated_at timestamp with time zone, credential_version integer, disabled_reason text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    c.id, c.integration_key, c.name, c.type, c.protocol, c.enabled,
    CASE
      WHEN NOT c.enabled THEN 'inactive'
      WHEN c.circuit_state = 'open' THEN 'error'
      WHEN c.last_error_at IS NOT NULL
           AND (c.last_success_at IS NULL OR c.last_error_at > c.last_success_at) THEN 'error'
      WHEN c.last_success_at IS NOT NULL THEN 'active'
      ELSE 'inactive'
    END AS status,
    c.base_url, c.auth_type,
    c.environment, c.owner_team, c.adapter_key, c.provider_verified,
    c.circuit_state, c.circuit_failure_count, c.circuit_opened_at,
    c.last_success_at, c.last_error_at, c.last_error,
    c.last_test_at, c.last_test_latency_ms, c.last_recovery_at,
    COALESCE(l.error_count, 0), COALESCE(l.event_count, 0),
    COALESCE(l.avg_latency, c.avg_latency_ms)::integer,
    CASE WHEN COALESCE(l.event_count,0) > 0
         THEN ROUND(100.0 * (l.event_count - l.error_count) / l.event_count, 2)
         ELSE c.success_rate END,
    CASE WHEN COALESCE(l.event_count,0) > 0
         THEN ROUND(100.0 * l.error_count / l.event_count, 2)
         ELSE c.error_rate END,
    cr.masked_hint, cr.rotated_at, c.credential_version,
    c.disabled_reason
  FROM public.integration_connections c
  LEFT JOIN (
    SELECT integration_key,
           COUNT(*) FILTER (WHERE status = 'failure') AS error_count,
           COUNT(*) AS event_count,
           AVG(duration_ms) AS avg_latency
    FROM public.integration_logs
    WHERE created_at > now() - interval '24 hours'
    GROUP BY integration_key
  ) l ON l.integration_key = c.integration_key
  LEFT JOIN public.integration_credentials cr
    ON cr.connection_id = c.id AND cr.is_current
  WHERE public.is_super_admin(auth.uid())
     OR public.has_permission(auth.uid(), 'settings', 'view')
  ORDER BY c.name;
$function$
;
CREATE OR REPLACE FUNCTION public.integration_record_fallback(_integration_key text, _operation text, _source_module text, _business_event text, _fallback_reason text, _execution_mode text DEFAULT 'fallback'::text, _fallback_implementation text DEFAULT NULL::text, _original_error_category text DEFAULT NULL::text, _original_error text DEFAULT NULL::text, _source_entity_type text DEFAULT NULL::text, _source_entity_id text DEFAULT NULL::text, _actor_id uuid DEFAULT NULL::uuid, _correlation_id uuid DEFAULT NULL::uuid, _idempotency_fingerprint text DEFAULT NULL::text, _integration_log_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conn public.integration_connections;
  v_id uuid;
BEGIN
  SELECT * INTO v_conn FROM public.integration_connections
   WHERE integration_key = _integration_key;

  INSERT INTO public.integration_fallback_events (
    integration_key, connection_id, adapter_key, operation, source_module,
    business_event, source_entity_type, source_entity_id, actor_id,
    correlation_id, idempotency_fingerprint, execution_mode, fallback_reason,
    fallback_implementation, original_error_category, original_error,
    integration_log_id, environment, business_critical
  ) VALUES (
    _integration_key, v_conn.id, COALESCE(v_conn.adapter_key, _integration_key),
    _operation, _source_module, _business_event, _source_entity_type,
    _source_entity_id, _actor_id, _correlation_id, _idempotency_fingerprint,
    _execution_mode, _fallback_reason, _fallback_implementation,
    _original_error_category, _original_error, _integration_log_id,
    v_conn.environment, COALESCE(v_conn.business_critical, false)
  ) RETURNING id INTO v_id;

  IF _execution_mode = 'fallback' THEN
    UPDATE public.integration_connections
       SET fallback_count = fallback_count + 1,
           fallback_since = COALESCE(fallback_since, now())
     WHERE id = v_conn.id;
  END IF;

  INSERT INTO public.audit_logs (
    user_id, action, entity_type, entity_id, new_value, metadata
  ) VALUES (
    _actor_id,
    'integration.' || _execution_mode || '_execution',
    'integration_connection',
    COALESCE(v_conn.id::text, _integration_key),
    jsonb_build_object(
      'integration_key', _integration_key,
      'operation', _operation,
      'execution_mode', _execution_mode,
      'fallback_reason', _fallback_reason,
      'fallback_implementation', _fallback_implementation,
      'original_error_category', _original_error_category
    ),
    jsonb_build_object(
      'source_module', _source_module,
      'business_event', _business_event,
      'source_entity_type', _source_entity_type,
      'source_entity_id', _source_entity_id,
      'correlation_id', _correlation_id,
      'environment', v_conn.environment,
      'fallback_event_id', v_id
    )
  );

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.integration_record_outcome(_integration_key text, _ok boolean, _latency_ms integer DEFAULT NULL::integer, _error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.integration_connections;
  v_new_state text;
BEGIN
  SELECT * INTO c FROM public.integration_connections
   WHERE integration_key = _integration_key;
  IF c.id IS NULL THEN RETURN jsonb_build_object('found', false); END IF;

  IF _ok THEN
    v_new_state := 'closed';
    UPDATE public.integration_connections SET
      status = 'active',
      last_success_at = now(),
      last_error = NULL,
      circuit_state = 'closed',
      circuit_failure_count = 0,
      circuit_opened_at = NULL,
      last_recovery_at = CASE WHEN c.circuit_state <> 'closed' THEN now()
                              ELSE last_recovery_at END,
      avg_latency_ms = CASE WHEN _latency_ms IS NULL THEN avg_latency_ms
        ELSE COALESCE((avg_latency_ms * 4 + _latency_ms) / 5, _latency_ms) END
    WHERE id = c.id;
  ELSE
    v_new_state := CASE
      WHEN c.circuit_failure_count + 1 >= c.circuit_failure_threshold THEN 'open'
      ELSE c.circuit_state END;
    UPDATE public.integration_connections SET
      status = 'error',
      last_error_at = now(),
      last_error = LEFT(COALESCE(_error, 'unknown error'), 500),
      circuit_failure_count = c.circuit_failure_count + 1,
      circuit_state = v_new_state,
      circuit_opened_at = CASE WHEN v_new_state = 'open' AND c.circuit_state <> 'open'
                               THEN now() ELSE circuit_opened_at END
    WHERE id = c.id;
  END IF;

  RETURN jsonb_build_object('found', true, 'circuit_state', v_new_state);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.integration_resolve_connection(_integration_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'id', c.id,
    'integration_key', c.integration_key,
    'name', c.name,
    'adapter_key', COALESCE(c.adapter_key, c.integration_key),
    'enabled', c.enabled,
    'environment', c.environment,
    'protocol', c.protocol,
    'auth_type', c.auth_type,
    'base_url', c.base_url,
    'timeout_ms', c.timeout_ms,
    'retry_count', c.retry_count,
    'retry_backoff_ms', c.retry_backoff_ms,
    'rate_limit_per_minute', c.rate_limit_per_minute,
    'requires_credentials', c.requires_credentials,
    'data_mapping', c.data_mapping,
    'circuit_state', c.circuit_state,
    'circuit_opened_at', c.circuit_opened_at,
    'circuit_cooloff_seconds', c.circuit_cooloff_seconds,
    'secret_ref', cr.secret_ref,
    'credential_version', c.credential_version,
    'provider_verified', c.provider_verified,
    'business_critical', c.business_critical,
    'fallback_enabled', c.fallback_enabled,
    'fallback_strategy', c.fallback_strategy,
    'fallback_implementation_key', c.fallback_implementation_key,
    'fallback_allowed_categories', c.fallback_allowed_categories,
    'fallback_max_duration_hours', c.fallback_max_duration_hours,
    'fallback_alert_threshold', c.fallback_alert_threshold,
    'fallback_recovery_policy', c.fallback_recovery_policy,
    'fallback_approval_status', c.fallback_approval_status
  )
  FROM public.integration_connections c
  LEFT JOIN public.integration_credentials cr
    ON cr.connection_id = c.id AND cr.is_current
  WHERE c.integration_key = _integration_key;
$function$
;
CREATE OR REPLACE FUNCTION public.integration_retry_assert_operator()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(), 'settings', 'edit')) THEN
    RAISE EXCEPTION 'not_authorized_integration_retry' USING ERRCODE = '42501';
  END IF;
END; $function$
;
CREATE OR REPLACE FUNCTION public.integration_retry_cancel(_id uuid, _justification text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v public.integration_retry_queue;
BEGIN
  PERFORM public.integration_retry_assert_operator();
  IF coalesce(btrim(_justification),'') = '' THEN
    RAISE EXCEPTION 'justification_required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v FROM public.integration_retry_queue WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'retry_item_not_found'; END IF;

  UPDATE public.integration_retry_queue
     SET status = 'cancelled', cancelled_at = now(), cancelled_by = auth.uid(),
         cancelled_reason = _justification, lease_owner = NULL, leased_until = NULL
   WHERE id = _id;

  UPDATE public.integration_dead_letter
     SET resolution_status = 'cancelled', resolution_note = _justification,
         resolved_by = auth.uid(), resolved_at = now()
   WHERE retry_queue_id = _id AND resolution_status IN ('open','retrying');

  PERFORM public.log_compliance_audit(
    'OVERRIDE'::compliance_audit_action, 'integration_retry_queue', _id::text,
    jsonb_build_object('status', v.status), jsonb_build_object('status','cancelled'),
    _justification, NULL, NULL,
    jsonb_build_object('integration_key', v.integration_key, 'operation', v.operation,
                       'event','integration.retry.cancelled'));
  RETURN _id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.integration_retry_claim(_worker text, _limit integer DEFAULT 10, _lease_seconds integer DEFAULT 120)
 RETURNS SETOF integration_retry_queue
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Recover items whose worker died mid-flight.
  UPDATE public.integration_retry_queue
     SET status = 'retry_scheduled',
         lease_owner = NULL,
         leased_until = NULL,
         next_attempt_at = now()
   WHERE status = 'processing'
     AND leased_until IS NOT NULL
     AND leased_until < now();

  RETURN QUERY
  WITH claimed AS (
    SELECT id FROM public.integration_retry_queue
     WHERE status IN ('queued','retry_scheduled')
       AND next_attempt_at <= now()
     ORDER BY next_attempt_at
     LIMIT greatest(1, coalesce(_limit, 10))
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.integration_retry_queue q
     SET status = 'processing',
         lease_owner = _worker,
         leased_until = now() + make_interval(secs => greatest(10, coalesce(_lease_seconds,120))),
         attempts = q.attempts + 1
    FROM claimed
   WHERE q.id = claimed.id
  RETURNING q.*;
END; $function$
;
CREATE OR REPLACE FUNCTION public.integration_retry_enqueue(_integration_key text, _operation text, _source_module text, _business_event text DEFAULT NULL::text, _payload jsonb DEFAULT '{}'::jsonb, _redacted_fields text[] DEFAULT '{}'::text[], _source_entity_type text DEFAULT NULL::text, _source_entity_id text DEFAULT NULL::text, _actor_id uuid DEFAULT NULL::uuid, _correlation_id uuid DEFAULT NULL::uuid, _idempotency_key text DEFAULT NULL::text, _idempotency_fingerprint text DEFAULT NULL::text, _error_category text DEFAULT NULL::text, _error text DEFAULT NULL::text, _provider_status integer DEFAULT NULL::integer, _integration_log_id uuid DEFAULT NULL::uuid, _required_capability text DEFAULT NULL::text, _fallback_policy text DEFAULT 'auto'::text, _timeout_override_ms integer DEFAULT NULL::integer, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conn public.integration_connections;
  v_max integer;
  v_id uuid;
BEGIN
  -- Permanent rejections and adverse business results are never retried.
  IF NOT public.integration_retry_is_retryable(_error_category) THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_conn FROM public.integration_connections
   WHERE integration_key = _integration_key LIMIT 1;

  v_max := greatest(1, coalesce(v_conn.max_retries, 3) + 1);

  -- Idempotent: an open queue item with the same fingerprint is reused.
  IF _idempotency_fingerprint IS NOT NULL THEN
    SELECT id INTO v_id FROM public.integration_retry_queue
     WHERE idempotency_fingerprint = _idempotency_fingerprint
       AND status IN ('queued','processing','retry_scheduled')
     LIMIT 1;
    IF v_id IS NOT NULL THEN
      RETURN v_id;
    END IF;
  END IF;

  INSERT INTO public.integration_retry_queue (
    integration_key, connection_id, operation, source_module, business_event,
    source_entity_type, source_entity_id, actor_id, correlation_id,
    idempotency_key, idempotency_fingerprint, payload, redacted_fields,
    required_capability, fallback_policy, timeout_override_ms, metadata,
    status, max_attempts, next_attempt_at,
    last_error_category, last_error, last_provider_status, last_integration_log_id,
    enqueued_reason
  ) VALUES (
    _integration_key, v_conn.id, _operation, _source_module, _business_event,
    _source_entity_type, _source_entity_id, _actor_id, _correlation_id,
    _idempotency_key, _idempotency_fingerprint, coalesce(_payload,'{}'::jsonb),
    coalesce(_redacted_fields,'{}'), _required_capability,
    coalesce(_fallback_policy,'auto'), _timeout_override_ms, coalesce(_metadata,'{}'::jsonb),
    'queued', v_max, now() + make_interval(secs => 1),
    _error_category, _error, _provider_status, _integration_log_id,
    coalesce(_error_category,'unknown')
  ) RETURNING id INTO v_id;

  RETURN v_id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.integration_retry_heartbeat(_id uuid, _worker text, _lease_seconds integer DEFAULT 120)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.integration_retry_queue
     SET leased_until = now() + make_interval(secs => greatest(10, coalesce(_lease_seconds,120)))
   WHERE id = _id AND lease_owner = _worker AND status = 'processing';
  RETURN FOUND;
END; $function$
;
CREATE OR REPLACE FUNCTION public.integration_retry_is_retryable(_error_category text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(_error_category, 'unknown') IN
    ('network','timeout','server','circuit_open','rate_limit','not_configured');
$function$
;
CREATE OR REPLACE FUNCTION public.integration_retry_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(), 'settings', 'view')) THEN
    RAISE EXCEPTION 'not_authorized_integration_retry' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'queued', count(*) FILTER (WHERE status = 'queued'),
    'processing', count(*) FILTER (WHERE status = 'processing'),
    'retry_scheduled', count(*) FILTER (WHERE status = 'retry_scheduled'),
    'succeeded', count(*) FILTER (WHERE status = 'succeeded'),
    'failed', count(*) FILTER (WHERE status = 'failed'),
    'cancelled', count(*) FILTER (WHERE status = 'cancelled'),
    'dead_letter', count(*) FILTER (WHERE status = 'dead_letter'),
    'oldest_pending_at', min(created_at) FILTER (WHERE status IN ('queued','retry_scheduled','processing')),
    'due_now', count(*) FILTER (WHERE status IN ('queued','retry_scheduled') AND next_attempt_at <= now())
  ) INTO v FROM public.integration_retry_queue;

  SELECT v || jsonb_build_object(
    'dlq_open', count(*) FILTER (WHERE resolution_status = 'open'),
    'dlq_retrying', count(*) FILTER (WHERE resolution_status = 'retrying'),
    'dlq_resolved', count(*) FILTER (WHERE resolution_status = 'resolved'),
    'dlq_total', count(*)
  ) INTO v FROM public.integration_dead_letter;

  RETURN v;
END; $function$
;
CREATE OR REPLACE FUNCTION public.integration_retry_now(_id uuid, _justification text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v public.integration_retry_queue;
BEGIN
  PERFORM public.integration_retry_assert_operator();
  IF coalesce(btrim(_justification),'') = '' THEN
    RAISE EXCEPTION 'justification_required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v FROM public.integration_retry_queue WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'retry_item_not_found'; END IF;

  -- Idempotency key/fingerprint deliberately unchanged.
  UPDATE public.integration_retry_queue
     SET status = 'retry_scheduled',
         next_attempt_at = now(),
         max_attempts = greatest(max_attempts, attempts + 1),
         lease_owner = NULL, leased_until = NULL,
         dead_lettered_at = NULL, completed_at = NULL,
         cancelled_at = NULL, cancelled_reason = NULL, cancelled_by = NULL
   WHERE id = _id;

  UPDATE public.integration_dead_letter
     SET resolution_status = 'retrying', last_retried_at = now(), last_retried_by = auth.uid()
   WHERE retry_queue_id = _id AND resolution_status IN ('open','retrying');

  PERFORM public.log_compliance_audit(
    'OVERRIDE'::compliance_audit_action, 'integration_retry_queue', _id::text,
    NULL, jsonb_build_object('status','retry_scheduled'), _justification, NULL, NULL,
    jsonb_build_object('integration_key', v.integration_key, 'operation', v.operation,
                       'source_module', v.source_module, 'correlation_id', v.correlation_id,
                       'event','integration.retry.manual'));
  RETURN _id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.integration_retry_record_outcome(_id uuid, _ok boolean, _execution_mode text DEFAULT NULL::text, _error_category text DEFAULT NULL::text, _error text DEFAULT NULL::text, _provider_status integer DEFAULT NULL::integer, _integration_log_id uuid DEFAULT NULL::uuid, _provider_response jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.integration_retry_queue;
  v_delay_ms numeric;
  v_history jsonb;
  v_outcome text;
BEGIN
  SELECT * INTO v FROM public.integration_retry_queue WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RETURN 'not_found'; END IF;

  v_history := v.attempt_history || jsonb_build_array(jsonb_build_object(
    'attempt', v.attempts,
    'at', now(),
    'ok', _ok,
    'execution_mode', _execution_mode,
    'error_category', _error_category,
    'error', left(coalesce(_error,''), 500),
    'provider_status', _provider_status,
    'integration_log_id', _integration_log_id,
    'worker', v.lease_owner
  ));

  IF _ok THEN
    UPDATE public.integration_retry_queue
       SET status = 'succeeded', completed_at = now(), lease_owner = NULL,
           leased_until = NULL, attempt_history = v_history,
           last_error_category = NULL, last_error = NULL,
           last_provider_status = _provider_status,
           last_integration_log_id = coalesce(_integration_log_id, last_integration_log_id)
     WHERE id = _id;
    RETURN 'succeeded';
  END IF;

  -- A permanent business rejection stops retrying immediately.
  IF NOT public.integration_retry_is_retryable(_error_category) THEN
    v_outcome := 'failed';
  ELSIF v.attempts >= v.max_attempts THEN
    v_outcome := 'dead_letter';
  ELSE
    v_outcome := 'retry_scheduled';
  END IF;

  IF v_outcome = 'retry_scheduled' THEN
    v_delay_ms := CASE v.backoff_strategy
      WHEN 'fixed' THEN v.backoff_base_ms
      ELSE v.backoff_base_ms * power(2, greatest(0, v.attempts - 1))
    END;
    IF v.backoff_strategy = 'exponential_jitter' THEN
      v_delay_ms := v_delay_ms * (0.5 + random());
    END IF;
    v_delay_ms := least(v_delay_ms, 3600000); -- cap at 1h
    UPDATE public.integration_retry_queue
       SET status = 'retry_scheduled', lease_owner = NULL, leased_until = NULL,
           next_attempt_at = now() + make_interval(secs => v_delay_ms / 1000.0),
           attempt_history = v_history,
           last_error_category = _error_category, last_error = _error,
           last_provider_status = _provider_status,
           last_integration_log_id = coalesce(_integration_log_id, last_integration_log_id)
     WHERE id = _id;
    RETURN 'retry_scheduled';
  END IF;

  UPDATE public.integration_retry_queue
     SET status = CASE WHEN v_outcome = 'dead_letter' THEN 'dead_letter' ELSE 'failed' END,
         lease_owner = NULL, leased_until = NULL,
         attempt_history = v_history,
         last_error_category = _error_category, last_error = _error,
         last_provider_status = _provider_status,
         last_integration_log_id = coalesce(_integration_log_id, last_integration_log_id),
         dead_lettered_at = CASE WHEN v_outcome = 'dead_letter' THEN now() ELSE NULL END,
         completed_at = now()
   WHERE id = _id;

  IF v_outcome = 'dead_letter' THEN
    INSERT INTO public.integration_dead_letter (
      retry_queue_id, integration_key, connection_id, operation, source_module,
      business_event, source_entity_type, source_entity_id, actor_id, correlation_id,
      idempotency_key, idempotency_fingerprint, payload, redacted_fields,
      provider_response, attempts, attempt_history, error_category, error_message,
      provider_status, integration_log_id, metadata
    ) VALUES (
      v.id, v.integration_key, v.connection_id, v.operation, v.source_module,
      v.business_event, v.source_entity_type, v.source_entity_id, v.actor_id, v.correlation_id,
      v.idempotency_key, v.idempotency_fingerprint, v.payload, v.redacted_fields,
      coalesce(_provider_response,'{}'::jsonb), v.attempts, v_history,
      _error_category, _error, _provider_status,
      coalesce(_integration_log_id, v.last_integration_log_id), v.metadata
    );
  END IF;

  RETURN v_outcome;
END; $function$
;
CREATE OR REPLACE FUNCTION public.integration_retry_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$
;
CREATE OR REPLACE FUNCTION public.intragroup_exposure_matrix(_group_id uuid, _period_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_method public.group_consolidation_methods;
  v_pct numeric := 10;
  v_capital numeric;
  v_basis text := 'group_total_exposure';
  v_threshold numeric;
  v_total numeric := 0;
  v_cells jsonb := '[]'::jsonb;
  v_by_type jsonb := '{}'::jsonb;
  v_large jsonb := '[]'::jsonb;
  v_cycles jsonb := '[]'::jsonb;
  v_entities jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_method FROM public.group_consolidation_methods
   WHERE group_id = _group_id AND is_active ORDER BY version DESC LIMIT 1;
  IF v_method.id IS NOT NULL THEN v_pct := COALESCE(v_method.large_exposure_pct, 10); END IF;

  SELECT jsonb_agg(jsonb_build_object('entity_id', l.id, 'name', l.name) ORDER BY l.name)
    INTO v_entities
  FROM public.financial_group_members m JOIN public.licensees l ON l.id = m.licensee_id
  WHERE m.group_id = _group_id;
  v_entities := COALESCE(v_entities, '[]'::jsonb);

  SELECT COALESCE(SUM(amount),0) INTO v_total FROM public.intragroup_exposures
   WHERE group_id = _group_id AND period_key = _period_key;

  -- Group capital basis (only when a capital ratio key is configured and present)
  IF v_method.capital_ratio_key IS NOT NULL THEN
    SELECT SUM(value) INTO v_capital FROM public.group_member_ratios(_group_id, _period_key)
     WHERE ratio_key = v_method.capital_ratio_key AND value IS NOT NULL;
    IF v_capital IS NOT NULL AND v_capital > 0 THEN v_basis := 'group_capital'; END IF;
  END IF;

  v_threshold := (v_pct / 100.0) * COALESCE(NULLIF(v_capital,0), v_total);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'from_entity_id', e.from_entity_id, 'to_entity_id', e.to_entity_id,
           'amount', e.amount, 'types', e.types, 'is_large', e.amount >= v_threshold AND v_threshold > 0)), '[]'::jsonb)
    INTO v_cells
  FROM (
    SELECT from_entity_id, to_entity_id, SUM(amount) AS amount,
           jsonb_object_agg(exposure_type, t_amount) AS types
    FROM (
      SELECT from_entity_id, to_entity_id, exposure_type, SUM(amount) AS t_amount, SUM(amount) AS amount
      FROM public.intragroup_exposures
      WHERE group_id = _group_id AND period_key = _period_key
      GROUP BY 1,2,3
    ) s GROUP BY 1,2
  ) e;

  SELECT COALESCE(jsonb_object_agg(exposure_type, total), '{}'::jsonb) INTO v_by_type
  FROM (SELECT exposure_type, SUM(amount) AS total FROM public.intragroup_exposures
        WHERE group_id = _group_id AND period_key = _period_key GROUP BY 1) t;

  SELECT COALESCE(jsonb_agg(c), '[]'::jsonb) INTO v_large
  FROM jsonb_array_elements(v_cells) c WHERE (c->>'is_large')::boolean;

  -- Circular chain detection
  WITH RECURSIVE edges AS (
    SELECT DISTINCT from_entity_id AS f, to_entity_id AS t
    FROM public.intragroup_exposures
    WHERE group_id = _group_id AND period_key = _period_key AND amount > 0
  ), paths(start_id, current_id, path, len) AS (
    SELECT f, t, ARRAY[f,t], 1 FROM edges
    UNION ALL
    SELECT p.start_id, e.t, p.path || e.t, p.len + 1
    FROM paths p JOIN edges e ON e.f = p.current_id
    WHERE p.len < 6 AND NOT (e.t = ANY (p.path[2:array_length(p.path,1)]))
  )
  SELECT COALESCE(jsonb_agg(DISTINCT jsonb_build_object('chain', to_jsonb(path), 'length', len)), '[]'::jsonb)
    INTO v_cycles
  FROM paths WHERE current_id = start_id AND len > 1;

  RETURN jsonb_build_object(
    'entities', v_entities,
    'cells', v_cells,
    'by_type', v_by_type,
    'total', v_total,
    'large_exposure_pct', v_pct,
    'large_exposure_threshold', v_threshold,
    'large_exposure_basis', v_basis,
    'large_exposures', v_large,
    'circular_chains', v_cycles
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.is_appeal_panel_member(_user_id uuid, _appeal_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.license_appeal_panel_snapshots s,
         LATERAL jsonb_array_elements(s.member_roster) m
    WHERE s.appeal_id = _appeal_id
      AND (m->>'user_id')::uuid = _user_id
  );
$function$
;
CREATE OR REPLACE FUNCTION public.is_assignment_only_regulator(_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_has_assignment boolean;
  v_has_any_permission boolean;
BEGIN
  IF _user_id IS NULL THEN
    RETURN false;
  END IF;
  IF public.is_super_admin(_user_id) THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.licensees l
    WHERE l.lead_regulator_id = _user_id
       OR l.regulator_officer_id = _user_id
       OR l.alternate_regulator_id = _user_id
  ) INTO v_has_assignment;

  IF NOT v_has_assignment THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_dynamic_roles udr
    JOIN public.role_permissions rp ON rp.role_id = udr.role_id
    WHERE udr.user_id = _user_id
  ) INTO v_has_any_permission;

  RETURN NOT v_has_any_permission;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.is_collab_admin(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
