$function$
;
CREATE OR REPLACE FUNCTION public.is_doc_staff(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = _user_id
      AND ur.role::text IN ('super_admin','admin','supervisor','licensing_officer','analyst')
  )
$function$
;
CREATE OR REPLACE FUNCTION public.is_eligible_ppoc_user(_user_id uuid, _existing_mapping_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_profile record;
  v_is_existing_mapping_user boolean := false;
BEGIN
  SELECT id, status, user_type::text AS user_type, role, licensee_id
    INTO v_profile
    FROM public.profiles
   WHERE id = _user_id;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF _existing_mapping_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
        FROM public.ppoc_entity_mappings m
       WHERE m.id = _existing_mapping_id
         AND m.ppoc_user_id = _user_id
    ) INTO v_is_existing_mapping_user;
  END IF;

  IF public.is_internal_staff_user(_user_id) THEN
    RETURN v_is_existing_mapping_user;
  END IF;

  IF COALESCE(v_profile.status, 'inactive') <> 'active' THEN
    RETURN v_is_existing_mapping_user;
  END IF;

  IF v_profile.user_type IN ('primary', 'secondary') THEN
    RETURN true;
  END IF;

  IF COALESCE(v_profile.role, '') IN ('licensee_primary', 'licensee_secondary', 'primary', 'ppoc', 'entity_contact') THEN
    RETURN true;
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.user_roles ur
     WHERE ur.user_id = _user_id
       AND ur.role IN ('licensee_primary'::app_role, 'licensee_secondary'::app_role)
  ) THEN
    RETURN true;
  END IF;

  RETURN v_is_existing_mapping_user;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.is_fp_staff(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    public.has_role(_user_id, 'super_admin'::app_role)
    OR public.has_role(_user_id, 'admin'::app_role)
    OR public.has_role(_user_id, 'supervisor'::app_role)
    OR public.has_role(_user_id, 'licensing_officer'::app_role)
    OR public.has_role(_user_id, 'analyst'::app_role)
    OR public.has_role(_user_id, 'legal_compliance'::app_role)
    OR public.has_role(_user_id, 'developer'::app_role);
$function$
;
CREATE OR REPLACE FUNCTION public.is_internal_staff(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = _user_id
      AND ur.role IN ('super_admin'::public.app_role, 'admin'::public.app_role, 'supervisor'::public.app_role, 'licensing_officer'::public.app_role, 'analyst'::public.app_role, 'legal_compliance'::public.app_role, 'developer'::public.app_role)
  )
  OR EXISTS (
    SELECT 1
    FROM public.user_dynamic_roles udr
    JOIN public.roles r ON r.id = udr.role_id
    WHERE udr.user_id = _user_id
      AND (
        r.role_type = 'internal'
        OR r.system_role IN ('super_admin', 'admin', 'supervisor', 'licensing_officer', 'analyst', 'legal_compliance', 'developer')
      )
  )
  OR EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = _user_id
      AND (
        p.role IN ('super_admin', 'admin', 'supervisor', 'licensing_officer', 'analyst', 'legal_compliance', 'developer')
        OR p.user_type = 'employee'
      )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.is_internal_staff_user(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.has_role(_user_id, 'super_admin'::app_role)
      OR public.has_role(_user_id, 'admin'::app_role)
      OR public.has_role(_user_id, 'supervisor'::app_role)
      OR public.has_role(_user_id, 'licensing_officer'::app_role)
      OR public.has_role(_user_id, 'analyst'::app_role)
      OR public.has_role(_user_id, 'developer'::app_role)
$function$
;
CREATE OR REPLACE FUNCTION public.is_legal_compliance_user(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_dynamic_roles udr
    JOIN public.roles r ON r.id = udr.role_id
    WHERE udr.user_id = _user_id
      AND (r.system_role = 'legal_compliance'
           OR r.name IN ('Legal/Compliance Reviewer','Legal / Compliance Reviewer'))
  )
$function$
;
CREATE OR REPLACE FUNCTION public.is_primary_user_of(_entity_id uuid, _user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.entity_user_access
    WHERE entity_id = _entity_id AND user_id = _user_id
      AND access_type = 'primary_user' AND is_active = true
