CREATE OR REPLACE FUNCTION public.is_prudential_action_entity_user(_user uuid, _action_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.prudential_actions a
     WHERE a.id = _action_id
       AND (
         a.entity_owner_user_id = _user
         OR EXISTS (SELECT 1 FROM public.entity_user_access eua
                     WHERE eua.entity_id = a.entity_id AND eua.user_id = _user)
         OR EXISTS (SELECT 1 FROM public.profiles p
                     WHERE p.id = _user AND p.licensee_id = a.entity_id)
       )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.is_record_assigned_to_user(_user_id uuid, _module text, _record_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  m text := lower(regexp_replace(coalesce(_module,''),'\s+','_','g'));
  hit boolean;
BEGIN
  IF _user_id IS NULL OR _record_id IS NULL OR m = '' THEN
    RETURN false;
  END IF;

  IF m IN ('application_management','applications') THEN
    SELECT EXISTS(SELECT 1 FROM public.applications a
                  WHERE a.id = _record_id AND a.assigned_to = _user_id) INTO hit;
    RETURN COALESCE(hit,false);

  ELSIF m IN ('complaint_management','complaints') THEN
    SELECT EXISTS(SELECT 1 FROM public.complaints c
                  WHERE c.id = _record_id AND c.investigator_id = _user_id)
        OR EXISTS(SELECT 1 FROM public.complaint_investigation_tasks t
                  WHERE t.complaint_id = _record_id AND t.owner_id = _user_id)
      INTO hit;
    RETURN COALESCE(hit,false);

  ELSIF m IN ('conduct_investigations','market_conduct') THEN
    SELECT EXISTS(SELECT 1 FROM public.conduct_investigations i
                  WHERE i.id = _record_id AND i.assigned_investigator = _user_id) INTO hit;
    RETURN COALESCE(hit,false);

  ELSIF m = 'conduct_alerts' THEN
    SELECT EXISTS(SELECT 1 FROM public.conduct_alerts a
                  WHERE a.id = _record_id AND a.assigned_to = _user_id) INTO hit;
    RETURN COALESCE(hit,false);

  ELSIF m IN ('inspection_management','inspections') THEN
    SELECT EXISTS(SELECT 1 FROM public.inspections i
                  WHERE i.id = _record_id
                    AND (i.lead_inspector_id = _user_id OR i.inspector_id = _user_id))
      INTO hit;
    RETURN COALESCE(hit,false);

  ELSIF m IN ('prudential_supervision','prudential_actions') THEN
    SELECT EXISTS(SELECT 1 FROM public.prudential_actions p
                  WHERE p.id = _record_id AND p.assigned_to = _user_id)
        OR EXISTS(SELECT 1 FROM public.entity_supervision_assignments a
                  WHERE a.entity_id = _record_id
                    AND a.supervisor_id = _user_id
                    AND COALESCE(a.status,'active') = 'active'
                    AND (a.effective_from IS NULL OR a.effective_from <= now())
                    AND (a.effective_to IS NULL OR a.effective_to >= now()))
        OR EXISTS(SELECT 1 FROM public.licensees l
                  WHERE l.id = _record_id
                    AND (l.lead_regulator_id = _user_id
                      OR l.regulator_officer_id = _user_id
                      OR l.alternate_regulator_id = _user_id
                      OR l.assigned_supervisor_id = _user_id))
      INTO hit;
    RETURN COALESCE(hit,false);

  ELSIF m IN ('licensee_management','licensees','license_management','licenses','returns_management','compliance_returns','returns_filed') THEN
    SELECT EXISTS(
      SELECT 1 FROM public.licensees l
      WHERE l.id = _record_id
        AND (l.lead_regulator_id = _user_id
          OR l.regulator_officer_id = _user_id
          OR l.alternate_regulator_id = _user_id
          OR l.assigned_supervisor_id = _user_id)
    ) INTO hit;
    RETURN COALESCE(hit,false);
  END IF;

  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.is_super_admin(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT _user_id IS NOT NULL AND public.has_role(_user_id, 'super_admin'::app_role);
$function$
;
CREATE OR REPLACE FUNCTION public.issue_decision_artifact(_application_id uuid, _artifact_type text, _rendered_html text, _merge_data jsonb DEFAULT '{}'::jsonb, _decision text DEFAULT NULL::text, _template_id uuid DEFAULT NULL::uuid, _template_version text DEFAULT NULL::text, _rationale text DEFAULT NULL::text, _conditions jsonb DEFAULT '[]'::jsonb, _issuing_regulator_id uuid DEFAULT NULL::uuid, _effective_date date DEFAULT NULL::date, _expiry_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_missing text[] := ARRAY[]::text[];
  v_version int;
  v_id uuid;
  v_exists boolean;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  IF public.has_external_role(v_actor) THEN
    PERFORM public.log_security_event(
      'ACCESS_DENIED'::security_event_type, 'issue_decision_artifact', NULL, NULL,
      jsonb_build_object('reason', 'external_role', 'application_id', _application_id),
      NULL, 'high', 'license_management', 'issue', 'decision_artifact', _application_id::text, NULL);
    RAISE EXCEPTION 'not authorised to issue decision artifacts';
  END IF;

  IF NOT public.can_issue_decision_artifact(v_actor) THEN
    PERFORM public.log_security_event(
      'ACCESS_DENIED'::security_event_type, 'issue_decision_artifact', NULL, NULL,
      jsonb_build_object('reason', 'no_licensing_decision_authority', 'application_id', _application_id),
      NULL, 'high', 'license_management', 'issue', 'decision_artifact', _application_id::text, NULL);
    RAISE EXCEPTION 'not authorised to issue decision artifacts';
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.applications WHERE id = _application_id) INTO v_exists;
  IF NOT v_exists THEN
    RAISE EXCEPTION 'application not found';
  END IF;

  IF NOT public.can_mutate_application(v_actor, _application_id) THEN
    PERFORM public.log_security_event(
      'ACCESS_DENIED'::security_event_type, 'issue_decision_artifact', NULL, NULL,
      jsonb_build_object('reason', 'no_application_decision_rights', 'application_id', _application_id),
      NULL, 'high', 'license_management', 'issue', 'decision_artifact', _application_id::text, NULL);
    RAISE EXCEPTION 'not authorised to issue decision artifacts for this application';
  END IF;

  IF _artifact_type NOT IN ('decision_letter', 'license_certificate') THEN
    RAISE EXCEPTION 'invalid artifact_type';
  END IF;

  IF btrim(coalesce(_merge_data->>'application_number', '')) = '' THEN
    v_missing := array_append(v_missing, 'application_number');
  END IF;
  IF btrim(coalesce(_merge_data->>'applicant_name', '')) = '' THEN
    v_missing := array_append(v_missing, 'applicant_name');
  END IF;
  IF btrim(coalesce(_merge_data->>'license_type', '')) = '' THEN
    v_missing := array_append(v_missing, 'license_type');
  END IF;
  IF _artifact_type = 'decision_letter' AND btrim(coalesce(_rationale, '')) = '' THEN
    v_missing := array_append(v_missing, 'rationale');
  END IF;
  IF _artifact_type = 'license_certificate' AND _effective_date IS NULL THEN
    v_missing := array_append(v_missing, 'effective_date');
  END IF;
  IF btrim(coalesce(_rendered_html, '')) = '' THEN
    v_missing := array_append(v_missing, 'rendered_document');
  END IF;

  IF array_length(v_missing, 1) > 0 THEN
    RETURN jsonb_build_object('success', false, 'code', 'MISSING_MERGE_FIELDS', 'missing', to_jsonb(v_missing));
  END IF;

  SELECT coalesce(max(version), 0) + 1 INTO v_version
  FROM public.decision_artifacts
  WHERE application_id = _application_id AND artifact_type = _artifact_type;

  INSERT INTO public.decision_artifacts (
    application_id, artifact_type, version, decision, template_id, template_version,
    rendered_html, merge_data, rationale, conditions, issuing_regulator_id,
    effective_date, expiry_date, checksum, issued_by
  ) VALUES (
    _application_id, _artifact_type, v_version, _decision, _template_id, _template_version,
    _rendered_html, coalesce(_merge_data, '{}'::jsonb), _rationale, coalesce(_conditions, '[]'::jsonb),
    _issuing_regulator_id, _effective_date, _expiry_date,
    md5(coalesce(_rendered_html, '') || coalesce(_merge_data::text, '')), v_actor
  ) RETURNING id INTO v_id;

  PERFORM public.log_compliance_audit(
    'APPROVE'::compliance_audit_action,
    'decision_artifact',
    v_id::text,
    NULL,
    jsonb_build_object('application_id', _application_id, 'artifact_type', _artifact_type, 'version', v_version),
    NULL, NULL, NULL,
    jsonb_build_object('source', 'issue_decision_artifact')
  );

  RETURN jsonb_build_object('success', true, 'id', v_id, 'version', v_version);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.issue_payment_invoice(_payment_id uuid, _fee_breakdown jsonb DEFAULT NULL::jsonb, _tax_amount numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_pay record;
  v_rec record;
  v_app record;
  v_name text;
  v_email text;
  v_lines jsonb;
  v_subtotal numeric;
  v_snapshot jsonb;
BEGIN
  SELECT * INTO v_pay FROM public.payments WHERE id = _payment_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'message', 'Payment not found.');
  END IF;

  IF v_uid IS NULL OR (v_pay.user_id <> v_uid
      AND NOT public.has_role(v_uid,'super_admin'::app_role)
      AND NOT public.has_role(v_uid,'admin'::app_role)) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'message', 'You do not have access to this payment.');
  END IF;

  IF lower(COALESCE(v_pay.status,'')) NOT IN ('completed','success','paid') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_PAID', 'message', 'Invoice is available once the payment is confirmed.');
  END IF;

  SELECT * INTO v_rec FROM public.payment_receipts WHERE payment_id = _payment_id;
  IF FOUND THEN
    IF v_rec.invoice_number IS NULL THEN
      UPDATE public.payment_receipts
         SET invoice_number = public.next_invoice_number()
       WHERE id = v_rec.id
       RETURNING * INTO v_rec;
    END IF;
    RETURN jsonb_build_object('ok', true, 'created', false, 'receipt_id', v_rec.id,
      'invoice_number', v_rec.invoice_number, 'total_amount', v_rec.total_amount);
  END IF;

  SELECT a.application_number, a.license_type, a.status
    INTO v_app
    FROM public.applications a
   WHERE a.id = v_pay.application_id;

  SELECT COALESCE(NULLIF(TRIM(COALESCE(pr.entity_name, '')), ''), NULLIF(TRIM(COALESCE(pr.full_name,'')),''), pr.email, 'Applicant'),
         pr.email
    INTO v_name, v_email
    FROM public.profiles pr
   WHERE pr.id = v_pay.user_id;

  v_lines := CASE
    WHEN _fee_breakdown IS NULL OR jsonb_typeof(_fee_breakdown) <> 'array' OR jsonb_array_length(_fee_breakdown) = 0
      THEN jsonb_build_array(jsonb_build_object('label','Application fee','amount', v_pay.amount))
    ELSE _fee_breakdown
  END;

  SELECT COALESCE(SUM((item->>'amount')::numeric), v_pay.amount)
    INTO v_subtotal
    FROM jsonb_array_elements(v_lines) item;

  IF v_subtotal + COALESCE(_tax_amount,0) <> v_pay.amount THEN
    v_lines := jsonb_build_array(jsonb_build_object('label','Application fee','amount', v_pay.amount));
    v_subtotal := v_pay.amount;
    _tax_amount := 0;
  END IF;

  v_snapshot := jsonb_build_object(
    'issued_at', now(),
    'invoice_date', now(),
    'payment_status', v_pay.status,
    'issued_to_name', COALESCE(v_name,'Applicant'),
    'issued_to_email', v_email,
    'application_id', v_pay.application_id,
    'application_number', v_app.application_number,
    'license_type', v_app.license_type,
    'fee_lines', v_lines,
    'subtotal', v_subtotal,
    'tax_amount', COALESCE(_tax_amount,0),
    'total_amount', v_subtotal + COALESCE(_tax_amount,0),
    'currency', COALESCE(v_pay.currency,'USD'),
    'payment_method', COALESCE(v_pay.offline_method, v_pay.payment_method),
    'payment_channel', v_pay.payment_channel,
    'payment_reference', v_pay.transaction_ref,
    'paid_at', COALESCE(v_pay.paid_at, now())
  );

  INSERT INTO public.payment_receipts (
    payment_id, issued_to_name, issued_to_email, amount, currency, fee_breakdown,
    invoice_number, application_id, subtotal, tax_amount, total_amount,
    payment_method, payment_reference, payment_channel, paid_at, issued_by, snapshot
  ) VALUES (
    v_pay.id, COALESCE(v_name,'Applicant'), v_email, v_pay.amount, COALESCE(v_pay.currency,'USD'), v_lines,
    public.next_invoice_number(), v_pay.application_id, v_subtotal, COALESCE(_tax_amount,0),
    v_subtotal + COALESCE(_tax_amount,0),
    COALESCE(v_pay.offline_method, v_pay.payment_method), v_pay.transaction_ref, v_pay.payment_channel,
    COALESCE(v_pay.paid_at, now()), v_uid, v_snapshot
  )
  RETURNING * INTO v_rec;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
  VALUES (v_uid, 'invoice_issued', 'payment', v_pay.id,
          jsonb_build_object('invoice_number', v_rec.invoice_number,
                             'total_amount', v_rec.total_amount,
                             'application_id', v_pay.application_id));

  RETURN jsonb_build_object('ok', true, 'created', true, 'receipt_id', v_rec.id,
    'invoice_number', v_rec.invoice_number, 'total_amount', v_rec.total_amount);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.issue_worker_token(_purpose text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_token text;
BEGIN
  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  DELETE FROM public.worker_invocation_tokens WHERE expires_at < now() - interval '1 hour';
  INSERT INTO public.worker_invocation_tokens (token, purpose, expires_at)
  VALUES (v_token, _purpose, now() + interval '5 minutes');
  RETURN v_token;
END; $function$
;
CREATE OR REPLACE FUNCTION public.jsonb_changed_fields(_before jsonb, _after jsonb)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(array_agg(DISTINCT k ORDER BY k), ARRAY[]::text[])
  FROM (
    SELECT k
    FROM jsonb_object_keys(COALESCE(_before, '{}'::jsonb) || COALESCE(_after, '{}'::jsonb)) AS k
    WHERE COALESCE(_before -> k, 'null'::jsonb) IS DISTINCT FROM COALESCE(_after -> k, 'null'::jsonb)
  ) s;
$function$
;
CREATE OR REPLACE FUNCTION public.latest_return_analysis(_return_id uuid)
 RETURNS SETOF return_consolidated_analysis
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT * FROM public.return_consolidated_analysis
   WHERE return_id = _return_id
   ORDER BY computed_at DESC
   LIMIT 1
$function$
;
CREATE OR REPLACE FUNCTION public.legacy_return_can_file(_uid uuid, _entity_id uuid, _on_behalf uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF _uid IS NULL THEN RETURN false; END IF;
  IF public.is_super_admin(_uid) THEN RETURN true; END IF;
  IF public.has_permission(_uid, 'returns_management', 'submit') THEN RETURN true; END IF;
  IF _entity_id IS NOT NULL AND _entity_id = ANY (COALESCE(public.external_user_entity_ids(_uid), ARRAY[]::uuid[])) THEN RETURN true; END IF;
  IF _on_behalf IS NOT NULL AND _on_behalf = ANY (COALESCE(public.ppoc_mapped_licensee_ids(_uid), ARRAY[]::uuid[])) THEN RETURN true; END IF;
  IF _entity_id IS NOT NULL AND _entity_id = ANY (COALESCE(public.ppoc_mapped_licensee_ids(_uid), ARRAY[]::uuid[])) THEN RETURN true; END IF;
  RETURN false;
END; $function$
;
CREATE OR REPLACE FUNCTION public.legacy_return_create(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _entity uuid; _on_behalf uuid; _id uuid; _after jsonb;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  _entity := nullif(_payload->>'entity_id','')::uuid;
  _on_behalf := nullif(_payload->>'on_behalf_of_licensee_id','')::uuid;
  IF _entity IS NULL THEN RAISE EXCEPTION 'entity_id is required' USING ERRCODE='22023'; END IF;
  IF NOT public.legacy_return_can_file(_uid, _entity, _on_behalf) THEN
    RAISE EXCEPTION 'You are not entitled to file returns for this entity' USING ERRCODE='42501';
  END IF;
  IF nullif(_payload->>'return_configuration_id','') IS NULL THEN
    RAISE EXCEPTION 'return_configuration_id is required' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.returns_filed (
    entity_id, on_behalf_of_licensee_id, return_configuration_id, sector_id, subsector_id,
    return_year, return_period, period_start_date, period_end_date, due_date,
    workflow_status, created_by, updated_by
  ) VALUES (
    _entity, _on_behalf,
    (_payload->>'return_configuration_id')::uuid,
    nullif(_payload->>'sector_id','')::uuid,
    nullif(_payload->>'subsector_id','')::uuid,
    nullif(_payload->>'return_year','')::int,
    nullif(_payload->>'return_period',''),
    nullif(_payload->>'period_start_date','')::date,
    nullif(_payload->>'period_end_date','')::date,
    nullif(_payload->>'due_date','')::date,
    'TEMP', _uid, _uid
  ) RETURNING id INTO _id;
  SELECT to_jsonb(r) INTO _after FROM public.returns_filed r WHERE r.id=_id;
  PERFORM public.log_compliance_audit('CREATE'::compliance_audit_action,'legacy_return',_id::text,NULL,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.legacy_return_delete_draft(_return_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _before jsonb;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  SELECT to_jsonb(r) INTO _before FROM public.returns_filed r WHERE r.id=_return_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Return not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.legacy_return_can_file(_uid, nullif(_before->>'entity_id','')::uuid, nullif(_before->>'on_behalf_of_licensee_id','')::uuid) THEN
    RAISE EXCEPTION 'You are not entitled to delete this return' USING ERRCODE='42501';
  END IF;
  IF upper(coalesce(_before->>'workflow_status','')) NOT IN ('TEMP','WIP') THEN
    RAISE EXCEPTION 'Only unsubmitted drafts can be deleted' USING ERRCODE='22023';
  END IF;
  DELETE FROM public.returns_filed WHERE id=_return_id;
  PERFORM public.log_compliance_audit('DELETE'::compliance_audit_action,'legacy_return',_return_id::text,_before,NULL,_reason);
  RETURN jsonb_build_object('deleted', true, 'id', _return_id);
END; $function$
;
CREATE OR REPLACE FUNCTION public.legacy_return_review_decision(_return_id uuid, _decision text, _comments text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _before jsonb; _after jsonb; _target text; _status text;
BEGIN
  IF _decision NOT IN ('approve','request_edit','reject') THEN
    RAISE EXCEPTION 'Invalid decision %', _decision USING ERRCODE='22023';
  END IF;
  PERFORM public.returns_require(CASE WHEN _decision='approve' THEN 'approve' ELSE 'review' END);
  _uid := auth.uid();
  SELECT to_jsonb(r) INTO _before FROM public.returns_filed r WHERE r.id=_return_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Return not found' USING ERRCODE='P0002'; END IF;
  _status := upper(coalesce(_before->>'workflow_status',''));
  IF _status NOT IN ('SUB','TBR') THEN
    RAISE EXCEPTION 'Return is not awaiting review (status %)', _status USING ERRCODE='22023';
  END IF;
  IF _decision <> 'approve' AND coalesce(length(btrim(_comments)),0) < 10 THEN
    RAISE EXCEPTION 'A rationale of at least 10 characters is required' USING ERRCODE='22023';
  END IF;
  _target := CASE _decision WHEN 'approve' THEN 'VAL' WHEN 'request_edit' THEN 'TBR' ELSE 'REJ' END;
  UPDATE public.returns_filed SET workflow_status=_target, updated_by=_uid, updated_at=now()
  WHERE id=_return_id RETURNING to_jsonb(returns_filed) INTO _after;
  PERFORM public.log_compliance_audit(
    (CASE WHEN _decision='approve' THEN 'APPROVE' WHEN _decision='reject' THEN 'REJECT' ELSE 'WORKFLOW_TRANSITION' END)::compliance_audit_action,
    'legacy_return',_return_id::text,_before,_after,_comments);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.legacy_return_save_draft(_return_id uuid, _patch jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _before jsonb; _after jsonb;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  SELECT to_jsonb(r) INTO _before FROM public.returns_filed r WHERE r.id=_return_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Return not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.legacy_return_can_file(_uid, nullif(_before->>'entity_id','')::uuid, nullif(_before->>'on_behalf_of_licensee_id','')::uuid) THEN
    RAISE EXCEPTION 'You are not entitled to edit this return' USING ERRCODE='42501';
  END IF;
  IF upper(coalesce(_before->>'workflow_status','')) NOT IN ('TEMP','WIP','TBR','REJ') THEN
    RAISE EXCEPTION 'This return can no longer be edited (status %)', _before->>'workflow_status' USING ERRCODE='22023';
  END IF;
  UPDATE public.returns_filed SET
    workflow_status = CASE
      WHEN upper(coalesce(_patch->>'workflow_status','')) IN ('TEMP','WIP') THEN upper(_patch->>'workflow_status')
      ELSE workflow_status END,
    explanations = CASE WHEN _patch ? 'explanations' THEN _patch->'explanations' ELSE explanations END,
    updated_by = _uid, updated_at = now()
  WHERE id=_return_id RETURNING to_jsonb(returns_filed) INTO _after;
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.legacy_return_submit(_return_id uuid, _ontime text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _before jsonb; _after jsonb; _status text; _ot text;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  SELECT to_jsonb(r) INTO _before FROM public.returns_filed r WHERE r.id=_return_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Return not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.legacy_return_can_file(_uid, nullif(_before->>'entity_id','')::uuid, nullif(_before->>'on_behalf_of_licensee_id','')::uuid) THEN
    RAISE EXCEPTION 'You are not entitled to file this return' USING ERRCODE='42501';
  END IF;
  _status := upper(coalesce(_before->>'workflow_status',''));
  IF _status NOT IN ('TEMP','WIP','TBR','REJ') THEN
    RAISE EXCEPTION 'Return cannot be submitted from status %', _status USING ERRCODE='22023';
  END IF;
  _ot := CASE WHEN upper(coalesce(_ontime,'')) IN ('ON_TIME','LATE') THEN upper(_ontime)
              WHEN nullif(_before->>'due_date','') IS NOT NULL
                   AND current_date > (_before->>'due_date')::date THEN 'LATE'
              ELSE 'ON_TIME' END;
  UPDATE public.returns_filed SET
    workflow_status='SUB', submit_date=now(), ontime_status=_ot::ontime_status_enum,
    updated_by=_uid, updated_at=now()
  WHERE id=_return_id RETURNING to_jsonb(returns_filed) INTO _after;
  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION'::compliance_audit_action,'legacy_return',_return_id::text,_before,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.license_action_input_requirements(_license_id uuid, _action_key text, _matter_kind text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE cfg jsonb; v_days int; v_out jsonb := '[]'::jsonb;
BEGIN
  cfg := public.license_lifecycle_config_resolve(_license_id, COALESCE(_matter_kind,'renewal'));
  v_days := COALESCE((cfg->>'representation_period_days')::int, 14);

  IF _action_key = 'ISSUE_NOTICE' THEN
    v_out := jsonb_build_array(
      jsonb_build_object('key','subject','label','Notice subject','type','text','required',true),
      jsonb_build_object('key','body','label','Notice body','type','textarea','required',true),
      jsonb_build_object('key','legal_basis','label','Legal basis','type','textarea',
        'required', COALESCE((cfg->>'legal_basis_required')::boolean, true)),
      jsonb_build_object('key','delivery_channel','label','Delivery channel','type','select','required',true,
        'options', jsonb_build_array('email','post','registered_post','hand_delivery','portal')),
      jsonb_build_object('key','notice_reference','label','Notice reference','type','text','required',false),
      jsonb_build_object('key','correspondence_thread_id','label','Correspondence thread','type','text','required',false),
      jsonb_build_object('key','representation_deadline','label',
        'Representation deadline (server default: ' || v_days || ' days)','type','date','required',false,
        'help','Leave blank to use the configured representation period.')
    );
  ELSIF _action_key = 'RECORD_REPRESENTATION' THEN
    v_out := jsonb_build_array(
      jsonb_build_object('key','summary','label','Representation summary','type','textarea','required',true),
      jsonb_build_object('key','received_via','label','Received via','type','select','required',true,
        'options', jsonb_build_array('email','post','portal','meeting','other')),
      jsonb_build_object('key','submitter_name','label','Submitted by (name)','type','text','required',true),
      jsonb_build_object('key','received_at','label','Received date','type','date','required',false,
        'help','Late status is derived by the server from the notice deadline.')
    );
  ELSIF _action_key = 'WAIVE_REPRESENTATION_PERIOD' THEN
    v_out := jsonb_build_array(
      jsonb_build_object('key','waiver_reason','label','Waiver reason','type','textarea','required',true));
  ELSIF _action_key IN ('COMPLETE_EVIDENCE_REVIEW','COMPLETE_SURRENDER_REVIEW','COMPLETE_REINSTATEMENT_VERIFICATION') THEN
    v_out := jsonb_build_array(
      jsonb_build_object('key','legal_basis','label','Legal basis','type','textarea',
        'required', COALESCE((cfg->>'legal_basis_required')::boolean, false)));
  ELSIF _action_key IN ('SUSPEND','REVOKE','REINSTATE','ACCEPT_SURRENDER','MARK_EXPIRED',
                        'REFUSE_SURRENDER','REFUSE_REINSTATEMENT') THEN
    v_out := jsonb_build_array(
      jsonb_build_object('key','legal_basis','label','Legal basis','type','textarea',
        'required', COALESCE((cfg->>'legal_basis_required')::boolean, true)),
      jsonb_build_object('key','effective_date','label','Effective date','type','date','required',true),
      jsonb_build_object('key','artifact_reference','label','Decision artifact reference','type','text','required',false));
  ELSIF _action_key IN ('BEGIN_SUSPENSION','BEGIN_REVOCATION','BEGIN_SURRENDER','BEGIN_REINSTATEMENT','BEGIN_EXPIRY_REVIEW') THEN
    v_out := jsonb_build_array(
      jsonb_build_object('key','source_kind','label','Source / trigger','type','select','required',true,
        'options', jsonb_build_array('condition_breach','prudential_matter','examination_finding','conduct_matter',
          'enforcement_case','complaint','licensing_review','entity_request','time_based_expiry','manual_referral')),
      jsonb_build_object('key','source_reference','label','Source reference','type','text','required',false),
      jsonb_build_object('key','legal_basis','label','Legal basis','type','textarea','required',false),
      jsonb_build_object('key','team','label','Owning team','type','text','required',false),
      jsonb_build_object('key','due_at','label','Target completion date','type','date','required',false));
  END IF;

  RETURN v_out;
END $function$
;
CREATE OR REPLACE FUNCTION public.license_adverse_matter_case(_license_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  can_view boolean;
  v_matters jsonb := '[]'::jsonb;
  v_actions jsonb := '[]'::jsonb;
  m record; tl jsonb; n record; rp record; d record; pre jsonb; cfg jsonb;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  can_view := public.is_super_admin(uid)
           OR public.has_permission(uid,'license_management','view')
           OR EXISTS (SELECT 1 FROM public.licenses l WHERE l.id=_license_id AND l.holder_id=uid);
  IF NOT can_view THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;

  FOR m IN
    SELECT * FROM public.license_lifecycle_matters
     WHERE license_id = _license_id
       AND matter_kind IN ('suspension','revocation','reinstatement','surrender','expiry')
     ORDER BY (status='open') DESC, opened_at DESC
  LOOP
    cfg := public.license_lifecycle_config_resolve(_license_id, m.matter_kind);
    pre := CASE WHEN m.status='open' THEN public.license_matter_prerequisites(m.id) ELSE '[]'::jsonb END;

    tl := jsonb_build_array(jsonb_build_object(
      'key','matter_opened','label','Matter opened','at', m.opened_at,
      'detail', COALESCE(m.reason, m.title),
      'actor', (SELECT full_name FROM public.profiles p WHERE p.id = m.opened_by),
      'state','done'));

    FOR n IN SELECT * FROM public.license_matter_notices WHERE matter_id=m.id ORDER BY issued_at LOOP
      tl := tl || jsonb_build_array(
        jsonb_build_object('key','notice','label','Notice issued — ' || COALESCE(n.notice_reference,'unreferenced'),
          'at', n.issued_at, 'detail', n.subject,
          'actor', (SELECT full_name FROM public.profiles p WHERE p.id = n.issued_by), 'state','done',
          'meta', jsonb_build_object('delivery_channel', n.delivery_channel,
                                     'representation_deadline', n.representation_deadline,
                                     'legal_basis', n.legal_basis)),
        jsonb_build_object('key','notice_delivery','label','Delivery evidence',
          'at', n.delivery_confirmed_at, 'detail',
          CASE WHEN n.delivery_confirmed_at IS NOT NULL
               THEN 'Delivery confirmed via ' || COALESCE(n.delivery_channel,'unknown channel')
               ELSE 'Delivery not yet confirmed' END,
          'state', CASE WHEN n.delivery_confirmed_at IS NOT NULL THEN 'done' ELSE 'pending' END,
          'meta', jsonb_build_object('evidence', n.delivery_evidence)),
        jsonb_build_object('key','representation_window','label','Representation period',
          'at', n.representation_deadline,
          'detail', CASE WHEN n.representation_deadline IS NULL THEN 'No representation period configured'
                         WHEN n.representation_deadline > now() THEN 'Open until ' || to_char(n.representation_deadline,'DD Mon YYYY')
                         ELSE 'Closed ' || to_char(n.representation_deadline,'DD Mon YYYY') END,
          'state', CASE WHEN n.representation_deadline IS NULL THEN 'skipped'
                        WHEN n.representation_deadline > now() THEN 'current' ELSE 'done' END));
    END LOOP;

    FOR rp IN SELECT * FROM public.license_matter_representations WHERE matter_id=m.id ORDER BY received_at LOOP
      tl := tl || jsonb_build_array(jsonb_build_object(
        'key', CASE WHEN rp.is_waiver THEN 'representation_waived' ELSE 'representation_received' END,
        'label', CASE WHEN rp.is_waiver THEN 'Representation period waived' ELSE 'Representation received' END,
        'at', rp.received_at,
        'detail', COALESCE(rp.summary, rp.waiver_reason),
        'actor', COALESCE(rp.submitter_name, (SELECT full_name FROM public.profiles p WHERE p.id = rp.recorded_by)),
        'state','done',
        'meta', jsonb_build_object('received_via', rp.received_via, 'is_late', rp.is_late,
                                   'documents', rp.documents)));
    END LOOP;

    tl := tl || jsonb_build_array(jsonb_build_object(
      'key','evidence_review','label','Evidence review',
      'at', m.metadata->'complete_evidence_review'->>'at',
      'detail', COALESCE(m.metadata->'complete_evidence_review'->>'note',
                         m.metadata->'complete_surrender_review'->>'note',
                         m.metadata->'complete_reinstatement_verification'->>'note'),
      'state', CASE WHEN m.stage IN ('DECISION_READY','DECIDED','CLOSED') THEN 'done'
                    WHEN m.stage IN ('EVIDENCE_REVIEW','VERIFICATION','SURRENDER_REVIEW','EXPIRY_REVIEW') THEN 'current'
                    ELSE 'pending' END));

    FOR d IN SELECT * FROM public.license_decisions WHERE matter_id=m.id ORDER BY decided_at LOOP
      tl := tl || jsonb_build_array(
        jsonb_build_object('key','decision','label','Decision — ' || d.decision_reference,
          'at', d.decided_at, 'detail', d.rationale,
          'actor', (SELECT full_name FROM public.profiles p WHERE p.id = d.actor_id), 'state','done',
          'meta', jsonb_build_object('decision', d.decision, 'authority', d.authority,
                                     'from_status', d.from_status, 'to_status', d.to_status,
                                     'legal_basis', d.legal_basis)),
        jsonb_build_object('key','effective','label','Effective date', 'at', d.effective_date,
          'detail', NULL, 'state', CASE WHEN d.effective_date IS NULL THEN 'skipped' ELSE 'done' END),
        jsonb_build_object('key','appeal','label','Appeal rights',
          'at', d.appeal_deadline,
          'detail', CASE WHEN NOT d.appealable THEN 'Decision is not appealable'
                         ELSE 'Appealable until ' || to_char(d.appeal_deadline,'DD Mon YYYY') END,
          'state', CASE WHEN NOT d.appealable THEN 'skipped'
                        WHEN d.appeal_deadline > now() THEN 'current' ELSE 'done' END));
    END LOOP;

    tl := tl || jsonb_build_array(jsonb_build_object(
      'key','closure','label','Matter closed', 'at', m.closed_at,
      'detail', CASE WHEN m.closed_at IS NULL THEN 'Matter is open' ELSE m.decision END,
      'actor', (SELECT full_name FROM public.profiles p WHERE p.id = m.closed_by),
      'state', CASE WHEN m.closed_at IS NULL THEN 'pending' ELSE 'done' END));

    v_matters := v_matters || jsonb_build_array(jsonb_build_object(
      'id', m.id, 'matter_reference', m.matter_reference, 'matter_kind', m.matter_kind,
      'title', m.title, 'stage', m.stage, 'status', m.status,
      'source_kind', m.source_kind, 'source_reference', m.source_reference, 'source_id', m.source_id,
      'legal_basis', m.legal_basis, 'reason', m.reason,
      'owner_user_id', m.owner_user_id,
      'owner_name', (SELECT full_name FROM public.profiles p WHERE p.id = m.owner_user_id),
      'team', m.team, 'sla_due_at', m.sla_due_at, 'due_at', m.due_at,
      'sla_state', CASE WHEN m.status <> 'open' THEN 'closed'
                        WHEN m.sla_due_at IS NULL THEN 'none'
                        WHEN m.sla_due_at < now() THEN 'breached'
                        WHEN m.sla_due_at < now() + interval '3 days' THEN 'at_risk'
                        ELSE 'on_track' END,
      'waiting_on', m.waiting_on, 'opened_at', m.opened_at, 'closed_at', m.closed_at,
      'effective_date', m.effective_date, 'related_matter_id', m.related_matter_id,
      'related_matter_reference', (SELECT x.matter_reference FROM public.license_lifecycle_matters x WHERE x.id = m.related_matter_id),
      'blockers', pre,
      'config', cfg,
      'timeline', tl,
      'notices', COALESCE((SELECT jsonb_agg(to_jsonb(n2) ORDER BY n2.issued_at)
                             FROM public.license_matter_notices n2 WHERE n2.matter_id=m.id), '[]'::jsonb),
      'representations', COALESCE((SELECT jsonb_agg(to_jsonb(r2) ORDER BY r2.received_at)
                             FROM public.license_matter_representations r2 WHERE r2.matter_id=m.id), '[]'::jsonb),
      'decisions', COALESCE((SELECT jsonb_agg(to_jsonb(d2) ORDER BY d2.decided_at)
                             FROM public.license_decisions d2 WHERE d2.matter_id=m.id), '[]'::jsonb)
    ));
  END LOOP;

  SELECT COALESCE(jsonb_agg(a || jsonb_build_object('input_requirements',
            public.license_action_input_requirements(_license_id, a->>'key', a->>'matter_kind'))), '[]'::jsonb)
    INTO v_actions
    FROM jsonb_array_elements(public.license_lifecycle_available_actions(_license_id)) a;

  RETURN jsonb_build_object(
    'license_id', _license_id,
    'matters', v_matters,
    'actions', v_actions,
    'decisions', COALESCE((SELECT jsonb_agg(to_jsonb(d3) ORDER BY d3.decided_at DESC)
                             FROM public.license_decisions d3 WHERE d3.license_id=_license_id), '[]'::jsonb),
    'generated_at', now());
END $function$
;
CREATE OR REPLACE FUNCTION public.license_adverse_matters(_license_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE l record; res jsonb;
BEGIN
  SELECT * INTO l FROM public.licenses WHERE id = _license_id;
  IF l IS NULL THEN RAISE EXCEPTION 'LICENSE_NOT_FOUND' USING ERRCODE='22023'; END IF;
  IF NOT (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(),'license_management','view')
          OR l.holder_id = auth.uid()) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';
  END IF;

  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'opened_at' DESC), '[]'::jsonb) INTO res
  FROM (
    SELECT jsonb_build_object(
      'matter_id', m.id, 'matter_reference', m.matter_reference, 'matter_kind', m.matter_kind,
      'stage', m.stage, 'status', m.status, 'title', m.title, 'reason', m.reason,
      'legal_basis', m.legal_basis, 'source_kind', m.source_kind, 'source_id', m.source_id,
      'source_reference', m.source_reference, 'related_matter_id', m.related_matter_id,
      'waiting_on', m.waiting_on, 'owner_user_id', m.owner_user_id, 'team', m.team,
      'sla_due_at', COALESCE(m.sla_due_at, m.due_at), 'opened_at', m.opened_at, 'opened_by', m.opened_by,
      'closed_at', m.closed_at, 'decision', m.decision, 'effective_date', m.effective_date,
      'prerequisites', public.license_matter_prerequisites(m.id),
      'notices', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', n.id, 'notice_kind', n.notice_kind, 'notice_reference', n.notice_reference,
          'subject', n.subject, 'body', n.body, 'legal_basis', n.legal_basis, 'issued_at', n.issued_at,
          'issued_by', n.issued_by, 'representation_deadline', n.representation_deadline,
          'delivery_channel', n.delivery_channel, 'delivery_evidence', n.delivery_evidence,
          'delivery_confirmed_at', n.delivery_confirmed_at,
          'correspondence_thread_id', n.correspondence_thread_id) ORDER BY n.issued_at DESC)
        FROM public.license_matter_notices n WHERE n.matter_id = m.id), '[]'::jsonb),
      'representations', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', r.id, 'received_at', r.received_at, 'received_via', r.received_via,
          'submitter_name', r.submitter_name, 'summary', r.summary, 'documents', r.documents,
          'is_late', r.is_late, 'is_waiver', r.is_waiver, 'waiver_reason', r.waiver_reason)
          ORDER BY r.received_at DESC)
        FROM public.license_matter_representations r WHERE r.matter_id = m.id), '[]'::jsonb),
      'decision_record', (
        SELECT jsonb_build_object(
          'decision_id', d.id, 'decision_reference', d.decision_reference,
          'decision_type', d.decision_type, 'decision', d.decision, 'authority', d.authority,
          'actor_id', d.actor_id, 'decided_at', d.decided_at, 'effective_date', d.effective_date,
          'rationale', d.rationale, 'legal_basis', d.legal_basis,
          'artifact_reference', d.artifact_reference, 'appealable', d.appealable,
          'appeal_deadline', d.appeal_deadline, 'matter_id', d.matter_id)
        FROM public.license_decisions d WHERE d.matter_id = m.id
        ORDER BY d.decided_at DESC LIMIT 1)
    ) AS x
    FROM public.license_lifecycle_matters m
    WHERE m.license_id = l.id
      AND m.matter_kind IN ('suspension','revocation','reinstatement','surrender','expiry')
  ) s;

  RETURN res;
END $function$
;
CREATE OR REPLACE FUNCTION public.license_appeal_acknowledge(_appeal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb;
BEGIN
  _uid := public.conduct_require('license_appeals','edit');
  SELECT to_jsonb(a) INTO _before FROM public.license_appeals a WHERE a.id=_appeal_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Appeal not found' USING ERRCODE='P0002'; END IF;
  IF coalesce(_before->>'status','') <> 'submitted' THEN
    RAISE EXCEPTION 'Only submitted appeals can be acknowledged (status %)', _before->>'status' USING ERRCODE='22023';
  END IF;
  UPDATE public.license_appeals SET status='under_review', acknowledged_at=now(), acknowledged_by=_uid, updated_at=now()
  WHERE id=_appeal_id RETURNING to_jsonb(license_appeals) INTO _after;
  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION'::compliance_audit_action,'license_appeal',_appeal_id::text,_before,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.license_appeal_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app RECORD;
  v_seq integer;
  v_year text := to_char(now(), 'YYYY');
BEGIN
  SELECT id, status, rejected_at, regulator_id, applicant_id
    INTO v_app
  FROM public.applications
  WHERE id = NEW.application_id;

  IF v_app.id IS NULL THEN
    RAISE EXCEPTION 'application_not_found';
  END IF;

  IF lower(coalesce(v_app.status, '')) <> 'rejected' THEN
    RAISE EXCEPTION 'appeal_requires_refused_application';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.license_appeals
    WHERE application_id = NEW.application_id
      AND status NOT IN ('withdrawn','rejected_out_of_time','decided')
  ) THEN
    RAISE EXCEPTION 'appeal_already_open_for_application';
  END IF;

  NEW.appeal_deadline := COALESCE(
    NEW.appeal_deadline,
    COALESCE(v_app.rejected_at, now()) + interval '30 days'
  );

  IF now() > NEW.appeal_deadline THEN
    RAISE EXCEPTION 'appeal_window_expired';
  END IF;

  NEW.regulator_id := COALESCE(NEW.regulator_id, v_app.regulator_id);
  NEW.filed_by := COALESCE(NEW.filed_by, auth.uid());
  NEW.status := COALESCE(NEW.status, 'submitted');

  SELECT count(*) + 1 INTO v_seq
  FROM public.license_appeals
  WHERE appeal_reference LIKE 'APL-' || v_year || '-%';

  NEW.appeal_reference := 'APL-' || v_year || '-' || lpad(v_seq::text, 6, '0');

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.license_appeal_file(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _app uuid; _id uuid; _after jsonb; _allowed boolean := false;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  _app := nullif(_payload->>'application_id','')::uuid;
  IF _app IS NULL THEN RAISE EXCEPTION 'application_id is required' USING ERRCODE='22023'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.applications a WHERE a.id=_app) THEN
    RAISE EXCEPTION 'Application not found' USING ERRCODE='P0002';
  END IF;
  IF coalesce(length(btrim(_payload->>'grounds')),0) < 10 THEN
    RAISE EXCEPTION 'Grounds of appeal are required (min 10 characters)' USING ERRCODE='22023';
  END IF;
  _allowed := public.is_super_admin(_uid)
    OR public.has_permission(_uid,'license_appeals','create')
    OR EXISTS (SELECT 1 FROM public.applications a WHERE a.id=_app AND a.applicant_id=_uid);
  IF NOT _allowed THEN RAISE EXCEPTION 'Permission denied: license_appeals.create' USING ERRCODE='42501'; END IF;
  INSERT INTO public.license_appeals (application_id, licensee_id, regulator_id, filed_by, grounds, relief_sought, appeal_deadline, status)
  VALUES (_app, nullif(_payload->>'licensee_id','')::uuid, nullif(_payload->>'regulator_id','')::uuid,
          _uid, btrim(_payload->>'grounds'), nullif(_payload->>'relief_sought',''),
          nullif(_payload->>'appeal_deadline','')::timestamptz, 'submitted')
  RETURNING id INTO _id;
  SELECT to_jsonb(a) INTO _after FROM public.license_appeals a WHERE a.id=_id;
  PERFORM public.log_compliance_audit('CREATE'::compliance_audit_action,'license_appeal',_id::text,NULL,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.license_appeal_log_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id)
    VALUES (NEW.id, 'filed', 'Appeal lodged (' || NEW.appeal_reference || ')', NEW.filed_by);
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id)
    VALUES (NEW.id, 'status_changed',
            'Status changed to ' || replace(NEW.status, '_', ' '), auth.uid());
  END IF;

  IF NEW.panel_id IS DISTINCT FROM OLD.panel_id AND NEW.panel_id IS NOT NULL THEN
    INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id)
    VALUES (NEW.id, 'panel_assigned',
            'Appeal panel assigned: ' ||
            COALESCE((SELECT name FROM public.license_appeal_panels WHERE id = NEW.panel_id), 'panel'),
            auth.uid());
  END IF;

  IF NEW.hearing_date IS DISTINCT FROM OLD.hearing_date AND NEW.hearing_date IS NOT NULL THEN
    INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id)
    VALUES (NEW.id, 'hearing_scheduled',
            'Hearing scheduled for ' || to_char(NEW.hearing_date, 'DD Mon YYYY'), auth.uid());
  END IF;

  IF NEW.decision IS DISTINCT FROM OLD.decision AND NEW.decision IS NOT NULL THEN
    INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id)
    VALUES (NEW.id, 'decided',
            'Decision recorded: ' || replace(NEW.decision, '_', ' '), auth.uid());
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.license_appeal_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.license_appeal_withdraw(_appeal_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _before jsonb; _after jsonb; _allowed boolean;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  SELECT to_jsonb(a) INTO _before FROM public.license_appeals a WHERE a.id=_appeal_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Appeal not found' USING ERRCODE='P0002'; END IF;
  _allowed := public.is_super_admin(_uid)
    OR public.has_permission(_uid,'license_appeals','edit')
    OR coalesce(_before->>'filed_by','') = _uid::text;
  IF NOT _allowed THEN RAISE EXCEPTION 'Permission denied: license_appeals.edit' USING ERRCODE='42501'; END IF;
  IF coalesce(_before->>'status','') IN ('decided','withdrawn','closed') THEN
    RAISE EXCEPTION 'Appeal is already concluded (status %)', _before->>'status' USING ERRCODE='22023';
  END IF;
  UPDATE public.license_appeals SET status='withdrawn', updated_at=now()
  WHERE id=_appeal_id RETURNING to_jsonb(license_appeals) INTO _after;
  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION'::compliance_audit_action,'license_appeal',_appeal_id::text,_before,_after,_reason);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.license_appealable_decisions(_license_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', d.id, 'reference', d.decision_reference, 'decision_type', d.decision_type,
           'decision', d.decision, 'decided_at', d.decided_at, 'appeal_deadline', d.appeal_deadline)
         ORDER BY d.decided_at DESC), '[]'::jsonb)
    FROM public.license_decisions d
   WHERE d.license_id = _license_id
     AND COALESCE(d.appealable,false)
     AND (d.appeal_deadline IS NULL OR d.appeal_deadline >= current_date)
     AND NOT EXISTS (SELECT 1 FROM public.license_decision_appeals a
                      WHERE a.decision_id = d.id AND a.status NOT IN ('withdrawn','determined'))
     AND public.is_internal_staff_user(auth.uid());
$function$
;
CREATE OR REPLACE FUNCTION public.license_case(_license_id uuid, _audience text DEFAULT 'internal'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  l record; ent record; pol jsonb;
  v_internal boolean;
  v_open_conditions int; v_overdue_conditions int;
  v_matter record; v_renewal record;
  v_days numeric; v_sla_state text; v_stage text; v_waiting text;
  v_priority text; v_priority_reason text;
  v_blockers jsonb := '[]'::jsonb; v_next jsonb;
  v_last timestamptz;
  v_owner_id uuid; v_owner_name text; v_team text;
  v_sa_supervisor uuid;
  v_actions jsonb := '[]'::jsonb;
BEGIN
  v_internal := public.is_super_admin(auth.uid()) OR public.has_permission(auth.uid(),'license_management','view');

  SELECT * INTO l FROM public.licenses WHERE id = _license_id;
  IF l IS NULL THEN RAISE EXCEPTION 'LICENSE_NOT_FOUND' USING ERRCODE = '22023'; END IF;

  IF NOT v_internal AND l.holder_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO ent FROM public.licensees WHERE license_id = l.id LIMIT 1;
  pol := public.license_lifecycle_policy(l.sector_id, l.sub_sector_id, l.category_id);

  SELECT count(*) FILTER (WHERE status IN ('open','in_progress')),
         count(*) FILTER (WHERE status IN ('open','in_progress') AND due_date < current_date)
    INTO v_open_conditions, v_overdue_conditions
    FROM public.license_conditions WHERE license_id = l.id;

  SELECT * INTO v_matter FROM public.license_lifecycle_matters
   WHERE license_id = l.id AND status = 'open'
   ORDER BY CASE matter_kind WHEN 'revocation' THEN 1 WHEN 'suspension' THEN 2 WHEN 'renewal' THEN 3 ELSE 4 END, opened_at
   LIMIT 1;

  SELECT * INTO v_renewal FROM public.license_renewals
   WHERE license_id = l.id AND status NOT IN ('approved','refused','withdrawn')
   ORDER BY created_at DESC LIMIT 1;

  v_days := CASE WHEN l.valid_until IS NULL THEN NULL
                 ELSE EXTRACT(EPOCH FROM (l.valid_until - now())) / 86400 END;

  v_sla_state := CASE
    WHEN l.status IN ('revoked','surrendered') THEN 'closed'
    WHEN v_days IS NULL THEN 'on_track'
    WHEN v_days < 0 THEN 'breached'
    WHEN v_days <= COALESCE((pol->>'renewal_window_days')::int, 90) THEN 'due_soon'
    ELSE 'on_track' END;

  v_stage := CASE
    WHEN l.status = 'revoked' THEN 'REVOKED'
    WHEN l.status = 'surrendered' THEN 'SURRENDERED'
    WHEN l.status = 'expired' THEN 'EXPIRY_REVIEW'
    WHEN l.status = 'suspended' THEN 'SUSPENDED'
    WHEN v_matter.matter_kind = 'revocation' THEN 'REVOCATION_REVIEW'
    WHEN v_matter.matter_kind = 'suspension' THEN 'SUSPENSION_REVIEW'
    WHEN v_matter.matter_kind = 'surrender' THEN 'SURRENDER_REVIEW'
    WHEN v_matter.matter_kind = 'variation' THEN 'VARIATION'
    WHEN v_renewal.id IS NOT NULL THEN 'RENEWAL'
    WHEN v_sla_state = 'breached' THEN 'EXPIRY_REVIEW'
    WHEN v_sla_state = 'due_soon' THEN 'RENEWAL_DUE'
    WHEN v_open_conditions > 0 THEN 'ACTIVE_WITH_CONDITIONS'
    WHEN l.status = 'active' THEN 'ACTIVE'
    ELSE upper(COALESCE(l.status,'UNKNOWN')) END;

  v_waiting := COALESCE(
    CASE WHEN v_renewal.status = 'information_requested' THEN 'entity' END,
    v_matter.waiting_on,
    CASE WHEN v_open_conditions > 0 THEN 'entity' ELSE 'regulator' END);

  IF l.status IN ('revoked','surrendered') THEN
    v_priority := 'low'; v_priority_reason := 'Licence closed';
  ELSIF l.status = 'suspended' OR v_matter.matter_kind IN ('revocation','suspension') THEN
    v_priority := 'critical'; v_priority_reason := 'Adverse lifecycle action in progress';
  ELSIF v_sla_state = 'breached' OR v_overdue_conditions > 0 THEN
    v_priority := 'high'; v_priority_reason := CASE WHEN v_sla_state = 'breached' THEN 'Licence past expiry' ELSE 'Overdue licence conditions' END;
  ELSIF v_sla_state = 'due_soon' THEN
    v_priority := 'medium'; v_priority_reason := 'Renewal window open';
  ELSE
    v_priority := 'low'; v_priority_reason := 'No open lifecycle matter';
  END IF;

  IF v_overdue_conditions > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('key','overdue_conditions','label', v_overdue_conditions || ' overdue condition(s)','href','/licenses/' || l.id || '?tab=conditions');
  END IF;
  IF v_sla_state = 'breached' AND l.status = 'active' THEN
    v_blockers := v_blockers || jsonb_build_object('key','past_expiry','label','Licence term has elapsed','href','/licenses/' || l.id || '?tab=renewal');
  END IF;

  v_next := CASE
    WHEN l.status IN ('revoked','surrendered') THEN NULL
    WHEN v_renewal.id IS NOT NULL AND v_renewal.status = 'information_requested'
      THEN jsonb_build_object('key','AWAIT_RENEWAL_INFORMATION','label','Awaiting renewal information','href','/licenses/' || l.id || '?tab=renewal','permission','license_management.view')
    WHEN v_renewal.id IS NOT NULL
      THEN jsonb_build_object('key','APPROVE_RENEWAL','label','Decide renewal','href','/licenses/' || l.id || '?tab=renewal','permission','license_management.approve')
    WHEN v_matter.matter_kind = 'suspension'
      THEN jsonb_build_object('key','SUSPEND','label','Conclude suspension review','href','/licenses/' || l.id || '?tab=adverse','permission','license_management.manage_license_actions')
    WHEN v_matter.matter_kind = 'revocation'
      THEN jsonb_build_object('key','REVOKE','label','Conclude revocation review','href','/licenses/' || l.id || '?tab=adverse','permission','license_management.manage_license_actions')
    WHEN v_matter.matter_kind = 'surrender'
      THEN jsonb_build_object('key','ACCEPT_SURRENDER','label','Decide surrender','href','/licenses/' || l.id || '?tab=adverse','permission','license_management.manage_license_actions')
    WHEN l.status = 'suspended'
      THEN jsonb_build_object('key','REINSTATE','label','Consider reinstatement','href','/licenses/' || l.id || '?tab=adverse','permission','license_management.manage_license_actions')
    WHEN v_sla_state = 'breached' AND l.status = 'active'
      THEN jsonb_build_object('key','MARK_EXPIRED','label','Complete expiry review','href','/licenses/' || l.id || '?tab=renewal','permission','license_management.manage_license_actions')
    WHEN v_sla_state = 'due_soon'
      THEN jsonb_build_object('key','START_RENEWAL','label','Start renewal','href','/licenses/' || l.id || '?tab=renewal','permission','license_management.workflow_action')
    WHEN v_overdue_conditions > 0
      THEN jsonb_build_object('key','REVIEW_CONDITIONS','label','Review overdue conditions','href','/licenses/' || l.id || '?tab=conditions','permission','license_management.manage_conditions')
    ELSE NULL END;

  SELECT max(created_at) INTO v_last FROM public.license_actions WHERE license_id = l.id;

  -- owner / team resolution (honest nulls when team-owned only)
  v_owner_id := COALESCE(ent.regulator_officer_id, ent.assigned_supervisor_id);
  SELECT sa.supervisor_id, sa.supervisor_name, sa.team
    INTO v_sa_supervisor, v_owner_name, v_team
    FROM public.entity_supervision_assignments sa
   WHERE ent.id IS NOT NULL AND sa.entity_id = ent.id
     AND COALESCE(sa.status,'active') = 'active'
   ORDER BY sa.effective_from DESC NULLS LAST LIMIT 1;
  IF v_owner_id IS NULL THEN v_owner_id := v_sa_supervisor; END IF;
  IF v_owner_id IS NOT NULL AND (v_owner_name IS NULL OR v_sa_supervisor IS DISTINCT FROM v_owner_id) THEN
    SELECT p.full_name INTO v_owner_name FROM public.profiles p WHERE p.id = v_owner_id;
  END IF;

  IF v_internal THEN
    v_actions := public.license_lifecycle_available_actions(l.id);
  END IF;

  RETURN jsonb_build_object(
    'header', jsonb_build_object(
      'license_id', l.id,
      'reference', l.license_number,
      'subject', COALESCE(ent.name, l.license_type),
      'entity_id', ent.id,
      'case_type', l.license_type,
      'stage', v_stage,
      'status', l.status,
      'owner_id', v_owner_id,
      'owner_name', v_owner_name,
      'team', v_team,
      'priority', v_priority,
      'priority_reason', v_priority_reason,
      'sla_due_at', l.valid_until,
      'sla_state', v_sla_state,
      'waiting_on', v_waiting,
      'blockers', v_blockers,
      'next_action', v_next,
      'available_actions', v_actions,
      'last_activity_at', COALESCE(v_last, l.updated_at, l.created_at),
      'issued_at', l.issued_at,
      'valid_from', l.valid_from,
      'valid_until', l.valid_until,
      'application_id', l.application_id,
      'sector_id', l.sector_id,
      'sub_sector_id', l.sub_sector_id,
      'category_id', l.category_id
    ),
    'policy', pol,
    'available_actions', v_actions,
    'counts', jsonb_build_object('open_conditions', v_open_conditions, 'overdue_conditions', v_overdue_conditions),
    'open_matter', CASE WHEN v_matter.id IS NULL THEN NULL ELSE to_jsonb(v_matter) END,
    'matters', COALESCE((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.opened_at DESC) FROM public.license_lifecycle_matters m WHERE m.license_id = l.id), '[]'::jsonb),
    'renewals', COALESCE((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC) FROM public.license_renewals r WHERE r.license_id = l.id), '[]'::jsonb),
    'conditions', COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.due_date NULLS LAST) FROM public.license_conditions c WHERE c.license_id = l.id), '[]'::jsonb),
    'history', CASE WHEN v_internal THEN COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.created_at DESC) FROM public.license_actions a WHERE a.license_id = l.id), '[]'::jsonb) ELSE '[]'::jsonb END,
    'appeals', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',ap.id,'reference',ap.appeal_reference,'status',ap.status,'filed_at',ap.filed_at,'decision',ap.decision) ORDER BY ap.filed_at DESC) FROM public.license_appeals ap WHERE ap.license_id = l.id), '[]'::jsonb),
    'enforcement', CASE WHEN ent.id IS NULL THEN '[]'::jsonb ELSE COALESCE((SELECT jsonb_agg(jsonb_build_object('id',e.id,'case_number',e.case_number,'status',e.status,'stage',e.stage,'source_kind',e.source_kind) ORDER BY e.created_at DESC) FROM public.enforcement_actions e WHERE e.entity_id = ent.id), '[]'::jsonb) END,
    'audience', CASE WHEN v_internal THEN 'internal' ELSE 'external' END
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.license_condition_create(_license_id uuid, _category text, _description text, _application_id uuid DEFAULT NULL::uuid, _due_date date DEFAULT NULL::date, _monitoring_owner text DEFAULT NULL::text, _notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _row record;
BEGIN
  PERFORM public.enforce_permission('license_management','manage_conditions');
  IF _description IS NULL OR length(btrim(_description)) < 5 THEN
    RAISE EXCEPTION 'condition description is required' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.licenses WHERE id = _license_id) THEN
    RAISE EXCEPTION 'license not found' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.license_conditions (license_id, application_id, category, description,
    due_date, monitoring_owner, notes, status, created_by)
  VALUES (_license_id, _application_id, COALESCE(NULLIF(btrim(_category),''),'other'),
          btrim(_description), _due_date, NULLIF(btrim(_monitoring_owner),''),
          NULLIF(btrim(_notes),''), 'open', _uid)
  RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'license.condition.created','license_condition',_row.id,
          jsonb_build_object('license_id',_license_id,'after',to_jsonb(_row)));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.license_condition_delete(_condition_id uuid, _reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record;
BEGIN
  PERFORM public.enforce_permission('license_management','manage_conditions');
  SELECT * INTO _prev FROM public.license_conditions WHERE id = _condition_id;
  IF _prev IS NULL THEN RETURN; END IF;
  DELETE FROM public.license_conditions WHERE id = _condition_id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'license.condition.deleted','license_condition',_condition_id,
          jsonb_build_object('before',to_jsonb(_prev),'reason',_reason));
END; $function$
;
CREATE OR REPLACE FUNCTION public.license_condition_review(_condition_id uuid, _decision text, _reason text DEFAULT NULL::text, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid(); c record; cfg jsonb;
  v_status text; v_review text; v_consequence text; v_matter_id uuid; v_new_condition uuid;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  PERFORM public.enforce_permission('license_management','manage_conditions');

  SELECT * INTO c FROM public.license_conditions WHERE id = _condition_id FOR UPDATE;
  IF c IS NULL THEN RAISE EXCEPTION 'CONDITION_NOT_FOUND' USING ERRCODE='22023'; END IF;

  IF _decision NOT IN ('SATISFY','WAIVE','VARY','BREACH','RETURN_FOR_EVIDENCE') THEN
    RAISE EXCEPTION 'UNKNOWN_ACTION' USING ERRCODE='22023';
  END IF;
  IF c.status IN ('satisfied','waived','closed') THEN
    RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023';
  END IF;
  IF _decision IN ('WAIVE','VARY','BREACH','RETURN_FOR_EVIDENCE')
     AND COALESCE(length(btrim(_reason)),0) < 10 THEN
    RAISE EXCEPTION 'REASON_REQUIRED' USING ERRCODE='22023';
  END IF;
  IF _decision = 'SATISFY' AND c.evidence_required
     AND NOT EXISTS (SELECT 1 FROM public.license_condition_evidence e WHERE e.condition_id = c.id) THEN
    RAISE EXCEPTION 'BLOCKED' USING ERRCODE='22023',
      DETAIL = 'No evidence has been submitted for this condition.';
  END IF;

  cfg := public.license_lifecycle_config_resolve(c.license_id, 'renewal');

  IF _decision = 'SATISFY' THEN
    v_status := 'satisfied'; v_review := 'accepted';
    UPDATE public.license_conditions
       SET status = v_status, review_state = v_review, satisfied_at = now(), satisfied_by = uid, updated_at = now()
     WHERE id = c.id;
    UPDATE public.license_condition_evidence
       SET review_state = 'accepted', reviewed_by = uid, reviewed_at = now(), review_note = _reason
     WHERE condition_id = c.id AND review_state IN ('submitted','under_review');
  ELSIF _decision = 'WAIVE' THEN
    v_status := 'waived'; v_review := 'waived';
    UPDATE public.license_conditions
       SET status = v_status, review_state = v_review, waived_at = now(), waived_by = uid,
           waiver_reason = _reason, updated_at = now()
     WHERE id = c.id;
  ELSIF _decision = 'VARY' THEN
    v_status := 'varied'; v_review := 'under_review';
    UPDATE public.license_conditions
       SET status = v_status, review_state = v_review, varied_at = now(), varied_by = uid,
           variation_reason = _reason,
           description = COALESCE(NULLIF(_payload->>'description',''), description),
           due_date = COALESCE((_payload->>'due_date')::date, due_date),
           updated_at = now()
     WHERE id = c.id;
  ELSIF _decision = 'RETURN_FOR_EVIDENCE' THEN
    v_status := 'evidence_due'; v_review := 'rejected';
    UPDATE public.license_conditions
       SET status = v_status, review_state = v_review,
           due_date = COALESCE((_payload->>'due_date')::date, due_date), updated_at = now()
     WHERE id = c.id;
    UPDATE public.license_condition_evidence
       SET review_state = 'rejected', reviewed_by = uid, reviewed_at = now(), review_note = _reason
     WHERE condition_id = c.id AND review_state IN ('submitted','under_review');
  ELSE
    v_status := 'breached'; v_review := 'rejected';
    v_consequence := COALESCE(NULLIF(_payload->>'consequence',''), cfg->>'breach_consequence', 'supervisory_followup');

    IF v_consequence IN ('lifecycle_matter','suspension_review') THEN
      INSERT INTO public.license_lifecycle_matters(license_id, matter_kind, title, reason, opened_by, waiting_on, metadata)
      VALUES (c.license_id,
              CASE WHEN v_consequence = 'suspension_review' THEN 'suspension' ELSE 'condition_review' END,
              'Condition breach follow-up', _reason, uid, 'regulator',
              jsonb_build_object('source','license_condition','condition_id', c.id, 'consequence', v_consequence))
      RETURNING id INTO v_matter_id;
    ELSIF v_consequence = 'additional_condition' THEN
      INSERT INTO public.license_conditions(license_id, category, description, due_date, status,
        source_decision, requirement_ref, effective_date, owner_team, evidence_required, created_by)
      VALUES (c.license_id, COALESCE(c.category,'remediation'),
              COALESCE(NULLIF(_payload->>'description',''), 'Remediation of breached condition ' || COALESCE(c.condition_reference, c.id::text)),
              COALESCE((_payload->>'due_date')::date, (current_date + 30)), 'open',
              'CONDITION_BREACH', c.requirement_ref, current_date, c.owner_team, true, uid)
      RETURNING id INTO v_new_condition;
    END IF;

    UPDATE public.license_conditions
       SET status = v_status, review_state = v_review, breached_at = now(), breached_by = uid,
           breach_reason = _reason, breach_consequence = v_consequence,
           breach_matter_id = v_matter_id, updated_at = now()
     WHERE id = c.id;
  END IF;

  INSERT INTO public.license_actions(license_id, action_type, actor_id, reason, old_status, new_status, metadata)
  VALUES (c.license_id, 'condition_' || lower(_decision), uid, _reason, c.status, v_status,
          jsonb_build_object('condition_id', c.id, 'consequence', v_consequence,
                             'matter_id', v_matter_id, 'new_condition_id', v_new_condition));

  INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
  VALUES (uid, 'license.condition.' || lower(_decision), 'license_condition', c.id,
          jsonb_build_object('license_id', c.license_id, 'from', c.status, 'to', v_status,
                             'reason', _reason, 'consequence', v_consequence));

  RETURN jsonb_build_object('condition_id', c.id, 'status', v_status, 'review_state', v_review,
                            'consequence', v_consequence, 'matter_id', v_matter_id,
                            'new_condition_id', v_new_condition);
END $function$
;
CREATE OR REPLACE FUNCTION public.license_condition_set_status(_condition_id uuid, _status text, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('license_management','manage_conditions');
  IF _status NOT IN ('open','in_progress','satisfied','waived','breached') THEN
    RAISE EXCEPTION 'invalid condition status' USING ERRCODE='22023';
  END IF;
  SELECT * INTO _prev FROM public.license_conditions WHERE id = _condition_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'condition not found' USING ERRCODE='22023'; END IF;
  UPDATE public.license_conditions
     SET status = _status,
         satisfied_at = CASE WHEN _status = 'satisfied' THEN now() ELSE NULL END,
         satisfied_by = CASE WHEN _status = 'satisfied' THEN _uid ELSE NULL END,
         notes = COALESCE(NULLIF(btrim(_note),''), notes)
   WHERE id = _condition_id RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'license.condition.status_changed','license_condition',_condition_id,
          jsonb_build_object('before',jsonb_build_object('status',_prev.status),
                             'after',jsonb_build_object('status',_status),'reason',_note));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.license_condition_submit_evidence(_condition_id uuid, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); c record; l record; v_id uuid;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT * INTO c FROM public.license_conditions WHERE id = _condition_id FOR UPDATE;
  IF c IS NULL THEN RAISE EXCEPTION 'CONDITION_NOT_FOUND' USING ERRCODE='22023'; END IF;
  SELECT * INTO l FROM public.licenses WHERE id = c.license_id;

  IF NOT (public.is_super_admin(uid)
          OR public.has_permission(uid,'license_management','view')
          OR l.holder_id = uid) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';
  END IF;

  IF c.status IN ('satisfied','waived','closed') THEN
    RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023',
      DETAIL = 'Condition is already concluded.';
  END IF;
  IF COALESCE(length(btrim(_payload->>'summary')),0) < 5 THEN
    RAISE EXCEPTION 'EVIDENCE_SUMMARY_REQUIRED' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.license_condition_evidence(condition_id, license_id, submitted_by, summary, document_ids, file_paths, metadata)
  VALUES (_condition_id, c.license_id, uid, _payload->>'summary',
          COALESCE(_payload->'document_ids','[]'::jsonb), COALESCE(_payload->'file_paths','[]'::jsonb),
          COALESCE(_payload->'metadata','{}'::jsonb))
  RETURNING id INTO v_id;

  UPDATE public.license_conditions
     SET status = 'under_review', review_state = 'submitted',
         last_evidence_at = now(), updated_at = now()
   WHERE id = _condition_id;

  INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
  VALUES (uid, 'license.condition.evidence_submitted', 'license_condition', _condition_id,
          jsonb_build_object('evidence_id', v_id, 'license_id', c.license_id));

  RETURN jsonb_build_object('evidence_id', v_id, 'condition_status', 'under_review', 'review_state', 'submitted');
END $function$
;
CREATE OR REPLACE FUNCTION public.license_decision_appeal_operation(_operation text, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); d record; ap record; v_id uuid; v_ref text; v_window int;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;

  IF _operation = 'lodge' THEN
    IF NOT (public.is_super_admin(uid) OR public.has_permission(uid,'license_management','workflow_action')) THEN
      RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
    SELECT * INTO d FROM public.license_decisions WHERE id = (_payload->>'decision_id')::uuid;
    IF d IS NULL THEN RAISE EXCEPTION 'DECISION_NOT_FOUND' USING ERRCODE='22023'; END IF;
    IF NOT COALESCE(d.appealable, false) THEN
      RAISE EXCEPTION 'NOT_APPEALABLE' USING ERRCODE='22023', DETAIL='This decision is not appealable.'; END IF;
    IF d.appeal_deadline IS NOT NULL AND d.appeal_deadline < current_date THEN
      RAISE EXCEPTION 'OUT_OF_TIME' USING ERRCODE='22023',
        DETAIL='The appeal window for this decision closed on ' || d.appeal_deadline || '.'; END IF;
    IF EXISTS (SELECT 1 FROM public.license_decision_appeals
                WHERE decision_id = d.id AND status NOT IN ('withdrawn','determined')) THEN
      RAISE EXCEPTION 'ALREADY_OPEN' USING ERRCODE='22023',
        DETAIL='An appeal against this decision is already live.'; END IF;
    IF NULLIF(btrim(COALESCE(_payload->>'grounds','')),'') IS NULL THEN
      RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023', DETAIL='Grounds of appeal are required.'; END IF;

    v_ref := 'LAP-' || to_char(now(),'YYYY') || '-' || lpad((
      (SELECT count(*) + 1 FROM public.license_decision_appeals
        WHERE lodged_at >= date_trunc('year', now())))::text, 5, '0');

    INSERT INTO public.license_decision_appeals(appeal_reference, decision_id, license_id, matter_id,
      entity_id, grounds, relief_sought, lodged_by, appeal_deadline, stay_of_effect, metadata)
    VALUES (v_ref, d.id, d.license_id, d.matter_id, d.entity_id, _payload->>'grounds',
            _payload->>'relief_sought', uid, d.appeal_deadline,
            COALESCE((_payload->>'stay_of_effect')::boolean, false),
            COALESCE(_payload->'metadata','{}'::jsonb))
    RETURNING id INTO v_id;

    INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
    VALUES (uid, 'license_decision_appeal_lodge', 'license_decision_appeal', v_id,
            jsonb_build_object('decision_id', d.id, 'reference', v_ref));
    RETURN jsonb_build_object('appeal_id', v_id, 'reference', v_ref);

  ELSIF _operation IN ('acknowledge','determine','withdraw') THEN
    SELECT * INTO ap FROM public.license_decision_appeals WHERE id = (_payload->>'appeal_id')::uuid;
    IF ap IS NULL THEN RAISE EXCEPTION 'APPEAL_NOT_FOUND' USING ERRCODE='22023'; END IF;

    IF _operation = 'acknowledge' THEN
      IF NOT (public.is_super_admin(uid) OR public.has_permission(uid,'license_management','workflow_action')) THEN
        RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
      IF ap.status <> 'lodged' THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023'; END IF;
      UPDATE public.license_decision_appeals SET status='under_review', updated_at=now() WHERE id=ap.id;

    ELSIF _operation = 'withdraw' THEN
      IF NOT (public.is_super_admin(uid) OR public.has_permission(uid,'license_management','workflow_action')) THEN
        RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
      IF ap.status IN ('determined','withdrawn') THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023'; END IF;
      IF NULLIF(btrim(COALESCE(_payload->>'rationale','')),'') IS NULL THEN
        RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023', DETAIL='A withdrawal reason is required.'; END IF;
      UPDATE public.license_decision_appeals
         SET status='withdrawn', outcome='withdrawn', outcome_rationale=_payload->>'rationale',
             decided_by=uid, decided_at=now(), updated_at=now() WHERE id=ap.id;

    ELSE
      IF NOT (public.is_super_admin(uid) OR public.has_permission(uid,'license_management','approve')) THEN
        RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
      IF ap.status NOT IN ('lodged','under_review') THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023'; END IF;
      IF COALESCE(_payload->>'outcome','') NOT IN ('upheld','dismissed','varied','remitted') THEN
        RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023', DETAIL='A valid appeal outcome is required.'; END IF;
      IF NULLIF(btrim(COALESCE(_payload->>'rationale','')),'') IS NULL THEN
        RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023', DETAIL='A written determination rationale is required.'; END IF;
      IF ap.lodged_by = uid AND NOT public.is_super_admin(uid) THEN
        RAISE EXCEPTION 'MAKER_CHECKER' USING ERRCODE='42501',
          DETAIL='The officer who lodged the appeal cannot determine it.'; END IF;
      UPDATE public.license_decision_appeals
         SET status='determined', outcome=_payload->>'outcome', outcome_rationale=_payload->>'rationale',
             decided_by=uid, decided_at=now(), updated_at=now() WHERE id=ap.id;
    END IF;

    INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
    VALUES (uid, 'license_decision_appeal_' || _operation, 'license_decision_appeal', ap.id, _payload);
    RETURN (SELECT to_jsonb(x) FROM public.license_decision_appeals x WHERE x.id = ap.id);
  END IF;
  RAISE EXCEPTION 'UNKNOWN_OPERATION' USING ERRCODE='22023';
END $function$
;
CREATE OR REPLACE FUNCTION public.license_decision_appeal_view(_license_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'appeal', to_jsonb(ap),
           'decision', jsonb_build_object('id', d.id, 'reference', d.decision_reference,
             'decision_type', d.decision_type, 'decision', d.decision, 'decided_at', d.decided_at,
             'effective_date', d.effective_date, 'appeal_deadline', d.appeal_deadline,
             'appealable', d.appealable, 'rationale', d.rationale)
         ) ORDER BY ap.lodged_at DESC), '[]'::jsonb)
    FROM public.license_decision_appeals ap
    JOIN public.license_decisions d ON d.id = ap.decision_id
   WHERE ap.license_id = _license_id AND public.is_internal_staff_user(auth.uid());
$function$
;
CREATE OR REPLACE FUNCTION public.license_expiry_sweep(_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  rec record; cfg jsonb; v_grace int; v_lapsed int := 0; v_opened int := 0; v_dec uuid; v_matter uuid;
BEGIN
  FOR rec IN
    SELECT l.* FROM public.licenses l
     WHERE l.status IN ('active','restricted')
       AND l.valid_until IS NOT NULL AND l.valid_until < now()
     ORDER BY l.valid_until
     LIMIT GREATEST(COALESCE(_limit,200),1)
  LOOP
    cfg := public.license_lifecycle_config_resolve(rec.id, 'expiry');
    v_grace := COALESCE(NULLIF(cfg->>'grace_period_days','')::int, 0);
    CONTINUE WHEN rec.valid_until + make_interval(days => v_grace) > now();

    IF COALESCE(cfg->>'expiry_behavior','officer_confirmed') = 'automatic' THEN
      INSERT INTO public.license_decisions(license_id, decision_type, decision, actor_id, effective_date,
        rationale, legal_basis, appealable, from_status, to_status, metadata)
      VALUES (rec.id, 'expiry', 'lapsed', NULL, current_date,
              'Licence term expired and the configured grace period elapsed.',
              NULLIF(cfg->>'decision_authority',''), false, rec.status, 'expired',
              jsonb_build_object('source','license_expiry_sweep','grace_period_days', v_grace))
      RETURNING id INTO v_dec;
      UPDATE public.licenses SET status='expired', updated_at=now() WHERE id = rec.id;
      UPDATE public.license_terms SET is_current = is_current WHERE license_id = rec.id AND false;
      INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
      VALUES (NULL, 'license.lifecycle.expiry_sweep_lapsed', 'license', rec.id,
              jsonb_build_object('decision_id', v_dec, 'valid_until', rec.valid_until));
      v_lapsed := v_lapsed + 1;
    ELSE
      IF NOT EXISTS (SELECT 1 FROM public.license_lifecycle_matters x
                      WHERE x.license_id = rec.id AND x.status='open' AND x.matter_kind='expiry') THEN
        INSERT INTO public.license_lifecycle_matters(license_id, matter_kind, title, reason, opened_by,
          waiting_on, stage, source_kind, sla_due_at, metadata)
        VALUES (rec.id, 'expiry', 'Expiry review',
                'Licence term expired on ' || to_char(rec.valid_until,'DD Mon YYYY') || '; officer confirmation required.',
                NULL, 'regulator', 'EXPIRY_REVIEW', 'time_based_expiry', now(),
                jsonb_build_object('source','license_expiry_sweep','policy_snapshot', cfg))
        RETURNING id INTO v_matter;
        INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
        VALUES (NULL, 'license.lifecycle.expiry_review_opened', 'license', rec.id,
                jsonb_build_object('matter_id', v_matter, 'valid_until', rec.valid_until));
        v_opened := v_opened + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('lapsed', v_lapsed, 'reviews_opened', v_opened, 'ran_at', now());
END $function$
;
CREATE OR REPLACE FUNCTION public.license_expiry_sweep_run(_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_run uuid; v_res jsonb; v_eligible int; v_skipped int;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501',
      DETAIL='license_expiry_sweep_run is a service-role operation and cannot be executed by a signed-in session.';
  END IF;

  INSERT INTO public.license_expiry_sweep_runs(initiator) VALUES ('SYSTEM') RETURNING id INTO v_run;

  SELECT count(*) INTO v_eligible FROM public.licenses l
   WHERE l.status IN ('active','restricted') AND l.valid_until IS NOT NULL AND l.valid_until < now();

  v_res := public.license_expiry_sweep(_limit);
  v_skipped := GREATEST(v_eligible - COALESCE((v_res->>'lapsed')::int,0) - COALESCE((v_res->>'reviews_opened')::int,0), 0);

  UPDATE public.license_expiry_sweep_runs
     SET finished_at = now(), eligible_count = v_eligible,
         auto_expired_count = COALESCE((v_res->>'lapsed')::int,0),
         review_created_count = COALESCE((v_res->>'reviews_opened')::int,0),
         skipped_count = v_skipped, result = v_res
   WHERE id = v_run;

  INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
  VALUES (NULL, 'license.lifecycle.expiry_sweep_run', 'license_expiry_sweep_run', v_run,
          jsonb_build_object('eligible', v_eligible, 'result', v_res));

  RETURN jsonb_build_object('run_id', v_run, 'eligible_count', v_eligible,
    'auto_expired_count', COALESCE((v_res->>'lapsed')::int,0),
    'review_created_count', COALESCE((v_res->>'reviews_opened')::int,0),
    'skipped_count', v_skipped, 'errors', '[]'::jsonb);
END $function$
;
CREATE OR REPLACE FUNCTION public.license_fee_assess(_license_id uuid, _matter_id uuid, _matter_kind text, _action_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); f jsonb; created int := 0;
BEGIN
  FOR f IN SELECT value FROM jsonb_array_elements(public.license_fee_resolve(_license_id, _matter_kind, _action_key)) LOOP
    IF EXISTS (SELECT 1 FROM public.license_fee_assessments a
                WHERE a.license_id = _license_id
                  AND a.matter_id IS NOT DISTINCT FROM _matter_id
                  AND COALESCE(a.fee_type_code,'') = COALESCE(f->>'fee_type_code','')
                  AND a.status <> 'void') THEN CONTINUE; END IF;
    INSERT INTO public.license_fee_assessments(
      license_id, matter_id, binding_id, matter_kind, fee_type_code, description, amount, currency,
      blocking, payment_verification_required, due_date, binding_snapshot, assessed_by)
    VALUES (_license_id, _matter_id, (f->>'binding_id')::uuid, _matter_kind, f->>'fee_type_code',
      f->>'description', COALESCE((f->>'amount')::numeric,0), COALESCE(f->>'currency','JMD'),
      COALESCE((f->>'blocking')::boolean,true), COALESCE((f->>'payment_verification_required')::boolean,true),
      current_date + COALESCE((f->>'due_days')::int,30), f, uid);
    created := created + 1;
  END LOOP;
  RETURN jsonb_build_object('assessed', created);
END $function$
;
CREATE OR REPLACE FUNCTION public.license_fee_configuration_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid();
BEGIN
  IF uid IS NULL OR NOT public.is_internal_staff_user(uid) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object(
    'fee_types', (SELECT COALESCE(jsonb_agg(jsonb_build_object('code', ft.code, 'name', ft.name, 'status', ft.status)
                                            ORDER BY ft.code), '[]'::jsonb) FROM public.fee_types ft),
    'bindings', (SELECT COALESCE(jsonb_agg(to_jsonb(b) ORDER BY b.purpose, b.matter_kind, b.fee_type_code), '[]'::jsonb)
                   FROM public.license_fee_bindings b),
    'schedules', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', fc.id, 'name', fc.name, 'fee_type', fc.fee_type,
                                                              'amount', fc.amount, 'currency', fc.currency,
                                                              'is_active', fc.is_active) ORDER BY fc.name), '[]'::jsonb)
                    FROM public.fee_configurations fc),
    'process_settings', (SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.matter_kind), '[]'::jsonb)
                           FROM public.license_fee_process_settings s),
    'verification_templates', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                                  'id', t.id, 'template_key', t.template_key, 'version', t.version,
                                  'name', t.name, 'matter_kind', t.matter_kind, 'purpose', t.purpose,
                                  'is_active', t.is_active, 'effective_from', t.effective_from,
                                  'effective_to', t.effective_to,
                                  'total_items', jsonb_array_length(t.items),
                                  'mandatory_items', (SELECT count(*) FROM jsonb_array_elements(t.items) i
                                                       WHERE COALESCE((i->>'required')::boolean,true)),
                                  'blocking_semantics', t.blocking_semantics)
                                  ORDER BY t.matter_kind, t.template_key, t.version), '[]'::jsonb)
                                FROM public.license_verification_templates t),
    'process_templates', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                              'id', p.id, 'template_key', p.template_key, 'version', p.version, 'name', p.name,
                              'process_code', p.process_code, 'purpose', p.purpose, 'is_active', p.is_active,
                              'step_count', jsonb_array_length(p.steps)) ORDER BY p.process_code, p.version), '[]'::jsonb)
                            FROM public.process_templates p));
END $function$
;
CREATE OR REPLACE FUNCTION public.license_fee_ledger(_license_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'assessments', COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.assessed_at DESC)
                               FROM public.license_fee_assessments a WHERE a.license_id = _license_id), '[]'::jsonb),
    'summary', COALESCE((SELECT jsonb_build_object(
                    'outstanding', count(*) FILTER (WHERE status IN ('due','paid')),
                    'outstanding_amount', COALESCE(sum(amount) FILTER (WHERE status IN ('due','paid')), 0),
                    'verified', count(*) FILTER (WHERE status='verified'),
                    'waived', count(*) FILTER (WHERE status='waived'))
                  FROM public.license_fee_assessments WHERE license_id = _license_id),
                 jsonb_build_object('outstanding',0,'outstanding_amount',0,'verified',0,'waived',0)),
    'gates', public.license_lifecycle_gates(_license_id, NULL)
  ) WHERE public.is_internal_staff_user(auth.uid());
$function$
;
CREATE OR REPLACE FUNCTION public.license_fee_operation(_assessment_id uuid, _operation text, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); a record;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT * INTO a FROM public.license_fee_assessments WHERE id = _assessment_id;
  IF a IS NULL THEN RAISE EXCEPTION 'ASSESSMENT_NOT_FOUND' USING ERRCODE='22023'; END IF;

  IF _operation = 'record_payment' THEN
    IF NOT (public.is_super_admin(uid) OR public.has_permission(uid,'license_management','workflow_action')) THEN
      RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
    IF a.status NOT IN ('due') THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023',
      DETAIL='Only a fee that is still due can have a payment recorded.'; END IF;
    IF NULLIF(btrim(COALESCE(_payload->>'payment_reference','')),'') IS NULL THEN
      RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023', DETAIL='Payment reference is required.'; END IF;
    UPDATE public.license_fee_assessments
       SET status = CASE WHEN payment_verification_required THEN 'paid' ELSE 'verified' END,
           payment_reference = _payload->>'payment_reference',
           paid_at = now(), recorded_by = uid,
           verified_by = CASE WHEN payment_verification_required THEN NULL ELSE uid END,
           verified_at = CASE WHEN payment_verification_required THEN NULL ELSE now() END,
           updated_at = now()
     WHERE id = a.id;

  ELSIF _operation = 'verify_payment' THEN
    IF NOT (public.is_super_admin(uid) OR public.has_permission(uid,'license_management','approve')) THEN
      RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
    IF a.status <> 'paid' THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023',
      DETAIL='Only a recorded payment can be verified.'; END IF;
    IF a.recorded_by = uid AND NOT public.is_super_admin(uid) THEN
      RAISE EXCEPTION 'MAKER_CHECKER' USING ERRCODE='42501',
        DETAIL='The officer who recorded the payment cannot verify it.'; END IF;
    UPDATE public.license_fee_assessments
       SET status='verified', verified_by=uid, verified_at=now(), updated_at=now() WHERE id=a.id;

  ELSIF _operation = 'waive' THEN
    IF NOT (public.is_super_admin(uid) OR public.has_permission(uid,'license_management','approve')) THEN
      RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
    IF a.status IN ('verified','waived','void') THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023',
      DETAIL='This fee can no longer be waived.'; END IF;
    IF NULLIF(btrim(COALESCE(_payload->>'reason','')),'') IS NULL THEN
      RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023', DETAIL='A written waiver rationale is required.'; END IF;
    UPDATE public.license_fee_assessments
       SET status='waived', waived_by=uid, waived_at=now(), waiver_reason=_payload->>'reason', updated_at=now()
     WHERE id=a.id;
  ELSE
    RAISE EXCEPTION 'UNKNOWN_OPERATION' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
  VALUES (uid, 'license_fee_' || _operation, 'license_fee_assessment', a.id,
          jsonb_build_object('license_id', a.license_id, 'matter_id', a.matter_id,
                             'fee_type_code', a.fee_type_code, 'payload', _payload));

  RETURN (SELECT to_jsonb(x) FROM public.license_fee_assessments x WHERE x.id = a.id);
END $function$
;
CREATE OR REPLACE FUNCTION public.license_fee_resolve(_license_id uuid, _matter_kind text, _action_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  l record; out jsonb := '[]'::jsonb; b record;
  v_cert boolean; v_allowed_purpose text; v_enabled boolean;
BEGIN
  SELECT * INTO l FROM public.licenses WHERE id = _license_id;
  IF l IS NULL THEN RAISE EXCEPTION 'LICENSE_NOT_FOUND' USING ERRCODE='22023'; END IF;

  v_cert := COALESCE(l.license_number LIKE 'CERT-%', false);
  v_allowed_purpose := CASE WHEN v_cert THEN 'CERTIFICATION' ELSE 'PRODUCTION' END;

  -- regulator/process level fees switch: absent setting means enabled
  SELECT s.fees_enabled INTO v_enabled
    FROM public.license_fee_process_settings s
   WHERE s.matter_kind = _matter_kind
     AND (s.regulator_id IS NULL OR s.regulator_id = l.regulator_id)
   ORDER BY (s.regulator_id IS NOT NULL) DESC
   LIMIT 1;
  IF v_enabled IS NOT NULL AND v_enabled = false THEN
    RETURN '[]'::jsonb;
  END IF;

  FOR b IN
    SELECT fb.*,
           (CASE WHEN fb.category_id  IS NOT NULL THEN 8 ELSE 0 END
          + CASE WHEN fb.sub_sector_id IS NOT NULL THEN 4 ELSE 0 END
          + CASE WHEN fb.sector_id    IS NOT NULL THEN 2 ELSE 0 END
          + CASE WHEN fb.action_key   IS NOT NULL THEN 1 ELSE 0 END) AS specificity,
           COALESCE(fb.amount_override, fc.amount, 0) AS resolved_amount,
           COALESCE(fb.currency, fc.currency, 'JMD')  AS resolved_currency
      FROM public.license_fee_bindings fb
      LEFT JOIN public.fee_configurations fc ON fc.id = fb.fee_configuration_id
     WHERE fb.is_active
       AND fb.purpose = v_allowed_purpose            -- TEMPLATE rows never resolve
       AND fb.matter_kind = _matter_kind
       AND fb.effective_from <= current_date
       AND (fb.effective_to IS NULL OR fb.effective_to >= current_date)
       AND (fb.action_key IS NULL OR _action_key IS NULL OR fb.action_key = _action_key)
       AND (fb.regulator_id  IS NULL OR fb.regulator_id  = l.regulator_id)
       AND (fb.sector_id     IS NULL OR fb.sector_id     = l.sector_id)
       AND (fb.sub_sector_id IS NULL OR fb.sub_sector_id = l.sub_sector_id)
       AND (fb.category_id   IS NULL OR fb.category_id   = l.category_id)
       AND (fb.license_type  IS NULL OR fb.license_type  = l.license_type)
     ORDER BY specificity DESC, fb.created_at
  LOOP
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(out) x
                WHERE COALESCE(x->>'fee_type_code','') = COALESCE(b.fee_type_code,'')) THEN
      CONTINUE;
    END IF;
    out := out || jsonb_build_array(jsonb_build_object(
      'binding_id', b.id, 'binding_key', b.binding_key, 'purpose', b.purpose,
      'fee_type_code', b.fee_type_code,
      'description', COALESCE(b.description, b.fee_type_code, 'Lifecycle fee'),
      'amount', ROUND(b.resolved_amount * COALESCE(b.quantity,1), 2),
      'unit_amount', b.resolved_amount, 'quantity', COALESCE(b.quantity,1),
      'charge_basis', b.charge_basis, 'currency', b.resolved_currency,
      'trigger_event', b.trigger_event, 'trigger_timing', b.trigger_timing,
      'workflow_step_key', b.workflow_step_key, 'gate_policy', b.gate_policy,
      'blocking', b.blocking, 'payment_verification_required', b.payment_verification_required,
      'due_days', b.due_days, 'fee_configuration_id', b.fee_configuration_id,
      'effective_from', b.effective_from, 'effective_to', b.effective_to,
      'specificity', b.specificity,
      'matter_kind', b.matter_kind, 'action_key', b.action_key));
  END LOOP;
  RETURN out;
END $function$
;
CREATE OR REPLACE FUNCTION public.license_fee_simulate(_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  v_matter text := COALESCE(_payload->>'matter_kind','renewal');
  v_action text := NULLIF(_payload->>'action_key','');
  v_reg uuid := NULLIF(_payload->>'regulator_id','')::uuid;
  v_sec uuid := NULLIF(_payload->>'sector_id','')::uuid;
  v_sub uuid := NULLIF(_payload->>'sub_sector_id','')::uuid;
  v_cat uuid := NULLIF(_payload->>'category_id','')::uuid;
  v_type text := NULLIF(_payload->>'license_type','');
  v_purpose text := COALESCE(NULLIF(_payload->>'purpose',''),'PRODUCTION');
  v_qty numeric := COALESCE((_payload->>'quantity')::numeric, 1);
  v_enabled boolean; out jsonb := '[]'::jsonb; b record; v_matched jsonb := '[]'::jsonb;
BEGIN
  IF uid IS NULL OR NOT public.is_internal_staff_user(uid) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;

  SELECT s.fees_enabled INTO v_enabled
    FROM public.license_fee_process_settings s
   WHERE s.matter_kind = v_matter
     AND (s.regulator_id IS NULL OR s.regulator_id = v_reg)
   ORDER BY (s.regulator_id IS NOT NULL) DESC LIMIT 1;

  FOR b IN
    SELECT fb.*, fc.amount AS schedule_amount, fc.currency AS schedule_currency, fc.name AS schedule_name,
           fc.is_active AS schedule_active,
           (CASE WHEN fb.category_id  IS NOT NULL THEN 8 ELSE 0 END
          + CASE WHEN fb.sub_sector_id IS NOT NULL THEN 4 ELSE 0 END
          + CASE WHEN fb.sector_id    IS NOT NULL THEN 2 ELSE 0 END
          + CASE WHEN fb.action_key   IS NOT NULL THEN 1 ELSE 0 END) AS specificity
      FROM public.license_fee_bindings fb
      LEFT JOIN public.fee_configurations fc ON fc.id = fb.fee_configuration_id
     WHERE fb.matter_kind = v_matter
       AND fb.purpose = v_purpose
       AND (fb.action_key IS NULL OR v_action IS NULL OR fb.action_key = v_action)
       AND (fb.regulator_id  IS NULL OR v_reg  IS NULL OR fb.regulator_id  = v_reg)
       AND (fb.sector_id     IS NULL OR v_sec  IS NULL OR fb.sector_id     = v_sec)
       AND (fb.sub_sector_id IS NULL OR v_sub  IS NULL OR fb.sub_sector_id = v_sub)
       AND (fb.category_id   IS NULL OR v_cat  IS NULL OR fb.category_id   = v_cat)
       AND (fb.license_type  IS NULL OR v_type IS NULL OR fb.license_type  = v_type)
     ORDER BY specificity DESC, fb.created_at
  LOOP
    DECLARE
      v_amount numeric := COALESCE(b.amount_override, b.schedule_amount, 0);
      v_effective boolean := b.effective_from <= current_date
                         AND (b.effective_to IS NULL OR b.effective_to >= current_date);
      v_dup boolean := EXISTS (SELECT 1 FROM jsonb_array_elements(v_matched) x
                                WHERE x->>'c' = COALESCE(b.fee_type_code,''));
      v_would boolean;
      v_reason text;
    BEGIN
      v_would := b.is_active AND v_effective AND NOT v_dup
                 AND COALESCE(v_enabled, true) AND b.purpose <> 'TEMPLATE';
      v_reason := CASE
        WHEN b.purpose = 'TEMPLATE' THEN 'Configuration template — never resolves at runtime'
        WHEN NOT b.is_active THEN 'Workflow fee binding disabled'
        WHEN NOT v_effective THEN 'Outside effective dates'
        WHEN COALESCE(v_enabled, true) = false THEN 'Fees disabled for this regulator/process'
        WHEN v_dup THEN 'Superseded by a more specific binding for the same fee type'
        ELSE 'Most specific active binding for this fee type at this scope' END;
      IF v_would THEN v_matched := v_matched || jsonb_build_array(jsonb_build_object('c', COALESCE(b.fee_type_code,''))); END IF;

      out := out || jsonb_build_array(jsonb_build_object(
        'binding_id', b.id, 'binding_key', b.binding_key, 'purpose', b.purpose,
        'fee_type_code', b.fee_type_code, 'description', b.description,
        'schedule_name', b.schedule_name, 'schedule_active', b.schedule_active,
        'catalogue_state', CASE WHEN EXISTS (SELECT 1 FROM public.fee_types ft
                                              WHERE upper(COALESCE(ft.code,'')) = b.fee_type_code
                                                AND ft.status = 'active')
                                THEN 'AVAILABLE' ELSE 'NOT_IN_CATALOGUE' END,
        'binding_enabled', b.is_active,
        'unit_amount', v_amount, 'quantity', v_qty,
        'total', ROUND(v_amount * v_qty, 2),
        'currency', COALESCE(b.currency, b.schedule_currency, 'JMD'),
        'charge_basis', b.charge_basis,
        'trigger_event', b.trigger_event, 'trigger_timing', b.trigger_timing,
        'workflow_step_key', b.workflow_step_key,
        'gate_policy', b.gate_policy,
        'payment_verification_required', b.payment_verification_required,
        'effective_from', b.effective_from, 'effective_to', b.effective_to,
        'specificity', b.specificity,
        'would_assess', v_would, 'reason', v_reason));
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'simulated_at', now(),
    'creates_obligation', false,
    'matter_kind', v_matter,
    'process_fees_enabled', COALESCE(v_enabled, true),
    'process_fees_setting_present', v_enabled IS NOT NULL,
    'candidates', out);
END $function$
;
CREATE OR REPLACE FUNCTION public.license_ids_for_licensee(_licensee_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT license_id FROM public.licensees WHERE id = _licensee_id AND license_id IS NOT NULL
$function$
;
CREATE OR REPLACE FUNCTION public.license_is_certification_scoped(_license_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(l.license_number LIKE 'CERT-%', false)
    FROM public.licenses l WHERE l.id = _license_id
$function$
;
CREATE OR REPLACE FUNCTION public.license_lifecycle_action(_license_id uuid, _action_key text, _payload jsonb DEFAULT '{}'::jsonb, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  l record; pol jsonb; cfg jsonb; m record; r record; am record; v_notice record;
  new_status text; old_status text;
  adverse boolean;
  v_matter_id uuid; v_renewal_id uuid; v_close_matter uuid; v_decision_id uuid;
  v_new_until timestamptz; v_deadline timestamptz;
  v_avail jsonb; v_offer jsonb;
  v_prev_term record; v_term_id uuid; v_term_no int;
  v_kind text; v_ent uuid; v_effective date; v_legal text;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;

  SELECT * INTO l FROM public.licenses WHERE id = _license_id FOR UPDATE;
  IF l IS NULL THEN RAISE EXCEPTION 'LICENSE_NOT_FOUND' USING ERRCODE='22023'; END IF;
  old_status := l.status;
  pol := public.license_lifecycle_policy(l.sector_id, l.sub_sector_id, l.category_id);
  cfg := public.license_lifecycle_config_resolve(l.id, 'renewal');
  SELECT id INTO v_ent FROM public.licensees WHERE license_id = l.id LIMIT 1;
  v_effective := COALESCE(NULLIF(_payload->>'effective_date','')::date, current_date);

  adverse := _action_key IN ('REFUSE_RENEWAL','BEGIN_SUSPENSION','SUSPEND','BEGIN_REVOCATION','REVOKE',
                             'ACCEPT_SURRENDER','MARK_EXPIRED','REFUSE_SURRENDER','REFUSE_REINSTATEMENT');

  IF _action_key IN ('IMPOSE_CONDITION','VARY_CONDITION','SATISFY_CONDITION') THEN
    PERFORM public.enforce_permission('license_management','manage_conditions');
  ELSIF _action_key IN ('APPROVE_RENEWAL','REFUSE_RENEWAL') THEN
    PERFORM public.enforce_permission('license_management','approve');
  ELSIF _action_key IN ('ISSUE_NOTICE','RECORD_REPRESENTATION','CLOSE_REPRESENTATION_WINDOW',
                        'WAIVE_REPRESENTATION_PERIOD','COMPLETE_EVIDENCE_REVIEW','COMPLETE_SURRENDER_REVIEW',
                        'COMPLETE_REINSTATEMENT_VERIFICATION','CLOSE_MATTER_NO_ACTION','BEGIN_REINSTATEMENT',
                        'BEGIN_EXPIRY_REVIEW','REINSTATE') OR adverse THEN
    PERFORM public.enforce_permission('license_management','manage_license_actions');
  ELSE
    PERFORM public.enforce_permission('license_management','workflow_action');
  END IF;

  -- single authority: the action must be currently offered by the server
  IF _action_key NOT IN ('IMPOSE_CONDITION','VARY_CONDITION','SATISFY_CONDITION') THEN
    v_avail := public.license_lifecycle_available_actions(l.id);
    SELECT a INTO v_offer FROM jsonb_array_elements(v_avail) a
     WHERE a->>'key' = _action_key
       AND (_payload->>'matter_id' IS NULL OR a->>'matter_id' IS NULL OR a->>'matter_id' = _payload->>'matter_id')
     LIMIT 1;
    IF v_offer IS NULL THEN
      RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023',
        DETAIL = 'Action ' || _action_key || ' is not available for this licence in its current state.';
    END IF;
    IF COALESCE((v_offer->>'requires_reason')::boolean,false) AND COALESCE(length(btrim(_reason)),0) < 10 THEN
      RAISE EXCEPTION 'REASON_REQUIRED' USING ERRCODE='22023';
    END IF;
    -- Due-process blockers on adverse decisions can never be overridden.
    IF jsonb_array_length(COALESCE(v_offer->'blockers','[]'::jsonb)) > 0
       AND (COALESCE((v_offer->>'adverse')::boolean,false)
            OR _action_key IN ('REINSTATE','COMPLETE_EVIDENCE_REVIEW','COMPLETE_SURRENDER_REVIEW',
                               'COMPLETE_REINSTATEMENT_VERIFICATION','CLOSE_REPRESENTATION_WINDOW')
            OR NOT COALESCE((_payload->>'override_blockers')::boolean,false)) THEN
      RAISE EXCEPTION 'BLOCKED' USING ERRCODE='22023', DETAIL = v_offer->>'blockers';
    END IF;
  END IF;

  IF adverse AND COALESCE(length(btrim(_reason)),0) < 10 THEN
    RAISE EXCEPTION 'REASON_REQUIRED' USING ERRCODE='22023';
  END IF;

  IF l.status IN ('revoked','surrendered') THEN
    RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023';
  END IF;

  -- resolve the adverse matter this action belongs to (server-side)
  IF v_offer ? 'matter_id' AND NULLIF(v_offer->>'matter_id','') IS NOT NULL THEN
    SELECT * INTO am FROM public.license_lifecycle_matters
     WHERE id = (v_offer->>'matter_id')::uuid FOR UPDATE;
  END IF;

  SELECT * INTO m FROM public.license_lifecycle_matters
   WHERE license_id = l.id AND status = 'open' ORDER BY opened_at LIMIT 1;

  IF _action_key = 'START_RENEWAL' THEN
    IF l.status NOT IN ('active','restricted','expired') THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023'; END IF;
    IF EXISTS (SELECT 1 FROM public.license_renewals x WHERE x.license_id = l.id AND x.status NOT IN ('approved','refused','withdrawn')) THEN
      RAISE EXCEPTION 'RENEWAL_ALREADY_OPEN' USING ERRCODE='22023';
    END IF;
    INSERT INTO public.license_renewals(license_id, initiated_by, status, previous_valid_until, notes)
    VALUES (l.id, uid, 'in_progress', l.valid_until, _reason) RETURNING id INTO v_renewal_id;
    INSERT INTO public.license_lifecycle_matters(license_id, matter_kind, title, reason, renewal_id, opened_by, due_at, waiting_on, metadata)
    VALUES (l.id, 'renewal', 'Licence renewal', _reason, v_renewal_id, uid, l.valid_until, 'regulator',
            jsonb_build_object('config_id', cfg->>'config_id', 'policy_snapshot', cfg))
    RETURNING id INTO v_matter_id;

  ELSIF _action_key = 'REQUEST_RENEWAL_INFORMATION' THEN
    SELECT * INTO r FROM public.license_renewals WHERE license_id = l.id AND status NOT IN ('approved','refused','withdrawn') ORDER BY created_at DESC LIMIT 1;
    IF r IS NULL THEN RAISE EXCEPTION 'NO_OPEN_RENEWAL' USING ERRCODE='22023'; END IF;
    UPDATE public.license_renewals SET status='information_requested', notes=COALESCE(_reason, notes), updated_at=now() WHERE id=r.id;
    UPDATE public.license_lifecycle_matters SET waiting_on='entity', reason=COALESCE(_reason, reason) WHERE license_id=l.id AND status='open' AND matter_kind='renewal';
    v_renewal_id := r.id;

  ELSIF _action_key IN ('APPROVE_RENEWAL','REFUSE_RENEWAL') THEN
    SELECT * INTO r FROM public.license_renewals WHERE license_id = l.id AND status NOT IN ('approved','refused','withdrawn') ORDER BY created_at DESC LIMIT 1;
    IF r IS NULL THEN RAISE EXCEPTION 'NO_OPEN_RENEWAL' USING ERRCODE='22023'; END IF;
    v_renewal_id := r.id;
    SELECT * INTO v_prev_term FROM public.license_terms WHERE license_id = l.id AND is_current LIMIT 1;

    IF _action_key = 'APPROVE_RENEWAL' THEN
      v_new_until := COALESCE((_payload->>'new_valid_until')::timestamptz,
                              GREATEST(COALESCE(l.valid_until, now()), now())
                                + make_interval(days => COALESCE(NULLIF(cfg->>'period_days','')::int,
                                                                 NULLIF(pol->>'period_days','')::int, 365)));
      UPDATE public.license_renewals SET status='approved', reviewed_by=uid, reviewed_at=now(),
             new_valid_until=v_new_until, decision_reason=_reason, updated_at=now() WHERE id=r.id;

      SELECT COALESCE(max(term_number),0) + 1 INTO v_term_no FROM public.license_terms WHERE license_id = l.id;
      IF v_prev_term.id IS NOT NULL THEN
        UPDATE public.license_terms SET is_current = false WHERE id = v_prev_term.id;
      END IF;
      INSERT INTO public.license_terms(license_id, term_number, term_kind, effective_from, effective_until,
        source_decision, renewal_id, matter_id, decision_actor, decision_at, conditions_snapshot, is_current, metadata)
      VALUES (l.id, v_term_no, 'renewal',
              COALESCE(v_prev_term.effective_until, l.valid_until, now()), v_new_until,
              'APPROVE_RENEWAL', r.id,
              (SELECT id FROM public.license_lifecycle_matters WHERE license_id=l.id AND status='open' AND matter_kind='renewal' ORDER BY opened_at LIMIT 1),
              uid, now(),
              COALESCE((SELECT jsonb_agg(jsonb_build_object('id',c.id,'category',c.category,'description',c.description,'status',c.status,'due_date',c.due_date))
                          FROM public.license_conditions c
                         WHERE c.license_id = l.id AND c.status NOT IN ('closed')), '[]'::jsonb),
              true,
              jsonb_build_object('policy_snapshot', cfg, 'decision_reason', _reason))
      RETURNING id INTO v_term_id;
      IF v_prev_term.id IS NOT NULL THEN
        UPDATE public.license_terms SET superseded_by = v_term_id, superseded_at = now() WHERE id = v_prev_term.id;
      END IF;

      UPDATE public.licenses SET valid_until=v_new_until,
             status = CASE WHEN status='expired' THEN 'active' ELSE status END, updated_at=now() WHERE id=l.id;
      new_status := (SELECT status FROM public.licenses WHERE id=l.id);
    ELSE
      UPDATE public.license_renewals SET status='refused', reviewed_by=uid, reviewed_at=now(), decision_reason=_reason, updated_at=now() WHERE id=r.id;
      UPDATE public.license_lifecycle_matters
         SET metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object(
               'refusal', jsonb_build_object('decided_by', uid, 'decided_at', now(),
                                             'rationale', _reason,
                                             'preserved_term_id', v_prev_term.id,
                                             'preserved_valid_until', l.valid_until))
       WHERE license_id = l.id AND status = 'open' AND matter_kind = 'renewal';
    END IF;
    UPDATE public.license_lifecycle_matters SET status='closed', closed_at=now(), closed_by=uid,
           stage='DECIDED', decision = _action_key WHERE license_id=l.id AND status='open' AND matter_kind='renewal';

  -- ================= A.9–A.13 matter entry points ====================
  ELSIF _action_key IN ('BEGIN_SUSPENSION','BEGIN_REVOCATION','BEGIN_SURRENDER','BEGIN_REINSTATEMENT',
                        'BEGIN_EXPIRY_REVIEW','APPLY_VARIATION') THEN
    v_kind := CASE _action_key WHEN 'BEGIN_SUSPENSION' THEN 'suspension'
                               WHEN 'BEGIN_REVOCATION' THEN 'revocation'
                               WHEN 'BEGIN_SURRENDER' THEN 'surrender'
                               WHEN 'BEGIN_REINSTATEMENT' THEN 'reinstatement'
                               WHEN 'BEGIN_EXPIRY_REVIEW' THEN 'expiry'
                               ELSE 'variation' END;
    cfg := public.license_lifecycle_config_resolve(l.id, v_kind);
    INSERT INTO public.license_lifecycle_matters(license_id, matter_kind, title, reason, opened_by, due_at,
      waiting_on, metadata, stage, source_kind, source_id, source_reference, legal_basis, owner_user_id, team,
      sla_due_at, related_matter_id, config_id, effective_date)
    VALUES (l.id, v_kind,
            COALESCE(NULLIF(_payload->>'title',''), initcap(replace(v_kind,'_',' ')) || ' review'),
            _reason, uid, (_payload->>'due_at')::timestamptz,
            CASE WHEN _action_key IN ('APPLY_VARIATION','BEGIN_SURRENDER') THEN 'entity' ELSE 'regulator' END,
            jsonb_build_object('policy_snapshot', cfg, 'payload', COALESCE(_payload,'{}'::jsonb)),
            CASE v_kind WHEN 'reinstatement' THEN 'VERIFICATION'
                        WHEN 'surrender' THEN 'SURRENDER_REVIEW'
                        WHEN 'expiry' THEN 'EXPIRY_REVIEW'
                        ELSE 'OPEN' END,
            NULLIF(_payload->>'source_kind',''), NULLIF(_payload->>'source_id','')::uuid,
            NULLIF(_payload->>'source_reference',''), NULLIF(_payload->>'legal_basis',''),
            COALESCE(NULLIF(_payload->>'owner_user_id','')::uuid, uid), NULLIF(_payload->>'team',''),
            (_payload->>'due_at')::timestamptz, NULLIF(_payload->>'related_matter_id','')::uuid,
            NULLIF(cfg->>'config_id','')::uuid, NULLIF(_payload->>'effective_date','')::date)
    RETURNING id INTO v_matter_id;

  -- ================= due process steps ===============================
  ELSIF _action_key = 'ISSUE_NOTICE' THEN
    cfg := public.license_lifecycle_config_resolve(l.id, am.matter_kind);
    v_deadline := COALESCE(NULLIF(_payload->>'representation_deadline','')::timestamptz,
                           now() + make_interval(days => COALESCE((cfg->>'representation_period_days')::int, 14)));
    INSERT INTO public.license_matter_notices(matter_id, license_id, notice_kind, notice_reference, subject, body,
      legal_basis, issued_by, representation_deadline, correspondence_thread_id, delivery_channel,
      delivery_evidence, delivery_confirmed_at, metadata)
    VALUES (am.id, l.id, 'proposed_action', NULLIF(_payload->>'notice_reference',''),
            COALESCE(NULLIF(_payload->>'subject',''), 'Notice of proposed ' || am.matter_kind),
            COALESCE(NULLIF(_payload->>'body',''), _reason),
            COALESCE(NULLIF(_payload->>'legal_basis',''), am.legal_basis), uid, v_deadline,
            NULLIF(_payload->>'correspondence_thread_id','')::uuid,
            COALESCE(NULLIF(_payload->>'delivery_channel',''),'email'),
            COALESCE(_payload->'delivery_evidence','[]'::jsonb),
            NULLIF(_payload->>'delivery_confirmed_at','')::timestamptz,
            jsonb_build_object('payload', COALESCE(_payload,'{}'::jsonb)));
    UPDATE public.license_lifecycle_matters
       SET stage = CASE WHEN COALESCE((cfg->>'representation_period_days')::int,14) > 0
                        THEN 'REPRESENTATION_WINDOW' ELSE 'EVIDENCE_REVIEW' END,
           waiting_on = 'entity',
           legal_basis = COALESCE(NULLIF(_payload->>'legal_basis',''), legal_basis),
           sla_due_at = v_deadline, due_at = COALESCE(due_at, v_deadline)
     WHERE id = am.id;
    v_matter_id := am.id;

  ELSIF _action_key = 'RECORD_REPRESENTATION' THEN
    SELECT * INTO v_notice FROM public.license_matter_notices
     WHERE matter_id = am.id AND notice_kind='proposed_action' ORDER BY issued_at DESC LIMIT 1;
    INSERT INTO public.license_matter_representations(matter_id, license_id, notice_id, received_at, received_via,
      submitter_name, submitted_by, summary, documents, is_late, recorded_by, metadata)
    VALUES (am.id, l.id, v_notice.id,
            COALESCE(NULLIF(_payload->>'received_at','')::timestamptz, now()),
            COALESCE(NULLIF(_payload->>'received_via',''),'email'),
            NULLIF(_payload->>'submitter_name',''), NULLIF(_payload->>'submitted_by','')::uuid,
            COALESCE(NULLIF(_payload->>'summary',''), _reason),
            COALESCE(_payload->'documents','[]'::jsonb),
            (v_notice.representation_deadline IS NOT NULL
             AND COALESCE(NULLIF(_payload->>'received_at','')::timestamptz, now()) > v_notice.representation_deadline),
            uid, jsonb_build_object('payload', COALESCE(_payload,'{}'::jsonb)));
    UPDATE public.license_lifecycle_matters SET waiting_on='regulator' WHERE id = am.id;
    v_matter_id := am.id;

  ELSIF _action_key IN ('CLOSE_REPRESENTATION_WINDOW','WAIVE_REPRESENTATION_PERIOD') THEN
    IF _action_key = 'WAIVE_REPRESENTATION_PERIOD' THEN
      SELECT * INTO v_notice FROM public.license_matter_notices
       WHERE matter_id = am.id AND notice_kind='proposed_action' ORDER BY issued_at DESC LIMIT 1;
      INSERT INTO public.license_matter_representations(matter_id, license_id, notice_id, received_via,
        summary, is_waiver, waiver_reason, recorded_by)
      VALUES (am.id, l.id, v_notice.id, 'waiver', 'Representation period waived', true, _reason, uid);
    END IF;
    UPDATE public.license_lifecycle_matters SET stage='EVIDENCE_REVIEW', waiting_on='regulator' WHERE id = am.id;
    v_matter_id := am.id;

  ELSIF _action_key IN ('COMPLETE_EVIDENCE_REVIEW','COMPLETE_SURRENDER_REVIEW','COMPLETE_REINSTATEMENT_VERIFICATION') THEN
    UPDATE public.license_lifecycle_matters
       SET stage='DECISION_READY', waiting_on='regulator',
           legal_basis = COALESCE(NULLIF(_payload->>'legal_basis',''), legal_basis),
           metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object(
             lower(_action_key), jsonb_build_object('by', uid, 'at', now(), 'note', _reason))
     WHERE id = am.id;
    v_matter_id := am.id;

  ELSIF _action_key = 'CLOSE_MATTER_NO_ACTION' THEN
    v_close_matter := am.id; v_matter_id := am.id;
    v_kind := am.matter_kind;

  -- ================= decisions =======================================
  ELSIF _action_key = 'SUSPEND' THEN
    IF l.status NOT IN ('active','restricted') THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023'; END IF;
    new_status := 'suspended'; v_close_matter := am.id; v_matter_id := am.id; v_kind := 'suspension';
  ELSIF _action_key = 'REVOKE' THEN
    new_status := 'revoked'; v_close_matter := am.id; v_matter_id := am.id; v_kind := 'revocation';
  ELSIF _action_key = 'REINSTATE' THEN
    IF l.status NOT IN ('suspended','restricted') THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023'; END IF;
    new_status := 'active'; v_close_matter := am.id; v_matter_id := am.id; v_kind := 'reinstatement';
  ELSIF _action_key = 'REFUSE_REINSTATEMENT' THEN
    v_close_matter := am.id; v_matter_id := am.id; v_kind := 'reinstatement';
  ELSIF _action_key = 'ACCEPT_SURRENDER' THEN
    new_status := 'surrendered'; v_close_matter := am.id; v_matter_id := am.id; v_kind := 'surrender';
  ELSIF _action_key = 'REFUSE_SURRENDER' THEN
    v_close_matter := am.id; v_matter_id := am.id; v_kind := 'surrender';
  ELSIF _action_key = 'MARK_EXPIRED' THEN
    IF l.valid_until IS NULL OR l.valid_until > now() THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023'; END IF;
    new_status := 'expired'; v_close_matter := am.id; v_matter_id := am.id; v_kind := 'expiry';

  ELSIF _action_key = 'APPROVE_VARIATION' THEN
    UPDATE public.license_lifecycle_matters SET status='closed', closed_at=now(), closed_by=uid,
           stage='DECIDED', decision='APPROVED'
     WHERE license_id=l.id AND status='open' AND matter_kind='variation';
  ELSE
    RAISE EXCEPTION 'UNKNOWN_ACTION' USING ERRCODE='22023';
  END IF;

  -- ---------------- decision record + matter closure -----------------
  IF v_close_matter IS NOT NULL THEN
    cfg := public.license_lifecycle_config_resolve(l.id, v_kind);
    SELECT COALESCE(NULLIF(am.legal_basis,''),
                    (SELECT n.legal_basis FROM public.license_matter_notices n
                      WHERE n.matter_id = am.id ORDER BY n.issued_at DESC LIMIT 1))
      INTO v_legal;

    INSERT INTO public.license_decisions(matter_id, license_id, entity_id, decision_type, decision, authority,
      actor_id, maker_id, checker_id, effective_date, rationale, legal_basis, conditions, remediation,
      artifact_reference, appealable, appeal_deadline, from_status, to_status, metadata)
    VALUES (am.id, l.id, v_ent, v_kind,
            CASE _action_key WHEN 'CLOSE_MATTER_NO_ACTION' THEN 'no_action' ELSE lower(_action_key) END,
            NULLIF(cfg->>'decision_authority',''), uid, am.opened_by, uid,
            v_effective, _reason, v_legal,
            COALESCE(_payload->'conditions','[]'::jsonb), COALESCE(_payload->'remediation','[]'::jsonb),
            NULLIF(_payload->>'artifact_reference',''),
            (_action_key IN ('SUSPEND','REVOKE','ACCEPT_SURRENDER','MARK_EXPIRED','REFUSE_SURRENDER','REFUSE_REINSTATEMENT')
              AND COALESCE((cfg->>'appealable')::boolean,true)),
            CASE WHEN _action_key IN ('SUSPEND','REVOKE','ACCEPT_SURRENDER','MARK_EXPIRED','REFUSE_SURRENDER','REFUSE_REINSTATEMENT')
                      AND COALESCE((cfg->>'appealable')::boolean,true)
                 THEN now() + make_interval(days => COALESCE((cfg->>'appeal_window_days')::int,30)) END,
            old_status, COALESCE(new_status, old_status),
            jsonb_build_object('payload', COALESCE(_payload,'{}'::jsonb), 'config_id', cfg->>'config_id'))
    RETURNING id INTO v_decision_id;

    UPDATE public.license_lifecycle_matters
       SET status='closed', closed_at=now(), closed_by=uid, stage='DECIDED',
           decision=_action_key, decision_id=v_decision_id,
           effective_date = COALESCE(effective_date, v_effective),
           legal_basis = COALESCE(legal_basis, v_legal)
     WHERE id = v_close_matter;
  END IF;

  IF new_status IS NOT NULL AND new_status <> old_status THEN
    UPDATE public.licenses SET status = new_status, updated_at = now() WHERE id = l.id;
  END IF;

  INSERT INTO public.license_actions(license_id, action_type, actor_id, reason, old_status, new_status, metadata)
  VALUES (l.id, lower(_action_key), uid, _reason, old_status, COALESCE(new_status, old_status),
          jsonb_build_object('payload', COALESCE(_payload,'{}'::jsonb), 'matter_id', v_matter_id,
                             'renewal_id', v_renewal_id, 'term_id', v_term_id, 'decision_id', v_decision_id));

  INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
  VALUES (uid, 'license.lifecycle.' || lower(_action_key), 'license', l.id,
          jsonb_build_object('from', old_status, 'to', COALESCE(new_status, old_status), 'reason', _reason,
                             'term_id', v_term_id, 'matter_id', v_matter_id, 'decision_id', v_decision_id,
                             'payload', COALESCE(_payload,'{}'::jsonb)));

  RETURN public.license_case(l.id, 'internal');
END $function$
;
CREATE OR REPLACE FUNCTION public.license_lifecycle_available_actions(_license_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  l record; pol jsonb; m record; r record; am record;
  v_open_conditions int; v_overdue_conditions int;
  v_days numeric; v_expired boolean;
  out_actions jsonb := '[]'::jsonb;
  can_workflow boolean; can_approve boolean; can_adverse boolean; can_conditions boolean;
  cfg jsonb; pre jsonb; pre_progress jsonb; v_notice record;
  v_kind_label text; v_decide_key text; v_decide_label text;
BEGIN
  SELECT * INTO l FROM public.licenses WHERE id = _license_id;
  IF l IS NULL THEN RAISE EXCEPTION 'LICENSE_NOT_FOUND' USING ERRCODE='22023'; END IF;
  IF uid IS NULL THEN RETURN '[]'::jsonb; END IF;

  can_workflow   := public.is_super_admin(uid) OR public.has_permission(uid,'license_management','workflow_action');
  can_approve    := public.is_super_admin(uid) OR public.has_permission(uid,'license_management','approve');
  can_adverse    := public.is_super_admin(uid) OR public.has_permission(uid,'license_management','manage_license_actions');
  can_conditions := public.is_super_admin(uid) OR public.has_permission(uid,'license_management','manage_conditions');
  IF NOT (can_workflow OR can_approve OR can_adverse OR can_conditions) THEN RETURN '[]'::jsonb; END IF;

  pol := public.license_lifecycle_policy(l.sector_id, l.sub_sector_id, l.category_id);

  SELECT count(*) FILTER (WHERE status IN ('open','in_progress','evidence_due')),
         count(*) FILTER (WHERE status IN ('open','in_progress','evidence_due') AND due_date < current_date)
    INTO v_open_conditions, v_overdue_conditions
    FROM public.license_conditions WHERE license_id = l.id;

  SELECT * INTO m FROM public.license_lifecycle_matters
   WHERE license_id = l.id AND status = 'open'
   ORDER BY CASE matter_kind WHEN 'revocation' THEN 1 WHEN 'suspension' THEN 2 WHEN 'renewal' THEN 3 ELSE 4 END, opened_at
   LIMIT 1;

  SELECT * INTO r FROM public.license_renewals
   WHERE license_id = l.id AND status NOT IN ('approved','refused','withdrawn')
   ORDER BY created_at DESC LIMIT 1;

  v_days := CASE WHEN l.valid_until IS NULL THEN NULL ELSE EXTRACT(EPOCH FROM (l.valid_until - now()))/86400 END;
  v_expired := v_days IS NOT NULL AND v_days < 0;

  IF l.status IN ('revoked','surrendered') THEN RETURN '[]'::jsonb; END IF;

  -- ---------------- renewal -----------------------------------------
  IF r.id IS NOT NULL THEN
    IF can_workflow AND r.status <> 'information_requested' THEN
      out_actions := out_actions || jsonb_build_array(jsonb_build_object(
        'key','REQUEST_RENEWAL_INFORMATION','label','Request renewal information',
        'permission','license_management.workflow_action','adverse',false,'requires_reason',true,
        'blockers','[]'::jsonb,'section','renewal'));
    END IF;
    IF can_approve THEN
      out_actions := out_actions || jsonb_build_array(
        jsonb_build_object('key','APPROVE_RENEWAL','label','Approve renewal',
          'permission','license_management.approve','adverse',false,'requires_reason',false,
          'blockers', CASE WHEN v_overdue_conditions > 0
                           THEN jsonb_build_array(jsonb_build_object('key','overdue_conditions',
                                'label', v_overdue_conditions || ' overdue condition(s) outstanding',
                                'href','/licenses/' || l.id || '?tab=conditions'))
                           ELSE '[]'::jsonb END,
          'section','renewal'),
        jsonb_build_object('key','REFUSE_RENEWAL','label','Refuse renewal',
          'permission','license_management.approve','adverse',true,'requires_reason',true,
          'blockers','[]'::jsonb,'section','renewal'));
    END IF;
  ELSIF can_workflow AND l.status IN ('active','restricted','expired') THEN
    out_actions := out_actions || jsonb_build_array(jsonb_build_object(
      'key','START_RENEWAL','label','Start renewal',
      'permission','license_management.workflow_action','adverse',false,'requires_reason',false,
      'blockers','[]'::jsonb,'section','renewal'));
  END IF;

  -- ---------------- variation ---------------------------------------
  IF m.matter_kind = 'variation' THEN
    IF can_approve THEN
      out_actions := out_actions || jsonb_build_array(jsonb_build_object(
        'key','APPROVE_VARIATION','label','Approve variation',
        'permission','license_management.approve','adverse',false,'requires_reason',false,
        'blockers','[]'::jsonb,'section','variation'));
    END IF;
  ELSIF can_workflow AND l.status = 'active' THEN
    out_actions := out_actions || jsonb_build_array(jsonb_build_object(
      'key','APPLY_VARIATION','label','Open variation matter',
      'permission','license_management.workflow_action','adverse',false,'requires_reason',false,
      'blockers','[]'::jsonb,'section','variation'));
  END IF;

  -- ============ A.9–A.13 adverse lifecycle, stage driven =============
  FOR am IN
    SELECT * FROM public.license_lifecycle_matters
     WHERE license_id = l.id AND status = 'open'
       AND matter_kind IN ('suspension','revocation','reinstatement','surrender','expiry')
     ORDER BY opened_at
  LOOP
    IF NOT can_adverse THEN CONTINUE; END IF;
    cfg := public.license_lifecycle_config_resolve(l.id, am.matter_kind);
    pre := public.license_matter_prerequisites(am.id);
    pre_progress := COALESCE((SELECT jsonb_agg(b) FROM jsonb_array_elements(pre) b
                               WHERE b->>'key' NOT IN ('NOTICE_NOT_ISSUED','REPRESENTATION_WINDOW_OPEN',
                                                       'EVIDENCE_REVIEW_INCOMPLETE','VERIFICATION_INCOMPLETE',
                                                       'SURRENDER_REVIEW_INCOMPLETE','MAKER_CHECKER',
                                                       'DECISION_AUTHORITY','LEGAL_BASIS')), '[]'::jsonb);
    v_kind_label := replace(initcap(am.matter_kind),'_',' ');

    SELECT * INTO v_notice FROM public.license_matter_notices
     WHERE matter_id = am.id AND notice_kind='proposed_action' ORDER BY issued_at DESC LIMIT 1;

    -- Every open adverse matter can be concluded without adverse action.
    out_actions := out_actions || jsonb_build_array(jsonb_build_object(
      'key','CLOSE_MATTER_NO_ACTION','label','Close matter — no further action',
      'permission','license_management.manage_license_actions','adverse',false,'requires_reason',true,
      'blockers','[]'::jsonb,'section','adverse','matter_id', am.id, 'matter_kind', am.matter_kind,
      'stage', am.stage));

    IF am.matter_kind IN ('suspension','revocation') THEN
      v_decide_key := CASE am.matter_kind WHEN 'suspension' THEN 'SUSPEND' ELSE 'REVOKE' END;
      v_decide_label := CASE am.matter_kind WHEN 'suspension' THEN 'Suspend licence' ELSE 'Revoke licence' END;

      IF am.stage = 'OPEN' AND COALESCE((cfg->>'notice_required')::boolean,true) THEN
        out_actions := out_actions || jsonb_build_array(jsonb_build_object(
          'key','ISSUE_NOTICE','label','Issue notice of proposed ' || lower(am.matter_kind),
          'permission','license_management.manage_license_actions','adverse',false,'requires_reason',true,
          'blockers','[]'::jsonb,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,
          'stage', am.stage));
      ELSIF am.stage IN ('NOTICE_OF_PROPOSED_ACTION','REPRESENTATION_WINDOW') THEN
        out_actions := out_actions || jsonb_build_array(
          jsonb_build_object('key','RECORD_REPRESENTATION','label','Record representation received',
            'permission','license_management.manage_license_actions','adverse',false,'requires_reason',false,
            'blockers','[]'::jsonb,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage),
          jsonb_build_object('key','CLOSE_REPRESENTATION_WINDOW','label','Close representation period',
            'permission','license_management.manage_license_actions','adverse',false,'requires_reason',false,
            'blockers', CASE WHEN v_notice.representation_deadline IS NOT NULL
                              AND v_notice.representation_deadline > now()
                              AND NOT EXISTS (SELECT 1 FROM public.license_matter_representations x WHERE x.matter_id = am.id)
                         THEN jsonb_build_array(jsonb_build_object('key','REPRESENTATION_WINDOW_OPEN',
                              'label','Representation period closes ' || to_char(v_notice.representation_deadline,'DD Mon YYYY'),
                              'href','/licenses/' || l.id || '?tab=adverse'))
                         ELSE '[]'::jsonb END,
            'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage));
        IF COALESCE((cfg->>'representation_waiver_allowed')::boolean,true) THEN
          out_actions := out_actions || jsonb_build_array(jsonb_build_object(
            'key','WAIVE_REPRESENTATION_PERIOD','label','Record waiver of representation period',
            'permission','license_management.manage_license_actions','adverse',false,'requires_reason',true,
            'blockers','[]'::jsonb,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage));
        END IF;
      ELSIF am.stage = 'EVIDENCE_REVIEW' OR (am.stage = 'OPEN' AND NOT COALESCE((cfg->>'notice_required')::boolean,true)) THEN
        out_actions := out_actions || jsonb_build_array(jsonb_build_object(
          'key','COMPLETE_EVIDENCE_REVIEW','label','Conclude evidence review',
          'permission','license_management.manage_license_actions','adverse',false,'requires_reason',true,
          'blockers', pre_progress,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage));
        IF COALESCE((cfg->>'late_representation_allowed')::boolean,true) THEN
          out_actions := out_actions || jsonb_build_array(jsonb_build_object(
            'key','RECORD_REPRESENTATION','label','Record late representation',
            'permission','license_management.manage_license_actions','adverse',false,'requires_reason',false,
            'blockers','[]'::jsonb,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage));
        END IF;
      ELSIF am.stage = 'DECISION_READY' THEN
        out_actions := out_actions || jsonb_build_array(jsonb_build_object(
          'key', v_decide_key,'label', v_decide_label,
          'permission','license_management.manage_license_actions','adverse',true,'requires_reason',true,
          'blockers', pre,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage));
      END IF;

    ELSIF am.matter_kind = 'reinstatement' THEN
      IF am.stage IN ('OPEN','VERIFICATION') THEN
        out_actions := out_actions || jsonb_build_array(jsonb_build_object(
          'key','COMPLETE_REINSTATEMENT_VERIFICATION','label','Complete reinstatement verification',
          'permission','license_management.manage_license_actions','adverse',false,'requires_reason',true,
          'blockers', pre_progress,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage));
      ELSIF am.stage = 'DECISION_READY' THEN
        out_actions := out_actions || jsonb_build_array(
          jsonb_build_object('key','REINSTATE','label','Reinstate licence',
            'permission','license_management.manage_license_actions','adverse',false,'requires_reason',true,
            'blockers', pre,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage),
          jsonb_build_object('key','REFUSE_REINSTATEMENT','label','Refuse reinstatement',
            'permission','license_management.manage_license_actions','adverse',true,'requires_reason',true,
            'blockers','[]'::jsonb,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage));
      END IF;

    ELSIF am.matter_kind = 'surrender' THEN
      IF am.stage IN ('OPEN','SURRENDER_REVIEW') THEN
        out_actions := out_actions || jsonb_build_array(jsonb_build_object(
          'key','COMPLETE_SURRENDER_REVIEW','label','Conclude surrender review',
          'permission','license_management.manage_license_actions','adverse',false,'requires_reason',true,
          'blockers', pre_progress,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage));
      ELSIF am.stage = 'DECISION_READY' THEN
        out_actions := out_actions || jsonb_build_array(
          jsonb_build_object('key','ACCEPT_SURRENDER','label','Accept surrender',
            'permission','license_management.manage_license_actions','adverse',true,'requires_reason',true,
            'blockers', pre,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage),
          jsonb_build_object('key','REFUSE_SURRENDER','label','Refuse surrender',
            'permission','license_management.manage_license_actions','adverse',true,'requires_reason',true,
            'blockers','[]'::jsonb,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage));
      END IF;

    ELSIF am.matter_kind = 'expiry' THEN
      out_actions := out_actions || jsonb_build_array(jsonb_build_object(
        'key','MARK_EXPIRED','label','Confirm lapse (mark expired)',
        'permission','license_management.manage_license_actions','adverse',true,'requires_reason',true,
        'blockers', pre,'section','adverse','matter_id', am.id,'matter_kind', am.matter_kind,'stage', am.stage));
    END IF;
  END LOOP;

  -- ---------------- entry points (no open matter of that kind) -------
  IF can_adverse AND l.status IN ('active','restricted')
     AND NOT EXISTS (SELECT 1 FROM public.license_lifecycle_matters x
                      WHERE x.license_id=l.id AND x.status='open' AND x.matter_kind='suspension') THEN
    out_actions := out_actions || jsonb_build_array(jsonb_build_object(
      'key','BEGIN_SUSPENSION','label','Begin suspension review',
      'permission','license_management.manage_license_actions','adverse',true,'requires_reason',true,
      'blockers','[]'::jsonb,'section','adverse'));
  END IF;

  IF can_adverse AND l.status IN ('active','restricted','suspended')
     AND NOT EXISTS (SELECT 1 FROM public.license_lifecycle_matters x
                      WHERE x.license_id=l.id AND x.status='open' AND x.matter_kind='revocation') THEN
    out_actions := out_actions || jsonb_build_array(jsonb_build_object(
      'key','BEGIN_REVOCATION','label','Begin revocation review',
      'permission','license_management.manage_license_actions','adverse',true,'requires_reason',true,
      'blockers','[]'::jsonb,'section','adverse'));
  END IF;

  IF can_adverse AND l.status = 'suspended'
     AND NOT EXISTS (SELECT 1 FROM public.license_lifecycle_matters x
                      WHERE x.license_id=l.id AND x.status='open' AND x.matter_kind='reinstatement') THEN
    out_actions := out_actions || jsonb_build_array(jsonb_build_object(
      'key','BEGIN_REINSTATEMENT','label','Begin reinstatement review',
      'permission','license_management.manage_license_actions','adverse',false,'requires_reason',true,
      'blockers','[]'::jsonb,'section','adverse'));
  END IF;

  IF can_workflow AND l.status IN ('active','restricted','suspended')
     AND NOT EXISTS (SELECT 1 FROM public.license_lifecycle_matters x
                      WHERE x.license_id=l.id AND x.status='open' AND x.matter_kind='surrender') THEN
    out_actions := out_actions || jsonb_build_array(jsonb_build_object(
      'key','BEGIN_SURRENDER','label','Open surrender matter',
      'permission','license_management.workflow_action','adverse',false,'requires_reason',true,
      'blockers','[]'::jsonb,'section','adverse'));
  END IF;

  IF can_adverse AND v_expired AND l.status IN ('active','restricted')
     AND NOT EXISTS (SELECT 1 FROM public.license_lifecycle_matters x
                      WHERE x.license_id=l.id AND x.status='open' AND x.matter_kind='expiry') THEN
    out_actions := out_actions || jsonb_build_array(jsonb_build_object(
      'key','BEGIN_EXPIRY_REVIEW','label','Open expiry review',
      'permission','license_management.manage_license_actions','adverse',false,'requires_reason',true,
      'blockers','[]'::jsonb,'section','adverse'));
  END IF;

  RETURN out_actions;
END
$function$
;
CREATE OR REPLACE FUNCTION public.license_lifecycle_config_resolve(_license_id uuid, _matter_kind text DEFAULT 'renewal'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE l record; pol jsonb; c record;
BEGIN
  SELECT * INTO l FROM public.licenses WHERE id = _license_id;
  IF l IS NULL THEN RAISE EXCEPTION 'LICENSE_NOT_FOUND' USING ERRCODE='22023'; END IF;
  pol := public.license_lifecycle_policy(l.sector_id, l.sub_sector_id, l.category_id);

  SELECT * INTO c
    FROM public.license_lifecycle_configs x
   WHERE x.is_active
     AND x.matter_kind = COALESCE(_matter_kind,'renewal')
     AND (x.regulator_id IS NULL OR x.regulator_id = l.regulator_id)
     AND (x.sector_id IS NULL OR x.sector_id = l.sector_id)
     AND (x.sub_sector_id IS NULL OR x.sub_sector_id = l.sub_sector_id)
     AND (x.category_id IS NULL OR x.category_id = l.category_id)
     AND (x.license_type IS NULL OR x.license_type = l.license_type)
   ORDER BY (CASE WHEN x.category_id IS NOT NULL THEN 8 ELSE 0 END)
          + (CASE WHEN x.license_type IS NOT NULL THEN 4 ELSE 0 END)
          + (CASE WHEN x.sub_sector_id IS NOT NULL THEN 2 ELSE 0 END)
          + (CASE WHEN x.sector_id IS NOT NULL THEN 1 ELSE 0 END) DESC,
          x.updated_at DESC
   LIMIT 1;

  IF c.id IS NULL THEN
    RETURN pol || jsonb_build_object(
      'config_id', NULL, 'matter_kind', COALESCE(_matter_kind,'renewal'), 'source', 'site_settings',
      'required_documents','[]'::jsonb, 'verification_required', true, 'verification_checklist','[]'::jsonb,
      'fp_required', false, 'fee_required', false, 'fee_type_code', NULL,
      'payment_verification_required', false, 'decision_authority', NULL,
      'late_renewal_treatment','grace_then_lapse', 'expiry_behavior','officer_confirmed',
      'breach_consequence','supervisory_followup', 'workflow_id', NULL,
      'required_form_package_id', NULL,
      'notice_required', true, 'representation_period_days', 14,
      'representation_waiver_allowed', true, 'late_representation_allowed', true,
      'evidence_review_required', true, 'maker_checker_required', false,
      'legal_basis_required', true, 'appealable', true, 'appeal_window_days', 30,
      'reinstatement_prerequisites','["conditions_satisfied","evidence_approved","obligations_resolved"]'::jsonb,
      'surrender_blockers','["OPEN_CONDITIONS","OPEN_ENFORCEMENT","UNRESOLVED_REPORTING"]'::jsonb);
  END IF;

  RETURN jsonb_build_object(
    'config_id', c.id, 'matter_kind', c.matter_kind, 'source','license_lifecycle_configs',
    'cycle_type', c.renewal_cycle, 'renewal_cycle', c.renewal_cycle,
    'period_days', c.period_days, 'renewal_window_days', c.renewal_window_days,
    'grace_period_days', c.grace_period_days, 'reminder_days', c.reminder_days,
    'required_form_package_id', c.required_form_package_id,
    'required_documents', c.required_documents,
    'verification_required', c.verification_required,
    'verification_checklist', c.verification_checklist,
    'fp_required', c.fp_required,
    'fee_required', c.fee_required, 'fee_type_code', c.fee_type_code,
    'payment_verification_required', c.payment_verification_required,
    'decision_authority', c.decision_authority,
    'late_renewal_treatment', c.late_renewal_treatment,
    'expiry_behavior', c.expiry_behavior,
    'breach_consequence', c.breach_consequence,
    'workflow_id', c.workflow_id,
    'notice_required', c.notice_required,
    'representation_period_days', c.representation_period_days,
    'representation_waiver_allowed', c.representation_waiver_allowed,
    'late_representation_allowed', c.late_representation_allowed,
    'evidence_review_required', c.evidence_review_required,
    'maker_checker_required', c.maker_checker_required,
    'legal_basis_required', c.legal_basis_required,
    'appealable', c.appealable,
    'appeal_window_days', c.appeal_window_days,
    'reinstatement_prerequisites', c.reinstatement_prerequisites,
    'surrender_blockers', c.surrender_blockers);
END $function$
;
CREATE OR REPLACE FUNCTION public.license_lifecycle_gates(_license_id uuid, _matter_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(b), '[]'::jsonb) FROM (
    SELECT jsonb_build_object(
             'key','fee_outstanding',
             'label', 'Fee outstanding: ' || COALESCE(a.description,'lifecycle fee')
                      || ' (' || a.currency || ' ' || to_char(a.amount,'FM999,999,999.00') || ')',
             'href', '/licenses/' || a.license_id || '?tab=fees') AS b
      FROM public.license_fee_assessments a
     WHERE a.license_id = _license_id
       AND (_matter_id IS NULL OR a.matter_id IS NOT DISTINCT FROM _matter_id)
       AND a.blocking AND a.status IN ('due','paid')
    UNION ALL
    SELECT jsonb_build_object('key','verification_incomplete',
             'label','Verification case not completed',
             'href','/licenses/' || c.license_id || '?tab=verification')
      FROM public.license_verification_cases c
     WHERE c.license_id = _license_id
       AND (_matter_id IS NULL OR c.matter_id IS NOT DISTINCT FROM _matter_id)
       AND c.status = 'in_progress'
  ) s;
$function$
;
CREATE OR REPLACE FUNCTION public.license_lifecycle_policy(_sector uuid, _sub uuid, _cat uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb; d jsonb; best jsonb; r jsonb; sc int; bestsc int := -1;
BEGIN
  SELECT value INTO v FROM public.site_settings WHERE key = 'license_expiry';
  d := COALESCE(v->'default', v, '{}'::jsonb);
  IF jsonb_typeof(d) <> 'object' THEN d := '{}'::jsonb; END IF;
  best := d;
  IF jsonb_typeof(v->'rules') = 'array' THEN
    FOR r IN SELECT * FROM jsonb_array_elements(v->'rules') LOOP
      IF (r->>'sector_id' IS NULL OR r->>'sector_id' = _sector::text)
         AND (r->>'sub_sector_id' IS NULL OR r->>'sub_sector_id' = _sub::text)
         AND (r->>'category_id' IS NULL OR r->>'category_id' = _cat::text) THEN
        sc := (CASE WHEN r->>'category_id' IS NOT NULL THEN 4 ELSE 0 END)
            + (CASE WHEN r->>'sub_sector_id' IS NOT NULL THEN 2 ELSE 0 END)
            + (CASE WHEN r->>'sector_id' IS NOT NULL THEN 1 ELSE 0 END);
        IF sc > bestsc THEN bestsc := sc; best := d || r; END IF;
      END IF;
    END LOOP;
  END IF;
  RETURN jsonb_build_object(
    'cycle_type', COALESCE(best->>'cycle_type','annual'),
    'period_days', COALESCE(NULLIF(best->>'period_days','')::int, 365),
    'grace_period_days', COALESCE(NULLIF(best->>'grace_period_days','')::int, 30),
    'renewal_window_days', COALESCE(NULLIF(best->>'renewal_window_days','')::int, 90),
    'reminder_days', COALESCE(best->'reminder_days', '[10,5,1]'::jsonb)
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.license_lifecycle_step(_license_id uuid, _action_key text, _payload jsonb DEFAULT '{}'::jsonb, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_avail jsonb; v_offer jsonb; req jsonb; f jsonb; fv text; v_gates jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;

  v_avail := public.license_lifecycle_available_actions(_license_id);
  SELECT a INTO v_offer FROM jsonb_array_elements(v_avail) a
   WHERE a->>'key' = _action_key
     AND (_payload->>'matter_id' IS NULL OR a->>'matter_id' IS NULL OR a->>'matter_id' = _payload->>'matter_id')
   LIMIT 1;

  IF v_offer IS NULL AND _action_key NOT IN ('IMPOSE_CONDITION','VARY_CONDITION','SATISFY_CONDITION') THEN
    RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023',
      DETAIL = 'Action ' || _action_key || ' is not available for this licence in its current state.';
  END IF;

  IF v_offer IS NOT NULL THEN
    req := public.license_action_input_requirements(_license_id, _action_key, v_offer->>'matter_kind');
    FOR f IN SELECT value FROM jsonb_array_elements(req) LOOP
      IF COALESCE((f->>'required')::boolean, false) THEN
        fv := NULLIF(btrim(COALESCE(_payload->>(f->>'key'), '')), '');
        IF fv IS NULL THEN
          RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023',
            DETAIL = (f->>'label') || ' is required for ' || _action_key || '.';
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- A.15–A.18: outstanding blocking fees / incomplete verification stop
  -- every determinative or renewal-granting step.
  IF _action_key IN ('APPROVE_RENEWAL','APPROVE_VARIATION','DECIDE_SUSPENSION','DECIDE_REVOCATION',
                     'DECIDE_REINSTATEMENT','ACCEPT_SURRENDER') THEN
    v_gates := public.license_lifecycle_gates(_license_id, NULLIF(_payload->>'matter_id','')::uuid);
    IF jsonb_array_length(v_gates) > 0 THEN
      RAISE EXCEPTION 'BLOCKED' USING ERRCODE='22023',
        DETAIL = (SELECT string_agg(b->>'label', '; ') FROM jsonb_array_elements(v_gates) b);
    END IF;
  END IF;

  RETURN public.license_lifecycle_action(_license_id, _action_key, COALESCE(_payload,'{}'::jsonb), _reason);
END $function$
;
CREATE OR REPLACE FUNCTION public.license_lifecycle_work_queue(_kinds text[] DEFAULT NULL::text[], _search text DEFAULT NULL::text, _page integer DEFAULT 0, _page_size integer DEFAULT 25)
 RETURNS TABLE(work_kind text, object_type text, object_id uuid, license_id uuid, reference text, entity_id uuid, entity_name text, stage text, status text, priority text, priority_reason text, sla_due_at timestamp with time zone, sla_state text, waiting_on text, owner_user_id uuid, owner_name text, team text, blocker_count integer, blockers jsonb, next_action text, next_action_code text, next_action_label text, next_action_permission text, canonical_href text, last_activity_at timestamp with time zone, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_internal boolean; v_off int;
BEGIN
  v_internal := public.is_super_admin(auth.uid()) OR public.has_permission(auth.uid(),'license_management','view');
  _page_size := LEAST(GREATEST(COALESCE(_page_size,25),1),200);
  v_off := GREATEST(COALESCE(_page,0),0) * _page_size;

  RETURN QUERY
  WITH lic AS (
    SELECT l.*, le.id AS ent_id, COALESCE(le.name, l.license_type) AS ent_name,
      COALESCE(le.regulator_officer_id, le.assigned_supervisor_id) AS ent_owner,
      CASE WHEN l.valid_until IS NULL THEN NULL ELSE EXTRACT(EPOCH FROM (l.valid_until - now()))/86400 END AS d2e,
      COALESCE((public.license_lifecycle_policy(l.sector_id,l.sub_sector_id,l.category_id)->>'renewal_window_days')::int, 90) AS win
    FROM public.licenses l
    LEFT JOIN public.licensees le ON le.license_id = l.id
    WHERE (v_internal OR l.holder_id = auth.uid())
  ),
  rows_all AS (
    SELECT m.matter_kind AS work_kind, 'license_matter'::text AS object_type, m.id AS object_id, l.id AS license_id,
           l.license_number AS reference, l.ent_id AS entity_id, l.ent_name AS entity_name,
           upper(m.matter_kind) AS stage, m.status AS status,
           CASE WHEN m.matter_kind IN ('revocation','suspension') THEN 'critical' ELSE 'medium' END AS priority,
           CASE WHEN m.matter_kind IN ('revocation','suspension') THEN 'Adverse lifecycle action in progress'
                ELSE 'Open ' || replace(m.matter_kind,'_',' ') || ' matter' END AS priority_reason,
           COALESCE(m.due_at, l.valid_until) AS sla_due_at,
           CASE WHEN COALESCE(m.due_at, l.valid_until) IS NULL THEN 'on_track'
                WHEN COALESCE(m.due_at, l.valid_until) < now() THEN 'breached' ELSE 'on_track' END AS sla_state,
           m.waiting_on AS waiting_on,
           l.ent_owner AS owner_user_id,
           ('Progress ' || replace(m.matter_kind,'_',' '))::text AS next_action,
           ('/licenses/' || l.id)::text AS canonical_href,
           m.updated_at AS last_activity_at
    FROM public.license_lifecycle_matters m JOIN lic l ON l.id = m.license_id
    WHERE m.status = 'open'
    UNION ALL
    SELECT CASE WHEN l.d2e < 0 THEN 'expiry_review' ELSE 'renewal_due' END, 'license', l.id, l.id,
           l.license_number, l.ent_id, l.ent_name,
           CASE WHEN l.d2e < 0 THEN 'EXPIRY_REVIEW' ELSE 'RENEWAL_DUE' END, l.status,
           CASE WHEN l.d2e < 0 THEN 'high' ELSE 'medium' END,
           CASE WHEN l.d2e < 0 THEN 'Licence past expiry' ELSE 'Renewal window open' END,
           l.valid_until,
           CASE WHEN l.d2e < 0 THEN 'breached' ELSE 'due_soon' END,
           'regulator', l.ent_owner,
           CASE WHEN l.d2e < 0 THEN 'Complete expiry review' ELSE 'Start renewal' END,
           ('/licenses/' || l.id)::text, l.updated_at
    FROM lic l
    WHERE l.status IN ('active','restricted') AND l.valid_until IS NOT NULL AND l.d2e <= l.win
      AND NOT EXISTS (SELECT 1 FROM public.license_lifecycle_matters m WHERE m.license_id = l.id AND m.status = 'open')
    UNION ALL
    SELECT 'condition_evidence', 'license_condition', c.id, l.id,
           l.license_number, l.ent_id, l.ent_name, 'CONDITION_EVIDENCE', c.status,
           CASE WHEN c.due_date < current_date THEN 'high' ELSE 'low' END,
           CASE WHEN c.due_date < current_date THEN 'Overdue licence condition' ELSE 'Condition evidence due' END,
           (c.due_date::timestamptz),
           CASE WHEN c.due_date IS NULL THEN 'on_track' WHEN c.due_date < current_date THEN 'breached' ELSE 'due_soon' END,
           'entity', l.ent_owner, 'Review condition evidence', ('/licenses/' || l.id || '?tab=conditions')::text, c.updated_at
    FROM public.license_conditions c JOIN lic l ON l.id = c.license_id
    WHERE c.status IN ('open','in_progress')
      AND c.due_date IS NOT NULL AND c.due_date <= (current_date + 30)
    UNION ALL
    SELECT 'suspension_review', 'license', l.id, l.id, l.license_number, l.ent_id, l.ent_name,
           'SUSPENDED', l.status, 'critical', 'Licence suspended pending review', l.valid_until, 'breached', 'regulator',
           l.ent_owner, 'Review suspension', ('/licenses/' || l.id)::text, l.updated_at
    FROM lic l WHERE l.status = 'suspended'
    UNION ALL
    SELECT 'appeal', 'license_appeal', a.id, l.id, COALESCE(a.appeal_reference, l.license_number), l.ent_id, l.ent_name,
           'APPEAL', a.status, 'high', 'Open licence appeal', a.appeal_deadline,
           CASE WHEN a.appeal_deadline IS NOT NULL AND a.appeal_deadline < now() THEN 'breached' ELSE 'on_track' END,
           'regulator', l.ent_owner, 'Progress appeal', ('/licensing/appeals/' || a.id)::text, a.updated_at
    FROM public.license_appeals a JOIN lic l ON l.id = a.license_id
    WHERE a.status NOT IN ('decided','withdrawn','closed')
  ),
  filtered AS (
    SELECT * FROM rows_all r
    WHERE (_kinds IS NULL OR array_length(_kinds,1) IS NULL OR r.work_kind = ANY(_kinds))
      AND (_search IS NULL OR _search = '' OR r.reference ILIKE '%'||_search||'%' OR COALESCE(r.entity_name,'') ILIKE '%'||_search||'%')
  ),
  paged AS (
    SELECT f.*, count(*) OVER () AS total_count
    FROM filtered f
    ORDER BY CASE f.priority WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'medium' THEN 3 ELSE 4 END,
             f.sla_due_at ASC NULLS LAST
    LIMIT _page_size OFFSET v_off
  )
  SELECT p.work_kind, p.object_type, p.object_id, p.license_id, p.reference, p.entity_id, p.entity_name,
         p.stage, p.status, p.priority, p.priority_reason, p.sla_due_at, p.sla_state, p.waiting_on,
         COALESCE(p.owner_user_id, sa.supervisor_id) AS owner_user_id,
         COALESCE(pr.full_name, sa.supervisor_name) AS owner_name,
         sa.team AS team,
         COALESCE(jsonb_array_length(hdr.h->'blockers'),0)::int AS blocker_count,
         COALESCE(hdr.h->'blockers','[]'::jsonb) AS blockers,
         p.next_action,
         NULLIF(hdr.h->'next_action'->>'key','') AS next_action_code,
         NULLIF(hdr.h->'next_action'->>'label','') AS next_action_label,
         NULLIF(hdr.h->'next_action'->>'permission','') AS next_action_permission,
         p.canonical_href, p.last_activity_at, p.total_count
  FROM paged p
  LEFT JOIN LATERAL (
    SELECT public.license_case(p.license_id,'internal')->'header' AS h
  ) hdr ON true
  LEFT JOIN public.profiles pr ON pr.id = p.owner_user_id
  LEFT JOIN LATERAL (
    SELECT s.supervisor_id, s.supervisor_name, s.team
    FROM public.entity_supervision_assignments s
    WHERE p.entity_id IS NOT NULL AND s.entity_id = p.entity_id AND COALESCE(s.status,'active')='active'
    ORDER BY s.effective_from DESC NULLS LAST LIMIT 1
  ) sa ON true
  ORDER BY CASE p.priority WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'medium' THEN 3 ELSE 4 END,
           p.sla_due_at ASC NULLS LAST;
END $function$
;
CREATE OR REPLACE FUNCTION public.license_lifecycle_work_queue_counts()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r jsonb;
BEGIN
  SELECT COALESCE(jsonb_object_agg(k, c), '{}'::jsonb) INTO r
  FROM (
    SELECT q.work_kind AS k, count(*) AS c
    FROM public.license_lifecycle_work_queue(NULL, NULL, 0, 200) q
    GROUP BY q.work_kind
  ) s;
  RETURN r;
END $function$
;
CREATE OR REPLACE FUNCTION public.license_matter_prerequisites(_matter_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  m record; l record; cfg jsonb; ent uuid;
  out_b jsonb := '[]'::jsonb;
  v_notice record; v_reps int; v_late int;
  v_open_conditions int; v_overdue_conditions int; v_under_review int;
  v_href text; v_prereq text; v_uid uuid := auth.uid();
BEGIN
  SELECT * INTO m FROM public.license_lifecycle_matters WHERE id = _matter_id;
  IF m IS NULL THEN RETURN out_b; END IF;
  SELECT * INTO l FROM public.licenses WHERE id = m.license_id;
  cfg := public.license_lifecycle_config_resolve(m.license_id, m.matter_kind);
  SELECT id INTO ent FROM public.licensees WHERE license_id = l.id LIMIT 1;
  v_href := '/licenses/' || l.id || '?tab=adverse';

  SELECT count(*) FILTER (WHERE status IN ('open','in_progress','evidence_due')),
         count(*) FILTER (WHERE status IN ('open','in_progress','evidence_due') AND due_date < current_date),
         count(*) FILTER (WHERE status = 'under_review')
    INTO v_open_conditions, v_overdue_conditions, v_under_review
    FROM public.license_conditions WHERE license_id = l.id;

  SELECT * INTO v_notice FROM public.license_matter_notices
   WHERE matter_id = m.id AND notice_kind = 'proposed_action'
   ORDER BY issued_at DESC LIMIT 1;

  SELECT count(*), count(*) FILTER (WHERE is_late) INTO v_reps, v_late
    FROM public.license_matter_representations WHERE matter_id = m.id;

  IF m.matter_kind IN ('suspension','revocation') THEN
    IF COALESCE((cfg->>'notice_required')::boolean, true) AND v_notice.id IS NULL THEN
      out_b := out_b || jsonb_build_object('key','NOTICE_NOT_ISSUED',
        'label','Notice of proposed action has not been issued','href',v_href);
    END IF;
    IF COALESCE((cfg->>'notice_required')::boolean, true)
       AND v_notice.id IS NOT NULL
       AND COALESCE((cfg->>'representation_period_days')::int, 0) > 0
       AND m.stage IN ('NOTICE_OF_PROPOSED_ACTION','REPRESENTATION_WINDOW') THEN
      out_b := out_b || jsonb_build_object('key','REPRESENTATION_WINDOW_OPEN',
        'label','Representation period is still running (closes ' ||
                COALESCE(to_char(v_notice.representation_deadline,'DD Mon YYYY'),'n/a') || ')',
        'href',v_href);
    END IF;
    IF COALESCE((cfg->>'evidence_review_required')::boolean, true)
       AND m.stage NOT IN ('DECISION_READY','DECIDED','CLOSED') THEN
      out_b := out_b || jsonb_build_object('key','EVIDENCE_REVIEW_INCOMPLETE',
        'label','Evidence review has not been concluded','href',v_href);
    END IF;
  END IF;

  IF m.matter_kind = 'reinstatement' THEN
    IF m.stage NOT IN ('DECISION_READY','DECIDED','CLOSED') THEN
      out_b := out_b || jsonb_build_object('key','VERIFICATION_INCOMPLETE',
        'label','Reinstatement verification has not been completed','href',v_href);
    END IF;
    FOR v_prereq IN SELECT jsonb_array_elements_text(COALESCE(cfg->'reinstatement_prerequisites','[]'::jsonb)) LOOP
      IF v_prereq = 'conditions_satisfied' AND v_overdue_conditions > 0 THEN
        out_b := out_b || jsonb_build_object('key','CONDITIONS_NOT_SATISFIED',
          'label', v_overdue_conditions || ' overdue licence condition(s) outstanding',
          'href','/licenses/' || l.id || '?tab=conditions');
      ELSIF v_prereq = 'evidence_approved' AND v_under_review > 0 THEN
        out_b := out_b || jsonb_build_object('key','EVIDENCE_NOT_APPROVED',
          'label', v_under_review || ' condition(s) awaiting evidence review',
          'href','/licenses/' || l.id || '?tab=conditions');
      ELSIF v_prereq = 'obligations_resolved' AND ent IS NOT NULL
        AND EXISTS (SELECT 1 FROM public.return_filings rf
                     WHERE rf.entity_id = ent AND rf.status IN ('DRAFT','CORRECTION_REQUESTED')) THEN
        out_b := out_b || jsonb_build_object('key','UNRESOLVED_REPORTING',
          'label','Outstanding regulatory returns must be resolved','href','/returns/filings');
      ELSIF v_prereq = 'fee_settled' AND l.application_id IS NOT NULL
        AND EXISTS (SELECT 1 FROM public.payments p
                     WHERE p.application_id = l.application_id
                       AND COALESCE(p.status,'pending') NOT IN ('paid','completed','verified','waived')) THEN
        out_b := out_b || jsonb_build_object('key','OUTSTANDING_FEE',
          'label','Outstanding fee must be settled','href','/licenses/' || l.id);
      END IF;
    END LOOP;
  END IF;

  IF m.matter_kind = 'surrender' THEN
    IF m.stage NOT IN ('DECISION_READY','DECIDED','CLOSED') THEN
      out_b := out_b || jsonb_build_object('key','SURRENDER_REVIEW_INCOMPLETE',
        'label','Surrender review has not been concluded','href',v_href);
    END IF;
    FOR v_prereq IN SELECT jsonb_array_elements_text(COALESCE(cfg->'surrender_blockers','[]'::jsonb)) LOOP
      IF v_prereq = 'OPEN_CONDITIONS' AND v_open_conditions > 0 THEN
        out_b := out_b || jsonb_build_object('key','OPEN_CONDITIONS',
          'label', v_open_conditions || ' open condition(s) must be satisfied or waived',
          'href','/licenses/' || l.id || '?tab=conditions');
      ELSIF v_prereq = 'OPEN_ENFORCEMENT' AND ent IS NOT NULL
        AND EXISTS (SELECT 1 FROM public.enforcement_actions e
                     WHERE e.entity_id = ent AND COALESCE(e.status,'open') NOT IN ('closed','withdrawn')) THEN
        out_b := out_b || jsonb_build_object('key','OPEN_ENFORCEMENT',
          'label','Open enforcement case must be concluded','href','/enforcement/queue');
      ELSIF v_prereq = 'UNRESOLVED_REPORTING' AND ent IS NOT NULL
        AND EXISTS (SELECT 1 FROM public.return_filings rf
                     WHERE rf.entity_id = ent AND rf.status IN ('DRAFT','CORRECTION_REQUESTED')) THEN
        out_b := out_b || jsonb_build_object('key','UNRESOLVED_REPORTING',
          'label','Outstanding regulatory returns must be resolved','href','/returns/filings');
      ELSIF v_prereq = 'OUTSTANDING_FEE' AND l.application_id IS NOT NULL
        AND EXISTS (SELECT 1 FROM public.payments p
                     WHERE p.application_id = l.application_id
                       AND COALESCE(p.status,'pending') NOT IN ('paid','completed','verified','waived')) THEN
        out_b := out_b || jsonb_build_object('key','OUTSTANDING_FEE',
          'label','Outstanding fee must be settled','href','/licenses/' || l.id);
      END IF;
    END LOOP;
  END IF;

  IF m.matter_kind IN ('suspension','revocation','reinstatement','surrender','expiry') THEN
    IF NULLIF(cfg->>'decision_authority','') IS NOT NULL
       AND NOT public.is_super_admin(v_uid)
       AND NOT EXISTS (SELECT 1 FROM public.user_roles ur
                        WHERE ur.user_id = v_uid AND ur.role::text = cfg->>'decision_authority') THEN
      out_b := out_b || jsonb_build_object('key','DECISION_AUTHORITY',
        'label','Decision authority required: ' || (cfg->>'decision_authority'),'href',v_href);
    END IF;
    IF COALESCE((cfg->>'maker_checker_required')::boolean,false)
       AND m.opened_by IS NOT NULL AND m.opened_by = v_uid AND NOT public.is_super_admin(v_uid) THEN
      out_b := out_b || jsonb_build_object('key','MAKER_CHECKER',
        'label','A second officer must take the decision (maker/checker)','href',v_href);
    END IF;
    IF COALESCE((cfg->>'legal_basis_required')::boolean,true)
       AND btrim(COALESCE(m.legal_basis, v_notice.legal_basis, '')) = '' THEN
      out_b := out_b || jsonb_build_object('key','LEGAL_BASIS',
        'label','Legal basis must be recorded for this decision','href',v_href);
    END IF;
  END IF;

  RETURN out_b;
END $function$
;
CREATE OR REPLACE FUNCTION public.license_recipients_for_holder(_license_id uuid)
 RETURNS TABLE(user_id uuid, email text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH lic AS (
    SELECT id, holder_id FROM public.licenses WHERE id = _license_id
  ),
  -- Direct holder profile
  holder AS (
    SELECT p.id AS user_id, p.email
    FROM lic JOIN public.profiles p ON p.id = lic.holder_id
  ),
  -- If holder is a licensee record, find its primary users
  licensee_users AS (
    SELECT p.id AS user_id, p.email
    FROM lic
    JOIN public.licensees l ON l.id = lic.holder_id
    JOIN public.profiles p ON p.licensee_id = l.id AND p.user_type = 'primary'
  )
  SELECT user_id, email FROM holder
  UNION
  SELECT user_id, email FROM licensee_users;
$function$
;
CREATE OR REPLACE FUNCTION public.license_register_page(_search text DEFAULT NULL::text, _status text DEFAULT NULL::text, _sector_id uuid DEFAULT NULL::uuid, _sla_state text DEFAULT NULL::text, _page integer DEFAULT 0, _page_size integer DEFAULT 25, _sort_by text DEFAULT 'valid_until'::text, _sort_dir text DEFAULT 'asc'::text)
 RETURNS TABLE(license_id uuid, license_number text, entity_id uuid, entity_name text, license_type text, status text, issued_at timestamp with time zone, valid_from timestamp with time zone, valid_until timestamp with time zone, sla_state text, days_to_expiry numeric, open_conditions integer, overdue_conditions integer, open_matter_kind text, next_action text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_internal boolean; v_off int;
BEGIN
  v_internal := public.is_super_admin(auth.uid()) OR public.has_permission(auth.uid(),'license_management','view');
  _page_size := LEAST(GREATEST(COALESCE(_page_size,25),1),200);
  v_off := GREATEST(COALESCE(_page,0),0) * _page_size;

  RETURN QUERY
  WITH base AS (
    SELECT l.*, le.id AS ent_id, le.name AS ent_name,
      CASE WHEN l.valid_until IS NULL THEN NULL ELSE EXTRACT(EPOCH FROM (l.valid_until - now()))/86400 END AS d2e,
      COALESCE((public.license_lifecycle_policy(l.sector_id,l.sub_sector_id,l.category_id)->>'renewal_window_days')::int, 90) AS win
    FROM public.licenses l
    LEFT JOIN public.licensees le ON le.license_id = l.id
    WHERE (v_internal OR l.holder_id = auth.uid())
      AND (_status IS NULL OR l.status = _status)
      AND (_sector_id IS NULL OR l.sector_id = _sector_id)
      AND (_search IS NULL OR _search = '' OR l.license_number ILIKE '%'||_search||'%' OR COALESCE(le.name,'') ILIKE '%'||_search||'%' OR COALESCE(l.license_type,'') ILIKE '%'||_search||'%')
  ), scored AS (
    SELECT b.*,
      CASE WHEN b.status IN ('revoked','surrendered') THEN 'closed'
           WHEN b.d2e IS NULL THEN 'on_track'
           WHEN b.d2e < 0 THEN 'breached'
           WHEN b.d2e <= b.win THEN 'due_soon'
           ELSE 'on_track' END AS sla,
      (SELECT count(*)::int FROM public.license_conditions c WHERE c.license_id = b.id AND c.status IN ('open','in_progress')) AS oc,
      (SELECT count(*)::int FROM public.license_conditions c WHERE c.license_id = b.id AND c.status IN ('open','in_progress') AND c.due_date < current_date) AS ovc,
      (SELECT m.matter_kind FROM public.license_lifecycle_matters m WHERE m.license_id = b.id AND m.status = 'open' ORDER BY m.opened_at LIMIT 1) AS mk
    FROM base b
  ), filtered AS (
    SELECT * FROM scored WHERE (_sla_state IS NULL OR sla = _sla_state)
  )
  SELECT f.id, f.license_number, f.ent_id, COALESCE(f.ent_name, f.license_type),
         f.license_type, f.status, f.issued_at, f.valid_from, f.valid_until,
         f.sla, f.d2e, f.oc, f.ovc, f.mk,
         CASE
           WHEN f.status IN ('revoked','surrendered') THEN NULL
           WHEN f.mk IS NOT NULL THEN 'Progress ' || replace(f.mk,'_',' ')
           WHEN f.sla = 'breached' THEN 'Complete expiry review'
           WHEN f.sla = 'due_soon' THEN 'Start renewal'
           WHEN f.ovc > 0 THEN 'Review overdue conditions'
           ELSE NULL END,
         count(*) OVER ()
  FROM filtered f
  ORDER BY
    CASE WHEN _sort_dir = 'desc' THEN NULL ELSE
      CASE _sort_by WHEN 'license_number' THEN f.license_number WHEN 'status' THEN f.status ELSE NULL END END ASC,
    CASE WHEN _sort_dir = 'desc' THEN
      CASE _sort_by WHEN 'license_number' THEN f.license_number WHEN 'status' THEN f.status ELSE NULL END END DESC,
    CASE WHEN _sort_by = 'valid_until' AND _sort_dir <> 'desc' THEN f.valid_until END ASC NULLS LAST,
    CASE WHEN _sort_by = 'valid_until' AND _sort_dir = 'desc' THEN f.valid_until END DESC NULLS LAST,
    f.issued_at DESC
  LIMIT _page_size OFFSET v_off;
END $function$
;
CREATE OR REPLACE FUNCTION public.license_related_cases(_license_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); l record;
BEGIN
  IF uid IS NULL OR NOT public.is_internal_staff_user(uid) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT * INTO l FROM public.licenses WHERE id = _license_id;
  IF l IS NULL THEN RAISE EXCEPTION 'LICENSE_NOT_FOUND' USING ERRCODE='22023'; END IF;

  RETURN jsonb_build_object(
    'originating_application', (
      SELECT jsonb_build_object('id', a.id, 'status', a.status, 'created_at', a.created_at,
                                'href', '/applications/' || a.id)
        FROM public.applications a WHERE a.id = l.application_id),
    'lifecycle_matters', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', m.id, 'matter_kind', m.matter_kind,
              'stage', m.stage, 'status', m.status, 'source_kind', m.source_kind,
              'created_at', m.created_at) ORDER BY m.created_at DESC), '[]'::jsonb)
        FROM public.license_lifecycle_matters m WHERE m.license_id = l.id),
    'conditions', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', c.id, 'status', c.status,
              'description', LEFT(COALESCE(c.description,''), 160)) ORDER BY c.created_at DESC), '[]'::jsonb)
        FROM public.license_conditions c WHERE c.license_id = l.id),
    'fp_roles', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', r.id, 'person_id', r.person_id,
              'href', '/fpa/individuals/' || r.person_id) ORDER BY r.created_at DESC), '[]'::jsonb)
        FROM public.fp_individual_roles r WHERE r.license_id = l.id),
    'fp_appeals', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', ap.id, 'status', ap.status) ORDER BY ap.created_at DESC), '[]'::jsonb)
        FROM public.fp_appeals ap WHERE ap.license_id = l.id),
    'supervisory_plans', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', sp.id, 'status', sp.status) ORDER BY sp.created_at DESC), '[]'::jsonb)
        FROM public.supervisory_plans sp WHERE sp.license_id = l.id),
    'enforcement', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', e.id, 'case_number', e.case_number,
              'status', e.status, 'href', '/enforcement/' || e.id) ORDER BY e.created_at DESC), '[]'::jsonb)
        FROM public.enforcement_actions e
       WHERE e.source_type = 'license' AND e.source_id = l.id),
    'decision_appeals', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', da.id, 'status', da.status) ORDER BY da.created_at DESC), '[]'::jsonb)
        FROM public.license_decision_appeals da
        JOIN public.license_decisions d ON d.id = da.decision_id
       WHERE d.license_id = l.id),
    'correspondence', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', t.id, 'subject', t.subject,
              'status', t.status, 'thread_type', t.thread_type, 'created_at', t.created_at,
              'href', '/correspondence/' || t.id) ORDER BY t.created_at DESC), '[]'::jsonb)
        FROM public.correspondence_threads t
       WHERE t.source_type = 'license' AND t.source_id = l.id));
END $function$
;
CREATE OR REPLACE FUNCTION public.license_variation_case(_license_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'variation', to_jsonb(v),
           'items', COALESCE((SELECT jsonb_agg(to_jsonb(i) ORDER BY i.created_at)
                                FROM public.license_variation_items i WHERE i.variation_id = v.id), '[]'::jsonb)
         ) ORDER BY v.requested_at DESC), '[]'::jsonb)
    FROM public.license_variations v
   WHERE v.license_id = _license_id AND public.is_internal_staff_user(auth.uid());
$function$
;
CREATE OR REPLACE FUNCTION public.license_variation_operation(_operation text, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); l record; v record; it jsonb; v_id uuid; v_ref text; v_dec uuid; v_matter uuid;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;

  IF _operation = 'open' THEN
    IF NOT (public.is_super_admin(uid) OR public.has_permission(uid,'license_management','workflow_action')) THEN
      RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
    SELECT * INTO l FROM public.licenses WHERE id = (_payload->>'license_id')::uuid;
    IF l IS NULL THEN RAISE EXCEPTION 'LICENSE_NOT_FOUND' USING ERRCODE='22023'; END IF;
    IF l.status <> 'active' THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023',
      DETAIL='Only an active licence can be varied.'; END IF;
    IF NULLIF(btrim(COALESCE(_payload->>'variation_type','')),'') IS NULL THEN
      RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023', DETAIL='Variation type is required.'; END IF;
    IF NULLIF(btrim(COALESCE(_payload->>'rationale','')),'') IS NULL THEN
      RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023', DETAIL='A rationale is required.'; END IF;
    IF jsonb_typeof(COALESCE(_payload->'items','[]'::jsonb)) <> 'array'
       OR jsonb_array_length(COALESCE(_payload->'items','[]'::jsonb)) = 0 THEN
      RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023',
        DETAIL='At least one requested change must be itemised.'; END IF;

    v_ref := 'VAR-' || to_char(now(),'YYYY') || '-' || lpad((
      (SELECT count(*) + 1 FROM public.license_variations
        WHERE requested_at >= date_trunc('year', now())))::text, 5, '0');

    INSERT INTO public.license_lifecycle_matters(license_id, matter_kind, title, reason, opened_by,
      waiting_on, stage, source_kind, source_reference, metadata)
    VALUES (l.id, 'variation', 'Variation — ' || (_payload->>'variation_type'),
            _payload->>'rationale', uid, 'regulator', 'ASSESSMENT', 'regulator_initiated', v_ref,
            jsonb_build_object('variation_reference', v_ref))
    RETURNING id INTO v_matter;

    INSERT INTO public.license_variations(license_id, matter_id, application_id, variation_reference,
      variation_type, status, rationale, requested_by, metadata)
    VALUES (l.id, v_matter, NULLIF(_payload->>'application_id','')::uuid, v_ref,
            _payload->>'variation_type', 'under_assessment', _payload->>'rationale', uid,
            COALESCE(_payload->'metadata','{}'::jsonb))
    RETURNING id INTO v_id;

    FOR it IN SELECT value FROM jsonb_array_elements(_payload->'items') LOOP
      IF NULLIF(btrim(COALESCE(it->>'requested_value','')),'') IS NULL THEN
        RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023',
          DETAIL='Every itemised change needs a requested value.'; END IF;
      INSERT INTO public.license_variation_items(variation_id, field_key, label, current_value,
        requested_value, requires_assessment)
      VALUES (v_id, COALESCE(it->>'field_key','change'), COALESCE(it->>'label', it->>'field_key','Change'),
              it->>'current_value', it->>'requested_value',
              COALESCE((it->>'requires_assessment')::boolean, true));
    END LOOP;

    INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
    VALUES (uid, 'license_variation_open', 'license_variation', v_id,
            jsonb_build_object('license_id', l.id, 'reference', v_ref));
    RETURN jsonb_build_object('variation_id', v_id, 'matter_id', v_matter, 'reference', v_ref);

  ELSIF _operation = 'decide' THEN
    IF NOT (public.is_super_admin(uid) OR public.has_permission(uid,'license_management','approve')) THEN
      RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
    SELECT * INTO v FROM public.license_variations WHERE id = (_payload->>'variation_id')::uuid;
    IF v IS NULL THEN RAISE EXCEPTION 'VARIATION_NOT_FOUND' USING ERRCODE='22023'; END IF;
    IF v.status NOT IN ('requested','under_assessment') THEN
      RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023', DETAIL='This variation is already decided.'; END IF;
    IF COALESCE(_payload->>'decision','') NOT IN ('approved','refused','withdrawn') THEN
      RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023', DETAIL='A valid decision is required.'; END IF;
    IF NULLIF(btrim(COALESCE(_payload->>'rationale','')),'') IS NULL THEN
      RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023', DETAIL='A written decision rationale is required.'; END IF;
    IF v.requested_by = uid AND NOT public.is_super_admin(uid) THEN
      RAISE EXCEPTION 'MAKER_CHECKER' USING ERRCODE='42501',
        DETAIL='The officer who opened the variation cannot decide it.'; END IF;
    IF jsonb_array_length(public.license_lifecycle_gates(v.license_id, v.matter_id)) > 0
       AND (_payload->>'decision') = 'approved' THEN
      RAISE EXCEPTION 'BLOCKED' USING ERRCODE='22023',
        DETAIL='Outstanding fees or incomplete verification block approval of this variation.'; END IF;

    INSERT INTO public.license_decisions(matter_id, license_id, entity_id, decision_type, decision,
      authority, actor_id, maker_id, checker_id, effective_date, rationale, legal_basis, appealable,
      appeal_deadline, metadata)
    SELECT v.matter_id, v.license_id, e.entity_id, 'variation', _payload->>'decision',
           COALESCE(_payload->>'authority','delegated_officer'), uid, v.requested_by, uid,
           COALESCE(NULLIF(_payload->>'effective_date','')::date, current_date),
           _payload->>'rationale', _payload->>'legal_basis', true,
           COALESCE(NULLIF(_payload->>'effective_date','')::date, current_date) + 30,
           jsonb_build_object('variation_id', v.id, 'variation_reference', v.variation_reference)
      FROM (SELECT a.entity_id FROM public.applications a WHERE a.id = (SELECT application_id FROM public.licenses WHERE id = v.license_id)) e
    RETURNING id INTO v_dec;

    UPDATE public.license_variation_items
       SET approved_value = CASE WHEN (_payload->>'decision') = 'approved' THEN requested_value ELSE NULL END
     WHERE variation_id = v.id;

    UPDATE public.license_variations
       SET status = _payload->>'decision', decision = _payload->>'decision', decision_id = v_dec,
           decided_by = uid, decided_at = now(),
           effective_date = COALESCE(NULLIF(_payload->>'effective_date','')::date, current_date),
           updated_at = now()
     WHERE id = v.id;

    UPDATE public.license_lifecycle_matters
       SET status='closed', closed_at=now(), closed_by=uid, decision=_payload->>'decision',
           decision_id=v_dec, stage='CLOSED', updated_at=now()
     WHERE id = v.matter_id;

    INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
    VALUES (uid, 'license_variation_decide', 'license_variation', v.id,
            jsonb_build_object('decision', _payload->>'decision', 'decision_id', v_dec));
    RETURN jsonb_build_object('variation_id', v.id, 'decision_id', v_dec);
  END IF;
  RAISE EXCEPTION 'UNKNOWN_OPERATION' USING ERRCODE='22023';
END $function$
;
CREATE OR REPLACE FUNCTION public.license_verification_case_view(_license_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'case', to_jsonb(c),
           'items', COALESCE((SELECT jsonb_agg(to_jsonb(i) ORDER BY i.created_at)
                                FROM public.license_verification_items i WHERE i.case_id = c.id), '[]'::jsonb)
         ) ORDER BY c.started_at DESC), '[]'::jsonb)
    FROM public.license_verification_cases c
   WHERE c.license_id = _license_id AND public.is_internal_staff_user(auth.uid());
$function$
;
CREATE OR REPLACE FUNCTION public.license_verification_operation(_operation text, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); l record; tpl record; c record; it jsonb; v_case_id uuid; v_item record; v_tpl_id uuid;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF NOT (public.is_super_admin(uid) OR public.has_permission(uid,'license_management','workflow_action')) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;

  IF _operation = 'start' THEN
    SELECT * INTO l FROM public.licenses WHERE id = (_payload->>'license_id')::uuid;
    IF l IS NULL THEN RAISE EXCEPTION 'LICENSE_NOT_FOUND' USING ERRCODE='22023'; END IF;
    IF EXISTS (SELECT 1 FROM public.license_verification_cases
                WHERE license_id=l.id AND matter_id IS NOT DISTINCT FROM NULLIF(_payload->>'matter_id','')::uuid
                  AND status='in_progress') THEN
      RAISE EXCEPTION 'ALREADY_OPEN' USING ERRCODE='22023', DETAIL='A verification case is already open.'; END IF;
    v_tpl_id := public.license_verification_template_resolve(l.id, _payload->>'matter_kind');
    IF v_tpl_id IS NULL THEN RAISE EXCEPTION 'NO_TEMPLATE' USING ERRCODE='22023',
      DETAIL='No active verification template is configured for this licence and matter kind.'; END IF;
    SELECT * INTO tpl FROM public.license_verification_templates WHERE id = v_tpl_id;
    INSERT INTO public.license_verification_cases(license_id, matter_id, matter_kind, template_id,
      template_key, template_version, template_snapshot, started_by)
    VALUES (l.id, NULLIF(_payload->>'matter_id','')::uuid, _payload->>'matter_kind', tpl.id,
      tpl.template_key, tpl.version, to_jsonb(tpl), uid)
    RETURNING id INTO v_case_id;
    FOR it IN SELECT value FROM jsonb_array_elements(tpl.items) LOOP
      INSERT INTO public.license_verification_items(case_id, item_key, label, required)
      VALUES (v_case_id, it->>'key', COALESCE(it->>'label', it->>'key'), COALESCE((it->>'required')::boolean, true));
    END LOOP;
    INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
    VALUES (uid, 'license_verification_start', 'license_verification_case', v_case_id,
            jsonb_build_object('license_id', l.id, 'matter_kind', _payload->>'matter_kind',
                               'template_key', tpl.template_key, 'template_version', tpl.version));
    RETURN jsonb_build_object('case_id', v_case_id, 'template_key', tpl.template_key, 'template_version', tpl.version);

  ELSIF _operation = 'record_item' THEN
    SELECT * INTO v_item FROM public.license_verification_items WHERE id = (_payload->>'item_id')::uuid;
    IF v_item IS NULL THEN RAISE EXCEPTION 'ITEM_NOT_FOUND' USING ERRCODE='22023'; END IF;
    IF COALESCE(_payload->>'result','') NOT IN ('satisfied','not_satisfied','not_applicable') THEN
      RAISE EXCEPTION 'FIELD_REQUIRED' USING ERRCODE='22023', DETAIL='A valid verification result is required.'; END IF;
    UPDATE public.license_verification_items
       SET result = _payload->>'result', note = _payload->>'note',
           evidence_document_id = NULLIF(_payload->>'evidence_document_id','')::uuid,
           recorded_by = uid, recorded_at = now()
     WHERE id = v_item.id;
    RETURN jsonb_build_object('ok', true);

  ELSIF _operation = 'complete' THEN
    SELECT * INTO c FROM public.license_verification_cases WHERE id = (_payload->>'case_id')::uuid;
    IF c IS NULL THEN RAISE EXCEPTION 'CASE_NOT_FOUND' USING ERRCODE='22023'; END IF;
    IF c.status <> 'in_progress' THEN RAISE EXCEPTION 'INVALID_FROM_STATE' USING ERRCODE='22023'; END IF;
    IF EXISTS (SELECT 1 FROM public.license_verification_items
                WHERE case_id=c.id AND required AND result IS NULL) THEN
      RAISE EXCEPTION 'INCOMPLETE' USING ERRCODE='22023',
        DETAIL='All required verification items must be recorded before completion.'; END IF;
    UPDATE public.license_verification_cases
       SET status='completed', completed_by=uid, completed_at=now(), updated_at=now(),
           outcome = CASE WHEN EXISTS (SELECT 1 FROM public.license_verification_items
                                        WHERE case_id=c.id AND result='not_satisfied')
                          THEN 'deficiencies_identified' ELSE 'satisfied' END
     WHERE id=c.id;
    INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, metadata)
    VALUES (uid, 'license_verification_complete', 'license_verification_case', c.id,
            jsonb_build_object('license_id', c.license_id));
    RETURN jsonb_build_object('ok', true);
  END IF;
  RAISE EXCEPTION 'UNKNOWN_OPERATION' USING ERRCODE='22023';
END $function$
;
CREATE OR REPLACE FUNCTION public.license_verification_template_resolve(_license_id uuid, _matter_kind text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE l record; v_cert boolean; v_purpose text; v_id uuid;
BEGIN
  SELECT * INTO l FROM public.licenses WHERE id = _license_id;
  IF l IS NULL THEN RETURN NULL; END IF;
  v_cert := COALESCE(l.license_number LIKE 'CERT-%', false);
  v_purpose := CASE WHEN v_cert THEN 'CERTIFICATION' ELSE 'PRODUCTION' END;

  SELECT t.id INTO v_id
    FROM public.license_verification_templates t
   WHERE t.is_active
     AND t.purpose = v_purpose
     AND t.matter_kind = _matter_kind
     AND t.superseded_by IS NULL
     AND t.effective_from <= current_date
     AND (t.effective_to IS NULL OR t.effective_to >= current_date)
     AND (t.license_type IS NULL OR t.license_type = l.license_type)
     AND (t.sector_id    IS NULL OR t.sector_id    = l.sector_id)
     AND (t.regulator_id IS NULL OR t.regulator_id = l.regulator_id)
   ORDER BY (CASE WHEN t.license_type IS NOT NULL THEN 4 ELSE 0 END
           + CASE WHEN t.sector_id    IS NOT NULL THEN 2 ELSE 0 END
           + CASE WHEN t.regulator_id IS NOT NULL THEN 1 ELSE 0 END) DESC,
            t.version DESC, t.created_at
   LIMIT 1;
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.licensee_entity_domain_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_domain text;
BEGIN
  IF NEW.lifecycle_stage_id IS NOT NULL THEN
    SELECT domain INTO v_domain FROM public.lifecycle_stages WHERE id = NEW.lifecycle_stage_id;
    IF v_domain IS DISTINCT FROM 'entity' THEN
      RAISE EXCEPTION 'Entity lifecycle stage must belong to the entity domain (got %)', COALESCE(v_domain,'unknown')
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.licensee_group_membership(_licensee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_gid uuid; v_row jsonb;
BEGIN
  SELECT group_id INTO v_gid FROM public.financial_group_members WHERE licensee_id = _licensee_id LIMIT 1;
  IF v_gid IS NULL THEN RETURN jsonb_build_object('is_member', false); END IF;
  IF NOT public.can_read_financial_group(auth.uid(), v_gid) THEN
    RETURN jsonb_build_object('is_member', true, 'authorised', false, 'group_id', v_gid);
  END IF;
  SELECT jsonb_build_object(
      'is_member', true, 'authorised', true, 'group_id', v_gid,
      'group_code', g.group_code, 'group_name', g.name,
      'member_role', m.member_role, 'ownership_percentage', m.ownership_percentage,
      'consolidation_treatment', m.consolidation_treatment)
    INTO v_row
  FROM public.financial_group_members m JOIN public.financial_groups g ON g.id = m.group_id
  WHERE m.licensee_id = _licensee_id AND m.group_id = v_gid;
  RETURN v_row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.licensee_ids_for_license(_license_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT id FROM public.licensees WHERE license_id = _license_id
$function$
;
CREATE OR REPLACE FUNCTION public.licensing_audit_record_determination(_entity_id uuid, _verdict text, _rationale text, _effective_date date DEFAULT CURRENT_DATE, _risk_rating_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _row record;
BEGIN
  PERFORM public.enforce_permission('license_management','approve');
  IF _rationale IS NULL OR length(btrim(_rationale)) < 10 THEN
    RAISE EXCEPTION 'rationale must be at least 10 characters' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.licensing_audit_determinations (entity_id, verdict, rationale, effective_date, risk_rating_id, issued_by)
  VALUES (_entity_id, _verdict, btrim(_rationale), COALESCE(_effective_date,CURRENT_DATE), _risk_rating_id, _uid)
  RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'licensing_audit.determination.recorded','licensing_audit_determination',_row.id,
          jsonb_build_object('entity_id',_entity_id,'after',to_jsonb(_row),'justification',btrim(_rationale)));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.licensing_audit_record_risk_profile(_entity_id uuid, _profile_score integer, _tier text, _key_drivers jsonb DEFAULT '[]'::jsonb, _snapshot jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _row record;
BEGIN
  PERFORM public.enforce_permission('license_management','edit');
  INSERT INTO public.licensing_audit_risk_profiles (entity_id, profile_score, tier, key_drivers, snapshot, generated_by)
  VALUES (_entity_id, _profile_score, _tier, COALESCE(_key_drivers,'[]'::jsonb), COALESCE(_snapshot,'{}'::jsonb), _uid)
  RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'licensing_audit.risk_profile.recorded','licensing_audit_risk_profile',_row.id,
          jsonb_build_object('entity_id',_entity_id,'after',to_jsonb(_row)));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.licensing_default_sla_hours()
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE lower(sla_unit)
           WHEN 'hours' THEN sla_duration::numeric
           WHEN 'days' THEN sla_duration::numeric * 24
           WHEN 'weeks' THEN sla_duration::numeric * 24 * 7
           ELSE sla_duration::numeric
         END
    FROM sla_configurations
   WHERE active AND process_type IN ('licensing', 'application', 'pre_application')
   ORDER BY CASE process_type WHEN 'licensing' THEN 0 WHEN 'application' THEN 1 ELSE 2 END
   LIMIT 1;
$function$
;
CREATE OR REPLACE FUNCTION public.link_complaint_licensee(_complaint_id uuid, _licensee_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  v_old uuid;
  v_name text;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501'; END IF;
  IF NOT (public.has_complaint_perm(actor, 'triage') OR public.has_complaint_perm(actor, 'escalate') OR public.has_complaint_perm(actor, 'assign')) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;
  IF _licensee_id IS NULL THEN RAISE EXCEPTION 'Licensee is required'; END IF;
  SELECT name INTO v_name FROM public.licensees WHERE id = _licensee_id;
  IF v_name IS NULL THEN RAISE EXCEPTION 'Licensee not found'; END IF;

  SELECT licensee_id INTO v_old FROM public.complaints WHERE id = _complaint_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Complaint not found'; END IF;

  UPDATE public.complaints
     SET licensee_id = _licensee_id,
         updated_at = now()
   WHERE id = _complaint_id;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value)
  VALUES (actor, 'licensee_linked', 'complaint', _complaint_id,
          jsonb_build_object('licensee_id', v_old),
          jsonb_build_object('licensee_id', _licensee_id, 'licensee_name', v_name));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_complaint_assignment_teams(_regulator_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(team text, complaint_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT assigned_team AS team, count(*)::bigint AS complaint_count
    FROM public.complaints
   WHERE assigned_team IS NOT NULL
     AND btrim(assigned_team) <> ''
     AND (_regulator_id IS NULL OR regulator_id = _regulator_id)
   GROUP BY assigned_team
   ORDER BY assigned_team;
$function$
;
CREATE OR REPLACE FUNCTION public.list_complaints(_filters jsonb DEFAULT '{}'::jsonb, _sort text DEFAULT 'created_at.desc'::text, _page integer DEFAULT 1, _page_size integer DEFAULT 25, _search text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_offset int; v_limit int; v_sort_col text; v_sort_dir text;
  v_total bigint; v_rows jsonb; v_is_internal boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  v_is_internal := public.has_complaint_perm(v_uid,'view_all') OR public.has_complaint_perm(v_uid,'triage');
  v_limit := LEAST(GREATEST(COALESCE(_page_size,25),1),200);
  v_offset := GREATEST((COALESCE(_page,1)-1)*v_limit, 0);
  v_sort_col := split_part(_sort,'.',1);
  v_sort_dir := LOWER(COALESCE(NULLIF(split_part(_sort,'.',2),''),'desc'));
  IF v_sort_col NOT IN ('created_at','updated_at','severity','status','sla_due_at','complaint_number','priority') THEN
    v_sort_col := 'created_at';
  END IF;
  IF v_sort_dir NOT IN ('asc','desc') THEN v_sort_dir := 'desc'; END IF;

  WITH filtered AS (
    SELECT c.* FROM public.complaints c
     WHERE (v_is_internal OR c.complainant_id = v_uid)
       AND (NULLIF(_filters->>'status','') IS NULL
            OR (_filters->>'status'='open' AND c.status IN ('submitted','under_investigation'))
            OR c.status = _filters->>'status')
       AND (NULLIF(_filters->>'severity','') IS NULL OR c.severity = _filters->>'severity')
       AND (NULLIF(_filters->>'priority','') IS NULL OR c.priority = _filters->>'priority')
       AND (NULLIF(_filters->>'complaint_type_id','') IS NULL OR c.complaint_type_id = (_filters->>'complaint_type_id')::uuid)
       AND (NULLIF(_filters->>'product_id','') IS NULL OR c.product_id = (_filters->>'product_id')::uuid)
       AND (NULLIF(_filters->>'channel_id','') IS NULL OR c.channel_id = (_filters->>'channel_id')::uuid)
       AND (NULLIF(_filters->>'conduct_risk_category_id','') IS NULL OR c.conduct_risk_category_id = (_filters->>'conduct_risk_category_id')::uuid)
       AND (NULLIF(_filters->>'assigned_team','') IS NULL OR c.assigned_team = _filters->>'assigned_team')
       AND (NULLIF(_filters->>'intake_source','') IS NULL OR c.intake_source = _filters->>'intake_source')
       AND (NULLIF(_filters->>'triage_override_status','') IS NULL OR c.triage_override_status = _filters->>'triage_override_status')
       AND (NULLIF(_filters->>'vulnerability_indicator','') IS NULL OR c.vulnerability_indicator = (_filters->>'vulnerability_indicator')::boolean)
       AND (NULLIF(_filters->>'licensee_id','') IS NULL OR c.licensee_id = (_filters->>'licensee_id')::uuid)
       AND (NULLIF(_filters->>'regulator_id','') IS NULL OR c.regulator_id = (_filters->>'regulator_id')::uuid)
       AND (NULLIF(_filters->>'date_from','') IS NULL OR c.created_at >= (_filters->>'date_from')::timestamptz)
       AND (NULLIF(_filters->>'date_to','')   IS NULL OR c.created_at <= (_filters->>'date_to')::timestamptz)
       AND (NULLIF(_filters->>'sla','') IS NULL
            OR public.complaint_sla_status(c.created_at,c.sla_due_at,c.sla_days,c.resolved_at) = _filters->>'sla')
       AND (NULLIF(_search,'') IS NULL
            OR c.complaint_number ILIKE '%'||_search||'%'
            OR c.subject ILIKE '%'||_search||'%'
            OR c.description ILIKE '%'||_search||'%'
            OR COALESCE(c.email,'') ILIKE '%'||_search||'%')
  ), paged AS (
    SELECT f.*, public.complaint_sla_status(f.created_at,f.sla_due_at,f.sla_days,f.resolved_at) AS sla_status
      FROM filtered f
     ORDER BY
       CASE WHEN v_sort_col='created_at' AND v_sort_dir='asc'  THEN f.created_at END ASC NULLS LAST,
       CASE WHEN v_sort_col='created_at' AND v_sort_dir='desc' THEN f.created_at END DESC NULLS LAST,
       CASE WHEN v_sort_col='updated_at' AND v_sort_dir='asc'  THEN f.updated_at END ASC NULLS LAST,
       CASE WHEN v_sort_col='updated_at' AND v_sort_dir='desc' THEN f.updated_at END DESC NULLS LAST,
       CASE WHEN v_sort_col='severity'   AND v_sort_dir='asc'  THEN f.severity   END ASC NULLS LAST,
       CASE WHEN v_sort_col='severity'   AND v_sort_dir='desc' THEN f.severity   END DESC NULLS LAST,
       CASE WHEN v_sort_col='status'     AND v_sort_dir='asc'  THEN f.status     END ASC NULLS LAST,
       CASE WHEN v_sort_col='status'     AND v_sort_dir='desc' THEN f.status     END DESC NULLS LAST,
       CASE WHEN v_sort_col='sla_due_at' AND v_sort_dir='asc'  THEN f.sla_due_at END ASC NULLS LAST,
       CASE WHEN v_sort_col='sla_due_at' AND v_sort_dir='desc' THEN f.sla_due_at END DESC NULLS LAST,
       CASE WHEN v_sort_col='complaint_number' AND v_sort_dir='asc'  THEN f.complaint_number END ASC NULLS LAST,
       CASE WHEN v_sort_col='complaint_number' AND v_sort_dir='desc' THEN f.complaint_number END DESC NULLS LAST,
       CASE WHEN v_sort_col='priority'   AND v_sort_dir='asc'  THEN f.priority END ASC NULLS LAST,
       CASE WHEN v_sort_col='priority'   AND v_sort_dir='desc' THEN f.priority END DESC NULLS LAST
     LIMIT v_limit OFFSET v_offset
  )
  SELECT (SELECT count(*) FROM filtered), COALESCE(jsonb_agg(to_jsonb(p.*)), '[]'::jsonb)
    INTO v_total, v_rows FROM paged p;

  RETURN jsonb_build_object('total',v_total,'page',GREATEST(_page,1),'page_size',v_limit,'rows',v_rows);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_duplicate_clusters(_dimension text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_rows jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF NOT (public.has_complaint_perm(v_uid,'triage') OR public.has_complaint_perm(v_uid,'view_all')) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(jsonb_agg(to_jsonb(c.*) ORDER BY array_length(c.member_ids,1) DESC NULLS LAST), '[]'::jsonb)
    INTO v_rows FROM public.complaint_duplicate_clusters c
   WHERE _dimension IS NULL OR c.dimension = _dimension;
  RETURN v_rows;
END; $function$
;
CREATE OR REPLACE FUNCTION public.list_fp_assessments(_filters jsonb DEFAULT '{}'::jsonb, _sort text DEFAULT 'created_at.desc'::text, _page integer DEFAULT 1, _page_size integer DEFAULT 25, _search text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_offset int; v_limit int; v_sort_col text; v_sort_dir text;
  v_total bigint; v_rows jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;

  v_limit := LEAST(GREATEST(COALESCE(_page_size,25),1),200);
  v_offset := GREATEST((COALESCE(_page,1)-1)*v_limit, 0);
  v_sort_col := split_part(_sort,'.',1);
  v_sort_dir := LOWER(COALESCE(NULLIF(split_part(_sort,'.',2),''),'desc'));
  IF v_sort_col NOT IN ('created_at','status','assessment_type','last_activity_at') THEN
    v_sort_col := 'created_at';
  END IF;
  IF v_sort_dir NOT IN ('asc','desc') THEN v_sort_dir := 'desc'; END IF;

  WITH scoped AS (
    SELECT
      a.id, a.individual_id, a.assessment_type, a.status, a.regulator_id,
      a.committee_id, a.created_at, a.submitted_at, a.determined_at, a.closed_at,
      GREATEST(a.created_at, COALESCE(a.submitted_at, a.created_at), COALESCE(a.determined_at, a.created_at), COALESCE(a.closed_at, a.created_at)) AS last_activity_at,
      i.full_name AS individual_name,
      i.national_id AS individual_national_id,
      r.name AS regulator_name
    FROM public.fp_assessments a
    JOIN public.fp_individuals i ON i.id = a.individual_id
    LEFT JOIN public.regulators r ON r.id = a.regulator_id
    WHERE public.can_read_fp_assessment(v_uid, a.id)
  ), filtered AS (
    SELECT * FROM scoped s
     WHERE (NULLIF(_filters->>'status','') IS NULL
            OR (_filters->>'status'='open' AND s.status IN ('draft','submitted','screening','awaiting_committee'))
            OR s.status = _filters->>'status')
       AND (NULLIF(_filters->>'assessment_type','') IS NULL OR s.assessment_type = _filters->>'assessment_type')
       AND (NULLIF(_filters->>'regulator_id','') IS NULL OR s.regulator_id = (_filters->>'regulator_id')::uuid)
       AND (NULLIF(_filters->>'date_from','') IS NULL OR s.created_at >= (_filters->>'date_from')::timestamptz)
       AND (NULLIF(_filters->>'date_to','')   IS NULL OR s.created_at <= (_filters->>'date_to')::timestamptz)
       AND (NULLIF(_search,'') IS NULL
            OR s.individual_name ILIKE '%'||_search||'%'
            OR COALESCE(s.individual_national_id,'') ILIKE '%'||_search||'%'
            OR s.id::text ILIKE '%'||_search||'%')
  ), paged AS (
    SELECT * FROM filtered f
     ORDER BY
       CASE WHEN v_sort_col='created_at'       AND v_sort_dir='asc'  THEN f.created_at END ASC NULLS LAST,
       CASE WHEN v_sort_col='created_at'       AND v_sort_dir='desc' THEN f.created_at END DESC NULLS LAST,
       CASE WHEN v_sort_col='status'           AND v_sort_dir='asc'  THEN f.status END ASC NULLS LAST,
       CASE WHEN v_sort_col='status'           AND v_sort_dir='desc' THEN f.status END DESC NULLS LAST,
       CASE WHEN v_sort_col='assessment_type'  AND v_sort_dir='asc'  THEN f.assessment_type END ASC NULLS LAST,
       CASE WHEN v_sort_col='assessment_type'  AND v_sort_dir='desc' THEN f.assessment_type END DESC NULLS LAST,
       CASE WHEN v_sort_col='last_activity_at' AND v_sort_dir='asc'  THEN f.last_activity_at END ASC NULLS LAST,
       CASE WHEN v_sort_col='last_activity_at' AND v_sort_dir='desc' THEN f.last_activity_at END DESC NULLS LAST
     LIMIT v_limit OFFSET v_offset
  )
  SELECT (SELECT count(*) FROM filtered), COALESCE(jsonb_agg(to_jsonb(p.*)), '[]'::jsonb)
    INTO v_total, v_rows FROM paged p;

  RETURN jsonb_build_object('total', v_total, 'page', GREATEST(_page,1), 'page_size', v_limit, 'rows', v_rows);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_internal_users(_search text DEFAULT NULL::text, _include_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(id uuid, full_name text, email text, primary_role text, status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _external_roles text[] := ARRAY['pre_licensee','licensee','licensee_primary','licensee_secondary','applicant'];
  _external_types text[] := ARRAY['primary','secondary','applicant','licensee','licensee_primary','licensee_secondary','pre_licensee'];
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_internal_staff(auth.uid()) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH staff AS (
    SELECT ur.user_id,
           (ARRAY_AGG(ur.role::text ORDER BY ur.role::text))[1] AS primary_role
    FROM public.user_roles ur
    WHERE NOT (ur.role::text = ANY (_external_roles))
    GROUP BY ur.user_id
  )
  SELECT p.id,
         p.full_name,
         p.email,
         s.primary_role,
         p.status
  FROM staff s
  JOIN public.profiles p ON p.id = s.user_id
  WHERE NOT EXISTS (
          SELECT 1 FROM public.user_roles ux
          WHERE ux.user_id = p.id
            AND ux.role::text = ANY (_external_roles)
        )
    AND NOT (COALESCE(LOWER(p.user_type::text), '') = ANY (_external_types))
    AND NOT EXISTS (
          SELECT 1 FROM public.entity_user_access eua
          WHERE eua.user_id = p.id
        )
    AND (
      _search IS NULL
      OR BTRIM(_search) = ''
      OR COALESCE(p.full_name, '') ILIKE '%' || BTRIM(_search) || '%'
      OR COALESCE(p.email, '') ILIKE '%' || BTRIM(_search) || '%'
    )
  UNION
  SELECT p.id,
         p.full_name,
         p.email,
         (SELECT (ARRAY_AGG(ur.role::text ORDER BY ur.role::text))[1]
            FROM public.user_roles ur WHERE ur.user_id = p.id),
         p.status
  FROM public.profiles p
  WHERE _include_ids IS NOT NULL
    AND p.id = ANY (_include_ids);
END;
$function$
;
