CREATE OR REPLACE FUNCTION public.log_application_triage_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
BEGIN
  IF NEW.priority IS DISTINCT FROM OLD.priority THEN
    INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value, metadata)
    VALUES (
      actor,
      'application.priority_changed',
      'applications',
      NEW.id::text,
      jsonb_build_object('priority', OLD.priority),
      jsonb_build_object('priority', NEW.priority, 'reason', NEW.priority_reason),
      jsonb_build_object('source', 'trigger', 'application_id', NEW.id, 'reason', NEW.priority_reason)
    );
  END IF;

  IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to THEN
    INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value, metadata)
    VALUES (
      actor,
      'application.assigned',
      'applications',
      NEW.id::text,
      jsonb_build_object('assigned_to', OLD.assigned_to),
      jsonb_build_object('assigned_to', NEW.assigned_to),
      jsonb_build_object('source', 'trigger', 'application_id', NEW.id)
    );
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.log_compliance_audit(_action_type compliance_audit_action, _object_type text, _object_id text DEFAULT NULL::text, _before_value jsonb DEFAULT NULL::jsonb, _after_value jsonb DEFAULT NULL::jsonb, _justification text DEFAULT NULL::text, _ai_model_version text DEFAULT NULL::text, _ip_address text DEFAULT NULL::text, _metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_role text := public.resolve_actor_role(auth.uid());
  v_id uuid;
BEGIN
  IF _action_type = 'OVERRIDE'::compliance_audit_action
     AND (_justification IS NULL OR length(btrim(_justification)) < 10) THEN
    RAISE EXCEPTION 'Override actions require a justification of at least 10 characters'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.compliance_audit_logs (
    timestamp, user_id, user_role, action_type, object_type, object_id,
    before_value, after_value, justification, ai_model_version,
    ip_address, user_agent, metadata, created_at
  ) VALUES (
    now(), v_user, v_role, _action_type, _object_type, _object_id,
    _before_value, _after_value, _justification, _ai_model_version,
    NULLIF(_ip_address,'')::inet, NULLIF(_metadata->>'user_agent',''),
    COALESCE(_metadata, '{}'::jsonb), now()
  )
  RETURNING entry_id INTO v_id;
  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.log_compliance_audit(_action_type text, _object_type text, _object_id uuid, _before_value jsonb, _after_value jsonb, _justification text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN public.log_compliance_audit(
    upper(btrim(_action_type))::public.compliance_audit_action,
    _object_type,
    _object_id::text,
    _before_value,
    _after_value,
    _justification
  );
END;
$function$
;
