CREATE OR REPLACE FUNCTION public.log_security_event(_event_type security_event_type, _target_resource text DEFAULT NULL::text, _ip_address inet DEFAULT NULL::inet, _user_agent text DEFAULT NULL::text, _detail jsonb DEFAULT NULL::jsonb, _metadata jsonb DEFAULT NULL::jsonb, _severity text DEFAULT 'medium'::text, _module text DEFAULT NULL::text, _action text DEFAULT NULL::text, _object_type text DEFAULT NULL::text, _object_id text DEFAULT NULL::text, _correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_user uuid := auth.uid();
  v_role text;
BEGIN
  SELECT role::text INTO v_role FROM public.user_roles WHERE user_id = v_user
  ORDER BY CASE role::text
    WHEN 'super_admin' THEN 1 WHEN 'admin' THEN 2 WHEN 'supervisor' THEN 3 ELSE 9 END
  LIMIT 1;

  INSERT INTO public.security_event_logs (
    user_id, user_role, event_type, ip_address, user_agent, target_resource,
    detail, metadata, severity, module, action, object_type, object_id, correlation_id
  ) VALUES (
    v_user, v_role, _event_type, _ip_address, _user_agent, _target_resource,
    public.redact_sensitive_jsonb(_detail), public.redact_sensitive_jsonb(_metadata),
    coalesce(nullif(btrim(_severity), ''), 'medium'), _module, _action, _object_type, _object_id, _correlation_id
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;
