CREATE OR REPLACE FUNCTION public.log_self_audit(_action text, _entity_type text, _entity_id text DEFAULT NULL::text, _old_value jsonb DEFAULT NULL::jsonb, _new_value jsonb DEFAULT NULL::jsonb, _metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT role::text INTO v_role
    FROM public.user_roles
   WHERE user_id = v_uid
   ORDER BY
     CASE role::text
       WHEN 'super_admin' THEN 1
       WHEN 'admin' THEN 2
       WHEN 'moderator' THEN 3
       ELSE 9
     END
   LIMIT 1;

  INSERT INTO public.audit_logs
    (user_id, user_role, action, entity_type, entity_id, old_value, new_value, metadata)
  VALUES
    (v_uid, v_role, _action, _entity_type, _entity_id, _old_value, _new_value, _metadata)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.log_validation_run(_return_id uuid, _results jsonb, _context text DEFAULT 'submit'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _batch uuid := gen_random_uuid(); _r jsonb;
BEGIN
  FOR _r IN SELECT jsonb_array_elements(_results) LOOP
    INSERT INTO public.return_validation_run_log(batch_id, return_id, rule_id, rule_version, rule_name, severity, passed, message, context, executed_by)
    VALUES (_batch, _return_id, NULLIF(_r->>'rule_id','')::uuid, NULLIF(_r->>'rule_version','')::int,
            _r->>'rule_name', COALESCE(_r->>'severity','error'), COALESCE((_r->>'passed')::boolean, false),
            _r->>'message', _context, auth.uid());
  END LOOP;
  UPDATE public.returns_filed SET latest_validation_batch_id = _batch WHERE id = _return_id;
  PERFORM public.log_compliance_audit('UPDATE','returns_filed', _return_id::text, NULL,
    jsonb_build_object('batch_id',_batch,'count',jsonb_array_length(_results)),
    'Validation executed', NULL, NULL, jsonb_build_object('event','RETURN_VALIDATED','context',_context));
  RETURN _batch;
END $function$
;
CREATE OR REPLACE FUNCTION public.log_workflow_authz_denial(_actor_id uuid, _step_id uuid, _action_type text, _reason text, _diagnostic jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.security_event_logs (
    user_id, event_type, severity, module, action,
    object_type, object_id, detail
  ) VALUES (
    _actor_id, 'ACCESS_DENIED', 'high', 'workflow_management',
    COALESCE(_action_type, 'unknown'),
    'approval_step', _step_id::text,
    jsonb_build_object('reason', COALESCE(_reason, 'WRONG_APPROVER'),
                       'diagnostic', COALESCE(_diagnostic, '{}'::jsonb))
  );
EXCEPTION WHEN OTHERS THEN
  NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.manual_escalate_complaint(_complaint_id uuid, _rule_key text, _target_tier text DEFAULT 'supervisor'::text, _severity text DEFAULT 'medium'::text, _notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_case_id uuid;
BEGIN
  IF NOT public.has_complaint_perm(auth.uid(), 'triage')
     AND NOT public.has_complaint_perm(auth.uid(), 'escalate')
     AND NOT public.has_complaint_perm(auth.uid(), 'view_all') THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.complaints WHERE id = _complaint_id) THEN
    RAISE EXCEPTION 'complaint_not_found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.complaint_escalation_cases
    (complaint_id, rule_key, rule_label, target_tier, severity, trigger_reason, status)
  VALUES
    (_complaint_id, _rule_key, initcap(replace(_rule_key,'_',' ')), _target_tier, _severity,
     COALESCE(_notes, 'Manual escalation'), 'pending')
  ON CONFLICT (complaint_id, rule_key)
  WHERE status IN ('pending','acknowledged','escalated')
  DO UPDATE SET updated_at = now(), notes = COALESCE(EXCLUDED.trigger_reason, complaint_escalation_cases.notes)
  RETURNING id INTO v_case_id;

  INSERT INTO public.audit_logs (user_id, action, table_name, record_id, new_values)
  VALUES (auth.uid(), 'manual_escalate', 'complaint_escalation_cases', v_case_id,
          jsonb_build_object('complaint_id', _complaint_id, 'rule_key', _rule_key, 'target_tier', _target_tier));

  RETURN v_case_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.mark_application_in_progress(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  SELECT id, applicant_id, status
    INTO v_app
    FROM public.applications
   WHERE id = _application_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND');
  END IF;

  IF v_uid IS NOT NULL AND v_app.applicant_id <> v_uid THEN
    RETURN jsonb_build_object('error','Not owner','code','FORBIDDEN');
  END IF;

  IF v_app.status <> 'draft' THEN
    RETURN jsonb_build_object('ok', true, 'status', v_app.status, 'changed', false);
  END IF;

  UPDATE public.applications
     SET status = 'in_progress', updated_at = now()
   WHERE id = _application_id AND status = 'draft';

  RETURN jsonb_build_object('ok', true, 'status', 'in_progress', 'changed', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.mark_correspondence_thread_read(_thread_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_staff boolean; v_actor text;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT public.correspondence_thread_visible(_thread_id, v_user) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  v_staff := public.is_internal_staff(v_user);
  v_actor := public.correspondence_actor_label(v_user);

  UPDATE public.correspondence_thread_participants
     SET last_read_at = now()
   WHERE thread_id = _thread_id AND user_id = v_user;

  IF NOT FOUND THEN
    INSERT INTO public.correspondence_thread_participants (thread_id, user_id, party_type, display_name, party_role, last_read_at)
    VALUES (_thread_id, v_user, CASE WHEN v_staff THEN 'officer' ELSE 'entity' END, v_actor,
            CASE WHEN v_staff THEN 'Officer' ELSE 'Entity' END, now())
    ON CONFLICT DO NOTHING;
  END IF;

  IF NOT v_staff THEN
    UPDATE public.correspondence_messages
       SET opened_at = COALESCE(opened_at, now()),
           delivery_status = CASE WHEN delivery_status IN ('bounced') THEN delivery_status ELSE 'opened' END
     WHERE thread_id = _thread_id AND message_kind = 'external_outbound' AND opened_at IS NULL;
  END IF;
END; $function$
;
CREATE OR REPLACE FUNCTION public.mark_expired_licenses()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  UPDATE public.licenses
     SET status = 'expired', updated_at = now()
   WHERE status = 'active'
     AND valid_until IS NOT NULL
     AND valid_until < now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.mark_prudential_actions_breached()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _n integer := 0; _r record;
BEGIN
  FOR _r IN
    SELECT * FROM public.prudential_actions
     WHERE status IN ('open','in_progress','overdue','awaiting_evidence')
       AND due_date IS NOT NULL
       AND due_date < (CURRENT_DATE - COALESCE(breach_after_days,7))
  LOOP
    UPDATE public.prudential_actions
       SET status = 'breached', breached_at = now(), updated_at = now()
     WHERE id = _r.id;

    INSERT INTO public.prudential_action_events(action_id, event_type, from_status, to_status, reason, actor_id)
    VALUES (_r.id, 'breached', _r.status, 'breached', 'Automated breach sweep: due date exceeded by breach window', NULL);

    IF NOT EXISTS (
      SELECT 1 FROM public.prudential_escalations e
       WHERE e.related_type = 'action' AND e.related_id = _r.id AND e.status IN ('open','under_review')
    ) THEN
      INSERT INTO public.prudential_escalations(entity_id, related_type, related_id, escalation_type, reason, status, priority, created_by)
      VALUES (_r.entity_id, 'action', _r.id, 'action_breach',
              'Supervisory action ' || _r.action_reference || ' breached its remediation deadline',
              'open', COALESCE(_r.severity,'high'), _r.created_by);
    END IF;
    _n := _n + 1;
  END LOOP;
  RETURN _n;
END $function$
;
CREATE OR REPLACE FUNCTION public.mark_prudential_actions_overdue()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n INT;
BEGIN
  UPDATE public.prudential_actions
     SET status = 'overdue', updated_at = now()
   WHERE status IN ('open','in_progress','awaiting_evidence')
     AND due_date IS NOT NULL AND due_date < CURRENT_DATE;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $function$
;
CREATE OR REPLACE FUNCTION public.mc_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$
;
CREATE OR REPLACE FUNCTION public.monitoring_result_risk_feedback()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  period text := to_char(now(),'YYYY-MM');
  cur record;
  new_components jsonb;
  new_score numeric;
  new_band text;
BEGIN
  IF NOT NEW.matched OR NEW.entity_id IS NULL OR NEW.risk_delta_applied = 0 THEN RETURN NEW; END IF;

  SELECT * INTO cur FROM public.entity_risk_scores
    WHERE entity_id = NEW.entity_id AND period_key = period
    ORDER BY computed_at DESC LIMIT 1;

  IF cur.id IS NULL THEN
    new_components := jsonb_build_object('monitoring', NEW.risk_delta_applied);
    new_score := GREATEST(0, LEAST(100, NEW.risk_delta_applied));
    new_band := CASE WHEN new_score >= 75 THEN 'critical'
                     WHEN new_score >= 50 THEN 'high'
                     WHEN new_score >= 25 THEN 'medium' ELSE 'low' END;
    UPDATE public.entity_risk_scores SET is_current = false WHERE entity_id = NEW.entity_id;
    INSERT INTO public.entity_risk_scores(entity_id, period_key, score, band, components, weights, is_current)
      VALUES (NEW.entity_id, period, new_score, new_band, new_components, '{}'::jsonb, true);
  ELSE
    new_components := cur.components || jsonb_build_object(
      'monitoring', COALESCE((cur.components->>'monitoring')::numeric,0) + NEW.risk_delta_applied
    );
    new_score := GREATEST(0, LEAST(100, cur.score + NEW.risk_delta_applied));
    new_band := CASE WHEN new_score >= 75 THEN 'critical'
                     WHEN new_score >= 50 THEN 'high'
                     WHEN new_score >= 25 THEN 'medium' ELSE 'low' END;
    UPDATE public.entity_risk_scores
      SET components = new_components, score = new_score, band = new_band,
          computed_at = now(), is_current = true
      WHERE id = cur.id;
  END IF;
  RETURN NEW;
END; $function$
;
