$function$
;
CREATE OR REPLACE FUNCTION public.normalize_entity_identifier(_identifier_type_id uuid, _raw_value text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_strategy text; v text := btrim(COALESCE(_raw_value, ''));
BEGIN
  SELECT normalization_strategy INTO v_strategy
    FROM public.entity_identifier_types WHERE id = _identifier_type_id;
  IF v_strategy IS NULL THEN
    RAISE EXCEPTION 'Unknown identifier type %', _identifier_type_id USING ERRCODE = '23503';
  END IF;

  CASE v_strategy
    WHEN 'TRIM_ONLY'           THEN NULL;
    WHEN 'CASE_SENSITIVE_TRIM' THEN v := regexp_replace(v, '\s+', ' ', 'g');
    WHEN 'UPPER_TRIM'          THEN v := upper(regexp_replace(v, '\s+', ' ', 'g'));
    WHEN 'UPPER_ALPHANUMERIC'  THEN v := upper(regexp_replace(v, '[^A-Za-z0-9]', '', 'g'));
    WHEN 'DIGITS_ONLY'         THEN v := regexp_replace(v, '[^0-9]', '', 'g');
    ELSE RAISE EXCEPTION 'Unsupported normalization strategy %', v_strategy USING ERRCODE = '22023';
  END CASE;

  RETURN v;
END $function$
;
CREATE OR REPLACE FUNCTION public.normalize_review_step_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.enabled = false THEN
    NEW.can_view := false;
    NEW.can_comment := false;
    NEW.can_reply := false;
    NEW.can_suggest := false;
    NEW.can_accept := false;
    NEW.can_reject := false;
    NEW.can_resolve := false;
    NEW.can_mark_blocking := false;
    NEW.block_approval_on_unresolved_blocking := false;
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.notif_enqueue(_event_key text, _entity_type text, _entity_id uuid, _reference text, _route text, _payload jsonb DEFAULT '{}'::jsonb, _suffix text DEFAULT NULL::text, _reminder_window text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payload jsonb;
BEGIN
  v_payload := coalesce(_payload, '{}'::jsonb)
    || jsonb_build_object(
         'source_entity_type', _entity_type,
         'source_entity_id', _entity_id,
         'source_reference', _reference,
         'source_route', _route,
         'actor_id', auth.uid()
       );
  RETURN public.notification_enqueue_event(
    _event_key, _entity_type, _entity_id, v_payload, _suffix, gen_random_uuid(), _reminder_window
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notif_event_configs_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$
;
CREATE OR REPLACE FUNCTION public.notification_admin_audit(_action text, _entity_type text, _entity_id text, _old jsonb DEFAULT NULL::jsonb, _new jsonb DEFAULT NULL::jsonb, _meta jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value, metadata)
  VALUES (auth.uid(), _action, _entity_type, _entity_id, _old, _new, COALESCE(_meta, '{}'::jsonb));
$function$
;
CREATE OR REPLACE FUNCTION public.notification_admin_guard(_action text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF NOT public.has_permission(auth.uid(), 'notification_management', _action) THEN
    RAISE EXCEPTION 'forbidden: notification_management.% required', _action;
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_archive(_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  UPDATE public.notifications
    SET status = 'archived', archived_at = now()
  WHERE id = ANY(_ids) AND user_id = auth.uid() AND status <> 'archived';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN
    PERFORM public.log_notification_audit('NOTIFICATION_ARCHIVED', _ids, '{}'::jsonb);
  END IF;
  RETURN n;
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_category_for(_event_key text, _type text)
 RETURNS notification_category
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _event_key ~* '(rfi|approval|assigned|action_required|due|payment_required|resubmission|vote|acknowledg)' THEN 'action_required'
    WHEN _event_key ~* '(breach|escalat|overdue|alert|warning|expiring|near_due|sla|threshold|pattern)' THEN 'alert'
    WHEN _event_key ~* '(system|integration|scheduler|form_version|maintenance)' THEN 'system'
    WHEN _type = 'error' THEN 'alert'
    ELSE 'info'
  END::public.notification_category
$function$
;
CREATE OR REPLACE FUNCTION public.notification_channel_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_smtp jsonb;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL OR NOT public.has_permission(v_uid, 'notification_management', 'view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(value -> 'smtp', '{}'::jsonb)
    INTO v_smtp
    FROM public.site_settings
   WHERE key = 'email_sms_settings';

  SELECT jsonb_build_object(
    'smtp', jsonb_build_object(
      'configured', COALESCE(
        COALESCE((v_smtp ->> 'enabled')::boolean, false)
        AND COALESCE(v_smtp ->> 'host', '') <> ''
        AND COALESCE(v_smtp ->> 'username', '') <> ''
        AND COALESCE(v_smtp ->> 'password', '') <> ''
        AND COALESCE(v_smtp ->> 'fromEmail', '') <> '', false),
      'host_set', COALESCE(v_smtp ->> 'host', '') <> '',
      'enabled', COALESCE((v_smtp ->> 'enabled')::boolean, false)
    ),
    'sms', jsonb_build_object('configured', false, 'available', false, 'reason', 'sms_provider_not_configured'),
    'email', jsonb_build_object(
      'last_success_at', (SELECT max(sent_at) FROM public.notification_dispatch_log WHERE channel = 'email' AND status IN ('sent','delivered')),
      'failures_1h', (SELECT count(*) FROM public.notification_dispatch_log WHERE channel = 'email' AND status IN ('failed','bounced') AND created_at > now() - interval '1 hour'),
      'failures_24h', (SELECT count(*) FROM public.notification_dispatch_log WHERE channel = 'email' AND status IN ('failed','bounced') AND created_at > now() - interval '24 hours'),
      'sent_24h', (SELECT count(*) FROM public.notification_dispatch_log WHERE channel = 'email' AND status IN ('sent','delivered') AND created_at > now() - interval '24 hours'),
      'bounced_24h', (SELECT count(*) FROM public.notification_dispatch_log WHERE channel = 'email' AND status = 'bounced' AND created_at > now() - interval '24 hours'),
      'poisoned', (SELECT count(*) FROM public.notification_dispatch_log WHERE channel = 'email' AND poisoned)
    ),
    'in_app', jsonb_build_object(
      'last_success_at', (SELECT max(delivered_at) FROM public.notification_dispatch_log WHERE channel = 'in_app' AND status = 'delivered'),
      'failures_24h', (SELECT count(*) FROM public.notification_dispatch_log WHERE channel = 'in_app' AND status = 'failed' AND created_at > now() - interval '24 hours')
    ),
    'queue', jsonb_build_object(
      'dispatch_pending', (SELECT count(*) FROM public.notification_dispatch_log WHERE status IN ('queued','processing')),
      'dispatch_oldest_pending_at', (SELECT min(created_at) FROM public.notification_dispatch_log WHERE status IN ('queued','processing')),
      'event_queue_pending', (SELECT count(*) FROM public.notification_event_queue WHERE status = 'pending'),
      'event_queue_dead', (SELECT count(*) FROM public.notification_event_queue WHERE status = 'dead'),
      'event_queue_oldest_pending_at', (SELECT min(created_at) FROM public.notification_event_queue WHERE status = 'pending'),
      'retry_backlog', (SELECT count(*) FROM public.notification_dispatch_log WHERE channel = 'email' AND status = 'failed' AND poisoned = false AND attempts < 5)
    ),
    'workers', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'jobname', w.jobname,
        'schedule', w.schedule,
        'active', w.active,
        'last_run_at', w.last_run_at,
        'last_status', w.last_status
      ) ORDER BY w.jobname)
      FROM (
        SELECT j.jobname::text AS jobname,
               j.schedule::text AS schedule,
               j.active,
               d.end_time AS last_run_at,
               d.status::text AS last_status
          FROM cron.job j
          LEFT JOIN LATERAL (
            SELECT end_time, status FROM cron.job_run_details r
             WHERE r.jobid = j.jobid ORDER BY end_time DESC NULLS LAST LIMIT 1
          ) d ON true
         WHERE j.jobname ILIKE '%notification%' OR j.jobname ILIKE '%digest%' OR j.jobname ILIKE '%escalation%'
      ) w
    ), '[]'::jsonb),
    'recent_errors', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', e.id,
        'event_key', e.event_key,
        'channel', e.channel,
        'status', e.status,
        'attempts', e.attempts,
        'created_at', e.created_at,
        'recipient_masked', CASE
          WHEN e.recipient_email IS NULL THEN NULL
          ELSE regexp_replace(e.recipient_email, '^(.).*(@.*)$', '\1***\2')
        END,
        'error', left(regexp_replace(COALESCE(e.error, ''), '(?i)(pass(word)?|secret|token|key)\s*[:=]\s*\S+', '\1=[redacted]', 'g'), 240)
      ) ORDER BY e.created_at DESC)
      FROM (
        SELECT * FROM public.notification_dispatch_log
         WHERE status IN ('failed','bounced')
         ORDER BY created_at DESC LIMIT 10
      ) e
    ), '[]'::jsonb),
    'generated_at', now()
  ) INTO v_result;

  RETURN v_result;
END; $function$
;
CREATE OR REPLACE FUNCTION public.notification_counts()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'total', count(*),
    'unread', count(*) FILTER (WHERE status = 'unread'),
    'unread_urgent', count(*) FILTER (WHERE status = 'unread' AND severity IN ('critical','high')),
    'action_required', count(*) FILTER (WHERE status = 'unread' AND category = 'action_required'),
    'alerts', count(*) FILTER (WHERE status = 'unread' AND category = 'alert'),
    'archived', count(*) FILTER (WHERE status = 'archived')
  )
  FROM public.notifications
  WHERE user_id = auth.uid() AND channel = 'in_app'
    AND status NOT IN ('dismissed','archived')
    AND (expires_at IS NULL OR expires_at > now())
$function$
;
CREATE OR REPLACE FUNCTION public.notification_dead_letters(_limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, event_key text, module text, channel text, recipient_user_id uuid, recipient_destination text, provider text, provider_message_id text, communication_state communication_state, failure_category text, error text, retry_count integer, attempts integer, requested_at timestamp with time zone, failed_at timestamp with time zone, last_attempt_at timestamp with time zone, entity_type text, entity_id text, correlation_id text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.enforce_permission('notification_management','dispatch');
  RETURN QUERY
  SELECT d.id, d.event_key, d.module, d.channel, d.recipient_user_id,
         COALESCE(d.recipient_email, d.recipient_phone), d.provider, d.provider_message_id,
         d.communication_state, d.failure_category, d.error,
         COALESCE(d.retry_count,0), COALESCE(d.attempts,0), d.requested_at, d.failed_at,
         d.last_attempt_at, d.entity_type, d.entity_id, d.correlation_id
  FROM public.notification_dispatch_log d
  WHERE d.communication_state IN ('DEAD_LETTER','PROVIDER_NOT_CONFIGURED')
  ORDER BY COALESCE(d.failed_at, d.created_at) DESC
  LIMIT LEAST(GREATEST(COALESCE(_limit,50),1),200) OFFSET GREATEST(COALESCE(_offset,0),0);
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_delivery_for(_notification_id uuid)
 RETURNS TABLE(channel text, status text, provider text, queued_at timestamp with time zone, sent_at timestamp with time zone, delivered_at timestamp with time zone, failed_at timestamp with time zone, retry_count integer, error text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT d.channel, d.status, d.provider, d.queued_at, d.sent_at,
         d.delivered_at, d.failed_at, COALESCE(d.retry_count, 0), d.error
  FROM public.notification_dispatch_log d
  JOIN public.notifications n ON n.id = d.notification_id
  WHERE d.notification_id = _notification_id
    AND n.user_id = auth.uid()
  ORDER BY d.created_at DESC;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_digest_build(_period text, _period_start timestamp with time zone DEFAULT NULL::timestamp with time zone, _channel text DEFAULT 'email'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  p_start timestamptz;
  p_end timestamptz := now();
  rec record;
  run_id uuid;
  inserted int;
  out_runs jsonb := '[]'::jsonb;
BEGIN
  IF _period NOT IN ('hourly','daily') THEN
    RAISE EXCEPTION 'invalid_period: %', _period;
  END IF;

  p_start := COALESCE(
    _period_start,
    CASE WHEN _period = 'hourly' THEN date_trunc('hour', now()) - interval '1 hour'
         ELSE date_trunc('day', now()) - interval '1 day' END
  );
  p_end := p_start + CASE WHEN _period = 'hourly' THEN interval '1 hour' ELSE interval '1 day' END;

  FOR rec IN
    SELECT n.user_id, count(*) AS cnt
    FROM public.notifications n
    JOIN public.notification_event_configs c ON c.event_key = n.event_key
    LEFT JOIN public.notification_user_event_preferences p
      ON p.user_id = n.user_id AND p.event_key = n.event_key AND p.effective_from <= n.created_at
    WHERE n.user_id IS NOT NULL
      AND n.channel = 'in_app'
      AND n.created_at >= p_start AND n.created_at < p_end
      AND n.dismissed_at IS NULL AND n.archived_at IS NULL
      AND COALESCE(n.severity, c.severity) NOT IN ('critical','high')
      AND COALESCE(c.system_required, false) = false
      AND COALESCE(p.muted, false) = false
      AND COALESCE(p.digest_frequency::text, 'immediate') = _period
      AND CASE WHEN _channel = 'email' THEN COALESCE(p.email_enabled, false)
               WHEN _channel = 'sms' THEN COALESCE(p.sms_enabled, false) AND public.notification_sms_available()
               ELSE false END
      AND NOT EXISTS (
        SELECT 1 FROM public.notification_digest_items di
        WHERE di.notification_id = n.id AND di.period = _period
      )
    GROUP BY n.user_id
  LOOP
    INSERT INTO public.notification_digest_runs (user_id, channel, period, period_start, period_end)
    VALUES (rec.user_id, _channel, _period, p_start, p_end)
    ON CONFLICT (user_id, channel, period, period_start) DO NOTHING
    RETURNING id INTO run_id;

    -- A run already exists for this window: duplicate digest prevented
    IF run_id IS NULL THEN
      CONTINUE;
    END IF;

    WITH eligible AS (
      SELECT n.id
      FROM public.notifications n
      JOIN public.notification_event_configs c ON c.event_key = n.event_key
      LEFT JOIN public.notification_user_event_preferences p
        ON p.user_id = n.user_id AND p.event_key = n.event_key AND p.effective_from <= n.created_at
      WHERE n.user_id = rec.user_id
        AND n.channel = 'in_app'
        AND n.created_at >= p_start AND n.created_at < p_end
        AND n.dismissed_at IS NULL AND n.archived_at IS NULL
        AND COALESCE(n.severity, c.severity) NOT IN ('critical','high')
        AND COALESCE(c.system_required, false) = false
        AND COALESCE(p.muted, false) = false
        AND COALESCE(p.digest_frequency::text, 'immediate') = _period
        AND CASE WHEN _channel = 'email' THEN COALESCE(p.email_enabled, false)
                 WHEN _channel = 'sms' THEN COALESCE(p.sms_enabled, false) AND public.notification_sms_available()
                 ELSE false END
    ), ins AS (
      INSERT INTO public.notification_digest_items (run_id, notification_id, period)
      SELECT run_id, id, _period FROM eligible
      ON CONFLICT (notification_id, period) DO NOTHING
      RETURNING 1
    )
    SELECT count(*) INTO inserted FROM ins;

    UPDATE public.notification_digest_runs SET item_count = inserted WHERE id = run_id;

    IF inserted = 0 THEN
      UPDATE public.notification_digest_runs
      SET status = 'skipped', error = 'no eligible notifications'
      WHERE id = run_id;
      CONTINUE;
    END IF;

    out_runs := out_runs || jsonb_build_array(jsonb_build_object(
      'run_id', run_id,
      'user_id', rec.user_id,
      'channel', _channel,
      'period', _period,
      'period_start', p_start,
      'period_end', p_end,
      'item_count', inserted,
      'items', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
          'id', n.id, 'title', n.title, 'preview', COALESCE(n.preview, n.message),
          'module', n.module, 'severity', n.severity, 'route', n.source_route,
          'created_at', n.created_at) ORDER BY n.created_at DESC), '[]'::jsonb)
        FROM public.notification_digest_items di
        JOIN public.notifications n ON n.id = di.notification_id
        WHERE di.run_id = run_id
      ),
      'recipient_email', (SELECT email FROM public.profiles WHERE id = rec.user_id),
      'recipient_name', (SELECT full_name FROM public.profiles WHERE id = rec.user_id)
    ));
  END LOOP;

  RETURN jsonb_build_object('period', _period, 'period_start', p_start, 'period_end', p_end, 'runs', out_runs);
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_digest_dispatch(_period text, _period_start timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_build jsonb;
  v_run record;
  v_email text;
  v_body text;
  v_subject text;
  v_label text;
  v_queued int := 0;
  v_skipped int := 0;
BEGIN
  IF _period NOT IN ('hourly','daily') THEN
    RAISE EXCEPTION 'invalid_digest_period: %', _period USING ERRCODE = 'P0001';
  END IF;

  v_build := public.notification_digest_build(_period, _period_start);
  v_label := CASE WHEN _period = 'hourly' THEN 'Hourly' ELSE 'Daily' END;

  FOR v_run IN
    SELECT r.*
    FROM public.notification_digest_runs r
    WHERE r.period = _period
      AND r.status IN ('pending','failed')
      AND r.item_count > 0
  LOOP
    SELECT p.email INTO v_email FROM public.profiles p WHERE p.id = v_run.user_id;

    IF v_email IS NULL OR v_email = '' THEN
      PERFORM public.notification_digest_mark(v_run.id, 'failed', 'no_recipient_email');
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    SELECT string_agg(
             format('- [%s] %s: %s', upper(n.severity::text), n.title, coalesce(n.message,'')),
             E'\n' ORDER BY n.created_at
           )
      INTO v_body
      FROM public.notification_digest_items di
      JOIN public.notifications n ON n.id = di.notification_id
     WHERE di.run_id = v_run.id;

    v_subject := format('%s notification digest — %s update(s)', v_label, v_run.item_count);
    v_body := format(
      E'%s notification digest for %s to %s.\n\nYou have %s new notification(s):\n\n%s\n\nOpen the Notification Centre to review and act on these items.\nYou can change your digest settings in Settings > Notifications.',
      v_label,
      to_char(v_run.period_start, 'DD Mon YYYY HH24:MI'),
      to_char(v_run.period_end, 'DD Mon YYYY HH24:MI'),
      v_run.item_count,
      coalesce(v_body, '')
    );

    INSERT INTO public.notification_outbox
      (event_key, entity_type, entity_id, recipient_user_id, recipient_email,
       channel, subject, body, payload, status)
    VALUES
      ('notification.digest', 'notification_digest_run', v_run.id, v_run.user_id, v_email,
       'email', v_subject, v_body,
       jsonb_build_object('period', _period, 'item_count', v_run.item_count,
                          'period_start', v_run.period_start, 'period_end', v_run.period_end),
       'pending');

    PERFORM public.notification_digest_mark(v_run.id, 'sent', NULL);
    v_queued := v_queued + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'period', _period,
    'built', coalesce(jsonb_array_length(v_build->'runs'), 0),
    'queued', v_queued,
    'skipped', v_skipped
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_digest_mark(_run_id uuid, _status text, _error text DEFAULT NULL::text, _dispatch_log_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF _status NOT IN ('pending','sent','failed','skipped') THEN
    RAISE EXCEPTION 'invalid_status: %', _status;
  END IF;

  UPDATE public.notification_digest_runs
  SET status = _status,
      error = _error,
      attempts = attempts + 1,
      dispatch_log_id = COALESCE(_dispatch_log_id, dispatch_log_id),
      sent_at = CASE WHEN _status = 'sent' THEN now() ELSE sent_at END
  WHERE id = _run_id;

  -- Failed digests release their items so a later run can retry them safely
  IF _status = 'failed' THEN
    DELETE FROM public.notification_digest_items WHERE run_id = _run_id;
    DELETE FROM public.notification_digest_runs WHERE id = _run_id AND attempts >= 5;
  END IF;
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_dismiss(_ids uuid[], _note text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  UPDATE public.notifications
    SET dismissed_at = now(), dismiss_note = _note, read = true
  WHERE id = ANY(_ids) AND user_id = auth.uid() AND dismissed_at IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN
    PERFORM public.log_notification_audit('NOTIFICATION_DISMISSED', _ids,
      jsonb_build_object('note', _note));
  END IF;
  RETURN n;
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_dispatch_log_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.rendered_content IS NOT NULL AND NEW.rendered_content IS DISTINCT FROM OLD.rendered_content THEN
    NEW.rendered_content := OLD.rendered_content;
  END IF;
  IF OLD.subject IS NOT NULL AND NEW.subject IS DISTINCT FROM OLD.subject THEN
    NEW.subject := OLD.subject;
  END IF;
  IF OLD.template_id IS NOT NULL AND NEW.template_id IS DISTINCT FROM OLD.template_id THEN
    NEW.template_id := OLD.template_id;
  END IF;
  IF OLD.template_version IS NOT NULL AND NEW.template_version IS DISTINCT FROM OLD.template_version THEN
    NEW.template_version := OLD.template_version;
  END IF;
  IF OLD.recipient_email IS NOT NULL AND NEW.recipient_email IS DISTINCT FROM OLD.recipient_email THEN
    NEW.recipient_email := OLD.recipient_email;
  END IF;
  IF OLD.sent_at IS NOT NULL AND NEW.sent_at IS DISTINCT FROM OLD.sent_at THEN
    NEW.sent_at := OLD.sent_at;
  END IF;
  IF OLD.event_key IS NOT NULL AND NEW.event_key IS DISTINCT FROM OLD.event_key THEN
    NEW.event_key := OLD.event_key;
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.notification_dispatch_traceability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.template_traceability_status := CASE
    WHEN NEW.template_id IS NOT NULL AND NEW.template_version IS NOT NULL THEN 'versioned'
    ELSE 'legacy_unversioned'
  END;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_effective_preference(_user_id uuid, _event_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  cfg record;
  sev public.notification_severity;
  pref record;
  legacy jsonb;
  result jsonb;
BEGIN
  SELECT severity, allow_mute, system_required INTO cfg
  FROM public.notification_event_configs WHERE event_key = _event_key LIMIT 1;
  sev := COALESCE(cfg.severity, public.notification_severity_for(_event_key, NULL));

  SELECT * INTO pref FROM public.notification_user_event_preferences
  WHERE user_id = _user_id AND event_key = _event_key AND effective_from <= now();

  IF pref.id IS NOT NULL THEN
    result := jsonb_build_object(
      'in_app', pref.in_app_enabled, 'email', pref.email_enabled, 'sms', pref.sms_enabled,
      'digest', pref.digest_frequency::text, 'muted', pref.muted, 'source', 'event_preference');
  ELSE
    SELECT COALESCE(type_settings, '{}'::jsonb) -> _event_key INTO legacy
    FROM public.notification_preferences WHERE user_id = _user_id;
    result := jsonb_build_object(
      'in_app', COALESCE((legacy->>'in_app')::boolean, true),
      'email', COALESCE((legacy->>'email')::boolean, true),
      'sms', COALESCE((legacy->>'sms')::boolean, false),
      'digest', COALESCE(legacy->>'digest', 'immediate'),
      'muted', COALESCE((legacy->>'muted')::boolean, false),
      'source', CASE WHEN legacy IS NULL THEN 'default' ELSE 'legacy_preference' END);
  END IF;

  -- Mandatory regulatory guarantees always win
  IF sev = 'critical' OR COALESCE(cfg.system_required,false) THEN
    result := result || jsonb_build_object('in_app', true, 'muted', false);
  END IF;
  IF sev IN ('critical','high') THEN
    result := result || jsonb_build_object('digest', 'immediate');
  END IF;
  IF COALESCE(cfg.system_required,false) THEN
    result := result || jsonb_build_object('email', true);
  END IF;

  RETURN result || jsonb_build_object('severity', sev::text, 'system_required', COALESCE(cfg.system_required,false));
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_enqueue_event(_event_key text, _entity_type text DEFAULT NULL::text, _entity_id uuid DEFAULT NULL::uuid, _payload jsonb DEFAULT '{}'::jsonb, _idempotency_suffix text DEFAULT NULL::text, _correlation_id uuid DEFAULT NULL::uuid, _reminder_window text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_key text;
  v_id uuid;
BEGIN
  v_key := concat_ws('#',
    _event_key,
    coalesce(_entity_type, '-'),
    coalesce(_entity_id::text, '-'),
    coalesce(_idempotency_suffix, '-'),
    coalesce(_reminder_window, '-')
  );

  INSERT INTO public.notification_event_queue (
    event_key, entity_type, entity_id, payload, idempotency_key, correlation_id, reminder_window
  ) VALUES (
    _event_key, _entity_type, _entity_id, coalesce(_payload, '{}'::jsonb), v_key,
    coalesce(_correlation_id, gen_random_uuid()), _reminder_window
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_id;

  RETURN v_id;
EXCEPTION WHEN OTHERS THEN
  -- A notification must never roll back a completed regulatory transaction.
  RAISE WARNING 'notification_enqueue_event failed for %: %', _event_key, SQLERRM;
  RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.notification_event_config_block_sms()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.channels IS NOT NULL AND 'sms' = ANY (NEW.channels) THEN
    NEW.channels := array_remove(NEW.channels, 'sms');
  END IF;
  IF NEW.channels IS NULL OR array_length(NEW.channels, 1) IS NULL THEN
    NEW.channels := ARRAY['in_app'];
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_event_config_requires_recipients()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(NEW.is_active, false) = true
     AND (NEW.recipient_rules IS NULL
          OR jsonb_typeof(NEW.recipient_rules) <> 'array'
          OR jsonb_array_length(NEW.recipient_rules) = 0) THEN
    RAISE EXCEPTION 'recipient_rules_required: event % cannot be active without at least one recipient rule', NEW.event_key
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.notification_event_config_requires_templates()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  ch text;
  missing text[] := '{}';
BEGIN
  IF NOT NEW.is_active OR NEW.fallback_allowed THEN
    RETURN NEW;
  END IF;

  -- Insert-time bindings cannot exist yet; enforcement applies from the first update.
  IF TG_OP = 'INSERT' THEN
    RETURN NEW;
  END IF;

  FOREACH ch IN ARRAY NEW.channels LOOP
    IF ch NOT IN ('in_app', 'email') THEN CONTINUE; END IF;
    IF NOT EXISTS (
      SELECT 1
        FROM public.notification_event_channel_templates b
        JOIN public.notification_templates t ON t.id = b.template_id
       WHERE b.event_config_id = NEW.id
         AND b.channel = ch
         AND t.status = 'active'
         AND EXISTS (SELECT 1 FROM public.notification_template_versions v
                      WHERE v.template_id = t.id)
    ) THEN
      missing := missing || ch;
    END IF;
  END LOOP;

  IF array_length(missing, 1) IS NOT NULL THEN
    RAISE EXCEPTION 'notification_event_missing_template: % has no published template for channel(s) %',
      NEW.event_key, array_to_string(missing, ', ');
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_event_config_save(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  cid uuid := NULLIF(_payload->>'id','')::uuid;
  before_row jsonb;
  chans text[] := COALESCE(
    ARRAY(SELECT jsonb_array_elements_text(_payload->'channels')),
    ARRAY['in_app']::text[]
  );
  rules jsonb := COALESCE(_payload->'recipient_rules', '[]'::jsonb);
  validation jsonb;
  binding jsonb;
  want_active boolean := COALESCE((_payload->>'is_active')::boolean, false);
  ch text;
BEGIN
  PERFORM public.notification_admin_guard('manage_events');
  IF COALESCE(_payload->>'event_key','') = '' THEN RAISE EXCEPTION 'event_key_required'; END IF;

  FOREACH ch IN ARRAY chans LOOP
    IF ch NOT IN ('in_app','email','sms') THEN RAISE EXCEPTION 'invalid_channel: %', ch; END IF;
  END LOOP;

  IF want_active THEN
    validation := public.notification_recipient_rules_validate(rules);
    IF NOT (validation->>'valid')::boolean THEN
      RAISE EXCEPTION 'invalid_recipient_rules: %', validation->>'errors';
    END IF;
  END IF;

  IF cid IS NULL THEN
    INSERT INTO public.notification_event_configs (
      event_key, description, module, notification_type, category, severity,
      action_required, system_required, allow_mute, channels, recipient_rules,
      dedupe_window_seconds, delivery_frequency, failure_escalation, is_active,
      title_template, message_template, email_subject_template, email_body_template
    ) VALUES (
      _payload->>'event_key', _payload->>'description',
      COALESCE(NULLIF(_payload->>'module',''), split_part(_payload->>'event_key','.',1)),
      COALESCE(NULLIF(_payload->>'notification_type',''), 'info'),
      COALESCE(NULLIF(_payload->>'category','')::notification_category, 'info'),
      COALESCE(NULLIF(_payload->>'severity','')::notification_severity, 'medium'),
      COALESCE((_payload->>'action_required')::boolean, false),
      COALESCE((_payload->>'system_required')::boolean, false),
      COALESCE((_payload->>'allow_mute')::boolean, true),
      chans, rules,
      COALESCE((_payload->>'dedupe_window_seconds')::int, 0),
      COALESCE(NULLIF(_payload->>'delivery_frequency',''), 'immediate'),
      COALESCE(_payload->'failure_escalation', '{}'::jsonb),
      false,
      _payload->>'title_template', _payload->>'message_template',
      _payload->>'email_subject_template', _payload->>'email_body_template'
    ) RETURNING id INTO cid;
    PERFORM public.notification_admin_audit('notification_event_config_created', 'notification_event_config', cid::text,
      NULL, jsonb_build_object('event_key', _payload->>'event_key'));
  ELSE
    SELECT to_jsonb(c) INTO before_row FROM public.notification_event_configs c WHERE c.id = cid;
    IF before_row IS NULL THEN RAISE EXCEPTION 'event_config_not_found'; END IF;
    UPDATE public.notification_event_configs SET
      event_key = _payload->>'event_key',
      description = _payload->>'description',
      module = COALESCE(NULLIF(_payload->>'module',''), split_part(_payload->>'event_key','.',1)),
      notification_type = COALESCE(NULLIF(_payload->>'notification_type',''), notification_type),
      category = COALESCE(NULLIF(_payload->>'category','')::notification_category, category),
      severity = COALESCE(NULLIF(_payload->>'severity','')::notification_severity, severity),
      action_required = COALESCE((_payload->>'action_required')::boolean, action_required),
      system_required = COALESCE((_payload->>'system_required')::boolean, system_required),
      allow_mute = COALESCE((_payload->>'allow_mute')::boolean, allow_mute),
      channels = chans,
      recipient_rules = rules,
      dedupe_window_seconds = COALESCE((_payload->>'dedupe_window_seconds')::int, dedupe_window_seconds),
      delivery_frequency = COALESCE(NULLIF(_payload->>'delivery_frequency',''), delivery_frequency),
      failure_escalation = COALESCE(_payload->'failure_escalation', failure_escalation),
      title_template = COALESCE(_payload->>'title_template', title_template),
      message_template = COALESCE(_payload->>'message_template', message_template),
      email_subject_template = COALESCE(_payload->>'email_subject_template', email_subject_template),
      email_body_template = COALESCE(_payload->>'email_body_template', email_body_template),
      updated_at = now()
    WHERE id = cid;
    PERFORM public.notification_admin_audit('notification_event_config_updated', 'notification_event_config', cid::text,
      before_row, (SELECT to_jsonb(c) FROM public.notification_event_configs c WHERE c.id = cid));
  END IF;

  -- channel -> template bindings
  IF _payload ? 'channel_templates' THEN
    DELETE FROM public.notification_event_channel_templates WHERE event_config_id = cid;
    FOR binding IN SELECT jsonb_array_elements(_payload->'channel_templates') LOOP
      IF COALESCE(binding->>'template_id','') <> '' THEN
        INSERT INTO public.notification_event_channel_templates
          (event_config_id, channel, template_id, template_version, created_by)
        SELECT cid, binding->>'channel', (binding->>'template_id')::uuid, t.published_version, auth.uid()
          FROM public.notification_templates t WHERE t.id = (binding->>'template_id')::uuid
        ON CONFLICT (event_config_id, channel) DO UPDATE
          SET template_id = EXCLUDED.template_id, template_version = EXCLUDED.template_version;
      END IF;
    END LOOP;
  END IF;

  IF want_active THEN
    PERFORM public.notification_event_config_set_active(cid, true);
  END IF;

  RETURN cid;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_event_config_set_active(_config_id uuid, _active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.notification_event_configs;
  validation jsonb;
  ch text;
  missing text[] := ARRAY[]::text[];
  has_inline boolean;
BEGIN
  PERFORM public.notification_admin_guard('manage_events');
  SELECT * INTO c FROM public.notification_event_configs WHERE id = _config_id FOR UPDATE;
  IF c.id IS NULL THEN RAISE EXCEPTION 'event_config_not_found'; END IF;

  IF _active THEN
    validation := public.notification_recipient_rules_validate(c.recipient_rules);
    IF NOT (validation->>'valid')::boolean THEN
      RAISE EXCEPTION 'invalid_recipient_rules: %', validation->>'errors';
    END IF;

    FOREACH ch IN ARRAY COALESCE(c.channels, ARRAY[]::text[]) LOOP
      has_inline := CASE ch
        WHEN 'email' THEN COALESCE(c.email_body_template, '') <> ''
        WHEN 'in_app' THEN COALESCE(c.message_template, '') <> ''
        ELSE COALESCE(c.message_template, '') <> ''
      END;
      IF NOT has_inline AND NOT EXISTS (
        SELECT 1 FROM public.notification_event_channel_templates b
          JOIN public.notification_templates t ON t.id = b.template_id
         WHERE b.event_config_id = c.id AND b.channel = ch AND t.status = 'active'
      ) THEN
        missing := missing || ch;
      END IF;
    END LOOP;

    IF array_length(missing, 1) > 0 THEN
      RAISE EXCEPTION 'missing_channel_template: no published template for channel(s) %', array_to_string(missing, ', ');
    END IF;
  END IF;

  UPDATE public.notification_event_configs
     SET is_active = _active, updated_at = now() WHERE id = c.id;

  PERFORM public.notification_admin_audit(
    CASE WHEN _active THEN 'notification_event_activated' ELSE 'notification_event_deactivated' END,
    'notification_event_config', c.id::text, NULL,
    jsonb_build_object('event_key', c.event_key, 'is_active', _active));

  RETURN jsonb_build_object('ok', true, 'is_active', _active);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_event_config_validate()
 RETURNS TABLE(event_key text, module text, severity text, category text, channels text[], recipient_rule_count integer, unsupported_rule_types text[], has_in_app_or_email boolean, templates_bound integer, templates_required integer, has_trigger_history boolean, dedupe_window_seconds integer, failure_escalation_configured boolean, fallback_allowed boolean, issues text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH supported AS (
    SELECT ARRAY[
      'role','user','payload_user','named_user','direct_email','custom_email','admin',
      'applicant','assigned_officer','current_approver','previous_actor','supervisor',
      'next_step_role','regulator_team','sector_regulators','actor_excluded',
      'entity_primary_users','entity_secondary_users',
      'licensee_primary_users','licensee_secondary_users',
      'return_admins','return_regulator_admins','return_entity_users','return_licensee_users',
      'return_sector_regulators','return_submitter',
      'return_workflow_current_step_approvers','return_workflow_next_step_approvers',
      'workflow_step_approvers','previous_workflow_actors','sla_process_team_leads',
      'thread_participants','thread_assigned_officer','record_assignee'
    ]::text[] AS types
  ), base AS (
    SELECT c.*,
      (SELECT count(*) FROM jsonb_array_elements(
         CASE WHEN jsonb_typeof(c.recipient_rules) = 'array' THEN c.recipient_rules ELSE '[]'::jsonb END))::int AS rule_count,
      (SELECT coalesce(array_agg(DISTINCT r->>'type'), '{}')
         FROM jsonb_array_elements(
           CASE WHEN jsonb_typeof(c.recipient_rules) = 'array' THEN c.recipient_rules ELSE '[]'::jsonb END) r
        WHERE (r->>'type') IS NOT NULL
          AND NOT ((r->>'type') IN (SELECT unnest(types) FROM supported))) AS bad_types,
      (SELECT count(*) FROM public.notification_event_channel_templates b
         JOIN public.notification_templates t ON t.id = b.template_id
        WHERE b.event_config_id = c.id AND t.status = 'active')::int AS bound,
      (SELECT count(*) FROM unnest(c.channels) x WHERE x IN ('in_app','email'))::int AS required,
      EXISTS (SELECT 1 FROM public.notification_dispatch_log l WHERE l.event_key = c.event_key) AS dispatched
    FROM public.notification_event_configs c
    WHERE c.is_active
  )
  SELECT
    b.event_key, b.module, b.severity::text, b.category::text, b.channels,
    b.rule_count, b.bad_types,
    EXISTS (SELECT 1 FROM unnest(b.channels) x WHERE x IN ('in_app','email')),
    b.bound, b.required, b.dispatched, b.dedupe_window_seconds,
    (b.failure_escalation IS NOT NULL AND b.failure_escalation <> '{}'::jsonb),
    b.fallback_allowed,
    (
      CASE WHEN b.rule_count = 0 THEN ARRAY['no_recipient_rules'] ELSE '{}'::text[] END
      || CASE WHEN array_length(b.bad_types, 1) IS NOT NULL THEN ARRAY['unsupported_rule_type'] ELSE '{}'::text[] END
      || CASE WHEN NOT EXISTS (SELECT 1 FROM unnest(b.channels) x WHERE x IN ('in_app','email')) THEN ARRAY['no_supported_channel'] ELSE '{}'::text[] END
      || CASE WHEN b.bound < b.required AND NOT b.fallback_allowed THEN ARRAY['template_not_bound'] ELSE '{}'::text[] END
      || CASE WHEN b.severity IS NULL THEN ARRAY['severity_missing'] ELSE '{}'::text[] END
      || CASE WHEN b.category IS NULL THEN ARRAY['category_missing'] ELSE '{}'::text[] END
      || CASE WHEN b.system_required AND b.allow_mute THEN ARRAY['mandatory_but_mutable'] ELSE '{}'::text[] END
      || CASE WHEN b.severity IN ('critical','high') AND b.delivery_frequency <> 'immediate' THEN ARRAY['high_severity_digested'] ELSE '{}'::text[] END
      || CASE WHEN b.dedupe_window_seconds < 0 THEN ARRAY['dedupe_window_invalid'] ELSE '{}'::text[] END
      || CASE WHEN NOT b.dispatched THEN ARRAY['no_trigger_history'] ELSE '{}'::text[] END
    )
  FROM base b
  ORDER BY b.event_key;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_event_queue_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END; $function$
;
CREATE OR REPLACE FUNCTION public.notification_export(_ids uuid[])
 RETURNS TABLE(created_at timestamp with time zone, severity text, category text, module text, type text, title text, message text, source_reference text, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.log_notification_audit(
    'NOTIFICATION_EXPORTED',
    COALESCE(_ids, ARRAY[]::uuid[]),
    jsonb_build_object('count', COALESCE(array_length(_ids, 1), 0))
  );

  RETURN QUERY
  SELECT n.created_at, n.severity::text, n.category::text, n.module, n.type,
         n.title, n.message, n.source_reference, n.status::text
  FROM public.notifications n
  WHERE n.user_id = auth.uid()
    AND n.id = ANY(COALESCE(_ids, ARRAY[]::uuid[]))
  ORDER BY n.created_at DESC;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_feed(_tab text DEFAULT 'all'::text, _module text DEFAULT NULL::text, _severity text DEFAULT NULL::text, _type text DEFAULT NULL::text, _status text DEFAULT NULL::text, _from timestamp with time zone DEFAULT NULL::timestamp with time zone, _to timestamp with time zone DEFAULT NULL::timestamp with time zone, _search text DEFAULT NULL::text, _cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _cursor_id uuid DEFAULT NULL::uuid, _limit integer DEFAULT 25)
 RETURNS SETOF notifications
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH params AS (
    SELECT
      auth.uid() AS uid,
      LEAST(GREATEST(COALESCE(_limit, 25), 1), 100) AS lim,
      CASE WHEN length(btrim(COALESCE(_search, ''))) >= 3
           THEN btrim(_search) END AS q
  )
  SELECT n.*
  FROM public.notifications n, params p
  WHERE n.user_id = p.uid
    AND n.channel = 'in_app'
    AND (n.expires_at IS NULL OR n.expires_at > now())
    -- tab semantics
    AND CASE COALESCE(_tab, 'all')
          WHEN 'unread'          THEN n.status = 'unread'
          WHEN 'action_required' THEN n.category = 'action_required'
                                      AND n.status NOT IN ('dismissed', 'archived')
          WHEN 'alerts'          THEN n.category = 'alert'
                                      AND n.status NOT IN ('dismissed', 'archived')
          WHEN 'system'          THEN n.category = 'system'
                                      AND n.status NOT IN ('dismissed', 'archived')
          WHEN 'archived'        THEN n.status IN ('dismissed', 'archived')
          ELSE n.status NOT IN ('dismissed', 'archived')
        END
    AND (_module IS NULL OR n.module = _module)
    AND (_severity IS NULL OR n.severity::text = _severity)
    AND (_type IS NULL OR n.type = _type)
    AND (_status IS NULL OR n.status::text = _status)
    AND (_from IS NULL OR n.created_at >= _from)
    AND (_to IS NULL OR n.created_at <= _to)
    AND (
      p.q IS NULL
      OR n.title ILIKE '%' || p.q || '%'
      OR n.message ILIKE '%' || p.q || '%'
      OR COALESCE(n.source_reference, '') ILIKE '%' || p.q || '%'
      OR COALESCE(n.entity_id, '') ILIKE '%' || p.q || '%'
    )
    AND (
      _cursor_created_at IS NULL
      OR (n.created_at, n.id) < (_cursor_created_at, COALESCE(_cursor_id, '00000000-0000-0000-0000-000000000000'::uuid))
    )
  ORDER BY n.created_at DESC, n.id DESC
  LIMIT (SELECT lim FROM params);
$function$
;
CREATE OR REPLACE FUNCTION public.notification_forward(_notification_id uuid, _to_user_id uuid, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_n public.notifications;
  v_thread_id uuid;
  v_reference text;
  v_from_name text;
  v_to_name text;
  v_to_email text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_n
  FROM public.notifications
  WHERE id = _notification_id AND user_id = v_uid;

  IF v_n.id IS NULL THEN
    RAISE EXCEPTION 'notification_not_found' USING ERRCODE = '42501';
  END IF;

  SELECT full_name INTO v_from_name FROM public.profiles WHERE id = v_uid;
  SELECT full_name, email INTO v_to_name, v_to_email FROM public.profiles WHERE id = _to_user_id;

  IF v_to_name IS NULL THEN
    RAISE EXCEPTION 'recipient_not_found' USING ERRCODE = '22023';
  END IF;

  v_reference := 'INT-' || to_char(now(), 'YYYY') || '-' || lpad((floor(random() * 1000000))::text, 6, '0');

  INSERT INTO public.correspondence_threads (
    reference, subject, summary, category, channel, direction, priority, status,
    sender_name, sender_email, thread_type, thread_state, source_type, source_id,
    source_reference, is_entity_facing, assigned_officer, assigned_officer_id,
    received_at, created_by
  ) VALUES (
    v_reference,
    'Forwarded: ' || v_n.title,
    COALESCE(v_n.preview, left(v_n.message, 160)),
    'internal',
    'internal',
    'internal',
    CASE WHEN v_n.severity::text IN ('critical', 'high') THEN 'high' ELSE 'normal' END,
    'open',
    COALESCE(v_from_name, 'Internal user'),
    NULL,
    'internal',
    'open',
    COALESCE(v_n.entity_type, 'notification'),
    NULL,
    COALESCE(v_n.source_reference, v_n.entity_id),
    false,
    v_to_name,
    _to_user_id,
    now(),
    v_uid
  )
  RETURNING id INTO v_thread_id;

  INSERT INTO public.correspondence_messages (
    thread_id, direction, channel, subject, body, is_internal_note,
    author_id, author_name, message_kind, is_draft, created_at
  ) VALUES (
    v_thread_id, 'internal', 'internal',
    'Forwarded: ' || v_n.title,
    COALESCE(_note || E'\n\n', '')
      || v_n.message
      || E'\n\n--\nForwarded notification: ' || v_n.id::text
      || COALESCE(E'\nSource reference: ' || v_n.source_reference, '')
      || COALESCE(E'\nSource record: ' || v_n.entity_type || ' ' || v_n.entity_id, ''),
    true, v_uid, COALESCE(v_from_name, 'Internal user'), 'note', true, now()
  );

  INSERT INTO public.notifications (
    user_id, title, message, type, channel, severity, category, module,
    action_required, entity_type, entity_id, source_reference, event_key, metadata
  ) VALUES (
    _to_user_id,
    'Notification forwarded to you',
    COALESCE(v_from_name, 'A colleague') || ' forwarded: ' || v_n.title,
    'info', 'in_app', 'medium', 'info', 'communications',
    false, 'correspondence_thread', v_thread_id::text, v_reference,
    'notification.forwarded',
    jsonb_build_object('forwarded_notification_id', v_n.id, 'from_user_id', v_uid)
  );

  PERFORM public.log_notification_audit(
    'NOTIFICATION_FORWARDED',
    ARRAY[_notification_id],
    jsonb_build_object('to_user_id', _to_user_id, 'thread_id', v_thread_id, 'reference', v_reference)
  );

  RETURN jsonb_build_object(
    'success', true,
    'thread_id', v_thread_id,
    'reference', v_reference,
    'route', '/correspondence/manager?thread=' || v_thread_id::text
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_global_template_tokens()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT ARRAY[
    'app_name', 'portal_name', 'support_email', 'cta_url', 'cta_label',
    'recipient_name', 'recipient_email', 'actor_name', 'actor_role',
    'entity_name', 'entity_type', 'entity_id', 'reference', 'source_reference',
    'status', 'previous_status', 'new_status', 'due_date', 'deadline',
    'comment', 'comments', 'remarks', 'reason', 'link', 'url', 'date', 'now',
    'step_name', 'previous_step_name', 'next_step_name', 'workflow_name',
    'severity', 'module', 'event_key', 'tier', 'sla_status'
  ]::text[];
$function$
;
CREATE OR REPLACE FUNCTION public.notification_history(_search text DEFAULT NULL::text, _channel text DEFAULT NULL::text, _status text DEFAULT NULL::text, _event_key text DEFAULT NULL::text, _from timestamp with time zone DEFAULT NULL::timestamp with time zone, _to timestamp with time zone DEFAULT NULL::timestamp with time zone, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, notification_id uuid, recipient_user_id uuid, recipient_name text, recipient_email text, event_key text, notification_type text, template_name text, channel text, status text, created_at timestamp with time zone, sent_at timestamp with time zone, failed_at timestamp with time zone, retry_count integer, error text, source_reference text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_q text := CASE WHEN length(btrim(COALESCE(_search, ''))) >= 3 THEN btrim(_search) END;
BEGIN
  PERFORM public.enforce_permission('notification_management', 'dispatch');

  RETURN QUERY
  SELECT d.id, d.notification_id, d.recipient_user_id,
         p.full_name, COALESCE(d.recipient_email, p.email),
         d.event_key, n.type, t.name, d.channel, d.status,
         d.created_at, d.sent_at, d.failed_at, COALESCE(d.retry_count, 0), d.error,
         COALESCE(n.source_reference, d.entity_id)
  FROM public.notification_dispatch_log d
  LEFT JOIN public.notifications n ON n.id = d.notification_id
  LEFT JOIN public.profiles p ON p.id = d.recipient_user_id
  LEFT JOIN public.notification_templates t ON t.id = d.template_id
  WHERE (_channel IS NULL OR d.channel = _channel)
    AND (_status IS NULL OR d.status = _status)
    AND (_event_key IS NULL OR d.event_key = _event_key)
    AND (_from IS NULL OR d.created_at >= _from)
    AND (_to IS NULL OR d.created_at <= _to)
    AND (
      v_q IS NULL
      OR COALESCE(p.full_name, '') ILIKE '%' || v_q || '%'
      OR COALESCE(d.recipient_email, '') ILIKE '%' || v_q || '%'
      OR COALESCE(d.event_key, '') ILIKE '%' || v_q || '%'
      OR COALESCE(n.source_reference, '') ILIKE '%' || v_q || '%'
      OR COALESCE(d.entity_id, '') ILIKE '%' || v_q || '%'
    )
  ORDER BY d.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(_limit, 50), 1), 200)
  OFFSET GREATEST(COALESCE(_offset, 0), 0);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_mark_actioned(_id uuid, _target text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  UPDATE public.notifications
    SET actioned_at = now(), read = true
  WHERE id = _id AND user_id = auth.uid();
  IF FOUND THEN
    PERFORM public.log_notification_audit('NOTIFICATION_ACTIONED', ARRAY[_id],
      jsonb_build_object('target', _target));
  END IF;
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_mark_all_read(_category notification_category DEFAULT NULL::notification_category)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  UPDATE public.notifications
    SET read = true
  WHERE user_id = auth.uid() AND read = false AND dismissed_at IS NULL
    AND (_category IS NULL OR category = _category);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN
    PERFORM public.log_notification_audit('NOTIFICATIONS_BULK_MARKED_READ', ARRAY[]::uuid[],
      jsonb_build_object('category', _category, 'count', n));
  END IF;
  RETURN n;
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_mark_read(_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  UPDATE public.notifications
    SET read = true
  WHERE id = ANY(_ids) AND user_id = auth.uid() AND read = false;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN
    PERFORM public.log_notification_audit(
      CASE WHEN array_length(_ids,1) > 1 THEN 'NOTIFICATIONS_BULK_MARKED_READ' ELSE 'NOTIFICATION_READ' END,
      _ids, '{}'::jsonb);
  END IF;
  RETURN n;
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_module_for(_event_key text, _entity_type text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN coalesce(_event_key,'') || coalesce(_entity_type,'') ~* '(licen|registration|appeal)' THEN 'licensing'
    WHEN coalesce(_event_key,'') || coalesce(_entity_type,'') ~* '(application|form|payment)' THEN 'applications'
    WHEN coalesce(_event_key,'') || coalesce(_entity_type,'') ~* '(fp_|fit_and_proper|fitandproper)' THEN 'fit_and_proper'
    WHEN coalesce(_event_key,'') || coalesce(_entity_type,'') ~* '(prudential|return|ratio|threshold)' THEN 'prudential'
    WHEN coalesce(_event_key,'') || coalesce(_entity_type,'') ~* '(complaint|conduct)' THEN 'conduct'
    WHEN coalesce(_event_key,'') || coalesce(_entity_type,'') ~* '(enforcement|inspection)' THEN 'enforcement'
    WHEN coalesce(_event_key,'') || coalesce(_entity_type,'') ~* '(report)' THEN 'reporting'
    WHEN coalesce(_event_key,'') || coalesce(_entity_type,'') ~* '(correspondence|thread|message)' THEN 'communications'
    ELSE 'system'
  END
$function$
;
CREATE OR REPLACE FUNCTION public.notification_preference_matrix()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  sms_ok boolean := public.notification_sms_available();
  rows jsonb;
  last_updated timestamptz;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'authentication_required';
  END IF;

  SELECT max(updated_at) INTO last_updated
  FROM public.notification_user_event_preferences WHERE user_id = uid;

  SELECT COALESCE(jsonb_agg(item ORDER BY item->>'module', item->>'name'), '[]'::jsonb) INTO rows
  FROM (
    SELECT jsonb_build_object(
      'event_key', c.event_key,
      'name', COALESCE(NULLIF(c.title_template, ''), replace(initcap(replace(c.event_key, '_', ' ')), '.', ' — ')),
      'module', public.notification_module_for(c.event_key, c.entity_type),
      'severity', c.severity::text,
      'description', c.description,
      'system_required', COALESCE(c.system_required, false),
      'allow_mute', COALESCE(c.allow_mute, true),
      'channels', to_jsonb(COALESCE(c.channels, ARRAY['in_app']::text[])),
      'in_app_enabled', COALESCE(p.in_app_enabled, true),
      'email_enabled', COALESCE(p.email_enabled, 'email' = ANY (COALESCE(c.channels, ARRAY[]::text[]))),
      'sms_enabled', COALESCE(p.sms_enabled, false) AND sms_ok,
      'digest_frequency', COALESCE(p.digest_frequency::text, 'immediate'),
      'muted', COALESCE(p.muted, false),
      'updated_at', p.updated_at,
      'locks', jsonb_strip_nulls(jsonb_build_object(
        'in_app', CASE
          WHEN c.severity = 'critical' THEN 'Critical alerts are always delivered in-app.'
          WHEN COALESCE(c.system_required, false) THEN 'This is a mandatory regulatory notification and cannot be disabled.'
          ELSE NULL END,
        'email', CASE
          WHEN COALESCE(c.system_required, false) THEN 'Mandatory notifications are always emailed.'
          WHEN NOT ('email' = ANY (COALESCE(c.channels, ARRAY[]::text[]))) THEN 'Email is not configured for this notification type.'
          ELSE NULL END,
        'sms', CASE
          WHEN NOT sms_ok THEN 'SMS delivery is not yet configured. Ask an administrator to enable an SMS provider in Settings → Email & SMS.'
          WHEN NOT ('sms' = ANY (COALESCE(c.channels, ARRAY[]::text[]))) THEN 'SMS is not configured for this notification type.'
          ELSE NULL END,
        'digest', CASE
          WHEN c.severity IN ('critical','high') THEN 'Critical and high urgency notifications are always sent immediately.'
          WHEN COALESCE(c.system_required, false) THEN 'Mandatory notifications are always sent immediately.'
          ELSE NULL END,
        'muted', CASE
          WHEN c.severity <> 'low' THEN 'Only low urgency notifications can be muted.'
          WHEN COALESCE(c.allow_mute, true) = false THEN 'This notification is configured as required and cannot be muted.'
          ELSE NULL END
      ))
    ) AS item
    FROM public.notification_event_configs c
    LEFT JOIN public.notification_user_event_preferences p
      ON p.event_key = c.event_key AND p.user_id = uid
    WHERE c.is_active
  ) s;

  RETURN jsonb_build_object(
    'sms_available', sms_ok,
    'last_updated_at', last_updated,
    'events', rows
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_preferences_save(_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  it jsonb;
  before_row public.notification_user_event_preferences;
  changes jsonb := '[]'::jsonb;
  changed int := 0;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'authentication_required';
  END IF;
  IF _items IS NULL OR jsonb_typeof(_items) <> 'array' THEN
    RAISE EXCEPTION 'invalid_payload: items array required';
  END IF;

  FOR it IN SELECT * FROM jsonb_array_elements(_items) LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.notification_event_configs
      WHERE event_key = it->>'event_key' AND is_active
    ) THEN
      RAISE EXCEPTION 'unknown_event_key: %', it->>'event_key';
    END IF;

    SELECT * INTO before_row FROM public.notification_user_event_preferences
    WHERE user_id = uid AND event_key = it->>'event_key';

    INSERT INTO public.notification_user_event_preferences AS t
      (user_id, event_key, in_app_enabled, email_enabled, sms_enabled, digest_frequency, muted, updated_by)
    VALUES (
      uid,
      it->>'event_key',
      COALESCE((it->>'in_app_enabled')::boolean, true),
      COALESCE((it->>'email_enabled')::boolean, false),
      COALESCE((it->>'sms_enabled')::boolean, false),
      COALESCE(NULLIF(it->>'digest_frequency',''), 'immediate')::public.notification_digest_frequency,
      COALESCE((it->>'muted')::boolean, false),
      uid
    )
    ON CONFLICT (user_id, event_key) DO UPDATE SET
      in_app_enabled = EXCLUDED.in_app_enabled,
      email_enabled = EXCLUDED.email_enabled,
      sms_enabled = EXCLUDED.sms_enabled,
      digest_frequency = EXCLUDED.digest_frequency,
      muted = EXCLUDED.muted,
      updated_by = uid;

    changed := changed + 1;
    changes := changes || jsonb_build_array(jsonb_build_object(
      'event_key', it->>'event_key',
      'before', CASE WHEN before_row.id IS NULL THEN NULL ELSE jsonb_build_object(
        'in_app_enabled', before_row.in_app_enabled,
        'email_enabled', before_row.email_enabled,
        'sms_enabled', before_row.sms_enabled,
        'digest_frequency', before_row.digest_frequency::text,
        'muted', before_row.muted) END,
      'after', jsonb_build_object(
        'in_app_enabled', COALESCE((it->>'in_app_enabled')::boolean, true),
        'email_enabled', COALESCE((it->>'email_enabled')::boolean, false),
        'sms_enabled', COALESCE((it->>'sms_enabled')::boolean, false),
        'digest_frequency', COALESCE(NULLIF(it->>'digest_frequency',''), 'immediate'),
        'muted', COALESCE((it->>'muted')::boolean, false))
    ));
  END LOOP;

  IF changed > 0 THEN
    INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata, old_value, new_value)
    VALUES (uid, 'NOTIFICATION_PREFERENCES_UPDATED', 'notification_preference', uid::text,
            jsonb_build_object('count', changed),
            jsonb_build_object('changes', changes),
            jsonb_build_object('changes', changes));
  END IF;

  RETURN jsonb_build_object(
    'updated', changed,
    'last_updated_at', (SELECT max(updated_at) FROM public.notification_user_event_preferences WHERE user_id = uid)
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_recent_cron_failures(_since_minutes integer DEFAULT 60)
 RETURNS TABLE(jobname text, end_time timestamp with time zone, return_message text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
  SELECT j.jobname::text, d.end_time, d.return_message
    FROM cron.job_run_details d
    JOIN cron.job j ON j.jobid = d.jobid
   WHERE d.status = 'failed'
     AND d.end_time > now() - make_interval(mins => GREATEST(1, COALESCE(_since_minutes, 60)))
   ORDER BY d.end_time DESC
   LIMIT 50;
$function$
;
