CREATE OR REPLACE FUNCTION public.notification_recipient_rules_validate(_rules jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  vocab jsonb := public.notification_recipient_rule_types();
  errs jsonb := '[]'::jsonb;
  rule jsonb;
  spec jsonb;
  req text;
  idx int := 0;
BEGIN
  PERFORM public.notification_admin_guard('view');
  IF _rules IS NULL OR jsonb_typeof(_rules) <> 'array' OR jsonb_array_length(_rules) = 0 THEN
    RETURN jsonb_build_object('valid', false, 'errors',
      jsonb_build_array(jsonb_build_object('index', -1, 'error', 'at least one recipient rule is required')));
  END IF;

  FOR rule IN SELECT jsonb_array_elements(_rules) LOOP
    SELECT s INTO spec FROM jsonb_array_elements(vocab) AS s
      WHERE s->>'type' = rule->>'type' LIMIT 1;
    IF spec IS NULL THEN
      errs := errs || jsonb_build_array(jsonb_build_object(
        'index', idx, 'error', format('unsupported recipient rule type "%s" — the delivery engine cannot execute it', COALESCE(rule->>'type','(none)'))));
    ELSE
      FOR req IN SELECT jsonb_array_elements_text(spec->'requires') LOOP
        IF COALESCE(rule->>req, '') = '' THEN
          errs := errs || jsonb_build_array(jsonb_build_object(
            'index', idx, 'error', format('rule "%s" requires "%s"', rule->>'type', req)));
        END IF;
      END LOOP;
      IF rule->>'type' = 'role' OR rule->>'type' = 'next_step_role' THEN
        IF COALESCE(rule->>'role','') <> '' AND NOT EXISTS (
          SELECT 1 FROM public.roles r WHERE r.name = rule->>'role' OR r.id::text = rule->>'role'
        ) THEN
          errs := errs || jsonb_build_array(jsonb_build_object(
            'index', idx, 'error', format('role "%s" does not exist', rule->>'role')));
        END IF;
      END IF;
      IF rule->>'type' = 'named_user' AND COALESCE(rule->>'user_id','') <> '' THEN
        IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id::text = rule->>'user_id') THEN
          errs := errs || jsonb_build_array(jsonb_build_object(
            'index', idx, 'error', 'named user does not exist'));
        END IF;
      END IF;
      IF rule->>'type' = 'regulator_team' AND COALESCE(rule->>'regulator_id','') <> '' THEN
        IF NOT EXISTS (SELECT 1 FROM public.regulators g WHERE g.id::text = rule->>'regulator_id') THEN
          errs := errs || jsonb_build_array(jsonb_build_object(
            'index', idx, 'error', 'regulator does not exist'));
        END IF;
      END IF;
      IF rule->>'type' = 'direct_email' AND COALESCE(rule->>'email','') !~* '^[^@\s]+@[^@\s]+\.[a-z]{2,}$' THEN
        errs := errs || jsonb_build_array(jsonb_build_object(
          'index', idx, 'error', 'custom email is not a valid address'));
      END IF;
    END IF;
    idx := idx + 1;
  END LOOP;

  RETURN jsonb_build_object('valid', jsonb_array_length(errs) = 0, 'errors', errs);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_recipients_for_role(_role text)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT ur.user_id FROM public.user_roles ur WHERE ur.role::text = _role
  UNION
  SELECT udr.user_id FROM public.user_dynamic_roles udr
    JOIN public.roles r ON r.id = udr.role_id WHERE r.system_role = _role;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_record_delivery(_event_key text, _channel text, _status text, _notification_id uuid DEFAULT NULL::uuid, _recipient_user_id uuid DEFAULT NULL::uuid, _recipient_email text DEFAULT NULL::text, _recipient_phone text DEFAULT NULL::text, _provider text DEFAULT NULL::text, _subject text DEFAULT NULL::text, _rendered_content text DEFAULT NULL::text, _template_id uuid DEFAULT NULL::uuid, _template_version integer DEFAULT NULL::integer, _provider_message_id text DEFAULT NULL::text, _error_details jsonb DEFAULT NULL::jsonb, _dedupe_key text DEFAULT NULL::text, _entity_type text DEFAULT NULL::text, _entity_id text DEFAULT NULL::text, _payload jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE row_id uuid;
BEGIN
  INSERT INTO public.notification_dispatch_log (
    event_key, channel, status, notification_id, recipient_user_id, recipient_email, recipient_phone,
    provider, subject, rendered_content, template_id, template_version, provider_message_id,
    error_details, error, dedupe_key, entity_type, entity_id, payload,
    queued_at, sent_at, delivered_at, failed_at, last_attempt_at
  ) VALUES (
    _event_key, _channel, _status, _notification_id, _recipient_user_id, _recipient_email, _recipient_phone,
    _provider, _subject, _rendered_content, _template_id, _template_version, _provider_message_id,
    _error_details, _error_details->>'message',
    COALESCE(_dedupe_key, _event_key || ':' || COALESCE(_recipient_user_id::text, _recipient_email, 'none') || ':' || _channel || ':' || gen_random_uuid()::text),
    _entity_type, _entity_id, _payload,
    now(),
    CASE WHEN _status IN ('sent','delivered') THEN now() END,
    CASE WHEN _status = 'delivered' THEN now() END,
    CASE WHEN _status IN ('failed','bounced') THEN now() END,
    now()
  )
  RETURNING id INTO row_id;

  IF _status IN ('sent','delivered') THEN
    PERFORM public.log_notification_audit('NOTIFICATION_SENT', ARRAY[_notification_id]::uuid[],
      jsonb_build_object('event_key', _event_key, 'channel', _channel, 'delivery_id', row_id));
  ELSIF _status IN ('failed','bounced') THEN
    PERFORM public.log_notification_audit('NOTIFICATION_DELIVERY_FAILED', ARRAY[_notification_id]::uuid[],
      jsonb_build_object('event_key', _event_key, 'channel', _channel, 'delivery_id', row_id, 'error', _error_details));
  END IF;

  RETURN row_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.notification_render(_text text, _vars jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  out_text text := COALESCE(_text, '');
  k text;
BEGIN
  FOR k IN SELECT jsonb_object_keys(COALESCE(_vars, '{}'::jsonb)) LOOP
    out_text := replace(out_text, '{{' || k || '}}', COALESCE(_vars->>k, ''));
    out_text := replace(out_text, '{{ ' || k || ' }}', COALESCE(_vars->>k, ''));
  END LOOP;
  RETURN out_text;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_route_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(NEW.source_route, '') = '' THEN
    NEW.source_route := public.notification_source_route(NEW.entity_type, NEW.entity_id);
  END IF;
  NEW.route_status := CASE
    WHEN coalesce(NEW.source_route, '') <> '' THEN 'resolved'
    ELSE 'legacy_no_route'
  END;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_severity_for(_event_key text, _type text)
 RETURNS notification_severity
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _event_key ~* '(breach|revoked|suspended|failed|failure|critical|enforcement|system_health)' THEN 'critical'
    WHEN _event_key ~* '(escalat|overdue|rejected|adverse|warning|expiring|near_due|sla)' THEN 'high'
    WHEN _event_key ~* '(rfi|approval|assigned|submitted|resubmit|payment|due|reminder|comment|appeal)' THEN 'medium'
    WHEN _type = 'error' THEN 'critical'
    WHEN _type = 'warning' THEN 'high'
    WHEN _type = 'success' THEN 'low'
    ELSE 'medium'
  END::public.notification_severity
$function$
;
CREATE OR REPLACE FUNCTION public.notification_sms_available()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((
    SELECT (value -> 'sms' ->> 'enabled')::boolean
           AND COALESCE(NULLIF(value -> 'sms' ->> 'senderId', ''), NULL) IS NOT NULL
    FROM public.site_settings
    WHERE key = 'email_sms_settings'
    LIMIT 1
  ), false)
$function$
;
CREATE OR REPLACE FUNCTION public.notification_source_route(_entity_type text, _entity_id text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _entity_type IS NULL OR coalesce(_entity_id, '') = '' THEN NULL
    WHEN _entity_id !~ '^[A-Za-z0-9._-]+$' THEN NULL
    ELSE (
      SELECT CASE lower(_entity_type)
        WHEN 'application'            THEN '/applications/'   || _entity_id
        WHEN 'applications'           THEN '/applications/'   || _entity_id
        WHEN 'registration'           THEN '/admin/registrations/' || _entity_id
        WHEN 'license'                THEN '/licenses/'       || _entity_id
        WHEN 'licensee'               THEN '/admin/licensees/' || _entity_id
        WHEN 'license_appeal'         THEN '/admin/license-appeals?appeal=' || _entity_id
        WHEN 'return'                 THEN '/returns-mgmt/'   || _entity_id
        WHEN 'return_filed'           THEN '/returns-mgmt/'   || _entity_id
        WHEN 'returns_filed'          THEN '/returns-mgmt/'   || _entity_id
        WHEN 'compliance_return'      THEN '/compliance/'     || _entity_id
        WHEN 'complaint'              THEN '/complaints/'     || _entity_id
        WHEN 'correspondence'         THEN '/correspondence/manager?thread=' || _entity_id
        WHEN 'correspondence_thread'  THEN '/correspondence/manager?thread=' || _entity_id
        WHEN 'escalation'             THEN '/escalations?escalation=' || _entity_id
        WHEN 'fp_individual'          THEN '/fit-and-proper/individuals/' || _entity_id
        WHEN 'fp_assessment'          THEN '/fit-and-proper/assessments/' || _entity_id
        WHEN 'prudential_assessment'  THEN '/prudential/assessments/' || _entity_id
        WHEN 'enforcement_action'     THEN '/enforcement/'    || _entity_id
        WHEN 'inspection'             THEN '/inspections/'    || _entity_id
        WHEN 'payment'                THEN '/payments/'       || _entity_id
        WHEN 'report'                 THEN '/reports/'        || _entity_id
        WHEN 'form_template'          THEN '/admin/forms/'    || _entity_id
        ELSE NULL
      END
    )
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_template_archive(_template_id uuid, _archive boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t public.notification_templates;
  bound int;
BEGIN
  PERFORM public.notification_admin_guard('manage_templates');
  SELECT * INTO t FROM public.notification_templates WHERE id = _template_id FOR UPDATE;
  IF t.id IS NULL THEN RAISE EXCEPTION 'template_not_found'; END IF;

  IF _archive THEN
    SELECT count(*) INTO bound
      FROM public.notification_event_channel_templates b
      JOIN public.notification_event_configs c ON c.id = b.event_config_id
     WHERE b.template_id = t.id AND c.is_active;
    IF bound > 0 THEN
      RAISE EXCEPTION 'template_in_use: unbind from % active event configuration(s) first', bound;
    END IF;
    UPDATE public.notification_templates
       SET status = 'archived', is_active = false, archived_at = now(),
           updated_by = auth.uid(), updated_at = now()
     WHERE id = t.id;
    PERFORM public.notification_admin_audit('notification_template_archived', 'notification_template', t.id::text,
      NULL, jsonb_build_object('template_code', t.template_code));
    RETURN jsonb_build_object('status', 'archived');
  END IF;

  UPDATE public.notification_templates
     SET status = CASE WHEN published_version IS NOT NULL THEN 'active' ELSE 'draft' END,
         is_active = published_version IS NOT NULL,
         archived_at = NULL, updated_by = auth.uid(), updated_at = now()
   WHERE id = t.id;
  PERFORM public.notification_admin_audit('notification_template_updated', 'notification_template', t.id::text,
    NULL, jsonb_build_object('unarchived', true));
  RETURN jsonb_build_object('status', 'restored');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_template_clone(_template_id uuid, _new_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t public.notification_templates;
  new_id uuid;
  new_code text;
BEGIN
  PERFORM public.notification_admin_guard('manage_templates');
  SELECT * INTO t FROM public.notification_templates WHERE id = _template_id;
  IF t.id IS NULL THEN RAISE EXCEPTION 'template_not_found'; END IF;

  new_code := COALESCE(t.template_code, 'TPL') || '_COPY_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 4);

  INSERT INTO public.notification_templates (
    name, template_code, module, event_key, event_type, channel, severity,
    subject, body, variables, status, version, published_version, is_active,
    regulator_id, created_by, updated_by
  ) VALUES (
    COALESCE(NULLIF(_new_name, ''), t.name || ' (copy)'), new_code, t.module, t.event_key, t.event_type,
    t.channel, t.severity, t.subject, t.body, COALESCE(t.variables, '[]'::jsonb),
    'draft', 1, NULL, false, t.regulator_id, auth.uid(), auth.uid()
  ) RETURNING id INTO new_id;

  PERFORM public.notification_admin_audit('notification_template_created', 'notification_template', new_id::text,
    NULL, jsonb_build_object('cloned_from', t.id, 'template_code', new_code));
  RETURN new_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_template_placeholder_check(_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t public.notification_templates;
  used text[];
  declared text[];
  unsupported text[];
BEGIN
  SELECT * INTO t FROM public.notification_templates WHERE id = _template_id;
  IF t.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'template_not_found');
  END IF;

  used := public.notification_template_placeholders(coalesce(t.subject, '') || ' ' || coalesce(t.body, ''));
  SELECT coalesce(array_agg(v), ARRAY[]::text[]) INTO declared
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(coalesce(t.variables, '[]'::jsonb)) = 'array'
           THEN t.variables ELSE '[]'::jsonb END
    ) AS v;

  SELECT coalesce(array_agg(u), ARRAY[]::text[]) INTO unsupported
    FROM unnest(used) AS u
   WHERE NOT (u = ANY(declared))
     AND NOT (u = ANY(public.notification_global_template_tokens()));

  RETURN jsonb_build_object(
    'ok', coalesce(array_length(unsupported, 1), 0) = 0,
    'template_id', t.id,
    'used', to_jsonb(used),
    'declared', to_jsonb(declared),
    'unsupported', to_jsonb(unsupported)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_template_placeholders(_text text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(array_agg(DISTINCT m[1]), ARRAY[]::text[])
  FROM regexp_matches(coalesce(_text, ''), '\{\{\s*([\w.]+)\s*\}\}', 'g') AS m;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_template_publish(_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t public.notification_templates;
  next_version integer;
  chk jsonb;
BEGIN
  PERFORM public.notification_admin_guard('manage_templates');
  SELECT * INTO t FROM public.notification_templates WHERE id = _template_id FOR UPDATE;
  IF t.id IS NULL THEN RAISE EXCEPTION 'template_not_found'; END IF;
  IF COALESCE(t.subject, '') = '' AND t.channel <> 'in_app' THEN RAISE EXCEPTION 'subject_required'; END IF;
  IF COALESCE(t.body, '') = '' THEN RAISE EXCEPTION 'body_required'; END IF;

  -- Placeholder contract: refuse to publish wording that uses tokens the
  -- template does not declare and that are not standard system tokens.
  chk := public.notification_template_placeholder_check(t.id);
  IF NOT (chk->>'ok')::boolean THEN
    RAISE EXCEPTION 'unsupported_placeholder: %', chk->>'unsupported';
  END IF;

  -- Refuse wording that renders to nothing once tokens are stripped.
  IF t.channel <> 'in_app'
     AND btrim(regexp_replace(COALESCE(t.subject, ''), '\{\{[^}]*\}\}', '', 'g')) = '' THEN
    RAISE EXCEPTION 'subject_renders_blank';
  END IF;
  IF btrim(regexp_replace(COALESCE(t.body, ''), '\{\{[^}]*\}\}', '', 'g')) = '' THEN
    RAISE EXCEPTION 'body_renders_blank';
  END IF;

  next_version := COALESCE(t.published_version, 0) + 1;

  INSERT INTO public.notification_template_versions (
    template_id, version, template_code, name, module, event_key, channel, severity,
    subject, body, variables, content_hash, published_by
  ) VALUES (
    t.id, next_version, t.template_code, t.name, t.module, t.event_key, t.channel, t.severity,
    t.subject, t.body, COALESCE(t.variables, '[]'::jsonb),
    md5(COALESCE(t.subject,'') || '|' || COALESCE(t.body,'')), auth.uid()
  );

  UPDATE public.notification_templates
     SET status = 'active', is_active = true, version = next_version,
         published_version = next_version, archived_at = NULL,
         updated_by = auth.uid(), updated_at = now()
   WHERE id = t.id;

  PERFORM public.notification_admin_audit('notification_template_published', 'notification_template', t.id::text,
    NULL, jsonb_build_object('version', next_version, 'template_code', t.template_code));

  RETURN jsonb_build_object('template_id', t.id, 'version', next_version, 'status', 'active');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_template_render_preview(_template_id uuid, _sample jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t public.notification_templates;
  vars jsonb;
  v text;
  subj text;
  body text;
BEGIN
  PERFORM public.notification_admin_guard('view');
  SELECT * INTO t FROM public.notification_templates WHERE id = _template_id;
  IF t.id IS NULL THEN RAISE EXCEPTION 'template_not_found'; END IF;

  -- safe sample values: declared variables get placeholder text unless supplied
  vars := COALESCE(_sample, '{}'::jsonb);
  IF jsonb_typeof(t.variables) = 'array' THEN
    FOR v IN SELECT jsonb_array_elements_text(t.variables) LOOP
      IF NOT vars ? v THEN
        vars := vars || jsonb_build_object(v, '[' || v || ']');
      END IF;
    END LOOP;
  END IF;
  vars := vars
    || jsonb_build_object('app_name', COALESCE(vars->>'app_name', 'Regulator Portal'))
    || jsonb_build_object('app_url', COALESCE(vars->>'app_url', 'https://portal.example'));

  subj := public.notification_render(t.subject, vars);
  body := public.notification_render(t.body, vars);

  RETURN jsonb_build_object(
    'template_id', t.id,
    'template_code', t.template_code,
    'channel', t.channel,
    'severity', t.severity,
    'subject', subj,
    'body', body,
    'sample_values', vars,
    'unresolved_tokens', to_jsonb(
      public.notification_unresolved_tokens(COALESCE(subj, '') || ' ' || COALESCE(body, ''))
    )
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_template_save(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  tid uuid := NULLIF(_payload->>'id', '')::uuid;
  before_row jsonb;
  code text := NULLIF(_payload->>'template_code', '');
  chan text := COALESCE(NULLIF(_payload->>'channel',''), 'email');
BEGIN
  PERFORM public.notification_admin_guard('manage_templates');

  IF chan NOT IN ('in_app','email','sms') THEN
    RAISE EXCEPTION 'invalid_channel: %', chan;
  END IF;
  IF COALESCE(_payload->>'name','') = '' THEN RAISE EXCEPTION 'name_required'; END IF;
  IF COALESCE(_payload->>'event_key','') = '' THEN RAISE EXCEPTION 'event_key_required'; END IF;

  IF tid IS NULL THEN
    code := COALESCE(code, upper(regexp_replace(_payload->>'event_key', '[^a-zA-Z0-9]+', '_', 'g'))
              || '_' || upper(chan) || '_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));
    INSERT INTO public.notification_templates (
      name, template_code, module, event_key, event_type, channel, severity,
      subject, body, variables, status, version, is_active, created_by, updated_by
    ) VALUES (
      _payload->>'name', code,
      COALESCE(NULLIF(_payload->>'module',''), split_part(_payload->>'event_key', '.', 1)),
      _payload->>'event_key', _payload->>'event_key', chan,
      COALESCE(NULLIF(_payload->>'severity','')::notification_severity, 'medium'),
      _payload->>'subject', _payload->>'body',
      COALESCE(_payload->'variables', '[]'::jsonb),
      'draft', 1, false, auth.uid(), auth.uid()
    ) RETURNING id INTO tid;

    PERFORM public.notification_admin_audit('notification_template_created', 'notification_template', tid::text,
      NULL, jsonb_build_object('name', _payload->>'name', 'template_code', code, 'channel', chan));
    RETURN tid;
  END IF;

  SELECT to_jsonb(t) INTO before_row FROM public.notification_templates t WHERE t.id = tid;
  IF before_row IS NULL THEN RAISE EXCEPTION 'template_not_found'; END IF;
  IF before_row->>'status' = 'archived' THEN RAISE EXCEPTION 'template_archived: unarchive before editing'; END IF;

  UPDATE public.notification_templates SET
    name = _payload->>'name',
    module = COALESCE(NULLIF(_payload->>'module',''), split_part(_payload->>'event_key', '.', 1)),
    event_key = _payload->>'event_key',
    event_type = _payload->>'event_key',
    channel = chan,
    severity = COALESCE(NULLIF(_payload->>'severity','')::notification_severity, severity),
    subject = _payload->>'subject',
    body = _payload->>'body',
    variables = COALESCE(_payload->'variables', variables),
    template_code = COALESCE(code, template_code),
    updated_by = auth.uid(),
    updated_at = now()
  WHERE id = tid;

  PERFORM public.notification_admin_audit('notification_template_updated', 'notification_template', tid::text,
    before_row, (SELECT to_jsonb(t) FROM public.notification_templates t WHERE t.id = tid));
  RETURN tid;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_template_snapshot(_template_id uuid, _actor uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t public.notification_templates;
  v integer;
BEGIN
  SELECT * INTO t FROM public.notification_templates WHERE id = _template_id;
  IF t.id IS NULL THEN
    RAISE EXCEPTION 'template_not_found';
  END IF;

  v := COALESCE(t.published_version, t.version, 1);

  IF EXISTS (SELECT 1 FROM public.notification_template_versions
              WHERE template_id = t.id AND version = v) THEN
    RETURN v;
  END IF;

  INSERT INTO public.notification_template_versions
    (template_id, version, template_code, name, module, event_key, channel,
     severity, subject, body, variables, content_hash, published_by)
  VALUES
    (t.id, v, t.template_code, t.name, t.module, COALESCE(t.event_key, t.event_type), t.channel,
     t.severity, t.subject, t.body, t.variables,
     md5(COALESCE(t.subject, '') || '::' || COALESCE(t.body, '')), _actor);

  UPDATE public.notification_templates
     SET published_version = v, status = 'active'
   WHERE id = t.id;

  RETURN v;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_template_versions_for(_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE res jsonb;
BEGIN
  PERFORM public.notification_admin_guard('view');
  SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.version DESC), '[]'::jsonb) INTO res
  FROM (
    SELECT v.id, v.version, v.name, v.channel, v.severity, v.subject, v.body, v.variables,
           v.content_hash, v.published_at, v.published_by,
           COALESCE(p.full_name, p.email, 'System') AS published_by_name
      FROM public.notification_template_versions v
      LEFT JOIN public.profiles p ON p.id = v.published_by
     WHERE v.template_id = _template_id
  ) x;
  RETURN res;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_template_versions_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'template_version_immutable: published notification template versions cannot be modified or deleted';
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_test_send(_template_id uuid, _sample jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  preview jsonb;
  t public.notification_templates;
  nid uuid;
BEGIN
  PERFORM public.notification_admin_guard('test_send');
  SELECT * INTO t FROM public.notification_templates WHERE id = _template_id;
  IF t.id IS NULL THEN RAISE EXCEPTION 'template_not_found'; END IF;

  preview := public.notification_template_render_preview(_template_id, _sample);

  -- Test notifications are always delivered to the requesting administrator only.
  INSERT INTO public.notifications (
    user_id, title, message, type, channel, severity, category,
    event_key, template_id, template_version, delivery_status, metadata
  ) VALUES (
    auth.uid(),
    '[TEST] ' || COALESCE(NULLIF(preview->>'subject', ''), t.name),
    COALESCE(preview->>'body', ''),
    'info', 'in_app', t.severity, 'system',
    t.event_key, t.id, t.published_version, 'delivered',
    jsonb_build_object('test_send', true, 'requested_by', auth.uid(),
                       'unresolved_tokens', preview->'unresolved_tokens')
  ) RETURNING id INTO nid;

  PERFORM public.notification_admin_audit('notification_test_sent', 'notification_template', t.id::text,
    NULL, jsonb_build_object('notification_id', nid, 'channel', t.channel,
                             'recipient', auth.uid(), 'unresolved_tokens', preview->'unresolved_tokens'));

  RETURN jsonb_build_object(
    'ok', true, 'notification_id', nid, 'recipient_user_id', auth.uid(),
    'channel_delivered', 'in_app',
    'unresolved_tokens', preview->'unresolved_tokens',
    'subject', preview->>'subject', 'body', preview->>'body'
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_unresolved_tokens(_text text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(array_agg(DISTINCT trim(m[1])), ARRAY[]::text[])
  FROM regexp_matches(COALESCE(_text, ''), '\{\{\s*([a-zA-Z0-9_\.]+)\s*\}\}', 'g') AS m;
$function$
;
CREATE OR REPLACE FUNCTION public.notification_worker_kick(_function_name text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_token text;
  v_req bigint;
BEGIN
  v_token := public.issue_worker_token(_function_name);
  SELECT net.http_post(
    url := 'https://sndfttzqmbkmkcnrvpfn.supabase.co/functions/v1/' || _function_name,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-worker-token', v_token),
    body := jsonb_build_object('triggered_by', 'cron', 'at', now())
  ) INTO v_req;
  RETURN v_req;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'notification_worker_kick(%) failed: %', _function_name, SQLERRM;
  RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.notifications_block_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL OR current_user NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'notifications_cannot_be_deleted';
  END IF;
  RETURN OLD;
END $function$
;
CREATE OR REPLACE FUNCTION public.notifications_guard_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- System / service paths (no end-user session) may write freely.
  IF auth.uid() IS NULL OR current_user IN ('service_role','postgres','supabase_admin') THEN
    RETURN NEW;
  END IF;

  IF NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.title IS DISTINCT FROM OLD.title
     OR NEW.message IS DISTINCT FROM OLD.message
     OR NEW.preview IS DISTINCT FROM OLD.preview
     OR NEW.severity IS DISTINCT FROM OLD.severity
     OR NEW.category IS DISTINCT FROM OLD.category
     OR NEW.module IS DISTINCT FROM OLD.module
     OR NEW.type IS DISTINCT FROM OLD.type
     OR NEW.event_key IS DISTINCT FROM OLD.event_key
     OR NEW.template_id IS DISTINCT FROM OLD.template_id
     OR NEW.template_version IS DISTINCT FROM OLD.template_version
     OR NEW.rendered_content_ref IS DISTINCT FROM OLD.rendered_content_ref
     OR NEW.entity_type IS DISTINCT FROM OLD.entity_type
     OR NEW.entity_id IS DISTINCT FROM OLD.entity_id
     OR NEW.source_reference IS DISTINCT FROM OLD.source_reference
     OR NEW.source_route IS DISTINCT FROM OLD.source_route
     OR NEW.system_required IS DISTINCT FROM OLD.system_required
     OR NEW.action_required IS DISTINCT FROM OLD.action_required
     OR NEW.correlation_id IS DISTINCT FROM OLD.correlation_id
     OR NEW.dedupe_key IS DISTINCT FROM OLD.dedupe_key
     OR NEW.channel IS DISTINCT FROM OLD.channel
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'notification_field_immutable';
  END IF;

  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.notifications_sync_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.preview IS NULL THEN
    NEW.preview := left(regexp_replace(COALESCE(NEW.message,''), '\s+', ' ', 'g'), 160);
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Legacy writers flip `read`; new writers set `status`.
    IF NEW.status = OLD.status THEN
      IF NEW.dismissed_at IS NOT NULL AND OLD.dismissed_at IS NULL THEN
        NEW.status := 'dismissed';
      ELSIF NEW.archived_at IS NOT NULL AND OLD.archived_at IS NULL THEN
        NEW.status := 'archived';
      ELSIF NEW.actioned_at IS NOT NULL AND OLD.actioned_at IS NULL THEN
        NEW.status := 'actioned';
      ELSIF NEW.read AND NOT OLD.read THEN
        NEW.status := 'read';
      END IF;
    END IF;
  END IF;

  IF NEW.status IN ('read','actioned','dismissed','archived') THEN
    NEW.read := true;
    NEW.read_at := COALESCE(NEW.read_at, now());
  END IF;
  IF NEW.status = 'actioned' THEN NEW.actioned_at := COALESCE(NEW.actioned_at, now()); END IF;
  IF NEW.status = 'dismissed' THEN NEW.dismissed_at := COALESCE(NEW.dismissed_at, now()); END IF;
  IF NEW.status = 'archived' THEN NEW.archived_at := COALESCE(NEW.archived_at, now()); END IF;

  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.notify_application_rfi_deadlines()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; n integer := 0; v_ref text;
BEGIN
  FOR r IN
    SELECT id, application_id, due_at, summary
    FROM public.application_rfis
    WHERE due_at IS NOT NULL
      AND lower(coalesce(status, '')) NOT IN ('closed', 'resolved', 'withdrawn')
  LOOP
    SELECT application_number INTO v_ref FROM public.applications WHERE id = r.application_id;
    IF r.due_at < now() THEN
      PERFORM public.notif_enqueue(
        'application.rfi_overdue', 'application', r.application_id, v_ref,
        '/applications/' || r.application_id,
        jsonb_build_object('application_number', coalesce(v_ref, ''), 'rfi_id', r.id,
                           'due_at', r.due_at, 'summary', coalesce(r.summary, '')),
        'overdue:' || r.id::text, to_char(current_date, 'YYYY-MM-DD')
      );
      UPDATE public.application_rfis SET overdue_notified_at = now() WHERE id = r.id;
      n := n + 1;
    ELSIF r.due_at <= now() + interval '2 days' THEN
      PERFORM public.notif_enqueue(
        'application.rfi_near_due', 'application', r.application_id, v_ref,
        '/applications/' || r.application_id,
        jsonb_build_object('application_number', coalesce(v_ref, ''), 'rfi_id', r.id,
                           'due_at', r.due_at, 'summary', coalesce(r.summary, '')),
        'near_due:' || r.id::text, to_char(current_date, 'YYYY-MM-DD')
      );
      UPDATE public.application_rfis SET near_due_notified_at = now() WHERE id = r.id;
      n := n + 1;
    END IF;
  END LOOP;
  RETURN n;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notify_overdue_complaint_investigations()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; n integer := 0;
BEGIN
  FOR r IN
    SELECT t.id AS task_id, t.title, t.due_date, c.id AS complaint_id, c.complaint_number,
           c.investigator_id, c.licensee_id
    FROM public.complaint_investigation_tasks t
    JOIN public.complaints c ON c.id = t.complaint_id
    WHERE t.due_date < current_date
      AND coalesce(t.status,'open') NOT IN ('completed','cancelled','closed')
      AND coalesce(c.status,'') NOT IN ('closed','resolved')
  LOOP
    PERFORM public.notification_enqueue_event('complaint.investigation_overdue', 'complaint', r.complaint_id,
      jsonb_build_object('complaint_id', r.complaint_id, 'complaint_number', r.complaint_number,
        'investigator_id', r.investigator_id, 'licensee_id', r.licensee_id,
        'task_title', r.title, 'due_date', r.due_date,
        'cta_url', '/complaints/' || r.complaint_id, 'cta_label', 'Open complaint'),
      r.task_id::text, NULL, current_date::text);
    n := n + 1;
  END LOOP;
  RETURN n;
END $function$
;
