CREATE OR REPLACE FUNCTION public.onboarding_evaluate_alert_rules(_event_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  e public.entity_identity_resolution_events;
  r public.onboarding_alert_rules;
  v_n integer;
BEGIN
  SELECT * INTO e FROM public.entity_identity_resolution_events WHERE id = _event_id;
  IF e.id IS NULL THEN RETURN; END IF;

  FOR r IN SELECT * FROM public.onboarding_alert_rules WHERE is_active LOOP
    v_n := NULL;
    IF r.condition_type = 'SEARCH_VOLUME_PER_USER' THEN
      SELECT count(*) INTO v_n FROM public.entity_identity_resolution_events
       WHERE user_id = e.user_id AND occurred_at > now() - make_interval(mins => r.window_minutes);
    ELSIF r.condition_type = 'DISTINCT_USERS_PER_NAME' THEN
      SELECT count(DISTINCT user_id) INTO v_n FROM public.entity_identity_resolution_events
       WHERE normalized_legal_name = e.normalized_legal_name
         AND occurred_at > now() - make_interval(mins => r.window_minutes);
    ELSIF r.condition_type = 'REPEATED_FAILURE' THEN
      SELECT count(*) INTO v_n FROM public.entity_identity_resolution_events
       WHERE user_id = e.user_id AND resolution_outcome IN ('NO_MATCH','VALIDATION_FAILURE','SYSTEM_ERROR','ERROR')
         AND occurred_at > now() - make_interval(mins => r.window_minutes);
    ELSIF r.condition_type = 'REPEATED_POSSIBLE_MATCH' THEN
      SELECT count(*) INTO v_n FROM public.entity_identity_resolution_events
       WHERE user_id = e.user_id AND resolution_outcome = 'POSSIBLE_MATCH'
         AND occurred_at > now() - make_interval(mins => r.window_minutes);
    END IF;

    IF v_n IS NOT NULL AND r.threshold_count IS NOT NULL AND v_n >= r.threshold_count THEN
      INSERT INTO public.onboarding_alert_signals (rule_key, severity, user_id, identification_event_id, subject_name, detail)
      VALUES (r.rule_key, r.severity, e.user_id, e.id, e.searched_legal_name,
              jsonb_build_object('observed', v_n, 'threshold', r.threshold_count, 'window_minutes', r.window_minutes));
    END IF;
  END LOOP;
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_form_first_resolve(_registration_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE reg public.registrations;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  SELECT * INTO reg FROM public.registrations WHERE id = _registration_id;
  IF reg.id IS NULL THEN RAISE EXCEPTION 'Registration not found' USING ERRCODE='22023'; END IF;
  IF reg.user_id <> auth.uid() AND NOT (public.is_internal_staff(auth.uid()) OR public.is_super_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE='42501';
  END IF;
  RETURN public.onboarding_form_first_resolve_internal(_registration_id);
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_form_first_resolve_internal(_registration_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  reg public.registrations;
  v_payload jsonb;
  v_raw jsonb;
  v_event uuid;
  v_entity uuid;
  v_case uuid;
  v_status text;
  v_prov jsonb;
  v_existing public.registration_entity_bindings;
BEGIN
  SELECT * INTO reg FROM public.registrations WHERE id = _registration_id;
  IF reg.id IS NULL THEN RAISE EXCEPTION 'Registration not found' USING ERRCODE='22023'; END IF;

  -- Service-path invocation (public registration submission): the applicant has
  -- no session yet, so act explicitly as the registration owner for the
  -- duration of this transaction. Governed resolution/provisioning functions
  -- then attribute every audit record to the applicant.
  IF auth.uid() IS NULL THEN
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', reg.user_id::text, 'role', 'authenticated')::text, true);
  END IF;

  SELECT * INTO v_existing FROM public.registration_entity_bindings WHERE registration_id = _registration_id;
  IF v_existing.id IS NOT NULL AND v_existing.entity_id IS NOT NULL THEN
    RETURN jsonb_build_object('outcome','ALREADY_BOUND','entity_bound',true,'binding_status',v_existing.binding_status);
  END IF;

  v_payload := jsonb_build_object(
    'legal_name', reg.applicant_name,
    'identifiers', COALESCE(reg.entity_specific_data->'identifiers','[]'::jsonb),
    'license_number', NULLIF(reg.entity_specific_data->>'license_number',''),
    'sector_id', reg.sector_id::text,
    'journey_type', 'FORM_FIRST');

  BEGIN
    v_raw := public.entity_resolve_identity(v_payload);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.onboarding_log_identification_event(
      reg.user_id, 'FORM_FIRST', 'PUBLIC_REGISTRATION', v_payload, 'SYSTEM_ERROR', NULL, NULL, '[]'::jsonb, NULL, SQLERRM);
    RAISE;
  END;

  v_entity := NULLIF(v_raw->>'entity_id','')::uuid;
  v_case := NULLIF(v_raw->>'case_id','')::uuid;

  v_event := public.onboarding_log_identification_event(
    reg.user_id, 'FORM_FIRST', 'PUBLIC_REGISTRATION', v_payload, COALESCE(v_raw->>'outcome','NO_MATCH'),
    v_entity, v_case, COALESCE(v_raw->'candidates','[]'::jsonb), v_raw->>'match_basis', NULL);

  IF (v_raw->>'outcome') = 'EXACT_MATCH' THEN
    v_status := 'BOUND_EXISTING';
  ELSIF (v_raw->>'outcome') = 'POSSIBLE_MATCH' THEN
    v_status := 'PENDING_RESOLUTION';
  ELSE
    v_prov := public.wb_onboarding_provision_entity(v_payload || jsonb_build_object('case_id', v_case));
    v_entity := (v_prov->>'entity_id')::uuid;
    v_status := 'BOUND_PROVISIONAL';
    PERFORM public.onboarding_record_journey_event(reg.user_id, 'PROVISIONAL_ENTITY_CREATED', 'FORM_FIRST',
      v_entity, _registration_id, v_event, jsonb_build_object('legal_name', reg.applicant_name));
  END IF;

  INSERT INTO public.registration_entity_bindings
    (registration_id, entity_id, resolution_case_id, identification_event_id, binding_status, bound_at)
  VALUES (_registration_id, v_entity, v_case, v_event, v_status,
          CASE WHEN v_entity IS NOT NULL THEN now() END)
  ON CONFLICT (registration_id) DO UPDATE
    SET entity_id = COALESCE(EXCLUDED.entity_id, public.registration_entity_bindings.entity_id),
        resolution_case_id = COALESCE(EXCLUDED.resolution_case_id, public.registration_entity_bindings.resolution_case_id),
        identification_event_id = EXCLUDED.identification_event_id,
        binding_status = EXCLUDED.binding_status,
        bound_at = COALESCE(EXCLUDED.bound_at, public.registration_entity_bindings.bound_at),
        updated_at = now();

  PERFORM public.onboarding_record_follow_up(
    CASE WHEN v_status = 'PENDING_RESOLUTION' THEN 'CONTINUE_FORM_FIRST' ELSE 'CONTINUES_APPLICATION' END,
    jsonb_build_object('registration_id', _registration_id, 'binding_status', v_status), v_event, reg.user_id);

  RETURN jsonb_build_object(
    'outcome', v_raw->>'outcome',
    'binding_status', v_status,
    'entity_bound', v_entity IS NOT NULL,
    'case_reference', v_raw->>'case_number',
    'event_reference', (SELECT event_reference FROM public.entity_identity_resolution_events WHERE id = v_event));
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_form_first_resolve_service(_registration_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN public.onboarding_form_first_resolve_internal(_registration_id);
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_identification_activity(_filters jsonb DEFAULT '{}'::jsonb, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, event_reference text, occurred_at timestamp with time zone, user_id uuid, user_email text, journey_type text, source_channel text, searched_legal_name text, identifier_type text, identifier_value_masked text, licence_number_masked text, resolution_outcome text, matched_entity_id uuid, matched_entity_name text, candidate_count integer, highest_match_score numeric, match_basis text, follow_up_action text, follow_up_at timestamp with time zone, resolution_case_id uuid, resolution_case_number text, failure_reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.onboarding_can_view_audit(auth.uid()) THEN
    RAISE EXCEPTION 'Not permitted to read onboarding audit activity' USING ERRCODE='42501';
  END IF;
  RETURN QUERY
  SELECT e.id, e.event_reference, e.occurred_at, e.user_id,
         COALESCE(p.email, plu.email) AS user_email,
         e.journey_type, e.source_channel, e.searched_legal_name, e.identifier_type,
         e.identifier_value_masked, e.licence_number_masked, e.resolution_outcome,
         e.matched_entity_id, l.name, e.candidate_count,
         e.highest_match_score, e.match_basis, e.follow_up_action, e.follow_up_at,
         e.resolution_case_id, rc.case_number, e.failure_reason
    FROM public.entity_identity_resolution_events e
    LEFT JOIN public.profiles p ON p.id = e.user_id
    LEFT JOIN public.pre_license_users plu ON plu.id = e.user_id
    LEFT JOIN public.licensees l ON l.id = e.matched_entity_id
    LEFT JOIN public.entity_resolution_cases rc ON rc.id = e.resolution_case_id
   WHERE (_filters->>'from' IS NULL OR e.occurred_at >= (_filters->>'from')::timestamptz)
     AND (_filters->>'to' IS NULL OR e.occurred_at <= (_filters->>'to')::timestamptz)
     AND (NULLIF(_filters->>'journey_type','') IS NULL OR e.journey_type = _filters->>'journey_type')
     AND (NULLIF(_filters->>'outcome','') IS NULL OR e.resolution_outcome = _filters->>'outcome')
     AND (NULLIF(_filters->>'follow_up_action','') IS NULL OR e.follow_up_action = _filters->>'follow_up_action')
     AND (NULLIF(_filters->>'regulator_id','') IS NULL OR e.regulator_id = (_filters->>'regulator_id')::uuid)
     AND (NULLIF(_filters->>'resolution_case_id','') IS NULL OR e.resolution_case_id = (_filters->>'resolution_case_id')::uuid)
     AND (NULLIF(_filters->>'organisation','') IS NULL OR e.searched_legal_name ILIKE '%' || (_filters->>'organisation') || '%'
          OR e.normalized_legal_name = upper(regexp_replace(_filters->>'organisation','[^A-Za-z0-9]','','g')))
     AND (NULLIF(_filters->>'user','') IS NULL
          OR COALESCE(p.email, plu.email) ILIKE '%' || (_filters->>'user') || '%')
   ORDER BY e.occurred_at DESC
   LIMIT GREATEST(COALESCE(_limit,50),1) OFFSET GREATEST(COALESCE(_offset,0),0);
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_identification_activity_counts(_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT public.onboarding_can_view_audit(auth.uid()) THEN
    RAISE EXCEPTION 'Not permitted to read onboarding audit activity' USING ERRCODE='42501';
  END IF;
  SELECT jsonb_build_object(
    'total', count(*),
    'exact_match', count(*) FILTER (WHERE resolution_outcome='EXACT_MATCH'),
    'possible_match', count(*) FILTER (WHERE resolution_outcome='POSSIBLE_MATCH'),
    'no_match', count(*) FILTER (WHERE resolution_outcome='NO_MATCH'),
    'failures', count(*) FILTER (WHERE resolution_outcome IN ('SYSTEM_ERROR','ERROR','VALIDATION_FAILURE','PROVIDER_UNAVAILABLE')),
    'open_signals', (SELECT count(*) FROM public.onboarding_alert_signals WHERE status='open'))
    INTO v
  FROM public.onboarding_identification_activity(_filters, 100000, 0);
  RETURN v;
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_identifier_catalogue()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'generated_at', now(),
    'identifier_types', COALESCE(jsonb_agg(jsonb_build_object(
        'key', t.key,
        'label', t.label,
        'description', t.description,
        'issuer_hint', t.issuer,
        'uniqueness_scope', t.uniqueness_scope,
        'requires_jurisdiction', COALESCE(t.scope_requires_jurisdiction,false),
        'requires_issuer', COALESCE(t.scope_requires_issuer,false),
        'requires_regulator', COALESCE(t.scope_requires_regulator,false),
        'is_unique_global', COALESCE(t.is_unique_global,false),
        'normalization', t.normalization_strategy,
        'validation_regex', t.validation_regex,
        'is_required', COALESCE(t.is_unique_global,false) AND COALESCE(t.is_system,false),
        'sort_order', COALESCE(t.sort_order, 999)
      ) ORDER BY COALESCE(t.sort_order,999), t.label), '[]'::jsonb))
  FROM public.entity_identifier_types t
  WHERE t.is_active;
$function$
;
CREATE OR REPLACE FUNCTION public.onboarding_issue_token(_kind text, _entity_id uuid, _case_id uuid, _payload jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_token text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  v_token := _kind || '_' || replace(gen_random_uuid()::text, '-', '');
  INSERT INTO public.onboarding_resolution_tokens (token, user_id, token_kind, entity_id, case_id, payload)
  VALUES (v_token, auth.uid(), _kind, _entity_id, _case_id, COALESCE(_payload,'{}'::jsonb));
  RETURN v_token;
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_journey_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE j public.onboarding_journey_state; v_status text; v_name text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('stage','USER_ACCOUNT'); END IF;
  SELECT * INTO j FROM public.onboarding_journey_state WHERE user_id = auth.uid();
  IF j.id IS NULL THEN RETURN jsonb_build_object('stage','USER_ACCOUNT'); END IF;

  SELECT m.status INTO v_status FROM public.entity_user_memberships m WHERE m.id = j.membership_id;
  SELECT COALESCE(o.legal_name, l.name) INTO v_name
    FROM public.licensees l LEFT JOIN public.organizations o ON o.party_id = l.party_id
   WHERE l.id = j.entity_id;

  RETURN jsonb_build_object(
    'stage', CASE WHEN v_status = 'APPROVED' AND j.stage = 'AUTHORITY_PENDING' THEN 'AUTHORITY_GRANTED' ELSE j.stage END,
    'membership_status', v_status,
    'entity_display_name', v_name,
    'intended_journey', j.intended_journey,
    'resume_route', COALESCE(j.intended_route, '/applications/new'),
    'updated_at', j.updated_at);
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_ledger_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(current_setting('app.onboarding_ledger_writer', true),'') <> 'on' THEN
    RAISE EXCEPTION 'Onboarding audit ledger is append-only and may only be written by governed onboarding operations'
      USING ERRCODE='42501';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Onboarding audit ledger rows cannot be deleted' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_log_identification_event(_user_id uuid, _journey_type text, _source_channel text, _payload jsonb, _outcome text, _matched_entity_id uuid DEFAULT NULL::uuid, _resolution_case_id uuid DEFAULT NULL::uuid, _candidates jsonb DEFAULT '[]'::jsonb, _match_basis text DEFAULT NULL::text, _failure_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_id uuid;
  v_ids jsonb := COALESCE(_payload->'identifiers','[]'::jsonb);
  v_first jsonb := CASE WHEN jsonb_array_length(COALESCE(_payload->'identifiers','[]'::jsonb)) > 0 THEN (_payload->'identifiers')->0 ELSE NULL END;
  v_name text := btrim(COALESCE(_payload->>'legal_name',''));
  v_cand_ids uuid[] := '{}';
  v_top numeric;
  v_journey uuid;
  c jsonb;
BEGIN
  SELECT id INTO v_journey FROM public.onboarding_journey_state WHERE user_id = _user_id;

  FOR c IN SELECT jsonb_array_elements(COALESCE(_candidates,'[]'::jsonb)) LOOP
    IF NULLIF(c->>'entity_id','') IS NOT NULL THEN
      v_cand_ids := v_cand_ids || (c->>'entity_id')::uuid;
    END IF;
    v_top := GREATEST(COALESCE(v_top, 0), COALESCE((c->>'match_score')::numeric, 0));
  END LOOP;

  PERFORM set_config('app.onboarding_ledger_writer','on', true);
  INSERT INTO public.entity_identity_resolution_events (
    event_reference, user_id, journey_id, journey_type, source_channel,
    searched_legal_name, normalized_legal_name, identifier_type, identifier_value_masked,
    identifier_value_hash, licence_number_masked, regulator_id, sector_id,
    resolution_outcome, matched_entity_id, resolution_case_id, candidate_entity_ids,
    candidate_count, highest_match_score, match_basis, resolver_version,
    request_correlation_id, failure_reason
  ) VALUES (
    'EIA-' || to_char(now(),'YYYY') || '-' || lpad(nextval('public.entity_identification_event_seq')::text, 6, '0'),
    _user_id, v_journey, _journey_type, COALESCE(NULLIF(_source_channel,''),'PUBLIC_REGISTRATION'),
    NULLIF(v_name,''), NULLIF(upper(regexp_replace(v_name, '[^A-Za-z0-9]', '', 'g')),''),
    NULLIF(v_first->>'type',''), public.onboarding_mask_value(v_first->>'value'),
    CASE WHEN NULLIF(v_first->>'value','') IS NULL THEN NULL
         ELSE encode(extensions.digest(upper(regexp_replace(v_first->>'value','[^A-Za-z0-9]','','g')),'sha256'),'hex') END,
    public.onboarding_mask_value(_payload->>'license_number'),
    NULLIF(_payload->>'regulator_id','')::uuid, NULLIF(_payload->>'sector_id','')::uuid,
    _outcome, _matched_entity_id, _resolution_case_id, v_cand_ids,
    COALESCE(jsonb_array_length(COALESCE(_candidates,'[]'::jsonb)),0), v_top, _match_basis, '1.0',
    NULLIF(_payload->>'correlation_id',''), _failure_reason
  ) RETURNING id INTO v_id;

  PERFORM public.onboarding_record_journey_event(
    _user_id, 'ENTITY_SEARCHED', _journey_type, _matched_entity_id, NULL, v_id,
    jsonb_build_object('outcome', _outcome, 'match_basis', _match_basis));

  IF _outcome = 'EXACT_MATCH' THEN
    PERFORM public.onboarding_record_journey_event(_user_id, 'ENTITY_MATCHED', _journey_type, _matched_entity_id, NULL, v_id, jsonb_build_object('match_basis', _match_basis));
  ELSIF _outcome = 'POSSIBLE_MATCH' THEN
    PERFORM public.onboarding_record_journey_event(_user_id, 'ENTITY_RESOLUTION_REQUIRED', _journey_type, NULL, NULL, v_id, jsonb_build_object('resolution_case_id', _resolution_case_id));
  END IF;

  PERFORM public.onboarding_evaluate_alert_rules(v_id);
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_mask_value(_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _value IS NULL OR btrim(_value) = '' THEN NULL
    WHEN length(btrim(_value)) <= 4 THEN repeat('*', greatest(length(btrim(_value)) - 1, 1)) || right(btrim(_value), 1)
    ELSE repeat('*', length(btrim(_value)) - 4) || right(btrim(_value), 4)
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.onboarding_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT (public.onboarding_can_view_audit(auth.uid()) OR public.is_internal_staff(auth.uid()) OR public.is_super_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE='42501';
  END IF;
  SELECT jsonb_build_object(
    'journeys_active', (SELECT count(*) FROM public.onboarding_journey_state WHERE stage NOT IN ('COMPLETE')),
    'identification_events_7d', (SELECT count(*) FROM public.entity_identity_resolution_events WHERE occurred_at > now() - interval '7 days'),
    'resolution_cases_open', (SELECT count(*) FROM public.entity_resolution_cases WHERE status NOT IN ('RESOLVED','CLOSED','resolved','closed')),
    'access_requests_pending', (SELECT count(*) FROM public.entity_user_memberships WHERE status IN ('REQUESTED','VERIFIED','PENDING')),
    'open_signals', (SELECT count(*) FROM public.onboarding_alert_signals WHERE status='open'))
  INTO v;
  RETURN v;
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_provision_from_token(_resolution_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.onboarding_resolution_tokens; v_res jsonb; v_entity uuid; v_event uuid;
BEGIN
  r := public.onboarding_redeem_token(_resolution_token, ARRAY['resolution']);
  v_res := public.wb_onboarding_provision_entity(r.payload || jsonb_build_object('case_id', r.case_id));
  v_entity := (v_res->>'entity_id')::uuid;
  UPDATE public.onboarding_resolution_tokens SET consumed_at = now() WHERE id = r.id;

  v_event := NULLIF(r.payload->>'identification_event_id','')::uuid;
  PERFORM public.onboarding_record_follow_up('PROVISIONS_NEW_ENTITY',
    jsonb_build_object('entity_id', v_entity), v_event, auth.uid());
  PERFORM public.onboarding_record_journey_event(auth.uid(), 'PROVISIONAL_ENTITY_CREATED', 'ENTITY_FIRST',
    v_entity, NULL, v_event, jsonb_build_object('legal_name', r.payload->>'legal_name'));

  RETURN jsonb_build_object(
    'membership_target_token', public.onboarding_issue_token('membership_target', v_entity, r.case_id,
        jsonb_build_object('identification_event_id', v_event)),
    'entity_display', jsonb_build_object('legal_name', r.payload->>'legal_name'));
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_record_follow_up(_action text, _detail jsonb DEFAULT '{}'::jsonb, _event_id uuid DEFAULT NULL::uuid, _user_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := COALESCE(_user_id, auth.uid()); v_event uuid := _event_id; v_journey text;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  IF _action IS NULL OR btrim(_action) = '' THEN RETURN NULL; END IF;

  IF v_event IS NULL THEN
    SELECT id INTO v_event FROM public.entity_identity_resolution_events
     WHERE user_id = v_uid ORDER BY occurred_at DESC LIMIT 1;
  END IF;

  SELECT journey_type INTO v_journey FROM public.entity_identity_resolution_events WHERE id = v_event;

  IF v_event IS NOT NULL THEN
    PERFORM set_config('app.onboarding_ledger_writer','on', true);
    UPDATE public.entity_identity_resolution_events
       SET follow_up_action = _action, follow_up_at = now()
     WHERE id = v_event AND follow_up_action IS DISTINCT FROM _action;
  END IF;

  RETURN public.onboarding_record_journey_event(v_uid, _action, v_journey, NULL, NULL, v_event, COALESCE(_detail,'{}'::jsonb));
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_record_journey_event(_user_id uuid, _stage text, _journey_type text DEFAULT NULL::text, _entity_id uuid DEFAULT NULL::uuid, _registration_id uuid DEFAULT NULL::uuid, _identification_event_id uuid DEFAULT NULL::uuid, _detail jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  PERFORM set_config('app.onboarding_ledger_writer','on', true);
  INSERT INTO public.registration_journey_events
    (event_reference, user_id, journey_type, stage, entity_id, registration_id, identification_event_id, detail, actor_id)
  VALUES ('RJE-' || to_char(now(),'YYYY') || '-' || lpad(nextval('public.registration_journey_event_seq')::text, 6, '0'),
          _user_id, _journey_type, _stage, _entity_id, _registration_id, _identification_event_id,
          COALESCE(_detail,'{}'::jsonb), auth.uid())
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_redeem_token(_token text, _kinds text[])
 RETURNS onboarding_resolution_tokens
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.onboarding_resolution_tokens;
BEGIN
  SELECT * INTO r FROM public.onboarding_resolution_tokens
   WHERE token = _token AND user_id = auth.uid() LIMIT 1;
  IF r.id IS NULL THEN RAISE EXCEPTION 'Invalid onboarding reference' USING ERRCODE='42501'; END IF;
  IF r.expires_at < now() THEN RAISE EXCEPTION 'Onboarding reference expired — please identify the entity again' USING ERRCODE='22023'; END IF;
  IF NOT (r.token_kind = ANY(_kinds)) THEN RAISE EXCEPTION 'Onboarding reference not valid for this step' USING ERRCODE='22023'; END IF;
  RETURN r;
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_request_membership_by_token(_token text, _membership_role_key text, _authority_evidence_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.onboarding_resolution_tokens; v_membership uuid; v_status text; v_stage text; v_route text; v_event uuid; v_primary boolean;
BEGIN
  r := public.onboarding_redeem_token(_token, ARRAY['membership_target','candidate']);
  IF r.entity_id IS NULL THEN RAISE EXCEPTION 'This reference has no entity to link' USING ERRCODE='22023'; END IF;

  v_membership := public.entity_membership_request(r.entity_id, _membership_role_key, _authority_evidence_reference);
  SELECT status INTO v_status FROM public.entity_user_memberships WHERE id = v_membership;

  v_stage := CASE WHEN v_status = 'APPROVED' THEN 'AUTHORITY_GRANTED' ELSE 'AUTHORITY_PENDING' END;

  UPDATE public.onboarding_journey_state
     SET stage = v_stage, entity_id = r.entity_id, membership_id = v_membership
   WHERE user_id = auth.uid()
   RETURNING intended_route INTO v_route;

  IF NOT FOUND THEN
    INSERT INTO public.onboarding_journey_state (user_id, stage, entity_id, membership_id)
    VALUES (auth.uid(), v_stage, r.entity_id, v_membership)
    RETURNING intended_route INTO v_route;
  END IF;

  UPDATE public.onboarding_resolution_tokens SET consumed_at = now() WHERE id = r.id;

  v_event := NULLIF(r.payload->>'identification_event_id','')::uuid;
  IF r.token_kind = 'candidate' THEN
    PERFORM public.onboarding_record_follow_up('SELECTS_CANDIDATE', jsonb_build_object('entity_id', r.entity_id), v_event, auth.uid());
  END IF;
  PERFORM public.onboarding_record_follow_up('REQUESTS_MEMBERSHIP',
    jsonb_build_object('membership_id', v_membership, 'role_key', _membership_role_key, 'status', v_status), v_event, auth.uid());
  PERFORM public.onboarding_record_journey_event(auth.uid(), 'MEMBERSHIP_REQUESTED', NULL, r.entity_id, NULL, v_event,
    jsonb_build_object('membership_id', v_membership, 'role_key', _membership_role_key));
  IF v_status = 'APPROVED' THEN
    PERFORM public.onboarding_record_journey_event(auth.uid(), 'MEMBERSHIP_APPROVED', NULL, r.entity_id, NULL, v_event,
      jsonb_build_object('membership_id', v_membership));
  END IF;

  SELECT COALESCE(is_primary_representative,false) INTO v_primary
    FROM public.entity_membership_roles WHERE key = _membership_role_key;
  IF COALESCE(v_primary,false) AND EXISTS (SELECT 1 FROM public.onboarding_alert_rules WHERE rule_key='PRIMARY_REPRESENTATIVE_REQUEST' AND is_active) THEN
    INSERT INTO public.onboarding_alert_signals (rule_key, severity, user_id, identification_event_id, subject_name, detail)
    VALUES ('PRIMARY_REPRESENTATIVE_REQUEST','high', auth.uid(), v_event, NULL,
            jsonb_build_object('entity_id', r.entity_id, 'role_key', _membership_role_key));
  END IF;

  RETURN jsonb_build_object(
    'membership_status', v_status,
    'authority_sufficient', v_status = 'APPROVED',
    'stage', v_stage,
    'resume_route', COALESCE(v_route, CASE WHEN v_status = 'APPROVED' THEN '/applications/new' ELSE '/register/authority-pending' END));
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_resolve_entity(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_raw jsonb;
  v_cands jsonb := '[]'::jsonb;
  c jsonb;
  v_entity uuid;
  v_token text;
  v_uid uuid := auth.uid();
  v_journey text := COALESCE(NULLIF(_payload->>'journey_type',''), 'ENTITY_FIRST');
  v_channel text := COALESCE(NULLIF(_payload->>'source_channel',''), 'PUBLIC_REGISTRATION');
  v_event uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;

  IF btrim(COALESCE(_payload->>'legal_name','')) = '' THEN
    PERFORM public.onboarding_log_identification_event(
      v_uid, v_journey, v_channel, _payload, 'VALIDATION_FAILURE',
      NULL, NULL, '[]'::jsonb, NULL, 'legal_name is required');
    RAISE EXCEPTION 'legal_name is required' USING ERRCODE='22023';
  END IF;

  BEGIN
    v_raw := public.entity_resolve_identity(_payload);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.onboarding_log_identification_event(
      v_uid, v_journey, v_channel, _payload, 'SYSTEM_ERROR',
      NULL, NULL, '[]'::jsonb, NULL, SQLERRM);
    RAISE;
  END;

  INSERT INTO public.onboarding_journey_state (user_id, stage, intended_journey, intended_route, context)
  VALUES (v_uid, 'ENTITY_IDENTIFICATION',
          COALESCE(NULLIF(_payload->>'intended_journey',''), v_journey), NULLIF(_payload->>'intended_route',''),
          jsonb_build_object('legal_name', _payload->>'legal_name', 'journey_type', v_journey))
  ON CONFLICT (user_id) DO UPDATE
    SET stage = CASE WHEN public.onboarding_journey_state.stage IN ('AUTHORITY_GRANTED','APPLICATION','COMPLETE')
                     THEN public.onboarding_journey_state.stage ELSE 'ENTITY_IDENTIFICATION' END,
        intended_journey = COALESCE(NULLIF(EXCLUDED.intended_journey,''), public.onboarding_journey_state.intended_journey),
        intended_route = COALESCE(NULLIF(EXCLUDED.intended_route,''), public.onboarding_journey_state.intended_route),
        context = public.onboarding_journey_state.context || EXCLUDED.context;

  v_event := public.onboarding_log_identification_event(
    v_uid, v_journey, v_channel, _payload, COALESCE(v_raw->>'outcome','NO_MATCH'),
    NULLIF(v_raw->>'entity_id','')::uuid, NULLIF(v_raw->>'case_id','')::uuid,
    COALESCE(v_raw->'candidates','[]'::jsonb), v_raw->>'match_basis', NULL);

  IF (v_raw->>'outcome') = 'EXACT_MATCH' THEN
    v_entity := (v_raw->>'entity_id')::uuid;
    v_token := public.onboarding_issue_token('membership_target', v_entity, NULL,
                 jsonb_build_object('match_basis', v_raw->>'match_basis', 'identification_event_id', v_event));
    RETURN jsonb_build_object(
      'outcome', 'EXACT_MATCH',
      'match_basis', v_raw->>'match_basis',
      'event_reference', (SELECT event_reference FROM public.entity_identity_resolution_events WHERE id = v_event),
      'membership_target_token', v_token,
      'entity_display', jsonb_build_object(
          'legal_name', COALESCE(v_raw->'entity'->>'legal_name', v_raw->'entity'->>'name'),
          'status', v_raw->'entity'->>'status'),
      'candidates', '[]'::jsonb);
  END IF;

  FOR c IN SELECT jsonb_array_elements(COALESCE(v_raw->'candidates','[]'::jsonb)) LOOP
    v_cands := v_cands || jsonb_build_array(jsonb_build_object(
      'candidate_token', public.onboarding_issue_token('candidate',
          NULLIF(c->>'entity_id','')::uuid, NULLIF(v_raw->>'case_id','')::uuid,
          jsonb_build_object('identification_event_id', v_event)),
      'legal_name', c->>'legal_name',
      'match_score', c->'match_score',
      'match_basis', c->>'match_basis'));
  END LOOP;

  RETURN jsonb_build_object(
    'outcome', v_raw->>'outcome',
    'case_reference', v_raw->>'case_number',
    'event_reference', (SELECT event_reference FROM public.entity_identity_resolution_events WHERE id = v_event),
    'resolution_token', public.onboarding_issue_token('resolution', NULL,
        NULLIF(v_raw->>'case_id','')::uuid, _payload || jsonb_build_object('identification_event_id', v_event)),
    'candidates', v_cands);
END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END $function$
;
CREATE OR REPLACE FUNCTION public.onboarding_user_journey_events(_user_id uuid)
 RETURNS TABLE(event_reference text, occurred_at timestamp with time zone, stage text, journey_type text, entity_id uuid, detail jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF _user_id <> auth.uid() AND NOT public.onboarding_can_view_audit(auth.uid()) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE='42501';
  END IF;
  RETURN QUERY
  SELECT e.event_reference, e.occurred_at, e.stage, e.journey_type, e.entity_id, e.detail
    FROM public.registration_journey_events e
   WHERE e.user_id = _user_id
   ORDER BY e.occurred_at DESC LIMIT 500;
END $function$
;
CREATE OR REPLACE FUNCTION public.party_subtype_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_kind text; v_expected text := CASE TG_TABLE_NAME WHEN 'organizations' THEN 'ORGANIZATION' ELSE 'PERSON' END;
BEGIN
  SELECT party_kind INTO v_kind FROM public.parties WHERE id = NEW.party_id;
  IF v_kind IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Party % is % and cannot be stored as %', NEW.party_id, COALESCE(v_kind,'unknown'), TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.payment_incident_record(_operator_id uuid, _incident_type text, _title text, _occurred_at timestamp with time zone, _notification_received_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _severity text DEFAULT 'medium'::text, _description text DEFAULT NULL::text, _affected_transactions bigint DEFAULT NULL::bigint, _affected_value numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hours numeric;
  v_delay numeric;
  v_breach boolean := false;
  v_id uuid;
  v_ref text;
  v_op public.payment_system_operators;
BEGIN
  IF NOT (public.can_act_on_payment_oversight(auth.uid(), 'create')
          OR public.can_act_on_payment_oversight(auth.uid(), 'edit')) THEN
    RAISE EXCEPTION 'not_authorised_for_payment_oversight';
  END IF;

  SELECT * INTO v_op FROM public.payment_system_operators WHERE id = _operator_id;
  IF v_op.id IS NULL THEN RAISE EXCEPTION 'operator_not_found'; END IF;

  SELECT incident_notification_hours INTO v_hours FROM public.payment_oversight_config WHERE id = 1;
  v_hours := COALESCE(v_hours, 2);

  IF _notification_received_at IS NOT NULL THEN
    v_delay := EXTRACT(EPOCH FROM (_notification_received_at - _occurred_at)) / 60.0;
    v_breach := v_delay > (v_hours * 60);
  END IF;

  INSERT INTO public.payment_system_incidents (
    operator_id, incident_type, title, description, severity, occurred_at,
    notification_received_at, affected_transactions, affected_value,
    notification_delay_minutes, sla_breached, created_by)
  VALUES (_operator_id, _incident_type, _title, _description, COALESCE(_severity,'medium'),
          _occurred_at, _notification_received_at, _affected_transactions, _affected_value,
          v_delay, v_breach, auth.uid())
  RETURNING id, reference INTO v_id, v_ref;

  INSERT INTO public.payment_oversight_events (operator_id, incident_id, event_type, actor_id, metadata)
  VALUES (_operator_id, v_id, 'INCIDENT_RECORDED', auth.uid(),
          jsonb_build_object('reference', v_ref, 'severity', _severity, 'sla_breached', v_breach));

  IF v_breach THEN
    INSERT INTO public.payment_oversight_events (operator_id, incident_id, event_type, actor_id, metadata)
    VALUES (_operator_id, v_id, 'INCIDENT_NOTIFICATION_SLA_BREACH', auth.uid(),
            jsonb_build_object('delay_minutes', round(v_delay), 'window_hours', v_hours));

    PERFORM public.notification_enqueue_event(
      'prudential.payment_incident_late_notification', 'payment_incident', v_id,
      jsonb_build_object('incident_id', v_id, 'reference', v_ref,
        'operator_id', _operator_id, 'operator_name', v_op.operator_name,
        'entity_id', v_op.entity_id, 'delay_minutes', round(v_delay),
        'window_hours', v_hours, 'severity', COALESCE(_severity,'medium'),
        'cta_url', '/prudential/payment-systems?tab=incidents',
        'cta_label', 'Open incident register'),
      'late');
  END IF;

  RETURN jsonb_build_object('ok', true, 'incident_id', v_id, 'reference', v_ref, 'sla_breached', v_breach);
END $function$
;
CREATE OR REPLACE FUNCTION public.payment_incident_resolve(_incident_id uuid, _notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_i public.payment_system_incidents;
BEGIN
  IF NOT (public.can_act_on_payment_oversight(auth.uid(), 'edit')
          OR public.can_act_on_payment_oversight(auth.uid(), 'workflow_action')) THEN
    RAISE EXCEPTION 'not_authorised_for_payment_oversight';
  END IF;
  SELECT * INTO v_i FROM public.payment_system_incidents WHERE id = _incident_id;
  IF v_i.id IS NULL THEN RAISE EXCEPTION 'incident_not_found'; END IF;
  IF v_i.resolution_status = 'resolved' THEN RAISE EXCEPTION 'incident_already_resolved'; END IF;

  UPDATE public.payment_system_incidents
     SET resolution_status = 'resolved', resolved_at = now(),
         resolution_notes = COALESCE(_notes, resolution_notes), updated_at = now()
   WHERE id = _incident_id;

  INSERT INTO public.payment_oversight_events (operator_id, incident_id, event_type, actor_id, notes)
  VALUES (v_i.operator_id, _incident_id, 'INCIDENT_RESOLVED', auth.uid(), _notes);

  RETURN jsonb_build_object('ok', true);
END $function$
;
CREATE OR REPLACE FUNCTION public.payment_incident_set_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE seq int;
BEGIN
  IF NEW.reference IS NULL OR NEW.reference = '' THEN
    SELECT COALESCE(MAX((regexp_replace(reference, '^PSI-\d{4}-', ''))::int), 0) + 1
      INTO seq FROM public.payment_system_incidents
     WHERE reference LIKE 'PSI-' || to_char(now(), 'YYYY') || '-%';
    NEW.reference := 'PSI-' || to_char(now(), 'YYYY') || '-' || lpad(seq::text, 4, '0');
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.payment_operator_set_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE seq int;
BEGIN
  IF NEW.reference IS NULL OR NEW.reference = '' THEN
    SELECT COALESCE(MAX((regexp_replace(reference, '^PSO-\d{4}-', ''))::int), 0) + 1
      INTO seq FROM public.payment_system_operators
     WHERE reference LIKE 'PSO-' || to_char(now(), 'YYYY') || '-%';
    NEW.reference := 'PSO-' || to_char(now(), 'YYYY') || '-' || lpad(seq::text, 4, '0');
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.payment_refund_decide(_refund_id uuid, _decision text, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _before jsonb; _after jsonb; _payment_id uuid;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;
  IF NOT (public.is_super_admin(_uid) OR public.has_permission(_uid,'fee_management','edit')) THEN
    RAISE EXCEPTION 'Refund approval permission required' USING ERRCODE='42501';
  END IF;
  IF _decision NOT IN ('approved','rejected') THEN
    RAISE EXCEPTION 'Refund decision must be approved or rejected' USING ERRCODE='22023';
  END IF;
  IF coalesce(length(btrim(_reason)),0) < 10 THEN
    RAISE EXCEPTION 'A refund decision rationale of at least 10 characters is required' USING ERRCODE='22023';
  END IF;

  SELECT to_jsonb(r) INTO _before FROM public.refunds r WHERE r.id=_refund_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Refund request not found' USING ERRCODE='P0002'; END IF;
  IF _before->>'status' <> 'pending' THEN
    RAISE EXCEPTION 'This refund request has already been decided' USING ERRCODE='22023';
  END IF;
  _payment_id := nullif(_before->>'payment_id','')::uuid;

  UPDATE public.refunds SET
    status = _decision,
    approved_by = CASE WHEN _decision='approved' THEN _uid ELSE approved_by END
  WHERE id=_refund_id RETURNING to_jsonb(refunds) INTO _after;

  IF _decision='approved' AND _payment_id IS NOT NULL THEN
    UPDATE public.payments SET status='refunded' WHERE id=_payment_id;
  END IF;

  PERFORM public.log_compliance_audit(
    (CASE WHEN _decision='approved' THEN 'APPROVE' ELSE 'REJECT' END)::compliance_audit_action,
    'payment_refund', _refund_id::text, _before, _after, btrim(_reason));
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.peer_ratio_snapshot(_period_end date, _ratio_key text, _sector_id uuid DEFAULT NULL::uuid, _entity_id uuid DEFAULT NULL::uuid, _min_peers integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sector uuid := _sector_id;
  v_category uuid := NULL;
  v_entity_value numeric := NULL;
  v_count int := 0;
  v_min int := GREATEST(COALESCE(_min_peers, 5), 1);
  v_stats jsonb;
  v_below int := 0;
  v_pct numeric := NULL;
BEGIN
  IF _entity_id IS NOT NULL THEN
    SELECT COALESCE(_sector_id, l.sector_id), l.category_id
      INTO v_sector, v_category
      FROM public.licensees l WHERE l.id = _entity_id;
  END IF;

  WITH peers AS (
    SELECT DISTINCT ON (c.entity_id) c.entity_id, c.value_numeric AS value
      FROM public.v_return_metric_facts_current c
      JOIN public.licensees l ON l.id = c.entity_id
     WHERE upper(c.metric_code) = upper(_ratio_key)
       AND c.period_end = _period_end
       AND c.value_numeric IS NOT NULL
       AND (v_sector IS NULL OR l.sector_id = v_sector)
       AND (v_category IS NULL OR l.category_id = v_category)
     ORDER BY c.entity_id, c.filing_updated_at DESC NULLS LAST
  )
  SELECT COUNT(*),
         MAX(CASE WHEN _entity_id IS NOT NULL AND entity_id = _entity_id THEN value END),
         jsonb_build_object(
           'min', MIN(value), 'max', MAX(value),
           'median', PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY value),
           'p25', PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY value),
           'p90', PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY value),
           'average', AVG(value))
    INTO v_count, v_entity_value, v_stats
    FROM peers;

  IF v_count < v_min THEN
    RETURN jsonb_build_object(
      'ratio_key', _ratio_key, 'period_end', _period_end,
      'state', 'INSUFFICIENT_PEER_DATA', 'peer_count', v_count,
      'min_peers', v_min, 'count', v_count,
      'entity_value', v_entity_value,
      'peer_group', jsonb_build_object('sector_id', v_sector, 'category_id', v_category));
  END IF;

  IF v_entity_value IS NOT NULL THEN
    WITH peers AS (
      SELECT DISTINCT ON (c.entity_id) c.entity_id, c.value_numeric AS value
        FROM public.v_return_metric_facts_current c
        JOIN public.licensees l ON l.id = c.entity_id
       WHERE upper(c.metric_code) = upper(_ratio_key)
         AND c.period_end = _period_end
         AND c.value_numeric IS NOT NULL
         AND (v_sector IS NULL OR l.sector_id = v_sector)
         AND (v_category IS NULL OR l.category_id = v_category)
       ORDER BY c.entity_id, c.filing_updated_at DESC NULLS LAST
    )
    SELECT COUNT(*) INTO v_below FROM peers WHERE value < v_entity_value;
    v_pct := ROUND((v_below::numeric / v_count::numeric) * 10000) / 100;
  END IF;

  RETURN v_stats
    || jsonb_build_object(
         'ratio_key', _ratio_key, 'period_end', _period_end,
         'state', 'OK', 'peer_count', v_count, 'count', v_count,
         'min_peers', v_min, 'entity_value', v_entity_value,
         'percentile', v_pct,
         'peer_group', jsonb_build_object('sector_id', v_sector, 'category_id', v_category));
END $function$
;
CREATE OR REPLACE FUNCTION public.pending_duplicate_count()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_n int;
BEGIN
  IF v_uid IS NULL THEN RETURN 0; END IF;
  IF NOT (public.has_complaint_perm(v_uid,'triage') OR public.has_complaint_perm(v_uid,'view_all')) THEN RETURN 0; END IF;
  SELECT count(*) INTO v_n FROM public.complaint_duplicate_pairs WHERE status='pending';
  RETURN COALESCE(v_n,0);
END; $function$
;
CREATE OR REPLACE FUNCTION public.pending_escalation_count()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_n int;
BEGIN
  IF v_uid IS NULL THEN RETURN 0; END IF;
  IF NOT (public.has_complaint_perm(v_uid,'triage') OR public.has_complaint_perm(v_uid,'view_all') OR public.has_complaint_perm(v_uid,'escalate')) THEN RETURN 0; END IF;
  SELECT count(*) INTO v_n FROM public.complaint_escalation_cases WHERE status='pending';
  RETURN COALESCE(v_n,0);
END; $function$
;
CREATE OR REPLACE FUNCTION public.perform_final_workflow_approval(_application_id uuid, _instance_id uuid, _step_id uuid, _comments text, _actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app record; v_instance record; v_step record;
  v_steps_total int; v_current_idx int;
  v_auth jsonb;
  v_allowed_actions text[];
  v_now timestamptz := now();
  v_provision jsonb;
  v_license_id uuid; v_license_number text; v_licensee_id uuid;
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  IF _actor_id IS NULL THEN
    RETURN jsonb_build_object('error','UNAUTHORIZED','code','UNAUTHORIZED','http',401);
  END IF;
  IF _comments IS NULL OR length(trim(_comments)) = 0 THEN
    RETURN jsonb_build_object('error','Remarks are mandatory for approval','code','REMARKS_REQUIRED','http',422);
  END IF;

  SELECT id, applicant_id, application_number, status, license_type,
         regulator_id, workflow_id, data, approved_at
    INTO v_app FROM public.applications WHERE id=_application_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  IF v_app.status = 'approved' THEN
    -- Already approved — try (re)provisioning; safe even if payment still pending.
    v_provision := public.provision_application_entity(_application_id);
    RETURN jsonb_build_object('success',true,'http',200,'already_processed',true,
      'application_id',_application_id,
      'applicant_id',v_app.applicant_id,
      'provision', v_provision);
  END IF;

  IF v_app.status NOT IN ('submitted','in_progress') THEN
    RETURN jsonb_build_object('error',format('Cannot approve application in ''%s'' status', v_app.status),
                              'code','INVALID_STATUS','http',409);
  END IF;

  SELECT id, workflow_id, current_step_id, status INTO v_instance
    FROM public.workflow_instances
   WHERE entity_id=_application_id AND entity_type='application' AND status='active'
   ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','No active workflow instance','code','NO_ACTIVE_INSTANCE','http',409);
  END IF;
  IF _instance_id IS NOT NULL AND _instance_id<>v_instance.id THEN
    RETURN jsonb_build_object('error','Stale workflow instance','code','STALE_INSTANCE','http',409);
  END IF;
  IF _step_id IS NOT NULL AND _step_id<>v_instance.current_step_id THEN
    RETURN jsonb_build_object('error','Stale step','code','STALE_STEP','http',409);
  END IF;

  SELECT id, step_order, approver_role, approver_role_id, allowed_actions
    INTO v_step FROM public.approval_steps WHERE id=v_instance.current_step_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Current step not found','code','STEP_NOT_FOUND','http',409);
  END IF;

  SELECT count(*),
         (SELECT count(*) FROM public.approval_steps s2
          WHERE s2.workflow_id=v_instance.workflow_id AND s2.step_order<v_step.step_order)
    INTO v_steps_total, v_current_idx
    FROM public.approval_steps WHERE workflow_id=v_instance.workflow_id;

  IF v_current_idx <> v_steps_total - 1 THEN
    RETURN jsonb_build_object('error','Final approval requires last workflow step','code','NOT_LAST_STEP','http',422);
  END IF;

  v_auth := public.user_can_act_on_workflow_step(_actor_id, v_step.id);
  IF NOT (v_auth->>'can_act')::boolean THEN
    PERFORM public.log_workflow_authz_denial(_actor_id, v_step.id, 'approve', COALESCE(v_auth->>'reason','WRONG_APPROVER'), v_auth);
    RETURN jsonb_build_object('error',
      format('Only %s can act on this step', COALESCE(v_auth->>'required_role_name', v_step.approver_role::text)),
      'code','WRONG_APPROVER','http',403,
      'diagnostic', v_auth);
  END IF;

  v_allowed_actions := ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_step.allowed_actions, '[]'::jsonb)));
  IF NOT ('approve' = ANY(v_allowed_actions)) THEN
    RETURN jsonb_build_object('error','Approve is not allowed on this step','code','ACTION_NOT_ALLOWED','http',422);
  END IF;

  UPDATE public.applications SET status='approved', approved_at=v_now, updated_at=v_now WHERE id=_application_id;
  UPDATE public.workflow_instances SET status='completed', completed_at=v_now, updated_at=v_now WHERE id=v_instance.id;

  -- Try provisioning entity now (only succeeds if payment is also verified).
  v_provision := public.provision_application_entity(_application_id);
  v_license_id    := NULLIF(v_provision->>'license_id','')::uuid;
  v_license_number := v_provision->>'license_number';
  v_licensee_id   := NULLIF(v_provision->>'licensee_id','')::uuid;

  INSERT INTO public.approval_actions (application_id, step_id, workflow_instance_id, actor_id,
    action, action_type, comments, responded_at)
  VALUES (_application_id, v_step.id, v_instance.id, _actor_id,
    'approve_final', 'approve', NULLIF(trim(_comments),''), v_now)
  ON CONFLICT (application_id) WHERE action='approve_final' DO NOTHING;

  PERFORM public.create_audit_log(_actor_id, 'application_final_approved', 'application',
    _application_id::text, NULL,
    jsonb_build_object('license_id',v_license_id,'license_number',v_license_number,
                       'licensee_id',v_licensee_id, 'auth', v_auth,
                       'provision', v_provision), NULL);

  PERFORM public.create_notification(v_app.applicant_id,
    'Application Approved: ' || v_app.application_number,
    CASE WHEN v_license_number IS NOT NULL
         THEN 'Your application has been approved. License Number: ' || v_license_number
         ELSE 'Your application has been approved. Your license will be issued once payment is verified.' END,
    'success', 'application', _application_id::text);

  RETURN jsonb_build_object('success',true,'http',200,
    'application_id',_application_id,
    'license_id',v_license_id,
    'license_number',v_license_number,
    'licensee_id',v_licensee_id,
    'applicant_id',v_app.applicant_id,
    'provision', v_provision);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.perform_manual_application_approval(_application_id uuid, _comments text, _actor_id uuid DEFAULT auth.uid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app record;
  v_caller_role text;
  v_now timestamptz := now();
  v_provision jsonb;
  v_license_id uuid;
  v_license_number text;
  v_licensee_id uuid;
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  IF _actor_id IS NULL THEN
    RETURN jsonb_build_object('error','UNAUTHORIZED','code','UNAUTHORIZED','http',401);
  END IF;

  -- Caller must be internal staff.
  SELECT public.get_user_role(_actor_id) INTO v_caller_role;
  IF v_caller_role IS NULL
     OR v_caller_role NOT IN ('super_admin','admin','supervisor','licensing_officer') THEN
    RETURN jsonb_build_object('error','Insufficient permissions','code','FORBIDDEN','http',403);
  END IF;

  IF _comments IS NULL OR length(trim(_comments)) = 0 THEN
    RETURN jsonb_build_object('error','Remarks are mandatory for approval','code','REMARKS_REQUIRED','http',422);
  END IF;

  SELECT id, applicant_id, application_number, status, license_type,
         regulator_id, workflow_id, data, approved_at
    INTO v_app
    FROM public.applications
   WHERE id = _application_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  IF v_app.status = 'approved' THEN
    -- Idempotent: re-run provisioning so the license/licensee exist.
    v_provision := public.provision_application_entity(_application_id);
    RETURN jsonb_build_object(
      'success', true, 'http', 200, 'already_processed', true,
      'application_id', _application_id,
      'application_number', v_app.application_number,
      'applicant_id', v_app.applicant_id,
      'license_id', NULLIF(v_provision->>'license_id','')::uuid,
      'license_number', v_provision->>'license_number',
      'licensee_id', NULLIF(v_provision->>'licensee_id','')::uuid,
      'provision', v_provision
    );
  END IF;

  IF v_app.status IN ('rejected','cancelled','withdrawn') THEN
    RETURN jsonb_build_object(
      'error', format('Cannot approve application in ''%s'' status', v_app.status),
      'code','INVALID_STATUS','http',409
    );
  END IF;

  UPDATE public.applications
     SET status = 'approved', approved_at = v_now, updated_at = v_now
   WHERE id = _application_id;

  -- Cancel any open workflow instances so they don't linger.
  UPDATE public.workflow_instances
     SET status = 'completed', completed_at = v_now, updated_at = v_now
   WHERE entity_id = _application_id
     AND entity_type = 'application'
     AND status = 'active';

  v_provision      := public.provision_application_entity(_application_id);
  v_license_id     := NULLIF(v_provision->>'license_id','')::uuid;
  v_license_number := v_provision->>'license_number';
  v_licensee_id    := NULLIF(v_provision->>'licensee_id','')::uuid;

  INSERT INTO public.approval_actions (
    application_id, step_id, workflow_instance_id, actor_id,
    action, action_type, comments, responded_at
  )
  VALUES (
    _application_id, NULL, NULL, _actor_id,
    'approve_final', 'approve', NULLIF(trim(_comments),''), v_now
  )
  ON CONFLICT (application_id) WHERE action='approve_final' DO NOTHING;

  PERFORM public.create_audit_log(
    _actor_id, 'application_manual_approved', 'application',
    _application_id::text, NULL,
    jsonb_build_object(
      'license_id', v_license_id,
      'license_number', v_license_number,
      'licensee_id', v_licensee_id,
      'provision', v_provision,
      'reason', 'no_workflow_configured'
    ), NULL
  );

  PERFORM public.create_notification(
    v_app.applicant_id,
    'Application Approved: ' || v_app.application_number,
    CASE WHEN v_license_number IS NOT NULL
         THEN 'Your application has been approved. License Number: ' || v_license_number
         ELSE 'Your application has been approved. Your license will be issued once payment is verified.'
    END,
    'success', 'application', _application_id::text
  );

  RETURN jsonb_build_object(
    'success', true, 'http', 200,
    'application_id', _application_id,
    'application_number', v_app.application_number,
    'applicant_id', v_app.applicant_id,
    'license_id', v_license_id,
    'license_number', v_license_number,
    'licensee_id', v_licensee_id,
    'provision', v_provision
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.perform_registration_workflow_transition(_registration_id uuid, _instance_id uuid, _step_id uuid, _action_type text, _comments text DEFAULT NULL::text, _actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
BEGIN
  BEGIN
    v_actor := public.workflow_resolve_actor(_actor_id);
  EXCEPTION WHEN insufficient_privilege THEN
    RETURN jsonb_build_object('error', SQLERRM, 'code', SQLERRM,
                              'http', CASE WHEN SQLERRM = 'UNAUTHORIZED' THEN 401 ELSE 403 END);
  END;

  RETURN public.perform_registration_workflow_transition_internal(
    _registration_id, _instance_id, _step_id, _action_type, _comments, v_actor);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.perform_registration_workflow_transition_internal(_registration_id uuid, _instance_id uuid, _step_id uuid, _action_type text, _comments text, _actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reg record;
  v_instance record;
  v_step record;
  v_auth jsonb;
  v_allowed text[];
  v_steps_total int;
  v_current_idx int;
  v_is_first boolean;
  v_is_last boolean;
  v_next record;
  v_prev record;
  v_new_step_id uuid;
  v_new_reg_status text;
  v_new_instance_status text;
  v_now timestamptz := now();
  v_is_internal boolean;
  v_role_match boolean;
  v_effective_action text;
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  IF _actor_id IS NULL THEN
    RETURN jsonb_build_object('error','UNAUTHORIZED','code','UNAUTHORIZED','http',401);
  END IF;
  IF _action_type NOT IN (
    'approve','reject','send_back','escalate',
    'request_resubmission','return_for_correction','request_more_info',
    'save_comment'
  ) THEN
    RETURN jsonb_build_object('error','Invalid action_type','code','BAD_ACTION','http',400);
  END IF;

  v_effective_action := CASE WHEN _action_type = 'save_comment' THEN 'approve' ELSE _action_type END;

  IF _action_type IN (
    'approve','reject','request_resubmission','return_for_correction','request_more_info','save_comment'
  ) AND (_comments IS NULL OR length(trim(_comments)) = 0) THEN
    RETURN jsonb_build_object('error','Remarks are mandatory for this action','code','REMARKS_REQUIRED','http',422);
  END IF;

  SELECT id, status, registration_reference, sector_id
    INTO v_reg FROM public.registrations WHERE id = _registration_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Registration not found','code','NOT_FOUND','http',404);
  END IF;

  IF v_reg.status NOT IN ('pending_review','in_progress','resubmission_required') THEN
    RETURN jsonb_build_object('error',format('Registration is in ''%s'' status', v_reg.status),
                              'code','INVALID_STATUS','http',409);
  END IF;

  SELECT id, workflow_id, current_step_id, status INTO v_instance
    FROM public.workflow_instances
   WHERE entity_id = _registration_id AND entity_type = 'registration'
     AND status IN ('active','paused')
   ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','No active workflow instance','code','NO_ACTIVE_INSTANCE','http',409);
  END IF;
  IF _instance_id IS NOT NULL AND _instance_id <> v_instance.id THEN
    RETURN jsonb_build_object('error','Stale workflow instance','code','STALE_INSTANCE','http',409);
  END IF;
  IF _step_id IS NOT NULL AND _step_id <> v_instance.current_step_id THEN
    RETURN jsonb_build_object('error','Stale step','code','STALE_STEP','http',409);
  END IF;

  SELECT id, step_order, name, approver_role, approver_role_id, allowed_actions
    INTO v_step FROM public.approval_steps WHERE id = v_instance.current_step_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Current step not found','code','STEP_NOT_FOUND','http',409);
  END IF;

  SELECT count(*),
         (SELECT count(*) FROM public.approval_steps s2
           WHERE s2.workflow_id = v_instance.workflow_id AND s2.step_order < v_step.step_order)
    INTO v_steps_total, v_current_idx
    FROM public.approval_steps WHERE workflow_id = v_instance.workflow_id;
  v_is_first := (v_current_idx = 0);
  v_is_last  := (v_current_idx = v_steps_total - 1);

  v_auth := public.user_can_act_on_workflow_step(_actor_id, v_step.id);
  v_role_match := COALESCE((v_auth->>'can_act')::boolean, false);
  v_is_internal := COALESCE((v_auth->>'is_internal')::boolean, false);

  IF _action_type = 'save_comment' THEN
    IF NOT v_is_internal THEN
      RETURN jsonb_build_object('error','Only internal staff can save a comment on this step',
                                'code','FORBIDDEN','http',403,'diagnostic',v_auth);
    END IF;
  ELSIF NOT v_role_match THEN
    PERFORM public.log_workflow_authz_denial(_actor_id, v_step.id, _action_type, COALESCE(v_auth->>'reason','WRONG_APPROVER'), v_auth);
    RETURN jsonb_build_object(
      'error', format('Only %s can act on this step',
                      COALESCE(v_auth->>'required_role_name', v_step.approver_role::text)),
      'code','WRONG_APPROVER','http',403, 'diagnostic', v_auth);
  END IF;

  IF _action_type <> 'save_comment' THEN
    v_allowed := ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_step.allowed_actions, '[]'::jsonb)));
    IF NOT (_action_type = ANY(v_allowed)) THEN
      RETURN jsonb_build_object('error',format('Action ''%s'' is not allowed on this step', _action_type),
                                'code','ACTION_NOT_ALLOWED','http',422);
    END IF;
  END IF;

  IF _action_type = 'send_back' AND v_is_first THEN
    RETURN jsonb_build_object('error','Cannot send back from the first step','code','CANNOT_SEND_BACK','http',422);
  END IF;
  IF _action_type = 'escalate' AND v_is_last THEN
    RETURN jsonb_build_object('error','Cannot escalate from the last step','code','CANNOT_ESCALATE','http',422);
  END IF;

  v_new_step_id := v_step.id;

  IF v_effective_action = 'approve' THEN
    IF v_is_last THEN
      v_new_reg_status := 'approved';
      v_new_instance_status := 'completed';
    ELSE
      SELECT id INTO v_next FROM public.approval_steps
       WHERE workflow_id = v_instance.workflow_id AND step_order > v_step.step_order
       ORDER BY step_order ASC LIMIT 1;
      v_new_step_id := v_next.id;
      v_new_reg_status := 'in_progress';
    END IF;
  ELSIF _action_type = 'reject' THEN
    v_new_reg_status := 'rejected';
    v_new_instance_status := 'completed';
  ELSIF _action_type = 'send_back' THEN
    SELECT id INTO v_prev FROM public.approval_steps
     WHERE workflow_id = v_instance.workflow_id AND step_order < v_step.step_order
     ORDER BY step_order DESC LIMIT 1;
    v_new_step_id := v_prev.id;
    v_new_reg_status := 'in_progress';
  ELSIF _action_type = 'escalate' THEN
    SELECT id INTO v_next FROM public.approval_steps
     WHERE workflow_id = v_instance.workflow_id AND step_order > v_step.step_order
     ORDER BY step_order ASC LIMIT 1;
    v_new_step_id := v_next.id;
    v_new_reg_status := 'in_progress';
  ELSIF _action_type IN ('request_resubmission','return_for_correction','request_more_info') THEN
    v_new_reg_status := 'resubmission_required';
    v_new_instance_status := 'paused';
  END IF;

  IF _action_type = 'save_comment' THEN
    DELETE FROM public.approval_actions
     WHERE entity_type = 'registration'
       AND entity_id = _registration_id
       AND step_id = v_step.id
       AND actor_id = _actor_id
       AND action_type = 'save_comment';
  END IF;

  INSERT INTO public.approval_actions (
    workflow_instance_id, step_id, actor_id, action, action_type, comments,
    entity_type, entity_id
  ) VALUES (
    v_instance.id, v_step.id, _actor_id,
    CASE WHEN _action_type = 'save_comment' THEN 'comment_saved' ELSE _action_type END,
    _action_type, _comments,
    'registration', _registration_id
  );

  UPDATE public.workflow_instances
     SET current_step_id = v_new_step_id,
         status = COALESCE(v_new_instance_status, status),
         completed_at = CASE WHEN COALESCE(v_new_instance_status, status) = 'completed' THEN v_now ELSE completed_at END,
         updated_at = v_now
   WHERE id = v_instance.id;

  IF v_new_reg_status IS NOT NULL THEN
    UPDATE public.registrations SET status = v_new_reg_status, updated_at = v_now
     WHERE id = _registration_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'action_type', _action_type,
    'registration_id', _registration_id,
    'registration_reference', v_reg.registration_reference,
    'new_step_id', v_new_step_id,
    'new_status', COALESCE(v_new_reg_status, v_reg.status),
    'instance_id', v_instance.id,
    'http', 200
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.perform_return_workflow_transition(_return_id uuid, _instance_id uuid, _step_id uuid, _action_type text, _comments text, _actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ret record;
  v_instance record;
  v_step record;
  v_auth jsonb;
  v_allowed_actions text[];
  v_steps_total int;
  v_current_idx int;
  v_is_last boolean;
  v_next_step record;
  v_prev_step record;
  v_new_step_id uuid;
  v_new_status text;
  v_new_instance_status text;
  v_now timestamptz := now();
  v_prev_status text;
  v_prev_step_id uuid;
  v_action_key text;
  v_event_key text;
  v_actor_role text;
  v_effective_action text;
BEGIN
  IF _actor_id IS NULL THEN
    RETURN jsonb_build_object('error','UNAUTHORIZED','code','UNAUTHORIZED','http',401);
  END IF;

  IF _action_type NOT IN ('approve','reject','send_back','escalate','request_resubmission','save_comment') THEN
    RETURN jsonb_build_object('error','Invalid action_type','code','BAD_ACTION','http',400);
  END IF;

  v_effective_action := CASE WHEN _action_type = 'save_comment' THEN 'approve' ELSE _action_type END;

  IF _action_type IN ('approve','reject','request_resubmission','save_comment')
     AND (_comments IS NULL OR length(trim(_comments)) = 0) THEN
    RETURN jsonb_build_object('error','Remarks are mandatory for this action','code','REMARKS_REQUIRED','http',422);
  END IF;

  SELECT id, unique_id, workflow_status, workflow_id, current_step_id
    INTO v_ret
    FROM public.returns_filed
   WHERE id = _return_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Return not found','code','NOT_FOUND','http',404);
  END IF;

  v_prev_status := v_ret.workflow_status::text;
  v_prev_step_id := v_ret.current_step_id;

  IF upper(v_prev_status) <> 'SUB' THEN
    RETURN jsonb_build_object('error', format('Return is in ''%s'' status', v_ret.workflow_status), 'code','INVALID_STATUS','http',409);
  END IF;

  SELECT id, workflow_id, current_step_id, status
    INTO v_instance
    FROM public.workflow_instances
   WHERE entity_id = _return_id
     AND entity_type = 'return'
     AND status = 'active'
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','No active workflow instance','code','NO_ACTIVE_INSTANCE','http',409);
  END IF;

  IF _instance_id IS NOT NULL AND _instance_id <> v_instance.id THEN
    RETURN jsonb_build_object('error','Stale workflow instance','code','STALE_INSTANCE','http',409);
  END IF;

  SELECT s.* INTO v_step FROM public.approval_steps s WHERE s.id = v_instance.current_step_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Current step missing','code','BAD_STEP','http',409);
  END IF;

  IF _step_id IS NOT NULL AND _step_id <> v_step.id THEN
    RETURN jsonb_build_object('error','Stale step','code','STALE_STEP','http',409);
  END IF;

  SELECT public.user_can_act_on_workflow_step(_actor_id, v_step.id) INTO v_auth;
  IF NOT COALESCE((v_auth->>'can_act')::boolean, false) THEN
    -- save_comment: allow if user is internal even without full role match
    IF NOT (_action_type = 'save_comment' AND COALESCE((v_auth->>'is_internal')::boolean, false)) THEN
      PERFORM public.log_workflow_authz_denial(_actor_id, v_step.id, _action_type, COALESCE(v_auth->>'reason','WRONG_APPROVER'), v_auth);
      RETURN jsonb_build_object('error','You are not authorized to act on this step','code','FORBIDDEN','http',403);
    END IF;
  END IF;

  IF _action_type <> 'save_comment' THEN
    v_allowed_actions := COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_auth->'allowed_actions')), ARRAY[]::text[]);
    IF NOT (_action_type = ANY(v_allowed_actions)) THEN
      RETURN jsonb_build_object('error', format('Action ''%s'' not allowed at this step', _action_type), 'code','ACTION_NOT_ALLOWED','http',403);
    END IF;
  END IF;

  v_actor_role := NULLIF(COALESCE(v_auth->>'required_role_name', v_auth->>'required_role_id'), '');

  SELECT count(*) INTO v_steps_total FROM public.approval_steps WHERE workflow_id = v_instance.workflow_id;
  SELECT count(*) INTO v_current_idx
    FROM public.approval_steps
   WHERE workflow_id = v_instance.workflow_id
     AND step_order <= v_step.step_order;
  v_is_last := v_current_idx = v_steps_total;

  SELECT * INTO v_next_step
    FROM public.approval_steps
   WHERE workflow_id = v_instance.workflow_id
     AND step_order > v_step.step_order
   ORDER BY step_order ASC
   LIMIT 1;

  SELECT * INTO v_prev_step
    FROM public.approval_steps
   WHERE workflow_id = v_instance.workflow_id
     AND step_order < v_step.step_order
   ORDER BY step_order DESC
   LIMIT 1;

  IF _action_type = 'send_back' AND v_prev_step.id IS NULL THEN
    RETURN jsonb_build_object('error','Cannot send back from the first step','code','CANNOT_SEND_BACK','http',422);
  END IF;

  IF _action_type = 'escalate' AND v_next_step.id IS NULL THEN
    RETURN jsonb_build_object('error','Cannot escalate from the last step','code','CANNOT_ESCALATE','http',422);
  END IF;

  IF v_effective_action = 'approve' THEN
    IF v_is_last THEN
      v_new_step_id := v_step.id;
      v_new_status := 'VAL';
      v_new_instance_status := 'completed';
      v_action_key := CASE WHEN _action_type = 'save_comment' THEN 'comment_saved' ELSE 'return_approved' END;
      v_event_key  := CASE WHEN _action_type = 'save_comment' THEN 'return.comment_saved' ELSE 'return.approved' END;
    ELSE
      v_new_step_id := v_next_step.id;
      v_new_status := v_prev_status;
      v_action_key := CASE WHEN _action_type = 'save_comment' THEN 'comment_saved' ELSE 'workflow_step_approved' END;
      v_event_key  := CASE WHEN _action_type = 'save_comment' THEN 'return.comment_saved' ELSE 'return.workflow_step_approved' END;
    END IF;
  ELSIF _action_type = 'reject' THEN
    v_new_step_id := v_step.id;
    v_new_status := 'REJ';
    v_new_instance_status := 'completed';
    v_action_key := 'return_rejected';
    v_event_key := 'return.rejected';
  ELSIF _action_type = 'send_back' THEN
    v_new_step_id := v_prev_step.id;
    v_new_status := v_prev_status;
    v_action_key := 'return_sent_back';
    v_event_key := 'return.send_back';
  ELSIF _action_type = 'request_resubmission' THEN
    v_new_step_id := v_step.id;
    v_new_status := 'TBR';
    v_new_instance_status := 'paused';
    v_action_key := 'edit_requested';
    v_event_key := 'return.edit_requested';

    INSERT INTO public.return_requests (return_id, reasons, status, requested_by)
    VALUES (_return_id, _comments, 'active', _actor_id);
  ELSIF _action_type = 'escalate' THEN
    v_new_step_id := v_next_step.id;
    v_new_status := v_prev_status;
    v_action_key := 'workflow_step_escalated';
    v_event_key := 'return.workflow_step_escalated';
  END IF;

  IF _action_type = 'save_comment' THEN
    DELETE FROM public.approval_actions
     WHERE entity_type = 'return'
       AND entity_id = _return_id
       AND step_id = v_step.id
       AND actor_id = _actor_id
       AND action_type = 'save_comment';
  END IF;

  INSERT INTO public.approval_actions
    (entity_type, entity_id, application_id, workflow_instance_id, step_id, actor_id, action, action_type, comments)
  VALUES
    ('return', _return_id, NULL, v_instance.id, v_step.id, _actor_id,
     CASE WHEN _action_type = 'save_comment' THEN 'comment_saved' ELSE _action_type END,
     _action_type, _comments);

  INSERT INTO public.return_audit_log
    (return_id, action, previous_status, new_status, comments, performed_by,
     previous_step_id, new_step_id, actor_role, metadata, event_key, source)
  VALUES
    (_return_id, v_action_key, v_prev_status, COALESCE(v_new_status, v_prev_status),
     _comments, _actor_id,
     v_prev_step_id, v_new_step_id, v_actor_role,
     jsonb_build_object(
       'workflow_id', v_instance.workflow_id,
       'instance_id', v_instance.id,
       'action_type', _action_type,
       'is_final', v_is_last,
       'step_order', v_step.step_order
     ),
     v_event_key, 'rpc:perform_return_workflow_transition');

  IF v_new_step_id IS DISTINCT FROM v_prev_step_id AND _action_type IN ('approve','save_comment','send_back','escalate') THEN
    INSERT INTO public.return_audit_log
      (return_id, action, previous_status, new_status, comments, performed_by,
       previous_step_id, new_step_id, actor_role, metadata, event_key, source)
    VALUES
      (_return_id, 'workflow_step_changed', v_prev_status, COALESCE(v_new_status, v_prev_status),
       CASE
         WHEN _action_type = 'send_back' THEN 'Workflow sent back to previous step'
         WHEN _action_type = 'escalate' THEN 'Workflow escalated to next step'
         ELSE 'Workflow step changed'
       END,
       _actor_id,
       v_prev_step_id, v_new_step_id, v_actor_role,
       jsonb_build_object('workflow_id', v_instance.workflow_id, 'instance_id', v_instance.id, 'action_type', _action_type),
       'return.workflow_step_changed', 'rpc:perform_return_workflow_transition');
  END IF;

  IF v_new_step_id IS DISTINCT FROM v_prev_step_id AND v_effective_action = 'approve' AND NOT v_is_last THEN
    INSERT INTO public.return_audit_log
      (return_id, action, previous_status, new_status, comments, performed_by,
       previous_step_id, new_step_id, actor_role, metadata, event_key, source)
    VALUES
      (_return_id, 'workflow_step_moved', v_prev_status, COALESCE(v_new_status, v_prev_status),
       'Workflow advanced to next step', _actor_id,
       v_prev_step_id, v_new_step_id, v_actor_role,
       jsonb_build_object('workflow_id', v_instance.workflow_id, 'instance_id', v_instance.id),
       'return.workflow_step_moved', 'rpc:perform_return_workflow_transition');
  END IF;

  IF v_new_status IS NOT NULL AND v_new_status <> v_prev_status THEN
    INSERT INTO public.return_audit_log
      (return_id, action, previous_status, new_status, comments, performed_by, actor_role, metadata, event_key, source)
    VALUES
      (_return_id, 'status_changed', v_prev_status, v_new_status,
       'Status changed by workflow action', _actor_id, v_actor_role,
       jsonb_build_object('from', v_prev_status, 'to', v_new_status, 'action_type', _action_type),
       'return.status_changed', 'rpc:perform_return_workflow_transition');

    IF v_new_status = 'TBR' THEN
      INSERT INTO public.return_audit_log
        (return_id, action, previous_status, new_status, comments, performed_by, actor_role, metadata, event_key, source)
      VALUES
        (_return_id, 'status_changed_to_tbr', v_prev_status, 'TBR',
         COALESCE(_comments, 'Return moved to TBR'), _actor_id, v_actor_role,
         jsonb_build_object('action_type', _action_type),
         'return.status_changed_to_tbr', 'rpc:perform_return_workflow_transition');
    END IF;
  END IF;

  UPDATE public.workflow_instances
     SET current_step_id = v_new_step_id,
         status = COALESCE(v_new_instance_status, status),
         completed_at = CASE WHEN COALESCE(v_new_instance_status, '') = 'completed' THEN v_now ELSE completed_at END,
         updated_at = v_now
   WHERE id = v_instance.id;

  IF v_new_status IS NOT NULL THEN
    UPDATE public.returns_filed
       SET workflow_status = v_new_status::public.return_workflow_status,
           current_step_id = CASE WHEN v_new_instance_status = 'completed' THEN NULL ELSE v_new_step_id END,
           updated_by = _actor_id,
           updated_at = v_now
     WHERE id = _return_id;
  ELSE
    UPDATE public.returns_filed
       SET current_step_id = v_new_step_id,
           updated_by = _actor_id,
           updated_at = v_now
     WHERE id = _return_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'action_type', _action_type,
    'action_key', v_action_key,
    'event_key', v_event_key,
    'return_id', _return_id,
    'unique_id', v_ret.unique_id,
    'new_step_id', v_new_step_id,
    'previous_step_id', v_prev_step_id,
    'new_status', COALESCE(v_new_status, v_prev_status),
    'previous_status', v_prev_status,
    'instance_id', v_instance.id,
    'http', 200
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.perform_workflow_transition(_application_id uuid, _instance_id uuid, _step_id uuid, _action_type text, _comments text, _actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app record;
  v_instance record;
  v_step record;
  v_auth jsonb;
  v_allowed_actions text[];
  v_steps_total int;
  v_current_idx int;
  v_is_first boolean;
  v_is_last boolean;
  v_next_step record;
  v_prev_step record;
  v_new_step_id uuid;
  v_new_app_status text;
  v_new_instance_status text;
  v_now timestamptz := now();
  v_role_match boolean;
  v_is_internal boolean;
  v_action_cfg record;
  v_has_cfg boolean := false;
  v_effective_action text;
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  BEGIN
    _actor_id := public.workflow_resolve_actor(_actor_id);
  EXCEPTION WHEN insufficient_privilege THEN
    RETURN jsonb_build_object('error', SQLERRM, 'code', SQLERRM,
                              'http', CASE WHEN SQLERRM = 'UNAUTHORIZED' THEN 401 ELSE 403 END);
  END;
  IF _action_type NOT IN (
    'approve','reject','send_back','escalate',
    'request_resubmission','return_for_correction','request_more_info',
    'save_comment'
  ) THEN
    RETURN jsonb_build_object('error','Invalid action_type','code','BAD_ACTION','http',400);
  END IF;

  -- save_comment progresses like approve internally but is recorded as itself.
  v_effective_action := CASE WHEN _action_type = 'save_comment' THEN 'approve' ELSE _action_type END;

  SELECT id, applicant_id, application_number, status, workflow_id
    INTO v_app FROM public.applications WHERE id = _application_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  IF v_app.status NOT IN ('submitted','in_progress') THEN
    IF v_effective_action = 'approve' AND v_app.status = 'approved' THEN
      RETURN jsonb_build_object('final_approval', true, 'http', 200);
    END IF;
    RETURN jsonb_build_object('error',format('Application is in ''%s'' status', v_app.status),
                              'code','INVALID_STATUS','http',409);
  END IF;

  SELECT id, workflow_id, current_step_id, status INTO v_instance
    FROM public.workflow_instances
   WHERE entity_id = _application_id AND entity_type = 'application' AND status = 'active'
   ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','No active workflow instance','code','NO_ACTIVE_INSTANCE','http',409);
  END IF;
  IF _instance_id IS NOT NULL AND _instance_id <> v_instance.id THEN
    RETURN jsonb_build_object('error','Stale workflow instance','code','STALE_INSTANCE','http',409);
  END IF;
  IF _step_id IS NOT NULL AND _step_id <> v_instance.current_step_id THEN
    RETURN jsonb_build_object('error','Stale step','code','STALE_STEP','http',409);
  END IF;

  SELECT id, step_order, name, approver_role, approver_role_id, allowed_actions
    INTO v_step FROM public.approval_steps WHERE id = v_instance.current_step_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Current step not found','code','STEP_NOT_FOUND','http',409);
  END IF;

  -- Load per-action config using the effective action (save_comment reuses approve config)
  SELECT * INTO v_action_cfg FROM public.approval_step_actions
   WHERE step_id = v_step.id AND action_type = v_effective_action;
  v_has_cfg := FOUND AND COALESCE(v_action_cfg.is_enabled, true);

  -- Mandatory remarks
  IF (_action_type IN (
        'approve','reject','request_resubmission',
        'return_for_correction','request_more_info','save_comment'
      ) OR (v_has_cfg AND v_action_cfg.require_comments))
     AND (_comments IS NULL OR length(trim(_comments)) = 0) THEN
    RETURN jsonb_build_object('error','Remarks are mandatory for this action','code','REMARKS_REQUIRED','http',422);
  END IF;

  SELECT count(*),
         (SELECT count(*) FROM public.approval_steps s2
          WHERE s2.workflow_id = v_instance.workflow_id AND s2.step_order < v_step.step_order)
    INTO v_steps_total, v_current_idx
    FROM public.approval_steps WHERE workflow_id = v_instance.workflow_id;
  v_is_first := (v_current_idx = 0);
  v_is_last  := (v_current_idx = v_steps_total - 1);

  v_auth := public.user_can_act_on_workflow_step(_actor_id, v_step.id);
  v_role_match := COALESCE((v_auth->>'can_act')::boolean, false);
  v_is_internal := COALESCE((v_auth->>'is_internal')::boolean, false);

  IF _action_type = 'save_comment' THEN
    -- Save Comment requires internal user on the step but does not need role match to approve.
    IF NOT v_is_internal THEN
      RETURN jsonb_build_object('error','Only internal staff can save a comment on this step',
                                'code','FORBIDDEN','http',403,'diagnostic',v_auth);
    END IF;
  ELSIF NOT v_role_match THEN
    PERFORM public.log_workflow_authz_denial(_actor_id, v_step.id, _action_type, COALESCE(v_auth->>'reason','WRONG_APPROVER'), v_auth);
    RETURN jsonb_build_object(
      'error', format('Only %s can act on this step',
                      COALESCE(v_auth->>'required_role_name', v_step.approver_role::text)),
      'code','WRONG_APPROVER','http',403,
      'diagnostic', v_auth
    );
  END IF;

  -- Skip allowed_actions gate for save_comment (implicitly available on every step)
  IF _action_type <> 'save_comment' THEN
    v_allowed_actions := ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_step.allowed_actions, '[]'::jsonb)));
    IF NOT (_action_type = ANY(v_allowed_actions)) THEN
      RETURN jsonb_build_object('error',format('Action ''%s'' is not allowed on this step', _action_type),
                                'code','ACTION_NOT_ALLOWED','http',422);
    END IF;
  END IF;

  v_new_step_id := v_step.id;
  v_new_app_status := NULL;
  v_new_instance_status := NULL;

  IF v_has_cfg AND _action_type NOT IN ('save_comment', 'reject') THEN
    IF v_action_cfg.next_step_mode = 'end_workflow' THEN
      IF v_action_cfg.end_state = 'approved' THEN
        RETURN jsonb_build_object('final_approval', true, 'http', 200);
      ELSIF v_action_cfg.end_state = 'rejected' THEN
        v_new_app_status := 'rejected';
        v_new_instance_status := 'completed';
      ELSIF v_action_cfg.end_state = 'cancelled' THEN
        v_new_app_status := 'cancelled';
        v_new_instance_status := 'completed';
      ELSE
        v_new_app_status := CASE WHEN _action_type='reject' THEN 'rejected' ELSE 'approved' END;
        v_new_instance_status := 'completed';
      END IF;
    ELSIF v_action_cfg.next_step_mode = 'specific_step' AND v_action_cfg.next_step_id IS NOT NULL THEN
      v_new_step_id := v_action_cfg.next_step_id;
      v_new_app_status := 'in_progress';
    ELSIF v_action_cfg.next_step_mode = 'previous' THEN
      SELECT id INTO v_prev_step FROM public.approval_steps
       WHERE workflow_id = v_instance.workflow_id AND step_order < v_step.step_order
       ORDER BY step_order DESC LIMIT 1;
      IF FOUND THEN
        v_new_step_id := v_prev_step.id;
        v_new_app_status := 'in_progress';
      END IF;
    ELSIF v_action_cfg.next_step_mode = 'return_to_applicant' THEN
      v_new_app_status := CASE
        WHEN _action_type = 'request_more_info' THEN 'info_requested'
        WHEN _action_type = 'return_for_correction' THEN 'returned_for_correction'
        ELSE 'resubmission_required'
      END;
      v_new_instance_status := 'paused';
    ELSIF v_action_cfg.next_step_mode = 'keep' THEN
      v_new_app_status := 'in_progress';
    ELSE
      SELECT id INTO v_next_step FROM public.approval_steps
       WHERE workflow_id = v_instance.workflow_id AND step_order > v_step.step_order
       ORDER BY step_order ASC LIMIT 1;
      IF FOUND THEN
        v_new_step_id := v_next_step.id;
        v_new_app_status := 'in_progress';
      ELSIF _action_type = 'approve' THEN
        RETURN jsonb_build_object('final_approval', true, 'http', 200);
      END IF;
    END IF;

    IF v_action_cfg.result_status_override IS NOT NULL
       AND length(trim(v_action_cfg.result_status_override)) > 0
       AND v_new_instance_status IS DISTINCT FROM 'completed' THEN
      v_new_app_status := v_action_cfg.result_status_override;
    END IF;
  ELSE
    -- Legacy / save_comment path: use built-in progression by effective action
    IF _action_type = 'send_back' AND v_is_first THEN
      RETURN jsonb_build_object('error','Cannot send back from the first step','code','CANNOT_SEND_BACK','http',422);
    END IF;
    IF _action_type = 'escalate' AND v_is_last THEN
      RETURN jsonb_build_object('error','Cannot escalate from the last step','code','CANNOT_ESCALATE','http',422);
    END IF;

    IF v_effective_action = 'approve' AND v_is_last THEN
      -- For save_comment on the last step: final approval path
      RETURN jsonb_build_object('final_approval', true, 'http', 200);
    END IF;

    IF v_effective_action = 'approve' THEN
      SELECT id INTO v_next_step FROM public.approval_steps
       WHERE workflow_id = v_instance.workflow_id AND step_order > v_step.step_order
       ORDER BY step_order ASC LIMIT 1;
      IF FOUND THEN v_new_step_id := v_next_step.id; v_new_app_status := 'in_progress'; END IF;
    ELSIF _action_type = 'reject' THEN
      v_new_app_status := 'rejected'; v_new_instance_status := 'completed';
    ELSIF _action_type = 'send_back' THEN
      SELECT id INTO v_prev_step FROM public.approval_steps
       WHERE workflow_id = v_instance.workflow_id AND step_order < v_step.step_order
       ORDER BY step_order DESC LIMIT 1;
      IF FOUND THEN v_new_step_id := v_prev_step.id; v_new_app_status := 'in_progress'; END IF;
    ELSIF _action_type = 'escalate' THEN
      SELECT id INTO v_next_step FROM public.approval_steps
       WHERE workflow_id = v_instance.workflow_id AND step_order > v_step.step_order
       ORDER BY step_order ASC LIMIT 1;
      IF FOUND THEN v_new_step_id := v_next_step.id; v_new_app_status := 'in_progress'; END IF;
    ELSIF _action_type = 'request_resubmission' THEN
      v_new_app_status := 'resubmission_required'; v_new_instance_status := 'paused';
    ELSIF _action_type = 'return_for_correction' THEN
      v_new_app_status := 'returned_for_correction'; v_new_instance_status := 'paused';
    ELSIF _action_type = 'request_more_info' THEN
      v_new_app_status := 'info_requested'; v_new_instance_status := 'paused';
    END IF;
  END IF;

  -- Enforce one save_comment per (actor, step) — replace older row
  IF _action_type = 'save_comment' THEN
    DELETE FROM public.approval_actions
     WHERE application_id = _application_id
       AND step_id = v_step.id
       AND actor_id = _actor_id
       AND action_type = 'save_comment';
  END IF;

  INSERT INTO public.approval_actions (
    application_id, workflow_instance_id, step_id, actor_id, action, action_type, comments
  )
  VALUES (
    _application_id, v_instance.id, v_step.id, _actor_id,
    CASE WHEN _action_type = 'save_comment' THEN 'comment_saved' ELSE _action_type END,
    _action_type, _comments
  );

  UPDATE public.workflow_instances
     SET current_step_id = v_new_step_id,
         status = COALESCE(v_new_instance_status, status),
         updated_at = v_now
   WHERE id = v_instance.id;

  IF v_new_app_status IS NOT NULL THEN
    UPDATE public.applications
       SET status = v_new_app_status,
           current_step_id = v_new_step_id,
           updated_at = v_now
     WHERE id = _application_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'action_type', _action_type,
    'application_id', _application_id,
    'application_number', v_app.application_number,
    'new_step_id', v_new_step_id,
    'new_status', COALESCE(v_new_app_status, v_app.status),
    'instance_paused', (v_new_instance_status = 'paused'),
    'used_action_config', v_has_cfg,
    'http', 200
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.permission_has_dependency(_action text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.permission_dependent_actions
    WHERE action = lower(coalesce(_action, ''))
  );
$function$
;
CREATE OR REPLACE FUNCTION public.person_upsert_for_appointment(_full_name text, _fp_individual_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_party uuid;
BEGIN
  PERFORM public.wb_require('entity_structure','propose');
  IF COALESCE(trim(_full_name),'') = '' THEN RAISE EXCEPTION 'Person name is required'; END IF;

  IF _fp_individual_id IS NOT NULL THEN
    SELECT person_party_id INTO v_party FROM public.fp_individual_party_links
     WHERE fp_individual_id = _fp_individual_id;
  END IF;

  IF v_party IS NULL THEN
    INSERT INTO public.parties (party_kind, display_name) VALUES ('PERSON', trim(_full_name))
    RETURNING id INTO v_party;
    INSERT INTO public.persons (party_id, full_name) VALUES (v_party, trim(_full_name))
    ON CONFLICT (party_id) DO NOTHING;
    IF _fp_individual_id IS NOT NULL THEN
      INSERT INTO public.fp_individual_party_links (fp_individual_id, person_party_id, match_method, match_confidence, linked_by)
      VALUES (_fp_individual_id, v_party, 'MANUAL', 'MANUAL', auth.uid())
      ON CONFLICT (fp_individual_id) DO NOTHING;
    END IF;
  END IF;
  RETURN jsonb_build_object('person_party_id', v_party);
END $function$
;
CREATE OR REPLACE FUNCTION public.pfmi_complete_assessment(_assessment_id uuid, _summary text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_a public.pfmi_assessments;
  v_missing int;
  v_overall text;
  v_op public.payment_system_operators;
BEGIN
  IF NOT (public.can_act_on_payment_oversight(auth.uid(), 'edit')
          OR public.can_act_on_payment_oversight(auth.uid(), 'workflow_action')) THEN
    RAISE EXCEPTION 'not_authorised_for_payment_oversight';
  END IF;

  SELECT * INTO v_a FROM public.pfmi_assessments WHERE id = _assessment_id;
  IF v_a.id IS NULL THEN RAISE EXCEPTION 'assessment_not_found'; END IF;
  IF v_a.status = 'completed' THEN RAISE EXCEPTION 'assessment_already_completed'; END IF;

  SELECT count(*) INTO v_missing FROM public.pfmi_assessment_principles
   WHERE assessment_id = _assessment_id AND regulatory_score IS NULL;
  IF v_missing > 0 THEN RAISE EXCEPTION 'principles_not_assessed: %', v_missing; END IF;

  SELECT CASE
      WHEN bool_or(regulatory_score = 'not_observed') THEN 'not_observed'
      WHEN bool_or(regulatory_score = 'partly_observed') THEN 'partly_observed'
      WHEN bool_or(regulatory_score = 'broadly_observed') THEN 'broadly_observed'
      ELSE 'observed' END
    INTO v_overall
    FROM public.pfmi_assessment_principles
   WHERE assessment_id = _assessment_id AND regulatory_score <> 'not_applicable';

  UPDATE public.pfmi_assessments
     SET status = 'completed', completed_at = now(), completed_by = auth.uid(),
         overall_rating = v_overall, summary = COALESCE(_summary, summary), updated_at = now()
   WHERE id = _assessment_id;

  UPDATE public.payment_system_operators
     SET last_pfmi_assessment_date = current_date,
         pfmi_compliance_level = v_overall, updated_at = now()
   WHERE id = v_a.operator_id
  RETURNING * INTO v_op;

  INSERT INTO public.payment_oversight_events (operator_id, assessment_id, event_type, actor_id, metadata)
  VALUES (v_a.operator_id, _assessment_id, 'PFMI_ASSESSMENT_COMPLETED', auth.uid(),
          jsonb_build_object('overall_rating', v_overall, 'reference', v_a.reference));

  IF v_overall IN ('partly_observed', 'not_observed') THEN
    PERFORM public.notification_enqueue_event(
      'prudential.pfmi_non_observance', 'pfmi_assessment', _assessment_id,
      jsonb_build_object(
        'assessment_id', _assessment_id, 'reference', v_a.reference,
        'operator_id', v_a.operator_id, 'operator_name', v_op.operator_name,
        'entity_id', v_op.entity_id, 'overall_rating', v_overall,
        'cta_url', '/prudential/payment-systems/assessments/' || _assessment_id,
        'cta_label', 'Open assessment'),
      v_overall);
  END IF;

  RETURN jsonb_build_object('ok', true, 'overall_rating', v_overall);
END $function$
;
CREATE OR REPLACE FUNCTION public.pfmi_save_principle(_assessment_id uuid, _principle_number integer, _self_score text DEFAULT NULL::text, _regulatory_score text DEFAULT NULL::text, _narrative text DEFAULT NULL::text, _evidence jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_status text;
BEGIN
  IF NOT public.can_act_on_payment_oversight(auth.uid(), 'edit') THEN
    RAISE EXCEPTION 'not_authorised_for_payment_oversight';
  END IF;
  SELECT status INTO v_status FROM public.pfmi_assessments WHERE id = _assessment_id;
  IF v_status IS NULL THEN RAISE EXCEPTION 'assessment_not_found'; END IF;
  IF v_status <> 'in_progress' THEN RAISE EXCEPTION 'assessment_not_editable'; END IF;

  IF _regulatory_score IS NOT NULL AND _regulatory_score NOT IN
     ('observed','broadly_observed','partly_observed','not_observed','not_applicable') THEN
    RAISE EXCEPTION 'invalid_regulatory_score';
  END IF;

  UPDATE public.pfmi_assessment_principles
     SET self_score = COALESCE(_self_score, self_score),
         regulatory_score = COALESCE(_regulatory_score, regulatory_score),
         narrative = COALESCE(_narrative, narrative),
         evidence = COALESCE(_evidence, evidence),
         assessed_by = auth.uid(), assessed_at = now(), updated_at = now()
   WHERE assessment_id = _assessment_id AND principle_number = _principle_number;

  IF NOT FOUND THEN RAISE EXCEPTION 'principle_not_in_assessment'; END IF;
  RETURN jsonb_build_object('ok', true);
END $function$
;
CREATE OR REPLACE FUNCTION public.pfmi_start_assessment(_operator_id uuid, _year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_op public.payment_system_operators;
  v_year int := COALESCE(_year, EXTRACT(YEAR FROM now())::int);
  v_id uuid;
  v_ref text;
  v_seq int;
  v_count int;
BEGIN
  IF NOT (public.can_act_on_payment_oversight(auth.uid(), 'create')
          OR public.can_act_on_payment_oversight(auth.uid(), 'edit')) THEN
    RAISE EXCEPTION 'not_authorised_for_payment_oversight';
  END IF;

  SELECT * INTO v_op FROM public.payment_system_operators WHERE id = _operator_id;
  IF v_op.id IS NULL THEN RAISE EXCEPTION 'operator_not_found'; END IF;

  IF EXISTS (SELECT 1 FROM public.pfmi_assessments
              WHERE operator_id = _operator_id AND status = 'in_progress') THEN
    RAISE EXCEPTION 'assessment_already_in_progress';
  END IF;

  SELECT COALESCE(MAX((regexp_replace(reference, '^PFMI-\d{4}-', ''))::int), 0) + 1
    INTO v_seq FROM public.pfmi_assessments
   WHERE reference LIKE 'PFMI-' || v_year::text || '-%';
  v_ref := 'PFMI-' || v_year::text || '-' || lpad(v_seq::text, 4, '0');

  INSERT INTO public.pfmi_assessments (reference, operator_id, assessment_year, started_by)
  VALUES (v_ref, _operator_id, v_year, auth.uid())
  RETURNING id INTO v_id;

  INSERT INTO public.pfmi_assessment_principles (assessment_id, principle_number)
  SELECT v_id, a.principle_number
    FROM public.pfmi_principle_applicability a
   WHERE a.operator_type = v_op.operator_type;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count = 0 THEN
    INSERT INTO public.pfmi_assessment_principles (assessment_id, principle_number)
    SELECT v_id, p.principle_number FROM public.pfmi_principles p;
  END IF;

  INSERT INTO public.payment_oversight_events (operator_id, assessment_id, event_type, actor_id, metadata)
  VALUES (_operator_id, v_id, 'PFMI_ASSESSMENT_INITIATED', auth.uid(),
          jsonb_build_object('reference', v_ref, 'year', v_year));

  RETURN jsonb_build_object('ok', true, 'assessment_id', v_id, 'reference', v_ref);
END $function$
;
CREATE OR REPLACE FUNCTION public.pin_workflow_instance_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _ver_id uuid;
  _snap jsonb;
BEGIN
  IF NEW.workflow_version_id IS NOT NULL THEN
    IF NEW.version_snapshot IS NULL THEN
      SELECT snapshot INTO NEW.version_snapshot FROM public.approval_workflow_versions WHERE id = NEW.workflow_version_id;
    END IF;
    IF NEW.current_step_key IS NULL AND NEW.current_step_id IS NOT NULL THEN
      NEW.current_step_key := NEW.current_step_id::text;
    END IF;
    RETURN NEW;
  END IF;

  SELECT current_published_version_id INTO _ver_id FROM public.approval_workflows WHERE id = NEW.workflow_id;
  IF _ver_id IS NOT NULL THEN
    SELECT snapshot INTO _snap FROM public.approval_workflow_versions WHERE id = _ver_id;
    NEW.workflow_version_id := _ver_id;
    NEW.version_snapshot := _snap;
    IF NEW.current_step_key IS NULL AND NEW.current_step_id IS NOT NULL THEN
      NEW.current_step_key := NEW.current_step_id::text;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.portal_application_entity_ids(_application_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT entity_id
  FROM (
    SELECT public.safe_uuid(a.data->>'licensee_id') AS entity_id
    FROM public.applications a
    WHERE a.id = _application_id

    UNION

    SELECT p.licensee_id AS entity_id
    FROM public.applications a
    JOIN public.profiles p ON p.id = a.applicant_id
    WHERE a.id = _application_id

    UNION

    SELECT l.id AS entity_id
    FROM public.licenses lic
    JOIN public.licensees l ON l.license_id = lic.id
    WHERE lic.application_id = _application_id

    UNION

    SELECT lic.holder_id AS entity_id
    FROM public.licenses lic
    WHERE lic.application_id = _application_id
      AND EXISTS (SELECT 1 FROM public.licensees l WHERE l.id = lic.holder_id)
  ) s
  WHERE entity_id IS NOT NULL;
$function$
;
CREATE OR REPLACE FUNCTION public.portal_license_entity_ids(_license_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT entity_id
  FROM (
    SELECT l.id AS entity_id
    FROM public.licensees l
    WHERE l.license_id = _license_id

    UNION

    SELECT lic.holder_id AS entity_id
    FROM public.licenses lic
    WHERE lic.id = _license_id
      AND EXISTS (SELECT 1 FROM public.licensees l WHERE l.id = lic.holder_id)

    UNION

    SELECT p.licensee_id AS entity_id
    FROM public.licenses lic
    JOIN public.profiles p ON p.id = lic.holder_id
    WHERE lic.id = _license_id

    UNION

    SELECT e.entity_id
    FROM public.licenses lic
    CROSS JOIN LATERAL public.portal_application_entity_ids(lic.application_id) e(entity_id)
    WHERE lic.id = _license_id
      AND lic.application_id IS NOT NULL
  ) s
  WHERE entity_id IS NOT NULL;
$function$
;
CREATE OR REPLACE FUNCTION public.post_correspondence_message(_thread_id uuid, _body text, _is_internal_note boolean DEFAULT false, _channel text DEFAULT NULL::text, _subject text DEFAULT NULL::text, _dispatch_id uuid DEFAULT NULL::uuid, _is_draft boolean DEFAULT false, _body_format text DEFAULT 'html'::text, _document_ids uuid[] DEFAULT NULL::uuid[], _draft_message_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_staff boolean;
  v_actor text;
  v_t public.correspondence_threads%ROWTYPE;
  v_kind text;
  v_direction text;
  v_internal boolean := COALESCE(_is_internal_note, false);
  v_id uuid;
  v_linked uuid[] := '{}';
  v_doc record;
  v_payload jsonb;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  IF COALESCE(length(TRIM(COALESCE(_body, ''))), 0) = 0 THEN RAISE EXCEPTION 'message_body_required'; END IF;
  IF NOT public.correspondence_thread_visible(_thread_id, v_user) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_t FROM public.correspondence_threads WHERE id = _thread_id;
  IF v_t.id IS NULL THEN RAISE EXCEPTION 'thread_not_found'; END IF;

  v_staff := public.is_internal_staff(v_user);
  v_actor := public.correspondence_actor_label(v_user);

  IF NOT v_staff THEN
    v_internal := false;
    IF v_t.is_entity_facing = false THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;
  END IF;

  IF v_t.thread_state = 'closed' THEN
    IF NOT (v_staff AND public.has_permission(v_user, 'correspondence_management', 'approve')) THEN
      RAISE EXCEPTION 'thread_closed' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF v_t.is_entity_facing = false THEN
    v_internal := true;
  END IF;

  v_kind := CASE WHEN v_internal THEN 'internal'
                 WHEN v_staff THEN 'external_outbound'
                 ELSE 'external_inbound' END;
  v_direction := CASE WHEN v_kind = 'external_inbound' THEN 'inbound'
                      WHEN v_kind = 'external_outbound' THEN 'outbound'
                      ELSE 'internal' END;

  IF _document_ids IS NOT NULL THEN
    FOR v_doc IN SELECT d.* FROM public.documents d WHERE d.id = ANY(_document_ids) LOOP
      IF public.correspondence_case_readable(v_doc.entity_type, v_doc.entity_id, v_user) THEN
        v_linked := v_linked || v_doc.id;
      END IF;
    END LOOP;
  END IF;

  IF _draft_message_id IS NOT NULL THEN
    UPDATE public.correspondence_messages
       SET body = _body,
           body_format = COALESCE(_body_format, 'html'),
           subject = COALESCE(_subject, subject),
           channel = COALESCE(_channel, channel),
           is_internal_note = v_internal,
           message_kind = v_kind,
           direction = v_direction,
           linked_document_ids = v_linked,
           is_draft = COALESCE(_is_draft, false),
           delivery_status = CASE WHEN COALESCE(_is_draft, false) THEN 'draft' ELSE 'sent' END,
           sent_at = CASE WHEN COALESCE(_is_draft, false) THEN sent_at ELSE now() END
     WHERE id = _draft_message_id
       AND thread_id = _thread_id
       AND author_id = v_user
       AND COALESCE(is_draft, false) = true
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN RAISE EXCEPTION 'draft_not_found'; END IF;
  ELSE
    INSERT INTO public.correspondence_messages (
      thread_id, direction, channel, subject, body, body_format, author_id, author_name, author_role,
      message_kind, delivery_status, is_internal_note, dispatch_id, is_draft, linked_document_ids
    ) VALUES (
      _thread_id, v_direction, COALESCE(_channel, v_t.channel), COALESCE(_subject, v_t.subject),
      _body, COALESCE(_body_format, 'html'), v_user, v_actor,
      CASE WHEN v_staff THEN 'Staff' ELSE 'Licensee' END,
      v_kind,
      CASE WHEN COALESCE(_is_draft, false) THEN 'draft'
           WHEN v_kind = 'internal' THEN 'internal' ELSE 'sent' END,
      v_internal, _dispatch_id, COALESCE(_is_draft, false), v_linked
    ) RETURNING id INTO v_id;
  END IF;

  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
  VALUES (_thread_id, v_user, v_actor, CASE WHEN v_staff THEN 'Staff' ELSE 'Licensee' END,
          CASE WHEN COALESCE(_is_draft, false) THEN 'MESSAGE_DRAFT_SAVED' ELSE 'MESSAGE_SENT' END,
          CASE WHEN v_internal THEN 'Internal note' ELSE initcap(replace(v_kind, '_', ' ')) END
            || CASE WHEN array_length(v_linked, 1) IS NOT NULL
                    THEN ' · ' || array_length(v_linked, 1) || ' linked document(s)' ELSE '' END,
          NOT v_internal AND NOT COALESCE(_is_draft, false));

  IF COALESCE(_is_draft, false) THEN
    RETURN v_id;
  END IF;

  IF v_kind = 'external_outbound' THEN
    UPDATE public.correspondence_threads
       SET thread_state = CASE WHEN thread_state = 'closed' THEN thread_state ELSE 'pending_response' END,
           pending_since = CASE WHEN thread_state = 'closed' THEN pending_since ELSE now() END,
           response_due_at = CASE WHEN thread_state = 'closed' THEN response_due_at
                                  ELSE now() + (COALESCE(sla_hours, COALESCE(sla_days, 5) * 24) || ' hours')::interval END,
           sla_warned_at = NULL, sla_breached_at = NULL,
           status = CASE WHEN status IN ('received', 'assigned') THEN 'in_review' ELSE status END
     WHERE id = _thread_id;
  ELSIF v_kind = 'external_inbound' THEN
    UPDATE public.correspondence_threads
       SET thread_state = CASE WHEN thread_state = 'closed' THEN thread_state ELSE 'open' END,
           responded_at = COALESCE(responded_at, now()),
           pending_since = NULL, response_due_at = NULL,
           sla_warned_at = NULL, sla_breached_at = NULL
     WHERE id = _thread_id;
  END IF;

  -- Notifications now flow through the central pipeline so that user
  -- preferences, email delivery, dispatch logging and retries all apply.
  v_payload := jsonb_build_object(
    'thread_id', _thread_id,
    'message_id', v_id,
    'reference', v_t.reference,
    'subject', COALESCE(_subject, v_t.subject),
    'actor_id', v_user,
    'actor_name', v_actor,
    'licensee_id', v_t.licensee_id,
    'assigned_officer_id', v_t.assigned_officer_id,
    'cta_url', '/correspondence/' || _thread_id::text,
    'cta_label', 'Open thread'
  );

  IF v_kind = 'external_outbound' THEN
    PERFORM public.notification_enqueue_event(
      'correspondence.external_message_sent', 'correspondence_thread', _thread_id, v_payload, v_id::text);
  ELSIF v_kind = 'external_inbound' THEN
    PERFORM public.notification_enqueue_event(
      'correspondence.external_response_received', 'correspondence_thread', _thread_id, v_payload, v_id::text);
  ELSE
    PERFORM public.notification_enqueue_event(
      'correspondence.internal_message_posted', 'correspondence_thread', _thread_id, v_payload, v_id::text);
  END IF;

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.ppoc_accessible_license_ids(_user_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH mapped_licensees AS (
    SELECT public.ppoc_mapped_licensee_ids(_user_id) AS licensee_id
  ),
  mapped_profiles AS (
    SELECT p.id AS user_id, p.licensee_id
    FROM public.profiles p
    JOIN mapped_licensees ml ON ml.licensee_id = p.licensee_id
  ),
  mapped_applications AS (
    SELECT a.id
    FROM public.applications a
    JOIN mapped_profiles mp ON mp.user_id = a.applicant_id

    UNION

    SELECT lic.application_id
    FROM public.licensees l
    JOIN mapped_licensees ml ON ml.licensee_id = l.id
    JOIN public.licenses lic ON lic.id = l.license_id
    WHERE lic.application_id IS NOT NULL
  )
  SELECT DISTINCT lic.id
  FROM public.licenses lic
  LEFT JOIN public.licensees linked_licensee ON linked_licensee.license_id = lic.id
  WHERE lic.holder_id IN (SELECT licensee_id FROM mapped_licensees)
     OR lic.holder_id IN (SELECT user_id FROM mapped_profiles)
     OR linked_licensee.id IN (SELECT licensee_id FROM mapped_licensees)
     OR lic.application_id IN (SELECT id FROM mapped_applications)
$function$
;
CREATE OR REPLACE FUNCTION public.ppoc_mapped_licensee_ids(_user_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT m.licensee_id
  FROM public.ppoc_entity_mappings m
  JOIN public.licensees l ON l.id = m.licensee_id
  WHERE m.ppoc_user_id = _user_id
    AND m.is_active = true
    AND EXISTS (
      SELECT 1
      FROM public.ppoc_mapping_sectors s
      WHERE s.mapping_id = m.id
        AND l.sector_id IS NOT NULL
        AND s.sector_id = l.sector_id
    )
$function$
;
CREATE OR REPLACE FUNCTION public.prevent_audit_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'Audit log rows are immutable (table=%, op=%)', TG_TABLE_NAME, TG_OP
    USING ERRCODE = '42501';
END;
$function$
;
CREATE OR REPLACE FUNCTION public.prevent_direct_application_workflow_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_trusted text;
BEGIN
  -- Trusted RPCs set this GUC for the duration of their transaction.
  v_trusted := current_setting('app.workflow_mutation_context', true);
  IF v_trusted = 'trusted' THEN
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status
     OR NEW.current_step_id IS DISTINCT FROM OLD.current_step_id
     OR NEW.workflow_id IS DISTINCT FROM OLD.workflow_id
     OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
     OR NEW.rejected_at IS DISTINCT FROM OLD.rejected_at
     OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
     OR NEW.cancelled_at IS DISTINCT FROM OLD.cancelled_at
  THEN
    RAISE EXCEPTION 'WORKFLOW_FIELD_LOCKED: applications.% can only be changed via approved RPCs',
      CASE
        WHEN NEW.status IS DISTINCT FROM OLD.status THEN 'status'
        WHEN NEW.current_step_id IS DISTINCT FROM OLD.current_step_id THEN 'current_step_id'
        WHEN NEW.workflow_id IS DISTINCT FROM OLD.workflow_id THEN 'workflow_id'
        WHEN NEW.approved_at IS DISTINCT FROM OLD.approved_at THEN 'approved_at'
        WHEN NEW.rejected_at IS DISTINCT FROM OLD.rejected_at THEN 'rejected_at'
        WHEN NEW.submitted_at IS DISTINCT FROM OLD.submitted_at THEN 'submitted_at'
        ELSE 'cancelled_at'
      END
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.prevent_duplicate_active_application()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sector uuid;
  v_sub uuid;
  v_cat uuid;
  v_svc uuid;
  v_existing_id uuid;
  v_settings jsonb;
  v_allow_reapply boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status IN ('draft','cancelled','rejected','withdrawn') THEN
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.status = OLD.status THEN RETURN NEW; END IF;
    IF NEW.status IN ('draft','cancelled','rejected','withdrawn') THEN
      RETURN NEW;
    END IF;
  END IF;

  IF public.has_role(auth.uid(), 'super_admin'::app_role)
     OR public.has_role(auth.uid(), 'admin'::app_role) THEN
    RETURN NEW;
  END IF;

  v_sector := NULLIF(NEW.data->>'sector_id','')::uuid;
  v_sub    := NULLIF(NEW.data->>'sub_sector_id','')::uuid;
  v_cat    := NULLIF(NEW.data->>'category_id','')::uuid;
  v_svc    := NULLIF(NEW.data->>'service_id','')::uuid;
  IF v_sector IS NULL THEN
    RETURN NEW;
  END IF;

  -- Read admin setting.
  SELECT value INTO v_settings
  FROM public.site_settings WHERE key = 'application_settings' LIMIT 1;
  v_allow_reapply := COALESCE(
    (v_settings->>'allow_reapplication')::boolean,
    (v_settings->>'allow_reapplication_after_final')::boolean,
    true
  );

  -- Active / in-progress / payment-pending duplicates are ONLY blocked when
  -- re-application is disabled. When allow_reapply = true, the user is
  -- explicitly permitted to start a parallel application for the same triple.
  IF NOT v_allow_reapply THEN
    SELECT id INTO v_existing_id
    FROM public.applications
    WHERE applicant_id = NEW.applicant_id
      AND id <> NEW.id
      AND COALESCE(data->>'sector_id','')      = COALESCE(v_sector::text,'')
      AND COALESCE(data->>'sub_sector_id','')  = COALESCE(v_sub::text,'')
      AND COALESCE(data->>'category_id','')    = COALESCE(v_cat::text,'')
      AND COALESCE(data->>'service_id','')     = COALESCE(v_svc::text,'')
      AND status IN (
        'submitted','in_progress','in_review','pending_review','under_review',
        'forwarded','query_raised','resubmission_requested','awaiting_approval',
        'payment_pending','awaiting_payment','pending_payment'
      )
    LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
      RAISE EXCEPTION 'DUPLICATE_ACTIVE_APPLICATION: An active application already exists for this sector / sub-sector / service (id=%).', v_existing_id
        USING ERRCODE = 'check_violation';
    END IF;

    -- Block approved/rejected duplicates only when policy is OFF.
    SELECT id INTO v_existing_id
    FROM public.applications
    WHERE applicant_id = NEW.applicant_id
      AND id <> NEW.id
      AND COALESCE(data->>'sector_id','')      = COALESCE(v_sector::text,'')
      AND COALESCE(data->>'sub_sector_id','')  = COALESCE(v_sub::text,'')
      AND COALESCE(data->>'category_id','')    = COALESCE(v_cat::text,'')
      AND COALESCE(data->>'service_id','')     = COALESCE(v_svc::text,'')
      AND status IN ('approved','rejected')
    LIMIT 1;
    IF v_existing_id IS NOT NULL THEN
      RAISE EXCEPTION 'REAPPLICATION_DISABLED: Re-application is not permitted for this sector / sub-sector / service (existing id=%).', v_existing_id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.prevent_new_application_when_active_exists()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_allow_reapp boolean;
  v_active_count int;
BEGIN
  IF public.has_role(NEW.applicant_id, 'admin') OR public.has_role(NEW.applicant_id, 'super_admin') THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE((value->>'allow_reapplication')::boolean, true) INTO v_allow_reapp
  FROM public.site_settings WHERE key = 'application_settings';

  IF v_allow_reapp IS NULL OR v_allow_reapp = true THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*) INTO v_active_count
  FROM public.applications
  WHERE applicant_id = NEW.applicant_id
    AND id <> NEW.id
    AND status NOT IN ('draft','cancelled','rejected','withdrawn','closed');

  IF v_active_count > 0 THEN
    RAISE EXCEPTION 'You cannot submit a new application while your previous application is still being processed.'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.process_preview(_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  v_code text := COALESCE(_payload->>'process_code','LICENCE_RENEWAL');
  v_matter text := COALESCE(_payload->>'matter_kind', CASE v_code
                     WHEN 'LICENCE_RENEWAL' THEN 'renewal'
                     WHEN 'LICENCE_APPLICATION' THEN 'application'
                     ELSE 'registration' END);
  tpl record; v_fees jsonb; v_steps jsonb := '[]'::jsonb; s jsonb; v_tplv record;
BEGIN
  IF uid IS NULL OR NOT public.is_internal_staff_user(uid) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501'; END IF;

  SELECT * INTO tpl FROM public.process_templates
   WHERE process_code = v_code
     AND (regulator_id IS NULL OR regulator_id = NULLIF(_payload->>'regulator_id','')::uuid)
     AND (sector_id    IS NULL OR sector_id    = NULLIF(_payload->>'sector_id','')::uuid)
     AND (license_type IS NULL OR license_type = NULLIF(_payload->>'license_type',''))
     AND effective_from <= current_date
     AND (effective_to IS NULL OR effective_to >= current_date)
   ORDER BY is_active DESC,
            (CASE WHEN license_type IS NOT NULL THEN 4 ELSE 0 END
           + CASE WHEN sector_id    IS NOT NULL THEN 2 ELSE 0 END
           + CASE WHEN regulator_id IS NOT NULL THEN 1 ELSE 0 END) DESC,
            version DESC
   LIMIT 1;
  IF tpl IS NULL THEN
    RETURN jsonb_build_object('resolved', false, 'reason', 'No process template configured for this selection.');
  END IF;

  v_fees := (public.license_fee_simulate(_payload || jsonb_build_object('matter_kind', v_matter)))->'candidates';

  SELECT * INTO v_tplv FROM public.license_verification_templates t
   WHERE t.matter_kind = v_matter
     AND t.superseded_by IS NULL
     AND (t.license_type IS NULL OR t.license_type = NULLIF(_payload->>'license_type',''))
     AND (t.sector_id    IS NULL OR t.sector_id    = NULLIF(_payload->>'sector_id','')::uuid)
     AND (t.regulator_id IS NULL OR t.regulator_id = NULLIF(_payload->>'regulator_id','')::uuid)
   ORDER BY t.is_active DESC, t.version DESC LIMIT 1;

  FOR s IN SELECT value FROM jsonb_array_elements(tpl.steps) LOOP
    DECLARE
      v_code2 text := s->>'key';
      v_fee jsonb := (SELECT x FROM jsonb_array_elements(COALESCE(v_fees,'[]'::jsonb)) x
                       WHERE x->>'workflow_step_key' = v_code2 LIMIT 1);
    BEGIN
      v_steps := v_steps || jsonb_build_array(s || jsonb_build_object(
        'resolved_fee', v_fee,
        'fee_state', CASE
           WHEN v_fee IS NULL AND (s->'fee') IS NULL THEN 'not_applicable'
           WHEN v_fee IS NULL THEN 'not_configured'
           WHEN (v_fee->>'would_assess')::boolean THEN 'enabled'
           ELSE 'disabled' END,
        'resolved_verification', CASE WHEN COALESCE((s->>'verification')::boolean,false) AND v_tplv.id IS NOT NULL
           THEN jsonb_build_object('template_key', v_tplv.template_key, 'version', v_tplv.version,
                                   'active', v_tplv.is_active, 'purpose', v_tplv.purpose,
                                   'mandatory_items', (SELECT count(*) FROM jsonb_array_elements(v_tplv.items) i
                                                        WHERE COALESCE((i->>'required')::boolean,true)),
                                   'total_items', jsonb_array_length(v_tplv.items))
           ELSE NULL END));
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'resolved', true,
    'process_code', tpl.process_code,
    'template_key', tpl.template_key,
    'template_version', tpl.version,
    'template_name', tpl.name,
    'template_active', tpl.is_active,
    'purpose', tpl.purpose,
    'matter_kind', v_matter,
    'steps', v_steps);
END $function$
;
CREATE OR REPLACE FUNCTION public.provision_application_entity(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app record;
  v_app_data jsonb;
  v_license record;
  v_licensee_id uuid;
  v_entity_name text;
  v_paid boolean;
  v_cfg jsonb;
  v_period_days int;
  v_valid_from timestamptz;
  v_valid_until timestamptz;
  v_reg record;
  v_plu record;
  v_prof record;
  v_is_renewal boolean;
  v_renewal_license_id uuid;
  v_existing_license record;
  v_prev_valid_until timestamptz;
  v_new_valid_until timestamptz;
  v_computed_text text;
  v_rule jsonb;
  v_best_rule jsonb;
  v_best_score int;
  v_score int;
  v_lic_sector uuid;
  v_lic_sub uuid;
  v_lic_cat uuid;
  v_policy jsonb;
  v_marker_license_id uuid;
  v_entity_id uuid;
  v_party_id uuid;
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  SELECT id, applicant_id, application_number, status, license_type,
         regulator_id, data, entity_id
    INTO v_app FROM public.applications WHERE id = _application_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  IF v_app.status <> 'approved' THEN
    RETURN jsonb_build_object('success', false, 'code','AWAITING_APPROVAL','http',200,
                              'application_id', _application_id);
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.payments
     WHERE application_id = _application_id
       AND status IN ('success','completed','paid','verified')
  ) INTO v_paid;

  IF NOT v_paid THEN
    RETURN jsonb_build_object('success', false, 'code','AWAITING_PAYMENT','http',200,
                              'application_id', _application_id);
  END IF;

  v_app_data := COALESCE(v_app.data, '{}'::jsonb);

  v_is_renewal := (v_app_data->>'is_renewal') = 'true'
              AND NULLIF(v_app_data->>'renewal_of_license_id','') IS NOT NULL;

  IF v_is_renewal THEN
    BEGIN
      v_renewal_license_id := (v_app_data->>'renewal_of_license_id')::uuid;
    EXCEPTION WHEN others THEN
      RETURN jsonb_build_object('error','Invalid renewal_of_license_id','code','RENEWAL_LICENSE_INVALID','http',409);
    END;

    IF v_app_data ? 'renewal_processed_at' THEN
      v_marker_license_id := COALESCE(
        NULLIF(v_app_data->>'renewed_license_id','')::uuid,
        v_renewal_license_id);
      SELECT id, license_number, valid_from, valid_until,
             sector_id, sub_sector_id, category_id
        INTO v_license
        FROM public.licenses WHERE id = v_marker_license_id;
      IF FOUND THEN
        v_licensee_id := public.entity_for_license(v_license.id, _application_id);
        RETURN jsonb_build_object('success', true, 'http', 200,
          'renewal', true,
          'idempotent', true,
          'application_id', _application_id,
          'license_id', v_license.id,
          'license_number', v_license.license_number,
          'valid_from', v_license.valid_from,
          'valid_until', v_license.valid_until,
          'new_valid_until', v_license.valid_until,
          'licensee_id', v_licensee_id,
          'applicant_id', v_app.applicant_id);
      END IF;
    END IF;

    SELECT id, license_number, valid_from, valid_until, status,
           sector_id, sub_sector_id, category_id
      INTO v_existing_license
      FROM public.licenses
     WHERE id = v_renewal_license_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('error','Original license not found','code','RENEWAL_LICENSE_NOT_FOUND','http',404);
    END IF;

    v_prev_valid_until := v_existing_license.valid_until;

    v_computed_text := NULLIF(v_app_data->>'computed_new_valid_until','');
    v_new_valid_until := NULL;
    IF v_computed_text IS NOT NULL THEN
      BEGIN
        v_new_valid_until := v_computed_text::timestamptz;
        IF v_new_valid_until <= now() THEN
          v_new_valid_until := NULL;
        END IF;
      EXCEPTION WHEN others THEN
        v_new_valid_until := NULL;
      END;
    END IF;

    IF v_new_valid_until IS NULL THEN
      v_cfg := COALESCE(
        (SELECT value FROM public.site_settings WHERE key = 'license_expiry'),
        '{}'::jsonb);

      v_lic_sector := v_existing_license.sector_id;
      v_lic_sub := v_existing_license.sub_sector_id;
      v_lic_cat := v_existing_license.category_id;

      v_best_rule := NULL;
      v_best_score := -1;
      IF jsonb_typeof(v_cfg->'rules') = 'array' THEN
        FOR v_rule IN SELECT * FROM jsonb_array_elements(v_cfg->'rules') LOOP
          IF NULLIF(v_rule->>'sector_id','') IS NOT NULL
             AND (v_lic_sector IS NULL OR (v_rule->>'sector_id')::uuid <> v_lic_sector) THEN
            CONTINUE;
          END IF;
          IF NULLIF(v_rule->>'sub_sector_id','') IS NOT NULL
             AND (v_lic_sub IS NULL OR (v_rule->>'sub_sector_id')::uuid <> v_lic_sub) THEN
            CONTINUE;
          END IF;
          IF NULLIF(v_rule->>'category_id','') IS NOT NULL
             AND (v_lic_cat IS NULL OR (v_rule->>'category_id')::uuid <> v_lic_cat) THEN
            CONTINUE;
          END IF;
          v_score :=
            (CASE WHEN NULLIF(v_rule->>'category_id','') IS NOT NULL THEN 4 ELSE 0 END)
          + (CASE WHEN NULLIF(v_rule->>'sub_sector_id','') IS NOT NULL THEN 2 ELSE 0 END)
          + (CASE WHEN NULLIF(v_rule->>'sector_id','') IS NOT NULL THEN 1 ELSE 0 END);
          IF v_score > v_best_score THEN
            v_best_score := v_score;
            v_best_rule := v_rule;
          END IF;
        END LOOP;
      END IF;

      v_policy := COALESCE(v_best_rule, v_cfg->'default', v_cfg);
      v_period_days := GREATEST(1, COALESCE(NULLIF(v_policy->>'period_days','')::int, 365));

      v_new_valid_until := GREATEST(COALESCE(v_existing_license.valid_until, now()), now())
                            + make_interval(days => v_period_days);
    END IF;

    UPDATE public.licenses
       SET valid_until = v_new_valid_until,
           status = 'active',
           updated_at = now()
     WHERE id = v_existing_license.id
     RETURNING id, license_number, valid_from, valid_until,
               sector_id, sub_sector_id, category_id
      INTO v_license;

    v_licensee_id := public.entity_for_license(v_license.id, _application_id);

    IF v_licensee_id IS NOT NULL THEN
      UPDATE public.licensees
         SET sector_id     = COALESCE(sector_id,     v_license.sector_id,
                                       NULLIF(v_app_data->>'sector_id','')::uuid),
             sub_sector_id = COALESCE(sub_sector_id, v_license.sub_sector_id,
                                       NULLIF(v_app_data->>'sub_sector_id','')::uuid),
             category_id   = COALESCE(category_id,   v_license.category_id,
                                       NULLIF(v_app_data->>'category_id','')::uuid),
             updated_at    = now()
       WHERE id = v_licensee_id
         AND (sector_id IS NULL OR sub_sector_id IS NULL OR category_id IS NULL);
    END IF;

    PERFORM public.entity_link_license(v_licensee_id, v_license.id, _application_id);

    UPDATE public.applications
       SET data = COALESCE(data, '{}'::jsonb) || jsonb_build_object(
             'renewal_processed_at', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
             'renewed_license_id', v_license.id::text,
             'renewed_valid_until', to_char(v_license.valid_until AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
           ),
           updated_at = now()
     WHERE id = _application_id;

    PERFORM public.create_audit_log(v_app.applicant_id, 'license_renewed', 'license',
      v_license.id::text, NULL,
      jsonb_build_object(
        'application_id', _application_id,
        'license_id', v_license.id,
        'license_number', v_license.license_number,
        'previous_valid_until', v_prev_valid_until,
        'new_valid_until', v_license.valid_until,
        'licensee_id', v_licensee_id
      ), NULL);

    RETURN jsonb_build_object('success', true, 'http', 200,
      'renewal', true,
      'application_id', _application_id,
      'license_id', v_license.id,
      'license_number', v_license.license_number,
      'valid_from', v_license.valid_from,
      'valid_until', v_license.valid_until,
      'new_valid_until', v_license.valid_until,
      'previous_valid_until', v_prev_valid_until,
      'licensee_id', v_licensee_id,
      'applicant_id', v_app.applicant_id);
  END IF;

  -- Non-renewal path
  v_cfg := COALESCE(
    (SELECT value FROM public.site_settings WHERE key = 'license_expiry'),
    '{}'::jsonb);
  v_period_days := GREATEST(1, COALESCE(NULLIF(v_cfg->>'period_days','')::int, 365));
  v_valid_from := now();
  v_valid_until := v_valid_from + make_interval(days => v_period_days);

  SELECT id, license_number, valid_from, valid_until,
         sector_id, sub_sector_id, category_id
    INTO v_license
    FROM public.licenses WHERE application_id = _application_id LIMIT 1;
  IF v_license.id IS NULL THEN
    INSERT INTO public.licenses (application_id, holder_id, license_type, regulator_id,
      sector_id, sub_sector_id, category_id, valid_from, valid_until)
    VALUES (_application_id, v_app.applicant_id, v_app.license_type, v_app.regulator_id,
      NULLIF(v_app_data->>'sector_id','')::uuid,
      NULLIF(v_app_data->>'sub_sector_id','')::uuid,
      NULLIF(v_app_data->>'category_id','')::uuid,
      v_valid_from, v_valid_until)
    RETURNING id, license_number, valid_from, valid_until,
              sector_id, sub_sector_id, category_id INTO v_license;
  END IF;

  -- Entity-first issuance: the canonical entity is resolved (or created once)
  -- BEFORE the licence is linked. A licence is never the entity's identity.
  v_licensee_id := public.entity_for_license(v_license.id, _application_id);

  IF v_licensee_id IS NULL THEN
    SELECT applicant_name INTO v_reg
      FROM public.registrations WHERE user_id = v_app.applicant_id
      ORDER BY created_at DESC LIMIT 1;
    SELECT entity_name, full_name INTO v_plu
      FROM public.pre_license_users WHERE id = v_app.applicant_id LIMIT 1;
    SELECT entity_name, full_name INTO v_prof
      FROM public.profiles WHERE id = v_app.applicant_id LIMIT 1;

    v_entity_name := COALESCE(
      NULLIF(v_app_data->>'entity_name',''),
      NULLIF(v_app_data->>'applicant_name',''),
      NULLIF(v_app_data->>'organization_name',''),
      NULLIF(v_plu.entity_name,''),
      NULLIF(v_plu.full_name,''),
      NULLIF(v_prof.entity_name,''),
      NULLIF(v_prof.full_name,''),
      NULLIF(v_reg.applicant_name,''),
      'Unnamed Licensee'
    );

    -- 1. Application already bound to a canonical entity -> always reuse it.
    v_entity_id := v_app.entity_id;

    -- 2. Deterministic reuse on exact normalized legal name (EXACT_MATCH never
    --    creates a duplicate). Same-applicant rows win the tie-break.
    IF v_entity_id IS NULL THEN
      SELECT l.id INTO v_entity_id
        FROM public.licensees l
        LEFT JOIN public.organizations o ON o.party_id = l.party_id
       WHERE l.merged_into_entity_id IS NULL
         AND upper(regexp_replace(COALESCE(o.legal_name, l.name), '[^A-Za-z0-9]', '', 'g'))
             = upper(regexp_replace(v_entity_name, '[^A-Za-z0-9]', '', 'g'))
       ORDER BY (l.applicant_id = v_app.applicant_id) DESC, l.created_at
       LIMIT 1;
    END IF;

    WHILE v_entity_id IS NOT NULL
      AND (SELECT merged_into_entity_id FROM public.licensees WHERE id = v_entity_id) IS NOT NULL LOOP
      SELECT merged_into_entity_id INTO v_entity_id FROM public.licensees WHERE id = v_entity_id;
    END LOOP;

    IF v_entity_id IS NULL THEN
      INSERT INTO public.parties (party_kind, display_name)
      VALUES ('ORGANIZATION', v_entity_name)
      RETURNING id INTO v_party_id;

      INSERT INTO public.organizations (party_id, legal_name, display_name, legal_name_authority)
      VALUES (v_party_id, v_entity_name, v_entity_name, 'LOCAL_VERIFIED');

      INSERT INTO public.licensees (
        license_id, name, applicant_id,
        sector_id, sub_sector_id, category_id,
        party_id, lifecycle_stage_id, identity_status_id
      )
      VALUES (
        v_license.id, v_entity_name, v_app.applicant_id,
        COALESCE(v_license.sector_id,     NULLIF(v_app_data->>'sector_id','')::uuid),
        COALESCE(v_license.sub_sector_id, NULLIF(v_app_data->>'sub_sector_id','')::uuid),
        COALESCE(v_license.category_id,   NULLIF(v_app_data->>'category_id','')::uuid),
        v_party_id,
        (SELECT id FROM public.lifecycle_stages WHERE key = 'authorised' AND domain = 'entity'),
        (SELECT id FROM public.entity_identity_statuses WHERE key = 'verified')
      )
      RETURNING id INTO v_licensee_id;
      v_entity_id := v_licensee_id;
    ELSE
      v_licensee_id := v_entity_id;
      UPDATE public.licensees
         SET license_id    = COALESCE(license_id, v_license.id),
             applicant_id  = COALESCE(applicant_id, v_app.applicant_id),
             sector_id     = COALESCE(sector_id,     v_license.sector_id,
                                       NULLIF(v_app_data->>'sector_id','')::uuid),
             sub_sector_id = COALESCE(sub_sector_id, v_license.sub_sector_id,
                                       NULLIF(v_app_data->>'sub_sector_id','')::uuid),
             category_id   = COALESCE(category_id,   v_license.category_id,
                                       NULLIF(v_app_data->>'category_id','')::uuid),
             lifecycle_stage_id = COALESCE(lifecycle_stage_id,
                                       (SELECT id FROM public.lifecycle_stages WHERE key = 'authorised' AND domain = 'entity')),
             identity_status_id = COALESCE(identity_status_id,
                                       (SELECT id FROM public.entity_identity_statuses WHERE key = 'verified')),
             updated_at    = now()
       WHERE id = v_licensee_id;
    END IF;
  ELSE
    v_entity_id := v_licensee_id;
    UPDATE public.licensees
       SET sector_id     = COALESCE(sector_id,     v_license.sector_id,
                                     NULLIF(v_app_data->>'sector_id','')::uuid),
           sub_sector_id = COALESCE(sub_sector_id, v_license.sub_sector_id,
                                     NULLIF(v_app_data->>'sub_sector_id','')::uuid),
           category_id   = COALESCE(category_id,   v_license.category_id,
                                     NULLIF(v_app_data->>'category_id','')::uuid),
           updated_at    = now()
     WHERE id = v_licensee_id
       AND (sector_id IS NULL OR sub_sector_id IS NULL OR category_id IS NULL);
  END IF;

  PERFORM public.entity_link_license(v_entity_id, v_license.id, _application_id);

  PERFORM public.create_audit_log(v_app.applicant_id, 'entity_provisioned', 'license',
    v_license.id::text, NULL,
    jsonb_build_object(
      'application_id', _application_id,
      'license_number', v_license.license_number,
      'licensee_id', v_licensee_id
    ), NULL);

  RETURN jsonb_build_object('success', true, 'http', 200,
    'application_id', _application_id,
    'license_id', v_license.id,
    'license_number', v_license.license_number,
    'valid_from', v_license.valid_from,
    'valid_until', v_license.valid_until,
    'licensee_id', v_licensee_id,
    'applicant_id', v_app.applicant_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_action_issue(_entity_id uuid, _action_type text, _title text, _description text DEFAULT NULL::text, _severity text DEFAULT 'medium'::text, _due_date date DEFAULT NULL::date, _assigned_to uuid DEFAULT NULL::uuid, _source_type text DEFAULT 'manual'::text, _source_id uuid DEFAULT NULL::uuid, _evidence_required boolean DEFAULT false, _entity_contact text DEFAULT NULL::text, _response_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _breach_after_days integer DEFAULT NULL::integer, _entity_owner_user_id uuid DEFAULT NULL::uuid)
 RETURNS prudential_actions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.prudential_actions;
BEGIN
  PERFORM public.prudential_enforce('initiate_supervisory_action', _entity_id);
  IF _entity_id IS NULL OR _action_type IS NULL OR _title IS NULL THEN
    RAISE EXCEPTION 'entity, action type and title are required' USING ERRCODE='22023';
  END IF;
  PERFORM public.prudential_require_rationale(_description, 10, 'action description');
  INSERT INTO public.prudential_actions(
    entity_id, action_type, title, description, severity, due_date, assigned_to,
    source_type, source_id, evidence_required, entity_contact, response_due_at,
    breach_after_days, entity_owner_user_id, status, created_by)
  VALUES (_entity_id, _action_type, _title, _description, COALESCE(_severity,'medium'), _due_date, _assigned_to,
    COALESCE(_source_type,'manual'), _source_id, COALESCE(_evidence_required,false), _entity_contact, _response_due_at,
    COALESCE(_breach_after_days, 7), _entity_owner_user_id, 'open', auth.uid())
  RETURNING * INTO v_row;
  PERFORM public.prudential_audit_event('prudential_action_issued','prudential_action',v_row.id,
    NULL, to_jsonb(v_row), jsonb_build_object('entity_id',_entity_id,'source_type',_source_type,'source_id',_source_id), _description, 'CREATE');
  RETURN v_row;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_action_monitor(_entity_id uuid DEFAULT NULL::uuid, _due_soon_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _rows jsonb;
BEGIN
  IF _uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHENTICATED');
  END IF;

  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'due_date' NULLS LAST), '[]'::jsonb) INTO _rows
  FROM (
    SELECT jsonb_build_object(
             'id', a.id,
             'action_reference', a.action_reference,
             'entity_id', a.entity_id,
             'entity_name', l.name,
             'title', a.title,
             'action_type', a.action_type,
             'severity', a.severity,
             'status', a.status,
             'review_status', a.review_status,
             'evidence_required', a.evidence_required,
             'progress_percent', a.progress_percent,
             'due_date', a.due_date,
             'breached_at', a.breached_at,
             'source_type', a.source_type,
             'source_id', a.source_id,
             'assigned_to', a.assigned_to,
             'bucket', CASE
               WHEN a.status = 'breached' THEN 'breached'
               WHEN a.status = 'overdue' THEN 'overdue'
               WHEN a.status = 'awaiting_review' THEN 'awaiting_review'
               WHEN a.status = 'awaiting_evidence' THEN 'awaiting_evidence'
               WHEN a.status = 'completed' THEN 'completed'
               WHEN a.status IN ('open','in_progress') AND a.due_date IS NOT NULL
                    AND a.due_date <= (CURRENT_DATE + GREATEST(COALESCE(_due_soon_days,7),0))
                    AND a.due_date >= CURRENT_DATE THEN 'due_soon'
               WHEN a.status IN ('open','in_progress') THEN 'open'
               ELSE 'other' END
           ) AS x
      FROM public.prudential_actions a
      LEFT JOIN public.licensees l ON l.id = a.entity_id
     WHERE (_entity_id IS NULL OR a.entity_id = _entity_id)
       AND public.can_read_prudential_entity(_uid, a.entity_id)
  ) s;

  RETURN jsonb_build_object(
    'rows', _rows,
    'counts', (
      SELECT COALESCE(jsonb_object_agg(bucket, c), '{}'::jsonb)
        FROM (SELECT r->>'bucket' AS bucket, count(*) AS c
                FROM jsonb_array_elements(_rows) r GROUP BY 1) g
    ),
    'generated_at', now()
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.prudential_action_update(_action_id uuid, _patch jsonb DEFAULT '{}'::jsonb, _reason text DEFAULT NULL::text)
 RETURNS prudential_actions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.prudential_actions; v_after public.prudential_actions;
        v_to text; v_uid uuid := auth.uid();
BEGIN
  SELECT * INTO v_before FROM public.prudential_actions WHERE id = _action_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'supervisory action % not found', _action_id USING ERRCODE='P0002'; END IF;
  v_to := NULLIF(_patch->>'status','');

  IF v_to IS NULL THEN
    PERFORM public.prudential_enforce('edit', v_before.entity_id);
  ELSIF v_to IN ('completed','waived','cancelled') THEN
    PERFORM public.prudential_enforce('manage_remediation', v_before.entity_id);
  ELSE
    PERFORM public.prudential_enforce('workflow_action', v_before.entity_id);
  END IF;

  IF v_before.status IN ('completed','waived','cancelled') THEN
    RAISE EXCEPTION 'supervisory action % is already closed (%)', _action_id, v_before.status USING ERRCODE='55000';
  END IF;
  IF v_to IS NOT NULL AND v_to NOT IN ('open','in_progress','awaiting_evidence','awaiting_review','completed','overdue','breached','waived','cancelled') THEN
    RAISE EXCEPTION 'unsupported supervisory action status %', v_to USING ERRCODE='22023';
  END IF;
  IF v_to IN ('completed','waived','cancelled') THEN
    PERFORM public.prudential_require_rationale(_reason, 10, 'closure rationale');
  END IF;

  UPDATE public.prudential_actions a
  SET status = COALESCE(v_to, a.status),
      title = COALESCE(_patch->>'title', a.title),
      description = COALESCE(_patch->>'description', a.description),
      severity = COALESCE(_patch->>'severity', a.severity),
      due_date = COALESCE((_patch->>'due_date')::date, a.due_date),
      assigned_to = COALESCE((_patch->>'assigned_to')::uuid, a.assigned_to),
      entity_contact = COALESCE(_patch->>'entity_contact', a.entity_contact),
      response_due_at = COALESCE((_patch->>'response_due_at')::timestamptz, a.response_due_at),
      progress_percent = COALESCE((_patch->>'progress_percent')::int, a.progress_percent),
      review_status = COALESCE(_patch->>'review_status', a.review_status),
      review_notes = COALESCE(_patch->>'review_notes', a.review_notes),
      reviewed_by = CASE WHEN _patch ? 'review_status' THEN v_uid ELSE a.reviewed_by END,
      reviewed_at = CASE WHEN _patch ? 'review_status' THEN now() ELSE a.reviewed_at END,
      completion_notes = CASE WHEN v_to='completed' THEN _reason ELSE a.completion_notes END,
      waiver_reason = CASE WHEN v_to='waived' THEN _reason ELSE a.waiver_reason END,
      cancellation_reason = CASE WHEN v_to='cancelled' THEN _reason ELSE a.cancellation_reason END,
      closed_at = CASE WHEN v_to IN ('completed','waived','cancelled') THEN now() ELSE a.closed_at END,
      closed_by = CASE WHEN v_to IN ('completed','waived','cancelled') THEN v_uid ELSE a.closed_by END,
      updated_at = now()
  WHERE a.id = _action_id
  RETURNING * INTO v_after;

  PERFORM public.prudential_audit_event(
    COALESCE('prudential_action_'||v_to,'prudential_action_updated'),'prudential_action',_action_id,
    to_jsonb(v_before), to_jsonb(v_after),
    jsonb_build_object('entity_id',v_before.entity_id,'from_status',v_before.status,'to_status',v_after.status),
    _reason, 'UPDATE');
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_analytics_metric_context(_metric_code text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH facts AS (
    SELECT c.entity_id, c.reporting_period_id, c.period_end, c.period_label
      FROM public.v_return_metric_facts_current c
     WHERE upper(c.metric_code) = upper(_metric_code)
       AND c.value_numeric IS NOT NULL
  )
  SELECT jsonb_build_object(
    'metric', (SELECT jsonb_build_object('metric_code', m.code, 'metric_name', m.name, 'unit', m.unit)
                 FROM public.regulatory_metrics m
                WHERE upper(m.code) = upper(_metric_code) LIMIT 1),
    'entities', COALESCE((
      SELECT jsonb_agg(s.e ORDER BY s.e->>'entity_name')
        FROM (
          SELECT jsonb_build_object(
                   'entity_id', l.id,
                   'entity_name', COALESCE(l.name, 'Entity ' || left(l.id::text, 8)),
                   'sector_id', l.sector_id,
                   'category_id', l.category_id,
                   'latest_available_period', max(fa.period_end),
                   'fact_count', count(*)
                 ) AS e
            FROM facts fa
            JOIN public.licensees l ON l.id = fa.entity_id
           GROUP BY l.id, l.name, l.sector_id, l.category_id
        ) s), '[]'::jsonb),
    'periods', COALESCE((
      SELECT jsonb_agg(s2.pp ORDER BY s2.pp->>'period_end' DESC)
        FROM (
          SELECT DISTINCT jsonb_build_object(
                   'reporting_period_id', fa.reporting_period_id,
                   'period_end', fa.period_end,
                   'period_label', fa.period_label) AS pp
            FROM facts fa
        ) s2), '[]'::jsonb)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_analytics_metric_trend(_entity_id uuid, _metric_code text, _limit integer DEFAULT 24)
 RETURNS TABLE(entity_id uuid, filing_id uuid, filing_version_id uuid, reporting_period_id uuid, period_end date, period_label text, metric_code text, value_numeric numeric, availability text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT t.entity_id, t.filing_id, t.filing_version_id, t.reporting_period_id,
         t.period_end, t.period_label, t.metric_code, t.value_numeric, t.availability
    FROM (
      SELECT DISTINCT ON (c.reporting_period_id)
             c.entity_id, c.filing_id, c.filing_version_id, c.reporting_period_id,
             c.period_end, c.period_label, c.metric_code, c.value_numeric, c.availability
        FROM public.v_return_metric_facts_current c
       WHERE c.entity_id = _entity_id
         AND upper(c.metric_code) = upper(_metric_code)
         AND c.value_numeric IS NOT NULL
       ORDER BY c.reporting_period_id, c.filing_updated_at DESC NULLS LAST
    ) t
   ORDER BY t.period_end
   LIMIT GREATEST(COALESCE(_limit, 24), 1);
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_analytics_metrics()
 RETURNS TABLE(metric_code text, metric_name text, unit text, entity_count bigint, period_count bigint, latest_period_end date)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT c.metric_code, c.metric_name, c.metric_unit,
         count(DISTINCT c.entity_id),
         count(DISTINCT c.reporting_period_id),
         max(c.period_end)
    FROM public.v_return_metric_facts_current c
   WHERE c.value_numeric IS NOT NULL
   GROUP BY c.metric_code, c.metric_name, c.metric_unit
   ORDER BY c.metric_name;
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_appendonly_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_setting('role', true) = 'service_role' THEN RETURN COALESCE(NEW, OLD); END IF;
  IF current_setting('app.version_maintenance', true) = 'on' AND TG_OP = 'UPDATE' THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Table % is append-only', TG_TABLE_NAME;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_assessment_case(_assessment_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
WITH a AS (
  SELECT a.*, l.name AS entity_name, l.sector_id
    FROM public.prudential_assessments a
    JOIN public.licensees l ON l.id = a.entity_id
   WHERE a.id = _assessment_id
),
gaps AS (
  SELECT coalesce(public.prudential_assessment_finalisation_gaps(_assessment_id), ARRAY[]::text[]) AS codes
),
asg AS (
  SELECT supervisor_id, supervisor_name, team
    FROM public.entity_supervision_assignments
   WHERE entity_id = (SELECT entity_id FROM a) AND status = 'active'
   ORDER BY effective_from DESC NULLS LAST LIMIT 1
),
sla AS (
  SELECT sla_days, due_soon_days FROM public.prudential_process_sla_config WHERE work_item_type = 'ASSESSMENT'
),
hdr AS (
  SELECT
    a.*,
    coalesce(a.submitted_at, a.created_at) + make_interval(days => (SELECT sla_days FROM sla)) AS sla_due_at,
    (SELECT codes FROM gaps) AS gap_codes
  FROM a
),
blockers AS (
  SELECT coalesce(jsonb_agg(b), '[]'::jsonb) AS list FROM (
    SELECT jsonb_build_object('code','component_rating_missing',
                              'label','Record a component rating for ' || c,
                              'href','/prudential/assessments/' || _assessment_id::text || '?section=risk') AS b
      FROM unnest((SELECT gap_codes FROM hdr)) AS c
     WHERE (SELECT status FROM hdr) IN ('draft','returned_for_revision')
    UNION ALL
    SELECT jsonb_build_object('code','rationale_required','label','Record the assessment rationale',
                              'href','/prudential/assessments/' || _assessment_id::text || '?section=risk')
     WHERE (SELECT status FROM hdr) IN ('draft','returned_for_revision')
       AND coalesce(btrim((SELECT rationale FROM hdr)), '') = ''
  ) s
),
filing AS (
  SELECT jsonb_build_object(
           'return_filing_id', f.id,
           'filing_reference', f.filing_reference,
           'status', f.status,
           'period_label', rp.period_label,
           'period_end', rp.period_end,
           'accepted_version_id', f.accepted_version_id,
           'accepted_version_number', av.version_number,
           'accepted_at', f.accepted_at,
           'href', '/returns/filings/' || f.id::text
         ) AS obj
    FROM public.return_filings f
    LEFT JOIN public.reporting_periods rp ON rp.id = f.reporting_period_id
    LEFT JOIN public.return_filing_versions av ON av.id = f.accepted_version_id
   WHERE f.id = (SELECT return_filing_id FROM hdr)
),
linked_actions AS (
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', pa.id, 'reference', pa.action_reference, 'title', pa.title,
           'status', pa.status, 'severity', pa.severity, 'due_date', pa.due_date,
           'href', '/prudential/actions?action=' || pa.id::text
         ) ORDER BY pa.created_at DESC), '[]'::jsonb) AS list
    FROM public.prudential_actions pa
   WHERE pa.source_type = 'assessment' AND pa.source_id = _assessment_id
),
related AS (
  SELECT coalesce(jsonb_agg(r), '[]'::jsonb) AS list FROM (
    SELECT jsonb_build_object('kind','return_filing', 'label', coalesce(f.filing_reference, 'Return filing'),
                              'detail', rp.period_label, 'href', '/returns/filings/' || f.id::text) AS r
      FROM public.return_filings f
      LEFT JOIN public.reporting_periods rp ON rp.id = f.reporting_period_id
     WHERE f.id = (SELECT return_filing_id FROM hdr)
    UNION ALL
    SELECT jsonb_build_object('kind','signal','label', 'Breach · ' || b.metric_key,
                              'detail', b.period_label, 'href', '/supervision/breaches?breach=' || b.id::text)
      FROM public.v_prudential_current_breaches b
     WHERE b.entity_id = (SELECT entity_id FROM hdr)
       AND (b.return_filing_id = (SELECT return_filing_id FROM hdr) OR (SELECT return_filing_id FROM hdr) IS NULL)
    UNION ALL
    SELECT jsonb_build_object('kind','supervisory_action','label', pa.action_reference || ' · ' || pa.title,
                              'detail', pa.status, 'href', '/prudential/actions?action=' || pa.id::text)
      FROM public.prudential_actions pa
     WHERE pa.source_type = 'assessment' AND pa.source_id = _assessment_id
    UNION ALL
    SELECT jsonb_build_object('kind','escalation','label', 'Escalation · ' || x.escalation_type,
                              'detail', x.status, 'href', '/prudential/escalations?escalation=' || x.id::text)
      FROM public.prudential_escalations x
     WHERE x.related_type = 'assessment' AND x.related_id = _assessment_id
    UNION ALL
    SELECT jsonb_build_object('kind','examination','label', ex.reference || ' · ' || ex.title,
                              'detail', ex.stage, 'href', '/prudential/examinations/' || ex.id::text)
      FROM public.examinations ex
     WHERE ex.entity_id = (SELECT entity_id FROM hdr) AND ex.closed_at IS NULL
    UNION ALL
    SELECT jsonb_build_object('kind','correspondence','label', coalesce(t.reference, t.subject),
                              'detail', t.status, 'href', '/correspondence/' || t.id::text)
      FROM public.correspondence_threads t
     WHERE t.licensee_id = (SELECT entity_id FROM hdr)
       AND coalesce(t.module, '') IN ('prudential','prudential_supervision')
  ) s
)
SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM hdr) THEN jsonb_build_object('found', false)
ELSE (
  SELECT jsonb_build_object(
    'found', true,
    'generated_at', now(),
    'header', jsonb_build_object(
      'reference', 'PA-ASMT-' || substr(h.id::text, 1, 8),
      'subject', h.entity_name,
      'entity_id', h.entity_id,
      'entity_href', '/entities/' || h.entity_id::text || '?view=prudential',
      'assessment_type', 'CAMELS prudential assessment',
      'period_start', h.period_start,
      'period_end', h.period_end,
      'stage', CASE h.status
                 WHEN 'draft' THEN 'DATA_REVIEW'
                 WHEN 'returned_for_revision' THEN 'RISK_ASSESSMENT'
                 WHEN 'submitted' THEN 'SUPERVISORY_REVIEW'
                 WHEN 'reviewed' THEN 'DECISION'
                 WHEN 'approved' THEN 'ACTION_MONITORING'
                 ELSE 'CLOSED' END,
      'stage_label', CASE h.status
                 WHEN 'draft' THEN 'Data review'
                 WHEN 'returned_for_revision' THEN 'Risk assessment (revision)'
                 WHEN 'submitted' THEN 'Supervisory review'
                 WHEN 'reviewed' THEN 'Decision'
                 WHEN 'approved' THEN 'Action monitoring'
                 ELSE 'Closed' END,
      'status', h.status,
      'status_label', initcap(replace(h.status, '_', ' ')),
      'overall_rating', h.overall_rating,
      'owner_user_id', coalesce(h.reviewed_by, h.created_by, (SELECT supervisor_id FROM asg)),
      'owner_name', coalesce((SELECT full_name FROM public.profiles WHERE id = coalesce(h.reviewed_by, h.created_by)),
                             (SELECT supervisor_name FROM asg)),
      'team', (SELECT team FROM asg),
      'priority', CASE WHEN h.overall_rating ~ '^[45]' THEN 'high'
                       WHEN h.sla_due_at < now() THEN 'high' ELSE 'medium' END,
      'sla_due_at', h.sla_due_at,
      'sla_state', CASE WHEN h.status IN ('approved','closed') THEN 'paused'
                        WHEN h.sla_due_at < now() THEN 'breached'
                        WHEN h.sla_due_at < now() + make_interval(days => (SELECT due_soon_days FROM sla)) THEN 'due_soon'
                        ELSE 'on_track' END,
      'waiting_on', 'regulator',
      'last_activity_at', h.updated_at
    ),
    'blockers', (SELECT list FROM blockers),
    'filing', (SELECT obj FROM filing),
    'linked_actions', (SELECT list FROM linked_actions),
    /*
     * EPR-02 §6 — supervisory rating policy is server-owned. No configured
     * rating methodology exists on this platform, so the read model reports
     * that there is NO automated rating suggestion rather than inventing one.
     * The human rating remains governed by the assessment process.
     */
    'rating_guidance', jsonb_build_object(
      'has_methodology', false,
      'suggested_rating', NULL,
      'basis', NULL,
      'message', 'NO AUTOMATED RATING SUGGESTION',
      'detail', 'No configured supervisory rating methodology exists. The overall rating is a human-governed determination recorded against the component ratings and rationale.'
    ),
    'evidence', jsonb_build_object(
      'return_filing_id', h.return_filing_id,
      'return_filing_version_id', h.return_filing_version_id,
      'available', h.return_filing_id IS NOT NULL
    ),
    'available_actions', (
      CASE h.status
        WHEN 'draft' THEN jsonb_build_array(jsonb_build_object(
          'code','submit','label','Submit for review','to_status','submitted',
          'requires_reason', false, 'permission','prudential_supervision.workflow_action',
          'enabled', jsonb_array_length((SELECT list FROM blockers)) = 0))
        WHEN 'returned_for_revision' THEN jsonb_build_array(jsonb_build_object(
          'code','resubmit','label','Resubmit for review','to_status','submitted',
          'requires_reason', false, 'permission','prudential_supervision.workflow_action',
          'enabled', jsonb_array_length((SELECT list FROM blockers)) = 0))
        WHEN 'submitted' THEN jsonb_build_array(
          jsonb_build_object('code','review','label','Mark reviewed','to_status','reviewed',
            'requires_reason', true, 'permission','prudential_supervision.workflow_action','enabled', true),
          jsonb_build_object('code','return','label','Return for revision','to_status','returned_for_revision',
            'requires_reason', true, 'permission','prudential_supervision.workflow_action','enabled', true))
        WHEN 'reviewed' THEN jsonb_build_array(
          jsonb_build_object('code','approve','label','Approve assessment','to_status','approved',
            'requires_reason', true, 'permission','prudential_supervision.workflow_action','enabled', true),
          jsonb_build_object('code','return','label','Return for revision','to_status','returned_for_revision',
            'requires_reason', true, 'permission','prudential_supervision.workflow_action','enabled', true))
        WHEN 'approved' THEN jsonb_build_array(jsonb_build_object(
          'code','close','label','Close assessment','to_status','closed',
          'requires_reason', true, 'permission','prudential_supervision.workflow_action','enabled', true))
        ELSE '[]'::jsonb END),
    'next_action', CASE h.status
        WHEN 'draft' THEN jsonb_build_object('code','submit','label','Complete and submit the assessment')
        WHEN 'returned_for_revision' THEN jsonb_build_object('code','resubmit','label','Address review comments and resubmit')
        WHEN 'submitted' THEN jsonb_build_object('code','review','label','Review the assessment')
        WHEN 'reviewed' THEN jsonb_build_object('code','approve','label','Take the approval decision')
        WHEN 'approved' THEN jsonb_build_object('code','monitor','label','Monitor the resulting supervisory actions')
        ELSE jsonb_build_object('code','none','label','No further action required') END,
    'completed_steps', (
      SELECT coalesce(jsonb_agg(jsonb_build_object('label', s.label, 'at', s.at)), '[]'::jsonb)
        FROM (
          SELECT 'Assessment opened' AS label, h.created_at AS at
          UNION ALL SELECT 'Submitted for review', h.submitted_at WHERE h.submitted_at IS NOT NULL
          UNION ALL SELECT 'Supervisory review recorded', h.reviewed_at WHERE h.reviewed_at IS NOT NULL
          UNION ALL SELECT 'Approved', h.approved_at WHERE h.approved_at IS NOT NULL
          UNION ALL SELECT 'Closed', h.closed_at WHERE h.closed_at IS NOT NULL
        ) s
    ),
    'review_notes', h.review_notes,
    'related_cases', (SELECT list FROM related)
  )
  FROM hdr h
) END;
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_assessment_create(_entity_id uuid, _period_start date, _period_end date, _return_filing_id uuid DEFAULT NULL::uuid, _return_filing_version_id uuid DEFAULT NULL::uuid, _ratings jsonb DEFAULT '{}'::jsonb, _rationale text DEFAULT NULL::text, _signal_snapshot jsonb DEFAULT '{}'::jsonb, _auto_suggested_rating text DEFAULT NULL::text)
 RETURNS prudential_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.prudential_assessments; v_period uuid; v_legacy uuid;
BEGIN
  PERFORM public.prudential_enforce('record_camels_assessment', _entity_id);
  IF _entity_id IS NULL OR _period_start IS NULL OR _period_end IS NULL THEN
    RAISE EXCEPTION 'entity and assessment period are required' USING ERRCODE='22023';
  END IF;
  IF _return_filing_id IS NOT NULL THEN
    SELECT reporting_period_id, legacy_return_filed_id INTO v_period, v_legacy
    FROM public.return_filings WHERE id = _return_filing_id;
  END IF;
  INSERT INTO public.prudential_assessments(
    entity_id, return_id, return_filing_id, return_filing_version_id, reporting_period_id,
    period_start, period_end, ratings, rationale, signal_snapshot, auto_suggested_rating, status, created_by)
  VALUES (_entity_id, v_legacy, _return_filing_id, _return_filing_version_id, v_period,
    _period_start, _period_end, COALESCE(_ratings,'{}'::jsonb), _rationale,
    COALESCE(_signal_snapshot,'{}'::jsonb), _auto_suggested_rating, 'draft', auth.uid())
  RETURNING * INTO v_row;
  PERFORM public.prudential_audit_event('prudential_assessment_created','prudential_assessment',v_row.id,
    NULL, to_jsonb(v_row), jsonb_build_object('entity_id',_entity_id,'return_filing_id',_return_filing_id), _rationale, 'CREATE');
  RETURN v_row;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_assessment_finalisation_gaps(_assessment_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sector uuid;
  v_codes text[];
  v_gaps text[];
BEGIN
  SELECT l.sector_id INTO v_sector
    FROM public.prudential_assessments a
    JOIN public.licensees l ON l.id = a.entity_id
   WHERE a.id = _assessment_id;

  SELECT ARRAY_AGG(code ORDER BY sort_order)
    INTO v_codes
    FROM public.prudential_assessment_components
   WHERE is_active
     AND sector_id IS NOT DISTINCT FROM v_sector;

  IF v_codes IS NULL THEN
    SELECT ARRAY_AGG(code ORDER BY sort_order)
      INTO v_codes
      FROM public.prudential_assessment_components
     WHERE is_active AND sector_id IS NULL;
  END IF;

  IF v_codes IS NULL THEN
    RETURN ARRAY[]::text[];
  END IF;

  SELECT ARRAY_AGG(c ORDER BY c)
    INTO v_gaps
    FROM UNNEST(v_codes) AS c
   WHERE NOT EXISTS (
     SELECT 1 FROM public.prudential_assessment_component_ratings r
      WHERE r.assessment_id = _assessment_id
        AND r.component_code = c
        AND r.rating IS NOT NULL
        AND btrim(r.rating) <> ''
   );

  RETURN COALESCE(v_gaps, ARRAY[]::text[]);
END $function$
;
CREATE OR REPLACE FUNCTION public.prudential_assessment_save_draft(_assessment_id uuid, _patch jsonb)
 RETURNS prudential_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.prudential_assessments; v_after public.prudential_assessments; v_clean jsonb;
BEGIN
  SELECT * INTO v_before FROM public.prudential_assessments WHERE id = _assessment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'assessment % not found', _assessment_id USING ERRCODE='P0002'; END IF;
  PERFORM public.prudential_enforce('record_camels_assessment', v_before.entity_id);
  IF v_before.status NOT IN ('draft','returned_for_revision') THEN
    RAISE EXCEPTION 'assessment % is not editable in status %', _assessment_id, v_before.status USING ERRCODE='55000';
  END IF;
  v_clean := COALESCE(_patch,'{}'::jsonb) - 'id' - 'status' - 'entity_id' - 'created_by'
    - 'approved_by' - 'approved_at' - 'reviewed_by' - 'reviewed_at' - 'submitted_at' - 'closed_at' - 'created_at' - 'updated_at';
  v_clean := jsonb_strip_nulls(jsonb_build_object(
    'overall_rating', v_clean->>'overall_rating',
    'ratings', v_clean->'ratings',
    'rationale', v_clean->>'rationale',
    'evidence_refs', v_clean->'evidence_refs',
    'conclusion', v_clean->>'conclusion',
    'recommended_response', v_clean->>'recommended_response',
    'override_reason', v_clean->>'override_reason',
    'auto_suggested_rating', v_clean->>'auto_suggested_rating',
    'signal_snapshot', v_clean->'signal_snapshot',
    'period_start', v_clean->>'period_start',
    'period_end', v_clean->>'period_end',
    'return_filing_id', v_clean->>'return_filing_id',
    'return_filing_version_id', v_clean->>'return_filing_version_id'));
  IF (v_clean ? 'overall_rating')
     AND v_before.auto_suggested_rating IS NOT NULL
     AND (v_clean->>'overall_rating') IS DISTINCT FROM v_before.auto_suggested_rating THEN
    PERFORM public.prudential_require_rationale(COALESCE(v_clean->>'override_reason', v_before.override_reason), 10, 'override justification');
  END IF;
  UPDATE public.prudential_assessments a
  SET overall_rating = COALESCE(v_clean->>'overall_rating', a.overall_rating),
      ratings = COALESCE(v_clean->'ratings', a.ratings),
      rationale = COALESCE(v_clean->>'rationale', a.rationale),
      evidence_refs = COALESCE(v_clean->'evidence_refs', a.evidence_refs),
      conclusion = COALESCE(v_clean->>'conclusion', a.conclusion),
      recommended_response = COALESCE(v_clean->>'recommended_response', a.recommended_response),
      override_reason = COALESCE(v_clean->>'override_reason', a.override_reason),
      auto_suggested_rating = COALESCE(v_clean->>'auto_suggested_rating', a.auto_suggested_rating),
      signal_snapshot = COALESCE(v_clean->'signal_snapshot', a.signal_snapshot),
      period_start = COALESCE((v_clean->>'period_start')::date, a.period_start),
      period_end = COALESCE((v_clean->>'period_end')::date, a.period_end),
      return_filing_id = COALESCE((v_clean->>'return_filing_id')::uuid, a.return_filing_id),
      return_filing_version_id = COALESCE((v_clean->>'return_filing_version_id')::uuid, a.return_filing_version_id),
      updated_at = now()
  WHERE a.id = _assessment_id
  RETURNING * INTO v_after;
  PERFORM public.prudential_audit_event('prudential_assessment_draft_saved','prudential_assessment',_assessment_id,
    to_jsonb(v_before), to_jsonb(v_after), jsonb_build_object('entity_id',v_before.entity_id), v_after.rationale, 'UPDATE');
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_assessment_transition(_assessment_id uuid, _to_status text, _reason text DEFAULT NULL::text)
 RETURNS prudential_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.prudential_assessments; v_after public.prudential_assessments; v_uid uuid := auth.uid();
BEGIN
  SELECT * INTO v_before FROM public.prudential_assessments WHERE id = _assessment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'assessment % not found', _assessment_id USING ERRCODE='P0002'; END IF;
  IF _to_status NOT IN ('submitted','reviewed','returned_for_revision','approved','closed') THEN
    RAISE EXCEPTION 'unsupported assessment transition target %', _to_status USING ERRCODE='22023';
  END IF;

  IF _to_status = 'submitted' THEN
    PERFORM public.prudential_enforce('record_camels_assessment', v_before.entity_id);
    IF v_before.status NOT IN ('draft','returned_for_revision') THEN
      RAISE EXCEPTION 'cannot submit assessment in status %', v_before.status USING ERRCODE='55000'; END IF;
  ELSE
    PERFORM public.prudential_enforce('workflow_action', v_before.entity_id);
    IF _to_status IN ('reviewed','returned_for_revision') AND v_before.status <> 'submitted' THEN
      RAISE EXCEPTION 'assessment must be submitted before review (current %)', v_before.status USING ERRCODE='55000'; END IF;
    IF _to_status = 'approved' AND v_before.status NOT IN ('submitted','reviewed') THEN
      RAISE EXCEPTION 'assessment must be submitted or reviewed before approval (current %)', v_before.status USING ERRCODE='55000'; END IF;
    IF _to_status = 'closed' AND v_before.status <> 'approved' THEN
      RAISE EXCEPTION 'only approved assessments can be closed (current %)', v_before.status USING ERRCODE='55000'; END IF;
    IF _to_status = 'approved' AND v_before.created_by IS NOT NULL AND v_before.created_by = v_uid THEN
      RAISE EXCEPTION 'the assessment author cannot approve their own assessment' USING ERRCODE='42501'; END IF;
  END IF;

  IF _to_status IN ('returned_for_revision','approved','closed') THEN
    PERFORM public.prudential_require_rationale(_reason, 10, 'decision rationale');
  END IF;

  UPDATE public.prudential_assessments a
  SET status = _to_status,
      submitted_at = CASE WHEN _to_status='submitted' THEN now() ELSE a.submitted_at END,
      reviewed_at = CASE WHEN _to_status IN ('reviewed','returned_for_revision') THEN now() ELSE a.reviewed_at END,
      reviewed_by = CASE WHEN _to_status IN ('reviewed','returned_for_revision') THEN v_uid ELSE a.reviewed_by END,
      approved_at = CASE WHEN _to_status='approved' THEN now() ELSE a.approved_at END,
      approved_by = CASE WHEN _to_status='approved' THEN v_uid ELSE a.approved_by END,
      closed_at = CASE WHEN _to_status='closed' THEN now() ELSE a.closed_at END,
      review_notes = COALESCE(_reason, a.review_notes),
      updated_at = now()
  WHERE a.id = _assessment_id
  RETURNING * INTO v_after;

  PERFORM public.prudential_audit_event('prudential_assessment_'||_to_status,'prudential_assessment',_assessment_id,
    to_jsonb(v_before), to_jsonb(v_after),
    jsonb_build_object('entity_id',v_before.entity_id,'from_status',v_before.status,'to_status',_to_status),
    _reason,
    CASE WHEN _to_status='approved' THEN 'APPROVE'::public.compliance_audit_action
         WHEN _to_status='returned_for_revision' THEN 'REJECT'::public.compliance_audit_action
         ELSE 'WORKFLOW_TRANSITION'::public.compliance_audit_action END);
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_audit_event(_action text, _entity_type text, _entity_id uuid, _before jsonb DEFAULT NULL::jsonb, _after jsonb DEFAULT NULL::jsonb, _context jsonb DEFAULT '{}'::jsonb, _justification text DEFAULT NULL::text, _compliance_action compliance_audit_action DEFAULT 'WORKFLOW_TRANSITION'::compliance_audit_action)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid();
BEGIN
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid, _action, _entity_type, _entity_id,
    jsonb_strip_nulls(COALESCE(_context,'{}'::jsonb) || jsonb_build_object('domain','prudential','before',_before,'after',_after,'justification',_justification)));
  INSERT INTO public.compliance_audit_logs (user_id, action_type, object_type, object_id, before_value, after_value, justification, metadata)
  VALUES (_uid, _compliance_action, _entity_type, _entity_id::text, _before, _after, _justification,
    jsonb_strip_nulls(COALESCE(_context,'{}'::jsonb) || jsonb_build_object('action',_action,'domain','prudential')));
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_breach_acknowledge(_breach_id uuid, _note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  b public.return_threshold_breaches;
  v_ack public.return_threshold_breach_acknowledgements;
BEGIN
  SELECT * INTO b FROM public.return_threshold_breaches WHERE id = _breach_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'breach % not found', _breach_id USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.prudential_enforce('review_returns', b.entity_id);
  PERFORM public.prudential_require_rationale(_note, 10, 'acknowledgement note');

  IF EXISTS (SELECT 1 FROM public.return_threshold_breach_acknowledgements
              WHERE breach_id = _breach_id) THEN
    RAISE EXCEPTION 'breach % is already acknowledged', _breach_id USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.return_threshold_breach_acknowledgements
    (breach_id, entity_id, detection_run_id, return_filing_id, return_filing_version_id,
     reporting_period_id, regulatory_metric_id, metric_key, level, note, acknowledged_by)
  VALUES (b.id, b.entity_id, b.detection_run_id, b.return_filing_id, b.return_filing_version_id,
          b.reporting_period_id, b.regulatory_metric_id, b.metric_key, b.level, _note, auth.uid())
  RETURNING * INTO v_ack;

  PERFORM public.prudential_audit_event(
    'return_breach_acknowledged', 'return_threshold_breach', _breach_id,
    NULL, to_jsonb(v_ack),
    jsonb_build_object('entity_id', b.entity_id,
                       'return_filing_id', b.return_filing_id,
                       'return_filing_version_id', b.return_filing_version_id,
                       'reporting_period_id', b.reporting_period_id,
                       'detection_run_id', b.detection_run_id,
                       'metric_key', b.metric_key,
                       'level', b.level,
                       'observed_value', b.value,
                       'threshold_value', b.threshold_value,
                       'threshold_version', b.threshold_version),
    _note, 'WORKFLOW_TRANSITION');

  RETURN jsonb_build_object(
    'success', true,
    'breach_id', b.id,
    'acknowledgement_id', v_ack.id,
    'acknowledged_by', v_ack.acknowledged_by,
    'acknowledged_at', v_ack.acknowledged_at,
    'note', v_ack.note,
    'detection_run_id', b.detection_run_id,
    'entity_id', b.entity_id,
    'metric_key', b.metric_key,
    'level', b.level);
END $function$
;
CREATE OR REPLACE FUNCTION public.prudential_breach_link_enforcement(_breach_id uuid, _enforcement_id uuid, _reason text DEFAULT NULL::text)
 RETURNS return_threshold_breaches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.return_threshold_breaches; v_after public.return_threshold_breaches;
BEGIN
  SELECT * INTO v_before FROM public.return_threshold_breaches WHERE id = _breach_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'breach % not found', _breach_id USING ERRCODE='P0002'; END IF;
  PERFORM public.prudential_enforce('initiate_supervisory_action', v_before.entity_id);
  IF v_before.escalated_enforcement_id IS NOT NULL THEN
    RAISE EXCEPTION 'breach % is already escalated to enforcement', _breach_id USING ERRCODE='55000'; END IF;
  UPDATE public.return_threshold_breaches b
  SET escalated_enforcement_id = _enforcement_id, escalated_at = now(), escalated_by = auth.uid()
  WHERE b.id = _breach_id RETURNING * INTO v_after;
  PERFORM public.prudential_audit_event('return_breach_escalated','return_threshold_breach',_breach_id,
    to_jsonb(v_before), to_jsonb(v_after),
    jsonb_build_object('entity_id',v_before.entity_id,'enforcement_id',_enforcement_id,
                       'return_filing_id',v_before.return_filing_id), _reason, 'WORKFLOW_TRANSITION');
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_canonical_detect(_return_filing_version_id uuid, _trigger_kind text DEFAULT 'manual'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entity uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT rf.entity_id INTO v_entity
    FROM public.return_filing_versions rfv
    JOIN public.return_filings rf ON rf.id = rfv.return_filing_id
   WHERE rfv.id = _return_filing_version_id;

  IF v_entity IS NULL THEN
    RAISE EXCEPTION 'A2: canonical filing version % not found', _return_filing_version_id;
  END IF;

  IF NOT public.can_read_prudential_entity(auth.uid(), v_entity) THEN
    RAISE EXCEPTION 'Not authorised to run prudential detection for this entity';
  END IF;

  RETURN public._prudential_canonical_detect_run(
    _return_filing_version_id,
    COALESCE(_trigger_kind, 'manual'),
    auth.uid());
END $function$
;
CREATE OR REPLACE FUNCTION public.prudential_component_rating_save(_assessment_id uuid, _component_code text, _rating text, _narrative text DEFAULT NULL::text, _component_id uuid DEFAULT NULL::uuid, _evidence jsonb DEFAULT '[]'::jsonb, _auto_suggested_rating text DEFAULT NULL::text, _suggestion_source jsonb DEFAULT NULL::jsonb, _override_justification text DEFAULT NULL::text)
 RETURNS prudential_assessment_component_ratings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_a public.prudential_assessments; v_before public.prudential_assessment_component_ratings; v_after public.prudential_assessment_component_ratings;
BEGIN
  SELECT * INTO v_a FROM public.prudential_assessments WHERE id = _assessment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'assessment % not found', _assessment_id USING ERRCODE='P0002'; END IF;
  PERFORM public.prudential_enforce('record_camels_assessment', v_a.entity_id);
  IF v_a.status NOT IN ('draft','returned_for_revision','submitted') THEN
    RAISE EXCEPTION 'component ratings cannot change once the assessment is %', v_a.status USING ERRCODE='55000';
  END IF;
  IF _rating IS NOT NULL THEN
    PERFORM public.prudential_require_rationale(_narrative, 10, 'component narrative');
  END IF;
  IF _auto_suggested_rating IS NOT NULL AND _rating IS NOT NULL AND _rating <> _auto_suggested_rating THEN
    PERFORM public.prudential_require_rationale(_override_justification, 10, 'override justification');
  END IF;

  SELECT * INTO v_before FROM public.prudential_assessment_component_ratings
   WHERE assessment_id = _assessment_id AND component_code = _component_code;

  IF v_before.id IS NULL THEN
    INSERT INTO public.prudential_assessment_component_ratings(
      assessment_id, component_id, component_code, rating, narrative, evidence,
      auto_suggested_rating, suggestion_source, override_justification, created_by, updated_by)
    VALUES (_assessment_id, _component_id, _component_code, _rating, _narrative, COALESCE(_evidence,'[]'::jsonb),
      _auto_suggested_rating, _suggestion_source, _override_justification, auth.uid(), auth.uid())
    RETURNING * INTO v_after;
  ELSE
    UPDATE public.prudential_assessment_component_ratings r
    SET component_id = COALESCE(_component_id, r.component_id),
        rating = _rating,
        narrative = COALESCE(_narrative, r.narrative),
        evidence = COALESCE(_evidence, r.evidence),
        auto_suggested_rating = COALESCE(_auto_suggested_rating, r.auto_suggested_rating),
        suggestion_source = COALESCE(_suggestion_source, r.suggestion_source),
        override_justification = COALESCE(_override_justification, r.override_justification),
        updated_by = auth.uid(), updated_at = now()
    WHERE r.id = v_before.id
    RETURNING * INTO v_after;
  END IF;

  PERFORM public.prudential_audit_event('prudential_component_rating_saved','prudential_assessment',_assessment_id,
    to_jsonb(v_before), to_jsonb(v_after),
    jsonb_build_object('entity_id',v_a.entity_id,'component_code',_component_code), COALESCE(_override_justification,_narrative), 'UPDATE');
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_dashboard_metrics()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'total_entities', (SELECT count(*) FROM public.licensees),
    'open_actions', (SELECT count(*) FROM public.prudential_actions WHERE status IN ('open','in_progress')),
    'overdue_actions', (SELECT count(*) FROM public.prudential_actions WHERE status = 'overdue'),
    'recent_breaches', (SELECT count(*) FROM public.return_threshold_breaches WHERE detected_at > now() - interval '30 days'),
    'stress_events_30d', (SELECT count(*) FROM public.prudential_stress_events WHERE triggered_at > now() - interval '30 days'),
    'open_escalations', (SELECT count(*) FROM public.prudential_escalations WHERE status IN ('open','under_review')),
    'assessments_draft', (SELECT count(*) FROM public.prudential_assessments WHERE status = 'draft'),
    'assessments_approved_30d', (SELECT count(*) FROM public.prudential_assessments WHERE status = 'approved' AND approved_at > now() - interval '30 days')
  )
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_dashboard_portfolio()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
WITH q AS (
  SELECT * FROM public.prudential_work_queue(_limit => 100000)
),
ent AS (
  SELECT l.id, l.name, l.sector_id FROM public.licensees l
   WHERE public.can_read_prudential_entity(auth.uid(), l.id)
)
SELECT jsonb_build_object(
  'generated_at', now(),
  'portfolio', jsonb_build_object(
    'entities_in_scope', (SELECT count(*) FROM ent),
    'entities_with_signals', (SELECT count(DISTINCT entity_id) FROM q WHERE work_item_type IN ('BREACH','EWI','STRESS_EVENT')),
    'entities_with_breaches', (SELECT count(DISTINCT entity_id) FROM q WHERE work_item_type = 'BREACH'),
    'entities_with_ewis', (SELECT count(DISTINCT entity_id) FROM q WHERE work_item_type = 'EWI')
  ),
  'signals', jsonb_build_object(
    'current_breaches', (SELECT count(*) FROM q WHERE work_item_type = 'BREACH'),
    'unacknowledged_breaches', (SELECT count(*) FROM q WHERE work_item_type = 'BREACH' AND status = 'unacknowledged'),
    'open_ewis', (SELECT count(*) FROM q WHERE work_item_type = 'EWI'),
    'stress_events', (SELECT count(*) FROM q WHERE work_item_type = 'STRESS_EVENT')
  ),
  'work', jsonb_build_object(
    'total', (SELECT count(*) FROM q),
    'mine', (SELECT count(*) FROM q WHERE owner_user_id = auth.uid()),
    'unassigned', (SELECT count(*) FROM q WHERE owner_user_id IS NULL),
    'overdue', (SELECT count(*) FROM q WHERE sla_state = 'breached'),
    'due_soon', (SELECT count(*) FROM q WHERE sla_state = 'due_soon'),
    'open_actions', (SELECT count(*) FROM q WHERE work_item_type = 'SUPERVISORY_ACTION'),
    'overdue_actions', (SELECT count(*) FROM q WHERE work_item_type = 'SUPERVISORY_ACTION' AND sla_state = 'breached'),
    'open_escalations', (SELECT count(*) FROM q WHERE work_item_type = 'ESCALATION'),
    'assessments_in_progress', (SELECT count(*) FROM q WHERE work_item_type = 'ASSESSMENT'),
    'plan_actions', (SELECT count(*) FROM q WHERE work_item_type = 'PLAN_ACTION'),
    'examinations_active', (SELECT count(*) FROM q WHERE work_item_type = 'EXAMINATION')
  ),
  'by_type', coalesce((SELECT jsonb_object_agg(work_item_type, n) FROM
      (SELECT work_item_type, count(*) n FROM q GROUP BY 1) t), '{}'::jsonb),
  'by_priority', coalesce((SELECT jsonb_object_agg(priority, n) FROM
      (SELECT priority, count(*) n FROM q GROUP BY 1) t), '{}'::jsonb),
  'workload', coalesce((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object(
               'owner_user_id', owner_user_id,
               'owner_name', coalesce(owner_name, 'Unassigned'),
               'team', team,
               'items', count(*),
               'overdue', count(*) FILTER (WHERE sla_state = 'breached')) AS x
        FROM q GROUP BY owner_user_id, owner_name, team
       ORDER BY count(*) DESC LIMIT 10) s), '[]'::jsonb),
  'deteriorating', coalesce((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object(
               'entity_id', entity_id, 'entity_name', entity_name,
               'signals', count(*) FILTER (WHERE work_item_type IN ('BREACH','EWI','STRESS_EVENT')),
               'open_work', count(*),
               'worst_priority', min(CASE priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END)) AS x
        FROM q GROUP BY entity_id, entity_name
       HAVING count(*) FILTER (WHERE work_item_type IN ('BREACH','EWI','STRESS_EVENT')) > 0
       ORDER BY min(CASE priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END),
                count(*) DESC LIMIT 10) s), '[]'::jsonb),
  'upcoming', coalesce((SELECT jsonb_agg(x) FROM (
      SELECT jsonb_build_object('work_item_type', work_item_type, 'title', title,
               'entity_name', entity_name, 'sla_due_at', sla_due_at, 'sla_state', sla_state,
               'href', next_action_href) AS x
        FROM q WHERE sla_due_at IS NOT NULL AND sla_due_at >= now()
       ORDER BY sla_due_at LIMIT 10) s), '[]'::jsonb)
);
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_enforce(_action text, _entity_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sector uuid;
BEGIN
  IF _entity_id IS NOT NULL THEN
    SELECT sector_id INTO v_sector FROM public.licensees WHERE id = _entity_id;
  END IF;
  PERFORM public.enforce_scoped_permission('prudential_supervision', _action, _entity_id, v_sector, NULL);
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_entity_audit_history(_entity_id uuid)
 RETURNS TABLE(entry_id uuid, "timestamp" timestamp with time zone, user_id uuid, user_role text, action_type compliance_audit_action, object_type text, object_id text, before_value jsonb, after_value jsonb, justification text, metadata jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT cal.entry_id, cal."timestamp", cal.user_id, cal.user_role,
         cal.action_type, cal.object_type, cal.object_id,
         cal.before_value, cal.after_value, cal.justification, cal.metadata
    FROM public.compliance_audit_logs cal
   WHERE (cal.object_type = 'licensee' AND cal.object_id = _entity_id::text)
      OR (cal.object_type = 'prudential_assessment'
          AND cal.object_id IN (SELECT id::text FROM public.prudential_assessments WHERE entity_id = _entity_id))
      OR (cal.object_type = 'prudential_action'
          AND cal.object_id IN (SELECT id::text FROM public.prudential_actions WHERE entity_id = _entity_id))
      OR (cal.object_type = 'prudential_escalation'
          AND cal.object_id IN (SELECT id::text FROM public.prudential_escalations WHERE entity_id = _entity_id))
      OR (cal.object_type = 'prudential_stress_event'
          AND cal.object_id IN (SELECT id::text FROM public.prudential_stress_events WHERE entity_id = _entity_id))
   ORDER BY cal."timestamp" DESC
   LIMIT 500;
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_entity_returns_profile(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH filings AS (
    SELECT w.*
      FROM public.v_return_filing_workflow_state w
     WHERE w.entity_id = _entity_id
  ),
  metrics AS (
    SELECT f.filing_id,
           COALESCE(f.accepted_version_id, f.current_version_id) AS version_id,
           f.reporting_period_id, f.period_label, f.period_end, f.status AS filing_status,
           m.id AS regulatory_metric_id, m.code, m.name, m.unit,
           mv.value_numeric, mv.availability, mv.source_kind, mv.recorded_at, mv.calculated_at
      FROM filings f
      JOIN public.return_metric_values mv
        ON mv.return_filing_version_id = COALESCE(f.accepted_version_id, f.current_version_id)
      JOIN public.regulatory_metrics m ON m.id = mv.regulatory_metric_id
     WHERE f.status <> 'WITHDRAWN'
       AND mv.value_numeric IS NOT NULL
  )
  SELECT jsonb_build_object(
    'filings', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'filing_id', f.filing_id,
        'filing_reference', f.filing_reference,
        'definition_name', f.definition_name,
        'reporting_period_id', f.reporting_period_id,
        'period_label', f.period_label,
        'period_start', f.period_start,
        'period_end', f.period_end,
        'due_date', f.due_date,
        'status', f.status,
        'status_label', f.status_label,
        'submitted_at', f.submitted_at,
        'accepted_at', f.accepted_at,
        'current_version_id', f.current_version_id,
        'current_version_number', f.current_version_number,
        'accepted_version_id', f.accepted_version_id,
        'is_overdue', f.is_overdue,
        'days_late', f.days_late
      ) ORDER BY f.period_end DESC NULLS LAST), '[]'::jsonb)
      FROM filings f
    ),
    'metrics', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'filing_id', x.filing_id,
        'return_filing_version_id', x.version_id,
        'reporting_period_id', x.reporting_period_id,
        'period_label', x.period_label,
        'period_end', x.period_end,
        'filing_status', x.filing_status,
        'regulatory_metric_id', x.regulatory_metric_id,
        'metric_code', x.code,
        'metric_name', x.name,
        'unit', x.unit,
        'value_numeric', x.value_numeric,
        'availability', x.availability,
        'source_kind', x.source_kind,
        'recorded_at', COALESCE(x.calculated_at, x.recorded_at)
      ) ORDER BY x.period_end DESC NULLS LAST, x.code), '[]'::jsonb)
      FROM metrics x
    ),
    'current_breaches', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', b.id,
        'entity_id', b.entity_id,
        'return_filing_id', b.return_filing_id,
        'return_filing_version_id', b.return_filing_version_id,
        'reporting_period_id', b.reporting_period_id,
        'regulatory_metric_id', b.regulatory_metric_id,
        'detection_run_id', b.detection_run_id,
        'metric_key', b.metric_key,
        'level', b.level,
        'risk_level', b.risk_level,
        'value', b.value,
        'threshold_value', b.threshold_value,
        'comparator', b.comparator,
        'detected_at', b.detected_at,
        'period_label', b.period_label,
        'period_end', b.period_end,
        'filing_reference', b.filing_reference,
        'filing_status', b.filing_status,
        'acknowledged_at', COALESCE(b.acknowledged_at_ts, b.acknowledged_at),
        'acknowledged_by', COALESCE(b.acknowledged_by_user, b.acknowledged_by),
        'escalated_enforcement_id', b.escalated_enforcement_id
      ) ORDER BY b.detected_at DESC), '[]'::jsonb)
      FROM public.v_prudential_current_breaches b
     WHERE b.entity_id = _entity_id
    ),
    'breach_history', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', b.id,
        'return_filing_id', b.return_filing_id,
        'return_filing_version_id', b.return_filing_version_id,
        'reporting_period_id', b.reporting_period_id,
        'detection_run_id', b.detection_run_id,
        'metric_key', b.metric_key,
        'level', b.level,
        'risk_level', b.risk_level,
        'value', b.value,
        'threshold_value', b.threshold_value,
        'comparator', b.comparator,
        'detected_at', b.detected_at
      ) ORDER BY b.detected_at DESC), '[]'::jsonb)
      FROM public.return_threshold_breaches b
     WHERE b.entity_id = _entity_id
    )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_entity_state(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
WITH q AS (
  SELECT * FROM public.prudential_work_queue(_entity_id => _entity_id, _limit => 100000)
),
asg AS (
  SELECT supervisor_id, supervisor_name, team, supervisory_cycle, cycle_start, cycle_end
    FROM public.entity_supervision_assignments
   WHERE entity_id = _entity_id AND status = 'active'
   ORDER BY effective_from DESC NULLS LAST LIMIT 1
),
latest_assessment AS (
  SELECT id, status, overall_rating, period_end, approved_at, updated_at
    FROM public.prudential_assessments
   WHERE entity_id = _entity_id
   ORDER BY coalesce(period_end, created_at::date) DESC, updated_at DESC LIMIT 1
),
latest_period AS (
  SELECT rp.period_label, rp.period_end, f.id AS filing_id, f.filing_reference AS reference
    FROM public.return_filings f
    JOIN public.reporting_periods rp ON rp.id = f.reporting_period_id
   WHERE f.entity_id = _entity_id AND upper(f.status) = 'ACCEPTED'
   ORDER BY rp.period_end DESC LIMIT 1
)
SELECT jsonb_build_object(
  'entity_id', _entity_id,
  'generated_at', now(),
  'allowed', public.can_read_prudential_entity(auth.uid(), _entity_id),
  'overall_rating', (SELECT overall_rating FROM latest_assessment),
  'latest_accepted_period', (SELECT jsonb_build_object('period_label', period_label, 'period_end', period_end,
                                                       'filing_id', filing_id, 'reference', reference)
                               FROM latest_period),
  'signals', jsonb_build_object(
    'breaches', (SELECT count(*) FROM q WHERE work_item_type = 'BREACH'),
    'unacknowledged_breaches', (SELECT count(*) FROM q WHERE work_item_type = 'BREACH' AND status = 'unacknowledged'),
    'ewis', (SELECT count(*) FROM q WHERE work_item_type = 'EWI'),
    'stress_events', (SELECT count(*) FROM q WHERE work_item_type = 'STRESS_EVENT')
  ),
  'actions', jsonb_build_object(
    'open', (SELECT count(*) FROM q WHERE work_item_type = 'SUPERVISORY_ACTION'),
    'overdue', (SELECT count(*) FROM q WHERE work_item_type = 'SUPERVISORY_ACTION' AND sla_state = 'breached'),
    'awaiting_review', (SELECT count(*) FROM q WHERE work_item_type = 'SUPERVISORY_ACTION' AND detail->>'review_status' = 'awaiting_review')
  ),
  'escalations_open', (SELECT count(*) FROM q WHERE work_item_type = 'ESCALATION'),
  'plan_actions_open', (SELECT count(*) FROM q WHERE work_item_type = 'PLAN_ACTION'),
  'examinations_active', (SELECT count(*) FROM q WHERE work_item_type = 'EXAMINATION'),
  'current_assessment', (SELECT jsonb_build_object('id', id, 'status', status, 'overall_rating', overall_rating,
                                                   'period_end', period_end, 'approved_at', approved_at)
                           FROM latest_assessment),
  'supervisor', (SELECT jsonb_build_object('user_id', supervisor_id, 'name', supervisor_name, 'team', team,
                                           'cycle', supervisory_cycle, 'cycle_start', cycle_start, 'cycle_end', cycle_end)
                   FROM asg),
  'next_required_action', (SELECT jsonb_build_object(
                                   'work_item_type', work_item_type, 'work_item_id', work_item_id,
                                   'label', next_action_label, 'href', next_action_href,
                                   'permission', next_action_permission, 'title', title,
                                   'sla_due_at', sla_due_at, 'sla_state', sla_state, 'priority', priority)
                             FROM q
                            ORDER BY CASE priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END,
                                     CASE sla_state WHEN 'breached' THEN 0 WHEN 'due_soon' THEN 1 ELSE 2 END,
                                     sla_due_at NULLS LAST
                            LIMIT 1),
  'work_items', coalesce((SELECT jsonb_agg(jsonb_build_object(
                             'work_item_type', work_item_type, 'work_item_id', work_item_id,
                             'title', title, 'reference', reference, 'stage_label', stage_label,
                             'status_label', status_label, 'priority', priority, 'sla_due_at', sla_due_at,
                             'sla_state', sla_state, 'owner_name', owner_name,
                             'next_action_label', next_action_label, 'next_action_href', next_action_href,
                             'detail', detail))
                            FROM q), '[]'::jsonb)
);
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_entity_universe(_sector_id uuid DEFAULT NULL::uuid, _status text DEFAULT NULL::text, _search text DEFAULT NULL::text)
 RETURNS TABLE(entity_id uuid, entity_name text, status text, sector_id uuid, sub_sector_id uuid, category_id uuid, license_id text, assigned_supervisor_id uuid, systemic_importance text, latest_filing_id uuid, latest_filing_reference text, latest_period_label text, latest_period_end date, latest_filing_status text, latest_submitted_at timestamp with time zone, latest_accepted_filing_id uuid, latest_accepted_period_end date, breach_count bigint, worst_breach text, open_ewi bigint, open_actions bigint, overdue_actions bigint, open_escalations bigint, stress_open bigint, latest_rating text, latest_rating_status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH ent AS (
    SELECT l.id, l.name, l.status, l.sector_id, l.sub_sector_id, l.category_id,
           l.license_id, l.assigned_supervisor_id, l.systemic_importance
      FROM public.licensees l
     WHERE (_sector_id IS NULL OR l.sector_id = _sector_id)
       AND (_status IS NULL OR l.status = _status)
       AND (_search IS NULL OR l.name ILIKE '%' || _search || '%')
  ),
  latest AS (
    SELECT DISTINCT ON (w.entity_id)
           w.entity_id, w.filing_id, w.filing_reference, w.period_label,
           w.period_end, w.status, w.submitted_at
      FROM public.v_return_filing_workflow_state w
      JOIN ent ON ent.id = w.entity_id
     WHERE w.status <> 'WITHDRAWN'
     ORDER BY w.entity_id, w.period_end DESC NULLS LAST, w.updated_at DESC NULLS LAST
  ),
  latest_accepted AS (
    SELECT DISTINCT ON (w.entity_id) w.entity_id, w.filing_id, w.period_end
      FROM public.v_return_filing_workflow_state w
      JOIN ent ON ent.id = w.entity_id
     WHERE w.status = 'ACCEPTED'
     ORDER BY w.entity_id, w.period_end DESC NULLS LAST
  ),
  breach AS (
    SELECT b.entity_id,
           count(*) AS breach_count,
           min(CASE lower(coalesce(b.risk_level, b.level, ''))
                 WHEN 'red' THEN 1 WHEN 'breach' THEN 1 WHEN 'critical' THEN 1 WHEN 'high' THEN 1
                 WHEN 'amber' THEN 2 WHEN 'warn' THEN 2 WHEN 'warning' THEN 2 WHEN 'medium' THEN 2
                 ELSE 3 END) AS worst_rank
      FROM public.v_prudential_current_breaches b
      JOIN ent ON ent.id = b.entity_id
     GROUP BY b.entity_id
  ),
  ewi AS (
    SELECT a.entity_id, count(*) AS open_ewi
      FROM public.prudential_ewi_alerts a
      JOIN ent ON ent.id = a.entity_id
     WHERE a.status = 'open'
     GROUP BY a.entity_id
  ),
  acts AS (
    SELECT a.entity_id,
           count(*) FILTER (WHERE a.status IN ('open','in_progress','overdue')) AS open_actions,
           count(*) FILTER (WHERE a.status = 'overdue') AS overdue_actions
      FROM public.prudential_actions a
      JOIN ent ON ent.id = a.entity_id
     GROUP BY a.entity_id
  ),
  esc AS (
    SELECT e.entity_id, count(*) AS open_escalations
      FROM public.prudential_escalations e
      JOIN ent ON ent.id = e.entity_id
     WHERE e.status IN ('open','under_review')
     GROUP BY e.entity_id
  ),
  stress AS (
    SELECT s.entity_id, count(*) AS stress_open
      FROM public.prudential_stress_events s
      JOIN ent ON ent.id = s.entity_id
     WHERE s.resolved_at IS NULL
     GROUP BY s.entity_id
  ),
  rated AS (
    SELECT DISTINCT ON (a.entity_id) a.entity_id, a.overall_rating, a.status
      FROM public.prudential_assessments a
      JOIN ent ON ent.id = a.entity_id
     WHERE a.status IN ('submitted','reviewed','approved','closed')
     ORDER BY a.entity_id,
              CASE WHEN a.status IN ('approved','closed') THEN 0 ELSE 1 END,
              coalesce(a.approved_at, a.reviewed_at, a.submitted_at, a.created_at) DESC
  )
  SELECT ent.id, ent.name, ent.status, ent.sector_id, ent.sub_sector_id, ent.category_id,
         ent.license_id, ent.assigned_supervisor_id, ent.systemic_importance,
         latest.filing_id, latest.filing_reference, latest.period_label, latest.period_end,
         latest.status, latest.submitted_at,
         latest_accepted.filing_id, latest_accepted.period_end,
         COALESCE(breach.breach_count, 0),
         CASE breach.worst_rank WHEN 1 THEN 'red' WHEN 2 THEN 'amber' WHEN 3 THEN 'green' ELSE NULL END,
         COALESCE(ewi.open_ewi, 0),
         COALESCE(acts.open_actions, 0),
         COALESCE(acts.overdue_actions, 0),
         COALESCE(esc.open_escalations, 0),
         COALESCE(stress.stress_open, 0),
         rated.overall_rating, rated.status
    FROM ent
    LEFT JOIN latest ON latest.entity_id = ent.id
    LEFT JOIN latest_accepted ON latest_accepted.entity_id = ent.id
    LEFT JOIN breach ON breach.entity_id = ent.id
    LEFT JOIN ewi ON ewi.entity_id = ent.id
    LEFT JOIN acts ON acts.entity_id = ent.id
    LEFT JOIN esc ON esc.entity_id = ent.id
    LEFT JOIN stress ON stress.entity_id = ent.id
    LEFT JOIN rated ON rated.entity_id = ent.id
   ORDER BY ent.name;
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_escalation_decide(_escalation_id uuid, _status text, _decision text DEFAULT NULL::text, _outcome text DEFAULT NULL::text, _priority text DEFAULT NULL::text)
 RETURNS prudential_escalations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.prudential_escalations; v_after public.prudential_escalations;
BEGIN
  SELECT * INTO v_before FROM public.prudential_escalations WHERE id = _escalation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'escalation % not found', _escalation_id USING ERRCODE='P0002'; END IF;
  PERFORM public.prudential_enforce('workflow_action', v_before.entity_id);
  IF _status NOT IN ('open','under_review','resolved','withdrawn') THEN
    RAISE EXCEPTION 'unsupported escalation status %', _status USING ERRCODE='22023'; END IF;
  IF v_before.status IN ('resolved','withdrawn') THEN
    RAISE EXCEPTION 'escalation % is already closed (%)', _escalation_id, v_before.status USING ERRCODE='55000'; END IF;
  IF _status IN ('resolved','withdrawn') THEN
    PERFORM public.prudential_require_rationale(COALESCE(_decision, _outcome), 10, 'escalation decision');
  END IF;
  UPDATE public.prudential_escalations e
  SET status = _status,
      decision = COALESCE(_decision, e.decision),
      outcome = COALESCE(_outcome, e.outcome),
      priority = COALESCE(_priority, e.priority),
      decision_by = CASE WHEN _status IN ('resolved','withdrawn') THEN auth.uid() ELSE e.decision_by END,
      decided_at = CASE WHEN _status IN ('resolved','withdrawn') THEN now() ELSE e.decided_at END,
      updated_at = now()
  WHERE e.id = _escalation_id
  RETURNING * INTO v_after;
  PERFORM public.prudential_audit_event('prudential_escalation_'||_status,'prudential_escalation',_escalation_id,
    to_jsonb(v_before), to_jsonb(v_after),
    jsonb_build_object('entity_id',v_before.entity_id,'from_status',v_before.status,'to_status',_status),
    COALESCE(_decision,_outcome), 'WORKFLOW_TRANSITION');
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_escalation_raise(_entity_id uuid, _escalation_type text, _reason text, _related_type text DEFAULT 'entity'::text, _related_id uuid DEFAULT NULL::uuid, _priority text DEFAULT 'medium'::text, _evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS prudential_escalations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.prudential_escalations;
BEGIN
  PERFORM public.prudential_enforce('initiate_supervisory_action', _entity_id);
  PERFORM public.prudential_require_rationale(_reason, 10, 'escalation reason');
  INSERT INTO public.prudential_escalations(entity_id, escalation_type, reason, related_type, related_id, priority, evidence, status, created_by)
  VALUES (_entity_id, _escalation_type, _reason, COALESCE(_related_type,'entity'), _related_id,
          COALESCE(_priority,'medium'), COALESCE(_evidence,'{}'::jsonb), 'open', auth.uid())
  RETURNING * INTO v_row;
  PERFORM public.prudential_audit_event('prudential_escalation_raised','prudential_escalation',v_row.id,
    NULL, to_jsonb(v_row), jsonb_build_object('entity_id',_entity_id,'related_type',_related_type,'related_id',_related_id), _reason, 'CREATE');
  RETURN v_row;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_ewi_acknowledge(_alert_id uuid, _notes text DEFAULT NULL::text, _status text DEFAULT 'acknowledged'::text)
 RETURNS prudential_ewi_alerts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  a public.prudential_ewi_alerts;
BEGIN
  SELECT * INTO a FROM public.prudential_ewi_alerts WHERE id = _alert_id;
  IF a.id IS NULL THEN RAISE EXCEPTION 'alert not found'; END IF;
  IF NOT (public.can_act_on_prudential(auth.uid())
          AND public.can_read_prudential_entity(auth.uid(), a.entity_id)) THEN
    RAISE EXCEPTION 'not authorised to acknowledge this alert';
  END IF;
  IF _status NOT IN ('acknowledged','dismissed','resolved') THEN
    RAISE EXCEPTION 'invalid status %', _status;
  END IF;

  UPDATE public.prudential_ewi_alerts
     SET status = _status, notes = COALESCE(_notes, notes),
         acknowledged_by = auth.uid(), acknowledged_at = now(), updated_at = now()
   WHERE id = _alert_id
  RETURNING * INTO a;

  BEGIN
    PERFORM public.log_compliance_audit(
      'UPDATE'::public.compliance_audit_action, 'prudential_ewi_alert', _alert_id::text,
      NULL, jsonb_build_object('status', _status, 'notes', _notes), _notes, NULL, NULL,
      jsonb_build_object('source', 'prudential_ewi_acknowledge'));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN a;
END $function$
;
CREATE OR REPLACE FUNCTION public.prudential_ewi_evaluate(_entity_id uuid, _period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r public.prudential_ewi_rules;
  v_created int := 0;
  v_refreshed int := 0;
  v_alert_id uuid;
  v_existing uuid;
  rec record;
BEGIN
  IF NOT (current_user IN ('service_role','postgres','supabase_admin') OR public.can_read_prudential_entity(auth.uid(), _entity_id)) THEN
    RAISE EXCEPTION 'not authorised to evaluate early warning indicators for this entity';
  END IF;

  FOR r IN
    SELECT * FROM public.prudential_ewi_rules
     WHERE is_active
       AND (sector_id IS NULL
            OR sector_id = (SELECT sector_id FROM public.licensees WHERE id = _entity_id))
  LOOP
    IF r.rule_type = 'repeated_breach' THEN
      FOR rec IN
        WITH periods AS (
          SELECT rf.id, rf.period_end_date
            FROM public.returns_filed rf
           WHERE rf.entity_id = _entity_id AND rf.period_end_date <= _period_end
           ORDER BY rf.period_end_date DESC
           LIMIT COALESCE((r.params->>'lookback_periods')::int, 3)
        )
        SELECT b.metric_key, COUNT(*)::int AS hits,
               jsonb_agg(jsonb_build_object('return_id', b.return_id, 'value', b.value,
                                            'threshold_value', b.threshold_value,
                                            'threshold_version', b.threshold_version)) AS ev
          FROM public.return_threshold_breaches b
          JOIN periods p ON p.id = b.return_id
         WHERE b.level = 'breach'
         GROUP BY b.metric_key
        HAVING COUNT(*) >= COALESCE((r.params->>'min_breaches')::int, 2)
      LOOP
        INSERT INTO public.prudential_ewi_alerts
          (entity_id, rule_id, rule_code, rule_version, period_end, metric_key, severity, evidence, executed_at)
        VALUES (_entity_id, r.id, r.code, r.version, _period_end, rec.metric_key, r.severity,
                jsonb_build_object('rule_type', r.rule_type, 'breaches', rec.hits, 'detail', rec.ev), now())
        ON CONFLICT (entity_id, rule_id, period_end, metric_key)
          DO UPDATE SET evidence = EXCLUDED.evidence, executed_at = now(),
                        rule_version = EXCLUDED.rule_version, updated_at = now()
        RETURNING id INTO v_alert_id;
        v_created := v_created + 1;
      END LOOP;

    ELSIF r.rule_type = 'multi_ratio_warning' THEN
      FOR rec IN
        SELECT COUNT(*)::int AS warnings,
               jsonb_agg(jsonb_build_object('metric_key', b.metric_key, 'value', b.value)) AS ev
          FROM public.return_threshold_breaches b
          JOIN public.returns_filed rf ON rf.id = b.return_id
         WHERE rf.entity_id = _entity_id AND rf.period_end_date = _period_end
           AND b.level = 'warn'
        HAVING COUNT(*) >= COALESCE((r.params->>'min_warnings')::int, 3)
      LOOP
        INSERT INTO public.prudential_ewi_alerts
          (entity_id, rule_id, rule_code, rule_version, period_end, metric_key, severity, evidence, executed_at)
        VALUES (_entity_id, r.id, r.code, r.version, _period_end, '', r.severity,
                jsonb_build_object('rule_type', r.rule_type, 'warnings', rec.warnings, 'detail', rec.ev), now())
        ON CONFLICT (entity_id, rule_id, period_end, metric_key)
          DO UPDATE SET evidence = EXCLUDED.evidence, executed_at = now(), updated_at = now()
        RETURNING id INTO v_alert_id;
        v_created := v_created + 1;
      END LOOP;

    ELSIF r.rule_type IN ('sharp_deterioration','adverse_trend') THEN
      FOR rec IN
        WITH vals AS (
          SELECT DISTINCT ON (rf.period_end_date, rcr.ratio_key)
                 rcr.ratio_key, rf.period_end_date, rcr.value
            FROM public.return_calculated_ratios rcr
            JOIN public.returns_filed rf ON rf.id = rcr.return_id
           WHERE rf.entity_id = _entity_id
             AND rf.period_end_date <= _period_end
             AND rcr.value IS NOT NULL
           ORDER BY rf.period_end_date, rcr.ratio_key, rcr.computed_at DESC
        ), ranked AS (
          SELECT ratio_key, period_end_date, value,
                 ROW_NUMBER() OVER (PARTITION BY ratio_key ORDER BY period_end_date DESC) AS rn
            FROM vals
        )
        SELECT ratio_key,
               MAX(value) FILTER (WHERE rn = 1) AS v1,
               MAX(value) FILTER (WHERE rn = 2) AS v2,
               MAX(value) FILTER (WHERE rn = 3) AS v3,
               MAX(value) FILTER (WHERE rn = 4) AS v4
          FROM ranked WHERE rn <= 4
         GROUP BY ratio_key
      LOOP
        IF r.rule_type = 'sharp_deterioration' THEN
          IF rec.v1 IS NOT NULL AND rec.v2 IS NOT NULL AND rec.v2 <> 0
             AND ((rec.v2 - rec.v1) / ABS(rec.v2)) * 100 >= COALESCE((r.params->>'min_change_pct')::numeric, 20) THEN
            INSERT INTO public.prudential_ewi_alerts
              (entity_id, rule_id, rule_code, rule_version, period_end, metric_key, severity, evidence, executed_at)
            VALUES (_entity_id, r.id, r.code, r.version, _period_end, rec.ratio_key, r.severity,
                    jsonb_build_object('rule_type', r.rule_type, 'current', rec.v1, 'previous', rec.v2,
                                       'change_pct', ROUND(((rec.v2 - rec.v1) / ABS(rec.v2)) * 10000) / 100), now())
            ON CONFLICT (entity_id, rule_id, period_end, metric_key)
              DO UPDATE SET evidence = EXCLUDED.evidence, executed_at = now(), updated_at = now();
            v_created := v_created + 1;
          END IF;
        ELSE
          IF rec.v1 IS NOT NULL AND rec.v2 IS NOT NULL AND rec.v3 IS NOT NULL AND rec.v4 IS NOT NULL
             AND rec.v1 < rec.v2 AND rec.v2 < rec.v3 AND rec.v3 < rec.v4 THEN
            INSERT INTO public.prudential_ewi_alerts
              (entity_id, rule_id, rule_code, rule_version, period_end, metric_key, severity, evidence, executed_at)
            VALUES (_entity_id, r.id, r.code, r.version, _period_end, rec.ratio_key, r.severity,
                    jsonb_build_object('rule_type', r.rule_type, 'series',
                                       jsonb_build_array(rec.v4, rec.v3, rec.v2, rec.v1)), now())
            ON CONFLICT (entity_id, rule_id, period_end, metric_key)
              DO UPDATE SET evidence = EXCLUDED.evidence, executed_at = now(), updated_at = now();
            v_created := v_created + 1;
          END IF;
        END IF;
      END LOOP;

    ELSIF r.rule_type = 'late_return' THEN
      SELECT id INTO v_existing FROM public.returns_filed
       WHERE entity_id = _entity_id AND period_end_date = _period_end
         AND workflow_status IN ('SUB','VAL','TBR')
       LIMIT 1;
      IF v_existing IS NULL THEN
        INSERT INTO public.prudential_ewi_alerts
          (entity_id, rule_id, rule_code, rule_version, period_end, metric_key, severity, evidence, executed_at)
        VALUES (_entity_id, r.id, r.code, r.version, _period_end, '', r.severity,
                jsonb_build_object('rule_type', r.rule_type, 'reason', 'no_submitted_return'), now())
        ON CONFLICT (entity_id, rule_id, period_end, metric_key)
          DO UPDATE SET evidence = EXCLUDED.evidence, executed_at = now(), updated_at = now();
        v_created := v_created + 1;
      END IF;
    END IF;
  END LOOP;

  BEGIN
    PERFORM public.log_compliance_audit(
      'CREATE'::public.compliance_audit_action, 'prudential_ewi_evaluation', _entity_id::text,
      NULL, jsonb_build_object('period_end', _period_end, 'alerts', v_created), NULL, NULL, NULL,
      jsonb_build_object('source', 'prudential_ewi_evaluate'));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('entity_id', _entity_id, 'period_end', _period_end,
                            'alerts_written', v_created, 'refreshed', v_refreshed,
                            'executed_at', now());
END $function$
;
CREATE OR REPLACE FUNCTION public.prudential_feed_log_record(_source text, _feed_type text, _status text, _row_count integer DEFAULT NULL::integer, _error text DEFAULT NULL::text, _related_filing_id uuid DEFAULT NULL::uuid, _completed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS prudential_data_feed_logs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.prudential_data_feed_logs;
BEGIN
  PERFORM public.enforce_permission('prudential_supervision','view');
  IF _status NOT IN ('started','success','failed','retried') THEN
    RAISE EXCEPTION 'unsupported feed status %', _status USING ERRCODE='22023'; END IF;
  INSERT INTO public.prudential_data_feed_logs(source, feed_type, status, row_count, error,
    related_filing_id, completed_at, triggered_by, metadata)
  VALUES (_source, _feed_type, _status, _row_count, _error, _related_filing_id, _completed_at, auth.uid(),
    COALESCE(_metadata,'{}'::jsonb))
  RETURNING * INTO v_row;
  RETURN v_row;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_filing_metric_facts(_return_filing_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH f AS (
    SELECT w.* FROM public.v_return_filing_workflow_state w WHERE w.filing_id = _return_filing_id
  )
  SELECT jsonb_build_object(
    'filing', (SELECT to_jsonb(f) FROM f),
    'metrics', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'filing_id', f.filing_id,
        'return_filing_version_id', mv.return_filing_version_id,
        'reporting_period_id', mv.reporting_period_id,
        'period_label', f.period_label,
        'period_end', f.period_end,
        'regulatory_metric_id', m.id,
        'metric_code', m.code,
        'metric_name', m.name,
        'unit', m.unit,
        'value_numeric', mv.value_numeric,
        'availability', mv.availability,
        'source_kind', mv.source_kind,
        'recorded_at', COALESCE(mv.calculated_at, mv.recorded_at)
      ) ORDER BY m.code), '[]'::jsonb)
      FROM f
      JOIN public.return_metric_values mv
        ON mv.return_filing_version_id = COALESCE(f.accepted_version_id, f.current_version_id)
      JOIN public.regulatory_metrics m ON m.id = mv.regulatory_metric_id
     WHERE mv.value_numeric IS NOT NULL
    ),
    'breaches', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', b.id,
        'return_filing_id', b.return_filing_id,
        'return_filing_version_id', b.return_filing_version_id,
        'reporting_period_id', b.reporting_period_id,
        'regulatory_metric_id', b.regulatory_metric_id,
        'detection_run_id', b.detection_run_id,
        'metric_key', b.metric_key,
        'level', b.level,
        'risk_level', b.risk_level,
        'value', b.value,
        'threshold_value', b.threshold_value,
        'comparator', b.comparator,
        'detected_at', b.detected_at
      ) ORDER BY b.detected_at DESC), '[]'::jsonb)
      FROM public.v_prudential_current_breaches b
     WHERE b.return_filing_id = _return_filing_id
    ),
    'stress_events', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', s.id,
        'indicator_id', s.indicator_id,
        'entity_id', s.entity_id,
        'return_filing_id', s.return_filing_id,
        'observed_value', s.observed_value,
        'triggered_at', s.triggered_at,
        'resolved_at', s.resolved_at,
        'label', i.label,
        'severity', i.severity,
        'metric_key', i.metric_key
      ) ORDER BY s.triggered_at DESC), '[]'::jsonb)
      FROM public.prudential_stress_events s
      LEFT JOIN public.prudential_stress_indicators i ON i.id = s.indicator_id
     WHERE s.return_filing_id = _return_filing_id
    )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_group_consolidated(_group_id uuid, _period_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_period text;
  v_group jsonb;
  v_members jsonb;
  v_snapshot jsonb;
  v_score jsonb;
  v_alerts jsonb;
  v_heatmap jsonb;
  v_breaches jsonb;
  v_member_metrics jsonb;
  v_method jsonb;
BEGIN
  IF NOT public.can_read_financial_group(auth.uid(), _group_id) THEN
    RAISE EXCEPTION 'not authorised to view this financial group';
  END IF;

  v_period := COALESCE(_period_key,
    (SELECT w.period_label
       FROM public.financial_group_members m
       JOIN public.v_return_filing_workflow_state w ON w.entity_id = m.licensee_id
      WHERE m.group_id = _group_id
        AND w.status <> 'WITHDRAWN'
        AND w.period_label IS NOT NULL
      ORDER BY w.period_end DESC NULLS LAST LIMIT 1));

  SELECT to_jsonb(g) || jsonb_build_object('holding_entity_name', l.name)
    INTO v_group
  FROM public.financial_groups g
  LEFT JOIN public.licensees l ON l.id = g.holding_entity_id
  WHERE g.id = _group_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'member_id', m.id, 'licensee_id', m.licensee_id, 'name', l.name,
      'parent_member_id', m.parent_member_id, 'member_role', m.member_role,
      'ownership_percentage', m.ownership_percentage,
      'consolidation_treatment', m.consolidation_treatment,
      'effective_date', m.effective_date, 'end_date', m.end_date,
      'licensee_status', l.status, 'sector_id', l.sector_id,
      'sector_name', s.name,
      'systemic_importance', l.systemic_importance,
      'risk_score', rs.score, 'risk_band', rs.band
    ) ORDER BY CASE m.member_role WHEN 'ultimate_holding' THEN 0 ELSE 1 END, l.name), '[]'::jsonb)
    INTO v_members
  FROM public.financial_group_members m
  JOIN public.licensees l ON l.id = m.licensee_id
  LEFT JOIN public.sectors s ON s.id = l.sector_id
  LEFT JOIN public.entity_risk_scores rs ON rs.entity_id = m.licensee_id AND rs.is_current
  WHERE m.group_id = _group_id;

  SELECT to_jsonb(x) INTO v_snapshot FROM public.group_consolidated_snapshots x
   WHERE x.group_id = _group_id AND x.period_key = v_period;

  SELECT to_jsonb(x) INTO v_score FROM public.group_risk_scores x
   WHERE x.group_id = _group_id AND x.period_key = v_period;

  SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.fired_at DESC), '[]'::jsonb) INTO v_alerts
  FROM public.group_ewi_alerts a WHERE a.group_id = _group_id AND a.status <> 'closed';

  SELECT to_jsonb(x) INTO v_method FROM public.group_consolidation_methods x
   WHERE x.group_id = _group_id AND x.is_active ORDER BY x.version DESC LIMIT 1;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'licensee_id', t.licensee_id, 'name', t.name,
      'overall_rating', t.overall_rating, 'ratings', t.ratings,
      'assessed_at', t.updated_at) ORDER BY t.name), '[]'::jsonb)
    INTO v_heatmap
  FROM (
    SELECT DISTINCT ON (m.licensee_id) m.licensee_id, l.name, a.overall_rating, a.ratings, a.updated_at
    FROM public.financial_group_members m
    JOIN public.licensees l ON l.id = m.licensee_id
    LEFT JOIN public.prudential_assessments a ON a.entity_id = m.licensee_id
    WHERE m.group_id = _group_id
    ORDER BY m.licensee_id,
             CASE WHEN a.status IN ('approved','closed') THEN 0 ELSE 1 END,
             a.updated_at DESC NULLS LAST
  ) t;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'licensee_id', b.entity_id, 'name', l.name, 'metric_key', b.metric_key,
      'risk_level', b.risk_level, 'level', b.level, 'value', b.value,
      'threshold_value', b.threshold_value, 'comparator', b.comparator,
      'detected_at', b.detected_at,
      'return_filing_id', b.return_filing_id,
      'return_filing_version_id', b.return_filing_version_id,
      'reporting_period_id', b.reporting_period_id,
      'period', b.period_label) ORDER BY b.detected_at DESC), '[]'::jsonb)
    INTO v_breaches
  FROM public.financial_group_members m
  JOIN public.licensees l ON l.id = m.licensee_id
  JOIN public.v_prudential_current_breaches b ON b.entity_id = m.licensee_id
  WHERE m.group_id = _group_id
    AND (v_period IS NULL OR b.period_label = v_period);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'licensee_id', w.entity_id, 'name', l.name,
      'return_filing_id', w.filing_id, 'filing_reference', w.filing_reference,
      'return_filing_version_id', COALESCE(w.accepted_version_id, w.current_version_id),
      'reporting_period_id', w.reporting_period_id,
      'period', w.period_label, 'period_end', w.period_end,
      'filing_status', w.status,
      'metric_code', rm.code, 'metric_name', rm.name, 'unit', rm.unit,
      'value', mv.value_numeric) ORDER BY l.name, rm.code), '[]'::jsonb)
    INTO v_member_metrics
  FROM public.financial_group_members m
  JOIN public.licensees l ON l.id = m.licensee_id
  JOIN public.v_return_filing_workflow_state w ON w.entity_id = m.licensee_id
  JOIN public.return_metric_values mv
    ON mv.return_filing_version_id = COALESCE(w.accepted_version_id, w.current_version_id)
  JOIN public.regulatory_metrics rm ON rm.id = mv.regulatory_metric_id
  WHERE m.group_id = _group_id
    AND w.status <> 'WITHDRAWN'
    AND mv.value_numeric IS NOT NULL
    AND (v_period IS NULL OR w.period_label = v_period);

  RETURN jsonb_build_object(
    'group', v_group,
    'period_key', v_period,
    'members', v_members,
    'methodology', v_method,
    'snapshot', v_snapshot,
    'score', v_score,
    'alerts', v_alerts,
    'heatmap', v_heatmap,
    'breaches', v_breaches,
    'member_metrics', v_member_metrics,
    'matrix', public.intragroup_exposure_matrix(_group_id, v_period)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_group_periods(_group_id uuid)
 RETURNS TABLE(period_key text, period_end date)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT ON (w.period_label) w.period_label, w.period_end
    FROM public.financial_group_members m
    JOIN public.v_return_filing_workflow_state w ON w.entity_id = m.licensee_id
   WHERE m.group_id = _group_id
     AND w.status <> 'WITHDRAWN'
     AND w.period_label IS NOT NULL
   ORDER BY w.period_label, w.period_end DESC;
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_min_peers()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT GREATEST(
    COALESCE((SELECT (value->>'min_peers')::int
                FROM public.site_settings
               WHERE key = 'prudential_peer_settings'), 5), 3)
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_ratio_delete(_ratio_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.prudential_ratios;
BEGIN
  PERFORM public.enforce_permission('prudential_supervision','manage_config');
  PERFORM public.prudential_require_rationale(_reason, 5, 'reason');
  SELECT * INTO v_before FROM public.prudential_ratios WHERE id = _ratio_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'ratio % not found', _ratio_id USING ERRCODE='P0002'; END IF;
  DELETE FROM public.prudential_ratios WHERE id = _ratio_id;
  PERFORM public.prudential_audit_event('prudential_ratio_deleted','prudential_ratio',_ratio_id,
    to_jsonb(v_before), NULL, '{}'::jsonb, _reason, 'DELETE');
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_ratio_save(_payload jsonb, _ratio_id uuid DEFAULT NULL::uuid, _reason text DEFAULT NULL::text)
 RETURNS prudential_ratios
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.prudential_ratios; v_after public.prudential_ratios;
BEGIN
  PERFORM public.enforce_permission('prudential_supervision','manage_config');
  IF _ratio_id IS NOT NULL THEN
    SELECT * INTO v_before FROM public.prudential_ratios WHERE id = _ratio_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'ratio % not found', _ratio_id USING ERRCODE='P0002'; END IF;
    UPDATE public.prudential_ratios r
    SET return_config_id = COALESCE((_payload->>'return_config_id')::uuid, r.return_config_id),
        ratio_key = COALESCE(_payload->>'ratio_key', r.ratio_key),
        label = COALESCE(_payload->>'label', r.label),
        formula = COALESCE(_payload->>'formula', r.formula),
        display_format = COALESCE(_payload->>'display_format', r.display_format),
        metric_key = COALESCE(_payload->>'metric_key', r.metric_key),
        category = COALESCE(_payload->>'category', r.category),
        recommendation_template = COALESCE(_payload->>'recommendation_template', r.recommendation_template),
        taxonomy_code = COALESCE(_payload->>'taxonomy_code', r.taxonomy_code),
        is_active = COALESCE((_payload->>'is_active')::boolean, r.is_active),
        updated_at = now()
    WHERE r.id = _ratio_id RETURNING * INTO v_after;
  ELSE
    INSERT INTO public.prudential_ratios(return_config_id, ratio_key, label, formula, display_format, metric_key,
      category, recommendation_template, taxonomy_code, is_active)
    VALUES ((_payload->>'return_config_id')::uuid, _payload->>'ratio_key', _payload->>'label', _payload->>'formula',
      _payload->>'display_format', _payload->>'metric_key', _payload->>'category', _payload->>'recommendation_template',
      _payload->>'taxonomy_code', COALESCE((_payload->>'is_active')::boolean, true))
    RETURNING * INTO v_after;
  END IF;
  PERFORM public.prudential_audit_event('prudential_ratio_saved','prudential_ratio',v_after.id,
    to_jsonb(v_before), to_jsonb(v_after), jsonb_build_object('config','ratio'), _reason,
    CASE WHEN _ratio_id IS NULL THEN 'CREATE'::public.compliance_audit_action ELSE 'UPDATE'::public.compliance_audit_action END);
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_require_rationale(_text text, _min integer DEFAULT 10, _label text DEFAULT 'rationale'::text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF _text IS NULL OR length(btrim(_text)) < _min THEN
    RAISE EXCEPTION 'a % of at least % characters is required', _label, _min USING ERRCODE = '22023';
  END IF;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_resolve_threshold(_metric_code text, _sector_id uuid, _as_of date)
 RETURNS TABLE(threshold_id uuid, label text, comparator text, warn_value numeric, breach_value numeric, unit text, threshold_version integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT t.id, t.label,
         COALESCE(tv.comparator, t.comparator),
         COALESCE(tv.warn_value, t.warn_value),
         COALESCE(tv.breach_value, t.breach_value),
         COALESCE(tv.unit, t.unit),
         COALESCE(tv.version, t.current_version, 1)
    FROM public.prudential_thresholds t
    LEFT JOIN public.prudential_threshold_versions tv
           ON tv.threshold_id = t.id
          AND (tv.effective_from IS NULL OR tv.effective_from <= _as_of)
          AND (tv.effective_to IS NULL OR tv.effective_to >= _as_of)
   WHERE t.is_active
     AND t.metric_key = _metric_code
     AND (t.sector_id IS NULL OR t.sector_id = _sector_id)
     AND (t.effective_from IS NULL OR t.effective_from <= _as_of)
     AND (t.effective_to IS NULL OR t.effective_to >= _as_of)
   ORDER BY (t.sector_id IS NULL), tv.effective_from DESC NULLS LAST, tv.version DESC NULLS LAST
   LIMIT 1;
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_sector_risk(_lookback_days integer DEFAULT 365)
 RETURNS TABLE(sector_id uuid, sector_name text, entity_count integer, ratio_breaches integer, severe_ewi integer, adverse_assessments integer, group_risk_signals integer, open_actions integer, evidence_count integer, score numeric, band text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _since timestamptz := now() - make_interval(days => GREATEST(COALESCE(_lookback_days, 365), 1));
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.user_has_permission(auth.uid(), 'prudential_supervision', 'view') THEN
    RAISE EXCEPTION 'insufficient_privilege: prudential_supervision.view required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH ent AS (
    SELECT l.id, l.sector_id
    FROM public.licensees l
    WHERE l.sector_id IS NOT NULL
  ),
  breaches AS (
    SELECT e.sector_id, count(*)::int AS n
    FROM public.return_threshold_breaches b
    JOIN public.returns_filed rf ON rf.id = b.return_id
    JOIN ent e ON e.id = rf.entity_id
    WHERE b.detected_at >= _since
      AND b.acknowledged_at IS NULL
      AND (lower(COALESCE(b.level, '')) IN ('breach', 'critical', 'high')
           OR lower(COALESCE(b.risk_level, '')) IN ('high', 'critical'))
    GROUP BY e.sector_id
  ),
  ewi AS (
    SELECT e.sector_id, count(*)::int AS n
    FROM public.prudential_ewi_alerts a
    JOIN ent e ON e.id = a.entity_id
    WHERE a.executed_at >= _since
      AND lower(COALESCE(a.severity, '')) IN ('high', 'critical')
      AND lower(COALESCE(a.status, '')) NOT IN ('closed', 'resolved', 'dismissed', 'cancelled', 'false_positive')
    GROUP BY e.sector_id
  ),
  assess AS (
    SELECT e.sector_id, count(*)::int AS n
    FROM public.prudential_assessments pa
    JOIN ent e ON e.id = pa.entity_id
    WHERE pa.created_at >= _since
      AND upper(COALESCE(pa.overall_rating, '')) IN ('4', '5', 'HIGH', 'CRITICAL', 'ADVERSE', 'UNSATISFACTORY')
    GROUP BY e.sector_id
  ),
  grp AS (
    SELECT DISTINCT e.sector_id, gm.group_id, gs.band
    FROM public.group_risk_scores gs
    JOIN public.financial_group_members gm ON gm.group_id = gs.group_id
    JOIN ent e ON e.id = gm.licensee_id
    WHERE gs.is_current
      AND lower(COALESCE(gs.band, '')) IN ('high', 'critical')
      AND (gm.end_date IS NULL OR gm.end_date >= current_date)
  ),
  grp_agg AS (
    SELECT sector_id, count(*)::int AS n FROM grp GROUP BY sector_id
  ),
  acts AS (
    SELECT e.sector_id, count(*)::int AS n
    FROM public.prudential_actions pact
    JOIN ent e ON e.id = pact.entity_id
    WHERE lower(COALESCE(pact.severity, '')) IN ('high', 'critical')
      AND lower(COALESCE(pact.status, '')) NOT IN ('closed', 'cancelled', 'completed', 'withdrawn')
    GROUP BY e.sector_id
  ),
  base AS (
    SELECT s.id AS sector_id,
           s.name AS sector_name,
           (SELECT count(*) FROM ent e WHERE e.sector_id = s.id)::int AS entity_count,
           COALESCE(breaches.n, 0) AS ratio_breaches,
           COALESCE(ewi.n, 0) AS severe_ewi,
           COALESCE(assess.n, 0) AS adverse_assessments,
           COALESCE(grp_agg.n, 0) AS group_risk_signals,
           COALESCE(acts.n, 0) AS open_actions
    FROM public.sectors s
    LEFT JOIN breaches ON breaches.sector_id = s.id
    LEFT JOIN ewi ON ewi.sector_id = s.id
    LEFT JOIN assess ON assess.sector_id = s.id
    LEFT JOIN grp_agg ON grp_agg.sector_id = s.id
    LEFT JOIN acts ON acts.sector_id = s.id
  ),
  scored AS (
    SELECT b.*,
           (b.ratio_breaches + b.severe_ewi + b.adverse_assessments
            + b.group_risk_signals + b.open_actions) AS evidence_count,
           (b.ratio_breaches * 3 + b.severe_ewi * 4 + b.adverse_assessments * 5
            + b.group_risk_signals * 3 + b.open_actions * 2)::numeric AS weighted
    FROM base b
  )
  SELECT sc.sector_id,
         sc.sector_name,
         sc.entity_count,
         sc.ratio_breaches,
         sc.severe_ewi,
         sc.adverse_assessments,
         sc.group_risk_signals,
         sc.open_actions,
         sc.evidence_count,
         CASE WHEN sc.evidence_count = 0 THEN NULL
              ELSE round(sc.weighted / GREATEST(sc.entity_count, 1), 2) END AS score,
         CASE
           WHEN sc.evidence_count = 0 THEN 'INSUFFICIENT_DATA'
           WHEN sc.weighted / GREATEST(sc.entity_count, 1) >= 8 THEN 'CRITICAL'
           WHEN sc.weighted / GREATEST(sc.entity_count, 1) >= 4 THEN 'HIGH'
           WHEN sc.weighted / GREATEST(sc.entity_count, 1) >= 1.5 THEN 'MEDIUM'
           ELSE 'LOW'
         END AS band
  FROM scored sc
  ORDER BY (sc.evidence_count = 0), sc.weighted / GREATEST(sc.entity_count, 1) DESC, sc.sector_name;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_sector_risk_distribution()
 RETURNS TABLE(sector_id uuid, sector_name text, entity_count bigint, breach_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT s.id, s.name,
         COUNT(DISTINCT l.id) AS entity_count,
         COUNT(b.id) AS breach_count
  FROM public.sectors s
  LEFT JOIN public.licensees l ON l.sector_id = s.id
  LEFT JOIN public.returns_filed rf ON rf.entity_id = l.id
  LEFT JOIN public.return_threshold_breaches b ON b.return_id = rf.id
  GROUP BY s.id, s.name
  ORDER BY s.name;
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_stress_event_acknowledge(_event_id uuid)
 RETURNS prudential_stress_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.prudential_stress_events; v_after public.prudential_stress_events;
BEGIN
  SELECT * INTO v_before FROM public.prudential_stress_events WHERE id = _event_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'stress event % not found', _event_id USING ERRCODE='P0002'; END IF;
  PERFORM public.prudential_enforce('view', v_before.entity_id);
  UPDATE public.prudential_stress_events e SET notified = true WHERE e.id = _event_id RETURNING * INTO v_after;
  PERFORM public.prudential_audit_event('prudential_stress_event_acknowledged','prudential_stress_event',_event_id,
    to_jsonb(v_before), to_jsonb(v_after), jsonb_build_object('entity_id',v_before.entity_id), NULL, 'UPDATE');
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_stress_indicator_delete(_indicator_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.prudential_stress_indicators;
BEGIN
  PERFORM public.enforce_permission('prudential_supervision','manage_config');
  PERFORM public.prudential_require_rationale(_reason, 5, 'reason');
  SELECT * INTO v_before FROM public.prudential_stress_indicators WHERE id = _indicator_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'stress indicator % not found', _indicator_id USING ERRCODE='P0002'; END IF;
  DELETE FROM public.prudential_stress_indicators WHERE id = _indicator_id;
  PERFORM public.prudential_audit_event('prudential_stress_indicator_deleted','prudential_stress_indicator',_indicator_id,
    to_jsonb(v_before), NULL, '{}'::jsonb, _reason, 'DELETE');
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_stress_indicator_save(_payload jsonb, _indicator_id uuid DEFAULT NULL::uuid, _reason text DEFAULT NULL::text)
 RETURNS prudential_stress_indicators
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.prudential_stress_indicators; v_after public.prudential_stress_indicators;
BEGIN
  PERFORM public.enforce_permission('prudential_supervision','manage_config');
  IF _indicator_id IS NOT NULL THEN
    SELECT * INTO v_before FROM public.prudential_stress_indicators WHERE id = _indicator_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'stress indicator % not found', _indicator_id USING ERRCODE='P0002'; END IF;
    UPDATE public.prudential_stress_indicators s
    SET metric_key = COALESCE(_payload->>'metric_key', s.metric_key),
        label = COALESCE(_payload->>'label', s.label),
        taxonomy_code = COALESCE(_payload->>'taxonomy_code', s.taxonomy_code),
        threshold_value = COALESCE((_payload->>'threshold_value')::numeric, s.threshold_value),
        direction = COALESCE(_payload->>'direction', s.direction),
        severity = COALESCE(_payload->>'severity', s.severity),
        sector_id = CASE WHEN _payload ? 'sector_id' THEN (_payload->>'sector_id')::uuid ELSE s.sector_id END,
        sub_sector_id = CASE WHEN _payload ? 'sub_sector_id' THEN (_payload->>'sub_sector_id')::uuid ELSE s.sub_sector_id END,
        notify_roles = COALESCE(_payload->'notify_roles', s.notify_roles),
        escalate = COALESCE((_payload->>'escalate')::boolean, s.escalate),
        is_active = COALESCE((_payload->>'is_active')::boolean, s.is_active),
        updated_at = now()
    WHERE s.id = _indicator_id RETURNING * INTO v_after;
  ELSE
    INSERT INTO public.prudential_stress_indicators(metric_key, label, taxonomy_code, threshold_value, direction,
      severity, sector_id, sub_sector_id, notify_roles, escalate, is_active, created_by)
    VALUES (_payload->>'metric_key', _payload->>'label', _payload->>'taxonomy_code',
      (_payload->>'threshold_value')::numeric, _payload->>'direction', _payload->>'severity',
      (_payload->>'sector_id')::uuid, (_payload->>'sub_sector_id')::uuid,
      COALESCE(_payload->'notify_roles','[]'::jsonb), COALESCE((_payload->>'escalate')::boolean,false),
      COALESCE((_payload->>'is_active')::boolean,true), auth.uid())
    RETURNING * INTO v_after;
  END IF;
  PERFORM public.prudential_audit_event('prudential_stress_indicator_saved','prudential_stress_indicator',v_after.id,
    to_jsonb(v_before), to_jsonb(v_after), jsonb_build_object('config','stress_indicator'), _reason,
    CASE WHEN _indicator_id IS NULL THEN 'CREATE'::public.compliance_audit_action ELSE 'UPDATE'::public.compliance_audit_action END);
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_taxonomy_save(_payload jsonb, _taxonomy_id uuid DEFAULT NULL::uuid, _reason text DEFAULT NULL::text)
 RETURNS prudential_risk_taxonomy
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.prudential_risk_taxonomy; v_after public.prudential_risk_taxonomy;
BEGIN
  PERFORM public.enforce_permission('prudential_supervision','manage_config');
  IF _taxonomy_id IS NOT NULL THEN
    SELECT * INTO v_before FROM public.prudential_risk_taxonomy WHERE id = _taxonomy_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'taxonomy node % not found', _taxonomy_id USING ERRCODE='P0002'; END IF;
    UPDATE public.prudential_risk_taxonomy t
    SET code = COALESCE(_payload->>'code', t.code),
        label = COALESCE(_payload->>'label', t.label),
        description = COALESCE(_payload->>'description', t.description),
        parent_id = CASE WHEN _payload ? 'parent_id' THEN (_payload->>'parent_id')::uuid ELSE t.parent_id END,
        sort_order = COALESCE((_payload->>'sort_order')::int, t.sort_order),
        is_active = COALESCE((_payload->>'is_active')::boolean, t.is_active),
        updated_at = now()
    WHERE t.id = _taxonomy_id RETURNING * INTO v_after;
  ELSE
    INSERT INTO public.prudential_risk_taxonomy(code, label, description, parent_id, sort_order, is_active)
    VALUES (_payload->>'code', _payload->>'label', _payload->>'description', (_payload->>'parent_id')::uuid,
      COALESCE((_payload->>'sort_order')::int, 0), COALESCE((_payload->>'is_active')::boolean, true))
    RETURNING * INTO v_after;
  END IF;
  PERFORM public.prudential_audit_event('prudential_taxonomy_saved','prudential_risk_taxonomy',v_after.id,
    to_jsonb(v_before), to_jsonb(v_after), jsonb_build_object('config','risk_taxonomy'), _reason,
    CASE WHEN _taxonomy_id IS NULL THEN 'CREATE'::public.compliance_audit_action ELSE 'UPDATE'::public.compliance_audit_action END);
  RETURN v_after;
END; $function$
;
