CREATE OR REPLACE FUNCTION public.prudential_threshold_save(_payload jsonb, _threshold_id uuid DEFAULT NULL::uuid, _reason text DEFAULT NULL::text)
 RETURNS prudential_thresholds
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.prudential_thresholds; v_after public.prudential_thresholds;
BEGIN
  PERFORM public.enforce_permission('prudential_supervision','manage_config');
  IF _threshold_id IS NOT NULL THEN
    SELECT * INTO v_before FROM public.prudential_thresholds WHERE id = _threshold_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'threshold % not found', _threshold_id USING ERRCODE='P0002'; END IF;
    UPDATE public.prudential_thresholds t
    SET return_config_id = COALESCE((_payload->>'return_config_id')::uuid, t.return_config_id),
        metric_key = COALESCE(_payload->>'metric_key', t.metric_key),
        label = COALESCE(_payload->>'label', t.label),
        comparator = COALESCE(_payload->>'comparator', t.comparator),
        warn_value = COALESCE((_payload->>'warn_value')::numeric, t.warn_value),
        breach_value = COALESCE((_payload->>'breach_value')::numeric, t.breach_value),
        upper_value = COALESCE((_payload->>'upper_value')::numeric, t.upper_value),
        unit = COALESCE(_payload->>'unit', t.unit),
        is_active = COALESCE((_payload->>'is_active')::boolean, t.is_active),
        effective_from = COALESCE((_payload->>'effective_from')::date, t.effective_from),
        effective_to = COALESCE((_payload->>'effective_to')::date, t.effective_to),
        sector_id = COALESCE((_payload->>'sector_id')::uuid, t.sector_id),
        return_type_id = COALESCE((_payload->>'return_type_id')::uuid, t.return_type_id),
        taxonomy_code = COALESCE(_payload->>'taxonomy_code', t.taxonomy_code),
        updated_at = now()
    WHERE t.id = _threshold_id RETURNING * INTO v_after;
  ELSE
    INSERT INTO public.prudential_thresholds(return_config_id, metric_key, label, comparator, warn_value, breach_value,
      upper_value, unit, is_active, effective_from, effective_to, sector_id, return_type_id, taxonomy_code)
    VALUES ((_payload->>'return_config_id')::uuid, _payload->>'metric_key', _payload->>'label',
      _payload->>'comparator', (_payload->>'warn_value')::numeric, (_payload->>'breach_value')::numeric,
      (_payload->>'upper_value')::numeric, _payload->>'unit', COALESCE((_payload->>'is_active')::boolean, true),
      (_payload->>'effective_from')::date, (_payload->>'effective_to')::date, (_payload->>'sector_id')::uuid,
      (_payload->>'return_type_id')::uuid, _payload->>'taxonomy_code')
    RETURNING * INTO v_after;
  END IF;
  PERFORM public.prudential_audit_event('prudential_threshold_saved','prudential_threshold',v_after.id,
    to_jsonb(v_before), to_jsonb(v_after), jsonb_build_object('config','threshold'), _reason,
    CASE WHEN _threshold_id IS NULL THEN 'CREATE'::public.compliance_audit_action ELSE 'UPDATE'::public.compliance_audit_action END);
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.prudential_visible_entities(_user uuid)
 RETURNS TABLE(id uuid, name text, sector_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH flags AS (
    SELECT
      _user IS NOT NULL AND NOT public.has_external_role(_user) AS internal,
      _user IS NOT NULL AND (
        public.is_super_admin(_user)
        OR public.has_permission(_user, 'prudential_supervision', 'view_all_entities')
      ) AS view_all,
      _user IS NOT NULL AND public.has_permission(_user, 'prudential_supervision', 'view') AS can_view
  )
  SELECT l.id, l.name, l.sector_id
    FROM public.licensees l, flags f
   WHERE f.internal
     AND (
       f.view_all
       OR (
         f.can_view
         AND (
           l.lead_regulator_id = _user
           OR l.regulator_officer_id = _user
           OR l.alternate_regulator_id = _user
           OR EXISTS (SELECT 1 FROM public.entity_user_access eua
                       WHERE eua.entity_id = l.id AND eua.user_id = _user)
         )
       )
     );
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_work_queue(_types text[] DEFAULT NULL::text[], _entity_id uuid DEFAULT NULL::uuid, _sector_id uuid DEFAULT NULL::uuid, _owner uuid DEFAULT NULL::uuid, _unassigned boolean DEFAULT false, _sla text DEFAULT NULL::text, _severity text[] DEFAULT NULL::text[], _stage text DEFAULT NULL::text, _search text DEFAULT NULL::text, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS TABLE(work_item_type text, work_item_id uuid, entity_id uuid, entity_name text, reference text, title text, stage text, stage_label text, status text, status_label text, owner_user_id uuid, owner_name text, team text, priority text, priority_reason text, sla_due_at timestamp with time zone, sla_state text, waiting_on text, blocker_count integer, blockers jsonb, next_action_code text, next_action_label text, next_action_href text, next_action_permission text, source_type text, source_id uuid, last_activity_at timestamp with time zone, canonical_href text, detail jsonb, total_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
WITH cfg AS (
  SELECT work_item_type, sla_days, due_soon_days FROM public.prudential_process_sla_config
),
vis AS MATERIALIZED (
  SELECT v.id, v.name, v.sector_id
    FROM public.prudential_visible_entities(auth.uid()) v
   WHERE (_entity_id IS NULL OR v.id = _entity_id)
     AND (_sector_id IS NULL OR v.sector_id = _sector_id)
),
assign AS (
  SELECT a.entity_id, a.supervisor_id, a.supervisor_name, a.team
    FROM public.entity_supervision_assignments a
    JOIN vis ON vis.id = a.entity_id
   WHERE a.status = 'active'
),
raw AS (
  SELECT
    'BREACH'::text AS work_item_type,
    b.id AS work_item_id,
    b.entity_id,
    b.metric_key AS reference,
    'Threshold breach · ' || coalesce(b.metric_key, 'metric') AS title,
    CASE WHEN b.acknowledged_at IS NULL THEN 'DETECTION'
         WHEN EXISTS (SELECT 1 FROM public.prudential_actions pa
                       WHERE pa.source_type = 'return_breach' AND pa.source_id = b.id
                         AND pa.status NOT IN ('completed','waived','cancelled')) THEN 'ACTION_MONITORING'
         ELSE 'SUPERVISORY_REVIEW' END AS stage,
    CASE WHEN b.acknowledged_at IS NULL THEN 'unacknowledged' ELSE 'acknowledged' END AS status,
    NULL::uuid AS owner_user_id,
    coalesce(lower(b.risk_level), lower(b.level), 'high') AS severity,
    'Breach of a configured prudential threshold' AS priority_reason,
    b.detected_at + (SELECT make_interval(days => sla_days) FROM cfg WHERE work_item_type = 'BREACH') AS sla_due_at,
    'regulator'::text AS waiting_on,
    'return_filing'::text AS source_type,
    b.return_filing_id AS source_id,
    greatest(b.detected_at, coalesce(b.acknowledged_at, b.detected_at)) AS last_activity_at,
    jsonb_build_object(
      'metric_key', b.metric_key,
      'period_label', b.period_label,
      'period_end', b.period_end,
      'observed_value', b.value,
      'threshold_value', b.threshold_value,
      'comparator', b.comparator,
      'acknowledged_at', b.acknowledged_at,
      'return_filing_id', b.return_filing_id,
      'filing_reference', b.filing_reference,
      'linked_actions', coalesce((
        SELECT jsonb_agg(jsonb_build_object('id', pa.id, 'reference', pa.action_reference,
                                            'title', pa.title, 'status', pa.status, 'due_date', pa.due_date))
          FROM public.prudential_actions pa
         WHERE pa.source_type = 'return_breach' AND pa.source_id = b.id), '[]'::jsonb)
    ) AS detail
  FROM public.v_prudential_current_breaches b
  JOIN vis ON vis.id = b.entity_id

  UNION ALL
  SELECT
    'EWI', e.id, e.entity_id, e.rule_code,
    'Early warning · ' || coalesce(nullif(e.metric_key, ''), e.rule_code),
    CASE WHEN e.status = 'open' THEN 'DETECTION' ELSE 'SUPERVISORY_REVIEW' END,
    e.status, e.acknowledged_by, lower(e.severity),
    'Early warning rule ' || e.rule_code || ' triggered',
    e.executed_at + (SELECT make_interval(days => sla_days) FROM cfg WHERE work_item_type = 'EWI'),
    'regulator', 'ewi_rule', e.rule_id,
    greatest(e.executed_at, coalesce(e.acknowledged_at, e.executed_at)),
    jsonb_build_object('metric_key', e.metric_key, 'period_end', e.period_end,
                       'rule_code', e.rule_code, 'rule_version', e.rule_version,
                       'evidence', e.evidence, 'acknowledged_at', e.acknowledged_at,
                       'return_filing_id', e.return_filing_id)
  FROM public.prudential_ewi_alerts e
  JOIN vis ON vis.id = e.entity_id
  WHERE e.status NOT IN ('closed','dismissed','resolved')

  UNION ALL
  SELECT
    'ASSESSMENT', a.id, a.entity_id, 'PA-ASMT-' || substr(a.id::text, 1, 8),
    'Prudential assessment' || coalesce(' · ' || to_char(a.period_end, 'DD Mon YYYY'), ''),
    CASE a.status
      WHEN 'draft' THEN 'DATA_REVIEW'
      WHEN 'returned_for_revision' THEN 'RISK_ASSESSMENT'
      WHEN 'submitted' THEN 'SUPERVISORY_REVIEW'
      WHEN 'reviewed' THEN 'DECISION'
      WHEN 'approved' THEN 'ACTION_MONITORING'
      ELSE 'CLOSED' END,
    a.status, coalesce(a.reviewed_by, a.created_by),
    CASE WHEN a.overall_rating ~ '^[45]' THEN 'high' ELSE 'medium' END,
    'Assessment in progress for the reporting period',
    coalesce(a.submitted_at, a.created_at) + (SELECT make_interval(days => sla_days) FROM cfg WHERE work_item_type = 'ASSESSMENT'),
    'regulator', 'return_filing', a.return_filing_id,
    a.updated_at,
    jsonb_build_object('overall_rating', a.overall_rating, 'period_start', a.period_start,
                       'period_end', a.period_end, 'return_filing_id', a.return_filing_id,
                       'has_rationale', (a.rationale IS NOT NULL AND length(trim(a.rationale)) > 0),
                       'has_conclusion', (a.conclusion IS NOT NULL AND length(trim(a.conclusion)) > 0))
  FROM public.prudential_assessments a
  JOIN vis ON vis.id = a.entity_id
  WHERE a.status NOT IN ('closed')

  UNION ALL
  SELECT
    'SUPERVISORY_ACTION', p.id, p.entity_id, p.action_reference, p.title,
    CASE WHEN p.review_status = 'awaiting_review' THEN 'SUPERVISORY_REVIEW' ELSE 'ACTION_MONITORING' END,
    p.status, p.assigned_to, lower(p.severity),
    CASE WHEN p.status IN ('overdue','breached') THEN 'Action is past its due date'
         ELSE 'Open supervisory action requiring follow-up' END,
    coalesce(p.response_due_at, (p.due_date + time '23:59')::timestamptz,
             p.created_at + (SELECT make_interval(days => sla_days) FROM cfg WHERE work_item_type = 'SUPERVISORY_ACTION')),
    CASE WHEN p.review_status = 'awaiting_review' THEN 'regulator'
         WHEN p.evidence_required AND p.status IN ('open','in_progress','awaiting_evidence','overdue','breached') THEN 'entity'
         ELSE 'regulator' END,
    p.source_type, p.source_id, p.updated_at,
    jsonb_build_object('action_type', p.action_type, 'due_date', p.due_date,
                       'response_due_at', p.response_due_at, 'evidence_required', p.evidence_required,
                       'review_status', p.review_status, 'progress_percent', p.progress_percent,
                       'breached_at', p.breached_at, 'description', p.description)
  FROM public.prudential_actions p
  JOIN vis ON vis.id = p.entity_id
  WHERE p.status NOT IN ('completed','waived','cancelled')

  UNION ALL
  SELECT
    'ESCALATION', x.id, x.entity_id, 'ESC-' || substr(x.id::text, 1, 8),
    'Escalation · ' || x.escalation_type,
    CASE WHEN x.status = 'open' THEN 'SUPERVISORY_REVIEW' ELSE 'DECISION' END,
    x.status, x.decision_by, coalesce(lower(x.priority), 'high'),
    'Escalated matter awaiting a supervisory decision',
    x.created_at + (SELECT make_interval(days => sla_days) FROM cfg WHERE work_item_type = 'ESCALATION'),
    'regulator', x.related_type, x.related_id, x.updated_at,
    jsonb_build_object('escalation_type', x.escalation_type, 'reason', x.reason,
                       'related_type', x.related_type, 'related_id', x.related_id,
                       'initiated_by', x.created_by, 'raised_at', x.created_at,
                       'decision', x.decision, 'outcome', x.outcome, 'evidence', x.evidence)
  FROM public.prudential_escalations x
  JOIN vis ON vis.id = x.entity_id
  WHERE x.status IN ('open','under_review')

  UNION ALL
  SELECT
    'STRESS_EVENT', s.id, s.entity_id, coalesce(i.taxonomy_code, i.metric_key, 'STRESS'),
    'Stress indicator · ' || coalesce(i.label, i.metric_key, 'indicator'),
    'DETECTION', 'open', NULL::uuid, coalesce(lower(i.severity), 'medium'),
    'Stress indicator triggered by canonical filing facts',
    s.triggered_at + (SELECT make_interval(days => sla_days) FROM cfg WHERE work_item_type = 'STRESS_EVENT'),
    'regulator', 'return_filing', s.return_filing_id, s.triggered_at,
    jsonb_build_object('indicator_label', i.label, 'indicator_code', i.taxonomy_code,
                       'metric_key', i.metric_key,
                       'observed_value', s.observed_value, 'triggered_at', s.triggered_at,
                       'return_filing_id', s.return_filing_id,
                       'return_filing_version_id', s.return_filing_version_id)
  FROM public.prudential_stress_events s
  JOIN vis ON vis.id = s.entity_id
  LEFT JOIN public.prudential_stress_indicators i ON i.id = s.indicator_id
  WHERE s.resolved_at IS NULL

  UNION ALL
  SELECT
    'PLAN_ACTION', pa.id, sp.entity_id, 'PLAN-' || substr(pa.id::text, 1, 8), pa.title,
    'ACTION_MONITORING', pa.status, NULL::uuid,
    CASE WHEN pa.due_date < current_date THEN 'high' ELSE 'medium' END,
    'Supervisory plan commitment',
    (pa.due_date + time '23:59')::timestamptz,
    'regulator', 'supervisory_plan', pa.plan_id, pa.updated_at,
    jsonb_build_object('owner_role', pa.owner_role, 'due_date', pa.due_date,
                       'plan_id', pa.plan_id, 'source', pa.source, 'description', pa.description)
  FROM public.supervisory_plan_actions pa
  JOIN public.supervisory_plans sp ON sp.id = pa.plan_id
  JOIN vis ON vis.id = sp.entity_id
  WHERE pa.status NOT IN ('completed','cancelled')

  UNION ALL
  SELECT
    'EXAMINATION', ex.id, ex.entity_id, ex.reference, ex.title,
    upper(ex.stage), ex.stage, ex.lead_examiner_id,
    coalesce(lower(ex.risk_rating), 'medium'),
    'Active onsite examination',
    ex.created_at + (SELECT make_interval(days => sla_days) FROM cfg WHERE work_item_type = 'EXAMINATION'),
    'regulator', 'examination', ex.id, ex.updated_at,
    jsonb_build_object('examination_type', ex.examination_type, 'stage', ex.stage,
                       'fieldwork_start', ex.fieldwork_start, 'fieldwork_end', ex.fieldwork_end,
                       'period_start', ex.period_under_review_start, 'period_end', ex.period_under_review_end)
  FROM public.examinations ex
  JOIN vis ON vis.id = ex.entity_id
  WHERE ex.closed_at IS NULL AND ex.cancellation_reason IS NULL
    AND public.can_read_examination(auth.uid(), ex.entity_id)
),
enriched AS (
  SELECT
    r.*,
    vis.name AS entity_name,
    vis.sector_id,
    coalesce(r.owner_user_id, asg.supervisor_id) AS eff_owner,
    coalesce(pr.full_name, asg.supervisor_name) AS owner_name,
    asg.team,
    CASE
      WHEN r.sla_due_at IS NULL THEN NULL
      WHEN r.sla_due_at < now() THEN 'breached'
      WHEN r.sla_due_at < now() + make_interval(days => coalesce((SELECT due_soon_days FROM cfg WHERE cfg.work_item_type = r.work_item_type), 3)) THEN 'due_soon'
      ELSE 'on_track'
    END AS sla_state
  FROM raw r
  JOIN vis ON vis.id = r.entity_id
  LEFT JOIN assign asg ON asg.entity_id = r.entity_id
  LEFT JOIN public.profiles pr ON pr.id = r.owner_user_id
),
shaped AS (
  SELECT
    e.work_item_type,
    e.work_item_id,
    e.entity_id,
    e.entity_name,
    e.reference,
    e.title,
    e.stage,
    initcap(replace(lower(e.stage), '_', ' ')) AS stage_label,
    e.status,
    initcap(replace(lower(e.status), '_', ' ')) AS status_label,
    e.eff_owner AS owner_user_id,
    e.owner_name,
    e.team,
    CASE
      WHEN e.sla_state = 'breached' AND e.severity IN ('critical','high') THEN 'critical'
      WHEN e.severity = 'critical' THEN 'critical'
      WHEN e.sla_state = 'breached' OR e.severity = 'high' THEN 'high'
      WHEN e.severity = 'medium' THEN 'medium'
      ELSE 'low' END AS priority,
    CASE WHEN e.sla_state = 'breached' THEN e.priority_reason || ' · SLA breached'
         ELSE e.priority_reason END AS priority_reason,
    e.sla_due_at,
    e.sla_state,
    e.waiting_on,
    e.severity,
    e.sector_id,
    CASE e.work_item_type
      WHEN 'ASSESSMENT' THEN (
        CASE WHEN e.status IN ('draft','returned_for_revision') AND NOT (e.detail->>'has_rationale')::boolean
             THEN jsonb_build_array(jsonb_build_object('code','rationale_required','label','Record the assessment rationale'))
             ELSE '[]'::jsonb END)
      WHEN 'SUPERVISORY_ACTION' THEN (
        CASE WHEN (e.detail->>'evidence_required')::boolean AND e.detail->>'review_status' = 'not_required'
             THEN jsonb_build_array(jsonb_build_object('code','evidence_outstanding','label','Remediation evidence not yet received from the entity'))
             ELSE '[]'::jsonb END)
      ELSE '[]'::jsonb
    END AS blockers,
    CASE e.work_item_type
      WHEN 'BREACH' THEN CASE WHEN e.status = 'unacknowledged' THEN 'acknowledge_breach'
                              WHEN jsonb_array_length(e.detail->'linked_actions') = 0 THEN 'open_supervisory_response'
                              ELSE 'monitor_directive' END
      WHEN 'EWI' THEN CASE WHEN e.status = 'open' THEN 'acknowledge_ewi' ELSE 'review_deterioration' END
      WHEN 'ASSESSMENT' THEN CASE e.status
                               WHEN 'draft' THEN 'complete_assessment'
                               WHEN 'returned_for_revision' THEN 'revise_assessment'
                               WHEN 'submitted' THEN 'review_assessment'
                               WHEN 'reviewed' THEN 'approve_assessment'
                               ELSE 'monitor_assessment_actions' END
      WHEN 'SUPERVISORY_ACTION' THEN CASE WHEN e.detail->>'review_status' = 'awaiting_review' THEN 'review_evidence'
                                          ELSE 'progress_action' END
      WHEN 'ESCALATION' THEN CASE WHEN e.status = 'open' THEN 'take_escalation_decision' ELSE 'record_escalation_outcome' END
      WHEN 'STRESS_EVENT' THEN 'review_stress_event'
      WHEN 'PLAN_ACTION' THEN 'progress_plan_action'
      ELSE 'open_examination_step'
    END AS next_action_code,
    CASE e.work_item_type
      WHEN 'BREACH' THEN CASE WHEN e.status = 'unacknowledged' THEN 'Acknowledge signal'
                              WHEN jsonb_array_length(e.detail->'linked_actions') = 0 THEN 'Open a supervisory response'
                              ELSE 'Monitor existing directive' END
      WHEN 'EWI' THEN CASE WHEN e.status = 'open' THEN 'Acknowledge early warning' ELSE 'Review deterioration' END
      WHEN 'ASSESSMENT' THEN CASE e.status
                               WHEN 'draft' THEN 'Complete and submit assessment'
                               WHEN 'returned_for_revision' THEN 'Revise and resubmit assessment'
                               WHEN 'submitted' THEN 'Review assessment'
                               WHEN 'reviewed' THEN 'Approve assessment'
                               ELSE 'Monitor resulting actions' END
      WHEN 'SUPERVISORY_ACTION' THEN CASE WHEN e.detail->>'review_status' = 'awaiting_review' THEN 'Review submitted evidence'
                                          ELSE 'Progress supervisory action' END
      WHEN 'ESCALATION' THEN CASE WHEN e.status = 'open' THEN 'Take escalation decision' ELSE 'Record escalation outcome' END
      WHEN 'STRESS_EVENT' THEN 'Review stress event'
      WHEN 'PLAN_ACTION' THEN 'Progress plan action'
      ELSE 'Open current examination step'
    END AS next_action_label,
    CASE e.work_item_type
      WHEN 'BREACH' THEN '/supervision/breaches?breach=' || e.work_item_id::text
      WHEN 'EWI' THEN '/supervision/early-warnings?alert=' || e.work_item_id::text
      WHEN 'ASSESSMENT' THEN '/prudential/assessments/' || e.work_item_id::text || '?section=current'
      WHEN 'SUPERVISORY_ACTION' THEN '/prudential/actions?action=' || e.work_item_id::text
      WHEN 'ESCALATION' THEN '/prudential/escalations?escalation=' || e.work_item_id::text
      WHEN 'STRESS_EVENT' THEN '/prudential/stress-indicators?event=' || e.work_item_id::text
      WHEN 'PLAN_ACTION' THEN '/supervision/plans?action=' || e.work_item_id::text
      ELSE '/prudential/examinations/' || e.work_item_id::text || '?section=current'
    END AS next_action_href,
    CASE e.work_item_type
      WHEN 'BREACH' THEN 'prudential_supervision.workflow_action'
      WHEN 'EWI' THEN 'prudential_supervision.workflow_action'
      WHEN 'ASSESSMENT' THEN 'prudential_supervision.workflow_action'
      WHEN 'SUPERVISORY_ACTION' THEN 'prudential_supervision.edit'
      WHEN 'ESCALATION' THEN 'prudential_supervision.workflow_action'
      ELSE 'prudential_supervision.view'
    END AS next_action_permission,
    e.source_type,
    e.source_id,
    e.last_activity_at,
    CASE e.work_item_type
      WHEN 'ASSESSMENT' THEN '/prudential/assessments/' || e.work_item_id::text
      WHEN 'EXAMINATION' THEN '/prudential/examinations/' || e.work_item_id::text
      ELSE '/entities/' || e.entity_id::text || '?view=prudential'
    END AS canonical_href,
    e.detail
  FROM enriched e
),
filtered AS (
  SELECT s.* FROM shaped s
  WHERE (_types IS NULL OR s.work_item_type = ANY (_types))
    AND (_owner IS NULL OR s.owner_user_id = _owner)
    AND (_unassigned IS NOT TRUE OR s.owner_user_id IS NULL)
    AND (_sla IS NULL OR s.sla_state = _sla)
    AND (_severity IS NULL OR s.priority = ANY (_severity))
    AND (_stage IS NULL OR s.stage = _stage)
    AND (_search IS NULL OR _search = '' OR
         s.entity_name ILIKE '%' || _search || '%' OR
         s.title ILIKE '%' || _search || '%' OR
         coalesce(s.reference, '') ILIKE '%' || _search || '%')
)
SELECT
  f.work_item_type, f.work_item_id, f.entity_id, f.entity_name, f.reference, f.title,
  f.stage, f.stage_label, f.status, f.status_label, f.owner_user_id, f.owner_name, f.team,
  f.priority, f.priority_reason, f.sla_due_at, f.sla_state, f.waiting_on,
  jsonb_array_length(f.blockers)::integer AS blocker_count, f.blockers,
  f.next_action_code, f.next_action_label, f.next_action_href, f.next_action_permission,
  f.source_type, f.source_id, f.last_activity_at, f.canonical_href,
  f.detail || jsonb_build_object('severity', f.severity),
  count(*) OVER () AS total_count
FROM filtered f
ORDER BY
  CASE f.priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END,
  CASE f.sla_state WHEN 'breached' THEN 0 WHEN 'due_soon' THEN 1 ELSE 2 END,
  f.sla_due_at NULLS LAST,
  f.last_activity_at DESC,
  f.work_item_type,
  f.work_item_id
LIMIT greatest(coalesce(_limit, 50), 1) OFFSET greatest(coalesce(_offset, 0), 0);
$function$
;
CREATE OR REPLACE FUNCTION public.prudential_work_queue_counts(_types text[] DEFAULT NULL::text[], _entity_id uuid DEFAULT NULL::uuid, _sector_id uuid DEFAULT NULL::uuid, _owner uuid DEFAULT NULL::uuid, _unassigned boolean DEFAULT false, _sla text DEFAULT NULL::text, _severity text[] DEFAULT NULL::text[], _stage text DEFAULT NULL::text, _search text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
WITH q AS MATERIALIZED (
  SELECT * FROM public.prudential_work_queue(
    _types, _entity_id, _sector_id, _owner, _unassigned, _sla, _severity, _stage, _search, 100000, 0)
)
SELECT jsonb_build_object(
  'generated_at', now(),
  'total', (SELECT count(*) FROM q),
  'mine', (SELECT count(*) FROM q WHERE owner_user_id = auth.uid()),
  'unassigned', (SELECT count(*) FROM q WHERE owner_user_id IS NULL),
  'overdue', (SELECT count(*) FROM q WHERE sla_state = 'breached'),
  'due_soon', (SELECT count(*) FROM q WHERE sla_state = 'due_soon'),
  'critical', (SELECT count(*) FROM q WHERE priority = 'critical'),
  'by_type', coalesce((SELECT jsonb_object_agg(work_item_type, n) FROM (
      SELECT work_item_type, count(*) AS n FROM q GROUP BY 1) t), '{}'::jsonb),
  'by_stage', coalesce((SELECT jsonb_object_agg(stage, n) FROM (
      SELECT stage, count(*) AS n FROM q GROUP BY 1) t), '{}'::jsonb),
  'by_priority', coalesce((SELECT jsonb_object_agg(priority, n) FROM (
      SELECT priority, count(*) AS n FROM q GROUP BY 1) t), '{}'::jsonb)
);
$function$
;
CREATE OR REPLACE FUNCTION public.public_entity_register_detail(_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_out jsonb;
BEGIN
  SELECT jsonb_build_object(
    'found', true,
    'slug', l.public_slug,
    'legal_name', COALESCE(o.legal_name, l.name),
    'trading_name', o.display_name,
    'sector', s.name,
    'entity_status', CASE WHEN p.publish_status THEN l.status ELSE NULL END,
    'publication_policy', p.key,
    'publication_policy_label', p.label,
    'licences', CASE WHEN p.publish_licences THEN COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
                 'license_number', lic.license_number,
                 'license_type', lic.license_type,
                 'status', lic.status,
                 'valid_from', lic.valid_from,
                 'valid_until', lic.valid_until,
                 'is_primary', el.is_primary,
                 'conditions', lic.conditions)
               ORDER BY el.is_primary DESC, lic.license_number)
          FROM public.entity_licenses el
          JOIN public.licenses lic ON lic.id = el.license_id
         WHERE el.entity_id = l.id
           AND (el.effective_to IS NULL OR el.effective_to > now())
           AND lower(COALESCE(lic.status,'')) IN ('active','approved','issued','renewed')
      ), '[]'::jsonb) ELSE '[]'::jsonb END,
    'former_names', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('name', sn.snapshot_data->>'legal_name', 'recorded_at', sn.captured_at)
                         ORDER BY sn.captured_at DESC)
          FROM public.entity_identity_snapshots sn
         WHERE sn.entity_id = l.id
           AND COALESCE(sn.snapshot_data->>'legal_name','') <> ''
           AND sn.snapshot_data->>'legal_name' IS DISTINCT FROM COALESCE(o.legal_name, l.name)
      ), '[]'::jsonb),
    'enforcement', CASE WHEN p.publish_enforcement THEN COALESCE((
        SELECT jsonb_agg(jsonb_build_object('enforcement_type', ea.enforcement_type, 'status', ea.status, 'date_opened', ea.date_opened)
                         ORDER BY ea.date_opened DESC)
          FROM public.enforcement_actions ea WHERE ea.entity_id = l.id
      ), '[]'::jsonb) ELSE '[]'::jsonb END
  ) INTO v_out
  FROM public.licensees l
  JOIN public.registry_publication_policies p ON p.id = l.publication_policy_id
  LEFT JOIN public.organizations o ON o.party_id = l.party_id
  LEFT JOIN public.sectors s ON s.id = l.sector_id
  WHERE l.public_slug = _slug
    AND l.merged_into_entity_id IS NULL
    AND p.is_active AND p.publish_entity
    AND (NOT p.requires_authorised_licence OR EXISTS (
          SELECT 1 FROM public.entity_licenses el
          JOIN public.licenses lic ON lic.id = el.license_id
          WHERE el.entity_id = l.id
            AND (el.effective_to IS NULL OR el.effective_to > now())
            AND lower(COALESCE(lic.status,'')) IN ('active','approved','issued','renewed')));

  RETURN COALESCE(v_out, jsonb_build_object('found', false));
END $function$
;
CREATE OR REPLACE FUNCTION public.public_entity_register_search(_criteria jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  q text := btrim(COALESCE(_criteria->>'query',''));
  v_sector uuid := NULLIF(_criteria->>'sector_id','')::uuid;
  lim int := LEAST(COALESCE((_criteria->>'limit')::int, 50), 200);
  off int := GREATEST(COALESCE((_criteria->>'offset')::int, 0), 0);
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(x ORDER BY x->>'legal_name')
    FROM (
      SELECT jsonb_build_object(
        'slug', l.public_slug,
        'legal_name', COALESCE(o.legal_name, l.name),
        'trading_name', o.display_name,
        'sector', s.name,
        'entity_status', CASE WHEN p.publish_status THEN l.status ELSE NULL END,
        'licence_count', (
          SELECT count(*) FROM public.entity_licenses el WHERE el.entity_id = l.id
            AND (el.effective_to IS NULL OR el.effective_to > now())),
        'licences', CASE WHEN p.publish_licences THEN COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
                   'license_number', lic.license_number,
                   'license_type', lic.license_type,
                   'status', lic.status,
                   'valid_from', lic.valid_from,
                   'valid_until', lic.valid_until,
                   'is_primary', el.is_primary)
                 ORDER BY el.is_primary DESC, lic.license_number)
            FROM public.entity_licenses el
            JOIN public.licenses lic ON lic.id = el.license_id
           WHERE el.entity_id = l.id
             AND (el.effective_to IS NULL OR el.effective_to > now())
             AND lower(COALESCE(lic.status,'')) IN ('active','approved','issued','renewed')
        ), '[]'::jsonb) ELSE '[]'::jsonb END,
        'publication_policy', p.key
      ) AS x
      FROM public.licensees l
      JOIN public.registry_publication_policies p ON p.id = l.publication_policy_id
      LEFT JOIN public.organizations o ON o.party_id = l.party_id
      LEFT JOIN public.sectors s ON s.id = l.sector_id
      WHERE l.merged_into_entity_id IS NULL
        AND p.is_active AND p.publish_entity
        AND (NOT p.requires_authorised_licence OR EXISTS (
              SELECT 1 FROM public.entity_licenses el
              JOIN public.licenses lic ON lic.id = el.license_id
              WHERE el.entity_id = l.id
                AND (el.effective_to IS NULL OR el.effective_to > now())
                AND lower(COALESCE(lic.status,'')) IN ('active','approved','issued','renewed')))
        AND (v_sector IS NULL OR l.sector_id = v_sector)
        AND (q = '' OR COALESCE(o.legal_name, l.name) ILIKE '%'||q||'%' OR COALESCE(o.display_name,'') ILIKE '%'||q||'%')
      ORDER BY COALESCE(o.legal_name, l.name)
      LIMIT lim OFFSET off
    ) t
  ), '[]'::jsonb);
END $function$
;
CREATE OR REPLACE FUNCTION public.publish_form_version(_version_id uuid, _effective_from timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_version record; v_missing int;
BEGIN
  PERFORM public.wb_require('form_management','publish');
  SELECT * INTO v_version FROM public.form_versions WHERE id = _version_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Form version not found'; END IF;
  IF v_version.status = 'published' THEN
    RETURN jsonb_build_object('success',true,'idempotent',true,'version_id',_version_id);
  END IF;

  -- 9. calculation integrity: every referenced logical field must exist in this version
  SELECT count(*) INTO v_missing FROM public.form_fields f
   WHERE f.version_id = _version_id
     AND COALESCE(f.calculated_expression,'') <> ''
     AND EXISTS (
       SELECT 1 FROM regexp_matches(f.calculated_expression, '[A-Za-z_][A-Za-z0-9_]*', 'g') AS t(tok)
        WHERE tok[1] NOT IN ('and','or','not','if','then','else','sum','abs','min','max','round')
          AND NOT EXISTS (SELECT 1 FROM public.form_fields g
                           WHERE g.version_id = _version_id AND g.field_name = tok[1]));
  IF v_missing > 0 THEN
    RAISE EXCEPTION 'Cannot publish: % calculated field(s) reference unknown fields', v_missing;
  END IF;

  PERFORM set_config('app.form_publish_context','trusted', true);
  UPDATE public.form_versions
     SET status = 'published', published_at = now(), effective_from = COALESCE(_effective_from, now())
   WHERE id = _version_id;
  UPDATE public.form_versions SET status = 'archived'
   WHERE template_id = v_version.template_id AND id <> _version_id AND status = 'published';
  UPDATE public.form_templates SET status = 'published', updated_at = now() WHERE id = v_version.template_id;
  UPDATE public.form_field_definitions d SET is_published = true
   WHERE d.template_id = v_version.template_id
     AND EXISTS (SELECT 1 FROM public.form_fields f WHERE f.version_id = _version_id AND f.form_field_definition_id = d.id);

  PERFORM public.create_audit_log(auth.uid(),'form.version.published','form_version',_version_id::text,NULL,
    jsonb_build_object('template_id',v_version.template_id,'version',v_version.version),NULL);
  RETURN jsonb_build_object('success',true,'version_id',_version_id,'version',v_version.version);
END $function$
;
CREATE OR REPLACE FUNCTION public.publish_prudential_ratio(_ratio_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _next integer; _row public.prudential_ratios;
BEGIN
  IF NOT public.can_manage_prudential_config(auth.uid()) THEN
    RAISE EXCEPTION 'You do not have permission to manage prudential configuration';
  END IF;
  PERFORM set_config('app.version_maintenance','on',true);
  SELECT COALESCE(MAX(version),0)+1 INTO _next FROM public.prudential_ratio_versions WHERE ratio_id = _ratio_id;
  SELECT * INTO _row FROM public.prudential_ratios WHERE id = _ratio_id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Ratio not found'; END IF;
  INSERT INTO public.prudential_ratio_versions(ratio_id, version, formula, display_format, published_by)
    VALUES (_ratio_id, _next, _row.formula, _row.display_format, auth.uid());
  UPDATE public.prudential_ratios SET current_version = _next, updated_at = now() WHERE id = _ratio_id;
  PERFORM public.log_compliance_audit('UPDATE','prudential_ratios', _ratio_id::text, NULL, to_jsonb(_row), 'Ratio published', NULL, NULL, jsonb_build_object('version',_next,'event','RATIO_PUBLISHED'));
  RETURN _next;
END $function$
;
CREATE OR REPLACE FUNCTION public.publish_prudential_threshold(_threshold_id uuid, _effective_from date DEFAULT CURRENT_DATE)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _next integer; _row public.prudential_thresholds;
BEGIN
  IF NOT public.can_manage_prudential_config(auth.uid()) THEN RAISE EXCEPTION 'Not authorised to manage prudential configuration'; END IF;
  PERFORM set_config('app.version_maintenance','on',true);
  UPDATE public.prudential_threshold_versions SET effective_to = _effective_from - 1
    WHERE threshold_id = _threshold_id AND effective_to IS NULL;
  SELECT COALESCE(MAX(version),0)+1 INTO _next FROM public.prudential_threshold_versions WHERE threshold_id = _threshold_id;
  SELECT * INTO _row FROM public.prudential_thresholds WHERE id = _threshold_id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Threshold not found'; END IF;
  INSERT INTO public.prudential_threshold_versions(threshold_id, version, warn_value, breach_value, upper_value, comparator, unit, effective_from, published_by)
    VALUES (_threshold_id, _next, _row.warn_value, _row.breach_value, _row.upper_value, _row.comparator, _row.unit, _effective_from, auth.uid());
  UPDATE public.prudential_thresholds SET current_version = _next, effective_from = _effective_from, updated_at = now() WHERE id = _threshold_id;
  PERFORM set_config('app.version_maintenance','off',true);
  PERFORM public.log_compliance_audit('UPDATE','prudential_thresholds', _threshold_id::text, NULL, to_jsonb(_row), 'Threshold published', NULL, NULL, jsonb_build_object('version',_next,'event','THRESHOLD_PUBLISHED'));
  RETURN _next;
END $function$
;
CREATE OR REPLACE FUNCTION public.publish_validation_rule(_rule_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _next integer; _def jsonb;
BEGIN
  IF NOT public.can_manage_returns_config(auth.uid()) THEN
    RAISE EXCEPTION 'You do not have permission to manage returns configuration';
  END IF;
  PERFORM set_config('app.version_maintenance','on',true);
  UPDATE public.return_validation_rule_versions SET is_current = false WHERE rule_id = _rule_id AND is_current;
  SELECT COALESCE(MAX(version),0)+1 INTO _next FROM public.return_validation_rule_versions WHERE rule_id = _rule_id;
  SELECT to_jsonb(r.*) INTO _def FROM public.return_validation_rules r WHERE r.id = _rule_id;
  IF _def IS NULL THEN RAISE EXCEPTION 'Rule not found'; END IF;
  INSERT INTO public.return_validation_rule_versions(rule_id, version, definition, published_by, is_current)
    VALUES (_rule_id, _next, _def, auth.uid(), true);
  UPDATE public.return_validation_rules SET current_version = _next, updated_at = now() WHERE id = _rule_id;
  PERFORM public.log_compliance_audit('UPDATE','return_validation_rules', _rule_id::text, NULL, _def, 'Rule published', NULL, NULL, jsonb_build_object('version',_next,'event','RULE_PUBLISHED'));
  RETURN _next;
END $function$
;
CREATE OR REPLACE FUNCTION public.publish_workflow_version(_workflow_id uuid, _notes text DEFAULT NULL::text)
 RETURNS approval_workflow_versions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _next_num integer;
  _snapshot jsonb;
  _row public.approval_workflow_versions;
BEGIN
  IF NOT (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(), 'workflow_management', 'publish')) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(MAX(version_number),0) + 1 INTO _next_num
    FROM public.approval_workflow_versions WHERE workflow_id = _workflow_id;

  _snapshot := public.build_workflow_snapshot(_workflow_id);

  INSERT INTO public.approval_workflow_versions
    (workflow_id, version_number, status, snapshot, notes, created_by, published_at)
  VALUES
    (_workflow_id, _next_num, 'published', _snapshot, _notes, auth.uid(), now())
  RETURNING * INTO _row;

  UPDATE public.approval_workflows
     SET current_published_version_id = _row.id,
         draft_version_id = NULL,
         updated_at = now()
   WHERE id = _workflow_id;

  RETURN _row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.purge_expired_audit_exports()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  WITH del AS (
    DELETE FROM public.audit_export_jobs
    WHERE retention_expires_at IS NOT NULL AND retention_expires_at < now()
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM del;
  RETURN COALESCE(v_count, 0);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.rbac_delete_role(_role_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  target public.roles;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;
  IF NOT (public.is_super_admin(uid) OR public.has_permission(uid,'role_management','delete')) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO target FROM public.roles WHERE id = _role_id FOR UPDATE;
  IF target.id IS NULL THEN
    RAISE EXCEPTION 'role_not_found' USING ERRCODE = '02000';
  END IF;
  IF COALESCE(target.is_system, false) THEN
    RAISE EXCEPTION 'system_role_not_deletable' USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.role_permissions WHERE role_id = _role_id;
  DELETE FROM public.user_dynamic_roles WHERE role_id = _role_id;
  DELETE FROM public.roles WHERE id = _role_id;
  RETURN jsonb_build_object('deleted', _role_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.rbac_reclassify_roles()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE updated int := 0;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Only fill missing metadata; never overwrite operator input.
  UPDATE public.roles r
     SET role_category = COALESCE(r.role_category,
           CASE
             WHEN r.is_system OR r.system_role NOT IN ('custom','') THEN 'system'
             ELSE 'operational'
           END),
         access_summary = CASE
           WHEN r.access_summary IS NULL OR r.access_summary = '{}'::jsonb
             THEN jsonb_build_object('auto_backfilled', true)
           ELSE r.access_summary END,
         status = COALESCE(NULLIF(r.status,''), 'active'),
         updated_at = now()
   WHERE (r.role_category IS NULL
       OR r.access_summary IS NULL OR r.access_summary = '{}'::jsonb
       OR r.status IS NULL OR r.status = '');
  GET DIAGNOSTICS updated = ROW_COUNT;
  RETURN jsonb_build_object('updated', updated);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.rbac_save_role(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  is_admin boolean;
  target_id uuid;
  new_name text := NULLIF(trim(_payload ->> 'name'), '');
  perm_ids uuid[];
  scope_cfg jsonb := COALESCE(_payload -> 'scope_config', '{}'::jsonb);
  m text; s text; missing_module text;
  scopeless_mod text;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;
  is_admin := public.is_super_admin(uid) OR public.has_permission(uid,'role_management','edit');
  IF NOT is_admin THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;
  IF new_name IS NULL THEN RAISE EXCEPTION 'role_name_required' USING ERRCODE = '22023'; END IF;

  FOR m, s IN SELECT k, COALESCE(v ->> 'scope','all') FROM jsonb_each(scope_cfg) AS x(k,v) LOOP
    IF NOT EXISTS (SELECT 1 FROM public.rbac_module_scopes WHERE module = m AND scope = s) THEN
      RAISE EXCEPTION 'invalid_scope: module=%, scope=%', m, s USING ERRCODE = '22023';
    END IF;
  END LOOP;

  perm_ids := ARRAY(SELECT DISTINCT jsonb_array_elements_text(COALESCE(_payload -> 'permission_ids','[]'::jsonb))::uuid);

  IF EXISTS (
    SELECT 1 FROM public.permissions p
    WHERE p.id = ANY(perm_ids) AND lower(p.name) <> 'view'
      AND NOT EXISTS (
        SELECT 1 FROM public.permissions v
        WHERE v.id = ANY(perm_ids) AND lower(v.name) = 'view'
          AND lower(regexp_replace(v.module,'\s+','_','g')) = lower(regexp_replace(p.module,'\s+','_','g'))
      )
  ) THEN
    RAISE EXCEPTION 'permission_dependency_violation: action selected without view on its module'
      USING ERRCODE = '22023';
  END IF;

  -- Auto-inject {"scope":"all"} for scopeless modules (only 'all' registered)
  -- so the UI (which hides scopeless modules) doesn't have to send them.
  FOR scopeless_mod IN
    SELECT DISTINCT lower(regexp_replace(p.module,'\s+','_','g')) AS mkey
    FROM public.permissions p
    WHERE p.id = ANY(perm_ids)
      AND NOT (scope_cfg ? lower(regexp_replace(p.module,'\s+','_','g')))
      AND EXISTS (
        SELECT 1 FROM public.rbac_module_scopes s
        WHERE s.module = lower(regexp_replace(p.module,'\s+','_','g'))
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.rbac_module_scopes s
        WHERE s.module = lower(regexp_replace(p.module,'\s+','_','g'))
          AND s.scope <> 'all'
      )
  LOOP
    scope_cfg := scope_cfg || jsonb_build_object(scopeless_mod, jsonb_build_object('scope','all'));
  END LOOP;

  SELECT lower(regexp_replace(p.module,'\s+','_','g')) INTO missing_module
  FROM public.permissions p
  JOIN public.rbac_module_scopes s ON s.module = lower(regexp_replace(p.module,'\s+','_','g'))
  WHERE p.id = ANY(perm_ids)
    AND NOT (scope_cfg ? lower(regexp_replace(p.module,'\s+','_','g')))
  LIMIT 1;
  IF missing_module IS NOT NULL THEN
    RAISE EXCEPTION 'scope_required_for_module: %', missing_module USING ERRCODE = '22023';
  END IF;

  target_id := NULLIF(_payload ->> 'id', '')::uuid;
  IF target_id IS NULL THEN
    INSERT INTO public.roles (
      name, description, system_role, is_system,
      role_type, dashboard_tier, role_category, status,
      access_summary, scope_config
    ) VALUES (
      new_name,
      NULLIF(_payload ->> 'description',''),
      COALESCE(NULLIF(_payload ->> 'system_role',''), 'custom'),
      false,
      COALESCE(NULLIF(_payload ->> 'role_type',''), 'custom'),
      COALESCE(NULLIF(_payload ->> 'dashboard_tier',''), 'operational'),
      NULLIF(_payload ->> 'role_category',''),
      COALESCE(NULLIF(_payload ->> 'status',''), 'active'),
      COALESCE(_payload -> 'access_summary', '{}'::jsonb),
      scope_cfg
    ) RETURNING id INTO target_id;
  ELSE
    UPDATE public.roles SET
      name = new_name,
      description = NULLIF(_payload ->> 'description',''),
      role_type = COALESCE(NULLIF(_payload ->> 'role_type',''), role_type),
      dashboard_tier = COALESCE(NULLIF(_payload ->> 'dashboard_tier',''), dashboard_tier),
      role_category = NULLIF(_payload ->> 'role_category',''),
      status = COALESCE(NULLIF(_payload ->> 'status',''), status),
      access_summary = COALESCE(_payload -> 'access_summary', access_summary),
      scope_config = scope_cfg,
      updated_at = now()
    WHERE id = target_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'role_not_found' USING ERRCODE = 'P0002'; END IF;
  END IF;

  -- Apply a dependency-safe permission delta instead of deleting everything.
  -- Deleting all rows first can attempt to remove `view` while old dependent
  -- rows still exist, which correctly trips the retention trigger even when
  -- the submitted final set still includes `view`.
  DELETE FROM public.role_permissions rp
  USING public.permissions p
  WHERE rp.permission_id = p.id
    AND rp.role_id = target_id
    AND NOT (rp.permission_id = ANY(perm_ids))
    AND lower(p.name) <> 'view';

  DELETE FROM public.role_permissions rp
  USING public.permissions p
  WHERE rp.permission_id = p.id
    AND rp.role_id = target_id
    AND NOT (rp.permission_id = ANY(perm_ids))
    AND lower(p.name) = 'view';

  IF array_length(perm_ids, 1) > 0 THEN
    INSERT INTO public.role_permissions (role_id, permission_id)
    SELECT target_id, p.id
    FROM public.permissions p
    WHERE p.id = ANY(perm_ids)
      AND lower(p.name) = 'view'
      AND NOT EXISTS (
        SELECT 1 FROM public.role_permissions rp
        WHERE rp.role_id = target_id AND rp.permission_id = p.id
      )
    ON CONFLICT DO NOTHING;

    INSERT INTO public.role_permissions (role_id, permission_id)
    SELECT target_id, p.id
    FROM public.permissions p
    WHERE p.id = ANY(perm_ids)
      AND lower(p.name) <> 'view'
      AND NOT EXISTS (
        SELECT 1 FROM public.role_permissions rp
        WHERE rp.role_id = target_id AND rp.permission_id = p.id
      )
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN jsonb_build_object('id', target_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.rdm_assert_single_active_default()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count integer;
BEGIN
  EXECUTE format('SELECT count(*) FROM public.%I WHERE is_default AND is_active', TG_TABLE_NAME) INTO v_count;
  IF v_count <> 1 THEN
    RAISE EXCEPTION
      'Table % must have exactly one active default policy (found %). Promote another active policy in the same transaction.',
      TG_TABLE_NAME, v_count USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_audit_metadata_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id text; v_action text; v_old jsonb; v_new jsonb;
BEGIN
  v_old := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END;
  v_new := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END;
  v_id := COALESCE((to_jsonb(COALESCE(NEW, OLD)) ->> 'id'), '');
  v_action := CASE
    WHEN TG_OP = 'INSERT' THEN 'regulatory_data.metadata.created'
    WHEN TG_OP = 'DELETE' THEN 'regulatory_data.metadata.deleted'
    WHEN COALESCE((v_old ->> 'is_active')::boolean, true) AND NOT COALESCE((v_new ->> 'is_active')::boolean, true)
      THEN 'regulatory_data.metadata.retired'
    WHEN NOT COALESCE((v_old ->> 'is_active')::boolean, true) AND COALESCE((v_new ->> 'is_active')::boolean, true)
      THEN 'regulatory_data.metadata.reinstated'
    ELSE 'regulatory_data.metadata.updated'
  END;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value, metadata)
  VALUES (auth.uid(), v_action, TG_TABLE_NAME, v_id, v_old, v_new,
    jsonb_build_object('program','RDM-ENTITY-001','phase','1.1','table',TG_TABLE_NAME));
  RETURN COALESCE(NEW, OLD);
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_backfill_application_requirements(_application_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_created integer := 0;
  v_with_evidence integer := 0;
  v_unknown integer := 0;
BEGIN
  v_uid := public.rdm_require('form_management', 'edit');

  WITH candidates AS (
    SELECT a.id AS application_id
    FROM public.applications a
    WHERE a.status <> 'draft'
      AND (_application_id IS NULL OR a.id = _application_id)
      AND NOT EXISTS (SELECT 1 FROM public.application_form_requirements r WHERE r.application_id = a.id)
  ), evidence AS (
    SELECT c.application_id, v.template_id, v.version_id, 'application_form_versions'::text AS source
    FROM candidates c
    JOIN public.application_form_versions v ON v.application_id = c.application_id
    WHERE v.version_id IS NOT NULL AND v.template_id IS NOT NULL
    UNION
    SELECT c.application_id, fr.template_id, fr.version_id, 'form_responses'::text
    FROM candidates c
    JOIN public.form_responses fr ON fr.entity_id = c.application_id
    WHERE fr.version_id IS NOT NULL AND fr.template_id IS NOT NULL
  ), ins AS (
    INSERT INTO public.application_form_requirements
      (application_id, template_id, form_version_id, is_required, status, pinned_at)
    SELECT DISTINCT ON (e.application_id, e.template_id)
           e.application_id, e.template_id, e.version_id, true, 'MIGRATED_WITH_EVIDENCE', now()
    FROM evidence e
    ORDER BY e.application_id, e.template_id, e.source
    ON CONFLICT (application_id, template_id) DO NOTHING
    RETURNING application_id
  )
  SELECT count(*) INTO v_created FROM ins;

  INSERT INTO public.application_requirement_migration_status
    (application_id, classification, evidence, requirements_created, decided_by)
  SELECT a.id,
         CASE WHEN EXISTS (SELECT 1 FROM public.application_form_requirements r
                            WHERE r.application_id = a.id AND r.status = 'MIGRATED_WITH_EVIDENCE')
              THEN 'MIGRATED_WITH_EVIDENCE' ELSE 'LEGACY_REQUIREMENTS_UNKNOWN' END,
         jsonb_build_object(
           'application_form_versions', (SELECT count(*) FROM public.application_form_versions v WHERE v.application_id = a.id AND v.version_id IS NOT NULL),
           'form_responses', (SELECT count(*) FROM public.form_responses fr WHERE fr.entity_id = a.id AND fr.version_id IS NOT NULL)),
         (SELECT count(*) FROM public.application_form_requirements r WHERE r.application_id = a.id AND r.status = 'MIGRATED_WITH_EVIDENCE'),
         v_uid
  FROM public.applications a
  WHERE a.status <> 'draft'
    AND (_application_id IS NULL OR a.id = _application_id)
  ON CONFLICT (application_id) DO UPDATE
    SET classification = EXCLUDED.classification,
        evidence = EXCLUDED.evidence,
        requirements_created = EXCLUDED.requirements_created,
        decided_by = EXCLUDED.decided_by,
        decided_at = now();

  SELECT count(*) FILTER (WHERE classification = 'MIGRATED_WITH_EVIDENCE'),
         count(*) FILTER (WHERE classification = 'LEGACY_REQUIREMENTS_UNKNOWN')
    INTO v_with_evidence, v_unknown
  FROM public.application_requirement_migration_status;

  INSERT INTO public.rdm_migration_decisions
    (target_type, target_id, decision, canonical_value, reason, affected_rows, decided_by)
  VALUES ('application_requirements_backfill', _application_id, 'EXACTLY_MAPPED',
          jsonb_build_object('requirements_created', v_created,
                             'migrated_with_evidence', v_with_evidence,
                             'legacy_unknown', v_unknown),
          'Evidence-only reconstruction from stored form_version_id references', v_created, v_uid);

  RETURN jsonb_build_object('requirements_created', v_created,
                            'migrated_with_evidence', v_with_evidence,
                            'legacy_requirements_unknown', v_unknown);
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_backfill_field_definitions(_template_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_created integer := 0;
  v_linked integer := 0;
BEGIN
  v_uid := public.rdm_require('form_management', 'edit');
  PERFORM set_config('app.form_publish_context', 'trusted', true);

  INSERT INTO public.form_field_definitions (template_id, field_key, label_hint, is_published, is_active)
  SELECT DISTINCT ON (v.template_id, f.field_name)
         v.template_id, f.field_name, f.label,
         EXISTS (SELECT 1 FROM public.form_versions v2 WHERE v2.template_id = v.template_id AND v2.status = 'published'),
         true
  FROM public.form_fields f
  JOIN public.form_versions v ON v.id = f.version_id
  WHERE COALESCE(f.field_name, '') <> ''
    AND (_template_id IS NULL OR v.template_id = _template_id)
    AND NOT EXISTS (
      SELECT 1 FROM public.form_field_definitions d
      WHERE d.template_id = v.template_id AND d.field_key = f.field_name)
  ORDER BY v.template_id, f.field_name, f.created_at;
  GET DIAGNOSTICS v_created = ROW_COUNT;

  UPDATE public.form_fields f
     SET form_field_definition_id = d.id
  FROM public.form_versions v, public.form_field_definitions d
  WHERE v.id = f.version_id
    AND d.template_id = v.template_id
    AND d.field_key = f.field_name
    AND f.form_field_definition_id IS NULL
    AND (_template_id IS NULL OR v.template_id = _template_id);
  GET DIAGNOSTICS v_linked = ROW_COUNT;

  INSERT INTO public.rdm_migration_decisions
    (target_type, target_id, decision, canonical_value, reason, affected_rows, decided_by)
  VALUES ('form_field_backfill', _template_id, 'EXACTLY_MAPPED',
          jsonb_build_object('definitions_created', v_created, 'fields_linked', v_linked),
          'Deterministic backfill: template + field_name identity', v_created + v_linked, v_uid);

  RETURN jsonb_build_object('definitions_created', v_created, 'fields_linked', v_linked);
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_can_read()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT auth.uid() IS NOT NULL AND public.sec_has_permission(auth.uid(), 'settings', 'view')
$function$
;
CREATE OR REPLACE FUNCTION public.rdm_can_write()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT auth.uid() IS NOT NULL AND public.sec_has_permission(auth.uid(), 'settings', 'edit')
$function$
;
CREATE OR REPLACE FUNCTION public.rdm_delete_metadata(_table text, _id uuid, _promote_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_is_system boolean; v_refs integer := 0; v_was_default boolean;
BEGIN
  IF NOT public.rdm_can_write() THEN
    RAISE EXCEPTION 'Not authorised to change regulatory data model configuration' USING ERRCODE = '42501';
  END IF;
  IF NOT (_table = ANY (public.rdm_metadata_tables())) THEN
    RAISE EXCEPTION 'Unknown regulatory metadata table: %', _table USING ERRCODE = '22023';
  END IF;
  EXECUTE format('SELECT is_system FROM public.%I WHERE id = $1', _table) INTO v_is_system USING _id;
  IF v_is_system IS NULL THEN
    RAISE EXCEPTION 'Regulatory metadata row % not found', _id USING ERRCODE = 'P0002';
  END IF;
  IF v_is_system THEN
    RAISE EXCEPTION 'System regulatory metadata cannot be deleted. Retire it instead.' USING ERRCODE = '42501';
  END IF;
  IF _table = 'classification_schemes' THEN
    SELECT count(*) INTO v_refs FROM public.classification_values WHERE scheme_id = _id;
  ELSIF _table = 'classification_values' THEN
    SELECT count(*) INTO v_refs FROM public.classification_values WHERE parent_id = _id;
  ELSIF _table = 'relationship_types' THEN
    SELECT count(*) INTO v_refs FROM public.relationship_types WHERE inverse_relationship_type_id = _id;
  END IF;
  IF v_refs > 0 THEN
    RAISE EXCEPTION 'Referenced regulatory metadata cannot be deleted (% dependent rows). Retire it instead.', v_refs USING ERRCODE = '42501';
  END IF;

  IF _table IN ('entity_resolution_policies','entity_registry_failure_policies') THEN
    EXECUTE format('SELECT is_default AND is_active FROM public.%I WHERE id = $1', _table) INTO v_was_default USING _id;
    IF COALESCE(v_was_default, false) AND _promote_id IS NULL THEN
      RAISE EXCEPTION
        'This is the active default policy in %. Select another active policy to promote before deleting it.', _table
        USING ERRCODE = '23514';
    END IF;
  END IF;

  EXECUTE format('DELETE FROM public.%I WHERE id = $1', _table) USING _id;

  IF COALESCE(v_was_default, false) THEN
    PERFORM public.rdm_promote_default_policy(_table, _promote_id);
  END IF;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_diag_duplicate_entities()
 RETURNS TABLE(normalised_name text, entity_count bigint, entity_ids uuid[], entity_names text[], statuses text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.rdm_can_read() THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT lower(trim(l.name)),
         count(*),
         array_agg(l.id ORDER BY l.created_at),
         array_agg(l.name ORDER BY l.created_at),
         array_agg(l.status ORDER BY l.created_at)
  FROM public.licensees l
  GROUP BY 1
  HAVING count(*) > 1
  ORDER BY 2 DESC, 1;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_diag_duplicate_organizations()
 RETURNS TABLE(normalised_name text, org_count integer, party_ids uuid[], legal_names text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.rdm_can_read() THEN
    RAISE EXCEPTION 'permission denied: settings.view' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT lower(btrim(o.legal_name))::text,
         count(*)::int,
         array_agg(o.party_id ORDER BY o.party_id),
         array_agg(o.legal_name ORDER BY o.party_id)
  FROM public.organizations o
  GROUP BY 1
  HAVING count(*) > 1
  ORDER BY 2 DESC, 1;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_entity_foundation_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT public.rdm_can_read() THEN
    RAISE EXCEPTION 'permission denied: settings.view' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'generated_at', now(),
    'parties_total', (SELECT count(*) FROM public.parties),
    'organization_parties', (SELECT count(*) FROM public.parties WHERE party_kind = 'ORGANIZATION'),
    'person_parties', (SELECT count(*) FROM public.parties WHERE party_kind = 'PERSON'),
    'regulated_entities_total', (SELECT count(*) FROM public.licensees),
    'entities_without_party_binding', (SELECT count(*) FROM public.licensees WHERE party_id IS NULL),
    'organization_parties_without_entity',
      (SELECT count(*) FROM public.organizations o
        WHERE NOT EXISTS (SELECT 1 FROM public.licensees e WHERE e.party_id = o.party_id)),
    'duplicate_organization_candidates',
      (SELECT count(*) FROM (
         SELECT lower(btrim(legal_name)) FROM public.organizations
         GROUP BY 1 HAVING count(*) > 1) d),
    'entities_without_lifecycle_stage', (SELECT count(*) FROM public.licensees WHERE lifecycle_stage_id IS NULL),
    'entities_without_identity_status', (SELECT count(*) FROM public.licensees WHERE identity_status_id IS NULL),
    'entity_licenses_rows', (SELECT count(*) FROM public.entity_licenses),
    'entities_with_zero_licenses',
      (SELECT count(*) FROM public.licensees e
        WHERE NOT EXISTS (SELECT 1 FROM public.entity_licenses el WHERE el.entity_id = e.id)),
    'entities_with_one_license',
      (SELECT count(*) FROM (SELECT entity_id FROM public.entity_licenses GROUP BY 1 HAVING count(*) = 1) x),
    'entities_with_multiple_licenses',
      (SELECT count(*) FROM (SELECT entity_id FROM public.entity_licenses GROUP BY 1 HAVING count(*) > 1) x),
    'licenses_without_entity_relationship',
      (SELECT count(*) FROM public.licenses l
        WHERE NOT EXISTS (SELECT 1 FROM public.entity_licenses el WHERE el.license_id = l.id)),
    'legacy_license_links_not_represented',
      (SELECT count(*) FROM public.licensees e
        WHERE e.license_id IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM public.entity_licenses el
                          WHERE el.entity_id = e.id AND el.license_id = e.license_id)),
    'identifiers_total', (SELECT count(*) FROM public.entity_identifiers),
    'identifiers_by_type',
      COALESCE((SELECT jsonb_object_agg(t.key, c.n) FROM (
          SELECT identifier_type_id, count(*) n FROM public.entity_identifiers GROUP BY 1) c
        JOIN public.entity_identifier_types t ON t.id = c.identifier_type_id), '{}'::jsonb),
    'identifier_scope_conflicts',
      (SELECT count(*) FROM (
         SELECT identifier_type_id, uniqueness_scope, jurisdiction_id, issuer_key, regulator_id, normalized_value
         FROM public.entity_identifiers
         WHERE effective_to IS NULL AND uniqueness_scope <> 'NONE'
         GROUP BY 1,2,3,4,5,6 HAVING count(DISTINCT entity_id) > 1) c),
    'identifiers_missing_required_scope',
      (SELECT count(*) FROM public.entity_identifiers
        WHERE (uniqueness_scope = 'JURISDICTION' AND jurisdiction_id IS NULL)
           OR (uniqueness_scope = 'ISSUER' AND NULLIF(btrim(COALESCE(issuer_key,'')),'') IS NULL)
           OR (uniqueness_scope = 'REGULATOR' AND regulator_id IS NULL)),
    'licenses_without_regulator_scope_identifier',
      (SELECT count(*) FROM public.licenses WHERE regulator_id IS NULL),
    'applications_total', (SELECT count(*) FROM public.applications),
    'applications_mapped_to_entity', (SELECT count(*) FROM public.applications WHERE entity_id IS NOT NULL),
    'applications_ambiguous_entity_mapping', (SELECT count(*) FROM public.applications WHERE entity_id IS NULL),
    'applications_without_pinned_form_version',
      (SELECT count(*) FROM public.applications WHERE form_version_id IS NULL)
  ) INTO v;

  RETURN v;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_entity_registry_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT public.rdm_can_read() THEN
    RAISE EXCEPTION 'permission denied: settings.view' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'generated_at', now(),
    'bindings_total', (SELECT count(*) FROM public.entity_registry_bindings),
    'bindings_active', (SELECT count(*) FROM public.entity_registry_bindings WHERE is_active AND effective_to IS NULL),
    'bindings_external_authoritative', (SELECT count(*) FROM public.entity_registry_bindings WHERE authority_mode = 'EXTERNAL_AUTHORITATIVE'),
    'bindings_hybrid_authority', (SELECT count(*) FROM public.entity_registry_bindings WHERE authority_mode = 'HYBRID_AUTHORITY'),
    'bindings_local_authoritative', (SELECT count(*) FROM public.entity_registry_bindings WHERE authority_mode = 'LOCAL_AUTHORITATIVE'),
    'integration_connections_available', (SELECT count(*) FROM public.integration_connections),
    'entities_with_external_reference',
      (SELECT count(DISTINCT entity_id) FROM public.entity_external_references WHERE effective_to IS NULL),
    'entities_with_multiple_external_references',
      (SELECT count(*) FROM (
         SELECT entity_id FROM public.entity_external_references
          WHERE effective_to IS NULL GROUP BY 1 HAVING count(*) > 1) x),
    'duplicate_external_ids_within_binding',
      (SELECT count(*) FROM (
         SELECT entity_registry_binding_id, external_entity_id
           FROM public.entity_external_references WHERE effective_to IS NULL
          GROUP BY 1,2 HAVING count(DISTINCT entity_id) > 1) x),
    'external_references_unverified',
      (SELECT count(*) FROM public.entity_external_references
        WHERE effective_to IS NULL AND verification_status <> 'VERIFIED'),
    'external_references_stale',
      (SELECT count(*) FROM public.entity_external_references
        WHERE effective_to IS NULL
          AND (last_verified_at IS NULL OR last_verified_at < now() - interval '30 days')),
    'authority_rules_total', (SELECT count(*) FROM public.entity_data_authority_rules),
    'authority_rules_by_domain',
      COALESCE((SELECT jsonb_object_agg(d.key, c.n) FROM (
          SELECT data_domain_id, count(*) n FROM public.entity_data_authority_rules
           WHERE is_active AND effective_to IS NULL GROUP BY 1) c
        JOIN public.data_domains d ON d.id = c.data_domain_id), '{}'::jsonb),
    'identity_snapshots_total', (SELECT count(*) FROM public.entity_identity_snapshots),
    'identity_snapshots_last_captured_at', (SELECT max(captured_at) FROM public.entity_identity_snapshots),
    'sync_states_total', (SELECT count(*) FROM public.entity_registry_sync_states),
    'sync_status_counts',
      COALESCE((SELECT jsonb_object_agg(sync_status, n) FROM (
          SELECT sync_status, count(*) n FROM public.entity_registry_sync_states GROUP BY 1) s), '{}'::jsonb),
    'last_successful_sync_at', (SELECT max(last_success_at) FROM public.entity_registry_sync_states),
    'sync_conflicts_total', (SELECT count(*) FROM public.entity_sync_conflicts),
    'sync_conflicts_open', (SELECT count(*) FROM public.entity_sync_conflicts WHERE status IN ('OPEN','UNDER_REVIEW')),
    'licence_number_entity_identifiers',
      (SELECT count(*) FROM public.entity_identifiers i
        JOIN public.entity_identifier_types t ON t.id = i.identifier_type_id
        WHERE t.key = 'license_number'),
    'retired_identifier_types',
      (SELECT count(*) FROM public.entity_identifier_types WHERE NOT is_active),
    'normalization_strategies_in_use',
      COALESCE((SELECT jsonb_object_agg(normalization_strategy, n) FROM (
          SELECT normalization_strategy, count(*) n FROM public.entity_identifier_types
           WHERE is_active GROUP BY 1) s), '{}'::jsonb)
  ) INTO v;

  RETURN v;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_guard_metadata_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.key IS DISTINCT FROM OLD.key THEN
      RAISE EXCEPTION 'Metadata key "%" is immutable (table %). Retire the row (is_active = false) and create a new key instead.',
        OLD.key, TG_TABLE_NAME USING ERRCODE = '42501';
    END IF;
    IF NEW.is_system IS DISTINCT FROM OLD.is_system THEN
      RAISE EXCEPTION 'is_system cannot be changed on regulatory metadata (table %)', TG_TABLE_NAME USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.is_system THEN
    RAISE EXCEPTION 'System regulatory metadata "%" cannot be deleted (table %). Retire it with is_active = false.',
      OLD.key, TG_TABLE_NAME USING ERRCODE = '42501';
  END IF;
  RETURN OLD;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_integrity_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r jsonb;
BEGIN
  IF NOT public.rdm_can_read() THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  SELECT jsonb_build_object(
    'generated_at', now(),
    'entities_total', (SELECT count(*) FROM public.licensees),
    'licenses_total', (SELECT count(*) FROM public.licenses),
    'entities_without_license', (SELECT count(*) FROM public.licensees WHERE license_id IS NULL),
    'licenses_without_entity', (SELECT count(*) FROM public.licenses l WHERE NOT EXISTS (SELECT 1 FROM public.licensees e WHERE e.license_id = l.id)),
    'entities_sharing_license_id', (SELECT count(*) FROM (SELECT license_id FROM public.licensees WHERE license_id IS NOT NULL GROUP BY 1 HAVING count(*) > 1) x),
    'entities_multi_license_capable', false,
    'duplicate_entity_names', (SELECT count(*) FROM (SELECT lower(trim(name)) FROM public.licensees GROUP BY 1 HAVING count(*) > 1) y),
    'applications_total', (SELECT count(*) FROM public.applications),
    'applications_without_pinned_form_version', (SELECT count(*) FROM public.applications WHERE form_version_id IS NULL),
    'applications_without_resolvable_entity', (SELECT count(*) FROM public.applications a WHERE NOT EXISTS (
        SELECT 1 FROM public.profiles p WHERE p.id = a.applicant_id AND p.licensee_id IS NOT NULL)),
    'registrations_total', (SELECT count(*) FROM public.registrations),
    'registrations_without_user', (SELECT count(*) FROM public.registrations WHERE user_id IS NULL),
    'duplicate_registration_numbers', (SELECT count(*) FROM (SELECT registration_number FROM public.registrations WHERE registration_number IS NOT NULL GROUP BY 1 HAVING count(*) > 1) z),
    'relationship_rows', (SELECT count(*) FROM public.entity_relationships),
    'distinct_relationship_type_values', (SELECT count(DISTINCT relationship_type) FROM public.entity_relationships),
    'form_templates_total', (SELECT count(*) FROM public.form_templates),
    'distinct_form_type_values', (SELECT count(DISTINCT form_type) FROM public.form_templates),
    'form_templates_without_published_version', (SELECT count(*) FROM public.form_templates t WHERE NOT EXISTS (
        SELECT 1 FROM public.form_versions v WHERE v.template_id = t.id)),
    'foreign_keys_referencing_licensees', (SELECT count(*) FROM pg_constraint WHERE contype = 'f' AND confrelid = 'public.licensees'::regclass),
    'configured_metadata', jsonb_build_object(
      'classification_schemes', (SELECT count(*) FROM public.classification_schemes),
      'classification_values', (SELECT count(*) FROM public.classification_values),
      'lifecycle_stages', (SELECT count(*) FROM public.lifecycle_stages),
      'entity_identity_statuses', (SELECT count(*) FROM public.entity_identity_statuses),
      'relationship_types', (SELECT count(*) FROM public.relationship_types),
      'role_types', (SELECT count(*) FROM public.role_types),
      'form_purposes', (SELECT count(*) FROM public.form_purposes),
      'form_trigger_types', (SELECT count(*) FROM public.form_trigger_types),
      'data_domains', (SELECT count(*) FROM public.data_domains),
      'entity_identifier_types', (SELECT count(*) FROM public.entity_identifier_types),
      'entity_resolution_policies', (SELECT count(*) FROM public.entity_resolution_policies),
      'entity_registry_failure_policies', (SELECT count(*) FROM public.entity_registry_failure_policies)
    )
  ) INTO r;
  RETURN r;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_metadata_tables()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT ARRAY[
    'classification_schemes','classification_values','lifecycle_stages',
    'entity_identity_statuses','relationship_types','role_types',
    'form_purposes','form_trigger_types','data_domains',
    'entity_identifier_types','entity_resolution_policies',
    'entity_registry_failure_policies'
  ]
$function$
;
CREATE OR REPLACE FUNCTION public.rdm_migration_decide(_target_type text, _target_id uuid, _decision text, _canonical jsonb DEFAULT '{}'::jsonb, _reason text DEFAULT NULL::text, _evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_rows integer := 0;
  v_legacy jsonb;
  v_purpose uuid;
  v_trigger uuid;
BEGIN
  v_uid := public.rdm_require('form_management', 'edit');

  IF _decision NOT IN ('EXACTLY_MAPPED','PARTIALLY_MAPPED','AMBIGUOUS','LEGACY_ONLY','CONCEPT_BOUND','CONCEPT_CAPTURE_ONLY') THEN
    RAISE EXCEPTION 'Unknown migration decision %', _decision;
  END IF;

  IF _target_type = 'form_template' THEN
    SELECT to_jsonb(t) - 'created_at' - 'updated_at' INTO v_legacy FROM public.form_templates t WHERE t.id = _target_id;
    IF v_legacy IS NULL THEN RAISE EXCEPTION 'Form definition not found'; END IF;

    IF COALESCE(_canonical->>'purpose_key','') <> '' THEN
      SELECT id INTO v_purpose FROM public.form_purposes WHERE key = _canonical->>'purpose_key';
      IF v_purpose IS NULL THEN RAISE EXCEPTION 'Unknown form purpose %', _canonical->>'purpose_key'; END IF;
    END IF;
    IF COALESCE(_canonical->>'trigger_key','') <> '' THEN
      SELECT id INTO v_trigger FROM public.form_trigger_types WHERE key = _canonical->>'trigger_key';
      IF v_trigger IS NULL THEN RAISE EXCEPTION 'Unknown trigger type %', _canonical->>'trigger_key'; END IF;
    END IF;

    UPDATE public.form_templates
       SET legacy_mapping_status = _decision,
           form_purpose_id = COALESCE(v_purpose, form_purpose_id),
           trigger_type_id = COALESCE(v_trigger, trigger_type_id),
           updated_at = now()
     WHERE id = _target_id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF COALESCE(_canonical->>'lifecycle_key','') <> '' THEN
      INSERT INTO public.form_lifecycle_applicability (template_id, lifecycle_key, lifecycle_stage_id)
      SELECT _target_id, _canonical->>'lifecycle_key',
             (SELECT ls.id FROM public.lifecycle_stages ls WHERE ls.key = _canonical->>'lifecycle_key' LIMIT 1)
      WHERE NOT EXISTS (
        SELECT 1 FROM public.form_lifecycle_applicability
        WHERE template_id = _target_id AND lifecycle_key = _canonical->>'lifecycle_key');
    END IF;

    IF COALESCE(_canonical->>'data_domain_key','') <> '' THEN
      INSERT INTO public.form_data_domains (template_id, data_domain_id, is_primary)
      SELECT _target_id, d.id, true FROM public.data_domains d
      WHERE d.key = _canonical->>'data_domain_key'
        AND NOT EXISTS (SELECT 1 FROM public.form_data_domains fd WHERE fd.template_id = _target_id AND fd.data_domain_id = d.id);
    END IF;

  ELSIF _target_type = 'form_field_definition' THEN
    SELECT to_jsonb(d) INTO v_legacy FROM public.form_field_definitions d WHERE d.id = _target_id;
    IF v_legacy IS NULL THEN RAISE EXCEPTION 'Logical field not found'; END IF;

    IF _decision = 'CONCEPT_BOUND' THEN
      IF COALESCE(_canonical->>'data_concept_id','') = '' THEN RAISE EXCEPTION 'data_concept_id required'; END IF;
      UPDATE public.form_field_definitions
         SET data_concept_id = (_canonical->>'data_concept_id')::uuid, updated_at = now()
       WHERE id = _target_id;
    ELSE
      UPDATE public.form_field_definitions SET updated_at = now() WHERE id = _target_id;
    END IF;
    GET DIAGNOSTICS v_rows = ROW_COUNT;

  ELSIF _target_type = 'application' THEN
    IF _decision <> 'LEGACY_ONLY' THEN
      RAISE EXCEPTION 'Applications may only be marked LEGACY_ONLY manually; requirements are reconstructed from evidence';
    END IF;
    INSERT INTO public.application_requirement_migration_status
      (application_id, classification, evidence, requirements_created, decided_by, decided_at)
    VALUES (_target_id, 'LEGACY_REQUIREMENTS_UNKNOWN', _evidence, 0, v_uid, now())
    ON CONFLICT (application_id) DO UPDATE
      SET classification = EXCLUDED.classification, evidence = EXCLUDED.evidence,
          decided_by = EXCLUDED.decided_by, decided_at = now();
    v_rows := 1;
  ELSE
    RAISE EXCEPTION 'Unsupported migration target %', _target_type;
  END IF;

  INSERT INTO public.rdm_migration_decisions
    (target_type, target_id, decision, legacy_value, canonical_value, evidence, reason, affected_rows, decided_by)
  VALUES (_target_type, _target_id, _decision, v_legacy, _canonical, _evidence, _reason, v_rows, v_uid);

  RETURN jsonb_build_object('ok', true, 'affected_rows', v_rows, 'decision', _decision);
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_promote_default_policy(_table text, _id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_active boolean;
BEGIN
  IF NOT public.rdm_can_write() THEN
    RAISE EXCEPTION 'Not authorised to change regulatory data model configuration' USING ERRCODE = '42501';
  END IF;
  IF _table NOT IN ('entity_resolution_policies','entity_registry_failure_policies') THEN
    RAISE EXCEPTION 'Table % has no default-policy semantics', _table USING ERRCODE = '22023';
  END IF;
  EXECUTE format('SELECT is_active FROM public.%I WHERE id = $1', _table) INTO v_active USING _id;
  IF v_active IS NULL THEN
    RAISE EXCEPTION 'Policy % not found in %', _id, _table USING ERRCODE = 'P0002';
  END IF;
  IF NOT v_active THEN
    RAISE EXCEPTION 'A retired policy cannot become the active default' USING ERRCODE = '23514';
  END IF;
  EXECUTE format('UPDATE public.%I SET is_default = false WHERE is_default AND id <> $1', _table) USING _id;
  EXECUTE format('UPDATE public.%I SET is_default = true WHERE id = $1', _table) USING _id;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_relationship_inverse_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_key text;
BEGIN
  IF NEW.inverse_relationship_type_id IS NOT NULL THEN
    SELECT key INTO v_key FROM public.relationship_types WHERE id = NEW.inverse_relationship_type_id;
    IF v_key IS NULL THEN
      RAISE EXCEPTION 'Inverse relationship type % does not exist', NEW.inverse_relationship_type_id;
    END IF;
    NEW.inverse_key := v_key;
  ELSIF NEW.inverse_key IS NOT NULL THEN
    SELECT id INTO v_id FROM public.relationship_types WHERE key = NEW.inverse_key;
    IF v_id IS NULL THEN
      RAISE EXCEPTION 'Inverse relationship key "%" does not resolve to a relationship type', NEW.inverse_key;
    END IF;
    NEW.inverse_relationship_type_id := v_id;
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_require(_module text, _action text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.has_permission(v_uid, _module, _action) THEN
    RAISE EXCEPTION 'Not permitted: %.%', _module, _action USING ERRCODE = '42501';
  END IF;
  RETURN v_uid;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_retire_data_concept(_id uuid, _reason text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid;
BEGIN
  v_uid := public.rdm_require('regulatory_data_model', 'manage');
  UPDATE public.data_concepts
     SET is_active = false, effective_to = COALESCE(effective_to, now()), updated_at = now()
   WHERE id = _id;
  INSERT INTO public.rdm_migration_decisions
    (target_type, target_id, decision, reason, affected_rows, decided_by)
  VALUES ('data_concept', _id, 'LEGACY_ONLY', COALESCE(_reason, 'Concept retired'), 1, v_uid);
  RETURN true;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_retire_metadata(_table text, _id uuid, _promote_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_was_default boolean;
BEGIN
  IF NOT public.rdm_can_write() THEN
    RAISE EXCEPTION 'Not authorised to change regulatory data model configuration' USING ERRCODE = '42501';
  END IF;
  IF NOT (_table = ANY (public.rdm_metadata_tables())) THEN
    RAISE EXCEPTION 'Unknown regulatory metadata table: %', _table USING ERRCODE = '22023';
  END IF;

  IF _table IN ('entity_resolution_policies','entity_registry_failure_policies') THEN
    EXECUTE format('SELECT is_default AND is_active FROM public.%I WHERE id = $1', _table) INTO v_was_default USING _id;
    EXECUTE format('UPDATE public.%I SET is_active = false, is_default = false WHERE id = $1', _table) USING _id;
    IF COALESCE(v_was_default, false) THEN
      IF _promote_id IS NULL THEN
        RAISE EXCEPTION
          'This is the active default policy in %. Select another active policy to promote before retiring it.', _table
          USING ERRCODE = '23514';
      END IF;
      PERFORM public.rdm_promote_default_policy(_table, _promote_id);
    END IF;
  ELSE
    EXECUTE format('UPDATE public.%I SET is_active = false WHERE id = $1', _table) USING _id;
  END IF;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_save_data_concept(_values jsonb, _id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid; v_id uuid; v_existing public.data_concepts;
BEGIN
  v_uid := public.rdm_require('regulatory_data_model', 'manage');

  IF _id IS NULL THEN
    INSERT INTO public.data_concepts (code, name, description, data_domain_id, data_type, cardinality,
      sensitivity_classification, value_source_type, master_data_source, canonical_target,
      projection_strategy, is_system, is_active)
    VALUES (
      upper(trim(_values->>'code')), _values->>'name', _values->>'description',
      NULLIF(_values->>'data_domain_id','')::uuid, COALESCE(_values->>'data_type','TEXT'),
      COALESCE(_values->>'cardinality','SINGLE'), COALESCE(_values->>'sensitivity_classification','INTERNAL'),
      _values->>'value_source_type', _values->>'master_data_source', _values->>'canonical_target',
      _values->>'projection_strategy', false, COALESCE((_values->>'is_active')::boolean, true))
    RETURNING id INTO v_id;
  ELSE
    SELECT * INTO v_existing FROM public.data_concepts WHERE id = _id;
    IF v_existing.id IS NULL THEN RAISE EXCEPTION 'Data concept not found'; END IF;
    IF COALESCE(_values->>'code','') <> '' AND upper(trim(_values->>'code')) IS DISTINCT FROM v_existing.code THEN
      RAISE EXCEPTION 'Concept code is immutable once created';
    END IF;
    UPDATE public.data_concepts SET
      name = COALESCE(_values->>'name', name),
      description = COALESCE(_values->>'description', description),
      data_domain_id = COALESCE(NULLIF(_values->>'data_domain_id','')::uuid, data_domain_id),
      data_type = COALESCE(_values->>'data_type', data_type),
      cardinality = COALESCE(_values->>'cardinality', cardinality),
      sensitivity_classification = COALESCE(_values->>'sensitivity_classification', sensitivity_classification),
      value_source_type = COALESCE(_values->>'value_source_type', value_source_type),
      master_data_source = COALESCE(_values->>'master_data_source', master_data_source),
      canonical_target = COALESCE(_values->>'canonical_target', canonical_target),
      projection_strategy = COALESCE(_values->>'projection_strategy', projection_strategy),
      is_active = COALESCE((_values->>'is_active')::boolean, is_active),
      updated_at = now()
    WHERE id = _id
    RETURNING id INTO v_id;
  END IF;

  INSERT INTO public.rdm_migration_decisions
    (target_type, target_id, decision, canonical_value, reason, affected_rows, decided_by)
  VALUES ('data_concept', v_id, 'EXACTLY_MAPPED', _values,
          CASE WHEN _id IS NULL THEN 'Data concept created' ELSE 'Data concept updated' END, 1, v_uid);

  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_save_metadata(_table text, _values jsonb, _id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid := _id;
  v_cols text[];
  v_assign text := '';
  v_insert_cols text := '';
  v_insert_vals text := '';
  v_key text; v_col text; v_type text; v_existing_key text; v_is_default boolean;
BEGIN
  IF NOT public.rdm_can_write() THEN
    RAISE EXCEPTION 'Not authorised to change regulatory data model configuration' USING ERRCODE = '42501';
  END IF;
  IF NOT (_table = ANY (public.rdm_metadata_tables())) THEN
    RAISE EXCEPTION 'Unknown regulatory metadata table: %', _table USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(column_name::text) INTO v_cols
  FROM information_schema.columns
  WHERE table_schema = 'public' AND table_name = _table
    AND is_generated <> 'ALWAYS'
    AND column_name NOT IN ('id','created_at','updated_at','is_system');

  v_key := NULLIF(btrim(COALESCE(_values ->> 'key','')), '');

  IF v_id IS NULL THEN
    IF v_key IS NULL THEN
      RAISE EXCEPTION 'A machine key is required when creating regulatory metadata' USING ERRCODE = '22023';
    END IF;
    IF v_key !~ '^[a-z0-9_]+$' THEN
      RAISE EXCEPTION 'Machine key must be lower_snake_case: %', v_key USING ERRCODE = '22023';
    END IF;
  ELSE
    EXECUTE format('SELECT key FROM public.%I WHERE id = $1', _table) INTO v_existing_key USING v_id;
    IF v_existing_key IS NULL THEN
      RAISE EXCEPTION 'Regulatory metadata row % not found in %', v_id, _table USING ERRCODE = 'P0002';
    END IF;
    _values := _values - 'key';
  END IF;

  IF _table IN ('entity_resolution_policies','entity_registry_failure_policies') THEN
    v_is_default := COALESCE((_values ->> 'is_default')::boolean, false)
                    AND COALESCE((_values ->> 'is_active')::boolean, true);
    IF v_is_default THEN
      EXECUTE format('UPDATE public.%I SET is_default = false WHERE is_default AND is_active AND ($1 IS NULL OR id <> $1)', _table) USING v_id;
    END IF;
  END IF;

  FOREACH v_col IN ARRAY v_cols LOOP
    IF _values ? v_col THEN
      SELECT format_type(a.atttypid, a.atttypmod) INTO v_type
      FROM pg_attribute a
      WHERE a.attrelid = format('public.%I', _table)::regclass AND a.attname = v_col;
      v_assign := v_assign || format('%I = ($1 ->> %L)::%s, ', v_col, v_col, v_type);
      v_insert_cols := v_insert_cols || format('%I, ', v_col);
      v_insert_vals := v_insert_vals || format('($1 ->> %L)::%s, ', v_col, v_type);
    END IF;
  END LOOP;

  IF v_assign = '' THEN
    RAISE EXCEPTION 'No recognised columns supplied for %', _table USING ERRCODE = '22023';
  END IF;

  IF v_id IS NULL THEN
    EXECUTE format('INSERT INTO public.%I (%s) VALUES (%s) RETURNING id',
      _table, left(v_insert_cols, length(v_insert_cols) - 2), left(v_insert_vals, length(v_insert_vals) - 2))
      INTO v_id USING _values;
  ELSE
    EXECUTE format('UPDATE public.%I SET %s WHERE id = $2', _table, left(v_assign, length(v_assign) - 2))
      USING _values, v_id;
  END IF;

  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END $function$
;
CREATE OR REPLACE FUNCTION public.rdm_wave_b_migration_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_out jsonb;
BEGIN
  PERFORM public.rdm_require('form_management', 'view');

  SELECT jsonb_build_object(
    'generated_at', now(),
    'counts', jsonb_build_object(
      'templates_total', (SELECT count(*) FROM public.form_templates),
      'templates_legacy_only', (SELECT count(*) FROM public.form_templates WHERE legacy_mapping_status = 'LEGACY_ONLY'),
      'templates_ambiguous', (SELECT count(*) FROM public.form_templates WHERE legacy_mapping_status = 'AMBIGUOUS'),
      'templates_partially_mapped', (SELECT count(*) FROM public.form_templates WHERE legacy_mapping_status = 'PARTIALLY_MAPPED'),
      'templates_exactly_mapped', (SELECT count(*) FROM public.form_templates WHERE legacy_mapping_status = 'EXACTLY_MAPPED'),
      'templates_unclassified', (SELECT count(*) FROM public.form_templates WHERE legacy_mapping_status IS NULL OR legacy_mapping_status = 'UNCLASSIFIED'),
      'fields_total', (SELECT count(*) FROM public.form_fields),
      'fields_without_definition', (SELECT count(*) FROM public.form_fields WHERE form_field_definition_id IS NULL),
      'definitions_total', (SELECT count(*) FROM public.form_field_definitions),
      'definitions_without_concept', (SELECT count(*) FROM public.form_field_definitions WHERE data_concept_id IS NULL),
      'applications_submitted', (SELECT count(*) FROM public.applications WHERE status <> 'draft'),
      'applications_missing_requirements', (
        SELECT count(*) FROM public.applications a
        WHERE a.status <> 'draft'
          AND NOT EXISTS (SELECT 1 FROM public.application_form_requirements r WHERE r.application_id = a.id)),
      'applications_migrated_with_evidence', (
        SELECT count(*) FROM public.application_requirement_migration_status WHERE classification = 'MIGRATED_WITH_EVIDENCE'),
      'applications_legacy_unknown', (
        SELECT count(*) FROM public.application_requirement_migration_status WHERE classification = 'LEGACY_REQUIREMENTS_UNKNOWN'),
      'concepts_without_domain', (SELECT count(*) FROM public.data_concepts WHERE data_domain_id IS NULL AND is_active),
      'fp_individuals_unlinked', (
        SELECT count(*) FROM public.fp_individuals i
        WHERE NOT EXISTS (SELECT 1 FROM public.fp_individual_party_links l WHERE l.fp_individual_id = i.id)),
      'packages_total', (SELECT count(*) FROM public.form_packages),
      'legacy_registration_schemas', (SELECT count(*) FROM public.registration_form_configs)
    ),
    'legacy_templates', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'name') FROM (
        SELECT jsonb_build_object(
          'id', t.id, 'name', t.name, 'legacy_form_type', t.form_type,
          'status', t.status,
          'mapping_status', COALESCE(t.legacy_mapping_status, 'UNCLASSIFIED'),
          'purpose_id', t.form_purpose_id,
          'purpose_key', fp.key,
          'trigger_key', tt.key,
          'domains', COALESCE((SELECT count(*) FROM public.form_data_domains d WHERE d.template_id = t.id), 0),
          'lifecycles', COALESCE((SELECT count(*) FROM public.form_lifecycle_applicability l WHERE l.template_id = t.id), 0),
          'field_count', COALESCE((SELECT count(*) FROM public.form_fields f JOIN public.form_versions v ON v.id = f.version_id WHERE v.template_id = t.id), 0),
          'suggested_purpose_key', (SELECT p2.key FROM public.form_purposes p2 WHERE p2.legacy_form_type = t.form_type AND p2.is_active LIMIT 1),
          'suggested_lifecycle', CASE t.form_type
              WHEN 'pre_license' THEN 'pre_authorisation'
              WHEN 'post_license' THEN 'post_authorisation'
              ELSE NULL END,
          'evidence', jsonb_build_object('source', 'form_templates.form_type', 'value', t.form_type)
        ) AS x
        FROM public.form_templates t
        LEFT JOIN public.form_purposes fp ON fp.id = t.form_purpose_id
        LEFT JOIN public.form_trigger_types tt ON tt.id = t.trigger_type_id
      ) s), '[]'::jsonb),
    'unmapped_fields_by_template', COALESCE((
      SELECT jsonb_agg(x) FROM (
        SELECT jsonb_build_object(
          'template_id', v.template_id,
          'template_name', t.name,
          'fields_without_definition', count(*) FILTER (WHERE f.form_field_definition_id IS NULL),
          'fields_total', count(*)
        ) AS x
        FROM public.form_fields f
        JOIN public.form_versions v ON v.id = f.version_id
        JOIN public.form_templates t ON t.id = v.template_id
        GROUP BY v.template_id, t.name
        HAVING count(*) FILTER (WHERE f.form_field_definition_id IS NULL) > 0
      ) s), '[]'::jsonb),
    'applications_missing_requirements_detail', COALESCE((
      SELECT jsonb_agg(x) FROM (
        SELECT jsonb_build_object(
          'application_id', a.id,
          'application_number', a.application_number,
          'status', a.status,
          'submitted_at', a.submitted_at,
          'evidence_versions', (
            SELECT count(*) FROM public.application_form_versions v WHERE v.application_id = a.id AND v.version_id IS NOT NULL),
          'evidence_responses', (
            SELECT count(*) FROM public.form_responses fr WHERE fr.entity_id = a.id AND fr.version_id IS NOT NULL),
          'classification', COALESCE(ms.classification,
            CASE WHEN EXISTS (SELECT 1 FROM public.application_form_versions v WHERE v.application_id = a.id AND v.version_id IS NOT NULL)
                   OR EXISTS (SELECT 1 FROM public.form_responses fr WHERE fr.entity_id = a.id AND fr.version_id IS NOT NULL)
                 THEN 'DERIVABLE_WITH_EVIDENCE'
                 ELSE 'LEGACY_REQUIREMENTS_UNKNOWN' END)
        ) AS x
        FROM public.applications a
        LEFT JOIN public.application_requirement_migration_status ms ON ms.application_id = a.id
        WHERE a.status <> 'draft'
          AND NOT EXISTS (SELECT 1 FROM public.application_form_requirements r WHERE r.application_id = a.id)
        ORDER BY a.submitted_at DESC NULLS LAST
        LIMIT 300
      ) s), '[]'::jsonb),
    'concepts_without_domain_detail', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', c.id, 'code', c.code, 'name', c.name, 'canonical_target', c.canonical_target))
      FROM public.data_concepts c WHERE c.data_domain_id IS NULL AND c.is_active), '[]'::jsonb),
    'sensitive_fields', COALESCE((
      SELECT jsonb_agg(x) FROM (
        SELECT jsonb_build_object(
          'definition_id', d.id, 'template_id', d.template_id, 'field_key', d.field_key,
          'concept_code', c.code, 'sensitivity', c.sensitivity_classification) AS x
        FROM public.form_field_definitions d
        JOIN public.data_concepts c ON c.id = d.data_concept_id
        WHERE c.sensitivity_classification IN ('CONFIDENTIAL', 'RESTRICTED', 'SENSITIVE')
        LIMIT 200
      ) s), '[]'::jsonb),
    'recent_decisions', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', md.id, 'target_type', md.target_type, 'target_id', md.target_id,
        'decision', md.decision, 'reason', md.reason, 'affected_rows', md.affected_rows,
        'decided_at', md.decided_at, 'decided_by', md.decided_by))
      FROM (SELECT * FROM public.rdm_migration_decisions ORDER BY decided_at DESC LIMIT 50) md), '[]'::jsonb)
  ) INTO v_out;

  RETURN v_out;
END $function$
;
CREATE OR REPLACE FUNCTION public.reap_stuck_notification_event_queue()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  UPDATE public.notification_event_queue
     SET status = 'pending', claimed_at = NULL, claimed_by = NULL
   WHERE status = 'processing' AND claimed_at < now() - interval '10 minutes';
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END; $function$
;
CREATE OR REPLACE FUNCTION public.reap_stuck_notification_outbox()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count int;
BEGIN
  WITH reaped AS (
    UPDATE public.notification_outbox
       SET status = 'pending',
           claimed_at = NULL,
           claimed_by = NULL,
           next_attempt_at = now()
     WHERE status = 'processing'
       AND claimed_at < now() - INTERVAL '10 minutes'
    RETURNING id
  )
  SELECT count(*) INTO v_count FROM reaped;
  RETURN v_count;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.recompute_return_ratios(_return_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_cfg uuid; v_ratios jsonb; v_data jsonb;
BEGIN
  SELECT rf.return_configuration_id INTO v_cfg FROM public.returns_filed rf WHERE rf.id = _return_id;
  SELECT COALESCE(jsonb_object_agg(rfd.form_template_id::text, rfd.form_data), '{}'::jsonb)
  INTO v_data FROM public.return_form_data rfd WHERE rfd.return_id = _return_id;
  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.label), '[]'::jsonb)
  INTO v_ratios FROM public.prudential_ratios r WHERE r.return_config_id = v_cfg AND r.is_active = true;
  RETURN jsonb_build_object('return_id', _return_id, 'return_config_id', v_cfg, 'ratios', v_ratios, 'form_data', v_data);
END; $function$
;
CREATE OR REPLACE FUNCTION public.reconcile_stale_ai_assessments(_application_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _count integer := 0;
BEGIN
  UPDATE public.application_ai_assessments a
     SET status = 'failed',
         error_message = 'Generation did not complete (timed out)'
   WHERE a.status = 'pending'
     AND a.created_at < now() - interval '10 minutes'
     AND (_application_id IS NULL OR a.application_id = _application_id)
     AND public.can_read_application(auth.uid(), a.application_id);
  GET DIAGNOSTICS _count = ROW_COUNT;
  RETURN _count;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.record_appeal_decision(_appeal_id uuid, _decision text, _rationale text, _dissent text DEFAULT NULL::text, _conditions text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_appeal record;
  v_snapshot record;
  v_voting int;
  v_reinstate jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF NOT public.has_permission(v_uid,'license_appeals','decide') THEN
    RETURN jsonb_build_object('error','You are not allowed to decide appeals','code','FORBIDDEN','http',403);
  END IF;
  IF nullif(trim(coalesce(_rationale,'')),'') IS NULL OR length(trim(_rationale)) < 10 THEN
    RETURN jsonb_build_object('error','A written rationale of at least 10 characters is required','code','RATIONALE_REQUIRED','http',400);
  END IF;
  IF _decision NOT IN ('upheld','partially_upheld','dismissed','remitted','overturned_to_approved') THEN
    RETURN jsonb_build_object('error','Unknown appeal decision','code','BAD_DECISION','http',400);
  END IF;

  SELECT * INTO v_appeal FROM public.license_appeals WHERE id = _appeal_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Appeal not found','code','NOT_FOUND','http',404);
  END IF;
  IF v_appeal.status = 'decided' THEN
    RETURN jsonb_build_object('error','This appeal has already been decided','code','ALREADY_DECIDED','http',409);
  END IF;

  SELECT * INTO v_snapshot
    FROM public.license_appeal_panel_snapshots
   WHERE appeal_id = _appeal_id
   ORDER BY snapshot_at DESC LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','A panel must be constituted before an appeal can be decided','code','NO_PANEL','http',409);
  END IF;

  SELECT count(*) INTO v_voting
    FROM jsonb_array_elements(v_snapshot.member_roster) r WHERE (r->>'is_voting')::boolean;

  IF v_voting < v_snapshot.quorum THEN
    RETURN jsonb_build_object('error',
      format('Quorum is not met: %s voting member(s) against a quorum of %s', v_voting, v_snapshot.quorum),
      'code','QUORUM_NOT_MET','http',422);
  END IF;

  UPDATE public.license_appeals
     SET decision = _decision,
         decision_rationale = _rationale,
         dissent_note = _dissent,
         decision_conditions = _conditions,
         decided_at = now(),
         decided_by = v_uid,
         quorum_met = true,
         status = 'decided',
         updated_at = now()
   WHERE id = _appeal_id;

  INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id, metadata)
  VALUES (
    _appeal_id, 'decided',
    CASE WHEN _decision IN ('upheld','partially_upheld','overturned_to_approved')
         THEN 'Appeal accepted for consideration' ELSE 'Appeal declined' END,
    v_uid,
    jsonb_build_object('decision', _decision, 'quorum', v_snapshot.quorum,
                       'voting_members', v_voting, 'decision_rule', v_snapshot.decision_rule,
                       'snapshot_id', v_snapshot.id)
  );

  IF _decision IN ('upheld','partially_upheld','overturned_to_approved') THEN
    v_reinstate := public.reinstate_application_after_appeal(_appeal_id, _rationale);
  END IF;

  RETURN jsonb_build_object('success', true, 'http', 200,
                            'quorum_met', true, 'reinstatement', v_reinstate);
END; $function$
;
CREATE OR REPLACE FUNCTION public.record_correspondence_delivery(_message_id uuid, _status text, _reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_msg public.correspondence_messages%ROWTYPE; v_actor text;
BEGIN
  IF NOT public.is_internal_staff(v_user) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF _status NOT IN ('queued','sent','delivered','opened','bounced') THEN RAISE EXCEPTION 'invalid_status'; END IF;
  SELECT * INTO v_msg FROM public.correspondence_messages WHERE id = _message_id;
  IF v_msg.id IS NULL THEN RAISE EXCEPTION 'message_not_found'; END IF;
  v_actor := public.correspondence_actor_label(v_user);

  UPDATE public.correspondence_messages
     SET delivery_status = _status,
         delivered_at = CASE WHEN _status IN ('delivered','opened') THEN COALESCE(delivered_at, now()) ELSE delivered_at END,
         opened_at = CASE WHEN _status = 'opened' THEN COALESCE(opened_at, now()) ELSE opened_at END,
         bounce_reason = CASE WHEN _status = 'bounced' THEN _reason ELSE bounce_reason END
   WHERE id = _message_id;

  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
  VALUES (v_msg.thread_id, v_user, v_actor, 'System',
          CASE WHEN _status = 'bounced' THEN 'MESSAGE_DELIVERY_FAILED' ELSE 'MESSAGE_DELIVERY_CONFIRMED' END,
          COALESCE(_reason, 'Status: ' || _status), false);
END; $function$
;
CREATE OR REPLACE FUNCTION public.record_correspondence_review(_thread_id uuid, _decision text, _notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_actor text; v_status text;
BEGIN
  IF NOT public.is_internal_staff(v_user) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF _decision NOT IN ('start_review','approve','reject') THEN RAISE EXCEPTION 'invalid_decision'; END IF;
  v_actor := public.correspondence_actor_label(v_user);
  v_status := CASE _decision WHEN 'start_review' THEN 'in_review' WHEN 'approve' THEN 'approved' ELSE 'in_review' END;
  UPDATE public.correspondence_threads SET status = v_status WHERE id = _thread_id;
  INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail)
  VALUES (_thread_id, v_user, v_actor, 'Staff',
          CASE _decision WHEN 'start_review' THEN 'Moved to In Review' WHEN 'approve' THEN 'Response approved' ELSE 'Sent back for revision' END,
          _notes);
END; $function$
;
CREATE OR REPLACE FUNCTION public.record_entity_risk_rating(_entity_id uuid, _overall_rating text, _risk_score numeric, _assessment_date date DEFAULT CURRENT_DATE, _risk_factors jsonb DEFAULT '[]'::jsonb, _mitigation_measures text DEFAULT NULL::text, _notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _row record;
BEGIN
  PERFORM public.enforce_permission('prudential_supervision','record_camels_assessment');
  IF _overall_rating NOT IN ('low','medium','high','critical') THEN
    RAISE EXCEPTION 'invalid risk rating' USING ERRCODE='22023';
  END IF;
  IF _risk_score IS NULL OR _risk_score < 0 OR _risk_score > 100 THEN
    RAISE EXCEPTION 'risk score must be between 0 and 100' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.risk_ratings (entity_id, overall_rating, risk_score, assessment_date,
    assessor_id, risk_factors, mitigation_measures, notes)
  VALUES (_entity_id, _overall_rating, _risk_score, COALESCE(_assessment_date, CURRENT_DATE),
          _uid, COALESCE(_risk_factors,'[]'::jsonb), _mitigation_measures, _notes)
  RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'entity.risk_rating.recorded','risk_rating',_row.id,
          jsonb_build_object('entity_id',_entity_id,'after',to_jsonb(_row)));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.record_export_intent(_module text, _action text, _meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF _action IS NULL OR _action NOT IN ('export','download') THEN
    RAISE EXCEPTION 'record_export_intent only accepts export/download actions'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  PERFORM public.enforce_permission(_module, _action);

  INSERT INTO public.audit_logs (
    user_id, action, entity_type, entity_id, metadata, created_at
  ) VALUES (
    auth.uid(),
    _module || '.' || _action,
    _module,
    NULL,
    coalesce(_meta, '{}'::jsonb),
    now()
  );

  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.record_lineage(_object_type text, _object_id text, _limit integer DEFAULT 200)
 RETURNS TABLE(source text, event_at timestamp with time zone, actor_id uuid, actor_role text, action text, before_value jsonb, after_value jsonb, changed_fields text[], justification text, metadata jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.can_view_lineage(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized to view data lineage';
  END IF;
  IF _object_type IS NULL OR _object_id IS NULL THEN
    RAISE EXCEPTION 'object_type and object_id are required';
  END IF;

  RETURN QUERY
  SELECT * FROM (
    SELECT 'compliance_audit_logs'::text AS source,
           COALESCE(cal.timestamp, cal.created_at) AS event_at,
           cal.user_id AS actor_id,
           cal.user_role AS actor_role,
           cal.action_type::text AS action,
           cal.before_value,
           cal.after_value,
           public.jsonb_changed_fields(cal.before_value, cal.after_value) AS changed_fields,
           cal.justification,
           cal.metadata
    FROM public.compliance_audit_logs cal
    WHERE cal.object_type = _object_type AND cal.object_id = _object_id
    UNION ALL
    SELECT 'audit_logs'::text,
           al.created_at,
           al.user_id,
           al.user_role,
           al.action,
           al.old_value,
           al.new_value,
           public.jsonb_changed_fields(al.old_value, al.new_value),
           NULL::text,
           al.metadata
    FROM public.audit_logs al
    WHERE al.entity_type = _object_type AND al.entity_id = _object_id
  ) merged
  ORDER BY merged.event_at DESC
  LIMIT GREATEST(1, LEAST(COALESCE(_limit, 200), 1000));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.record_return_breach(_return_id uuid, _metric_key text, _level text, _value numeric, _threshold_value numeric, _comparator text, _risk_level text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_cfg uuid;
BEGIN
  SELECT return_configuration_id INTO v_cfg FROM public.returns_filed WHERE id = _return_id;
  INSERT INTO public.return_threshold_breaches(
    return_id, return_config_id, metric_key, level, value, threshold_value, comparator, risk_level
  )
  VALUES (
    _return_id, v_cfg, _metric_key, _level, _value, _threshold_value, _comparator,
    COALESCE(_risk_level, CASE WHEN _level = 'breach' THEN 'red' WHEN _level = 'warn' THEN 'amber' END)
  )
  RETURNING id INTO v_id;
  RETURN v_id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.record_return_ratio(_return_id uuid, _ratio_key text, _label text, _value numeric, _display_format text, _computed_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_cfg uuid;
BEGIN
  SELECT return_configuration_id INTO v_cfg FROM public.returns_filed WHERE id = _return_id;
  INSERT INTO public.return_calculated_ratios(return_id, return_config_id, ratio_key, label, value, display_format, computed_by)
  VALUES (_return_id, v_cfg, _ratio_key, _label, _value, _display_format, COALESCE(_computed_by, auth.uid()))
  RETURNING id INTO v_id;
  RETURN v_id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.record_return_ratio(_return_id uuid, _ratio_key text, _label text, _value numeric, _display_format text, _computed_by uuid DEFAULT NULL::uuid, _null_reason text DEFAULT NULL::text, _ratio_version integer DEFAULT NULL::integer, _formula_snapshot text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_cfg uuid;
BEGIN
  SELECT return_configuration_id INTO v_cfg FROM public.returns_filed WHERE id = _return_id;
  INSERT INTO public.return_calculated_ratios(
    return_id, return_config_id, ratio_key, label, value, display_format, computed_by,
    null_reason, ratio_version, formula_snapshot)
  VALUES (_return_id, v_cfg, _ratio_key, _label, _value, _display_format,
          COALESCE(_computed_by, auth.uid()),
          CASE WHEN _value IS NULL THEN COALESCE(_null_reason, 'missing_input') ELSE NULL END,
          _ratio_version, _formula_snapshot)
  RETURNING id INTO v_id;
  RETURN v_id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.record_sufficiency_determination(_application_id uuid, _decision text, _reason text, _checklist jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app RECORD;
  v_eval RECORD;
  v_blockers int := 0;
  v_open_rfi int := 0;
  v_gates jsonb;
  v_row public.sufficiency_determinations;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'Not authenticated', 'code', 'UNAUTHENTICATED');
  END IF;

  IF NOT (
    public.is_super_admin(v_uid)
    OR public.has_permission(v_uid, 'application_management', 'workflow_action')
    OR public.has_permission(v_uid, 'application_management', 'edit')
  ) THEN
    RETURN jsonb_build_object('error', 'You are not permitted to record a sufficiency determination', 'code', 'FORBIDDEN');
  END IF;

  IF _decision NOT IN ('sufficient','insufficient','deferred') THEN
    RETURN jsonb_build_object('error', 'Invalid decision', 'code', 'INVALID_DECISION');
  END IF;
  IF length(btrim(coalesce(_reason, ''))) < 10 THEN
    RETURN jsonb_build_object('error', 'Reason must be at least 10 characters', 'code', 'REASON_REQUIRED');
  END IF;

  SELECT id, status, submitted_at INTO v_app FROM public.applications WHERE id = _application_id;
  IF v_app.id IS NULL THEN
    RETURN jsonb_build_object('error', 'Application not found', 'code', 'NOT_FOUND');
  END IF;
  IF v_app.submitted_at IS NULL THEN
    RETURN jsonb_build_object('error', 'Application has not been submitted', 'code', 'NOT_SUBMITTED');
  END IF;

  SELECT * INTO v_eval
  FROM public.sufficiency_evaluations
  WHERE application_id = _application_id
  ORDER BY evaluated_at DESC
  LIMIT 1;

  IF v_eval.id IS NULL THEN
    RETURN jsonb_build_object(
      'error', 'Run a sufficiency evaluation before recording a determination',
      'code', 'NO_EVALUATION');
  END IF;

  SELECT count(*) INTO v_blockers
  FROM public.sufficiency_evaluation_results r
  WHERE r.evaluation_id = v_eval.id
    AND r.status = 'fail'
    AND r.severity = 'blocker'
    AND NOT EXISTS (SELECT 1 FROM public.sufficiency_overrides o WHERE o.evaluation_result_id = r.id);

  SELECT count(*) INTO v_open_rfi
  FROM public.application_rfis
  WHERE application_id = _application_id AND status IN ('open','responded');

  v_gates := public.decision_gate_status(_application_id);

  -- Server-enforced: a "sufficient" outcome is impossible while blocking
  -- conditions remain, regardless of what the reviewer ticked in the UI.
  IF _decision = 'sufficient' AND (v_blockers > 0 OR v_open_rfi > 0) THEN
    RETURN jsonb_build_object(
      'error', 'Cannot declare sufficient: '
        || v_blockers || ' unresolved blocker(s), ' || v_open_rfi || ' open/unclosed RFI(s)',
      'code', 'SUFFICIENCY_GATES_UNMET',
      'unresolved_blocker_count', v_blockers,
      'open_rfi_count', v_open_rfi,
      'gates', v_gates);
  END IF;

  INSERT INTO public.sufficiency_determinations (
    application_id, evaluation_id, decision, reason, checklist,
    unresolved_blocker_count, open_rfi_count, gate_snapshot, determined_by
  ) VALUES (
    _application_id, v_eval.id, _decision, btrim(_reason), coalesce(_checklist, '[]'::jsonb),
    v_blockers, v_open_rfi, coalesce(v_gates, '{}'::jsonb), v_uid
  )
  RETURNING * INTO v_row;

  UPDATE public.applications
  SET sufficiency_status = CASE
        WHEN _decision = 'sufficient' THEN 'passed'
        WHEN _decision = 'insufficient' THEN 'blocked'
        ELSE 'warning' END,
      last_sufficiency_evaluation_id = v_eval.id,
      updated_at = now()
  WHERE id = _application_id;

  RETURN jsonb_build_object('success', true, 'determination', to_jsonb(v_row));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.redact_sensitive_jsonb(_payload jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _payload IS NULL OR jsonb_typeof(_payload) <> 'object' THEN _payload
    ELSE (
      SELECT coalesce(jsonb_object_agg(
        k,
        CASE WHEN lower(k) ~ '(token|secret|password|passwd|api[_-]?key|authorization|bearer|service[_-]?role|credential|private[_-]?key)'
             THEN to_jsonb('[redacted]'::text)
             ELSE v END
      ), '{}'::jsonb)
      FROM jsonb_each(_payload) AS e(k, v)
    )
  END
$function$
;
CREATE OR REPLACE FUNCTION public.refer_conduct_signal_to_investigation(_signal_id uuid, _allegation text, _reason text DEFAULT NULL::text, _priority text DEFAULT 'medium'::text, _due_date date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _sig public.conduct_alerts;
  _inv_id uuid;
BEGIN
  IF NOT (public.is_super_admin(_uid)
          OR public.has_permission(_uid,'market_conduct','initiate_investigation')) THEN
    RAISE EXCEPTION 'Not authorized to refer signals to investigation';
  END IF;

  SELECT * INTO _sig FROM public.conduct_alerts WHERE id = _signal_id;
  IF _sig.id IS NULL THEN
    RAISE EXCEPTION 'Signal not found';
  END IF;
  IF _sig.disposition <> 'UNDER_REVIEW' THEN
    RAISE EXCEPTION 'Only a signal under review can be referred (current: %)', _sig.disposition;
  END IF;
  IF COALESCE(btrim(_allegation),'') = '' THEN
    RAISE EXCEPTION 'An allegation summary is required';
  END IF;

  INSERT INTO public.conduct_investigations
    (source_type, source_id, licensee_id, product_id, allegation, priority, severity, due_date, opened_by, metadata)
  VALUES
    ('surveillance_signal', _signal_id, _sig.licensee_id, _sig.product_id, btrim(_allegation),
     COALESCE(_priority,'medium'), _sig.severity, _due_date, _uid,
     jsonb_build_object(
       'signal_id', _signal_id,
       'signal_kind', _sig.kind,
       'signal_rule_id', _sig.triage_rule_id,
       'signal_rule_version', _sig.rule_version,
       'signal_threshold', _sig.threshold_value,
       'signal_explanation', _sig.explanation,
       'signal_source_record_ids', to_jsonb(_sig.source_record_ids),
       'signal_observation_start', _sig.observation_start,
       'signal_observation_end', _sig.observation_end,
       'referral_reason', NULLIF(btrim(_reason),'')
     ))
  RETURNING id INTO _inv_id;

  PERFORM set_config('app.signal_disposition_ok','on', true);

  UPDATE public.conduct_alerts
     SET disposition = 'ESCALATED',
         disposition_reason = COALESCE(NULLIF(btrim(_reason),''), disposition_reason),
         reviewed_by = _uid,
         reviewed_at = now(),
         investigation_id = _inv_id,
         updated_at = now()
   WHERE id = _signal_id;

  INSERT INTO public.conduct_signal_events
    (signal_id, from_disposition, to_disposition, reason, actor_id, investigation_id)
  VALUES (_signal_id, 'UNDER_REVIEW', 'ESCALATED', NULLIF(btrim(_reason),''), _uid, _inv_id);

  PERFORM set_config('app.signal_disposition_ok','', true);
  RETURN _inv_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.registration_journey_register(_filters jsonb DEFAULT '{}'::jsonb, _limit integer DEFAULT 100, _offset integer DEFAULT 0)
 RETURNS TABLE(user_id uuid, user_email text, journey_type text, stage text, entity_id uuid, entity_name text, membership_status text, last_event_at timestamp with time zone, event_count bigint, latest_stage text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.onboarding_can_view_audit(auth.uid()) THEN
    RAISE EXCEPTION 'Not permitted to read onboarding journeys' USING ERRCODE='42501';
  END IF;
  RETURN QUERY
  SELECT js.user_id,
         COALESCE(p.email, plu.email),
         COALESCE(js.intended_journey, js.context->>'journey_type'),
         js.stage, js.entity_id, l.name,
         m.status, GREATEST(js.updated_at, COALESCE(max(ev.occurred_at), js.updated_at)),
         count(ev.id), max(ev.stage)
    FROM public.onboarding_journey_state js
    LEFT JOIN public.profiles p ON p.id = js.user_id
    LEFT JOIN public.pre_license_users plu ON plu.id = js.user_id
    LEFT JOIN public.licensees l ON l.id = js.entity_id
    LEFT JOIN public.entity_user_memberships m ON m.id = js.membership_id
    LEFT JOIN public.registration_journey_events ev ON ev.user_id = js.user_id
   WHERE (NULLIF(_filters->>'user','') IS NULL OR COALESCE(p.email, plu.email) ILIKE '%' || (_filters->>'user') || '%')
     AND (NULLIF(_filters->>'stage','') IS NULL OR js.stage = _filters->>'stage')
     AND (NULLIF(_filters->>'journey_type','') IS NULL OR COALESCE(js.intended_journey, js.context->>'journey_type') = _filters->>'journey_type')
   GROUP BY js.user_id, p.email, plu.email, js.intended_journey, js.context, js.stage, js.entity_id, l.name, m.status, js.updated_at
   ORDER BY GREATEST(js.updated_at, COALESCE(max(ev.occurred_at), js.updated_at)) DESC
   LIMIT GREATEST(COALESCE(_limit,100),1) OFFSET GREATEST(COALESCE(_offset,0),0);
END $function$
;
CREATE OR REPLACE FUNCTION public.regulatory_metric_code_locked()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.code <> OLD.code AND EXISTS (
      SELECT 1 FROM public.return_metric_values WHERE regulatory_metric_id = OLD.id) THEN
    RAISE EXCEPTION 'Metric code is immutable once values exist' USING ERRCODE='42501';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.regulatory_request_available_types(_entity_id uuid)
 RETURNS TABLE(key text, label text, description text, requires_change_set boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT t.key, t.label, t.description, t.requires_change_set
    FROM public.regulatory_request_types t
   WHERE t.is_active
     AND (public.has_permission(auth.uid(),'regulatory_requests','create')
          OR (t.external_startable
              AND public.wb_membership_capability(_entity_id, COALESCE(t.min_membership_capability,'start_regulatory_request'))))
   ORDER BY t.sort_order, t.label;
$function$
;
CREATE OR REPLACE FUNCTION public.regulatory_request_start(_entity_id uuid, _request_type_key text, _effective_date date DEFAULT NULL::date, _summary text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_type record; v_req record; v_res jsonb; v_item jsonb; v_pinned int := 0; v_missing int := 0;
BEGIN
  SELECT * INTO v_type FROM public.regulatory_request_types
   WHERE key = _request_type_key AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown or inactive request type %', _request_type_key; END IF;

  PERFORM public.wb_require('regulatory_requests','create', _entity_id,
    COALESCE(v_type.min_membership_capability,'start_regulatory_request'));

  INSERT INTO public.regulatory_requests (entity_id, request_type_id, status, effective_date, summary, created_by)
  VALUES (_entity_id, v_type.id, 'DRAFT', _effective_date, _summary, auth.uid())
  RETURNING * INTO v_req;

  v_res := public.resolve_applicable_form_package(jsonb_build_object(
    'request_type_key', _request_type_key,
    'lifecycle_key', 'authorised',
    'regulator_id', (SELECT regulator_id::text FROM public.licensees WHERE id = _entity_id),
    'sector_id', (SELECT sector_id::text FROM public.licensees WHERE id = _entity_id),
    'sub_sector_id', (SELECT sub_sector_id::text FROM public.licensees WHERE id = _entity_id),
    'category_id', (SELECT category_id::text FROM public.licensees WHERE id = _entity_id)));

  IF (v_res->>'resolved')::boolean THEN
    UPDATE public.regulatory_requests SET package_id = (v_res->>'package_id')::uuid WHERE id = v_req.id;
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_res->'items') LOOP
      IF NULLIF(v_item->>'form_version_id','') IS NULL THEN v_missing := v_missing + 1; CONTINUE; END IF;
      INSERT INTO public.regulatory_request_form_requirements
        (request_id, template_id, form_version_id, package_id, is_required, sequence)
      VALUES (v_req.id, (v_item->>'template_id')::uuid, (v_item->>'form_version_id')::uuid,
              (v_res->>'package_id')::uuid, COALESCE((v_item->>'is_required')::boolean,true),
              COALESCE((v_item->>'sequence')::int,0))
      ON CONFLICT (request_id, template_id) DO NOTHING;
      v_pinned := v_pinned + 1;
    END LOOP;
  END IF;

  PERFORM public.create_audit_log(auth.uid(),'regulatory_request.created','regulatory_request',
    v_req.id::text, NULL, jsonb_build_object('entity_id',_entity_id,'type',_request_type_key,
    'pinned_forms',v_pinned,'skipped_unpublished',v_missing), NULL);

  RETURN jsonb_build_object('success',true,'request_id',v_req.id,'request_number',v_req.request_number,
    'pinned_forms',v_pinned,'skipped_unpublished',v_missing,'package_resolved',(v_res->>'resolved')::boolean);
END $function$
;
CREATE OR REPLACE FUNCTION public.regulatory_request_transition(_request_id uuid, _action text, _notes text DEFAULT NULL::text, _assignee uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_req record; v_evt text;
BEGIN
  SELECT * INTO v_req FROM public.regulatory_requests WHERE id = _request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Regulatory request not found'; END IF;

  IF _action = 'submit' THEN
    PERFORM public.wb_require('regulatory_requests','create', v_req.entity_id, 'start_regulatory_request');
    IF v_req.status <> 'DRAFT' THEN RAISE EXCEPTION 'Only draft requests can be submitted'; END IF;
    UPDATE public.regulatory_requests SET status='SUBMITTED', submitted_by=auth.uid(), submitted_at=now(),
      updated_at=now() WHERE id=_request_id;
    v_evt := 'regulatory_request.submitted';
  ELSIF _action = 'assign' THEN
    PERFORM public.wb_require('regulatory_requests','assign');
    UPDATE public.regulatory_requests SET assigned_to=_assignee, assigned_by=auth.uid(), assigned_at=now(),
      status = CASE WHEN status='SUBMITTED' THEN 'UNDER_REVIEW' ELSE status END, updated_at=now()
     WHERE id=_request_id;
    v_evt := NULL;
  ELSIF _action = 'review' THEN
    PERFORM public.wb_require('regulatory_requests','review');
    UPDATE public.regulatory_requests SET status='UNDER_REVIEW', updated_at=now() WHERE id=_request_id;
    v_evt := NULL;
  ELSIF _action = 'approve' THEN
    PERFORM public.wb_require('regulatory_requests','approve');
    UPDATE public.regulatory_requests SET status='APPROVED', decided_by=auth.uid(), decided_at=now(),
      decision_rationale=_notes, updated_at=now() WHERE id=_request_id;
    v_evt := 'regulatory_request.approved';
  ELSIF _action = 'reject' THEN
    PERFORM public.wb_require('regulatory_requests','reject');
    UPDATE public.regulatory_requests SET status='REJECTED', decided_by=auth.uid(), decided_at=now(),
      decision_rationale=_notes, updated_at=now() WHERE id=_request_id;
    v_evt := 'regulatory_request.rejected';
  ELSIF _action = 'close' THEN
    PERFORM public.wb_require('regulatory_requests','close');
    UPDATE public.regulatory_requests SET status='CLOSED', closed_by=auth.uid(), closed_at=now(),
      updated_at=now() WHERE id=_request_id;
    v_evt := 'regulatory_request.closed';
  ELSE
    RAISE EXCEPTION 'Unknown action %', _action;
  END IF;

  IF v_evt IS NOT NULL THEN
    PERFORM public.create_audit_log(auth.uid(), v_evt, 'regulatory_request', _request_id::text, NULL,
      jsonb_build_object('entity_id',v_req.entity_id,'notes',_notes), NULL);
  END IF;
  RETURN jsonb_build_object('success',true,'request_id',_request_id,'action',_action);
END $function$
;
CREATE OR REPLACE FUNCTION public.reinstate_application_after_appeal(_appeal_id uuid, _remarks text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_now timestamptz := now();
  v_appeal record;
  v_app record;
  v_actor_roles text[];
  v_instance_id uuid;
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;

  SELECT array_agg(DISTINCT r) INTO v_actor_roles FROM (
    SELECT role::text AS r FROM public.user_roles WHERE user_id = v_uid
    UNION
    SELECT ro.system_role AS r
      FROM public.user_dynamic_roles udr
      JOIN public.roles ro ON ro.id = udr.role_id
     WHERE udr.user_id = v_uid AND ro.system_role IS NOT NULL
  ) sub;
  v_actor_roles := COALESCE(v_actor_roles, ARRAY[]::text[]);

  IF NOT (
    public.has_permission(v_uid, 'license_appeals', 'decide')
    OR v_actor_roles && ARRAY['super_admin','admin','supervisor','licensing_officer']::text[]
  ) THEN
    RETURN jsonb_build_object('error','You are not allowed to decide appeals','code','FORBIDDEN','http',403);
  END IF;

  SELECT * INTO v_appeal FROM public.license_appeals WHERE id = _appeal_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Appeal not found','code','NOT_FOUND','http',404);
  END IF;

  SELECT id, applicant_id, application_number, status
    INTO v_app
    FROM public.applications
   WHERE id = v_appeal.application_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  IF v_app.status <> 'rejected' THEN
    RETURN jsonb_build_object(
      'success', true, 'http', 200, 'skipped', true,
      'reason', format('Application is already ''%s''', v_app.status),
      'application_id', v_app.id, 'status', v_app.status
    );
  END IF;

  -- Guard: never create a second active workflow for the same entity.
  IF EXISTS (
    SELECT 1 FROM public.workflow_instances
     WHERE entity_type = 'application' AND entity_id = v_app.id
       AND status IN ('active','paused')
  ) THEN
    v_instance_id := NULL;
  ELSE
    UPDATE public.workflow_instances
       SET status = 'active', completed_at = NULL, updated_at = v_now
     WHERE id = (
       SELECT id FROM public.workflow_instances
        WHERE entity_type = 'application' AND entity_id = v_app.id
          AND status IN ('rejected','completed','cancelled')
        ORDER BY updated_at DESC
        LIMIT 1
     )
    RETURNING id INTO v_instance_id;
  END IF;

  UPDATE public.applications
     SET status = 'in_progress', rejected_at = NULL, updated_at = v_now
   WHERE id = v_app.id;

  INSERT INTO public.approval_actions (
    application_id, actor_id, action, action_type, comments, responded_at, workflow_instance_id
  ) VALUES (
    v_app.id, v_uid, 'reinstated', 'save_comment',
    COALESCE(NULLIF(trim(_remarks), ''), 'Application reinstated for reconsideration after the appeal was considered'),
    v_now, v_instance_id
  );

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
  VALUES (
    v_uid, 'application_reinstated_after_appeal', 'application', v_app.id::text,
    jsonb_build_object(
      'appeal_id', v_appeal.id,
      'appeal_reference', v_appeal.appeal_reference,
      'remarks', _remarks,
      'previous_status', 'rejected',
      'new_status', 'in_progress'
    )
  );

  INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id, metadata)
  VALUES (
    v_appeal.id, 'application_reinstated',
    format('Application %s reinstated for reconsideration after the appeal was considered', v_app.application_number),
    v_uid,
    jsonb_build_object('application_id', v_app.id)
  );

  INSERT INTO public.notifications (user_id, title, message, type, entity_type, entity_id)
  VALUES (
    v_app.applicant_id,
    'Appeal considered: ' || v_app.application_number,
    'Your appeal was accepted for consideration and application ' || v_app.application_number
      || ' is back under review.',
    'success', 'application', v_app.id::text
  );

  RETURN jsonb_build_object(
    'success', true, 'http', 200,
    'application_id', v_app.id,
    'application_number', v_app.application_number,
    'status', 'in_progress',
    'workflow_instance_id', v_instance_id
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reject_application_action(_application_id uuid, _comments text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_now timestamptz := now();
  v_actor_roles text[];
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF _comments IS NULL OR length(trim(_comments)) = 0 THEN
    RETURN jsonb_build_object('error','Remarks are required for rejection','code','REMARKS_REQUIRED','http',422);
  END IF;

  SELECT array_agg(DISTINCT r) INTO v_actor_roles FROM (
    SELECT role::text AS r FROM public.user_roles WHERE user_id = v_uid
    UNION
    SELECT system_role AS r
      FROM public.user_dynamic_roles udr
      JOIN public.roles ro ON ro.id = udr.role_id
     WHERE udr.user_id = v_uid AND ro.system_role IS NOT NULL
  ) sub;
  v_actor_roles := COALESCE(v_actor_roles, ARRAY[]::text[]);

  IF NOT (v_actor_roles && ARRAY['super_admin','admin','supervisor','licensing_officer']::text[]) THEN
    RETURN jsonb_build_object('error','Only reviewers can reject applications','code','FORBIDDEN','http',403);
  END IF;

  SELECT id, applicant_id, application_number, status
    INTO v_app
    FROM public.applications
   WHERE id = _application_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  IF v_app.status NOT IN ('submitted','in_progress','resubmission_requested','query_raised') THEN
    RETURN jsonb_build_object(
      'error', format('Cannot reject while status is ''%s''', v_app.status),
      'code','INVALID_STATUS','http',409
    );
  END IF;

  UPDATE public.applications
     SET status = 'rejected', rejected_at = v_now, updated_at = v_now
   WHERE id = _application_id;

  UPDATE public.workflow_instances
     SET status = 'rejected', completed_at = v_now, updated_at = v_now
   WHERE entity_id = _application_id
     AND entity_type = 'application'
     AND status IN ('active','paused');

  INSERT INTO public.approval_actions (
    application_id, actor_id, action, action_type, comments, responded_at
  ) VALUES (
    _application_id, v_uid, 'rejected', 'reject', NULLIF(trim(_comments),''), v_now
  );

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
  VALUES (
    v_uid, 'application_rejected', 'application', _application_id::text,
    jsonb_build_object('comments', _comments)
  );

  INSERT INTO public.notifications (user_id, title, message, type, entity_type, entity_id)
  VALUES (
    v_app.applicant_id,
    'Application Rejected: ' || v_app.application_number,
    'Your application has been rejected. Remarks: ' || _comments,
    'error', 'application', _application_id::text
  );

  RETURN jsonb_build_object(
    'success', true, 'http', 200,
    'application_id', _application_id,
    'status', 'rejected'
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reject_return(_return_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF _return_id IS NULL THEN
    RAISE EXCEPTION 'return_id required' USING ERRCODE = '22023';
  END IF;

  IF _reason IS NULL OR btrim(_reason) = '' THEN
    RAISE EXCEPTION 'reason required' USING ERRCODE = '22023';
  END IF;

  PERFORM public.enforce_permission('returns_management', 'reject');

  INSERT INTO public.audit_logs (user_id, action, resource_type, resource_id, metadata)
  VALUES (
    _uid,
    'reject_return',
    'returns_filed',
    _return_id,
    jsonb_build_object('reason', _reason, 'module', 'returns_management', 'permission_action', 'reject')
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reject_review_suggestion(_suggestion_id uuid)
 RETURNS review_suggestions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s public.review_suggestions%ROWTYPE;
BEGIN
  SELECT * INTO s FROM public.review_suggestions WHERE id = _suggestion_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REVIEW_NOT_FOUND'; END IF;
  IF s.status <> 'pending' THEN RAISE EXCEPTION 'REVIEW_ALREADY_DECIDED'; END IF;
  PERFORM public._assert_review_action(auth.uid(), s.entity_type, s.entity_id, s.workflow_step_id, NULL, 'reject');
  UPDATE public.review_suggestions
     SET status = 'rejected', decided_by = auth.uid(), decided_at = now()
   WHERE id = _suggestion_id RETURNING * INTO s;
  RETURN s;
END $function$
;
CREATE OR REPLACE FUNCTION public.reorder_approval_steps(_workflow_id uuid, _orders jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  rec record;
  expected_count int;
  matched_count int;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF NOT (
    public.has_role(auth.uid(), 'super_admin'::app_role)
    OR public.has_role(auth.uid(), 'admin'::app_role)
  ) THEN
    RAISE EXCEPTION 'insufficient privileges';
  END IF;

  IF _orders IS NULL OR jsonb_typeof(_orders) <> 'array' THEN
    RAISE EXCEPTION 'orders must be a JSON array';
  END IF;

  -- Validate every id belongs to the workflow
  SELECT count(*) INTO expected_count
  FROM jsonb_array_elements(_orders) AS e;

  SELECT count(*) INTO matched_count
  FROM jsonb_array_elements(_orders) AS e
  JOIN public.approval_steps s
    ON s.id = (e->>'id')::uuid
   AND s.workflow_id = _workflow_id;

  IF matched_count <> expected_count THEN
    RAISE EXCEPTION 'reorder payload references steps outside workflow %', _workflow_id;
  END IF;

  -- Pass 1: shift to a negative range to avoid unique collisions.
  FOR rec IN SELECT (e->>'id')::uuid AS id, (e->>'step_order')::int AS step_order
             FROM jsonb_array_elements(_orders) AS e
  LOOP
    UPDATE public.approval_steps
       SET step_order = -1 * (rec.step_order + 1)
     WHERE id = rec.id AND workflow_id = _workflow_id;
  END LOOP;

  -- Pass 2: write the final orders.
  FOR rec IN SELECT (e->>'id')::uuid AS id, (e->>'step_order')::int AS step_order
             FROM jsonb_array_elements(_orders) AS e
  LOOP
    UPDATE public.approval_steps
       SET step_order = rec.step_order
     WHERE id = rec.id AND workflow_id = _workflow_id;
  END LOOP;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.repair_application_workflow(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app record;
  v_sector uuid;
  v_category uuid;
  v_is_post boolean;
  v_eff_reg uuid;
  v_wf_id uuid;
  v_step_id uuid;
  v_existing record;
  v_new_instance uuid;
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  SELECT id, status, license_type, regulator_id, data, workflow_id, current_step_id
    INTO v_app
    FROM public.applications
   WHERE id = _application_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;

  IF v_app.status NOT IN ('submitted','in_progress','resubmission_requested',
                          'resubmission_required','returned_for_correction',
                          'info_requested','query_raised','in_review',
                          'pending_review','under_review','forwarded','awaiting_approval') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'status_not_eligible', 'status', v_app.status);
  END IF;

  -- already attached?
  SELECT id, workflow_id, current_step_id, status INTO v_existing
    FROM public.workflow_instances
   WHERE entity_id = _application_id
     AND entity_type = 'application'
     AND status IN ('active','paused')
   ORDER BY created_at DESC LIMIT 1;
  IF FOUND THEN
    -- backfill application columns if missing
    IF v_app.workflow_id IS NULL OR v_app.current_step_id IS NULL THEN
      UPDATE public.applications
         SET workflow_id = COALESCE(workflow_id, v_existing.workflow_id),
             current_step_id = COALESCE(current_step_id, v_existing.current_step_id),
             updated_at = now()
       WHERE id = _application_id;
    END IF;
    RETURN jsonb_build_object('ok', true, 'instance_id', v_existing.id, 'created', false);
  END IF;

  v_sector := NULLIF(v_app.data->>'sector_id','')::uuid;
  v_category := NULLIF(v_app.data->>'category_id','')::uuid;
  v_is_post := COALESCE(NULLIF(v_app.data->>'service_id','') IS NOT NULL, false)
               OR (v_app.data->>'type') = 'post_license';

  v_eff_reg := public._resolve_effective_regulator(v_app.regulator_id, v_sector, v_category);

  SELECT r.workflow_id, r.first_step_id INTO v_wf_id, v_step_id
    FROM public._resolve_application_workflow(
           v_app.license_type, v_eff_reg, v_sector, v_category, v_is_post) r;

  IF v_wf_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_matching_workflow');
  END IF;

  INSERT INTO public.workflow_instances (workflow_id, entity_type, entity_id, current_step_id, status)
  VALUES (v_wf_id, 'application', _application_id, v_step_id, 'active')
  RETURNING id INTO v_new_instance;

  UPDATE public.applications
     SET workflow_id = COALESCE(workflow_id, v_wf_id),
         current_step_id = COALESCE(current_step_id, v_step_id),
         regulator_id = COALESCE(v_eff_reg, regulator_id),
         updated_at = now()
   WHERE id = _application_id;

  RETURN jsonb_build_object('ok', true, 'instance_id', v_new_instance, 'workflow_id', v_wf_id, 'created', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.request_export_job(_source text, _justification text, _from_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _to_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _module_filter text DEFAULT NULL::text, _export_format text DEFAULT 'csv'::text, _filters jsonb DEFAULT NULL::jsonb, _row_count integer DEFAULT NULL::integer, _file_path text DEFAULT NULL::text, _file_hash text DEFAULT NULL::text, _retention_days integer DEFAULT 90)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF _source IS NULL OR btrim(_source) = '' THEN
    RAISE EXCEPTION 'Export source is required';
  END IF;
  IF _justification IS NULL OR length(btrim(_justification)) < 10 THEN
    RAISE EXCEPTION 'A justification of at least 10 characters is required for regulated data exports';
  END IF;

  INSERT INTO public.audit_export_jobs (
    requested_by, source, from_date, to_date, module_filter, status,
    row_count, file_path, file_hash, filters, export_format,
    justification, retention_expires_at, completed_at
  ) VALUES (
    v_uid, _source, _from_date, _to_date, _module_filter,
    CASE WHEN _row_count IS NULL THEN 'pending' ELSE 'completed' END,
    _row_count, _file_path, _file_hash, _filters, COALESCE(_export_format, 'csv'),
    btrim(_justification),
    now() + (GREATEST(1, LEAST(COALESCE(_retention_days, 90), 3650)) || ' days')::interval,
    CASE WHEN _row_count IS NULL THEN NULL ELSE now() END
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.request_legal_notes_access(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_allowed boolean;
BEGIN
  v_allowed := public.can_view_application_legal_notes(auth.uid(), _application_id);
  IF NOT v_allowed THEN
    PERFORM public.log_restricted_legal_note_denial(_application_id, NULL, 'view_denied', 'request_legal_notes_access');
  END IF;
  RETURN jsonb_build_object('allowed', v_allowed);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.request_resubmission_for_application(_application_id uuid, _comments text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_now timestamptz := now();
  v_actor_roles text[];
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF _comments IS NULL OR length(trim(_comments)) = 0 THEN
    RETURN jsonb_build_object('error','Remarks are required','code','REMARKS_REQUIRED','http',422);
  END IF;

  SELECT array_agg(DISTINCT r) INTO v_actor_roles FROM (
    SELECT role::text AS r FROM public.user_roles WHERE user_id = v_uid
    UNION
    SELECT system_role AS r
      FROM public.user_dynamic_roles udr
      JOIN public.roles ro ON ro.id = udr.role_id
     WHERE udr.user_id = v_uid AND ro.system_role IS NOT NULL
  ) sub;
  v_actor_roles := COALESCE(v_actor_roles, ARRAY[]::text[]);

  IF NOT (v_actor_roles && ARRAY['super_admin','admin','supervisor','licensing_officer','analyst']::text[]) THEN
    RETURN jsonb_build_object('error','Only reviewers can request resubmission','code','FORBIDDEN','http',403);
  END IF;

  SELECT id, applicant_id, application_number, status
    INTO v_app
    FROM public.applications
   WHERE id = _application_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  IF v_app.status NOT IN ('submitted','in_progress') THEN
    RETURN jsonb_build_object(
      'error', format('Cannot request resubmission while status is ''%s''', v_app.status),
      'code','INVALID_STATUS','http',409
    );
  END IF;

  UPDATE public.applications
     SET status = 'resubmission_requested', updated_at = v_now
   WHERE id = _application_id;

  UPDATE public.workflow_instances
     SET status = 'paused', updated_at = v_now
   WHERE entity_id = _application_id
     AND entity_type = 'application'
     AND status = 'active';

  INSERT INTO public.approval_actions (
    application_id, actor_id, action, action_type, comments, responded_at
  ) VALUES (
    _application_id, v_uid, 'resubmission_requested', 'request_resubmission',
    NULLIF(trim(_comments),''), v_now
  );

  PERFORM public.create_audit_log(
    v_uid, 'resubmission_requested', 'application', _application_id::text, NULL,
    jsonb_build_object('comments', _comments), NULL
  );

  PERFORM public.create_notification(
    v_app.applicant_id,
    'Resubmission Requested: ' || v_app.application_number,
    'Your application requires revisions. Remarks: ' || _comments,
    'warning', 'application', _application_id::text
  );

  RETURN jsonb_build_object(
    'success', true, 'http', 200,
    'application_id', _application_id,
    'status', 'resubmission_requested'
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.request_return_edit(_return_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_return public.returns_filed%ROWTYPE;
  v_uid uuid := auth.uid();
  v_req_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'Not authenticated', 'code', 'UNAUTHORIZED', 'http', 401);
  END IF;
  IF _reason IS NULL OR btrim(_reason) = '' THEN
    RETURN jsonb_build_object('error', 'A reason is required', 'code', 'BAD_REQUEST', 'http', 400);
  END IF;

  SELECT * INTO v_return FROM public.returns_filed WHERE id = _return_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Return not found', 'code', 'NOT_FOUND', 'http', 404);
  END IF;

  IF v_return.created_by IS DISTINCT FROM v_uid THEN
    RETURN jsonb_build_object('error', 'You are not authorised to request edits for this return', 'code', 'FORBIDDEN', 'http', 403);
  END IF;

  IF upper(coalesce(v_return.workflow_status::text, '')) NOT IN ('SUB','VAL') THEN
    RETURN jsonb_build_object('error', 'Edit requests are only allowed on submitted or validated returns', 'code', 'INVALID_STATE', 'http', 422);
  END IF;

  IF EXISTS (SELECT 1 FROM public.return_edit_requests WHERE return_id = _return_id AND status = 'pending') THEN
    RETURN jsonb_build_object('error', 'An edit request is already pending admin review', 'code', 'ALREADY_PENDING', 'http', 409);
  END IF;

  INSERT INTO public.return_edit_requests(return_id, reason, status, requested_by)
  VALUES (_return_id, btrim(_reason), 'pending', v_uid)
  RETURNING id INTO v_req_id;

  BEGIN
    INSERT INTO public.return_audit_log(return_id, action, previous_status, new_status, comments, performed_by, created_at)
    VALUES (_return_id, 'applicant_edit_requested', v_return.workflow_status::text, v_return.workflow_status::text, btrim(_reason), v_uid, now());
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN jsonb_build_object('ok', true, 'request_id', v_req_id);
END $function$
;
CREATE OR REPLACE FUNCTION public.reset_application_for_provisioning(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_now timestamptz := now();
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;

  IF NOT (public.has_role(v_uid, 'super_admin'::app_role) OR public.has_role(v_uid, 'admin'::app_role)) THEN
    RETURN jsonb_build_object('error','Admin only','code','FORBIDDEN','http',403);
  END IF;

  SELECT id, status INTO v_app FROM public.applications WHERE id = _application_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  IF v_app.status <> 'approved' THEN
    RETURN jsonb_build_object('error','Only approved applications can be reset','code','INVALID_STATUS','http',409);
  END IF;

  UPDATE public.applications
     SET status = 'in_progress', approved_at = NULL, updated_at = v_now
   WHERE id = _application_id;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
  VALUES (v_uid, 'application_reset_for_provisioning', 'application',
          _application_id::text, jsonb_build_object('previous_status','approved'));

  RETURN jsonb_build_object('success', true, 'http', 200, 'application_id', _application_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reset_system_role_permissions(p_role_name text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role_id uuid;
  v_count integer := 0;
  v_bypass text := current_setting('app.rbac_bypass', true);
BEGIN
  IF v_bypass IS DISTINCT FROM 'reset' THEN
    PERFORM public.assert_role_management_action('reset');
    PERFORM set_config('app.rbac_bypass', 'reset', true);
  END IF;

  SELECT id INTO v_role_id FROM public.roles WHERE name = p_role_name AND is_system = true;
  IF v_role_id IS NULL THEN
    PERFORM set_config('app.rbac_bypass', '', true);
    RAISE EXCEPTION 'System role % not found', p_role_name;
  END IF;

  DELETE FROM public.role_permissions WHERE role_id = v_role_id;

  WITH matrix(role_name, module, action) AS (
    VALUES
      ('Applicant','application_management','view'),
      ('Applicant','application_management','create'),
      ('Applicant','application_management','edit'),
      ('Applicant','licensing','view'),
      ('Applicant','licensing','submit'),
      ('Applicant','licensing','respond_rfi'),
      ('Applicant','licensing','upload_documents'),
      ('Regulated Entity User','application_management','view'),
      ('Regulated Entity User','license_management','view'),
      ('Regulated Entity User','returns_management','view'),
      ('Regulated Entity User','returns_management','create'),
      ('Regulated Entity User','returns_management','edit'),
      ('Regulated Entity User','returns_management','submit'),
      ('Regulated Entity User','returns_management','upload_documents'),
      ('Regulated Entity User','returns_management','respond_rfi'),
      ('Regulated Entity User','returns_management','view_status'),
      ('Regulated Entity User','complaint_management','view'),
      ('Regulated Entity User','complaint_management','create'),
      ('Regulated Entity User','complaint_management','edit'),
      ('Regulated Entity User','complaint_management','submit'),
      ('Regulated Entity User','complaint_management','upload_documents'),
      ('Regulated Entity User','complaint_management','view_status'),
      ('Regulated Entity User','fit_and_proper','view'),
      ('Regulated Entity User','fit_and_proper','submit'),
      ('Regulated Entity User','fit_and_proper','upload_documents'),
      ('Regulated Entity User','fit_and_proper','view_status'),
      ('Licensing Officer','application_management','view'),
      ('Licensing Officer','application_management','create'),
      ('Licensing Officer','application_management','edit'),
      ('Licensing Officer','license_management','view'),
      ('Licensing Officer','license_management','edit'),
      ('Licensing Officer','registration_management','view'),
      ('Licensing Officer','registration_management','edit'),
      ('Licensing Officer','licensing','view'),
      ('Licensing Officer','licensing','respond_rfi'),
      ('Licensing Officer','licensing','add_legal_notes'),
      ('Licensing Officer','licensing','flag_concern'),
      ('Licensing Officer','licensing','recommend_conditions'),
      ('Licensing Officer','licensing','upload_documents'),
      ('Licensing Officer','report_management','view'),
      ('Analyst','application_management','view'),
      ('Analyst','application_management','edit'),
      ('Analyst','license_management','view'),
      ('Analyst','registration_management','view'),
      ('Analyst','returns_management','view'),
      ('Analyst','complaint_management','view'),
      ('Analyst','report_management','view'),
      ('Analyst','licensing','view'),
      ('Analyst','licensing','flag_concern'),
      ('Legal/Compliance Reviewer','application_management','view'),
      ('Legal/Compliance Reviewer','application_management','edit'),
      ('Legal/Compliance Reviewer','license_management','view'),
      ('Legal/Compliance Reviewer','registration_management','view'),
      ('Legal/Compliance Reviewer','returns_management','view'),
      ('Legal/Compliance Reviewer','complaint_management','view'),
      ('Legal/Compliance Reviewer','complaint_management','edit'),
      ('Legal/Compliance Reviewer','report_management','view'),
      ('Legal/Compliance Reviewer','licensing','view'),
      ('Legal/Compliance Reviewer','licensing','add_legal_notes'),
      ('Legal/Compliance Reviewer','licensing','recommend_conditions'),
      ('Legal/Compliance Reviewer','licensing','flag_concern'),
      ('Approver/Decision-Maker','application_management','view'),
      ('Approver/Decision-Maker','application_management','approve'),
      ('Approver/Decision-Maker','application_management','reject'),
      ('Approver/Decision-Maker','license_management','view'),
      ('Approver/Decision-Maker','license_management','approve'),
      ('Approver/Decision-Maker','registration_management','view'),
      ('Approver/Decision-Maker','registration_management','approve'),
      ('Approver/Decision-Maker','registration_management','reject'),
      ('Approver/Decision-Maker','returns_management','view'),
      ('Approver/Decision-Maker','returns_management','approve'),
      ('Approver/Decision-Maker','complaint_management','view'),
      ('Approver/Decision-Maker','complaint_management','edit'),
      ('Approver/Decision-Maker','report_management','view'),
      ('Approver/Decision-Maker','licensing','view'),
      ('Approver/Decision-Maker','licensing','approve'),
      ('Approver/Decision-Maker','licensing','reject'),
      ('Approver/Decision-Maker','licensing','conditional_approve'),
      ('Approver/Decision-Maker','licensing','issue_digital_license'),
      ('Approver/Decision-Maker','licensing','override_ai_recommendation'),
      ('Approver/Decision-Maker','licensing','sign_enforcement_order'),
      ('Prudential Supervisor','application_management','view'),
      ('Prudential Supervisor','license_management','view'),
      ('Prudential Supervisor','returns_management','view'),
      ('Prudential Supervisor','returns_management','edit'),
      ('Prudential Supervisor','returns_management','approve'),
      ('Prudential Supervisor','complaint_management','view'),
      ('Prudential Supervisor','report_management','view'),
      ('Market Conduct Supervisor','application_management','view'),
      ('Market Conduct Supervisor','license_management','view'),
      ('Market Conduct Supervisor','complaint_management','view'),
      ('Market Conduct Supervisor','complaint_management','create'),
      ('Market Conduct Supervisor','complaint_management','edit'),
      ('Market Conduct Supervisor','report_management','view'),
      ('Committee Member','application_management','view'),
      ('Committee Member','application_management','approve'),
      ('Committee Member','license_management','view'),
      ('Committee Member','license_management','approve'),
      ('Committee Member','registration_management','view'),
      ('Committee Member','registration_management','approve'),
      ('Committee Member','returns_management','view'),
      ('Committee Member','returns_management','approve'),
      ('Committee Member','complaint_management','view'),
      ('Committee Member','report_management','view'),
      ('Committee Member','fit_and_proper_committee','view'),
      ('Committee Member','fit_and_proper_committee','cast_weighted_vote'),
      ('Committee Member','fit_and_proper_committee','provide_rationale')
  )
  INSERT INTO public.role_permissions (role_id, permission_id)
  SELECT v_role_id, p.id
  FROM matrix m
  JOIN public.permissions p ON p.module = m.module AND p.name = m.action
  WHERE m.role_name = p_role_name
    AND COALESCE(p.deprecated, false) = false
    AND p.enforced = true
  ON CONFLICT DO NOTHING;

  IF p_role_name = 'Executive Supervisor' THEN
    INSERT INTO public.role_permissions (role_id, permission_id)
    SELECT v_role_id, p.id FROM public.permissions p
    WHERE (p.name IN ('view','approve','view_status')
       OR p.module = 'executive_oversight'
       OR (p.module = 'settings' AND p.name = 'view'))
      AND COALESCE(p.deprecated, false) = false
      AND p.enforced = true
    ON CONFLICT DO NOTHING;
  END IF;

  IF p_role_name = 'System Administrator' THEN
    INSERT INTO public.role_permissions (role_id, permission_id)
    SELECT v_role_id, p.id FROM public.permissions p
    WHERE COALESCE(p.deprecated, false) = false AND p.enforced = true
    ON CONFLICT DO NOTHING;
  END IF;

  SELECT count(*) INTO v_count FROM public.role_permissions WHERE role_id = v_role_id;
  PERFORM set_config('app.rbac_bypass', '', true);
  RETURN v_count;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reset_system_role_permissions_guarded(p_role_name text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  PERFORM public.assert_role_management_action('reset');
  PERFORM set_config('app.rbac_bypass', 'reset', true);
  BEGIN
    v_count := public.reset_system_role_permissions(p_role_name);
    PERFORM set_config('app.rbac_bypass', '', true);
    RETURN v_count;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.rbac_bypass', '', true);
    RAISE;
  END;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_actor_role(_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT role::text
  FROM public.user_roles
  WHERE user_id = _user_id
  ORDER BY CASE role::text
    WHEN 'super_admin' THEN 1
    WHEN 'admin' THEN 2
    WHEN 'supervisor' THEN 3
    WHEN 'licensing_officer' THEN 4
    WHEN 'legal_compliance' THEN 5
    WHEN 'analyst' THEN 6
    WHEN 'licensee_primary' THEN 7
    WHEN 'licensee_secondary' THEN 8
    WHEN 'pre_licensee' THEN 9
    WHEN 'applicant' THEN 10
    ELSE 99
  END
  LIMIT 1;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_applicable_form_package(_ctx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rule record; v_items jsonb;
BEGIN
  SELECT r.*,
         ((CASE WHEN r.regulator_id IS NOT NULL THEN 16 ELSE 0 END)
        + (CASE WHEN r.category_id IS NOT NULL THEN 32 ELSE 0 END)
        + (CASE WHEN r.sub_sector_id IS NOT NULL THEN 16 ELSE 0 END)
        + (CASE WHEN r.sector_id IS NOT NULL THEN 8 ELSE 0 END)
        + (CASE WHEN r.license_type IS NOT NULL THEN 4 ELSE 0 END)
        + (CASE WHEN r.request_type_key IS NOT NULL THEN 4 ELSE 0 END)
        + (CASE WHEN r.lifecycle_key IS NOT NULL THEN 2 ELSE 0 END)
        + (CASE WHEN r.application_type IS NOT NULL THEN 1 ELSE 0 END)) AS specificity
    INTO v_rule
    FROM public.form_applicability_rules r
    JOIN public.form_packages p ON p.id = r.package_id
   WHERE r.is_active AND p.status = 'published' AND p.is_active
     AND r.effective_from <= now() AND (r.effective_to IS NULL OR r.effective_to > now())
     AND (r.regulator_id IS NULL OR r.regulator_id = NULLIF(_ctx->>'regulator_id','')::uuid)
     AND (r.sector_id IS NULL OR r.sector_id = NULLIF(_ctx->>'sector_id','')::uuid)
     AND (r.sub_sector_id IS NULL OR r.sub_sector_id = NULLIF(_ctx->>'sub_sector_id','')::uuid)
     AND (r.category_id IS NULL OR r.category_id = NULLIF(_ctx->>'category_id','')::uuid)
     AND (r.service_id IS NULL OR r.service_id = NULLIF(_ctx->>'service_id','')::uuid)
     AND (r.license_type IS NULL OR r.license_type = NULLIF(_ctx->>'license_type',''))
     AND (r.lifecycle_key IS NULL OR r.lifecycle_key = NULLIF(_ctx->>'lifecycle_key',''))
     AND (r.request_type_key IS NULL OR r.request_type_key = NULLIF(_ctx->>'request_type_key',''))
     AND (r.application_type IS NULL OR r.application_type = NULLIF(_ctx->>'application_type',''))
     AND (r.jurisdiction IS NULL OR r.jurisdiction = NULLIF(_ctx->>'jurisdiction',''))
   ORDER BY specificity DESC, r.priority DESC, r.effective_from DESC, r.id
   LIMIT 1;

  IF v_rule.id IS NULL THEN
    RETURN jsonb_build_object('resolved', false, 'reason','NO_APPLICABLE_PACKAGE');
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
           'template_id', i.template_id,
           'template_name', t.name,
           'is_required', i.is_required,
           'sequence', i.sequence,
           'form_version_id', pv.id,
           'form_version', pv.version)
         ORDER BY i.sequence, t.name)
    INTO v_items
    FROM public.form_package_items i
    JOIN public.form_templates t ON t.id = i.template_id
    LEFT JOIN LATERAL (
      SELECT v.id, v.version FROM public.form_versions v
       WHERE v.template_id = i.template_id AND v.status = 'published'
       ORDER BY v.version DESC LIMIT 1) pv ON true
   WHERE i.package_id = v_rule.package_id;

  RETURN jsonb_build_object('resolved', true,
    'package_id', v_rule.package_id,
    'applicability_rule_id', v_rule.id,
    'specificity', v_rule.specificity,
    'items', COALESCE(v_items,'[]'::jsonb));
END $function$
;
CREATE OR REPLACE FUNCTION public.resolve_application_form_version(_application_id uuid, _template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_is_internal boolean;
  v_assignment record;
  v_legacy_id uuid;
  v_chosen record;
  v_now timestamptz := now();
  v_existing_map jsonb := '{}'::jsonb;
  v_updated_data jsonb := '{}'::jsonb;
  v_pinned_is_usable boolean;
  v_is_editable boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;

  IF _application_id IS NULL OR _template_id IS NULL THEN
    RETURN jsonb_build_object('error','application_id and template_id are required','code','BAD_REQUEST','http',400);
  END IF;

  v_is_internal := public.has_role(v_uid, 'super_admin'::app_role)
                OR public.has_role(v_uid, 'admin'::app_role)
                OR public.has_role(v_uid, 'supervisor'::app_role)
                OR public.has_role(v_uid, 'licensing_officer'::app_role)
                OR public.has_role(v_uid, 'analyst'::app_role);

  SELECT id, applicant_id, data, status
    INTO v_app
    FROM public.applications
   WHERE id = _application_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  IF NOT v_is_internal AND v_app.applicant_id <> v_uid THEN
    RETURN jsonb_build_object('error','You do not have access to this application','code','FORBIDDEN','http',403);
  END IF;

  v_is_editable := COALESCE(lower(v_app.status), 'draft') IN ('draft', 'in_progress', 'resubmission_requested', 'query_raised');

  SELECT afv.id,
         afv.version_id,
         afv.assigned_reason,
         fv.id AS form_version_id,
         fv.template_id AS form_version_template_id,
         fv.version,
         fv.semantic_version,
         fv.status AS fv_status,
         fv.effective_from AS fv_effective_from,
         fv.effective_until AS fv_effective_until
    INTO v_assignment
    FROM public.application_form_versions afv
    LEFT JOIN public.form_versions fv ON fv.id = afv.version_id
   WHERE afv.application_id = _application_id
     AND afv.template_id = _template_id
     AND afv.status = 'active'
   ORDER BY afv.created_at DESC
   LIMIT 1;

  IF FOUND THEN
    IF v_assignment.form_version_id IS NULL OR v_assignment.form_version_template_id IS DISTINCT FROM _template_id THEN
      RETURN jsonb_build_object(
        'error','The assigned form version could not be found. Please contact support.',
        'code','PINNED_VERSION_MISSING','http',404,
        'application_id', _application_id,
        'template_id', _template_id,
        'version_id', v_assignment.version_id
      );
    END IF;

    v_pinned_is_usable := v_assignment.fv_status IN ('published','archived')
      AND (v_assignment.fv_effective_from IS NULL OR v_assignment.fv_effective_from <= v_now)
      AND (
        v_assignment.fv_effective_until IS NULL
        OR (date_trunc('day', v_assignment.fv_effective_until) + interval '1 day' - interval '1 microsecond') >= v_now
      );

    IF v_is_editable AND NOT v_pinned_is_usable THEN
      SELECT fv.id, fv.version, fv.semantic_version
        INTO v_chosen
        FROM public.form_versions fv
       WHERE fv.template_id = _template_id
         AND fv.status = 'published'
         AND (fv.effective_from IS NULL OR fv.effective_from <= v_now)
         AND (
           fv.effective_until IS NULL
           OR (date_trunc('day', fv.effective_until) + interval '1 day' - interval '1 microsecond') >= v_now
         )
       ORDER BY fv.version DESC, COALESCE(fv.published_at, fv.created_at) DESC, fv.id DESC
       LIMIT 1;

      IF FOUND AND v_chosen.id IS DISTINCT FROM v_assignment.version_id THEN
        UPDATE public.application_form_versions
           SET status = 'superseded'
         WHERE id = v_assignment.id;

        INSERT INTO public.application_form_versions (
          application_id, template_id, version_id, assigned_reason, assigned_by, locked_at, status
        ) VALUES (
          _application_id, _template_id, v_chosen.id, 'repinned_after_archive', v_uid, v_now, 'active'
        )
        ON CONFLICT DO NOTHING;

        v_updated_data := jsonb_set(
          COALESCE(v_app.data, '{}'::jsonb),
          '{form_version_ids}',
          COALESCE(v_app.data->'form_version_ids', '{}'::jsonb) || jsonb_build_object(_template_id::text, v_chosen.id::text),
          true
        );
        UPDATE public.applications SET data = v_updated_data WHERE id = _application_id;

        RETURN jsonb_build_object(
          'success', true,
          'http', 200,
          'application_id', _application_id,
          'template_id', _template_id,
          'version_id', v_chosen.id,
          'version_number', v_chosen.version,
          'semantic_version', v_chosen.semantic_version,
          'assigned_reason', 'repinned_after_archive',
          'was_existing_assignment', false
        );
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'http', 200,
      'application_id', _application_id,
      'template_id', _template_id,
      'version_id', v_assignment.version_id,
      'version_number', v_assignment.version,
      'semantic_version', v_assignment.semantic_version,
      'assigned_reason', 'resumed_existing',
      'was_existing_assignment', true
    );
  END IF;

  v_existing_map := COALESCE(v_app.data->'form_version_ids', '{}'::jsonb);
  v_legacy_id := NULLIF(v_existing_map->>(_template_id::text), '')::uuid;

  IF v_legacy_id IS NOT NULL THEN
    SELECT id, template_id, version, semantic_version, status, effective_from, effective_until
      INTO v_chosen
      FROM public.form_versions
     WHERE id = v_legacy_id;

    IF NOT FOUND OR v_chosen.template_id IS DISTINCT FROM _template_id THEN
      RETURN jsonb_build_object(
        'error','The assigned form version could not be found. Please contact support.',
        'code','PINNED_VERSION_MISSING','http',404,
        'application_id', _application_id,
        'template_id', _template_id,
        'version_id', v_legacy_id
      );
    END IF;

    v_pinned_is_usable := v_chosen.status IN ('published','archived')
      AND (v_chosen.effective_from IS NULL OR v_chosen.effective_from <= v_now)
      AND (
        v_chosen.effective_until IS NULL
        OR (date_trunc('day', v_chosen.effective_until) + interval '1 day' - interval '1 microsecond') >= v_now
      );

    IF v_is_editable AND NOT v_pinned_is_usable THEN
      SELECT fv.id, fv.version, fv.semantic_version
        INTO v_chosen
        FROM public.form_versions fv
       WHERE fv.template_id = _template_id
         AND fv.status = 'published'
         AND (fv.effective_from IS NULL OR fv.effective_from <= v_now)
         AND (
           fv.effective_until IS NULL
           OR (date_trunc('day', fv.effective_until) + interval '1 day' - interval '1 microsecond') >= v_now
         )
       ORDER BY fv.version DESC, COALESCE(fv.published_at, fv.created_at) DESC, fv.id DESC
       LIMIT 1;

      IF NOT FOUND THEN
        RETURN jsonb_build_object(
          'error','No active form version is available for this form. Please contact support.',
          'code','NO_ACTIVE_VERSION','http',409,
          'application_id', _application_id,
          'template_id', _template_id
        );
      END IF;

      INSERT INTO public.application_form_versions (
        application_id, template_id, version_id, assigned_reason, assigned_by, locked_at, status
      ) VALUES (
        _application_id, _template_id, v_chosen.id, 'repinned_after_archive', v_uid, v_now, 'active'
      )
      ON CONFLICT DO NOTHING;

      v_updated_data := jsonb_set(
        COALESCE(v_app.data, '{}'::jsonb),
        '{form_version_ids}',
        COALESCE(v_app.data->'form_version_ids', '{}'::jsonb) || jsonb_build_object(_template_id::text, v_chosen.id::text),
        true
      );
      UPDATE public.applications SET data = v_updated_data WHERE id = _application_id;

      RETURN jsonb_build_object(
        'success', true,
        'http', 200,
        'application_id', _application_id,
        'template_id', _template_id,
        'version_id', v_chosen.id,
        'version_number', v_chosen.version,
        'semantic_version', v_chosen.semantic_version,
        'assigned_reason', 'repinned_after_archive',
        'was_existing_assignment', false
      );
    END IF;

    INSERT INTO public.application_form_versions (
      application_id, template_id, version_id, assigned_reason, assigned_by, locked_at, status
    ) VALUES (
      _application_id, _template_id, v_chosen.id, 'migrated_from_json', v_uid, v_now, 'active'
    )
    ON CONFLICT DO NOTHING;

    RETURN jsonb_build_object(
      'success', true,
      'http', 200,
      'application_id', _application_id,
      'template_id', _template_id,
      'version_id', v_chosen.id,
      'version_number', v_chosen.version,
      'semantic_version', v_chosen.semantic_version,
      'assigned_reason', 'resumed_existing',
      'was_existing_assignment', true
    );
  END IF;

  SELECT fv.id, fv.version, fv.semantic_version
    INTO v_chosen
    FROM public.form_versions fv
   WHERE fv.template_id = _template_id
     AND fv.status = 'published'
     AND (fv.effective_from IS NULL OR fv.effective_from <= v_now)
     AND (
       fv.effective_until IS NULL
       OR (date_trunc('day', fv.effective_until) + interval '1 day' - interval '1 microsecond') >= v_now
     )
   ORDER BY fv.version DESC, COALESCE(fv.published_at, fv.created_at) DESC, fv.id DESC
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'error','No active form version is available for this form. Please contact support.',
      'code','NO_ACTIVE_VERSION','http',409,
      'application_id', _application_id,
      'template_id', _template_id
    );
  END IF;

  INSERT INTO public.application_form_versions (
    application_id, template_id, version_id, assigned_reason, assigned_by, locked_at, status
  ) VALUES (
    _application_id, _template_id, v_chosen.id, 'latest_at_start', v_uid, v_now, 'active'
  )
  ON CONFLICT DO NOTHING;

  v_updated_data := jsonb_set(
    COALESCE(v_app.data, '{}'::jsonb),
    '{form_version_ids}',
    COALESCE(v_app.data->'form_version_ids', '{}'::jsonb) || jsonb_build_object(_template_id::text, v_chosen.id::text),
    true
  );
  UPDATE public.applications SET data = v_updated_data WHERE id = _application_id;

  RETURN jsonb_build_object(
    'success', true,
    'http', 200,
    'application_id', _application_id,
    'template_id', _template_id,
    'version_id', v_chosen.id,
    'version_number', v_chosen.version,
    'semantic_version', v_chosen.semantic_version,
    'assigned_reason', 'latest_at_start',
    'was_existing_assignment', false
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_complaint(_id uuid, _resolution text)
 RETURNS complaints
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  before_row public.complaints%ROWTYPE;
  after_row public.complaints%ROWTYPE;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='28000'; END IF;
  IF NOT public.has_complaint_perm(actor, 'resolve') THEN
    RAISE EXCEPTION 'permission denied: complaint_management.resolve' USING ERRCODE='42501';
  END IF;
  IF _resolution IS NULL OR length(btrim(_resolution)) < 5 THEN
    RAISE EXCEPTION 'resolution notes required (min 5 chars)' USING ERRCODE='22023';
  END IF;
  SELECT * INTO before_row FROM public.complaints WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'complaint not found' USING ERRCODE='P0002'; END IF;
  IF before_row.status NOT IN ('submitted','under_investigation','resolved') THEN
    RAISE EXCEPTION 'invalid transition from % to resolved', before_row.status USING ERRCODE='22023';
  END IF;

  UPDATE public.complaints
     SET status = 'resolved',
         resolution = btrim(_resolution),
         resolved_at = COALESCE(resolved_at, now()),
         updated_at = now()
   WHERE id = _id
  RETURNING * INTO after_row;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value)
  VALUES (actor, 'complaint.resolved', 'complaint', _id,
          jsonb_build_object('status', before_row.status),
          jsonb_build_object('status', after_row.status, 'resolution', after_row.resolution));
  RETURN after_row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_complaint(_id uuid, _resolution text, _expected_updated_at timestamp with time zone)
 RETURNS complaints
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  before_row public.complaints%ROWTYPE;
  after_row  public.complaints%ROWTYPE;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='28000'; END IF;
  IF NOT public.has_complaint_perm(actor, 'resolve') THEN
    RAISE EXCEPTION 'permission denied: complaint_management.resolve' USING ERRCODE='42501';
  END IF;
  IF _resolution IS NULL OR length(btrim(_resolution)) < 5 THEN
    RAISE EXCEPTION 'resolution notes required (min 5 chars)' USING ERRCODE='22023';
  END IF;
  PERFORM public._assert_complaint_fresh(_id, _expected_updated_at);
  SELECT * INTO before_row FROM public.complaints WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'complaint not found' USING ERRCODE='P0002'; END IF;
  IF before_row.status NOT IN ('submitted','under_investigation','resolved') THEN
    RAISE EXCEPTION 'invalid transition from % to resolved', before_row.status USING ERRCODE='22023';
  END IF;

  UPDATE public.complaints
     SET status = 'resolved',
         resolution = btrim(_resolution),
         resolved_at = COALESCE(resolved_at, now()),
         updated_at = now()
   WHERE id = _id
  RETURNING * INTO after_row;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value)
  VALUES (actor, 'complaint.resolved', 'complaint', _id,
          jsonb_build_object('status', before_row.status),
          jsonb_build_object('status', after_row.status, 'resolution', after_row.resolution));
  RETURN after_row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_complaint_entity_context(_complaint_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_c record;
  v_lic record;
  v_plu record;
  v_app record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT id, licensee_id, complainant_id INTO v_c
  FROM public.complaints WHERE id = _complaint_id;
  IF v_c.id IS NULL THEN
    RETURN jsonb_build_object('kind','none','source','not_found');
  END IF;

  IF NOT (
    public.has_complaint_perm(v_uid, 'view')
    OR public.external_can_access_complaint(v_uid, _complaint_id, 'view')
  ) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;

  IF v_c.licensee_id IS NOT NULL THEN
    SELECT l.id, l.name, li.license_number
      INTO v_lic
      FROM public.licensees l
      LEFT JOIN public.licenses li ON li.id = l.license_id
     WHERE l.id = v_c.licensee_id;
    RETURN jsonb_build_object(
      'kind','licensed',
      'source','complaint.licensee_id',
      'licensee_id', v_c.licensee_id,
      'entity_name', v_lic.name,
      'license_number', v_lic.license_number
    );
  END IF;

  IF v_c.complainant_id IS NOT NULL THEN
    -- Licensed entity linked to the submitter's own profile
    SELECT l.id, l.name, li.license_number
      INTO v_lic
      FROM public.profiles p
      JOIN public.licensees l ON l.id = p.licensee_id
      LEFT JOIN public.licenses li ON li.id = l.license_id
     WHERE p.id = v_c.complainant_id
     LIMIT 1;

    IF v_lic.id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'kind','licensed',
        'source','profile.licensee_id',
        'licensee_id', v_lic.id,
        'entity_name', v_lic.name,
        'license_number', v_lic.license_number
      );
    END IF;

    -- Licensed entity created from this applicant's approved application
    SELECT l.id, l.name, li.license_number
      INTO v_lic
      FROM public.licensees l
      LEFT JOIN public.licenses li ON li.id = l.license_id
     WHERE l.applicant_id = v_c.complainant_id
     ORDER BY (l.status = 'active') DESC, l.created_at DESC
     LIMIT 1;

    IF v_lic.id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'kind','licensed',
        'source','licensee.applicant_id',
        'licensee_id', v_lic.id,
        'entity_name', v_lic.name,
        'license_number', v_lic.license_number
      );
    END IF;

    SELECT u.full_name, u.entity_name, u.status
      INTO v_plu
      FROM public.pre_license_users u
     WHERE u.id = v_c.complainant_id;

    IF v_plu.entity_name IS NOT NULL OR v_plu.full_name IS NOT NULL THEN
      SELECT a.application_number, a.status
        INTO v_app
        FROM public.applications a
       WHERE a.applicant_id = v_c.complainant_id
       ORDER BY (a.status = 'approved') DESC, a.created_at DESC
       LIMIT 1;

      RETURN jsonb_build_object(
        'kind','applicant',
        'source','pre_license_user',
        'entity_name', COALESCE(v_plu.entity_name, v_plu.full_name),
        'application_number', v_app.application_number,
        'application_status', v_app.status
      );
    END IF;
  END IF;

  RETURN jsonb_build_object('kind','none','source','unresolved');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_effective_threshold(_return_config_id uuid, _metric_key text, _as_of date DEFAULT CURRENT_DATE, _sector_id uuid DEFAULT NULL::uuid, _return_type_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF prudential_thresholds
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT * FROM public.prudential_thresholds t
   WHERE t.metric_key = _metric_key AND t.is_active = true
     AND (t.return_config_id = _return_config_id OR t.return_config_id IS NULL)
     AND (t.sector_id IS NULL OR t.sector_id = _sector_id)
     AND (t.return_type_id IS NULL OR t.return_type_id = _return_type_id)
     AND t.effective_from <= _as_of
     AND (t.effective_to IS NULL OR t.effective_to >= _as_of)
   ORDER BY (t.return_config_id = _return_config_id) DESC,
            (t.sector_id = _sector_id) DESC,
            (t.return_type_id = _return_type_id) DESC,
            t.effective_from DESC
   LIMIT 1;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_license_action_form(_action_type text, _regulator_id uuid, _sector_id uuid, _sub_sector_id uuid, _category_id uuid)
 RETURNS TABLE(id uuid, form_template_id uuid, is_required boolean, match_score integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT c.id, c.form_template_id, c.is_required,
    ( (CASE WHEN c.category_id   IS NOT NULL AND c.category_id   = _category_id   THEN 8 ELSE 0 END)
    + (CASE WHEN c.sub_sector_id IS NOT NULL AND c.sub_sector_id = _sub_sector_id THEN 4 ELSE 0 END)
    + (CASE WHEN c.sector_id     IS NOT NULL AND c.sector_id     = _sector_id     THEN 2 ELSE 0 END)
    + (CASE WHEN c.regulator_id  IS NOT NULL AND c.regulator_id  = _regulator_id  THEN 1 ELSE 0 END)
    ) AS match_score
  FROM public.license_action_form_configs c
  WHERE c.is_active = true
    AND c.license_action_type = _action_type
    AND (c.category_id   IS NULL OR c.category_id   = _category_id)
    AND (c.sub_sector_id IS NULL OR c.sub_sector_id = _sub_sector_id)
    AND (c.sector_id     IS NULL OR c.sector_id     = _sector_id)
    AND (c.regulator_id  IS NULL OR c.regulator_id  = _regulator_id)
  ORDER BY match_score DESC, c.updated_at DESC
  LIMIT 1
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_registration_workflow(_sector_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_workflow_id uuid;
  v_regulator_id uuid;
BEGIN
  IF _sector_id IS NOT NULL THEN
    SELECT regulator_id INTO v_regulator_id FROM public.sectors WHERE id = _sector_id;

    -- exact sector match
    SELECT id INTO v_workflow_id FROM public.approval_workflows
     WHERE entity_type = 'registration' AND is_active = true AND sector_id = _sector_id
     ORDER BY updated_at DESC LIMIT 1;
    IF v_workflow_id IS NOT NULL THEN RETURN v_workflow_id; END IF;

    -- same regulator (any sector)
    IF v_regulator_id IS NOT NULL THEN
      SELECT id INTO v_workflow_id FROM public.approval_workflows
       WHERE entity_type = 'registration' AND is_active = true
         AND regulator_id = v_regulator_id
       ORDER BY updated_at DESC LIMIT 1;
      IF v_workflow_id IS NOT NULL THEN RETURN v_workflow_id; END IF;
    END IF;
  END IF;

  -- global fallback
  SELECT id INTO v_workflow_id FROM public.approval_workflows
   WHERE entity_type = 'registration' AND is_active = true
     AND sector_id IS NULL AND regulator_id IS NULL
   ORDER BY updated_at DESC LIMIT 1;
  IF v_workflow_id IS NOT NULL THEN RETURN v_workflow_id; END IF;

  -- last-resort: any active registration workflow
  SELECT id INTO v_workflow_id FROM public.approval_workflows
   WHERE entity_type = 'registration' AND is_active = true
   ORDER BY updated_at DESC LIMIT 1;
  RETURN v_workflow_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_return_form_version(_return_submission_id uuid, _template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_return record;
  v_is_internal boolean;
  v_has_ppoc_access boolean := false;
  v_assignment record;
  v_legacy_id uuid;
  v_chosen record;
  v_now timestamptz := now();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;

  IF _return_submission_id IS NULL OR _template_id IS NULL THEN
    RETURN jsonb_build_object('error','return_submission_id and template_id are required','code','BAD_REQUEST','http',400);
  END IF;

  v_is_internal := public.has_role(v_uid, 'super_admin'::app_role)
                OR public.has_role(v_uid, 'admin'::app_role)
                OR public.has_role(v_uid, 'supervisor'::app_role)
                OR public.has_role(v_uid, 'licensing_officer'::app_role)
                OR public.has_role(v_uid, 'analyst'::app_role);

  SELECT id, created_by, entity_id, workflow_status
    INTO v_return
    FROM public.returns_filed
   WHERE id = _return_submission_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Return not found','code','NOT_FOUND','http',404);
  END IF;

  IF v_return.entity_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.ppoc_entity_mappings pem
      WHERE pem.ppoc_user_id = v_uid
        AND pem.licensee_id = v_return.entity_id
        AND pem.is_active = true
    ) INTO v_has_ppoc_access;
  END IF;

  IF NOT v_is_internal AND v_return.created_by <> v_uid AND NOT v_has_ppoc_access THEN
    RETURN jsonb_build_object('error','You do not have access to this return','code','FORBIDDEN','http',403);
  END IF;

  SELECT rfv.id,
         rfv.version_id,
         fv.id AS form_version_id,
         fv.template_id AS form_version_template_id,
         fv.version,
         fv.semantic_version
    INTO v_assignment
    FROM public.return_form_versions rfv
    LEFT JOIN public.form_versions fv ON fv.id = rfv.version_id
   WHERE rfv.return_id = _return_submission_id
     AND rfv.template_id = _template_id
     AND rfv.status = 'active'
   ORDER BY rfv.created_at DESC
   LIMIT 1;

  IF FOUND THEN
    IF v_assignment.form_version_id IS NULL OR v_assignment.form_version_template_id IS DISTINCT FROM _template_id THEN
      RETURN jsonb_build_object(
        'error','The assigned form version could not be found. Please contact support.',
        'code','PINNED_VERSION_MISSING','http',404,
        'return_submission_id', _return_submission_id,
        'template_id', _template_id,
        'version_id', v_assignment.version_id
      );
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'http', 200,
      'return_submission_id', _return_submission_id,
      'template_id', _template_id,
      'version_id', v_assignment.version_id,
      'version_number', v_assignment.version,
      'semantic_version', v_assignment.semantic_version,
      'assigned_reason', 'resumed_existing',
      'was_existing_assignment', true
    );
  END IF;

  SELECT rfd.form_version_id AS version_id,
         fv.template_id,
         fv.version,
         fv.semantic_version
    INTO v_chosen
    FROM public.return_form_data rfd
    LEFT JOIN public.form_versions fv ON fv.id = rfd.form_version_id
   WHERE rfd.return_id = _return_submission_id
     AND rfd.form_id = _template_id
     AND rfd.form_version_id IS NOT NULL
   ORDER BY rfd.updated_at DESC, rfd.created_at DESC
   LIMIT 1;

  IF FOUND THEN
    IF v_chosen.version_id IS NULL OR v_chosen.template_id IS DISTINCT FROM _template_id THEN
      RETURN jsonb_build_object(
        'error','The assigned form version could not be found. Please contact support.',
        'code','PINNED_VERSION_MISSING','http',404,
        'return_submission_id', _return_submission_id,
        'template_id', _template_id,
        'version_id', v_chosen.version_id
      );
    END IF;

    INSERT INTO public.return_form_versions (
      return_id,
      template_id,
      version_id,
      assigned_reason,
      assigned_by,
      locked_at,
      status
    )
    VALUES (
      _return_submission_id,
      _template_id,
      v_chosen.version_id,
      'migrated_from_return_form_data',
      v_uid,
      v_now,
      'active'
    )
    ON CONFLICT DO NOTHING;

    RETURN jsonb_build_object(
      'success', true,
      'http', 200,
      'return_submission_id', _return_submission_id,
      'template_id', _template_id,
      'version_id', v_chosen.version_id,
      'version_number', v_chosen.version,
      'semantic_version', v_chosen.semantic_version,
      'assigned_reason', 'resumed_existing',
      'was_existing_assignment', true
    );
  END IF;

  SELECT fv.id, fv.version, fv.semantic_version
    INTO v_chosen
    FROM public.form_versions fv
   WHERE fv.template_id = _template_id
     AND fv.status = 'published'
     AND (fv.effective_from IS NULL OR fv.effective_from <= v_now)
     AND (
       fv.effective_until IS NULL
       OR (date_trunc('day', fv.effective_until) + interval '1 day' - interval '1 microsecond') >= v_now
     )
   ORDER BY fv.version DESC, COALESCE(fv.published_at, fv.created_at) DESC, fv.id DESC
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'error','No active form version is available for this form. Please contact support.',
      'code','NO_ACTIVE_VERSION','http',409,
      'return_submission_id', _return_submission_id,
      'template_id', _template_id
    );
  END IF;

  INSERT INTO public.return_form_versions (
    return_id,
    template_id,
    version_id,
    assigned_reason,
    assigned_by,
    locked_at,
    status
  )
  VALUES (
    _return_submission_id,
    _template_id,
    v_chosen.id,
    'latest_at_start',
    v_uid,
    v_now,
    'active'
  )
  ON CONFLICT DO NOTHING;

  PERFORM public.create_audit_log(
    v_uid,
    'form_version_assigned',
    'return',
    _return_submission_id::text,
    NULL,
    jsonb_build_object(
      'template_id', _template_id,
      'version_id', v_chosen.id,
      'version_number', v_chosen.version,
      'assigned_reason', 'latest_at_start'
    ),
    NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'http', 200,
    'return_submission_id', _return_submission_id,
    'template_id', _template_id,
    'version_id', v_chosen.id,
    'version_number', v_chosen.version,
    'semantic_version', v_chosen.semantic_version,
    'assigned_reason', 'latest_at_start',
    'was_existing_assignment', false
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_return_workflow(_return_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sector uuid;
  v_sub uuid;
  v_regulator uuid;
  v_workflow_id uuid;
BEGIN
  SELECT rf.sector_id,
         COALESCE(rf.subsector_id, rcs.subsector_id, rcn.sub_sector_id),
         COALESCE(s.regulator_id, s2.regulator_id, rcn.regulator_id)
    INTO v_sector, v_sub, v_regulator
    FROM public.returns_filed rf
    LEFT JOIN public.return_configs rcs ON rcs.id = rf.return_configuration_id
    LEFT JOIN public.return_configurations rcn ON rcn.id = rf.return_configuration_id
    LEFT JOIN public.sectors s ON s.id = rf.sector_id
    LEFT JOIN public.sectors s2 ON s2.id = rcs.sector_id
   WHERE rf.id = _return_id;

  IF v_sector IS NULL THEN
    v_sector := (SELECT rcs.sector_id FROM public.returns_filed rf
                   LEFT JOIN public.return_configs rcs ON rcs.id = rf.return_configuration_id
                  WHERE rf.id = _return_id);
  END IF;

  -- A workflow's scoped column matches when it's NULL (covers everything below
  -- it) OR equal to the return's value. When the return itself has no value
  -- for a given scope (v_* IS NULL), we accept any workflow at that scope
  -- level rather than refusing to route — the admin's scoping intent still
  -- wins via the ORDER BY below (most-specific match first).
  SELECT id INTO v_workflow_id
    FROM public.approval_workflows
   WHERE entity_type IN ('return', 'compliance')
     AND is_active = true
     AND (regulator_id IS NULL OR v_regulator IS NULL OR regulator_id = v_regulator)
     AND (sector_id IS NULL OR v_sector IS NULL OR sector_id = v_sector)
     AND (sub_sector_id IS NULL OR v_sub IS NULL OR sub_sector_id = v_sub)
     AND category_id IS NULL
   ORDER BY (sub_sector_id IS NOT NULL AND sub_sector_id = v_sub)::int DESC,
            (sector_id IS NOT NULL AND sector_id = v_sector)::int DESC,
            (regulator_id IS NOT NULL AND regulator_id = v_regulator)::int DESC,
            created_at ASC
   LIMIT 1;

  RETURN v_workflow_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_review_comment(_comment_id uuid, _resolved boolean)
 RETURNS review_comments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c public.review_comments%ROWTYPE;
BEGIN
  SELECT * INTO c FROM public.review_comments WHERE id = _comment_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REVIEW_NOT_FOUND'; END IF;
  PERFORM public._assert_review_action(auth.uid(), c.entity_type, c.entity_id, c.workflow_step_id, NULL,
    CASE WHEN _resolved THEN 'resolve' ELSE 'reopen' END);
  UPDATE public.review_comments
     SET status = CASE WHEN _resolved THEN 'resolved' ELSE 'open' END,
         resolved_by = CASE WHEN _resolved THEN auth.uid() ELSE NULL END,
         resolved_at = CASE WHEN _resolved THEN now() ELSE NULL END
   WHERE id = _comment_id RETURNING * INTO c;
  RETURN c;
END $function$
;
CREATE OR REPLACE FUNCTION public.resolve_stage_sla(_process_type text, _stage_name text, _step_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(sla_hours numeric, sla_source text, sla_config_id uuid, calendar_profile_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cfg RECORD;
  v_step_hours integer;
BEGIN
  SELECT c.id, c.sla_duration, c.sla_unit, c.calendar_profile_id
    INTO v_cfg
  FROM public.sla_configurations c
  WHERE c.active
    AND c.process_type = _process_type
    AND lower(trim(c.stage_name)) = lower(trim(COALESCE(_stage_name, '')))
  LIMIT 1;

  IF v_cfg.id IS NOT NULL THEN
    RETURN QUERY SELECT
      CASE WHEN v_cfg.sla_unit = 'days' THEN v_cfg.sla_duration * 24.0 ELSE v_cfg.sla_duration::numeric END,
      'configuration'::text,
      v_cfg.id,
      v_cfg.calendar_profile_id;
    RETURN;
  END IF;

  IF _step_id IS NOT NULL THEN
    SELECT s.sla_hours INTO v_step_hours FROM public.approval_steps s WHERE s.id = _step_id;
  END IF;

  RETURN QUERY SELECT v_step_hours::numeric, 'step'::text, NULL::uuid, NULL::uuid;
END; $function$
;
CREATE OR REPLACE FUNCTION public.resolve_user_display_names(_ids uuid[])
 RETURNS TABLE(id uuid, display_name text, email text, kind text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with caller as (
    select auth.uid() as uid,
           exists (select 1 from public.user_roles ur where ur.user_id = auth.uid()) as is_staff
  )
  select p.id,
         coalesce(nullif(p.full_name, ''), p.email, '') as display_name,
         p.email,
         'staff'::text as kind
  from public.profiles p, caller c
  where p.id = any(_ids)
    and c.uid is not null
    and (c.is_staff or p.id = c.uid)
  union all
  select u.id,
         coalesce(nullif(u.full_name, ''), u.email, '') as display_name,
         u.email,
         'external'::text as kind
  from public.pre_license_users u, caller c
  where u.id = any(_ids)
    and c.uid is not null
    and (c.is_staff or u.id = c.uid)
$function$
;
CREATE OR REPLACE FUNCTION public.restore_prudential_ratio(_ratio_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row public.prudential_ratios;
BEGIN
  IF NOT public.can_manage_prudential_config(auth.uid()) THEN
    RAISE EXCEPTION 'You do not have permission to manage prudential configuration';
  END IF;
  SELECT * INTO _row FROM public.prudential_ratios WHERE id=_ratio_id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Ratio not found'; END IF;
  UPDATE public.prudential_ratios SET is_active=true, updated_at=now() WHERE id=_ratio_id;
  PERFORM public.log_compliance_audit('UPDATE','prudential_ratios',_ratio_id::text,to_jsonb(_row),NULL,'Ratio restored',NULL,NULL,jsonb_build_object('event','RATIO_RESTORED'));
END $function$
;
CREATE OR REPLACE FUNCTION public.restore_prudential_threshold(_threshold_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row public.prudential_thresholds;
BEGIN
  IF NOT public.can_manage_prudential_config(auth.uid()) THEN RAISE EXCEPTION 'Not authorised to manage prudential configuration'; END IF;
  SELECT * INTO _row FROM public.prudential_thresholds WHERE id=_threshold_id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Threshold not found'; END IF;
  PERFORM set_config('app.version_maintenance','on',true);
  UPDATE public.prudential_thresholds SET is_active=true, effective_to=NULL, updated_at=now() WHERE id=_threshold_id;
  UPDATE public.prudential_threshold_versions SET effective_to=NULL
    WHERE threshold_id=_threshold_id
      AND version = (SELECT MAX(version) FROM public.prudential_threshold_versions WHERE threshold_id=_threshold_id);
  PERFORM set_config('app.version_maintenance','off',true);
  PERFORM public.log_compliance_audit('UPDATE','prudential_thresholds',_threshold_id::text,to_jsonb(_row),NULL,'Threshold restored',NULL,NULL,jsonb_build_object('event','THRESHOLD_RESTORED'));
END $function$
;
CREATE OR REPLACE FUNCTION public.restore_validation_rule(_rule_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _next integer; _def jsonb;
BEGIN
  IF NOT public.can_manage_returns_config(auth.uid()) THEN
    RAISE EXCEPTION 'You do not have permission to manage returns configuration';
  END IF;
  PERFORM set_config('app.version_maintenance','on',true);
  UPDATE public.return_validation_rules SET is_active = true, updated_at = now() WHERE id = _rule_id;
  UPDATE public.return_validation_rule_versions SET is_current = false WHERE rule_id = _rule_id AND is_current;
  SELECT COALESCE(MAX(version),0)+1 INTO _next FROM public.return_validation_rule_versions WHERE rule_id = _rule_id;
  SELECT to_jsonb(r.*) INTO _def FROM public.return_validation_rules r WHERE r.id = _rule_id;
  INSERT INTO public.return_validation_rule_versions(rule_id, version, definition, published_by, is_current)
    VALUES (_rule_id, _next, _def || jsonb_build_object('archived', false), auth.uid(), true);
  UPDATE public.return_validation_rules SET current_version = _next WHERE id = _rule_id;
  PERFORM set_config('app.version_maintenance','off',true);
  PERFORM public.log_compliance_audit('UPDATE','return_validation_rules', _rule_id::text, NULL, _def,
    'Rule restored', NULL, NULL, jsonb_build_object('event','RULE_RESTORED','version',_next));
END $function$
;
CREATE OR REPLACE FUNCTION public.resubmit_return(_return_id uuid, _actor_id uuid, _comments text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ret record;
  v_instance record;
  v_first_step uuid;
  v_closed_count int := 0;
BEGIN
  IF _actor_id IS NULL THEN
    RETURN jsonb_build_object('error','UNAUTHORIZED','code','UNAUTHORIZED','http',401);
  END IF;

  SELECT id, workflow_status, workflow_id, current_step_id
    INTO v_ret
    FROM public.returns_filed
   WHERE id = _return_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Return not found','code','NOT_FOUND','http',404);
  END IF;

  IF upper(v_ret.workflow_status::text) <> 'TBR' THEN
    RETURN jsonb_build_object('error','Return is not awaiting resubmission','code','INVALID_STATUS','http',409);
  END IF;

  WITH closed AS (
    UPDATE public.return_requests
       SET status = 'resolved', resolved_at = now()
     WHERE return_id = _return_id
       AND status = 'active'
     RETURNING id
  )
  SELECT count(*) INTO v_closed_count FROM closed;

  SELECT id, workflow_id, current_step_id, status
    INTO v_instance
    FROM public.workflow_instances
   WHERE entity_id = _return_id
     AND entity_type = 'return'
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE;

  IF FOUND THEN
    SELECT id INTO v_first_step
      FROM public.approval_steps
     WHERE workflow_id = v_instance.workflow_id
     ORDER BY step_order ASC
     LIMIT 1;

    UPDATE public.workflow_instances
       SET status = 'active',
           current_step_id = v_first_step,
           completed_at = NULL,
           updated_at = now()
     WHERE id = v_instance.id;

    UPDATE public.returns_filed
       SET workflow_status = 'SUB'::public.return_workflow_status,
           workflow_id = v_instance.workflow_id,
           current_step_id = v_first_step,
           submit_date = now(),
           updated_by = _actor_id,
           updated_at = now()
     WHERE id = _return_id;

    INSERT INTO public.return_audit_log
      (return_id, action, previous_status, new_status, comments, performed_by,
       previous_step_id, new_step_id, actor_role, metadata, event_key, source)
    VALUES
      (_return_id, 'workflow_step_assigned', 'TBR', 'SUB',
       'Workflow reopened at first step on resubmission', _actor_id,
       v_ret.current_step_id, v_first_step, 'licensee',
       jsonb_build_object('workflow_id', v_instance.workflow_id, 'instance_id', v_instance.id),
       'return.workflow_step_assigned', 'rpc:resubmit_return');

    IF v_first_step IS DISTINCT FROM v_ret.current_step_id THEN
      INSERT INTO public.return_audit_log
        (return_id, action, previous_status, new_status, comments, performed_by,
         previous_step_id, new_step_id, actor_role, metadata, event_key, source)
      VALUES
        (_return_id, 'workflow_step_changed', 'TBR', 'SUB',
         'Workflow step changed on resubmission', _actor_id,
         v_ret.current_step_id, v_first_step, 'licensee',
         jsonb_build_object('workflow_id', v_instance.workflow_id, 'instance_id', v_instance.id),
         'return.workflow_step_changed', 'rpc:resubmit_return');
    END IF;
  ELSE
    UPDATE public.returns_filed
       SET workflow_status = 'SUB'::public.return_workflow_status,
           submit_date = now(),
           updated_by = _actor_id,
           updated_at = now()
     WHERE id = _return_id;
  END IF;

  INSERT INTO public.return_audit_log
    (return_id, action, previous_status, new_status, comments, performed_by, actor_role, metadata, event_key, source)
  VALUES
    (_return_id, 'return_resubmitted', v_ret.workflow_status::text, 'SUB',
     COALESCE(_comments, 'Return resubmitted by licensee'), _actor_id,
     'licensee', '{}'::jsonb, 'return.resubmitted', 'rpc:resubmit_return'),
    (_return_id, 'status_changed', v_ret.workflow_status::text, 'SUB',
     'Status transition on resubmission', _actor_id,
     'licensee', jsonb_build_object('from', v_ret.workflow_status::text, 'to', 'SUB'),
     'return.status_changed', 'rpc:resubmit_return');

  IF v_closed_count > 0 THEN
    INSERT INTO public.return_audit_log
      (return_id, action, previous_status, new_status, comments, performed_by, actor_role, metadata, event_key, source)
    VALUES
      (_return_id, 'edit_request_closed', v_ret.workflow_status::text, 'SUB',
       'Active edit request resolved on resubmission', _actor_id,
       'licensee', jsonb_build_object('closed_count', v_closed_count),
       'return.edit_request_closed', 'rpc:resubmit_return');
  END IF;

  RETURN jsonb_build_object('success', true, 'http', 200, 'edit_requests_closed', v_closed_count);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resume_registration_workflow(_registration_id uuid, _actor_id uuid, _comments text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reg record;
  v_instance record;
  v_now timestamptz := now();
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  IF _actor_id IS NULL THEN
    RETURN jsonb_build_object('error','UNAUTHORIZED','code','UNAUTHORIZED','http',401);
  END IF;

  SELECT id, status, user_id, registration_reference
    INTO v_reg
    FROM public.registrations
   WHERE id = _registration_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Registration not found','code','NOT_FOUND','http',404);
  END IF;

  -- Only the owning applicant may resume their own paused workflow via this RPC.
  IF v_reg.user_id IS DISTINCT FROM _actor_id THEN
    RETURN jsonb_build_object('error','Only the applicant can resume this workflow','code','FORBIDDEN','http',403);
  END IF;

  SELECT id, workflow_id, workflow_version_id, current_step_id, status
    INTO v_instance
    FROM public.workflow_instances
   WHERE entity_id = _registration_id
     AND entity_type = 'registration'
     AND status IN ('active','paused')
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE;

  -- No instance: nothing to resume (registration may never have been routed yet).
  IF NOT FOUND THEN
    UPDATE public.registrations
       SET status = 'pending_review', updated_at = v_now
     WHERE id = _registration_id;
    RETURN jsonb_build_object('success', true, 'resumed', false, 'matched', false, 'http', 200);
  END IF;

  IF v_instance.status = 'paused' THEN
    UPDATE public.workflow_instances
       SET status = 'active', updated_at = v_now
     WHERE id = v_instance.id;
  END IF;

  -- Set registration back to in_progress so the approver UI no longer renders the paused/awaiting-applicant state.
  UPDATE public.registrations
     SET status = 'in_progress', updated_at = v_now
   WHERE id = _registration_id;

  -- Audit trail: record an applicant-side resubmission action against the current step.
  IF v_instance.current_step_id IS NOT NULL THEN
    INSERT INTO public.approval_actions (
      workflow_instance_id, step_id, actor_id, action, action_type, comments,
      entity_type, entity_id, workflow_version_id
    ) VALUES (
      v_instance.id, v_instance.current_step_id, _actor_id,
      'resubmit', 'resubmit', COALESCE(_comments, 'Applicant resubmitted registration'),
      'registration', _registration_id, v_instance.workflow_version_id
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'resumed', true,
    'matched', true,
    'instance_id', v_instance.id,
    'workflow_id', v_instance.workflow_id,
    'current_step_id', v_instance.current_step_id,
    'http', 200
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.retire_form_definition(_template_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.wb_require('form_management','retire');
  PERFORM set_config('app.form_publish_context','trusted', true);
  UPDATE public.form_templates SET status = 'archived', updated_at = now() WHERE id = _template_id;
  UPDATE public.form_versions SET status = 'retired', effective_until = now()
   WHERE template_id = _template_id AND status IN ('published','draft');
  PERFORM public.create_audit_log(auth.uid(),'form.version.retired','form_template',_template_id::text,NULL,
    jsonb_build_object('reason',_reason),NULL);
  RETURN jsonb_build_object('success',true,'template_id',_template_id);
END $function$
;
CREATE OR REPLACE FUNCTION public.retry_complaint_triage(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_complaint_perm(v_uid,'triage') THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;
  -- Mark for reprocessing; the edge function scheduler picks these up.
  UPDATE public.complaints
     SET triage_source = 'manual_retry', updated_at = now()
   WHERE id = _id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid,'complaint.triage_retry_requested','complaint',_id, '{}'::jsonb);
END; $function$
;
CREATE OR REPLACE FUNCTION public.retry_dead_notification_outbox(_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count int;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin'::app_role)
          OR public.has_role(auth.uid(), 'super_admin'::app_role)) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  WITH revived AS (
    UPDATE public.notification_outbox
       SET status = 'pending',
           retry_count = 0,
           last_error = NULL,
           next_attempt_at = now(),
           claimed_at = NULL,
           claimed_by = NULL
     WHERE id = ANY(_ids) AND status = 'dead'
    RETURNING id
  )
  SELECT count(*) INTO v_count FROM revived;
  RETURN v_count;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.return_filing_version_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_immutable THEN
      RAISE EXCEPTION 'Submitted filing versions are durable regulatory evidence and cannot be deleted'
        USING ERRCODE='42501';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.is_immutable AND OLD.status IN ('ACCEPTED','REJECTED','SUPERSEDED')
     AND (NEW.version_number <> OLD.version_number OR NEW.return_filing_id <> OLD.return_filing_id
          OR NEW.submitted_at <> OLD.submitted_at) THEN
    RAISE EXCEPTION 'Accepted filing version content is immutable' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.return_metric_value_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_status text;
BEGIN
  SELECT status INTO v_status FROM public.return_filing_versions
   WHERE id = COALESCE(OLD.return_filing_version_id, NEW.return_filing_version_id);
  IF v_status IN ('ACCEPTED','SUPERSEDED','REJECTED') THEN
    RAISE EXCEPTION 'Metric values of an accepted filing version are immutable' USING ERRCODE='42501';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $function$
;
CREATE OR REPLACE FUNCTION public.return_status_is_submitted_lifecycle(_status text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT lower(coalesce(_status, '')) IN (
    'submitted', 'under_review', 'reviewed', 'approved', 'rejected',
    'accepted', 'archived', 'closed', 'completed', 'final'
  );
$function$
;
CREATE OR REPLACE FUNCTION public.returns_adopt_legacy_config(_config_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; t record; v_def uuid; v_code text; v_freq text;
BEGIN
  PERFORM public.returns_require('manage_config');
  SELECT * INTO c FROM public.return_configs WHERE id = _config_id;
  IF c.id IS NULL THEN RAISE EXCEPTION 'Legacy configuration not found'; END IF;
  IF c.return_type_id IS NULL THEN
    RAISE EXCEPTION 'This legacy configuration has no return type and cannot be adopted without a decision';
  END IF;
  SELECT * INTO t FROM public.return_types WHERE id = c.return_type_id;

  SELECT id INTO v_def FROM public.return_definitions WHERE legacy_return_config_id = _config_id;
  IF v_def IS NOT NULL THEN RETURN v_def; END IF;

  v_code := upper(regexp_replace(COALESCE(t.code, t.name, 'RETURN') || '-' ||
                                 left(regexp_replace(c.name, '[^A-Za-z0-9]+','','g'), 12),
                                 '[^A-Z0-9\-]', '', 'g'));
  WHILE EXISTS (SELECT 1 FROM public.return_definitions WHERE code = v_code) LOOP
    v_code := v_code || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,3);
  END LOOP;

  v_freq := CASE
    WHEN COALESCE(t.name,'') ILIKE '%month%' THEN 'MONTHLY'
    WHEN COALESCE(t.name,'') ILIKE '%quarter%' THEN 'QUARTERLY'
    WHEN COALESCE(t.name,'') ILIKE '%annual%' OR COALESCE(t.name,'') ILIKE '%year%' THEN 'ANNUAL'
    ELSE 'QUARTERLY' END;

  INSERT INTO public.return_definitions(
    code, name, description, frequency, status, is_active,
    legacy_return_type_id, legacy_return_config_id, created_by)
  VALUES (v_code, c.name, 'Adopted from the legacy return configuration', v_freq,
          CASE WHEN c.status = 'active' THEN 'ACTIVE' ELSE 'DRAFT' END, true,
          c.return_type_id, c.id, auth.uid())
  RETURNING id INTO v_def;

  INSERT INTO public.return_definition_forms(
    return_definition_id, form_template_id, sequence, is_required, tab_name)
  SELECT v_def, cf.form_id, COALESCE(cf.display_order, 1), true, cf.tab_name
    FROM public.return_config_forms cf
   WHERE cf.return_configuration_id = _config_id
     AND EXISTS (SELECT 1 FROM public.form_templates ft WHERE ft.id = cf.form_id)
  ON CONFLICT DO NOTHING;

  UPDATE public.returns_legacy_mappings
     SET canonical_table = 'return_definitions', canonical_id = v_def
   WHERE legacy_table = 'return_configs' AND legacy_id = _config_id;

  PERFORM public.create_audit_log('return_definition', v_def, 'ADOPT_LEGACY_CONFIG',
    jsonb_build_object('legacy_config_id', _config_id));
  RETURN v_def;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_assign_filing(_filing_id uuid, _owner_user_id uuid, _team text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before jsonb; v_after jsonb;
BEGIN
  IF NOT (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(),'returns_management','review')) THEN
    RAISE EXCEPTION 'Not authorised to assign return filings' USING ERRCODE = '42501';
  END IF;
  SELECT jsonb_build_object('assigned_reviewer_id', assigned_reviewer_id, 'assigned_team', assigned_team)
    INTO v_before FROM public.return_filings WHERE id = _filing_id;
  IF v_before IS NULL THEN RAISE EXCEPTION 'Filing not found'; END IF;

  UPDATE public.return_filings
     SET assigned_reviewer_id = _owner_user_id,
         assigned_team = _team,
         assigned_at = now(),
         assigned_by = auth.uid(),
         updated_at = now()
   WHERE id = _filing_id;

  v_after := jsonb_build_object('assigned_reviewer_id', _owner_user_id, 'assigned_team', _team);
  PERFORM public.log_compliance_audit('UPDATE'::compliance_audit_action, 'return_filing',
    _filing_id::text, v_before, v_after, 'Return filing ownership assignment');
  RETURN v_after;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_attach_form_response(_requirement_id uuid, _form_response_id uuid, _completion text DEFAULT 'COMPLETED'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_entity uuid; v_status text;
BEGIN
  SELECT f.entity_id, v.status INTO v_entity, v_status
    FROM public.return_filing_form_requirements r
    JOIN public.return_filing_versions v ON v.id = r.return_filing_version_id
    JOIN public.return_filings f ON f.id = v.return_filing_id
   WHERE r.id = _requirement_id;
  IF v_entity IS NULL THEN RAISE EXCEPTION 'Form requirement not found'; END IF;
  IF NOT public.returns_can_prepare(v_entity) THEN
    RAISE EXCEPTION 'You are not authorised to prepare returns for this entity' USING ERRCODE='42501';
  END IF;
  IF v_status NOT IN ('DRAFT','CORRECTION_REQUESTED') THEN
    RAISE EXCEPTION 'This filing version is no longer editable';
  END IF;

  UPDATE public.return_filing_form_requirements
     SET form_response_id = _form_response_id,
         completion_status = COALESCE(_completion, 'COMPLETED')
   WHERE id = _requirement_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_bind_field_metric(_field_definition_id uuid, _metric_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.returns_require('manage_config');
  UPDATE public.form_field_definitions SET regulatory_metric_id = _metric_id, updated_at = now()
   WHERE id = _field_definition_id;
  PERFORM public.create_audit_log('form_field_definition', _field_definition_id, 'BIND_METRIC',
    jsonb_build_object('regulatory_metric_id', _metric_id));
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_calculate_metrics(_version_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v record; rule record; dep text; v_expr text; v_val numeric;
        v_missing boolean; v_dep_val numeric; v_count int := 0;
BEGIN
  SELECT v2.id, f.entity_id, f.reporting_period_id INTO v
    FROM public.return_filing_versions v2
    JOIN public.return_filings f ON f.id = v2.return_filing_id
   WHERE v2.id = _version_id;
  IF v.id IS NULL THEN RAISE EXCEPTION 'Filing version not found'; END IF;

  FOR rule IN
    SELECT mcr.*, rm.id AS metric_id FROM public.metric_calculation_rules mcr
      JOIN public.regulatory_metrics rm ON rm.id = mcr.regulatory_metric_id
     WHERE mcr.is_active AND rm.is_active
     ORDER BY array_length(mcr.dependency_metric_codes, 1) NULLS FIRST
  LOOP
    v_expr := rule.expression; v_missing := false;
    FOREACH dep IN ARRAY rule.dependency_metric_codes LOOP
      SELECT mv.value_numeric INTO v_dep_val
        FROM public.return_metric_values mv
        JOIN public.regulatory_metrics m2 ON m2.id = mv.regulatory_metric_id
       WHERE mv.return_filing_version_id = _version_id AND m2.code = dep
         AND mv.availability = 'AVAILABLE';
      IF v_dep_val IS NULL THEN v_missing := true; EXIT; END IF;
      v_expr := regexp_replace(v_expr, '\m' || dep || '\M', '(' || v_dep_val::text || ')', 'gi');
    END LOOP;

    IF v_missing THEN
      INSERT INTO public.return_metric_values(
        return_filing_version_id, entity_id, regulatory_metric_id, reporting_period_id,
        availability, availability_reason, source_kind, calculation_rule_id, calculated_at)
      VALUES (_version_id, v.entity_id, rule.metric_id, v.reporting_period_id,
        CASE WHEN rule.on_missing_dependency = 'ERROR' THEN 'ERROR' ELSE 'NOT_AVAILABLE' END,
        'A required input measurement was not reported for this period',
        'CALCULATED', rule.id, now())
      ON CONFLICT (return_filing_version_id, regulatory_metric_id) DO UPDATE
        SET availability = EXCLUDED.availability,
            availability_reason = EXCLUDED.availability_reason,
            calculation_rule_id = EXCLUDED.calculation_rule_id,
            calculated_at = now();
      CONTINUE;
    END IF;

    IF v_expr !~ '^[0-9+\-*/(). ]+$' THEN
      RAISE EXCEPTION 'Formula for metric % could not be resolved safely', rule.metric_id;
    END IF;

    BEGIN
      EXECUTE format('SELECT (%s)::numeric', v_expr) INTO v_val;
    EXCEPTION WHEN OTHERS THEN
      v_val := NULL;
    END;

    INSERT INTO public.return_metric_values(
      return_filing_version_id, entity_id, regulatory_metric_id, reporting_period_id,
      value_numeric, availability, availability_reason, source_kind,
      calculation_rule_id, calculation_inputs, calculated_at)
    VALUES (_version_id, v.entity_id, rule.metric_id, v.reporting_period_id, v_val,
      CASE WHEN v_val IS NULL THEN 'ERROR' ELSE 'AVAILABLE' END,
      CASE WHEN v_val IS NULL THEN 'The formula could not be evaluated for this period' END,
      'CALCULATED', rule.id,
      jsonb_build_object('expression', rule.expression, 'resolved', v_expr), now())
    ON CONFLICT (return_filing_version_id, regulatory_metric_id) DO UPDATE
      SET value_numeric = EXCLUDED.value_numeric,
          availability = EXCLUDED.availability,
          availability_reason = EXCLUDED.availability_reason,
          calculation_rule_id = EXCLUDED.calculation_rule_id,
          calculation_inputs = EXCLUDED.calculation_inputs,
          calculated_at = now();
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_can_file(_entity_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT auth.uid() IS NOT NULL AND (
    public.is_super_admin(auth.uid())
    OR (
      public.sec_is_internal_user(auth.uid())
      AND NOT public.has_external_role(auth.uid())
      AND public.has_permission(auth.uid(), 'returns_management', 'create')
    )
    OR public.entity_membership_capability(auth.uid(), _entity_id, 'returns.submit')
  );
$function$
;
CREATE OR REPLACE FUNCTION public.returns_can_prepare(_entity_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT auth.uid() IS NOT NULL AND (
    public.returns_can_file(_entity_id)
    OR public.entity_membership_capability(auth.uid(), _entity_id, 'prepare_filing')
  );
$function$
;
CREATE OR REPLACE FUNCTION public.returns_can_view_filing_scope(_entity_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.is_super_admin(auth.uid())
      OR public.has_permission(auth.uid(),'returns_management','view')
      OR public.entity_membership_capability(auth.uid(), _entity_id, 'returns.view');
$function$
;
CREATE OR REPLACE FUNCTION public.returns_classify_legacy()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n int;
BEGIN
  PERFORM public.returns_require('manage_config');

  -- Configurations: exact when they carry a return type and sector
  INSERT INTO public.returns_legacy_mappings(
    legacy_table, legacy_id, classification, evidence, decided_by)
  SELECT 'return_configs', c.id,
    CASE WHEN c.return_type_id IS NOT NULL AND c.sector_id IS NOT NULL
           THEN 'EXACT_CANONICAL_MAPPING'
         WHEN c.return_type_id IS NOT NULL THEN 'DERIVABLE_WITH_EVIDENCE'
         ELSE 'AMBIGUOUS' END,
    jsonb_build_object('name', c.name, 'return_type_id', c.return_type_id,
                       'sector_id', c.sector_id, 'status', c.status),
    auth.uid()
    FROM public.return_configs c
  ON CONFLICT (legacy_table, legacy_id) DO NOTHING;

  -- Filings: exact when entity, config and period dates are all present
  INSERT INTO public.returns_legacy_mappings(
    legacy_table, legacy_id, classification, evidence, decided_by)
  SELECT 'returns_filed', rf.id,
    CASE WHEN rf.entity_id IS NOT NULL AND rf.return_configuration_id IS NOT NULL
              AND rf.period_start_date IS NOT NULL AND rf.period_end_date IS NOT NULL
              AND EXISTS (SELECT 1 FROM public.licensees l WHERE l.id = rf.entity_id)
           THEN 'EXACT_CANONICAL_MAPPING'
         WHEN rf.entity_id IS NOT NULL AND rf.return_configuration_id IS NOT NULL
           THEN 'DERIVABLE_WITH_EVIDENCE'
         WHEN rf.entity_id IS NULL THEN 'LEGACY_ONLY'
         ELSE 'AMBIGUOUS' END,
    jsonb_build_object('unique_id', rf.unique_id, 'workflow_status', rf.workflow_status,
                       'return_year', rf.return_year, 'return_period', rf.return_period,
                       'period_start', rf.period_start_date, 'period_end', rf.period_end_date),
    auth.uid()
    FROM public.returns_filed rf
  ON CONFLICT (legacy_table, legacy_id) DO NOTHING;

  SELECT count(*) INTO v_n FROM public.returns_legacy_mappings;
  PERFORM public.create_audit_log('returns_legacy_mappings', gen_random_uuid(), 'CLASSIFY',
    jsonb_build_object('total', v_n));
  RETURN jsonb_build_object('total_classified', v_n);
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_compare_filing_versions(_version_a uuid, _version_b uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE va record; vb record; v_forms jsonb := '[]'::jsonb; v_metrics jsonb; v_val jsonb; v_req jsonb;
        fr record;
BEGIN
  PERFORM public.returns_require('view');
  SELECT v.*, f.filing_reference INTO va
    FROM public.return_filing_versions v JOIN public.return_filings f ON f.id = v.return_filing_id
   WHERE v.id = _version_a;
  SELECT v.*, f.filing_reference INTO vb
    FROM public.return_filing_versions v JOIN public.return_filings f ON f.id = v.return_filing_id
   WHERE v.id = _version_b;
  IF va.id IS NULL OR vb.id IS NULL THEN RAISE EXCEPTION 'Filing version not found'; END IF;
  IF va.return_filing_id <> vb.return_filing_id THEN RAISE EXCEPTION 'Versions belong to different filings'; END IF;

  -- form response field diffs, keyed by template
  FOR fr IN
    SELECT COALESCE(a.form_template_id, b.form_template_id) AS template_id,
           t.name AS template_name,
           a.form_version_id AS a_form_version_id, b.form_version_id AS b_form_version_id,
           a.completion_status AS a_completion, b.completion_status AS b_completion,
           ra.response_data AS a_data, rb.response_data AS b_data
      FROM (SELECT * FROM public.return_filing_form_requirements WHERE return_filing_version_id = _version_a) a
      FULL JOIN (SELECT * FROM public.return_filing_form_requirements WHERE return_filing_version_id = _version_b) b
        ON b.form_template_id = a.form_template_id
      LEFT JOIN public.form_templates t ON t.id = COALESCE(a.form_template_id, b.form_template_id)
      LEFT JOIN public.form_responses ra ON ra.id = a.form_response_id
      LEFT JOIN public.form_responses rb ON rb.id = b.form_response_id
  LOOP
    v_forms := v_forms || jsonb_build_object(
      'template_id', fr.template_id,
      'template_name', fr.template_name,
      'a_form_version_id', fr.a_form_version_id,
      'b_form_version_id', fr.b_form_version_id,
      'form_version_pinning_changed', fr.a_form_version_id IS DISTINCT FROM fr.b_form_version_id,
      'a_completion', fr.a_completion,
      'b_completion', fr.b_completion,
      'field_changes', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
                 'field', k,
                 'old_value', (fr.a_data -> k),
                 'new_value', (fr.b_data -> k),
                 'change', CASE
                   WHEN NOT (COALESCE(fr.a_data,'{}'::jsonb) ? k) THEN 'ADDED'
                   WHEN NOT (COALESCE(fr.b_data,'{}'::jsonb) ? k) THEN 'REMOVED'
                   ELSE 'CHANGED' END)
                 ORDER BY k)
          FROM (SELECT jsonb_object_keys(COALESCE(fr.a_data,'{}'::jsonb) || COALESCE(fr.b_data,'{}'::jsonb)) AS k) keys
         WHERE (fr.a_data -> k) IS DISTINCT FROM (fr.b_data -> k)
      ), '[]'::jsonb)
    );
  END LOOP;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'code', m.code, 'name', m.name, 'unit', m.unit,
           'a_value', a.value_numeric, 'b_value', b.value_numeric,
           'a_availability', a.availability, 'b_availability', b.availability,
           'delta', CASE WHEN a.value_numeric IS NOT NULL AND b.value_numeric IS NOT NULL
                         THEN b.value_numeric - a.value_numeric END,
           'changed', a.value_numeric IS DISTINCT FROM b.value_numeric
                      OR a.availability IS DISTINCT FROM b.availability) ORDER BY m.code), '[]'::jsonb)
    INTO v_metrics
    FROM public.regulatory_metrics m
    LEFT JOIN public.return_metric_values a ON a.regulatory_metric_id = m.id AND a.return_filing_version_id = _version_a
    LEFT JOIN public.return_metric_values b ON b.regulatory_metric_id = m.id AND b.return_filing_version_id = _version_b
   WHERE a.id IS NOT NULL OR b.id IS NOT NULL;

  SELECT jsonb_build_object(
    'a', COALESCE((SELECT jsonb_agg(jsonb_build_object('rule_code', rule_code, 'severity', severity,
            'message', message, 'is_blocking', is_blocking) ORDER BY rule_code)
          FROM public.return_filing_validation_results WHERE return_filing_version_id = _version_a), '[]'::jsonb),
    'b', COALESCE((SELECT jsonb_agg(jsonb_build_object('rule_code', rule_code, 'severity', severity,
            'message', message, 'is_blocking', is_blocking) ORDER BY rule_code)
          FROM public.return_filing_validation_results WHERE return_filing_version_id = _version_b), '[]'::jsonb)
  ) INTO v_val;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('request_kind', request_kind, 'message', message,
           'status', status, 'response_text', response_text, 'created_at', created_at,
           'responded_at', responded_at) ORDER BY created_at), '[]'::jsonb)
    INTO v_req
    FROM public.return_filing_requests
   WHERE return_filing_version_id IN (_version_a, _version_b);

  RETURN jsonb_build_object(
    'filing_reference', va.filing_reference,
    'a', jsonb_build_object('id', va.id, 'version_number', va.version_number, 'status', va.status,
           'submitted_at', va.submitted_at, 'accepted_at', va.accepted_at, 'rejected_at', va.rejected_at,
           'rejection_reason', va.rejection_reason, 'declaration_accepted_at', va.declaration_accepted_at,
           'is_immutable', va.is_immutable),
    'b', jsonb_build_object('id', vb.id, 'version_number', vb.version_number, 'status', vb.status,
           'submitted_at', vb.submitted_at, 'accepted_at', vb.accepted_at, 'rejected_at', vb.rejected_at,
           'rejection_reason', vb.rejection_reason, 'declaration_accepted_at', vb.declaration_accepted_at,
           'is_immutable', vb.is_immutable),
    'forms', v_forms,
    'metrics', COALESCE(v_metrics, '[]'::jsonb),
    'validation', v_val,
    'requests', v_req
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_delete_definition_form(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d uuid;
BEGIN
  PERFORM public.returns_require('manage_config');
  SELECT return_definition_id INTO d FROM public.return_definition_forms WHERE id = _id;
  IF d IS NULL THEN RETURN; END IF;
  DELETE FROM public.return_definition_forms WHERE id = _id;
  PERFORM public.create_audit_log('return_definition', d, 'RETURN_DEFINITION_FORM_REMOVED',
    jsonb_build_object('id', _id));
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_derive_entity_obligations(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_created int := 0; v_closed int := 0; r record; v_ent record;
BEGIN
  PERFORM public.returns_require('manage_config');
  SELECT id, sector_id, sub_sector_id, category_id, license_id, lifecycle_stage_id, status
    INTO v_ent FROM public.licensees WHERE id = _entity_id;
  IF v_ent.id IS NULL THEN RAISE EXCEPTION 'Entity not found'; END IF;

  FOR r IN
    SELECT DISTINCT ON (ru.return_definition_id) ru.*, d.frequency AS def_frequency,
           d.due_days_after_period_end AS def_due_days
      FROM public.reporting_obligation_rules ru
      JOIN public.return_definitions d ON d.id = ru.return_definition_id
     WHERE ru.is_active AND d.is_active AND d.status = 'ACTIVE'
       AND ru.effective_from <= CURRENT_DATE
       AND (ru.effective_to IS NULL OR ru.effective_to >= CURRENT_DATE)
       AND (ru.sector_id IS NULL OR ru.sector_id = v_ent.sector_id)
       AND (ru.sub_sector_id IS NULL OR ru.sub_sector_id = v_ent.sub_sector_id)
       AND (ru.category_id IS NULL OR ru.category_id = v_ent.category_id)
       AND (ru.lifecycle_stage_id IS NULL OR ru.lifecycle_stage_id = v_ent.lifecycle_stage_id)
       AND (NOT ru.requires_active_license OR EXISTS (
              SELECT 1 FROM public.entity_licenses el
               WHERE el.entity_id = _entity_id
                 AND (el.effective_to IS NULL OR el.effective_to > now())))
     ORDER BY ru.return_definition_id, ru.priority ASC, ru.effective_from DESC
  LOOP
    IF EXISTS (SELECT 1 FROM public.entity_reporting_obligations o
                WHERE o.entity_id = _entity_id AND o.return_definition_id = r.return_definition_id
                  AND o.status = 'ACTIVE') THEN
      CONTINUE;
    END IF;
    INSERT INTO public.entity_reporting_obligations(
      entity_id, return_definition_id, source_rule_id, origin, frequency,
      due_days_after_period_end, effective_from, created_by)
    VALUES (_entity_id, r.return_definition_id, r.id, 'RULE',
      COALESCE(r.frequency_override, r.def_frequency),
      COALESCE(r.due_days_override, r.def_due_days),
      GREATEST(r.effective_from, CURRENT_DATE), auth.uid())
    ON CONFLICT DO NOTHING;
    v_created := v_created + 1;
  END LOOP;

  -- close obligations whose source rule no longer applies and which have no filings
  UPDATE public.entity_reporting_obligations o
     SET status = 'CLOSED', closed_reason = 'Applicability rule no longer matches', effective_to = CURRENT_DATE
   WHERE o.entity_id = _entity_id AND o.status = 'ACTIVE' AND o.origin = 'RULE'
     AND NOT EXISTS (SELECT 1 FROM public.return_filings f WHERE f.entity_reporting_obligation_id = o.id)
     AND (o.source_rule_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.reporting_obligation_rules ru
         WHERE ru.id = o.source_rule_id AND ru.is_active
           AND (ru.effective_to IS NULL OR ru.effective_to >= CURRENT_DATE)));
  v_closed := 0;

  PERFORM public.create_audit_log('entity', _entity_id, 'DERIVE_REPORTING_OBLIGATIONS',
    jsonb_build_object('created', v_created));
  RETURN jsonb_build_object('created', v_created, 'closed', v_closed);
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_entity_calendar(_entity_id uuid)
 RETURNS TABLE(obligation_id uuid, period_id uuid, definition_code text, definition_name text, frequency text, period_label text, period_start date, period_end date, due_date date, period_status text, filing_id uuid, filing_reference text, filing_status text, current_version_id uuid, is_overdue boolean, days_remaining integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT o.id, p.id, d.code, d.name, o.frequency, p.period_label, p.period_start,
         p.period_end, p.due_date, p.status, f.id, f.filing_reference, f.status,
         (SELECT v.id FROM public.return_filing_versions v
           WHERE v.return_filing_id = f.id ORDER BY v.version_number DESC LIMIT 1),
         (p.due_date < CURRENT_DATE AND COALESCE(f.status,'DRAFT') NOT IN ('ACCEPTED','SUBMITTED','UNDER_REVIEW')),
         (p.due_date - CURRENT_DATE)
    FROM public.entity_reporting_obligations o
    JOIN public.reporting_periods p ON p.entity_reporting_obligation_id = o.id
    JOIN public.return_definitions d ON d.id = o.return_definition_id
    LEFT JOIN public.return_filings f ON f.reporting_period_id = p.id
   WHERE o.entity_id = _entity_id
     AND o.status = 'ACTIVE'
     AND (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(),'returns_management','view')
          OR public.entity_membership_capability(auth.uid(), _entity_id, 'returns.view'))
   ORDER BY p.due_date DESC
   LIMIT 300;
$function$
;
CREATE OR REPLACE FUNCTION public.returns_entity_filing_history(_entity_id uuid)
 RETURNS TABLE(filing_id uuid, filing_reference text, definition_name text, period_label text, period_start date, period_end date, due_date date, status text, status_label text, submitted_at timestamp with time zone, accepted_at timestamp with time zone, current_version_number integer, accepted_version_id uuid, breach_count bigint, metric_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT w.filing_id, w.filing_reference, w.definition_name, w.period_label,
         w.period_start, w.period_end, w.due_date, w.status, w.status_label,
         w.submitted_at, w.accepted_at, w.current_version_number, w.accepted_version_id,
         (SELECT count(*) FROM public.return_threshold_breaches b WHERE b.return_filing_id = w.filing_id),
         (SELECT count(*) FROM public.return_metric_values mv
           WHERE mv.return_filing_version_id = COALESCE(w.accepted_version_id, w.current_version_id))
  FROM public.v_return_filing_workflow_state w
  WHERE w.entity_id = _entity_id
  ORDER BY w.period_end DESC NULLS LAST;
$function$
;
CREATE OR REPLACE FUNCTION public.returns_entity_summary(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_obl int; v_next jsonb; v_overdue int; v_recent jsonb; v_metrics jsonb; v_corr int;
BEGIN
  PERFORM public.returns_require('view');

  SELECT count(*) INTO v_obl FROM public.entity_reporting_obligations
   WHERE entity_id = _entity_id AND status = 'ACTIVE';

  SELECT to_jsonb(x) INTO v_next FROM (
    SELECT d.code AS definition_code, d.name AS definition_name, p.period_label, p.due_date
      FROM public.reporting_periods p
      JOIN public.entity_reporting_obligations o ON o.id = p.entity_reporting_obligation_id
      JOIN public.return_definitions d ON d.id = o.return_definition_id
     WHERE o.entity_id = _entity_id AND o.status = 'ACTIVE'
       AND p.due_date >= CURRENT_DATE
       AND NOT EXISTS (SELECT 1 FROM public.return_filings f
                        WHERE f.reporting_period_id = p.id AND f.status = 'ACCEPTED')
     ORDER BY p.due_date ASC LIMIT 1) x;

  SELECT count(*) INTO v_overdue
    FROM public.reporting_periods p
    JOIN public.entity_reporting_obligations o ON o.id = p.entity_reporting_obligation_id
   WHERE o.entity_id = _entity_id AND o.status = 'ACTIVE' AND p.due_date < CURRENT_DATE
     AND NOT EXISTS (SELECT 1 FROM public.return_filings f
                      WHERE f.reporting_period_id = p.id
                        AND f.status IN ('SUBMITTED','UNDER_REVIEW','ACCEPTED'));

  SELECT COALESCE(jsonb_agg(to_jsonb(y) ORDER BY y.period_end DESC), '[]'::jsonb) INTO v_recent FROM (
    SELECT f.id AS filing_id, f.filing_reference, f.status, f.current_version_number,
           d.code AS definition_code, d.name AS definition_name,
           p.period_label, p.period_end, p.due_date, f.submitted_at
      FROM public.return_filings f
      JOIN public.return_definitions d ON d.id = f.return_definition_id
      JOIN public.reporting_periods p ON p.id = f.reporting_period_id
     WHERE f.entity_id = _entity_id
     ORDER BY p.period_end DESC LIMIT 8) y;

  SELECT COALESCE(jsonb_agg(to_jsonb(z) ORDER BY z.code), '[]'::jsonb) INTO v_metrics FROM (
    SELECT DISTINCT ON (m.code) m.code, m.name, m.unit, mv.value_numeric, mv.availability,
           p.period_label, p.period_end
      FROM public.return_metric_values mv
      JOIN public.regulatory_metrics m ON m.id = mv.regulatory_metric_id
      JOIN public.return_filing_versions v ON v.id = mv.return_filing_version_id
      JOIN public.return_filings f ON f.id = v.return_filing_id
      JOIN public.reporting_periods p ON p.id = f.reporting_period_id
     WHERE mv.entity_id = _entity_id AND f.accepted_version_id = v.id
     ORDER BY m.code, p.period_end DESC) z;

  SELECT count(*) INTO v_corr FROM public.return_filings
   WHERE entity_id = _entity_id AND status = 'CORRECTION_REQUESTED';

  RETURN jsonb_build_object(
    'entity_id', _entity_id,
    'active_obligations', v_obl,
    'next_due', v_next,
    'overdue_count', v_overdue,
    'correction_requested_count', v_corr,
    'recent_filings', v_recent,
    'latest_accepted_metrics', v_metrics);
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_entity_summary(_entity_ids uuid[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH scoped AS (
    SELECT * FROM public.v_return_filing_workflow_state
    WHERE entity_id = ANY(COALESCE(_entity_ids, ARRAY[]::uuid[]))
  )
  SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM scoped),
    'draft', (SELECT count(*) FROM scoped WHERE status = 'DRAFT'),
    'pending_review', (SELECT count(*) FROM scoped WHERE status IN ('SUBMITTED','UNDER_REVIEW')),
    'correction_requested', (SELECT count(*) FROM scoped WHERE status = 'CORRECTION_REQUESTED'),
    'accepted', (SELECT count(*) FROM scoped WHERE status = 'ACCEPTED'),
    'overdue', (SELECT count(*) FROM scoped WHERE is_overdue),
    'due_soon', (SELECT count(*) FROM scoped WHERE NOT is_overdue AND sla_state = 'DUE_SOON'),
    'upcoming', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', filing_id, 'filing_reference', filing_reference, 'definition_name', definition_name,
        'period_label', period_label, 'due_date', due_date, 'status', status,
        'status_label', status_label, 'is_overdue', is_overdue))
      FROM (SELECT * FROM scoped WHERE status NOT IN ('ACCEPTED','WITHDRAWN') ORDER BY due_date NULLS LAST LIMIT 10) t
    ), '[]'::jsonb)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.returns_extract_metrics(_version_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v record; v_count int := 0;
BEGIN
  SELECT v2.id, f.entity_id, f.reporting_period_id INTO v
    FROM public.return_filing_versions v2
    JOIN public.return_filings f ON f.id = v2.return_filing_id
   WHERE v2.id = _version_id;
  IF v.id IS NULL THEN RAISE EXCEPTION 'Filing version not found'; END IF;

  DELETE FROM public.return_metric_values
   WHERE return_filing_version_id = _version_id AND source_kind <> 'LEGACY_EVIDENCE';

  INSERT INTO public.return_metric_values(
    return_filing_version_id, entity_id, regulatory_metric_id, reporting_period_id,
    value_numeric, value_text, value_boolean, value_date, availability, source_kind,
    source_form_response_id, source_form_version_id, source_field_definition_id)
  SELECT DISTINCT ON (fd.regulatory_metric_id)
         _version_id, v.entity_id, fd.regulatory_metric_id, v.reporting_period_id,
         sv.value_number, sv.value_text, sv.value_boolean, sv.value_date,
         CASE WHEN sv.value_number IS NULL AND sv.value_text IS NULL
                   AND sv.value_boolean IS NULL AND sv.value_date IS NULL
              THEN 'NOT_AVAILABLE' ELSE 'AVAILABLE' END,
         'REPORTED', sv.response_id, sv.form_version_id, fd.id
    FROM public.return_filing_form_requirements r
    JOIN public.form_submission_values sv ON sv.response_id = r.form_response_id
    JOIN public.form_field_definitions fd ON fd.id = sv.form_field_definition_id
   WHERE r.return_filing_version_id = _version_id
     AND fd.regulatory_metric_id IS NOT NULL
     AND COALESCE(sv.repeat_index, 0) = 0
   ORDER BY fd.regulatory_metric_id, sv.created_at DESC
  ON CONFLICT (return_filing_version_id, regulatory_metric_id) DO NOTHING;

  SELECT count(*) INTO v_count FROM public.return_metric_values
   WHERE return_filing_version_id = _version_id;
  RETURN v_count;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_filing_detail(_filing_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE f record; v_result jsonb; v_current uuid;
BEGIN
  SELECT * INTO f FROM public.return_filings WHERE id = _filing_id;
  IF f.id IS NULL THEN RAISE EXCEPTION 'Filing not found'; END IF;
  IF NOT (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(),'returns_management','view')
          OR public.entity_membership_capability(auth.uid(), f.entity_id, 'returns.view')) THEN
    RAISE EXCEPTION 'Not authorised to view this filing' USING ERRCODE='42501';
  END IF;

  SELECT ver.id INTO v_current
    FROM public.return_filing_versions ver
   WHERE ver.return_filing_id = f.id
   ORDER BY ver.version_number DESC LIMIT 1;

  SELECT jsonb_build_object(
    'filing', to_jsonb(f),
    'entity_name', (SELECT l.name FROM public.licensees l WHERE l.id = f.entity_id),
    'definition', (SELECT to_jsonb(d) FROM public.return_definitions d WHERE d.id = f.return_definition_id),
    'period', (SELECT to_jsonb(p) FROM public.reporting_periods p WHERE p.id = f.reporting_period_id),
    'versions', (SELECT COALESCE(jsonb_agg(to_jsonb(ver) ORDER BY ver.version_number DESC), '[]'::jsonb)
                   FROM public.return_filing_versions ver WHERE ver.return_filing_id = f.id),
    'forms', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                    'id', r.id, 'form_template_id', r.form_template_id,
                    'form_version_id', r.form_version_id, 'template_name', t.name,
                    'form_version', fv.version, 'is_required', r.is_required,
                    'sequence', r.sequence, 'tab_name', r.tab_name,
                    'form_response_id', r.form_response_id,
                    'completion_status', r.completion_status,
                    'return_filing_version_id', r.return_filing_version_id) ORDER BY r.sequence), '[]'::jsonb)
                 FROM public.return_filing_form_requirements r
                 LEFT JOIN public.form_templates t ON t.id = r.form_template_id
                 LEFT JOIN public.form_versions fv ON fv.id = r.form_version_id
                WHERE r.return_filing_version_id = v_current),
    'metrics', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                    'code', m.code, 'name', m.name, 'unit', m.unit,
                    'value_numeric', mv.value_numeric, 'value_text', mv.value_text,
                    'availability', mv.availability, 'availability_reason', mv.availability_reason,
                    'source_kind', mv.source_kind,
                    'calculation_inputs', mv.calculation_inputs) ORDER BY m.code), '[]'::jsonb)
                  FROM public.return_metric_values mv
                  JOIN public.regulatory_metrics m ON m.id = mv.regulatory_metric_id
                 WHERE mv.return_filing_version_id = v_current),
    'findings', (SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.severity, r.detected_at), '[]'::jsonb)
                   FROM public.return_filing_validation_results r WHERE r.return_filing_id = f.id),
    'requests', (SELECT COALESCE(jsonb_agg(to_jsonb(q) ORDER BY q.created_at DESC), '[]'::jsonb)
                   FROM public.return_filing_requests q WHERE q.return_filing_id = f.id)
  ) INTO v_result;
  RETURN v_result;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_filing_queue(_status text DEFAULT NULL::text, _entity_id uuid DEFAULT NULL::uuid, _limit integer DEFAULT 200)
 RETURNS TABLE(filing_id uuid, filing_reference text, entity_id uuid, entity_name text, definition_code text, definition_name text, frequency text, period_label text, period_end date, due_date date, status text, current_version_number integer, current_version_id uuid, submitted_at timestamp with time zone, is_overdue boolean, days_late integer, blocking_errors bigint, open_requests bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT f.id, f.filing_reference, f.entity_id, l.name, d.code, d.name, o.frequency,
         p.period_label, p.period_end, p.due_date, f.status, f.current_version_number,
         (SELECT v.id FROM public.return_filing_versions v
           WHERE v.return_filing_id = f.id ORDER BY v.version_number DESC LIMIT 1),
         f.submitted_at,
         (f.status NOT IN ('ACCEPTED','WITHDRAWN') AND p.due_date < CURRENT_DATE),
         GREATEST(0, (COALESCE(f.submitted_at::date, CURRENT_DATE) - p.due_date)),
         (SELECT count(*) FROM public.return_filing_validation_results r
           WHERE r.return_filing_id = f.id AND r.is_blocking),
         (SELECT count(*) FROM public.return_filing_requests rq
           WHERE rq.return_filing_id = f.id AND rq.status = 'OPEN')
    FROM public.return_filings f
    JOIN public.reporting_periods p ON p.id = f.reporting_period_id
    JOIN public.entity_reporting_obligations o ON o.id = f.entity_reporting_obligation_id
    JOIN public.return_definitions d ON d.id = f.return_definition_id
    LEFT JOIN public.licensees l ON l.id = f.entity_id
   WHERE (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(),'returns_management','view')
          OR public.entity_membership_capability(auth.uid(), f.entity_id, 'returns.view'))
     AND (_status IS NULL OR f.status = _status)
     AND (_entity_id IS NULL OR f.entity_id = _entity_id)
   ORDER BY p.due_date DESC
   LIMIT LEAST(COALESCE(_limit, 200), 500);
$function$
;
CREATE OR REPLACE FUNCTION public.returns_filing_queue_counts(_status text DEFAULT NULL::text, _stage text DEFAULT NULL::text, _entity_id uuid DEFAULT NULL::uuid, _owner_user_id uuid DEFAULT NULL::uuid, _overdue_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'total', count(*),
    'overdue', count(*) FILTER (WHERE w.is_overdue),
    'sla_breached', count(*) FILTER (WHERE w.sla_state = 'BREACHED'),
    'blocking_validations', count(*) FILTER (WHERE w.blocking_validation_count > 0),
    'open_requests', count(*) FILTER (WHERE w.open_request_count > 0),
    'unassigned', count(*) FILTER (WHERE w.owner_user_id IS NULL AND w.waiting_on = 'REGULATOR'),
    'awaiting_regulator', count(*) FILTER (WHERE w.waiting_on = 'REGULATOR'),
    'awaiting_entity', count(*) FILTER (WHERE w.waiting_on = 'ENTITY'),
    'by_stage', COALESCE((SELECT jsonb_object_agg(t.stage, t.n) FROM (
        SELECT w2.stage, count(*) AS n FROM public.v_return_filing_workflow_state w2
         WHERE public.returns_can_view_filing_scope(w2.entity_id)
           AND (_entity_id IS NULL OR w2.entity_id = _entity_id)
         GROUP BY w2.stage) t), '{}'::jsonb)
  )
  FROM public.v_return_filing_workflow_state w
  WHERE public.returns_can_view_filing_scope(w.entity_id)
    AND (_status IS NULL OR w.status = _status)
    AND (_stage IS NULL OR w.stage = _stage)
    AND (_entity_id IS NULL OR w.entity_id = _entity_id)
    AND (_owner_user_id IS NULL OR w.owner_user_id = _owner_user_id)
    AND (NOT COALESCE(_overdue_only,false) OR w.is_overdue);
$function$
;
CREATE OR REPLACE FUNCTION public.returns_filing_queue_v2(_status text DEFAULT NULL::text, _stage text DEFAULT NULL::text, _entity_id uuid DEFAULT NULL::uuid, _owner_user_id uuid DEFAULT NULL::uuid, _overdue_only boolean DEFAULT false, _limit integer DEFAULT 300)
 RETURNS TABLE(filing_id uuid, filing_reference text, entity_id uuid, entity_name text, return_definition_id uuid, definition_code text, definition_name text, frequency text, reporting_period_id uuid, period_label text, period_start date, period_end date, due_date date, stage text, stage_label text, status text, status_label text, owner_user_id uuid, owner_name text, team text, priority text, priority_reason text, sla_due_at timestamp with time zone, sla_state text, waiting_on text, blocker_count integer, blocking_validation_count bigint, open_request_count bigint, incomplete_required_forms bigint, last_activity_at timestamp with time zone, next_action text, next_action_label text, next_action_href text, next_action_permission text, current_version_id uuid, current_version_number integer, submitted_at timestamp with time zone, is_overdue boolean, days_late integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT w.filing_id, w.filing_reference, w.entity_id, w.entity_name,
         w.return_definition_id, w.definition_code, w.definition_name, w.frequency,
         w.reporting_period_id, w.period_label, w.period_start, w.period_end, w.due_date,
         w.stage, w.stage_label, w.status, w.status_label,
         w.owner_user_id, w.owner_name, w.team,
         w.priority, w.priority_reason,
         w.sla_due_at, w.sla_state, w.waiting_on,
         w.blocker_count::integer, w.blocking_validation_count, w.open_request_count,
         w.incomplete_required_forms,
         w.last_activity_at,
         w.next_action, w.next_action_label, w.next_action_href, w.next_action_permission,
         w.current_version_id, w.current_version_number,
         w.submitted_at, w.is_overdue, w.days_late
    FROM public.v_return_filing_workflow_state w
   WHERE public.returns_can_view_filing_scope(w.entity_id)
     AND (_status IS NULL OR w.status = _status)
     AND (_stage IS NULL OR w.stage = _stage)
     AND (_entity_id IS NULL OR w.entity_id = _entity_id)
     AND (_owner_user_id IS NULL OR w.owner_user_id = _owner_user_id)
     AND (NOT COALESCE(_overdue_only,false) OR w.is_overdue)
   ORDER BY CASE w.priority WHEN 'CRITICAL' THEN 0 WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2
                            WHEN 'NORMAL' THEN 3 ELSE 4 END,
            w.due_date
   LIMIT LEAST(COALESCE(_limit, 300), 1000);
$function$
;
CREATE OR REPLACE FUNCTION public.returns_filing_related_cases(_filing_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_entity uuid; v_out jsonb;
BEGIN
  SELECT entity_id INTO v_entity FROM public.return_filings WHERE id = _filing_id;
  IF v_entity IS NULL THEN RAISE EXCEPTION 'Filing not found'; END IF;
  IF NOT public.returns_can_view_filing_scope(v_entity) THEN
    RAISE EXCEPTION 'Not authorised to view this filing' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'breaches', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id', b.id, 'metric_key', b.metric_key, 'level', b.level, 'value', b.value,
        'threshold_value', b.threshold_value, 'risk_level', b.risk_level,
        'detected_at', b.detected_at, 'acknowledged_at', b.acknowledged_at,
        'return_filing_version_id', b.return_filing_version_id) ORDER BY b.detected_at DESC)
      FROM public.return_threshold_breaches b WHERE b.return_filing_id = _filing_id), '[]'::jsonb),
    'ewi_alerts', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'severity', a.severity, 'status', a.status, 'created_at', a.created_at)
        ORDER BY a.created_at DESC)
      FROM public.prudential_ewi_alerts a WHERE a.return_filing_id = _filing_id), '[]'::jsonb),
    'assessments', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id', pa.id, 'status', pa.status, 'created_at', pa.created_at) ORDER BY pa.created_at DESC)
      FROM public.prudential_assessments pa WHERE pa.return_filing_id = _filing_id), '[]'::jsonb),
    'actions', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id', ac.id, 'action_reference', ac.action_reference, 'action_type', ac.action_type,
        'title', ac.title, 'status', ac.status, 'severity', ac.severity, 'due_date', ac.due_date)
        ORDER BY ac.created_at DESC)
      FROM public.prudential_actions ac
      WHERE ac.source_id IN (SELECT b.id FROM public.return_threshold_breaches b
                              WHERE b.return_filing_id = _filing_id)), '[]'::jsonb),
    'enforcement', COALESCE((SELECT jsonb_agg(DISTINCT jsonb_build_object(
        'id', b.escalated_enforcement_id, 'escalated_at', b.escalated_at))
      FROM public.return_threshold_breaches b
     WHERE b.return_filing_id = _filing_id AND b.escalated_enforcement_id IS NOT NULL), '[]'::jsonb)
  ) INTO v_out;
  RETURN v_out;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_filing_trend(_months integer DEFAULT 6)
 RETURNS TABLE(month text, filings bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT to_char(date_trunc('month', f.created_at), 'YYYY-MM') AS month, count(*)::bigint
  FROM public.return_filings f
  WHERE f.created_at >= date_trunc('month', now()) - ((GREATEST(_months, 1) - 1) || ' months')::interval
  GROUP BY 1
  ORDER BY 1;
$function$
;
CREATE OR REPLACE FUNCTION public.returns_filing_workflow_state(_filing_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE w record; v_blockers jsonb := '[]'::jsonb; v_actions jsonb := '[]'::jsonb;
        v_can_review boolean; v_can_approve boolean;
BEGIN
  SELECT * INTO w FROM public.v_return_filing_workflow_state WHERE filing_id = _filing_id;
  IF w.filing_id IS NULL THEN RAISE EXCEPTION 'Filing not found'; END IF;
  IF NOT public.returns_can_view_filing_scope(w.entity_id) THEN
    RAISE EXCEPTION 'Not authorised to view this filing' USING ERRCODE = '42501';
  END IF;

  v_can_review  := public.is_super_admin(auth.uid()) OR public.has_permission(auth.uid(),'returns_management','review');
  v_can_approve := public.is_super_admin(auth.uid()) OR public.has_permission(auth.uid(),'returns_management','approve');

  IF w.blocking_validation_count > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code','BLOCKING_VALIDATION',
      'label', w.blocking_validation_count || ' blocking validation finding(s)',
      'detail','The filing cannot be accepted until these findings are cleared or the entity resubmits.',
      'severity','critical');
  END IF;
  IF w.open_request_count > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code','OPEN_REQUEST',
      'label', w.open_request_count || ' open information request(s)',
      'detail','Awaiting a response from the regulated entity.','severity','warning');
  END IF;
  IF w.status IN ('DRAFT','CORRECTION_REQUESTED') AND w.incomplete_required_forms > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code','INCOMPLETE_FORMS',
      'label', w.incomplete_required_forms || ' required form(s) incomplete',
      'detail','The entity must complete every required form before submission.','severity','warning');
  END IF;
  IF w.status IN ('DRAFT','CORRECTION_REQUESTED') AND w.requires_declaration
     AND w.declaration_accepted_at IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','DECLARATION_OUTSTANDING',
      'label','Filer declaration not accepted',
      'detail','This return requires the filer declaration before submission.','severity','warning');
  END IF;

  IF w.status = 'SUBMITTED' AND v_can_review THEN
    v_actions := v_actions || jsonb_build_object('code','START_REVIEW','label','Start regulatory review','variant','primary');
  END IF;
  IF w.status IN ('SUBMITTED','UNDER_REVIEW') AND (v_can_review OR v_can_approve) THEN
    v_actions := v_actions || jsonb_build_object('code','VALIDATE','label','Re-run validation','variant','outline');
  END IF;
  IF w.status IN ('SUBMITTED','UNDER_REVIEW') AND v_can_review THEN
    v_actions := v_actions || jsonb_build_object('code','REQUEST_CORRECTION','label','Request correction','variant','outline','requires_reason',true);
  END IF;
  IF w.status IN ('SUBMITTED','UNDER_REVIEW') AND v_can_approve THEN
    IF w.blocking_validation_count = 0 THEN
      v_actions := v_actions || jsonb_build_object('code','ACCEPT','label','Accept filing','variant','primary');
    END IF;
    v_actions := v_actions || jsonb_build_object('code','REJECT','label','Reject filing','variant','destructive','requires_reason',true);
  END IF;
  IF v_can_review THEN
    v_actions := v_actions || jsonb_build_object('code','ASSIGN','label','Assign owner','variant','outline');
  END IF;

  RETURN jsonb_build_object(
    'filing_id', w.filing_id,
    'stage', w.stage, 'stage_label', w.stage_label,
    'status', w.status, 'status_label', w.status_label,
    'waiting_on', w.waiting_on,
    'owner_user_id', w.owner_user_id, 'owner_name', w.owner_name, 'team', w.team,
    'priority', w.priority, 'priority_reason', w.priority_reason,
    'sla_due_at', w.sla_due_at, 'sla_state', w.sla_state,
    'due_date', w.due_date, 'is_overdue', w.is_overdue, 'days_late', w.days_late,
    'last_activity_at', w.last_activity_at,
    'current_version_id', w.current_version_id,
    'current_version_number', w.current_version_number,
    'accepted_version_id', w.accepted_version_id,
    'blocker_count', w.blocker_count,
    'blockers', v_blockers,
    'available_actions', v_actions,
    'next_action', w.next_action,
    'next_action_label', w.next_action_label,
    'next_action_href', w.next_action_href,
    'next_action_permission', w.next_action_permission,
    'completed', jsonb_build_object(
      'submitted_at', w.submitted_at, 'accepted_at', w.accepted_at, 'rejected_at', w.rejected_at,
      'required_forms_complete', (w.incomplete_required_forms = 0),
      'declaration_accepted_at', w.declaration_accepted_at)
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_generate_periods(_obligation_id uuid, _through date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE o record; v_start date; v_end date; v_step interval; v_label text; v_count int := 0;
        v_through date := COALESCE(_through, CURRENT_DATE);
BEGIN
  PERFORM public.returns_require('manage_config');
  SELECT * INTO o FROM public.entity_reporting_obligations WHERE id = _obligation_id;
  IF o.id IS NULL THEN RAISE EXCEPTION 'Obligation not found'; END IF;
  IF o.frequency IN ('EVENT_DRIVEN','AD_HOC') THEN
    RETURN jsonb_build_object('created', 0, 'reason', 'Event-driven obligations have no calendar periods');
  END IF;

  v_step := CASE o.frequency
    WHEN 'MONTHLY' THEN interval '1 month'
    WHEN 'QUARTERLY' THEN interval '3 months'
    WHEN 'SEMI_ANNUAL' THEN interval '6 months'
    ELSE interval '1 year' END;

  v_start := date_trunc(CASE o.frequency WHEN 'MONTHLY' THEN 'month'
                                         WHEN 'ANNUAL' THEN 'year' ELSE 'quarter' END,
                        o.effective_from)::date;
  IF o.frequency = 'SEMI_ANNUAL' THEN
    v_start := make_date(EXTRACT(YEAR FROM o.effective_from)::int,
                         CASE WHEN EXTRACT(MONTH FROM o.effective_from) <= 6 THEN 1 ELSE 7 END, 1);
  END IF;

  WHILE v_start <= v_through LOOP
    v_end := (v_start + v_step - interval '1 day')::date;
    v_label := CASE o.frequency
      WHEN 'MONTHLY' THEN to_char(v_start, 'YYYY-MM')
      WHEN 'QUARTERLY' THEN to_char(v_start, 'YYYY') || '-Q' || EXTRACT(QUARTER FROM v_start)::int
      WHEN 'SEMI_ANNUAL' THEN to_char(v_start, 'YYYY') || '-H' ||
        CASE WHEN EXTRACT(MONTH FROM v_start) <= 6 THEN 1 ELSE 2 END
      ELSE to_char(v_start, 'YYYY') END;

    INSERT INTO public.reporting_periods(
      entity_reporting_obligation_id, period_label, period_start, period_end, due_date, status, opened_at)
    VALUES (_obligation_id, v_label, v_start, v_end,
            v_end + o.due_days_after_period_end,
            CASE WHEN v_end <= CURRENT_DATE THEN 'OPEN' ELSE 'SCHEDULED' END,
            CASE WHEN v_end <= CURRENT_DATE THEN now() END)
    ON CONFLICT (entity_reporting_obligation_id, period_start, period_end) DO NOTHING;
    IF FOUND THEN v_count := v_count + 1; END IF;
    v_start := (v_start + v_step)::date;
  END LOOP;

  UPDATE public.entity_reporting_obligations SET next_due_date = (
    SELECT min(p.due_date) FROM public.reporting_periods p
      LEFT JOIN public.return_filings f ON f.reporting_period_id = p.id
     WHERE p.entity_reporting_obligation_id = _obligation_id
       AND p.status IN ('OPEN','SCHEDULED')
       AND (f.id IS NULL OR f.status NOT IN ('ACCEPTED','WITHDRAWN')))
   WHERE id = _obligation_id;

  RETURN jsonb_build_object('created', v_count);
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_legacy_classification_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  PERFORM public.returns_require('view');
  SELECT jsonb_build_object(
    'return_types', (SELECT count(*) FROM public.return_types),
    'return_configs', (SELECT count(*) FROM public.return_configs),
    'legacy_filings', (SELECT count(*) FROM public.returns_filed),
    'definitions_mapped', (SELECT count(*) FROM public.return_definitions
                            WHERE legacy_return_config_id IS NOT NULL),
    'filings_migrated', (SELECT count(*) FROM public.return_filings
                          WHERE legacy_return_filed_id IS NOT NULL),
    'classification', (
      SELECT COALESCE(jsonb_object_agg(classification, n), '{}'::jsonb) FROM (
        SELECT classification, count(*) n FROM public.returns_legacy_mappings GROUP BY 1) s),
    'unclassified_filings', (
      SELECT count(*) FROM public.returns_filed rf
       WHERE NOT EXISTS (SELECT 1 FROM public.returns_legacy_mappings m
                          WHERE m.legacy_table = 'returns_filed' AND m.legacy_id = rf.id)),
    'blockers', (
      SELECT COALESCE(jsonb_agg(b), '[]'::jsonb) FROM (
        SELECT jsonb_build_object('issue','LEGACY_FILING_WITHOUT_ENTITY','count',count(*)) b
          FROM public.returns_filed rf
         WHERE rf.entity_id IS NULL OR NOT EXISTS (
            SELECT 1 FROM public.licensees l WHERE l.id = rf.entity_id)
        HAVING count(*) > 0
        UNION ALL
        SELECT jsonb_build_object('issue','LEGACY_FILING_WITHOUT_PERIOD_DATES','count',count(*))
          FROM public.returns_filed rf
         WHERE rf.period_start_date IS NULL OR rf.period_end_date IS NULL
        HAVING count(*) > 0
        UNION ALL
        SELECT jsonb_build_object('issue','LEGACY_CONFIG_WITHOUT_RETURN_TYPE','count',count(*))
          FROM public.return_configs c WHERE c.return_type_id IS NULL
        HAVING count(*) > 0) x)
  ) INTO v;
  RETURN v;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_metric_series(_entity_id uuid, _metric_codes text[] DEFAULT NULL::text[], _limit integer DEFAULT 24)
 RETURNS TABLE(metric_code text, metric_name text, unit text, period_label text, period_end date, value_numeric numeric, availability text, source_kind text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT m.code, m.name, m.unit, p.period_label, p.period_end,
         mv.value_numeric, mv.availability, mv.source_kind
    FROM public.return_metric_values mv
    JOIN public.regulatory_metrics m ON m.id = mv.regulatory_metric_id
    JOIN public.reporting_periods p ON p.id = mv.reporting_period_id
    JOIN public.return_filing_versions v ON v.id = mv.return_filing_version_id
   WHERE mv.entity_id = _entity_id
     AND v.status IN ('SUBMITTED','UNDER_REVIEW','ACCEPTED','SUPERSEDED')
     AND (_metric_codes IS NULL OR m.code = ANY(_metric_codes))
     AND (public.is_super_admin(auth.uid())
          OR public.has_permission(auth.uid(),'returns_management','view')
          OR public.entity_membership_capability(auth.uid(), _entity_id, 'returns.view'))
   ORDER BY m.code, p.period_end DESC
   LIMIT GREATEST(COALESCE(_limit, 24), 1) * 40;
$function$
;
CREATE OR REPLACE FUNCTION public.returns_migrate_legacy_filing(_legacy_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE rf record; v_def uuid; v_ob uuid; v_period uuid; v_filing uuid; v_version uuid;
        v_map record; v_status text; v_due date;
BEGIN
  PERFORM public.returns_require('manage_config');
  SELECT * INTO rf FROM public.returns_filed WHERE id = _legacy_id;
  IF rf.id IS NULL THEN RAISE EXCEPTION 'Legacy filing not found'; END IF;

  SELECT * INTO v_map FROM public.returns_legacy_mappings
   WHERE legacy_table = 'returns_filed' AND legacy_id = _legacy_id;
  IF v_map.id IS NULL THEN
    RAISE EXCEPTION 'This legacy filing has not been classified yet';
  END IF;
  IF v_map.classification NOT IN ('EXACT_CANONICAL_MAPPING','DERIVABLE_WITH_EVIDENCE') THEN
    RETURN jsonb_build_object('migrated', false,
      'reason', 'Left in place for review: ' || v_map.classification);
  END IF;

  SELECT id INTO v_filing FROM public.return_filings WHERE legacy_return_filed_id = _legacy_id;
  IF v_filing IS NOT NULL THEN
    RETURN jsonb_build_object('migrated', true, 'filing_id', v_filing, 'already', true);
  END IF;

  v_def := public.returns_adopt_legacy_config(rf.return_configuration_id);

  SELECT id INTO v_ob FROM public.entity_reporting_obligations
   WHERE entity_id = rf.entity_id AND return_definition_id = v_def
   ORDER BY effective_from LIMIT 1;
  IF v_ob IS NULL THEN
    INSERT INTO public.entity_reporting_obligations(
      entity_id, return_definition_id, origin, frequency, due_days_after_period_end,
      effective_from, created_by)
    SELECT rf.entity_id, v_def, 'LEGACY_MIGRATION', d.frequency, d.due_days_after_period_end,
           COALESCE(rf.period_start_date, CURRENT_DATE), auth.uid()
      FROM public.return_definitions d WHERE d.id = v_def
    RETURNING id INTO v_ob;
  END IF;

  v_due := COALESCE(rf.due_date, rf.period_end_date + 30);
  SELECT id INTO v_period FROM public.reporting_periods
   WHERE entity_reporting_obligation_id = v_ob
     AND period_start = rf.period_start_date AND period_end = rf.period_end_date;
  IF v_period IS NULL THEN
    INSERT INTO public.reporting_periods(
      entity_reporting_obligation_id, period_label, period_start, period_end, due_date, status)
    VALUES (v_ob,
      COALESCE(NULLIF(rf.return_period,''), rf.return_year::text, to_char(rf.period_end_date,'YYYY-MM')),
      rf.period_start_date, rf.period_end_date, v_due, 'CLOSED')
    RETURNING id INTO v_period;
  END IF;

  v_status := CASE rf.workflow_status::text
    WHEN 'VAL' THEN 'ACCEPTED' WHEN 'SUB' THEN 'SUBMITTED'
    WHEN 'REJ' THEN 'REJECTED' WHEN 'TBR' THEN 'CORRECTION_REQUESTED' ELSE 'DRAFT' END;

  INSERT INTO public.return_filings(
    filing_reference, entity_id, entity_reporting_obligation_id, reporting_period_id,
    return_definition_id, status, current_version_number, submitted_at,
    legacy_return_filed_id, created_by, created_at)
  VALUES (COALESCE(NULLIF(rf.unique_id,''), 'LEG-' || left(replace(rf.id::text,'-',''),12)),
    rf.entity_id, v_ob, v_period, v_def, v_status, 1, rf.submit_date, rf.id,
    rf.created_by, rf.created_at)
  RETURNING id INTO v_filing;

  INSERT INTO public.return_filing_versions(
    return_filing_id, version_number, status, is_immutable, legacy_origin,
    submitted_at, submitted_by, created_at)
  VALUES (v_filing, 1,
    CASE WHEN v_status = 'DRAFT' THEN 'DRAFT' ELSE v_status END,
    v_status <> 'DRAFT', 'LEGACY_SINGLE_VERSION', rf.submit_date, rf.created_by, rf.created_at)
  RETURNING id INTO v_version;

  IF v_status = 'ACCEPTED' THEN
    UPDATE public.return_filings SET accepted_version_id = v_version, accepted_at = rf.submit_date
     WHERE id = v_filing;
  END IF;

  UPDATE public.returns_legacy_mappings
     SET canonical_table = 'return_filings', canonical_id = v_filing,
         notes = 'Migrated as a single historical version; legacy record retained'
   WHERE id = v_map.id;

  PERFORM public.create_audit_log('return_filing', v_filing, 'MIGRATE_LEGACY',
    jsonb_build_object('legacy_return_filed_id', _legacy_id, 'classification', v_map.classification));

  RETURN jsonb_build_object('migrated', true, 'filing_id', v_filing, 'version_id', v_version);
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_open_filing(_period_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p record; o record; d record; v_filing public.return_filings;
        v_version_id uuid; v_ref text; v_seq int;
BEGIN
  SELECT * INTO p FROM public.reporting_periods WHERE id = _period_id;
  IF p.id IS NULL THEN RAISE EXCEPTION 'Reporting period not found'; END IF;
  SELECT * INTO o FROM public.entity_reporting_obligations WHERE id = p.entity_reporting_obligation_id;
  SELECT * INTO d FROM public.return_definitions WHERE id = o.return_definition_id;

  IF NOT public.returns_can_file(o.entity_id) THEN
    RAISE EXCEPTION 'You are not authorised to file returns for this entity' USING ERRCODE='42501';
  END IF;
  IF o.status <> 'ACTIVE' THEN RAISE EXCEPTION 'This reporting obligation is not active'; END IF;
  IF p.status = 'WAIVED' THEN RAISE EXCEPTION 'This period has been waived'; END IF;

  SELECT * INTO v_filing FROM public.return_filings WHERE reporting_period_id = _period_id;
  IF v_filing.id IS NULL THEN
    SELECT count(*) + 1 INTO v_seq FROM public.return_filings WHERE entity_id = o.entity_id;
    v_ref := 'FIL-' || to_char(now(),'YYYY') || '-' || lpad(v_seq::text, 6, '0') || '-' ||
             substr(replace(gen_random_uuid()::text,'-',''), 1, 4);
    INSERT INTO public.return_filings(
      filing_reference, entity_id, entity_reporting_obligation_id, reporting_period_id,
      return_definition_id, status, created_by)
    VALUES (v_ref, o.entity_id, o.id, p.id, d.id, 'DRAFT', auth.uid())
    RETURNING * INTO v_filing;
  END IF;

  SELECT id INTO v_version_id FROM public.return_filing_versions
   WHERE return_filing_id = v_filing.id AND status IN ('DRAFT','CORRECTION_REQUESTED')
   ORDER BY version_number DESC LIMIT 1;

  IF v_version_id IS NULL THEN
    INSERT INTO public.return_filing_versions(return_filing_id, version_number, status)
    VALUES (v_filing.id,
      COALESCE((SELECT max(version_number) FROM public.return_filing_versions
                 WHERE return_filing_id = v_filing.id), 0) + 1, 'DRAFT')
    RETURNING id INTO v_version_id;

    UPDATE public.return_filings
       SET current_version_number = (SELECT max(version_number) FROM public.return_filing_versions
                                      WHERE return_filing_id = v_filing.id),
           status = CASE WHEN status = 'ACCEPTED' THEN status ELSE 'DRAFT' END,
           updated_at = now()
     WHERE id = v_filing.id;

    -- pin the form versions in force for this period
    INSERT INTO public.return_filing_form_requirements(
      return_filing_version_id, form_template_id, form_version_id, is_required, sequence, tab_name)
    SELECT v_version_id, df.form_template_id, fv.id, df.is_required, df.sequence,
           COALESCE(df.tab_name, df.section_label)
      FROM public.return_definition_forms df
      JOIN LATERAL (
        SELECT v.id FROM public.form_versions v
         WHERE v.template_id = df.form_template_id AND v.status = 'published'
           AND (v.effective_from IS NULL OR v.effective_from::date <= p.period_end)
         ORDER BY v.version DESC LIMIT 1) fv ON true
     WHERE df.return_definition_id = d.id
       AND df.effective_from <= p.period_end
       AND (df.effective_to IS NULL OR df.effective_to >= p.period_end)
    ON CONFLICT DO NOTHING;
  END IF;

  PERFORM public.create_audit_log('return_filing', v_filing.id, 'OPEN',
    jsonb_build_object('version_id', v_version_id, 'period', p.period_label));

  RETURN jsonb_build_object('filing_id', v_filing.id, 'filing_reference', v_filing.filing_reference,
                            'version_id', v_version_id);
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_require(_action text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;
  IF public.is_super_admin(auth.uid()) THEN RETURN; END IF;
  IF public.has_permission(auth.uid(), 'returns_management', _action) THEN RETURN; END IF;
  RAISE EXCEPTION 'Not authorised for returns %', _action USING ERRCODE='42501';
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_resolve_legacy_filing(_legacy_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT f.id FROM public.return_filings f
   WHERE (f.id = _legacy_id OR f.legacy_return_filed_id = _legacy_id)
     AND public.returns_can_view_filing_scope(f.entity_id)
   ORDER BY (f.id = _legacy_id) DESC
   LIMIT 1;
$function$
;
CREATE OR REPLACE FUNCTION public.returns_respond_to_request(_request_id uuid, _response text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_entity uuid;
BEGIN
  IF COALESCE(length(trim(_response)),0) < 10 THEN
    RAISE EXCEPTION 'Please provide a response of at least 10 characters';
  END IF;
  SELECT f.entity_id INTO v_entity FROM public.return_filing_requests q
    JOIN public.return_filings f ON f.id = q.return_filing_id WHERE q.id = _request_id;
  IF v_entity IS NULL THEN RAISE EXCEPTION 'Request not found'; END IF;
  IF NOT public.returns_can_file(v_entity) THEN
    RAISE EXCEPTION 'You are not authorised to respond for this entity' USING ERRCODE='42501';
  END IF;
  UPDATE public.return_filing_requests
     SET response_text = _response, status = 'RESPONDED', responded_at = now(),
         responded_by = auth.uid(), updated_at = now()
   WHERE id = _request_id AND status = 'OPEN';
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_review_filing(_version_id uuid, _action text, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v record; v_new_version uuid;
BEGIN
  IF _action NOT IN ('START_REVIEW','ACCEPT','REJECT','REQUEST_CORRECTION') THEN
    RAISE EXCEPTION 'Unsupported review action';
  END IF;
  IF _action IN ('ACCEPT','REJECT') THEN
    PERFORM public.returns_require('approve');
  ELSE
    PERFORM public.returns_require('review');
  END IF;
  IF _action IN ('REJECT','REQUEST_CORRECTION') AND COALESCE(length(trim(_reason)),0) < 10 THEN
    RAISE EXCEPTION 'Please record a reason of at least 10 characters';
  END IF;

  SELECT v2.id, v2.status, v2.return_filing_id, v2.version_number, f.entity_id
    INTO v FROM public.return_filing_versions v2
    JOIN public.return_filings f ON f.id = v2.return_filing_id
   WHERE v2.id = _version_id FOR UPDATE;
  IF v.id IS NULL THEN RAISE EXCEPTION 'Filing version not found'; END IF;
  IF v.status NOT IN ('SUBMITTED','UNDER_REVIEW') THEN
    RAISE EXCEPTION 'Only a submitted filing version can be reviewed';
  END IF;

  IF _action = 'START_REVIEW' THEN
    UPDATE public.return_filing_versions SET status = 'UNDER_REVIEW' WHERE id = _version_id;
    UPDATE public.return_filings SET status = 'UNDER_REVIEW', updated_at = now() WHERE id = v.return_filing_id;
  ELSIF _action = 'ACCEPT' THEN
    UPDATE public.return_filing_versions
       SET status = 'ACCEPTED', accepted_at = now(), accepted_by = auth.uid(), is_immutable = true
     WHERE id = _version_id;
    UPDATE public.return_filings
       SET status = 'ACCEPTED', accepted_at = now(), accepted_version_id = _version_id, updated_at = now()
     WHERE id = v.return_filing_id;
  ELSIF _action = 'REJECT' THEN
    UPDATE public.return_filing_versions
       SET status = 'REJECTED', rejected_at = now(), rejected_by = auth.uid(),
           rejection_reason = _reason, is_immutable = true
     WHERE id = _version_id;
    UPDATE public.return_filings
       SET status = 'REJECTED', rejected_at = now(), updated_at = now()
     WHERE id = v.return_filing_id;
  ELSE
    UPDATE public.return_filing_versions SET status = 'SUPERSEDED', is_immutable = true WHERE id = _version_id;
    INSERT INTO public.return_filing_versions(return_filing_id, version_number, status, supersedes_version_id)
    VALUES (v.return_filing_id, v.version_number + 1, 'DRAFT', _version_id)
    RETURNING id INTO v_new_version;

    INSERT INTO public.return_filing_form_requirements(
      return_filing_version_id, form_template_id, form_version_id, is_required, sequence, tab_name, completion_status)
    SELECT v_new_version, r.form_template_id, r.form_version_id, r.is_required, r.sequence, r.tab_name, 'PENDING'
      FROM public.return_filing_form_requirements r
     WHERE r.return_filing_version_id = _version_id;

    UPDATE public.return_filings
       SET status = 'CORRECTION_REQUESTED', current_version_number = v.version_number + 1, updated_at = now()
     WHERE id = v.return_filing_id;

    INSERT INTO public.return_filing_requests(
      return_filing_id, return_filing_version_id, request_kind, message, status, created_by)
    VALUES (v.return_filing_id, _version_id, 'CORRECTION', _reason, 'OPEN', auth.uid());
  END IF;

  PERFORM public.create_audit_log('return_filing', v.return_filing_id, 'RETURN_REVIEW_' || _action,
    jsonb_build_object('version_id', _version_id, 'reason', _reason));
  RETURN jsonb_build_object('action', _action, 'new_version_id', v_new_version);
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_save_definition(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid := NULLIF(_payload->>'id','')::uuid;
BEGIN
  PERFORM public.returns_require('manage_config');
  IF COALESCE(_payload->>'code','') = '' OR COALESCE(_payload->>'name','') = '' THEN
    RAISE EXCEPTION 'Code and name are required';
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.return_definitions(
      code, name, description, regulator_id, frequency, filing_basis, consolidation_basis,
      currency_basis, due_days_after_period_end, requires_declaration, declaration_text,
      status, effective_from, effective_to, created_by)
    VALUES (
      upper(_payload->>'code'), _payload->>'name', _payload->>'description',
      NULLIF(_payload->>'regulator_id','')::uuid,
      COALESCE(_payload->>'frequency','QUARTERLY'),
      COALESCE(_payload->>'filing_basis','SOLO'),
      _payload->>'consolidation_basis', _payload->>'currency_basis',
      COALESCE((_payload->>'due_days_after_period_end')::int, 30),
      COALESCE((_payload->>'requires_declaration')::boolean, true),
      _payload->>'declaration_text',
      COALESCE(_payload->>'status','DRAFT'),
      COALESCE((_payload->>'effective_from')::date, CURRENT_DATE),
      NULLIF(_payload->>'effective_to','')::date, auth.uid())
    RETURNING id INTO v_id;
  ELSE
    IF EXISTS (SELECT 1 FROM public.return_definitions d
                WHERE d.id = v_id AND d.code <> upper(_payload->>'code')
                  AND EXISTS (SELECT 1 FROM public.return_filings f WHERE f.return_definition_id = v_id)) THEN
      RAISE EXCEPTION 'Definition code is immutable once filings exist';
    END IF;
    UPDATE public.return_definitions SET
      code = upper(_payload->>'code'), name = _payload->>'name',
      description = _payload->>'description',
      regulator_id = NULLIF(_payload->>'regulator_id','')::uuid,
      frequency = COALESCE(_payload->>'frequency', frequency),
      filing_basis = COALESCE(_payload->>'filing_basis', filing_basis),
      consolidation_basis = _payload->>'consolidation_basis',
      currency_basis = _payload->>'currency_basis',
      due_days_after_period_end = COALESCE((_payload->>'due_days_after_period_end')::int, due_days_after_period_end),
      requires_declaration = COALESCE((_payload->>'requires_declaration')::boolean, requires_declaration),
      declaration_text = _payload->>'declaration_text',
      status = COALESCE(_payload->>'status', status),
      is_active = COALESCE((_payload->>'is_active')::boolean, is_active),
      effective_from = COALESCE((_payload->>'effective_from')::date, effective_from),
      effective_to = NULLIF(_payload->>'effective_to','')::date,
      updated_at = now()
    WHERE id = v_id;
  END IF;

  IF _payload ? 'forms' THEN
    DELETE FROM public.return_definition_forms WHERE return_definition_id = v_id;
    INSERT INTO public.return_definition_forms(
      return_definition_id, form_template_id, sequence, is_required, section_label, tab_name)
    SELECT v_id, (f->>'form_template_id')::uuid,
           COALESCE((f->>'sequence')::int, 1),
           COALESCE((f->>'is_required')::boolean, true),
           f->>'section_label', f->>'tab_name'
      FROM jsonb_array_elements(_payload->'forms') f;
  END IF;

  PERFORM public.create_audit_log('return_definition', v_id, 'SAVE', _payload);
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_save_definition_form(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  PERFORM public.returns_require('manage_config');
  v_id := NULLIF(_payload->>'id','')::uuid;
  IF _payload->>'return_definition_id' IS NULL OR _payload->>'form_template_id' IS NULL THEN
    RAISE EXCEPTION 'Return definition and form template are required';
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.return_definition_forms(
      return_definition_id, form_template_id, sequence, is_required, section_label, tab_name, effective_from)
    VALUES (
      (_payload->>'return_definition_id')::uuid,
      (_payload->>'form_template_id')::uuid,
      COALESCE((_payload->>'sequence')::int, 1),
      COALESCE((_payload->>'is_required')::boolean, true),
      NULLIF(_payload->>'section_label',''),
      NULLIF(_payload->>'tab_name',''),
      COALESCE(NULLIF(_payload->>'effective_from','')::date, CURRENT_DATE))
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.return_definition_forms SET
      sequence = COALESCE((_payload->>'sequence')::int, sequence),
      is_required = COALESCE((_payload->>'is_required')::boolean, is_required),
      section_label = NULLIF(_payload->>'section_label',''),
      tab_name = NULLIF(_payload->>'tab_name','')
     WHERE id = v_id;
  END IF;
  PERFORM public.create_audit_log('return_definition', (_payload->>'return_definition_id')::uuid,
    'RETURN_DEFINITION_FORM_SAVED', _payload);
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_save_metric(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid := NULLIF(_payload->>'id','')::uuid;
        v_expr text := NULLIF(_payload->>'expression','');
        v_deps text[];
BEGIN
  PERFORM public.returns_require('manage_config');
  IF COALESCE(_payload->>'code','') = '' OR COALESCE(_payload->>'name','') = '' THEN
    RAISE EXCEPTION 'Metric code and name are required';
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.regulatory_metrics(
      code, name, description, data_domain_id, data_type, unit, aggregation_type,
      sensitivity, is_calculated, calculation_strategy, effective_from, effective_to, created_by)
    VALUES (upper(_payload->>'code'), _payload->>'name', _payload->>'description',
      NULLIF(_payload->>'data_domain_id','')::uuid,
      COALESCE(_payload->>'data_type','NUMERIC'), _payload->>'unit',
      COALESCE(_payload->>'aggregation_type','POINT_IN_TIME'),
      COALESCE(_payload->>'sensitivity','INTERNAL'),
      COALESCE((_payload->>'is_calculated')::boolean, v_expr IS NOT NULL),
      _payload->>'calculation_strategy',
      COALESCE((_payload->>'effective_from')::date, CURRENT_DATE),
      NULLIF(_payload->>'effective_to','')::date, auth.uid())
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.regulatory_metrics SET
      code = upper(_payload->>'code'), name = _payload->>'name',
      description = _payload->>'description',
      data_domain_id = NULLIF(_payload->>'data_domain_id','')::uuid,
      data_type = COALESCE(_payload->>'data_type', data_type),
      unit = _payload->>'unit',
      aggregation_type = COALESCE(_payload->>'aggregation_type', aggregation_type),
      sensitivity = COALESCE(_payload->>'sensitivity', sensitivity),
      is_calculated = COALESCE((_payload->>'is_calculated')::boolean, is_calculated),
      calculation_strategy = _payload->>'calculation_strategy',
      effective_from = COALESCE((_payload->>'effective_from')::date, effective_from),
      effective_to = NULLIF(_payload->>'effective_to','')::date,
      is_active = COALESCE((_payload->>'is_active')::boolean, is_active)
    WHERE id = v_id;
  END IF;

  IF v_expr IS NOT NULL THEN
    IF v_expr !~ '^[A-Za-z0-9_+\-*/(). ]+$' THEN
      RAISE EXCEPTION 'A formula may only reference metric codes, numbers and + - * / ( )';
    END IF;
    SELECT array_agg(DISTINCT upper(m[1])) INTO v_deps
      FROM regexp_matches(v_expr, '([A-Za-z_][A-Za-z0-9_]*)', 'g') m;
    v_deps := COALESCE(v_deps, '{}');
    IF EXISTS (SELECT 1 FROM unnest(v_deps) d
                WHERE NOT EXISTS (SELECT 1 FROM public.regulatory_metrics rm WHERE rm.code = d)) THEN
      RAISE EXCEPTION 'Formula references a metric that does not exist';
    END IF;
    IF upper(_payload->>'code') = ANY(v_deps) THEN
      RAISE EXCEPTION 'A metric formula cannot reference itself';
    END IF;
    UPDATE public.metric_calculation_rules SET is_active = false WHERE regulatory_metric_id = v_id;
    INSERT INTO public.metric_calculation_rules(
      regulatory_metric_id, version, expression, dependency_metric_codes,
      on_missing_dependency, notes, created_by)
    VALUES (v_id,
      COALESCE((SELECT max(version) FROM public.metric_calculation_rules WHERE regulatory_metric_id = v_id), 0) + 1,
      v_expr, v_deps,
      COALESCE(_payload->>'on_missing_dependency','NOT_AVAILABLE'),
      _payload->>'formula_notes', auth.uid());
    UPDATE public.regulatory_metrics SET is_calculated = true WHERE id = v_id;
  END IF;

  PERFORM public.create_audit_log('regulatory_metric', v_id, 'SAVE', _payload);
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_save_obligation_rule(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid := NULLIF(_payload->>'id','')::uuid;
BEGIN
  PERFORM public.returns_require('manage_config');
  IF NULLIF(_payload->>'return_definition_id','') IS NULL THEN
    RAISE EXCEPTION 'A rule must belong to a return definition';
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.reporting_obligation_rules(
      return_definition_id, code, name, description, regulator_id, sector_id, sub_sector_id,
      category_id, license_type_id, classification_value_id, lifecycle_stage_id,
      requires_active_license, jurisdiction, priority, frequency_override, due_days_override,
      effective_from, effective_to, created_by)
    VALUES (
      (_payload->>'return_definition_id')::uuid, upper(_payload->>'code'), _payload->>'name',
      _payload->>'description', NULLIF(_payload->>'regulator_id','')::uuid,
      NULLIF(_payload->>'sector_id','')::uuid, NULLIF(_payload->>'sub_sector_id','')::uuid,
      NULLIF(_payload->>'category_id','')::uuid, NULLIF(_payload->>'license_type_id','')::uuid,
      NULLIF(_payload->>'classification_value_id','')::uuid, NULLIF(_payload->>'lifecycle_stage_id','')::uuid,
      COALESCE((_payload->>'requires_active_license')::boolean, true),
      _payload->>'jurisdiction', COALESCE((_payload->>'priority')::int, 100),
      NULLIF(_payload->>'frequency_override',''), NULLIF(_payload->>'due_days_override','')::int,
      COALESCE((_payload->>'effective_from')::date, CURRENT_DATE),
      NULLIF(_payload->>'effective_to','')::date, auth.uid())
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.reporting_obligation_rules SET
      name = _payload->>'name', description = _payload->>'description',
      regulator_id = NULLIF(_payload->>'regulator_id','')::uuid,
      sector_id = NULLIF(_payload->>'sector_id','')::uuid,
      sub_sector_id = NULLIF(_payload->>'sub_sector_id','')::uuid,
      category_id = NULLIF(_payload->>'category_id','')::uuid,
      license_type_id = NULLIF(_payload->>'license_type_id','')::uuid,
      classification_value_id = NULLIF(_payload->>'classification_value_id','')::uuid,
      lifecycle_stage_id = NULLIF(_payload->>'lifecycle_stage_id','')::uuid,
      requires_active_license = COALESCE((_payload->>'requires_active_license')::boolean, requires_active_license),
      jurisdiction = _payload->>'jurisdiction',
      priority = COALESCE((_payload->>'priority')::int, priority),
      frequency_override = NULLIF(_payload->>'frequency_override',''),
      due_days_override = NULLIF(_payload->>'due_days_override','')::int,
      effective_from = COALESCE((_payload->>'effective_from')::date, effective_from),
      effective_to = NULLIF(_payload->>'effective_to','')::date,
      is_active = COALESCE((_payload->>'is_active')::boolean, is_active),
      updated_at = now()
    WHERE id = v_id;
  END IF;
  PERFORM public.create_audit_log('reporting_obligation_rule', v_id, 'SAVE', _payload);
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_set_definition_status(_definition_id uuid, _status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d record;
BEGIN
  PERFORM public.returns_require('manage_config');
  IF _status NOT IN ('DRAFT','ACTIVE','SUSPENDED','RETIRED') THEN
    RAISE EXCEPTION 'Unsupported definition status %', _status;
  END IF;
  SELECT * INTO d FROM public.return_definitions WHERE id = _definition_id FOR UPDATE;
  IF d.id IS NULL THEN RAISE EXCEPTION 'Return definition not found'; END IF;
  IF d.status = 'RETIRED' AND _status <> 'RETIRED' THEN
    RAISE EXCEPTION 'A retired return definition cannot be reactivated';
  END IF;
  UPDATE public.return_definitions
     SET status = _status,
         is_active = (_status = 'ACTIVE'),
         effective_to = CASE WHEN _status = 'RETIRED' THEN COALESCE(effective_to, CURRENT_DATE) ELSE effective_to END,
         updated_at = now()
   WHERE id = _definition_id;
  PERFORM public.create_audit_log('return_definition', _definition_id, 'RETURN_DEFINITION_STATUS',
    jsonb_build_object('from', d.status, 'to', _status));
  RETURN jsonb_build_object('id', _definition_id, 'status', _status);
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_submit_filing(_version_id uuid, _declaration_accepted boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v record; d record; v_check jsonb;
BEGIN
  SELECT v2.id, v2.status, v2.return_filing_id, f.entity_id, f.return_definition_id, f.id AS filing_id
    INTO v FROM public.return_filing_versions v2
    JOIN public.return_filings f ON f.id = v2.return_filing_id
   WHERE v2.id = _version_id FOR UPDATE;
  IF v.id IS NULL THEN RAISE EXCEPTION 'Filing version not found'; END IF;
  IF NOT public.returns_can_file(v.entity_id) THEN
    RAISE EXCEPTION 'You are not authorised to submit returns for this entity' USING ERRCODE='42501';
  END IF;
  IF v.status NOT IN ('DRAFT','CORRECTION_REQUESTED') THEN
    RAISE EXCEPTION 'This filing version has already been submitted';
  END IF;

  SELECT * INTO d FROM public.return_definitions WHERE id = v.return_definition_id;
  IF d.requires_declaration AND NOT _declaration_accepted THEN
    RAISE EXCEPTION 'The declaration must be accepted before submission';
  END IF;

  PERFORM public.returns_extract_metrics(_version_id);
  PERFORM public.returns_calculate_metrics(_version_id);
  v_check := public.returns_validate_filing(_version_id);
  IF NOT (v_check->>'can_submit')::boolean THEN
    RETURN jsonb_build_object('submitted', false, 'validation', v_check);
  END IF;

  UPDATE public.return_filing_versions
     SET status = 'SUBMITTED', is_immutable = true, submitted_at = now(), submitted_by = auth.uid(),
         declaration_accepted_at = CASE WHEN _declaration_accepted THEN now() END,
         declaration_accepted_by = CASE WHEN _declaration_accepted THEN auth.uid() END
   WHERE id = _version_id;

  UPDATE public.return_filings
     SET status = 'SUBMITTED', submitted_at = COALESCE(submitted_at, now()), updated_at = now()
   WHERE id = v.filing_id;

  UPDATE public.return_filing_requests SET status = 'RESOLVED', updated_at = now()
   WHERE return_filing_id = v.filing_id AND status IN ('OPEN','RESPONDED') AND request_kind = 'CORRECTION';

  PERFORM public.create_audit_log('return_filing', v.filing_id, 'SUBMIT',
    jsonb_build_object('version_id', _version_id, 'validation', v_check));

  RETURN jsonb_build_object('submitted', true, 'validation', v_check);
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_supervisory_summary(_sector_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH scoped AS (
    SELECT w.*
    FROM public.v_return_filing_workflow_state w
    LEFT JOIN public.licensees l ON l.id = w.entity_id
    WHERE _sector_id IS NULL OR l.sector_id = _sector_id
  )
  SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM scoped),
    'draft', (SELECT count(*) FROM scoped WHERE status = 'DRAFT'),
    'submitted', (SELECT count(*) FROM scoped WHERE status IN ('SUBMITTED','UNDER_REVIEW','CORRECTION_REQUESTED','ACCEPTED','REJECTED')),
    'pending_review', (SELECT count(*) FROM scoped WHERE status IN ('SUBMITTED','UNDER_REVIEW')),
    'correction_requested', (SELECT count(*) FROM scoped WHERE status = 'CORRECTION_REQUESTED'),
    'accepted', (SELECT count(*) FROM scoped WHERE status = 'ACCEPTED'),
    'rejected', (SELECT count(*) FROM scoped WHERE status = 'REJECTED'),
    'overdue', (SELECT count(*) FROM scoped WHERE is_overdue),
    'due_soon', (SELECT count(*) FROM scoped WHERE NOT is_overdue AND sla_state = 'DUE_SOON'),
    'sla_breached', (SELECT count(*) FROM scoped WHERE sla_state = 'BREACHED'),
    'top_overdue', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', filing_id, 'filing_reference', filing_reference, 'entity_id', entity_id,
        'entity_name', entity_name, 'definition_name', definition_name,
        'period_label', period_label, 'due_date', due_date, 'days_late', days_late,
        'status', status, 'stage', stage))
      FROM (SELECT * FROM scoped WHERE is_overdue ORDER BY due_date NULLS LAST LIMIT 5) t
    ), '[]'::jsonb)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.returns_test_obligation_rule(_rule_id uuid, _entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; e record; d record; v_reasons jsonb := '[]'::jsonb; v_match boolean := true;
        v_has_lic boolean; v_freq text; v_due int;
  PROCEDURE_placeholder int;
BEGIN
  PERFORM public.returns_require('manage_config');
  SELECT * INTO r FROM public.reporting_obligation_rules WHERE id = _rule_id;
  IF r.id IS NULL THEN RAISE EXCEPTION 'Obligation rule not found'; END IF;
  SELECT id, name, sector_id, sub_sector_id, category_id, lifecycle_stage_id, status
    INTO e FROM public.licensees WHERE id = _entity_id;
  IF e.id IS NULL THEN RAISE EXCEPTION 'Entity not found'; END IF;
  SELECT * INTO d FROM public.return_definitions WHERE id = r.return_definition_id;

  IF NOT r.is_active THEN v_match := false;
    v_reasons := v_reasons || jsonb_build_object('dimension','rule_active','pass',false,'detail','Rule is inactive');
  ELSE v_reasons := v_reasons || jsonb_build_object('dimension','rule_active','pass',true,'detail','Rule is active'); END IF;

  IF NOT (d.is_active AND d.status = 'ACTIVE') THEN v_match := false;
    v_reasons := v_reasons || jsonb_build_object('dimension','definition_status','pass',false,'detail','Return definition is '||d.status);
  ELSE v_reasons := v_reasons || jsonb_build_object('dimension','definition_status','pass',true,'detail','Return definition is ACTIVE'); END IF;

  IF r.effective_from > CURRENT_DATE OR (r.effective_to IS NOT NULL AND r.effective_to < CURRENT_DATE) THEN
    v_match := false;
    v_reasons := v_reasons || jsonb_build_object('dimension','effective_window','pass',false,'detail','Today is outside the rule effective window');
  ELSE v_reasons := v_reasons || jsonb_build_object('dimension','effective_window','pass',true,'detail','Rule is in force today'); END IF;

  IF r.sector_id IS NULL THEN
    v_reasons := v_reasons || jsonb_build_object('dimension','sector','pass',true,'detail','Any sector');
  ELSIF r.sector_id = e.sector_id THEN
    v_reasons := v_reasons || jsonb_build_object('dimension','sector','pass',true,'detail','Entity sector matches');
  ELSE v_match := false;
    v_reasons := v_reasons || jsonb_build_object('dimension','sector','pass',false,'detail','Entity sector does not match');
  END IF;

  IF r.sub_sector_id IS NULL THEN
    v_reasons := v_reasons || jsonb_build_object('dimension','sub_sector','pass',true,'detail','Any sub-sector');
  ELSIF r.sub_sector_id = e.sub_sector_id THEN
    v_reasons := v_reasons || jsonb_build_object('dimension','sub_sector','pass',true,'detail','Entity sub-sector matches');
  ELSE v_match := false;
    v_reasons := v_reasons || jsonb_build_object('dimension','sub_sector','pass',false,'detail','Entity sub-sector does not match');
  END IF;

  IF r.category_id IS NULL THEN
    v_reasons := v_reasons || jsonb_build_object('dimension','category','pass',true,'detail','Any category');
  ELSIF r.category_id = e.category_id THEN
    v_reasons := v_reasons || jsonb_build_object('dimension','category','pass',true,'detail','Entity category matches');
  ELSE v_match := false;
    v_reasons := v_reasons || jsonb_build_object('dimension','category','pass',false,'detail','Entity category does not match');
  END IF;

  IF r.lifecycle_stage_id IS NULL THEN
    v_reasons := v_reasons || jsonb_build_object('dimension','lifecycle','pass',true,'detail','Any lifecycle stage');
  ELSIF r.lifecycle_stage_id = e.lifecycle_stage_id THEN
    v_reasons := v_reasons || jsonb_build_object('dimension','lifecycle','pass',true,'detail','Lifecycle stage matches');
  ELSE v_match := false;
    v_reasons := v_reasons || jsonb_build_object('dimension','lifecycle','pass',false,'detail','Lifecycle stage does not match');
  END IF;

  IF r.classification_value_id IS NULL THEN
    v_reasons := v_reasons || jsonb_build_object('dimension','classification','pass',true,'detail','Any classification');
  ELSE
    IF EXISTS (SELECT 1 FROM public.entity_facts f
                WHERE f.entity_id = _entity_id AND f.classification_value_id = r.classification_value_id) THEN
      v_reasons := v_reasons || jsonb_build_object('dimension','classification','pass',true,'detail','Entity carries the required classification');
    ELSE v_match := false;
      v_reasons := v_reasons || jsonb_build_object('dimension','classification','pass',false,'detail','Entity does not carry the required classification');
    END IF;
  END IF;

  IF r.requires_active_license THEN
    SELECT EXISTS (SELECT 1 FROM public.entity_licenses el
                    WHERE el.entity_id = _entity_id
                      AND (el.effective_to IS NULL OR el.effective_to > now())) INTO v_has_lic;
    IF v_has_lic THEN
      v_reasons := v_reasons || jsonb_build_object('dimension','active_licence','pass',true,'detail','Entity holds an in-force licence');
    ELSE v_match := false;
      v_reasons := v_reasons || jsonb_build_object('dimension','active_licence','pass',false,'detail','Entity holds no in-force licence');
    END IF;
  ELSE
    v_reasons := v_reasons || jsonb_build_object('dimension','active_licence','pass',true,'detail','Active licence not required');
  END IF;

  IF r.jurisdiction IS NOT NULL THEN
    v_reasons := v_reasons || jsonb_build_object('dimension','jurisdiction','pass',true,'detail','Rule jurisdiction: '||r.jurisdiction);
  END IF;

  v_freq := COALESCE(r.frequency_override, d.frequency);
  v_due := COALESCE(r.due_days_override, d.due_days_after_period_end);

  RETURN jsonb_build_object(
    'matches', v_match,
    'entity_id', _entity_id,
    'entity_name', e.name,
    'rule_code', r.code,
    'rule_name', r.name,
    'priority', r.priority,
    'definition_code', d.code,
    'definition_name', d.name,
    'frequency', v_freq,
    'frequency_source', CASE WHEN r.frequency_override IS NOT NULL THEN 'RULE_OVERRIDE' ELSE 'DEFINITION' END,
    'due_days_after_period_end', v_due,
    'due_days_source', CASE WHEN r.due_days_override IS NOT NULL THEN 'RULE_OVERRIDE' ELSE 'DEFINITION' END,
    'example_period_end', date_trunc('quarter', CURRENT_DATE)::date - 1,
    'example_due_date', (date_trunc('quarter', CURRENT_DATE)::date - 1) + v_due,
    'already_obliged', EXISTS (SELECT 1 FROM public.entity_reporting_obligations o
                                WHERE o.entity_id = _entity_id
                                  AND o.return_definition_id = r.return_definition_id
                                  AND o.status = 'ACTIVE'),
    'reasons', v_reasons
  );
END $function$
;
CREATE OR REPLACE FUNCTION public.returns_validate_filing(_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v record; v_errors int; v_warnings int;
BEGIN
  SELECT v2.id, v2.return_filing_id, f.entity_id INTO v
    FROM public.return_filing_versions v2
    JOIN public.return_filings f ON f.id = v2.return_filing_id
   WHERE v2.id = _version_id;
  IF v.id IS NULL THEN RAISE EXCEPTION 'Filing version not found'; END IF;

  DELETE FROM public.return_filing_validation_results WHERE return_filing_version_id = _version_id;

  INSERT INTO public.return_filing_validation_results(
    return_filing_id, return_filing_version_id, severity, rule_code, scope,
    form_template_id, message, is_blocking)
  SELECT v.return_filing_id, _version_id, 'ERROR', 'REQUIRED_FORM_INCOMPLETE', 'FORM',
         r.form_template_id,
         'A required part of this return has not been completed: ' || COALESCE(t.name, 'form'), true
    FROM public.return_filing_form_requirements r
    LEFT JOIN public.form_templates t ON t.id = r.form_template_id
   WHERE r.return_filing_version_id = _version_id
     AND r.is_required AND (r.form_response_id IS NULL OR r.completion_status <> 'COMPLETED');

  INSERT INTO public.return_filing_validation_results(
    return_filing_id, return_filing_version_id, severity, rule_code, scope,
    regulatory_metric_id, message, is_blocking)
  SELECT v.return_filing_id, _version_id, 'WARNING', 'METRIC_NOT_AVAILABLE', 'METRIC',
         mv.regulatory_metric_id,
         'A measurement could not be determined for this period: ' || m.name, false
    FROM public.return_metric_values mv
    JOIN public.regulatory_metrics m ON m.id = mv.regulatory_metric_id
   WHERE mv.return_filing_version_id = _version_id AND mv.availability <> 'AVAILABLE';

  SELECT count(*) FILTER (WHERE severity = 'ERROR'), count(*) FILTER (WHERE severity = 'WARNING')
    INTO v_errors, v_warnings
    FROM public.return_filing_validation_results WHERE return_filing_version_id = _version_id;

  RETURN jsonb_build_object('errors', v_errors, 'warnings', v_warnings,
                            'can_submit', v_errors = 0);
END $function$
;
CREATE OR REPLACE FUNCTION public.review_prudential_action_response(_action_id uuid, _decision text, _notes text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid();
        _a public.prudential_actions;
        _has_resp boolean;
        _new_status text;
BEGIN
  IF _uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHENTICATED');
  END IF;
  IF _decision NOT IN ('accepted','rejected') THEN
    RETURN jsonb_build_object('error','Decision must be accepted or rejected','code','VALIDATION');
  END IF;
  IF _notes IS NULL OR length(trim(_notes)) < 5 THEN
    RETURN jsonb_build_object('error','Review notes of at least 5 characters are required','code','VALIDATION');
  END IF;
  SELECT * INTO _a FROM public.prudential_actions WHERE id = _action_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Action not found','code','NOT_FOUND');
  END IF;
  IF NOT (public.is_super_admin(_uid)
          OR public.has_permission(_uid,'prudential_supervision','workflow_action')
          OR public.has_permission(_uid,'prudential_supervision','edit')
          OR public.has_permission(_uid,'prudential_supervision','manage_remediation')) THEN
    RETURN jsonb_build_object('error','You are not permitted to review supervisory actions','code','FORBIDDEN');
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.prudential_action_responses r
                  WHERE r.action_id = _action_id AND r.kind = 'entity_response') INTO _has_resp;
  IF NOT _has_resp THEN
    RETURN jsonb_build_object('error','There is no entity response to review','code','NO_RESPONSE');
  END IF;

  _new_status := CASE WHEN _decision = 'accepted' THEN 'completed' ELSE 'in_progress' END;

  INSERT INTO public.prudential_action_responses(action_id, kind, narrative, decision, submitted_by)
  VALUES (_action_id, 'supervisor_review', trim(_notes), _decision, _uid);

  UPDATE public.prudential_actions
     SET review_status = _decision,
         review_notes = trim(_notes),
         reviewed_by = _uid,
         reviewed_at = now(),
         status = _new_status,
         completion_notes = CASE WHEN _decision = 'accepted' THEN trim(_notes) ELSE completion_notes END,
         closed_at = CASE WHEN _decision = 'accepted' THEN now() ELSE closed_at END,
         closed_by = CASE WHEN _decision = 'accepted' THEN _uid ELSE closed_by END,
         progress_percent = CASE WHEN _decision = 'accepted' THEN 100 ELSE progress_percent END,
         updated_at = now()
   WHERE id = _action_id;

  INSERT INTO public.prudential_action_events(action_id, event_type, from_status, to_status, actor_id, reason)
  VALUES (_action_id, 'supervisor_review_' || _decision, _a.status, _new_status, _uid, trim(_notes));

  RETURN jsonb_build_object('ok', true, 'status', _new_status, 'review_status', _decision);
END $function$
;
CREATE OR REPLACE FUNCTION public.rfi_pause_sla()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.pauses_sla AND NEW.status IN ('open') THEN
      UPDATE public.workflow_instances
        SET paused_at = COALESCE(paused_at, now()),
            paused_reason = COALESCE(paused_reason, 'RFI ' || NEW.id::text),
            resumed_at = NULL
        WHERE entity_type = 'application' AND entity_id = NEW.application_id AND status = 'active';

      PERFORM public.sla_stage_pause('application', NEW.application_id, 'rfi_open',
                                     jsonb_build_object('rfi_id', NEW.id));

      INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, new_value, metadata)
        VALUES (auth.uid(), 'workflow.sla.paused', 'application', NEW.application_id,
                jsonb_build_object('rfi_id', NEW.id),
                jsonb_build_object('trigger','rfi_open'));
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.pauses_sla AND OLD.status = 'open' AND NEW.status IN ('responded','closed','cancelled') THEN
      UPDATE public.workflow_instances w
        SET resumed_at = now(),
            total_pause_seconds = w.total_pause_seconds + GREATEST(0, EXTRACT(EPOCH FROM (now() - COALESCE(w.paused_at, now())))::int),
            paused_at = NULL,
            paused_reason = NULL
        WHERE w.entity_type='application' AND w.entity_id = NEW.application_id AND w.status='active';

      PERFORM public.sla_stage_resume('application', NEW.application_id, 'rfi_' || NEW.status,
                                      jsonb_build_object('rfi_id', NEW.id));

      INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, new_value, metadata)
        VALUES (auth.uid(), 'workflow.sla.resumed', 'application', NEW.application_id,
                jsonb_build_object('rfi_id', NEW.id, 'new_status', NEW.status),
                jsonb_build_object('trigger','rfi_'||NEW.status));
    END IF;
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.role_scope_for(_role_id uuid, _module text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT (scope_config -> _module) FROM public.roles WHERE id = _role_id),
    jsonb_build_object('scope','all')
  );
$function$
;
CREATE OR REPLACE FUNCTION public.rollback_prudential_ratio(_ratio_id uuid, _to_version integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _snap public.prudential_ratio_versions; _next integer; _row public.prudential_ratios;
BEGIN
  IF NOT public.can_manage_prudential_config(auth.uid()) THEN
    RAISE EXCEPTION 'You do not have permission to manage prudential configuration';
  END IF;
  PERFORM set_config('app.version_maintenance','on',true);
  SELECT * INTO _snap FROM public.prudential_ratio_versions WHERE ratio_id=_ratio_id AND version=_to_version;
  IF _snap IS NULL THEN RAISE EXCEPTION 'Version % not found', _to_version; END IF;
  UPDATE public.prudential_ratios SET formula=_snap.formula, display_format=_snap.display_format, updated_at=now() WHERE id=_ratio_id;
  SELECT COALESCE(MAX(version),0)+1 INTO _next FROM public.prudential_ratio_versions WHERE ratio_id=_ratio_id;
  SELECT * INTO _row FROM public.prudential_ratios WHERE id=_ratio_id;
  IF NOT EXISTS (SELECT 1 FROM public.prudential_ratio_versions WHERE ratio_id=_ratio_id AND version=_next) THEN
    INSERT INTO public.prudential_ratio_versions(ratio_id, version, formula, display_format, published_by)
      VALUES (_ratio_id, _next, _row.formula, _row.display_format, auth.uid());
  END IF;
  SELECT COALESCE(MAX(version),1) INTO _next FROM public.prudential_ratio_versions WHERE ratio_id=_ratio_id;
  UPDATE public.prudential_ratios SET current_version=_next WHERE id=_ratio_id;
  PERFORM public.log_compliance_audit('UPDATE','prudential_ratios',_ratio_id::text,NULL,to_jsonb(_row),'Ratio rolled back',NULL,NULL,jsonb_build_object('event','RATIO_ROLLBACK','from_version',_to_version,'new_version',_next));
  RETURN _next;
END $function$
;
CREATE OR REPLACE FUNCTION public.rollback_prudential_threshold(_threshold_id uuid, _to_version integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _snap public.prudential_threshold_versions; _next integer; _row public.prudential_thresholds;
BEGIN
  IF NOT public.can_manage_prudential_config(auth.uid()) THEN RAISE EXCEPTION 'Not authorised to manage prudential configuration'; END IF;
  SELECT * INTO _snap FROM public.prudential_threshold_versions WHERE threshold_id=_threshold_id AND version=_to_version;
  IF _snap IS NULL THEN RAISE EXCEPTION 'Version % not found', _to_version; END IF;
  PERFORM set_config('app.version_maintenance','on',true);
  UPDATE public.prudential_thresholds
    SET warn_value=_snap.warn_value, breach_value=_snap.breach_value, upper_value=_snap.upper_value,
        comparator=_snap.comparator, unit=_snap.unit, updated_at=now()
    WHERE id=_threshold_id;
  UPDATE public.prudential_threshold_versions SET effective_to = current_date - 1
    WHERE threshold_id=_threshold_id AND effective_to IS NULL;
  SELECT COALESCE(MAX(version),0)+1 INTO _next FROM public.prudential_threshold_versions WHERE threshold_id=_threshold_id;
  SELECT * INTO _row FROM public.prudential_thresholds WHERE id=_threshold_id;
  IF NOT EXISTS (SELECT 1 FROM public.prudential_threshold_versions WHERE threshold_id=_threshold_id AND version=_next) THEN
    INSERT INTO public.prudential_threshold_versions(threshold_id, version, warn_value, breach_value, upper_value, comparator, unit, effective_from, published_by)
      VALUES (_threshold_id, _next, _row.warn_value, _row.breach_value, _row.upper_value, _row.comparator, _row.unit, current_date, auth.uid());
  END IF;
  SELECT COALESCE(MAX(version),1) INTO _next FROM public.prudential_threshold_versions WHERE threshold_id=_threshold_id;
  UPDATE public.prudential_thresholds SET current_version=_next, effective_from=current_date WHERE id=_threshold_id;
  PERFORM set_config('app.version_maintenance','off',true);
  PERFORM public.log_compliance_audit('UPDATE','prudential_thresholds',_threshold_id::text,NULL,to_jsonb(_row),'Threshold rolled back',NULL,NULL,jsonb_build_object('event','THRESHOLD_ROLLBACK','from_version',_to_version,'new_version',_next));
  RETURN _next;
END $function$
;
CREATE OR REPLACE FUNCTION public.rollback_validation_rule(_rule_id uuid, _to_version integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _def jsonb; _next integer;
BEGIN
  IF NOT public.can_manage_returns_config(auth.uid()) THEN
    RAISE EXCEPTION 'You do not have permission to manage returns configuration';
  END IF;
  PERFORM set_config('app.version_maintenance','on',true);
  SELECT definition INTO _def FROM public.return_validation_rule_versions
    WHERE rule_id = _rule_id AND version = _to_version;
  IF _def IS NULL THEN RAISE EXCEPTION 'Version % not found for this rule', _to_version; END IF;

  UPDATE public.return_validation_rules SET
    name          = COALESCE(_def->>'name', name),
    scope         = COALESCE(_def->>'scope', scope),
    rule_type     = COALESCE(_def->>'rule_type', rule_type),
    expression    = COALESCE(_def->>'expression', expression),
    error_message = COALESCE(_def->>'error_message', error_message),
    severity      = COALESCE(_def->>'severity', severity),
    form_id       = NULLIF(_def->>'form_id','')::uuid,
    is_active     = COALESCE((_def->>'is_active')::boolean, is_active),
    updated_at    = now()
  WHERE id = _rule_id;

  UPDATE public.return_validation_rule_versions SET is_current = false WHERE rule_id = _rule_id AND is_current;
  SELECT COALESCE(MAX(version),0)+1 INTO _next FROM public.return_validation_rule_versions WHERE rule_id = _rule_id;
  IF NOT EXISTS (SELECT 1 FROM public.return_validation_rule_versions WHERE rule_id=_rule_id AND version=_next) THEN
    INSERT INTO public.return_validation_rule_versions(rule_id, version, definition, published_by, is_current)
      VALUES (_rule_id, _next, _def || jsonb_build_object('rolled_back_from', _to_version), auth.uid(), true);
  END IF;
  SELECT COALESCE(MAX(version),1) INTO _next FROM public.return_validation_rule_versions WHERE rule_id = _rule_id;
  UPDATE public.return_validation_rules SET current_version = _next WHERE id = _rule_id;
  PERFORM public.log_compliance_audit('UPDATE','return_validation_rules', _rule_id::text, NULL, _def,
    'Rule rolled back', NULL, NULL,
    jsonb_build_object('event','RULE_ROLLBACK','from_version',_to_version,'new_version',_next));
  RETURN _next;
END $function$
;
CREATE OR REPLACE FUNCTION public.rule_inventory_search(_search text DEFAULT NULL::text, _family text DEFAULT NULL::text, _module text DEFAULT NULL::text, _sub_module text DEFAULT NULL::text, _rule_type text DEFAULT NULL::text, _status text DEFAULT NULL::text, _severity text DEFAULT NULL::text, _tag text DEFAULT NULL::text, _triggered_from timestamp with time zone DEFAULT NULL::timestamp with time zone, _triggered_to timestamp with time zone DEFAULT NULL::timestamp with time zone, _sort text DEFAULT 'last_modified_at'::text, _dir text DEFAULT 'desc'::text, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rows jsonb; v_total int; v_kpi jsonb; v_facets jsonb;
  v_sort text := lower(coalesce(_sort,'last_modified_at'));
  v_dir text := CASE WHEN lower(coalesce(_dir,'desc')) = 'asc' THEN 'ASC' ELSE 'DESC' END;
  v_limit int := least(greatest(coalesce(_limit,50),1),200);
  v_offset int := greatest(coalesce(_offset,0),0);
  v_where text;
  v_families text[] := ARRAY['shared_engine','return_validation','prudential','conduct',
                             'complaint_triage','sufficiency','rfi_auto','correspondence','escalation'];
BEGIN
  IF NOT public.can_view_rule_engine(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_sort NOT IN ('rule_code','name','family','module','rule_type','severity','status',
                    'trigger_count','last_triggered_at','last_tested_at','last_modified_at') THEN
    v_sort := 'last_modified_at';
  END IF;

  v_where := $w$
    ($1 IS NULL OR btrim($1) = ''
      OR concat_ws(' ', i.rule_code, i.name, i.description, i.module, i.sub_module,
                   array_to_string(i.tags,' ')) ILIKE '%' || btrim($1) || '%')
    AND ($2 IS NULL OR $2 = 'all' OR i.family = $2)
    AND ($3 IS NULL OR $3 = 'all' OR i.module = $3)
    AND ($4 IS NULL OR $4 = 'all' OR i.sub_module = $4)
    AND ($5 IS NULL OR $5 = 'all' OR i.rule_type = $5)
    AND ($6 IS NULL OR $6 = 'all' OR i.status = $6)
    AND ($7 IS NULL OR $7 = 'all' OR i.severity = $7)
    AND ($8 IS NULL OR $8 = 'all' OR i.tags @> ARRAY[$8])
    AND ($9 IS NULL OR i.last_triggered_at >= $9)
    AND ($10 IS NULL OR i.last_triggered_at <= $10)
  $w$;

  EXECUTE 'SELECT count(*) FROM public.rule_inventory_ext i WHERE ' || v_where
  INTO v_total
  USING _search, _family, _module, _sub_module, _rule_type, _status, _severity, _tag,
        _triggered_from, _triggered_to;

  EXECUTE format($q$
    SELECT coalesce(jsonb_agg(to_jsonb(x) || jsonb_build_object(
             'owner_name', (SELECT p.full_name FROM public.profiles p WHERE p.id = x.owner_user_id),
             'modified_by_name', (SELECT p.full_name FROM public.profiles p WHERE p.id = x.last_modified_by)
           )), '[]'::jsonb)
    FROM (
      SELECT * FROM public.rule_inventory_ext i
      WHERE %1$s
      ORDER BY i.%2$I %3$s NULLS LAST, i.rule_code ASC
      LIMIT %4$s OFFSET %5$s
    ) x
  $q$, v_where, v_sort, v_dir, v_limit, v_offset)
  INTO v_rows
  USING _search, _family, _module, _sub_module, _rule_type, _status, _severity, _tag,
        _triggered_from, _triggered_to;

  SELECT jsonb_build_object(
    'total', count(*),
    'active', count(*) FILTER (WHERE status = 'active'),
    'draft', count(*) FILTER (WHERE status = 'draft'),
    'inactive', count(*) FILTER (WHERE status = 'inactive'),
    'never_executed', count(*) FILTER (WHERE coalesce(trigger_count,0) = 0),
    'never_tested', count(*) FILTER (WHERE last_tested_at IS NULL AND capabilities->>'test' = 'true'),
    'stale_tests', count(*) FILTER (WHERE capabilities->>'test' = 'true'
                     AND last_tested_at IS NOT NULL AND last_tested_at < now() - interval '90 days'),
    'families', (
      SELECT jsonb_object_agg(f.fam, coalesce(c.cnt, 0))
      FROM unnest(v_families) AS f(fam)
      LEFT JOIN (SELECT family, count(*) AS cnt FROM public.rule_inventory_ext GROUP BY family) c
             ON c.family = f.fam
    ),
    'failing', (
      SELECT count(DISTINCT e.rule_id) FROM public.engine_rule_executions e
       WHERE e.executed_at > now() - interval '30 days' AND e.reason ILIKE 'error%'
    )
  ) INTO v_kpi
  FROM public.rule_inventory_ext;

  SELECT jsonb_build_object(
    'modules', (SELECT coalesce(jsonb_agg(DISTINCT i.module), '[]'::jsonb)
                  FROM public.rule_inventory_ext i WHERE i.module IS NOT NULL),
    'sub_modules', (SELECT coalesce(jsonb_agg(DISTINCT i.sub_module), '[]'::jsonb)
                  FROM public.rule_inventory_ext i WHERE i.sub_module IS NOT NULL),
    'rule_types', (SELECT coalesce(jsonb_agg(DISTINCT i.rule_type), '[]'::jsonb)
                  FROM public.rule_inventory_ext i WHERE i.rule_type IS NOT NULL),
    'severities', (SELECT coalesce(jsonb_agg(DISTINCT i.severity), '[]'::jsonb)
                  FROM public.rule_inventory_ext i WHERE i.severity IS NOT NULL),
    'tags', (SELECT coalesce(jsonb_agg(DISTINCT tg), '[]'::jsonb)
                  FROM public.rule_inventory_ext i, unnest(coalesce(i.tags, ARRAY[]::text[])) AS t(tg))
  ) INTO v_facets;

  RETURN jsonb_build_object('rows', v_rows, 'total', v_total, 'kpis', v_kpi, 'facets', v_facets);
END; $function$
;
CREATE OR REPLACE FUNCTION public.rule_module_test(_family text, _rule_id uuid, _inputs jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_start timestamptz := clock_timestamp();
  v_corr uuid := gen_random_uuid();
  v_code text;
  v_name text;
  v_conditions jsonb := '[]'::jsonb;
  v_actions jsonb := '[]'::jsonb;
  v_matched boolean := false;
  v_notes text;
  v_out jsonb;
  v_in jsonb := coalesce(_inputs, '{}'::jsonb);
  r record;
  r2 public.prudential_thresholds;
  v_decision jsonb;
  v_route jsonb;
  v_effective uuid;
  v_risk text;
  v_from timestamptz;
  v_asof timestamptz;
BEGIN
  IF NOT public.can_manage_rule_engine(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _family IS NULL OR _rule_id IS NULL THEN
    RAISE EXCEPTION 'family and rule id are required' USING ERRCODE = '22023';
  END IF;

  -- ---------------- Return validation ----------------
  IF _family = 'return_validation' THEN
    SELECT * INTO r FROM public.return_validation_rules WHERE id = _rule_id;
    IF r.id IS NULL THEN RAISE EXCEPTION 'rule not found' USING ERRCODE='P0002'; END IF;
    v_code := 'RVR-' || left(replace(r.id::text,'-',''),8);
    v_name := r.name;
    SELECT jsonb_agg(jsonb_build_object(
             'label', 'field ' || f.ref,
             'metric', f.ref,
             'actual', coalesce(v_in->'values'->f.ref, 'null'::jsonb),
             'operator', coalesce(v_in->>'operator', 'is_present'),
             'expected', coalesce(v_in->'expected', 'null'::jsonb),
             'passed', public.rule_test_compare(v_in->'values'->f.ref,
                        coalesce(v_in->>'operator','is_present'), v_in->'expected'),
             'reason', CASE WHEN (v_in->'values'->f.ref) IS NULL
                            THEN 'no sample value supplied for this field'
                            ELSE 'evaluated against sample value' END))
      INTO v_conditions
      FROM jsonb_array_elements_text(coalesce(r.field_refs,'[]'::jsonb)) AS f(ref);
    v_conditions := coalesce(v_conditions, '[]'::jsonb);
    v_matched := EXISTS (SELECT 1 FROM jsonb_array_elements(v_conditions) c WHERE (c->>'passed')::boolean IS FALSE);
    v_actions := jsonb_build_array(jsonb_build_object(
      'index', 0, 'type', 'validation_finding', 'severity', r.severity,
      'message', r.error_message,
      'blocks_submission', (lower(coalesce(r.severity,'')) IN ('error','critical'))));
    v_notes := 'Expression: ' || coalesce(r.expression,'(none)') ||
               '. Expression arithmetic is evaluated by evaluate_return_validations() at submission time; '
               'this tester reports field-level presence/comparison results and the user-facing message.';

  -- ---------------- Prudential threshold ----------------
  ELSIF _family = 'prudential' THEN
    SELECT * INTO r FROM public.prudential_thresholds WHERE id = _rule_id;
    IF r.id IS NULL THEN RAISE EXCEPTION 'rule not found' USING ERRCODE='P0002'; END IF;
    v_code := 'PTH-' || upper(r.metric_key);
    v_name := coalesce(r.label, r.metric_key);
    v_conditions := jsonb_build_array(
      jsonb_build_object('label','warning threshold','metric',r.metric_key,
        'actual', coalesce(v_in->'actual','null'::jsonb), 'operator', r.comparator,
        'expected', to_jsonb(r.warn_value),
        'passed', NOT public.rule_test_compare(coalesce(v_in->'actual','null'::jsonb), r.comparator, to_jsonb(r.warn_value)),
        'reason','breach when the metric fails "'||r.comparator||' '||coalesce(r.warn_value::text,'-')||'"'),
      jsonb_build_object('label','breach threshold','metric',r.metric_key,
        'actual', coalesce(v_in->'actual','null'::jsonb), 'operator', r.comparator,
        'expected', to_jsonb(r.breach_value),
        'passed', NOT public.rule_test_compare(coalesce(v_in->'actual','null'::jsonb), r.comparator, to_jsonb(r.breach_value)),
        'reason','breach when the metric fails "'||r.comparator||' '||coalesce(r.breach_value::text,'-')||'"'));
    v_matched := EXISTS (SELECT 1 FROM jsonb_array_elements(v_conditions) c WHERE (c->>'passed')::boolean IS TRUE);
    v_actions := CASE WHEN v_matched THEN jsonb_build_array(
        jsonb_build_object('index',0,'type','threshold_breach_record','target','return_threshold_breaches'),
        jsonb_build_object('index',1,'type','prudential_assessment_flag'),
        jsonb_build_object('index',2,'type','notification','event','prudential.threshold_breached'))
      ELSE '[]'::jsonb END;
    v_notes := 'Unit ' || coalesce(r.unit,'ratio') || ', taxonomy ' || coalesce(r.taxonomy_code,'(any)') ||
               ', effective ' || coalesce(r.effective_from::text,'-') || ' → ' || coalesce(r.effective_to::text,'open') ||
               '. Runtime owner: prudential-monitoring-sweep.';

    -- Production parity: scope resolution and risk banding use the runtime helpers
    SELECT * INTO r2 FROM public.resolve_effective_threshold(
      COALESCE(NULLIF(v_in->>'return_config_id','')::uuid, r.return_config_id),
      r.metric_key,
      COALESCE(NULLIF(v_in->>'as_of','')::date, CURRENT_DATE),
      NULLIF(v_in->>'sector_id','')::uuid,
      NULLIF(v_in->>'return_type_id','')::uuid);
    v_effective := COALESCE(r2.id, r.id);
    v_risk := public.classify_ratio_risk(
      NULLIF(v_in->>'actual','')::numeric,
      COALESCE(r2.warn_value, r.warn_value),
      COALESCE(r2.breach_value, r.breach_value),
      COALESCE(r2.comparator, r.comparator));
    v_conditions := v_conditions || jsonb_build_array(jsonb_build_object(
      'label','effective threshold resolution','metric','effective_threshold_id',
      'actual', to_jsonb(v_effective), 'operator','=', 'expected', to_jsonb(r.id),
      'passed', (v_effective = r.id),
      'reason', CASE WHEN v_effective = r.id
                     THEN 'resolve_effective_threshold() selects this row for the supplied scope and date'
                     ELSE 'another threshold row outranks this one for the supplied scope and date' END));
    v_notes := v_notes || ' Scope resolved by resolve_effective_threshold(); risk band from classify_ratio_risk(): '
               || COALESCE(v_risk, '(no actual value supplied)') || '.';

  -- ---------------- Conduct monitoring ----------------
  ELSIF _family = 'conduct' THEN
    SELECT * INTO r FROM public.conduct_monitoring_rules WHERE id = _rule_id;
    IF r.id IS NULL THEN RAISE EXCEPTION 'rule not found' USING ERRCODE='P0002'; END IF;
    v_code := 'CMR-' || left(replace(r.id::text,'-',''),8);
    v_name := r.name;
    v_conditions := jsonb_build_array(jsonb_build_object(
      'label', coalesce(r.definition->>'metric','metric'),
      'metric', r.definition->>'metric',
      'actual', coalesce(v_in->'metrics'->(r.definition->>'metric'), v_in->'actual', 'null'::jsonb),
      'operator', coalesce(r.definition->>'op','>='),
      'expected', coalesce(r.definition->'threshold','null'::jsonb),
      'passed', public.rule_test_compare(
                  coalesce(v_in->'metrics'->(r.definition->>'metric'), v_in->'actual','null'::jsonb),
                  coalesce(r.definition->>'op','>='), r.definition->'threshold'),
      'reason','window ' || coalesce(r.definition->>'window_days','-') || ' days'));
    v_matched := (v_conditions->0->>'passed')::boolean;
    v_actions := CASE WHEN v_matched THEN jsonb_build_array(
        jsonb_build_object('index',0,'type','conduct_alert','scope',r.scope),
        jsonb_build_object('index',1,'type','risk_score_delta','value',r.risk_delta),
        jsonb_build_object('index',2,'type','notification','event','conduct.alert_created'))
      ELSE '[]'::jsonb END;
    v_notes := 'Frequency ' || coalesce(r.frequency,'-') || '. Runtime owner: evaluate-conduct-monitoring.';

  -- ---------------- Complaint triage ----------------
  ELSIF _family = 'complaint_triage' THEN
    SELECT * INTO r FROM public.complaint_intake_rules WHERE id = _rule_id;
    IF r.id IS NULL THEN RAISE EXCEPTION 'rule not found' USING ERRCODE='P0002'; END IF;
    v_code := 'CIR-' || left(replace(r.id::text,'-',''),8);
    v_name := coalesce(r.variant,'intake') || ' intake rules';
    SELECT jsonb_agg(jsonb_build_object(
             'label','required field ' || f.ref, 'metric', f.ref,
             'actual', coalesce(v_in->'facts'->f.ref,'null'::jsonb),
             'operator','is_present','expected', to_jsonb('required'::text),
             'passed', public.rule_test_compare(v_in->'facts'->f.ref,'is_present',NULL),
             'reason', CASE WHEN public.rule_test_compare(v_in->'facts'->f.ref,'is_present',NULL)
                            THEN 'supplied' ELSE 'missing — intake would be rejected' END))
      INTO v_conditions
      FROM unnest(coalesce(r.required_fields, ARRAY[]::text[])) AS f(ref);
    v_conditions := coalesce(v_conditions,'[]'::jsonb)
      || jsonb_build_array(jsonb_build_object(
           'label','anonymous submission','metric','anonymous',
           'actual', coalesce(v_in->'facts'->'anonymous','false'::jsonb),
           'operator','=','expected', to_jsonb(r.allow_anonymous),
           'passed', (coalesce((v_in->'facts'->>'anonymous')::boolean,false) IS NOT TRUE) OR r.allow_anonymous,
           'reason', CASE WHEN r.allow_anonymous THEN 'anonymous permitted' ELSE 'anonymous not permitted for this variant' END),
         jsonb_build_object(
           'label','attachment count','metric','attachments',
           'actual', coalesce(v_in->'facts'->'attachments','0'::jsonb),
           'operator','<=','expected', to_jsonb(r.max_attachments),
           'passed', public.rule_test_compare(coalesce(v_in->'facts'->'attachments','0'::jsonb),'<=',to_jsonb(r.max_attachments)),
           'reason','maximum ' || coalesce(r.max_attachments::text,'-') || ' attachments'));
    v_matched := NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_conditions) c WHERE (c->>'passed')::boolean IS FALSE);
    v_actions := jsonb_build_array(
      jsonb_build_object('index',0,'type','classify_complaint','result',
        CASE WHEN v_matched THEN 'accepted for triage' ELSE 'rejected at intake' END),
      jsonb_build_object('index',1,'type','apply_complaint_type_sla'),
      jsonb_build_object('index',2,'type','start_complaint_workflow'),
      jsonb_build_object('index',3,'type','notification','event','complaint.created'));

    -- Production parity: acceptance decided by the same function create_complaint() calls
    v_decision := public.complaint_intake_decide(r.variant, r.regulator_id, COALESCE(v_in->'facts','{}'::jsonb));
    v_conditions := v_conditions || jsonb_build_array(jsonb_build_object(
      'label','production intake decision','metric','complaint_intake_decide',
      'actual', COALESCE(v_decision->'errors','[]'::jsonb), 'operator','is_empty', 'expected','[]'::jsonb,
      'passed', jsonb_array_length(COALESCE(v_decision->'errors','[]'::jsonb)) = 0,
      'reason', CASE WHEN jsonb_array_length(COALESCE(v_decision->'errors','[]'::jsonb)) = 0
                     THEN 'create_complaint() would accept this submission'
                     ELSE 'create_complaint() would reject this submission' END));
    v_matched := v_matched AND jsonb_array_length(COALESCE(v_decision->'errors','[]'::jsonb)) = 0;
    v_actions := jsonb_set(v_actions, '{0,result}',
      to_jsonb(CASE WHEN v_matched THEN 'accepted for triage' ELSE 'rejected at intake' END));
    v_actions := jsonb_set(v_actions, '{1,derived_severity}', COALESCE(v_decision->'severity','null'::jsonb));
    v_actions := jsonb_set(v_actions, '{1,derived_priority}', COALESCE(v_decision->'priority','null'::jsonb));
    v_actions := jsonb_set(v_actions, '{1,derived_intake_source}', COALESCE(v_decision->'intake_source','null'::jsonb));
    v_notes := 'Runtime owner: create_complaint() -> public.complaint_intake_decide(), the same function this tester calls. '
               'Priority, SLA and assignment are then derived by the complaint type and workflow, previewed above in action order.';

  -- ---------------- Sufficiency ----------------
  ELSIF _family = 'sufficiency' THEN
    SELECT * INTO r FROM public.sufficiency_rules WHERE id = _rule_id;
    IF r.id IS NULL THEN RAISE EXCEPTION 'rule not found' USING ERRCODE='P0002'; END IF;
    v_code := coalesce(r.code, 'SFR-' || left(replace(r.id::text,'-',''),8));
    v_name := r.name;
    v_conditions := jsonb_build_array(jsonb_build_object(
      'label', coalesce(r.config->>'label', r.rule_type),
      'metric', coalesce(r.config->>'metric', r.config->>'field', r.rule_type),
      'actual', coalesce(v_in->'facts'->coalesce(r.config->>'metric', r.config->>'field',''), v_in->'actual','null'::jsonb),
      'operator', coalesce(r.config->>'op','is_present'),
      'expected', coalesce(r.config->'value', r.config->'threshold','null'::jsonb),
      'passed', public.rule_test_compare(
                  coalesce(v_in->'facts'->coalesce(r.config->>'metric', r.config->>'field',''), v_in->'actual','null'::jsonb),
                  coalesce(r.config->>'op','is_present'),
                  coalesce(r.config->'value', r.config->'threshold')),
      'reason','sufficiency rule type ' || coalesce(r.rule_type,'-')));
    v_matched := (v_conditions->0->>'passed')::boolean IS FALSE;
    v_actions := CASE WHEN v_matched THEN
        jsonb_build_array(
          jsonb_build_object('index',0,'type','sufficiency_finding','severity',r.severity),
          jsonb_build_object('index',1,'type','suggest_rfi','auto',r.auto_rfi,
            'prompt', r.rfi_prompt_template, 'question_type', r.rfi_question_type,
            'note','suggestion only — no RFI is created by a test run'))
      ELSE '[]'::jsonb END;
    v_notes := 'Runtime owner: evaluate-application-sufficiency. A failing condition means information is missing.';

  -- ---------------- RFI auto rules ----------------
  ELSIF _family = 'rfi_auto' THEN
    SELECT * INTO r FROM public.application_rfi_auto_rules WHERE id = _rule_id;
    IF r.id IS NULL THEN RAISE EXCEPTION 'rule not found' USING ERRCODE='P0002'; END IF;
    v_code := 'RFA-' || left(replace(r.id::text,'-',''),8);
    v_name := r.name;
    v_conditions := jsonb_build_array(jsonb_build_object(
      'label', coalesce(r.condition->>'label','condition'),
      'metric', coalesce(r.condition->>'field', r.condition->>'metric','field'),
      'actual', coalesce(v_in->'facts'->coalesce(r.condition->>'field', r.condition->>'metric',''), v_in->'actual','null'::jsonb),
      'operator', coalesce(r.condition->>'op','is_empty'),
      'expected', coalesce(r.condition->'value','null'::jsonb),
      'passed', public.rule_test_compare(
                  coalesce(v_in->'facts'->coalesce(r.condition->>'field', r.condition->>'metric',''), v_in->'actual','null'::jsonb),
                  coalesce(r.condition->>'op','is_empty'), r.condition->'value'),
      'reason','workflow ' || coalesce(r.workflow_type_key,'(any)')));
    v_matched := (v_conditions->0->>'passed')::boolean;
    v_actions := CASE WHEN v_matched THEN jsonb_build_array(jsonb_build_object(
        'index',0,'type','suggest_rfi_item','question_type', r.question_type,
        'required', r.required, 'due_days', r.default_due_days,
        'prompt', r.prompt_template,
        'duplicate_check', CASE WHEN coalesce((v_in->'facts'->>'open_item_exists')::boolean,false)
                                THEN 'suppressed — an open RFI item already covers this requirement'
                                ELSE 'no open RFI item found for this requirement' END,
        'note','suggestion only — officer confirmation creates the real RFI'))
      ELSE '[]'::jsonb END;
    v_notes := 'Runtime owner: application RFI suggestion path (officer-confirmed).';

  -- ---------------- Correspondence routing ----------------
  ELSIF _family = 'correspondence' THEN
    SELECT * INTO r FROM public.correspondence_routing_rules WHERE id = _rule_id;
    IF r.id IS NULL THEN RAISE EXCEPTION 'rule not found' USING ERRCODE='P0002'; END IF;
    v_code := 'CRR-' || left(replace(r.id::text,'-',''),8);
    v_name := r.name;
    v_conditions := jsonb_build_array(jsonb_build_object(
      'label','match ' || r.match_type, 'metric', r.match_type,
      'actual', coalesce(v_in->'message'->r.match_type, v_in->'actual','null'::jsonb),
      'operator','contains','expected', to_jsonb(r.match_value),
      'passed', public.rule_test_compare(coalesce(v_in->'message'->r.match_type, v_in->'actual','null'::jsonb),
                                         'contains', to_jsonb(r.match_value)),
      'reason','sort order ' || coalesce(r.sort_order::text,'-') ||
               ' — the first matching active rule wins'));

    -- Production parity: precedence resolved by the same function create_correspondence_thread() calls
    v_route := public.correspondence_route_decide(
      COALESCE(v_in->'message'->>'category', v_in->>'category'),
      COALESCE(v_in->'message'->>'channel',  v_in->>'channel'),
      COALESCE(v_in->'message'->>'subject',  v_in->>'subject'),
      COALESCE(v_in->'message'->>'priority', v_in->>'priority'));
    v_conditions := v_conditions || jsonb_build_array(jsonb_build_object(
      'label','winning rule (production precedence)','metric','routing_rule_id',
      'actual', COALESCE(v_route->'rule_id','null'::jsonb), 'operator','=', 'expected', to_jsonb(r.id),
      'passed', COALESCE(v_route->>'rule_id','') = r.id::text,
      'reason','the first matching active rule by sort order wins'));
    v_matched := COALESCE(v_route->>'rule_id','') = r.id::text;
    IF v_matched THEN
      v_actions := jsonb_build_array(
        jsonb_build_object('index',0,'type','route_to_unit','value', v_route->'assign_unit'),
        jsonb_build_object('index',1,'type','assign_officer','value', v_route->'assign_officer'),
        jsonb_build_object('index',2,'type','set_priority','value', v_route->'priority'),
        jsonb_build_object('index',3,'type','set_sla','days', v_route->'sla_days'),
        jsonb_build_object('index',4,'type','thread_status','value', v_route->'status'),
        jsonb_build_object('index',5,'type','notification','event','correspondence.message_received'));
    ELSE
      v_actions := '[]'::jsonb;
    END IF;
    v_notes := 'Runtime owner: create_correspondence_thread() -> public.correspondence_route_decide(), the same function this tester calls. Manual override '
               || CASE WHEN r.allow_manual_override THEN 'permitted' ELSE 'not permitted' END || '.';

  -- ---------------- Escalation rules ----------------
  ELSIF _family = 'escalation' THEN
    SELECT * INTO r FROM public.escalation_rules WHERE id = _rule_id;
    IF r.id IS NULL THEN RAISE EXCEPTION 'rule not found' USING ERRCODE='P0002'; END IF;
    v_code := 'ESR-' || left(replace(r.id::text,'-',''),8);
    v_name := r.name;
    v_conditions := jsonb_build_array(
      jsonb_build_object('label','tier 1 acknowledgement threshold','metric','elapsed_minutes',
        'actual', coalesce(v_in->'elapsed_minutes','null'::jsonb),'operator','>=',
        'expected', to_jsonb(r.tier1_ack_threshold_minutes),
        'passed', public.rule_test_compare(v_in->'elapsed_minutes','>=',to_jsonb(r.tier1_ack_threshold_minutes)),
        'reason', CASE WHEN r.business_hours_only THEN 'business hours only — elapsed time must be business minutes' ELSE 'calendar minutes' END),
      jsonb_build_object('label','tier 2 acknowledgement threshold','metric','elapsed_minutes',
        'actual', coalesce(v_in->'elapsed_minutes','null'::jsonb),'operator','>=',
        'expected', to_jsonb(r.tier2_ack_threshold_minutes),
        'passed', public.rule_test_compare(v_in->'elapsed_minutes','>=',to_jsonb(r.tier2_ack_threshold_minutes)),
        'reason','tier 2 fires only when tier 1 is unacknowledged'),
      jsonb_build_object('label','tier 3 acknowledgement threshold','metric','elapsed_minutes',
        'actual', coalesce(v_in->'elapsed_minutes','null'::jsonb),'operator','>=',
        'expected', to_jsonb(r.tier3_ack_threshold_minutes),
        'passed', public.rule_test_compare(v_in->'elapsed_minutes','>=',to_jsonb(r.tier3_ack_threshold_minutes)),
        'reason','tier 3 is the final tier'),
      jsonb_build_object('label','acknowledged pauses escalation','metric','acknowledged',
        'actual', coalesce(v_in->'acknowledged','false'::jsonb),'operator','=','expected','false'::jsonb,
        'passed', NOT (r.pause_on_acknowledgement AND coalesce((v_in->>'acknowledged')::boolean,false)),
        'reason', CASE WHEN r.pause_on_acknowledgement THEN 'rule pauses on acknowledgement' ELSE 'rule ignores acknowledgement' END));
    v_matched := (v_conditions->0->>'passed')::boolean AND (v_conditions->3->>'passed')::boolean;
    v_actions := CASE WHEN v_matched THEN jsonb_build_array(
        jsonb_build_object('index',0,'type','escalate','next_tier',
          CASE WHEN (v_conditions->2->>'passed')::boolean THEN 3
               WHEN (v_conditions->1->>'passed')::boolean THEN 2 ELSE 1 END,
          'recipient_role',
          CASE WHEN (v_conditions->2->>'passed')::boolean THEN r.tier3_recipient_role
               WHEN (v_conditions->1->>'passed')::boolean THEN r.tier2_recipient_role
               ELSE r.tier1_recipient_role END,
          'channels',
          CASE WHEN (v_conditions->2->>'passed')::boolean THEN to_jsonb(r.tier3_channels)
               WHEN (v_conditions->1->>'passed')::boolean THEN to_jsonb(r.tier2_channels)
               ELSE to_jsonb(r.tier1_channels) END),
        jsonb_build_object('index',1,'type','create_task','enabled',r.create_task),
        jsonb_build_object('index',2,'type','create_case','enabled',r.create_case),
        jsonb_build_object('index',3,'type','notification','event','escalation.tier_reached'))
      ELSE '[]'::jsonb END;
    v_notes := 'Source module ' || coalesce(r.source_module,'-') || ', severity ' || coalesce(r.default_severity::text,'-') ||
               ', calendar profile ' || coalesce(r.business_calendar_profile_id::text,'(none)') ||
               '. Runtime owner: escalation_sweep().';

    -- Production parity: due times computed by the runtime business-calendar helper
    v_from := COALESCE(NULLIF(v_in->>'from','')::timestamptz, now());
    v_asof := COALESCE(NULLIF(v_in->>'as_of','')::timestamptz, now());
    v_conditions := v_conditions || jsonb_build_array(
      jsonb_build_object('label','tier 1 due (escalation_deadline)','metric','tier1_due_at',
        'actual', to_jsonb(public.escalation_deadline(r.id, v_from, r.tier1_ack_threshold_minutes)),
        'operator','<=','expected', to_jsonb(v_asof),
        'passed', public.escalation_deadline(r.id, v_from, r.tier1_ack_threshold_minutes) <= v_asof,
        'reason','escalation_deadline() applies this rule''s business calendar profile'),
      jsonb_build_object('label','tier 2 due (escalation_deadline)','metric','tier2_due_at',
        'actual', to_jsonb(public.escalation_deadline(r.id, v_from, r.tier2_ack_threshold_minutes)),
        'operator','<=','expected', to_jsonb(v_asof),
        'passed', public.escalation_deadline(r.id, v_from, r.tier2_ack_threshold_minutes) <= v_asof,
        'reason','tier 2 due time in business minutes from the source event'),
      jsonb_build_object('label','tier 3 due (escalation_deadline)','metric','tier3_due_at',
        'actual', to_jsonb(public.escalation_deadline(r.id, v_from, r.tier3_ack_threshold_minutes)),
        'operator','<=','expected', to_jsonb(v_asof),
        'passed', public.escalation_deadline(r.id, v_from, r.tier3_ack_threshold_minutes) <= v_asof,
        'reason','tier 3 is the final tier'));
    v_notes := v_notes || ' Due times computed by public.escalation_deadline() / escalation_business_deadline().';

  ELSE
    RAISE EXCEPTION 'unknown rule family: %', _family USING ERRCODE = '22023';
  END IF;

  v_out := jsonb_build_object(
    'family', _family,
    'rule_id', _rule_id,
    'rule_code', v_code,
    'rule_name', v_name,
    'mode', 'dry_run',
    'inputs', v_in,
    'conditions', v_conditions,
    'matched', v_matched,
    'expected_actions', v_actions,
    'notes', v_notes,
    'correlation_id', v_corr,
    'duration_ms', (extract(epoch FROM (clock_timestamp() - v_start)) * 1000)::int,
    'side_effects', 'none — this is a dry run; no production record was created or modified'
  );

  INSERT INTO public.module_rule_tests
    (family, rule_id, rule_code, inputs, output, passed, matched, duration_ms, correlation_id, tested_by)
  VALUES (_family, _rule_id, v_code, v_in, v_out,
          NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_conditions) c WHERE c->>'passed' IS NULL),
          v_matched, (v_out->>'duration_ms')::int, v_corr, auth.uid());

  RETURN v_out;
END; $function$
;
CREATE OR REPLACE FUNCTION public.rule_test_compare(_actual jsonb, _op text, _expected jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  a_num numeric; e_num numeric;
  a_txt text := CASE WHEN _actual IS NULL OR jsonb_typeof(_actual)='null' THEN NULL ELSE btrim(_actual #>> '{}') END;
  e_txt text := CASE WHEN _expected IS NULL OR jsonb_typeof(_expected)='null' THEN NULL ELSE btrim(_expected #>> '{}') END;
  op text := lower(coalesce(_op,'='));
BEGIN
  BEGIN a_num := a_txt::numeric; EXCEPTION WHEN others THEN a_num := NULL; END;
  BEGIN e_num := e_txt::numeric; EXCEPTION WHEN others THEN e_num := NULL; END;

  IF op IN ('is_empty','empty','missing') THEN
    RETURN a_txt IS NULL OR a_txt = '';
  ELSIF op IN ('is_present','present','required','not_empty') THEN
    RETURN a_txt IS NOT NULL AND a_txt <> '';
  END IF;

  IF a_txt IS NULL THEN RETURN false; END IF;

  IF op IN ('>','gt') THEN RETURN a_num IS NOT NULL AND e_num IS NOT NULL AND a_num > e_num;
  ELSIF op IN ('>=','gte') THEN RETURN a_num IS NOT NULL AND e_num IS NOT NULL AND a_num >= e_num;
  ELSIF op IN ('<','lt') THEN RETURN a_num IS NOT NULL AND e_num IS NOT NULL AND a_num < e_num;
  ELSIF op IN ('<=','lte') THEN RETURN a_num IS NOT NULL AND e_num IS NOT NULL AND a_num <= e_num;
  ELSIF op IN ('=','==','eq','equals') THEN
    RETURN CASE WHEN a_num IS NOT NULL AND e_num IS NOT NULL THEN a_num = e_num ELSE lower(a_txt) = lower(coalesce(e_txt,'')) END;
  ELSIF op IN ('!=','<>','neq','not_equals') THEN
    RETURN CASE WHEN a_num IS NOT NULL AND e_num IS NOT NULL THEN a_num <> e_num ELSE lower(a_txt) <> lower(coalesce(e_txt,'')) END;
  ELSIF op IN ('contains','ilike') THEN RETURN e_txt IS NOT NULL AND a_txt ILIKE '%'||e_txt||'%';
  ELSIF op IN ('starts_with','prefix') THEN RETURN e_txt IS NOT NULL AND a_txt ILIKE e_txt||'%';
  ELSIF op = 'in' THEN
    RETURN _expected IS NOT NULL AND jsonb_typeof(_expected)='array'
       AND EXISTS (SELECT 1 FROM jsonb_array_elements_text(_expected) v WHERE lower(v) = lower(a_txt));
  END IF;
  RETURN false;
END; $function$
;
CREATE OR REPLACE FUNCTION public.run_complaint_escalation_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  r_rec public.complaint_escalation_rules%ROWTYPE;
  c_rec public.complaints%ROWTYPE;
  v_created int := 0; v_reason text; v_min_sev text;
  v_sev_rank int; v_min_rank int; v_age_days int; v_vol_count int;
BEGIN
  IF v_uid IS NOT NULL AND NOT (public.has_complaint_perm(v_uid,'escalate') OR public.has_complaint_perm(v_uid,'triage')) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;
  FOR r_rec IN SELECT * FROM public.complaint_escalation_rules WHERE enabled = true ORDER BY priority LOOP
    FOR c_rec IN SELECT * FROM public.complaints WHERE status IN ('submitted','under_investigation') LOOP
      v_reason := NULL;
      IF r_rec.criterion = 'harm' THEN
        v_min_sev := r_rec.thresholds->>'minSeverity';
        v_sev_rank := CASE c_rec.severity WHEN 'critical' THEN 4 WHEN 'high' THEN 3 WHEN 'medium' THEN 2 WHEN 'low' THEN 1 ELSE 0 END;
        v_min_rank := CASE v_min_sev WHEN 'critical' THEN 4 WHEN 'high' THEN 3 WHEN 'medium' THEN 2 WHEN 'low' THEN 1 ELSE 0 END;
        IF v_min_sev IS NOT NULL AND v_sev_rank >= v_min_rank THEN
          v_reason := 'Consumer harm marked ' || c_rec.severity;
        END IF;
      ELSIF r_rec.criterion = 'age' THEN
        v_age_days := floor(EXTRACT(EPOCH FROM (now() - c_rec.created_at))/86400)::int;
        IF (r_rec.thresholds->>'maxAgeDays') IS NOT NULL
           AND v_age_days >= (r_rec.thresholds->>'maxAgeDays')::int THEN
          v_reason := 'Open ' || v_age_days || ' days (threshold ' || (r_rec.thresholds->>'maxAgeDays') || ')';
        END IF;
      ELSIF r_rec.criterion = 'recurrence' THEN
        IF (r_rec.thresholds->>'minRepeats') IS NOT NULL
           AND COALESCE(c_rec.repeat_complaint_count,0) >= (r_rec.thresholds->>'minRepeats')::int THEN
          v_reason := 'Recurrence count ' || c_rec.repeat_complaint_count;
        END IF;
      ELSIF r_rec.criterion = 'volume' THEN
        IF c_rec.licensee_id IS NOT NULL
           AND (r_rec.thresholds->>'windowDays') IS NOT NULL
           AND (r_rec.thresholds->>'minCount') IS NOT NULL THEN
          SELECT count(*) INTO v_vol_count FROM public.complaints x
           WHERE x.licensee_id = c_rec.licensee_id
             AND x.created_at >= now() - make_interval(days => (r_rec.thresholds->>'windowDays')::int);
          IF v_vol_count >= (r_rec.thresholds->>'minCount')::int THEN
            v_reason := 'Institution: ' || v_vol_count || ' in ' || (r_rec.thresholds->>'windowDays') || 'd';
          END IF;
        END IF;
      END IF;
      IF v_reason IS NOT NULL THEN
        INSERT INTO public.complaint_escalation_cases (complaint_id, rule_id, rule_key, rule_label, severity, target_tier, trigger_reason, status)
        VALUES (c_rec.id, r_rec.id, r_rec.key, r_rec.label, c_rec.severity, r_rec.target_tier, v_reason, 'pending')
        ON CONFLICT (complaint_id, rule_key) DO NOTHING;
        IF FOUND THEN v_created := v_created + 1; END IF;
        INSERT INTO public.complaint_escalation_log (complaint_id, rule_key, rule_label, severity, outcome, note, snapshot)
        VALUES (c_rec.id, r_rec.key, r_rec.label, c_rec.severity, 'pending', v_reason,
                jsonb_build_object('complaint_number', c_rec.complaint_number, 'licensee_id', c_rec.licensee_id));
      END IF;
    END LOOP;
  END LOOP;
  RETURN jsonb_build_object('created_cases', v_created, 'ran_at', now());
END; $function$
;
CREATE OR REPLACE FUNCTION public.safe_uuid(_value text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  IF _value IS NULL OR btrim(_value) = '' THEN
    RETURN NULL;
  END IF;
  RETURN _value::uuid;
EXCEPTION WHEN invalid_text_representation THEN
  RETURN NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.save_notification_event_preference(_event_key text, _in_app boolean DEFAULT true, _email boolean DEFAULT true, _sms boolean DEFAULT false, _digest notification_digest_frequency DEFAULT 'immediate'::notification_digest_frequency, _muted boolean DEFAULT false, _effective_from timestamp with time zone DEFAULT now())
 RETURNS notification_user_event_preferences
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE row_out public.notification_user_event_preferences;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  INSERT INTO public.notification_user_event_preferences
    (user_id, event_key, in_app_enabled, email_enabled, sms_enabled, digest_frequency, muted, effective_from, updated_by)
  VALUES (auth.uid(), _event_key, _in_app, _email, _sms, _digest, _muted, COALESCE(_effective_from, now()), auth.uid())
  ON CONFLICT (user_id, event_key) DO UPDATE
    SET in_app_enabled = EXCLUDED.in_app_enabled,
        email_enabled = EXCLUDED.email_enabled,
        sms_enabled = EXCLUDED.sms_enabled,
        digest_frequency = EXCLUDED.digest_frequency,
        muted = EXCLUDED.muted,
        effective_from = EXCLUDED.effective_from,
        updated_by = auth.uid()
  RETURNING * INTO row_out;

  PERFORM public.log_notification_audit('NOTIFICATION_PREFERENCES_UPDATED', ARRAY[]::uuid[],
    jsonb_build_object('event_key', _event_key, 'preference_id', row_out.id));

  RETURN row_out;
END $function$
;
CREATE OR REPLACE FUNCTION public.save_notification_preferences(_channels jsonb DEFAULT NULL::jsonb, _categories jsonb DEFAULT NULL::jsonb, _type_settings jsonb DEFAULT NULL::jsonb, _digest_enabled boolean DEFAULT NULL::boolean, _digest_time time without time zone DEFAULT NULL::time without time zone, _digest_timezone text DEFAULT NULL::text, _quiet_hours jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  INSERT INTO public.notification_preferences AS p (
    user_id, channels, categories, type_settings, digest_enabled, digest_time, digest_timezone, quiet_hours
  ) VALUES (
    auth.uid(),
    COALESCE(_channels, '{}'::jsonb),
    COALESCE(_categories, '{}'::jsonb),
    COALESCE(_type_settings, '{}'::jsonb),
    COALESCE(_digest_enabled, false),
    _digest_time,
    COALESCE(_digest_timezone, 'UTC'),
    _quiet_hours
  )
  ON CONFLICT (user_id) DO UPDATE SET
    channels        = COALESCE(_channels, p.channels),
    categories      = COALESCE(_categories, p.categories),
    type_settings   = COALESCE(_type_settings, p.type_settings),
    digest_enabled  = COALESCE(_digest_enabled, p.digest_enabled),
    digest_time     = COALESCE(_digest_time, p.digest_time),
    digest_timezone = COALESCE(_digest_timezone, p.digest_timezone),
    quiet_hours     = COALESCE(_quiet_hours, p.quiet_hours);

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (auth.uid(), 'NOTIFICATION_PREFERENCES_UPDATED', 'notification_preferences', auth.uid()::text,
          jsonb_build_object('digest_enabled', _digest_enabled));
END $function$
;
CREATE OR REPLACE FUNCTION public.save_ppoc_mapping(_mapping_id uuid, _ppoc_user_id uuid, _licensee_id uuid, _sector_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_mapping_id uuid;
  v_licensee record;
  v_resolved_sector_id uuid;
  v_existing record;
  v_sector_count integer;
  v_unique_sector_count integer;
  v_same_sectors boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;

  IF NOT (public.has_role(v_uid,'super_admin'::app_role) OR public.has_role(v_uid,'admin'::app_role)) THEN
    RETURN jsonb_build_object('error','Admin only','code','FORBIDDEN','http',403);
  END IF;

  IF _ppoc_user_id IS NULL THEN
    RETURN jsonb_build_object('error','Please select a PPOC user.','code','PPOC_REQUIRED','http',422);
  END IF;

  IF _licensee_id IS NULL THEN
    RETURN jsonb_build_object('error','Please select a licensee entity.','code','LICENSEE_REQUIRED','http',422);
  END IF;

  IF _sector_ids IS NULL OR coalesce(array_length(_sector_ids, 1), 0) = 0 THEN
    RETURN jsonb_build_object('error','Please select at least one sector for this PPOC mapping.','code','SECTORS_REQUIRED','http',422);
  END IF;

  SELECT count(*)::int, count(distinct s)::int
    INTO v_sector_count, v_unique_sector_count
    FROM unnest(_sector_ids) AS s;

  IF v_sector_count <> v_unique_sector_count THEN
    RETURN jsonb_build_object('error','Duplicate sectors are not allowed in a PPOC mapping.','code','DUPLICATE_SECTORS','http',422);
  END IF;

  SELECT l.id, l.name, l.sector_id, l.status, l.license_id
    INTO v_licensee
    FROM public.licensees l
   WHERE l.id = _licensee_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Selected licensee entity was not found.','code','LICENSEE_NOT_FOUND','http',404);
  END IF;

  -- Resolve sector with the same priority as the Licensee Entities admin page:
  -- registrations.sector_id -> applications.data->>'sector_id' -> licensees.sector_id
  v_resolved_sector_id := v_licensee.sector_id;

  IF v_resolved_sector_id IS NULL AND v_licensee.license_id IS NOT NULL THEN
    SELECT COALESCE(
             NULLIF(r.sector_id::text,'')::uuid,
             NULLIF(a.data->>'sector_id','')::uuid
           )
      INTO v_resolved_sector_id
      FROM public.licenses lic
      LEFT JOIN public.applications a ON a.id = lic.application_id
      LEFT JOIN public.registrations r ON r.user_id = a.applicant_id
     WHERE lic.id = v_licensee.license_id
     LIMIT 1;
  END IF;

  IF v_resolved_sector_id IS NULL THEN
    RETURN jsonb_build_object('error','Selected licensee entity does not have a resolvable sector assignment.','code','LICENSEE_SECTOR_MISSING','http',422);
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.sectors s
     WHERE s.id = ANY(_sector_ids)
       AND COALESCE(s.status, 'active') = 'active'
    HAVING count(*) = array_length(_sector_ids, 1)
  ) THEN
    RETURN jsonb_build_object('error','One or more selected sectors are invalid or inactive.','code','INVALID_SECTORS','http',422);
  END IF;

  IF NOT (v_resolved_sector_id = ANY(_sector_ids)) THEN
    RETURN jsonb_build_object('error','Selected entity does not belong to the assigned PPOC sectors.','code','LICENSEE_SECTOR_MISMATCH','http',422);
  END IF;

  IF _mapping_id IS NOT NULL THEN
    SELECT *
      INTO v_existing
      FROM public.ppoc_entity_mappings
     WHERE id = _mapping_id
     FOR UPDATE;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('error','PPOC mapping not found.','code','MAPPING_NOT_FOUND','http',404);
    END IF;
  END IF;

  IF NOT public.is_eligible_ppoc_user(_ppoc_user_id, _mapping_id) THEN
    RETURN jsonb_build_object('error','Selected PPOC user is not an eligible external or licensee contact user.','code','INVALID_PPOC_USER','http',422);
  END IF;

  SELECT EXISTS (
    SELECT 1
      FROM public.ppoc_entity_mappings m
     WHERE m.ppoc_user_id = _ppoc_user_id
       AND m.licensee_id = _licensee_id
       AND (_mapping_id IS NULL OR m.id <> _mapping_id)
  ) INTO v_same_sectors;

  IF v_same_sectors THEN
    RETURN jsonb_build_object('error','This PPOC mapping already exists.','code','DUPLICATE_MAPPING','http',409);
  END IF;

  IF _mapping_id IS NULL THEN
    INSERT INTO public.ppoc_entity_mappings (ppoc_user_id, licensee_id, is_active)
    VALUES (_ppoc_user_id, _licensee_id, true)
    RETURNING id INTO v_mapping_id;
  ELSE
    UPDATE public.ppoc_entity_mappings
       SET ppoc_user_id = _ppoc_user_id,
           licensee_id = _licensee_id,
           updated_at = now()
     WHERE id = _mapping_id;
    v_mapping_id := _mapping_id;
  END IF;

  DELETE FROM public.ppoc_mapping_sectors WHERE mapping_id = v_mapping_id;

  INSERT INTO public.ppoc_mapping_sectors (mapping_id, sector_id)
  SELECT v_mapping_id, s
    FROM unnest(_sector_ids) AS s;

  PERFORM public.create_audit_log(
    v_uid,
    CASE WHEN _mapping_id IS NULL THEN 'ppoc_mapping_created' ELSE 'ppoc_mapping_updated' END,
    'ppoc_mapping',
    v_mapping_id::text,
    NULL,
    jsonb_build_object('ppoc_user_id', _ppoc_user_id, 'licensee_id', _licensee_id, 'sector_ids', _sector_ids, 'resolved_sector_id', v_resolved_sector_id),
    NULL
  );

  RETURN jsonb_build_object('success', true, 'mapping_id', v_mapping_id, 'http', 200);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.schedule_appeal_hearing(_appeal_id uuid, _hearing_date timestamp with time zone, _hearing_format text, _venue text DEFAULT NULL::text, _link text DEFAULT NULL::text, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_appeal record;
  v_reschedule boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF NOT (public.has_permission(v_uid,'license_appeals','assign_panel')
          OR public.has_permission(v_uid,'license_appeals','decide')
          OR public.has_permission(v_uid,'license_appeals','edit')) THEN
    RETURN jsonb_build_object('error','You are not allowed to schedule appeal hearings','code','FORBIDDEN','http',403);
  END IF;

  SELECT * INTO v_appeal FROM public.license_appeals WHERE id = _appeal_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Appeal not found','code','NOT_FOUND','http',404);
  END IF;
  IF v_appeal.panel_id IS NULL THEN
    RETURN jsonb_build_object('error','Refer the appeal to a panel before scheduling a hearing','code','NO_PANEL','http',409);
  END IF;
  IF _hearing_format NOT IN ('written','oral','virtual','in_person') THEN
    RETURN jsonb_build_object('error','Unknown hearing format','code','BAD_FORMAT','http',400);
  END IF;

  v_reschedule := v_appeal.hearing_date IS NOT NULL;

  UPDATE public.license_appeals
     SET hearing_date = _hearing_date,
         hearing_format = _hearing_format,
         hearing_venue = _venue,
         hearing_link = _link,
         hearing_completed_at = NULL,
         updated_at = now()
   WHERE id = _appeal_id;

  INSERT INTO public.license_appeal_events (appeal_id, event_type, description, actor_id, metadata)
  VALUES (
    _appeal_id,
    CASE WHEN v_reschedule THEN 'hearing_rescheduled' ELSE 'hearing_scheduled' END,
    format('%s for %s (%s)%s',
           CASE WHEN v_reschedule THEN 'Hearing rescheduled' ELSE 'Hearing scheduled' END,
           to_char(_hearing_date,'DD Mon YYYY HH24:MI'), _hearing_format,
           CASE WHEN nullif(trim(coalesce(_reason,'')),'') IS NULL THEN '' ELSE ' — ' || _reason END),
    v_uid,
    jsonb_build_object('hearing_date', _hearing_date, 'hearing_format', _hearing_format,
                       'venue', _venue, 'link', _link, 'reason', _reason)
  );

  PERFORM public.notification_enqueue_event(
    CASE WHEN v_reschedule THEN 'license_appeal.hearing_rescheduled' ELSE 'license_appeal.hearing_scheduled' END,
    'license_appeal', _appeal_id,
    jsonb_build_object('appeal_reference', v_appeal.appeal_reference,
                       'recipient_id', v_appeal.filed_by,
                       'hearing_date', to_char(_hearing_date,'DD Mon YYYY HH24:MI'),
                       'hearing_format', _hearing_format),
    to_char(_hearing_date,'YYYYMMDDHH24MI')
  );

  RETURN jsonb_build_object('success', true, 'http', 200, 'rescheduled', v_reschedule);
END; $function$
;
CREATE OR REPLACE FUNCTION public.search_licensees(_q text DEFAULT NULL::text, _limit integer DEFAULT 25, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, name text, status text, sector_id uuid, sector_name text, regulator_id uuid, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_q text := NULLIF(btrim(coalesce(_q, '')), '');
  v_limit int := LEAST(GREATEST(coalesce(_limit, 25), 1), 100);
  v_offset int := GREATEST(coalesce(_offset, 0), 0);
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required'
      USING ERRCODE = '42501', HINT = 'auth_required';
  END IF;

  IF NOT (
    public.is_super_admin(v_uid)
    OR public.has_any_permission(v_uid, ARRAY[
      'complaint_management.view',
      'licensee_management.view',
      'license_management.view'
    ])
  ) THEN
    RAISE EXCEPTION 'permission denied for entity search'
      USING ERRCODE = '42501', HINT = 'permission_denied';
  END IF;

  RETURN QUERY
  WITH filtered AS (
    SELECT l.id, l.name, l.status, l.sector_id,
           s.name AS sector_name, s.regulator_id AS regulator_id
    FROM public.licensees l
    LEFT JOIN public.sectors s ON s.id = l.sector_id
    WHERE (v_q IS NULL OR l.name ILIKE '%' || v_q || '%')
  ),
  counted AS (SELECT count(*)::bigint AS c FROM filtered)
  SELECT f.id, f.name, f.status, f.sector_id, f.sector_name, f.regulator_id,
         (SELECT c FROM counted)
  FROM filtered f
  ORDER BY f.name
  LIMIT v_limit OFFSET v_offset;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.search_notifications(_search text DEFAULT NULL::text, _category notification_category DEFAULT NULL::notification_category, _severity notification_severity DEFAULT NULL::notification_severity, _module text DEFAULT NULL::text, _unread_only boolean DEFAULT false, _include_dismissed boolean DEFAULT false, _from timestamp with time zone DEFAULT NULL::timestamp with time zone, _to timestamp with time zone DEFAULT NULL::timestamp with time zone, _limit integer DEFAULT 50, _offset integer DEFAULT 0)
 RETURNS SETOF notifications
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT n.*
  FROM public.notifications n
  WHERE n.user_id = auth.uid()
    AND n.channel = 'in_app'
    AND (_include_dismissed OR n.dismissed_at IS NULL)
    AND (NOT _unread_only OR n.read = false)
    AND (_category IS NULL OR n.category = _category)
    AND (_severity IS NULL OR n.severity = _severity)
    AND (_module IS NULL OR n.module = _module)
    AND (_from IS NULL OR n.created_at >= _from)
    AND (_to IS NULL OR n.created_at <= _to)
    AND (
      _search IS NULL OR length(_search) < 3 OR
      to_tsvector('simple', coalesce(n.title,'') || ' ' || coalesce(n.message,'') || ' ' || coalesce(n.entity_id,''))
        @@ plainto_tsquery('simple', _search)
      OR n.title ILIKE '%' || _search || '%'
      OR n.message ILIKE '%' || _search || '%'
    )
  ORDER BY n.created_at DESC
  LIMIT GREATEST(COALESCE(_limit, 50), 1)
  OFFSET GREATEST(COALESCE(_offset, 0), 0)
$function$
;
CREATE OR REPLACE FUNCTION public.sec_assign_user_roles(p_user_id uuid, p_role_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  v_ids uuid[] := COALESCE(p_role_ids, '{}'::uuid[]);
  v_before jsonb;
  v_after jsonb;
  v_primary uuid;
  v_system_roles text[];
  v_bad uuid;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;
  IF NOT (public.is_super_admin(uid)
          OR public.has_permission(uid, 'user_management', 'edit')
          OR public.has_permission(uid, 'role_management', 'assign')) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'user_id_required' USING ERRCODE = '22023'; END IF;

  SELECT x INTO v_bad FROM unnest(v_ids) AS t(x)
  WHERE NOT EXISTS (SELECT 1 FROM public.sec_roles r WHERE r.id = t.x AND r.status = 'active')
  LIMIT 1;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'unknown_or_inactive_role: %', v_bad USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.sec_roles r
    WHERE r.is_break_glass
      AND ((r.id = ANY(v_ids)) <> EXISTS (
            SELECT 1 FROM public.sec_user_roles ur
            WHERE ur.user_id = p_user_id AND ur.role_id = r.id AND ur.status = 'active'))
  ) AND NOT public.is_super_admin(uid) THEN
    RAISE EXCEPTION 'break_glass_role_protected' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.sec_user_roles ur
    JOIN public.sec_roles r ON r.id = ur.role_id
    WHERE ur.user_id = p_user_id AND ur.status = 'active' AND r.is_break_glass
      AND NOT (r.id = ANY(v_ids))
      AND (SELECT count(*) FROM public.sec_user_roles u2
           JOIN public.sec_roles r2 ON r2.id = u2.role_id
           WHERE r2.is_break_glass AND u2.status = 'active') <= 1
  ) THEN
    RAISE EXCEPTION 'last_break_glass_admin_protected' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(jsonb_agg(role_id), '[]'::jsonb) INTO v_before
  FROM public.sec_user_roles WHERE user_id = p_user_id AND status = 'active';

  DELETE FROM public.sec_user_roles
  WHERE user_id = p_user_id AND NOT (role_id = ANY(v_ids));

  INSERT INTO public.sec_user_roles (user_id, role_id, status, assigned_by)
  SELECT p_user_id, x, 'active', uid FROM unnest(v_ids) AS t(x)
  ON CONFLICT (user_id, role_id)
  DO UPDATE SET status = 'active', assigned_by = uid, updated_at = now();

  DELETE FROM public.user_dynamic_roles
  WHERE user_id = p_user_id AND NOT (role_id = ANY(v_ids));
  INSERT INTO public.user_dynamic_roles (user_id, role_id)
  SELECT p_user_id, x FROM unnest(v_ids) AS t(x)
  WHERE EXISTS (SELECT 1 FROM public.roles r WHERE r.id = t.x)
  ON CONFLICT (user_id, role_id) DO NOTHING;

  -- Only mirror the primary role onto the legacy profile when a legacy
  -- counterpart exists; canonical-only roles must not break assignment.
  SELECT x INTO v_primary FROM unnest(v_ids) AS t(x)
  WHERE EXISTS (SELECT 1 FROM public.roles r WHERE r.id = t.x)
  LIMIT 1;
  IF v_primary IS NOT NULL THEN
    UPDATE public.profiles SET role_id = v_primary, updated_at = now() WHERE id = p_user_id;
  END IF;

  SELECT ARRAY(
    SELECT DISTINCT r.system_role FROM public.sec_roles r
    WHERE r.id = ANY(v_ids) AND COALESCE(r.system_role, '') <> ''
      AND r.system_role <> 'custom'
  ) INTO v_system_roles;

  IF array_length(v_system_roles, 1) > 0 THEN
    DELETE FROM public.user_roles
    WHERE user_id = p_user_id AND NOT (role::text = ANY(v_system_roles));
    INSERT INTO public.user_roles (user_id, role)
    SELECT p_user_id, x::app_role FROM unnest(v_system_roles) AS t(x)
    ON CONFLICT DO NOTHING;
  ELSE
    DELETE FROM public.user_roles WHERE user_id = p_user_id;
  END IF;

  SELECT COALESCE(jsonb_agg(role_id), '[]'::jsonb) INTO v_after
  FROM public.sec_user_roles WHERE user_id = p_user_id AND status = 'active';

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value)
  VALUES (uid, 'security.assign_user_roles', 'user', p_user_id::text,
          jsonb_build_object('role_ids', v_before), jsonb_build_object('role_ids', v_after));

  RETURN jsonb_build_object('user_id', p_user_id, 'role_ids', v_after);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.sec_can_access_path(p_user_id uuid, p_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record;
BEGIN
  SELECT * INTO r FROM public.sec_route_for_path(p_path);
  IF r.route_key IS NULL THEN
    -- Unregistered route: deny inside the internal surface, allow elsewhere.
    RETURN NOT (p_path = '/admin' OR p_path LIKE '/admin/%' OR p_path LIKE '/settings%');
  END IF;
  IF NOT r.is_protected THEN RETURN true; END IF;
  IF r.module_key IS NULL THEN RETURN true; END IF;
  RETURN public.sec_has_permission(p_user_id, r.module_key, r.action_key);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.sec_delete_role(_role_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;
  IF NOT (public.is_super_admin(uid) OR public.has_permission(uid, 'role_management', 'delete')) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.sec_roles WHERE id = _role_id AND (is_system OR is_break_glass)) THEN
    RAISE EXCEPTION 'system_role_not_deletable' USING ERRCODE = '22023';
  END IF;

  PERFORM public.rbac_delete_role(_role_id);
  DELETE FROM public.sec_role_permissions WHERE role_id = _role_id;
  DELETE FROM public.sec_user_roles WHERE role_id = _role_id;
  DELETE FROM public.sec_roles WHERE id = _role_id;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id)
  VALUES (uid, 'security.delete_role', 'sec_role', _role_id::text);

  RETURN jsonb_build_object('deleted', _role_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.sec_get_user_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  is_bypass boolean;
  result jsonb;
BEGIN
  IF uid IS NULL THEN
    RETURN jsonb_build_object('authenticated', false);
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.sec_user_roles ur
    JOIN public.sec_roles r ON r.id = ur.role_id
    WHERE ur.user_id = uid AND ur.status = 'active' AND r.is_break_glass
  ) INTO is_bypass;

  SELECT jsonb_build_object(
    'authenticated', true,
    'user_id', uid,
    'is_bypass', is_bypass,
    'roles', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', r.id, 'key', r.key, 'name', r.name,
        'role_type', r.role_type, 'dashboard_tier', r.dashboard_tier)
        ORDER BY r.name)
      FROM public.sec_user_roles ur
      JOIN public.sec_roles r ON r.id = ur.role_id AND r.status = 'active'
      WHERE ur.user_id = uid AND ur.status = 'active'
    ), '[]'::jsonb),
    'permissions', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('module', up.module_key, 'action', up.action_key))
      FROM public.sec_user_permissions(uid) up
    ), '[]'::jsonb),
    'memberships', public.sec_user_memberships(uid),
    'scopes', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'module', m.key,
        'scope', st.key,
        'values', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('kind', v.value_kind, 'id', v.value_id))
          FROM public.sec_role_scope_values v WHERE v.role_scope_id = rs.id
        ), '[]'::jsonb)))
      FROM public.sec_user_roles ur
      JOIN public.sec_role_scopes rs ON rs.role_id = ur.role_id
      JOIN public.sec_modules m ON m.id = rs.module_id
      JOIN public.sec_scope_types st ON st.id = rs.scope_type_id
      WHERE ur.user_id = uid AND ur.status = 'active'
    ), '[]'::jsonb),
    'routes', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'key', rt.key, 'path', rt.path_pattern, 'match_type', rt.match_type,
        'audience', rt.audience, 'is_protected', rt.is_protected,
        'module', m.key, 'action', p.key, 'priority', rt.priority)
        ORDER BY rt.priority)
      FROM public.sec_routes rt
      LEFT JOIN public.sec_permissions p ON p.id = rt.required_permission_id
      LEFT JOIN public.sec_modules m ON m.id = p.module_id
      WHERE rt.is_active
    ), '[]'::jsonb),
    'navigation', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'key', n.key, 'parent_key', pn.key, 'label', n.label,
        'item_type', n.item_type,
        'href', COALESCE(n.href_override, rt.path_pattern),
        'icon', n.icon_key, 'sort_order', n.sort_order,
        'audience', n.audience, 'admin_only', n.admin_only,
        'module', m.key, 'action', p.key,
        'show_in_sidebar', n.show_in_sidebar,
        'show_in_search', n.show_in_search,
        'keywords', COALESCE(to_jsonb(n.keywords), '[]'::jsonb),
        'allowed', (
          n.required_permission_id IS NULL
          OR is_bypass
          OR public.sec_has_permission(uid, m.key, p.key)
        ))
        ORDER BY n.sort_order)
      FROM public.sec_navigation_items n
      LEFT JOIN public.sec_navigation_items pn ON pn.id = n.parent_id
      LEFT JOIN public.sec_routes rt ON rt.id = n.route_id
      LEFT JOIN public.sec_permissions p ON p.id = n.required_permission_id
      LEFT JOIN public.sec_modules m ON m.id = p.module_id
      WHERE n.is_active AND (n.show_in_sidebar OR n.show_in_search)
    ), '[]'::jsonb)
  ) INTO result;

  RETURN result;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.sec_has_permission(p_user_id uuid, p_module text, p_action text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    EXISTS (
      SELECT 1 FROM public.sec_user_roles ur
      JOIN public.sec_roles r ON r.id = ur.role_id
      WHERE ur.user_id = p_user_id AND ur.status = 'active' AND r.is_break_glass
    )
    OR EXISTS (
      SELECT 1 FROM public.sec_user_permissions(p_user_id) up
      WHERE up.module_key = lower(regexp_replace(coalesce(p_module,''), '\s+', '_', 'g'))
        AND up.action_key = lower(trim(coalesce(p_action,'')))
    );
$function$
;
CREATE OR REPLACE FUNCTION public.sec_is_internal_user(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT _user_id IS NOT NULL AND (
    public.is_super_admin(_user_id)
    OR EXISTS (
      SELECT 1 FROM public.sec_user_roles ur
      JOIN public.sec_roles r ON r.id = ur.role_id
      WHERE ur.user_id = _user_id
        AND ur.status = 'active'
        AND r.status = 'active'
        AND r.role_type = 'internal'
        AND (ur.effective_from IS NULL OR ur.effective_from <= now())
        AND (ur.effective_until IS NULL OR ur.effective_until > now())
    )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.sec_route_for_path(p_path text)
 RETURNS TABLE(route_key text, audience text, is_protected boolean, module_key text, action_key text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT rt.key, rt.audience, rt.is_protected, m.key, p.key
  FROM public.sec_routes rt
  LEFT JOIN public.sec_permissions p ON p.id = rt.required_permission_id
  LEFT JOIN public.sec_modules m ON m.id = p.module_id
  WHERE rt.is_active
    AND (
      (rt.match_type = 'exact' AND p_path = rt.path_pattern)
      OR (rt.match_type = 'prefix' AND (p_path = rt.path_pattern OR p_path LIKE rt.path_pattern || '/%'))
    )
  ORDER BY rt.priority
  LIMIT 1;
$function$
;
CREATE OR REPLACE FUNCTION public.sec_save_role(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  v_result jsonb;
  v_role_id uuid;
  v_key text;
  v_perm_ids uuid[];
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501'; END IF;
  IF NOT (public.is_super_admin(uid) OR public.has_permission(uid, 'role_management', 'edit')) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Legacy writer performs validation (scopes, permission dependencies).
  v_result := public.rbac_save_role(_payload);
  v_role_id := (v_result ->> 'id')::uuid;

  v_key := lower(regexp_replace(trim(COALESCE(_payload ->> 'name', '')), '[^a-zA-Z0-9]+', '_', 'g'));
  v_key := NULLIF(trim(both '_' from v_key), '');

  INSERT INTO public.sec_roles (id, key, name, description, role_type, role_category,
                                dashboard_tier, status, system_role, is_system, created_by)
  SELECT r.id,
         COALESCE(v_key, 'role_' || replace(r.id::text, '-', '')),
         r.name, r.description,
         COALESCE(r.role_type, 'internal'), r.role_category,
         r.dashboard_tier, COALESCE(r.status, 'active'),
         r.system_role, COALESCE(r.is_system, false), uid
  FROM public.roles r WHERE r.id = v_role_id
  ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    role_type = EXCLUDED.role_type,
    role_category = EXCLUDED.role_category,
    dashboard_tier = EXCLUDED.dashboard_tier,
    status = EXCLUDED.status,
    system_role = EXCLUDED.system_role,
    updated_at = now();

  -- Mirror grants: legacy permission ids are the canonical ids' twins by
  -- (module, action), so resolve through the catalogs.
  SELECT ARRAY(
    SELECT DISTINCT sp.id
    FROM public.role_permissions rp
    JOIN public.permissions p ON p.id = rp.permission_id
    JOIN public.sec_modules m ON m.key = lower(regexp_replace(p.module, '\s+', '_', 'g'))
    JOIN public.sec_permissions sp ON sp.module_id = m.id AND sp.key = lower(p.name)
    WHERE rp.role_id = v_role_id
  ) INTO v_perm_ids;

  DELETE FROM public.sec_role_permissions
  WHERE role_id = v_role_id AND NOT (permission_id = ANY(v_perm_ids));

  INSERT INTO public.sec_role_permissions (role_id, permission_id)
  SELECT v_role_id, x FROM unnest(v_perm_ids) AS t(x)
  ON CONFLICT DO NOTHING;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
  VALUES (uid, 'security.save_role', 'sec_role', v_role_id::text,
          jsonb_build_object('permission_count', COALESCE(array_length(v_perm_ids, 1), 0)));

  RETURN jsonb_build_object('id', v_role_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.sec_user_memberships(_user_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'entity_id', m.entity_id,
    'entity_name', l.name,
    'membership_role', r.key,
    'membership_role_label', r.label,
    'is_primary_rep', r.is_primary_representative,
    'effective_from', m.effective_from,
    'capabilities', COALESCE((
      SELECT jsonb_agg(p.capability ORDER BY p.capability)
      FROM public.entity_membership_role_permissions p
      WHERE p.membership_role_id = r.id
    ), '[]'::jsonb)
  ) ORDER BY l.name), '[]'::jsonb)
  FROM public.entity_user_memberships m
  JOIN public.entity_membership_roles r ON r.id = m.membership_role_id
  JOIN public.licensees l ON l.id = m.entity_id
  WHERE m.user_id = _user_id
    AND m.status = 'APPROVED'
    AND (m.effective_from IS NULL OR m.effective_from <= now())
    AND (m.effective_to IS NULL OR m.effective_to > now());
$function$
;
CREATE OR REPLACE FUNCTION public.sec_user_permissions(p_user_id uuid)
 RETURNS TABLE(module_key text, action_key text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT m.key, p.key
  FROM public.sec_user_roles ur
  JOIN public.sec_roles r ON r.id = ur.role_id AND r.status = 'active'
  JOIN public.sec_role_permissions rp ON rp.role_id = r.id
  JOIN public.sec_permissions p ON p.id = rp.permission_id AND p.is_active
  JOIN public.sec_modules m ON m.id = p.module_id AND m.is_active
  WHERE ur.user_id = p_user_id
    AND ur.status = 'active'
    AND (ur.effective_from IS NULL OR ur.effective_from <= now())
    AND (ur.effective_until IS NULL OR ur.effective_until > now());
$function$
;
CREATE OR REPLACE FUNCTION public.seed_external_portal_defaults(_user_id uuid, _entity_id uuid, _role app_role, _actor uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role_id uuid;
BEGIN
  IF _user_id IS NULL THEN RETURN; END IF;

  IF _role IN ('applicant'::app_role, 'pre_licensee'::app_role) THEN
    SELECT id INTO v_role_id FROM public.roles WHERE name = 'Applicant' LIMIT 1;
  ELSIF _role IN ('licensee_primary'::app_role, 'licensee_secondary'::app_role) THEN
    SELECT id INTO v_role_id FROM public.roles WHERE name = 'Regulated Entity User' LIMIT 1;
  END IF;

  IF v_role_id IS NOT NULL THEN
    INSERT INTO public.user_dynamic_roles (user_id, role_id)
    VALUES (_user_id, v_role_id)
    ON CONFLICT DO NOTHING;
  END IF;
END; $function$
;
CREATE OR REPLACE FUNCTION public.set_acknowledgement_delivery_state(_acknowledgement_id uuid, _status text, _provider text DEFAULT NULL::text, _provider_message_id text DEFAULT NULL::text, _failure_reason text DEFAULT NULL::text, _document_bucket text DEFAULT NULL::text, _document_path text DEFAULT NULL::text, _document_checksum text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.application_acknowledgements;
BEGIN
  IF _status NOT IN ('GENERATED','DELIVERY_PENDING','DELIVERED','DELIVERY_FAILED','PROVIDER_NOT_CONFIGURED') THEN
    RETURN jsonb_build_object('error', 'Invalid acknowledgement status', 'code', 'INVALID_STATUS');
  END IF;

  UPDATE public.application_acknowledgements a
  SET status = _status,
      provider = coalesce(_provider, a.provider),
      provider_message_id = coalesce(_provider_message_id, a.provider_message_id),
      failure_reason = CASE WHEN _status = 'DELIVERY_FAILED' THEN _failure_reason ELSE NULL END,
      retry_count = CASE WHEN _status = 'DELIVERY_FAILED' THEN a.retry_count + 1 ELSE a.retry_count END,
      delivery_requested_at = CASE
        WHEN _status = 'DELIVERY_PENDING' THEN coalesce(a.delivery_requested_at, now())
        ELSE a.delivery_requested_at END,
      delivered_at = CASE WHEN _status = 'DELIVERED' THEN now() ELSE a.delivered_at END,
      document_bucket = coalesce(_document_bucket, a.document_bucket),
      document_path = coalesce(_document_path, a.document_path),
      document_checksum = coalesce(a.document_checksum, _document_checksum),
      delivery_history = a.delivery_history || jsonb_build_object(
        'status', _status,
        'at', now(),
        'provider', _provider,
        'provider_message_id', _provider_message_id,
        'failure_reason', _failure_reason
      )
  WHERE a.id = _acknowledgement_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RETURN jsonb_build_object('error', 'Acknowledgement not found', 'code', 'NOT_FOUND');
  END IF;
  RETURN jsonb_build_object('success', true, 'acknowledgement', to_jsonb(v_row));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.set_application_ai_assessments_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.set_application_rejected_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'rejected' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'rejected') AND NEW.rejected_at IS NULL THEN
    NEW.rejected_at := now();
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.set_complaint_internal_creator()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.internal_created_by IS NULL
     AND auth.uid() IS NOT NULL
     AND public.is_internal_staff(auth.uid()) THEN
    NEW.internal_created_by := auth.uid();
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.set_complaint_repeat_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.complainant_id IS NOT NULL AND NEW.licensee_id IS NOT NULL THEN
    SELECT COUNT(*) INTO NEW.repeat_complaint_count
    FROM public.complaints
    WHERE complainant_id = NEW.complainant_id
      AND licensee_id = NEW.licensee_id
      AND created_at > (now() - interval '12 months')
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.set_conduct_signal_disposition(_signal_id uuid, _disposition text, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _cur text;
BEGIN
  IF _disposition NOT IN ('NEW','UNDER_REVIEW','FALSE_POSITIVE','MONITOR','ESCALATED','CLOSED') THEN
    RAISE EXCEPTION 'Invalid disposition %', _disposition;
  END IF;
  IF _disposition = 'ESCALATED' THEN
    RAISE EXCEPTION 'Use refer_conduct_signal_to_investigation() to escalate a signal';
  END IF;

  IF NOT (
    public.is_super_admin(_uid)
    OR public.has_permission(_uid,'market_conduct','run_conduct_analytics')
    OR public.has_permission(_uid,'market_conduct','manage_monitoring_rules')
    OR public.has_permission(_uid,'market_conduct','manage_complaints')
  ) THEN
    RAISE EXCEPTION 'Not authorized to review surveillance signals';
  END IF;

  SELECT disposition INTO _cur FROM public.conduct_alerts WHERE id = _signal_id;
  IF _cur IS NULL THEN
    RAISE EXCEPTION 'Signal not found';
  END IF;
  IF _cur IN ('ESCALATED','CLOSED') THEN
    RAISE EXCEPTION 'Signal is % and cannot be re-dispositioned', _cur;
  END IF;
  IF _cur = _disposition THEN
    RAISE EXCEPTION 'Signal is already %', _cur;
  END IF;
  IF _disposition IN ('FALSE_POSITIVE','CLOSED') AND COALESCE(btrim(_reason),'') = '' THEN
    RAISE EXCEPTION 'A reason is required to mark a signal % ', _disposition;
  END IF;

  PERFORM set_config('app.signal_disposition_ok','on', true);

  UPDATE public.conduct_alerts
     SET disposition = _disposition,
         disposition_reason = COALESCE(NULLIF(btrim(_reason),''), disposition_reason),
         reviewed_by = _uid,
         reviewed_at = now(),
         status = CASE
                    WHEN _disposition IN ('FALSE_POSITIVE','CLOSED') THEN 'closed'
                    WHEN _disposition IN ('UNDER_REVIEW','MONITOR') THEN 'acknowledged'
                    ELSE status
                  END,
         closed_by = CASE WHEN _disposition IN ('FALSE_POSITIVE','CLOSED') THEN _uid ELSE closed_by END,
         closed_at = CASE WHEN _disposition IN ('FALSE_POSITIVE','CLOSED') THEN now() ELSE closed_at END,
         closure_reason = CASE WHEN _disposition IN ('FALSE_POSITIVE','CLOSED')
                               THEN COALESCE(NULLIF(btrim(_reason),''), closure_reason) ELSE closure_reason END,
         acknowledged_by = CASE WHEN _disposition IN ('UNDER_REVIEW','MONITOR')
                                THEN COALESCE(acknowledged_by, _uid) ELSE acknowledged_by END,
         acknowledged_at = CASE WHEN _disposition IN ('UNDER_REVIEW','MONITOR')
                                THEN COALESCE(acknowledged_at, now()) ELSE acknowledged_at END,
         updated_at = now()
   WHERE id = _signal_id;

  INSERT INTO public.conduct_signal_events (signal_id, from_disposition, to_disposition, reason, actor_id)
  VALUES (_signal_id, _cur, _disposition, NULLIF(btrim(_reason),''), _uid);

  PERFORM set_config('app.signal_disposition_ok','', true);
  RETURN _signal_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.set_correspondence_thread_state(_thread_id uuid, _state text, _justification text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_actor text;
  v_thread public.correspondence_threads%ROWTYPE;
BEGIN
  IF NOT public.is_internal_staff(v_user) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF _state NOT IN ('open','pending_response','closed') THEN RAISE EXCEPTION 'invalid_state'; END IF;
  SELECT * INTO v_thread FROM public.correspondence_threads WHERE id = _thread_id;
  IF v_thread.id IS NULL THEN RAISE EXCEPTION 'thread_not_found'; END IF;
  v_actor := public.correspondence_actor_label(v_user);

  IF _state = 'closed' THEN
    IF v_thread.thread_state = 'pending_response'
       AND v_thread.response_due_at IS NOT NULL
       AND v_thread.response_due_at > now()
       AND COALESCE(length(TRIM(_justification)), 0) < 10 THEN
      RAISE EXCEPTION 'closure_justification_required';
    END IF;
    UPDATE public.correspondence_threads
       SET thread_state = 'closed', status = 'closed', closed_at = now(),
           close_justification = _justification, pending_since = NULL
     WHERE id = _thread_id;
    INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
    VALUES (_thread_id, v_user, v_actor, 'Staff', 'THREAD_CLOSED', _justification, true);
  ELSIF _state = 'pending_response' THEN
    UPDATE public.correspondence_threads
       SET thread_state = 'pending_response', pending_since = now(),
           response_due_at = now() + (COALESCE(sla_days,5) || ' days')::interval
     WHERE id = _thread_id;
    INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
    VALUES (_thread_id, v_user, v_actor, 'Staff', 'THREAD_STATUS_CHANGED', 'Pending response · SLA started', true);
  ELSE
    UPDATE public.correspondence_threads
       SET thread_state = 'open', pending_since = NULL, response_due_at = NULL,
           closed_at = NULL,
           status = CASE WHEN status = 'closed' THEN 'in_review' ELSE status END
     WHERE id = _thread_id;
    INSERT INTO public.correspondence_events (thread_id, actor_id, actor_name, actor_role, action, detail, visible_to_licensee)
    VALUES (_thread_id, v_user, v_actor, 'Staff', 'THREAD_STATUS_CHANGED', 'Reopened', true);
  END IF;
END; $function$
;
CREATE OR REPLACE FUNCTION public.set_payment_remarks_updated_at()
