CREATE OR REPLACE FUNCTION public.simulate_escalation_rule(_criterion text, _thresholds jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_total int; v_fire int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF NOT (public.has_complaint_perm(v_uid,'triage') OR public.has_complaint_perm(v_uid,'escalate')) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;
  SELECT count(*) INTO v_total FROM public.complaints WHERE status IN ('submitted','under_investigation');
  IF _criterion = 'harm' THEN
    SELECT count(*) INTO v_fire FROM public.complaints
     WHERE status IN ('submitted','under_investigation')
       AND (CASE severity WHEN 'critical' THEN 4 WHEN 'high' THEN 3 WHEN 'medium' THEN 2 WHEN 'low' THEN 1 ELSE 0 END)
         >= (CASE _thresholds->>'minSeverity' WHEN 'critical' THEN 4 WHEN 'high' THEN 3 WHEN 'medium' THEN 2 WHEN 'low' THEN 1 ELSE 0 END);
  ELSIF _criterion = 'age' THEN
    SELECT count(*) INTO v_fire FROM public.complaints
     WHERE status IN ('submitted','under_investigation')
       AND floor(EXTRACT(EPOCH FROM (now() - created_at))/86400) >= COALESCE((_thresholds->>'maxAgeDays')::int, 999999);
  ELSIF _criterion = 'recurrence' THEN
    SELECT count(*) INTO v_fire FROM public.complaints
     WHERE status IN ('submitted','under_investigation')
       AND COALESCE(repeat_complaint_count,0) >= COALESCE((_thresholds->>'minRepeats')::int, 999999);
  ELSIF _criterion = 'volume' THEN
    SELECT count(*) INTO v_fire FROM public.complaints c
     WHERE status IN ('submitted','under_investigation')
       AND c.licensee_id IS NOT NULL
       AND (SELECT count(*) FROM public.complaints x
             WHERE x.licensee_id = c.licensee_id
               AND x.created_at >= now() - make_interval(days => COALESCE((_thresholds->>'windowDays')::int,30)))
           >= COALESCE((_thresholds->>'minCount')::int, 999999);
  ELSE
    v_fire := 0;
  END IF;
  RETURN jsonb_build_object('total_open', COALESCE(v_total,0), 'fire_count', COALESCE(v_fire,0));
END; $function$
;
CREATE OR REPLACE FUNCTION public.sla_add_duration(_start timestamp with time zone, _hours numeric, _calendar_profile_id uuid DEFAULT NULL::uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_working int[];
  v_remaining numeric := COALESCE(_hours, 0);
  v_cursor timestamptz := _start;
  v_guard int := 0;
  v_dow int;
  v_is_working boolean;
BEGIN
  IF _hours IS NULL OR _hours <= 0 THEN RETURN NULL; END IF;
  IF _calendar_profile_id IS NULL THEN RETURN _start + make_interval(hours => 0) + (_hours || ' hours')::interval; END IF;

  SELECT working_days INTO v_working FROM public.business_calendar_profiles WHERE id = _calendar_profile_id;
  IF v_working IS NULL OR array_length(v_working, 1) IS NULL THEN
    RETURN _start + (_hours || ' hours')::interval;
  END IF;

  -- Consume the SLA in 24h working-day chunks, skipping non-working days and holidays.
  WHILE v_remaining > 0 AND v_guard < 2000 LOOP
    v_guard := v_guard + 1;
    v_dow := EXTRACT(DOW FROM v_cursor)::int;
    v_is_working := v_dow = ANY (v_working)
      AND NOT EXISTS (
        SELECT 1 FROM public.business_calendar_holidays h
        WHERE h.profile_id = _calendar_profile_id AND h.holiday_date = v_cursor::date
      );
    IF v_is_working THEN
      IF v_remaining <= 24 THEN
        v_cursor := v_cursor + (v_remaining || ' hours')::interval;
        v_remaining := 0;
      ELSE
        v_cursor := v_cursor + interval '24 hours';
        v_remaining := v_remaining - 24;
      END IF;
    ELSE
      v_cursor := v_cursor + interval '24 hours';
    END IF;
  END LOOP;

  RETURN v_cursor;
END; $function$
;
CREATE OR REPLACE FUNCTION public.sla_stage_complete(_stage_instance_id uuid, _reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.sla_stage_instances;
BEGIN
  SELECT * INTO v_row FROM public.sla_stage_instances WHERE id = _stage_instance_id;
  IF v_row.id IS NULL OR v_row.state = 'completed' THEN RETURN; END IF;

  UPDATE public.sla_stage_instances SET
    state = 'completed',
    completed_at = now(),
    pause_seconds = pause_seconds + CASE WHEN paused_at IS NOT NULL
      THEN GREATEST(0, EXTRACT(EPOCH FROM (now() - paused_at))::int) ELSE 0 END,
    active_seconds = GREATEST(0, EXTRACT(EPOCH FROM (now() - started_at))::int)
      - (pause_seconds + CASE WHEN paused_at IS NOT NULL
          THEN GREATEST(0, EXTRACT(EPOCH FROM (now() - paused_at))::int) ELSE 0 END),
    paused_at = NULL
  WHERE id = _stage_instance_id;

  PERFORM public.sla_stage_log_event(_stage_instance_id, 'completed', v_row.state, 'completed', _reason, '{}'::jsonb);
END; $function$
;
CREATE OR REPLACE FUNCTION public.sla_stage_log_event(_stage_instance_id uuid, _event_type text, _from_state text, _to_state text, _reason text DEFAULT NULL::text, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.sla_stage_events(stage_instance_id, event_type, actor_id, actor_kind, from_state, to_state, reason, metadata)
  VALUES (_stage_instance_id, _event_type, auth.uid(),
          CASE WHEN auth.uid() IS NULL THEN 'system' ELSE 'user' END,
          _from_state, _to_state, _reason, COALESCE(_metadata, '{}'::jsonb))
  RETURNING id INTO v_id;
  RETURN v_id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.sla_stage_mark_breached(_stage_instance_id uuid, _reason text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.sla_stage_instances;
BEGIN
  SELECT * INTO v_row FROM public.sla_stage_instances WHERE id = _stage_instance_id;
  IF v_row.id IS NULL OR v_row.state <> 'active' OR v_row.due_at IS NULL OR v_row.due_at > now() THEN
    RETURN false;
  END IF;

  UPDATE public.sla_stage_instances
    SET state = 'breached', breached_at = COALESCE(breached_at, now())
    WHERE id = _stage_instance_id;

  PERFORM public.sla_stage_log_event(_stage_instance_id, 'breached', 'active', 'breached', _reason,
    jsonb_build_object('due_at', v_row.due_at));

  INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, new_value, metadata)
  VALUES (NULL, 'workflow.sla.breached', v_row.entity_type, v_row.entity_id,
          jsonb_build_object('stage_instance_id', _stage_instance_id, 'due_at', v_row.due_at, 'stage_name', v_row.stage_name),
          jsonb_build_object('actor','system','process_type', v_row.process_type));
  RETURN true;
END; $function$
;
CREATE OR REPLACE FUNCTION public.sla_stage_mark_escalated(_stage_instance_id uuid, _tier integer, _recipients text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.sla_stage_instances
    SET first_breach_notified_at = COALESCE(first_breach_notified_at, now())
    WHERE id = _stage_instance_id;
  PERFORM public.sla_stage_log_event(_stage_instance_id, 'escalated', NULL, NULL, 'tier ' || _tier,
    jsonb_build_object('tier', _tier, 'recipients', _recipients));
END; $function$
;
CREATE OR REPLACE FUNCTION public.sla_stage_open(_process_type text, _entity_type text, _entity_id uuid, _workflow_instance_id uuid DEFAULT NULL::uuid, _step_id uuid DEFAULT NULL::uuid, _stage_name text DEFAULT NULL::text, _started_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_res RECORD;
  v_id uuid;
  v_start timestamptz := COALESCE(_started_at, now());
  v_name text := COALESCE(_stage_name, (SELECT name FROM public.approval_steps WHERE id = _step_id));
BEGIN
  -- Close any still-open stage for the same workflow instance.
  PERFORM public.sla_stage_complete(id, 'superseded')
  FROM public.sla_stage_instances
  WHERE state IN ('active','paused','breached')
    AND (
      (_workflow_instance_id IS NOT NULL AND workflow_instance_id = _workflow_instance_id)
      OR (_workflow_instance_id IS NULL AND entity_type = _entity_type AND entity_id = _entity_id)
    );

  SELECT * INTO v_res FROM public.resolve_stage_sla(_process_type, v_name, _step_id);

  INSERT INTO public.sla_stage_instances(
    process_type, entity_type, entity_id, workflow_instance_id, step_id, stage_name,
    sla_config_id, sla_hours, sla_source, calendar_profile_id, started_at, due_at, state
  ) VALUES (
    _process_type, _entity_type, _entity_id, _workflow_instance_id, _step_id, v_name,
    v_res.sla_config_id, v_res.sla_hours, COALESCE(v_res.sla_source, 'step'), v_res.calendar_profile_id,
    v_start, public.sla_add_duration(v_start, v_res.sla_hours, v_res.calendar_profile_id), 'active'
  ) RETURNING id INTO v_id;

  PERFORM public.sla_stage_log_event(v_id, 'started', NULL, 'active', NULL,
    jsonb_build_object('sla_hours', v_res.sla_hours, 'sla_source', COALESCE(v_res.sla_source,'step')));
  RETURN v_id;
END; $function$
;
CREATE OR REPLACE FUNCTION public.sla_stage_pause(_entity_type text, _entity_id uuid, _reason text DEFAULT NULL::text, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.sla_stage_instances;
BEGIN
  SELECT * INTO v_row FROM public.sla_stage_instances
  WHERE entity_type = _entity_type AND entity_id = _entity_id AND state IN ('active','breached')
  ORDER BY started_at DESC LIMIT 1;
  IF v_row.id IS NULL THEN RETURN; END IF;

  UPDATE public.sla_stage_instances
    SET state = 'paused', paused_at = COALESCE(paused_at, now())
    WHERE id = v_row.id;
  PERFORM public.sla_stage_log_event(v_row.id, 'paused', v_row.state, 'paused', _reason, _metadata);
END; $function$
;
CREATE OR REPLACE FUNCTION public.sla_stage_resume(_entity_type text, _entity_id uuid, _reason text DEFAULT NULL::text, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.sla_stage_instances;
  v_added int;
BEGIN
  SELECT * INTO v_row FROM public.sla_stage_instances
  WHERE entity_type = _entity_type AND entity_id = _entity_id AND state = 'paused'
  ORDER BY started_at DESC LIMIT 1;
  IF v_row.id IS NULL THEN RETURN; END IF;

  v_added := GREATEST(0, EXTRACT(EPOCH FROM (now() - COALESCE(v_row.paused_at, now())))::int);

  UPDATE public.sla_stage_instances SET
    state = 'active',
    paused_at = NULL,
    pause_seconds = pause_seconds + v_added,
    due_at = CASE WHEN due_at IS NULL THEN NULL ELSE due_at + make_interval(secs => v_added) END
  WHERE id = v_row.id;

  PERFORM public.sla_stage_log_event(v_row.id, 'resumed', 'paused', 'active', _reason,
    COALESCE(_metadata,'{}'::jsonb) || jsonb_build_object('pause_seconds_added', v_added));
END; $function$
;
CREATE OR REPLACE FUNCTION public.snapshot_return_revision(_return_id uuid, _reason text, _previous_status text DEFAULT NULL::text, _new_status text DEFAULT NULL::text, _actor_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_snapshot JSONB;
  v_versions JSONB;
  v_next INT;
  v_id UUID;
  v_actor UUID;
BEGIN
  IF _reason NOT IN ('submitted','edit_requested','resubmitted','admin_edit') THEN
    RAISE EXCEPTION 'invalid snapshot_reason: %', _reason;
  END IF;

  v_actor := COALESCE(_actor_id, auth.uid());

  -- Aggregate current form data grouped by form_id
  SELECT
    COALESCE(jsonb_object_agg(form_id, data), '{}'::jsonb),
    COALESCE(jsonb_object_agg(form_id, ver), '{}'::jsonb)
  INTO v_snapshot, v_versions
  FROM (
    SELECT
      form_id::text AS form_id,
      jsonb_object_agg(field_name, to_jsonb(field_value)) AS data,
      COALESCE(MAX(form_version_id::text), NULL) AS ver
    FROM public.return_form_data
    WHERE return_id = _return_id
    GROUP BY form_id
  ) grouped;

  SELECT COALESCE(MAX(revision_number), 0) + 1
  INTO v_next
  FROM public.return_data_revisions
  WHERE return_id = _return_id;

  INSERT INTO public.return_data_revisions
    (return_id, revision_number, snapshot_reason, previous_status, new_status, snapshot, form_version_ids, created_by)
  VALUES
    (_return_id, v_next, _reason, _previous_status, _new_status, COALESCE(v_snapshot,'{}'::jsonb), COALESCE(v_versions,'{}'::jsonb), v_actor)
  RETURNING id INTO v_id;

  -- Best-effort audit entry
  BEGIN
    INSERT INTO public.return_audit_log (return_id, action, previous_status, new_status, performed_by, event_key, source, metadata)
    VALUES (
      _return_id,
      'revision_snapshot_created',
      _previous_status,
      _new_status,
      v_actor,
      'return.revision.snapshot',
      'rpc:snapshot_return_revision',
      jsonb_build_object('revision_id', v_id, 'revision_number', v_next, 'reason', _reason)
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.stamp_approval_action_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.workflow_version_id IS NULL AND NEW.workflow_instance_id IS NOT NULL THEN
    SELECT workflow_version_id INTO NEW.workflow_version_id
      FROM public.workflow_instances WHERE id = NEW.workflow_instance_id;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.start_complaint_investigation(_id uuid)
 RETURNS complaints
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  before_row public.complaints%ROWTYPE;
  after_row public.complaints%ROWTYPE;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='28000'; END IF;
  IF NOT public.has_complaint_perm(actor, 'investigate') THEN
    RAISE EXCEPTION 'permission denied: complaint_management.investigate' USING ERRCODE='42501';
  END IF;
  SELECT * INTO before_row FROM public.complaints WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'complaint not found' USING ERRCODE='P0002'; END IF;
  IF before_row.status NOT IN ('submitted','under_investigation') THEN
    RAISE EXCEPTION 'invalid transition from % to under_investigation', before_row.status USING ERRCODE='22023';
  END IF;

  UPDATE public.complaints
     SET status = 'under_investigation',
         investigator_id = COALESCE(investigator_id, actor),
         acknowledged_at = COALESCE(acknowledged_at, now()),
         updated_at = now()
   WHERE id = _id
  RETURNING * INTO after_row;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value)
  VALUES (actor, 'complaint.investigation_started', 'complaint', _id,
          jsonb_build_object('status', before_row.status),
          jsonb_build_object('status', after_row.status, 'investigator_id', after_row.investigator_id));
  RETURN after_row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.start_complaint_investigation(_id uuid, _expected_updated_at timestamp with time zone)
 RETURNS complaints
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  before_row public.complaints%ROWTYPE;
  after_row  public.complaints%ROWTYPE;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='28000'; END IF;
  IF NOT public.has_complaint_perm(actor, 'investigate') THEN
    RAISE EXCEPTION 'permission denied: complaint_management.investigate' USING ERRCODE='42501';
  END IF;
  PERFORM public._assert_complaint_fresh(_id, _expected_updated_at);
  SELECT * INTO before_row FROM public.complaints WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'complaint not found' USING ERRCODE='P0002'; END IF;
  IF before_row.status NOT IN ('submitted','under_investigation') THEN
    RAISE EXCEPTION 'invalid transition from % to under_investigation', before_row.status USING ERRCODE='22023';
  END IF;

  UPDATE public.complaints
     SET status = 'under_investigation',
         investigator_id = COALESCE(investigator_id, actor),
         acknowledged_at = COALESCE(acknowledged_at, now()),
         updated_at = now()
   WHERE id = _id
  RETURNING * INTO after_row;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value)
  VALUES (actor, 'complaint.investigation_started', 'complaint', _id,
          jsonb_build_object('status', before_row.status),
          jsonb_build_object('status', after_row.status, 'investigator_id', after_row.investigator_id));
  RETURN after_row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.start_complaint_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_workflow_id uuid;
  v_first_step_id uuid;
  v_step_role text;
  v_step_approver_type text;
  v_step_config jsonb;
  v_instance_id uuid;
  v_user_ids uuid[];
  v_uid uuid;
BEGIN
  SELECT w.id INTO v_workflow_id
  FROM public.approval_workflows w
  WHERE w.entity_type = 'complaint'
    AND w.is_active = true
    AND (NEW.regulator_id IS NULL OR w.regulator_id IS NULL OR w.regulator_id = NEW.regulator_id)
  ORDER BY
    (w.regulator_id IS NOT NULL AND w.regulator_id = NEW.regulator_id)::int DESC,
    (w.regulator_id IS NOT NULL)::int DESC,
    w.updated_at DESC NULLS LAST
  LIMIT 1;

  IF v_workflow_id IS NOT NULL THEN
    SELECT s.id, s.approver_role, s.approver_type, s.approver_config
      INTO v_first_step_id, v_step_role, v_step_approver_type, v_step_config
    FROM public.approval_steps s
    WHERE s.workflow_id = v_workflow_id
    ORDER BY s.step_order ASC
    LIMIT 1;

    IF v_first_step_id IS NOT NULL THEN
      INSERT INTO public.workflow_instances (workflow_id, entity_type, entity_id, current_step_id, status, started_at)
      VALUES (v_workflow_id, 'complaint', NEW.id, v_first_step_id, 'active', now())
      RETURNING id INTO v_instance_id;

      -- Resolve assignees
      IF v_step_approver_type = 'specific_users' THEN
        SELECT ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_step_config->'user_ids','[]'::jsonb))::uuid)
          INTO v_user_ids;
      ELSE
        SELECT ARRAY(
          SELECT DISTINCT ur.user_id
          FROM public.user_roles ur
          WHERE ur.role::text = v_step_role
        ) INTO v_user_ids;
      END IF;

      IF v_step_role IS NOT NULL THEN
        UPDATE public.complaints SET assigned_team = v_step_role WHERE id = NEW.id;
      END IF;

      IF v_user_ids IS NOT NULL THEN
        FOREACH v_uid IN ARRAY v_user_ids LOOP
          INSERT INTO public.notifications (user_id, title, message, type, entity_type, entity_id, channel, delivery_status)
          VALUES (
            v_uid,
            'Complaint ' || NEW.complaint_number || ' assigned',
            'Complaint "' || NEW.subject || '" is assigned to you. SLA due ' || COALESCE(to_char(NEW.sla_due_at,'YYYY-MM-DD HH24:MI'),'—'),
            'complaint.assigned', 'complaint', NEW.id::text, 'in_app', 'delivered'
          );
        END LOOP;
      END IF;
    END IF;
  END IF;

  IF NEW.complainant_id IS NOT NULL THEN
    INSERT INTO public.notifications (user_id, title, message, type, entity_type, entity_id, channel, delivery_status)
    VALUES (
      NEW.complainant_id,
      'Complaint ' || NEW.complaint_number || ' received',
      'Your complaint "' || NEW.subject || '" was received. SLA due ' || COALESCE(to_char(NEW.sla_due_at,'YYYY-MM-DD HH24:MI'),'—'),
      'complaint.filed', 'complaint', NEW.id::text, 'in_app', 'delivered'
    );
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'start_complaint_workflow error: %', SQLERRM;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.start_registration_workflow(_registration_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reg record;
  v_workflow_id uuid;
  v_first_step uuid;
  v_existing uuid;
  v_instance_id uuid;
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  SELECT id, sector_id INTO v_reg FROM public.registrations WHERE id = _registration_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT id INTO v_existing FROM public.workflow_instances
   WHERE entity_id = _registration_id AND entity_type = 'registration'
     AND status IN ('active','paused')
   ORDER BY created_at DESC LIMIT 1;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;

  v_workflow_id := public.resolve_registration_workflow(v_reg.sector_id);
  IF v_workflow_id IS NULL THEN RETURN NULL; END IF;

  SELECT id INTO v_first_step FROM public.approval_steps
   WHERE workflow_id = v_workflow_id ORDER BY step_order ASC LIMIT 1;
  IF v_first_step IS NULL THEN RETURN NULL; END IF;

  INSERT INTO public.workflow_instances (workflow_id, entity_type, entity_id, current_step_id, status, started_at)
  VALUES (v_workflow_id, 'registration', _registration_id, v_first_step, 'active', now())
  RETURNING id INTO v_instance_id;

  RETURN v_instance_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.start_return_workflow(_return_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_workflow_id uuid;
  v_first_step uuid;
  v_instance_id uuid;
  v_existing_instance uuid;
  v_existing_step uuid;
  v_existing_status text;
  v_ret record;
BEGIN
  SELECT id, workflow_id, current_step_id, workflow_status
    INTO v_ret
    FROM public.returns_filed
   WHERE id = _return_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Return not found','code','NOT_FOUND','http',404);
  END IF;

  SELECT id, current_step_id, status
    INTO v_existing_instance, v_existing_step, v_existing_status
    FROM public.workflow_instances
   WHERE entity_id = _return_id
     AND entity_type = 'return'
     AND status IN ('active','paused')
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_existing_instance IS NOT NULL THEN
    SELECT workflow_id INTO v_workflow_id FROM public.workflow_instances WHERE id = v_existing_instance;
    UPDATE public.returns_filed
       SET current_step_id = COALESCE(v_existing_step, current_step_id),
           workflow_id = COALESCE(v_workflow_id, workflow_id),
           updated_at = now()
     WHERE id = _return_id;

    RETURN jsonb_build_object(
      'success', true,
      'reused', true,
      'instance_id', v_existing_instance,
      'workflow_id', v_workflow_id,
      'step_id', v_existing_step,
      'http', 200
    );
  END IF;

  -- Prefer the cached workflow_id on the row, but fall back to the dynamic
  -- routing resolver so returns whose workflow_id was never persisted still
  -- start correctly.
  v_workflow_id := v_ret.workflow_id;
  IF v_workflow_id IS NULL THEN
    v_workflow_id := public.resolve_return_workflow(_return_id);
  END IF;

  IF v_workflow_id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'no_workflow', true, 'http', 200);
  END IF;

  SELECT id INTO v_first_step
    FROM public.approval_steps
   WHERE workflow_id = v_workflow_id
   ORDER BY step_order ASC
   LIMIT 1;

  IF v_first_step IS NULL THEN
    RETURN jsonb_build_object('error','Workflow has no steps','code','NO_STEPS','http',422);
  END IF;

  INSERT INTO public.workflow_instances (workflow_id, entity_type, entity_id, current_step_id, status, started_at)
  VALUES (v_workflow_id, 'return', _return_id, v_first_step, 'active', now())
  RETURNING id INTO v_instance_id;

  UPDATE public.returns_filed
     SET current_step_id = v_first_step,
         workflow_id = v_workflow_id,
         updated_at = now()
   WHERE id = _return_id;

  INSERT INTO public.return_audit_log
    (return_id, action, previous_status, new_status, comments, performed_by,
     previous_step_id, new_step_id, actor_role, metadata, event_key, source)
  VALUES
    (_return_id, 'workflow_started', v_ret.workflow_status::text, v_ret.workflow_status::text,
     'Workflow started', NULL, v_ret.current_step_id, v_first_step, NULL,
     jsonb_build_object('workflow_id', v_workflow_id, 'instance_id', v_instance_id),
     'return.workflow_started', 'rpc:start_return_workflow'),
    (_return_id, 'workflow_step_assigned', v_ret.workflow_status::text, v_ret.workflow_status::text,
     'Initial workflow step assigned', NULL, v_ret.current_step_id, v_first_step, NULL,
     jsonb_build_object('workflow_id', v_workflow_id, 'instance_id', v_instance_id, 'step_id', v_first_step),
     'return.workflow_step_assigned', 'rpc:start_return_workflow');

  RETURN jsonb_build_object(
    'success', true,
    'reused', false,
    'instance_id', v_instance_id,
    'workflow_id', v_workflow_id,
    'step_id', v_first_step,
    'http', 200
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.submit_application(_application_id uuid, _ack_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_now timestamptz := now();
  v_is_resub boolean;
  v_payment_count int;
  v_sector_id uuid;
  v_sub_sector_id uuid;
  v_service_id uuid;
  v_category_id uuid;
  v_license_id uuid;
  v_workflow_id uuid;
  v_first_step_id uuid;
  v_existing_instance record;
  v_new_instance_id uuid;
  v_action_label text;
  v_audit_action text;
  v_app_status_target text;
  v_effective_regulator uuid;
  v_is_post_license boolean;
  v_ctx record;
  v_authority text;
  v_canonical jsonb;
BEGIN
  PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;

  SELECT id, applicant_id, entity_id, application_number, status, license_type,
         regulator_id, data
    INTO v_app
    FROM public.applications
   WHERE id = _application_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Application not found','code','NOT_FOUND','http',404);
  END IF;

  -- GAP-F5-02: submission authority is an entity capability, not row ownership.
  IF v_app.applicant_id = v_uid THEN
    v_authority := 'applicant';
  ELSIF v_app.entity_id IS NOT NULL
        AND public.entity_membership_capability(v_uid, v_app.entity_id, 'submit') THEN
    v_authority := 'entity_delegate';
  ELSE
    RETURN jsonb_build_object(
      'error','You are not authorised to submit this filing for this entity',
      'code','FORBIDDEN','http',403);
  END IF;

  v_is_resub := v_app.status IN (
    'resubmission_requested','resubmission_required',
    'returned_for_correction','info_requested',
    'query_raised'
  );
  IF v_app.status NOT IN ('draft', 'in_progress') AND NOT v_is_resub THEN
    RETURN jsonb_build_object(
      'error', format('Application is in ''%s'' status — cannot submit', v_app.status),
      'code','INVALID_STATUS','http',409
    );
  END IF;

  SELECT count(*) INTO v_payment_count
    FROM public.payments
   WHERE application_id = _application_id
     AND status IN ('completed','success','paid');
  IF v_payment_count = 0 THEN
    RETURN jsonb_build_object(
      'error','No completed payment found — please complete payment first',
      'code','PAYMENT_REQUIRED','http',402
    );
  END IF;

  v_sector_id := NULLIF(v_app.data->>'sector_id','')::uuid;
  v_sub_sector_id := NULLIF(v_app.data->>'sub_sector_id','')::uuid;
  v_service_id := NULLIF(v_app.data->>'service_id','')::uuid;
  v_category_id := NULLIF(v_app.data->>'category_id','')::uuid;
  v_license_id := NULLIF(v_app.data->>'license_id','')::uuid;
  v_is_post_license := v_service_id IS NOT NULL OR (v_app.data->>'type') = 'post_license';

  -- GAP-F5-01 / GAP-F5-15: re-derive taxonomy from the licence at submission
  -- and refuse any incompatible or ineligible binding.
  IF v_is_post_license THEN
    IF v_license_id IS NULL THEN
      RETURN jsonb_build_object(
        'error','This post-licence filing is not bound to a licence','code','LICENSE_REQUIRED','http',409);
    END IF;

    SELECT * INTO v_ctx
      FROM public.resolve_post_license_intake_context(v_license_id, v_service_id);
    IF v_ctx.entity_id IS NULL THEN
      RETURN jsonb_build_object(
        'error','The licence for this filing could not be found','code','LICENSE_NOT_FOUND','http',409);
    END IF;

    IF v_service_id IS NOT NULL
       AND NOT public.service_license_compatible(v_service_id, v_license_id) THEN
      RETURN jsonb_build_object(
        'error','The selected service is not available for the scope of this licence',
        'code','SERVICE_LICENSE_INCOMPATIBLE','http',409);
    END IF;

    IF NOT public.can_act_on_specific_license(v_license_id, v_ctx.entity_id, NULL, NULL, NULL) THEN
      RETURN jsonb_build_object(
        'error','This service is unavailable because the related licence is not currently approved, issued and in good standing.',
        'code','LICENSE_ENTITLEMENT_REQUIRED','http',409);
    END IF;

    v_sector_id := v_ctx.sector_id;
    v_sub_sector_id := v_ctx.sub_sector_id;
    v_category_id := v_ctx.category_id;

    v_canonical := jsonb_build_object(
      'licensee_id', v_ctx.entity_id,
      'sector_id', v_ctx.sector_id,
      'sub_sector_id', v_ctx.sub_sector_id,
      'category_id', v_ctx.category_id
    );

    UPDATE public.applications
       SET data = COALESCE(data,'{}'::jsonb) || v_canonical,
           entity_id = COALESCE(entity_id, v_ctx.entity_id),
           updated_at = v_now
     WHERE id = _application_id;
  END IF;

  v_effective_regulator := public._resolve_effective_regulator(
    v_app.regulator_id, v_sector_id, v_category_id
  );

  SELECT id, workflow_id, current_step_id, status
    INTO v_existing_instance
    FROM public.workflow_instances
   WHERE entity_id = _application_id
     AND entity_type = 'application'
     AND status IN ('active','paused')
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE;

  IF FOUND THEN
    v_workflow_id := v_existing_instance.workflow_id;
    v_first_step_id := v_existing_instance.current_step_id;
    IF v_existing_instance.status = 'paused' THEN
      UPDATE public.workflow_instances
         SET status = 'active', updated_at = v_now
       WHERE id = v_existing_instance.id;
    END IF;
  ELSE
    SELECT r.workflow_id, r.first_step_id INTO v_workflow_id, v_first_step_id
      FROM public._resolve_application_workflow(
             v_app.license_type, v_effective_regulator, v_sector_id, v_category_id,
             v_is_post_license, v_service_id, v_sub_sector_id) r;

    IF v_workflow_id IS NOT NULL THEN
      INSERT INTO public.workflow_instances (
        workflow_id, entity_type, entity_id, current_step_id, status
      ) VALUES (
        v_workflow_id, 'application', _application_id, v_first_step_id, 'active'
      )
      RETURNING id INTO v_new_instance_id;
    END IF;
  END IF;

  v_app_status_target := 'submitted';

  UPDATE public.applications
     SET status = v_app_status_target,
         submitted_at = COALESCE(submitted_at, v_now),
         workflow_id = COALESCE(workflow_id, v_workflow_id),
         current_step_id = v_first_step_id,
         regulator_id = COALESCE(v_effective_regulator, regulator_id),
         ack_by = CASE WHEN _ack_text IS NOT NULL THEN v_uid ELSE ack_by END,
         ack_at = CASE WHEN _ack_text IS NOT NULL THEN v_now ELSE ack_at END,
         ack_text = CASE WHEN _ack_text IS NOT NULL
                         THEN substring(_ack_text from 1 for 4000)
                         ELSE ack_text END,
         updated_at = v_now
   WHERE id = _application_id;

  UPDATE public.form_responses
     SET status = 'submitted', submitted_at = v_now
   WHERE entity_id = _application_id
     AND entity_type = 'application';

  v_action_label := CASE WHEN v_is_resub THEN 'resubmitted' ELSE 'submitted' END;
  v_audit_action := CASE WHEN v_is_resub THEN 'resubmitted' ELSE 'submitted' END;

  INSERT INTO public.audit_logs (
    entity_type, entity_id, action, user_id, new_value, metadata
  ) VALUES (
    'application',
    _application_id::text,
    'application.' || v_audit_action,
    v_uid,
    jsonb_build_object('status', v_app_status_target),
    jsonb_build_object(
      'source', 'submit_application_rpc',
      'application_id', _application_id,
      'application_number', v_app.application_number,
      'workflow_id', v_workflow_id,
      'first_step_id', v_first_step_id,
      'is_resubmission', v_is_resub,
      'previous_status', v_app.status,
      'resumed', v_is_resub,
      'submission_authority', v_authority,
      'submitted_by', v_uid,
      'applicant_id', v_app.applicant_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'application_id', _application_id,
    'application_number', v_app.application_number,
    'status', v_app_status_target,
    'workflow_id', v_workflow_id,
    'first_step_id', v_first_step_id,
    'is_resubmission', v_is_resub,
    'resumed', v_is_resub,
    'workflow_attached', v_workflow_id IS NOT NULL,
    'submission_authority', v_authority,
    'previous_status', v_app.status
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.submit_declaration_by_token(p_token text, p_inv_id uuid, p_assessment_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hash text := encode(sha256(p_token::bytea), 'hex');
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.declaration_invitations
    WHERE id = p_inv_id AND token_hash = v_hash AND assessment_id = p_assessment_id
  ) THEN
    RETURN false;
  END IF;

  UPDATE public.declaration_invitations
  SET    status       = 'SUBMITTED',
         submitted_at = now()
  WHERE  id = p_inv_id;

  RETURN true;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.submit_declaration_form(p_token text, p_inv_id uuid, p_assessment_id uuid, p_form_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hash           text := encode(sha256(p_token::bytea), 'hex');
  v_existing       jsonb;
  v_merged         jsonb;
  v_assess_creator uuid;
  v_inv_sender     uuid;
  v_indiv_name     text;
  v_assess_type    text;
  v_notif_message  text;
  v_config_ids     uuid[];
BEGIN
  -- ── 1. Validate token → invitation is still open & unexpired ──────────────
  IF NOT EXISTS (
    SELECT 1
    FROM   public.declaration_invitations
    WHERE  id            = p_inv_id
      AND  token_hash    = v_hash
      AND  assessment_id = p_assessment_id
      AND  status       != 'SUBMITTED'
      AND  expires_at    > now()
  ) THEN
    RETURN jsonb_build_object('success', false);
  END IF;

  -- ── 2. Fetch context needed for notifications ─────────────────────────────
  SELECT a.created_by,
         i.full_name,
         a.assessment_type
  INTO   v_assess_creator,
         v_indiv_name,
         v_assess_type
  FROM   public.fp_assessments a
  JOIN   public.fp_individuals i ON i.id = a.individual_id
  WHERE  a.id = p_assessment_id;

  SELECT created_by
  INTO   v_inv_sender
  FROM   public.declaration_invitations
  WHERE  id = p_inv_id;

  -- ── 3. Merge form data into fp_assessments.declaration_data ───────────────
  SELECT COALESCE(declaration_data, '{}'::jsonb)
  INTO   v_existing
  FROM   public.fp_assessments
  WHERE  id = p_assessment_id;

  v_merged := v_existing
           || p_form_data
           || jsonb_build_object('submitted_at', now()::text);

  -- ── 4. Persist & advance assessment status ────────────────────────────────
  UPDATE public.fp_assessments
  SET    declaration_data = v_merged,
         status           = CASE
                              WHEN status IN ('draft', 'screening') THEN 'submitted'
                              ELSE status
                            END,
         updated_at       = now()
  WHERE  id = p_assessment_id;

  -- ── 5. Mark invitation SUBMITTED ──────────────────────────────────────────
  UPDATE public.declaration_invitations
  SET    status       = 'SUBMITTED',
         submitted_at = now()
  WHERE  id = p_inv_id;

  -- ── 6. Build notification message ─────────────────────────────────────────
  v_notif_message :=
    COALESCE(v_indiv_name, 'An individual')
    || ' has submitted their Personal Questionnaire Declaration'
    || CASE
         WHEN v_assess_type IS NOT NULL
         THEN ' (' || replace(v_assess_type, '_', ' ') || ' assessment)'
         ELSE ''
       END
    || '. The assessment is ready for your review.';

  -- ── 7. Notify the assessment creator ─────────────────────────────────────
  -- SECURITY DEFINER bypasses RLS — insert always succeeds.
  -- The INSERT triggers Supabase Realtime → bell badge updates instantly.
  IF v_assess_creator IS NOT NULL THEN
    INSERT INTO public.notifications (
      user_id, title, message, type,
      entity_type, entity_id,
      channel, delivery_status, read
    ) VALUES (
      v_assess_creator,
      'Declaration Submitted',
      v_notif_message,
      'success',
      'fp_assessment', p_assessment_id::text,
      'in_app', 'delivered', false
    );
  END IF;

  -- ── 8. Notify the invitation sender (if different from assessment creator) ─
  IF v_inv_sender IS NOT NULL
     AND v_inv_sender IS DISTINCT FROM v_assess_creator THEN
    INSERT INTO public.notifications (
      user_id, title, message, type,
      entity_type, entity_id,
      channel, delivery_status, read
    ) VALUES (
      v_inv_sender,
      'Declaration Submitted',
      v_notif_message,
      'success',
      'fp_assessment', p_assessment_id::text,
      'in_app', 'delivered', false
    );
  END IF;

  -- ── 9. Resolve active "Received Declaration" automatic screening rules ────
  SELECT COALESCE(array_agg(screening_config_id), ARRAY[]::uuid[])
  INTO   v_config_ids
  FROM   public.fp_screening_execution_rules
  WHERE  is_active     = true
    AND  trigger_event = 'declaration_received'
    AND  (assessment_type IS NULL OR assessment_type = v_assess_type);

  -- ── 10. Record a real before/after audit entry ────────────────────────────
  -- Actor is anonymous (public portal, anon role), so user_id is NULL; the
  -- insert bypasses the client-INSERT revocation because this function runs
  -- SECURITY DEFINER.
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value, metadata)
  VALUES (
    NULL,
    'fp_assessment.declaration_submitted',
    'fp_assessment',
    p_assessment_id,
    jsonb_build_object('declaration_data', v_existing),
    jsonb_build_object('declaration_data', v_merged),
    jsonb_build_object('source', 'public_portal', 'invitation_id', p_inv_id)
  );

  RETURN jsonb_build_object('success', true, 'auto_config_ids', to_jsonb(v_config_ids));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.submit_offline_payment(_application_id uuid, _amount numeric, _offline_method text, _payment_date date, _reference text, _bank_name text DEFAULT NULL::text, _remarks text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_existing record;
  v_pay record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code','UNAUTHORIZED','message','You must be signed in.');
  END IF;
  IF _offline_method IS NULL OR _offline_method NOT IN ('bank_transfer','cheque','cash','demand_draft','manager_cheque') THEN
    RETURN jsonb_build_object('ok', false, 'code','INVALID','message','Select a valid offline payment method.');
  END IF;
  IF _amount IS NULL OR _amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'code','INVALID','message','Enter the amount paid.');
  END IF;
  IF _offline_method <> 'cash' AND (_reference IS NULL OR length(TRIM(_reference)) < 3) THEN
    RETURN jsonb_build_object('ok', false, 'code','INVALID','message','Enter the payment reference (min 3 characters).');
  END IF;
  IF _payment_date IS NULL OR _payment_date > (now()::date) OR _payment_date < (now()::date - interval '2 years') THEN
    RETURN jsonb_build_object('ok', false, 'code','INVALID','message','Enter a valid payment date.');
  END IF;

  SELECT id, applicant_id, status INTO v_app FROM public.applications WHERE id = _application_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code','NOT_FOUND','message','Application not found.');
  END IF;
  IF v_app.applicant_id <> v_uid
     AND NOT public.has_role(v_uid,'super_admin'::app_role)
     AND NOT public.has_role(v_uid,'admin'::app_role) THEN
    RETURN jsonb_build_object('ok', false, 'code','FORBIDDEN','message','You do not have access to this application.');
  END IF;
  IF lower(COALESCE(v_app.status,'')) IN ('approved','rejected','cancelled','withdrawn') THEN
    RETURN jsonb_build_object('ok', false, 'code','INVALID_STATE',
      'message','This application is closed and cannot accept a new payment.');
  END IF;

  SELECT id, status, verification_status INTO v_existing
    FROM public.payments
   WHERE application_id = _application_id
     AND (lower(status) IN ('completed','success','paid')
          OR (payment_channel = 'offline' AND verification_status = 'pending'))
   ORDER BY created_at DESC LIMIT 1;

  IF v_existing.id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'code','ALREADY_EXISTS','payment_id', v_existing.id,
      'message','A payment already exists for this application.');
  END IF;

  INSERT INTO public.payments (
    user_id, application_id, amount, status, payment_method, payment_channel,
    offline_method, payment_date, bank_name, transaction_ref,
    verification_status, verification_remarks
  ) VALUES (
    v_uid, _application_id, _amount, 'pending_verification', 'offline', 'offline',
    _offline_method, _payment_date, NULLIF(TRIM(COALESCE(_bank_name,'')),''), NULLIF(TRIM(COALESCE(_reference,'')),''),
    'pending', NULLIF(TRIM(COALESCE(_remarks,'')),'')
  ) RETURNING id, status, verification_status INTO v_pay;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, new_value)
  VALUES (v_uid, 'offline_payment_submitted', 'payment', v_pay.id,
          jsonb_build_object('application_id', _application_id, 'amount', _amount,
                             'offline_method', _offline_method, 'payment_date', _payment_date,
                             'verification_status', 'pending'));

  RETURN jsonb_build_object('ok', true, 'payment_id', v_pay.id, 'status', v_pay.status,
    'verification_status', v_pay.verification_status);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.submit_prudential_action_response(_action_id uuid, _narrative text, _document_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid();
        _a public.prudential_actions;
        _resp public.prudential_action_responses;
BEGIN
  IF _uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHENTICATED');
  END IF;
  SELECT * INTO _a FROM public.prudential_actions WHERE id = _action_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Action not found','code','NOT_FOUND');
  END IF;
  IF NOT public.is_prudential_action_entity_user(_uid, _action_id) THEN
    RETURN jsonb_build_object('error','Only users of the regulated entity may respond to this action','code','FORBIDDEN');
  END IF;
  IF _a.status IN ('completed','waived','cancelled') THEN
    RETURN jsonb_build_object('error','Action is closed','code','CLOSED');
  END IF;
  IF _narrative IS NULL OR length(trim(_narrative)) < 5 THEN
    RETURN jsonb_build_object('error','A response narrative of at least 5 characters is required','code','VALIDATION');
  END IF;
  IF _a.evidence_required AND COALESCE(array_length(_document_ids,1),0) = 0 THEN
    RETURN jsonb_build_object('error','This action requires supporting evidence documents','code','EVIDENCE_REQUIRED');
  END IF;

  INSERT INTO public.prudential_action_responses(action_id, kind, narrative, evidence_document_ids, submitted_by)
  VALUES (_action_id, 'entity_response', trim(_narrative), COALESCE(_document_ids,'{}'::uuid[]), _uid)
  RETURNING * INTO _resp;

  UPDATE public.prudential_actions
     SET status = 'awaiting_review',
         review_status = 'awaiting_review',
         review_notes = NULL,
         reviewed_by = NULL,
         reviewed_at = NULL,
         updated_at = now()
   WHERE id = _action_id;

  INSERT INTO public.prudential_action_events(action_id, event_type, from_status, to_status, actor_id, reason, metadata)
  VALUES (_action_id, 'entity_response_submitted', _a.status, 'awaiting_review', _uid, NULL,
          jsonb_build_object('response_id', _resp.id, 'document_count', COALESCE(array_length(_document_ids,1),0)));

  RETURN jsonb_build_object('ok', true, 'response_id', _resp.id);
END $function$
;
CREATE OR REPLACE FUNCTION public.sup_can_read_domain(_user uuid, _domain text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case
    when _user is null then false
    when public.is_super_admin(_user) then true
    when _domain = 'prudential' then public.has_permission(_user,'prudential_supervision','view')
      or public.has_permission(_user,'returns_management','view')
    when _domain = 'conduct' then public.has_permission(_user,'market_conduct','view')
      or public.has_permission(_user,'complaint_management','view')
    when _domain = 'licensing' then public.has_permission(_user,'application_management','view')
      or public.has_permission(_user,'license_management','view')
    when _domain = 'returns' then public.has_permission(_user,'returns_management','view')
    else false
  end
$function$
;
CREATE OR REPLACE FUNCTION public.sup_dashboard_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  u uuid := public.sup_read_guard();
  can_pru boolean := public.sup_can_read_domain(u,'prudential');
  can_con boolean := public.sup_can_read_domain(u,'conduct');
  can_lic boolean := public.sup_can_read_domain(u,'licensing');
  res jsonb := jsonb_build_object('generated_at', now(),
    'domains', jsonb_build_object('prudential', can_pru, 'conduct', can_con, 'licensing', can_lic));
begin
  if can_pru then
    res := res || jsonb_build_object('prudential', jsonb_build_object(
      'current_breaches', (select count(*) from public.v_prudential_current_breaches where level = 'breach'),
      'current_ewis', (select count(*) from public.v_prudential_current_breaches where level <> 'breach'),
      'awaiting_acknowledgement', (select count(*) from public.v_prudential_current_breaches where acknowledged_at is null),
      'entities_with_signals', (select count(distinct entity_id) from public.v_prudential_current_breaches),
      'open_plan_actions', (select count(*) from public.supervisory_plan_actions where status <> 'completed')
    ), 'returns', jsonb_build_object(
      'awaiting_review', (select count(*) from public.return_filings where upper(status) in ('SUBMITTED','UNDER_REVIEW')),
      'overdue', (select count(*) from public.return_filings f
         join public.reporting_periods rp on rp.id = f.reporting_period_id
         where f.accepted_at is null and rp.due_date < current_date),
      'due_next_30_days', (select count(*) from public.reporting_periods rp
         where rp.due_date between current_date and current_date + 30 and rp.closed_at is null),
      'accepted_last_30_days', (select count(*) from public.return_filings
         where accepted_at >= now() - interval '30 days')
    ));
  end if;

  if can_con then
    res := res || jsonb_build_object('conduct', jsonb_build_object(
      'open_complaints', (select count(*) from public.complaints where closed_at is null),
      'complaints_sla_breached', (select count(*) from public.complaints
         where closed_at is null and sla_due_at is not null and sla_due_at < now()),
      'open_alerts', (select count(*) from public.conduct_alerts where closed_at is null),
      'open_investigations', (select count(*) from public.conduct_investigations where closed_at is null),
      'open_thematic_reviews', (select count(*) from public.thematic_reviews where closed_at is null),
      'open_thematic_actions', (select count(*) from public.thematic_review_actions where status <> 'completed'),
      'overdue_conduct_actions', (select count(*) from public.conduct_actions
         where status not in ('completed','cancelled') and due_date < current_date),
      'open_enforcement', (select count(*) from public.enforcement_actions where closed_at is null)
    ));
  end if;

  if can_lic then
    res := res || jsonb_build_object('licensing', jsonb_build_object(
      'in_flight_applications', (select count(*) from public.applications
         where status in ('submitted','under_review','pending_approval')),
      'decided_last_30_days', (select count(*) from public.decision_artifacts
         where issued_at >= now() - interval '30 days'),
      'artifacts_total', (select count(*) from public.decision_artifacts)
    ));
  end if;

  return res;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.sup_entity_supervisory_state(_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  u uuid := public.sup_read_guard();
  can_pru boolean := public.sup_can_read_domain(u,'prudential');
  can_con boolean := public.sup_can_read_domain(u,'conduct');
  can_lic boolean := public.sup_can_read_domain(u,'licensing');
  res jsonb;
begin
  if _entity_id is null then raise exception 'entity_id required'; end if;

  res := jsonb_build_object(
    'entity_id', _entity_id,
    'sections', jsonb_build_object('prudential', can_pru, 'conduct', can_con, 'licensing', can_lic),
    'generated_at', now()
  );

  res := res || jsonb_build_object('returns', jsonb_build_object(
    'obligations_active', (select count(*) from public.entity_reporting_obligations o
       where o.entity_id = _entity_id and lower(o.status) = 'active'),
    'filings_total', (select count(*) from public.return_filings f where f.entity_id = _entity_id),
    'filings_awaiting_review', (select count(*) from public.return_filings f
       where f.entity_id = _entity_id and upper(f.status) in ('SUBMITTED','UNDER_REVIEW')),
    'filings_overdue', (select count(*) from public.return_filings f
       join public.reporting_periods rp on rp.id = f.reporting_period_id
       where f.entity_id = _entity_id and f.accepted_at is null and rp.due_date < current_date),
    'next_due', (select jsonb_build_object('period_label', rp.period_label, 'due_date', rp.due_date)
       from public.reporting_periods rp
       join public.entity_reporting_obligations o on o.id = rp.entity_reporting_obligation_id
       where o.entity_id = _entity_id and rp.due_date >= current_date
       order by rp.due_date limit 1),
    'latest_accepted_filing', (select jsonb_build_object('id', f.id, 'reference', f.filing_reference,
         'accepted_at', f.accepted_at, 'version', f.current_version_number)
       from public.return_filings f
       where f.entity_id = _entity_id and f.accepted_at is not null
       order by f.accepted_at desc limit 1)
  ));

  if can_pru then
    res := res || jsonb_build_object('prudential', jsonb_build_object(
      'current_breaches', (select count(*) from public.v_prudential_current_breaches b
         where b.entity_id = _entity_id and b.level = 'breach'),
      'current_ewis', (select count(*) from public.v_prudential_current_breaches b
         where b.entity_id = _entity_id and b.level <> 'breach'),
      'unacknowledged', (select count(*) from public.v_prudential_current_breaches b
         where b.entity_id = _entity_id and b.acknowledged_at is null),
      'signals', coalesce((select jsonb_agg(s.x order by s.detected_at desc) from (
          select jsonb_build_object('id', b.id, 'metric_key', b.metric_key, 'level', b.level,
            'value', b.value, 'threshold_value', b.threshold_value, 'comparator', b.comparator,
            'detected_at', b.detected_at, 'detection_source', b.detection_source,
            'detection_run_id', b.detection_run_id, 'return_filing_id', b.return_filing_id,
            'acknowledged_at', b.acknowledged_at, 'escalated_enforcement_id', b.escalated_enforcement_id,
            'directives', coalesce((select jsonb_agg(jsonb_build_object(
                 'id', pact.id, 'reference', pact.action_reference, 'action_type', pact.action_type,
                 'title', pact.title, 'status', pact.status, 'severity', pact.severity,
                 'due_date', pact.due_date) order by pact.created_at desc)
               from public.prudential_actions pact
               where pact.source_type = 'return_breach' and pact.source_id = b.id), '[]'::jsonb)) x,
            b.detected_at
          from public.v_prudential_current_breaches b where b.entity_id = _entity_id
          order by b.detected_at desc limit 25) s), '[]'::jsonb),
      'latest_approved_assessment', (select jsonb_build_object('id', pa.id, 'period_end', pa.period_end,
           'overall_rating', pa.overall_rating, 'status', pa.status, 'approved_at', pa.approved_at)
         from public.prudential_assessments pa
         where pa.entity_id = _entity_id and pa.approved_at is not null
         order by pa.approved_at desc limit 1),
      'open_directives', (select count(*) from public.prudential_actions pact
         where pact.entity_id = _entity_id and pact.status not in ('completed','cancelled','closed')),
      'open_plan_actions', (select count(*) from public.supervisory_plan_actions sa
         join public.supervisory_plans sp on sp.id = sa.plan_id
         where sp.entity_id = _entity_id and sa.status <> 'completed')
    ));
  end if;

  if can_con then
    res := res || jsonb_build_object('conduct', jsonb_build_object(
      'open_complaints', (select count(*) from public.complaints c
         where c.licensee_id = _entity_id and c.closed_at is null),
      'open_alerts', (select count(*) from public.conduct_alerts a
         where a.licensee_id = _entity_id and a.closed_at is null),
      'alerts', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'title', a.title,
           'kind', a.kind, 'severity', a.severity, 'status', a.status, 'created_at', a.created_at,
           'investigation_id', a.investigation_id))
         from public.conduct_alerts a where a.licensee_id = _entity_id
           and a.created_at >= now() - interval '365 days'), '[]'::jsonb),
      'open_investigations', (select count(*) from public.conduct_investigations i
         where i.licensee_id = _entity_id and i.closed_at is null),
      'investigations', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'code', i.code,
           'status', i.status, 'severity', i.severity, 'outcome', i.outcome, 'closed_at', i.closed_at))
         from public.conduct_investigations i where i.licensee_id = _entity_id), '[]'::jsonb),
      'open_conduct_actions', (select count(*) from public.conduct_actions ca
         where ca.entity_id = _entity_id and ca.status not in ('completed','cancelled')),
      'conduct_actions', coalesce((select jsonb_agg(jsonb_build_object('id', ca.id, 'title', ca.title,
           'action_type', ca.action_type, 'status', ca.status, 'due_date', ca.due_date))
         from public.conduct_actions ca where ca.entity_id = _entity_id), '[]'::jsonb),
      'thematic_reviews_in_scope', (select count(distinct tre.review_id)
         from public.thematic_review_entities tre where tre.licensee_id = _entity_id),
      'thematic_findings', (select count(*) from public.thematic_review_findings tf
         where tf.licensee_id = _entity_id
            or tf.review_id in (select tre.review_id from public.thematic_review_entities tre
                                 where tre.licensee_id = _entity_id)),
      'open_thematic_actions', (select count(*) from public.thematic_review_actions ta
         where ta.licensee_id = _entity_id and ta.status <> 'completed'),
      'thematic', coalesce((select jsonb_agg(jsonb_build_object('review_id', tr.id, 'code', tr.code,
           'title', tr.title, 'status', tr.status, 'closure_state', tr.closure_state,
           'closed_at', tr.closed_at,
           'findings', (select count(*) from public.thematic_review_findings f where f.review_id = tr.id),
           'actions_open', (select count(*) from public.thematic_review_actions a
              where a.review_id = tr.id and a.status <> 'completed')))
         from public.thematic_reviews tr
         where tr.id in (select tre.review_id from public.thematic_review_entities tre
                          where tre.licensee_id = _entity_id)
            or tr.id in (select ta.review_id from public.thematic_review_actions ta
                          where ta.licensee_id = _entity_id)), '[]'::jsonb),
      'open_enforcement', (select count(*) from public.enforcement_actions ea
         where ea.entity_id = _entity_id and ea.closed_at is null)
    ));
  end if;

  if can_lic then
    res := res || jsonb_build_object('licensing', jsonb_build_object(
      'open_applications', (select count(*) from public.applications a
         where a.entity_id = _entity_id and a.status not in ('approved','rejected','withdrawn','closed')),
      'decision_artifacts', (select count(*) from public.decision_artifacts da
         join public.applications a on a.id = da.application_id where a.entity_id = _entity_id),
      'artifacts', coalesce((select jsonb_agg(jsonb_build_object('id', da.id, 'artifact_type', da.artifact_type,
           'version', da.version, 'decision', da.decision, 'issued_at', da.issued_at,
           'checksum', da.checksum, 'application_id', da.application_id) order by da.issued_at desc)
         from public.decision_artifacts da
         join public.applications a on a.id = da.application_id
         where a.entity_id = _entity_id), '[]'::jsonb),
      'latest_decision_artifact', (select jsonb_build_object('id', da.id, 'artifact_type', da.artifact_type,
           'version', da.version, 'decision', da.decision, 'issued_at', da.issued_at)
         from public.decision_artifacts da
         join public.applications a on a.id = da.application_id
         where a.entity_id = _entity_id order by da.issued_at desc limit 1)
    ));
  end if;

  return res;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.sup_priority_work_queue(_limit integer DEFAULT 50, _domain text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  u uuid := public.sup_read_guard();
  can_pru boolean := public.sup_can_read_domain(u,'prudential');
  can_con boolean := public.sup_can_read_domain(u,'conduct');
  can_lic boolean := public.sup_can_read_domain(u,'licensing');
  lim integer := least(greatest(coalesce(_limit,50),1),200);
begin
  return coalesce((
    select jsonb_agg(z.x order by z.rank_order, z.due_at nulls last)
    from (
      select q.x, q.rank_order, q.due_at
      from (
        select jsonb_build_object('kind','prudential_signal','domain','prudential',
          'id', b.id, 'entity_id', b.entity_id,
          'title', initcap(replace(lower(b.metric_key),'_',' ')) || ' ' || lower(b.level),
          'severity', case when b.level = 'breach' then 'critical' else 'high' end,
          'status', case when b.acknowledged_at is null then 'awaiting_acknowledgement' else 'acknowledged' end,
          'due_at', b.detected_at, 'href', '/supervision/breaches') x,
          case when b.level = 'breach' then 1 else 2 end rank_order, b.detected_at due_at
        from public.v_prudential_current_breaches b
        where can_pru and (_domain is null or _domain = 'prudential') and b.acknowledged_at is null
        union all
        select jsonb_build_object('kind','return_filing','domain','returns',
          'id', f.id, 'entity_id', f.entity_id,
          'title', coalesce(f.filing_reference,'Return filing'),
          'severity', case when rp.due_date < current_date and f.accepted_at is null then 'high' else 'medium' end,
          'status', f.status, 'due_at', rp.due_date::timestamptz,
          'href', '/returns/filings/' || f.id),
          case when rp.due_date < current_date and f.accepted_at is null then 2 else 4 end, rp.due_date::timestamptz
        from public.return_filings f
        left join public.reporting_periods rp on rp.id = f.reporting_period_id
        where can_pru and (_domain is null or _domain = 'returns')
          and (upper(f.status) in ('SUBMITTED','UNDER_REVIEW','CORRECTION_REQUESTED')
               or (f.accepted_at is null and rp.due_date < current_date))
        union all
        select jsonb_build_object('kind','conduct_investigation','domain','conduct',
          'id', i.id, 'entity_id', i.licensee_id,
          'title', coalesce(i.code,'Conduct investigation'),
          'severity', coalesce(i.severity,'medium'), 'status', i.status, 'due_at', null,
          'href', '/conduct/investigations/' || i.id),
          3, i.created_at
        from public.conduct_investigations i
        where can_con and (_domain is null or _domain = 'conduct') and i.closed_at is null
        union all
        select jsonb_build_object('kind','conduct_action','domain','conduct',
          'id', ca.id, 'entity_id', ca.entity_id, 'title', ca.title,
          'severity', case when ca.due_date < current_date then 'high' else 'medium' end,
          'status', ca.status, 'due_at', ca.due_date::timestamptz,
          'href', '/conduct/actions'),
          case when ca.due_date < current_date then 2 else 4 end, ca.due_date::timestamptz
        from public.conduct_actions ca
        where can_con and (_domain is null or _domain = 'conduct') and ca.status not in ('completed','cancelled')
        union all
        select jsonb_build_object('kind','thematic_action','domain','conduct',
          'id', ta.id, 'entity_id', ta.licensee_id, 'title', ta.title,
          'severity', case when ta.due_date < current_date then 'high' else 'medium' end,
          'status', ta.status, 'due_at', ta.due_date::timestamptz,
          'href', '/supervision/thematic-reviews/' || ta.review_id),
          case when ta.due_date < current_date then 2 else 4 end, ta.due_date::timestamptz
        from public.thematic_review_actions ta
        where can_con and (_domain is null or _domain = 'conduct') and ta.status <> 'completed'
        union all
        select jsonb_build_object('kind','application','domain','licensing',
          'id', a.id, 'entity_id', a.entity_id,
          'title', coalesce(a.application_number,'Licence application'),
          'severity','medium', 'status', a.status, 'due_at', a.created_at,
          'href', '/applications/' || a.id),
          4, a.created_at
        from public.applications a
        where can_lic and (_domain is null or _domain = 'licensing')
          and a.status in ('submitted','under_review','in_progress','pending_approval')
      ) q
      order by q.rank_order, q.due_at nulls last
      limit lim
    ) z
  ), '[]'::jsonb);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.sup_read_guard()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  u uuid := auth.uid();
  has_internal boolean;
begin
  if u is null then raise exception 'authentication required'; end if;

  select exists (
    select 1 from public.user_roles
    where user_id = u
      and role in ('super_admin'::app_role,'admin'::app_role,'supervisor'::app_role,
                   'licensing_officer'::app_role,'analyst'::app_role,
                   'legal_compliance'::app_role,'developer'::app_role)
  ) into has_internal;

  -- Supervisory read models are internal-only. A session that holds no
  -- internal role (external user, or an authenticated account with no roles
  -- at all) must never reach supervisory truth.
  if not has_internal then
    raise exception 'not authorised: supervisory read models are internal only';
  end if;
  return u;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.sup_team_performance(_from date DEFAULT (CURRENT_DATE - 90), _to date DEFAULT CURRENT_DATE, _domain text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  u uuid := public.sup_read_guard();
  can_pru boolean := public.sup_can_read_domain(u,'prudential');
  can_con boolean := public.sup_can_read_domain(u,'conduct');
  can_lic boolean := public.sup_can_read_domain(u,'licensing');
  allowed boolean := public.is_super_admin(u)
    or public.has_permission(u,'admin_dashboard','view')
    or public.has_permission(u,'report_management','view')
    or public.has_permission(u,'employee_management','view');
  d_from timestamptz := coalesce(_from, current_date - 90)::timestamptz;
  d_to timestamptz := (coalesce(_to, current_date) + 1)::timestamptz;
begin
  if not allowed then
    raise exception 'not authorised to view team performance';
  end if;

  return jsonb_build_object(
    'period', jsonb_build_object('from', _from, 'to', _to),
    'domains', jsonb_build_object('prudential', can_pru, 'conduct', can_con, 'licensing', can_lic),
    'officers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'officer_id', o.officer_id,
        'officer_name', coalesce(p.full_name, 'Unassigned'),
        'department', p.department,
        'open_items', o.open_items,
        'overdue_items', o.overdue_items,
        'due_soon_items', o.due_soon_items,
        'completed_in_period', o.completed_in_period,
        'by_domain', o.by_domain) order by o.open_items desc)
      from (
        select officer_id,
          count(*) filter (where state = 'open') open_items,
          count(*) filter (where state = 'open' and due_date is not null and due_date < current_date) overdue_items,
          count(*) filter (where state = 'open' and due_date between current_date and current_date + 14) due_soon_items,
          count(*) filter (where state = 'completed') completed_in_period,
          jsonb_object_agg(domain, cnt) by_domain
        from (
          select officer_id, domain, state, min(due_date) due_date, count(*) cnt
          from (
            select f.assigned_reviewer_id officer_id, 'returns'::text domain,
              case when f.accepted_at is null and f.rejected_at is null then 'open' else 'completed' end state,
              rp.due_date
            from public.return_filings f
            left join public.reporting_periods rp on rp.id = f.reporting_period_id
            where can_pru and (_domain is null or _domain = 'returns')
              and (f.accepted_at is null or f.accepted_at between d_from and d_to)
            union all
            select i.assigned_investigator, 'conduct', case when i.closed_at is null then 'open' else 'completed' end, i.due_date
            from public.conduct_investigations i
            where can_con and (_domain is null or _domain = 'conduct')
              and (i.closed_at is null or i.closed_at between d_from and d_to)
            union all
            select ca.assigned_to, 'conduct', case when ca.status in ('completed','cancelled') then 'completed' else 'open' end, ca.due_date
            from public.conduct_actions ca
            where can_con and (_domain is null or _domain = 'conduct')
              and (ca.status not in ('completed','cancelled') or ca.closed_at between d_from and d_to)
            union all
            select ta.assigned_to, 'conduct', case when ta.status = 'completed' then 'completed' else 'open' end, ta.due_date
            from public.thematic_review_actions ta
            where can_con and (_domain is null or _domain = 'conduct')
              and (ta.status <> 'completed' or ta.completed_at between d_from and d_to)
            union all
            select a.assigned_to, 'licensing',
              case when a.status in ('approved','rejected','withdrawn','closed') then 'completed' else 'open' end, null::date
            from public.applications a
            where can_lic and (_domain is null or _domain = 'licensing')
              and (a.status not in ('approved','rejected','withdrawn','closed') or a.created_at between d_from and d_to)
          ) items
          group by officer_id, domain, state
        ) g
        group by officer_id
      ) o
      left join public.profiles p on p.id = o.officer_id
    ), '[]'::jsonb),
    'unassigned', jsonb_build_object(
      'breaches_awaiting_acknowledgement', case when can_pru then
        (select count(*) from public.v_prudential_current_breaches where acknowledged_at is null) else null end,
      'filings_unassigned', case when can_pru then
        (select count(*) from public.return_filings where assigned_reviewer_id is null
           and upper(status) in ('SUBMITTED','UNDER_REVIEW')) else null end,
      'complaints_unassigned_team', case when can_con then
        (select count(*) from public.complaints where closed_at is null and assigned_team is null) else null end
    )
  );
end;
$function$
;
CREATE OR REPLACE FUNCTION public.supervisory_ai_report_detail(_id uuid)
 RETURNS TABLE(id uuid, module text, analysis_type text, title text, scope text, scope_id uuid, entity_id uuid, object_type text, object_id uuid, source_modules text[], source_records jsonb, citations jsonb, period_key text, provider_state text, model text, input_fingerprint text, feedback text, generated_at timestamp with time zone, generated_by uuid, explanation text, recommendation text, payload jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    i.id, i.module, i.analysis_type, i.title, i.scope, i.scope_id, i.entity_id,
    i.object_type, i.object_id, i.source_modules, i.source_records, i.citations,
    i.period_key, i.provider_state, i.model, i.input_fingerprint, i.feedback,
    i.generated_at, i.generated_by, i.explanation, i.recommendation,
    coalesce(i.payload, '{}'::jsonb)
  from public.ai_insights i
  where i.id = _id
    and public.can_view_advisory_ai(i.module, i.source_modules)
  limit 1;
$function$
;
CREATE OR REPLACE FUNCTION public.supervisory_ai_report_entity_options()
 RETURNS TABLE(entity_id uuid, entity_name text, n bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with counts as (
    select i.entity_id, count(*)::bigint as n
    from public.supervisory_ai_reports_index(
      null, null, null, null, null, null, true, null, null, 100000, 0) i
    where i.entity_id is not null
    group by 1
  )
  select l.id, l.name, coalesce(c.n, 0)
  from public.licensees l
  left join counts c on c.entity_id = l.id
  order by l.name
$function$
;
CREATE OR REPLACE FUNCTION public.supervisory_ai_report_facets(_modules text[] DEFAULT NULL::text[], _from timestamp with time zone DEFAULT NULL::timestamp with time zone, _to timestamp with time zone DEFAULT NULL::timestamp with time zone, _search text DEFAULT NULL::text, _include_failed boolean DEFAULT false)
 RETURNS TABLE(kind text, value text, label text, n bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with idx as (
    select * from public.supervisory_ai_reports_index(
      _modules, null, null, _from, _to, _search, _include_failed, null, null, 100000, 0)
  )
  select 'entity'::text, i.entity_id::text, i.entity_name, count(*)
  from idx i
  where i.entity_id is not null and i.entity_name is not null
  group by 2, 3
  union all
  select 'analysis_type'::text, i.analysis_type, i.analysis_type, count(*)
  from idx i
  where i.analysis_type is not null
  group by 2, 3;
$function$
;
CREATE OR REPLACE FUNCTION public.supervisory_ai_report_sources()
 RETURNS TABLE(source text, available boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select 'ai_insights'::text,
         coalesce(public.is_super_admin(auth.uid()), false)
         or public.can_view_advisory_ai('examination')
         or public.can_view_advisory_ai('enforcement')
         or public.can_view_advisory_ai('complaints')
         or public.can_view_advisory_ai('conduct')
         or public.can_view_advisory_ai('cross_module')
         or public.can_view_advisory_ai('executive')
  union all
  select 'application_assessment'::text,
         coalesce(public.is_super_admin(auth.uid()), false)
         or public.has_permission(auth.uid(), 'application_management', 'view')
         or public.has_permission(auth.uid(), 'application_management', 'view_all_entities')
  union all
  select 'fpa'::text,
         coalesce(public.is_super_admin(auth.uid()), false)
         or public.has_permission(auth.uid(), 'fit_and_proper', 'view')
         or public.has_permission(auth.uid(), 'fit_and_proper', 'view_all_entities');
$function$
;
CREATE OR REPLACE FUNCTION public.supervisory_ai_report_versions(_version_key text)
 RETURNS TABLE(id uuid, source text, module text, analysis_type text, title text, summary text, entity_id uuid, entity_name text, record_id uuid, record_reference text, subject_name text, period_key text, generated_at timestamp with time zone, generated_by uuid, confidence text, report_state text, freshness text, limited_evidence boolean, flagged boolean, feedback text, review_status text, version_key text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select i.id, i.source, i.module, i.analysis_type, i.title, i.summary,
         i.entity_id, i.entity_name, i.record_id, i.record_reference, i.subject_name,
         i.period_key, i.generated_at, i.generated_by, i.confidence,
         i.report_state, i.freshness, i.limited_evidence, i.flagged,
         i.feedback, i.review_status, i.version_key
  from public.supervisory_ai_reports_index(null, null, null, null, null, null, true, null, null, 100000, 0) i
  where i.version_key = _version_key
  order by i.generated_at desc nulls last;
$function$
;
CREATE OR REPLACE FUNCTION public.supervisory_ai_reports_index(_modules text[] DEFAULT NULL::text[], _analysis_types text[] DEFAULT NULL::text[], _entity_id uuid DEFAULT NULL::uuid, _from timestamp with time zone DEFAULT NULL::timestamp with time zone, _to timestamp with time zone DEFAULT NULL::timestamp with time zone, _search text DEFAULT NULL::text, _include_failed boolean DEFAULT false, _confidence text DEFAULT NULL::text, _freshness text DEFAULT NULL::text, _limit integer DEFAULT 25, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, source text, module text, analysis_type text, title text, summary text, entity_id uuid, entity_name text, record_id uuid, record_reference text, subject_name text, period_key text, generated_at timestamp with time zone, generated_by uuid, confidence text, report_state text, freshness text, limited_evidence boolean, flagged boolean, feedback text, review_status text, version_key text, total_count bigint, recent_7d bigint, outdated_count bigint, limited_count bigint, module_counts jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with raw as (
    select
      i.id,
      'ai_insights'::text as source,
      i.module,
      i.analysis_type,
      coalesce(nullif(btrim(i.title), ''), i.analysis_type) as title,
      nullif(btrim(coalesce(i.payload->>'summary', coalesce(i.explanation, ''))), '') as summary,
      coalesce(i.entity_id, case when i.scope = 'entity' then i.scope_id end) as entity_id,
      coalesce(i.scope_id, i.object_id, i.entity_id) as record_id,
      i.period_key,
      i.generated_at,
      i.generated_by,
      case lower(coalesce(i.payload->>'confidence', ''))
        when 'high' then 'high' when 'moderate' then 'moderate' when 'medium' then 'moderate'
        when 'limited' then 'limited' when 'low' then 'limited' else null end as confidence,
      case
        when lower(coalesce(i.provider_state, 'live')) in ('live', 'success') then 'available'
        when lower(coalesce(i.provider_state, '')) = 'insufficient_data' then 'limited'
        when lower(coalesce(i.provider_state, '')) in ('pending', 'processing', 'running') then 'processing'
        else 'failed'
      end as report_state,
      coalesce((i.payload->>'insufficient_evidence')::boolean, false)
        or lower(coalesce(i.payload->>'confidence','')) in ('limited','low')
        or lower(coalesce(i.provider_state,'')) = 'insufficient_data' as limited_evidence,
      (i.feedback = 'flagged') as flagged,
      i.feedback,
      i.review_status,
      i.module || '|' || coalesce(i.analysis_type, '') || '|' ||
        coalesce(
          (coalesce(i.scope_id, i.object_id, i.entity_id))::text,
          'scope:' || coalesce(i.scope, '') || ':' || coalesce(i.period_key, '')
        ) as version_key,
      i.input_fingerprint
    from public.ai_insights i
    where (_modules is null or i.module = any(_modules))
      and public.can_view_advisory_ai(i.module, i.source_modules)

    union all

    select
      x.id,
      'application_assessment'::text,
      'licensing'::text,
      'application_assessment'::text,
      'Licensing application AI assessment'::text,
      nullif(btrim(coalesce(x.summary, '')), ''),
      x.entity_id,
      x.application_id,
      null::text,
      coalesce(x.generated_at, x.created_at),
      null::uuid,
      case
        when x.confidence_score is null then null
        when x.confidence_score >= 0.75 then 'high'
        when x.confidence_score >= 0.5 then 'moderate'
        else 'limited' end,
      case
        when lower(coalesce(x.status,'')) in ('completed', 'ready', 'success') then 'available'
        when lower(coalesce(x.status,'')) in ('pending', 'processing', 'running', 'queued') then 'processing'
        else 'failed' end,
      (x.confidence_score is not null and x.confidence_score < 0.5),
      false,
      null::text,
      null::text,
      'licensing|application_assessment|' || x.application_id::text,
      x.source_payload_hash
    from (
      select aa.id, aa.application_id, aa.status, aa.summary, aa.confidence_score,
             aa.generated_at, aa.created_at, aa.source_payload_hash,
             (select l.holder_id from public.licenses l where l.application_id = aa.application_id
               order by l.created_at desc limit 1) as entity_id
      from public.application_ai_assessments aa
      where (_modules is null or 'licensing' = any(_modules))
        and public.can_read_application(auth.uid(), aa.application_id)
    ) x

    union all

    select
      r.id,
      'fpa'::text,
      'fit_proper'::text,
      'fp_ai_media_screening'::text,
      'Fit & Proper adverse-media screening analysis'::text,
      case when r.total_hits is not null and r.total_checks is not null
        then r.total_hits || ' potential adverse-media match(es) from ' || r.total_checks || ' check(s).'
        else null end,
      fa.licensee_id,
      coalesce(r.assessment_id, r.individual_id),
      null::text,
      coalesce(r.completed_at, r.started_at),
      r.triggered_by,
      null::text,
      case
        when lower(coalesce(r.status,'')) in ('completed','success') then 'available'
        when lower(coalesce(r.status,'')) in ('pending', 'running', 'processing') then 'processing'
        else 'failed' end,
      false,
      false,
      null::text,
      null::text,
      'fit_proper|fp_ai_media_screening|' || coalesce(r.assessment_id, r.individual_id)::text,
      null::text
    from public.fp_screening_runs r
    left join public.fp_assessments fa on fa.id = r.assessment_id
    where r.run_type = 'ai_media'
      and (_modules is null or 'fit_proper' = any(_modules))
      and (
        public.can_read_fp_assessment(auth.uid(), r.assessment_id)
        or public.can_read_fp_individual(auth.uid(), r.individual_id)
      )
  ),
  resolved as (
    select
      b.*,
      coalesce(
        (select l.name from public.licensees l where l.id = b.entity_id),
        case when b.source = 'application_assessment' then (
          select coalesce(a.data->>'organization_name', a.data->>'entity_name',
                          a.data->>'company_name', a.data->>'applicant_name')
          from public.applications a where a.id = b.record_id
        ) end
      ) as entity_name,
      case b.module
        when 'examination' then (select e.reference from public.examinations e where e.id = b.record_id)
        when 'complaints' then (select c.complaint_number from public.complaints c where c.id = b.record_id)
        when 'enforcement' then (select nullif(btrim(a.case_number),'') from public.enforcement_actions a where a.id = b.record_id)
        when 'licensing' then (select a.application_number from public.applications a where a.id = b.record_id)
        when 'fit_proper' then (
          select fi.full_name from public.fp_individuals fi
          where fi.id = coalesce(
            (select fa2.individual_id from public.fp_assessments fa2 where fa2.id = b.record_id),
            b.record_id)
        )
        else null
      end as record_reference,
      case b.module
        when 'examination' then (select e.title from public.examinations e where e.id = b.record_id)
        when 'complaints' then (select c.subject from public.complaints c where c.id = b.record_id)
        else null
      end as subject_name,
      case b.module
        when 'examination' then (select e.entity_id from public.examinations e where e.id = b.record_id)
        when 'complaints' then (select c.licensee_id from public.complaints c where c.id = b.record_id)
        when 'enforcement' then (select a.entity_id from public.enforcement_actions a where a.id = b.record_id)
        else null
      end as resolved_entity_id
    from raw b
  ),
  shaped as (
    select
      r.id, r.source, r.module, r.analysis_type, r.title, r.summary,
      coalesce(r.resolved_entity_id, r.entity_id) as entity_id,
      coalesce(
        (select l.name from public.licensees l where l.id = coalesce(r.resolved_entity_id, r.entity_id)),
        r.entity_name
      ) as entity_name,
      r.record_id, r.record_reference, r.subject_name, r.period_key,
      r.generated_at, r.generated_by, r.confidence, r.report_state,
      case
        when r.generated_at is null then 'unknown'
        when r.source = 'fpa' then 'unknown'
        else case
          when public.supervisory_ai_source_updated_at(
                 r.module, r.record_id, coalesce(r.resolved_entity_id, r.entity_id)) is null then 'unknown'
          when public.supervisory_ai_source_updated_at(
                 r.module, r.record_id, coalesce(r.resolved_entity_id, r.entity_id)) > r.generated_at
            then 'outdated'
          else 'current'
        end
      end as freshness,
      r.limited_evidence, r.flagged, r.feedback, r.review_status, r.version_key
    from resolved r
  ),
  filtered as (
    select s.*
    from shaped s
    where (_analysis_types is null or s.analysis_type = any(_analysis_types))
      and (_entity_id is null or s.entity_id = _entity_id)
      and (_from is null or s.generated_at >= _from)
      and (_to is null or s.generated_at < _to)
      and (_include_failed or s.report_state in ('available', 'limited'))
      and (_confidence is null or s.confidence = _confidence)
      and (_freshness is null or s.freshness = _freshness)
      and (
        _search is null or length(btrim(_search)) = 0
        or concat_ws(' ', s.title, s.analysis_type, s.summary, s.entity_name,
                     s.record_reference, s.subject_name)
           ilike '%' || btrim(_search) || '%'
      )
  ),
  totals as (
    select
      count(*) as total_count,
      count(*) filter (where generated_at >= now() - interval '7 days') as recent_7d,
      count(*) filter (where freshness = 'outdated') as outdated_count,
      count(*) filter (where limited_evidence) as limited_count,
      coalesce(jsonb_object_agg(module, n) filter (where module is not null), '{}'::jsonb) as module_counts
    from (
      select generated_at, freshness, limited_evidence, module,
             count(*) over (partition by module) as n
      from filtered
    ) z
  )
  select
    f.id, f.source, f.module, f.analysis_type, f.title, f.summary,
    f.entity_id, f.entity_name, f.record_id, f.record_reference, f.subject_name,
    f.period_key, f.generated_at, f.generated_by, f.confidence, f.report_state,
    f.freshness, f.limited_evidence, f.flagged, f.feedback, f.review_status, f.version_key,
    t.total_count, t.recent_7d, t.outdated_count, t.limited_count, t.module_counts
  from filtered f cross join totals t
  order by f.generated_at desc nulls last, f.id
  limit greatest(coalesce(_limit, 25), 1)
  offset greatest(coalesce(_offset, 0), 0);
$function$
;
CREATE OR REPLACE FUNCTION public.supervisory_ai_reports_list(_modules text[] DEFAULT NULL::text[], _analysis_types text[] DEFAULT NULL::text[], _entity_id uuid DEFAULT NULL::uuid, _from timestamp with time zone DEFAULT NULL::timestamp with time zone, _to timestamp with time zone DEFAULT NULL::timestamp with time zone, _search text DEFAULT NULL::text, _include_failed boolean DEFAULT false, _limit integer DEFAULT 25, _offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, module text, analysis_type text, title text, scope text, scope_id uuid, entity_id uuid, object_type text, object_id uuid, source_modules text[], period_key text, provider_state text, model text, input_fingerprint text, feedback text, generated_at timestamp with time zone, generated_by uuid, summary text, confidence text, limitation_count integer, insufficient_evidence boolean, total_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with visible as (
    select i.*
    from public.ai_insights i
    where public.can_view_advisory_ai(i.module, i.source_modules)
      and (_modules is null or i.module = any(_modules))
      and (_analysis_types is null or i.analysis_type = any(_analysis_types))
      and (
        _entity_id is null
        or i.entity_id = _entity_id
        or i.scope_id = _entity_id
        or i.object_id = _entity_id
      )
      and (_from is null or i.generated_at >= _from)
      and (_to is null or i.generated_at <= _to)
      and (
        _include_failed
        or coalesce(i.provider_state, 'live') in ('live', 'success', 'INSUFFICIENT_DATA')
      )
      and (
        _search is null
        or length(btrim(_search)) = 0
        or i.title ilike '%' || btrim(_search) || '%'
        or i.analysis_type ilike '%' || btrim(_search) || '%'
        or coalesce(i.payload->>'summary', '') ilike '%' || btrim(_search) || '%'
      )
  )
  select
    v.id,
    v.module,
    v.analysis_type,
    v.title,
    v.scope,
    v.scope_id,
    v.entity_id,
    v.object_type,
    v.object_id,
    v.source_modules,
    v.period_key,
    v.provider_state,
    v.model,
    v.input_fingerprint,
    v.feedback,
    v.generated_at,
    v.generated_by,
    nullif(btrim(coalesce(v.payload->>'summary', coalesce(v.explanation, ''))), '') as summary,
    v.payload->>'confidence' as confidence,
    coalesce(jsonb_array_length(case when jsonb_typeof(v.payload->'limitations') = 'array'
      then v.payload->'limitations' else '[]'::jsonb end), 0) as limitation_count,
    coalesce((v.payload->>'insufficient_evidence')::boolean, false) as insufficient_evidence,
    count(*) over () as total_count
  from visible v
  order by v.generated_at desc nulls last
  limit greatest(coalesce(_limit, 25), 1)
  offset greatest(coalesce(_offset, 0), 0);
$function$
;
CREATE OR REPLACE FUNCTION public.supervisory_ai_source_updated_at(_module text, _record_id uuid, _entity_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case _module
    when 'examination' then greatest(
      (select e.updated_at from public.examinations e where e.id = _record_id),
      (select max(w.updated_at) from public.examination_workpapers w where w.examination_id = _record_id),
      (select max(f.updated_at) from public.examination_findings f where f.examination_id = _record_id),
      (select max(s.updated_at) from public.examination_scoping s where s.examination_id = _record_id),
      (select max(d.updated_at) from public.examination_data_requests d where d.examination_id = _record_id)
    )
    when 'complaints' then greatest(
      (select c.updated_at from public.complaints c where c.id = _record_id),
      (select max(t.updated_at) from public.complaint_investigation_tasks t where t.complaint_id = _record_id),
      (select max(ev.created_at) from public.complaint_evidence ev where ev.complaint_id = _record_id),
      (select max(r.updated_at) from public.complaint_rfis r where r.complaint_id = _record_id),
      (select max(k.created_at) from public.complaint_correspondence k where k.complaint_id = _record_id),
      (select max(q.created_at) from public.complaint_closure_reviews q where q.complaint_id = _record_id)
    )
    when 'enforcement' then greatest(
      (select a.updated_at from public.enforcement_actions a where a.id = _record_id),
      (select max(ev.created_at) from public.enforcement_case_events ev where ev.case_id = _record_id),
      (select max(o.updated_at) from public.enforcement_obligations o where o.case_id = _record_id),
      (select max(ce.created_at) from public.enforcement_compliance_evidence ce where ce.case_id = _record_id)
    )
    when 'licensing' then (select a.updated_at from public.applications a where a.id = _record_id)
    when 'prudential' then greatest(
      (select l.updated_at from public.licensees l where l.id = coalesce(_entity_id, _record_id)),
      (select max(rs.updated_at) from public.entity_risk_scores rs where rs.entity_id = coalesce(_entity_id, _record_id))
    )
    when 'conduct' then greatest(
      (select l.updated_at from public.licensees l where l.id = coalesce(_entity_id, _record_id)),
      (select max(c.updated_at) from public.complaints c where c.licensee_id = coalesce(_entity_id, _record_id))
    )
    when 'cross_module' then greatest(
      (select l.updated_at from public.licensees l where l.id = coalesce(_entity_id, _record_id)),
      (select max(rs.updated_at) from public.entity_risk_scores rs where rs.entity_id = coalesce(_entity_id, _record_id)),
      (select max(c.updated_at) from public.complaints c where c.licensee_id = coalesce(_entity_id, _record_id)),
      (select max(a.updated_at) from public.enforcement_actions a where a.entity_id = coalesce(_entity_id, _record_id)),
      (select max(e.updated_at) from public.examinations e where e.entity_id = coalesce(_entity_id, _record_id))
    )
    else null
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.supervisory_breach_issue_enforcement(_entity_id uuid, _breach_ids uuid[], _enforcement_type text, _rationale text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _case_id uuid; _summary text;
BEGIN
  PERFORM public.enforce_permission('prudential_supervision','initiate_supervisory_action');
  PERFORM public.enforce_permission('enforcement_management','create');
  IF _rationale IS NULL OR length(btrim(_rationale)) < 10 THEN
    RAISE EXCEPTION 'rationale must be at least 10 characters' USING ERRCODE='22023';
  END IF;
  IF _breach_ids IS NULL OR array_length(_breach_ids,1) IS NULL THEN
    RAISE EXCEPTION 'at least one breach must be cited' USING ERRCODE='22023';
  END IF;
  SELECT string_agg(metric_key || ' ' || COALESCE(comparator,'') || ' ' ||
                    COALESCE(threshold_value::text,'') || ' (actual ' || COALESCE(value::text,'n/a') || ')', '; ')
    INTO _summary
    FROM public.return_threshold_breaches WHERE id = ANY(_breach_ids);
  IF _summary IS NULL THEN RAISE EXCEPTION 'cited breaches not found' USING ERRCODE='22023'; END IF;
  INSERT INTO public.enforcement_actions (entity_id, enforcement_type, description, findings,
    opened_by, source_type, source_reference_id, status)
  VALUES (_entity_id, COALESCE(NULLIF(_enforcement_type,''),'warning'), btrim(_rationale),
          _summary, _uid, 'return_threshold_breach', _breach_ids[1], 'open')
  RETURNING id INTO _case_id;
  INSERT INTO public.enforcement_case_events (case_id, event_type, actor_id, note, detail)
  VALUES (_case_id,'opened_from_threshold_breach',_uid,btrim(_rationale),
          jsonb_build_object('breach_ids',to_jsonb(_breach_ids)));
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'supervision.breach.enforcement_issued','enforcement_action',_case_id,
          jsonb_build_object('entity_id',_entity_id,'breach_ids',to_jsonb(_breach_ids),
                             'justification',btrim(_rationale)));
  RETURN jsonb_build_object('enforcement_case_id',_case_id);
END; $function$
;
CREATE OR REPLACE FUNCTION public.supervisory_plan_action_create(_plan_id uuid, _title text, _description text DEFAULT NULL::text, _owner_role text DEFAULT NULL::text, _due_date date DEFAULT NULL::date, _source text DEFAULT 'manual'::text)
 RETURNS supervisory_plan_actions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_entity uuid; v_row public.supervisory_plan_actions;
BEGIN
  SELECT entity_id INTO v_entity FROM public.supervisory_plans WHERE id = _plan_id;
  IF v_entity IS NULL THEN RAISE EXCEPTION 'supervisory plan % not found', _plan_id USING ERRCODE='P0002'; END IF;
  PERFORM public.prudential_enforce('edit', v_entity);
  IF _title IS NULL OR btrim(_title) = '' THEN RAISE EXCEPTION 'activity title is required' USING ERRCODE='22023'; END IF;
  INSERT INTO public.supervisory_plan_actions(plan_id, title, description, owner_role, due_date, status, source)
  VALUES (_plan_id, _title, _description, _owner_role, _due_date, 'planned', COALESCE(_source,'manual'))
  RETURNING * INTO v_row;
  PERFORM public.prudential_audit_event('supervisory_plan_action_created','supervisory_plan_action',v_row.id,
    NULL, to_jsonb(v_row), jsonb_build_object('plan_id',_plan_id,'entity_id',v_entity), _description, 'CREATE');
  RETURN v_row;
END; $function$
;
CREATE OR REPLACE FUNCTION public.supervisory_plan_action_transition(_action_id uuid, _to_status text, _reason text DEFAULT NULL::text, _owner_role text DEFAULT NULL::text, _due_date date DEFAULT NULL::date)
 RETURNS supervisory_plan_actions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.supervisory_plan_actions; v_after public.supervisory_plan_actions; v_entity uuid; v_uid uuid := auth.uid();
BEGIN
  SELECT * INTO v_before FROM public.supervisory_plan_actions WHERE id = _action_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan activity % not found', _action_id USING ERRCODE='P0002'; END IF;
  SELECT entity_id INTO v_entity FROM public.supervisory_plans WHERE id = v_before.plan_id;
  IF _to_status IN ('completed','cancelled') THEN
    PERFORM public.prudential_enforce('manage_remediation', v_entity);
  ELSE
    PERFORM public.prudential_enforce('edit', v_entity);
  END IF;
  IF _to_status NOT IN ('planned','in_progress','completed','cancelled','rescheduled','reassigned') THEN
    RAISE EXCEPTION 'unsupported plan activity status %', _to_status USING ERRCODE='22023'; END IF;
  IF v_before.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'plan activity % is already %', _action_id, v_before.status USING ERRCODE='55000'; END IF;
  IF _to_status IN ('completed','cancelled','rescheduled','reassigned') THEN
    PERFORM public.prudential_require_rationale(_reason, 5, 'reason');
  END IF;

  UPDATE public.supervisory_plan_actions s
  SET status = CASE WHEN _to_status IN ('rescheduled','reassigned') THEN s.status ELSE _to_status END,
      owner_role = CASE WHEN _to_status='reassigned' THEN COALESCE(_owner_role, s.owner_role) ELSE s.owner_role END,
      reassigned_from = CASE WHEN _to_status='reassigned' THEN s.owner_role ELSE s.reassigned_from END,
      reassigned_at = CASE WHEN _to_status='reassigned' THEN now() ELSE s.reassigned_at END,
      reassigned_by = CASE WHEN _to_status='reassigned' THEN v_uid ELSE s.reassigned_by END,
      previous_due_date = CASE WHEN _to_status='rescheduled' THEN s.due_date ELSE s.previous_due_date END,
      due_date = CASE WHEN _to_status='rescheduled' THEN COALESCE(_due_date, s.due_date) ELSE s.due_date END,
      extension_reason = CASE WHEN _to_status='rescheduled' THEN _reason ELSE s.extension_reason END,
      description = CASE WHEN _to_status='completed' THEN COALESCE(s.description,'') || CASE WHEN _reason IS NULL THEN '' ELSE E'\n[outcome] ' || _reason END ELSE s.description END,
      completed_at = CASE WHEN _to_status='completed' THEN now() ELSE s.completed_at END,
      completed_by = CASE WHEN _to_status='completed' THEN v_uid ELSE s.completed_by END,
      updated_at = now()
  WHERE s.id = _action_id
  RETURNING * INTO v_after;

  PERFORM public.prudential_audit_event('supervisory_plan_action_'||_to_status,'supervisory_plan_action',_action_id,
    to_jsonb(v_before), to_jsonb(v_after),
    jsonb_build_object('plan_id',v_before.plan_id,'entity_id',v_entity,'from_status',v_before.status,'to_status',_to_status),
    _reason, 'WORKFLOW_TRANSITION');
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.supervisory_plan_create(_entity_id uuid, _license_id uuid DEFAULT NULL::uuid, _risk_rating_id uuid DEFAULT NULL::uuid, _created_from text DEFAULT 'manual'::text, _notes text DEFAULT NULL::text)
 RETURNS supervisory_plans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.supervisory_plans;
BEGIN
  PERFORM public.prudential_enforce('edit', _entity_id);
  INSERT INTO public.supervisory_plans(entity_id, license_id, risk_rating_id, created_from, notes, status, approval_status, created_by)
  VALUES (_entity_id, _license_id, _risk_rating_id, COALESCE(_created_from,'manual'), _notes, 'draft', 'draft', auth.uid())
  RETURNING * INTO v_row;
  PERFORM public.prudential_audit_event('supervisory_plan_created','supervisory_plan',v_row.id,
    NULL, to_jsonb(v_row), jsonb_build_object('entity_id',_entity_id), _notes, 'CREATE');
  RETURN v_row;
END; $function$
;
CREATE OR REPLACE FUNCTION public.supervisory_plan_decision(_plan_id uuid, _decision text, _reason text DEFAULT NULL::text)
 RETURNS supervisory_plans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.supervisory_plans; v_after public.supervisory_plans; v_uid uuid := auth.uid();
BEGIN
  SELECT * INTO v_before FROM public.supervisory_plans WHERE id = _plan_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'supervisory plan % not found', _plan_id USING ERRCODE='P0002'; END IF;
  IF _decision NOT IN ('submit','approve','reject') THEN
    RAISE EXCEPTION 'unsupported plan decision %', _decision USING ERRCODE='22023'; END IF;

  IF _decision = 'submit' THEN
    PERFORM public.prudential_enforce('edit', v_before.entity_id);
    IF COALESCE(v_before.approval_status,'draft') NOT IN ('draft','rejected') THEN
      RAISE EXCEPTION 'plan already submitted (%)', v_before.approval_status USING ERRCODE='55000'; END IF;
  ELSE
    PERFORM public.prudential_enforce('workflow_action', v_before.entity_id);
    IF COALESCE(v_before.approval_status,'draft') <> 'pending_review' THEN
      RAISE EXCEPTION 'plan is not awaiting review (%)', v_before.approval_status USING ERRCODE='55000'; END IF;
    IF v_before.submitted_for_review_by IS NOT NULL AND v_before.submitted_for_review_by = v_uid THEN
      RAISE EXCEPTION 'the officer who submitted the plan cannot approve it' USING ERRCODE='42501'; END IF;
    PERFORM public.prudential_require_rationale(_reason, 10, 'decision rationale');
  END IF;

  UPDATE public.supervisory_plans p
  SET approval_status = CASE _decision WHEN 'submit' THEN 'pending_review' WHEN 'approve' THEN 'approved' ELSE 'rejected' END,
      status = CASE _decision WHEN 'approve' THEN 'active' ELSE p.status END,
      submitted_for_review_at = CASE WHEN _decision='submit' THEN now() ELSE p.submitted_for_review_at END,
      submitted_for_review_by = CASE WHEN _decision='submit' THEN v_uid ELSE p.submitted_for_review_by END,
      approved_at = CASE WHEN _decision='approve' THEN now() ELSE p.approved_at END,
      approved_by = CASE WHEN _decision='approve' THEN v_uid ELSE p.approved_by END,
      notes = COALESCE(_reason, p.notes),
      updated_at = now()
  WHERE p.id = _plan_id
  RETURNING * INTO v_after;

  PERFORM public.prudential_audit_event('supervisory_plan_'||_decision,'supervisory_plan',_plan_id,
    to_jsonb(v_before), to_jsonb(v_after), jsonb_build_object('entity_id',v_before.entity_id), _reason,
    CASE _decision WHEN 'approve' THEN 'APPROVE'::public.compliance_audit_action
                   WHEN 'reject' THEN 'REJECT'::public.compliance_audit_action
                   ELSE 'WORKFLOW_TRANSITION'::public.compliance_audit_action END);
  RETURN v_after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.sync_application_decision_rationale()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text := lower(trim(coalesce(NEW.action_type, NEW.action, '')));
BEGIN
  IF v_action IN (
    'approve', 'approved', 'conditional_approve', 'conditionally_approved',
    'reject', 'rejected', 'return', 'resubmission_requested', 'defer', 'deferred'
  ) AND nullif(trim(coalesce(NEW.comments, '')), '') IS NOT NULL THEN
    UPDATE public.applications
       SET decision_rationale = trim(NEW.comments),
           updated_at = greatest(coalesce(updated_at, NEW.created_at), NEW.created_at)
     WHERE id = NEW.application_id
       AND decision_rationale IS DISTINCT FROM trim(NEW.comments);
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.sync_user_roles_from_dynamic()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_sys_role text;
BEGIN
  v_user_id := COALESCE(NEW.user_id, OLD.user_id);

  FOR v_sys_role IN
    SELECT DISTINCT r.system_role
    FROM public.user_dynamic_roles udr
    JOIN public.roles r ON r.id = udr.role_id
    WHERE udr.user_id = v_user_id
      AND r.system_role IS NOT NULL
      AND btrim(r.system_role) <> ''
  LOOP
    BEGIN
      INSERT INTO public.user_roles (user_id, role)
      VALUES (v_user_id, v_sys_role::public.app_role)
      ON CONFLICT (user_id, role) DO NOTHING;
    EXCEPTION WHEN invalid_text_representation THEN
      NULL;
    END;
  END LOOP;

  RETURN COALESCE(NEW, OLD);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_aan_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END $function$
;
CREATE OR REPLACE FUNCTION public.tg_acknowledgement_identity_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ACKNOWLEDGEMENT_APPEND_ONLY: acknowledgements cannot be deleted'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW.application_id IS DISTINCT FROM OLD.application_id
     OR NEW.submission_version IS DISTINCT FROM OLD.submission_version
     OR NEW.reference IS DISTINCT FROM OLD.reference
     OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR (OLD.document_checksum IS NOT NULL AND NEW.document_checksum IS DISTINCT FROM OLD.document_checksum)
  THEN
    RAISE EXCEPTION 'ACKNOWLEDGEMENT_IMMUTABLE: identity/provenance columns cannot be changed'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_ai_insights_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.title <> OLD.title OR NEW.explanation IS DISTINCT FROM OLD.explanation
     OR NEW.recommendation IS DISTINCT FROM OLD.recommendation
     OR NEW.source_records::text <> OLD.source_records::text
     OR NEW.citations::text <> OLD.citations::text
     OR NEW.provider_state <> OLD.provider_state
     OR NEW.model IS DISTINCT FROM OLD.model
     OR NEW.confidence IS DISTINCT FROM OLD.confidence THEN
    RAISE EXCEPTION 'AI insight output is immutable; only review status may change' USING ERRCODE = '42501';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.tg_aia_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'AI insight actions are append-only' USING ERRCODE = '42501';
END $function$
