$function$
;
CREATE OR REPLACE FUNCTION public.tg_applications_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text;
  v_meta jsonb;
  v_actor uuid := auth.uid();
  v_email text;
  v_changed text[];
BEGIN
  SELECT email INTO v_email FROM public.profiles WHERE id = NEW.applicant_id LIMIT 1;
  IF v_email IS NULL THEN
    SELECT email INTO v_email FROM public.pre_license_users WHERE id = NEW.applicant_id LIMIT 1;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_meta := jsonb_build_object(
      'source','trigger',
      'application_id', NEW.id,
      'application_number', NEW.application_number,
      'applicant_id', NEW.applicant_id,
      'applicant_email', v_email,
      'license_type', NEW.license_type,
      'sector_id', NEW.data->>'sector_id',
      'sub_sector_id', NEW.data->>'sub_sector_id',
      'category_id', NEW.data->>'category_id',
      'to_status', NEW.status
    );

    PERFORM public.write_audit(
      'application.created',
      'application',
      NEW.id::text,
      COALESCE(v_actor, NEW.applicant_id),
      NULL,
      to_jsonb(NEW) - 'data' - 'search_vector',
      v_meta
    );

    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    v_action := CASE NEW.status
      WHEN 'submitted' THEN CASE WHEN OLD.status IN ('resubmission_requested','query_raised') THEN 'application.resubmitted' ELSE 'application.submitted' END
      WHEN 'cancelled' THEN 'application.cancelled'
      WHEN 'approved' THEN 'application.approved'
      WHEN 'rejected' THEN 'application.rejected'
      WHEN 'resubmission_requested' THEN 'application.resubmission_requested'
      ELSE 'application.status_changed'
    END;

    v_meta := jsonb_build_object(
      'source','trigger',
      'application_id', NEW.id,
      'application_number', NEW.application_number,
      'applicant_id', NEW.applicant_id,
      'applicant_email', v_email,
      'license_type', NEW.license_type,
      'from_status', OLD.status,
      'to_status', NEW.status
    );

    PERFORM public.write_audit(
      v_action,
      'application',
      NEW.id::text,
      COALESCE(v_actor, NEW.applicant_id),
      jsonb_build_object('status', OLD.status),
      jsonb_build_object('status', NEW.status),
      v_meta
    );

    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.status IS NOT DISTINCT FROM OLD.status
     AND COALESCE(NEW.status, '') IN (
       'draft', 'in_progress',
       'info_requested', 'resubmission_requested', 'resubmission_required',
       'query_raised', 'returned_for_correction'
     ) THEN
    v_changed := ARRAY[]::text[];

    IF NEW.license_type IS DISTINCT FROM OLD.license_type THEN
      v_changed := array_append(v_changed, 'license_type');
    END IF;
    IF NEW.regulator_id IS DISTINCT FROM OLD.regulator_id THEN
      v_changed := array_append(v_changed, 'regulator_id');
    END IF;
    IF NEW.data IS DISTINCT FROM OLD.data THEN
      v_changed := array_append(v_changed, 'data');
    END IF;

    IF array_length(v_changed, 1) IS NULL THEN
      RETURN NEW;
    END IF;

    v_meta := jsonb_build_object(
      'source','trigger',
      'application_id', NEW.id,
      'application_number', NEW.application_number,
      'applicant_id', NEW.applicant_id,
      'applicant_email', v_email,
      'license_type', NEW.license_type,
      'from_status', OLD.status,
      'to_status', NEW.status,
      'changed_fields', to_jsonb(v_changed),
      'forms_data_changed', (NEW.data->'forms_data') IS DISTINCT FROM (OLD.data->'forms_data'),
      'sector_id', COALESCE(NEW.data->>'sector_id', OLD.data->>'sector_id'),
      'sub_sector_id', COALESCE(NEW.data->>'sub_sector_id', OLD.data->>'sub_sector_id'),
      'category_id', COALESCE(NEW.data->>'category_id', OLD.data->>'category_id')
    );

    PERFORM public.write_audit(
      CASE
        WHEN COALESCE(NEW.status, '') IN ('draft', 'in_progress') THEN 'application.draft_updated'
        ELSE 'application.form_data_updated'
      END,
      'application',
      NEW.id::text,
      COALESCE(v_actor, NEW.applicant_id),
      jsonb_build_object(
        'license_type', OLD.license_type,
        'regulator_id', OLD.regulator_id,
        'data', OLD.data
      ),
      jsonb_build_object(
        'license_type', NEW.license_type,
        'regulator_id', NEW.regulator_id,
        'data', NEW.data
      ),
      v_meta,
      30
    );
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_approval_actions_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text;
  v_app RECORD;
  v_instance RECORD;
  v_step_name text;
  v_assignee text;
  v_to_status text;
  v_meta jsonb;
BEGIN
  SELECT id, application_number, applicant_id, status
    INTO v_app
    FROM public.applications
   WHERE id = NEW.application_id
   LIMIT 1;

  SELECT workflow_id, current_step_id, status
    INTO v_instance
    FROM public.workflow_instances
   WHERE id = NEW.workflow_instance_id
   LIMIT 1;

  SELECT name INTO v_step_name
    FROM public.approval_steps
   WHERE id = NEW.step_id
   LIMIT 1;

  v_assignee := public.audit_step_assignee_label(NEW.step_id);
  v_to_status := CASE
    WHEN lower(coalesce(NEW.action, NEW.action_type, '')) = 'approve_final' THEN 'approved'
    WHEN lower(coalesce(NEW.action, NEW.action_type, '')) = 'reject' THEN 'rejected'
    WHEN lower(coalesce(NEW.action, NEW.action_type, '')) = 'request_resubmission' THEN 'resubmission_requested'
    ELSE v_app.status
  END;

  v_action := CASE lower(coalesce(NEW.action, NEW.action_type, ''))
    WHEN 'edit_requested' THEN 'application.edit_requested'
    WHEN 'edit_approved' THEN 'application.edit_approved'
    WHEN 'edit_denied' THEN 'application.edit_denied'
    WHEN 'resubmitted' THEN 'application.resubmitted'
    WHEN 'approve_final' THEN 'workflow.step_completed'
    ELSE 'workflow.action_taken'
  END;

  v_meta := jsonb_build_object(
    'source', 'trigger',
    'application_id', NEW.application_id,
    'application_number', v_app.application_number,
    'workflow_id', v_instance.workflow_id,
    'workflow_instance_id', NEW.workflow_instance_id,
    'step_id', NEW.step_id,
    'step_name', v_step_name,
    'action', NEW.action,
    'action_type', NEW.action_type,
    'actor_id', NEW.actor_id,
    'comments', NEW.comments,
    'from_assignee', NEW.delegated_from,
    'to_assignee', COALESCE(NEW.delegated_to::text, v_assignee),
    'from_status', NULL,
    'to_status', v_to_status,
    'delegated_to', NEW.delegated_to,
    'delegated_from', NEW.delegated_from
  );

  PERFORM public.write_audit(
    v_action,
    'application',
    NEW.application_id::text,
    COALESCE(NEW.actor_id, auth.uid(), v_app.applicant_id),
    NULL,
    to_jsonb(NEW),
    v_meta
  );

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_auto_compliance_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action compliance_audit_action;
  v_before jsonb;
  v_after jsonb;
  v_object_id text;
  v_user uuid := auth.uid();
  v_role text := public.resolve_actor_role(auth.uid());
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'CREATE'::compliance_audit_action;
    v_before := NULL;
    v_after := to_jsonb(NEW);
    v_object_id := COALESCE((to_jsonb(NEW)->>'id'), (to_jsonb(NEW)->>'entry_id'));
  ELSIF TG_OP = 'UPDATE' THEN
    -- Map status transitions to APPROVE/REJECT/WORKFLOW_TRANSITION when possible
    v_before := to_jsonb(OLD);
    v_after := to_jsonb(NEW);
    v_object_id := COALESCE((to_jsonb(NEW)->>'id'), (to_jsonb(NEW)->>'entry_id'));
    IF v_after ? 'status' AND v_before->>'status' IS DISTINCT FROM v_after->>'status' THEN
      IF v_after->>'status' ILIKE '%approved%' THEN v_action := 'APPROVE';
      ELSIF v_after->>'status' ILIKE '%reject%' OR v_after->>'status' ILIKE '%denied%' THEN v_action := 'REJECT';
      ELSE v_action := 'WORKFLOW_TRANSITION';
      END IF;
    ELSE
      v_action := 'UPDATE';
    END IF;
  ELSE -- DELETE
    v_action := 'DELETE'::compliance_audit_action;
    v_before := to_jsonb(OLD);
    v_after := NULL;
    v_object_id := COALESCE((to_jsonb(OLD)->>'id'), (to_jsonb(OLD)->>'entry_id'));
  END IF;

  BEGIN
    INSERT INTO public.compliance_audit_logs (
      timestamp, user_id, user_role, action_type, object_type, object_id,
      before_value, after_value, metadata, created_at
    ) VALUES (
      now(), v_user, v_role, v_action, TG_TABLE_NAME, v_object_id,
      v_before, v_after,
      jsonb_build_object('source','trigger','schema',TG_TABLE_SCHEMA,'op',TG_OP),
      now()
    );
  EXCEPTION WHEN OTHERS THEN
    -- Never fail the underlying transaction due to audit issues
    RAISE WARNING 'auto audit failed for %.%: %', TG_TABLE_SCHEMA, TG_TABLE_NAME, SQLERRM;
  END;

  RETURN COALESCE(NEW, OLD);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_cal_block_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'compliance_audit_logs entries are immutable';
