CREATE OR REPLACE FUNCTION public.tg_documents_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.write_audit(
      'document.uploaded',
      'document',
      NEW.id::text,
      COALESCE(v_actor, NEW.uploaded_by),
      NULL,
      to_jsonb(NEW),
      jsonb_build_object(
        'source','trigger',
        'document_id', NEW.id,
        'application_id', CASE WHEN NEW.entity_type = 'application' THEN NEW.entity_id::text END,
        'entity_type', NEW.entity_type,
        'entity_id', NEW.entity_id,
        'file_name', NEW.file_name,
        'file_size', NEW.file_size,
        'document_type', NEW.entity_type,
        'mime_type', NEW.mime_type
      )
    );
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.file_path IS DISTINCT FROM OLD.file_path
       OR NEW.file_name IS DISTINCT FROM OLD.file_name
       OR NEW.file_size IS DISTINCT FROM OLD.file_size THEN
      PERFORM public.write_audit(
        'document.replaced',
        'document',
        NEW.id::text,
        COALESCE(v_actor, NEW.uploaded_by),
        to_jsonb(OLD),
        to_jsonb(NEW),
        jsonb_build_object(
          'source','trigger',
          'document_id', NEW.id,
          'application_id', CASE WHEN NEW.entity_type = 'application' THEN NEW.entity_id::text END,
          'entity_type', NEW.entity_type,
          'entity_id', NEW.entity_id,
          'old_file_name', OLD.file_name,
          'new_file_name', NEW.file_name,
          'old_file_size', OLD.file_size,
          'new_file_size', NEW.file_size,
          'document_type', NEW.entity_type
        )
      );
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM public.write_audit(
      'document.deleted',
      'document',
      OLD.id::text,
      COALESCE(v_actor, OLD.uploaded_by),
      to_jsonb(OLD),
      NULL,
      jsonb_build_object(
        'source','trigger',
        'document_id', OLD.id,
        'application_id', CASE WHEN OLD.entity_type = 'application' THEN OLD.entity_id::text END,
        'entity_type', OLD.entity_type,
        'entity_id', OLD.entity_id,
        'file_name', OLD.file_name,
        'document_type', OLD.entity_type
      )
    );
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_enforcement_referral_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.source_kind IS NULL THEN
    NEW.source_kind := CASE
      WHEN NEW.source_type IS NULL THEN 'MANUAL_REFERRAL'
      WHEN lower(NEW.source_type) LIKE '%complaint%' THEN 'COMPLAINT'
      WHEN lower(NEW.source_type) LIKE '%conduct%' THEN 'CONDUCT_INVESTIGATION'
      WHEN lower(NEW.source_type) LIKE '%thematic%' THEN 'THEMATIC_FINDING'
      WHEN lower(NEW.source_type) LIKE '%breach%' THEN 'PRUDENTIAL_BREACH'
      WHEN lower(NEW.source_type) LIKE '%prudential%' THEN 'PRUDENTIAL_ACTION'
      WHEN lower(NEW.source_type) LIKE '%inspection%' THEN 'EXAMINATION_FINDING'
      WHEN lower(NEW.source_type) LIKE '%exam%' THEN 'EXAMINATION_FINDING'
      WHEN lower(NEW.source_type) LIKE '%licen%' THEN 'LICENSING_VIOLATION'
      WHEN lower(NEW.source_type) LIKE '%fit%' OR lower(NEW.source_type) LIKE '%fp%' THEN 'FP_MATTER'
      ELSE 'MANUAL_REFERRAL' END;
  END IF;

  NEW.source_id := coalesce(NEW.source_id, NEW.source_reference_id, NEW.source_investigation_id);
  NEW.referred_by := coalesce(NEW.referred_by, NEW.opened_by, auth.uid());
  NEW.referred_at := coalesce(NEW.referred_at, now());
  NEW.referral_reason := coalesce(
    NEW.referral_reason,
    nullif(btrim(coalesce(NEW.description, '')), ''),
    'Referred into the enforcement process.');

  IF NEW.stage IS NULL OR NEW.stage = '' THEN NEW.stage := 'REFERRAL'; END IF;

  IF nullif(btrim(coalesce(NEW.case_number, '')), '') IS NULL THEN
    NEW.case_number := 'ENF-' || to_char(now(), 'YYYY') || '-' || lpad((
      SELECT count(*) + 1 FROM public.enforcement_actions
       WHERE date_trunc('year', created_at) = date_trunc('year', now()))::text, 5, '0');
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_escalation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IN ('resolved','closed') THEN
    IF coalesce(length(btrim(NEW.resolution_narrative)), 0) < 50 THEN
      RAISE EXCEPTION 'resolution_narrative_too_short: at least 50 characters are required';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- immutable identity / source linkage
    IF NEW.escalation_ref <> OLD.escalation_ref
       OR NEW.source_module <> OLD.source_module
       OR NEW.source_event <> OLD.source_event
       OR coalesce(NEW.source_entity_id, '00000000-0000-0000-0000-000000000000') <> coalesce(OLD.source_entity_id, '00000000-0000-0000-0000-000000000000')
       OR NEW.created_at <> OLD.created_at THEN
      RAISE EXCEPTION 'escalation_identity_immutable';
    END IF;
    -- tier may never move backwards
    IF NEW.current_tier < OLD.current_tier THEN
      RAISE EXCEPTION 'escalation_tier_cannot_regress';
    END IF;
    -- resolved/closed records are terminal
    IF OLD.status IN ('resolved','closed') AND NEW.status NOT IN ('resolved','closed') THEN
      RAISE EXCEPTION 'escalation_is_terminal';
    END IF;
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$function$
;
