CREATE OR REPLACE FUNCTION public.tg_pacr_finalised_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_status text;
BEGIN
  SELECT status INTO v_status FROM public.prudential_assessments
   WHERE id = COALESCE(NEW.assessment_id, OLD.assessment_id);
  IF v_status IN ('approved','closed') THEN
    RAISE EXCEPTION 'component ratings of a finalised assessment are immutable';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $function$
;
CREATE OR REPLACE FUNCTION public.tg_pacr_override_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.auto_suggested_rating IS NOT NULL
     AND NEW.rating IS NOT NULL
     AND NEW.rating <> NEW.auto_suggested_rating
     AND COALESCE(btrim(NEW.override_justification), '') = '' THEN
    RAISE EXCEPTION 'override of suggested rating % for component % requires a justification',
      NEW.auto_suggested_rating, NEW.component_code
      USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.auto_suggested_rating IS NOT NULL
     AND NEW.auto_suggested_rating IS DISTINCT FROM OLD.auto_suggested_rating THEN
    RAISE EXCEPTION 'the original system suggestion for component % cannot be altered', OLD.component_code
      USING ERRCODE = 'check_violation';
  END IF;

  NEW.updated_by := COALESCE(auth.uid(), NEW.updated_by);
  NEW.updated_at := now();
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.tg_payment_receipts_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app_id uuid;
  v_app_number text;
  v_actor uuid := auth.uid();
BEGIN
  SELECT p.application_id, a.application_number
    INTO v_app_id, v_app_number
    FROM public.payments p
    LEFT JOIN public.applications a ON a.id = p.application_id
   WHERE p.id = NEW.payment_id
   LIMIT 1;

  PERFORM public.write_audit(
    'payment.receipt_generated',
    'payment',
    NEW.payment_id::text,
    v_actor,
    NULL,
    to_jsonb(NEW),
    jsonb_build_object(
      'source', 'trigger',
      'receipt_id', NEW.id,
      'receipt_number', NEW.receipt_number,
      'payment_id', NEW.payment_id,
      'application_id', v_app_id,
      'application_number', v_app_number,
      'amount', NEW.amount,
      'currency', NEW.currency,
      'issued_to_email', NEW.issued_to_email,
      'issued_to_name', NEW.issued_to_name
    )
  );
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_payments_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_app_number text;
  v_meta jsonb;
  v_status_norm text;
BEGIN
  IF NEW.application_id IS NOT NULL THEN
    SELECT application_number INTO v_app_number
      FROM public.applications WHERE id = NEW.application_id LIMIT 1;
  END IF;
  v_status_norm := lower(coalesce(NEW.status,''));

  v_meta := jsonb_build_object(
    'source','trigger',
    'payment_id', NEW.id,
    'application_id', NEW.application_id,
    'application_number', v_app_number,
    'amount', NEW.amount,
    'currency', NEW.currency,
    'status', NEW.status,
    'transaction_ref', NEW.transaction_ref,
    'receipt_number', NEW.receipt_number,
    'user_id', NEW.user_id
  );

  IF TG_OP = 'INSERT' THEN
    PERFORM public.write_audit(
      'payment.initiated','payment', NEW.id::text,
      COALESCE(v_actor, NEW.user_id), NULL, to_jsonb(NEW), v_meta
    );
    IF v_status_norm IN ('completed','success','paid') THEN
      PERFORM public.write_audit(
        'payment.completed','payment', NEW.id::text,
        COALESCE(v_actor, NEW.user_id), NULL, to_jsonb(NEW), v_meta
      );
    ELSIF v_status_norm = 'failed' THEN
      PERFORM public.write_audit(
        'payment.failed','payment', NEW.id::text,
        COALESCE(v_actor, NEW.user_id), NULL, to_jsonb(NEW), v_meta
      );
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    IF v_status_norm IN ('completed','success','paid') THEN
      PERFORM public.write_audit(
        'payment.completed','payment', NEW.id::text,
        COALESCE(v_actor, NEW.user_id),
        jsonb_build_object('status', OLD.status),
        jsonb_build_object('status', NEW.status),
        v_meta
      );
    ELSIF v_status_norm = 'failed' THEN
      PERFORM public.write_audit(
        'payment.failed','payment', NEW.id::text,
        COALESCE(v_actor, NEW.user_id),
        jsonb_build_object('status', OLD.status),
        jsonb_build_object('status', NEW.status),
        v_meta
      );
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.receipt_number IS DISTINCT FROM OLD.receipt_number
     AND NEW.receipt_number IS NOT NULL THEN
    PERFORM public.write_audit(
      'payment.receipt_generated','payment', NEW.id::text,
      COALESCE(v_actor, NEW.user_id),
      jsonb_build_object('receipt_number', OLD.receipt_number),
      jsonb_build_object('receipt_number', NEW.receipt_number),
      v_meta
    );
  END IF;
  RETURN NEW;
END;
$function$
;
