CREATE OR REPLACE FUNCTION public.tg_prudential_action_log_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.prudential_action_events(action_id, event_type, from_status, to_status, actor_id, reason)
    VALUES (NEW.id, 'created', NULL, NEW.status, COALESCE(auth.uid(), NEW.created_by), NULL);
    RETURN NEW;
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.prudential_action_events(action_id, event_type, from_status, to_status, actor_id, reason)
    VALUES (NEW.id, 'status_changed', OLD.status, NEW.status, auth.uid(),
            COALESCE(NEW.completion_notes, NEW.waiver_reason, NEW.cancellation_reason, NEW.review_notes));
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.tg_prudential_assessment_finalise_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_gaps text[];
BEGIN
  IF NEW.status IN ('approved','closed') AND OLD.status NOT IN ('approved','closed') THEN
    v_gaps := public.prudential_assessment_finalisation_gaps(NEW.id);
    IF array_length(v_gaps, 1) > 0 THEN
      RAISE EXCEPTION 'assessment % cannot be finalised: unrated components %',
        NEW.id, array_to_string(v_gaps, ',')
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.tg_prudential_assessment_finalised_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status IN ('approved','closed') THEN
      RAISE EXCEPTION 'finalised prudential assessment % cannot be deleted', OLD.id;
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.status IN ('approved','closed') THEN
    RAISE EXCEPTION 'finalised prudential assessment % is immutable', OLD.id;
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.tg_prudential_detect_on_acceptance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'ACCEPTED' AND COALESCE(OLD.status, '') <> 'ACCEPTED' THEN
    BEGIN
      PERFORM public._prudential_canonical_detect_run(NEW.id, 'filing_accepted', auth.uid());
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO public.prudential_detection_runs
        (entity_id, return_filing_version_id, status, trigger_kind, error_detail, completed_at)
      SELECT rf.entity_id, NEW.id, 'FAILED', 'filing_accepted', SQLERRM, now()
        FROM public.return_filings rf WHERE rf.id = NEW.return_filing_id;
    END;
  END IF;
  RETURN NEW;
END $function$
;
