CREATE OR REPLACE FUNCTION public.tg_validate_escalation_rule()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(btrim(NEW.initial_recipient_role), '') = '' THEN
    RAISE EXCEPTION 'escalation_rule_invalid: initial recipient role is required';
  END IF;

  -- thresholds must be positive when present
  IF NEW.tier1_ack_threshold_minutes IS NOT NULL AND NEW.tier1_ack_threshold_minutes <= 0
     OR NEW.tier2_ack_threshold_minutes IS NOT NULL AND NEW.tier2_ack_threshold_minutes <= 0
     OR NEW.tier3_ack_threshold_minutes IS NOT NULL AND NEW.tier3_ack_threshold_minutes <= 0
     OR NEW.resolution_threshold_minutes IS NOT NULL AND NEW.resolution_threshold_minutes <= 0 THEN
    RAISE EXCEPTION 'escalation_rule_invalid: thresholds must be positive';
  END IF;

  -- a configured tier (threshold OR recipient) must have both
  IF (NEW.tier1_recipient_role IS NOT NULL) <> (NEW.tier1_ack_threshold_minutes IS NOT NULL) THEN
    RAISE EXCEPTION 'escalation_rule_invalid: tier 1 requires both a recipient role and an acknowledgement threshold';
  END IF;
  IF (NEW.tier2_recipient_role IS NOT NULL) <> (NEW.tier2_ack_threshold_minutes IS NOT NULL) THEN
    RAISE EXCEPTION 'escalation_rule_invalid: tier 2 requires both a recipient role and an acknowledgement threshold';
  END IF;
  IF (NEW.tier3_recipient_role IS NOT NULL) <> (NEW.tier3_ack_threshold_minutes IS NOT NULL) THEN
    RAISE EXCEPTION 'escalation_rule_invalid: tier 3 requires both a recipient role and an acknowledgement threshold';
  END IF;

  -- contiguity: cannot configure tier N without tier N-1
  IF NEW.tier2_recipient_role IS NOT NULL AND NEW.tier1_recipient_role IS NULL THEN
    RAISE EXCEPTION 'escalation_rule_invalid: tier 2 configured without tier 1';
  END IF;
  IF NEW.tier3_recipient_role IS NOT NULL AND NEW.tier2_recipient_role IS NULL THEN
    RAISE EXCEPTION 'escalation_rule_invalid: tier 3 configured without tier 2';
  END IF;

  IF NEW.business_hours_only AND NEW.business_calendar_profile_id IS NULL THEN
    SELECT id INTO NEW.business_calendar_profile_id
    FROM public.business_calendar_profiles WHERE is_default LIMIT 1;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_validate_working_days()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE d int;
BEGIN
  IF NEW.working_days IS NULL OR array_length(NEW.working_days,1) IS NULL THEN
    RAISE EXCEPTION 'working_days must contain at least one day (0=Sun..6=Sat)';
  END IF;
  IF array_length(NEW.working_days,1) > 7 THEN
    RAISE EXCEPTION 'working_days cannot exceed 7 entries';
  END IF;
  FOREACH d IN ARRAY NEW.working_days LOOP
    IF d < 0 OR d > 6 THEN
      RAISE EXCEPTION 'working_days entries must be between 0 (Sun) and 6 (Sat); got %', d;
    END IF;
  END LOOP;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.tg_workflow_instance_sla_stage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_process text;
BEGIN
  v_process := COALESCE(NEW.entity_type, 'application');

  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'active' THEN
      PERFORM public.sla_stage_open(v_process, NEW.entity_type, NEW.entity_id, NEW.id, NEW.current_step_id,
                                    NULL, COALESCE(NEW.started_at, NEW.created_at, now()));
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status IN ('completed','cancelled','rejected') AND OLD.status <> NEW.status THEN
    PERFORM public.sla_stage_complete(id, 'workflow_' || NEW.status)
      FROM public.sla_stage_instances
      WHERE workflow_instance_id = NEW.id AND state IN ('active','paused','breached');
    RETURN NEW;
  END IF;

  IF NEW.status = 'active' AND COALESCE(NEW.current_step_id::text,'') <> COALESCE(OLD.current_step_id::text,'') THEN
    PERFORM public.sla_stage_open(v_process, NEW.entity_type, NEW.entity_id, NEW.id, NEW.current_step_id, NULL, now());
  END IF;

  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.tg_workflow_instances_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app RECORD;
  v_old_step_name text;
  v_new_step_name text;
  v_old_assignee text;
  v_new_assignee text;
  v_actor uuid := auth.uid();
BEGIN
  IF COALESCE(CASE WHEN TG_OP = 'DELETE' THEN OLD.entity_type ELSE NEW.entity_type END, '') <> 'application' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT id, application_number, applicant_id, status
    INTO v_app
    FROM public.applications
   WHERE id = COALESCE(NEW.entity_id, OLD.entity_id)
   LIMIT 1;

  IF TG_OP <> 'INSERT' THEN
    SELECT name INTO v_old_step_name FROM public.approval_steps WHERE id = OLD.current_step_id LIMIT 1;
    v_old_assignee := public.audit_step_assignee_label(OLD.current_step_id);
  END IF;

  IF TG_OP <> 'DELETE' THEN
    SELECT name INTO v_new_step_name FROM public.approval_steps WHERE id = NEW.current_step_id LIMIT 1;
    v_new_assignee := public.audit_step_assignee_label(NEW.current_step_id);
  END IF;

  IF TG_OP = 'INSERT' THEN
    PERFORM public.write_audit(
      'workflow.assigned',
      'application',
      NEW.entity_id::text,
      COALESCE(v_actor, v_app.applicant_id),
      NULL,
      to_jsonb(NEW),
      jsonb_build_object(
        'source', 'trigger',
        'application_id', NEW.entity_id,
        'application_number', v_app.application_number,
        'workflow_id', NEW.workflow_id,
        'step_id', NEW.current_step_id,
        'step_name', v_new_step_name,
        'actor_id', v_actor,
        'from_assignee', NULL,
        'to_assignee', v_new_assignee,
        'from_status', NULL,
        'to_status', NEW.status
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.current_step_id IS DISTINCT FROM OLD.current_step_id THEN
      PERFORM public.write_audit(
        'workflow.step_completed',
        'application',
        NEW.entity_id::text,
        COALESCE(v_actor, v_app.applicant_id),
        jsonb_build_object('step_id', OLD.current_step_id, 'status', OLD.status),
        jsonb_build_object('step_id', NEW.current_step_id, 'status', NEW.status),
        jsonb_build_object(
          'source', 'trigger',
          'application_id', NEW.entity_id,
          'application_number', v_app.application_number,
          'workflow_id', NEW.workflow_id,
          'step_id', OLD.current_step_id,
          'step_name', v_old_step_name,
          'actor_id', v_actor,
          'from_assignee', v_old_assignee,
          'to_assignee', v_new_assignee,
          'from_status', OLD.status,
          'to_status', NEW.status
        )
      );

      PERFORM public.write_audit(
        'workflow.reassigned',
        'application',
        NEW.entity_id::text,
        COALESCE(v_actor, v_app.applicant_id),
        jsonb_build_object('step_id', OLD.current_step_id, 'status', OLD.status),
        jsonb_build_object('step_id', NEW.current_step_id, 'status', NEW.status),
        jsonb_build_object(
          'source', 'trigger',
          'application_id', NEW.entity_id,
          'application_number', v_app.application_number,
          'workflow_id', NEW.workflow_id,
          'step_id', NEW.current_step_id,
          'step_name', v_new_step_name,
          'actor_id', v_actor,
          'from_assignee', v_old_assignee,
          'to_assignee', v_new_assignee,
          'from_status', OLD.status,
          'to_status', NEW.status
        )
      );
      RETURN NEW;
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status
       AND NEW.status = 'active'
       AND OLD.status IN ('paused', 'pending') THEN
      PERFORM public.write_audit(
        'workflow.assigned',
        'application',
        NEW.entity_id::text,
        COALESCE(v_actor, v_app.applicant_id),
        jsonb_build_object('status', OLD.status),
        jsonb_build_object('status', NEW.status),
        jsonb_build_object(
          'source', 'trigger',
          'application_id', NEW.entity_id,
          'application_number', v_app.application_number,
          'workflow_id', NEW.workflow_id,
          'step_id', NEW.current_step_id,
          'step_name', v_new_step_name,
          'actor_id', v_actor,
          'from_assignee', v_old_assignee,
          'to_assignee', v_new_assignee,
          'from_status', OLD.status,
          'to_status', NEW.status
        )
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.thematic_action_extend_due_date(_action_id uuid, _new_due_date date, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before jsonb; v_rev uuid;
BEGIN
  IF _reason IS NULL OR length(btrim(_reason)) < 10 THEN
    RAISE EXCEPTION 'An extension justification of at least 10 characters is required' USING ERRCODE='22023'; END IF;
  IF _new_due_date IS NULL THEN
    RAISE EXCEPTION 'A new due date is required' USING ERRCODE='22023'; END IF;
  SELECT to_jsonb(a), a.review_id INTO v_before, v_rev
  FROM public.thematic_review_actions a WHERE a.id=_action_id;
  IF v_before IS NULL THEN RAISE EXCEPTION 'Action not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_manage_thematic_review(v_rev) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;

  UPDATE public.thematic_review_actions SET
    original_due_date = COALESCE(original_due_date, due_date),
    due_date = _new_due_date,
    extension_reason = btrim(_reason),
    extension_count = extension_count + 1,
    status = CASE WHEN status='overdue' AND _new_due_date >= current_date THEN 'open' ELSE status END
  WHERE id=_action_id;

  PERFORM public.log_compliance_audit('OVERRIDE','thematic_review_action', _action_id::text, v_before,
    (SELECT to_jsonb(a) FROM public.thematic_review_actions a WHERE a.id=_action_id),
    btrim(_reason), NULL, NULL, jsonb_build_object('module','market_conduct','event','due_date_extension'));
END $function$
;
CREATE OR REPLACE FUNCTION public.thematic_action_record_verification(_action_id uuid, _verification_status text, _notes text DEFAULT NULL::text, _evidence text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before jsonb; v_rev uuid;
BEGIN
  SELECT to_jsonb(a), a.review_id INTO v_before, v_rev
  FROM public.thematic_review_actions a WHERE a.id=_action_id;
  IF v_before IS NULL THEN RAISE EXCEPTION 'Action not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_manage_thematic_review(v_rev) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;
  IF _verification_status NOT IN ('pending','evidence_received','verified','not_satisfied') THEN
    RAISE EXCEPTION 'Invalid verification status' USING ERRCODE='22023'; END IF;
  IF _verification_status IN ('verified','not_satisfied')
     AND (_notes IS NULL OR length(btrim(_notes)) < 10) THEN
    RAISE EXCEPTION 'Verification notes of at least 10 characters are required' USING ERRCODE='22023'; END IF;
  IF _verification_status IN ('evidence_received','verified')
     AND COALESCE(NULLIF(btrim(COALESCE(_evidence,'')),''),
                  v_before->>'evidence_of_completion') IS NULL THEN
    RAISE EXCEPTION 'Evidence of completion is required' USING ERRCODE='22023'; END IF;

  UPDATE public.thematic_review_actions SET
    verification_status = _verification_status,
    verification_notes  = COALESCE(NULLIF(btrim(COALESCE(_notes,'')),''), verification_notes),
    evidence_of_completion = COALESCE(NULLIF(btrim(COALESCE(_evidence,'')),''), evidence_of_completion),
    verified_by = CASE WHEN _verification_status IN ('verified','not_satisfied') THEN auth.uid() ELSE verified_by END,
    verified_at = CASE WHEN _verification_status IN ('verified','not_satisfied') THEN now() ELSE verified_at END,
    status = CASE WHEN _verification_status='verified' THEN 'completed' ELSE status END,
    completed_at = CASE WHEN _verification_status='verified' THEN now() ELSE completed_at END
  WHERE id=_action_id;

  PERFORM public.log_compliance_audit('UPDATE','thematic_review_action', _action_id::text, v_before,
    (SELECT to_jsonb(a) FROM public.thematic_review_actions a WHERE a.id=_action_id),
    _notes, NULL, NULL, jsonb_build_object('module','market_conduct','event','verification'));
END $function$
;
CREATE OR REPLACE FUNCTION public.thematic_action_set_follow_up(_action_id uuid, _follow_up_due_date date DEFAULT NULL::date, _responsible_officer_id uuid DEFAULT NULL::uuid, _entity_contact text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before jsonb; v_rev uuid;
BEGIN
  SELECT to_jsonb(a), a.review_id INTO v_before, v_rev
  FROM public.thematic_review_actions a WHERE a.id=_action_id;
  IF v_before IS NULL THEN RAISE EXCEPTION 'Action not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_manage_thematic_review(v_rev) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;

  UPDATE public.thematic_review_actions SET
    follow_up_due_date = _follow_up_due_date,
    responsible_officer_id = _responsible_officer_id,
    entity_contact = NULLIF(btrim(COALESCE(_entity_contact,'')),'')
  WHERE id=_action_id;

  PERFORM public.log_compliance_audit('UPDATE','thematic_review_action', _action_id::text, v_before,
    (SELECT to_jsonb(a) FROM public.thematic_review_actions a WHERE a.id=_action_id),
    NULL, NULL, NULL, jsonb_build_object('module','market_conduct','event','follow_up_schedule'));
END $function$
;
CREATE OR REPLACE FUNCTION public.thematic_action_sync_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE tr_regulator uuid;
BEGIN
  IF TG_OP='INSERT' THEN
    INSERT INTO public.conduct_actions(
      source_module, source_id, entity_id, action_type, title, description,
      due_date, status, assigned_to, assigned_team, thematic_action_id,
      waiver_override_id, created_by
    ) VALUES (
      'thematic_review', NEW.review_id, NEW.licensee_id, NEW.action_type, NEW.title, NEW.description,
      NEW.due_date, NEW.status, NEW.assigned_to, NEW.assigned_team, NEW.id,
      NEW.waiver_override_id, NEW.created_by
    );
  ELSIF TG_OP='UPDATE' THEN
    UPDATE public.conduct_actions SET
      entity_id = NEW.licensee_id,
      action_type = NEW.action_type,
      title = NEW.title,
      description = NEW.description,
      due_date = NEW.due_date,
      status = NEW.status,
      assigned_to = NEW.assigned_to,
      assigned_team = NEW.assigned_team,
      waiver_override_id = NEW.waiver_override_id,
      closed_at = CASE WHEN NEW.status IN ('completed','waived') AND OLD.status NOT IN ('completed','waived') THEN now() ELSE closed_at END,
      updated_at = now()
    WHERE thematic_action_id = NEW.id;
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.thematic_report_approve(_report_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rev uuid; v_status text;
BEGIN
  SELECT review_id, status INTO v_rev, v_status FROM public.thematic_review_reports WHERE id=_report_id;
  IF v_rev IS NULL THEN RAISE EXCEPTION 'Report not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_approve_thematic_closure(v_rev) THEN
    RAISE EXCEPTION 'Not authorised to approve this report' USING ERRCODE='42501'; END IF;
  IF v_status <> 'in_review' THEN
    RAISE EXCEPTION 'Report is not awaiting approval' USING ERRCODE='22023'; END IF;

  UPDATE public.thematic_review_reports
     SET status='approved', approved_by=auth.uid(), approved_at=now()
   WHERE id=_report_id;

  PERFORM public.log_compliance_audit('APPROVE','thematic_review_report', _report_id::text,
    jsonb_build_object('status',v_status), jsonb_build_object('status','approved'),
    NULL, NULL, NULL, jsonb_build_object('module','market_conduct'));
END $function$
;
CREATE OR REPLACE FUNCTION public.thematic_report_publish(_report_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rev uuid; v_status text; v_review record; v_rep record; v_count integer := 0; r record;
BEGIN
  SELECT * INTO v_rep FROM public.thematic_review_reports WHERE id=_report_id;
  IF v_rep IS NULL THEN RAISE EXCEPTION 'Report not found' USING ERRCODE='P0002'; END IF;
  v_rev := v_rep.review_id; v_status := v_rep.status;
  IF NOT public.can_approve_thematic_closure(v_rev) THEN
    RAISE EXCEPTION 'Not authorised to publish this report' USING ERRCODE='42501'; END IF;
  IF v_status <> 'approved' THEN
    RAISE EXCEPTION 'Only an approved report can be published' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_review FROM public.thematic_reviews WHERE id=v_rev;

  UPDATE public.thematic_review_reports
     SET status='published', published_by=auth.uid(), published_at=now()
   WHERE id=_report_id;

  FOR r IN
    SELECT l.id AS licensee_id, l.name
    FROM public.thematic_review_entities e
    JOIN public.licensees l ON l.id = e.licensee_id
    WHERE e.review_id = v_rev
  LOOP
    INSERT INTO public.thematic_review_letters(
      review_id, report_id, licensee_id, recipient_name, subject, body, status, created_by)
    VALUES (
      v_rev, _report_id, r.licensee_id, r.name,
      concat('Supervisory letter — ', COALESCE(v_review.code,''), ' ', v_review.title),
      concat_ws(E'\n\n',
        'Dear '||r.name||',',
        'Following the conclusion of the thematic review "'||v_review.title||'"'||
          COALESCE(' ('||v_review.code||')','')||', we set out below the findings relevant to your institution and the actions required.',
        'Executive summary:'||E'\n'||COALESCE(v_rep.executive_summary,'See attached report.'),
        'Findings:'||E'\n'||COALESCE((
          SELECT string_agg('- ['||f.severity||'] '||f.title||COALESCE(': '||f.detail,''), E'\n' ORDER BY f.created_at)
          FROM public.thematic_review_findings f
          WHERE f.review_id=v_rev AND (f.licensee_id = r.licensee_id OR f.licensee_id IS NULL)
        ),'No entity-specific findings recorded.'),
        'Required actions:'||E'\n'||COALESCE((
          SELECT string_agg('- '||a.title||COALESCE(' (due '||a.due_date::text||')',''), E'\n' ORDER BY a.due_date NULLS LAST)
          FROM public.thematic_review_actions a
          WHERE a.review_id=v_rev AND (a.licensee_id = r.licensee_id OR a.licensee_id IS NULL)
            AND a.status <> 'cancelled'
        ),'No required actions.'),
        'Please respond with evidence of completion by the dates indicated.',
        'Yours faithfully,'||E'\n'||'Market Conduct Supervision'),
      'pending', auth.uid());
    v_count := v_count + 1;
  END LOOP;

  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION','thematic_review_report', _report_id::text,
    jsonb_build_object('status',v_status), jsonb_build_object('status','published'),
    NULL, NULL, NULL, jsonb_build_object('module','market_conduct','letters_staged',v_count));

  PERFORM public.notification_enqueue_event('thematic_review.report_published','thematic_review', v_rev,
    jsonb_build_object('review_title', v_review.title, 'review_code', COALESCE(v_review.code,''),
                       'report_version', v_rep.version, 'letters', v_count),
    _report_id::text, NULL, NULL);

  RETURN v_count;
END $function$
;
CREATE OR REPLACE FUNCTION public.thematic_report_reject(_report_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rev uuid; v_status text;
BEGIN
  IF _reason IS NULL OR length(btrim(_reason)) < 10 THEN
    RAISE EXCEPTION 'A rejection reason of at least 10 characters is required' USING ERRCODE='22023'; END IF;
  SELECT review_id, status INTO v_rev, v_status FROM public.thematic_review_reports WHERE id=_report_id;
  IF v_rev IS NULL THEN RAISE EXCEPTION 'Report not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_approve_thematic_closure(v_rev) THEN
    RAISE EXCEPTION 'Not authorised to reject this report' USING ERRCODE='42501'; END IF;
  IF v_status <> 'in_review' THEN
    RAISE EXCEPTION 'Report is not awaiting approval' USING ERRCODE='22023'; END IF;

  UPDATE public.thematic_review_reports
     SET status='rejected', rejection_reason=btrim(_reason)
   WHERE id=_report_id;

  PERFORM public.log_compliance_audit('REJECT','thematic_review_report', _report_id::text,
    jsonb_build_object('status',v_status), jsonb_build_object('status','rejected'),
    btrim(_reason), NULL, NULL, jsonb_build_object('module','market_conduct'));
END $function$
;
CREATE OR REPLACE FUNCTION public.thematic_report_submit_for_approval(_report_id uuid, _approver_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rev uuid; v_status text;
BEGIN
  SELECT review_id, status INTO v_rev, v_status FROM public.thematic_review_reports WHERE id=_report_id;
  IF v_rev IS NULL THEN RAISE EXCEPTION 'Report not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_manage_thematic_review(v_rev) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;
  IF v_status NOT IN ('draft','rejected') THEN
    RAISE EXCEPTION 'Only draft reports can be submitted for approval' USING ERRCODE='22023'; END IF;

  UPDATE public.thematic_review_reports
     SET status='in_review', submitted_at=now(), approver_id=_approver_id, rejection_reason=NULL
   WHERE id=_report_id;

  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION','thematic_review_report', _report_id::text,
    jsonb_build_object('status',v_status), jsonb_build_object('status','in_review'),
    NULL, NULL, NULL, jsonb_build_object('module','market_conduct','approver_id',_approver_id));
END $function$
;
CREATE OR REPLACE FUNCTION public.thematic_report_upsert_draft(_review_id uuid, _report_id uuid DEFAULT NULL::uuid, _title text DEFAULT NULL::text, _executive_summary text DEFAULT NULL::text, _background text DEFAULT NULL::text, _scope_methodology text DEFAULT NULL::text, _key_findings text DEFAULT NULL::text, _required_actions text DEFAULT NULL::text, _regulatory_learning text DEFAULT NULL::text, _report_type text DEFAULT 'final'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_ver integer; v_before jsonb;
BEGIN
  IF NOT public.can_manage_thematic_review(_review_id) THEN
    RAISE EXCEPTION 'Not authorised to edit thematic review reports' USING ERRCODE='42501';
  END IF;

  IF _report_id IS NULL THEN
    SELECT COALESCE(MAX(version),0)+1 INTO v_ver FROM public.thematic_review_reports WHERE review_id=_review_id;
    INSERT INTO public.thematic_review_reports(
      review_id, version, report_type, title, executive_summary, background,
      scope_methodology, key_findings, required_actions, regulatory_learning,
      status, prepared_by)
    VALUES (_review_id, v_ver, COALESCE(_report_type,'final'),
      COALESCE(NULLIF(btrim(_title),''), 'Thematic review report v'||v_ver),
      _executive_summary, _background, _scope_methodology, _key_findings,
      _required_actions, _regulatory_learning, 'draft', auth.uid())
    RETURNING id INTO v_id;

    PERFORM public.log_compliance_audit('CREATE','thematic_review_report', v_id::text, NULL,
      jsonb_build_object('review_id',_review_id,'version',v_ver), NULL, NULL, NULL,
      jsonb_build_object('module','market_conduct'));
  ELSE
    SELECT to_jsonb(r) INTO v_before FROM public.thematic_review_reports r WHERE r.id=_report_id;
    IF v_before IS NULL THEN RAISE EXCEPTION 'Report not found' USING ERRCODE='P0002'; END IF;
    IF v_before->>'status' NOT IN ('draft','rejected') THEN
      RAISE EXCEPTION 'Only draft or rejected reports can be edited' USING ERRCODE='22023';
    END IF;
    UPDATE public.thematic_review_reports SET
      title = COALESCE(NULLIF(btrim(_title),''), title),
      executive_summary=_executive_summary, background=_background,
      scope_methodology=_scope_methodology, key_findings=_key_findings,
      required_actions=_required_actions, regulatory_learning=_regulatory_learning,
      report_type=COALESCE(_report_type, report_type), status='draft'
    WHERE id=_report_id RETURNING id INTO v_id;

    PERFORM public.log_compliance_audit('UPDATE','thematic_review_report', v_id::text, v_before,
      (SELECT to_jsonb(r) FROM public.thematic_review_reports r WHERE r.id=v_id), NULL, NULL, NULL,
      jsonb_build_object('module','market_conduct'));
  END IF;
  RETURN v_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.thematic_require(_action text DEFAULT 'initiate_thematic_review'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  IF public.is_super_admin(_uid) THEN RETURN _uid; END IF;
  IF public.has_permission(_uid,'market_conduct',_action) THEN RETURN _uid; END IF;
  RAISE EXCEPTION 'Permission denied: market_conduct.%', _action USING ERRCODE='42501';
END; $function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_action_complete(_action_id uuid, _evidence text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb;
BEGIN
  _uid := public.thematic_require('initiate_thematic_review');
  SELECT to_jsonb(a) INTO _before FROM public.thematic_review_actions a WHERE a.id=_action_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Action not found' USING ERRCODE='P0002'; END IF;
  IF coalesce(_before->>'status','') IN ('completed','waived') THEN
    RAISE EXCEPTION 'Action is already concluded' USING ERRCODE='22023';
  END IF;
  UPDATE public.thematic_review_actions SET status='completed', completed_at=now(),
         evidence_of_completion=nullif(btrim(coalesce(_evidence,'')),''), updated_at=now()
  WHERE id=_action_id RETURNING to_jsonb(thematic_review_actions) INTO _after;
  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION'::compliance_audit_action,'thematic_review_action',_action_id::text,_before,_after,_evidence);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_action_save(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _id uuid; _before jsonb; _after jsonb; _review uuid;
BEGIN
  _uid := public.thematic_require('initiate_thematic_review');
  _id := nullif(_payload->>'action_id','')::uuid;
  IF coalesce(length(btrim(_payload->>'title')),0) < 3 THEN
    RAISE EXCEPTION 'An action title is required' USING ERRCODE='22023';
  END IF;
  IF _id IS NULL THEN
    _review := nullif(_payload->>'review_id','')::uuid;
    IF NOT EXISTS (SELECT 1 FROM public.thematic_reviews t WHERE t.id=_review) THEN
      RAISE EXCEPTION 'Thematic review not found' USING ERRCODE='P0002';
    END IF;
    INSERT INTO public.thematic_review_actions (review_id, finding_id, licensee_id, action_type, title, description,
                                                due_date, original_due_date, status, created_by)
    VALUES (_review, nullif(_payload->>'finding_id','')::uuid, nullif(_payload->>'licensee_id','')::uuid,
            coalesce(nullif(_payload->>'action_type',''),'remediation'), btrim(_payload->>'title'),
            nullif(_payload->>'description',''), nullif(_payload->>'due_date','')::date,
            nullif(_payload->>'due_date','')::date, 'open', _uid)
    RETURNING id INTO _id;
  ELSE
    SELECT to_jsonb(a) INTO _before FROM public.thematic_review_actions a WHERE a.id=_id;
    IF _before IS NULL THEN RAISE EXCEPTION 'Action not found' USING ERRCODE='P0002'; END IF;
    UPDATE public.thematic_review_actions SET
      title = btrim(_payload->>'title'),
      description = nullif(_payload->>'description',''),
      action_type = coalesce(nullif(_payload->>'action_type',''), action_type),
      licensee_id = nullif(_payload->>'licensee_id','')::uuid,
      finding_id = nullif(_payload->>'finding_id','')::uuid,
      updated_at = now()
    WHERE id=_id;
  END IF;
  SELECT to_jsonb(a) INTO _after FROM public.thematic_review_actions a WHERE a.id=_id;
  PERFORM public.log_compliance_audit(
    (CASE WHEN _before IS NULL THEN 'CREATE' ELSE 'UPDATE' END)::compliance_audit_action,
    'thematic_review_action',_id::text,_before,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_action_waive(_action_id uuid, _override_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb;
BEGIN
  _uid := public.thematic_require('initiate_thematic_review');
  IF _override_id IS NULL THEN
    RAISE EXCEPTION 'A recorded override is required to waive an action' USING ERRCODE='22023';
  END IF;
  SELECT to_jsonb(a) INTO _before FROM public.thematic_review_actions a WHERE a.id=_action_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Action not found' USING ERRCODE='P0002'; END IF;
  UPDATE public.thematic_review_actions SET status='waived', waiver_override_id=_override_id, updated_at=now()
  WHERE id=_action_id RETURNING to_jsonb(thematic_review_actions) INTO _after;
  PERFORM public.log_compliance_audit('OVERRIDE'::compliance_audit_action,'thematic_review_action',_action_id::text,_before,_after,_reason);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_approve_closure(_review_id uuid, _note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_review record;
BEGIN
  SELECT * INTO v_review FROM public.thematic_reviews WHERE id=_review_id;
  IF v_review IS NULL THEN RAISE EXCEPTION 'Review not found' USING ERRCODE='P0002'; END IF;
  IF v_review.closure_state <> 'pending_approval' THEN
    RAISE EXCEPTION 'This review is not awaiting closure approval' USING ERRCODE='22023'; END IF;
  IF NOT public.can_approve_thematic_closure(_review_id) THEN
    RAISE EXCEPTION 'Not authorised to approve closure' USING ERRCODE='42501'; END IF;
  IF v_review.closure_requested_by = auth.uid() AND NOT has_role(auth.uid(),'super_admin'::app_role) THEN
    RAISE EXCEPTION 'Closure must be approved by someone other than the requester' USING ERRCODE='42501'; END IF;

  UPDATE public.thematic_reviews SET
    closure_state='approved', closure_approved_by=auth.uid(), closure_approved_at=now(),
    status='closed', closed_at=now()
  WHERE id=_review_id;

  PERFORM public.log_compliance_audit('APPROVE','thematic_review', _review_id::text,
    jsonb_build_object('status', v_review.status, 'closure_state','pending_approval'),
    jsonb_build_object('status','closed','closure_state','approved'),
    _note, NULL, NULL, jsonb_build_object('module','market_conduct'));

  PERFORM public.notification_enqueue_event('thematic_review.closure_approved','thematic_review', _review_id,
    jsonb_build_object('review_title', v_review.title, 'review_code', COALESCE(v_review.code,''),
                       'requested_by', v_review.closure_requested_by),
    'closure', NULL, NULL);
END $function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_closure_readiness(_review_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'published_report_id', (SELECT r.id FROM public.thematic_review_reports r
       WHERE r.review_id=_review_id AND r.status='published' ORDER BY r.version DESC LIMIT 1),
    'unverified_actions', (SELECT count(*) FROM public.thematic_review_actions a
       WHERE a.review_id=_review_id AND a.status NOT IN ('waived','cancelled')
         AND a.verification_status <> 'verified'),
    'open_findings', (SELECT count(*) FROM public.thematic_review_findings f
       WHERE f.review_id=_review_id AND f.status='draft'),
    'pending_letters', (SELECT count(*) FROM public.thematic_review_letters l
       WHERE l.review_id=_review_id AND l.status <> 'dispatched')
  )
$function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_create(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _id uuid; _after jsonb;
BEGIN
  _uid := public.thematic_require('initiate_thematic_review');
  IF coalesce(length(btrim(_payload->>'title')),0) < 3 THEN
    RAISE EXCEPTION 'A review title is required' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.thematic_reviews (title, description, hypothesis, risk_category_id, scope_start, scope_end,
                                       lead_officer_id, regulator_id, status, opened_at, created_by)
  VALUES (btrim(_payload->>'title'), nullif(_payload->>'description',''), nullif(_payload->>'hypothesis',''),
          nullif(_payload->>'risk_category_id','')::uuid, nullif(_payload->>'scope_start','')::date,
          nullif(_payload->>'scope_end','')::date,
          coalesce(nullif(_payload->>'lead_officer_id','')::uuid, _uid),
          nullif(_payload->>'regulator_id','')::uuid, 'draft', now(), _uid)
  RETURNING id INTO _id;
  SELECT to_jsonb(t) INTO _after FROM public.thematic_reviews t WHERE t.id=_id;
  PERFORM public.log_compliance_audit('CREATE'::compliance_audit_action,'thematic_review',_id::text,NULL,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_finding_issue(_finding_id uuid, _rationale text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb;
BEGIN
  _uid := public.thematic_require('initiate_thematic_review');
  SELECT to_jsonb(f) INTO _before FROM public.thematic_review_findings f WHERE f.id=_finding_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Finding not found' USING ERRCODE='P0002'; END IF;
  IF coalesce(_before->>'status','') = 'issued' THEN
    RAISE EXCEPTION 'Finding is already issued' USING ERRCODE='22023';
  END IF;
  UPDATE public.thematic_review_findings SET status='issued', issued_at=now(), issued_by=_uid, updated_at=now()
  WHERE id=_finding_id RETURNING to_jsonb(thematic_review_findings) INTO _after;
  PERFORM public.log_compliance_audit('APPROVE'::compliance_audit_action,'thematic_review_finding',_finding_id::text,_before,_after,_rationale);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_finding_save(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _id uuid; _before jsonb; _after jsonb; _review uuid;
BEGIN
  _uid := public.thematic_require('initiate_thematic_review');
  _id := nullif(_payload->>'finding_id','')::uuid;
  IF coalesce(length(btrim(_payload->>'title')),0) < 3 THEN
    RAISE EXCEPTION 'A finding title is required' USING ERRCODE='22023';
  END IF;
  IF coalesce(_payload->>'severity','medium') NOT IN ('low','medium','high','critical') THEN
    RAISE EXCEPTION 'Invalid severity' USING ERRCODE='22023';
  END IF;
  IF _id IS NULL THEN
    _review := nullif(_payload->>'review_id','')::uuid;
    IF NOT EXISTS (SELECT 1 FROM public.thematic_reviews t WHERE t.id=_review) THEN
      RAISE EXCEPTION 'Thematic review not found' USING ERRCODE='P0002';
    END IF;
    INSERT INTO public.thematic_review_findings (review_id, licensee_id, severity, title, detail, root_cause, status, created_by)
    VALUES (_review, nullif(_payload->>'licensee_id','')::uuid, coalesce(nullif(_payload->>'severity',''),'medium'),
            btrim(_payload->>'title'), nullif(_payload->>'detail',''), nullif(_payload->>'root_cause',''), 'draft', _uid)
    RETURNING id INTO _id;
  ELSE
    SELECT to_jsonb(f) INTO _before FROM public.thematic_review_findings f WHERE f.id=_id;
    IF _before IS NULL THEN RAISE EXCEPTION 'Finding not found' USING ERRCODE='P0002'; END IF;
    IF coalesce(_before->>'status','') = 'issued' THEN
      RAISE EXCEPTION 'An issued finding cannot be edited' USING ERRCODE='22023';
    END IF;
    UPDATE public.thematic_review_findings SET
      licensee_id = nullif(_payload->>'licensee_id','')::uuid,
      severity = coalesce(nullif(_payload->>'severity',''), severity),
      title = btrim(_payload->>'title'),
      detail = nullif(_payload->>'detail',''),
      root_cause = nullif(_payload->>'root_cause',''),
      updated_at = now()
    WHERE id=_id;
  END IF;
  SELECT to_jsonb(f) INTO _after FROM public.thematic_review_findings f WHERE f.id=_id;
  PERFORM public.log_compliance_audit(
    (CASE WHEN _before IS NULL THEN 'CREATE' ELSE 'UPDATE' END)::compliance_audit_action,
    'thematic_review_finding',_id::text,_before,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_letter_mark_dispatched(_letter_id uuid, _recipient_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb;
BEGIN
  _uid := public.thematic_require('initiate_thematic_review');
  SELECT to_jsonb(l) INTO _before FROM public.thematic_review_letters l WHERE l.id=_letter_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Letter not found' USING ERRCODE='P0002'; END IF;
  IF coalesce(_before->>'status','') = 'dispatched' THEN
    RAISE EXCEPTION 'Letter is already dispatched' USING ERRCODE='22023';
  END IF;
  UPDATE public.thematic_review_letters SET status='dispatched', dispatched_at=now(), dispatched_by=_uid,
         recipient_email = coalesce(nullif(btrim(coalesce(_recipient_email,'')),''), recipient_email),
         error_message=NULL, updated_at=now()
  WHERE id=_letter_id RETURNING to_jsonb(thematic_review_letters) INTO _after;
  PERFORM public.log_compliance_audit('APPROVE'::compliance_audit_action,'thematic_review_letter',_letter_id::text,_before,_after,NULL);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_reject_closure(_review_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_review record;
BEGIN
  IF _reason IS NULL OR length(btrim(_reason)) < 10 THEN
    RAISE EXCEPTION 'A rejection reason of at least 10 characters is required' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_review FROM public.thematic_reviews WHERE id=_review_id;
  IF v_review IS NULL THEN RAISE EXCEPTION 'Review not found' USING ERRCODE='P0002'; END IF;
  IF v_review.closure_state <> 'pending_approval' THEN
    RAISE EXCEPTION 'This review is not awaiting closure approval' USING ERRCODE='22023'; END IF;
  IF NOT public.can_approve_thematic_closure(_review_id) THEN
    RAISE EXCEPTION 'Not authorised to reject closure' USING ERRCODE='42501'; END IF;

  UPDATE public.thematic_reviews SET
    closure_state='rejected', closure_rejection_reason=btrim(_reason)
  WHERE id=_review_id;

  INSERT INTO public.thematic_review_status_history(review_id, from_status, to_status, changed_by, reason, metadata)
  VALUES (_review_id, v_review.status, v_review.status, auth.uid(), btrim(_reason),
          jsonb_build_object('event','closure_rejected'));

  PERFORM public.log_compliance_audit('REJECT','thematic_review', _review_id::text,
    jsonb_build_object('closure_state','pending_approval'),
    jsonb_build_object('closure_state','rejected'),
    btrim(_reason), NULL, NULL, jsonb_build_object('module','market_conduct'));

  PERFORM public.notification_enqueue_event('thematic_review.closure_rejected','thematic_review', _review_id,
    jsonb_build_object('review_title', v_review.title, 'review_code', COALESCE(v_review.code,''),
                       'reason', btrim(_reason), 'requested_by', v_review.closure_requested_by),
    'closure', NULL, NULL);
END $function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_request_closure(_review_id uuid, _closure_summary text, _regulatory_learning jsonb DEFAULT '{}'::jsonb, _approver_id uuid DEFAULT NULL::uuid, _override_id uuid DEFAULT NULL::uuid, _override_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ready jsonb; v_review record;
BEGIN
  SELECT * INTO v_review FROM public.thematic_reviews WHERE id=_review_id;
  IF v_review IS NULL THEN RAISE EXCEPTION 'Review not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.can_manage_thematic_review(_review_id) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE='42501'; END IF;
  IF v_review.status = 'closed' THEN
    RAISE EXCEPTION 'Review is already closed' USING ERRCODE='22023'; END IF;
  IF v_review.closure_state = 'pending_approval' THEN
    RAISE EXCEPTION 'Closure approval is already pending' USING ERRCODE='22023'; END IF;
  IF _closure_summary IS NULL OR length(btrim(_closure_summary)) < 20 THEN
    RAISE EXCEPTION 'A closure summary of at least 20 characters is required' USING ERRCODE='22023'; END IF;

  v_ready := public.thematic_review_closure_readiness(_review_id);

  IF (v_ready->>'published_report_id') IS NULL THEN
    RAISE EXCEPTION 'A published report is required before closure can be requested' USING ERRCODE='22023';
  END IF;

  IF (v_ready->>'unverified_actions')::int > 0 THEN
    IF _override_id IS NULL OR _override_reason IS NULL OR length(btrim(_override_reason)) < 10 THEN
      RAISE EXCEPTION 'Closure blocked: % required action(s) are not verified. A documented override is needed.',
        (v_ready->>'unverified_actions') USING ERRCODE='22023';
    END IF;
  END IF;

  UPDATE public.thematic_reviews SET
    closure_state='pending_approval',
    closure_summary=btrim(_closure_summary),
    regulatory_learning=COALESCE(_regulatory_learning,'{}'::jsonb),
    closure_approver_id=_approver_id,
    closure_requested_by=auth.uid(),
    closure_requested_at=now(),
    closure_rejection_reason=NULL,
    closure_override_id=_override_id
  WHERE id=_review_id;

  INSERT INTO public.thematic_review_status_history(review_id, from_status, to_status, changed_by, reason, override_id, metadata)
  VALUES (_review_id, v_review.status, v_review.status, auth.uid(),
          COALESCE(_override_reason,'Closure requested'), _override_id,
          jsonb_build_object('event','closure_requested','readiness',v_ready));

  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION','thematic_review', _review_id::text,
    jsonb_build_object('closure_state', v_review.closure_state),
    jsonb_build_object('closure_state','pending_approval'),
    COALESCE(_override_reason, btrim(_closure_summary)), NULL, NULL,
    jsonb_build_object('module','market_conduct','readiness',v_ready,'approver_id',_approver_id));

  PERFORM public.notification_enqueue_event('thematic_review.closure_requested','thematic_review', _review_id,
    jsonb_build_object('review_title', v_review.title, 'review_code', COALESCE(v_review.code,''),
                       'approver_id', _approver_id, 'closure_summary', btrim(_closure_summary)),
    'closure', NULL, NULL);
END $function$
;
CREATE OR REPLACE FUNCTION public.thematic_review_set_status(_review_id uuid, _status text, _reason text DEFAULT NULL::text, _override_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid; _before jsonb; _after jsonb;
BEGIN
  _uid := public.thematic_require('initiate_thematic_review');
  SELECT to_jsonb(t) INTO _before FROM public.thematic_reviews t WHERE t.id=_review_id;
  IF _before IS NULL THEN RAISE EXCEPTION 'Thematic review not found' USING ERRCODE='P0002'; END IF;
  IF _status NOT IN ('draft','scoped','evidence_collection','analysis','findings_issued','actions_required','monitoring','closed','cancelled') THEN
    RAISE EXCEPTION 'Invalid thematic review status %', _status USING ERRCODE='22023';
  END IF;
  IF _status IN ('closed','cancelled') AND coalesce(length(btrim(_reason)),0) < 10 THEN
    RAISE EXCEPTION 'A rationale of at least 10 characters is required to close or cancel a review' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.thematic_review_status_history (review_id, from_status, to_status, changed_by, reason, override_id)
  VALUES (_review_id, _before->>'status', _status, _uid, _reason, _override_id);
  UPDATE public.thematic_reviews SET
    status=_status,
    closed_at = CASE WHEN _status IN ('closed','cancelled') THEN now() ELSE closed_at END,
    updated_at = now()
  WHERE id=_review_id RETURNING to_jsonb(thematic_reviews) INTO _after;
  PERFORM public.log_compliance_audit('WORKFLOW_TRANSITION'::compliance_audit_action,'thematic_review',_review_id::text,_before,_after,_reason);
  RETURN _after;
END; $function$
;
CREATE OR REPLACE FUNCTION public.thematic_reviews_code_default()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE seq int;
BEGIN
  IF NEW.code IS NULL OR NEW.code = '' THEN
    SELECT COALESCE(MAX((regexp_replace(code,'^TR-\d{4}-','','g'))::int),0)+1
      INTO seq FROM public.thematic_reviews
      WHERE code LIKE 'TR-'||to_char(now(),'YYYY')||'-%';
    NEW.code := 'TR-'||to_char(now(),'YYYY')||'-'||lpad(seq::text,4,'0');
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.thematic_reviews_status_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  allowed text[] := ARRAY['draft','scoped','evidence_collection','analysis','findings_issued','actions_required','monitoring','closed'];
  fwd jsonb := '{
    "draft":["scoped"],
    "scoped":["evidence_collection"],
    "evidence_collection":["analysis"],
    "analysis":["findings_issued"],
    "findings_issued":["actions_required"],
    "actions_required":["monitoring"],
    "monitoring":["closed"]
  }'::jsonb;
  ok_forward boolean;
  has_override boolean;
BEGIN
  IF NEW.status = OLD.status THEN RETURN NEW; END IF;
  IF NOT (NEW.status = ANY(allowed)) THEN
    RAISE EXCEPTION 'Invalid thematic review status: %', NEW.status;
  END IF;
  ok_forward := (fwd -> OLD.status) ? NEW.status;
  IF NOT ok_forward THEN
    -- backward or skip; require override recorded in status history within same tx
    SELECT EXISTS(SELECT 1 FROM public.thematic_review_status_history
                    WHERE review_id = NEW.id
                      AND to_status = NEW.status
                      AND override_id IS NOT NULL
                      AND changed_at > now() - interval '30 seconds')
      INTO has_override;
    IF NOT has_override THEN
      RAISE EXCEPTION 'Backward/skip transition % -> % requires an override entry', OLD.status, NEW.status
        USING HINT='Insert into thematic_review_status_history with override_id first.';
    END IF;
  END IF;
  -- log if not already logged in same tx
  INSERT INTO public.thematic_review_status_history(review_id, from_status, to_status, changed_by, reason)
    SELECT NEW.id, OLD.status, NEW.status, auth.uid(), NULL
    WHERE NOT EXISTS (
      SELECT 1 FROM public.thematic_review_status_history
       WHERE review_id = NEW.id AND to_status = NEW.status
         AND changed_at > now() - interval '30 seconds'
    );
  IF NEW.status = 'closed' AND NEW.closed_at IS NULL THEN NEW.closed_at := now(); END IF;
  IF OLD.status = 'draft' AND NEW.status = 'scoped' AND NEW.opened_at IS NULL THEN NEW.opened_at := now(); END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.toggle_ppoc_mapping_status(_mapping_id uuid, _is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_old record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','Not authenticated','code','UNAUTHORIZED','http',401);
  END IF;
  IF NOT (public.has_role(v_uid,'super_admin'::app_role) OR public.has_role(v_uid,'admin'::app_role)) THEN
    RETURN jsonb_build_object('error','Admin only','code','FORBIDDEN','http',403);
  END IF;
  IF _mapping_id IS NULL THEN
    RETURN jsonb_build_object('error','Mapping id required','code','INVALID','http',422);
  END IF;

  SELECT * INTO v_old FROM public.ppoc_entity_mappings WHERE id = _mapping_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','Mapping not found','code','NOT_FOUND','http',404);
  END IF;

  UPDATE public.ppoc_entity_mappings
     SET is_active = _is_active, updated_at = now()
   WHERE id = _mapping_id;

  INSERT INTO public.audit_logs(user_id, action, entity_type, entity_id, old_value, new_value, metadata)
  VALUES (
    v_uid,
    CASE WHEN _is_active THEN 'ppoc_mapping_activated' ELSE 'ppoc_mapping_deactivated' END,
    'ppoc_entity_mapping',
    _mapping_id::text,
    jsonb_build_object('is_active', v_old.is_active),
    jsonb_build_object('is_active', _is_active),
    jsonb_build_object('ppoc_user_id', v_old.ppoc_user_id, 'licensee_id', v_old.licensee_id)
  );

  RETURN jsonb_build_object('ok', true, 'mapping_id', _mapping_id, 'is_active', _is_active);
END;
$function$
;
