CREATE OR REPLACE FUNCTION public.transition_complaint_status(_id uuid, _new_status text, _reason text DEFAULT NULL::text, _expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_current text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF _new_status NOT IN ('submitted','under_investigation','resolved','closed') THEN
    RAISE EXCEPTION 'Invalid status' USING ERRCODE = '22023';
  END IF;
  IF NOT (public.has_complaint_perm(v_uid,'triage') OR public.has_complaint_perm(v_uid,'investigate') OR public.has_complaint_perm(v_uid,'close')) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;
  PERFORM public._assert_complaint_fresh(_id, _expected_updated_at);
  SELECT status INTO v_current FROM public.complaints WHERE id = _id;
  IF v_current IS NULL THEN RAISE EXCEPTION 'Complaint not found' USING ERRCODE = 'P0002'; END IF;
  IF v_current = _new_status THEN RETURN; END IF;
  UPDATE public.complaints SET status = _new_status, updated_at = now() WHERE id = _id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'complaint.status_changed','complaint',_id,
          jsonb_build_object('from',v_current,'to',_new_status,'reason',_reason));
END; $function$
;
CREATE OR REPLACE FUNCTION public.trg_application_notification_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payload jsonb;
  v_new_legal boolean; v_old_legal boolean;
  v_new_terminal boolean; v_old_terminal boolean;
BEGIN
  v_payload := jsonb_build_object(
    'application_id', NEW.id,
    'application_number', NEW.application_number,
    'applicant_id', NEW.applicant_id,
    'licensee_id', NEW.data->>'licensee_id',
    'status', NEW.status,
    'cta_url', '/applications/' || NEW.id,
    'cta_label', 'Open application'
  );

  IF NEW.assigned_to IS NOT NULL AND NEW.assigned_to IS DISTINCT FROM OLD.assigned_to THEN
    IF public.has_role(NEW.assigned_to, 'licensing_officer'::app_role) THEN
      PERFORM public.notification_enqueue_event('application.officer_assigned', 'application', NEW.id,
        v_payload || jsonb_build_object('assignee_id', NEW.assigned_to), NEW.assigned_to::text);
    ELSE
      PERFORM public.notification_enqueue_event('application.analyst_assigned', 'application', NEW.id,
        v_payload || jsonb_build_object('assignee_id', NEW.assigned_to), NEW.assigned_to::text);
    END IF;
  END IF;

  IF NEW.current_step_id IS DISTINCT FROM OLD.current_step_id THEN
    SELECT coalesce(is_legal_compliance_stage,false), coalesce(is_terminal,false)
      INTO v_new_legal, v_new_terminal FROM public.approval_steps WHERE id = NEW.current_step_id;
    SELECT coalesce(is_legal_compliance_stage,false), coalesce(is_terminal,false)
      INTO v_old_legal, v_old_terminal FROM public.approval_steps WHERE id = OLD.current_step_id;

    IF coalesce(v_new_legal,false) THEN
      PERFORM public.notification_enqueue_event('application.routed_to_legal', 'application', NEW.id,
        v_payload, NEW.current_step_id::text);
    END IF;
    IF coalesce(v_old_legal,false) AND NOT coalesce(v_new_legal,false) THEN
      PERFORM public.notification_enqueue_event('application.legal_review_completed', 'application', NEW.id,
        v_payload, OLD.current_step_id::text);
    END IF;
    IF coalesce(v_new_terminal,false) AND NOT coalesce(v_old_terminal,false) THEN
      PERFORM public.notification_enqueue_event('application.decision_ready', 'application', NEW.id,
        v_payload, NEW.current_step_id::text);
    END IF;
  END IF;

  IF (NEW.approved_at IS NOT NULL AND OLD.approved_at IS NULL)
     OR (NEW.rejected_at IS NOT NULL AND OLD.rejected_at IS NULL) THEN
    PERFORM public.notification_enqueue_event('application.decision_dispatched', 'application', NEW.id,
      v_payload || jsonb_build_object('decision',
        CASE WHEN NEW.approved_at IS NOT NULL THEN 'approved' ELSE 'rejected' END),
      coalesce(NEW.approved_at, NEW.rejected_at)::text);
  END IF;

  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.trg_application_rfi_closed_restores_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_open int;
  v_status text;
  v_prev text;
BEGIN
  IF NEW.status = 'open' OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  IF NEW.approval_step_action_id IS NOT NULL THEN
    UPDATE public.approval_step_actions
       SET resumed_at = now()
     WHERE id = NEW.approval_step_action_id
       AND paused_at IS NOT NULL
       AND resumed_at IS NULL;
  END IF;

  SELECT count(*) INTO v_open
    FROM public.application_rfis r
   WHERE r.application_id = NEW.application_id
     AND r.status = 'open';
  IF v_open > 0 THEN
    RETURN NEW;
  END IF;

  SELECT a.status, nullif(a.data->>'pre_rfi_status','')
    INTO v_status, v_prev
    FROM public.applications a
   WHERE a.id = NEW.application_id;

  IF v_status = 'info_requested' THEN
    PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

    UPDATE public.applications a
       SET status = coalesce(v_prev, 'submitted'),
           data = coalesce(a.data, '{}'::jsonb) - 'pre_rfi_status',
           updated_at = now()
     WHERE a.id = NEW.application_id;

    INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value, metadata)
    VALUES (coalesce(NEW.closed_by, auth.uid()), 'application.info_request_resolved', 'application',
            NEW.application_id::text,
            jsonb_build_object('status', 'info_requested'),
            jsonb_build_object('status', coalesce(v_prev, 'submitted')),
            jsonb_build_object('rfi_id', NEW.id, 'rfi_status', NEW.status));
  ELSIF v_status IS NOT NULL AND v_prev IS NOT NULL THEN
    -- Applicant already resubmitted: just clear the stash.
    UPDATE public.applications a
       SET data = coalesce(a.data, '{}'::jsonb) - 'pre_rfi_status'
     WHERE a.id = NEW.application_id;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_application_rfi_open_sets_info_requested()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
BEGIN
  IF NEW.status IS DISTINCT FROM 'open' THEN
    RETURN NEW;
  END IF;

  SELECT a.status INTO v_status FROM public.applications a WHERE a.id = NEW.application_id;
  IF v_status IS NULL THEN
    RETURN NEW;
  END IF;

  IF v_status = ANY (ARRAY['submitted','under_review','clarification_requested']) THEN
    PERFORM set_config('app.workflow_mutation_context', 'trusted', true);

    UPDATE public.applications a
       SET status = 'info_requested',
           data = coalesce(a.data, '{}'::jsonb) || jsonb_build_object('pre_rfi_status', v_status),
           updated_at = now()
     WHERE a.id = NEW.application_id;

    INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value, metadata)
    VALUES (NEW.raised_by, 'application.info_requested', 'application', NEW.application_id::text,
            jsonb_build_object('status', v_status),
            jsonb_build_object('status', 'info_requested'),
            jsonb_build_object('rfi_id', NEW.id, 'summary', NEW.summary));
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_approval_action_escalation_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE a public.applications%ROWTYPE;
BEGIN
  IF NEW.application_id IS NULL THEN RETURN NEW; END IF;
  IF coalesce(NEW.action,'') NOT ILIKE '%escalat%' THEN RETURN NEW; END IF;
  SELECT * INTO a FROM public.applications WHERE id = NEW.application_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  PERFORM public.notification_enqueue_event('application.escalated_to_supervisor', 'application', a.id,
    jsonb_build_object('application_id', a.id, 'application_number', a.application_number,
      'applicant_id', a.applicant_id, 'licensee_id', a.data->>'licensee_id',
      'actor_id', NEW.actor_id, 'comments', NEW.comments,
      'cta_url', '/applications/' || a.id, 'cta_label', 'Open application'),
    NEW.id::text);
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.trg_complaint_case_to_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_ref text; v_sev public.escalation_severity;
BEGIN
  IF NEW.escalation_id IS NOT NULL THEN RETURN NEW; END IF;
  SELECT complaint_number INTO v_ref FROM public.complaints WHERE id = NEW.complaint_id;
  v_sev := CASE lower(coalesce(NEW.severity::text,'medium'))
             WHEN 'critical' THEN 'critical' WHEN 'high' THEN 'high'
             WHEN 'low' THEN 'low' ELSE 'medium' END::public.escalation_severity;

  v_id := public.escalation_raise(
    'complaint_management',
    'complaint_escalation.' || coalesce(NEW.rule_key, 'manual'),
    'complaint_escalation'::public.escalation_type,
    'complaint', NEW.complaint_id, v_ref, v_sev, NEW.rule_id,
    jsonb_build_object('rule_label', NEW.rule_label, 'trigger_reason', NEW.trigger_reason,
                       'target_tier', NEW.target_tier, 'case_id', NEW.id),
    NULL);

  NEW.escalation_id := v_id;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_complaint_correspondence_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c public.complaints%ROWTYPE;
BEGIN
  IF NEW.direction <> 'outbound' THEN RETURN NEW; END IF;
  SELECT * INTO c FROM public.complaints WHERE id = NEW.complaint_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  PERFORM public.notification_enqueue_event('complaint.complainant_update', 'complaint', c.id,
    jsonb_build_object('complaint_id', c.id, 'complaint_number', c.complaint_number,
      'complainant_id', c.complainant_id, 'complainant_email', c.email,
      'licensee_id', c.licensee_id, 'subject', NEW.subject,
      'cta_url', '/complaints/' || c.id, 'cta_label', 'Open complaint'),
    NEW.id::text);
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.trg_complaint_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_payload jsonb;
BEGIN
  v_payload := jsonb_build_object(
    'complaint_number', NEW.complaint_number,
    'complainant_id', NEW.complainant_id,
    'complainant_email', NEW.email,
    'investigator_id', NEW.investigator_id,
    'entity_id', NEW.licensee_id,
    'priority', NEW.priority,
    'severity', NEW.severity,
    'status', NEW.status,
    'sla_due_at', NEW.sla_due_at,
    'subject', NEW.subject
  );

  IF TG_OP = 'INSERT' THEN
    PERFORM public.notification_enqueue_event('complaint.acknowledged', 'complaint', NEW.id, v_payload, 'intake');
    IF NEW.investigator_id IS NOT NULL THEN
      PERFORM public.notification_enqueue_event('complaint.assigned', 'complaint', NEW.id, v_payload, NEW.investigator_id::text);
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.investigator_id IS NOT NULL AND NEW.investigator_id IS DISTINCT FROM OLD.investigator_id THEN
    PERFORM public.notification_enqueue_event('complaint.assigned', 'complaint', NEW.id, v_payload, NEW.investigator_id::text);
  END IF;

  IF NEW.priority IS DISTINCT FROM OLD.priority OR NEW.severity IS DISTINCT FROM OLD.severity THEN
    PERFORM public.notification_enqueue_event('complaint.priority_changed', 'complaint', NEW.id,
      v_payload || jsonb_build_object(
        'old_priority', COALESCE(OLD.priority, OLD.severity),
        'new_priority', COALESCE(NEW.priority, NEW.severity)),
      concat_ws('>', COALESCE(OLD.priority, OLD.severity), COALESCE(NEW.priority, NEW.severity)));
  END IF;

  IF NEW.status IN ('closed','resolved') AND OLD.status IS DISTINCT FROM NEW.status THEN
    PERFORM public.notification_enqueue_event('complaint.outcome_released', 'complaint', NEW.id,
      v_payload || jsonb_build_object('outcome', COALESCE(NEW.resolution, NEW.resolution_notes, NEW.closure_reason, NEW.status)),
      NEW.status);
  END IF;

  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.trg_complaints_block_progress_when_needs_remediation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.status IS DISTINCT FROM OLD.status
     AND NEW.vulnerability_review_state = 'needs_remediation'
     AND NEW.status NOT IN ('rejected', 'duplicate', 'closed') THEN
    RAISE EXCEPTION 'vulnerability_remediation_required'
      USING HINT = 'Complete vulnerability review (confirm or mark not applicable) before advancing status.';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_complaints_generate_duplicates_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.generate_complaint_duplicate_candidates(NEW.id);
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_complaints_vulnerability_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.vulnerability_indicator = FALSE THEN
    NEW.vulnerability_notes := NULL;
    NEW.vulnerability_category := NULL;
    NEW.vulnerability_review_state := 'not_applicable';
  ELSE
    IF NEW.vulnerability_review_state = 'not_applicable' THEN
      IF COALESCE(btrim(NEW.vulnerability_notes), '') <> ''
         OR COALESCE(btrim(NEW.vulnerability_category), '') <> '' THEN
        NEW.vulnerability_review_state := 'confirmed';
      ELSE
        NEW.vulnerability_review_state := 'needs_remediation';
      END IF;
    ELSIF NEW.vulnerability_review_state = 'confirmed' THEN
      IF COALESCE(btrim(NEW.vulnerability_notes), '') = ''
         AND COALESCE(btrim(NEW.vulnerability_category), '') = '' THEN
        RAISE EXCEPTION 'vulnerability_confirmed_requires_detail'
          USING HINT = 'Provide vulnerability_category or vulnerability_notes to confirm.';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
