CREATE OR REPLACE FUNCTION public.trg_conduct_alert_to_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_ref text;
BEGIN
  IF NEW.escalation_id IS NOT NULL THEN RETURN NEW; END IF;
  SELECT name INTO v_ref FROM public.licensees WHERE id = NEW.licensee_id;

  v_id := public.escalation_raise(
    'market_conduct',
    'conduct_alert.' || coalesce(NEW.kind, 'pattern') || '#' || left(NEW.id::text, 8),
    'conduct_alert'::public.escalation_type,
    'licensee', NEW.licensee_id, coalesce(v_ref, NEW.title),
    CASE lower(coalesce(NEW.severity::text,'medium'))
      WHEN 'critical' THEN 'critical' WHEN 'high' THEN 'high'
      WHEN 'low' THEN 'low' ELSE 'medium' END::public.escalation_severity,
    NEW.triage_rule_id,
    jsonb_build_object('title', NEW.title, 'detail', NEW.detail, 'kind', NEW.kind,
                       'source', NEW.source, 'legacy_id', NEW.id),
    NULL);

  NEW.escalation_id := v_id;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_conduct_complaint_notification_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_payload jsonb;
BEGIN
  v_payload := jsonb_build_object(
    'complaint_id', NEW.id, 'complaint_number', NEW.complaint_number,
    'licensee_id', NEW.licensee_id, 'entity_id', NEW.licensee_id,
    'severity', NEW.severity, 'priority', NEW.priority,
    'assigned_to', NEW.investigator_id, 'record_assignee_id', NEW.investigator_id,
    'subject', NEW.subject,
    'cta_url', '/complaints/' || NEW.id, 'cta_label', 'Open complaint');

  IF TG_OP = 'INSERT' THEN
    PERFORM public.notification_enqueue_event('conduct_complaint_created', 'complaint', NEW.id, v_payload);
    IF coalesce(NEW.severity,'') IN ('high','critical') THEN
      PERFORM public.notification_enqueue_event('conduct_high_severity_complaint', 'complaint', NEW.id, v_payload);
    END IF;
  ELSE
    IF NEW.triage_evaluated_at IS NOT NULL AND OLD.triage_evaluated_at IS DISTINCT FROM NEW.triage_evaluated_at THEN
      PERFORM public.notification_enqueue_event('conduct_complaint_triaged', 'complaint', NEW.id, v_payload,
        NEW.triage_evaluated_at::text);
    END IF;
    IF NEW.severity IS DISTINCT FROM OLD.severity AND coalesce(NEW.severity,'') IN ('high','critical') THEN
      PERFORM public.notification_enqueue_event('conduct_high_severity_complaint', 'complaint', NEW.id, v_payload,
        NEW.severity);
    END IF;
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.trg_conduct_pattern_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_entity text; v_complaint text;
BEGIN
  SELECT COALESCE(name, id::text) INTO v_entity FROM public.licensees WHERE id = NEW.licensee_id;
  SELECT complaint_number INTO v_complaint FROM public.complaints WHERE id = NEW.complaint_id;

  IF NEW.kind ILIKE '%systemic%' THEN
    PERFORM public.notification_enqueue_event('conduct.systemic_flag_raised', 'conduct_alert', NEW.id,
      jsonb_build_object(
        'entity_name', COALESCE(v_entity, 'entity'),
        'complaint_number', COALESCE(v_complaint, '-'),
        'actor_name', COALESCE(NEW.generated_by, 'system'),
        'detail', NEW.detail
      ), NEW.kind);
  ELSIF NEW.kind ILIKE '%pattern%' OR NEW.kind ILIKE '%spike%' OR NEW.kind ILIKE '%trend%' THEN
    PERFORM public.notification_enqueue_event('conduct.pattern_alert', 'conduct_alert', NEW.id,
      jsonb_build_object(
        'pattern_label', COALESCE(NEW.title, NEW.kind),
        'complaint_count', COALESCE((NEW.detail->>'complaint_count')::text, '1'),
        'entity_name', COALESCE(v_entity, 'entity'),
        'detail', NEW.detail
      ), NEW.kind);
  END IF;
  RETURN NEW;
END; $function$
;
