CREATE OR REPLACE FUNCTION public.trg_enforcement_notification_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_payload jsonb; v_complainant uuid;
BEGIN
  SELECT complainant_id INTO v_complainant FROM public.complaints
   WHERE enforcement_action_id = NEW.id LIMIT 1;

  v_payload := jsonb_build_object('enforcement_id', NEW.id, 'case_number', NEW.case_number,
    'entity_id', NEW.entity_id, 'licensee_id', NEW.entity_id,
    'enforcement_type', NEW.enforcement_type, 'status', NEW.status,
    'complainant_id', v_complainant,
    'cta_url', '/enforcement/' || NEW.id, 'cta_label', 'Open case');

  IF NEW.notice_issued_at IS NOT NULL AND OLD.notice_issued_at IS NULL THEN
    PERFORM public.notification_enqueue_event('enforcement.notice_issued', 'enforcement_action', NEW.id, v_payload, 'notice');
  END IF;
  IF NEW.response_received_at IS NOT NULL AND OLD.response_received_at IS NULL THEN
    PERFORM public.notification_enqueue_event('enforcement.response_received', 'enforcement_action', NEW.id, v_payload, 'response');
  END IF;
  IF NEW.decision_at IS NOT NULL AND OLD.decision_at IS NULL THEN
    PERFORM public.notification_enqueue_event('enforcement.decision_recorded', 'enforcement_action', NEW.id,
      v_payload || jsonb_build_object('decision_outcome', NEW.decision_outcome), 'decision');
  END IF;
  IF NEW.closed_at IS NOT NULL AND OLD.closed_at IS NULL THEN
    IF coalesce(NEW.decision_outcome,'') ILIKE '%withdraw%' OR coalesce(NEW.status,'') ILIKE '%withdraw%' THEN
      PERFORM public.notification_enqueue_event('enforcement.case_withdrawn', 'enforcement_action', NEW.id, v_payload, 'withdrawn');
    ELSE
      PERFORM public.notification_enqueue_event('enforcement.case_closed', 'enforcement_action', NEW.id, v_payload, 'closed');
    END IF;
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.trg_entity_resolution_maker_checker()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.approved_by IS NOT NULL
     AND NEW.recommended_by IS NOT NULL
     AND NEW.approved_by = NEW.recommended_by THEN
    RAISE EXCEPTION 'Maker-checker violation: the recommending officer cannot approve the same entity resolution case'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.supervisor_decided_by IS NOT NULL
     AND NEW.recommended_by IS NOT NULL
     AND NEW.supervisor_decided_by = NEW.recommended_by THEN
    RAISE EXCEPTION 'Maker-checker violation: the recommending officer cannot record the supervisory decision'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_entity_user_access_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_payload jsonb;
BEGIN
  v_payload := jsonb_build_object('access_id', NEW.id, 'affected_user_id', NEW.user_id,
    'entity_id', NEW.entity_id, 'licensee_id', NEW.entity_id,
    'access_type', NEW.access_type, 'previous_access_type', OLD.access_type,
    'cta_url', '/admin/licensees/' || NEW.entity_id, 'cta_label', 'Open entity');

  IF coalesce(OLD.is_active,true) AND NOT coalesce(NEW.is_active,true) THEN
    PERFORM public.notification_enqueue_event('entity.user_access_revoked', 'licensee', NEW.entity_id,
      v_payload, NEW.id::text);
  END IF;
  IF NEW.access_type IS DISTINCT FROM OLD.access_type THEN
    PERFORM public.notification_enqueue_event('entity.user_role_changed', 'licensee', NEW.entity_id,
      v_payload, NEW.id::text || ':' || NEW.access_type::text);
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.trg_escalation_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_payload jsonb;
BEGIN
  v_payload := jsonb_build_object(
    'escalation_ref', NEW.escalation_ref,
    'escalation_type', NEW.escalation_type,
    'severity', NEW.severity,
    'current_tier', NEW.current_tier,
    'source_module', NEW.source_module,
    'source_reference', COALESCE(NEW.source_reference, NEW.source_entity_id::text),
    'source_entity_type', NEW.source_entity_type,
    'source_entity_id', NEW.source_entity_id,
    'assigned_user_id', NEW.assigned_user_id,
    'acknowledgement_deadline', NEW.acknowledgement_deadline,
    'resolution_deadline', NEW.resolution_deadline,
    'resolution_narrative', NEW.resolution_narrative
  );

  IF TG_OP = 'INSERT' THEN
    PERFORM public.notification_enqueue_event('escalation.created', 'escalation', NEW.id, v_payload,
      'tier' || COALESCE(NEW.current_tier, 0)::text, NEW.correlation_id);
    IF NEW.assigned_user_id IS NOT NULL THEN
      PERFORM public.notification_enqueue_event('escalation.ownership_assigned', 'escalation', NEW.id, v_payload,
        NEW.assigned_user_id::text, NEW.correlation_id);
    END IF;
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.current_tier, 0) > COALESCE(OLD.current_tier, 0) THEN
    PERFORM public.notification_enqueue_event('escalation.tier_advanced', 'escalation', NEW.id, v_payload,
      'tier' || COALESCE(NEW.current_tier, 0)::text, NEW.correlation_id);
  END IF;

  IF NEW.assigned_user_id IS NOT NULL AND NEW.assigned_user_id IS DISTINCT FROM OLD.assigned_user_id THEN
    PERFORM public.notification_enqueue_event('escalation.ownership_assigned', 'escalation', NEW.id, v_payload,
      NEW.assigned_user_id::text, NEW.correlation_id);
  END IF;

  IF NEW.status::text IN ('resolved','closed') AND OLD.status IS DISTINCT FROM NEW.status THEN
    PERFORM public.notification_enqueue_event('escalation.resolved', 'escalation', NEW.id, v_payload,
      NEW.status::text, NEW.correlation_id);
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_escalation_rule_activated_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(NEW.is_active,false) AND NOT coalesce(OLD.is_active,false) THEN
    PERFORM public.notification_enqueue_event('rule.activated', 'escalation_rule', NEW.id,
      jsonb_build_object('rule_id', NEW.id, 'rule_name', NEW.name,
        'source_module', NEW.source_module, 'escalation_type', NEW.escalation_type,
        'cta_url', '/admin/escalations', 'cta_label', 'Open escalation rules'),
      'activated');
  END IF;
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.trg_escalation_rule_change_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_change text; v_rec record;
BEGIN
  IF TG_OP = 'INSERT' THEN v_change := 'created'; v_rec := NEW;
  ELSIF TG_OP = 'DELETE' THEN v_change := 'deleted'; v_rec := OLD;
  ELSE
    v_rec := NEW;
    v_change := CASE
      WHEN NEW.is_active AND NOT OLD.is_active THEN 'activated'
      WHEN NOT NEW.is_active AND OLD.is_active THEN 'deactivated'
      ELSE 'updated' END;
  END IF;

  PERFORM public.notification_enqueue_event('escalation_rule.changed', 'escalation_rule', v_rec.id,
    jsonb_build_object(
      'rule_name', v_rec.name,
      'change_type', v_change,
      'source_module', v_rec.source_module,
      'actor_name', COALESCE((SELECT COALESCE(full_name, email) FROM public.profiles WHERE id = auth.uid()), 'system')
    ),
    v_change || ':' || to_char(now(), 'YYYYMMDDHH24MI'));

  RETURN COALESCE(NEW, OLD);
END; $function$
;
CREATE OR REPLACE FUNCTION public.trg_examination_finding_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_entity text; v_entity_id uuid;
BEGIN
  SELECT i.entity_id, COALESCE(l.entity_name, l.legal_name, l.id::text)
    INTO v_entity_id, v_entity
    FROM public.inspections i
    LEFT JOIN public.licensees l ON l.id = i.entity_id
   WHERE i.id = NEW.inspection_id;

  PERFORM public.notification_enqueue_event('prudential.examination_finding_recorded', 'inspection_finding', NEW.id,
    jsonb_build_object(
      'entity_name', COALESCE(v_entity, 'entity'),
      'entity_id', v_entity_id,
      'inspection_id', NEW.inspection_id,
      'finding_title', COALESCE(NEW.category, 'Finding'),
      'severity_label', COALESCE(NEW.severity, 'medium'),
      'description', NEW.description
    ), 'created');
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.trg_examination_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_entity text; v_payload jsonb;
BEGIN
  SELECT COALESCE(name, id::text) INTO v_entity FROM public.licensees WHERE id = NEW.entity_id;
  v_payload := jsonb_build_object(
    'entity_name', COALESCE(v_entity, 'entity'),
    'entity_id', NEW.entity_id,
    'examination_type', NEW.inspection_type,
    'start_date', COALESCE(NEW.scheduled_date, NEW.date_conducted),
    'scope', NEW.scope
  );

  IF COALESCE(NEW.lead_inspector_id, NEW.inspector_id) IS NOT NULL
     AND (TG_OP = 'INSERT'
          OR COALESCE(NEW.lead_inspector_id, NEW.inspector_id)
             IS DISTINCT FROM COALESCE(OLD.lead_inspector_id, OLD.inspector_id)) THEN
    PERFORM public.notification_enqueue_event('prudential.examination_assigned', 'inspection', NEW.id,
      v_payload || jsonb_build_object('assignee_id', COALESCE(NEW.lead_inspector_id, NEW.inspector_id)),
      COALESCE(NEW.lead_inspector_id, NEW.inspector_id)::text);
  END IF;

  IF NEW.status IN ('notified','scheduled','in_progress')
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    PERFORM public.notification_enqueue_event('prudential.examination_notice_issued', 'inspection', NEW.id,
      v_payload, NEW.status);
  END IF;

  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.trg_fp_assessment_committee_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m record; v_payload jsonb;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
  v_payload := jsonb_build_object('assessment_id', NEW.id, 'individual_id', NEW.individual_id,
    'licensee_id', NEW.licensee_id, 'entity_id', NEW.licensee_id, 'committee_id', NEW.committee_id,
    'status', NEW.status, 'assessor_id', NEW.created_by,
    'cta_url', '/fit-and-proper/individuals/' || NEW.individual_id, 'cta_label', 'Open record');

  IF NEW.status = 'awaiting_committee' THEN
    IF NEW.committee_id IS NOT NULL THEN
      FOR m IN SELECT user_id FROM public.fp_committee_members
               WHERE committee_id = NEW.committee_id AND coalesce(is_active,true) LOOP
        PERFORM public.notification_enqueue_event('fp.committee_ready', 'fp_assessment', NEW.id,
          v_payload || jsonb_build_object('member_user_id', m.user_id), m.user_id::text);
      END LOOP;
    ELSE
      PERFORM public.notification_enqueue_event('fp.committee_ready', 'fp_assessment', NEW.id, v_payload, 'no-committee');
    END IF;
  ELSIF NEW.status = 'determined' THEN
    PERFORM public.notification_enqueue_event('fp.committee_decision', 'fp_assessment', NEW.id, v_payload, 'determined');
  END IF;
  RETURN NEW;
END $function$
;
