      v_payload, NEW.id::text);
  ELSIF NEW.status = 'SUBMITTED' AND OLD.status IS DISTINCT FROM 'SUBMITTED' THEN
    PERFORM public.notification_enqueue_event('fp.pq_submitted', 'fp_assessment', NEW.assessment_id,
      v_payload, NEW.id::text);
