CREATE OR REPLACE FUNCTION public.trg_monitoring_rule_first_fired_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_prior integer; v_name text;
BEGIN
  IF NOT coalesce(NEW.matched,false) THEN RETURN NEW; END IF;
  SELECT count(*) INTO v_prior FROM public.conduct_monitoring_results
   WHERE rule_id = NEW.rule_id AND matched AND id <> NEW.id;
  IF coalesce(v_prior,0) > 0 THEN RETURN NEW; END IF;
  SELECT name INTO v_name FROM public.conduct_monitoring_rules WHERE id = NEW.rule_id;
  PERFORM public.notification_enqueue_event('rule.first_fired', 'monitoring_rule', NEW.rule_id,
    jsonb_build_object('rule_id', NEW.rule_id, 'rule_name', v_name,
      'result_id', NEW.id, 'entity_id', NEW.entity_id, 'licensee_id', NEW.entity_id,
      'metrics', NEW.metrics,
      'cta_url', '/conduct/monitoring-rules', 'cta_label', 'Open rules'),
    'first_fired');
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.trg_notification_template_published()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'active' AND (OLD.status IS DISTINCT FROM NEW.status
      OR COALESCE(NEW.published_version, 0) > COALESCE(OLD.published_version, 0)) THEN
    PERFORM public.notification_enqueue_event('notification_template.published', 'notification_template', NEW.id,
      jsonb_build_object(
        'template_name', NEW.name,
        'event_key', NEW.event_key,
        'version', COALESCE(NEW.published_version, NEW.version, 1),
        'actor_name', COALESCE((SELECT COALESCE(full_name, email) FROM public.profiles WHERE id = auth.uid()), 'system')
      ),
      'v' || COALESCE(NEW.published_version, NEW.version, 1)::text);
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.trg_notify_application_ai_overridden()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ref text;
BEGIN
  IF NEW.routing_decision IS DISTINCT FROM OLD.routing_decision
     AND NEW.routing_decision_by IS NOT NULL THEN
    SELECT application_number INTO v_ref FROM public.applications WHERE id = NEW.application_id;
    PERFORM public.notif_enqueue(
      'application.ai_overridden', 'application', NEW.application_id, v_ref,
      '/applications/' || NEW.application_id,
      jsonb_build_object(
        'application_number', v_ref,
        'routing_decision', NEW.routing_decision,
        'reason', coalesce(NEW.routing_decision_reason, NEW.analyst_justification, '')
      ),
      NEW.routing_decision
    );
  END IF;
  RETURN NEW;
END;
$function$
;
