    jsonb_build_object(
      'application_number', coalesce(v_ref, ''), 'amount', NEW.amount,
      'currency', coalesce(NEW.currency, 'JMD'), 'status', NEW.status,
      'receipt_number', coalesce(NEW.receipt_number, ''),
