CREATE OR REPLACE FUNCTION public.trg_prudential_escalation_to_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_ref text;
BEGIN
  IF NEW.escalation_id IS NOT NULL THEN RETURN NEW; END IF;
  SELECT name INTO v_ref FROM public.licensees WHERE id = NEW.entity_id;

  v_id := public.escalation_raise(
    'prudential_supervision',
    'prudential_escalation.' || coalesce(NEW.escalation_type, 'review'),
    'prudential_breach'::public.escalation_type,
    'licensee', NEW.entity_id, v_ref,
    CASE lower(coalesce(NEW.priority,'medium'))
      WHEN 'critical' THEN 'critical' WHEN 'high' THEN 'high'
      WHEN 'low' THEN 'low' ELSE 'medium' END::public.escalation_severity,
    NULL,
    jsonb_build_object('reason', NEW.reason, 'related_type', NEW.related_type,
                       'related_id', NEW.related_id, 'legacy_id', NEW.id),
    NULL);

  NEW.escalation_id := v_id;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_prudential_ratio_autoversion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _next integer;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.formula IS NOT DISTINCT FROM OLD.formula
     AND NEW.display_format IS NOT DISTINCT FROM OLD.display_format THEN
    RETURN NULL;
  END IF;
  SELECT COALESCE(MAX(version),0)+1 INTO _next FROM public.prudential_ratio_versions WHERE ratio_id = NEW.id;
  INSERT INTO public.prudential_ratio_versions(ratio_id, version, formula, display_format, published_by)
    VALUES (NEW.id, _next, NEW.formula, NEW.display_format, auth.uid())
    ON CONFLICT (ratio_id, version) DO NOTHING;
  UPDATE public.prudential_ratios SET current_version = _next WHERE id = NEW.id;
  RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.trg_prudential_threshold_autoversion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _next integer;
BEGIN
  UPDATE public.prudential_threshold_versions
     SET effective_to = GREATEST(current_date - 1, effective_from)
   WHERE threshold_id = NEW.id AND effective_to IS NULL;

  SELECT COALESCE(MAX(version),0)+1 INTO _next
    FROM public.prudential_threshold_versions WHERE threshold_id = NEW.id;

  INSERT INTO public.prudential_threshold_versions(
    threshold_id, version, warn_value, breach_value, upper_value, comparator, unit, effective_from, published_by)
  VALUES (NEW.id, _next, NEW.warn_value, NEW.breach_value, NEW.upper_value, NEW.comparator, NEW.unit,
          COALESCE(NEW.effective_from, current_date), auth.uid());

  UPDATE public.prudential_thresholds SET current_version = _next WHERE id = NEW.id;
  RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.trg_registration_approved_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_portal jsonb;
  v_base text;
  v_login text;
  v_name text;
BEGIN
  IF NEW.status <> 'approved' OR OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;

  SELECT value INTO v_portal FROM public.site_settings WHERE key = 'portal';
  v_base := COALESCE(v_portal->>'base_url', 'https://boj.skntreasury.com');
  v_login := COALESCE(v_portal->>'login_url', v_base || '/login');

  v_name := COALESCE(
    NULLIF(btrim(NEW.applicant_name), ''),
    NULLIF(btrim(NEW.applicant_name_alt), ''),
    NULLIF(btrim(COALESCE(NEW.first_name,'') || ' ' || COALESCE(NEW.last_name,'')), ''),
    'Applicant'
  );

  PERFORM public.notification_enqueue_event('registration.approved', 'registration', NEW.id,
    jsonb_build_object(
      'registration_reference', NEW.registration_reference,
      'applicant_name', v_name,
      'applicant_email', NEW.email,
      'sector_id', NEW.sector_id,
      'portal_url', v_base, 'login_url', v_login,
      'cta_url', v_login, 'cta_label', 'Login'),
    'approved');
  RETURN NEW;
END;
$function$
;
