CREATE OR REPLACE FUNCTION public.trg_role_permissions_action_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Allow reset flow (already validated) to write without re-checking assign.
  IF current_setting('app.rbac_bypass', true) = 'reset' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    PERFORM public.assert_role_management_action('assign_permissions');
    RETURN OLD;
  ELSE
    PERFORM public.assert_role_management_action('assign_permissions');
    RETURN NEW;
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_role_permissions_dependency_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  role_perms uuid[];
  offender record;
BEGIN
  -- Collect the effective permission set for this role AFTER the change.
  IF TG_OP = 'DELETE' THEN
    SELECT array_agg(permission_id) INTO role_perms
      FROM public.role_permissions WHERE role_id = OLD.role_id AND permission_id <> OLD.permission_id;
  ELSE
    SELECT array_agg(permission_id) INTO role_perms
      FROM (
        SELECT permission_id FROM public.role_permissions WHERE role_id = NEW.role_id
        UNION SELECT NEW.permission_id
      ) x;
  END IF;

  IF role_perms IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;

  -- Any dependent action selected must have View on the same module.
  SELECT p.module, p.name INTO offender
    FROM public.permissions p
   WHERE p.id = ANY(role_perms)
     AND lower(p.name) IN (SELECT action FROM public.permission_dependent_actions)
     AND NOT EXISTS (
       SELECT 1 FROM public.permissions v
        WHERE v.id = ANY(role_perms)
          AND lower(v.name) = 'view'
          AND lower(regexp_replace(v.module,'\s+','_','g'))
              = lower(regexp_replace(p.module,'\s+','_','g'))
     )
   LIMIT 1;
  IF offender.module IS NOT NULL THEN
    RAISE EXCEPTION 'permission_dependency_violation: "%" on % requires view on same module',
      offender.name, offender.module USING ERRCODE = '22023';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_roles_action_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.assert_role_management_action('create');
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    PERFORM public.assert_role_management_action('edit');
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM public.assert_role_management_action('delete');
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_roles_block_activate_when_invalid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE first_err record;
BEGIN
  IF NEW.status = 'active' AND (OLD.status IS DISTINCT FROM 'active') AND NEW.scope_config IS NOT NULL THEN
    SELECT * INTO first_err FROM public.validate_scope_config(NEW.scope_config) LIMIT 1;
    IF first_err.module IS NOT NULL THEN
      RAISE EXCEPTION 'cannot activate role: invalid scope_config on module "%": %',
        first_err.module, first_err.error USING ERRCODE = '22023';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_roles_validate_scope_config()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE first_err record;
BEGIN
  IF NEW.scope_config IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT * INTO first_err FROM public.validate_scope_config(NEW.scope_config) LIMIT 1;
  IF first_err.module IS NOT NULL THEN
    RAISE EXCEPTION 'invalid scope_config on module "%": %', first_err.module, first_err.error
      USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_snapshot_return_on_submit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev TEXT;
  v_new TEXT;
  v_reason TEXT;
BEGIN
  v_prev := COALESCE(OLD.workflow_status::text, '');
  v_new := COALESCE(NEW.workflow_status::text, '');
  IF v_new <> 'SUB' OR v_prev = v_new THEN
    RETURN NEW;
  END IF;
  IF v_prev = 'TBR' THEN
    v_reason := 'resubmitted';
  ELSE
    v_reason := 'submitted';
  END IF;
  PERFORM public.snapshot_return_revision(NEW.id, v_reason, v_prev, v_new, NEW.updated_by);
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_source_close_syncs_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_closed boolean;
BEGIN
  IF NEW.escalation_id IS NULL THEN RETURN NEW; END IF;

  v_closed := CASE TG_TABLE_NAME
    WHEN 'complaint_escalation_cases' THEN NEW.status::text IN ('dismissed','escalated','resolved','closed')
    WHEN 'prudential_escalations' THEN NEW.status::text IN ('resolved','closed')
    WHEN 'conduct_alerts' THEN NEW.status::text IN ('closed','dismissed','resolved')
    WHEN 'coordination_escalations' THEN NEW.status::text IN ('resolved','closed')
    ELSE false END;

  IF v_closed THEN
    UPDATE public.escalations
    SET status = 'resolved',
        resolved_at = coalesce(resolved_at, now()),
        resolution_narrative = coalesce(resolution_narrative,
          'Closed in the source module (' || TG_TABLE_NAME || '). See the source record for the full outcome and rationale.'),
        next_auto_escalation_at = NULL
    WHERE id = NEW.escalation_id
      AND status NOT IN ('resolved','closed');
  END IF;

  RETURN NEW;
END;
$function$
;
