CREATE OR REPLACE FUNCTION public.trg_user_role_change_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid;
  v_role text;
  v_change text;
  v_name text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_user := OLD.user_id; v_role := OLD.role::text; v_change := 'removed';
  ELSE
    v_user := NEW.user_id; v_role := NEW.role::text; v_change := 'granted';
  END IF;

  SELECT COALESCE(full_name, email) INTO v_name FROM public.profiles WHERE id = v_user;

  PERFORM public.notification_enqueue_event('user.role_changed', 'profile', v_user,
    jsonb_build_object(
      'target_user_id', v_user,
      'target_user_name', COALESCE(v_name, 'user'),
      'change_summary', v_change || ' ' || v_role,
      'actor_name', COALESCE((SELECT COALESCE(full_name, email) FROM public.profiles WHERE id = auth.uid()), 'system')
    ),
    v_change || ':' || v_role || ':' || to_char(now(), 'YYYYMMDDHH24MI'));

  RETURN COALESCE(NEW, OLD);
END; $function$
;
CREATE OR REPLACE FUNCTION public.trg_validation_rule_autoversion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _next integer; _def jsonb;
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.name IS NOT DISTINCT FROM OLD.name
     AND NEW.scope IS NOT DISTINCT FROM OLD.scope
     AND NEW.rule_type IS NOT DISTINCT FROM OLD.rule_type
     AND NEW.expression IS NOT DISTINCT FROM OLD.expression
     AND NEW.error_message IS NOT DISTINCT FROM OLD.error_message
     AND NEW.severity IS NOT DISTINCT FROM OLD.severity THEN
    RETURN NULL;
  END IF;
  PERFORM set_config('app.version_maintenance','on',true);
  UPDATE public.return_validation_rule_versions SET is_current = false WHERE rule_id = NEW.id AND is_current;
  SELECT COALESCE(MAX(version),0)+1 INTO _next FROM public.return_validation_rule_versions WHERE rule_id = NEW.id;
  SELECT to_jsonb(r.*) INTO _def FROM public.return_validation_rules r WHERE r.id = NEW.id;
  INSERT INTO public.return_validation_rule_versions(rule_id, version, definition, published_by, is_current)
    VALUES (NEW.id, _next, _def, auth.uid(), true)
    ON CONFLICT (rule_id, version) DO NOTHING;
  UPDATE public.return_validation_rules SET current_version = _next WHERE id = NEW.id;
  RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.trg_workflow_published_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_version integer;
BEGIN
  IF NEW.current_published_version_id IS NOT NULL
     AND NEW.current_published_version_id IS DISTINCT FROM OLD.current_published_version_id THEN
    SELECT version_number INTO v_version
      FROM public.approval_workflow_versions WHERE id = NEW.current_published_version_id;
    PERFORM public.notification_enqueue_event('workflow.published', 'approval_workflow', NEW.id,
      jsonb_build_object(
        'workflow_name', NEW.name,
        'entity_type', NEW.entity_type,
        'version', COALESCE(v_version, 1),
        'actor_name', COALESCE((SELECT COALESCE(full_name, email) FROM public.profiles WHERE id = auth.uid()), 'system')
      ),
      NEW.current_published_version_id::text);
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.twinpeaks_raise_disagreement(_application_id uuid, _description text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _row record;
BEGIN
  PERFORM public.enforce_permission('coordination','update');
  IF _description IS NULL OR length(btrim(_description)) < 10 THEN
    RAISE EXCEPTION 'disagreement description must be at least 10 characters' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.twinpeaks_disagreements (application_id, raised_by, description, status)
  VALUES (_application_id, _uid, btrim(_description), 'open') RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'coordination.twinpeaks.disagreement_raised','twinpeaks_disagreement',_row.id,
          jsonb_build_object('application_id',_application_id,'after',jsonb_build_object('status','open')));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.twinpeaks_record_clearance(_application_id uuid, _regulator_role text, _status text, _conditions text[] DEFAULT '{}'::text[], _rationale text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _row record;
BEGIN
  PERFORM public.enforce_permission('coordination','update');
  IF _status NOT IN ('pending','cleared','cleared_with_conditions','objected') THEN
    RAISE EXCEPTION 'invalid clearance status' USING ERRCODE='22023';
  END IF;
  IF _status <> 'pending' AND (_rationale IS NULL OR length(btrim(_rationale)) < 10) THEN
    RAISE EXCEPTION 'clearance rationale must be at least 10 characters' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.twinpeaks_clearances (application_id, regulator_role, status, conditions, rationale, recorded_by, recorded_at)
  VALUES (_application_id, _regulator_role, _status, COALESCE(_conditions,'{}'::text[]), _rationale, _uid, now())
  ON CONFLICT (application_id, regulator_role) DO UPDATE
     SET status = EXCLUDED.status, conditions = EXCLUDED.conditions,
         rationale = EXCLUDED.rationale, recorded_by = EXCLUDED.recorded_by, recorded_at = now()
  RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'coordination.twinpeaks.clearance_recorded','twinpeaks_clearance',_row.id,
          jsonb_build_object('application_id',_application_id,'regulator_role',_regulator_role,
                             'after',jsonb_build_object('status',_status),'justification',_rationale));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.twinpeaks_resolve_disagreement(_disagreement_id uuid, _resolution text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _prev record; _row record;
BEGIN
  PERFORM public.enforce_permission('coordination','update');
  IF _resolution IS NULL OR length(btrim(_resolution)) < 10 THEN
    RAISE EXCEPTION 'resolution must be at least 10 characters' USING ERRCODE='22023';
  END IF;
  SELECT * INTO _prev FROM public.twinpeaks_disagreements WHERE id = _disagreement_id FOR UPDATE;
  IF _prev IS NULL THEN RAISE EXCEPTION 'disagreement not found' USING ERRCODE='22023'; END IF;
  UPDATE public.twinpeaks_disagreements
     SET status = 'resolved', resolution = btrim(_resolution), resolved_by = _uid, resolved_at = now()
   WHERE id = _disagreement_id RETURNING * INTO _row;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (_uid,'coordination.twinpeaks.disagreement_resolved','twinpeaks_disagreement',_disagreement_id,
          jsonb_build_object('before',jsonb_build_object('status',_prev.status),
                             'after',jsonb_build_object('status','resolved'),'justification',btrim(_resolution)));
  RETURN to_jsonb(_row);
END; $function$
;
CREATE OR REPLACE FUNCTION public.update_complaint_severity(_id uuid, _severity text, _reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_current text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF _severity NOT IN ('low','medium','high','critical') THEN
    RAISE EXCEPTION 'Invalid severity: %', _severity USING ERRCODE = '22023';
  END IF;
  IF NOT public.has_complaint_perm(v_uid, 'triage') AND NOT public.has_complaint_perm(v_uid, 'investigate') THEN
    RAISE EXCEPTION 'Not permitted to change severity' USING ERRCODE = '42501';
  END IF;
  SELECT severity INTO v_current FROM public.complaints WHERE id = _id;
  IF v_current IS NULL THEN RAISE EXCEPTION 'Complaint not found' USING ERRCODE = 'P0002'; END IF;
  IF v_current = _severity THEN RETURN; END IF;
  IF _reason IS NULL OR length(trim(_reason)) < 5 THEN
    RAISE EXCEPTION 'Severity override reason (min 5 chars) is required' USING ERRCODE = '22023';
  END IF;
  UPDATE public.complaints
     SET severity = _severity,
         severity_override_reason = _reason,
         severity_overridden_by = v_uid,
         severity_overridden_at = now(),
         updated_at = now()
   WHERE id = _id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'complaint.severity_updated', 'complaint', _id,
          jsonb_build_object('from', v_current, 'to', _severity, 'reason', _reason));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_complaint_severity(_id uuid, _severity text, _reason text, _expected_updated_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_current text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF _severity NOT IN ('low','medium','high','critical') THEN
    RAISE EXCEPTION 'Invalid severity: %', _severity USING ERRCODE = '22023';
  END IF;
  IF NOT public.has_complaint_perm(v_uid, 'triage') AND NOT public.has_complaint_perm(v_uid, 'investigate') THEN
    RAISE EXCEPTION 'Not permitted to change severity' USING ERRCODE = '42501';
  END IF;
  PERFORM public._assert_complaint_fresh(_id, _expected_updated_at);
  SELECT severity INTO v_current FROM public.complaints WHERE id = _id;
  IF v_current IS NULL THEN RAISE EXCEPTION 'Complaint not found' USING ERRCODE = 'P0002'; END IF;
  IF v_current = _severity THEN RETURN; END IF;
  IF _reason IS NULL OR length(trim(_reason)) < 5 THEN
    RAISE EXCEPTION 'Severity override reason (min 5 chars) is required' USING ERRCODE = '22023';
  END IF;
  UPDATE public.complaints
     SET severity = _severity,
         severity_override_reason = _reason,
         severity_overridden_by = v_uid,
         severity_overridden_at = now(),
         updated_at = now()
   WHERE id = _id;
  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'complaint.severity_updated', 'complaint', _id,
          jsonb_build_object('from', v_current, 'to', _severity, 'reason', _reason));
END;
$function$
;
