CREATE OR REPLACE FUNCTION public.user_can_access_document_object(_object_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  rec record;
BEGIN
  IF uid IS NULL THEN
    RETURN false;
  END IF;

  IF public.is_internal_staff(uid) THEN
    RETURN true;
  END IF;

  SELECT uploaded_by, entity_type, entity_id::text AS entity_id
    INTO rec
    FROM public.documents
   WHERE file_path = _object_name
   LIMIT 1;

  IF NOT FOUND THEN
    SELECT uploaded_by, entity_type, entity_id::text AS entity_id
      INTO rec
      FROM public.file_uploads
     WHERE file_path = _object_name
     LIMIT 1;
  END IF;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF rec.uploaded_by = uid THEN
    RETURN true;
  END IF;

  IF rec.entity_type = 'application' AND rec.entity_id IS NOT NULL THEN
    RETURN EXISTS (
      SELECT 1 FROM public.applications
      WHERE id::text = rec.entity_id AND applicant_id = uid
    );
  END IF;

  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.user_can_act_on_workflow_step(_user_id uuid, _step_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_step record;
  v_actor_system_roles text[];
  v_actor_dynamic_role_ids uuid[];
  v_required_role_name text;
  v_required_system_role text;
  v_role_match boolean := false;
  v_role_exact boolean := false;
  v_reason text := 'WRONG_APPROVER';
  v_internal_roles text[] := ARRAY['super_admin','admin','supervisor','licensing_officer','analyst','developer'];
  v_is_internal boolean := false;
  v_allow_equiv boolean := false;
  v_allowed text[];
  v_steps_total int := 0;
  v_current_idx int := 0;
  v_is_last boolean := false;
  v_is_first boolean := false;
  v_can_add_remark boolean := false;
  v_can_reject boolean := false;
  v_can_forward boolean := false;
  v_can_approve boolean := false;
  v_can_send_back boolean := false;
  v_can_escalate boolean := false;
  v_can_request_resubmission boolean := false;
  v_can_return_for_correction boolean := false;
  v_can_request_more_info boolean := false;
  v_cfg_role_ids uuid[];
  v_cfg_user_ids uuid[];
BEGIN
  IF _user_id IS NULL OR _step_id IS NULL THEN
    RETURN jsonb_build_object('can_act', false, 'reason', 'BAD_INPUT', 'deny_reason', 'BAD_INPUT');
  END IF;

  SELECT id, approver_role, approver_role_id, allowed_actions, name, step_order, workflow_id,
         approver_type, approver_config
    INTO v_step FROM public.approval_steps WHERE id = _step_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('can_act', false, 'reason', 'STEP_NOT_FOUND', 'deny_reason', 'STEP_NOT_FOUND');
  END IF;

  SELECT array_agg(DISTINCT r) INTO v_actor_system_roles FROM (
    SELECT role::text AS r FROM public.user_roles WHERE user_id = _user_id
    UNION
    SELECT ro.system_role FROM public.user_dynamic_roles udr
      JOIN public.roles ro ON ro.id = udr.role_id
     WHERE udr.user_id = _user_id AND ro.system_role IS NOT NULL
  ) sub;
  v_actor_system_roles := COALESCE(v_actor_system_roles, ARRAY[]::text[]);

  SELECT array_agg(DISTINCT role_id) INTO v_actor_dynamic_role_ids
    FROM public.user_dynamic_roles WHERE user_id = _user_id;
  v_actor_dynamic_role_ids := COALESCE(v_actor_dynamic_role_ids, ARRAY[]::uuid[]);

  -- `is_internal` is informational ONLY: it grants no decision right, it only
  -- permits a non-decisional remark (save_comment).
  v_is_internal := EXISTS (
    SELECT 1 FROM unnest(v_actor_system_roles) AS r WHERE r = ANY(v_internal_roles)
  );

  v_allow_equiv := COALESCE((v_step.approver_config->>'allow_system_role_equivalence')::boolean, false);

  IF COALESCE(v_step.approver_type, 'role_based_user') = 'specific_users' THEN
    SELECT ARRAY(
      SELECT (value)::uuid FROM jsonb_array_elements_text(
        COALESCE(v_step.approver_config->'user_ids', '[]'::jsonb)
      )
    ) INTO v_cfg_user_ids;
    IF _user_id = ANY(v_cfg_user_ids) THEN
      v_role_match := true; v_role_exact := true; v_reason := 'SPECIFIC_USER_MATCH';
    END IF;
    v_required_role_name := 'specific users';
    v_required_system_role := NULL;
  ELSE
    SELECT ARRAY(
      SELECT (value)::uuid FROM jsonb_array_elements_text(
        COALESCE(v_step.approver_config->'role_ids', '[]'::jsonb)
      )
    ) INTO v_cfg_role_ids;

    IF v_step.approver_role_id IS NOT NULL THEN
      SELECT name, system_role INTO v_required_role_name, v_required_system_role
        FROM public.roles WHERE id = v_step.approver_role_id;
      IF v_step.approver_role_id = ANY(v_actor_dynamic_role_ids) THEN
        v_role_match := true; v_role_exact := true; v_reason := 'DYNAMIC_ROLE_MATCH';
      ELSIF v_allow_equiv
         AND v_required_system_role IS NOT NULL
         AND v_required_system_role = ANY(v_actor_system_roles) THEN
        v_role_match := true; v_reason := 'SYSTEM_ROLE_EQUIVALENT_MATCH';
      END IF;
    ELSE
      v_required_role_name := v_step.approver_role::text;
      v_required_system_role := v_step.approver_role::text;
      IF v_step.approver_role::text = ANY(v_actor_system_roles) THEN
        v_role_match := true; v_role_exact := true; v_reason := 'LEGACY_SYSTEM_ROLE_MATCH';
      END IF;
    END IF;

    IF NOT v_role_match AND array_length(v_cfg_role_ids, 1) > 0 THEN
      IF EXISTS (
        SELECT 1 FROM unnest(v_cfg_role_ids) AS rid
        WHERE rid = ANY(v_actor_dynamic_role_ids)
      ) THEN
        v_role_match := true; v_role_exact := true; v_reason := 'CFG_ROLE_MATCH';
      ELSIF v_allow_equiv AND EXISTS (
        SELECT 1 FROM public.roles ro
        WHERE ro.id = ANY(v_cfg_role_ids)
          AND ro.system_role IS NOT NULL
          AND ro.system_role = ANY(v_actor_system_roles)
      ) THEN
        v_role_match := true; v_reason := 'CFG_ROLE_SYSTEM_MATCH';
      END IF;
    END IF;
  END IF;

  IF NOT v_role_match AND 'super_admin' = ANY(v_actor_system_roles) THEN
    v_role_match := true; v_reason := 'SUPER_ADMIN_OVERRIDE';
  END IF;

  SELECT count(*),
         (SELECT count(*) FROM public.approval_steps s2
          WHERE s2.workflow_id = v_step.workflow_id AND s2.step_order < v_step.step_order)
    INTO v_steps_total, v_current_idx
    FROM public.approval_steps WHERE workflow_id = v_step.workflow_id;
  v_is_first := (v_current_idx = 0);
  v_is_last  := (v_steps_total > 0 AND v_current_idx = v_steps_total - 1);

  v_allowed := ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_step.allowed_actions, '[]'::jsonb)));

  v_can_add_remark := v_is_internal;
  IF v_role_match THEN
    v_can_reject := ('reject' = ANY(v_allowed));
    IF 'approve' = ANY(v_allowed) THEN
      IF v_is_last THEN v_can_approve := true; ELSE v_can_forward := true; END IF;
    END IF;
    v_can_send_back := ('send_back' = ANY(v_allowed));
    v_can_escalate := (NOT v_is_last) AND ('escalate' = ANY(v_allowed));
    v_can_request_resubmission := ('request_resubmission' = ANY(v_allowed));
    v_can_return_for_correction := ('return_for_correction' = ANY(v_allowed));
    v_can_request_more_info := ('request_more_info' = ANY(v_allowed));
  END IF;

  RETURN jsonb_build_object(
    'can_act', v_role_match,
    'reason', v_reason,
    'deny_reason', CASE WHEN v_role_match THEN NULL ELSE 'WRONG_APPROVER' END,
    'role_exact', v_role_exact,
    'is_internal', v_is_internal,
    'approver_type', COALESCE(v_step.approver_type, 'role_based_user'),
    'required_role_name', v_required_role_name,
    'required_system_role', v_required_system_role,
    'actor_system_roles', to_jsonb(v_actor_system_roles),
    'is_first', v_is_first,
    'is_last', v_is_last,
    'allowed_actions', to_jsonb(v_allowed),
    'can_add_remark', v_can_add_remark,
    'can_reject', v_can_reject,
    'can_forward', v_can_forward,
    'can_approve', v_can_approve,
    'can_send_back', v_can_send_back,
    'can_escalate', v_can_escalate,
    'can_request_resubmission', v_can_request_resubmission,
    'can_return_for_correction', v_can_return_for_correction,
    'can_request_more_info', v_can_request_more_info
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.user_can_upload_document_object(_object_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  parts text[];
  top text;
  is_internal boolean;
  is_super boolean;
  v_entity_id uuid;
  v_entity_type text;
BEGIN
  IF uid IS NULL OR _object_name IS NULL OR length(_object_name) = 0 THEN
    RETURN false;
  END IF;

  parts := storage.foldername(_object_name);
  IF parts IS NULL OR array_length(parts, 1) IS NULL OR array_length(parts, 1) < 1 THEN
    -- Files at the bucket root are never allowed.
    RETURN false;
  END IF;

  top := parts[1];

  is_super := public.has_role(uid, 'super_admin'::app_role);
  is_internal := is_super
              OR public.has_role(uid, 'admin'::app_role)
              OR public.has_role(uid, 'supervisor'::app_role)
              OR public.has_role(uid, 'licensing_officer'::app_role)
              OR public.has_role(uid, 'analyst'::app_role);

  -- 1) Self folder: any authenticated user may upload under their own UID.
  --    Applicants are restricted to this branch only.
  IF top = uid::text THEN
    RETURN true;
  END IF;

  -- Beyond this point, only internal users can proceed.
  IF NOT is_internal THEN
    RETURN false;
  END IF;

  -- 2) applications/<application_id>/... — application must exist.
  IF top = 'applications' AND array_length(parts, 1) >= 2 THEN
    BEGIN
      v_entity_id := parts[2]::uuid;
    EXCEPTION WHEN OTHERS THEN
      RETURN false;
    END;
    RETURN EXISTS (SELECT 1 FROM public.applications WHERE id = v_entity_id);
  END IF;

  -- 3) entities/<entity_type>/<entity_id>/... — known entity type + valid uuid.
  IF top = 'entities' AND array_length(parts, 1) >= 3 THEN
    v_entity_type := parts[2];
    BEGIN
      v_entity_id := parts[3]::uuid;
    EXCEPTION WHEN OTHERS THEN
      RETURN false;
    END;
    IF v_entity_type NOT IN ('application','license','licensee','complaint','return','inspection','enforcement') THEN
      RETURN false;
    END IF;
    RETURN true;
  END IF;

  -- 4) reviewers/<reviewer_uid>/... — only own folder, super-admin exempt.
  IF top = 'reviewers' AND array_length(parts, 1) >= 2 THEN
    BEGIN
      v_entity_id := parts[2]::uuid;
    EXCEPTION WHEN OTHERS THEN
      RETURN false;
    END;
    RETURN v_entity_id = uid OR is_super;
  END IF;

  -- Anything else is rejected.
  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.user_has_entity_assignment(_user_id uuid, _licensee_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT _user_id IS NOT NULL AND _licensee_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.licensees l
    WHERE l.id = _licensee_id
      AND (
        l.lead_regulator_id = _user_id
        OR l.regulator_officer_id = _user_id
        OR l.alternate_regulator_id = _user_id
      )
  );
$function$
;
CREATE OR REPLACE FUNCTION public.user_has_permission(_user_id uuid, _module text, _action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_has_dynamic boolean;
  v_match boolean;
BEGIN
  IF _user_id IS NULL THEN
    RETURN false;
  END IF;
  IF public.has_role(_user_id, 'super_admin'::app_role) THEN
    RETURN true;
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.user_dynamic_roles WHERE user_id = _user_id) INTO v_has_dynamic;
  IF NOT v_has_dynamic THEN
    RETURN public.has_role(_user_id, 'admin'::app_role);
  END IF;
  SELECT EXISTS (
    SELECT 1
    FROM public.user_dynamic_roles udr
    JOIN public.role_permissions rp ON rp.role_id = udr.role_id
    JOIN public.permissions p ON p.id = rp.permission_id
    WHERE udr.user_id = _user_id
      AND lower(regexp_replace(coalesce(p.module,''), '\s+', '_', 'g')) = lower(regexp_replace(coalesce(_module,''), '\s+', '_', 'g'))
      AND lower(coalesce(p.name,'')) = lower(coalesce(_action,''))
  ) INTO v_match;
  RETURN v_match;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.user_licensee_id(_user_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT licensee_id FROM public.profiles WHERE id = _user_id
$function$
;
CREATE OR REPLACE FUNCTION public.user_scope_for(_user_id uuid, _module text, _action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  has_all boolean := false;
  sectors_agg text[] := '{}';
  licensees_agg text[] := '{}';
  has_assigned boolean := false;
  has_own boolean := false;
  qualified boolean := false;
  rec record; sc jsonb; s text;
BEGIN
  IF _user_id IS NULL THEN
    RETURN jsonb_build_object('scope','none','source','anonymous');
  END IF;
  IF public.is_super_admin(_user_id) THEN
    RETURN jsonb_build_object('scope','all','source','super_admin');
  END IF;

  FOR rec IN
    SELECT r.id AS role_id,
           COALESCE(st.key, 'all') AS scope_key,
           rs.id AS role_scope_id
    FROM public.sec_user_roles ur
    JOIN public.sec_roles r ON r.id = ur.role_id
    JOIN public.sec_role_permissions rp ON rp.role_id = r.id
    JOIN public.sec_permissions p ON p.id = rp.permission_id
    JOIN public.sec_modules m ON m.id = p.module_id
    LEFT JOIN public.sec_role_scopes rs ON rs.role_id = r.id AND rs.module_id = m.id
    LEFT JOIN public.sec_scope_types st ON st.id = rs.scope_type_id
    WHERE ur.user_id = _user_id
      AND COALESCE(ur.status,'active') = 'active'
      AND (ur.effective_from IS NULL OR ur.effective_from <= now())
      AND (ur.effective_until IS NULL OR ur.effective_until >= now())
      AND COALESCE(r.status,'active') = 'active'
      AND lower(m.key) = lower(_module)
      AND lower(p.key) = lower(_action)
  LOOP
    qualified := true;
    s := rec.scope_key;
    IF s = 'all' THEN has_all := true;
    ELSIF s = 'sector' THEN
      sectors_agg := sectors_agg || COALESCE(ARRAY(
        SELECT COALESCE(v.value_id::text, v.value_text)
        FROM public.sec_role_scope_values v
        WHERE v.role_scope_id = rec.role_scope_id), '{}');
    ELSIF s = 'institution' THEN
      licensees_agg := licensees_agg || COALESCE(ARRAY(
        SELECT COALESCE(v.value_id::text, v.value_text)
        FROM public.sec_role_scope_values v
        WHERE v.role_scope_id = rec.role_scope_id), '{}');
    ELSIF s = 'assigned' THEN has_assigned := true;
    ELSIF s = 'own' THEN has_own := true;
    END IF;
  END LOOP;

  IF NOT qualified THEN
    FOR rec IN
      SELECT r.id, r.scope_config
      FROM public.user_dynamic_roles udr
      JOIN public.roles r ON r.id = udr.role_id
      JOIN public.role_permissions rp ON rp.role_id = r.id
      JOIN public.permissions p ON p.id = rp.permission_id
      WHERE udr.user_id = _user_id
        AND COALESCE(r.status,'active') = 'active'
        AND lower(regexp_replace(p.module,'\s+','_','g')) = lower(_module)
        AND lower(p.name) = lower(_action)
      GROUP BY r.id, r.scope_config
    LOOP
      qualified := true;
      sc := rec.scope_config -> _module;
      IF sc IS NULL THEN has_all := true; CONTINUE; END IF;
      s := COALESCE(sc ->> 'scope', 'all');
      IF s = 'all' THEN has_all := true;
      ELSIF s = 'sector' THEN
        sectors_agg := sectors_agg || COALESCE(ARRAY(SELECT jsonb_array_elements_text(sc -> 'sectors')), '{}');
      ELSIF s = 'institution' THEN
        licensees_agg := licensees_agg || COALESCE(ARRAY(SELECT jsonb_array_elements_text(sc -> 'licensees')), '{}');
      ELSIF s = 'assigned' THEN has_assigned := true;
      ELSIF s = 'own' THEN has_own := true;
      END IF;
    END LOOP;
  END IF;

  IF NOT qualified THEN RETURN jsonb_build_object('scope','none','source','no_qualifying_role'); END IF;
  IF has_all THEN RETURN jsonb_build_object('scope','all','source','role_grant'); END IF;
  IF array_length(sectors_agg,1) > 0 THEN
    RETURN jsonb_build_object('scope','sector',
      'sectors', to_jsonb(ARRAY(SELECT DISTINCT unnest(sectors_agg))), 'source','role_grant');
  END IF;
  IF array_length(licensees_agg,1) > 0 THEN
    RETURN jsonb_build_object('scope','institution',
      'licensees', to_jsonb(ARRAY(SELECT DISTINCT unnest(licensees_agg))), 'source','role_grant');
  END IF;
  IF has_assigned THEN RETURN jsonb_build_object('scope','assigned','source','role_grant'); END IF;
  IF has_own THEN RETURN jsonb_build_object('scope','own','source','role_grant'); END IF;
  RETURN jsonb_build_object('scope','none','source','unbacked_scope_only');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.user_workflow_role_slugs(_user uuid)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH legacy AS (
    SELECT ur.role::text AS slug FROM public.user_roles ur WHERE ur.user_id = _user
  ), dyn AS (
    SELECT regexp_replace(lower(r.name), '[^a-z0-9]+', '_', 'g') AS slug, r.name AS rname
    FROM public.user_dynamic_roles udr
    JOIN public.roles r ON r.id = udr.role_id
    WHERE udr.user_id = _user
  ), base AS (
    SELECT slug FROM legacy
    UNION SELECT slug FROM dyn
  ), flags AS (
    SELECT
      EXISTS (SELECT 1 FROM legacy WHERE slug IN ('super_admin','admin'))
      OR EXISTS (SELECT 1 FROM dyn WHERE rname IN ('System Administrator','Legacy Admin','Super Admin')) AS is_admin,
      EXISTS (SELECT 1 FROM legacy WHERE slug NOT IN ('applicant','pre_licensee','licensee_primary','licensee_secondary'))
      OR EXISTS (SELECT 1 FROM dyn WHERE rname NOT IN ('Applicant','Regulated Entity User','Consumer / Complainant')) AS is_internal
  )
  SELECT COALESCE(array_agg(DISTINCT s), ARRAY[]::text[]) FROM (
    SELECT slug AS s FROM base
    UNION SELECT 'admin' WHERE (SELECT is_admin FROM flags)
    UNION SELECT 'regulator' WHERE (SELECT is_internal FROM flags)
  ) x WHERE s IS NOT NULL;
$function$
;
CREATE OR REPLACE FUNCTION public.validate_approval_step_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role record;
  v_existing_role_ids jsonb;
BEGIN
  -- Specific-users steps don't need a role; approver_config carries user_ids.
  IF COALESCE(NEW.approver_type, 'role_based_user') = 'specific_users' THEN
    RETURN NEW;
  END IF;

  IF NEW.approver_role_id IS NULL THEN
    RAISE EXCEPTION 'APPROVER_ROLE_ID_REQUIRED: approval steps must reference a configured role (roles.id)'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT id, name, is_system, system_role INTO v_role
    FROM public.roles WHERE id = NEW.approver_role_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'APPROVER_ROLE_NOT_FOUND: roles.id=% does not exist', NEW.approver_role_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  IF v_role.system_role IS NOT NULL THEN
    NEW.approver_role := v_role.system_role::public.app_role;
  END IF;

  v_existing_role_ids := COALESCE(
    (
      SELECT jsonb_agg(x)
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(NEW.approver_config->'role_ids') = 'array' THEN NEW.approver_config->'role_ids'
          ELSE '[]'::jsonb
        END
      ) AS ids(x)
      WHERE x <> NEW.approver_role_id::text
        AND EXISTS (SELECT 1 FROM public.roles r WHERE r.id::text = x)
    ),
    '[]'::jsonb
  );

  NEW.approver_config := jsonb_set(
    COALESCE(NULLIF(NEW.approver_config, 'null'::jsonb), '{}'::jsonb),
    '{role_ids}',
    jsonb_build_array(NEW.approver_role_id::text) || v_existing_role_ids,
    true
  );

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.validate_approval_workflow_entity_type()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_type record;
BEGIN
  SELECT key, is_active
    INTO v_type
    FROM public.approval_workflow_types
   WHERE key = NEW.entity_type;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unknown approval workflow type: %', NEW.entity_type
      USING ERRCODE = '23503';
  END IF;

  IF NEW.is_active AND NOT v_type.is_active THEN
    RAISE EXCEPTION 'Approval workflow type "%" is inactive and cannot be assigned to an active workflow', NEW.entity_type
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.validate_form_version_effective_dates()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.effective_from IS NOT NULL
     AND NEW.effective_until IS NOT NULL
     AND NEW.effective_until < NEW.effective_from THEN
    RAISE EXCEPTION 'FORM_VERSION_INVALID_EFFECTIVE_RANGE'
      USING MESSAGE = 'effective_until cannot be before effective_from';
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.validate_notification_preferences()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  k text;
  v jsonb;
BEGIN
  FOR k, v IN SELECT key, value FROM jsonb_each(COALESCE(NEW.type_settings, '{}'::jsonb)) LOOP
    IF (v->>'severity') IN ('critical','high')
       AND COALESCE(v->>'digest','immediate') <> 'immediate' THEN
      RAISE EXCEPTION 'digest_not_permitted_for_high_severity: %', k;
    END IF;
    IF (v->>'severity') IN ('critical','high') AND COALESCE((v->>'in_app')::boolean, true) = false THEN
      RAISE EXCEPTION 'in_app_required_for_high_severity: %', k;
    END IF;
  END LOOP;
  NEW.updated_at := now();
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.validate_notification_recipient_config(_recipient_type text, _recipient_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE _cfg jsonb := coalesce(_recipient_config, '{}'::jsonb);
DECLARE _txt text;
BEGIN
  IF _recipient_type = 'custom_email' THEN
    _txt := lower(btrim(coalesce(_cfg->>'email','')));
    IF _txt = '' THEN
      RAISE EXCEPTION 'Custom email recipient requires an email address' USING ERRCODE='22023';
    END IF;
    IF _txt !~ '^[^@[:space:]]+@[^@[:space:]]+\.[a-z]{2,}$' THEN
      RAISE EXCEPTION 'Custom email recipient address is not a valid email' USING ERRCODE='22023';
    END IF;
    _cfg := _cfg || jsonb_build_object('email', _txt);

  ELSIF _recipient_type = 'role' THEN
    _txt := btrim(coalesce(_cfg->>'role', _cfg->>'role_name',''));
    IF _txt = '' AND nullif(_cfg->>'role_id','') IS NULL THEN
      RAISE EXCEPTION 'Role recipient requires a role selection' USING ERRCODE='22023';
    END IF;
    -- Prefer stable role identity: resolve a name to its role_id when unambiguous.
    IF nullif(_cfg->>'role_id','') IS NULL AND _txt <> '' THEN
      _cfg := _cfg || jsonb_build_object('role', _txt, 'role_name', _txt);
    END IF;

  ELSIF _recipient_type = 'named_user' THEN
    IF nullif(_cfg->>'user_id','') IS NULL
       AND coalesce(jsonb_array_length(_cfg->'user_ids'),0) = 0 THEN
      RAISE EXCEPTION 'Named user recipient requires a user selection' USING ERRCODE='22023';
    END IF;
  END IF;

  RETURN _cfg;
END $function$
;
CREATE OR REPLACE FUNCTION public.validate_scope_config(_scope_config jsonb)
 RETURNS TABLE(module text, error text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  mod text; entry jsonb; kind text; sels jsonb;
  ok_kind boolean; bad_ids uuid[];
BEGIN
  IF _scope_config IS NULL OR jsonb_typeof(_scope_config) <> 'object' THEN RETURN; END IF;
  FOR mod, entry IN SELECT k, v FROM jsonb_each(_scope_config) AS t(k,v) LOOP
    IF jsonb_typeof(entry) <> 'object' THEN
      module := mod; error := 'scope entry must be an object'; RETURN NEXT; CONTINUE;
    END IF;
    kind := entry ->> 'scope';
    IF kind IS NULL THEN
      module := mod; error := 'scope kind missing'; RETURN NEXT; CONTINUE;
    END IF;
    SELECT EXISTS(SELECT 1 FROM public.rbac_module_scopes s WHERE s.module = mod AND s.scope = kind) INTO ok_kind;
    IF NOT ok_kind THEN
      module := mod; error := format('scope kind "%s" not supported for module %s', kind, mod); RETURN NEXT; CONTINUE;
    END IF;

    IF kind = 'institution' THEN
      sels := entry -> 'licensees';
      IF sels IS NULL OR jsonb_typeof(sels) <> 'array' OR jsonb_array_length(sels) = 0 THEN
        module := mod; error := 'institution scope requires at least one licensee id'; RETURN NEXT;
      ELSE
        SELECT array_agg(v::uuid) INTO bad_ids
        FROM jsonb_array_elements_text(sels) AS v
        WHERE NOT EXISTS (SELECT 1 FROM public.licensees l WHERE l.id = v::uuid);
        IF bad_ids IS NOT NULL AND array_length(bad_ids,1) > 0 THEN
          module := mod; error := 'unknown licensee id(s): ' || bad_ids::text; RETURN NEXT;
        END IF;
      END IF;
    ELSIF kind = 'sector' THEN
      sels := entry -> 'sectors';
      IF sels IS NULL OR jsonb_typeof(sels) <> 'array' OR jsonb_array_length(sels) = 0 THEN
        module := mod; error := 'sector scope requires at least one sector id'; RETURN NEXT;
      ELSE
        SELECT array_agg(v::uuid) INTO bad_ids
        FROM jsonb_array_elements_text(sels) AS v
        WHERE NOT EXISTS (SELECT 1 FROM public.sectors s WHERE s.id = v::uuid);
        IF bad_ids IS NOT NULL AND array_length(bad_ids,1) > 0 THEN
          module := mod; error := 'unknown sector id(s): ' || bad_ids::text; RETURN NEXT;
        END IF;
      END IF;
    END IF;
  END LOOP;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.validate_stress_indicator_taxonomy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.taxonomy_code IS NOT NULL AND NEW.taxonomy_code <> '' THEN
    IF NOT EXISTS (SELECT 1 FROM public.prudential_risk_taxonomy t WHERE t.code = NEW.taxonomy_code) THEN
      RAISE EXCEPTION 'Unknown risk taxonomy code: %', NEW.taxonomy_code
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.validate_user_event_preference()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  cfg record;
  sev public.notification_severity;
BEGIN
  SELECT severity, allow_mute, system_required, channels, is_active INTO cfg
  FROM public.notification_event_configs WHERE event_key = NEW.event_key LIMIT 1;

  sev := COALESCE(cfg.severity, public.notification_severity_for(NEW.event_key, NULL));

  IF COALESCE(cfg.system_required, false) THEN
    IF NEW.in_app_enabled = false OR NEW.email_enabled = false OR NEW.muted THEN
      RAISE EXCEPTION 'system_required_notification_cannot_be_disabled: %', NEW.event_key;
    END IF;
  END IF;

  IF sev = 'critical' AND NEW.in_app_enabled = false THEN
    RAISE EXCEPTION 'in_app_required_for_critical: %', NEW.event_key;
  END IF;

  IF sev IN ('critical','high') AND NEW.digest_frequency <> 'immediate' THEN
    RAISE EXCEPTION 'digest_not_permitted_for_high_severity: %', NEW.event_key;
  END IF;

  IF NEW.muted AND (sev <> 'low' OR COALESCE(cfg.allow_mute, true) = false) THEN
    RAISE EXCEPTION 'mute_not_permitted_for_event: %', NEW.event_key;
  END IF;

  -- SMS may not be enabled while no provider is configured
  IF NEW.sms_enabled AND NOT public.notification_sms_available() THEN
    RAISE EXCEPTION 'sms_channel_unavailable: %', NEW.event_key;
  END IF;

  -- Channels the event does not support cannot be enabled
  IF cfg.channels IS NOT NULL THEN
    IF NEW.sms_enabled AND NOT ('sms' = ANY (cfg.channels)) THEN
      RAISE EXCEPTION 'channel_not_supported_for_event: sms/%', NEW.event_key;
    END IF;
    IF NEW.email_enabled AND NOT ('email' = ANY (cfg.channels)) THEN
      RAISE EXCEPTION 'channel_not_supported_for_event: email/%', NEW.event_key;
    END IF;
  END IF;

  -- Preferences only ever affect future dispatches
  NEW.effective_from := GREATEST(COALESCE(NEW.effective_from, now()), now());
  NEW.updated_at := now();
  NEW.updated_by := COALESCE(NEW.updated_by, auth.uid());
  RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.verify_declaration_identity(p_token text, p_dob text, p_last4id text)
 RETURNS TABLE(verified boolean, invitation_id uuid, assessment_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hash  text := encode(sha256(p_token::bytea), 'hex');
  v_vhash text := encode(sha256((p_dob || '|' || upper(p_last4id))::bytea), 'hex');
  v_inv   public.declaration_invitations%ROWTYPE;
BEGIN
  SELECT * INTO v_inv FROM public.declaration_invitations WHERE token_hash = v_hash;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::uuid, NULL::uuid;
    RETURN;
  END IF;

  -- Block expired, locked-out, or already-submitted invitations
  IF v_inv.expires_at < now()
     OR v_inv.failed_identity_attempts >= 5
     OR v_inv.status IN ('SUBMITTED', 'EXPIRED') THEN
    RETURN QUERY SELECT false, NULL::uuid, NULL::uuid;
    RETURN;
  END IF;

  -- Accept either identity document's hash — national ID or passport.
  IF v_inv.verification_hash = v_vhash
     OR (v_inv.verification_hash_alt IS NOT NULL AND v_inv.verification_hash_alt = v_vhash) THEN
    UPDATE public.declaration_invitations
    SET    status    = CASE WHEN status IN ('PENDING','SENT','RESENT') THEN 'OPENED' ELSE status END,
           opened_at = COALESCE(opened_at, now())
    WHERE  id = v_inv.id;
    RETURN QUERY SELECT true, v_inv.id, v_inv.assessment_id;
  ELSE
    UPDATE public.declaration_invitations
    SET    failed_identity_attempts = failed_identity_attempts + 1
    WHERE  id = v_inv.id;
    RETURN QUERY SELECT false, NULL::uuid, NULL::uuid;
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.verify_offline_payment(_payment_id uuid, _approve boolean, _remarks text DEFAULT NULL::text, _fee_breakdown jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_pay record;
  v_prev_status text;
  v_prev_verification text;
  v_proof_count integer := 0;
  v_invoice jsonb := NULL;
BEGIN
  IF v_uid IS NULL OR NOT (public.has_role(v_uid,'super_admin'::app_role) OR public.has_role(v_uid,'admin'::app_role)) THEN
    RETURN jsonb_build_object('ok', false, 'code','FORBIDDEN','message','Only regulators can verify offline payments.');
  END IF;

  SELECT * INTO v_pay FROM public.payments WHERE id = _payment_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code','NOT_FOUND','message','Payment not found.');
  END IF;
  IF v_pay.payment_channel <> 'offline' THEN
    RETURN jsonb_build_object('ok', false, 'code','INVALID','message','Only offline payments require verification.');
  END IF;
  IF v_pay.verification_status IS DISTINCT FROM 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'code','ALREADY_REVIEWED',
      'verification_status', v_pay.verification_status, 'message','This payment has already been reviewed.');
  END IF;
  IF NOT _approve AND (_remarks IS NULL OR length(TRIM(_remarks)) < 10) THEN
    RETURN jsonb_build_object('ok', false, 'code','INVALID','message','Provide a rejection reason (min 10 characters).');
  END IF;

  IF _approve AND COALESCE(v_pay.offline_method,'') IN ('bank_transfer','cheque','manager_cheque','demand_draft') THEN
    SELECT count(*) INTO v_proof_count FROM public.payment_attachments WHERE payment_id = _payment_id;
    IF v_proof_count = 0 THEN
      RETURN jsonb_build_object('ok', false, 'code','PROOF_REQUIRED',
        'message','Proof of payment must be attached before this payment can be approved.');
    END IF;
  END IF;

  v_prev_status := v_pay.status;
  v_prev_verification := v_pay.verification_status;

  UPDATE public.payments
     SET status = CASE WHEN _approve THEN 'completed' ELSE 'rejected' END,
         verification_status = CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,
         paid_at = CASE WHEN _approve THEN COALESCE(paid_at, now()) ELSE paid_at END,
         verified_by = v_uid,
         verified_at = now(),
         verification_remarks = NULLIF(TRIM(COALESCE(_remarks,'')),'')
   WHERE id = _payment_id
   RETURNING * INTO v_pay;

  IF _approve THEN
    v_invoice := public.issue_payment_invoice(_payment_id, _fee_breakdown, 0);
  END IF;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value)
  VALUES (v_uid,
          CASE WHEN _approve THEN 'offline_payment_approved' ELSE 'offline_payment_rejected' END,
          'payment', _payment_id,
          jsonb_build_object('status', v_prev_status, 'verification_status', v_prev_verification),
          jsonb_build_object('status', v_pay.status, 'verification_status', v_pay.verification_status,
                             'remarks', NULLIF(TRIM(COALESCE(_remarks,'')),''),
                             'invoice_number', v_invoice->>'invoice_number'));

  RETURN jsonb_build_object('ok', true, 'payment_id', _payment_id,
    'status', v_pay.status, 'verification_status', v_pay.verification_status, 'invoice', v_invoice);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.wave_b_integrity_report()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'generated_at', now(),
    'forms_without_purpose', (SELECT count(*) FROM public.form_templates WHERE form_purpose_id IS NULL),
    'forms_without_lifecycle', (SELECT count(*) FROM public.form_templates t
        WHERE NOT EXISTS (SELECT 1 FROM public.form_lifecycle_applicability l WHERE l.template_id = t.id)),
    'forms_without_domain', (SELECT count(*) FROM public.form_templates t
        WHERE NOT EXISTS (SELECT 1 FROM public.form_data_domains d WHERE d.template_id = t.id)),
    'legacy_mapping', (SELECT jsonb_object_agg(legacy_mapping_status, c) FROM
        (SELECT legacy_mapping_status, count(*) c FROM public.form_templates GROUP BY 1) s),
    'unmapped_logical_fields', (SELECT count(*) FROM public.form_fields WHERE form_field_definition_id IS NULL),
    'field_definitions_without_concept', (SELECT count(*) FROM public.form_field_definitions WHERE data_concept_id IS NULL),
    'duplicate_field_names_in_version', (SELECT count(*) FROM
        (SELECT version_id, field_name FROM public.form_fields WHERE field_name IS NOT NULL
          GROUP BY 1,2 HAVING count(*) > 1) d),
    'submissions_without_version', (SELECT count(*) FROM public.form_responses WHERE version_id IS NULL),
    'applications_without_pinned_version', (SELECT count(*) FROM public.applications a
        WHERE a.submitted_at IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM public.application_form_requirements r WHERE r.application_id = a.id)),
    'requirements_without_version', (SELECT count(*) FROM public.application_form_requirements WHERE form_version_id IS NULL),
    'packages_with_unpublished_forms', (SELECT count(DISTINCT i.package_id) FROM public.form_package_items i
        WHERE NOT EXISTS (SELECT 1 FROM public.form_versions v
                           WHERE v.template_id = i.template_id AND v.status = 'published')),
    'packages_without_applicability', (SELECT count(*) FROM public.form_packages p
        WHERE NOT EXISTS (SELECT 1 FROM public.form_applicability_rules r WHERE r.package_id = p.id)),
    'ownership_via_generic_relationships', (SELECT count(*) FROM public.entity_relationships
        WHERE COALESCE(ownership_percentage,0) > 0),
    'ownership_interests_current', (SELECT count(*) FROM public.ownership_interests WHERE effective_to IS NULL),
    'appointments_current', (SELECT count(*) FROM public.entity_appointments WHERE effective_to IS NULL),
    'fp_individuals_unlinked', (SELECT count(*) FROM public.fp_individuals f
        WHERE NOT EXISTS (SELECT 1 FROM public.fp_individual_party_links l WHERE l.fp_individual_id = f.id)),
    'change_sets_stale_pending', (SELECT count(*) FROM public.entity_change_sets cs
        JOIN public.licensees l ON l.id = cs.entity_id
       WHERE cs.status IN ('SUBMITTED','UNDER_REVIEW','RECOMMENDED','APPROVED')
         AND cs.baseline_version <> l.structure_version),
    'concepts_without_domain', (SELECT count(*) FROM public.data_concepts WHERE data_domain_id IS NULL)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.wb_entity_member(_entity_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.entity_user_memberships m
     WHERE m.entity_id = _entity_id AND m.user_id = auth.uid()
       AND upper(COALESCE(m.status,'')) = 'APPROVED'
  );
$function$
;
CREATE OR REPLACE FUNCTION public.wb_grant_template(_template_key text, _perms text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tpl uuid; v_p text;
BEGIN
  SELECT id INTO v_tpl FROM public.sec_role_templates WHERE key = _template_key;
  IF v_tpl IS NULL THEN RETURN; END IF;
  FOREACH v_p IN ARRAY _perms LOOP
    INSERT INTO public.sec_role_template_permissions (template_id, permission_id)
    SELECT v_tpl, p.id FROM public.sec_permissions p JOIN public.sec_modules m ON m.id = p.module_id
     WHERE m.key = split_part(v_p,'.',1) AND p.key = split_part(v_p,'.',2)
       AND NOT EXISTS (SELECT 1 FROM public.sec_role_template_permissions x
                        WHERE x.template_id = v_tpl AND x.permission_id = p.id);
  END LOOP;
END $function$
;
CREATE OR REPLACE FUNCTION public.wb_membership_capability(_entity_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.entity_user_memberships m
      JOIN public.entity_membership_role_permissions c ON c.membership_role_id = m.membership_role_id
     WHERE m.entity_id = _entity_id AND m.user_id = auth.uid()
       AND upper(COALESCE(m.status,'')) = 'APPROVED'
       AND c.capability = _capability);
$function$
;
CREATE OR REPLACE FUNCTION public.wb_onboarding_provision_entity(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  v_name text := btrim(COALESCE(_payload->>'legal_name',''));
  v_entity uuid;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  IF v_name = '' THEN RAISE EXCEPTION 'legal_name is required' USING ERRCODE='22023'; END IF;

  v_entity := public.entity_create_local(
    v_name,
    COALESCE(_payload->'identifiers','[]'::jsonb),
    NULLIF(_payload->>'sector_id','')::uuid,
    COALESCE(NULLIF(_payload->>'lifecycle_key',''), 'pre_authorisation'),
    COALESCE(NULLIF(_payload->>'identity_status_key',''), 'provisional'),
    NULLIF(_payload->>'case_id','')::uuid
  );

  PERFORM public.create_audit_log(uid, 'entity.onboarding.provisioned', 'licensee', v_entity::text,
    NULL, jsonb_build_object('legal_name', v_name, 'origin','public_onboarding'), '{}'::jsonb);

  RETURN jsonb_build_object('entity_id', v_entity, 'outcome', 'PROVISIONED');
END $function$
;
CREATE OR REPLACE FUNCTION public.wb_require(_module text, _action text, _entity_id uuid DEFAULT NULL::uuid, _capability text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.has_permission(auth.uid(), _module, _action) THEN RETURN; END IF;
  IF _entity_id IS NOT NULL AND _capability IS NOT NULL
     AND public.wb_membership_capability(_entity_id, _capability) THEN RETURN; END IF;
  RAISE EXCEPTION 'Not authorized: %.%', _module, _action USING ERRCODE = '42501';
END $function$
;
CREATE OR REPLACE FUNCTION public.worker_kick(_function_name text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  RETURN public.notification_worker_kick(_function_name);
END; $function$
;
CREATE OR REPLACE FUNCTION public.workflow_actor_sector_allowed(_user_id uuid, _sector_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_has_sector_scope boolean;
BEGIN
  IF _user_id IS NULL THEN RETURN false; END IF;
  IF _sector_id IS NULL THEN RETURN true; END IF;
  IF public.is_super_admin(_user_id) THEN RETURN true; END IF;

  SELECT EXISTS (
    SELECT 1
      FROM public.sec_user_roles sur
      JOIN public.sec_role_scopes srs ON srs.role_id = sur.role_id
      JOIN public.sec_scope_types st ON st.id = srs.scope_type_id
      JOIN public.sec_role_scope_values v ON v.role_scope_id = srs.id
     WHERE sur.user_id = _user_id AND st.key = 'sector'
  ) INTO v_has_sector_scope;

  IF NOT COALESCE(v_has_sector_scope, false) THEN RETURN true; END IF;

  RETURN EXISTS (
    SELECT 1
      FROM public.sec_user_roles sur
      JOIN public.sec_role_scopes srs ON srs.role_id = sur.role_id
      JOIN public.sec_scope_types st ON st.id = srs.scope_type_id
      JOIN public.sec_role_scope_values v ON v.role_scope_id = srs.id
     WHERE sur.user_id = _user_id
       AND st.key = 'sector'
       AND v.value_id = _sector_id
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.workflow_diagnostic_for_application(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
  v_inst record;
  v_steps jsonb;
  v_can jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error','UNAUTHORIZED');
  END IF;

  SELECT id, application_number, status, workflow_id, current_step_id, license_type, regulator_id
    INTO v_app FROM public.applications WHERE id = _application_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','NOT_FOUND');
  END IF;

  SELECT id, workflow_id, current_step_id, status
    INTO v_inst FROM public.workflow_instances
   WHERE entity_id = _application_id AND entity_type='application'
   ORDER BY created_at DESC LIMIT 1;

  SELECT jsonb_agg(jsonb_build_object(
    'step_id', s.id, 'step_order', s.step_order, 'name', s.name,
    'approver_role_id', s.approver_role_id, 'role_name', r.name,
    'role_system_role', r.system_role,
    'legacy_approver_role', s.approver_role,
    'allowed_actions', s.allowed_actions,
    'is_current', (s.id = v_inst.current_step_id)
  ) ORDER BY s.step_order) INTO v_steps
  FROM public.approval_steps s
  LEFT JOIN public.roles r ON r.id = s.approver_role_id
  WHERE s.workflow_id = COALESCE(v_inst.workflow_id, v_app.workflow_id);

  IF v_inst.current_step_id IS NOT NULL THEN
    v_can := public.user_can_act_on_workflow_step(v_uid, v_inst.current_step_id);
  END IF;

  RETURN jsonb_build_object(
    'application', to_jsonb(v_app),
    'instance', to_jsonb(v_inst),
    'steps', COALESCE(v_steps, '[]'::jsonb),
    'can_act', v_can
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.workflow_resolve_actor(_claimed uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_service boolean := coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role'),
    current_user
  ) = 'service_role';
BEGIN
  IF v_service THEN
    IF _claimed IS NULL THEN
      RAISE EXCEPTION 'ACTOR_REQUIRED' USING ERRCODE = '42501';
    END IF;
    RETURN _claimed;
  END IF;

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
  END IF;
  IF _claimed IS NOT NULL AND _claimed <> v_uid THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH' USING ERRCODE = '42501';
  END IF;
  RETURN v_uid;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.write_audit(_action text, _entity_type text, _entity_id text, _user_id uuid, _old_value jsonb DEFAULT NULL::jsonb, _new_value jsonb DEFAULT NULL::jsonb, _metadata jsonb DEFAULT NULL::jsonb, _dedupe_seconds integer DEFAULT 10)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_exists uuid;
  v_legacy text;
BEGIN
  IF _action IS NULL OR _entity_type IS NULL THEN
    RETURN NULL;
  END IF;

  -- Map dot/underscore variants to a normalised legacy form so dedupe
  -- works regardless of which name was previously written.
  v_legacy := replace(_action, '.', '_');

  IF _entity_id IS NOT NULL AND _dedupe_seconds > 0 THEN
    SELECT id INTO v_exists
      FROM public.audit_logs
     WHERE entity_id = _entity_id
       AND (action = _action OR action = v_legacy OR action = replace(_action,'_','.'))
       AND created_at >= now() - make_interval(secs => _dedupe_seconds)
     LIMIT 1;
    IF v_exists IS NOT NULL THEN
      RETURN v_exists;
    END IF;
  END IF;

  INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, old_value, new_value, metadata)
  VALUES (_user_id, _action, _entity_type, _entity_id, _old_value, _new_value,
          COALESCE(_metadata, '{}'::jsonb))
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.service_license_compatible(_service_id uuid, _license_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_svc public.services;
  v_lic public.licenses;
BEGIN
  IF _service_id IS NULL OR _license_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT * INTO v_svc FROM public.services WHERE id = _service_id;
  IF v_svc.id IS NULL OR lower(COALESCE(v_svc.status,'')) <> 'active' THEN
    RETURN false;
  END IF;
  IF v_svc.effective_to IS NOT NULL AND v_svc.effective_to <= now() THEN
    RETURN false;
  END IF;

  SELECT * INTO v_lic FROM public.licenses WHERE id = _license_id;
  IF v_lic.id IS NULL THEN
    RETURN false;
  END IF;

  IF v_lic.sub_sector_id IS NOT NULL THEN
    RETURN v_svc.sub_sector_id = v_lic.sub_sector_id;
  END IF;

  RETURN public.sector_effective_id(v_svc.sector_id)
         = public.sector_effective_id(v_lic.sector_id);
END $function$
;
CREATE OR REPLACE FUNCTION public.resolve_post_license_intake_context(_license_id uuid, _service_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(entity_id uuid, license_id uuid, service_id uuid, sector_id uuid, sub_sector_id uuid, category_id uuid, regulator_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT lic.holder_id,
         lic.id,
         _service_id,
         lic.sector_id,
         lic.sub_sector_id,
         lic.category_id,
         COALESCE(svc.regulator_id, lic.regulator_id)
    FROM public.licenses lic
    LEFT JOIN public.services svc ON svc.id = _service_id
   WHERE lic.id = _license_id;
$function$
;
CREATE OR REPLACE FUNCTION public.can_submit_application(_application_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_app record;
BEGIN
  IF v_uid IS NULL OR _application_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT id, applicant_id, entity_id
    INTO v_app
    FROM public.applications
   WHERE id = _application_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF v_app.applicant_id = v_uid THEN
    RETURN true;
  END IF;

  IF v_app.entity_id IS NOT NULL
     AND public.entity_membership_capability(v_uid, v_app.entity_id, 'submit') THEN
    RETURN true;
  END IF;

  RETURN false;
END $function$
;
